  )
}

'use client'

import React, { useState, useEffect } from 'react'
import { useParams, useRouter } from 'next/navigation'
import Image from 'next/image'

interface TicketResponse {
  id: string
  message: string
  isAdminResponse: boolean
  createdAt: string
  admin?: {
    name: string
    email: string
  }
}

interface SupportTicket {
  id: string
  subject: string
  message: string
  userEmail: string
  userName: string
  status: string
  priority: string
  category: string
  createdAt: string
  updatedAt: string
  responses: TicketResponse[]
}

export default function TicketPage() {
  const params = useParams()
  const router = useRouter()
  const ticketId = params.id as string

  const [ticket, setTicket] = useState<SupportTicket | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState('')
  const [isAuthenticated, setIsAuthenticated] = useState(false)
  const [expandedResponses, setExpandedResponses] = useState<Set<string>>(new Set())
  const [newResponse, setNewResponse] = useState('')
  const [isSendingResponse, setIsSendingResponse] = useState(false)

  // Load expanded state from localStorage
  useEffect(() => {
    if (typeof window !== 'undefined' && ticketId) {
      const savedState = localStorage.getItem(`ticket-${ticketId}-expanded`)
      if (savedState) {
        try {
          const expandedIds = JSON.parse(savedState)
          setExpandedResponses(new Set(expandedIds))
        } catch (error) {
          console.error('Failed to parse saved expanded state:', error)
        }
      }
    }
  }, [ticketId])

  // Save expanded state to localStorage whenever it changes
  useEffect(() => {
    if (typeof window !== 'undefined' && ticketId) {
      const expandedIds = Array.from(expandedResponses)
      if (expandedIds.length > 0) {
        localStorage.setItem(`ticket-${ticketId}-expanded`, JSON.stringify(expandedIds))
      } else {
        // Remove from localStorage if no responses are expanded
        localStorage.removeItem(`ticket-${ticketId}-expanded`)
      }
    }
  }, [expandedResponses, ticketId])

  // Check authentication
  useEffect(() => {
    const token = sessionStorage.getItem('adminToken')
    if (!token) {
      router.push('/admin-panel')
      return
    }
    setIsAuthenticated(true)
    loadTicketData()
  }, [ticketId, router])

  const loadTicketData = async () => {
    try {
      setIsLoading(true)
      const response = await fetch(`/api/admin/tickets?action=get_ticket&ticketId=${ticketId}`, {
        headers: {
          'Authorization': `Bearer ${sessionStorage.getItem('adminToken')}`
        }
      })

      if (!response.ok) {
        throw new Error('Failed to load ticket data')
      }

      const data = await response.json()
      setTicket(data.ticket)

      // Fix: Only set initial expanded state if we don't already have responses in state
      // This prevents loadTicketData from overriding user's collapse preferences
      if (data.ticket.responses && data.ticket.responses.length > 0) {
        // Check if we already have expanded state (either from localStorage or previous load)
        const savedState = localStorage.getItem(`ticket-${ticketId}-expanded`)
        const hasExistingState = expandedResponses.size > 0 || savedState

        if (!hasExistingState) {
          // Only expand all by default on first load with no saved state
          console.log('First load - expanding all responses by default')
          const allResponseIds = new Set<string>(data.ticket.responses.map((r: TicketResponse) => r.id))
          setExpandedResponses(allResponseIds)
        } else {
          console.log('Preserving existing expanded state from localStorage or previous load')
        }
      }

      // Pre-fill response with greeting template
      if (data.ticket && !newResponse) {
        let customerName = 'there'
        if (data.ticket.userName && data.ticket.userName.trim()) {
          if (data.ticket.userName.includes('@')) {
            customerName = data.ticket.userName.split('@')[0]
          } else {
            customerName = data.ticket.userName
          }
          customerName = customerName.charAt(0).toUpperCase() + customerName.slice(1).toLowerCase()
        }

        const greeting = `Hi ${customerName},\n\n`
        const signature = `\n\nWarmest Regards,\nHelfi Support Team`
        setNewResponse(greeting + signature)
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load ticket')
    } finally {
      setIsLoading(false)
    }
  }

  const toggleResponseExpansion = (responseId: string) => {
    const newExpanded = new Set(expandedResponses)
    if (newExpanded.has(responseId)) {
      newExpanded.delete(responseId)
    } else {
      newExpanded.add(responseId)
    }
    setExpandedResponses(newExpanded)

    // Save to localStorage for persistence
    if (ticket?.id) {
      const storageKey = `ticket-${ticket.id}-expanded`
      localStorage.setItem(storageKey, JSON.stringify(Array.from(newExpanded)))
    }
  }

  const handleStatusChange = async (newStatus: string) => {
    try {
      const response = await fetch('/api/admin/tickets', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${sessionStorage.getItem('adminToken')}`
        },
        body: JSON.stringify({
          action: 'update_status',
          ticketId: ticket?.id,
          status: newStatus
        })
      })

      if (response.ok) {
        setTicket(prev => prev ? { ...prev, status: newStatus } : null)
      }
    } catch (err) {
      console.error('Failed to update status:', err)
    }
  }

  const handleSendResponse = async () => {
    if (!newResponse.trim() || !ticket) return

    setIsSendingResponse(true)
    try {
      const response = await fetch('/api/admin/tickets', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${sessionStorage.getItem('adminToken')}`
        },
        body: JSON.stringify({
          action: 'add_response',
          ticketId: ticket.id,
          message: newResponse.trim()
        })
      })

      if (response.ok) {
        // Reload ticket data to get updated responses
        await loadTicketData()
        setNewResponse('')
      }
    } catch (err) {
      console.error('Failed to send response:', err)
    } finally {
      setIsSendingResponse(false)
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'OPEN': return 'bg-green-100 text-green-800 border-green-200'
      case 'IN_PROGRESS': return 'bg-yellow-100 text-yellow-800 border-yellow-200'
      case 'AWAITING_RESPONSE': return 'bg-blue-100 text-blue-800 border-blue-200'
      case 'RESPONDED': return 'bg-purple-100 text-purple-800 border-purple-200'
      case 'RESOLVED': return 'bg-gray-100 text-gray-800 border-gray-200'
      case 'CLOSED': return 'bg-red-100 text-red-800 border-red-200'
      default: return 'bg-gray-100 text-gray-800 border-gray-200'
    }
  }

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'LOW': return 'bg-gray-100 text-gray-800 border-gray-200'
      case 'MEDIUM': return 'bg-blue-100 text-blue-800 border-blue-200'
      case 'HIGH': return 'bg-orange-100 text-orange-800 border-orange-200'
      case 'URGENT': return 'bg-red-100 text-red-800 border-red-200'
      default: return 'bg-gray-100 text-gray-800 border-gray-200'
    }
  }

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }

  if (!isAuthenticated) {
    return null
  }

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="flex items-center space-x-3">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-emerald-500"></div>
          <span className="text-gray-600">Loading ticket...</span>
        </div>
      </div>
    )
  }

  if (error || !ticket) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="bg-red-50 border border-red-200 rounded-lg p-6 max-w-md">
            <h2 className="text-lg font-semibold text-red-800 mb-2">Error Loading Ticket</h2>
            <p className="text-red-600 mb-4">{error || 'Ticket not found'}</p>
            <button
              onClick={() => router.push('/admin-panel')}
              className="bg-red-500 text-white px-4 py-2 rounded-lg hover:bg-red-600 transition-colors"
            >
              Back to Admin Panel
            </button>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <div className="bg-white border-b border-gray-200 px-6 py-4">
        <div className="flex justify-between items-center">
          <div className="flex items-center space-x-4">
            <button
              onClick={() => {
                // Use URL hash to indicate which tab should be active
                router.push('/admin-panel#tickets')
              }}
              className="flex items-center space-x-2 text-gray-600 hover:text-gray-800 transition-colors"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
              </svg>
              <span>Back to Support Tickets</span>
            </button>
            <div className="h-6 w-px bg-gray-300"></div>
            <div className="flex items-center space-x-3">
              <Image
                src="/mobile-assets/LOGOS/helfi-01-01.png"
                alt="Helfi Logo"
                width={32}
                height={32}
              />
              <div>
                <h1 className="text-xl font-bold text-gray-900">Support Ticket #{ticket.id.slice(-8)}</h1>
                <p className="text-sm text-gray-600">{ticket.subject}</p>
              </div>
            </div>
          </div>
          <div className="flex items-center space-x-3">
            <span className={`px-3 py-1 rounded-full text-sm font-medium border ${getStatusColor(ticket.status)}`}>
              {ticket.status.replace('_', ' ')}
            </span>
            <span className={`px-3 py-1 rounded-full text-sm font-medium border ${getPriorityColor(ticket.priority)}`}>
              {ticket.priority}
            </span>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-6 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Main Content */}
          <div className="lg:col-span-2 space-y-6">
            {/* Conversation Thread */}
            <div className="bg-white rounded-lg shadow-sm border border-gray-200">
              <div className="px-6 py-4 border-b border-gray-200">
                <h2 className="text-lg font-semibold text-gray-900">💬 Conversation</h2>
                <p className="text-sm text-gray-600 mt-1">Latest responses appear first</p>
              </div>

              <div className="p-6 space-y-4">
                {/* Response Form - At Top */}
                <div className="bg-emerald-50 border border-emerald-200 rounded-lg p-4">
                  <h3 className="text-sm font-medium text-emerald-900 mb-3">📤 Send New Response</h3>
                  <textarea
                    value={newResponse}
                    onChange={(e) => setNewResponse(e.target.value)}
                    rows={6}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 resize-none"
                    placeholder="Type your response to the customer..."
                  />
                  <div className="flex justify-end space-x-3 mt-3">
                    <button
                      onClick={() => setNewResponse('')}
                      className="px-4 py-2 text-gray-600 hover:text-gray-800 transition-colors"
                    >
                      Clear
                    </button>
                    <button
                      onClick={handleSendResponse}
                      disabled={isSendingResponse || !newResponse.trim()}
                      className="px-6 py-2 bg-emerald-500 text-white rounded-lg hover:bg-emerald-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center space-x-2"
                    >
                      {isSendingResponse ? (
                        <>
                          <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>
                          <span>Sending...</span>
                        </>
                      ) : (
                        <>
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
                          </svg>
                          <span>Send Response</span>
                        </>
                      )}
                    </button>
                  </div>
                </div>

                {/* Responses - Latest First */}
                {ticket.responses && ticket.responses.length > 0 && (
                  <div className="space-y-4">
                    {[...ticket.responses].reverse().map((response) => (
                      <div
                        key={response.id}
                        className={`border rounded-lg overflow-hidden ${
                          response.isAdminResponse 
                            ? 'border-blue-200 bg-blue-50' 
                            : 'border-gray-200 bg-gray-50'
                        }`}
                      >
                        <div 
                          className="px-4 py-3 cursor-pointer hover:bg-opacity-80 transition-colors"
                          onClick={() => toggleResponseExpansion(response.id)}
                        >
                          <div className="flex justify-between items-center">
                            <div className="flex items-center space-x-3">
                              <div className={`w-8 h-8 rounded-full flex items-center justify-center text-white font-medium ${
                                response.isAdminResponse ? 'bg-blue-500' : 'bg-gray-500'
                              }`}>
                                {response.isAdminResponse ? '🛡️' : '👤'}
                              </div>
                              <div>
                                <div className="font-medium text-gray-900">
                                  {response.isAdminResponse 
                                    ? `${response.admin?.name || 'Admin'} (Support Team)`
                                    : `${ticket.userName || 'Customer'}`}
                                </div>
                                <div className="text-sm text-gray-600">
                                  {formatDate(response.createdAt)}
                                </div>
                              </div>
                            </div>
                            <div className="flex items-center space-x-2">
                              <span className={`px-2 py-1 text-xs font-medium rounded ${
                                response.isAdminResponse 
                                  ? 'bg-blue-100 text-blue-800' 
                                  : 'bg-gray-100 text-gray-800'
                              }`}>
                                {response.isAdminResponse ? 'Admin Reply' : 'Customer'}
                              </span>
                              <svg 
                                className={`w-4 h-4 text-gray-400 transition-transform ${
                                  expandedResponses.has(response.id) ? 'rotate-180' : ''
                                }`} 
                                fill="none" 
                                stroke="currentColor" 
                                viewBox="0 0 24 24"
                              >
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                              </svg>
                            </div>
                          </div>
                        </div>

                        {expandedResponses.has(response.id) && (
                          <div className="px-4 pb-4 border-t border-gray-200 bg-white">
                            <div className="pt-3">
                              <p className="text-gray-700 whitespace-pre-wrap leading-relaxed">
                                {response.message}
                              </p>
                            </div>
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                )}

                {/* Original Message - At Bottom */}
                <div className="border border-orange-200 bg-orange-50 rounded-lg p-4">
                  <div className="flex items-center space-x-2 mb-3">
                    <svg className="w-5 h-5 text-orange-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" />
                    </svg>
                    <h3 className="text-sm font-medium text-orange-900">Original Message</h3>
                    <span className="text-xs text-orange-600">({formatDate(ticket.createdAt)})</span>
                  </div>
                  <p className="text-gray-700 whitespace-pre-wrap leading-relaxed">
                    {ticket.message}
                  </p>
                </div>
              </div>
            </div>
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            {/* Customer Info */}
            <div className="bg-white rounded-lg shadow-sm border border-gray-200">
              <div className="px-6 py-4 border-b border-gray-200">
                <h3 className="text-lg font-semibold text-gray-900">👤 Customer Information</h3>
              </div>
              <div className="p-6 space-y-4">
                <div className="flex items-center space-x-3">
                  <div className="w-12 h-12 bg-emerald-100 rounded-full flex items-center justify-center">
                    <span className="text-emerald-600 font-semibold text-lg">
                      {ticket.userName ? ticket.userName.charAt(0).toUpperCase() : ticket.userEmail.charAt(0).toUpperCase()}
                    </span>
                  </div>
                  <div>
                    <div className="font-medium text-gray-900">
                      {ticket.userName || 'Unknown User'}
                    </div>
                    <div className="text-sm text-gray-600">
                      {ticket.userEmail}
                    </div>
                  </div>
                </div>

                <div className="pt-4 border-t border-gray-200">
                  <div className="space-y-3">
                    <div className="flex justify-between">
                      <span className="text-sm text-gray-600">Category:</span>
                      <span className="text-sm font-medium text-gray-900">{ticket.category}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-sm text-gray-600">Created:</span>
                      <span className="text-sm font-medium text-gray-900">{formatDate(ticket.createdAt)}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-sm text-gray-600">Last Update:</span>
                      <span className="text-sm font-medium text-gray-900">{formatDate(ticket.updatedAt)}</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Ticket Management */}
            <div className="bg-white rounded-lg shadow-sm border border-gray-200">
              <div className="px-6 py-4 border-b border-gray-200">
                <h3 className="text-lg font-semibold text-gray-900">⚙️ Ticket Management</h3>
              </div>
              <div className="p-6 space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Status
                  </label>
                  <select
                    value={ticket.status}
                    onChange={(e) => handleStatusChange(e.target.value)}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500"
                  >
                    <option value="OPEN">Open</option>
                    <option value="IN_PROGRESS">In Progress</option>
                    <option value="AWAITING_RESPONSE">Awaiting Response</option>
                    <option value="RESPONDED">Responded</option>
                    <option value="RESOLVED">Resolved</option>
                    <option value="CLOSED">Closed</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Priority
                  </label>
                  <div className={`px-3 py-2 rounded-lg border ${getPriorityColor(ticket.priority)}`}>
                    {ticket.priority}
                  </div>
                </div>

                <div className="pt-4 border-t border-gray-200">
                  <button
                    onClick={() => {
                      if (confirm(`Are you sure you want to permanently delete this ticket? This action cannot be undone.`)) {
                        // Handle delete logic here
                        console.log('Delete ticket:', ticket.id)
                      }
                    }}
                    className="w-full bg-red-500 text-white px-4 py-2 rounded-lg hover:bg-red-600 transition-colors"
                  >
                    🗑️ Delete Ticket
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import React, { useCallback, useEffect, useMemo, useState } from 'react'
import { useParams, useRouter } from 'next/navigation'

type AdminUser = {
  id: string
  email: string
  name?: string | null
  createdAt: string
  dailyAnalysisCredits?: number | null
  dailyAnalysisUsed?: number | null
  additionalCredits?: number | null
  walletMonthlyResetAt?: string | null
  totalAvailableCredits?: number | null
  totalAnalysisCount?: number | null
  dailyFoodAnalysisUsed?: number | null
  dailyFoodReanalysisUsed?: number | null
  dailyInteractionAnalysisUsed?: number | null
  monthlyMedicalImageAnalysisUsed?: number | null
  monthlySymptomAnalysisUsed?: number | null
  monthlyInsightsGenerationUsed?: number | null
  lastAnalysisResetDate?: string | null
  subscription?: {
    plan?: string | null
    monthlyPriceCents?: number | null
    startDate?: string | null
    endDate?: string | null
    stripeSubscriptionId?: string | null
    source?: string | null
    storeProductId?: string | null
    storeTransactionId?: string | null
    storeOriginalTransactionId?: string | null
  } | null
}

function subscriptionSourceLabel(source?: string | null) {
  if (source === 'apple_iap') return 'Apple App Store'
  if (source === 'google_iap') return 'Google Play'
  if (source === 'stripe') return 'Stripe'
  if (source === 'admin') return 'Admin'
  return 'Not recorded'
}

export default function AdminUserPage() {
  const router = useRouter()
  const params = useParams()
  const userId = params.userId as string
  const [adminToken, setAdminToken] = useState('')
  const [user, setUser] = useState<AdminUser | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [actionInFlight, setActionInFlight] = useState<Record<string, boolean>>({})

  useEffect(() => {
    const storedToken = sessionStorage.getItem('adminToken') || ''
    setAdminToken(storedToken)
  }, [])

  const loadUser = useCallback(async () => {
    if (!adminToken || !userId) return
    setLoading(true)
    setError('')
    try {
      const params = new URLSearchParams({
        userId,
        page: '1',
        limit: '1',
      })
      const response = await fetch(`/api/admin/user-management?${params.toString()}`, {
        cache: 'no-store',
        headers: { Authorization: `Bearer ${adminToken}` },
      })
      if (response.ok) {
        const result = await response.json()
        setUser(result.users?.[0] || null)
        if (!result.users?.length) {
          setError('User not found. Try returning to the users list and selecting again.')
        }
      } else if (response.status === 401) {
        setError('Admin login is required to view this user.')
      } else {
        setError('Unable to load this user right now.')
      }
    } catch (err) {
      console.error('Failed to load user:', err)
      setError('Unable to load this user right now.')
    } finally {
      setLoading(false)
    }
  }, [adminToken, userId])

  useEffect(() => {
    if (adminToken) {
      loadUser()
    } else {
      setLoading(false)
    }
  }, [adminToken, loadUser])

  const handleUserAction = async (action: string, data?: any) => {
    if (!user) return
    const key = `${action}:${user.id}`
    if (actionInFlight[key]) return
    setActionInFlight((prev) => ({ ...prev, [key]: true }))
    try {
      const response = await fetch('/api/admin/user-management', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${adminToken}`,
        },
        body: JSON.stringify({ action, userId: user.id, data }),
      })
      const result = await response.json()
      if (response.ok) {
        if (action === 'deactivate') {
          setUser((current) =>
            current
              ? {
                  ...current,
                  subscription: null,
                }
              : current,
          )
        }
        await loadUser()
        if (action === 'refund_latest_payment') {
          const amountCents = typeof result?.refundedAmountCents === 'number' ? result.refundedAmountCents : null
          const currency = typeof result?.currency === 'string' ? result.currency.toUpperCase() : 'AUD'
          const amountText = amountCents != null ? `${currency} ${(amountCents / 100).toFixed(2)}` : 'the payment'
          alert(`Refund started for ${amountText}. Access and credits will be removed automatically.`)
        } else {
          const successMessage = result?.message || `User ${action} completed successfully`
          alert(successMessage)
        }
      } else {
        const errorMessage = result.error || 'Action failed. Please try again.'
        alert(`Action failed: ${errorMessage}`)
      }
    } catch (err) {
      console.error('Failed to run user action:', err)
      alert('Action failed. Please try again.')
    } finally {
      setActionInFlight((prev) => {
        const next = { ...prev }
        delete next[key]
        return next
      })
    }
  }

  const planLabel = useMemo(() => {
    if (!user?.subscription?.plan || user.subscription.plan !== 'PREMIUM') {
      return 'No Subscription'
    }
    const price = user.subscription.monthlyPriceCents || 0
    if (user.subscription.endDate) {
      const endDate = new Date(user.subscription.endDate)
      const startDate = new Date(user.subscription.startDate || user.createdAt)
      const totalDays = Math.ceil((endDate.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24))
      const credits = Math.floor(price * 0.5)
      if (totalDays > 90) return `Permanent (${credits} credits/month)`
      return `${totalDays}-Day Access (${credits} credits)`
    }
    if (price === 1000) return '$10/month (700 credits)'
    if (price === 2000) return '$20/month (1,400 credits)'
    if (price === 3000) return '$30/month (2,100 credits)'
    if (price === 5000) return '$50/month (3,500 credits)'
    return `$${Math.round(price / 100)}/month`
  }, [user])

  const isPremium = user?.subscription?.plan === 'PREMIUM'
  const isPermanentAccess =
    !!user?.subscription?.endDate && new Date(user.subscription.endDate).getFullYear() > 2050
  const hasStripeSubscription = !!user?.subscription?.stripeSubscriptionId
  const isApplePremium = isPremium && user?.subscription?.source === 'apple_iap'
  const isGooglePremium = isPremium && user?.subscription?.source === 'google_iap'
  const isPaidPremium = isPremium && (hasStripeSubscription || isApplePremium || isGooglePremium)
  const isStripePaidPremium = isPremium && hasStripeSubscription
  const isAdminGrantedPremium = isPremium && !hasStripeSubscription && !isApplePremium && !isGooglePremium

  const accessLabel = useMemo(() => {
    if (!user?.subscription) return 'No Subscription'
    if (user.subscription.source === 'apple_iap') {
      return user.subscription.endDate
        ? `Apple App Store subscription until ${new Date(user.subscription.endDate).toLocaleDateString()}`
        : 'Apple App Store subscription'
    }
    if (user.subscription.source === 'google_iap') {
      return user.subscription.endDate
        ? `Google Play subscription until ${new Date(user.subscription.endDate).toLocaleDateString()}`
        : 'Google Play subscription'
    }
    if (user.subscription.plan === 'PREMIUM' && !user.subscription.stripeSubscriptionId) {
      if (user.subscription.endDate) {
        const endDate = new Date(user.subscription.endDate)
        return endDate.getFullYear() > 2050
          ? 'Admin granted permanent access'
          : `Admin granted access until ${endDate.toLocaleDateString()}`
      }
      return 'Admin granted premium access'
    }
    if (user.subscription.endDate) {
      const endDate = new Date(user.subscription.endDate)
      return endDate.getFullYear() > 2050
        ? 'Permanent Access'
        : `Expires ${endDate.toLocaleDateString()}`
    }
    return 'Active Premium Subscription'
  }, [user])

  const nextRenewal = useMemo(() => {
    if (!user?.subscription?.startDate || user.subscription.endDate) return null
    const startDate = new Date(user.subscription.startDate)
    const now = new Date()
    const addMonthsClampedUtc = (anchor: Date, monthsToAdd: number) => {
      const y = anchor.getUTCFullYear()
      const m = anchor.getUTCMonth()
      const d = anchor.getUTCDate()
      const hh = anchor.getUTCHours()
      const mm = anchor.getUTCMinutes()
      const ss = anchor.getUTCSeconds()
      const ms = anchor.getUTCMilliseconds()

      const absoluteMonth = m + monthsToAdd
      const targetYear = y + Math.floor(absoluteMonth / 12)
      const targetMonth = ((absoluteMonth % 12) + 12) % 12
      const maxDay = new Date(Date.UTC(targetYear, targetMonth + 1, 0)).getUTCDate()
      const targetDay = Math.min(d, maxDay)

      return new Date(Date.UTC(targetYear, targetMonth, targetDay, hh, mm, ss, ms))
    }

    let monthsSinceStart =
      (now.getUTCFullYear() - startDate.getUTCFullYear()) * 12 +
      (now.getUTCMonth() - startDate.getUTCMonth())

    let nextRenewalDate = addMonthsClampedUtc(startDate, monthsSinceStart)
    if (nextRenewalDate.getTime() <= now.getTime()) {
      monthsSinceStart += 1
      nextRenewalDate = addMonthsClampedUtc(startDate, monthsSinceStart)
    }
    while (nextRenewalDate.getTime() <= now.getTime()) {
      monthsSinceStart += 1
      nextRenewalDate = addMonthsClampedUtc(startDate, monthsSinceStart)
    }

    return nextRenewalDate.toLocaleString(undefined, {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
      second: '2-digit',
      hour12: true,
    })
  }, [user])

  if (!adminToken && !loading) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
        <div className="bg-white border border-slate-200 rounded-2xl p-8 shadow-sm text-center max-w-lg">
          <h1 className="text-xl font-semibold text-slate-900 mb-2">Admin login required</h1>
          <p className="text-slate-600 mb-6">
            Please sign in to the admin panel before managing user accounts.
          </p>
          <button
            onClick={() => router.push('/admin-panel')}
            className="bg-emerald-600 text-white px-5 py-2 rounded-lg hover:bg-emerald-700 transition-colors"
          >
            Go to Admin Login
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-slate-50">
      <div className="max-w-6xl mx-auto px-6 py-8">
        <div className="flex flex-wrap items-center justify-between gap-4">
          <button
            onClick={() => router.push('/admin-panel?tab=management')}
            className="text-sm text-slate-600 hover:text-slate-900 transition-colors flex items-center gap-2"
          >
            <span className="text-lg">←</span>
            Back to Users
          </button>
          <button
            onClick={() => loadUser()}
            className="bg-white border border-slate-200 text-slate-700 px-4 py-2 rounded-lg hover:border-slate-300 hover:text-slate-900 transition-colors"
          >
            Refresh
          </button>
        </div>

        {loading ? (
          <div className="mt-10 text-slate-500">Loading user details…</div>
        ) : error ? (
          <div className="mt-10 bg-white border border-rose-200 text-rose-700 rounded-xl p-6">
            {error}
          </div>
        ) : user ? (
          <>
            <div className="mt-6 bg-white border border-slate-200 rounded-2xl shadow-sm p-6">
              <div className="flex flex-wrap items-start justify-between gap-6">
                <div>
                  <h1 className="text-2xl font-semibold text-slate-900">
                    {user.name || user.email}
                  </h1>
                  <p className="text-slate-500">{user.email}</p>
                </div>
                <div className="flex flex-wrap gap-2">
                  <span className={`px-3 py-1 rounded-full text-xs font-semibold ${
                    isPremium ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-600'
                  }`}>
                    {isPremium ? 'Premium' : 'Free'}
                  </span>
                  {isPermanentAccess && (
                    <span className="px-3 py-1 rounded-full text-xs font-semibold bg-amber-100 text-amber-700">
                      Permanent
                    </span>
                  )}
                  {isPaidPremium && (
                    <span className="px-3 py-1 rounded-full text-xs font-semibold bg-blue-100 text-blue-700">
                      {isApplePremium ? 'Apple paid' : isGooglePremium ? 'Google paid' : 'Paid'}
                    </span>
                  )}
                  {isAdminGrantedPremium && (
                    <span className="px-3 py-1 rounded-full text-xs font-semibold bg-violet-100 text-violet-700">
                      Admin granted
                    </span>
                  )}
                </div>
              </div>

              <div className="mt-6 grid gap-4 md:grid-cols-4">
                <div className="bg-slate-50 rounded-xl p-4">
                  <div className="text-xs text-slate-500">Plan</div>
                  <div className="text-sm font-semibold text-slate-900">{planLabel}</div>
                </div>
                <div className="bg-slate-50 rounded-xl p-4">
                  <div className="text-xs text-slate-500">Access</div>
                  <div className="text-sm font-semibold text-slate-900">{accessLabel}</div>
                </div>
                <div className="bg-slate-50 rounded-xl p-4">
                  <div className="text-xs text-slate-500">Billing source</div>
                  <div className="text-sm font-semibold text-slate-900">
                    {subscriptionSourceLabel(user.subscription?.source)}
                  </div>
                </div>
                <div className="bg-slate-50 rounded-xl p-4">
                  <div className="text-xs text-slate-500">Next Renewal</div>
                  <div className="text-sm font-semibold text-slate-900">
                    {nextRenewal || '—'}
                  </div>
                </div>
              </div>
            </div>

            <div className="mt-6 grid gap-6 lg:grid-cols-3">
              <div className="lg:col-span-2 space-y-6">
                <div className="bg-white border border-slate-200 rounded-2xl shadow-sm p-6">
                  <div className="flex items-center justify-between mb-4">
                    <h2 className="text-lg font-semibold text-slate-900">Credits & Usage</h2>
                    <span className="text-xs text-slate-500">Total available credits</span>
                  </div>
                  <div className="flex items-baseline gap-2 mb-6">
                    <div className="text-3xl font-semibold text-emerald-600">
                      {user.totalAvailableCredits !== undefined
                        ? user.totalAvailableCredits
                        : (user.additionalCredits || 0)}
                    </div>
                    <div className="text-sm text-slate-500">credits</div>
                  </div>
                  <div className="grid gap-4 md:grid-cols-3">
                    <div className="bg-slate-50 rounded-xl p-4">
                      <div className="text-xs text-slate-500">Daily usage</div>
                      <div className="text-sm font-semibold text-slate-900">
                        {user.dailyAnalysisUsed || 0}/{user.dailyAnalysisCredits || 3}
                      </div>
                    </div>
                    <div className="bg-slate-50 rounded-xl p-4">
                      <div className="text-xs text-slate-500">Total analyses</div>
                      <div className="text-sm font-semibold text-slate-900">{user.totalAnalysisCount || 0}</div>
                    </div>
                    <div className="bg-slate-50 rounded-xl p-4">
                      <div className="text-xs text-slate-500">Wallet reset</div>
                      <div className="text-sm font-semibold text-slate-900">
                        {user.walletMonthlyResetAt
                          ? new Date(user.walletMonthlyResetAt).toLocaleString()
                          : user.lastAnalysisResetDate
                          ? `${new Date(user.lastAnalysisResetDate).toLocaleDateString()} (legacy daily reset)`
                          : '—'}
                      </div>
                    </div>
                  </div>

                  <div className="mt-6">
                    <div className="text-xs text-slate-500 mb-3">Monthly feature usage</div>
                    <div className="grid gap-3 md:grid-cols-2 text-sm">
                      <div className="flex justify-between bg-slate-50 rounded-lg px-3 py-2">
                        <span>Food photo notes</span>
                        <span className="font-semibold">{user.dailyFoodAnalysisUsed || 0}</span>
                      </div>
                      <div className="flex justify-between bg-slate-50 rounded-lg px-3 py-2">
                        <span>Food photo retry</span>
                        <span className="font-semibold">{user.dailyFoodReanalysisUsed || 0}</span>
                      </div>
                      <div className="flex justify-between bg-slate-50 rounded-lg px-3 py-2">
                        <span>Health image notes</span>
                        <span className="font-semibold">{user.monthlyMedicalImageAnalysisUsed || 0}</span>
                      </div>
                      <div className="flex justify-between bg-slate-50 rounded-lg px-3 py-2">
                        <span>Interaction analysis</span>
                        <span className="font-semibold">{user.dailyInteractionAnalysisUsed || 0}</span>
                      </div>
                      <div className="flex justify-between bg-slate-50 rounded-lg px-3 py-2">
                        <span>Symptom notes</span>
                        <span className="font-semibold">{user.monthlySymptomAnalysisUsed || 0}</span>
                      </div>
                      <div className="flex justify-between bg-slate-50 rounded-lg px-3 py-2">
                        <span>Insights generation</span>
                        <span className="font-semibold">{user.monthlyInsightsGenerationUsed || 0}</span>
                      </div>
                    </div>
                  </div>

                  <div className="mt-6 flex flex-wrap gap-2">
                    <button
                      onClick={() => {
                        const credits = prompt('Enter number of credits to add:')
                        if (credits && !isNaN(parseInt(credits)) && parseInt(credits) > 0) {
                          handleUserAction('add_credits', { creditAmount: parseInt(credits) })
                        }
                      }}
                      className="bg-emerald-500 text-white px-4 py-2 rounded-lg text-sm hover:bg-emerald-600 transition-colors"
                    >
                      Add credits
                    </button>
                    <button
                      onClick={() => {
                        const credits = prompt('Enter number of credits to remove:')
                        if (credits && !isNaN(parseInt(credits)) && parseInt(credits) > 0) {
                          if (confirm(`Are you sure you want to remove ${credits} credits?`)) {
                            handleUserAction('remove_credits', { creditAmount: parseInt(credits) })
                          }
                        }
                      }}
                      className="bg-rose-500 text-white px-4 py-2 rounded-lg text-sm hover:bg-rose-600 transition-colors"
                    >
                      Remove credits
                    </button>
                    <button
                      onClick={() => {
                        if (confirm('Reset daily quota for this user?')) {
                          handleUserAction('reset_daily_quota')
                        }
                      }}
                      className="bg-slate-900 text-white px-4 py-2 rounded-lg text-sm hover:bg-slate-800 transition-colors"
                    >
                      Reset daily quota
                    </button>
                  </div>
                </div>

                <div className="bg-white border border-slate-200 rounded-2xl shadow-sm p-6">
                  <h2 className="text-lg font-semibold text-slate-900 mb-4">Grant subscription access</h2>
                  <div className="grid gap-3 md:grid-cols-4">
                    <button
                      onClick={() => handleUserAction('grant_subscription', { tier: '10' })}
                      className="bg-emerald-100 text-emerald-700 px-4 py-3 rounded-xl text-sm font-semibold hover:bg-emerald-200 transition-colors"
                    >
                      $10/month
                      <div className="text-xs font-normal">700 credits</div>
                    </button>
                    <button
                      onClick={() => handleUserAction('grant_subscription', { tier: '20' })}
                      className="bg-emerald-200 text-emerald-800 px-4 py-3 rounded-xl text-sm font-semibold hover:bg-emerald-300 transition-colors"
                    >
                      $20/month
                      <div className="text-xs font-normal">1,400 credits</div>
                    </button>
                    <button
                      onClick={() => handleUserAction('grant_subscription', { tier: '30' })}
                      className="bg-emerald-300 text-emerald-900 px-4 py-3 rounded-xl text-sm font-semibold hover:bg-emerald-400 transition-colors"
                    >
                      $30/month
                      <div className="text-xs font-normal">2,100 credits</div>
                    </button>
                    <button
                      onClick={() => handleUserAction('grant_subscription', { tier: '50' })}
                      className="bg-slate-900 text-white px-4 py-3 rounded-xl text-sm font-semibold hover:bg-slate-800 transition-colors"
                    >
                      $50/month
                      <div className="text-xs font-normal text-slate-200">3,500 credits</div>
                    </button>
                  </div>

                  <div className="mt-6">
                    <h3 className="text-sm font-semibold text-slate-700 mb-3">Temporary access</h3>
                    <div className="grid gap-3 md:grid-cols-2">
                      <button
                        onClick={() => handleUserAction('grant_trial', { trialDays: 7 })}
                        className="bg-blue-100 text-blue-700 px-4 py-3 rounded-xl text-sm font-semibold hover:bg-blue-200 transition-colors"
                      >
                        7-day premium
                        <div className="text-xs font-normal">250 credits</div>
                      </button>
                      <button
                        onClick={() => handleUserAction('grant_trial', { trialDays: 30 })}
                        className="bg-blue-100 text-blue-700 px-4 py-3 rounded-xl text-sm font-semibold hover:bg-blue-200 transition-colors"
                      >
                        30-day premium
                        <div className="text-xs font-normal">1,400 credits</div>
                      </button>
                    </div>
                  </div>

                  <div className="mt-6">
                    <h3 className="text-sm font-semibold text-slate-700 mb-3">Quick credit packages</h3>
                    <div className="grid gap-3 md:grid-cols-3">
                      <button
                        onClick={() => handleUserAction('add_credits', { creditPackage: '250' })}
                        className="bg-purple-100 text-purple-700 px-4 py-3 rounded-xl text-sm font-semibold hover:bg-purple-200 transition-colors"
                      >
                        250 credits
                        <div className="text-xs font-normal">$5</div>
                      </button>
                      <button
                        onClick={() => handleUserAction('add_credits', { creditPackage: '500' })}
                        className="bg-purple-100 text-purple-700 px-4 py-3 rounded-xl text-sm font-semibold hover:bg-purple-200 transition-colors"
                      >
                        500 credits
                        <div className="text-xs font-normal">$10</div>
                      </button>
                      <button
                        onClick={() => handleUserAction('add_credits', { creditPackage: '1000' })}
                        className="bg-purple-100 text-purple-700 px-4 py-3 rounded-xl text-sm font-semibold hover:bg-purple-200 transition-colors"
                      >
                        1,000 credits
                        <div className="text-xs font-normal">$20</div>
                      </button>
                    </div>
                  </div>
                </div>
              </div>

              <div className="space-y-6">
                <div className="bg-white border border-slate-200 rounded-2xl shadow-sm p-6">
                  <h2 className="text-lg font-semibold text-slate-900 mb-3">Plan controls</h2>
                  <div className="space-y-3">
                    {user.subscription?.plan === 'PREMIUM' ? (
                      <button
                        onClick={() => handleUserAction('deactivate')}
                        className="w-full bg-amber-500 text-white px-4 py-2 rounded-lg text-sm hover:bg-amber-600 transition-colors"
                      >
                        Remove subscription
                      </button>
                    ) : (
                      <button
                        onClick={() => handleUserAction('activate')}
                        className="w-full bg-emerald-600 text-white px-4 py-2 rounded-lg text-sm hover:bg-emerald-700 transition-colors"
                      >
                        Upgrade to premium
                      </button>
                    )}
                    <button
                      onClick={() => {
                        if (confirm('Are you sure you want to delete this user? This action cannot be undone.')) {
                          handleUserAction('delete_user')
                        }
                      }}
                      className="w-full bg-rose-600 text-white px-4 py-2 rounded-lg text-sm hover:bg-rose-700 transition-colors"
                    >
                      Delete user
                    </button>
                  </div>
                </div>

                <div className="bg-white border border-slate-200 rounded-2xl shadow-sm p-6">
                  <h2 className="text-lg font-semibold text-slate-900 mb-3">Refunds</h2>
                  {isStripePaidPremium ? (
                    <>
                      <p className="text-sm text-slate-600 mb-4">
                        Refund the most recent payment. Access and credits are removed automatically.
                      </p>
                      <button
                        onClick={() => {
                          const raw = prompt('Refund amount in dollars (leave blank for full refund):')
                          if (raw === null) return
                          const trimmed = raw.trim()
                          let amountCents: number | null = null
                          if (trimmed) {
                            const parsed = Number(trimmed)
                            if (!Number.isFinite(parsed) || parsed <= 0) {
                              alert('Please enter a valid amount.')
                              return
                            }
                            amountCents = Math.round(parsed * 100)
                          }
                          const amountLabel = amountCents ? `$${(amountCents / 100).toFixed(2)}` : 'the full amount'
                          if (confirm(`Refund ${amountLabel} from the most recent payment for ${user.email}?`)) {
                            handleUserAction('refund_latest_payment', { amountCents })
                          }
                        }}
                        className="w-full bg-amber-500 text-white px-4 py-2 rounded-lg text-sm hover:bg-amber-600 transition-colors"
                      >
                        Refund latest payment
                      </button>
                    </>
                  ) : isApplePremium ? (
                    <div className="rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-600">
                      Apple purchases are managed in the App Store sandbox account. Refunds are not handled from this admin panel.
                    </div>
                  ) : isGooglePremium ? (
                    <div className="rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-600">
                      Google Play purchases are managed in Google Play. Refunds are not handled from this admin panel.
                    </div>
                  ) : (
                    <div className="rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-600">
                      No refund available. This account has admin-granted access and no paid Stripe charge.
                    </div>
                  )}
                </div>

                <div className="bg-white border border-slate-200 rounded-2xl shadow-sm p-6">
                  <h2 className="text-lg font-semibold text-slate-900 mb-3">Account security</h2>
                  <p className="text-sm text-slate-600 mb-4">
                    Log this user out everywhere if their device is lost or they can’t log out.
                  </p>
                  <button
                    onClick={() => {
                      if (confirm(`Log ${user.email} out of all devices now?`)) {
                        handleUserAction('revoke_sessions')
                      }
                    }}
