type AffiliateMeResponse =
  | { ok: true; affiliate: null }
  | {
      ok: true
      affiliate: {
        id: string
        code: string
        status: 'ACTIVE' | 'SUSPENDED'
        stripeConnectAccountId: string | null
        stripeConnectDetailsSubmitted: boolean
        stripeConnectChargesEnabled: boolean
        stripeConnectPayoutsEnabled: boolean
        stripeConnectOnboardedAt: string | null
        createdAt: string
      }
      referralLink: string
      stats: {
        clicks: number
        uniqueVisitors: number
        conversionsByType: Record<string, number>
        commissionTotalsByStatus: Record<string, number>
        payableNowCents: number
        payableNowByCurrency?: Record<string, number>
      }
      events: Array<{
        occurredAt: string
        type: string
        currency: string
        amountGrossCents: number
        stripeFeeCents: number
        amountNetCents: number
        commission: null | { status: string; commissionCents: number; payableAt: string; paidAt: string | null }
      }>
    }

function formatMoney(cents: number, currency: string) {
  const amount = cents / 100
  try {
    return new Intl.NumberFormat('en-AU', { style: 'currency', currency: currency.toUpperCase() }).format(amount)
  } catch {
    return `${amount.toFixed(2)} ${currency.toUpperCase()}`
  }
}

function formatCurrencyTotals(totals: Record<string, number> | undefined, fallbackCents: number) {
  const entries = Object.entries(totals || {}).filter(([, cents]) => Number(cents || 0) > 0)
  if (!entries.length) return formatMoney(fallbackCents || 0, 'usd')
  return entries.map(([currency, cents]) => formatMoney(Number(cents || 0), currency)).join(' / ')
}

