import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { extractAdminFromHeaders } from '@/lib/admin-auth'

/**
 * Admin endpoint to manually mark waitlist entries as unsubscribed
 * This fixes cases where someone unsubscribed before the column existed
 */
export async function POST(request: NextRequest) {
  try {
    // JWT authentication check
    const authHeader = request.headers.get('authorization')
    const admin = extractAdminFromHeaders(authHeader)

    if (!admin) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const { email } = await request.json()

    if (!email) {
      return NextResponse.json({ error: 'Email is required' }, { status: 400 })
    }

    const normalizedEmail = email.trim().toLowerCase()

    // Ensure column exists
    await prisma.$executeRawUnsafe(`
      ALTER TABLE "Waitlist" 
      ADD COLUMN IF NOT EXISTS "unsubscribed" BOOLEAN NOT NULL DEFAULT false
    `).catch(() => {})

    // Mark as unsubscribed using raw SQL
    const escapedEmail = normalizedEmail.replace(/'/g, "''")
    await prisma.$executeRawUnsafe(`
      UPDATE "Waitlist" 
      SET unsubscribed = true 
      WHERE LOWER(email) = LOWER('${escapedEmail}')
    `)

    return NextResponse.json({ 
      success: true,
      message: `Marked ${normalizedEmail} as unsubscribed`
    })

  } catch (error: any) {
    console.error('Error marking as unsubscribed:', error)
    return NextResponse.json(
      { error: 'Failed to mark as unsubscribed: ' + (error?.message || 'Unknown error') },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { extractAdminFromHeaders } from '@/lib/admin-auth'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function GET(request: NextRequest) {
  try {
    const authHeader = request.headers.get('authorization')
    const admin = extractAdminFromHeaders(authHeader)
    if (!admin) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const url = new URL(request.url)
    const rangeDaysRaw = url.searchParams.get('rangeDays') || '30'
    const rangeDays = Math.max(1, Math.min(365, parseInt(rangeDaysRaw, 10) || 30))
    const since = new Date(Date.now() - rangeDays * 24 * 60 * 60 * 1000)

    const [analysisCount, fallbackCount] = await Promise.all([
      prisma.aIUsageEvent.count({
        where: {
          feature: 'food:analysis',
          createdAt: { gte: since },
        },
      }),
      prisma.aIUsageEvent.count({
        where: {
          feature: 'food:image-analysis-fallback',
          createdAt: { gte: since },
        },
      }),
    ])

    const estimatedCallsPerAnalysis = 3
    const estimatedTotalServerCalls = analysisCount * estimatedCallsPerAnalysis

    return NextResponse.json({
      rangeDays,
      analysisCount,
      fallbackCount,
      estimatedCallsPerAnalysis,
      estimatedTotalServerCalls,
      note: 'Estimate assumes 1 note call + 1 save + 1 refresh per food photo notes request.',
    })
  } catch (error) {
    console.error('[admin food-analysis-usage] error', error)
    return NextResponse.json({ error: 'Failed to load food photo notes usage' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { extractAdminFromHeaders } from '@/lib/admin-auth'
import { prisma } from '@/lib/prisma'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const FOOD_MODEL_GOAL_NAME = '__FOOD_ANALYZER_MODEL__'
const DEFAULT_MODEL = 'gpt-5.6-sol'
const ALLOWED_MODELS = new Set(['gpt-5.6-sol'])

const normalizeEmail = (raw: string) => raw.trim().toLowerCase()

const parseModelFromGoalCategory = (category: unknown): string | null => {
  if (typeof category !== 'string' || !category.trim()) return null
  try {
    const parsed = JSON.parse(category)
    const model = typeof parsed?.model === 'string' ? parsed.model.trim() : ''
    return model || null
  } catch {
    return null
  }
}

export async function GET(req: NextRequest) {
  try {
    const authHeader = req.headers.get('authorization')
    const admin = extractAdminFromHeaders(authHeader)
    if (!admin) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const { searchParams } = new URL(req.url)
    const userEmailRaw = searchParams.get('userEmail') || ''
    const userEmail = userEmailRaw ? normalizeEmail(userEmailRaw) : ''
    if (!userEmail) return NextResponse.json({ error: 'Missing userEmail' }, { status: 400 })

    const user = await prisma.user.findUnique({
      where: { email: userEmail },
      select: { id: true, email: true },
    })
    if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

    const goal = await prisma.healthGoal.findFirst({
      where: { userId: user.id, name: FOOD_MODEL_GOAL_NAME },
      select: { id: true, category: true, updatedAt: true },
    })
    const override = goal ? parseModelFromGoalCategory(goal.category) : null
    const overrideModel = override && ALLOWED_MODELS.has(override) ? override : null

    return NextResponse.json({
      success: true,
      userEmail: user.email,
      defaultModel: DEFAULT_MODEL,
      overrideModel,
      effectiveModel: overrideModel || DEFAULT_MODEL,
      allowedModels: Array.from(ALLOWED_MODELS),
      updatedAt: goal?.updatedAt?.toISOString?.() || null,
    })
  } catch (err) {
    console.error('[admin food-analyzer-model] GET error', err)
    return NextResponse.json({ error: 'Failed to load food analyzer model' }, { status: 500 })
  }
}

export async function POST(req: NextRequest) {
  try {
    const authHeader = req.headers.get('authorization')
    const admin = extractAdminFromHeaders(authHeader)
    if (!admin) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const body = await req.json().catch(() => ({} as any))
    const userEmailRaw = typeof body?.userEmail === 'string' ? body.userEmail : ''
    const userEmail = userEmailRaw ? normalizeEmail(userEmailRaw) : ''
    const modelRaw = typeof body?.model === 'string' ? body.model.trim() : ''
    const model = modelRaw === '' || modelRaw === 'default' ? null : modelRaw

    if (!userEmail) return NextResponse.json({ error: 'Missing userEmail' }, { status: 400 })
    if (model !== null && !ALLOWED_MODELS.has(model)) {
      return NextResponse.json({ error: `Unsupported model: ${model}` }, { status: 400 })
    }

    const user = await prisma.user.findUnique({
      where: { email: userEmail },
      select: { id: true, email: true },
    })
    if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

    const existing = await prisma.healthGoal.findFirst({
      where: { userId: user.id, name: FOOD_MODEL_GOAL_NAME },
      select: { id: true },
    })

    if (model === null) {
      if (existing?.id) {
        await prisma.healthGoal.delete({ where: { id: existing.id } })
      }
      return NextResponse.json({
        success: true,
        userEmail: user.email,
        defaultModel: DEFAULT_MODEL,
        overrideModel: null,
        effectiveModel: DEFAULT_MODEL,
      })
    }

    const payload = JSON.stringify({ model })
    if (existing?.id) {
      await prisma.healthGoal.update({
        where: { id: existing.id },
        data: { category: payload, currentRating: 0 },
      })
    } else {
      await prisma.healthGoal.create({
        data: {
          userId: user.id,
          name: FOOD_MODEL_GOAL_NAME,
          category: payload,
          currentRating: 0,
        },
      })
    }

    return NextResponse.json({
      success: true,
      userEmail: user.email,
      defaultModel: DEFAULT_MODEL,
      overrideModel: model,
      effectiveModel: model,
    })
  } catch (err) {
    console.error('[admin food-analyzer-model] POST error', err)
    return NextResponse.json({ error: 'Failed to update food analyzer model' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { extractAdminFromHeaders } from '@/lib/admin-auth'
import OpenAI from 'openai'
import { chatCompletionWithCost } from '@/lib/metered-openai'
import { openaiCostCentsForTokens, costCentsForTokens } from '@/lib/cost-meter'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const getOpenAIClient = (): OpenAI | null => {
  if (!process.env.OPENAI_API_KEY) return null
  return new OpenAI({ apiKey: process.env.OPENAI_API_KEY })
}

const isSafeImageUrl = (url: string) => /^https?:\/\//i.test(url) && url.length < 2000

const buildBenchmarkMessages = (imageUrl: string) => {
  return [
    {
      role: 'user',
      content: [
        {
          type: 'text',
          text:
            'Analyze this food image.\n' +
            '- Return short, plain ingredient names (no "several components:" prefixes).\n' +
            '- For sliced produce (e.g., avocado slices), treat as a portion (grams or fraction of whole), NOT "pieces".\n' +
            '- Be conservative when uncertain and mark guesses.\n' +
            'Return ONLY a JSON block with shape:\n' +
            '{"items":[{"name":"string","brand":null,"serving_size":"string","servings":1,"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"fiber_g":0,"sugar_g":0,"isGuess":false}],"total":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"fiber_g":0,"sugar_g":0}}',
        },
        { type: 'image_url', image_url: { url: imageUrl, detail: 'high' } },
      ],
    },
  ]
}

export async function POST(req: NextRequest) {
  try {
    const authHeader = req.headers.get('authorization')
    const admin = extractAdminFromHeaders(authHeader)
    if (!admin) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const body = await req.json().catch(() => ({} as any))
    const imageUrl = typeof body?.imageUrl === 'string' ? body.imageUrl.trim() : ''
    const models = Array.isArray(body?.models) ? body.models : []
    const modelList =
      models.length > 0
        ? models.filter((m: any) => typeof m === 'string' && m.trim().length > 0).slice(0, 3)
        : ['gpt-5.6-sol']

    if (!imageUrl || !isSafeImageUrl(imageUrl)) {
      return NextResponse.json({ error: 'Provide a public https:// imageUrl' }, { status: 400 })
    }

    const openai = getOpenAIClient()
    if (!openai) return NextResponse.json({ error: 'AI service not configured' }, { status: 500 })

    const messages = buildBenchmarkMessages(imageUrl)

    const results: any[] = []
    for (const model of modelList) {
      const isGpt5Family = model.toLowerCase().includes('gpt-5')
      const out = await chatCompletionWithCost(
        openai,
        {
          model,
          messages,
          ...(isGpt5Family ? { max_completion_tokens: 700 } : { max_tokens: 700 }),
          temperature: 0,
        } as any,
        { feature: 'admin:food-benchmark' }
      )
      const text = out.completion.choices?.[0]?.message?.content?.trim?.() || ''
      const vendorCostCents = openaiCostCentsForTokens(model, {
        promptTokens: out.promptTokens,
        completionTokens: out.completionTokens,
      })
      const billedCostCents = costCentsForTokens(model, {
        promptTokens: out.promptTokens,
        completionTokens: out.completionTokens,
      })
      results.push({
        model,
        promptTokens: out.promptTokens,
        completionTokens: out.completionTokens,
        vendorCostCents,
        billedCostCents,
        outputPreview: text.slice(0, 1200),
      })
    }

    return NextResponse.json({
      success: true,
      imageUrl,
      results,
      note:
        'Benchmark prompt is simplified vs the live analyzer. Use this to compare relative cost/token usage and qualitative output.',
    })
  } catch (err: any) {
    console.error('[admin food-benchmark] error', err)
    return NextResponse.json({ error: err?.message || 'Benchmark failed' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { extractAdminFromHeaders } from '@/lib/admin-auth'
import { costCentsForTokens, openaiCostCentsForTokens } from '@/lib/cost-meter'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const parseRangeDays = (raw: string | null): number => {
  const n = Number(raw)
  if (!Number.isFinite(n) || n <= 0) return 7
  return Math.min(365, Math.max(1, Math.floor(n)))
}

const avg = (nums: number[]) => {
  if (!nums.length) return 0
  return nums.reduce((a, b) => a + b, 0) / nums.length
}

export async function GET(req: NextRequest) {
  try {
    const authHeader = req.headers.get('authorization')
    const admin = extractAdminFromHeaders(authHeader)
    if (!admin) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const { searchParams } = new URL(req.url)
    const rangeDays = parseRangeDays(searchParams.get('rangeDays'))

    const now = new Date()
    const start = new Date(now.getTime() - rangeDays * 24 * 60 * 60 * 1000)

    // Prefer the per-image usage logs (avoid double-counting the later aggregate "food:analysis" event).
    const rows = await prisma.aIUsageEvent.findMany({
      where: {
        createdAt: { gte: start, lte: now },
        success: true,
        endpoint: '/api/analyze-food',
        OR: [{ feature: 'food:image-analysis' }, { feature: 'food:image-reanalysis' }],
      },
      select: {
        model: true,
        promptTokens: true,
        completionTokens: true,
        totalTokens: true,
        costCents: true,
      },
      orderBy: { createdAt: 'desc' },
      take: 500,
    })

    const promptTokens = rows.map((r) => Number(r.promptTokens || 0)).filter((n) => n > 0)
    const completionTokens = rows.map((r) => Number(r.completionTokens || 0)).filter((n) => n >= 0)
    const totalTokens = rows
      .map((r) => Number(r.totalTokens || (Number(r.promptTokens || 0) + Number(r.completionTokens || 0))))
      .filter((n) => n > 0)
    const billedCostCents = rows.map((r) => Number(r.costCents || 0)).filter((n) => n >= 0)

    const avgPrompt = Math.round(avg(promptTokens))
    const avgCompletion = Math.round(avg(completionTokens))
    const avgTotal = Math.round(avg(totalTokens))
    const avgBilled = Math.round(avg(billedCostCents))

    const simulate = (model: string) => {
      const vendor = openaiCostCentsForTokens(model, { promptTokens: avgPrompt, completionTokens: avgCompletion })
      const billed = costCentsForTokens(model, { promptTokens: avgPrompt, completionTokens: avgCompletion })
      const analysesPer1400 = avgTotal > 0 ? Math.floor(1400 / Math.max(1, billed)) : 0
      return {
        model,
        vendorCostCents: vendor,
        billedCostCents: billed,
        analysesPer1400Credits: analysesPer1400,
      }
    }

    // Models to compare (you can add/remove in the UI)
    const simulations = [
      simulate('gpt-5.6-sol'),
      simulate('gpt-4o'),
      simulate('gpt-5.2'),
      simulate('gpt-5-mini'),
      simulate('gpt-5.2-pro'),
    ]

    return NextResponse.json({
      success: true,
      rangeDays,
      samples: rows.length,
      averages: {
        promptTokens: avgPrompt,
        completionTokens: avgCompletion,
        totalTokens: avgTotal,
        billedCostCents: avgBilled,
      },
      simulations,
      notes: {
        interpretation:
          'Simulated costs assume token usage stays the same when switching models. Real token usage and accuracy may change; use the benchmark tool for head-to-head tests.',
        credits: 'Helfi credits are cents. 1400 credits is the current $20/month plan mapping.',
        sampling: 'This is based on up to 500 recent food:image-* events within the selected range.',
      },
    })
  } catch (err) {
    console.error('[admin food-cost-sim] error', err)
    return NextResponse.json({ error: 'Failed to compute food cost simulation' }, { status: 500 })
  }
}

