import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import crypto from 'crypto'

const LOGIN_TTL_MS = 5 * 60 * 1000

async function cleanupExpired() {
  const now = new Date()
  await prisma.adminQrLogin.deleteMany({
    where: { expiresAt: { lt: now } }
  })
}

export async function GET(request: NextRequest) {
  try {
    await cleanupExpired()

    const token = crypto.randomBytes(32).toString('hex')
    const expiresAt = new Date(Date.now() + LOGIN_TTL_MS)

    await prisma.adminQrLogin.create({
      data: {
        token,
        status: 'PENDING',
        expiresAt
      }
    })

    const origin = request.headers.get('origin') || request.headers.get('host')
    const protocol = request.headers.get('x-forwarded-proto') || 'https'
    const baseUrl =
      process.env.NEXT_PUBLIC_APP_URL ||
      (origin ? `${protocol}://${origin}` : 'https://helfi.ai')

    return NextResponse.json({
      token,
      url: `${baseUrl}/admin-panel/qr-login?token=${token}`,
      expiresAt: expiresAt.getTime()
    })
  } catch (error: any) {
    console.error('[ADMIN QR LOGIN] start error', error)
    return NextResponse.json({ error: 'Failed to create QR login' }, { status: 500 })
  }
}

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import jwt from 'jsonwebtoken'

const JWT_SECRET = process.env.JWT_SECRET || process.env.NEXTAUTH_SECRET

async function cleanupExpired() {
  const now = new Date()
  await prisma.adminQrLogin.deleteMany({
    where: { expiresAt: { lt: now } }
  })
}

export async function GET(request: NextRequest) {
  try {
    if (!JWT_SECRET) {
      return NextResponse.json({ error: 'Admin login secret not configured' }, { status: 500 })
    }
    const { searchParams } = new URL(request.url)
    const token = (searchParams.get('token') || '').trim()
    if (!token) {
      return NextResponse.json({ error: 'Token required' }, { status: 400 })
    }

    await cleanupExpired()

    const entry = await prisma.adminQrLogin.findUnique({
      where: { token }
    })

    if (!entry) {
      return NextResponse.json({ error: 'Invalid or expired token' }, { status: 404 })
    }

    if (!entry.expiresAt || entry.expiresAt.getTime() < Date.now()) {
      await prisma.adminQrLogin.delete({ where: { token } })
      return NextResponse.json({ error: 'Token expired' }, { status: 410 })
    }

    if (entry.status !== 'APPROVED' || !entry.adminId || !entry.email) {
      return NextResponse.json({ status: 'PENDING' })
    }

    const adminUser = await prisma.adminUser.findUnique({
      where: { id: entry.adminId },
      select: {
        id: true,
        email: true,
        name: true,
        role: true,
        isActive: true
      }
    })

    if (!adminUser || adminUser.isActive === false) {
      await prisma.$executeRawUnsafe(`DELETE FROM "AdminQrLogin" WHERE token = $1`, token)
      return NextResponse.json({ error: 'Admin user not found or inactive' }, { status: 404 })
    }

    const jwtToken = jwt.sign(
      {
        adminId: adminUser.id,
        email: adminUser.email,
        role: adminUser.role
      },
      JWT_SECRET,
      { expiresIn: '7d' }
    )

    await prisma.adminQrLogin.delete({ where: { token } })

    return NextResponse.json({
      status: 'APPROVED',
      token: jwtToken,
      admin: {
        id: adminUser.id,
        email: adminUser.email,
        name: adminUser.name,
        role: adminUser.role
      }
    })
  } catch (error: any) {
    console.error('[ADMIN QR LOGIN] status error', error)
    return NextResponse.json({ error: 'Failed to check QR login status' }, { status: 500 })
  }
}

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import jwt from 'jsonwebtoken'

const JWT_SECRET = process.env.JWT_SECRET || process.env.NEXTAUTH_SECRET

/**
 * Refresh admin token - extends expiration if token is still valid
 * This allows admins to stay logged in without re-authenticating
 */
export async function POST(request: NextRequest) {
  try {
    if (!JWT_SECRET) {
      return NextResponse.json({ error: 'Admin login secret not configured' }, { status: 500 })
    }

    const authHeader = request.headers.get('authorization')
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return NextResponse.json({ error: 'Authorization header required' }, { status: 401 })
    }

    const token = authHeader.replace('Bearer ', '')
    // Important: admins reported "refresh token" doesn't work once the JWT is expired.
    // We allow refreshing an expired token if it is still correctly signed, and not too old.
    let decoded: any = null
    try {
      decoded = jwt.verify(token, JWT_SECRET, { ignoreExpiration: true })
    } catch {
      decoded = null
    }

    if (!decoded) {
      return NextResponse.json({ error: 'Invalid or expired token' }, { status: 401 })
    }

    // Safety: don't allow refreshing indefinitely if someone stole an old token.
    // If the token was originally issued more than 30 days ago, require re-login.
    const iatSeconds = typeof decoded.iat === 'number' ? decoded.iat : null
    if (iatSeconds) {
      const ageMs = Date.now() - iatSeconds * 1000
      const maxAgeMs = 30 * 24 * 60 * 60 * 1000
      if (ageMs > maxAgeMs) {
        return NextResponse.json({ error: 'Token too old. Please log in again.' }, { status: 401 })
      }
    }

    // Verify admin user still exists and is active
    const adminUser = await prisma.adminUser.findUnique({
      where: { id: String(decoded.adminId || '') },
      select: {
        id: true,
        email: true,
        name: true,
        role: true,
        isActive: true
      }
    })

    if (!adminUser || !adminUser.isActive) {
      return NextResponse.json({ error: 'Admin user not found or inactive' }, { status: 401 })
    }

    // Create new token with extended expiration (7 days)
    const newToken = jwt.sign(
      {
        adminId: adminUser.id,
        email: adminUser.email,
        role: adminUser.role
      },
      JWT_SECRET,
      { expiresIn: '7d' }
    )

    return NextResponse.json({
      success: true,
      token: newToken,
      admin: {
        id: adminUser.id,
        email: adminUser.email,
        name: adminUser.name,
        role: adminUser.role
      }
    })
  } catch (error) {
    console.error('Error refreshing admin token:', error)
    return NextResponse.json({ error: 'Failed to refresh token' }, { status: 500 })
  }
}

