import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { extractAdminFromHeaders } from '@/lib/admin-auth'
import { CreditManager } from '@/lib/credit-system'
import { revokeUserSessions } from '@/lib/session-revocation'
import { ensureSubscriptionStoreColumns } from '@/lib/native-billing/subscription-store'
import Stripe from 'stripe'
import bcrypt from 'bcryptjs'

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || '', { apiVersion: '2024-06-20' })

export const dynamic = 'force-dynamic'
export const revalidate = 0

export async function GET(request: NextRequest) {
  try {
    // JWT authentication check
    const authHeader = request.headers.get('authorization')
    const admin = extractAdminFromHeaders(authHeader)

    if (!admin) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const { searchParams } = new URL(request.url)
    const search = searchParams.get('search') || ''
    const userId = searchParams.get('userId')
    const status = searchParams.get('status') || 'all'
    const plan = searchParams.get('plan') || 'all'
    const page = parseInt(searchParams.get('page') || '1')
    const limit = parseInt(searchParams.get('limit') || '20')

    // Build filter conditions
    const where: any = {}

    if (userId) {
      where.id = userId
    } else if (search) {
      where.OR = [
        { email: { contains: search, mode: 'insensitive' } },
        { name: { contains: search, mode: 'insensitive' } }
      ]
    }

    if (!userId && plan !== 'all') {
      if (plan === 'premium') {
        where.subscription = {
          plan: 'PREMIUM'
        }
      } else if (plan === 'non-subscribed') {
        where.subscription = null
      }
    }

    // Get total count for pagination
    let totalUsers = 0
    try {
      totalUsers = await prisma.user.count({ where })
    } catch (e) {
      console.error('User count failed, returning 0:', e)
      totalUsers = 0
    }

    // Get users with pagination
    await ensureSubscriptionStoreColumns()
    const users = await prisma.user.findMany({
      where,
      select: {
        id: true,
        email: true,
        name: true,
        createdAt: true,
        gender: true,
        dailyAnalysisCredits: true,
        dailyAnalysisUsed: true,
        additionalCredits: true,
        walletMonthlyResetAt: true,
        totalAnalysisCount: true,
        dailyFoodAnalysisUsed: true,
        dailyFoodReanalysisUsed: true,
        dailyMedicalAnalysisUsed: true,
        dailyInteractionAnalysisUsed: true,
        lastAnalysisResetDate: true,
        monthlyInsightsGenerationUsed: true,
        monthlyMedicalImageAnalysisUsed: true,
        monthlySymptomAnalysisUsed: true,
        subscription: {
          select: {
            plan: true,
            monthlyPriceCents: true,
            endDate: true,
            startDate: true,
            stripeSubscriptionId: true,
            source: true,
            storeProductId: true,
            storeTransactionId: true,
            storeOriginalTransactionId: true,
          },
        },
        creditTopUps: {
          where: {
            expiresAt: { gt: new Date() }
          },
          select: {
            amountCents: true,
            usedCents: true,
            expiresAt: true
          }
        },
        _count: {
          select: {
            healthGoals: true,
            supplements: true,
            medications: true,
            foodLogs: true,
            exerciseLogs: true
          }
        }
      },
      orderBy: { createdAt: 'desc' },
      skip: (page - 1) * limit,
      take: limit
    })

    // Calculate total available credits from CreditTopUp records + non-expiring additional credits
    const usersWithCredits = users.map(user => {
      const now = new Date()
      const topUpAvailable = user.creditTopUps
        .filter(topUp => topUp.expiresAt > now)
        .reduce((sum, topUp) => sum + Math.max(0, topUp.amountCents - topUp.usedCents), 0)
      const additionalAvailable = Math.max(0, user.additionalCredits || 0)
      const availableCredits = topUpAvailable + additionalAvailable

      return {
        ...user,
        totalAvailableCredits: availableCredits, // Total in cents (which equals credits)
        additionalAvailableCredits: additionalAvailable,
        topUpAvailableCredits: topUpAvailable,
      }
    })

    return NextResponse.json({
      users: usersWithCredits,
      pagination: {
        page,
        limit,
        total: totalUsers,
        pages: Math.ceil(totalUsers / limit)
      }
    })

  } catch (error) {
    console.error('Error fetching users:', error)
    return NextResponse.json({ error: 'Failed to fetch users' }, { status: 500 })
  }
}

export async function POST(request: NextRequest) {
  try {
    // JWT authentication check
    const authHeader = request.headers.get('authorization')
    const admin = extractAdminFromHeaders(authHeader)

    if (!admin) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const body = await request.json()
    const { action, userId, data } = body

    await ensureSubscriptionStoreColumns()

    switch (action) {
      case 'sync_stripe_subscription': {
        const targetEmail = data?.email?.toLowerCase()
        if (!targetEmail) {
          return NextResponse.json({ error: 'Email required' }, { status: 400 })
        }

        // Find user
        const user = await prisma.user.findUnique({ where: { email: targetEmail } })
        if (!user) {
          return NextResponse.json({ error: 'User not found' }, { status: 404 })
        }

        // Lookup Stripe customer and active subscription
        if (!process.env.STRIPE_SECRET_KEY) {
          return NextResponse.json({ error: 'Stripe not configured' }, { status: 500 })
        }

        const customers = await stripe.customers.list({ email: targetEmail, limit: 1 })
        if (!customers.data.length) {
          return NextResponse.json({ error: 'Stripe customer not found' }, { status: 404 })
        }
        const customer = customers.data[0]
        const subs = await stripe.subscriptions.list({ customer: customer.id, status: 'all', limit: 1 })
        if (!subs.data.length) {
          return NextResponse.json({ error: 'Stripe subscription not found' }, { status: 404 })
        }
        const sub = subs.data[0]
        const amountCents = sub.items.data[0]?.price?.unit_amount || 0
        const currentPeriodStart = sub.current_period_start ? new Date(sub.current_period_start * 1000) : new Date()
        const currentPeriodEnd = sub.current_period_end ? new Date(sub.current_period_end * 1000) : null

        // Update subscription to Stripe details (auto-add column if missing)
        const upsertSubscription = async () => {
          await prisma.subscription.upsert({
            where: { userId: user.id },
            update: {
              plan: 'PREMIUM',
              monthlyPriceCents: amountCents,
              stripeSubscriptionId: sub.id,
              source: 'stripe',
              storeProductId: sub.items.data[0]?.price?.id || null,
              storeTransactionId: sub.id,
              storeOriginalTransactionId: sub.id,
              startDate: currentPeriodStart,
              endDate: currentPeriodEnd
            } as any,
            create: {
              userId: user.id,
              plan: 'PREMIUM',
              monthlyPriceCents: amountCents,
              stripeSubscriptionId: sub.id,
              source: 'stripe',
              storeProductId: sub.items.data[0]?.price?.id || null,
              storeTransactionId: sub.id,
              storeOriginalTransactionId: sub.id,
              startDate: currentPeriodStart,
              endDate: currentPeriodEnd
            } as any
          })
        }

        try {
          await upsertSubscription()
        } catch (err: any) {
          const msg = err?.message || ''
          if (msg.includes('stripeSubscriptionId')) {
            // Add column if missing (defensive for older DBs)
            await prisma.$executeRawUnsafe(
              'ALTER TABLE \"Subscription\" ADD COLUMN IF NOT EXISTS \"stripeSubscriptionId\" TEXT'
            )
            await upsertSubscription()
          } else {
            throw err
          }
        }

        // Reset wallet/monthly counters to align with Stripe period start
        await prisma.user.update({
          where: { id: user.id },
          data: {
            walletMonthlyUsedCents: 0,
            walletMonthlyResetAt: currentPeriodStart,
            monthlySymptomAnalysisUsed: 0,
            monthlyFoodAnalysisUsed: 0,
            monthlyMedicalImageAnalysisUsed: 0,
            monthlyInteractionAnalysisUsed: 0,
            monthlyInsightsGenerationUsed: 0,
          } as any
        })

        return NextResponse.json({
          success: true,
          userId: user.id,
          stripeSubscriptionId: sub.id,
          startDate: currentPeriodStart,
          endDate: currentPeriodEnd,
          amountCents
        })
      }

      case 'activate':
        // Create or update subscription to PREMIUM (defaults to $20 tier)
        await prisma.subscription.upsert({
          where: { userId },
          update: { 
            plan: 'PREMIUM',
            monthlyPriceCents: 2000, // Default to $20 tier
            stripeSubscriptionId: null,
            source: 'admin',
            storeProductId: null,
            storeTransactionId: null,
            storeOriginalTransactionId: null,
          },
          create: { 
            userId, 
            plan: 'PREMIUM',
            monthlyPriceCents: 2000,
            stripeSubscriptionId: null,
            source: 'admin',
            storeProductId: null,
            storeTransactionId: null,
            storeOriginalTransactionId: null,
          }
        })
        // Update daily credits for premium
        await prisma.user.update({
          where: { id: userId },
          data: { dailyAnalysisCredits: 30 }
        })
        break

      case 'revoke_sessions': {
        const revokedAt = await revokeUserSessions(userId)
        if (!revokedAt) {
          return NextResponse.json({ error: 'Failed to revoke sessions' }, { status: 500 })
        }
        return NextResponse.json({
          success: true,
          message: 'User sessions revoked. They will be logged out on their next request.',
          revokedAt,
        })
      }
      case 'set_password': {
        const newPassword = typeof data?.newPassword === 'string' ? data.newPassword : ''
        if (!newPassword || newPassword.length < 8) {
          return NextResponse.json({ error: 'Password must be at least 8 characters.' }, { status: 400 })
        }
        const passwordHash = await bcrypt.hash(newPassword, 12)
        await prisma.user.update({
          where: { id: userId },
          data: {
            passwordHash,
            emailVerified: new Date(),
          },
        })
        return NextResponse.json({ success: true, message: 'Password reset successfully.' })
      }

      case 'grant_subscription':
        // Grant subscription with specific tier ($10, $20, $30, or $50)
        const tier = data?.tier // '10', '20', '30', or '50'
        const priceCentsMap: Record<string, number> = {
          '10': 1000,
          '20': 2000,
          '30': 3000,
          '50': 5000
        }
        const priceCents = priceCentsMap[tier || '20'] || 2000

        // Check if subscription already exists and if tier is changing
        const existingSub = await prisma.subscription.findUnique({
          where: { userId }
        })

        // If tier is changing, reset startDate to start new billing cycle
        const shouldResetStartDate = existingSub && existingSub.monthlyPriceCents !== priceCents

        const newStartDate = shouldResetStartDate || !existingSub ? new Date() : existingSub.startDate

        await prisma.subscription.upsert({
          where: { userId },
          update: { 
            plan: 'PREMIUM',
            monthlyPriceCents: priceCents,
            // Reset startDate if tier changed or if subscription didn't exist
            startDate: newStartDate,
            stripeSubscriptionId: null,
            source: 'admin',
            storeProductId: null,
            storeTransactionId: null,
            storeOriginalTransactionId: null,
          },
          create: { 
            userId, 
            plan: 'PREMIUM',
            monthlyPriceCents: priceCents,
            startDate: newStartDate,
            stripeSubscriptionId: null,
            source: 'admin',
            storeProductId: null,
            storeTransactionId: null,
            storeOriginalTransactionId: null,
          }
        })

        // Reset monthly counters and wallet when starting new subscription cycle
        if (shouldResetStartDate || !existingSub) {
          await prisma.user.update({
            where: { id: userId },
            data: {
              dailyAnalysisCredits: 30,
              walletMonthlyUsedCents: 0,
              walletMonthlyResetAt: newStartDate,
              monthlySymptomAnalysisUsed: 0,
              monthlyFoodAnalysisUsed: 0,
              monthlyMedicalImageAnalysisUsed: 0,
              monthlyInteractionAnalysisUsed: 0,
              monthlyInsightsGenerationUsed: 0,
            } as any
          })
        } else {
          // Just update daily credits if not resetting
          await prisma.user.update({
            where: { id: userId },
            data: { dailyAnalysisCredits: 30 }
          })
        }
        break

      case 'deactivate':
        // Remove subscription (delete subscription record)
        await prisma.subscription.delete({
          where: { userId }
        }).catch(() => {
          // Ignore if subscription doesn't exist
        })
        break

      case 'grant_free_access':
        // Grant permanent PREMIUM subscription (admin-only) - defaults to $20 tier
        const endDate = new Date()
        endDate.setFullYear(endDate.getFullYear() + 100) // 100 years = permanent

        await prisma.subscription.upsert({
          where: { userId },
          update: { 
            plan: 'PREMIUM',
            endDate: endDate,
            monthlyPriceCents: 2000, // Default to $20 tier
            stripeSubscriptionId: null,
            source: 'admin',
            storeProductId: null,
            storeTransactionId: null,
            storeOriginalTransactionId: null,
          },
          create: { 
            userId, 
            plan: 'PREMIUM',
            endDate: endDate,
            monthlyPriceCents: 2000,
            stripeSubscriptionId: null,
            source: 'admin',
            storeProductId: null,
            storeTransactionId: null,
            storeOriginalTransactionId: null,
          }
        })
        break

      case 'grant_trial':
        // Grant temporary PREMIUM subscription (admin-only)
        const trialDays = data?.trialDays || 30
        const trialEndDate = new Date()
        trialEndDate.setDate(trialEndDate.getDate() + trialDays)

        // For 7-day trials, grant 250 credits ($5 tier = 500 cents, 50% = 250 credits)
        // For 30-day trials, grant 1,000 credits ($20 tier = 2000 cents, 50% = 1,000 credits)
        const monthlyPriceCents = trialDays === 7 ? 500 : 2000

        await prisma.subscription.upsert({
          where: { userId },
          update: { 
            plan: 'PREMIUM',
            endDate: trialEndDate,
            monthlyPriceCents: monthlyPriceCents,
            stripeSubscriptionId: null,
            source: 'admin',
            storeProductId: null,
            storeTransactionId: null,
            storeOriginalTransactionId: null,
          },
          create: { 
            userId, 
            plan: 'PREMIUM',
            endDate: trialEndDate,
            monthlyPriceCents: monthlyPriceCents,
            stripeSubscriptionId: null,
            source: 'admin',
            storeProductId: null,
            storeTransactionId: null,
            storeOriginalTransactionId: null,
          }
        })
        break

      case 'update_profile':
        // Update user profile information
        await prisma.user.update({
          where: { id: userId },
          data: {
            name: data.name,
            email: data.email,
            gender: data.gender,
            weight: data.weight,
            height: data.height
          }
        })
        break

      case 'delete_user':
        // Delete user and all related data (cascading)
        await prisma.user.delete({
          where: { id: userId }
        })
        break

      case 'add_credits':
        // Add credits using wallet-based system (CreditTopUp)
        // Credits = cents (1 credit = 1 cent). Admin grants should reflect immediately in the meter,
        // so we store them as non-expiring additionalCredits.
        const creditPackage = data?.creditPackage // e.g., '250', '500', '1000'
        const creditAmount = data?.creditAmount // Direct credit amount

        let centsAmount = 0

        if (creditPackage) {
          // Credit packages: 250, 500, or 1000 credits (1 credit = 1 cent)
          const packageMap: Record<string, number> = {
            '250': 250,    // 250 credits = 250 cents
            '500': 500,    // 500 credits = 500 cents
            '1000': 1000   // 1000 credits = 1000 cents
          }

          centsAmount = packageMap[creditPackage]
          if (!centsAmount) {
            return NextResponse.json({ error: 'Invalid credit package. Use: 250, 500, or 1000' }, { status: 400 })
          }
        } else if (creditAmount && creditAmount > 0) {
          // Direct credit amount (credits = cents)
          centsAmount = creditAmount
        } else {
          return NextResponse.json({ error: 'Invalid credit amount or package. Provide creditPackage (250/500/1000) or creditAmount (number)' }, { status: 400 })
        }

        // Store as non-expiring additionalCredits so the meter and consumption see it immediately.
        await prisma.user.update({
          where: { id: userId },
          data: {
            additionalCredits: {
              increment: centsAmount,
            },
          },
        })
        break

      case 'remove_credits':
        // Remove credits by creating a negative top-up or marking existing top-ups as used
        const removeAmount = data?.creditAmount || 0
        if (removeAmount <= 0) {
          return NextResponse.json({ error: 'Invalid credit amount to remove' }, { status: 400 })
        }

        // Get all non-expired, unused top-ups
        const now = new Date()
        const topUps = await prisma.creditTopUp.findMany({
          where: {
            userId,
            expiresAt: { gt: now }
          },
          orderBy: { expiresAt: 'asc' } // FIFO - oldest first
        })

        let remainingToRemove = removeAmount
        for (const topUp of topUps) {
          if (remainingToRemove <= 0) break

          const available = topUp.amountCents - topUp.usedCents
          if (available > 0) {
            const toRemove = Math.min(remainingToRemove, available)
            await prisma.creditTopUp.update({
              where: { id: topUp.id },
              data: {
                usedCents: topUp.usedCents + toRemove
              }
            })
            remainingToRemove -= toRemove
          }
        }

        if (remainingToRemove > 0) {
          return NextResponse.json({ 
            error: `Only ${removeAmount - remainingToRemove} credits were available to remove. ${remainingToRemove} credits could not be removed.`,
            partial: true 
          }, { status: 200 }) // Still return 200 since some credits were removed
        }
        break

      case 'refund_latest_payment': {
        if (!process.env.STRIPE_SECRET_KEY) {
          return NextResponse.json({ error: 'Stripe not configured' }, { status: 500 })
        }
        const user = await prisma.user.findUnique({
          where: { id: userId },
          select: { email: true },
        })
        if (!user?.email) {
          return NextResponse.json({ error: 'User email not found' }, { status: 404 })
        }

        const customers = await stripe.customers.list({ email: user.email.toLowerCase(), limit: 1 })
        if (!customers.data.length) {
          return NextResponse.json({ error: 'Stripe customer not found' }, { status: 404 })
        }
        const customer = customers.data[0]
        const charges = await stripe.charges.list({ customer: customer.id, limit: 10 })
        const charge = charges.data.find(
          (c) => c.paid && c.status === 'succeeded' && (c.amount - c.amount_refunded) > 0
        )
        if (!charge) {
          return NextResponse.json({ error: 'No refundable payments found' }, { status: 404 })
        }

        const remaining = charge.amount - charge.amount_refunded
        const requestedAmount = data?.amountCents ? Number(data.amountCents) : null
        if (requestedAmount != null && (Number.isNaN(requestedAmount) || requestedAmount <= 0)) {
          return NextResponse.json({ error: 'Invalid refund amount' }, { status: 400 })
        }
        if (requestedAmount != null && requestedAmount > remaining) {
          return NextResponse.json({ error: 'Refund amount exceeds remaining balance' }, { status: 400 })
        }

        const refund = await stripe.refunds.create({
          charge: charge.id,
          ...(requestedAmount ? { amount: requestedAmount } : {}),
        })

        return NextResponse.json({
          success: true,
          refundId: refund.id,
          refundedAmountCents: refund.amount,
          currency: refund.currency,
          chargeId: charge.id,
          remainingAmountCents: Math.max(0, remaining - refund.amount),
        })
      }

      case 'reset_daily_quota':
        // Reset daily analysis quota using new credit system
        await CreditManager.resetDailyQuota(userId)
        break

      case 'view_credit_usage':
        // Get detailed credit usage information using new credit system
        const creditUsage = await CreditManager.getCreditUsage(userId)
        return NextResponse.json({ success: true, creditUsage })

      default:
        return NextResponse.json({ error: 'Invalid action' }, { status: 400 })
    }

    return NextResponse.json({ success: true, message: `User ${action} completed successfully` })

  } catch (error) {
    console.error('Error managing user:', error)
    const errorMessage = error instanceof Error ? error.message : 'Failed to manage user'
    return NextResponse.json({ error: errorMessage }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { extractAdminFromHeaders } from '@/lib/admin-auth'

// This API route uses dynamic headers and should not be statically generated
export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function GET(request: NextRequest) {
  try {
    // JWT authentication check
    const authHeader = request.headers.get('authorization')
    const admin = extractAdminFromHeaders(authHeader)

    if (!admin) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      )
    }

    // Get user statistics
    const totalUsers = await prisma.user.count()

    const usersWithProfiles = await prisma.user.count({
      where: {
        OR: [
          { name: { not: null } },
          { gender: { not: null } },
          { weight: { not: null } },
          { height: { not: null } }
        ]
      }
    })

    const usersWithGoals = await prisma.user.count({
      where: {
        healthGoals: {
          some: {}
        }
      }
    })

    const usersWithSupplements = await prisma.user.count({
      where: {
        supplements: {
          some: {}
        }
      }
    })

    const usersWithMedications = await prisma.user.count({
      where: {
        medications: {
          some: {}
        }
      }
    })

    const usersWithFoodLogs = await prisma.user.count({
      where: {
        foodLogs: {
          some: {}
        }
      }
    })

    // Get recent signups (last 30 days)
    const thirtyDaysAgo = new Date()
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30)

    const recentSignups = await prisma.user.count({
      where: {
        createdAt: {
          gte: thirtyDaysAgo
        }
      }
    })

    // Get users by gender breakdown
    const genderStats = await prisma.user.groupBy({
      by: ['gender'],
      _count: {
        gender: true
      }
    })

    // Get recent users (last 10)
    const recentUsers = await prisma.user.findMany({
      orderBy: { createdAt: 'desc' },
      take: 10,
      select: {
        id: true,
        email: true,
        name: true,
        createdAt: true,
        gender: true,
        _count: {
          select: {
            healthGoals: true,
            supplements: true,
            medications: true,
            foodLogs: true
          }
        }
      }
    })

    // Device interest counts (from user.data JSON field category if present)
    // Count from hidden HealthGoal records storing device interest
    const deviceFitbit = await prisma.healthGoal.count({ where: { name: '__DEVICE_INTEREST__', category: { contains: '"fitbit":true' } } })
    const deviceGarmin = await prisma.healthGoal.count({ where: { name: '__DEVICE_INTEREST__', category: { contains: '"garmin":true' } } })
    const deviceGoogleFit = await prisma.healthGoal.count({ where: { name: '__DEVICE_INTEREST__', category: { contains: '"googleFit":true' } } })
    const deviceOura = await prisma.healthGoal.count({ where: { name: '__DEVICE_INTEREST__', category: { contains: '"oura":true' } } })
    const devicePolar = await prisma.healthGoal.count({ where: { name: '__DEVICE_INTEREST__', category: { contains: '"polar":true' } } })
    const deviceHuawei = await prisma.healthGoal.count({ where: { name: '__DEVICE_INTEREST__', category: { contains: '"huawei":true' } } })

    const stats = {
      totalUsers,
      usersWithProfiles,
      usersWithGoals,
      usersWithSupplements,
      usersWithMedications,
      usersWithFoodLogs,
      recentSignups,
      genderStats,
      recentUsers,
      completionRate: totalUsers > 0 ? Math.round((usersWithProfiles / totalUsers) * 100) : 0,
      deviceInterest: {
        fitbit: deviceFitbit,
        garmin: deviceGarmin,
        googleFit: deviceGoogleFit,
        oura: deviceOura,
        polar: devicePolar,
        huawei: deviceHuawei
      }
    }

    return NextResponse.json(stats)

  } catch (error) {
    console.error('Error fetching user stats:', error)
    return NextResponse.json(
      { error: 'Failed to fetch user stats' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { extractAdminFromHeaders } from '@/lib/admin-auth'
import { sendVercelSpendAlertEmail } from '@/lib/admin-alerts'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

function resolveBaseUrl(): string {
  let base =
    process.env.PUBLIC_BASE_URL ||
    (process.env.VERCEL_URL ? `https://${process.env.VERCEL_URL}` : '') ||
    process.env.NEXT_PUBLIC_APP_URL ||
    ''
  base = (base || '').trim()
  if (base && !/^https?:\/\//i.test(base)) {
    base = `https://${base}`
  }
  return base.replace(/\/+$/, '')
}

export async function POST(request: NextRequest) {
  try {
    const authHeader = request.headers.get('authorization')
    const admin = extractAdminFromHeaders(authHeader)
    if (!admin) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const secret = (process.env.VERCEL_SPEND_WEBHOOK_SECRET || '').trim()
    if (!secret) {
      return NextResponse.json({ error: 'Webhook secret not configured' }, { status: 400 })
    }

    const payload = {
      test: true,
      source: 'admin-panel',
      sentAt: new Date().toISOString(),
    }

    const baseUrl = resolveBaseUrl()
    if (!baseUrl) {
      await sendVercelSpendAlertEmail({ payload })
      return NextResponse.json({
        ok: true,
        delivered: 'email',
        note: 'Base URL not configured; sent direct email instead.',
      })
    }

    const webhookUrl = `${baseUrl}/api/vercel/spend-webhook?secret=${encodeURIComponent(secret)}`
    const res = await fetch(webhookUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    })

    if (!res.ok) {
      const text = await res.text().catch(() => '')
      return NextResponse.json(
        { error: 'Webhook test failed', status: res.status, detail: text },
        { status: 500 }
      )
    }

    return NextResponse.json({ ok: true, delivered: 'webhook', url: webhookUrl })
  } catch (error) {
    console.error('[admin vercel-spend-test] error', error)
    return NextResponse.json({ error: 'Failed to send test webhook' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { extractAdminFromHeaders } from '@/lib/admin-auth'
import { prisma } from '@/lib/prisma'
import { computeCostCentsFromTokens, fetchOpenAIUsageTotals } from '@/lib/openai-billing'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const num = (value: any) => {
  const n = Number(value)
  return Number.isFinite(n) ? n : 0
}

const safeModel = (model?: string | null) => (model && model.trim()) || 'gpt-5.6-sol'

export async function GET(req: NextRequest) {
  try {
    const authHeader = req.headers.get('authorization')
    const admin = extractAdminFromHeaders(authHeader)
    if (!admin) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const url = new URL(req.url)
    const rangeRaw = url.searchParams.get('rangeDays')
    const preset = url.searchParams.get('preset') // today|7|30|mtd
    const userFilter = url.searchParams.get('user')

    let rangeDays = 30
    if (preset === 'today') rangeDays = 1
    else if (preset === '7') rangeDays = 7
    else if (preset === '30') rangeDays = 30
    else if (preset === 'mtd') rangeDays = 60 // mtd handled separately
    else if (rangeRaw) {
      const parsed = Number(rangeRaw)
      if (Number.isFinite(parsed) && parsed > 0) rangeDays = parsed
    }

    const now = new Date()
    const from = new Date(now.getTime() - rangeDays * 24 * 60 * 60 * 1000)
    const monthStart = new Date(now.getFullYear(), now.getMonth(), 1)
    const rangeStart = preset === 'mtd' ? monthStart : from
    const rangeStartStr = rangeStart.toISOString().slice(0, 10)
    const todayStr = now.toISOString().slice(0, 10)
    const monthStartStr = monthStart.toISOString().slice(0, 10)

    const where: any = {
      createdAt: { gte: rangeStart },
    }
    if (userFilter) {
      where.OR = [
        { userId: userFilter },
        { userLabel: { contains: userFilter, mode: 'insensitive' } },
      ]
    }
    // Avoid double-counting Food Analyzer usage:
    // `/api/analyze-food` logs a per-request `food:image-*` or `food:text-*` event AND an
    // aggregate `food:analysis` event with the same tokens, which inflates totals.
    // The per-request events are the canonical ones for usage reporting.
    where.NOT = [{ feature: 'food:analysis' }]

    const [
      rangeAggregates,
      monthAggregates,
      recent,
      featureGroups,
      featureModelGroups,
      userModelGroups,
      userFeatureGroups,
      trendModelRaw,
      billingRange,
      billingMtd,
    ] = await Promise.all([
      prisma.aIUsageEvent.aggregate({
        where,
        _count: { _all: true },
        _sum: { promptTokens: true, completionTokens: true, totalTokens: true },
      }),
      prisma.aIUsageEvent.aggregate({
        where: {
          ...(userFilter ? { OR: where.OR } : {}),
          createdAt: { gte: monthStart },
        },
        _sum: { promptTokens: true, completionTokens: true, totalTokens: true },
      }),
      prisma.aIUsageEvent.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        take: 100,
      }),
      prisma.aIUsageEvent.groupBy({
        by: ['feature'],
        where,
        _count: { _all: true },
        _sum: { promptTokens: true, completionTokens: true, totalTokens: true },
        _max: { imageWidth: true, imageHeight: true },
      }),
      prisma.aIUsageEvent.groupBy({
        by: ['feature', 'model'],
        where,
        _count: { _all: true },
        _sum: { promptTokens: true, completionTokens: true },
      }),
      prisma.aIUsageEvent.groupBy({
        by: ['userId', 'userLabel', 'model'],
        where,
        _count: { _all: true },
        _sum: { promptTokens: true, completionTokens: true },
      }),
      prisma.aIUsageEvent.groupBy({
        by: ['userId', 'userLabel', 'feature'],
        where,
        _count: { _all: true },
      }),
      prisma.$queryRawUnsafe<
        { day: string; model: string | null; prompttokens: number; completiontokens: number; calls: bigint }[]
      >(
        `SELECT TO_CHAR("createdAt"::date, 'YYYY-MM-DD') as day,
                COALESCE("model", 'unknown') as model,
                SUM("promptTokens") as prompttokens,
                SUM("completionTokens") as completiontokens,
                COUNT(*) as calls
         FROM "AIUsageEvent"
         WHERE "createdAt" >= $1${userFilter ? ' AND ("userId" = $2 OR "userLabel" ILIKE $3)' : ''}
         GROUP BY 1, 2
         ORDER BY 1, 2`,
        rangeStart,
        ...(userFilter ? [userFilter, `%${userFilter}%`] as any : []),
      ),
      fetchOpenAIUsageTotals({ startDate: rangeStartStr, endDate: todayStr }),
      fetchOpenAIUsageTotals({ startDate: monthStartStr, endDate: todayStr }),
    ])

    const featureSummary: Record<string, any> = {}
    featureGroups.forEach((fg) => {
      featureSummary[fg.feature] = {
        count: fg._count?._all || 0,
        costCents: 0,
        promptTokens: fg._sum?.promptTokens || 0,
        completionTokens: fg._sum?.completionTokens || 0,
        tokens: fg._sum?.totalTokens || 0,
        maxWidth: fg._max?.imageWidth || null,
        maxHeight: fg._max?.imageHeight || null,
        models: {},
        costSource: 'openai_ratecard',
      }
    })

    featureModelGroups.forEach((fm) => {
      const feature = fm.feature || 'unknown'
      const promptTokens = num(fm._sum?.promptTokens)
      const completionTokens = num(fm._sum?.completionTokens)
      const modelCost = computeCostCentsFromTokens(safeModel(fm.model), promptTokens, completionTokens)
      if (!featureSummary[feature]) {
        featureSummary[feature] = {
          count: num(fm._count?._all || 0),
          costCents: modelCost,
          promptTokens,
          completionTokens,
          tokens: promptTokens + completionTokens,
          models: {},
          maxWidth: null,
          maxHeight: null,
          costSource: 'openai_ratecard',
        }
      } else {
        featureSummary[feature].costCents += modelCost
      }
      featureSummary[feature].models[fm.model] = {
        count: num(fm._count?._all || 0),
        promptTokens,
        completionTokens,
        costCents: modelCost,
      }
    })

    Object.keys(featureSummary).forEach((key) => {
      const f = featureSummary[key]
      f.tokens = num(f.promptTokens) + num(f.completionTokens)
    })

    const userSummary: Record<string, any> = {}
    userModelGroups.forEach((um) => {
      const key = um.userId || um.userLabel || 'guest'
      const label = um.userLabel || um.userId || 'guest'
      if (!userSummary[key]) {
        userSummary[key] = {
          label,
          count: 0,
          costCents: 0,
          promptTokens: 0,
          completionTokens: 0,
          tokens: 0,
          features: {},
        }
      }
      const promptTokens = num(um._sum?.promptTokens)
      const completionTokens = num(um._sum?.completionTokens)
      const modelCost = computeCostCentsFromTokens(safeModel(um.model), promptTokens, completionTokens)
      userSummary[key].count += num(um._count?._all || 0)
      userSummary[key].promptTokens += promptTokens
      userSummary[key].completionTokens += completionTokens
      userSummary[key].tokens = userSummary[key].promptTokens + userSummary[key].completionTokens
      userSummary[key].costCents += modelCost
    })

    userFeatureGroups.forEach((uf) => {
      const key = uf.userId || uf.userLabel || 'guest'
      if (!userSummary[key]) {
        userSummary[key] = {
          label: uf.userLabel || uf.userId || 'guest',
          count: 0,
          costCents: 0,
          promptTokens: 0,
          completionTokens: 0,
          tokens: 0,
          features: {},
        }
      }
      userSummary[key].features = userSummary[key].features || {}
      userSummary[key].features[uf.feature] = (userSummary[key].features[uf.feature] || 0) + num(uf._count?._all || 0)
    })

    const trendByDay: Record<string, { costCents: number; calls: number }> = {}
    ;(trendModelRaw || []).forEach((row) => {
      const cost = computeCostCentsFromTokens(
        safeModel((row as any).model),
        num((row as any).prompttokens),
        num((row as any).completiontokens),
      )
      if (!trendByDay[row.day]) {
        trendByDay[row.day] = { costCents: 0, calls: 0 }
      }
      trendByDay[row.day].costCents += cost
      trendByDay[row.day].calls += Number(row.calls || 0)
    })

    const trend = Object.entries(trendByDay)
      .map(([day, val]) => ({
        day,
        costCents: val.costCents,
        calls: val.calls,
      }))
      .sort((a, b) => a.day.localeCompare(b.day))

    // Spike detection: compare latest day vs previous day
    let spikeAlert: any = null
    if (trend.length >= 2) {
      const last = trend[trend.length - 1]
      const prev = trend[trend.length - 2]
      if (prev.costCents > 0 && last.costCents > prev.costCents * 1.4) {
        spikeAlert = {
          todayCostCents: last.costCents,
          yesterdayCostCents: prev.costCents,
          increasePct: ((last.costCents - prev.costCents) / prev.costCents) * 100,
        }
      }
    }

    const recentMapped = recent.map((r) => {
      const costCents = computeCostCentsFromTokens(safeModel(r.model), num(r.promptTokens), num(r.completionTokens))
      return {
        ...r,
        costUsd: costCents / 100,
        tokens: Number(r.totalTokens || (Number(r.promptTokens || 0) + Number(r.completionTokens || 0))),
        timestampIso: r.createdAt.toISOString(),
        expensive: costCents > 1000, // > $10
      }
    })

    const costFromLogsCents = Object.values(featureSummary).reduce((acc, f: any) => acc + num(f.costCents), 0)

    const totals = {
      totalCalls: rangeAggregates._count?._all || 0,
      totalPromptTokens: rangeAggregates._sum?.promptTokens || 0,
      totalCompletionTokens: rangeAggregates._sum?.completionTokens || 0,
      totalTokens: rangeAggregates._sum?.totalTokens || 0,
      monthPromptTokens: monthAggregates._sum?.promptTokens || 0,
      monthCompletionTokens: monthAggregates._sum?.completionTokens || 0,
      monthTotalTokens: monthAggregates._sum?.totalTokens || 0,
      rangeCostCentsFromLogs: costFromLogsCents,
    }

    const tokenSource = billingRange.tokenTotals ? 'openai_usage' : 'app_logs'
    const altKeys = Object.keys(process.env || {}).filter(
      (key) => key !== 'OPENAI_API_KEY' && key.toUpperCase().includes('OPENAI_API_KEY') && process.env[key],
    )

    return NextResponse.json({
      success: true,
      rangeDays,
      rangeStart: rangeStartStr,
      rangeEnd: todayStr,
      totalCalls: totals.totalCalls,
      totalCostCents: billingRange.totalUsageCents ?? costFromLogsCents,
      features: Object.keys(featureSummary).length,
      featureSummary,
      userSummary,
      trend,
      recent: recentMapped,
      totals,
      spikeAlert,
      billing: {
        range: billingRange,
        monthToDate: billingMtd,
      },
      sources: {
        billing: billingRange.source,
        billingFallback: billingRange.usingFallback || billingMtd.usingFallback,
        tokens: tokenSource,
        logsCostCents: costFromLogsCents,
      },
      keyStatus: {
        hasKey: !!process.env.OPENAI_API_KEY,
        altKeys,
        baseUrl: process.env.OPENAI_BASE_URL || 'https://api.openai.com',
      },
    })
  } catch (err) {
    console.error('[admin vision-usage] error', err)
    return NextResponse.json({ error: 'Failed to load vision usage' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { getAffiliateUser } from '@/lib/affiliate-auth'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function GET(request: NextRequest) {
