      riskLevel: true,
      recommendation: true,
      primaryChannel: true,
      primaryChannelOther: true,
      audienceSize: true,
      termsVersion: true,
      termsAcceptedAt: true,
      createdAt: true,
      reviewedAt: true,
      aiReasoning: true,
    },
  })

  return NextResponse.json({ ok: true, affiliate, application })
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { screenAffiliateApplication } from '@/lib/affiliate-screening'
import { notifyAdminAffiliateManualReview } from '@/lib/affiliate-admin-email'
import { createUniqueAffiliateCode } from '@/lib/affiliate-code'
import { getAffiliateUser } from '@/lib/affiliate-auth'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const AFFILIATE_TERMS_VERSION = '2025-12-22'

function getClientIp(request: NextRequest): string | null {
  const header = request.headers.get('x-forwarded-for')
  if (!header) return null
  const first = header.split(',')[0]?.trim()
  return first || null
}

export async function POST(request: NextRequest) {
  const user = await getAffiliateUser(request)
  const email = user?.email?.toLowerCase()
  if (!email || !user?.id) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const body = await request.json().catch(() => ({}))
  const name = String(body?.name || '').trim()
  const website = body?.website ? String(body.website).trim() : null
  const primaryChannel = String(body?.primaryChannel || '').trim()
  const primaryChannelOther = body?.primaryChannelOther ? String(body.primaryChannelOther).trim() : null
  const audienceSize = body?.audienceSize ? String(body.audienceSize).trim() : null
  const termsAccepted = Boolean(body?.termsAccepted)
  const termsVersion = String(body?.termsVersion || '').trim()
  const promotionMethod = String(body?.promotionMethod || '').trim()
  const notes = body?.notes ? String(body.notes).trim() : null

  if (!name || name.length < 2) return NextResponse.json({ error: 'Name is required' }, { status: 400 })
  if (!termsAccepted || termsVersion !== AFFILIATE_TERMS_VERSION) {
    return NextResponse.json({ error: 'You must accept the affiliate terms to apply' }, { status: 400 })
  }
  if (!primaryChannel) {
    return NextResponse.json({ error: 'Primary promotion channel is required' }, { status: 400 })
  }
  const allowedChannels = new Set([
    'WEBSITE',
    'YOUTUBE',
    'SOCIAL',
    'NEWSLETTER',
    'PODCAST',
    'COMMUNITY',
    'PAID_ADS',
    'OTHER',
  ])
  if (!allowedChannels.has(primaryChannel)) {
    return NextResponse.json({ error: 'Invalid promotion channel' }, { status: 400 })
  }
  if (primaryChannel === 'OTHER') {
    if (!primaryChannelOther || primaryChannelOther.length < 2) {
      return NextResponse.json({ error: 'Please specify the other channel' }, { status: 400 })
    }
  }
  const allowedAudienceSizes = new Set([
    'UNDER_1K',
    '1K_10K',
    '10K_50K',
    '50K_250K',
    '250K_PLUS',
    'UNKNOWN',
  ])
  if (audienceSize && !allowedAudienceSizes.has(audienceSize)) {
    return NextResponse.json({ error: 'Invalid audience size' }, { status: 400 })
  }
  if (!promotionMethod || promotionMethod.length < 10) {
    return NextResponse.json({ error: 'Promotion method must be at least 10 characters' }, { status: 400 })
  }

  const existingAffiliate = await prisma.affiliate.findFirst({
    where: { user: { email } },
    select: { id: true, code: true, status: true },
  })
  if (existingAffiliate) {
    return NextResponse.json({ ok: true, alreadyAffiliate: true, affiliate: existingAffiliate })
  }

  const existingApplication = await prisma.affiliateApplication.findFirst({
    where: {
      userId: user.id,
      status: { in: ['PENDING_REVIEW', 'APPROVED'] as any },
    },
    orderBy: { createdAt: 'desc' },
    select: { id: true, status: true },
  })
  if (existingApplication) {
    return NextResponse.json({
      ok: true,
      status: existingApplication.status,
      applicationId: existingApplication.id,
    })
  }

  const ip = getClientIp(request)
  const userAgent = request.headers.get('user-agent')
  const country = request.headers.get('cf-ipcountry') || null
  const region = request.headers.get('x-vercel-ip-country-region') || null
  const city = request.headers.get('x-vercel-ip-city') || null

  const application = await prisma.affiliateApplication.create({
    data: {
      userId: user.id,
      email,
      name,
      website,
      primaryChannel,
      primaryChannelOther,
      audienceSize,
      termsVersion,
      termsAcceptedAt: new Date(),
      promotionMethod,
      notes,
      ip,
      userAgent,
      country,
      region,
      city,
    },
    select: { id: true },
  })

  const screening = await screenAffiliateApplication({
    email,
    name,
    website,
    primaryChannel,
    primaryChannelOther,
    audienceSize,
    promotionMethod,
    notes,
    ip,
    userAgent,
    country,
    region,
    city,
  })

  const isLowAutoApprove = screening.riskLevel === 'LOW' && screening.recommendedAction === 'AUTO_APPROVE'

  await prisma.affiliateApplication.update({
    where: { id: application.id },
    data: {
      riskLevel: screening.riskLevel,
      recommendation: screening.recommendedAction,
      aiReasoning: screening.reasoning,
      aiRawJson: screening.raw ?? null,
      status: isLowAutoApprove ? 'APPROVED' : 'PENDING_REVIEW',
      autoApproved: isLowAutoApprove,
      reviewedAt: isLowAutoApprove ? new Date() : null,
    },
  })

  if (!isLowAutoApprove && (screening.riskLevel === 'MEDIUM' || screening.riskLevel === 'HIGH')) {
    const ownerEmail = process.env.OWNER_EMAIL
    if (ownerEmail) {
      notifyAdminAffiliateManualReview({
        toEmail: ownerEmail,
        applicationId: application.id,
        applicantEmail: email,
        applicantName: name,
        riskLevel: screening.riskLevel,
        reasoning: screening.reasoning,
      }).catch(() => {})
    }
  }

  if (!isLowAutoApprove) {
    return NextResponse.json({
      ok: true,
      status: 'PENDING_REVIEW',
      applicationId: application.id,
      screening: {
        riskLevel: screening.riskLevel,
        recommendedAction: screening.recommendedAction,
      },
    })
  }

  const code = await createUniqueAffiliateCode()
  const affiliate = await prisma.affiliate.create({
    data: {
      userId: user.id,
      applicationId: application.id,
      code,
      status: 'ACTIVE',
    },
    select: { id: true, code: true, status: true },
  })

  return NextResponse.json({
    ok: true,
    status: 'APPROVED',
    affiliate,
  })
}

import { NextRequest, NextResponse } from 'next/server'
import Stripe from 'stripe'
import { prisma } from '@/lib/prisma'
import { getAffiliateUser } from '@/lib/affiliate-auth'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function POST(request: NextRequest) {
  const user = await getAffiliateUser(request)
  if (!user?.email) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const secretKey = process.env.STRIPE_SECRET_KEY
  if (!secretKey) return NextResponse.json({ error: 'Stripe not configured' }, { status: 500 })
  const stripe = new Stripe(secretKey, { apiVersion: '2024-06-20' })

  const affiliate = await prisma.affiliate.findUnique({
    where: { userId: user.id },
    select: { id: true, status: true, stripeConnectAccountId: true },
  })
  if (!affiliate || affiliate.status !== 'ACTIVE') {
    return NextResponse.json({ error: 'Not an active affiliate' }, { status: 403 })
  }

  const origin = new URL(request.url).origin
  const returnUrl = `${origin}/affiliate`

  let accountId = affiliate.stripeConnectAccountId
  if (!accountId) {
    const account = await stripe.accounts.create({
      type: 'express',
      country: 'AU',
      email: user.email,
      capabilities: { transfers: { requested: true } },
      metadata: { helfi_affiliate_id: affiliate.id },
    })
    accountId = account.id
    await prisma.affiliate.update({
      where: { id: affiliate.id },
      data: { stripeConnectAccountId: accountId },
    })
  }

  const accountLink = await stripe.accountLinks.create({
    account: accountId,
    refresh_url: `${returnUrl}?connect=refresh`,
    return_url: `${returnUrl}?connect=return`,
    type: 'account_onboarding',
  })

  return NextResponse.json({ url: accountLink.url })
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { getAffiliateUser } from '@/lib/affiliate-auth'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function GET(request: NextRequest) {
  const user = await getAffiliateUser(request)
  if (!user?.email) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const affiliate = await prisma.affiliate.findUnique({
    where: { userId: user.id },
    select: {
      id: true,
      code: true,
      status: true,
      stripeConnectAccountId: true,
      stripeConnectDetailsSubmitted: true,
      stripeConnectChargesEnabled: true,
      stripeConnectPayoutsEnabled: true,
      stripeConnectOnboardedAt: true,
      createdAt: true,
    },
  })
  if (!affiliate) return NextResponse.json({ ok: true, affiliate: null })

  const [clickCount, uniqueVisitors, conversionCounts, sums] = await Promise.all([
    prisma.affiliateClick.count({ where: { affiliateId: affiliate.id } }),
    prisma.affiliateClick.findMany({
      where: { affiliateId: affiliate.id },
      distinct: ['visitorId'],
      select: { visitorId: true },
    }),
    prisma.affiliateConversion.groupBy({
      by: ['type'],
      where: { affiliateId: affiliate.id },
      _count: { _all: true },
    }),
    prisma.affiliateCommission.groupBy({
      by: ['status'],
      where: { affiliateId: affiliate.id },
      _sum: { commissionCents: true },
    }),
  ])

  const now = new Date()
  const payableByCurrencyRows = await prisma.affiliateCommission.groupBy({
    by: ['currency'],
    where: { affiliateId: affiliate.id, status: 'PENDING', payableAt: { lte: now } },
    _sum: { commissionCents: true },
  })
  const payableNowByCurrency = payableByCurrencyRows.reduce(
    (acc: Record<string, number>, row: any) => {
      acc[String(row.currency || 'usd').toLowerCase()] = Number(row._sum.commissionCents || 0)
      return acc
    },
    {} as Record<string, number>
  )

  const conversions = await prisma.affiliateConversion.findMany({
    where: { affiliateId: affiliate.id },
    orderBy: { occurredAt: 'desc' },
    take: 50,
    select: {
      occurredAt: true,
      type: true,
      currency: true,
      amountGrossCents: true,
      stripeFeeCents: true,
      amountNetCents: true,
      commission: { select: { status: true, commissionCents: true, payableAt: true, paidAt: true } },
    },
  })

  const stats = {
    clicks: clickCount,
    uniqueVisitors: uniqueVisitors.length,
    conversionsByType: conversionCounts.reduce(
      (acc: Record<string, number>, row: any) => {
        acc[row.type] = row._count._all
        return acc
      },
      {} as Record<string, number>
    ),
    commissionTotalsByStatus: sums.reduce(
      (acc: Record<string, number>, row: any) => {
        acc[row.status] = Number(row._sum.commissionCents || 0)
        return acc
      },
      {} as Record<string, number>
    ),
    payableNowCents: Object.values(payableNowByCurrency).reduce((sum, value) => sum + Number(value || 0), 0),
    payableNowByCurrency,
  }

  return NextResponse.json({
    ok: true,
    affiliate,
    referralLink: `/r/${affiliate.code}`,
    stats,
    events: conversions.map(c => ({
      occurredAt: c.occurredAt,
      type: c.type,
      currency: c.currency,
      amountGrossCents: c.amountGrossCents,
      stripeFeeCents: c.stripeFeeCents,
      amountNetCents: c.amountNetCents,
      commission: c.commission,
    })),
  })
}

import { NextRequest, NextResponse } from 'next/server'
import crypto from 'crypto'
import { prisma } from '@/lib/prisma'
import { normalizeAffiliateCode } from '@/lib/affiliate-cookies'
import { consumeRateLimit } from '@/lib/rate-limit'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const RATE_LIMIT_WINDOW_MS = 5 * 60 * 1000
const RATE_LIMIT_MAX_REQUESTS = 20

function getClientIp(request: NextRequest): string | null {
  const header = request.headers.get('x-forwarded-for')
  if (!header) return null
  const first = header.split(',')[0]?.trim()
  return first || null
}

export async function POST(request: NextRequest) {
  const body = await request.json().catch(() => ({}))
  const code = normalizeAffiliateCode(String(body?.code || ''))
  const visitorId = String(body?.visitorId || '').trim() || crypto.randomUUID()
  if (!code) return NextResponse.json({ error: 'Affiliate code is required' }, { status: 400 })

  const affiliate = await prisma.affiliate.findUnique({
    where: { code },
    select: { id: true, status: true },
  })
  if (!affiliate || affiliate.status !== 'ACTIVE') {
    return NextResponse.json({ error: 'Affiliate link is not active' }, { status: 404 })
  }

  const ip = getClientIp(request)
  const limiterKey = ip || visitorId
  const rateLimit = await consumeRateLimit('affiliate_native_click', limiterKey, RATE_LIMIT_MAX_REQUESTS, RATE_LIMIT_WINDOW_MS)
  if (!rateLimit.allowed) {
    return NextResponse.json({ error: 'Too many referral attempts' }, { status: 429 })
  }

  const click = await prisma.affiliateClick.create({
    data: {
      affiliateId: affiliate.id,
      visitorId,
      ip,
      userAgent: request.headers.get('user-agent'),
      referer: request.headers.get('referer'),
      landingPath: `/r/${code}`,
      destinationPath: 'native-app',
    },
    select: { id: true, createdAt: true },
  })

  return NextResponse.json({
    ok: true,
    attribution: {
      code,
      clickId: click.id,
      visitorId,
      clickedAtMs: click.createdAt.getTime(),
    },
  })
}

