    }

    // Find user and check credit quota
    const user = await prisma.user.findUnique({
      where: { email: session.user.email },
      include: { subscription: true, creditTopUps: true }
    });

    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 });
    }

    logServerCall({
      feature: 'interactionAnalysis',
      endpoint: '/api/analyze-interactions',
      kind: 'analysis',
    }).catch((error) => {
      console.error('❌ Failed to log interaction analysis call:', error);
    });

    // PREMIUM/CREDITS/FREE USE GATING
    const isPremium = isSubscriptionActive(user.subscription);

    // Check if user has purchased credits (non-expired)
    const now = new Date();
    const hasPurchasedCredits = user.creditTopUps.some(
      (topUp: any) => topUp.expiresAt > now && (topUp.amountCents - topUp.usedCents) > 0
    );

    const hasFreeInteractionCredits = await hasFreeCredits(user.id, 'INTERACTION_ANALYSIS');
    const hasFreeInteractionReanalysis = await hasFreeCredits(user.id, 'INTERACTION_REANALYSIS');

    // Allow if: Premium subscription OR has purchased credits OR has free credits
    let allowViaFreeUse = false;
    if (!isPremium && !hasPurchasedCredits) {
      if (reanalysis) {
        if (hasFreeInteractionReanalysis) {
          allowViaFreeUse = true;
        } else {
          return NextResponse.json(
            {
              error: 'Payment required',
              message: 'You\'ve used all your free interaction re-analyses. Subscribe to a monthly plan or purchase credits to continue.',
              requiresPayment: true,
              exhaustedFreeCredits: true,
            },
            { status: 402 }
          );
        }
      } else if (hasFreeInteractionCredits) {
        allowViaFreeUse = true;
      } else {
        return NextResponse.json(
          { 
            error: 'Payment required',
            message: 'You\'ve used all your free interaction analyses. Subscribe to a monthly plan or purchase credits to continue.',
            requiresPayment: true,
            exhaustedFreeCredits: true,
          },
          { status: 402 }
        );
      }
    }
    // Use optional chaining to avoid type errors if field not present in client types
    const lastMonthlyReset = (user as any).lastMonthlyResetDate as Date | null;
    const monthChanged = !lastMonthlyReset || lastMonthlyReset.getUTCFullYear() !== now.getUTCFullYear() || lastMonthlyReset.getUTCMonth() !== now.getUTCMonth();
    if (monthChanged) {
      await prisma.user.update({
        where: { id: user.id },
        data: { 
          // Cast to any to support add-only schema push in staging
          ...( { monthlyInteractionAnalysisUsed: 0, lastMonthlyResetDate: now } as any )
        }
      });
      (user as any).monthlyInteractionAnalysisUsed = 0 as any;
    }

    // Plan/trial gating removed – wallet pre-check governs access (trial counters still updated later)

    // Prepare the data for AI analysis
    const supplementList = (supplementsList as any[]).map((s: any) => ({
      name: s.name,
      dosage: s.dosage,
      timing: Array.isArray(s.timing) ? s.timing.join(', ') : s.timing,
      schedule: s.scheduleInfo
    }));

    const medicationList = (medicationsList as any[]).map((m: any) => ({
      name: m.name,
      dosage: m.dosage,
      timing: Array.isArray(m.timing) ? m.timing.join(', ') : m.timing,
      schedule: m.scheduleInfo
    }));

    const prompt = `Review the following supplements and medications for possible interaction risks and discussion points:

SUPPLEMENTS:
${supplementList.map(s => `- ${s.name}: ${s.dosage}, taken ${s.timing}, schedule: ${s.schedule}`).join('\n')}

MEDICATIONS:
${medicationList.map(m => `- ${m.name}: ${m.dosage}, taken ${m.timing}, schedule: ${m.schedule}`).join('\n')}

CRITICAL REQUIREMENT: In your summary, you MUST list ALL supplements and medications by their actual names (e.g., "Analysis completed for Vitamin E, Magnesium, and Ibuprofen. Overall risk level: medium.") - do NOT use generic counts like "5 supplements and 2 medications".

Please provide a comprehensive interaction analysis in the following JSON format:
{
  "overallRisk": "low|medium|high",
  "interactions": [
    {
      "substance1": "name",
      "substance2": "name",
      "severity": "low|medium|high",
      "description": "detailed explanation of the interaction",
      "recommendation": "specific recommendation for the user",
      "timingAdjustment": "suggested timing changes if needed"
    }
  ],
  "timingOptimization": {
    "morning": ["list of substances best taken in morning"],
    "afternoon": ["list of substances best taken in afternoon"],
    "evening": ["list of substances best taken in evening"],
    "beforeBed": ["list of substances best taken before bed"]
  },
  "generalRecommendations": [
    "general advice for this combination"
  ],
  "disclaimer": "Important medical disclaimer text"
}

CRITICAL INSTRUCTIONS:
1. ONLY include interactions that are MEDIUM or HIGH severity - do not include low/safe interactions
2. For timing optimization, DO NOT include substances that have HIGH severity interactions with each other
3. For MEDIUM severity interactions, include timing recommendations but note spacing requirements
4. Focus on actionable, significant interactions only

Focus on:
1. Drug-supplement interactions
2. Supplement-supplement interactions
3. Timing conflicts that could reduce effectiveness
4. Absorption interference
5. Dosage concerns
6. Any contraindications

Be thorough but not alarmist. Provide actionable recommendations.`;

    const openai = getOpenAIClient();
    if (!openai) {
      return NextResponse.json({ error: 'AI service not configured' }, { status: 500 });
    }

    const model = "gpt-5.6-sol";

    let maxTokens = 2000;
    // Wallet pre-check (skip if allowed via free use)
    if (!allowViaFreeUse) {
      const cm = new CreditManager(user.id);
      const wallet = await cm.getWalletStatus();
      const cappedMaxTokens = capMaxTokensToBudget(model, prompt, maxTokens, wallet.totalAvailableCents);
      if (cappedMaxTokens <= 0) {
        return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 });
      }
      maxTokens = cappedMaxTokens;
    }

    // Immediate pre-charge (interaction analysis typical cost = CREDIT_COSTS.INTERACTION_ANALYSIS)
    let prechargedCents = 0;
    if (!allowViaFreeUse) {
      try {
        const cm = new CreditManager(user.id);
        const immediate = CREDIT_COSTS.INTERACTION_ANALYSIS;
        const okPre = await cm.chargeCents(immediate);
        if (!okPre) {
          return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 });
        }
        prechargedCents = immediate;
      } catch {
        return NextResponse.json({ error: 'Billing error' }, { status: 402 });
      }
    }

    const wrapped = await chatCompletionWithCost(openai, {
      model,
      messages: [
        {
          role: "system",
          content:
            "You are a cautious medication and supplement interaction reviewer. Provide evidence-aligned tracking notes and discussion points while avoiding medical advice, diagnosis, or treatment instructions. Return ONLY valid JSON.",
        },
        {
          role: "user",
          content: prompt,
        },
      ],
      temperature: 0.3,
      max_tokens: maxTokens,
      response_format: { type: "json_object" },
    } as any);

    const rawContent = wrapped.completion.choices[0].message.content as any;
    const analysisText =
      typeof rawContent === 'string'
        ? rawContent
        : Array.isArray(rawContent)
          ? rawContent
              .map((part: any) => {
                if (typeof part?.text === 'string') return part.text;
                if (typeof part?.output_text === 'string') return part.output_text;
                if (part?.output_json) return JSON.stringify(part.output_json);
                if (part?.json) return JSON.stringify(part.json);
                if (part?.content && typeof part.content === 'string') return part.content;
                if (part?.content && typeof part.content === 'object') return JSON.stringify(part.content);
                return '';
              })
              .join('')
          : rawContent
            ? JSON.stringify(rawContent)
            : '';
    console.log('AI Response:', analysisText);

    // Parse the JSON response with improved resilience.
    const buildFallbackSummary = () => {
      const supplementNames = (supplementsList as any[])
        .map((s: any) => String(s?.name || '').trim())
        .filter(Boolean)
        .join(', ');
      const medicationNames = (medicationsList as any[])
        .map((m: any) => String(m?.name || '').trim())
        .filter(Boolean)
        .join(', ');

      let summaryText = 'Analysis completed for ';
      if (supplementNames && medicationNames) {
        summaryText += `${supplementNames} and ${medicationNames}`;
      } else if (supplementNames) {
        summaryText += supplementNames;
      } else if (medicationNames) {
        summaryText += medicationNames;
      } else {
        summaryText += 'no supplements or medications';
      }
      summaryText += '.';
      return summaryText;
    };

    const fallbackAnalysis = {
      overallRisk: 'low',
      summary: buildFallbackSummary(),
      interactions: [],
      timingOptimization: {
        morning: [],
        afternoon: [],
        evening: [],
        beforeBed: [],
      },
      generalRecommendations: [],
      disclaimer:
        'This analysis is for informational purposes only and should not replace professional medical advice.',
    };

    const normalizeAnalysis = (raw: any) => {
      const base = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
      const normalized: any = { ...fallbackAnalysis, ...base };
      if (!normalized.overallRisk) normalized.overallRisk = fallbackAnalysis.overallRisk;
      if (typeof normalized.summary !== 'string' || !normalized.summary.trim()) {
        normalized.summary = fallbackAnalysis.summary;
      } else {
        normalized.summary = normalized.summary.trim();
      }
      if (!Array.isArray(normalized.interactions)) normalized.interactions = [];
      if (!normalized.timingOptimization || typeof normalized.timingOptimization !== 'object') {
        normalized.timingOptimization = { ...fallbackAnalysis.timingOptimization };
      } else {
        normalized.timingOptimization = {
          morning: Array.isArray(normalized.timingOptimization.morning)
            ? normalized.timingOptimization.morning
            : [],
          afternoon: Array.isArray(normalized.timingOptimization.afternoon)
            ? normalized.timingOptimization.afternoon
            : [],
          evening: Array.isArray(normalized.timingOptimization.evening)
            ? normalized.timingOptimization.evening
            : [],
          beforeBed: Array.isArray(normalized.timingOptimization.beforeBed)
            ? normalized.timingOptimization.beforeBed
            : [],
        };
      }
      if (!Array.isArray(normalized.generalRecommendations)) {
        normalized.generalRecommendations = [];
      }
      if (!normalized.disclaimer) normalized.disclaimer = fallbackAnalysis.disclaimer;
      return normalized;
    };

    let analysis: any = fallbackAnalysis;
    try {
      if (analysisText) {
        // Try to extract JSON from the response if it's wrapped in markdown
        let jsonText = analysisText.trim();

        // Handle different markdown formats
        if (jsonText.includes('```json')) {
          const jsonMatch = jsonText.match(/```json\s*\n([\s\S]*?)\n```/);
          if (jsonMatch) {
            jsonText = jsonMatch[1].trim();
          }
        } else if (jsonText.includes('```')) {
          const jsonMatch = jsonText.match(/```\s*\n([\s\S]*?)\n```/);
          if (jsonMatch) {
            jsonText = jsonMatch[1].trim();
          }
        }

        // Clean up common JSON formatting issues
        jsonText = jsonText.replace(/^[^{]*({[\s\S]*})[^}]*$/, '$1');
        jsonText = jsonText.replace(/,\s*([}\]])/g, '$1');

        const parsed = JSON.parse(jsonText);
        analysis = normalizeAnalysis(parsed);
      } else {
        analysis = normalizeAnalysis(fallbackAnalysis);
      }
    } catch (parseError) {
      console.error('Failed to parse AI response:', parseError);
      console.error('Raw response:', analysisText);
      const trimmed = analysisText?.trim() || '';
      if (trimmed && !trimmed.startsWith('{')) {
        analysis = normalizeAnalysis({ summary: trimmed.slice(0, 800) });
      } else {
        analysis = normalizeAnalysis(fallbackAnalysis);
      }
    }

    // Add metadata
    analysis.analysisDate = new Date().toISOString();
    analysis.supplementCount = supplementsList.length;
    analysis.medicationCount = medicationsList.length;

    // Generate analysis name if not provided
    const defaultAnalysisName = analysisName || 
      `Analysis ${new Date().toLocaleDateString()} - ${supplementsList.length} supplements, ${medicationsList.length} medications`;

    const cleanedSupplements = stripImageFields(supplementsList);
    const cleanedMedications = stripImageFields(medicationsList);

    // Save analysis to database
    const savedAnalysis = await prisma.interactionAnalysis.create({
      data: {
        userId: user.id,
        analysisName: defaultAnalysisName,
        overallRisk: analysis.overallRisk,
        supplementCount: supplementsList.length,
        medicationCount: medicationsList.length,
        analysisData: analysis,
        supplementsAnalyzed: cleanedSupplements,
        medicationsAnalyzed: cleanedMedications,
      }
    });

    try {
      await cleanupInteractionImages({
        userId: user.id,
        supplements: supplementsList,
        medications: medicationsList,
      });
    } catch (cleanupError) {
      console.warn('⚠️ Failed to clean up interaction photos:', cleanupError);
    }

    // Charge wallet and update counters (skip if allowed via free use)
    if (!allowViaFreeUse) {
      const cm = new CreditManager(user.id);
      const remainder = Math.max(0, wrapped.costCents - prechargedCents);
      const ok = await cm.chargeCents(remainder);
      if (!ok) {
        return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 });
      }
    }

    // Update counters and consume free credits
    if (allowViaFreeUse) {
      await consumeFreeCredit(user.id, reanalysis ? 'INTERACTION_REANALYSIS' : 'INTERACTION_ANALYSIS');
    }
    // Update counters (for all users, not just premium)
    await prisma.user.update({
      where: { id: user.id },
      data: ( {
        monthlyInteractionAnalysisUsed: { increment: 1 },
        totalInteractionAnalysisCount: { increment: 1 },
        totalAnalysisCount: { increment: 1 },
      } as any )
    });

    // Log AI usage for interaction analysis (fire-and-forget)
    try {
      await logAIUsage({
        context: { feature: 'interactions:analysis', userId: user.id },
        model,
        promptTokens: wrapped.promptTokens,
        completionTokens: wrapped.completionTokens,
        costCents: wrapped.costCents,
      });
    } catch {
      // Logging should never break the main flow
    }

    // Fire-and-forget: update insights preview based on new interaction results
    try { fetch('/api/insights/generate?preview=1', { method: 'POST' }).catch(()=>{}) } catch {}
    return NextResponse.json({ 
      success: true, 
      analysis,
      analysisId: savedAnalysis.id
    });

  } catch (error) {
    console.error('Error analyzing interactions:', error);
    return NextResponse.json({ 
      error: 'Failed to analyze interactions',
      details: error instanceof Error ? error.message : 'Unknown error'
    }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import OpenAI from 'openai'
import { runChatCompletionWithLogging } from '@/lib/ai-usage-logger'
import { logAiUsageEvent } from '@/lib/ai-usage-logger'
import { consumeRateLimit } from '@/lib/rate-limit'
import { getImageMetadata } from '@/lib/image-metadata'
import { prisma } from '@/lib/prisma'
import { CreditManager, CREDIT_COSTS } from '@/lib/credit-system'
import { consumeFreeCredit, hasFreeCredits } from '@/lib/free-credits'
import { isSubscriptionActive } from '@/lib/subscription-utils'
import { logServerCall } from '@/lib/server-call-tracker'

const RATE_LIMIT_WINDOW_MS = 60_000
const RATE_LIMIT_MAX = 3

const getOpenAIClient = () => {
  if (!process.env.OPENAI_API_KEY) return null
  return new OpenAI({ apiKey: process.env.OPENAI_API_KEY })
}

export async function POST(req: NextRequest) {
  const session = await getServerSession(authOptions)
  if (!session?.user?.email) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const contentType = req.headers.get('content-type') || ''
  const openai = getOpenAIClient()
  if (!openai) return NextResponse.json({ error: 'AI service not configured' }, { status: 500 })

  const clientIp = (req.headers.get('x-forwarded-for') || '').split(',')[0]?.trim() || 'unknown'
  const rateKey = (session.user as any)?.id ? `user:${(session.user as any)?.id}` : `ip:${clientIp}`
  const rateCheck = await consumeRateLimit('analyze-packaged', rateKey, RATE_LIMIT_MAX, RATE_LIMIT_WINDOW_MS)
  if (!rateCheck.allowed) {
    const retryAfter = Math.max(1, Math.ceil(rateCheck.retryAfterMs / 1000))
    return NextResponse.json(
      { error: 'Too many packaged label analyses. Please wait and try again.' },
      { status: 429, headers: { 'Retry-After': String(retryAfter) } }
    )
  }

  const user = await prisma.user.findUnique({
    where: { email: session.user.email },
    include: { subscription: true, creditTopUps: true },
  })
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  logServerCall({
    feature: 'packagedFoodLabel',
    endpoint: '/api/analyze-packaged',
    kind: 'analysis',
  }).catch((error) => {
    console.error('❌ Failed to log packaged label call:', error)
  })

  const isPremium = isSubscriptionActive(user.subscription)
  const now = new Date()
  const hasPurchasedCredits = user.creditTopUps.some(
    (topUp: any) => topUp.expiresAt > now && (topUp.amountCents - topUp.usedCents) > 0
  )
  const hasFreeFoodCredits = await hasFreeCredits(user.id, 'FOOD_ANALYSIS')

  let allowViaFreeUse = false
  if (!isPremium && !hasPurchasedCredits && hasFreeFoodCredits) {
    allowViaFreeUse = true
  } else if (!isPremium && !hasPurchasedCredits && !hasFreeFoodCredits) {
    return NextResponse.json(
      {
        error: 'Payment required',
        message: 'You\'ve used all your free food analyses. Subscribe to a monthly plan or purchase credits to continue.',
        requiresPayment: true,
        exhaustedFreeCredits: true,
      },
      { status: 402 }
    )
  }

  let promptText = ''
  let imageDataUrl: string | null = null
  let imageMeta: ReturnType<typeof getImageMetadata> | null = null
  let imageBytes: number | null = null
  let imageMime: string | null = null

  if (contentType.includes('application/json')) {
    const { text } = await req.json()
    if (!text) return NextResponse.json({ error: 'No label text provided' }, { status: 400 })
    promptText = text
  } else {
    // NextRequest.formData() returns a standard web FormData, but type
    // definitions can vary between runtimes and cause build-time TS errors.
    // Cast to `any` here to preserve runtime behavior without changing logic.
    const form: any = await req.formData()
    const image = form.get('image') as File | null
    if (!image) return NextResponse.json({ error: 'No image provided' }, { status: 400 })
    const buf = await image.arrayBuffer()
    const base64 = Buffer.from(buf).toString('base64')
    imageDataUrl = `data:${image.type};base64,${base64}`
    imageMeta = getImageMetadata(buf)
    imageBytes = buf.byteLength
    imageMime = image.type || null
  }

  if (!allowViaFreeUse) {
    const cm = new CreditManager(user.id)
    const wallet = await cm.getWalletStatus()
    if (wallet.totalAvailableCents < CREDIT_COSTS.FOOD_ANALYSIS) {
      return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
    }
    const ok = await cm.chargeCents(CREDIT_COSTS.FOOD_ANALYSIS)
    if (!ok) {
      return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
    }
  }

  // Ask the model to extract per-portion nutrition from either text or image
  const messages: any[] = [
    imageDataUrl
      ? {
          role: 'user',
          content: [
            {
              type: 'text',
              text:
                'Read this packaged food nutrition label. Return a JSON block between <NUTR_JSON> and </NUTR_JSON> only, with fields: {"serving_size":"string","per_serving":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"fiber_g":0,"sugar_g":0}}. Use numbers; if unknown, use null.'
            },
            { type: 'image_url', image_url: { url: imageDataUrl, detail: 'high' } }
          ]
        }
      : {
          role: 'user',
          content:
            'Read this packaged food nutrition label text. Return a JSON block between <NUTR_JSON> and </NUTR_JSON> only, with fields: {"serving_size":"string","per_serving":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"fiber_g":0,"sugar_g":0}}. Use numbers; if unknown, use null.\n\nLabel text:\n' +
            promptText,
        },
  ]

  const result: any = await runChatCompletionWithLogging(
    openai,
    {
      model: 'gpt-5.6-sol',
      messages,
      max_tokens: 400,
      temperature: 0,
    },
    { feature: 'food:analyze-packaged', userId: user.id },
    imageDataUrl
      ? {
          image: {
            width: imageMeta?.width ?? null,
            height: imageMeta?.height ?? null,
            bytes: imageBytes,
            mime: imageMime,
          },
        }
      : undefined
  )

  if (imageDataUrl) {
    logAiUsageEvent({
      feature: 'food:analyze-packaged',
      endpoint: '/api/analyze-packaged',
      userId: user.id,
      userLabel: user.email || null,
      scanId: `packaged-${Date.now()}`,
      model: 'gpt-5.6-sol',
      promptTokens: (result as any)?.promptTokens || 0,
      completionTokens: (result as any)?.completionTokens || 0,
      costCents: (result as any)?.costCents || 0,
      image: {
        width: imageMeta?.width ?? null,
        height: imageMeta?.height ?? null,
        bytes: imageBytes,
        mime: imageMime,
      },
      success: true,
    }).catch(() => {})
  } else {
    logAiUsageEvent({
      feature: 'food:analyze-packaged',
      endpoint: '/api/analyze-packaged',
      userId: user.id,
      userLabel: user.email || null,
      scanId: `packaged-${Date.now()}`,
      model: 'gpt-5.6-sol',
      promptTokens: (result as any)?.promptTokens || 0,
      completionTokens: (result as any)?.completionTokens || 0,
      costCents: (result as any)?.costCents || 0,
      success: true,
    }).catch(() => {})
  }
  const content = result.choices?.[0]?.message?.content || ''
  const m = content.match(/<NUTR_JSON>([\s\S]*?)<\/NUTR_JSON>/i)
  let parsed: any = null
  if (m && m[1]) {
    try {
      parsed = JSON.parse(m[1])
    } catch {}
  }

  if (allowViaFreeUse) {
    await consumeFreeCredit(user.id, 'FOOD_ANALYSIS')
  }

  return NextResponse.json({ success: true, raw: content.trim(), parsed })
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import OpenAI from 'openai';
import crypto from 'crypto';
import { logAiUsageEvent } from '@/lib/ai-usage-logger';
import { consumeRateLimit } from '@/lib/rate-limit';
import { getImageMetadata } from '@/lib/image-metadata';
import { prisma } from '@/lib/prisma';
import { CreditManager } from '@/lib/credit-system';
import { hasFreeCredits, consumeFreeCredit, ensureFreeCreditColumns, type FreeCreditType } from '@/lib/free-credits';
import { capMaxTokensToBudget } from '@/lib/cost-meter';
import { chatCompletionWithCost } from '@/lib/metered-openai';
import { getUserIdFromNativeAuth } from '@/lib/native-auth';
import { signNativeVoiceDraft } from '@/lib/native-voice-review-token';
import { findHealthIntakeReviewMatch } from '@/lib/health-intake-review-match';

const RATE_LIMIT_WINDOW_MS = 60_000;
const RATE_LIMIT_MAX = 3;
const VOICE_PAID_ACCESS_MESSAGE = 'Talk to Helfi needs an active subscription or purchased credits.';

function getOpenAIClient() {
  if (!process.env.OPENAI_API_KEY) {
    return null;
  }
  return new OpenAI({ apiKey: process.env.OPENAI_API_KEY });
}

function cleanText(value: unknown, max = 1000) {
  return String(value || '').replace(/\s+/g, ' ').trim().slice(0, max);
}

function isPlaceholderName(value: unknown) {
  const safe = cleanText(value, 120).toLowerCase();
  return new Set(['unknown', 'unknown supplement', 'unknown medication', 'analysis error', 'supplement label', 'medication label']).has(safe);
}

function hasPrivateLabelSignal(value: unknown, options: { allowSupplementBrandTerms?: boolean } = {}) {
  const text = cleanText(value, 240)
  const hasStrictPrivateSignal =
    /\b(patient|pharmacy|pharmacist|prescriber|prescribed by|doctor\s*(?:name|:)|rx\s*#?\s*\d|prescription|script|refill|npi|dob|date of birth|address|phone|tel|take as directed)\b/i.test(text)
  if (hasStrictPrivateSignal) return true
  if (options.allowSupplementBrandTerms) return false
  return /\bdr\.?\s+[a-z]+\s+[a-z]+\b/i.test(text)
}

function cleanLabelDosage(value: unknown) {
  const text = cleanText(value, 120)
  if (!text) return ''
  if (hasPrivateLabelSignal(text)) {
    return ''
  }

  const compact = text
    .replace(/\b(?:per|each)\s+(?:tablet|capsule|softgel|serving|dose)\b/gi, '')
    .replace(/\b(?:tablet|tablets|capsule|capsules|softgel|softgels)\b/gi, '')
    .replace(/\s+/g, ' ')
    .trim()

  const doseMatch = compact.match(/\b\d+(?:[.,]\d+)?\s*(?:(?:billion|million|bn|m)\s+)?(?:mg|mcg|µg|ug|g|iu|i\.u\.|ml|mL|l|mmol|mEq|units?|cfu|%)\b(?:\s*\/\s*\d+(?:[.,]\d+)?\s*(?:(?:billion|million|bn|m)\s+)?(?:mg|mcg|µg|ug|g|iu|i\.u\.|ml|mL|l|mmol|mEq|units?|cfu|%))?/i)
  if (!doseMatch) return ''

  return cleanText(doseMatch[0].replace(/\s+/g, ' '), 80)
}

function cleanLabelName(value: unknown, fallback: string) {
  const isSupplementFallback = fallback === 'Unknown Supplement'
  const text = cleanText(value, 180)
    .replace(/^[`"']+/, '')
    .replace(/[`"']+$/, '')
    .split('\n')[0]
    ?.trim() || fallback
  if (hasPrivateLabelSignal(text, { allowSupplementBrandTerms: isSupplementFallback })) {
    return fallback
  }
  const withoutDose = text
    .replace(/\b\d+(?:[.,]\d+)?\s*(?:tablet|tablets|capsule|capsules|softgel|softgels|serving|servings|count|ct)\b/gi, ' ')
    .replace(/\b\d+(?:[.,]\d+)?\s*(?:(?:billion|million|bn|m)\s+)?(?:mg|mcg|µg|ug|g|iu|i\.u\.|ml|mL|l|mmol|mEq|units?|cfu|%)\b(?:\s*\/\s*\d+(?:[.,]\d+)?\s*(?:(?:billion|million|bn|m)\s+)?(?:mg|mcg|µg|ug|g|iu|i\.u\.|ml|mL|l|mmol|mEq|units?|cfu|%))?/gi, ' ')
    .replace(/\b(?:per|each)\s+(?:tablet|capsule|softgel|serving|dose)\b/gi, ' ')
    .replace(/\b(?:tablet|tablets|capsule|capsules|softgel|softgels|serving|servings|count|ct)\b/gi, ' ')
    .replace(/\s*[-–—]\s*$/g, '')
    .replace(/\s+/g, ' ')
    .trim()
  return cleanText(withoutDose || text, 160) || fallback
}

function stripJsonFence(value: string) {
  return value
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

function hasAiConsentFlag(value: unknown) {
  const text = String(value ?? '').trim().toLowerCase();
  return text === 'true' || text === '1' || text === 'yes' || text === 'granted';
}

function hasPaidVoiceWalletAccess(wallet: any) {
  const topUpsAvailable = Array.isArray(wallet?.topUps)
    ? wallet.topUps.reduce((sum: number, item: any) => sum + Math.max(0, Number(item?.availableCents || 0)), 0)
    : 0;
  const additionalAvailable = Math.max(0, Number(wallet?.additionalCreditsCents || 0));
  return Boolean(wallet?.plan) || topUpsAvailable > 0 || additionalAvailable > 0;
}

function voicePaidAccessResponse() {
  return NextResponse.json(
    { error: VOICE_PAID_ACCESS_MESSAGE, code: 'voice_subscription_required', requiresSubscription: true },
    { status: 402 },
  );
}

function imageNameFeature(scanType: 'supplement' | 'medication') {
  return scanType === 'medication' ? 'medications:image-name' : 'supplements:image-name';
}

async function countPriorImageNameScans(userId: string, feature: string) {
  const [withScanId, withoutScanId] = await Promise.all([
    prisma.aIUsageEvent.findMany({
      where: { userId, feature, success: true, scanId: { not: null } },
      distinct: ['scanId'],
      select: { scanId: true },
    }),
    prisma.aIUsageEvent.count({
      where: { userId, feature, success: true, scanId: null },
    }),
  ]);
  return withScanId.length + withoutScanId;
}

async function resolveRequestUser(req: NextRequest) {
  const session = await getServerSession(authOptions).catch(() => null);
  const sessionUserId = typeof session?.user?.id === 'string' ? session.user.id : null;
  const sessionEmail = typeof session?.user?.email === 'string' ? session.user.email : null;
  const nativeUserId = sessionUserId || sessionEmail ? null : await getUserIdFromNativeAuth(req);
  if (sessionUserId || nativeUserId) {
    return prisma.user.findUnique({
      where: { id: sessionUserId || nativeUserId || '' },
      include: { subscription: true, creditTopUps: true },
    });
  }
  if (sessionEmail) {
    return prisma.user.findUnique({
      where: { email: sessionEmail },
      include: { subscription: true, creditTopUps: true },
    });
  }
  return null;
}

function parseVoiceReviewLabelResult(raw: unknown, scanType: 'supplement' | 'medication') {
  const fallback = scanType === 'medication' ? 'Unknown Medication' : 'Unknown Supplement';
  const text = cleanText(raw, 1000) || fallback;
  let name = text.split('\n')[0]?.trim() || fallback;
  let dosage = '';

  try {
    const parsed = JSON.parse(stripJsonFence(text));
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      const rawName =
        (parsed as any).name ||
        (parsed as any).productName ||
        (parsed as any).product ||
        (parsed as any).label ||
        fallback
      name = cleanLabelName(
        rawName,
        fallback,
      );
      dosage = cleanLabelDosage(
        (parsed as any).dosage ||
          (parsed as any).dose ||
          (parsed as any).strength ||
          '',
      ) || cleanLabelDosage(rawName);
    }
  } catch {
    name = cleanLabelName(text, fallback);
    dosage = cleanLabelDosage(text);
  }

  return { name, dosage };
}

function parseLegacyLabelName(raw: unknown, scanType: 'supplement' | 'medication') {
  const fallback = scanType === 'medication' ? 'Unknown Medication' : 'Unknown Supplement';
  return cleanText(raw, 1000)
    .replace(/^[`"']+/, '')
    .replace(/[`"']+$/, '')
    .split('\n')[0]
    ?.trim() || fallback;
}

async function buildVoiceReviewDraft(userId: string, itemType: 'supplement' | 'medication', name: string, localDate: string, dosage = '') {
  const label = itemType === 'medication' ? 'Medication' : 'Supplement';
  const catalogMatch = await findHealthIntakeReviewMatch(itemType, name);
  const dose = cleanLabelDosage(dosage);
  const baseDraft = {
    action: 'health_intake_items',
    transcript: `Bottle label scan: ${name}`,
    localDate,
    summary: `Health Intake: 1 ${itemType}`,
    confirmationMessage:
      `I found this label:\n${label}: ${name} (${dose || 'dose not specified'}; timing not specified)\n\n` +
      'Please review it before saving. I am only recording what you already take, not recommending that you start, stop, or change anything.',
    canConfirm: true,
    autoSave: false,
    healthIntake: {
      items: [
        {
          type: itemType,
          name,
          dosage: dose,
          timing: [],
          scheduleInfo: '',
          method: 'photo',
          imageUrl: null,
          source: 'label_scan',
          catalogMatch,
        },
      ],
    },
  };
  const reviewableDraft = {
    ...baseDraft,
    reviewNonce: crypto.randomUUID(),
    reviewIssuedAt: Date.now(),
  };
  return {
    ...reviewableDraft,
    reviewToken: signNativeVoiceDraft(userId, reviewableDraft),
  };
}

export async function POST(req: NextRequest) {
  try {
    const user = await resolveRequestUser(req);
    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // NextRequest.formData() returns a standard web FormData, but type
    // definitions can vary between runtimes and cause build-time TS errors.
    // Cast to `any` here to preserve runtime behavior without changing logic.
    const formData: any = await req.formData();
    const imageFile = formData.get('image') as File;
    const scanType = String(formData.get('scanType') || 'supplement').toLowerCase() === 'medication' ? 'medication' : 'supplement';
    const scanId = String(formData.get('scanId') || '').trim();
    const voiceReview = String(formData.get('voiceReview') || '').toLowerCase() === 'true';
    const aiConsentGranted = hasAiConsentFlag(formData.get('aiConsentGranted') || formData.get('aiConsent'));
    const localDate = /^\d{4}-\d{2}-\d{2}$/.test(String(formData.get('localDate') || '').trim())
      ? String(formData.get('localDate')).trim()
      : new Date().toISOString().slice(0, 10);

    if (voiceReview && !aiConsentGranted) {
      return NextResponse.json(
        { error: 'AI sharing consent is required before a bottle label can be reviewed by Talk to Helfi.' },
        { status: 403 }
      );
    }

    if (voiceReview) {
      const wallet = await new CreditManager(user.id).getWalletStatus();
      if (!hasPaidVoiceWalletAccess(wallet)) return voicePaidAccessResponse();
    }

    if (!imageFile) {
      return NextResponse.json({ error: 'No image provided' }, { status: 400 });
    }

    const clientIp = (req.headers.get('x-forwarded-for') || '').split(',')[0]?.trim() || 'unknown';
    const rateCheck = await consumeRateLimit('supplement-image', `ip:${clientIp}`, RATE_LIMIT_MAX, RATE_LIMIT_WINDOW_MS);
    if (!rateCheck.allowed) {
      const retryAfter = Math.max(1, Math.ceil(rateCheck.retryAfterMs / 1000));
      return NextResponse.json(
        { error: 'Too many supplement image analyses. Please wait and try again.' },
        { status: 429, headers: { 'Retry-After': String(retryAfter) } }
      );
    }

    // Convert image to base64
    const imageBuffer = await imageFile.arrayBuffer();
    const imageBase64 = Buffer.from(imageBuffer).toString('base64');
    const meta = getImageMetadata(imageBuffer);

    console.log('Analyzing supplement image:', {
      name: imageFile.name,
      type: imageFile.type,
      size: imageFile.size
    });

    await ensureFreeCreditColumns();
    // Analyze image to extract supplement name
    const openai = getOpenAIClient();
    if (!openai) {
      return NextResponse.json({ error: 'AI service not configured' }, { status: 500 });
    }
    const promptText = voiceReview
      ? `Analyze this supplement or medication bottle/package image and extract the BRAND + PRODUCT NAME and clearly visible dose/strength.

CRITICAL INSTRUCTIONS:
1. Return the brand AND the product name if both are clearly visible.
2. Format: "Brand - Product" (example: "Thorne - Magnesium Bisglycinate").
3. If brand is not visible, return only the product name.
4. Put clearly visible dose/strength in dosage only, for example "500 mg", "1000 IU", "50 mcg", or "1 mg/mL".
5. If it's a medication and both brand + generic are clearly visible, return "Brand (Generic)" or "Generic (Brand)".
6. Do NOT include package size, capsule/tablet count, marketing claims, pharmacy details, prescriber names, patient names, or prescription numbers.
7. If dose/strength is not clearly visible, use an empty dosage string.
8. If the label is not clear enough to identify the product name, use "${scanType === 'medication' ? 'Unknown Medication' : 'Unknown Supplement'}".

Return only JSON in this exact shape:
{"name":"Brand - Product","dosage":"clearly visible dose or empty string"}`
      : `Analyze this supplement or medication bottle/package image and extract the BRAND + PRODUCT NAME.

CRITICAL INSTRUCTIONS:
1. Return the brand AND the product name if both are visible.
2. Format: "Brand - Product" (example: "Thorne - Magnesium Bisglycinate").
3. If brand is not visible, return only the product name.
4. Do NOT include dosage, size, "capsules", "tablets", or marketing claims.
5. If it's a medication and both brand + generic are visible, return "Brand (Generic)" or "Generic (Brand)".
6. If you are not 100% sure, still return your BEST GUESS.
7. Only return "Unknown Supplement" if the label is unreadable.

Return only the final name string, no extra text.`;

    const model = "gpt-5.6-sol";
    const cm = new CreditManager(user.id);
    const freeType: FreeCreditType = scanType === 'medication' ? 'MEDICATION_IMAGE' : 'SUPPLEMENT_IMAGE';
    const feature = imageNameFeature(scanType);
    let maxTokens = voiceReview ? 80 : 50;

    // If this scanId was already charged once (front/back pair), skip charging again.
    let skipCharge = false;
    if (scanId) {
      const prior = await prisma.aIUsageEvent.findFirst({
        where: {
          scanId,
          feature,
        },
        select: { id: true },
      });
      if (prior) skipCharge = true;
    }

    let usedFree = false;
    if (!skipCharge) {
      // If user hasn't used photo scans yet, grant the initial free batch (10).
      const supplementField = (user as any).freeSupplementImageRemaining ?? 0;
      const medicationField = (user as any).freeMedicationImageRemaining ?? 0;
      if (scanType === 'supplement' && supplementField <= 0) {
        const [savedImageCount, usedScanCount] = await Promise.all([
          prisma.supplement.count({
            where: { userId: user.id, imageUrl: { not: null } },
          }),
          countPriorImageNameScans(user.id, feature),
        ]);
        const usedCount = Math.max(savedImageCount, usedScanCount);
        const remaining = Math.max(0, 10 - usedCount);
        if (remaining > 0) {
          await prisma.user.update({
            where: { id: user.id },
            data: { freeSupplementImageRemaining: remaining } as any,
          });
        }
      }
      if (scanType === 'medication' && medicationField <= 0) {
        const [savedImageCount, usedScanCount] = await Promise.all([
          prisma.medication.count({
            where: { userId: user.id, imageUrl: { not: null } },
          }),
          countPriorImageNameScans(user.id, feature),
        ]);
        const usedCount = Math.max(savedImageCount, usedScanCount);
        const remaining = Math.max(0, 10 - usedCount);
        if (remaining > 0) {
          await prisma.user.update({
            where: { id: user.id },
            data: { freeMedicationImageRemaining: remaining } as any,
          });
        }
      }

      const hasFree = await hasFreeCredits(user.id, freeType);
      if (hasFree) {
        const consumed = await consumeFreeCredit(user.id, freeType);
        usedFree = consumed;
      }
      if (!usedFree) {
        const wallet = await cm.getWalletStatus();
        maxTokens = capMaxTokensToBudget(model, promptText, maxTokens, wallet.totalAvailableCents);
        if (maxTokens <= 0) {
          return NextResponse.json(
            {
              error: 'Insufficient credits',
              message: 'Free photo scans used up. Please upgrade or buy credits in Billing to add more.',
            },
            { status: 402 }
          );
        }
      }
    }

    const wrapped = await chatCompletionWithCost(openai, {
      model,
      messages: [
        {
          role: "user",
          content: [
            { type: "text", text: promptText },
            {
              type: "image_url",
              image_url: {
                url: `data:${imageFile.type};base64,${imageBase64}`,
                detail: "high"
              }
            }
          ]
        }
      ],
      max_tokens: maxTokens,
      temperature: 0.1
    } as any);

    if (!usedFree && !skipCharge) {
      const ok = await cm.chargeCents(wrapped.costCents);
      if (!ok) {
        return NextResponse.json(
          {
            error: 'Insufficient credits',
            message: 'Free photo scans used up. Please upgrade or buy credits in Billing to add more.',
          },
          { status: 402 }
        );
      }
    }

    // Persist usage (vision)
    logAiUsageEvent({
      feature,
      endpoint: '/api/analyze-supplement-image',
      userId: user.id,
      userLabel: user.email || (clientIp ? `ip:${clientIp}` : null),
      scanId: scanId || `supplement-${Date.now()}`,
      model,
      promptTokens: wrapped.promptTokens,
      completionTokens: wrapped.completionTokens,
      costCents: usedFree || skipCharge ? 0 : wrapped.costCents,
      image: {
        width: meta.width,
        height: meta.height,
        bytes: imageBuffer.byteLength,
        mime: imageFile.type || null
      },
      success: true,
    }).catch(() => {});

    const rawName = wrapped.completion.choices?.[0]?.message?.content?.trim() || (scanType === 'medication' ? 'Unknown Medication' : 'Unknown Supplement');
    const labelResult = voiceReview
      ? parseVoiceReviewLabelResult(rawName, scanType)
      : { name: parseLegacyLabelName(rawName, scanType), dosage: '' };
    const cleanedName = labelResult.name;

    console.log('Extracted supplement name:', cleanedName);

    if (voiceReview && isPlaceholderName(cleanedName)) {
      return NextResponse.json(
        {
          error: 'I could not read the label clearly enough. Please try a clearer photo or type the name.',
          supplementName: cleanedName,
        },
        { status: 422 }
      );
    }

    return NextResponse.json({
      success: true,
      supplementName: cleanedName,
      ...(voiceReview ? { dosage: labelResult.dosage, draft: await buildVoiceReviewDraft(user.id, scanType, cleanedName, localDate, labelResult.dosage) } : {}),
    });

  } catch (error) {
    console.error('Error analyzing supplement image:', error);
    return NextResponse.json(
      { error: 'Failed to analyze supplement image', supplementName: 'Analysis Error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import OpenAI from 'openai'
import { prisma } from '@/lib/prisma'
import { CreditManager } from '@/lib/credit-system'
import { capMaxTokensToBudget } from '@/lib/cost-meter'
import { logAIUsage } from '@/lib/ai-usage-logger'
import { chatCompletionWithCost } from '@/lib/metered-openai'
import { consumeFreeCredit, hasFreeCredits } from '@/lib/free-credits'
import { isSubscriptionActive } from '@/lib/subscription-utils'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'
import {
  getThread,
  createThread,
  listMessages,
  appendMessage,
  updateThreadTitle,
  updateThreadContext,
  updateThreadCost,
} from '@/lib/symptom-chat-store'

const EMPTY_RESPONSE_FALLBACK =
  'I had a temporary issue answering that. Please try sending your question again.'

function getOpenAIClient(): OpenAI | null {
  if (!process.env.OPENAI_API_KEY) return null
  return new OpenAI({ apiKey: process.env.OPENAI_API_KEY })
}

function buildTitle(text: string): string {
  const trimmed = text.trim()
  if (!trimmed) return 'New chat'
  return trimmed.length > 50 ? `${trimmed.slice(0, 47)}...` : trimmed
}

export async function GET(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    const userId = session?.user?.id || (await getUserIdFromNativeAuth(req))
    if (!userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }
    const url = new URL(req.url)
    const threadId = url.searchParams.get('threadId')
    if (!threadId) {
      return NextResponse.json({ error: 'threadId required' }, { status: 400 })
    }
    const thread = await getThread(userId, threadId)
    if (!thread) {
      return NextResponse.json({ error: 'Thread not found' }, { status: 404 })
    }
    const messages = await listMessages(threadId, 60)
    return NextResponse.json({ threadId, messages }, { status: 200 })
  } catch (error) {
    console.error('[symptom-chat.GET] error', error)
    return NextResponse.json({ error: 'server_error' }, { status: 500 })
  }
}

export async function POST(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    const userId = session?.user?.id || (await getUserIdFromNativeAuth(req))
    if (!userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const contentType = req.headers.get('content-type') || ''
    let body: {
      message?: string
      threadId?: string
      symptoms?: string[]
      duration?: string
      notes?: string
      analysisResult?: any
    } = {}
    if (contentType.includes('application/json')) {
      try {
        body = await req.json()
      } catch {}
    }

    const question = String(body?.message || '').trim()
    if (!question) {
      return NextResponse.json({ error: 'Message required' }, { status: 400 })
    }

    const safeSymptoms = Array.isArray(body?.symptoms)
      ? body.symptoms.filter((item) => typeof item === 'string')
      : []
    const safeDuration = typeof body?.duration === 'string' ? body.duration : null
    const safeNotes = typeof body?.notes === 'string' ? body.notes : null
    const safeAnalysisResult =
      body?.analysisResult && typeof body.analysisResult === 'object' ? body.analysisResult : {}
    const contextPayload = {
      symptoms: safeSymptoms,
      duration: safeDuration,
      notes: safeNotes,
      analysisResult: safeAnalysisResult,
    }
    const hasContext =
      safeSymptoms.length > 0 ||
      Boolean(safeDuration) ||
      Boolean(safeNotes) ||
      Object.keys(safeAnalysisResult || {}).length > 0

    const requestedThreadId = typeof body?.threadId === 'string' ? body.threadId.trim() : ''
    let threadId = requestedThreadId
    let thread = threadId ? await getThread(userId, threadId) : null

    if (!thread) {
      const title = buildTitle(question)
      const created = await createThread(userId, hasContext ? contextPayload : undefined, title)
      threadId = created.id
      thread = { id: created.id, title, context: hasContext ? contextPayload : null }
    } else {
      if (hasContext) {
        await updateThreadContext(userId, threadId, contextPayload)
      }
      if (!thread.title) {
        await updateThreadTitle(userId, threadId, buildTitle(question))
      }
    }

    const threadContext = hasContext ? contextPayload : thread?.context || {}
    const symptoms = Array.isArray(threadContext?.symptoms)
      ? threadContext.symptoms.filter((item: unknown) => typeof item === 'string')
      : []
    const duration = typeof threadContext?.duration === 'string' ? threadContext.duration : null
    const notes = typeof threadContext?.notes === 'string' ? threadContext.notes : null
    const analysisResult =
      threadContext?.analysisResult && typeof threadContext.analysisResult === 'object'
        ? threadContext.analysisResult
        : {}

    const openai = getOpenAIClient()
    if (!openai) {
      return NextResponse.json({ error: 'AI service not configured' }, { status: 500 })
    }
    const user = await prisma.user.findUnique({ where: { id: userId }, include: { subscription: true, creditTopUps: true } })
    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    const isPremium = isSubscriptionActive(user.subscription)
    const now = new Date()
    const hasPurchasedCredits = user.creditTopUps?.some(
      (topUp: any) => topUp.expiresAt > now && (topUp.amountCents - topUp.usedCents) > 0
    )
    const hasFreeChatCredits = await hasFreeCredits(user.id, 'SYMPTOM_CHAT')
    const allowViaFreeUse = !isPremium && !hasPurchasedCredits && hasFreeChatCredits
    if (!isPremium && !hasPurchasedCredits && !hasFreeChatCredits) {
      return NextResponse.json(
        {
          error: 'Payment required',
          message: 'You\'ve used all your free symptom chat uses. Subscribe to a monthly plan or purchase credits to continue.',
          requiresPayment: true,
          exhaustedFreeCredits: true,
        },
        { status: 402 }
      )
    }

    // Build system prompt with symptom notes context.
    const systemPrompt = [
      'You are a careful, patient-friendly general health assistant helping users discuss their symptom notes.',
      'You are not a doctor and must not provide diagnosis, treatment advice, or certainty. Always include a reminder to consult qualified healthcare professionals.',
      '',
      `Original symptoms: ${symptoms.join(', ')}`,
      duration ? `Duration: ${duration}` : '',
      notes ? `User notes: ${notes}` : '',
      '',
      analysisResult.summary ? `Analysis summary: ${analysisResult.summary}` : '',
      analysisResult.possibleCauses?.length
        ? `Doctor discussion topics:\n${analysisResult.possibleCauses.map((c: any) => `- ${c.name}: ${c.whyLikely}`).join('\n')}`
        : '',
      analysisResult.redFlags?.length ? `Urgent-care warning signs:\n${analysisResult.redFlags.map((rf: string) => `- ${rf}`).join('\n')}` : '',
      analysisResult.nextSteps?.length ? `Tracking notes and doctor questions:\n${analysisResult.nextSteps.map((ns: string) => `- ${ns}`).join('\n')}` : '',
      '',
      'Rules:',
      '- Be concise and practical',
      '- Always remind users to consult healthcare professionals for concerning symptoms',
      '- Use clear, non-technical language',
      '- Reference specific parts of their notes when relevant',
      '- Avoid providing diagnoses, treatment plans, or supplement recommendations',
      '',
      'When users ask about supplements or dietary supplements:',
      '- Do not recommend supplements for symptoms.',
      '- Suggest discussing supplements with a qualified healthcare professional, especially if they use medications or have ongoing symptoms.',
      '- Consider multiple supplement categories: vitamins, minerals, herbal supplements, probiotics/prebiotics, enzymes, amino acids, etc.',
    ]
      .filter(Boolean)
      .join('\n')

    const accept = (req.headers.get('accept') || '').toLowerCase()
    const wantsStream = accept.includes('text/event-stream')

    const history = await listMessages(threadId, 30)
    const chatMessages = [
      { role: 'system' as const, content: systemPrompt },
      ...history.map((m) => ({ role: m.role, content: m.content })),
      { role: 'user' as const, content: question },
    ]

    await appendMessage(threadId, 'user', question)

    if (wantsStream) {
      const model = 'gpt-5.6-sol'
      const promptText = [systemPrompt, ...history.map((m) => m.content), question].join('\n')
      let maxTokens = 800
      if (!allowViaFreeUse) {
        const cm = new CreditManager(user.id)
        const wallet = await cm.getWalletStatus()
        const cappedMaxTokens = capMaxTokensToBudget(model, promptText, maxTokens, wallet.totalAvailableCents)
        if (cappedMaxTokens <= 0) {
          return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
        }
        maxTokens = cappedMaxTokens
      }

      const wrapped = await chatCompletionWithCost(openai, {
        model,
        temperature: 0.2,
        max_tokens: maxTokens,
        messages: chatMessages as any,
      } as any)

      if (!allowViaFreeUse) {
        const cm = new CreditManager(user.id)
        const ok = await cm.chargeCents(wrapped.costCents)
        if (!ok) {
          return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
        }
      } else {
        await consumeFreeCredit(user.id, 'SYMPTOM_CHAT')
      }

      try {
        await logAIUsage({
          context: { feature: 'symptoms:chat', userId: user.id },
          model,
          promptTokens: wrapped.promptTokens,
          completionTokens: wrapped.completionTokens,
          costCents: wrapped.costCents,
        })
      } catch {
        // Ignore logging failures
      }

      const textRaw = wrapped.completion.choices?.[0]?.message?.content || ''
      const text = textRaw.trim() ? textRaw : EMPTY_RESPONSE_FALLBACK
      await appendMessage(threadId, 'assistant', text)
      await updateThreadCost(userId, threadId, wrapped.costCents, allowViaFreeUse)
      const enc = new TextEncoder()
      const chunks = text.match(/[\s\S]{1,200}/g) || ['']
      const costPayload = JSON.stringify({ costCents: wrapped.costCents, covered: allowViaFreeUse })
      const stream = new ReadableStream({
        start(controller) {
          for (const chunk of chunks) {
            controller.enqueue(enc.encode(`data: ${chunk}\n\n`))
          }
          controller.enqueue(enc.encode(`data: __cost__${costPayload}\n\n`))
          controller.enqueue(enc.encode('event: end\n\n'))
          controller.close()
        },
      })
      return new Response(stream, { headers: { 'Content-Type': 'text/event-stream' } })
    }

    // Non-streaming fallback
    {
      const model = 'gpt-5.6-sol'
      let maxTokens = 800
      // Pre-check
      if (!allowViaFreeUse) {
        const cm = new CreditManager(user.id)
        const wallet = await cm.getWalletStatus()
        const cappedMaxTokens = capMaxTokensToBudget(
          model,
          [systemPrompt, ...history.map((m) => m.content), question].join('\n'),
          maxTokens,
          wallet.totalAvailableCents
        )
        if (cappedMaxTokens <= 0) {
          return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
        }
        maxTokens = cappedMaxTokens
      }
      const wrapped = await chatCompletionWithCost(openai, {
        model,
        temperature: 0.2,
        max_tokens: maxTokens,
        messages: chatMessages as any,
      } as any)
      if (!allowViaFreeUse) {
        const cm = new CreditManager(user.id)
        const ok = await cm.chargeCents(wrapped.costCents)
        if (!ok) {
          return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
        }
      } else {
        await consumeFreeCredit(user.id, 'SYMPTOM_CHAT')
      }

      // Log AI usage for non-streaming symptom chat
      try {
        await logAIUsage({
          context: { feature: 'symptoms:chat', userId: user.id },
          model,
          promptTokens: wrapped.promptTokens,
          completionTokens: wrapped.completionTokens,
          costCents: wrapped.costCents,
        })
      } catch {
        // Ignore logging failures
      }

      const textRaw = wrapped.completion.choices?.[0]?.message?.content || ''
      const text = textRaw.trim() ? textRaw : EMPTY_RESPONSE_FALLBACK
      await appendMessage(threadId, 'assistant', text)
      await updateThreadCost(userId, threadId, wrapped.costCents, allowViaFreeUse)
      return NextResponse.json({ assistant: text, costCents: wrapped.costCents, covered: allowViaFreeUse, threadId })
    }
  } catch (error) {
    console.error('[symptom-chat.POST] error', error)
    return NextResponse.json({ error: 'server_error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { getToken } from 'next-auth/jwt'
import { authOptions } from '@/lib/auth'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'
import { prisma } from '@/lib/prisma'
import { CreditManager, CREDIT_COSTS } from '@/lib/credit-system'
import { consumeFreeCredit, hasFreeCredits } from '@/lib/free-credits'
import OpenAI from 'openai'
import { chatCompletionWithCost } from '@/lib/metered-openai'
import { capMaxTokensToBudget } from '@/lib/cost-meter'
import { logAIUsage } from '@/lib/ai-usage-logger'
import { isSubscriptionActive } from '@/lib/subscription-utils'
import { logServerCall } from '@/lib/server-call-tracker'

// Initialize OpenAI client only when API key is available (same pattern as analyze-food)
const getOpenAIClient = () => {
  if (!process.env.OPENAI_API_KEY) return null
  return new OpenAI({ apiKey: process.env.OPENAI_API_KEY })
}

export async function POST(req: NextRequest) {
  try {
    // Auth check (with JWT fallback to avoid sporadic session resolution issues)
    const nativeUserId = await getUserIdFromNativeAuth(req)
    const session = await getServerSession(authOptions)
    let userEmail: string | null = session?.user?.email ?? null
    if (!nativeUserId && !userEmail) {
      try {
        const token = await getToken({
          req,
          secret: process.env.NEXTAUTH_SECRET || process.env.AUTH_SECRET || 'helfi-secret-key-production-2024',
        })
        if (token?.email) {
          userEmail = token.email as string
        }
      } catch {
        // ignore – will fall through to 401 below if still missing
      }
    }
    if (!nativeUserId && !userEmail) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    // Input parsing
    const contentType = req.headers.get('content-type')
    if (!contentType?.includes('application/json')) {
      return NextResponse.json({ error: 'Expected application/json' }, { status: 400 })
    }
    const body = await req.json()
    const { symptoms, duration, notes } = body as { symptoms?: string[] | string; duration?: string; notes?: string }

    const symptomsList: string[] = Array.isArray(symptoms)
      ? symptoms.filter(Boolean)
      : (typeof symptoms === 'string' ? symptoms.split(/[,\n]/).map(s => s.trim()).filter(Boolean) : [])

    if (!symptomsList.length) {
      return NextResponse.json({ error: 'Please enter at least one symptom' }, { status: 400 })
    }

    // Basic dependencies
    const openai = getOpenAIClient()
    if (!openai) {
      return NextResponse.json({ error: 'AI service not configured' }, { status: 500 })
    }

    // Fetch user
    const user = nativeUserId
      ? await prisma.user.findUnique({ where: { id: nativeUserId }, include: { subscription: true, creditTopUps: true } })
      : await prisma.user.findUnique({ where: { email: userEmail as string }, include: { subscription: true, creditTopUps: true } })
    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    logServerCall({
      feature: 'symptomAnalysis',
      endpoint: '/api/analyze-symptoms',
      kind: 'analysis',
    }).catch((error) => {
      console.error('❌ Failed to log symptom notes call:', error)
    })

    // PREMIUM/CREDITS/FREE USE GATING
    const isPremium = isSubscriptionActive(user.subscription)

    // Check if user has purchased credits (non-expired)
    const now = new Date()
    const hasPurchasedCredits = user.creditTopUps.some(
      (topUp: any) => topUp.expiresAt > now && (topUp.amountCents - topUp.usedCents) > 0
    )

    const hasFreeSymptomCredits = await hasFreeCredits(user.id, 'SYMPTOM_ANALYSIS')
    let allowViaFreeUse = false
    if (!isPremium && !hasPurchasedCredits && hasFreeSymptomCredits) {
      allowViaFreeUse = true
    } else if (!isPremium && !hasPurchasedCredits) {
      // No subscription, no credits, and no free credits - require payment
      return NextResponse.json(
        {
          error: 'Payment required',
          message: 'You\'ve used all your free symptom note uses. Subscribe to a monthly plan or purchase credits to continue.',
          requiresPayment: true,
          exhaustedFreeCredits: true,
        },
        { status: 402 }
      )
    }

    const creditManager = new CreditManager(user.id)
    // Trigger daily reset logic via credit system (ensures dailyMedicalAnalysisUsed resets too)
    const creditStatus = await creditManager.checkCredits('SYMPTOM_ANALYSIS')

    // Re-fetch to reflect any resets
    const refreshedUser = await prisma.user.findUnique({ where: { id: user.id }, include: { subscription: true } })
    if (!refreshedUser) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    // Daily/plan gating removed – wallet pre-check below governs access

    // Build prompt for general symptom notes with structured JSON.
    const symptomsStr = symptomsList.join(', ')
    const durationStr = duration ? String(duration).trim() : 'unspecified'
    const notesStr = notes ? String(notes).trim() : ''

    const messages = [
      {
        role: 'user' as const,
        content: `You are a general health information assistant that helps users organise symptom notes for a future conversation with a licensed healthcare professional.
You are not a doctor, not a medical device, and must not provide diagnosis, treatment advice, or certainty.

Create general symptom notes and produce:
- A short plain-language summary of what the user logged
- 3-5 general topics the user may want to discuss with a doctor, not likely causes and not diagnoses
- A clear list of warning signs where urgent care or emergency help may be appropriate
- Practical tracking notes and questions to discuss with a licensed healthcare professional
- Always include a disclaimer that this is general information only

Important:
- Do not name a condition as the likely answer.
- Do not rank conditions by likelihood.
- Do not suggest medicines, supplements, treatment plans, dosing, or home treatment.
- Do not tell the user they do not need a doctor.
- Be concise but careful. Do not reveal chain-of-thought.
- Use non-alarming, supportive language.
- If symptoms are potentially urgent, put them in the warning signs section.

User Input:
Symptoms: ${symptomsStr}
Duration: ${durationStr}
Notes: ${notesStr}

Return two parts:
1) A readable explanation for the user (one to three short paragraphs and section headers)
2) Then a compact JSON between <STRUCTURED_JSON> and </STRUCTURED_JSON> with this exact shape:
<STRUCTURED_JSON>{"summary":"string","possibleCauses":[{"name":"string","whyLikely":"string","confidence":"low|medium|high"}],"redFlags":["string"],"nextSteps":["string"],"disclaimer":"string"}</STRUCTURED_JSON>

JSON rules:
- The field named "possibleCauses" is an internal compatibility field. Fill it with general discussion topics only.
- "name" must be a broad topic such as "Digestive pattern to discuss" or "Respiratory symptoms to discuss", not a diagnosis.
- "whyLikely" must explain why the topic is worth discussing with a doctor, not why a condition is likely.
- Set every "confidence" value to "low" because Helfi is not assessing medical likelihood.
- "nextSteps" must contain tracking notes and doctor questions only, not treatment instructions.`
      }
    ]

    // Wallet pre-check (skip when allowed via one-time free use)
    const model = 'gpt-5.6-sol'
    const promptText = messages.map((m) => (typeof (m as any).content === 'string' ? (m as any).content : '')).join('\n')
    let maxTokens = 1200
    if (!allowViaFreeUse) {
      const cm = new CreditManager(refreshedUser.id)
      const wallet = await cm.getWalletStatus()
      const cappedMaxTokens = capMaxTokensToBudget(model, promptText, maxTokens, wallet.totalAvailableCents)
      if (cappedMaxTokens <= 0) {
        return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
      }
      maxTokens = cappedMaxTokens
    }

    // Immediate pre-charge (1 credit) before calling the model (skip for free trial)
    if (!allowViaFreeUse) {
      try {
        const cm = new CreditManager(refreshedUser.id)
        const immediate = CREDIT_COSTS.SYMPTOM_ANALYSIS
        const okPre = await cm.chargeCents(immediate)
        if (!okPre) {
          return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
        }
      } catch {
        return NextResponse.json({ error: 'Billing error' }, { status: 402 })
      }
    }

    // Progress is handled on UI; this call may take longer for deeper reasoning
    const wrapped = await chatCompletionWithCost(openai, {
      model,
      messages,
      max_tokens: maxTokens,
      temperature: 0.4,
    } as any)

    const content = wrapped.completion.choices?.[0]?.message?.content || ''
    if (!content) {
      return NextResponse.json({ error: 'No analysis received from AI service' }, { status: 500 })
    }

    // Try to extract structured JSON block
    let structured: any = null
    try {
      const m = content.match(/<STRUCTURED_JSON>([\s\S]*?)<\/STRUCTURED_JSON>/i)
      if (m && m[1]) {
        structured = JSON.parse(m[1])
      }
    } catch {
      // ignore parsing error, we'll still return analysisText
    }

    // Symptom Notes has a fixed advertised price. The model's actual cost is
    // still recorded below for internal tracking, but must not be charged to
    // the user's wallet on top of the fixed pre-charge.

    // Update counters (for all users, not just premium)
    await prisma.user.update({
      where: { id: refreshedUser.id },
      data: {
        totalAnalysisCount: { increment: 1 },
        monthlySymptomAnalysisUsed: { increment: 1 },
      } as any,
    })

    if (allowViaFreeUse) {
      await consumeFreeCredit(refreshedUser.id, 'SYMPTOM_ANALYSIS')
    }

    // Log AI usage for cost tracking (fire-and-forget; does not affect user flow)
    try {
      await logAIUsage({
        context: { feature: 'symptoms:analysis', userId: refreshedUser.id },
        model,
        promptTokens: wrapped.promptTokens,
        completionTokens: wrapped.completionTokens,
        costCents: wrapped.costCents,
      })
    } catch {
      // Logging failures must never break the main feature
    }

    // Build response
    const analysisText = content.replace(/<STRUCTURED_JSON>[\s\S]*?<\/STRUCTURED_JSON>/i, '').trim()
    const resp: any = {
      success: true,
      analysisText,
    }
    if (structured && typeof structured === 'object') {
      resp.summary = structured.summary || null
      resp.possibleCauses = Array.isArray(structured.possibleCauses) ? structured.possibleCauses : []
      resp.redFlags = Array.isArray(structured.redFlags) ? structured.redFlags : []
      resp.nextSteps = Array.isArray(structured.nextSteps) ? structured.nextSteps : []
      resp.disclaimer = structured.disclaimer || 'This is not medical advice. If you have concerning or worsening symptoms, contact a licensed medical professional or emergency services.'
    } else {
      // Always ensure a disclaimer is present
      resp.disclaimer = 'This is not medical advice. If you have concerning or worsening symptoms, contact a licensed medical professional or emergency services.'
    }

    try {
      const analysisData = structured && typeof structured === 'object'
        ? {
            summary: resp.summary ?? null,
            possibleCauses: resp.possibleCauses ?? [],
            redFlags: resp.redFlags ?? [],
            nextSteps: resp.nextSteps ?? [],
            disclaimer: resp.disclaimer ?? null,
          }
        : {
            summary: resp.summary ?? null,
            possibleCauses: [],
            redFlags: [],
            nextSteps: [],
            disclaimer: resp.disclaimer ?? null,
          }

      await prisma.symptomAnalysis.create({
        data: {
          userId: refreshedUser.id,
          symptoms: symptomsList,
          duration: duration ? String(duration).trim() : null,
          notes: notes ? String(notes).trim() : null,
          summary: resp.summary ?? null,
          analysisText: analysisText || null,
          analysisData,
        },
      })
    } catch (historyError) {
      console.warn('Failed to save symptom notes history:', historyError)
    }

    return NextResponse.json(resp)
  } catch (error) {
    if (error instanceof Error) {
      if (error.message.includes('insufficient_quota')) {
        return NextResponse.json({ error: 'AI service quota exceeded. Please check your billing.' }, { status: 429 })
      }
      if (error.message.includes('invalid_api_key')) {
        return NextResponse.json({ error: 'Invalid AI service key. Please check your configuration.' }, { status: 401 })
      }
    }
    return NextResponse.json({ error: 'Failed to analyze symptoms' }, { status: 500 })
  }
}

