import {
  assertGarminConfigured,
  exchangeGarminCodeForTokens,
  fetchGarminUserId,
  registerGarminUser,
} from '@/lib/garmin-oauth'

function nativeReturnHtml(provider: 'garmin', status: 'connected' | 'error', error?: string) {
