  servings?: number | null
  calories: number | null
  protein_g: number | null
  carbs_g: number | null
  fat_g: number | null
  fiber_g: number | null
  sugar_g: number | null
  barcode?: string | null
  basis?: 'per_serving' | 'per_100g' | null
  quantity_g?: number | null
  energyUnit?: 'kcal' | 'kJ' | null
  piecesPerServing?: number | null
  pieces?: number | null
}

type OpenFoodFactsResult = {
  food: NormalizedFood | null
  productName: string | null
}

const parseNumber = (val?: string | number | null): number | null => {
  if (val === undefined || val === null) return null
  const num = typeof val === 'number' ? val : parseFloat(val)
  return Number.isFinite(num) ? num : null
}

const kjToKcal = (valueKj: number | null): number | null => {
  if (!Number.isFinite(Number(valueKj))) return null
  const kcal = Number(valueKj) / 4.184
  return Number.isFinite(kcal) ? Math.round(kcal * 10) / 10 : null
}

const parseGramsFromLabel = (label?: string | null): number | null => {
  if (!label) return null
  const normalized = String(label).toLowerCase()
  const g = normalized.match(/(\d+(?:\.\d+)?)\s*(g|gram|grams)/i)
  if (g) return parseFloat(g[1])
  const ml = normalized.match(/(\d+(?:\.\d+)?)\s*(ml|milliliter|millilitre)/i)
  if (ml) return parseFloat(ml[1])
  const oz = normalized.match(/(\d+(?:\.\d+)?)\s*(oz|ounce|ounces)/i)
  if (oz) return parseFloat(oz[1]) * 28.3495
  return null
}

const parseServingWeight = (servingSize?: string | null): number | null => {
  if (!servingSize) return null
  const normalized = String(servingSize).toLowerCase()
  const g = normalized.match(/(\d+(?:\.\d+)?)\s*(g|gram|grams)\b/i)
  if (g) return parseFloat(g[1])
  const ml = normalized.match(/(\d+(?:\.\d+)?)\s*(ml|milliliter|millilitre)\b/i)
  if (ml) return parseFloat(ml[1])
  const oz = normalized.match(/(\d+(?:\.\d+)?)\s*(oz|ounce|ounces)\b/i)
  if (oz) return parseFloat(oz[1]) * 28.3495
  return null
}

const expandUpcEToUpcA = (value: string): string | null => {
  if (!/^[01]\d{7}$/.test(value)) return null
  const numberSystem = value[0]
  const e1 = value[1]
  const e2 = value[2]
  const e3 = value[3]
  const e4 = value[4]
  const e5 = value[5]
  const e6 = value[6]
  const check = value[7]
  let manufacturer = ''
  let product = ''
  if (e6 === '0' || e6 === '1' || e6 === '2') {
    manufacturer = `${e1}${e2}${e6}00`
    product = `00${e3}${e4}${e5}`
  } else if (e6 === '3') {
    manufacturer = `${e1}${e2}${e3}00`
    product = `000${e4}${e5}`
  } else if (e6 === '4') {
    manufacturer = `${e1}${e2}${e3}${e4}0`
    product = `0000${e5}`
  } else {
    manufacturer = `${e1}${e2}${e3}${e4}${e5}`
    product = `0000${e6}`
  }
  return `${numberSystem}${manufacturer}${product}${check}`
}

const BARCODE_TRAILING_DESCRIPTOR_TOKENS = new Set([
  'smooth',
  'mild',
  'sharp',
  'creamy',
  'soft',
  'hard',
  'smoked',
  'salted',
  'sweet',
  'spicy',
  'classic',
  'original',
  'light',
  'thick',
  'thin',
])

const tokenizeBarcodeName = (value: string | null | undefined) =>
  String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .split(' ')
    .filter(Boolean)

const shouldProbeOpenFoodFactsForNameOrder = (value: string | null | undefined) => {
  const tokens = tokenizeBarcodeName(value)
  if (tokens.length !== 2) return false
  const [first, second] = tokens
  return BARCODE_TRAILING_DESCRIPTOR_TOKENS.has(second) && !BARCODE_TRAILING_DESCRIPTOR_TOKENS.has(first)
}

const haveSameTokenBag = (left: string | null | undefined, right: string | null | undefined) => {
  const a = tokenizeBarcodeName(left)
  const b = tokenizeBarcodeName(right)
  if (a.length === 0 || a.length !== b.length) return false
  const sortedA = [...a].sort()
  const sortedB = [...b].sort()
  return sortedA.every((token, idx) => token === sortedB[idx])
}

const isLikelyOilProduct = (nameRaw: string | null | undefined): boolean => {
  const name = String(nameRaw || '').toLowerCase()
  if (!name) return false
  return (
    name.includes('oil') ||
    name.includes('olive oil') ||
    name.includes('avocado oil') ||
    name.includes('coconut oil') ||
    name.includes('sesame oil') ||
    name.includes('canola oil') ||
    name.includes('sunflower oil') ||
    name.includes('vegetable oil') ||
    name.includes('grapeseed oil')
  )
}

const isServingNutritionPlausible = (data: {
  servingSize?: string | null
  calories?: number | null
  protein?: number | null
  carbs?: number | null
  fat?: number | null
  fiber?: number | null
}) => {
  const weight = parseServingWeight(data.servingSize || null)
  if (!weight || weight <= 0) return true
  const safe = (v?: number | null) => (Number.isFinite(Number(v)) && Number(v) > 0 ? Number(v) : 0)
  const macroSum = safe(data.protein) + safe(data.carbs) + safe(data.fat) + safe(data.fiber)
  const macroLimit = weight * 1.3 + 2
  if (macroSum > macroLimit) return false
  const calories = safe(data.calories)
  const calorieLimit = weight * 9.5 + 10
  if (calories > calorieLimit) return false
  return true
}

