// ============ FatSecret API ============

async function getFatSecretAccessToken(): Promise<string | null> {
  if (!FATSECRET_CLIENT_ID || !FATSECRET_CLIENT_SECRET) {
    console.log('FatSecret credentials not configured, skipping')
    return null
  }

  try {
    const params = new URLSearchParams({
      grant_type: 'client_credentials',
      scope: 'basic',
    })

    const auth = Buffer.from(`${FATSECRET_CLIENT_ID}:${FATSECRET_CLIENT_SECRET}`).toString('base64')

    const res = await fetch('https://oauth.fatsecret.com/connect/token', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        Authorization: `Basic ${auth}`,
      },
      body: params.toString(),
      cache: 'no-store',
    })

    if (!res.ok) {
      const txt = await res.text()
      console.warn('FatSecret token request failed', res.status, txt.substring(0, 200))
      return null
    }

    const data = await res.json()
    return data.access_token || null
  } catch (err) {
    console.warn('FatSecret token error', err)
    return null
  }
}

async function fetchFoodFromFatSecret(barcode: string): Promise<NormalizedFood | null> {
  const token = await getFatSecretAccessToken()
  if (!token) return null

  try {
    // Step 1: find food_id from barcode
    const findParams = new URLSearchParams({
      method: 'food.find_id_for_barcode',
      barcode,
      format: 'json',
    })

    const findRes = await fetch(`https://platform.fatsecret.com/rest/server.api?${findParams.toString()}`, {
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
      cache: 'no-store',
      next: { revalidate: 0 },
    })

    if (!findRes.ok) {
      const txt = await findRes.text()
      console.warn('FatSecret barcode lookup failed', findRes.status, txt.substring(0, 200))
      return null
    }

    const findData = await findRes.json()
    const foodId =
      findData?.food?.food_id ||
      findData?.food_id ||
      findData?.food?.[0]?.food_id

    if (!foodId) {
      console.log('FatSecret: No food_id found for barcode', barcode)
      return null
    }

    // Step 2: fetch food details
    const foodParams = new URLSearchParams({
      method: 'food.get.v2',
      food_id: String(foodId),
      format: 'json',
    })

    const foodRes = await fetch(`https://platform.fatsecret.com/rest/server.api?${foodParams.toString()}`, {
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
      cache: 'no-store',
      next: { revalidate: 0 },
    })

    if (!foodRes.ok) {
      const txt = await foodRes.text()
      console.warn('FatSecret food.get.v2 failed', foodRes.status, txt.substring(0, 200))
      return null
    }

    const foodJson = await foodRes.json()
    const food: FatSecretFood | null = (foodJson as any)?.food || null
    if (!food?.food_name) return null

    // Handle both array and single serving object
    const servingsRaw = food.servings?.serving
    const servings = Array.isArray(servingsRaw) ? servingsRaw : servingsRaw ? [servingsRaw] : []
    if (servings.length === 0) return null

    const preferred =
      servings.find(
        (s) =>
          s.measurement_description?.toLowerCase().includes('100 g') ||
          s.measurement_description?.toLowerCase().includes('serving'),
      ) || servings[0]

    console.log('✅ FatSecret found:', food.food_name, 'for barcode', barcode)

    const servingSize = preferred.measurement_description || preferred.serving_description || '1 serving'
    const quantity_g = parseGramsFromLabel(servingSize)
    const basis: NormalizedFood['basis'] = servingSize.toLowerCase().includes('100 g') ? 'per_100g' : 'per_serving'

    return {
      source: 'fatsecret',
      id: String(foodId),
      name: food.food_name,
      brand: food.brand_name || null,
      serving_size: servingSize,
      calories: parseNumber(preferred.calories),
      protein_g: parseNumber(preferred.protein),
      carbs_g: parseNumber(preferred.carbohydrate),
      fat_g: parseNumber(preferred.fat),
      fiber_g: parseNumber(preferred.fiber),
      sugar_g: parseNumber(preferred.sugar),
      barcode,
      basis,
      quantity_g,
      energyUnit: null,
    }
  } catch (err) {
    console.warn('FatSecret barcode handler error', err)
    return null
  }
}

// ============ OpenFoodFacts API ============

async function fetchFoodFromOpenFoodFacts(barcode: string): Promise<OpenFoodFactsResult> {
  try {
    const url = `https://world.openfoodfacts.org/api/v0/product/${encodeURIComponent(barcode)}.json`
    const res = await fetch(url, {
      headers: {
        'User-Agent': OPENFOODFACTS_USER_AGENT,
      },
      cache: 'no-store',
      next: { revalidate: 0 },
    })

    if (!res.ok) {
      console.warn('OpenFoodFacts barcode lookup failed', res.status)
      return { food: null, productName: null }
    }

    const data = await res.json()
    if (data?.status !== 1 || !data?.product) {
      return { food: null, productName: null }
    }

    const product = data.product || {}
    const nutr = product.nutriments || {}

    const name: string =
      product.product_name ||
      product.generic_name ||
      product.brands ||
      product.categories ||
      product.labels ||
      barcode

    if (!name) return { food: null, productName: null }

    const servingSizeRaw = String(product.serving_size || '').trim()
    const servingSize = servingSizeRaw || '1 serving'
    const quantity_g = parseGramsFromLabel(servingSize)

    const kcalServing = parseNumber(nutr['energy-kcal_serving'])
    const kjServing = parseNumber(nutr['energy_serving'])
    const kcal100g = parseNumber(nutr['energy-kcal_100g'])
    const kj100g = parseNumber(nutr['energy_100g'])

    const proteinServing = parseNumber(nutr['proteins_serving'])
    const carbsServing = parseNumber(nutr['carbohydrates_serving'])
    const fatServing = parseNumber(nutr['fat_serving'])
    const fiberServing = parseNumber(nutr['fiber_serving'])
    const sugarServing = parseNumber(nutr['sugars_serving'])

    const protein100g = parseNumber(nutr['proteins_100g'])
    const carbs100g = parseNumber(nutr['carbohydrates_100g'])
    const fat100g = parseNumber(nutr['fat_100g'])
    const fiber100g = parseNumber(nutr['fiber_100g'])
    const sugar100g = parseNumber(nutr['sugars_100g'])

    // Prefer per-serving values when present, otherwise use per-100g.
    const hasServingMacros =
      kcalServing != null ||
      kjServing != null ||
      proteinServing != null ||
      carbsServing != null ||
      fatServing != null

    const calories = hasServingMacros ? (kcalServing ?? kjToKcal(kjServing)) : (kcal100g ?? kjToKcal(kj100g))
    const protein_g = hasServingMacros ? proteinServing : protein100g
    const carbs_g = hasServingMacros ? carbsServing : carbs100g
    const fat_g = hasServingMacros ? fatServing : fat100g
    const fiber_g = hasServingMacros ? fiberServing : fiber100g
    const sugar_g = hasServingMacros ? sugarServing : sugar100g

    const basis: NormalizedFood['basis'] = hasServingMacros ? 'per_serving' : 'per_100g'
    const finalServingSize = hasServingMacros ? servingSize : '100 g'

    const plausible = isServingNutritionPlausible({
      servingSize: finalServingSize,
      calories,
      protein: protein_g,
      carbs: carbs_g,
      fat: fat_g,
      fiber: fiber_g,
    })
    if (!plausible) {
      console.warn('OpenFoodFacts rejected due to implausible nutrition', barcode)
      return { food: null, productName: name }
    }

    return {
      food: {
        source: 'openfoodfacts',
        id: barcode,
        name,
        brand: product.brands || null,
        serving_size: finalServingSize,
        calories,
        protein_g,
        carbs_g,
        fat_g,
        fiber_g,
        sugar_g,
        barcode,
        basis,
        quantity_g,
        energyUnit: kcalServing != null || kcal100g != null ? 'kcal' : kjServing != null || kj100g != null ? 'kJ' : null,
      },
      productName: name,
    }
  } catch (err) {
    console.warn('OpenFoodFacts barcode handler error', err)
    return { food: null, productName: null }
  }
}

// ============ USDA API (search by product name) ============

async function searchFoodFromUSDA(productName: string, barcode: string): Promise<NormalizedFood | null> {
  if (!USDA_API_KEY) {
    console.log('USDA API key not configured, skipping')
    return null
  }

  try {
    const params = new URLSearchParams({
      api_key: USDA_API_KEY,
      query: productName,
      pageSize: '1',
      dataType: 'Branded',
    })

    const url = `https://api.nal.usda.gov/fdc/v1/foods/search?${params.toString()}`

    const res = await fetch(url, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
      },
      cache: 'no-store',
      next: { revalidate: 0 },
    })

    if (!res.ok) {
      console.warn('USDA search failed', res.status)
      return null
    }

    const data = await res.json()
    const foods = data.foods || []

    if (foods.length === 0) {
      console.log('USDA: No results for query', productName)
      return null
    }

    const food = foods[0]
    const nutrients = food.foodNutrients || []

    const findNutrient = (name: string): number | null => {
      const n = nutrients.find(
        (n: any) => n.nutrientName?.toLowerCase().includes(name.toLowerCase())
      )
      return n ? parseNumber(n.value) : null
    }

    console.log('✅ USDA found:', food.description, 'for barcode', barcode)

    const servingSize =
      food.servingSize ? `${food.servingSize} ${food.servingSizeUnit || 'g'}` : '100 g'
    const quantity_g = parseGramsFromLabel(servingSize)
    const basis: NormalizedFood['basis'] = food.servingSize ? 'per_serving' : 'per_100g'

    return {
      source: 'usda',
      id: String(food.fdcId),
      name: food.description || productName,
      brand: food.brandName || food.brandOwner || null,
      serving_size: servingSize,
      calories: findNutrient('energy'),
      protein_g: findNutrient('protein'),
      carbs_g: findNutrient('carbohydrate'),
      fat_g: findNutrient('fat') ?? findNutrient('lipid'),
      fiber_g: findNutrient('fiber'),
      sugar_g: findNutrient('sugar'),
      barcode,
      basis,
      quantity_g,
      energyUnit: null,
    }
  } catch (err) {
    console.warn('USDA search error', err)
    return null
  }
}

// ============ Main Handler ============

export async function GET(req: NextRequest) {
  const { searchParams } = new URL(req.url)
  const code = (searchParams.get('code') || '').trim().replace(/[^0-9A-Za-z]/g, '')

  if (!code) {
    return NextResponse.json({ error: 'Missing barcode code' }, { status: 400 })
  }

  // Require signed-in user for credit charge
  const session = await getServerSession(authOptions)
  let userEmail = session?.user?.email || null
  if (!userEmail) {
    try {
      const token = await getToken({
        req,
        secret: process.env.NEXTAUTH_SECRET || process.env.AUTH_SECRET || 'helfi-secret-key-production-2024',
      })
      if (token?.email) userEmail = String(token.email)
    } catch (tokenError) {
      console.error('❌ Barcode lookup JWT auth fallback failed:', tokenError)
    }
  }
  if (!userEmail) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const user = await prisma.user.findUnique({
    where: { email: userEmail },
    include: { subscription: true, creditTopUps: true },
  })

  if (!user) {
    return NextResponse.json({ error: 'User not found' }, { status: 404 })
  }

  const cm = new CreditManager(user.id)
  const wallet = await cm.getWalletStatus()
  // Pre-check for sufficient credits, but only charge if a product is actually found
  if (wallet.totalAvailableCents < BARCODE_SCAN_COST_CENTS) {
    return NextResponse.json(
      { error: 'Insufficient credits', message: 'Barcode scanning requires 3 credits.' },
      { status: 402 },
    )
  }

  const buildBarcodeCandidates = (value: string) => {
    const normalized = value.replace(/[^0-9A-Za-z]/g, '')
    const candidates = new Set<string>()
    const addWithNumericVariants = (candidate: string) => {
      if (!candidate) return
      candidates.add(candidate)
      if (!/^\d+$/.test(candidate)) return
      if (candidate.length === 12) candidates.add(`0${candidate}`)
      if (candidate.length === 13 && candidate.startsWith('0')) candidates.add(candidate.slice(1))
    }
    addWithNumericVariants(normalized)
    if (/^[01]\d{7}$/.test(normalized)) {
      const expanded = expandUpcEToUpcA(normalized)
      if (expanded) addWithNumericVariants(expanded)
    }
    return Array.from(candidates)
  }

  const barcodeCandidates = buildBarcodeCandidates(code)

  console.log('🔍 Looking up barcode:', code)
  let food: NormalizedFood | null = null
  let openFoodFacts: OpenFoodFactsResult | null = null

  // Try Helfi cache first (user-labeled nutrition from barcode scans)
  for (const candidate of barcodeCandidates) {
    food = await fetchFoodFromHelfiBarcode(candidate)
    if (food) {
      if (candidate !== code) {
        console.log('✅ Helfi barcode matched via normalized code', candidate)
      }
      break
    }
  }

  // Try local USDA cache next (branded foods with barcodes)
  if (!food) {
    for (const candidate of barcodeCandidates) {
      food = await fetchFoodFromLocalBarcode(candidate)
      if (food) {
        if (candidate !== code) {
          console.log('✅ Local barcode matched via normalized code', candidate)
        }
        break
      }
    }
  }

  // Try FatSecret first (best for packaged foods)
  if (!food) {
    for (const candidate of barcodeCandidates) {
      food = await fetchFoodFromFatSecret(candidate)
      if (food) {
        if (candidate !== code) {
          console.log('✅ FatSecret barcode matched via normalized code', candidate)
        }
        break
      }
    }
  }

  // Try OpenFoodFacts next (often best coverage outside US)
  if (!food) {
    for (const candidate of barcodeCandidates) {
      const result = await fetchFoodFromOpenFoodFacts(candidate)
      if (!openFoodFacts?.productName && result.productName) {
        openFoodFacts = { food: null, productName: result.productName }
      }
      if (result.food) {
        openFoodFacts = result
        food = result.food
        if (candidate !== code) {
          console.log('✅ OpenFoodFacts barcode matched via normalized code', candidate)
        }
        break
      }
    }
  }

  // Try USDA using the best available product name
  if (!food) {
    const usdaQuery = openFoodFacts?.productName || code
    for (const candidate of barcodeCandidates) {
      const usdaFood = await searchFoodFromUSDA(usdaQuery, candidate)
      if (usdaFood) {
        food = usdaFood
        if (candidate !== code) {
          console.log('✅ USDA barcode matched via normalized code', candidate)
        }
        break
      }
    }
  }

  if (food) {
    // If provider order looks reversed (e.g. "Blue smooth"), try OFF title order.
    if (food.source !== 'openfoodfacts' && shouldProbeOpenFoodFactsForNameOrder(food.name)) {
      try {
        const probe = await fetchFoodFromOpenFoodFacts(code)
        const candidateName = String(probe?.productName || '').trim()
        const currentName = String(food.name || '').trim()
        if (candidateName && currentName && currentName !== candidateName && haveSameTokenBag(currentName, candidateName)) {
          food = { ...food, name: candidateName }
          console.log('✅ Barcode name order corrected via OpenFoodFacts title', {
            from: currentName,
            to: candidateName,
          })
        }
      } catch (err) {
        console.warn('OpenFoodFacts name-order probe failed', err)
      }
    }

    console.log('[BARCODE_DEBUG] source payload', {
      source: food.source,
      serving_size: food.serving_size,
      calories: food.calories,
      protein_g: food.protein_g,
      carbs_g: food.carbs_g,
      fat_g: food.fat_g,
      fiber_g: food.fiber_g,
      sugar_g: food.sugar_g,
      basis: food.basis || null,
      quantity_g: food.quantity_g || null,
      energyUnit: food.energyUnit || null,
    })

    const normalized = normalizeBarcodeFood(food)
    food = {
      ...food,
      ...normalized.food,
      source: food.source,
      serving_size: normalized.food.serving_size || food.serving_size || '1 serving',
      name: food.name || 'Scanned food',
      id: String(food.id || code),
    }

    const protein = Number(food.protein_g ?? 0)
    const carbs = Number(food.carbs_g ?? 0)
    const sugar = Number(food.sugar_g ?? 0)
    const fiber = Number(food.fiber_g ?? 0)
    const fat = Number(food.fat_g ?? 0)
    const nonFatMacros =
      (Number.isFinite(protein) && protein > 0.5) ||
      (Number.isFinite(carbs) && carbs > 0.5) ||
      (Number.isFinite(sugar) && sugar > 0.5) ||
      (Number.isFinite(fiber) && fiber > 0.5)
    if (food.source !== 'helfi' && isLikelyOilProduct(food.name) && Number.isFinite(fat) && fat > 10 && nonFatMacros) {
      return NextResponse.json(
        {
          found: false,
          error: 'nutrition_suspect',
          message: 'Barcode nutrition for oils looks unreliable. Please scan the nutrition label to lock in the correct values.',
          product: {
            name: food.name || null,
            brand: food.brand || null,
            serving_size: food.serving_size || null,
          },
          barcode: code,
        },
        { status: 422 },
      )
    }

    // Owner rule: never return a barcode result without calories + protein + carbs + fat.
    const required = [food.calories, food.protein_g, food.carbs_g, food.fat_g]
    const hasRequiredMacros = required.every((v) => Number.isFinite(Number(v)))
    if (!hasRequiredMacros) {
      return NextResponse.json(
        {
          found: false,
          error: 'nutrition_missing',
          message: 'Product found, but calories/macros are missing. Please scan the nutrition label instead.',
          product: {
            name: food.name || null,
            brand: food.brand || null,
            serving_size: food.serving_size || null,
          },
          barcode: code,
        },
        { status: 422 },
      )
    }

    const discreteLog = summarizeDiscreteItemsForLog([food])
    if (discreteLog.length > 0) {
      console.log('[BARCODE_DEBUG] discrete normalization', discreteLog)
    }
    console.log('[BARCODE_DEBUG] normalized barcode payload', normalized.debug)

    // Charge only when we actually have a product to return
    const charged = await cm.chargeCents(BARCODE_SCAN_COST_CENTS)
    if (!charged) {
      return NextResponse.json(
        { error: 'Insufficient credits', message: 'Barcode scanning requires 3 credits.' },
        { status: 402 },
      )
    }
    return NextResponse.json({ found: true, food })
  }

  console.log('⚠️ No barcode match found after FatSecret, OpenFoodFacts, or USDA for:', code)

  return NextResponse.json(
    {
      found: false,
      message: 'No product found for this barcode. Try searching by product name instead.',
      barcode: code,
    },
    { status: 404 },
  )
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import Stripe from 'stripe'
import { notifyOwner } from '@/lib/owner-notifications'
import { reportCriticalError } from '@/lib/error-reporter'

// Force dynamic so this route isn't considered for static optimization at build time
export const dynamic = 'force-dynamic'
export const revalidate = 0

export async function GET(request: NextRequest) {
  let sessionParam: string | null = null
  try {
    sessionParam = new URL(request.url).searchParams.get('session_id')
    if (!sessionParam) {
      return NextResponse.json({ error: 'missing_session_id' }, { status: 400 })
    }
    const secretKey = process.env.STRIPE_SECRET_KEY
    if (!secretKey) {
      return NextResponse.json({ error: 'stripe_not_configured' }, { status: 500 })
    }
    const stripe = new Stripe(secretKey, { apiVersion: '2024-06-20' })
    const checkout = await stripe.checkout.sessions.retrieve(sessionParam, {
      expand: ['line_items', 'payment_intent'],
    })

    if (checkout.payment_status !== 'paid') {
      return NextResponse.json({ error: 'not_paid' }, { status: 400 })
    }

    const serverSession = (await getServerSession(authOptions as any)) as any
    const sessionUserId = (serverSession?.user?.id as string) || ''
    const sessionEmail = ((serverSession?.user?.email as string) || '').toLowerCase()
    const metadata = (checkout.metadata || {}) as Record<string, string>
    const metaUserId = String(metadata.helfi_user_id || '').trim()
    const metaEmail = String(metadata.helfi_user_email || '').toLowerCase().trim()
    const checkoutEmail = String(checkout.customer_details?.email || checkout.customer_email || '').toLowerCase().trim()
    const expectedUserId = metaUserId
    const expectedEmail = metaEmail || checkoutEmail

    if ((sessionUserId || sessionEmail) && (expectedUserId || expectedEmail)) {
      const matchesId = expectedUserId && sessionUserId && expectedUserId === sessionUserId
      const matchesEmail = expectedEmail && sessionEmail && expectedEmail === sessionEmail
      if (!matchesId && !matchesEmail) {
        return NextResponse.json({ error: 'user_mismatch' }, { status: 403 })
      }
    }

    let user = null as { id: string; email: string; name: string | null } | null
    if (expectedUserId) {
      user = await prisma.user.findUnique({ where: { id: expectedUserId }, select: { id: true, email: true, name: true } })
    } else if (expectedEmail) {
      user = await prisma.user.findUnique({ where: { email: expectedEmail }, select: { id: true, email: true, name: true } })
    } else if (sessionEmail) {
      user = await prisma.user.findUnique({ where: { email: sessionEmail }, select: { id: true, email: true, name: true } })
    }

    if (!user) {
      return NextResponse.json({ error: 'user_not_found' }, { status: 404 })
    }

    // Only process one time
    const existing = await prisma.creditTopUp.findFirst({
      where: { source: `stripe:${checkout.id}` },
    })
    if (existing) {
      return NextResponse.json({ ok: true, alreadyProcessed: true })
    }

    // For credit purchases we used Checkout in 'payment' mode.
    const paymentCents = typeof checkout.amount_total === 'number' ? checkout.amount_total : 0
    if (paymentCents <= 0 || checkout.mode !== 'payment') {
      return NextResponse.json({ error: 'not_a_credit_purchase' }, { status: 400 })
    }

    const purchasedAt = new Date()
    const expiresAt = new Date(purchasedAt)
    expiresAt.setUTCMonth(expiresAt.getUTCMonth() + 12)

    // Map paid amount to wallet credits (not 1:1 dollars). New schedule (75% profit target):
    // $5 -> 250 credits, $10 -> 500 credits, $20 -> 1,000 credits. Fallback: use payment amount.
    let creditAmount = 0
    if (paymentCents >= 2000) creditAmount = 1000
    else if (paymentCents >= 1000) creditAmount = 500
    else if (paymentCents >= 500) creditAmount = 250
    const walletCredits = creditAmount > 0 ? creditAmount : paymentCents

    await prisma.creditTopUp.create({
      data: {
        userId: user.id,
        amountCents: walletCredits,
        usedCents: 0,
        purchasedAt,
        expiresAt,
        source: `stripe:${checkout.id}`,
      },
    })

    // Notify owner of credit purchase (don't await to avoid blocking response)
    notifyOwner({
      event: 'credit_purchase',
      userEmail: user.email,
      userName: user.name || undefined,
      amount: paymentCents,
      currency: (checkout.currency || 'usd').toUpperCase(),
      creditAmount: creditAmount || undefined,
    }).catch(error => {
      console.error('❌ Owner notification failed (non-blocking):', error)
    })

    return NextResponse.json({ ok: true })
  } catch (err) {
    reportCriticalError({
      source: 'billing.confirm',
      error: err,
      details: {
        sessionId: sessionParam || undefined,
      },
    })
    console.error('[billing.confirm] error', err)
    return NextResponse.json({ error: 'server_error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import Stripe from 'stripe'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import crypto from 'crypto'
import { getAffiliateCookieData, isAffiliateAttributionFresh } from '@/lib/affiliate-cookies'

// POST /api/billing/create-checkout-session
export async function POST(request: NextRequest) {
  try {
    const secretKey = process.env.STRIPE_SECRET_KEY
    if (!secretKey) {
      return NextResponse.json({ error: 'Stripe not configured' }, { status: 500 })
    }

    const stripe = new Stripe(secretKey, {
      apiVersion: '2024-06-20',
    })

    const url = new URL(request.url)
    const origin = url.origin

    const body = await request.json().catch(() => ({} as any))
    const requestedPlan: string | undefined = body?.plan
    const quantity: number = Number(body?.quantity || 1)

    const PLAN_TO_PRICE: Record<string, string | undefined> = {
      // Monthly subscription plans
      plan_10_monthly: process.env.STRIPE_PRICE_10_MONTHLY,
      plan_20_monthly: process.env.STRIPE_PRICE_20_MONTHLY,
      plan_30_monthly: process.env.STRIPE_PRICE_30_MONTHLY,
      plan_50_monthly: process.env.STRIPE_PRICE_50_MONTHLY,
      // Legacy plan names (for backward compatibility)
      premium_monthly: process.env.STRIPE_PRICE_PREMIUM_MONTHLY,
      premium_yearly: process.env.STRIPE_PRICE_PREMIUM_YEARLY,
      premium_plus_monthly: process.env.STRIPE_PRICE_PREMIUM_PLUS_MONTHLY,
      premium_plus_yearly: process.env.STRIPE_PRICE_PREMIUM_PLUS_YEARLY,
      // Credit top-ups (one-time payments)
      credits_250: process.env.STRIPE_PRICE_CREDITS_250,
      credits_500: process.env.STRIPE_PRICE_CREDITS_500,
      credits_1000: process.env.STRIPE_PRICE_CREDITS_1000,
      // Legacy credit name
      credits_100: process.env.STRIPE_PRICE_CREDITS_100,
    }

    const priceId = requestedPlan ? PLAN_TO_PRICE[requestedPlan] : undefined
    const isCredits = (requestedPlan ?? '').startsWith('credits_')

    if (!isCredits && !priceId) {
      return NextResponse.json({ error: 'Invalid plan or price not configured' }, { status: 400 })
    }
    if (isCredits && !requestedPlan) {
      return NextResponse.json({ error: 'Invalid credit plan' }, { status: 400 })
    }

    const CREDIT_PLAN_FALLBACK: Record<string, { unitAmount: number; title: string }> = {
      credits_250: { unitAmount: 500, title: 'Helfi Credit Top-up (250 credits)' },
      credits_500: { unitAmount: 1000, title: 'Helfi Credit Top-up (500 credits)' },
      credits_1000: { unitAmount: 2000, title: 'Helfi Credit Top-up (1,000 credits)' },
      credits_100: { unitAmount: 200, title: 'Helfi Credit Top-up (100 credits)' },
    }

    // Get user email from session if available
    const session = await getServerSession(authOptions)
    const customerEmail = session?.user?.email || undefined

    const affiliateCookie = getAffiliateCookieData(request)
    let hasFreshAffiliateAttribution =
      affiliateCookie && isAffiliateAttributionFresh(affiliateCookie.clickedAtMs)
        ? true
        : false
    if (hasFreshAffiliateAttribution && customerEmail) {
      const referringAffiliate = await prisma.affiliate.findUnique({
        where: { code: affiliateCookie!.code.toLowerCase() },
        select: { user: { select: { email: true } } },
      })
      if (referringAffiliate?.user?.email?.toLowerCase() === customerEmail.toLowerCase()) {
        hasFreshAffiliateAttribution = false
      }
    }
    const baseMetadata: Record<string, string> = {}
    if (hasFreshAffiliateAttribution) {
      baseMetadata.helfi_aff_code = affiliateCookie!.code
      baseMetadata.helfi_aff_click = affiliateCookie!.clickId
      baseMetadata.helfi_aff_ts = String(affiliateCookie!.clickedAtMs)
    }
    if (session?.user?.id) {
      baseMetadata.helfi_user_id = String(session.user.id)
    }
    if (customerEmail) {
      baseMetadata.helfi_user_email = String(customerEmail).toLowerCase()
    }

    // Check if user already has an active subscription (only for subscription plans, not credit top-ups)
    if (!isCredits && customerEmail) {
      try {
        const user = await prisma.user.findUnique({
          where: { email: customerEmail.toLowerCase() },
          include: { subscription: true }
        })

        if (user?.subscription) {
          // Check if subscription is active (no endDate or endDate is in the future)
          const now = new Date()
          const isActive = !user.subscription.endDate || new Date(user.subscription.endDate) > now

          if (isActive) {
            // Determine current plan tier for better error message
            const currentTier = user.subscription.monthlyPriceCents
            let tierName = 'Premium'
            if (currentTier === 1000) tierName = '$10/month (700 credits)'
            else if (currentTier === 2000) tierName = '$20/month (1,400 credits)'
            else if (currentTier === 3000) tierName = '$30/month (2,100 credits)'
            else if (currentTier === 5000) tierName = '$50/month (3,500 credits)'
            else if (currentTier) tierName = `$${(currentTier / 100).toFixed(0)}/month`

            return NextResponse.json(
              { 
                error: 'You already have an active subscription',
                message: `You are currently subscribed to ${tierName}. Please cancel your existing subscription before subscribing to a new plan.`,
                currentPlan: tierName
              },
              { status: 400 }
            )
          }
        }
      } catch (error) {
        console.error('Error checking existing subscription:', error)
        // Continue with checkout if we can't check (don't block user)
      }
    }

    let lineItems: Stripe.Checkout.SessionCreateParams.LineItem[] = []
    if (!isCredits) {
      lineItems = [{ price: priceId, quantity }]
    } else {
      let canUseConfiguredPrice = false
      if (priceId) {
        try {
          const stripePrice = await stripe.prices.retrieve(priceId)
          canUseConfiguredPrice = !!(stripePrice?.active && stripePrice?.type === 'one_time')
        } catch {
          canUseConfiguredPrice = false
        }
      }

      if (canUseConfiguredPrice && priceId) {
        lineItems = [{ price: priceId, quantity }]
      } else {
        const fallback = CREDIT_PLAN_FALLBACK[String(requestedPlan || '')]
        if (!fallback) {
          return NextResponse.json(
            { error: 'Credit package not configured. Please try again shortly.' },
            { status: 400 },
          )
        }
        lineItems = [
          {
            quantity,
            price_data: {
              currency: 'usd',
              unit_amount: fallback.unitAmount,
              product_data: { name: fallback.title },
            },
          },
        ]
      }
    }

    const checkoutSession = await stripe.checkout.sessions.create({
      mode: isCredits ? 'payment' : 'subscription',
      line_items: lineItems,
      success_url: `${origin}/billing?checkout=success&session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${origin}/billing?checkout=cancelled`,
      customer_email: customerEmail,
      allow_promotion_codes: true,
      ...(!isCredits ? { payment_method_collection: 'always' } : {}),
      ...(Object.keys(baseMetadata).length ? { metadata: baseMetadata } : {}),
      ...(isCredits
        ? Object.keys(baseMetadata).length
          ? { payment_intent_data: { metadata: baseMetadata } }
          : {}
        : Object.keys(baseMetadata).length
          ? { subscription_data: { metadata: baseMetadata } }
          : {}),
      // No trial period - subscriptions start immediately
    })

    return NextResponse.json({ url: checkoutSession.url })
  } catch (error: any) {
    console.error('Error creating checkout session:', error)
    return NextResponse.json(
      {
        error: 'Failed to create checkout session',
        message: error?.message || 'Unknown checkout error',
      },
      { status: 500 },
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'
import { prisma } from '@/lib/prisma'
import Stripe from 'stripe'

async function getBillingEmail(req: NextRequest): Promise<string | null> {
  const session = await getServerSession(authOptions)
  const sessionEmail = String(session?.user?.email || '').trim().toLowerCase()
  if (sessionEmail) return sessionEmail

  const nativeUserId = await getUserIdFromNativeAuth(req)
  if (!nativeUserId) return null

  const user = await prisma.user.findUnique({
    where: { id: nativeUserId },
    select: { email: true },
  })
  return String(user?.email || '').trim().toLowerCase() || null
}

export async function POST(req: NextRequest) {
  try {
    const email = await getBillingEmail(req)
    if (!email) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const secretKey = process.env.STRIPE_SECRET_KEY
    if (!secretKey) {
      return NextResponse.json({ error: 'Stripe not configured' }, { status: 500 })
    }

    const stripe = new Stripe(secretKey, { apiVersion: '2024-06-20' })
    // Find Stripe customer by email
    const customers = await stripe.customers.list({ email, limit: 1 })
    if (!customers.data.length) {
      // User might have admin-granted subscription without Stripe customer
      // Return a helpful error message
      return NextResponse.json({ 
        error: 'No Stripe customer found',
        message: 'Your subscription was granted by an administrator. Please contact support to manage your subscription, or subscribe through Stripe to enable self-service management.'
      }, { status: 404 })
    }

    const customerId = customers.data[0].id
    const returnUrl = `${req.nextUrl.origin}/billing`

    const portalSession = await stripe.billingPortal.sessions.create({
      customer: customerId,
      return_url: returnUrl,
    })

    return NextResponse.json({ url: portalSession.url })
  } catch (error: any) {
    console.error('Error creating portal session:', error)
    return NextResponse.json({ 
      error: 'Failed to create portal session',
      details: error?.message || 'Unknown error',
      code: error?.code || 'NO_CODE'
    }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'

// Debug endpoint to check what's happening
export async function GET(request: NextRequest) {
  const debug: any = {
    timestamp: new Date().toISOString(),
    checks: []
  }

  try {
    // Check 1: Session
    const session = await getServerSession(authOptions)
    debug.checks.push({
      name: 'Session',
      status: session ? 'OK' : 'FAILED',
      email: session?.user?.email || 'N/A'
    })

    if (!session?.user?.email) {
      return NextResponse.json({ error: 'Unauthorized', debug }, { status: 401 })
    }

    // Check 2: Stripe Config
    const stripeKey = process.env.STRIPE_SECRET_KEY
    debug.checks.push({
      name: 'Stripe Config',
      status: stripeKey ? 'OK' : 'FAILED',
      keyPrefix: stripeKey ? stripeKey.substring(0, 10) + '...' : 'NOT SET'
    })

    // Check 3: User lookup
    let user
    try {
      user = await prisma.user.findUnique({
        where: { email: session.user.email.toLowerCase() },
        select: { id: true, email: true }
      })
      debug.checks.push({
        name: 'User Lookup',
        status: user ? 'OK' : 'NOT FOUND',
        userId: user?.id || 'N/A'
      })
    } catch (error: any) {
      debug.checks.push({
        name: 'User Lookup',
        status: 'ERROR',
        error: error?.message
      })
      return NextResponse.json({ error: 'User lookup failed', debug }, { status: 500 })
    }

    if (!user) {
      return NextResponse.json({ error: 'User not found', debug }, { status: 404 })
    }

    // Check 4: Subscription lookup
    let subscription
    try {
      subscription = await prisma.subscription.findFirst({
        where: { userId: user.id },
      })
      debug.checks.push({
        name: 'Subscription Lookup',
        status: subscription ? 'OK' : 'NOT FOUND',
        subscriptionId: subscription?.id || 'N/A',
        monthlyPriceCents: subscription?.monthlyPriceCents || 'N/A'
      })
    } catch (error: any) {
      debug.checks.push({
        name: 'Subscription Lookup',
        status: 'ERROR',
        error: error?.message,
        stack: error?.stack
      })
      return NextResponse.json({ error: 'Subscription lookup failed', debug }, { status: 500 })
    }

    // Check 5: Try to access stripeSubscriptionId
    try {
      const stripeId = (subscription as any)?.stripeSubscriptionId
      debug.checks.push({
        name: 'Stripe Subscription ID Access',
        status: 'OK',
        value: stripeId || 'NULL'
      })
    } catch (error: any) {
      debug.checks.push({
        name: 'Stripe Subscription ID Access',
        status: 'ERROR',
        error: error?.message
      })
    }

    return NextResponse.json({ 
      success: true,
      debug,
      subscription: subscription ? {
        id: subscription.id,
        monthlyPriceCents: subscription.monthlyPriceCents,
        stripeSubscriptionId: (subscription as any).stripeSubscriptionId || null
      } : null
    })
  } catch (error: any) {
    debug.checks.push({
      name: 'Overall Error',
      status: 'ERROR',
      error: error?.message,
      stack: error?.stack
    })
    return NextResponse.json({ error: 'Debug endpoint failed', debug }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import Stripe from 'stripe'
