import { createSign } from 'crypto'
import { authOptions } from '@/lib/auth'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'
import { prisma } from '@/lib/prisma'
import { ensureSubscriptionStoreColumns } from '@/lib/native-billing/subscription-store'

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || '', { apiVersion: '2024-06-20' })

function isMissingStripeSubscriptionError(error: any) {
  const code = String(error?.code || '').toLowerCase()
  const message = String(error?.message || '')
  return code === 'resource_missing' || /no such subscription/i.test(message)
}

async function clearStripeSubscriptionIdForUser(userId: string) {
  try {
    await prisma.$executeRawUnsafe(
      `UPDATE "Subscription" SET "stripeSubscriptionId" = NULL WHERE "userId" = $1`,
      userId,
    )
  } catch (error) {
    console.error('Error clearing stale stripeSubscriptionId:', error)
  }
}

async function getBillingUser(request: NextRequest) {
  const session = await getServerSession(authOptions)
  const sessionEmail = String(session?.user?.email || '').trim().toLowerCase()
  if (sessionEmail) {
    return prisma.user.findUnique({
      where: { email: sessionEmail },
      select: { id: true, email: true, name: true },
    })
  }

  const nativeUserId = await getUserIdFromNativeAuth(request)
  if (!nativeUserId) return null

  return prisma.user.findUnique({
    where: { id: nativeUserId },
    select: { id: true, email: true, name: true },
  })
}

type AppleApiCredentials = {
  issuerId: string
  keyId: string
  privateKey: string
  bundleId: string
}

type AppleSubscriptionState = {
  autoRenewStatus: number | null
  expiresDate: Date | null
}

function base64Url(input: string | Buffer): string {
  const raw = Buffer.isBuffer(input) ? input : Buffer.from(input)
  return raw
    .toString('base64')
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
}

function decodeBase64UrlJSON(value: string): any {
  const normalized = value.replace(/-/g, '+').replace(/_/g, '/')
  const padded = normalized + '='.repeat((4 - (normalized.length % 4)) % 4)
  return JSON.parse(Buffer.from(padded, 'base64').toString('utf8'))
}

function parseAppleJwsPayload(value: string): any {
  const parts = String(value || '').split('.')
  if (parts.length < 2) return null
  return decodeBase64UrlJSON(parts[1])
}

function getAppleApiCredentials(): AppleApiCredentials | null {
  const issuerId = String(process.env.APPLE_IAP_ISSUER_ID || '').trim()
  const keyId = String(process.env.APPLE_IAP_KEY_ID || '').trim()
  const privateKey = String(process.env.APPLE_IAP_PRIVATE_KEY || '').replace(/\\n/g, '\n').trim()
  const bundleId = String(process.env.APPLE_IAP_BUNDLE_ID || '').trim()
  if (!issuerId || !keyId || !privateKey || !bundleId) return null
  return { issuerId, keyId, privateKey, bundleId }
}

function createAppleAppStoreApiToken(credentials: AppleApiCredentials): string {
  const now = Math.floor(Date.now() / 1000)
  const unsignedToken = `${base64Url(JSON.stringify({
    alg: 'ES256',
    kid: credentials.keyId,
    typ: 'JWT',
  }))}.${base64Url(JSON.stringify({
    iss: credentials.issuerId,
    iat: now,
    exp: now + 60 * 5,
    aud: 'appstoreconnect-v1',
    bid: credentials.bundleId,
  }))}`
  const signer = createSign('SHA256')
  signer.update(unsignedToken)
  signer.end()
  const signature = signer.sign({ key: credentials.privateKey, dsaEncoding: 'ieee-p1363' })
  return `${unsignedToken}.${base64Url(signature)}`
}

async function fetchAppleSubscriptionState(subscription: any): Promise<AppleSubscriptionState | null> {
  const source = String(subscription?.source || '')
  const transactionId = String(subscription?.storeOriginalTransactionId || subscription?.storeTransactionId || '').trim()
  const storeProductId = String(subscription?.storeProductId || '').trim()
  if (source !== 'apple_iap' || !transactionId) return null

  const credentials = getAppleApiCredentials()
  if (!credentials) return null

  const token = createAppleAppStoreApiToken(credentials)
  const encodedTransactionId = encodeURIComponent(transactionId)
  const urls = [
    `https://api.storekit.itunes.apple.com/inApps/v1/subscriptions/${encodedTransactionId}`,
    `https://api.storekit.apple.com/inApps/v1/subscriptions/${encodedTransactionId}`,
    `https://api.storekit-sandbox.itunes.apple.com/inApps/v1/subscriptions/${encodedTransactionId}`,
    `https://api.storekit-sandbox.apple.com/inApps/v1/subscriptions/${encodedTransactionId}`,
  ]

  for (const url of urls) {
    let res: Response
    let data: any
    try {
      res = await fetch(url, { headers: { authorization: `Bearer ${token}` } })
      data = await res.json().catch(() => ({}))
    } catch (error: any) {
      console.warn('Apple subscription status request failed:', {
        host: new URL(url).host,
        message: error?.message || 'request failed',
      })
      continue
    }
    if (!res.ok) {
      console.warn('Apple subscription status returned non-OK:', {
        host: new URL(url).host,
        status: res.status,
        errorCode: data?.errorCode || null,
      })
      continue
    }

    const groups = Array.isArray(data?.data) ? data.data : []
    const transactions = groups.flatMap((group: any) =>
      Array.isArray(group?.lastTransactions) ? group.lastTransactions : [],
    )

    const candidates = transactions
      .map((item: any) => {
        const transactionInfo = parseAppleJwsPayload(String(item?.signedTransactionInfo || '')) || {}
        const renewalInfo = parseAppleJwsPayload(String(item?.signedRenewalInfo || '')) || {}
        return {
          status: Number(item?.status || item?.rawStatus || 0) || null,
          productId: String(transactionInfo?.productId || renewalInfo?.productId || ''),
          expiresDateMs: Number(transactionInfo?.expiresDate || 0),
          autoRenewStatus:
            renewalInfo?.autoRenewStatus === 0 || renewalInfo?.autoRenewStatus === 1
              ? Number(renewalInfo.autoRenewStatus)
              : null,
        }
      })
      .filter((item: any) => !storeProductId || item.productId === storeProductId)
      .sort((a: any, b: any) => Number(b.expiresDateMs || 0) - Number(a.expiresDateMs || 0))

    const current = candidates[0]
    if (!current) continue

    const expiresDate =
      Number.isFinite(current.expiresDateMs) && current.expiresDateMs > 0
        ? new Date(current.expiresDateMs)
        : null

    return {
      autoRenewStatus: current.autoRenewStatus,
      expiresDate,
    }
  }

  return null
}

// GET /api/billing/subscription - Get current subscription status
export async function GET(request: NextRequest) {
  try {
    const authUser = await getBillingUser(request)
    if (!authUser?.email) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    // Check Stripe configuration
    const stripeSecretKey = process.env.STRIPE_SECRET_KEY
    if (!stripeSecretKey) {
      console.error('STRIPE_SECRET_KEY is not set')
      return NextResponse.json({ 
        error: 'Stripe not configured',
        details: 'STRIPE_SECRET_KEY environment variable is missing'
      }, { status: 500 })
    }

    // Fetch user and subscription separately to avoid Prisma client issues
    let user
    try {
      user = authUser
    } catch (error) {
      console.error('Error fetching user:', error)
      return NextResponse.json({ 
        error: 'Database error',
        details: error instanceof Error ? error.message : 'Unknown error'
      }, { status: 500 })
    }

    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    // Fetch subscription using raw SQL to avoid Prisma schema issues with stripeSubscriptionId column
    let subscription
    try {
      await ensureSubscriptionStoreColumns()
      const subscriptionResult: any[] = await prisma.$queryRawUnsafe(
        `SELECT id, "userId", plan, "monthlyPriceCents", "startDate", "endDate",
                source, "storeProductId", "storeTransactionId", "storeOriginalTransactionId"
         FROM "Subscription"
         WHERE "userId" = $1
         LIMIT 1`,
        user.id
      )
      subscription = subscriptionResult && subscriptionResult.length > 0 ? subscriptionResult[0] : null

      // Try to get stripeSubscriptionId separately if column exists
      if (subscription) {
        try {
          const stripeIdResult: any[] = await prisma.$queryRawUnsafe(
            `SELECT "stripeSubscriptionId" FROM "Subscription" WHERE "userId" = $1 LIMIT 1`,
            user.id
          )
          if (stripeIdResult && stripeIdResult.length > 0) {
            subscription.stripeSubscriptionId = stripeIdResult[0].stripeSubscriptionId || null
          } else {
            subscription.stripeSubscriptionId = null
          }
        } catch {
          // Column doesn't exist, set to null
          subscription.stripeSubscriptionId = null
        }
      }
    } catch (error: any) {
      console.error('Error fetching subscription:', error)
      return NextResponse.json({ 
        error: 'Database error',
        details: error?.message || 'Unknown error'
      }, { status: 500 })
    }

    if (!subscription) {
      return NextResponse.json({ 
        hasSubscription: false,
        subscription: null
      })
    }

    let appleSubscriptionState: AppleSubscriptionState | null = null
    try {
      appleSubscriptionState = await fetchAppleSubscriptionState(subscription)
      if (appleSubscriptionState?.expiresDate) {
        subscription.endDate = appleSubscriptionState.expiresDate
        await prisma.$executeRawUnsafe(
          `UPDATE "Subscription" SET "endDate" = $1 WHERE "userId" = $2`,
          appleSubscriptionState.expiresDate,
          user.id,
        )
      }
    } catch (error: any) {
      console.error('Error fetching Apple subscription status:', error?.message || error)
    }

    // Check if subscription is active
    const now = new Date()
    const endDate = subscription.endDate ? new Date(subscription.endDate) : null
    const isActive = !endDate || endDate > now
    const appleCancelAtPeriodEnd = appleSubscriptionState?.autoRenewStatus === 0

    // Get Stripe subscription details if available
    let stripeSubscription = null
    // Safely access stripeSubscriptionId field (may not exist in Prisma types yet)
    let stripeSubscriptionId = (subscription as any).stripeSubscriptionId || null

    if (stripeSubscriptionId) {
      try {
        stripeSubscription = await stripe.subscriptions.retrieve(stripeSubscriptionId)
      } catch (error: any) {
        console.error('Error fetching Stripe subscription:', error?.message || error)
        if (isMissingStripeSubscriptionError(error)) {
          await clearStripeSubscriptionIdForUser(user.id)
          stripeSubscriptionId = null
        }
      }
    } else {
      // Try to find Stripe subscription by customer email
      try {
        const customers = await stripe.customers.list({
          email: user.email.toLowerCase(),
          limit: 1
        })

        if (customers.data.length > 0) {
          const customer = customers.data[0]
          const subscriptions = await stripe.subscriptions.list({
            customer: customer.id,
            status: 'all',
            limit: 1
          })

          if (subscriptions.data.length > 0) {
            stripeSubscription = subscriptions.data[0]
            // Update database with Stripe subscription ID (only if column exists) - use raw SQL
            try {
              await prisma.$executeRawUnsafe(
                `UPDATE "Subscription" SET "stripeSubscriptionId" = $1, source = 'stripe' WHERE "userId" = $2`,
                stripeSubscription.id,
                user.id
              )
            } catch (updateError: any) {
              console.error('Error updating stripeSubscriptionId:', updateError?.message || updateError)
              // Continue without updating - column might not exist yet
            }
          }
        }
      } catch (error: any) {
        console.error('Error finding Stripe subscription by email:', error?.message || error)
        // Continue without Stripe data - user might not have Stripe customer yet
      }
    }

    const currentPeriodEnd =
      stripeSubscription?.current_period_end
        ? new Date(stripeSubscription.current_period_end * 1000).toISOString()
        : endDate
          ? endDate.toISOString()
          : null

    // Determine plan tier name
    const currentTier = subscription.monthlyPriceCents
    let tierName = 'Premium'
    let credits = 0

    const subscriptionCreditsMap: Record<number, number> = {
      1000: 700,  // $10/month → 700 credits
      2000: 1400, // $20/month → 1,400 credits
      3000: 2100, // $30/month → 2,100 credits
      5000: 3500, // $50/month → 3,500 credits
    }

    if (currentTier && subscriptionCreditsMap[currentTier]) {
      tierName = `$${(currentTier / 100).toFixed(0)}/month`
      credits = subscriptionCreditsMap[currentTier]
    } else if (currentTier) {
      tierName = `$${(currentTier / 100).toFixed(0)}/month`
      // Estimate credits based on price (rough approximation)
      credits = Math.round(currentTier / 2) // $1 = ~50 credits
    } else {
      // Default for admin-granted subscriptions without price set
      tierName = 'Premium'
      credits = 1000 // Default estimate
    }

    return NextResponse.json({
      hasSubscription: true,
      isActive,
      subscription: {
        id: subscription.id,
        plan: subscription.plan,
        tier: tierName,
        credits,
        monthlyPriceCents: subscription.monthlyPriceCents,
        startDate: subscription.startDate?.toISOString() || subscription.startDate,
        endDate: subscription.endDate?.toISOString() || subscription.endDate || null,
        stripeSubscriptionId,
        source: subscription.source || (stripeSubscriptionId ? 'stripe' : null),
        storeProductId: subscription.storeProductId || null,
        storeTransactionId: subscription.storeTransactionId || null,
        storeOriginalTransactionId: subscription.storeOriginalTransactionId || null,
        stripeStatus: stripeSubscription?.status,
        stripeCancelAtPeriodEnd: Boolean(stripeSubscription?.cancel_at_period_end || appleCancelAtPeriodEnd),
        stripeCurrentPeriodEnd: currentPeriodEnd,
        storeCancelAtPeriodEnd: appleCancelAtPeriodEnd,
        storeAutoRenewStatus: appleSubscriptionState?.autoRenewStatus ?? null,
        isStripeManaged: !!stripeSubscription
      }
    })
  } catch (error: any) {
    console.error('Error fetching subscription:', error)
    console.error('Error details:', {
      message: error?.message,
      stack: error?.stack,
      name: error?.name,
      code: error?.code
    })

    // Always return detailed error to help diagnose (we can remove later)
    return NextResponse.json({ 
      error: 'Failed to fetch subscription',
      details: {
        message: error?.message || 'Unknown error',
        name: error?.name || 'Error',
        code: error?.code || 'NO_CODE',
        stack: error?.stack ? error.stack.split('\n').slice(0, 5).join('\n') : 'No stack trace'
      }
    }, { status: 500 })
  }
}

// POST /api/billing/subscription - Cancel, upgrade, or downgrade subscription
export async function POST(request: NextRequest) {
  try {
    const user = await getBillingUser(request)
    if (!user?.email) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const body = await request.json()
    const { action, newPlan } = body // action: 'cancel' | 'upgrade' | 'downgrade', newPlan: 'plan_20_monthly' | etc.

    // Fetch subscription using raw SQL to avoid Prisma schema issues
    let dbSubscription
    try {
      await ensureSubscriptionStoreColumns()
      const subscriptionResult: any[] = await prisma.$queryRawUnsafe(
        `SELECT id, "userId", plan, "monthlyPriceCents", "startDate", "endDate",
                source, "storeProductId", "storeTransactionId", "storeOriginalTransactionId"
         FROM "Subscription"
         WHERE "userId" = $1
         LIMIT 1`,
        user.id
      )
      dbSubscription = subscriptionResult && subscriptionResult.length > 0 ? subscriptionResult[0] : null

      // Try to get stripeSubscriptionId separately if column exists
      if (dbSubscription) {
        try {
          const stripeIdResult: any[] = await prisma.$queryRawUnsafe(
            `SELECT "stripeSubscriptionId" FROM "Subscription" WHERE "userId" = $1 LIMIT 1`,
            user.id
          )
          if (stripeIdResult && stripeIdResult.length > 0) {
            dbSubscription.stripeSubscriptionId = stripeIdResult[0].stripeSubscriptionId || null
          } else {
            dbSubscription.stripeSubscriptionId = null
          }
        } catch {
          // Column doesn't exist, set to null
          dbSubscription.stripeSubscriptionId = null
        }
      }
    } catch (error: any) {
      console.error('Error fetching subscription:', error)
      return NextResponse.json({ 
        error: 'Database error',
        message: error?.message || 'Failed to fetch subscription'
      }, { status: 500 })
    }

    if (!dbSubscription) {
      return NextResponse.json({ error: 'No active subscription found' }, { status: 400 })
    }

    // Find or get Stripe subscription
    let stripeSubscriptionId = dbSubscription.stripeSubscriptionId || null

    if (!stripeSubscriptionId) {
      // Try to find by customer email
      try {
        const customers = await stripe.customers.list({
          email: user.email.toLowerCase(),
          limit: 1
        })

        if (customers.data.length > 0) {
          const customer = customers.data[0]
          const subscriptions = await stripe.subscriptions.list({
            customer: customer.id,
            status: 'active',
            limit: 1
          })

          if (subscriptions.data.length > 0) {
            stripeSubscriptionId = subscriptions.data[0].id
            // Update database (only if column exists) - use raw SQL
            try {
              await prisma.$executeRawUnsafe(
                `UPDATE "Subscription" SET "stripeSubscriptionId" = $1, source = 'stripe' WHERE "userId" = $2`,
                stripeSubscriptionId,
                user.id
              )
            } catch (updateError) {
              console.error('Error updating stripeSubscriptionId (column may not exist yet):', updateError)
              // Continue without updating
            }
          }
        }
      } catch (error) {
        console.error('Error finding Stripe subscription:', error)
      }
    }

    if (action === 'cancel') {
      if (stripeSubscriptionId) {
        try {
          // Cancel Stripe subscription at period end
          const updatedSubscription = await stripe.subscriptions.update(stripeSubscriptionId, {
            cancel_at_period_end: true
          })

          // Get the actual cancellation date (current_period_end)
          const cancellationDate = updatedSubscription.current_period_end 
            ? new Date(updatedSubscription.current_period_end * 1000)
            : null

          return NextResponse.json({ 
            success: true,
            message: 'Subscription will be canceled at the end of the current billing period',
            cancellationDate: cancellationDate?.toISOString() || null
          })
        } catch (error: any) {
          if (!isMissingStripeSubscriptionError(error)) throw error
          await clearStripeSubscriptionIdForUser(user.id)
          stripeSubscriptionId = null
        }
      }

      // Admin-granted subscription - set endDate to end of current period
      const startDate = dbSubscription.startDate ? new Date(dbSubscription.startDate) : new Date()
      const endDate = new Date(startDate)
      endDate.setMonth(endDate.getMonth() + 1) // Cancel at end of current month

      // Use raw SQL to update endDate
      await prisma.$executeRawUnsafe(
        `UPDATE "Subscription" SET "endDate" = $1 WHERE "userId" = $2`,
        endDate,
        user.id
      )

      return NextResponse.json({ 
        success: true,
        message: 'Subscription will be canceled at the end of the current billing period',
        cancellationDate: endDate.toISOString()
      })
    } else if (action === 'upgrade' || action === 'downgrade') {
      if (!newPlan) {
        return NextResponse.json({ error: 'New plan required for upgrade/downgrade' }, { status: 400 })
      }

      const PLAN_TO_PRICE: Record<string, string | undefined> = {
        plan_10_monthly: process.env.STRIPE_PRICE_10_MONTHLY,
        plan_20_monthly: process.env.STRIPE_PRICE_20_MONTHLY,
        plan_30_monthly: process.env.STRIPE_PRICE_30_MONTHLY,
        plan_50_monthly: process.env.STRIPE_PRICE_50_MONTHLY,
      }

      const newPriceId = PLAN_TO_PRICE[newPlan]
      if (!newPriceId) {
        return NextResponse.json({ error: 'Invalid plan' }, { status: 400 })
      }

      if (stripeSubscriptionId) {
        try {
          // Update Stripe subscription
          const stripeSub = await stripe.subscriptions.retrieve(stripeSubscriptionId)
          const currentPriceId = stripeSub.items.data[0]?.price?.id

          if (currentPriceId === newPriceId) {
            return NextResponse.json({ error: 'You are already on this plan' }, { status: 400 })
          }

          // Update subscription to new price
          await stripe.subscriptions.update(stripeSubscriptionId, {
            items: [{
              id: stripeSub.items.data[0].id,
              price: newPriceId,
            }],
            proration_behavior: 'always_invoice', // Prorate the difference
          })

          // Determine new tier
          let newPriceCents = 2000
          if (newPlan === 'plan_10_monthly') newPriceCents = 1000
          else if (newPlan === 'plan_20_monthly') newPriceCents = 2000
          else if (newPlan === 'plan_30_monthly') newPriceCents = 3000
          else if (newPlan === 'plan_50_monthly') newPriceCents = 5000

          // Update database using raw SQL
          await prisma.$executeRawUnsafe(
            `UPDATE "Subscription" SET "monthlyPriceCents" = $1 WHERE "userId" = $2`,
            newPriceCents,
            user.id
          )

          return NextResponse.json({ 
            success: true,
            message: `Subscription ${action === 'upgrade' ? 'upgraded' : 'downgraded'} successfully`
          })
        } catch (error: any) {
          if (!isMissingStripeSubscriptionError(error)) throw error
          await clearStripeSubscriptionIdForUser(user.id)
          stripeSubscriptionId = null
        }
      }

      // Admin-granted subscription - update database only
      let newPriceCents = 2000
      if (newPlan === 'plan_10_monthly') newPriceCents = 1000
      else if (newPlan === 'plan_20_monthly') newPriceCents = 2000
      else if (newPlan === 'plan_30_monthly') newPriceCents = 3000
      else if (newPlan === 'plan_50_monthly') newPriceCents = 5000

      // Update database using raw SQL
      await prisma.$executeRawUnsafe(
        `UPDATE "Subscription" SET "monthlyPriceCents" = $1 WHERE "userId" = $2`,
        newPriceCents,
        user.id
      )

      return NextResponse.json({ 
        success: true,
        message: `Subscription ${action === 'upgrade' ? 'upgraded' : 'downgraded'} successfully`
      })
    } else {
      return NextResponse.json({ error: 'Invalid action' }, { status: 400 })
    }
  } catch (error: any) {
    console.error('Error managing subscription:', error)
    return NextResponse.json({ 
      error: 'Failed to manage subscription',
      message: error?.message || 'Unknown error occurred',
      details: error?.code || 'NO_CODE'
    }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import Stripe from 'stripe'
import { prisma } from '@/lib/prisma'
import { Resend } from 'resend'
import { notifyOwner } from '@/lib/owner-notifications'
import { getEmailFooter } from '@/lib/email-footer'
import { reportCriticalError } from '@/lib/error-reporter'
import {
  sendPractitionerPaymentFailedEmail,
  sendPractitionerSubscriptionCanceledEmail,
  sendPractitionerBoostReceiptEmail,
} from '@/lib/practitioner-emails'

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || '', { apiVersion: '2024-06-20' })
const resend = process.env.RESEND_API_KEY ? new Resend(process.env.RESEND_API_KEY) : null
const endpointSecret = process.env.STRIPE_WEBHOOK_SECRET || ''
const SUBSCRIBER_MILESTONE_INTERVAL = 20

async function getBalanceTransactionForPaymentIntent(paymentIntentId: string) {
  const pi = await stripe.paymentIntents.retrieve(paymentIntentId, {
    expand: ['latest_charge.balance_transaction', 'charges.data.balance_transaction'],
  })
  let charge = (pi as any)?.latest_charge as Stripe.Charge | undefined
  if (typeof (pi as any)?.latest_charge === 'string') {
    charge = await stripe.charges.retrieve(String((pi as any).latest_charge), {
      expand: ['balance_transaction'],
    })
  }
  if (!charge) {
    charge = (pi as any)?.charges?.data?.[0] as Stripe.Charge | undefined
  }
  const balanceTx = (charge as any)?.balance_transaction as Stripe.BalanceTransaction | undefined
  return { charge, balanceTx }
}

function isStripeSubscriptionActive(subscription: Stripe.Subscription): boolean {
  return subscription.status === 'active' || subscription.status === 'trialing'
}

async function findCheckoutSessionForPaymentIntent(paymentIntentId: string): Promise<Stripe.Checkout.Session | null> {
  try {
    const sessions = await stripe.checkout.sessions.list({
      payment_intent: paymentIntentId,
      limit: 1,
    })
    return sessions.data[0] ?? null
  } catch {
    return null
  }
}

function addDays(date: Date, days: number): Date {
  const d = new Date(date)
  d.setUTCDate(d.getUTCDate() + days)
  return d
}

async function updatePractitionerSubscriptionFromStripe(sub: Stripe.Subscription) {
  const listingId = (sub.metadata as any)?.helfi_listing_id
  if (!listingId) return false

  const listing = await prisma.practitionerListing.findUnique({
    where: { id: String(listingId) },
    include: { practitionerAccount: true },
  })
  if (!listing) return true

  const currentPeriodStart = sub.current_period_start ? new Date(sub.current_period_start * 1000) : null
  const currentPeriodEnd = sub.current_period_end ? new Date(sub.current_period_end * 1000) : null
  const trialStartAt = sub.trial_start ? new Date(sub.trial_start * 1000) : null
  const trialEndAt = sub.trial_end ? new Date(sub.trial_end * 1000) : null

  const normalizedStatus = (() => {
    switch (sub.status) {
      case 'active':
        return 'ACTIVE'
      case 'trialing':
        return 'TRIALING'
      case 'past_due':
        return 'PAST_DUE'
      case 'canceled':
        return 'CANCELED'
      case 'incomplete':
        return 'INCOMPLETE'
      case 'unpaid':
        return 'EXPIRED'
      default:
        return 'EXPIRED'
    }
  })()

  await prisma.practitionerListingSubscription.upsert({
    where: { listingId: listing.id },
    create: {
      listingId: listing.id,
      provider: 'STRIPE',
      providerCustomerId: typeof sub.customer === 'string' ? sub.customer : sub.customer?.id,
      providerSubscriptionId: sub.id,
      plan: 'LISTING_4_95',
      trialStartAt,
      trialEndAt,
      currentPeriodStart,
      currentPeriodEnd,
      status: normalizedStatus as any,
      cancelAtPeriodEnd: sub.cancel_at_period_end || false,
    },
    update: {
      providerCustomerId: typeof sub.customer === 'string' ? sub.customer : sub.customer?.id,
      providerSubscriptionId: sub.id,
      trialStartAt,
      trialEndAt,
      currentPeriodStart,
      currentPeriodEnd,
      status: normalizedStatus as any,
      cancelAtPeriodEnd: sub.cancel_at_period_end || false,
    },
  })

  const isActive = sub.status === 'active' || sub.status === 'trialing'
  if (isActive && listing.reviewStatus === 'APPROVED') {
    await prisma.practitionerListing.update({
      where: { id: listing.id },
      data: { status: 'ACTIVE', visibilityReason: 'SUB_ACTIVE' },
    })
  }

  if (!isActive) {
    const visibilityReason = sub.status === 'past_due' ? 'PAYMENT_FAILED' : 'SUB_LAPSED'
    await prisma.practitionerListing.update({
      where: { id: listing.id },
      data: { status: 'HIDDEN', visibilityReason },
    })
  }

  if (sub.cancel_at_period_end && listing.practitionerAccount) {
    const existing = await prisma.practitionerEmailLog.findFirst({
      where: { listingId: listing.id, type: 'SUB_CANCELED' },
      select: { id: true },
    })
    if (!existing) {
      sendPractitionerSubscriptionCanceledEmail({
        practitionerAccountId: listing.practitionerAccountId,
        listingId: listing.id,
        toEmail: listing.practitionerAccount.contactEmail,
        displayName: listing.displayName,
      }).catch((error) => {
        console.error('❌ Practitioner cancel email failed (non-blocking):', error)
      })
    }
  }

  return true
}

async function ensureSubscriberMilestonesTable() {
  await prisma.$executeRawUnsafe(`
    CREATE TABLE IF NOT EXISTS SubscriberMilestones (
      id TEXT PRIMARY KEY,
      total_count INT NOT NULL DEFAULT 0,
      last_notified_count INT NOT NULL DEFAULT 0,
      updated_at TIMESTAMP NOT NULL DEFAULT NOW()
    )
  `)

  await prisma.$executeRawUnsafe(`
    INSERT INTO SubscriberMilestones (id, total_count, last_notified_count)
    VALUES ('global', 0, 0)
    ON CONFLICT (id) DO NOTHING
  `)
}

async function incrementSubscriberMilestoneCounter(): Promise<{
  totalCount: number
  shouldNotify: boolean
}> {
  await ensureSubscriberMilestonesTable()

  return prisma.$transaction(async (tx) => {
    const rows = await tx.$queryRawUnsafe<
      Array<{ total_count: number; last_notified_count: number }>
    >(`SELECT total_count, last_notified_count FROM SubscriberMilestones WHERE id = 'global' FOR UPDATE`)
    const currentCount = rows[0]?.total_count ?? 0
    const lastNotified = rows[0]?.last_notified_count ?? 0
    const totalCount = currentCount + 1
    const shouldNotify =
      totalCount % SUBSCRIBER_MILESTONE_INTERVAL === 0 && totalCount > lastNotified
    const nextNotified = shouldNotify ? totalCount : lastNotified

    await tx.$executeRawUnsafe(
      `UPDATE SubscriberMilestones
       SET total_count = $1, last_notified_count = $2, updated_at = NOW()
       WHERE id = 'global'`,
      totalCount,
      nextNotified
    )

    return { totalCount, shouldNotify }
  })
}

async function sendSubscriberMilestoneEmail(options: {
  recipientEmail: string
  totalCount: number
  latestSubscriberEmail: string
}) {
  if (!resend) {
    console.log('📧 Resend API not configured, skipping subscriber milestone email')
    return
  }

  const { recipientEmail, totalCount, latestSubscriberEmail } = options
  const subject = `Helfi milestone reached: ${totalCount} paid subscribers`
  const html = `
    <div style="font-family: Arial, sans-serif; line-height: 1.5; color: #111827;">
      <h2 style="margin: 0 0 16px 0;">Subscriber milestone reached</h2>
      <p style="margin: 0 0 8px 0;"><strong>Total paid subscribers:</strong> ${totalCount}</p>
      <p style="margin: 0 0 16px 0;"><strong>Latest subscriber:</strong> ${latestSubscriberEmail}</p>
      <p style="margin: 0 0 16px 0;">You asked to be notified every ${SUBSCRIBER_MILESTONE_INTERVAL} new subscribers.</p>
      ${getEmailFooter({
        recipientEmail,
        emailType: 'admin',
        reasonText: 'You received this email because you requested subscriber milestone alerts.'
      })}
    </div>
  `

  const emailResponse = await resend.emails.send({
    from: 'Helfi Alerts <support@helfi.ai>',
    to: recipientEmail,
    subject,
    html,
  })

  console.log(`✅ [SUBSCRIBER MILESTONE] Sent to ${recipientEmail} with ID: ${emailResponse.data?.id}`)
}

export async function POST(request: NextRequest) {
  const sig = request.headers.get('stripe-signature') || ''
  const rawBody = await request.text()

  let event: Stripe.Event
  try {
    event = stripe.webhooks.constructEvent(rawBody, sig, endpointSecret)
  } catch (err) {
    return NextResponse.json({ error: 'Invalid signature' }, { status: 400 })
  }

  try {
    switch (event.type) {
      case 'customer.subscription.created':
      case 'customer.subscription.updated': {
        const sub = event.data.object as Stripe.Subscription
        const handledListing = await updatePractitionerSubscriptionFromStripe(sub)
        if (handledListing) break

        const currentPeriodStart = sub.current_period_start
          ? new Date(sub.current_period_start * 1000)
          : new Date()
        const currentPeriodEnd = sub.current_period_end
          ? new Date(sub.current_period_end * 1000)
          : null
        // Get customer email via customer ID
        const customerId = typeof sub.customer === 'string' ? sub.customer : sub.customer?.id
        let email: string | undefined
        if (customerId) {
          try {
            const customer = await stripe.customers.retrieve(customerId)
            if ((customer as Stripe.Customer).email) {
              email = (customer as Stripe.Customer).email as string
            }
          } catch {
            // ignore customer fetch errors
          }
        }
        if (!email) break

        // Determine monthly price from subscription
        const amountCents = sub.items.data[0]?.price?.unit_amount || 0

        // Check if subscription already exists and if tier is changing
        const existingUser = await prisma.user.findUnique({
          where: { email: email.toLowerCase() },
          include: { subscription: true }
        })

        const isActive = isStripeSubscriptionActive(sub)
        if (!isActive) {
          if (existingUser?.subscription) {
            await prisma.subscription.update({
              where: { userId: existingUser.id },
              data: {
                stripeSubscriptionId: sub.id,
                monthlyPriceCents: amountCents,
                endDate: new Date(),
              },
            })
          }
          console.log(`[Webhook] Subscription ${sub.id} for ${email} is ${sub.status}. Access paused.`)
          break
        }

        const existingSub = existingUser?.subscription
        const isNewSubscription = !existingSub
        const isTierChange = existingSub && existingSub.monthlyPriceCents !== amountCents
        // Also reset if switching from admin-granted (no stripeSubscriptionId) to Stripe-managed subscription
        // This is critical: if subscription exists but doesn't have stripeSubscriptionId, and we're adding one, reset everything
        const isSwitchingToStripe = existingSub && !existingSub.stripeSubscriptionId
        const hasNewStripeId = !existingSub?.stripeSubscriptionId || existingSub.stripeSubscriptionId !== sub.id

        // If tier is changing, new subscription, or switching to Stripe, reset startDate to start new billing cycle
        const shouldResetCredits = isNewSubscription || isTierChange || isSwitchingToStripe || hasNewStripeId
        // Always align startDate/reset to Stripe period start when switching to Stripe or creating new subscription
        const newStartDate = shouldResetCredits ? currentPeriodStart : (existingSub?.startDate || currentPeriodStart)

        // Log for debugging
        console.log(`[Webhook] Subscription ${sub.id} for ${email}:`, {
          isNewSubscription,
          isTierChange,
          isSwitchingToStripe,
          hasNewStripeId,
          shouldResetCredits,
          existingStripeId: existingSub?.stripeSubscriptionId,
          newStripeId: sub.id,
          existingStartDate: existingSub?.startDate,
          newStartDate,
          currentPeriodStart,
          currentPeriodEnd
        })

        // Set plan to PREMIUM and store Stripe subscription ID
        // IMPORTANT: Always update startDate when switching to Stripe, even if using upsert
        // Use direct update if subscription exists to ensure startDate is always updated when switching to Stripe
        let user
        if (existingSub) {
          // Subscription exists - update it directly to ensure startDate is always set correctly
          await prisma.subscription.update({
            where: { userId: existingUser.id },
            data: {
              plan: 'PREMIUM',
              monthlyPriceCents: amountCents,
              stripeSubscriptionId: sub.id,
              startDate: newStartDate, // Always update startDate when switching to Stripe
              endDate: currentPeriodEnd
            }
          })
          // Fetch updated user with subscription
          user = await prisma.user.findUnique({
            where: { email: email.toLowerCase() },
            include: { subscription: true }
          })
        } else {
          // New subscription - use upsert create
          user = await prisma.user.update({
            where: { email: email.toLowerCase() },
            data: {
              subscription: { 
                create: { 
                  plan: 'PREMIUM',
                  monthlyPriceCents: amountCents,
                  stripeSubscriptionId: sub.id,
                  startDate: newStartDate,
                  endDate: currentPeriodEnd
                }
              },
            },
            include: { subscription: true }
          })
        }

        if (!user) {
          console.error(`[Webhook] Failed to update user ${email} after subscription update`)
          break
        }

        // Reset monthly counters and wallet when starting new subscription cycle or changing tier
        if (shouldResetCredits) {
          console.log(`[Webhook] Resetting credits for user ${user.id} - switching to Stripe or new subscription`, {
            walletResetAt: newStartDate
          })
          await prisma.user.update({
            where: { id: user.id },
            data: {
              dailyAnalysisCredits: 30,
              walletMonthlyUsedCents: 0,
              walletMonthlyResetAt: newStartDate,
              monthlySymptomAnalysisUsed: 0,
              monthlyFoodAnalysisUsed: 0,
              monthlyMedicalImageAnalysisUsed: 0,
              monthlyInteractionAnalysisUsed: 0,
              monthlyInsightsGenerationUsed: 0,
            } as any
          })
        }

        if (isNewSubscription) {
          let milestoneResult: { totalCount: number; shouldNotify: boolean } | null = null
          try {
            milestoneResult = await incrementSubscriberMilestoneCounter()
          } catch (error) {
            console.error('❌ Subscriber milestone counter failed:', error)
          }
          if (milestoneResult?.shouldNotify) {
            const milestoneRecipient =
              (process.env.OWNER_EMAIL || 'louie@helfi.ai').trim() || 'louie@helfi.ai'
            sendSubscriberMilestoneEmail({
              recipientEmail: milestoneRecipient,
              totalCount: milestoneResult.totalCount,
              latestSubscriberEmail: email,
            }).catch((error) => {
              console.error('❌ Subscriber milestone email failed (non-blocking):', error)
            })
          }
        }

        // Notify owner of subscription purchase (don't await to avoid blocking webhook)
        const currency = sub.currency?.toUpperCase() || 'USD'
        const planName = `Premium (${currency === 'USD' ? '$' : ''}${(amountCents / 100).toFixed(0)}/month)`

        notifyOwner({
          event: 'subscription',
          userEmail: email,
          userName: user.name || undefined,
          amount: amountCents,
          currency: currency,
          planName: planName,
        }).catch(error => {
          console.error('❌ Owner notification failed (non-blocking):', error)
        })

        break
      }
      case 'customer.subscription.trial_will_end': {
        // Trial periods removed - this event can be ignored
        break
      }
      case 'customer.subscription.deleted': {
        const sub = event.data.object as Stripe.Subscription
        const listingId = (sub.metadata as any)?.helfi_listing_id
        if (listingId) {
          await updatePractitionerSubscriptionFromStripe(sub)
          const listing = await prisma.practitionerListing.findUnique({
            where: { id: String(listingId) },
            include: { practitionerAccount: true },
          })
          if (listing) {
            const existing = await prisma.practitionerEmailLog.findFirst({
              where: { listingId: listing.id, type: 'SUB_CANCELED' },
              select: { id: true },
            })
            if (!existing) {
              sendPractitionerSubscriptionCanceledEmail({
                practitionerAccountId: listing.practitionerAccountId,
                listingId: listing.id,
                toEmail: listing.practitionerAccount.contactEmail,
                displayName: listing.displayName,
              }).catch((error) => {
                console.error('❌ Practitioner cancel email failed (non-blocking):', error)
              })
            }
          }
          break
        }
        const customerId = typeof sub.customer === 'string' ? sub.customer : sub.customer?.id
        let email: string | undefined
        if (customerId) {
          try {
            const customer = await stripe.customers.retrieve(customerId)
            if ((customer as Stripe.Customer).email) {
              email = (customer as Stripe.Customer).email as string
            }
          } catch {}
        }
        if (email) {
          // Delete subscription instead of setting to FREE
          // First find the user by email to get userId
          const user = await prisma.user.findUnique({
            where: { email: email.toLowerCase() },
            select: { id: true }
          })

          if (user) {
            await prisma.subscription.delete({
              where: { userId: user.id }
            }).catch(() => {
              // Ignore if subscription doesn't exist
            })
          }
        }
        break
      }
      case 'account.updated': {
        const acct = event.data.object as Stripe.Account
        const accountId = acct.id
        await prisma.affiliate
          .update({
            where: { stripeConnectAccountId: accountId },
            data: {
              stripeConnectDetailsSubmitted: !!acct.details_submitted,
              stripeConnectChargesEnabled: !!acct.charges_enabled,
              stripeConnectPayoutsEnabled: !!acct.payouts_enabled,
              stripeConnectOnboardedAt: acct.details_submitted ? new Date() : undefined,
            },
          })
          .catch(() => {})
        break
      }
      case 'invoice.paid': {
        const invoice = event.data.object as Stripe.Invoice

        // Only pay commission on the initial subscription payment (first invoice)
        if (invoice.billing_reason !== 'subscription_create') break

        const subscriptionId = typeof invoice.subscription === 'string' ? invoice.subscription : invoice.subscription?.id
        if (!subscriptionId) break

        const subscription = await stripe.subscriptions.retrieve(subscriptionId)
        const affCode = (subscription.metadata as any)?.helfi_aff_code || (invoice.metadata as any)?.helfi_aff_code
        const affClickId = (subscription.metadata as any)?.helfi_aff_click || (invoice.metadata as any)?.helfi_aff_click

        if (!affCode || !affClickId) break

        const affiliate = await prisma.affiliate.findUnique({
          where: { code: String(affCode).toLowerCase() },
          select: { id: true, status: true, userId: true },
        })
        if (!affiliate || affiliate.status !== 'ACTIVE') break

        const click = await prisma.affiliateClick.findUnique({
          where: { id: String(affClickId) },
          select: { id: true, affiliateId: true, createdAt: true },
        })
        if (!click || click.affiliateId !== affiliate.id) break

        const occurredAt = invoice.status_transitions?.paid_at
          ? new Date(invoice.status_transitions.paid_at * 1000)
          : new Date()
        // Enforce 30-day attribution window from click to conversion
        if (occurredAt.getTime() - click.createdAt.getTime() > 30 * 24 * 60 * 60 * 1000) break

        const paymentIntentId = typeof invoice.payment_intent === 'string' ? invoice.payment_intent : invoice.payment_intent?.id
        if (!paymentIntentId) break

        const { charge, balanceTx } = await getBalanceTransactionForPaymentIntent(paymentIntentId)
        if (!charge || !balanceTx) break

        const currency = String(balanceTx.currency || charge.currency || invoice.currency || 'aud').toLowerCase()
        const gross = Number(balanceTx.amount || 0)
        const fee = Number(balanceTx.fee || 0)
        const net = Number(balanceTx.net || 0)
        const chargeId = charge.id

        const customerId = typeof invoice.customer === 'string' ? invoice.customer : invoice.customer?.id
        let customerEmail: string | null = null
        if (customerId) {
          try {
            const customer = await stripe.customers.retrieve(customerId)
            customerEmail = (customer as Stripe.Customer)?.email?.toLowerCase() || null
          } catch {}
        }
        const referredUser = customerEmail
          ? await prisma.user.findUnique({ where: { email: customerEmail }, select: { id: true } }).catch(() => null)
          : null
        if (referredUser?.id && referredUser.id === affiliate.userId) break

        const conversion = await prisma.affiliateConversion
          .create({
            data: {
              affiliateId: affiliate.id,
              clickId: click.id,
              referredUserId: referredUser?.id || null,
              type: 'SUBSCRIPTION_INITIAL',
              stripeEventId: event.id,
              stripeCheckoutSessionId: null,
              stripePaymentIntentId: paymentIntentId,
              stripeChargeId: chargeId,
              stripeInvoiceId: invoice.id,
              currency,
              amountGrossCents: gross,
              stripeFeeCents: fee,
              amountNetCents: net,
              occurredAt,
            },
            select: { id: true },
          })
          .catch(() => null)

        if (!conversion) break

        const commissionCents = Math.floor(net / 2)
        await prisma.affiliateCommission.create({
          data: {
            affiliateId: affiliate.id,
            conversionId: conversion.id,
            status: 'PENDING',
            currency,
            netRevenueCents: net,
            commissionCents,
            payableAt: addDays(occurredAt, 30),
          },
        })

        break
      }
      case 'checkout.session.completed': {
        const session = event.data.object as Stripe.Checkout.Session

        // Only handle credit purchases (one-time payments), not subscriptions
        if (session.mode === 'payment' && session.payment_status === 'paid') {
          const customerEmail = session.customer_details?.email || session.customer_email
          if (!customerEmail) break

          const user = await prisma.user.findUnique({
            where: { email: customerEmail.toLowerCase() },
            select: { id: true, email: true, name: true }
          })

          if (user) {
            // Get amount and credit details from line items
            const amountCents = session.amount_total || 0
            const currency = (session.currency || 'usd').toUpperCase()

            // Determine credit amount based on price (common credit packages)
            // This is approximate - actual credits are handled in /api/billing/confirm
            let creditAmount = 0
            if (amountCents >= 1000) creditAmount = 1000 // $10 = 1000 credits
            else if (amountCents >= 500) creditAmount = 500 // $5 = 500 credits
            else if (amountCents >= 250) creditAmount = 250 // $2.50 = 250 credits

            // Notify owner of credit purchase (don't await to avoid blocking webhook)
            notifyOwner({
              event: 'credit_purchase',
              userEmail: user.email,
              userName: user.name || undefined,
              amount: amountCents,
              currency: currency,
              creditAmount: creditAmount || undefined,
            }).catch(error => {
              console.error('❌ Owner notification failed (non-blocking):', error)
            })
          }
        }

        // Practitioner boost purchases
        if (session.mode === 'payment' && session.payment_status === 'paid') {
          const boostFlag = (session.metadata as any)?.helfi_boost
          const listingId = (session.metadata as any)?.helfi_boost_listing_id
          if (boostFlag && listingId) {
            const radiusTier = String((session.metadata as any)?.helfi_boost_radius_tier || '')
            const geoKey = String((session.metadata as any)?.helfi_boost_geo_key || '')
            const categoryId = String((session.metadata as any)?.helfi_boost_category_id || '')
            const durationDays = Number((session.metadata as any)?.helfi_boost_duration_days || 7)
            const priceCents = Number((session.metadata as any)?.helfi_boost_price_cents || session.amount_total || 0)
            const paymentIntentId =
              typeof session.payment_intent === 'string' ? session.payment_intent : (session.payment_intent as any)?.id

            const existingBoost = await prisma.practitionerBoostPurchase.findFirst({
              where: {
                providerCheckoutSessionId: session.id,
              },
            })

            if (!existingBoost && radiusTier && geoKey && categoryId) {
              const startsAt = new Date()
              const endsAt = addDays(startsAt, durationDays || 7)
              await prisma.practitionerBoostPurchase.create({
                data: {
                  listingId: String(listingId),
                  categoryId,
                  geoKey,
                  radiusTier: radiusTier as any,
                  startsAt,
                  endsAt,
                  status: 'ACTIVE',
                  priceCents,
                  currency: String(session.currency || 'usd').toLowerCase(),
                  providerCheckoutSessionId: session.id,
                  providerPaymentIntentId: paymentIntentId || null,
                },
              })

              const listing = await prisma.practitionerListing.findUnique({
                where: { id: String(listingId) },
                include: { practitionerAccount: true },
              })

              if (listing) {
                const radiusLabel =
                  radiusTier === 'R5' ? '5 km' : radiusTier === 'R10' ? '10 km' : radiusTier === 'R25' ? '25 km' : '50 km'
                sendPractitionerBoostReceiptEmail({
                  practitionerAccountId: listing.practitionerAccountId,
                  listingId: listing.id,
                  toEmail: listing.practitionerAccount.contactEmail,
                  displayName: listing.displayName,
                  radiusLabel,
                  priceCents,
                }).catch((error) => {
                  console.error('❌ Practitioner boost receipt failed (non-blocking):', error)
                })
              }
            }
          }
        }

        // Affiliate attribution for top-ups (one-time payments)
        if (session.mode === 'payment' && session.payment_status === 'paid') {
          const affCode = (session.metadata as any)?.helfi_aff_code
          const affClickId = (session.metadata as any)?.helfi_aff_click
          if (!affCode || !affClickId) break

          const affiliate = await prisma.affiliate.findUnique({
            where: { code: String(affCode).toLowerCase() },
            select: { id: true, status: true, userId: true },
          })
          if (!affiliate || affiliate.status !== 'ACTIVE') break

          const click = await prisma.affiliateClick.findUnique({
            where: { id: String(affClickId) },
            select: { id: true, affiliateId: true, createdAt: true },
          })
          if (!click || click.affiliateId !== affiliate.id) break

          const occurredAt = session.created ? new Date(session.created * 1000) : new Date()
          if (occurredAt.getTime() - click.createdAt.getTime() > 30 * 24 * 60 * 60 * 1000) break

          const paymentIntentId =
            typeof session.payment_intent === 'string' ? session.payment_intent : (session.payment_intent as any)?.id
          if (!paymentIntentId) break

          const { charge, balanceTx } = await getBalanceTransactionForPaymentIntent(paymentIntentId)
          if (!charge || !balanceTx) break

          const currency = String(balanceTx.currency || charge.currency || session.currency || 'aud').toLowerCase()
          const gross = Number(balanceTx.amount || 0)
          const fee = Number(balanceTx.fee || 0)
          const net = Number(balanceTx.net || 0)
          const chargeId = charge.id

          const customerEmail = (session.customer_details?.email || session.customer_email || '').toLowerCase()
          const referredUser = customerEmail
            ? await prisma.user.findUnique({ where: { email: customerEmail }, select: { id: true } }).catch(() => null)
            : null
          if (referredUser?.id && referredUser.id === affiliate.userId) break

          const conversion = await prisma.affiliateConversion
            .create({
              data: {
                affiliateId: affiliate.id,
                clickId: click.id,
                referredUserId: referredUser?.id || null,
                type: 'TOPUP',
                stripeEventId: event.id,
                stripeCheckoutSessionId: session.id,
                stripePaymentIntentId: paymentIntentId,
                stripeChargeId: chargeId,
                stripeInvoiceId: null,
                currency,
                amountGrossCents: gross,
                stripeFeeCents: fee,
                amountNetCents: net,
                occurredAt,
              },
              select: { id: true },
            })
            .catch(() => null)

          if (!conversion) break

          const commissionCents = Math.floor(net / 2)
          await prisma.affiliateCommission.create({
            data: {
              affiliateId: affiliate.id,
              conversionId: conversion.id,
              status: 'PENDING',
              currency,
              netRevenueCents: net,
              commissionCents,
              payableAt: addDays(occurredAt, 30),
            },
          })
        }
        break
      }
      case 'invoice.payment_failed': {
        const invoice = event.data.object as Stripe.Invoice
        const customerId = typeof invoice.customer === 'string' ? invoice.customer : invoice.customer?.id
        const subscriptionId = typeof invoice.subscription === 'string' ? invoice.subscription : invoice.subscription?.id
        if (subscriptionId) {
          const listingSubscription = await prisma.practitionerListingSubscription.findFirst({
            where: { providerSubscriptionId: subscriptionId },
            include: { listing: { include: { practitionerAccount: true } } },
          })
          if (listingSubscription) {
            await prisma.practitionerListingSubscription.update({
              where: { listingId: listingSubscription.listingId },
              data: { status: 'PAST_DUE' },
            })
            await prisma.practitionerListing.update({
              where: { id: listingSubscription.listingId },
              data: { status: 'HIDDEN', visibilityReason: 'PAYMENT_FAILED' },
            })
            sendPractitionerPaymentFailedEmail({
              practitionerAccountId: listingSubscription.listing.practitionerAccountId,
              listingId: listingSubscription.listingId,
              toEmail: listingSubscription.listing.practitionerAccount.contactEmail,
              displayName: listingSubscription.listing.displayName,
            }).catch((error) => {
              console.error('❌ Practitioner payment failed email (non-blocking):', error)
            })
            break
          }
        }
        let email: string | undefined
        if (customerId) {
          try {
            const customer = await stripe.customers.retrieve(customerId)
            if ((customer as Stripe.Customer).email) {
              email = (customer as Stripe.Customer).email as string
            }
          } catch {}
        }
        if (!email) break

        const user = await prisma.user.findUnique({
          where: { email: email.toLowerCase() },
          include: { subscription: true },
        })
        if (!user?.subscription) break

        await prisma.subscription.update({
          where: { userId: user.id },
          data: {
            stripeSubscriptionId: subscriptionId || user.subscription.stripeSubscriptionId,
            endDate: new Date(),
          },
        })
        console.log(`[Webhook] Payment failed for ${email}. Access paused.`)
        break
      }
      case 'charge.refunded':
      case 'charge.dispute.created': {
        const charge = event.data.object as Stripe.Charge
        const conversion = await prisma.affiliateConversion.findFirst({
          where: { stripeChargeId: charge.id },
          select: { id: true, commission: { select: { id: true, status: true, payableAt: true } } },
        })
        if (conversion?.commission && conversion.commission.status === 'PENDING') {
          await prisma.affiliateCommission.update({
            where: { id: conversion.commission.id },
            data: { status: 'VOIDED' },
          })
        }

        const now = new Date()

        // Revoke subscription access for refunded/charged-back invoices.
        const invoiceId = typeof charge.invoice === 'string' ? charge.invoice : charge.invoice?.id
        if (invoiceId) {
          try {
            const invoice = await stripe.invoices.retrieve(invoiceId)
            const subscriptionId =
              typeof invoice.subscription === 'string' ? invoice.subscription : invoice.subscription?.id
            if (subscriptionId) {
              const updated = await prisma.subscription.updateMany({
                where: { stripeSubscriptionId: subscriptionId },
                data: { endDate: now },
              })
              if (!updated.count) {
                const customerId = typeof charge.customer === 'string' ? charge.customer : charge.customer?.id
                let email: string | undefined
                if (customerId) {
                  try {
                    const customer = await stripe.customers.retrieve(customerId)
                    if ((customer as Stripe.Customer).email) {
                      email = (customer as Stripe.Customer).email as string
                    }
                  } catch {}
                }
                if (email) {
                  const user = await prisma.user.findUnique({
                    where: { email: email.toLowerCase() },
                    select: { id: true },
                  })
                  if (user) {
                    await prisma.subscription.updateMany({
                      where: { userId: user.id },
                      data: { endDate: now },
                    })
                  }
                }
              }
            }
          } catch {}
        }

        // Revoke top-up credits linked to the refunded/charged-back payment.
        const paymentIntentId =
          typeof charge.payment_intent === 'string' ? charge.payment_intent : charge.payment_intent?.id
        if (paymentIntentId) {
          const session = await findCheckoutSessionForPaymentIntent(paymentIntentId)
          if (session?.id) {
            const source = `stripe:${session.id}`
            const topUps = await prisma.creditTopUp.findMany({ where: { source } })
            if (topUps.length) {
              for (const topUp of topUps) {
                const nextUsed = Math.max(topUp.usedCents, topUp.amountCents)
                await prisma.creditTopUp.update({
                  where: { id: topUp.id },
                  data: { usedCents: nextUsed },
                })
              }
            }
          }
        }
        break
      }

      default:
        break
    }

    return NextResponse.json({ received: true })
  } catch (e) {
    reportCriticalError({
      source: 'billing.webhook',
      error: e,
      details: {
        eventType: event?.type,
        eventId: event?.id,
      },
    })
    console.error('Stripe webhook error', e)
    return NextResponse.json({ error: 'Webhook handler failure' }, { status: 500 })
  }
}

