            duration: true,
            intensity: true,
            createdAt: true,
          },
          orderBy: { createdAt: 'desc' },
          take: 20,
        },
        foodLogs: {
          select: {
            name: true,
            description: true,
            createdAt: true,
          },
          orderBy: { createdAt: 'desc' },
          take: 20,
        },
      },
    }),
    prisma.$queryRawUnsafe<Array<{ id: string; name: string; polarity: string; slug: string | null }>>(
      'SELECT id, name, polarity, NULL::text AS slug FROM CheckinIssues WHERE userId = $1',
      userId
    ).catch(() => []),
  ])

  if (!user) return null

  return {
    profile: {
      gender: user.gender,
      weight: user.weight,
      height: user.height,
      bodyType: user.bodyType,
      exerciseFrequency: user.exerciseFrequency,
      exerciseTypes: user.exerciseTypes,
    },
    healthGoals: user.healthGoals,
    supplements: user.supplements,
    medications: user.medications,
    exerciseLogs: user.exerciseLogs,
    foodLogs: user.foodLogs,
    issues: issues.map((i) => ({ id: i.id, name: i.name, polarity: i.polarity, slug: i.slug })),
  }
}

const isValidDateString = (value: string) => /^\d{4}-\d{2}-\d{2}$/.test(value)

const shiftDateString = (date: string, deltaDays: number) => {
  if (!isValidDateString(date)) return date
  const [y, m, d] = date.split('-').map((v) => parseInt(v, 10))
  const base = new Date(Date.UTC(y, m - 1, d))
  base.setUTCDate(base.getUTCDate() + deltaDays)
  const year = base.getUTCFullYear()
  const month = String(base.getUTCMonth() + 1).padStart(2, '0')
  const day = String(base.getUTCDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

const resolveDateFromQuestion = (question: string, defaultDate: string) => {
  const text = String(question || '').toLowerCase()
  const isoMatch = text.match(/\b(\d{4}-\d{2}-\d{2})\b/)
  if (isoMatch && isValidDateString(isoMatch[1])) {
    return isoMatch[1]
  }
  if (text.includes('yesterday') || text.includes('previous day')) {
    return shiftDateString(defaultDate, -1)
  }
  if (text.includes('tomorrow')) {
    return shiftDateString(defaultDate, 1)
  }
  return defaultDate
}

const formatMacroValue = (value: number | null, unit: 'kcal' | 'g') => {
  if (typeof value !== 'number' || !Number.isFinite(value)) return 'N/A'
  const rounded = unit === 'kcal' ? Math.round(value) : Math.round(value * 10) / 10
  return `${rounded} ${unit}`
}

const formatRemaining = (value: FoodDiarySnapshot['remaining'][keyof FoodDiarySnapshot['remaining']]) => {
  if (!value) return 'N/A'
  const remaining = typeof value.remainingClamped === 'number' ? value.remainingClamped : value.remaining
  const over = value.overBy
  if (typeof over === 'number' && over > 0) return `Over by ${Math.round(over * 10) / 10}`
  if (typeof remaining === 'number') return `${Math.round(remaining * 10) / 10} left`
  return 'N/A'
}

