const MAX_HISTORY_MESSAGES = 16
const MAX_MESSAGE_CHARS = 2000

const trimMessageContent = (value: string) => {
  const text = String(value || '')
  if (text.length <= MAX_MESSAGE_CHARS) return text
  return `${text.slice(0, MAX_MESSAGE_CHARS).trim()}...`
}

const extractAssistantContent = (message: any) => {
  if (!message) return ''
  const content = message.content
  if (typeof content === 'string') return content.trim()
  if (content && typeof content === 'object' && typeof content.text === 'string') {
    return content.text.trim()
  }
  if (Array.isArray(content)) {
    const joined = content
      .map((part: any) => {
        if (typeof part?.text === 'string') return part.text
        if (typeof part?.text?.value === 'string') return part.text.value
        if (typeof part?.text?.content === 'string') return part.text.content
        if (typeof part?.content === 'string') return part.content
        return ''
      })
      .join('')
    return joined.trim()
  }
  if (typeof message.refusal === 'string') return message.refusal.trim()
  if (typeof (message as any).output_text === 'string') return String((message as any).output_text).trim()
  return ''
}

const MEAL_OPTIONS_JSON_START = '[[MEAL_OPTIONS_JSON]]'
const MEAL_OPTIONS_JSON_END = '[[/MEAL_OPTIONS_JSON]]'

type StructuredMealOption = {
  optionNumber: number
  title: string
  category: 'breakfast' | 'lunch' | 'dinner' | 'snacks' | 'uncategorized'
  servings: number
  prepMinutes: number | null
  cookMinutes: number | null
  ingredients: string[]
  steps: string[]
}

const splitTitleToIngredients = (title: string) => {
  const cleaned = String(title || '')
    .replace(/\((.*?)\)/g, '')
    .replace(/\s+/g, ' ')
    .trim()
  if (!cleaned) return []
  return cleaned
    .split(/\s+\+\s+|\s+&\s+|\s+with\s+|,\s+(?=[a-z0-9])/i)
    .map((part) => String(part || '').trim())
    .filter(Boolean)
    .slice(0, 16)
}

const inferMealCategory = (title: string): StructuredMealOption['category'] => {
  const t = String(title || '').toLowerCase()
  if (/(breakfast|oat|porridge|omelette|omelet|toast|pancake|waffle|yogurt bowl|smoothie bowl|granola)/i.test(t)) return 'breakfast'
  if (/(snack|protein bar|trail mix|popcorn|nuts|fruit cup)/i.test(t)) return 'snacks'
  if (/(lunch|salad|sandwich|wrap|bowl)/i.test(t)) return 'lunch'
  if (/(dinner|steak|curry|stir fry|chili|pasta|roast|salmon|chicken breast)/i.test(t)) return 'dinner'
  return 'uncategorized'
}

const normalizeMealCategory = (raw: any, fallbackTitle: string): StructuredMealOption['category'] => {
  const value = String(raw || '').toLowerCase().trim()
  if (!value) return inferMealCategory(fallbackTitle)
  if (value.includes('breakfast')) return 'breakfast'
  if (value.includes('lunch')) return 'lunch'
  if (value.includes('dinner')) return 'dinner'
  if (value.includes('snack')) return 'snacks'
  if (value.includes('uncat') || value.includes('other')) return 'uncategorized'
  return inferMealCategory(fallbackTitle)
}

const sanitizeLine = (value: any) =>
  String(value || '')
    .replace(/^[\s•*\-–—]+/, '')
    .replace(/^\d+\.\s+/, '')
    .replace(/\s+/g, ' ')
    .trim()

const clampServingCount = (value: number) => {
  if (!Number.isFinite(value)) return 1
  return Math.max(1, Math.min(12, Math.round(value)))
}

const parseServingCountFromText = (text: string): number | null => {
  const raw = String(text || '')
  if (!raw) return null

  const rangeMatch =
    raw.match(/\b(?:serves?|servings?)\s*[:\-]?\s*(\d+(?:\.\d+)?)\s*(?:to|-)\s*(\d+(?:\.\d+)?)/i) ||
    raw.match(/\b(\d+(?:\.\d+)?)\s*(?:to|-)\s*(\d+(?:\.\d+)?)\s*servings?\b/i)
  if (rangeMatch) {
    const first = Number(rangeMatch[1])
    const second = Number(rangeMatch[2])
    if (Number.isFinite(first) && Number.isFinite(second) && first > 0 && second > 0) {
      return clampServingCount((first + second) / 2)
    }
  }

  const singleMatch =
    raw.match(/\b(?:serves?|servings?)\s*[:\-]?\s*(\d+(?:\.\d+)?)/i) ||
    raw.match(/\bfor\s+(\d+(?:\.\d+)?)\s+(?:people|servings?)\b/i) ||
    raw.match(/\b(\d+(?:\.\d+)?)\s+servings?\b/i)
  if (!singleMatch) return null
  const value = Number(singleMatch[1])
  if (!Number.isFinite(value) || value <= 0) return null
  return clampServingCount(value)
}

const parseApproxRecipeCaloriesFromText = (text: string): number | null => {
  const raw = String(text || '')
  if (!raw) return null
  const match = raw.match(/(-?\d+(?:\.\d+)?)\s*kcal\b/i)
  if (!match) return null
  const value = Number(match[1])
  if (!Number.isFinite(value) || value <= 0) return null
  return value
}

const resolveRecipeServingCount = (params: {
  visibleMessage: string
  fallbackText?: string
  title?: string
  ingredientsCount?: number
  seed?: number | null
}) => {
  const visible = String(params.visibleMessage || '')
  const fallback = String(params.fallbackText || '')
  const title = String(params.title || '')
  const contextText = `${title}\n${visible}\n${fallback}`.trim()

  const explicit =
    parseServingCountFromText(visible) ||
    parseServingCountFromText(fallback) ||
    parseServingCountFromText(title)
  if (explicit) return explicit

  if (/\b(single serve|single-serving|for one|one serving)\b/i.test(contextText)) return 1

  let estimate =
    Number.isFinite(Number(params.seed)) && Number(params.seed) > 0 ? clampServingCount(Number(params.seed)) : 1

  const calories = parseApproxRecipeCaloriesFromText(visible)
  if (calories !== null) {
    if (calories >= 2200) estimate = Math.max(estimate, 4)
    else if (calories >= 1500) estimate = Math.max(estimate, 3)
    else if (calories >= 900) estimate = Math.max(estimate, 2)
  }

  const ingredientCount = Number(params.ingredientsCount)
  if (Number.isFinite(ingredientCount) && ingredientCount > 0) {
    if (ingredientCount >= 10) estimate = Math.max(estimate, 4)
    else if (ingredientCount >= 7) estimate = Math.max(estimate, 3)
    else if (ingredientCount >= 4) estimate = Math.max(estimate, 2)
  }

  if (estimate < 2 && /\b(pasta|alfredo|curry|stir fry|soup|chili|salad|roast|casserole)\b/i.test(contextText)) {
    estimate = 2
  }

  return clampServingCount(estimate)
}

const parseOptionTitlesFromVisibleText = (text: string) => {
  const lines = String(text || '')
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean)
  const out: Array<{ optionNumber: number; title: string }> = []
  for (const line of lines) {
    const m = line.match(/^Option\s+(\d+):\s*(.+)$/i)
    if (!m) continue
    const optionNumber = Number(m[1])
    const title = String(m[2] || '').trim()
    if (!Number.isFinite(optionNumber) || optionNumber <= 0 || !title) continue
    out.push({ optionNumber: Math.round(optionNumber), title })
  }
  return out
}

const isRecipeIngredientHeader = (line: string) =>
  /^(ingredients?|you(?:'|’)ll need|what you(?:'|’)ll need|shopping list)\b[:\-]?\s*$/i.test(
    String(line || '').trim(),
  )

const isRecipeStepHeader = (line: string) =>
  /^(instructions?|directions?|method|steps?|how to (make|cook|prepare))\b[:\-]?\s*$/i.test(
    String(line || '').trim(),
  )

const cleanRecipeTitle = (line: string) =>
  String(line || '')
    .replace(/^recipe[:\-]?\s*/i, '')
    .replace(/^here(?:'|’)s\s+(?:a|the)\s+/i, '')
    .replace(/^option\s+\d+:\s*/i, '')
    .replace(/[.!?]+$/, '')
    .trim()

const isRecipeSignalLine = (line: string) => {
  const normalized = String(line || '').toLowerCase()
  if (!normalized) return false
  return (
    normalized.includes('ingredient') ||
    normalized.includes('instruction') ||
    normalized.includes('directions') ||
    normalized.includes('method') ||
    normalized.includes('step') ||
    normalized.includes('cook') ||
    normalized.includes('serve') ||
    normalized.includes('stir') ||
    normalized.includes('simmer') ||
    normalized.includes('bake') ||
    normalized.includes('saute')
  )
}

const inferRecipeTitleFromQuestion = (question: string) => {
  const q = String(question || '').trim()
  if (!q) return 'Custom meal recipe'
  const cleaned = q
    .replace(/^can you\s+/i, '')
    .replace(/^please\s+/i, '')
    .replace(/^could you\s+/i, '')
    .replace(/^make(?:\s+me)?\s+/i, '')
    .replace(/^create(?:\s+me)?\s+/i, '')
    .replace(/^give me\s+/i, '')
    .replace(/^a\s+/i, '')
    .replace(/\?+$/, '')
    .trim()
  return cleanRecipeTitle(cleaned || q).slice(0, 120) || 'Custom meal recipe'
}

const parseSingleRecipeOptionFromVisibleText = (
  visibleMessage: string,
  fallbackTitle: string,
): StructuredMealOption | null => {
  const lines = String(visibleMessage || '')
    .replace(/\r/g, '')
    .split('\n')
    .map((line) => String(line || '').trim())
    .filter(Boolean)
  if (lines.length === 0) return null

  const hasRecipeSignal = lines.some((line) => isRecipeSignalLine(line))
  if (!hasRecipeSignal) return null

  let inferredTitle = ''
  for (const line of lines) {
    if (isRecipeIngredientHeader(line) || isRecipeStepHeader(line)) break
    if (/^(current totals|targets|macros|after eating|servings?|serves|option\s+\d+):/i.test(line)) continue
    if (/^\d+[.)]\s+/.test(line)) continue
    if (/^[-•*]\s+/.test(line)) continue
    if (line.length < 4) continue
    inferredTitle = cleanRecipeTitle(line)
    break
  }
  const title = inferredTitle || inferRecipeTitleFromQuestion(fallbackTitle)

  const ingredients: string[] = []
  const steps: string[] = []
  let inIngredients = false
  let inSteps = false
  let sawNumberedStep = false

  for (const rawLine of lines) {
    if (isRecipeIngredientHeader(rawLine)) {
      inIngredients = true
      inSteps = false
      continue
    }
    if (isRecipeStepHeader(rawLine)) {
      inSteps = true
      inIngredients = false
      continue
    }

    const numbered = rawLine.match(/^(\d+)[.)]\s+(.+)$/)
    if (numbered) {
      sawNumberedStep = true
      inSteps = true
      inIngredients = false
      const stepLine = sanitizeLine(numbered[2])
      if (stepLine) steps.push(stepLine)
      continue
    }

    const bullet = rawLine.match(/^[-•*]\s+(.+)$/)
    if (bullet) {
      const bulletLine = sanitizeLine(bullet[1])
      if (!bulletLine) continue
      if (inSteps) {
        steps.push(bulletLine)
      } else if (inIngredients || !sawNumberedStep) {
        ingredients.push(bulletLine)
      }
      continue
    }

    if (inIngredients) {
      ingredients.push(sanitizeLine(rawLine))
      continue
    }
    if (inSteps) {
      steps.push(sanitizeLine(rawLine))
    }
  }

  const uniqueIngredients = Array.from(new Set(ingredients.map((line) => line.toLowerCase())))
    .map((key) => ingredients.find((line) => line.toLowerCase() === key) || '')
    .filter(Boolean)
    .slice(0, 60)
  const cleanSteps = steps.map((line) => sanitizeLine(line)).filter(Boolean).slice(0, 30)

  if (uniqueIngredients.length < 2 || cleanSteps.length < 2) return null

  const servings = resolveRecipeServingCount({
    visibleMessage,
    fallbackText: fallbackTitle,
    title,
    ingredientsCount: uniqueIngredients.length,
  })

  return {
    optionNumber: 1,
    title,
    category: inferMealCategory(title),
    servings,
    prepMinutes: null,
    cookMinutes: null,
    ingredients: uniqueIngredients,
    steps: cleanSteps,
  }
}

const stripMealOptionsJsonBlock = (message: string) => {
  const raw = String(message || '')
  const start = raw.indexOf(MEAL_OPTIONS_JSON_START)
  const end = raw.indexOf(MEAL_OPTIONS_JSON_END)
  if (start === -1 || end <= start) return { visibleMessage: raw.trim(), jsonRaw: null as string | null }
  const before = raw.slice(0, start).trimEnd()
  const after = raw.slice(end + MEAL_OPTIONS_JSON_END.length).trimStart()
  return {
    visibleMessage: `${before}${before && after ? '\n\n' : ''}${after}`.trim(),
    jsonRaw: raw.slice(start + MEAL_OPTIONS_JSON_START.length, end).trim(),
  }
}

const safeParseObject = (raw: string) => {
  try {
    return JSON.parse(raw)
  } catch {
    const cleaned = String(raw || '')
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .trim()
    try {
      return JSON.parse(cleaned)
    } catch {
      return null
    }
  }
}

const normalizeStructuredMealOptions = (
  raw: any,
  fallbackTitles: Array<{ optionNumber: number; title: string }>,
): StructuredMealOption[] => {
  const input = Array.isArray(raw?.options) ? raw.options : Array.isArray(raw) ? raw : []
  const byIndex = new Map<number, { optionNumber: number; title: string }>()
  fallbackTitles.forEach((entry, index) => {
    byIndex.set(index + 1, entry)
    byIndex.set(entry.optionNumber, entry)
  })
  const normalized = input
    .map((entry: any, index: number) => {
      const fallback = byIndex.get(index + 1) || byIndex.get(Number(entry?.optionNumber)) || null
      const optionNumberRaw = Number(entry?.optionNumber ?? fallback?.optionNumber ?? index + 1)
      const optionNumber = Number.isFinite(optionNumberRaw) && optionNumberRaw > 0 ? Math.round(optionNumberRaw) : index + 1
      const title = sanitizeLine(entry?.title || fallback?.title || '')
      if (!title) return null

      const ingredientListRaw = Array.isArray(entry?.ingredients) ? entry.ingredients : []
      let ingredients = ingredientListRaw.map((line: any) => sanitizeLine(line)).filter(Boolean).slice(0, 60)
      if (ingredients.length < 2) {
        ingredients = splitTitleToIngredients(title)
      }
      if (ingredients.length < 2) return null

      const stepsRaw = Array.isArray(entry?.steps) ? entry.steps : []
      const steps = stepsRaw.map((line: any) => sanitizeLine(line)).filter(Boolean).slice(0, 30)
      const safeSteps =
        steps.length >= 2
          ? steps
          : [`Prepare ingredients for ${title}.`, `Cook and assemble ${title}.`, `Serve and enjoy.`]

      const servingsRaw = Number(entry?.servings)
      const servings = Number.isFinite(servingsRaw) && servingsRaw > 0 ? Math.round(servingsRaw) : 1
      const prepRaw = Number(entry?.prepMinutes)
      const prepMinutes = Number.isFinite(prepRaw) && prepRaw >= 0 ? Math.round(prepRaw) : null
      const cookRaw = Number(entry?.cookMinutes)
      const cookMinutes = Number.isFinite(cookRaw) && cookRaw >= 0 ? Math.round(cookRaw) : null

      return {
        optionNumber,
        title,
        category: normalizeMealCategory(entry?.category, title),
        servings,
        prepMinutes,
        cookMinutes,
        ingredients,
        steps: safeSteps,
      } as StructuredMealOption
    })
    .filter((entry: StructuredMealOption | null): entry is StructuredMealOption => Boolean(entry))
    .slice(0, 3)

  return normalized
}

const appendMealOptionsJsonBlock = (visibleMessage: string, options: StructuredMealOption[]) => {
  const body = String(visibleMessage || '').trim()
  const payload = JSON.stringify({ options })
  return `${body}\n\n${MEAL_OPTIONS_JSON_START}\n${payload}\n${MEAL_OPTIONS_JSON_END}`
}

const buildStructuredFoodOptions = async (params: {
  openai: OpenAI
  visibleMessage: string
  optionTitles: Array<{ optionNumber: number; title: string }>
  model: string
  fallbackModel: string
}) => {
  const run = async (modelName: string) => {
    const completion = await chatCompletionWithCost(params.openai, {
      model: modelName,
      temperature: 0.1,
      max_tokens: 700,
      response_format: { type: 'json_object' } as any,
      messages: [
        {
          role: 'system',
          content:
            'Convert meal options into structured recipe data.\n' +
            'Return valid JSON object only: {"options":[...]}\n' +
            'Each option requires: optionNumber, title, category, servings, prepMinutes, cookMinutes, ingredients, steps.\n' +
            'ingredients must be separate lines with amount + unit (for example "150 g chicken breast").\n' +
            'steps must be concise cooking steps in order.\n' +
            'Keep only options that exist in the visible text.',
        },
        {
          role: 'user',
          content:
            `Visible meal options text:\n${params.visibleMessage}\n\n` +
            `Known options:\n${JSON.stringify(params.optionTitles)}`,
        },
      ],
    } as any)
    const raw = extractAssistantContent(completion.completion.choices?.[0]?.message)
    return { completion, raw }
  }

  let first = await run(params.model)
  let parsed = safeParseObject(first.raw)
  let normalized = normalizeStructuredMealOptions(parsed, params.optionTitles)
  let totalCostCents = first.completion.costCents

  if (normalized.length > 0) {
    return { options: normalized, costCents: totalCostCents }
  }

  if (params.fallbackModel && params.fallbackModel !== params.model) {
    const second = await run(params.fallbackModel)
    totalCostCents += second.completion.costCents
    parsed = safeParseObject(second.raw)
    normalized = normalizeStructuredMealOptions(parsed, params.optionTitles)
  }

  return { options: normalized, costCents: totalCostCents }
}

