    // Save user message
    await appendMessage(threadId, 'user', question, undefined, clientMessageId)

    // Auto-generate title from first message if thread has no title
    const threads = await listThreads(session.user.id, chatContext)
    const currentThread = threads.find(t => t.id === threadId)
    if (currentThread && !currentThread.title) {
      const title = question.length > 50 ? question.substring(0, 47) + '...' : question
      await updateThreadTitle(threadId, title)
    }

    // If only estimating, return cost
    if (body?.estimateOnly) {
      return NextResponse.json({
        estimatedCost: shouldCharge ? (allowViaFreeUse ? 0 : VOICE_CHAT_COST_CENTS) : 0,
        availableCredits: wallet.totalAvailableCents,
        freeUseApplied: allowViaFreeUse,
      })
    }

    if (shouldCharge && !allowViaFreeUse && wallet.totalAvailableCents < VOICE_CHAT_COST_CENTS) {
      return NextResponse.json(
        {
          error: 'Insufficient credits',
          estimatedCost: VOICE_CHAT_COST_CENTS,
          availableCredits: wallet.totalAvailableCents,
        },
        { status: 402 }
      )
    }

    const maxTokens = isFoodChat ? 900 : 500

    if (wantsStream) {
      const completionResult = await runVoiceCompletionWithFallback({
        openai,
        model,
        fallbackModel,
        messages: chatMessages,
        maxTokens,
      })
      const wrapped = completionResult.wrapped
      const usedModel = completionResult.usedModel
      let assistantMessage = completionResult.assistantMessage
      let structuredExtraCostCents = 0
      const chargedCents = shouldCharge ? (allowViaFreeUse ? 0 : VOICE_CHAT_COST_CENTS) : 0
      if (shouldCharge) {
        if (!allowViaFreeUse) {
          const ok = await cm.chargeCents(chargedCents)
          if (!ok) {
            return NextResponse.json(
              {
                error: 'Insufficient credits',
                estimatedCost: VOICE_CHAT_COST_CENTS,
                availableCredits: wallet.totalAvailableCents,
              },
              { status: 402 }
            )
          }
        } else {
          await consumeFreeCredit(user.id, 'VOICE_CHAT')
        }
        await markThreadCharged(threadId)
      }

      // PROTECTED: FOOD_CHAT_MEAL_PAYLOAD_ENRICH_STREAM START
      if (isFoodChat && assistantMessage) {
        try {
          const ensured = await ensureFoodMealOptionsPayload({
            openai,
            assistantMessage,
            model,
            fallbackModel,
            userQuestion: question,
          })
          assistantMessage = ensured.assistantMessage
          structuredExtraCostCents = ensured.extraCostCents
        } catch (foodOptionError) {
          console.warn('[voice-chat] food option payload enrichment failed', foodOptionError)
        }
      }
      // PROTECTED: FOOD_CHAT_MEAL_PAYLOAD_ENRICH_STREAM END

      const apiCostCents = (wrapped.costCents + structuredExtraCostCents) * 2

      // Save assistant message
      await appendMessage(threadId, 'assistant', assistantMessage)

      // Log usage for visibility
      try {
        await logAIUsage({
          context: { feature: 'voice:chat', userId: user.id },
          model: usedModel,
          promptTokens: wrapped.promptTokens,
          completionTokens: wrapped.completionTokens,
          costCents: apiCostCents,
        })
      } catch {
        // Ignore logging failures
      }

      const enc = new TextEncoder()
      const chunks = assistantMessage.match(/[\s\S]{1,200}/g) || ['']
      const stream = new ReadableStream({
        start(controller) {
          for (const chunk of chunks) {
            const payload = JSON.stringify({ token: chunk })
            controller.enqueue(enc.encode(`data: ${payload}\n\n`))
          }
          const chargePayload = JSON.stringify({ chargedCents, chargedOnce: true })
          controller.enqueue(enc.encode(`event: charged\ndata: ${chargePayload}\n\n`))
          controller.enqueue(enc.encode('event: end\n\n'))
          controller.close()
        },
      })

      return new Response(stream, {
        headers: {
          'Content-Type': 'text/event-stream',
          'Cache-Control': 'no-cache',
          Connection: 'keep-alive',
        },
      })
    } else {
      // Non-streaming
      const completionResult = await runVoiceCompletionWithFallback({
        openai,
        model,
        fallbackModel,
        messages: chatMessages,
        maxTokens,
      })
      const wrapped = completionResult.wrapped
      const usedModel = completionResult.usedModel
      const chargedCents = shouldCharge ? (allowViaFreeUse ? 0 : VOICE_CHAT_COST_CENTS) : 0
      if (shouldCharge) {
        if (!allowViaFreeUse) {
          const ok = await cm.chargeCents(chargedCents)
          if (!ok) {
            return NextResponse.json(
              {
                error: 'Insufficient credits',
                estimatedCost: VOICE_CHAT_COST_CENTS,
                availableCredits: wallet.totalAvailableCents,
              },
              { status: 402 }
            )
          }
        } else {
          await consumeFreeCredit(user.id, 'VOICE_CHAT')
        }
        await markThreadCharged(threadId)
      }

      let assistantMessage = completionResult.assistantMessage
      let structuredExtraCostCents = 0
      // PROTECTED: FOOD_CHAT_MEAL_PAYLOAD_ENRICH_NON_STREAM START
      if (isFoodChat && assistantMessage) {
        try {
          const ensured = await ensureFoodMealOptionsPayload({
            openai,
            assistantMessage,
            model,
            fallbackModel,
            userQuestion: question,
          })
          assistantMessage = ensured.assistantMessage
          structuredExtraCostCents = ensured.extraCostCents
        } catch (foodOptionError) {
          console.warn('[voice-chat] food option payload enrichment failed', foodOptionError)
        }
      }
      // PROTECTED: FOOD_CHAT_MEAL_PAYLOAD_ENRICH_NON_STREAM END

      // Log AI usage for cost tracking (voice chat, non-streaming)
      try {
        await logAIUsage({
          context: { feature: 'voice:chat', userId: user.id },
          model: usedModel,
          promptTokens: wrapped.promptTokens,
          completionTokens: wrapped.completionTokens,
          costCents: (wrapped.costCents + structuredExtraCostCents) * 2,
        })
      } catch {
        // Ignore logging failures
      }

      // Save assistant message
      await appendMessage(threadId, 'assistant', assistantMessage)

      return NextResponse.json({
        assistant: assistantMessage,
        estimatedCost: chargedCents,
        chargedCostCents: chargedCents,
        chargedOnce: true,
        threadId,
      })
    }
  } catch (err: any) {
    console.error('[voice-chat] Error:', err)
    const message = String(err?.message || '')
    const lower = message.toLowerCase()
    if (lower.includes('tokens') && lower.includes('limit')) {
      return NextResponse.json(
        { error: 'That chat is too long. Please start a new chat and try again.' },
        { status: 400 }
      )
    }
    return NextResponse.json({ error: err.message || 'Internal server error' }, { status: 500 })
  }
}

