import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { getCheckinUser } from '@/app/api/checkins/_auth'

export const dynamic = 'force-dynamic'
export const revalidate = 0

let checkinTablesEnsured = false

async function ensureCheckinTables() {
  if (checkinTablesEnsured) return
  try {
    await prisma.$executeRawUnsafe(`
      CREATE TABLE IF NOT EXISTS CheckinIssues (
        id TEXT PRIMARY KEY,
        userId TEXT NOT NULL,
        name TEXT NOT NULL,
        polarity TEXT NOT NULL,
        UNIQUE (userId, name)
      )
    `)
    await prisma.$executeRawUnsafe(`
      CREATE TABLE IF NOT EXISTS CheckinRatings (
        id TEXT PRIMARY KEY,
        userId TEXT NOT NULL,
        issueId TEXT NOT NULL,
        date TEXT NOT NULL,
        timestamp TIMESTAMP NOT NULL DEFAULT NOW(),
        value INTEGER,
        note TEXT,
        isNa BOOLEAN DEFAULT false
      )
    `)
    await prisma.$executeRawUnsafe(`ALTER TABLE CheckinRatings ADD COLUMN IF NOT EXISTS note TEXT`).catch(() => {})
    await prisma.$executeRawUnsafe(`ALTER TABLE CheckinRatings ADD COLUMN IF NOT EXISTS isNa BOOLEAN DEFAULT false`).catch(() => {})
    checkinTablesEnsured = true
  } catch (error) {
    console.error('[checkins] Failed to ensure tables', error)
  }
}

export async function GET(req: NextRequest) {
  const user = await getCheckinUser(req)
  if (!user) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  await ensureCheckinTables()

  const { searchParams } = new URL(req.url)
  const start = searchParams.get('start') || '1970-01-01'
  const end = searchParams.get('end') || new Date().toISOString().slice(0,10)

  try {
    const rows: any[] = await prisma.$queryRawUnsafe(
      `SELECT r.id, r.date, r.timestamp, r.issueId AS "issueId", i.name, i.polarity, r.value, r.note, r.isNa AS "isNa"
       FROM CheckinRatings r
       JOIN CheckinIssues i ON i.id = r.issueId
       WHERE r.userId = $1 AND r.date BETWEEN $2 AND $3
       ORDER BY r.timestamp DESC, i.name ASC`,
      user.id, start, end
    )
    console.info('[checkins history] loaded', { userId: user.id, start, end, count: rows.length })
    return NextResponse.json(
      { history: rows },
      { headers: { 'Cache-Control': 'private, no-store, max-age=0' } },
    )
  } catch (e) {
    console.error('checkins history error', e)
    return NextResponse.json({ error: 'Failed to load history' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { createWriteGuard, hashPayload } from '@/lib/write-guard'
import { getCircuitState, openCircuit } from '@/lib/safety-circuit'
import { sendWriteSpikeAlertEmail } from '@/lib/admin-alerts'
import crypto from 'crypto'

let checkinIssuesReady = false

async function ensureCheckinIssuesTable() {
  if (checkinIssuesReady) return
  await prisma.$executeRawUnsafe(`
    CREATE TABLE IF NOT EXISTS CheckinIssues (
      id TEXT PRIMARY KEY,
      userId TEXT NOT NULL,
      name TEXT NOT NULL,
      polarity TEXT NOT NULL,
      UNIQUE (userId, name)
    )
  `)
  // Remove historical duplicates before creating unique index
  await prisma.$executeRawUnsafe(`
    DELETE FROM CheckinIssues a
    USING CheckinIssues b
    WHERE a.id > b.id AND a.userId = b.userId AND a.name = b.name
  `)
  // Ensure composite unique index exists even if table was created earlier without it
  await prisma.$executeRawUnsafe(`
    CREATE UNIQUE INDEX IF NOT EXISTS checkinissues_user_name_idx ON CheckinIssues (userId, name)
  `)
  checkinIssuesReady = true
}

export async function GET() {
  const session = await getServerSession(authOptions)
  if (!session?.user?.email) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  const user = await prisma.user.findUnique({ where: { email: session.user.email } })
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  try {
    await ensureCheckinIssuesTable()
    const rows: any[] = await prisma.$queryRawUnsafe(`SELECT id, name, polarity FROM CheckinIssues WHERE userId = $1`, user.id)
    return NextResponse.json({ issues: rows })
  } catch {
    return NextResponse.json({ issues: [] })
  }
}

export async function POST(req: NextRequest) {
  const session = await getServerSession(authOptions)
  if (!session?.user?.email) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  const user = await prisma.user.findUnique({ where: { email: session.user.email } })
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  const { issues } = (await req.json()) as { issues: Array<{ name: string; polarity?: 'positive' | 'negative' }> }
  const safeIssues = Array.isArray(issues) ? issues : []

  try {
    // If a runaway loop was detected elsewhere, pause only this specific save action.
    const circuit = await getCircuitState('health-setup-saves')
    if (circuit.open) {
      return NextResponse.json(
        {
          error:
            'Health setup saving is temporarily paused due to unusually high activity. Please try again in a few minutes.',
          paused: true,
          openUntil: circuit.openUntil?.toISOString() || null,
          reason: circuit.reason || null,
        },
        { status: 503 }
      )
    }

    await ensureCheckinIssuesTable()

    // Write guard: skip repeated identical saves (prevents runaway client loops).
    const normalizedNames = Array.isArray(issues)
      ? issues.map((i) => String(i?.name || '').trim()).filter(Boolean).sort()
      : []
    const payloadHash = hashPayload({ names: normalizedNames })
    const writeGuard = createWriteGuard(prisma)
    const guardResult = await writeGuard.readGuard({
      ownerKey: user.id,
      scope: 'checkins:issues',
      payloadHash,
      windowMs: 90 * 1000,
    })
    if (guardResult.skip) {
      if (guardResult.hitCount === 25) {
        const recipientEmail =
          ((process.env.OWNER_EMAIL || 'support@helfi.ai') as string).trim() || 'support@helfi.ai'
        openCircuit({
          scope: 'health-setup-saves',
          minutes: 10,
          reason: `Runaway checkins/issues saves detected (repeat payload x${guardResult.hitCount} within ~90s).`,
        }).catch(() => {})
        sendWriteSpikeAlertEmail({
          recipientEmail,
          subject: 'Helfi runaway protection activated',
          html: `
            <div style="font-family: Arial, sans-serif; line-height: 1.5; color: #111827;">
              <h2 style="margin: 0 0 12px 0;">Runaway protection activated</h2>
              <p style="margin: 0 0 12px 0;">
                We detected a burst of repeated health setup issue saves (same data sent many times quickly).
              </p>
              <p style="margin: 0 0 12px 0;">
                Action taken: health setup saves are paused for ~10 minutes to prevent a database spike.
              </p>
              <p style="margin: 0 0 12px 0;"><strong>User:</strong> ${String(session?.user?.email || '')}</p>
              <p style="margin: 0 0 12px 0;"><strong>Repeat count:</strong> ${guardResult.hitCount}</p>
            </div>
          `,
        }).catch((error) => {
          console.error('[runaway protection] alert email failed', error)
        })
      }

      return NextResponse.json({ success: true, skipped: true, reason: 'repeat_write_guard' })
    }

    // Replace saved list with exactly what client sent
    const names = safeIssues.map((i) => String(i?.name || '').trim()).filter(Boolean)
    if (names.length === 0) {
      await prisma.$executeRawUnsafe(`DELETE FROM CheckinIssues WHERE userId = $1`, user.id)
    } else {
      const placeholders = names.map((_, idx) => `$${idx + 2}`).join(',')
      await prisma.$executeRawUnsafe(
        `DELETE FROM CheckinIssues WHERE userId = $1 AND name NOT IN (${placeholders})`,
        user.id, ...names
      )
    }

    for (const item of issues) {
      const name = String(item.name || '').trim()
      if (!name) continue
      const polarity = (item.polarity === 'negative' || /pain|ache|anxiety|depress|fatigue|nausea|bloat|insomnia|brain fog|headache|migraine|cramp|stress|itch|rash|acne|diarrh|constipat|gas|heartburn/i.test(name)) ? 'negative' : 'positive'
      const id = crypto.randomUUID()
      // Use queryRawUnsafe for broad compatibility; ON CONFLICT upserts by (userId,name)
      await prisma.$queryRawUnsafe(
        `INSERT INTO CheckinIssues (id, userId, name, polarity) VALUES ($1,$2,$3,$4)
         ON CONFLICT (userId, name) DO UPDATE SET polarity=EXCLUDED.polarity`,
        id, user.id, name, polarity
      )
    }
    return NextResponse.json({ success: true })
  } catch (e) {
    console.error('checkins issues save error', e)
    return NextResponse.json({ error: (e as any)?.message || 'Failed to save issues' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { getCheckinUser } from '@/app/api/checkins/_auth'

// Delete a single rating entry
export async function DELETE(req: NextRequest) {
  const user = await getCheckinUser(req)
  if (!user) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { searchParams } = new URL(req.url)
  const date = searchParams.get('date')
  const issueId = searchParams.get('issueId')

  if (!date || !issueId) {
    return NextResponse.json({ error: 'Missing date or issueId' }, { status: 400 })
  }

  try {
    await prisma.$executeRawUnsafe(
      `DELETE FROM CheckinRatings WHERE userId = $1 AND date = $2 AND issueId = $3`,
      user.id, date, issueId
    )
    return NextResponse.json({ success: true })
  } catch (e) {
    console.error('delete rating error', e)
    return NextResponse.json({ error: 'Failed to delete rating' }, { status: 500 })
  }
}

// Update a rating entry
export async function PATCH(req: NextRequest) {
  const user = await getCheckinUser(req)
  if (!user) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const body = await req.json().catch(() => ({}))
  const { date, issueId, value, note } = body

  if (!date || !issueId) {
    return NextResponse.json({ error: 'Missing date or issueId' }, { status: 400 })
  }

  try {
    const clamped = (value === null || value === undefined) ? null : Math.max(0, Math.min(6, Number(value)))
    // Use INSERT ... ON CONFLICT to handle both update and insert
    await prisma.$executeRawUnsafe(
      `INSERT INTO CheckinRatings (userId, issueId, date, value, note)
       VALUES ($1, $2, $3, $4, $5)
       ON CONFLICT (userId, issueId, date) DO UPDATE SET value = EXCLUDED.value, note = EXCLUDED.note`,
      user.id, issueId, date, clamped, String(note || '')
    )
    return NextResponse.json({ success: true })
  } catch (e) {
    console.error('update rating error', e)
    return NextResponse.json({ error: 'Failed to update rating' }, { status: 500 })
  }
}

// Delete multiple ratings (by issue or all)
export async function POST(req: NextRequest) {
  const user = await getCheckinUser(req)
  if (!user) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const body = await req.json().catch(() => ({}))
  const { action, issueIds } = body

  if (action === 'delete-all') {
    try {
      await prisma.$executeRawUnsafe(`DELETE FROM CheckinRatings WHERE userId = $1`, user.id)
      return NextResponse.json({ success: true })
    } catch (e) {
      console.error('delete all ratings error', e)
      return NextResponse.json({ error: 'Failed to delete all ratings' }, { status: 500 })
    }
  }

  if (action === 'delete-by-issues' && Array.isArray(issueIds) && issueIds.length > 0) {
    try {
      const placeholders = issueIds.map((_, i) => `$${i + 2}`).join(',')
      await prisma.$executeRawUnsafe(
        `DELETE FROM CheckinRatings WHERE userId = $1 AND issueId IN (${placeholders})`,
        user.id, ...issueIds
      )
      return NextResponse.json({ success: true })
    } catch (e) {
      console.error('delete by issues error', e)
      return NextResponse.json({ error: 'Failed to delete ratings' }, { status: 500 })
    }
  }

  return NextResponse.json({ error: 'Invalid action' }, { status: 400 })
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'
import { prisma } from '@/lib/prisma'
import { publishWithQStash, scheduleAllActiveReminders } from '@/lib/qstash'
import { ensureCheckinTables } from '@/app/api/checkins/_db'
import { isSubscriptionActive } from '@/lib/subscription-utils'

async function getCheckinSettingsUser(req: NextRequest) {
  const nativeUserId = await getUserIdFromNativeAuth(req)
  if (nativeUserId) {
    return prisma.user.findUnique({
      where: { id: nativeUserId },
      include: { subscription: true, creditTopUps: true },
    })
  }

  const session = await getServerSession(authOptions)
  const email = String(session?.user?.email || '').trim().toLowerCase()
  if (!email) return null
  return prisma.user.findUnique({
    where: { email },
    include: { subscription: true, creditTopUps: true },
  })
}

export async function GET(req: NextRequest) {
  const user = await getCheckinSettingsUser(req)
  if (!user) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  await ensureCheckinTables()
  const now = new Date()
  const hasSubscription = isSubscriptionActive(user.subscription, now)
  const hasPurchasedCredits = (user.creditTopUps || []).some(
    (topUp: any) => topUp.expiresAt > now && (topUp.amountCents - topUp.usedCents) > 0
  )
  const isPaidUser = hasSubscription || hasPurchasedCredits
  const maxFrequency = isPaidUser ? 4 : 1

  const rows: Array<{
    enabled: boolean
    time1: string
    time2: string
    time3: string
    time4: string
    timezone: string
    frequency: number
  }> = await prisma.$queryRawUnsafe(
    `SELECT enabled, time1, time2, time3, time4, timezone, frequency FROM CheckinSettings WHERE userId = $1`,
    user.id
  )

  if (rows.length > 0) {
    const row = rows[0]
    return NextResponse.json({
      ...row,
      frequency: Math.min(Math.max(1, row.frequency), maxFrequency),
      maxFrequency,
      isPaidUser,
    })
  }

  const defaultFrequency = Math.min(3, maxFrequency)
  return NextResponse.json({
    enabled: true,
    time1: '12:30',
    time2: '18:30',
    time3: '21:30',
    time4: '09:00',
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || 'Australia/Melbourne',
    frequency: defaultFrequency,
    maxFrequency,
    isPaidUser,
  })
}

export async function POST(req: NextRequest) {
  const user = await getCheckinSettingsUser(req)
  if (!user) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const body = await req.json().catch(() => ({}))
  let { enabled, time1, time2, time3, time4, timezone, frequency } = body as any

  const normalizeTime = (input?: string, defaultValue: string = '21:00'): string => {
    if (!input) return defaultValue
    const s = String(input).trim().toLowerCase()
    const m24 = s.match(/^([01]?\d|2[0-3]):([0-5]\d)$/)
    if (m24) return `${m24[1].padStart(2, '0')}:${m24[2]}`
    const m12 = s.match(/^([0-1]?\d):([0-5]\d)\s*(am|pm)$/)
    if (m12) {
      let h = parseInt(m12[1], 10)
      const mm = m12[2]
      const ap = m12[3]
      if (ap === 'pm' && h !== 12) h += 12
      if (ap === 'am' && h === 12) h = 0
      return `${String(h).padStart(2, '0')}:${mm}`
    }
    const digits = s.replace(/[^0-9]/g, '')
    if (digits.length >= 3) {
      const h = parseInt(digits.slice(0, digits.length - 2), 10)
      const mm = parseInt(digits.slice(-2), 10)
      return `${String(Math.max(0, Math.min(23, h))).padStart(2, '0')}:${String(
        Math.max(0, Math.min(59, mm))
      ).padStart(2, '0')}`
    }
    return defaultValue
  }

  enabled = typeof enabled === 'boolean' ? enabled : true
  time1 = normalizeTime(time1, '12:30')
  time2 = normalizeTime(time2, '18:30')
  time3 = normalizeTime(time3, '21:30')
  time4 = normalizeTime(time4, '09:00')
  timezone =
    (timezone && String(timezone).trim()) ||
    Intl.DateTimeFormat().resolvedOptions().timeZone ||
    'Australia/Melbourne'

  const now = new Date()
  const hasSubscription = isSubscriptionActive(user.subscription, now)
  const hasPurchasedCredits = (user.creditTopUps || []).some(
    (topUp: any) => topUp.expiresAt > now && (topUp.amountCents - topUp.usedCents) > 0
  )
  const isPaidUser = hasSubscription || hasPurchasedCredits
  const maxFrequency = isPaidUser ? 4 : 1
  frequency = Math.max(1, Math.min(maxFrequency, parseInt(String(frequency || 1), 10)))

  try {
    await ensureCheckinTables()
    console.log('Saving CheckinSettings for', user.id, { enabled, time1, time2, time3, timezone, frequency })

    await prisma.$queryRawUnsafe(
      `INSERT INTO CheckinSettings (userId, enabled, time1, time2, time3, time4, timezone, frequency)
       VALUES ($1,$2,$3,$4,$5,$6,$7,$8)
       ON CONFLICT (userId) DO UPDATE SET 
         enabled=EXCLUDED.enabled,
         time1=EXCLUDED.time1, 
         time2=EXCLUDED.time2, 
         time3=EXCLUDED.time3, 
         time4=EXCLUDED.time4,
         timezone=EXCLUDED.timezone,
         frequency=EXCLUDED.frequency`,
      user.id,
      enabled,
      time1,
      time2,
      time3,
      time4,
      timezone,
      frequency
    )

    const scheduleResults = enabled
      ? await scheduleAllActiveReminders(user.id, { time1, time2, time3, time4, timezone, frequency }).catch(
          (error) => {
            console.error('[CHECKINS] Failed to schedule reminders via QStash', error)
            return []
          }
        )
      : []

    const failedSchedules = scheduleResults.filter((result) => !result.scheduled)
    if (failedSchedules.length > 0) {
      console.error('[CHECKINS] QStash scheduling failures detected', { failedSchedules })
    }

    try {
      if (!enabled) {
        return NextResponse.json({ success: true, scheduleResults })
      }
      const currentTime = new Date()
      const fmt = new Intl.DateTimeFormat('en-GB', {
        timeZone: timezone,
        hour: '2-digit',
        minute: '2-digit',
        hour12: false,
      })
      const parts = fmt.formatToParts(currentTime)
      const ch = parseInt(parts.find((p) => p.type === 'hour')?.value || '0', 10)
      const cm = parseInt(parts.find((p) => p.type === 'minute')?.value || '0', 10)
      const currentTotal = ch * 60 + cm
      const sendWindowMinutes = 5
      const candidates: string[] = []
      if (frequency >= 1) candidates.push(time1)
      if (frequency >= 2) candidates.push(time2)
      if (frequency >= 3) candidates.push(time3)
      if (frequency >= 4) candidates.push(time4)
      for (const t of candidates) {
        const [hh, mm] = t.split(':').map((v) => parseInt(v, 10))
        const target = hh * 60 + mm
        let diff = currentTotal - target
        if (diff < 0) diff += 1440
        if (diff >= 0 && diff <= sendWindowMinutes) {
          const publishResult = await publishWithQStash('/api/push/dispatch', {
            userId: user.id,
            reminderTime: t,
            timezone,
          }).catch(() => ({ ok: false, reason: 'exception' }))
          if (!publishResult?.ok) {
            console.warn('[CHECKINS] Failed to enqueue immediate reminder via QStash', {
              userId: user.id,
              reminderTime: t,
              reason: publishResult?.reason,
            })
          }
          break
        }
      }
    } catch {}

    return NextResponse.json({ success: true, scheduleResults })
  } catch (e) {
    console.error('checkins settings save error', e)
    const message = e instanceof Error ? e.message : 'Unknown error'
    return NextResponse.json({ error: 'Failed to save settings', detail: message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
