  try {
    const url = new URL(_req.url)
    const featureParam = (url.searchParams.get('feature') || '').trim()
    debugStage = 'resolve-session'

    debugStage = 'load-user'
    const user = await getFeatureUsageUser(_req)

    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    if (featureParam) {
      logServerCall({
        feature: featureParam,
        endpoint: '/api/credit/feature-usage',
        kind: 'feature_usage',
      }).catch((error) => {
        console.error('❌ Failed to log feature usage call:', error)
      })
    }

    const hasSubscription = isSubscriptionActive(user.subscription)

    debugStage = 'prepare-counts'
    const foodMonthly = user.monthlyFoodAnalysisUsed || 0

    const symptomMonthly = user.monthlySymptomAnalysisUsed || 0
    const symptomAnalysisLifetime = Math.max(
      0,
      (user.totalAnalysisCount || 0) -
        (user.totalFoodAnalysisCount || 0) -
        (user.totalInteractionAnalysisCount || 0)
    )
    const symptomLabel: 'monthly' | 'total' = symptomMonthly > 0 ? 'monthly' : 'total'
    const symptomCount = symptomLabel === 'monthly' ? symptomMonthly : symptomAnalysisLifetime

    const interactionMonthly = user.monthlyInteractionAnalysisUsed || 0
    const interactionLifetime = user.totalInteractionAnalysisCount || 0

    const medicalMonthly = user.monthlyMedicalImageAnalysisUsed || 0
    const insightsMonthly = user.monthlyInsightsGenerationUsed || 0

    // Health tips usage (no counters; derive from usage events)
    const startOfUtcMonth = (() => {
      const now = new Date()
      return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1, 0, 0, 0, 0))
    })()
    const healthTipsMonthly = await prisma.aIUsageEvent.count({
      where: {
        userId: user.id,
        success: true,
        createdAt: { gte: startOfUtcMonth },
        feature: { startsWith: 'health-tips:' },
      },
    })

    const featureUsage: any = {
      symptomAnalysis: {
        count: symptomCount,
        costPerUse: CREDIT_COSTS.SYMPTOM_ANALYSIS,
        label: symptomLabel,
      },
      foodAnalysis: {
        count: foodMonthly,
        costPerUse: CREDIT_COSTS.FOOD_ANALYSIS,
        label: 'monthly',
      },
      interactionAnalysis: {
        count: interactionMonthly > 0 ? interactionMonthly : interactionLifetime,
        costPerUse: CREDIT_COSTS.INTERACTION_ANALYSIS,
        label: interactionMonthly > 0 ? 'monthly' : 'total',
      },
      medicalImageAnalysis: {
        count: medicalMonthly,
        costPerUse: CREDIT_COSTS.MEDICAL_IMAGE_ANALYSIS,
        label: medicalMonthly > 0 ? 'monthly' : 'total',
      },
      insightsGeneration: {
        count: insightsMonthly,
        costPerUse: CREDIT_COSTS.INSIGHTS_GENERATION,
        label: insightsMonthly > 0 ? 'monthly' : 'total',
      },
      healthTips: {
        count: healthTipsMonthly,
        costPerUse: 0,
        label: 'monthly',
        totalCredits: 0,
      },
    }

    return NextResponse.json({
      debugStage: 'success',
      schemaVersion: 3,
      featureUsage,
      hasSubscription,
      actualCreditsUsed: user.walletMonthlyUsedCents || 0,
    })
  } catch (err: any) {
    console.error('Error fetching feature usage:', err)
    // Degrade gracefully: return zeros so UI can still render without errors.
    return NextResponse.json({
      debugStage,
      schemaVersion: 2,
      featureUsage: {
        symptomAnalysis: {
          count: 0,
          costPerUse: CREDIT_COSTS.SYMPTOM_ANALYSIS,
          label: 'total',
        },
        foodAnalysis: {
          count: 0,
          costPerUse: CREDIT_COSTS.FOOD_ANALYSIS,
          label: 'total',
        },
        interactionAnalysis: {
          count: 0,
          costPerUse: CREDIT_COSTS.INTERACTION_ANALYSIS,
          label: 'total',
        },
        medicalImageAnalysis: {
          count: 0,
          costPerUse: CREDIT_COSTS.MEDICAL_IMAGE_ANALYSIS,
          label: 'total',
        },
        insightsGeneration: {
          count: 0,
          costPerUse: CREDIT_COSTS.INSIGHTS_GENERATION,
          label: 'total',
        },
        healthTips: {
          count: 0,
          costPerUse: 0,
          label: 'total',
          totalCredits: 0,
        },
      },
      hasSubscription: false,
      actualCreditsUsed: 0,
      degraded: true,
      errorType: err?.name || 'UnknownError',
      errorMessage: err?.message || 'Unknown error',
    })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { getToken } from 'next-auth/jwt'
import { authOptions } from '@/lib/auth'
import { getFreeCreditsStatus, hasExhaustedFreeCredits } from '@/lib/free-credits'
import { prisma } from '@/lib/prisma'
import { isSubscriptionActive } from '@/lib/subscription-utils'
import { CreditManager, computeNextWalletResetAt } from '@/lib/credit-system'
import { logServerCall } from '@/lib/server-call-tracker'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'

// ABSOLUTE GUARD RAIL:
// This endpoint powers the "Credits remaining" bar. Do NOT change credit
// calculation rules or disable billing here without:
//   1) Reading `GUARD_RAILS.md` (credits section), and
//   2) Getting explicit written approval from the user.
//
// This API must always be dynamic because it depends on per-request auth headers.
export const dynamic = 'force-dynamic'
export const revalidate = 0

// Direct mapping of subscription price → monthly wallet credits
// Mirrors CreditManager.SUBSCRIPTION_CREDITS_MAP but kept local here to
// avoid depending on wallet internals (display‑only endpoint).
const SUBSCRIPTION_CREDITS_MAP: Record<number, number> = {
  1000: 700,  // $10/month → 700 credits
  2000: 1400, // $20/month → 1,400 credits
  3000: 2100, // $30/month → 2,100 credits
  5000: 3500, // $50/month → 3,500 credits
}

function creditsForSubscriptionPrice(monthlyPriceCents: number | null | undefined): number {
  if (!monthlyPriceCents) return 0
  if (SUBSCRIPTION_CREDITS_MAP[monthlyPriceCents]) {
    return SUBSCRIPTION_CREDITS_MAP[monthlyPriceCents]
  }
  // Fallback: 50% of price as credits if an unknown tier appears
  const percent = Number(process.env.HELFI_WALLET_PLAN_PERCENT || '0.5')
  const safePercent = percent > 0 && percent <= 1 ? percent : 0.5
  return Math.floor(monthlyPriceCents * safePercent)
}

function monthlyCapFromSubscription(sub: any | null | undefined): number {
  if (!isSubscriptionActive(sub)) return 0
  if (sub.monthlyPriceCents != null) {
    return creditsForSubscriptionPrice(sub.monthlyPriceCents)
  }
  // Defensive fallback by plan name if price is missing
  if (sub.plan === 'PREMIUM') return SUBSCRIPTION_CREDITS_MAP[2000] || 1000
  return 0
}

function computeNextResetAt(subscriptionStart: Date | null): string | null {
  try {
    const nextReset = computeNextWalletResetAt(subscriptionStart, new Date())
    return nextReset ? nextReset.toISOString() : null
  } catch {
    return null
  }
}

export async function GET(_req: NextRequest) {
  let debugStage = 'start'
  try {
    const url = new URL(_req.url)
    const featureParam = (url.searchParams.get('feature') || '').trim()
    // 1) Resolve current user (session or JWT fallback)
    debugStage = 'resolve-session'
    let session = await getServerSession(authOptions)
    let userEmail: string | null = session?.user?.email ?? null
    let userId: string | null = session?.user?.id ?? null

    if (!userEmail || !userId) {
      try {
        const token = await getToken({
          req: _req,
          secret: process.env.NEXTAUTH_SECRET || process.env.AUTH_SECRET || 'helfi-secret-key-production-2024',
        })
        if (!userEmail && token?.email) {
          userEmail = String(token.email)
        }
        if (!userId && typeof token?.sub === 'string') userId = token.sub
        if (!userId && typeof (token as any)?.id === 'string') userId = String((token as any).id)
      } catch (tokenError) {
        console.error('/api/credit/status - JWT fallback failed:', tokenError)
      }
    }

    if (!userId) {
      userId = await getUserIdFromNativeAuth(_req)
    }

    if (!userEmail && !userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    // 2) Load user with all fields needed for wallet + legacy credits
    debugStage = 'load-user'
    const user = await prisma.user.findUnique({
      where: userId ? { id: userId } : { email: userEmail as string },
      select: {
        id: true,
        // Legacy daily/additional credits
        dailyAnalysisCredits: true,
        dailyAnalysisUsed: true,
        additionalCredits: true,
        // Wallet + subscription
        walletMonthlyUsedCents: true,
        subscription: {
          select: {
            plan: true,
            monthlyPriceCents: true,
            startDate: true,
            endDate: true,
          },
        },
        // Free credits
        freeFoodAnalysisRemaining: true,
        freeSymptomAnalysisRemaining: true,
        freeMedicalAnalysisRemaining: true,
        freeInteractionAnalysisRemaining: true,
        freeHealthIntakeRemaining: true,
        freeInsightsUpdateRemaining: true,
        creditTopUps: {
          select: {
            id: true,
            amountCents: true,
            usedCents: true,
            expiresAt: true,
          },
        },
      },
    })

    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    if (featureParam) {
      logServerCall({
        feature: featureParam,
        endpoint: '/api/credit/status',
        kind: 'credit_status',
      }).catch((error) => {
        console.error('❌ Failed to log credit status call:', error)
      })
    }

    const now = new Date()
    const isPremium = isSubscriptionActive(user.subscription)

    // 3) Wallet‑style credits (subscription + top‑ups + manual additional credits)
    // Use CreditManager so monthly reset happens automatically when due.
    debugStage = 'wallet-calc'
    const wallet = await new CreditManager(user.id).getWalletStatus().catch(() => null)
    const monthlyCapCents = wallet?.monthlyCapCents ?? monthlyCapFromSubscription(user.subscription)
    const monthlyUsedCents = wallet?.monthlyUsedCents ?? (user.walletMonthlyUsedCents || 0)
    const monthlyRemainingCents = wallet?.monthlyRemainingCents ?? Math.max(0, monthlyCapCents - monthlyUsedCents)

    const activeTopUps = (user.creditTopUps || []).filter((t) => t.expiresAt > now)
    const topUpsTotalAvailable = wallet
      ? wallet.topUps.reduce((sum, t) => sum + Math.max(0, t.availableCents), 0)
      : activeTopUps.reduce((sum, t) => sum + Math.max(0, t.amountCents - t.usedCents), 0)
    const topUpsTotalPurchased = activeTopUps.reduce((sum, t) => sum + t.amountCents, 0)
    const topUpsTotalUsed = activeTopUps.reduce((sum, t) => sum + t.usedCents, 0)
    const additionalAvailable = wallet?.additionalCreditsCents ?? Math.max(0, user.additionalCredits || 0)

    const totalAvailableCents = wallet?.totalAvailableCents ?? (monthlyRemainingCents + topUpsTotalAvailable + additionalAvailable)

    let percentUsed = wallet?.percentUsed ?? 0
    if (!wallet && monthlyCapCents > 0) {
      percentUsed = Math.min(100, Math.floor((monthlyUsedCents / monthlyCapCents) * 100))
    } else if (!wallet && topUpsTotalPurchased > 0) {
      percentUsed = Math.min(100, Math.floor((topUpsTotalUsed / topUpsTotalPurchased) * 100))
    }

    // 4) Legacy daily/additional credits (for truly free accounts)
    debugStage = 'legacy-calc'
    const dailyRemainingLegacy = Math.max(
      0,
      (user.dailyAnalysisCredits || 0) - (user.dailyAnalysisUsed || 0)
    )
    const additionalRemainingLegacy = user.additionalCredits || 0
    const legacyTotal = dailyRemainingLegacy + additionalRemainingLegacy

    // For subscription / wallet users, show wallet credits.
    // For non‑subscription users without wallet credits, fall back to legacy.
    const hasWalletCredits = totalAvailableCents > 0
    const showLegacy = !isPremium && !hasWalletCredits

    const creditsTotal = showLegacy ? legacyTotal : totalAvailableCents

    debugStage = 'compute-reset'
    const refreshAt = computeNextResetAt(isPremium ? user.subscription?.startDate ?? null : null)

    // Get free credits status. If this optional part fails, keep returning the
    // paid wallet status so real paid users are not blocked by Talk to Helfi.
    let freeCreditsStatus: Awaited<ReturnType<typeof getFreeCreditsStatus>> | null = null
    let exhaustedFreeCredits = false
    let freeCreditsUnavailable = false
    try {
      freeCreditsStatus = await getFreeCreditsStatus(user.id)
      exhaustedFreeCredits = await hasExhaustedFreeCredits(user.id)
    } catch (freeCreditError) {
      freeCreditsUnavailable = true
      console.error('/api/credit/status - free credit status failed:', freeCreditError)
    }

    return NextResponse.json({
      schemaVersion: 2,
      debugStage: 'success',
      percentUsed,
      refreshAt,
      plan: isPremium ? user.subscription?.plan ?? null : null,
      // Any authenticated user can see the meter; billing enforcement happens in
      // the analyzer APIs.
      hasAccess: true,
      monthlyCapCents,
      monthlyUsedCents,
      topUps: wallet
        ? wallet.topUps
        : activeTopUps.map((t) => ({
            id: t.id,
            availableCents: Math.max(0, t.amountCents - t.usedCents),
            expiresAt: t.expiresAt,
          })),
      additionalAvailableCents: additionalAvailable,
      totalAvailableCents,
      credits: {
        total: creditsTotal,
        dailyRemaining: showLegacy ? dailyRemainingLegacy : 0,
        additionalRemaining: additionalAvailable,
      },
      freeCredits: freeCreditsStatus,
      exhaustedFreeCredits,
      freeCreditsUnavailable,
    })
  } catch (err: any) {
    console.error('Error in /api/credit/status:', err)
    // Degrade gracefully: zero credits but keep shape stable so UI can render.
    return NextResponse.json({
      schemaVersion: 2,
      debugStage,
      percentUsed: 0,
      refreshAt: null,
      plan: null,
      hasAccess: false,
      monthlyCapCents: 0,
      monthlyUsedCents: 0,
      topUps: [],
      additionalAvailableCents: 0,
      totalAvailableCents: 0,
      credits: {
        total: 0,
        dailyRemaining: 0,
        additionalRemaining: 0,
      },
      degraded: true,
      errorType: err?.name || 'UnknownError',
      errorMessage: err?.message || 'Unknown error',
    })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { CREDIT_COSTS } from '@/lib/credit-system'
import { isSubscriptionActive } from '@/lib/subscription-utils'

// Guard rail: this endpoint is for diagnostics/admin use only. It should not be
// changed to "patch over" wallet bugs; fix the underlying credit logic instead.
//
// Usage breakdown reads per-user data and must be dynamic.
export const dynamic = 'force-dynamic'
export const revalidate = 0

export async function GET(_req: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.email) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const user = await prisma.user.findUnique({
      where: { email: session.user.email },
      select: {
        id: true,
        walletMonthlyUsedCents: true,
        monthlySymptomAnalysisUsed: true,
        monthlyFoodAnalysisUsed: true,
        monthlyMedicalImageAnalysisUsed: true,
        monthlyInteractionAnalysisUsed: true,
        totalFoodAnalysisCount: true,
        totalInteractionAnalysisCount: true,
        subscription: {
          select: {
            plan: true,
            startDate: true,
            endDate: true,
          },
        },
        creditTopUps: {
          select: {
            purchasedAt: true,
            expiresAt: true,
          },
          orderBy: {
            purchasedAt: 'desc',
          },
        },
      },
    })

    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    // Calculate the start date for monthly counting (same logic as feature-usage)
    let monthlyStartDate: Date | null = null

    const hasActiveSubscription = isSubscriptionActive(user.subscription)
    if (hasActiveSubscription && user.subscription?.startDate) {
      const subStartDate = new Date(user.subscription.startDate)
      const now = new Date()

      const startYear = subStartDate.getUTCFullYear()
      const startMonth = subStartDate.getUTCMonth()
      const startDay = subStartDate.getUTCDate()

      const currentYear = now.getUTCFullYear()
      const currentMonth = now.getUTCMonth()
      const currentDay = now.getUTCDate()

      let monthsSinceStart = (currentYear - startYear) * 12 + (currentMonth - startMonth)

      if (currentDay < startDay) {
        monthsSinceStart--
      }

      monthlyStartDate = new Date(Date.UTC(startYear, startMonth + monthsSinceStart, startDay, 0, 0, 0, 0))

      if (monthlyStartDate > now) {
        monthsSinceStart--
        monthlyStartDate = new Date(Date.UTC(startYear, startMonth + monthsSinceStart, startDay, 0, 0, 0, 0))
      }
    } else if (user.creditTopUps && user.creditTopUps.length > 0) {
      const mostRecentTopUp = user.creditTopUps[0]
      if (mostRecentTopUp && mostRecentTopUp.expiresAt > new Date()) {
        const purchaseDate = new Date(mostRecentTopUp.purchasedAt)
        const now = new Date()

        const purchaseYear = purchaseDate.getUTCFullYear()
        const purchaseMonth = purchaseDate.getUTCMonth()
        const purchaseDay = purchaseDate.getUTCDate()

        const currentYear = now.getUTCFullYear()
        const currentMonth = now.getUTCMonth()
        const currentDay = now.getUTCDate()

        let monthsSincePurchase = (currentYear - purchaseYear) * 12 + (currentMonth - purchaseMonth)

        if (currentDay < purchaseDay) {
          monthsSincePurchase--
        }

        monthlyStartDate = new Date(Date.UTC(purchaseYear, purchaseMonth + monthsSincePurchase, purchaseDay, 0, 0, 0, 0))

        if (monthlyStartDate > now) {
          monthsSincePurchase--
          monthlyStartDate = new Date(Date.UTC(purchaseYear, purchaseMonth + monthsSincePurchase, purchaseDay, 0, 0, 0, 0))
        }
      }
    }

    // Query actual usage from database since monthlyStartDate
    const breakdown: any = {
      schemaVersion: 1,
      monthlyStartDate: monthlyStartDate?.toISOString() || null,
      walletMonthlyUsedCents: user.walletMonthlyUsedCents || 0,
      features: {},
    }

    if (monthlyStartDate) {
      // Count FoodLog entries (food analysis)
      const foodLogCount = await prisma.foodLog.count({
        where: {
          userId: user.id,
          createdAt: {
            gte: monthlyStartDate,
          },
        },
      })
      breakdown.features.foodAnalysis = {
        count: foodLogCount,
        costPerUse: CREDIT_COSTS.FOOD_ANALYSIS,
        totalCredits: foodLogCount * CREDIT_COSTS.FOOD_ANALYSIS,
      }

      // Count InteractionAnalysis entries
      const interactionCount = await prisma.interactionAnalysis.count({
        where: {
          userId: user.id,
          createdAt: {
            gte: monthlyStartDate,
          },
        },
      })
      breakdown.features.interactionAnalysis = {
        count: interactionCount,
        costPerUse: CREDIT_COSTS.INTERACTION_ANALYSIS,
        totalCredits: interactionCount * CREDIT_COSTS.INTERACTION_ANALYSIS,
      }

      // For symptom notes, we need to check if there's a way to track them
      // Since there's no SymptomAnalysis table, we'll use the monthly counter
      // but also check if there are any other records
      breakdown.features.symptomAnalysis = {
        count: user.monthlySymptomAnalysisUsed || 0,
        costPerUse: CREDIT_COSTS.SYMPTOM_ANALYSIS,
        totalCredits: (user.monthlySymptomAnalysisUsed || 0) * CREDIT_COSTS.SYMPTOM_ANALYSIS,
      }

      // Health image notes - check if there's a way to track this
      breakdown.features.medicalImageAnalysis = {
        count: user.monthlyMedicalImageAnalysisUsed || 0,
        costPerUse: CREDIT_COSTS.MEDICAL_IMAGE_ANALYSIS,
        totalCredits: (user.monthlyMedicalImageAnalysisUsed || 0) * CREDIT_COSTS.MEDICAL_IMAGE_ANALYSIS,
      }
    } else {
      // Fallback to monthly counters
      breakdown.features.foodAnalysis = {
        count: user.monthlyFoodAnalysisUsed || 0,
        costPerUse: CREDIT_COSTS.FOOD_ANALYSIS,
        totalCredits: (user.monthlyFoodAnalysisUsed || 0) * CREDIT_COSTS.FOOD_ANALYSIS,
      }
      breakdown.features.interactionAnalysis = {
        count: user.monthlyInteractionAnalysisUsed || 0,
        costPerUse: CREDIT_COSTS.INTERACTION_ANALYSIS,
        totalCredits: (user.monthlyInteractionAnalysisUsed || 0) * CREDIT_COSTS.INTERACTION_ANALYSIS,
      }
      breakdown.features.symptomAnalysis = {
        count: user.monthlySymptomAnalysisUsed || 0,
        costPerUse: CREDIT_COSTS.SYMPTOM_ANALYSIS,
        totalCredits: (user.monthlySymptomAnalysisUsed || 0) * CREDIT_COSTS.SYMPTOM_ANALYSIS,
      }
      breakdown.features.medicalImageAnalysis = {
        count: user.monthlyMedicalImageAnalysisUsed || 0,
        costPerUse: CREDIT_COSTS.MEDICAL_IMAGE_ANALYSIS,
        totalCredits: (user.monthlyMedicalImageAnalysisUsed || 0) * CREDIT_COSTS.MEDICAL_IMAGE_ANALYSIS,
      }
    }

    // Calculate total expected credits
    const totalExpectedCredits = Object.values(breakdown.features).reduce(
      (sum: number, feature: any) => sum + (feature.totalCredits || 0),
      0
    )

    // Note: Food reanalyses and insights chat also charge credits but aren't tracked in monthly counters
    // Food reanalyses: 1 credit each (tracked in dailyFoodReanalysisUsed but not monthly)
    // Insights chat: Variable cost based on actual API usage

    breakdown.summary = {
      totalExpectedCredits,
      walletMonthlyUsedCents: user.walletMonthlyUsedCents || 0,
      difference: (user.walletMonthlyUsedCents || 0) - totalExpectedCredits,
      note: 'Food reanalyses and insights chat also charge credits but are not included in monthly counters above',
    }

    return NextResponse.json(breakdown)
  } catch (err) {
    console.error('Error fetching usage breakdown:', err)
    return NextResponse.json({ error: 'server_error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function GET(request: NextRequest) {
  const authHeader = request.headers.get('authorization')
  const expected = process.env.CRON_SECRET || process.env.SCHEDULER_SECRET

  if (!expected) {
    return NextResponse.json({ error: 'Scheduler secret is not configured' }, { status: 500 })
  }

  if (authHeader !== `Bearer ${expected}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const origin = new URL(request.url).origin
  const res = await fetch(`${origin}/api/admin/affiliates/payout-run`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...(expected ? { Authorization: `Bearer ${expected}` } : {}),
    },
    body: JSON.stringify({
      currency: 'usd',
      minThresholdCents: 5000,
      dryRun: false,
    }),
  })

  const data = await res.json().catch(() => ({}))
  if (!res.ok) {
    return NextResponse.json({ error: data?.error || 'Payout run failed' }, { status: res.status })
  }

  return NextResponse.json({ ok: true, result: data })
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { reportCriticalError } from '@/lib/error-reporter'

export const dynamic = 'force-dynamic'
export const runtime = 'nodejs'

const SUPPORT_ALERT_EMAIL = (process.env.SUPPORT_ALERT_EMAIL || 'support@helfi.ai').trim() || 'support@helfi.ai'

function isAuthorized(request: NextRequest) {
  const authHeader = request.headers.get('authorization') || ''
  const expected = process.env.SCHEDULER_SECRET || ''
  const vercelCronHeader = request.headers.get('x-vercel-cron')
  const isVercelCron = vercelCronHeader !== null
  return isVercelCron || (expected && authHeader === `Bearer ${expected}`)
}

export async function GET(request: NextRequest) {
  if (!isAuthorized(request)) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    await prisma.barcodeProduct.findFirst({ select: { barcode: true } })
    await prisma.foodLibraryItem.findFirst({ select: { id: true } })
