const resolveCountry = (value: string | null | undefined) => {
  const trimmed = String(value || '').trim().toUpperCase()
  return trimmed || null
}

export async function GET(request: NextRequest) {
  const vercelCronHeader = request.headers.get('x-vercel-cron')
  const isVercelCron = vercelCronHeader !== null
  const authHeader = request.headers.get('authorization')
  const expected = process.env.FOOD_MISSING_AUTOFILL_SECRET || process.env.SCHEDULER_SECRET

  if (!(isVercelCron || (expected && authHeader === `Bearer ${expected}`))) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const syncResult = await syncFastFoodMenus()

  const pendingReports = await prisma.foodMissingReport.findMany({
    where: { status: 'PENDING' },
    orderBy: { createdAt: 'asc' },
    take: 50,
  })

  let matched = 0
  let added = 0
  let skipped = 0

  for (const report of pendingReports) {
    const reportCountry = resolveCountry(report.country)
    const brand = report.brand || report.chain || null

    const menuMatch = findMenuMatchForReport({
      name: report.name,
      brand,
      country: reportCountry,
    })

    if (menuMatch) {
      const key = buildCustomFoodKey({
        name: menuMatch.name,
        brand: menuMatch.chain,
        kind: 'FAST_FOOD',
        country: menuMatch.country ?? null,
      })

      const customItem = await prisma.customFoodItem.findUnique({ where: { key } })

      if (customItem) {
        await prisma.foodMissingReport.update({
          where: { id: report.id },
          data: {
            status: 'ADDED',
            matchedCustomFoodId: customItem.id,
            processedAt: new Date(),
            processedNote: 'Matched to fast-food menu list',
          },
        })

        added += 1

        // Fire-and-forget email (do not await)
        sendAddedEmail({
          name: customItem.name,
          brand: customItem.brand,
          country: customItem.country,
          userEmail: report.userEmail,
        }).catch((error) => {
          console.error('❌ [MISSING FOOD AUTO-ADD] Error:', error)
        })
        continue
      }
    }

    const existing = await prisma.customFoodItem.findFirst({
      where: {
        kind: 'FAST_FOOD',
        name: report.name,
        ...(reportCountry ? { OR: [{ country: reportCountry }, { country: null }] } : {}),
        ...(brand ? { brand } : {}),
      },
    })

    if (existing) {
      await prisma.foodMissingReport.update({
        where: { id: report.id },
        data: {
          status: 'MATCHED',
          matchedCustomFoodId: existing.id,
          processedAt: new Date(),
          processedNote: 'Already available in custom foods',
        },
      })
      matched += 1
    } else {
      skipped += 1
    }
  }

  return NextResponse.json({
    ok: true,
    synced: syncResult,
    pending: pendingReports.length,
    matched,
    added,
    skipped,
  })
}

import { NextRequest, NextResponse } from 'next/server'
import { del, list } from '@vercel/blob'
import { prisma } from '@/lib/prisma'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const FOOD_PHOTO_PREFIX = 'food-photos/'

const getRetentionDays = () => {
  const raw = Number(process.env.FOOD_PHOTO_RETENTION_DAYS || 7)
  if (!Number.isFinite(raw) || raw < 1) return 7
  return Math.min(Math.round(raw), 3650)
}

const chunk = <T,>(items: T[], size: number) => {
  const result: T[][] = []
  for (let i = 0; i < items.length; i += size) {
    result.push(items.slice(i, i + size))
  }
  return result
}

export async function GET(request: NextRequest) {
  const vercelCronHeader = request.headers.get('x-vercel-cron')
  const isVercelCron = vercelCronHeader !== null
  const authHeader = request.headers.get('authorization')
  const expected = process.env.FOOD_PHOTO_CLEANUP_SECRET || process.env.SCHEDULER_SECRET

  if (!(isVercelCron || (expected && authHeader === `Bearer ${expected}`))) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  if (!process.env.BLOB_READ_WRITE_TOKEN) {
    return NextResponse.json({ error: 'Blob storage not configured' }, { status: 500 })
  }

  const retentionDays = getRetentionDays()
  const cutoffMs = Date.now() - retentionDays * 24 * 60 * 60 * 1000

  let cursor: string | undefined = undefined
  let scanned = 0
  let deleted = 0

  try {
    do {
      const result: Awaited<ReturnType<typeof list>> = await list({
        prefix: FOOD_PHOTO_PREFIX,
        limit: 1000,
        cursor,
      })
      cursor = result.cursor
      const expiredTargets = result.blobs
        .filter((blob) => {
          scanned += 1
          return blob.uploadedAt.getTime() < cutoffMs
        })
        .map((blob) => ({
          path: blob.pathname,
          url: blob.url,
        }))

      const uniquePaths = Array.from(new Set(expiredTargets.map((item) => item.path)))
      const batches = chunk(uniquePaths, 100)
      for (const batch of batches) {
        if (batch.length === 0) continue
        await del(batch)
        const batchSet = new Set(batch)
        const urlsForBatch = expiredTargets
          .filter((item) => batchSet.has(item.path))
          .map((item) => item.url)
        await prisma.foodLog.updateMany({
          where: {
            OR: [
              { imageUrl: { in: batch } },
              { imageUrl: { in: urlsForBatch } },
            ],
          },
          data: { imageUrl: null },
        })
        deleted += batch.length
      }
    } while (cursor)

    return NextResponse.json({
      ok: true,
      scanned,
      deleted,
      retentionDays,
    })
  } catch (error) {
    console.error('❌ Food photo cleanup failed', error)
    return NextResponse.json({ error: 'Cleanup failed' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { del, list } from '@vercel/blob'
import { prisma } from '@/lib/prisma'
import { ensureMoodTables } from '@/app/api/mood/_db'
import { extractScopedBlobPath } from '@/lib/blob-access'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const MOOD_MEDIA_PREFIX = 'mood-journal/'

const getRetentionDays = () => {
  const raw = Number(process.env.MOOD_MEDIA_RETENTION_DAYS || 1)
  if (!Number.isFinite(raw) || raw < 1) return 1
  return Math.min(Math.round(raw), 3650)
}

const chunk = <T,>(items: T[], size: number) => {
  const result: T[][] = []
  for (let i = 0; i < items.length; i += size) {
    result.push(items.slice(i, i + size))
  }
  return result
}

const coerceMediaList = (value: unknown): string[] => {
  if (Array.isArray(value)) {
    return value.map((entry) => String(entry ?? '').trim()).filter(Boolean)
  }
  if (typeof value === 'string') {
    const trimmed = value.trim()
    if (!trimmed) return []
    try {
      const parsed = JSON.parse(trimmed)
      if (Array.isArray(parsed)) {
        return parsed.map((entry) => String(entry ?? '').trim()).filter(Boolean)
      }
    } catch {
      return [trimmed]
    }
  }
  return []
}

const pruneDeletedMedia = (value: unknown, deletedPaths: Set<string>) => {
  const original = coerceMediaList(value)
  if (original.length === 0) return { list: [], removed: 0, changed: false }

  let removed = 0
  const kept: string[] = []
  for (const media of original) {
    const path = extractScopedBlobPath(media, 'mood-journal')
    if (path && deletedPaths.has(path)) {
      removed += 1
      continue
    }
    kept.push(media)
  }

  const changed = removed > 0 || kept.length !== original.length
  return { list: kept, removed, changed }
}

export async function GET(request: NextRequest) {
  const vercelCronHeader = request.headers.get('x-vercel-cron')
  const isVercelCron = vercelCronHeader !== null
  const authHeader = request.headers.get('authorization')
  const expected = process.env.MOOD_MEDIA_CLEANUP_SECRET || process.env.SCHEDULER_SECRET

  if (!(isVercelCron || (expected && authHeader === `Bearer ${expected}`))) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  if (!process.env.BLOB_READ_WRITE_TOKEN) {
    return NextResponse.json({ error: 'Blob storage not configured' }, { status: 500 })
  }

  const retentionDays = getRetentionDays()
  const cutoffMs = Date.now() - retentionDays * 24 * 60 * 60 * 1000

  let cursor: string | undefined = undefined
  let scanned = 0
  let deleted = 0

  const expiredTargets: Array<{ path: string; url: string }> = []

  try {
    do {
      const result: Awaited<ReturnType<typeof list>> = await list({
        prefix: MOOD_MEDIA_PREFIX,
        limit: 1000,
        cursor,
      })

      cursor = result.cursor
      for (const blob of result.blobs) {
        scanned += 1
        if (blob.uploadedAt.getTime() < cutoffMs) {
          expiredTargets.push({ path: blob.pathname, url: blob.url })
        }
      }
    } while (cursor)

    const uniquePaths = Array.from(new Set(expiredTargets.map((item) => item.path)))
    const batches = chunk(uniquePaths, 100)
    for (const batch of batches) {
      if (!batch.length) continue
      await del(batch)
      deleted += batch.length
    }

    await ensureMoodTables()

    const deletedPaths = new Set(uniquePaths)
    let entriesUpdated = 0
    let mediaRefsCleared = 0

    const rows = await prisma.$queryRawUnsafe<Array<{ id: string; images: unknown; audio: unknown }>>(
      'SELECT id, images, audio FROM MoodJournalEntries',
    )

    for (const row of rows) {
      const imageState = pruneDeletedMedia(row.images, deletedPaths)
      const audioState = pruneDeletedMedia(row.audio, deletedPaths)
      if (!imageState.changed && !audioState.changed) continue

      await prisma.$executeRawUnsafe(
        `UPDATE MoodJournalEntries
         SET images = $1::jsonb,
             audio = $2::jsonb,
             updatedAt = NOW()
         WHERE id = $3`,
        JSON.stringify(imageState.list),
        JSON.stringify(audioState.list),
        row.id,
      )
      entriesUpdated += 1
      mediaRefsCleared += imageState.removed + audioState.removed
    }

    return NextResponse.json({
      ok: true,
      scanned,
      deleted,
      retentionDays,
      entriesUpdated,
      mediaRefsCleared,
    })
  } catch (error) {
    console.error('mood media cleanup failed', error)
    return NextResponse.json({ error: 'Cleanup failed' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { sendPractitionerContactSummaryEmail } from '@/lib/practitioner-emails'

export const dynamic = 'force-dynamic'
export const runtime = 'nodejs'

function isAuthorized(request: NextRequest) {
  const authHeader = request.headers.get('authorization') || ''
  const expected = process.env.SCHEDULER_SECRET || ''
  const vercelCronHeader = request.headers.get('x-vercel-cron')
  const isVercelCron = vercelCronHeader !== null
  return isVercelCron || (expected && authHeader === `Bearer ${expected}`)
}

async function ensureAnalyticsTable() {
  await prisma.$executeRawUnsafe(`
    CREATE TABLE IF NOT EXISTS "AnalyticsEvent" (
      id TEXT PRIMARY KEY,
      "timestamp" TIMESTAMPTZ NOT NULL,
      "action" TEXT,
      "type" TEXT,
      "userId" TEXT,
      payload JSONB NOT NULL
    )
  `)
}

async function ensurePreferencesTable() {
  await prisma.$executeRawUnsafe(`
    CREATE TABLE IF NOT EXISTS "PractitionerNotificationPreference" (
      "practitionerAccountId" TEXT PRIMARY KEY,
      "weeklySummaryEnabled" BOOLEAN NOT NULL DEFAULT true,
      "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
      "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now()
    )
  `)
}

async function getWeeklySummaryEnabled(accountId: string): Promise<boolean> {
  const rows = await prisma.$queryRawUnsafe<Array<{ weeklySummaryEnabled: boolean }>>(
    `SELECT "weeklySummaryEnabled"
     FROM "PractitionerNotificationPreference"
     WHERE "practitionerAccountId" = $1`,
    accountId
  )
  if (!rows.length) return true
  return Boolean(rows[0].weeklySummaryEnabled)
}

function normalizePayload(value: any): any {
  if (!value) return {}
  if (typeof value === 'string') {
    try {
      return JSON.parse(value)
    } catch {
      return { raw: value }
    }
  }
  return value
}

export async function POST(request: NextRequest) {
  if (!isAuthorized(request)) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  await ensureAnalyticsTable()
  await ensurePreferencesTable()

  const rangeEnd = new Date()
  const rangeStart = new Date(rangeEnd.getTime() - 7 * 24 * 60 * 60 * 1000)

  const rows = await prisma.$queryRawUnsafe<
    Array<{ action: string | null; timestamp: Date; payload: any }>
  >(
    `SELECT "action", "timestamp", payload
     FROM "AnalyticsEvent"
     WHERE "timestamp" >= $1 AND "type" = $2
     ORDER BY "timestamp" ASC`,
    rangeStart,
    'practitioner-contact'
  )

  if (!rows.length) {
    return NextResponse.json({ sent: 0, events: 0 })
  }

  const events = rows
    .map((row) => {
      const payload = normalizePayload(row.payload)
      const listingId = String(payload?.listingId || '').trim()
      if (!listingId) return null
      return {
        listingId,
        action: row.action || payload?.action || '',
        timestamp: new Date(row.timestamp),
      }
    })
    .filter(Boolean) as Array<{ listingId: string; action: string; timestamp: Date }>

  const listingIds = Array.from(new Set(events.map((event) => event.listingId)))
  if (!listingIds.length) {
    return NextResponse.json({ sent: 0, events: rows.length })
  }

  const listings = await prisma.practitionerListing.findMany({
    where: { id: { in: listingIds } },
    include: { practitionerAccount: true },
  })

  const listingMap = new Map(listings.map((listing) => [listing.id, listing]))
  let sent = 0

  for (const listingId of listingIds) {
    const listing = listingMap.get(listingId)
    if (!listing?.practitionerAccount?.contactEmail) continue
    const weeklySummaryEnabled = await getWeeklySummaryEnabled(listing.practitionerAccountId)
    if (!weeklySummaryEnabled) continue
    const listingEvents = events
      .filter((event) => event.listingId === listingId)
      .sort((a, b) => a.timestamp.getTime() - b.timestamp.getTime())
    if (!listingEvents.length) continue
    sendPractitionerContactSummaryEmail({
      toEmail: listing.practitionerAccount.contactEmail,
      displayName: listing.displayName,
      slug: listing.slug,
      rangeStart,
      rangeEnd,
      events: listingEvents,
    })
    sent += 1
  }

  return NextResponse.json({ sent, events: rows.length })
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import {
  sendPractitionerTrialReminderEmail,
  sendPractitionerTrialEndedEmail,
  sendPractitionerReengageEmail,
} from '@/lib/practitioner-emails'

export const dynamic = 'force-dynamic'
export const runtime = 'nodejs'

function isAuthorized(request: NextRequest) {
  const authHeader = request.headers.get('authorization') || ''
  const expected = process.env.SCHEDULER_SECRET || ''
  const vercelCronHeader = request.headers.get('x-vercel-cron')
  const isVercelCron = vercelCronHeader !== null
  return isVercelCron || (expected && authHeader === `Bearer ${expected}`)
}

function daysUntil(date: Date): number {
  const diffMs = date.getTime() - Date.now()
  return Math.ceil(diffMs / (1000 * 60 * 60 * 24))
}

export async function POST(request: NextRequest) {
  if (!isAuthorized(request)) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const subscriptions = await prisma.practitionerListingSubscription.findMany({
    where: {
      status: 'TRIALING',
      trialEndAt: { not: null },
    },
    include: {
      listing: {
        include: { practitionerAccount: true },
      },
    },
  })

  let remindersSent = 0
  let trialsEnded = 0
  let reengageSent = 0

  for (const subscription of subscriptions) {
    if (!subscription.trialEndAt) continue
    const listing = subscription.listing
    if (!listing) continue

    const daysLeft = daysUntil(new Date(subscription.trialEndAt))
    const logTypes = await prisma.practitionerEmailLog.findMany({
      where: {
        listingId: listing.id,
        type: { in: ['TRIAL_14D', 'TRIAL_7D', 'TRIAL_1D', 'TRIAL_ENDED'] },
      },
      select: { type: true },
    })
    const sentSet = new Set(logTypes.map((row) => row.type))

    if ([14, 7, 1].includes(daysLeft)) {
      const type = daysLeft === 14 ? 'TRIAL_14D' : daysLeft === 7 ? 'TRIAL_7D' : 'TRIAL_1D'
      if (!sentSet.has(type)) {
        sendPractitionerTrialReminderEmail({
          practitionerAccountId: listing.practitionerAccountId,
          listingId: listing.id,
          toEmail: listing.practitionerAccount.contactEmail,
          displayName: listing.displayName,
          daysLeft,
        })
        remindersSent += 1
      }
    }

    if (daysLeft <= 0 && !sentSet.has('TRIAL_ENDED')) {
      await prisma.practitionerListing.update({
        where: { id: listing.id },
        data: { status: 'HIDDEN', visibilityReason: 'SUB_LAPSED' },
      })
      await prisma.practitionerListingSubscription.update({
        where: { listingId: listing.id },
        data: { status: 'EXPIRED' },
      })
      sendPractitionerTrialEndedEmail({
        practitionerAccountId: listing.practitionerAccountId,
        listingId: listing.id,
        toEmail: listing.practitionerAccount.contactEmail,
        displayName: listing.displayName,
      })
      trialsEnded += 1
    }
  }

  const hiddenListings = await prisma.practitionerListing.findMany({
    where: {
      status: 'HIDDEN',
      reviewStatus: 'APPROVED',
      visibilityReason: { in: ['SUB_LAPSED', 'PAYMENT_FAILED'] },
    },
    include: { practitionerAccount: true },
  })

  for (const listing of hiddenListings) {
    const lastEmail = await prisma.practitionerEmailLog.findFirst({
      where: { listingId: listing.id, type: 'WEEKLY_REENGAGE' },
      orderBy: { sentAt: 'desc' },
      select: { sentAt: true },
    })
    const lastSentAt = lastEmail?.sentAt ? new Date(lastEmail.sentAt) : null
    const daysSince = lastSentAt ? Math.floor((Date.now() - lastSentAt.getTime()) / (1000 * 60 * 60 * 24)) : null

    if (!lastSentAt || (daysSince !== null && daysSince >= 7)) {
      sendPractitionerReengageEmail({
        practitionerAccountId: listing.practitionerAccountId,
        listingId: listing.id,
        toEmail: listing.practitionerAccount.contactEmail,
        displayName: listing.displayName,
      })
      reengageSent += 1
    }
  }

  return NextResponse.json({ processed: subscriptions.length, remindersSent, trialsEnded, reengageSent })
}

import { NextRequest, NextResponse } from 'next/server'
import { backfillWeeklyReportState, listDueWeeklyReportUsers } from '@/lib/weekly-health-report'
import { publishWithQStash } from '@/lib/qstash'

export const dynamic = 'force-dynamic'
export const runtime = 'nodejs'

function isAuthorized(request: NextRequest) {
  const authHeader = request.headers.get('authorization') || ''
  const expected = process.env.SCHEDULER_SECRET || ''
  const vercelCronHeader = request.headers.get('x-vercel-cron')
  const isVercelCron = vercelCronHeader !== null
  return isVercelCron || (expected && authHeader === `Bearer ${expected}`)
}

function getBaseUrl() {
  let base = process.env.PUBLIC_BASE_URL || (process.env.VERCEL_URL ? `https://${process.env.VERCEL_URL}` : '')
  if (!base) return ''
  base = base.trim()
  if (!/^https?:\/\//i.test(base)) base = `https://${base}`
  return base.replace(/\/+$/, '')
}

export async function POST(request: NextRequest) {
  if (!isAuthorized(request)) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  await backfillWeeklyReportState(50)
  const dueUsers = await listDueWeeklyReportUsers(20)
  if (dueUsers.length === 0) {
    return NextResponse.json({ processed: 0, scheduled: 0 })
  }

  const base = getBaseUrl()
  const schedulerSecret = process.env.SCHEDULER_SECRET || ''

  const results = [] as Array<{ userId: string; ok: boolean; reason?: string }>

  for (const user of dueUsers) {
    if (process.env.QSTASH_TOKEN) {
      const published = await publishWithQStash('/api/reports/weekly/run', { userId: user.userId })
      results.push({ userId: user.userId, ok: published.ok, reason: published.reason })
      continue
    }

    if (!base || !schedulerSecret) {
      results.push({ userId: user.userId, ok: false, reason: 'missing_base_or_secret' })
      continue
    }

    try {
      const res = await fetch(`${base}/api/reports/weekly/run`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${schedulerSecret}`,
        },
        body: JSON.stringify({ userId: user.userId }),
      })
      results.push({ userId: user.userId, ok: res.ok, reason: res.ok ? undefined : `http_${res.status}` })
    } catch (error: any) {
      results.push({ userId: user.userId, ok: false, reason: error?.message || 'fetch_error' })
    }
  }

  return NextResponse.json({ processed: dueUsers.length, scheduled: results.length, results })
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { sendWriteSpikeAlertEmail } from '@/lib/admin-alerts'
import { estimateDailyCostUsd, fetchNeonUsageSummary } from '@/lib/neon-usage'
import { formatNumber, getSpikeCandidates } from '@/lib/usage-report'
import { openCircuit } from '@/lib/safety-circuit'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

function isAuthorized(request: NextRequest) {
  const authHeader = request.headers.get('authorization') || ''
  const expected = process.env.SCHEDULER_SECRET || ''
  const vercelCronHeader = request.headers.get('x-vercel-cron')
  const isVercelCron = vercelCronHeader !== null
  return isVercelCron || (expected && authHeader === `Bearer ${expected}`)
}

async function ensureAlertTable() {
  await prisma.$executeRawUnsafe(`
    CREATE TABLE IF NOT EXISTS WriteSpikeAlertLog (
      scope TEXT PRIMARY KEY,
      lastAlertAt TIMESTAMPTZ NOT NULL DEFAULT NOW()
    )
  `)
}

async function canSendAlert(scope: string, cooldownMinutes: number) {
  await ensureAlertTable()
  const rows: any[] = await prisma.$queryRawUnsafe(
    'SELECT lastAlertAt FROM WriteSpikeAlertLog WHERE scope = $1',
    scope
  )
  const existing = rows?.[0]
  const now = Date.now()
  if (existing?.lastAlertAt) {
    const last = new Date(existing.lastAlertAt).getTime()
    if (now - last < cooldownMinutes * 60 * 1000) {
      return false
    }
  }

  await prisma.$queryRawUnsafe(
    `INSERT INTO WriteSpikeAlertLog (scope, lastAlertAt)
     VALUES ($1, NOW())
     ON CONFLICT (scope) DO UPDATE SET lastAlertAt = NOW()`,
    scope
  )
  return true
}

export async function GET(request: NextRequest) {
  if (!isAuthorized(request)) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const now = new Date()

  const recentMinutes = 10
  const baselineHours = 6
  const baselineWindows = (baselineHours * 60) / recentMinutes

  const recentFrom = new Date(now.getTime() - recentMinutes * 60 * 1000)
  const baselineFrom = new Date(now.getTime() - baselineHours * 60 * 60 * 1000)

  const candidates = await getSpikeCandidates({
    recentFrom,
    recentTo: now,
    baselineFrom,
    baselineTo: now,
    baselineWindows,
  })

  const spikes = candidates.filter((row) => {
    if (row.recentCount < row.spikeThreshold) return false
    const baseline = row.baselinePerWindow || 0
    if (baseline === 0) return row.recentCount >= row.spikeThreshold
    return row.recentCount >= baseline * 3
  })

  if (!spikes.length) {
    return NextResponse.json({ ok: true, spikes: 0 })
  }

  // Optional context: include Neon API usage estimate if available.
  let neonNote: string | null = null
  let estimatedDailyCostUsd: number | null = null
  try {
    const costWindowStart = new Date(now.getTime() - 24 * 60 * 60 * 1000)
    const neonUsage = await fetchNeonUsageSummary({
      from: costWindowStart.toISOString(),
      to: now.toISOString(),
      granularity: 'daily',
      orgId: (process.env.NEON_ORG_ID || '').trim() || undefined,
    })
    const costEstimate = estimateDailyCostUsd(neonUsage)
    estimatedDailyCostUsd = costEstimate.estimatedDailyCostUsd
    neonNote = costEstimate.note || neonUsage?.note || null
  } catch {}

  const scope = 'write-spike-alert'
  const allowed = await canSendAlert(scope, 60)
  if (!allowed) {
    return NextResponse.json({ ok: true, spikes: spikes.length, suppressed: true })
  }

  const recipientEmail = ((process.env.OWNER_EMAIL || 'support@helfi.ai') as string).trim() || 'support@helfi.ai'
  const subject = 'Helfi write spike alert'

  const listHtml = spikes
    .map(
      (row) =>
        `<li>${row.label}: ${formatNumber(row.recentCount)} in last ${recentMinutes} mins (baseline ${formatNumber(Math.round(row.baselinePerWindow || 0))})</li>`
    )
    .join('')

  // Auto-pause health setup saves if we see an "impossible" HealthGoal spike.
  try {
    const healthGoalSpike = spikes.find((row) => row.table === 'HealthGoal')
    const baseline = healthGoalSpike?.baselinePerWindow || 0
    const recent = healthGoalSpike?.recentCount || 0
    const severe = !!healthGoalSpike && (recent >= 200 || (baseline > 0 && recent >= baseline * 10))
    if (severe) {
      openCircuit({
        scope: 'health-setup-saves',
        minutes: 15,
        reason: `Health goals write spike detected (${recent} in ${recentMinutes} mins).`,
      }).catch(() => {})
    }
  } catch {}

  const costLine =
    estimatedDailyCostUsd !== null
      ? `<p style="margin: 0 0 12px 0;"><strong>Estimated Neon daily cost (approx):</strong> $${estimatedDailyCostUsd.toFixed(2)}</p>`
      : '<p style="margin: 0 0 12px 0;"><strong>Estimated Neon daily cost (approx):</strong> unavailable.</p>'
  const noteLine = neonNote ? `<p style="margin: 0 0 12px 0; color:#b91c1c;">Note: ${neonNote}</p>` : ''

  const html = `
    <div style="font-family: Arial, sans-serif; line-height: 1.5; color: #111827;">
      <h2 style="margin: 0 0 12px 0;">Write spike alert</h2>
      <p style="margin: 0 0 12px 0;">Window: last ${recentMinutes} minutes.</p>
      ${costLine}
      ${noteLine}
      <ul>${listHtml}</ul>
      <p style="margin: 12px 0 0 0; color:#6b7280; font-size:12px;">
        If the spike looks like a bug, the app may temporarily pause health setup saves to protect the database.
      </p>
    </div>
  `

  await sendWriteSpikeAlertEmail({
    recipientEmail,
    subject,
    html,
  })

  return NextResponse.json({ ok: true, spikes: spikes.length, sentTo: recipientEmail })
}

