import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { fitbitApiRequest, getFitbitUserId } from '@/lib/fitbit-api'
import { ingestExerciseEntry } from '@/lib/exercise/ingest'
import { parseFitbitActivitiesToIngest } from '@/lib/exercise/fitbit-workouts'

/**
 * Sync Fitbit data for the authenticated user
 * POST /api/fitbit/sync
 */
export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      )
    }

    const fitbitUserId = await getFitbitUserId(session.user.id)
    if (!fitbitUserId) {
      return NextResponse.json(
        { error: 'Fitbit account not connected' },
        { status: 400 }
      )
    }

    const body = await request.json()
    const date = body.date || new Date().toISOString().split('T')[0] // Default to today
    const dataTypes = body.dataTypes || ['steps', 'heartrate', 'sleep', 'weight'] // Default to all

    const syncedData: any = {}

    // Sync steps
    if (dataTypes.includes('steps')) {
      const stepsResponse = await fitbitApiRequest(
        session.user.id,
        `/1/user/${fitbitUserId}/activities/date/${date}.json`
      )

      if (stepsResponse?.ok) {
        const stepsData = await stepsResponse.json()
        await prisma.fitbitData.upsert({
          where: {
            userId_date_dataType: {
              userId: session.user.id,
              date: new Date(date),
              dataType: 'steps',
            },
          },
          update: {
            value: stepsData.summary || stepsData,
            syncedAt: new Date(),
          },
          create: {
            userId: session.user.id,
            date: new Date(date),
            dataType: 'steps',
            value: stepsData.summary || stepsData,
          },
        })
        syncedData.steps = stepsData.summary || stepsData
      }
    }

    // Sync heart rate
    if (dataTypes.includes('heartrate')) {
      const hrResponse = await fitbitApiRequest(
        session.user.id,
        `/1/user/${fitbitUserId}/activities/heart/date/${date}/1d.json`
      )

      if (hrResponse?.ok) {
        const hrData = await hrResponse.json()
        await prisma.fitbitData.upsert({
          where: {
            userId_date_dataType: {
              userId: session.user.id,
              date: new Date(date),
              dataType: 'heartrate',
            },
          },
          update: {
            value: hrData,
            syncedAt: new Date(),
          },
          create: {
            userId: session.user.id,
            date: new Date(date),
            dataType: 'heartrate',
            value: hrData,
          },
        })
        syncedData.heartrate = hrData
      }
    }

    // Sync sleep
    if (dataTypes.includes('sleep')) {
      const sleepResponse = await fitbitApiRequest(
        session.user.id,
        `/1.2/user/${fitbitUserId}/sleep/date/${date}.json`
      )

      if (sleepResponse?.ok) {
        const sleepData = await sleepResponse.json()
        await prisma.fitbitData.upsert({
          where: {
            userId_date_dataType: {
              userId: session.user.id,
              date: new Date(date),
              dataType: 'sleep',
            },
          },
          update: {
            value: sleepData,
            syncedAt: new Date(),
          },
          create: {
            userId: session.user.id,
            date: new Date(date),
            dataType: 'sleep',
            value: sleepData,
          },
        })
        syncedData.sleep = sleepData
      }
    }

    // Sync weight
    if (dataTypes.includes('weight')) {
      const weightResponse = await fitbitApiRequest(
        session.user.id,
        `/1/user/${fitbitUserId}/body/log/weight/date/${date}.json`
      )

      if (weightResponse?.ok) {
        const weightData = await weightResponse.json()
        await prisma.fitbitData.upsert({
          where: {
            userId_date_dataType: {
              userId: session.user.id,
              date: new Date(date),
              dataType: 'weight',
            },
          },
          update: {
            value: weightData,
            syncedAt: new Date(),
          },
          create: {
            userId: session.user.id,
            date: new Date(date),
            dataType: 'weight',
            value: weightData,
          },
        })
        syncedData.weight = weightData
      }
    }

    // Sync activity/workouts (and ingest into Food Diary exercise log)
    if (dataTypes.includes('activity')) {
      const activityResponse = await fitbitApiRequest(
        session.user.id,
        `/1/user/${fitbitUserId}/activities/list.json?afterDate=${date}&sort=asc&offset=0&limit=100`
      )

      if (activityResponse?.ok) {
        const activityData = await activityResponse.json()
        await prisma.fitbitData.upsert({
          where: {
            userId_date_dataType: {
              userId: session.user.id,
              date: new Date(date),
              dataType: 'activity',
            },
          },
          update: {
            value: activityData,
            syncedAt: new Date(),
          },
          create: {
            userId: session.user.id,
            date: new Date(date),
            dataType: 'activity',
            value: activityData,
          },
        })
        syncedData.activity = activityData

        const workouts = parseFitbitActivitiesToIngest({ date, payload: activityData })
        for (const w of workouts as any[]) {
          await ingestExerciseEntry({
            userId: session.user.id,
            source: 'FITBIT',
            deviceId: `fitbit:${w.deviceId}`,
            localDate: date,
            startTime: w.startTime,
            durationMinutes: w.durationMinutes,
            calories: w.calories,
            label: w.label,
            rawPayload: w.raw,
          })
        }
      }
    }

    return NextResponse.json({
      success: true,
      synced: syncedData,
      date,
    })
  } catch (error) {
    console.error('❌ Fitbit sync error:', error)
    return NextResponse.json(
      { error: 'Failed to sync Fitbit data' },
      { status: 500 }
    )
  }
}

/**
 * Get synced Fitbit data for the authenticated user
 * GET /api/fitbit/data
 */
export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      )
    }

    const searchParams = request.nextUrl.searchParams
    const date = searchParams.get('date') || new Date().toISOString().split('T')[0]
    const dataType = searchParams.get('dataType') // Optional filter

    const where: any = {
      userId: session.user.id,
      date: new Date(date),
    }

    if (dataType) {
      where.dataType = dataType
    }

    const data = await prisma.fitbitData.findMany({
      where,
      orderBy: {
        syncedAt: 'desc',
      },
    })

    return NextResponse.json({
      success: true,
      data,
      date,
    })
  } catch (error) {
    console.error('❌ Error fetching Fitbit data:', error)
    return NextResponse.json(
      { error: 'Failed to fetch Fitbit data' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'

export async function POST(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const body = await req.json()
    const rating = Number(body?.rating)
    const scope = String(body?.scope || '').toLowerCase()
    const scanId = typeof body?.analysisId === 'string' ? body.analysisId : null
    const analysisMode = typeof body?.analysisMode === 'string' ? body.analysisMode : null
    const analysisHint = typeof body?.analysisHint === 'string' ? body.analysisHint : null

    if (!Number.isFinite(rating) || ![1, -1].includes(rating)) {
      return NextResponse.json({ error: 'Invalid rating' }, { status: 400 })
    }
    if (scope !== 'overall' && scope !== 'item') {
      return NextResponse.json({ error: 'Invalid scope' }, { status: 400 })
    }

    const reasons = Array.isArray(body?.reasons)
      ? body.reasons.map((r: any) => String(r || '')).filter(Boolean)
      : []

    const comment = typeof body?.comment === 'string' ? body.comment.trim() : null
    const itemIndex = Number.isFinite(Number(body?.itemIndex)) ? Number(body.itemIndex) : null
    const itemName = typeof body?.itemName === 'string' ? body.itemName.trim() : null
    const itemServingSize = typeof body?.itemServingSize === 'string' ? body.itemServingSize.trim() : null
    const itemBrand = typeof body?.itemBrand === 'string' ? body.itemBrand.trim() : null

    await prisma.foodAnalysisFeedback.create({
      data: {
        userId: session.user.id,
        scanId,
        analysisMode,
        analysisHint,
        scope,
        rating,
        reasons: reasons.length ? reasons : null,
        comment: comment && comment.length ? comment : null,
        itemIndex,
        itemName,
        itemServingSize,
        itemBrand,
      },
    })

    return NextResponse.json({ ok: true })
  } catch (error) {
    console.error('food-analysis-feedback error', error)
    return NextResponse.json({ error: 'Failed to save feedback' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth/next'
import { getToken } from 'next-auth/jwt'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const FOOD_MODEL_GOAL_NAME = '__FOOD_ANALYZER_MODEL__'
const ALLOWED_MODELS = new Set(['gpt-5.6-sol'])

function normalizeModel(model: unknown): string | null {
  if (typeof model !== 'string') return null
  const trimmed = model.trim()
  if (!trimmed) return null
  if (ALLOWED_MODELS.has(trimmed)) return trimmed
  return null
}

async function getAuthedUserId(req: NextRequest): Promise<string | null> {
  let session = await getServerSession(authOptions)
  let userEmail: string | null = session?.user?.email ?? null

  if (!userEmail) {
    try {
      const token = await getToken({
        req,
        secret: process.env.NEXTAUTH_SECRET || process.env.AUTH_SECRET || 'helfi-secret-key-production-2024',
      })
      if (token?.email) userEmail = String(token.email)
    } catch {
      // ignore
    }
  }

  if (!userEmail) return null
  const user = await prisma.user.findUnique({ where: { email: userEmail }, select: { id: true } })
  return user?.id || null
}

export async function GET(req: NextRequest) {
  try {
    const userId = await getAuthedUserId(req)
    if (!userId) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

    const existing = await prisma.healthGoal.findFirst({
      where: { userId, name: FOOD_MODEL_GOAL_NAME },
      select: { id: true, category: true },
    })

    let model: string | null = null
    if (existing?.category) {
      try {
        const parsed = JSON.parse(existing.category)
        model = normalizeModel(parsed?.model)
      } catch {}
    }

    return NextResponse.json({
      model: model || 'gpt-5.6-sol',
      source: model ? 'user_override' : 'default',
    })
  } catch (err) {
    console.error('[food-analyzer-model] GET error', err)
    return NextResponse.json({ error: 'Failed to load model' }, { status: 500 })
  }
}

export async function POST(req: NextRequest) {
  try {
    const userId = await getAuthedUserId(req)
    if (!userId) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

    const body = await req.json().catch(() => ({}))
    const model = normalizeModel(body?.model)
    if (!model) {
      return NextResponse.json({ error: 'Invalid model (use gpt-5.6-sol)' }, { status: 400 })
    }

    const payload = JSON.stringify({ model })
    const existing = await prisma.healthGoal.findFirst({
      where: { userId, name: FOOD_MODEL_GOAL_NAME },
      select: { id: true },
    })

    if (existing?.id) {
      await prisma.healthGoal.update({
        where: { id: existing.id },
        data: { category: payload, currentRating: 0 },
      })
    } else {
      await prisma.healthGoal.create({
        data: {
          userId,
          name: FOOD_MODEL_GOAL_NAME,
          category: payload,
          currentRating: 0,
        },
      })
    }

    return NextResponse.json({ ok: true, model })
  } catch (err) {
    console.error('[food-analyzer-model] POST error', err)
    return NextResponse.json({ error: 'Failed to save model' }, { status: 500 })
  }
}

export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { fetchFatSecretBrandList } from '@/lib/food-data'

const brandCache = new Map<string, { items: string[]; expiresAtMs: number }>()

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const startsWith = String(searchParams.get('startsWith') || searchParams.get('q') || '').trim()
    const brandType = String(searchParams.get('type') || 'restaurant').trim().toLowerCase()

    if (startsWith.length < 2) {
      return NextResponse.json({ success: true, items: [] })
    }

    const key = `${brandType}:${startsWith.toLowerCase()}`
    const cached = brandCache.get(key)
    if (cached && Date.now() < cached.expiresAtMs) {
      return NextResponse.json({ success: true, items: cached.items })
    }

    const items = await fetchFatSecretBrandList(startsWith, { brandType, limit: 20 })
    brandCache.set(key, { items, expiresAtMs: Date.now() + 24 * 60 * 60 * 1000 })
    return NextResponse.json({ success: true, items })
  } catch (error) {
    console.warn('Food brands lookup failed', error)
    return NextResponse.json({ success: false, items: [] }, { status: 200 })
  }
}

export const dynamic = 'force-dynamic';

import { NextRequest, NextResponse } from 'next/server'
import { isFoodPreparationCompatible } from '@/native/src/lib/foodPreparation'
import { liquidDensity } from '@/native/src/lib/foodUnits'
import { optionalNutrient } from '@/native/src/lib/nutrientValues'
import { isSingleMilkQuery, isSingleMilkIdentityCompatible, milkSearchText, singleMilkLookupQueries } from '@/lib/food/single-milk-identity'
import { hasCoreFoodNutrition } from '@/lib/food/openfoodfacts'
import {
  searchOpenFoodFactsByQuery,
  searchUsdaFoods,
  searchFatSecretFoods,
  lookupFoodNutrition,
  searchLocalFoods,
} from '@/lib/food-data'
import { searchCustomFoodMacros, getCustomPackagedItems } from '@/lib/food/custom-foods'
import { prisma } from '@/lib/prisma'

let usdaHealthCache: { count: number | null; checkedAt: number } = { count: null, checkedAt: 0 }

// Lightweight read-only endpoint that proxies to external food databases
// and returns a normalized list of items in a format compatible with the
// Food Diary `items[]` structure (name, brand, serving_size, macros).
//
// Query parameters:
// - source: "usda" | "fatsecret" | "auto" (accepted for compatibility)
// - q: search query (product name, brand, or keywords)
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const source = (searchParams.get('source') || '').toLowerCase()
    const query = (searchParams.get('q') || '').trim()
    const kind = (searchParams.get('kind') || '').toLowerCase()
    const localOnly = searchParams.get('localOnly') === '1'
    const limitRaw = searchParams.get('limit')
    const limitParsed = limitRaw ? Number.parseInt(limitRaw, 10) : NaN
    const limit = Number.isFinite(limitParsed) ? Math.min(Math.max(limitParsed, 1), 50) : 20
    const kindMode = kind === 'packaged' ? 'packaged' : 'single'
    const countryParam = (searchParams.get('country') || '').trim().toUpperCase()
    const headerCountry =
      (request.headers.get('x-vercel-ip-country') || request.headers.get('cf-ipcountry') || '').trim().toUpperCase()
    const resolvedCountry = countryParam || headerCountry || ''

    if (!query) {
      return NextResponse.json(
        { success: false, error: 'Missing required parameter: q' },
        { status: 400 },
      )
    }

    const knownSources = new Set(['', 'auto', 'usda', 'fatsecret', 'openfoodfacts'])
    if (!knownSources.has(source)) {
      return NextResponse.json(
        { success: false, error: 'Invalid source. Expected "usda", "fatsecret", or "auto".' },
        { status: 400 },
      )
    }

    let items: any[] = []
    // Owner rule: always start with Helfi database first, then use FatSecret to fill missing results.
    // We treat all known `source` values as "auto" so the ordering is consistent.
    let actualSource = 'auto'

    const normalizeForMatch = (value: any) =>
      String(value || '')
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, ' ')
        .trim()
        .replace(/\s+/g, ' ')

    const normalizeForCompact = (value: any) => normalizeForMatch(value).replace(/\s+/g, '')

    const prefersMlServingLabel = (item: any) => {
      const name = normalizeForMatch(item?.name)
      if (!name) return false
      if (/\b(chocolate|cocoa)\b/.test(name) && !/\b(chocolate milk|hot chocolate|milkshake|shake|smoothie|syrup)\b/.test(name)) {
        return false
      }
      if (/\b(bread|cookie|biscuit|cracker|cereal|chips|crisps|popcorn|powder|mix|bar|cake|brownie|bean|beans)\b/.test(name)) {
        return false
      }
      return /\b(water|milk|juice|coffee|tea|soda|cola|drink|beverage|smoothie|shake|broth|stock|oil|vinegar)\b/.test(name)
    }

    const liquidDensityForName = (item: any) => liquidDensity(String(item?.name || ''))

    const normalizeSingleLiquidServing = (item: any) => {
      if (!item || !prefersMlServingLabel(item)) return item
      if (!/^\s*100\s*g\s*$/i.test(String(item?.serving_size || ''))) return item
      const density = liquidDensityForName(item)
      // Keep the recorded gram basis when weight-to-volume conversion is unknown.
      if (density == null || !Number.isFinite(density) || density <= 0) return item
      const scaleValue = (value: any) => {
        const num = optionalNutrient(value)
        return num == null ? null : num * density
      }
      return {
        ...item,
        serving_size: '100 ml',
        calories: scaleValue(item.calories),
        protein_g: scaleValue(item.protein_g),
        carbs_g: scaleValue(item.carbs_g),
        fat_g: scaleValue(item.fat_g),
        fiber_g: scaleValue(item.fiber_g),
        sugar_g: scaleValue(item.sugar_g),
      }
    }

    const sortByNameAsc = (list: any[]) =>
      [...list].sort((a, b) => normalizeForMatch(a?.name).localeCompare(normalizeForMatch(b?.name)))

    // "Alphabetical hierarchy" (Google-Maps-like feel):
    // 1) Prefer items whose FIRST word matches what you typed.
    // 2) Then prefer items where the matching word is closest (egg beats eggplant).
    // 3) If the match is in a later word (Black-eyed peas), sort by that word.
    const sortByAlphabeticalHierarchyAsc = (list: any[], searchQuery: string) => {
      const stableNameKey = (it: any) => normalizeForMatch(it?.name)
      const queryNorm = normalizeForMatch(searchQuery)
      const queryTokens = getSearchTokens(searchQuery)
      const queryFirstRaw = queryTokens[0] || queryNorm
      const queryFirst = singularizeToken(queryFirstRaw)
      const queryAlt = singularizeToken(queryFirstRaw)
      const queryCandidates = Array.from(new Set([queryFirstRaw, queryFirst, queryAlt].filter(Boolean)))
      const minCandidateLen = queryCandidates.length > 0 ? Math.min(...queryCandidates.map((t) => t.length)) : 0

      const getMatchMeta = (name: any) => {
        const normalizedName = normalizeForMatch(name)
        const nameTokens = getSearchTokens(String(name || ''))
        let matchIndex = Number.POSITIVE_INFINITY
        let matchedWord = ''
        let matchedCandidateLen = minCandidateLen || 0

        for (let i = 0; i < nameTokens.length; i += 1) {
          const word = nameTokens[i]
          if (!word) continue
          const wordSingular = singularizeToken(word)
          for (const candidate of queryCandidates) {
            if (!candidate) continue
            if (word.startsWith(candidate)) {
              matchIndex = i
              matchedWord = word
              matchedCandidateLen = candidate.length
              break
            }
            if (wordSingular && wordSingular !== word && wordSingular.startsWith(candidate)) {
              matchIndex = i
              matchedWord = wordSingular
              matchedCandidateLen = candidate.length
              break
            }
          }
          if (matchIndex !== Number.POSITIVE_INFINITY) break
        }

        const isFirstWordMatch = matchIndex === 0
        const exactWordMatch = queryCandidates.some((c) => c === matchedWord || c === singularizeToken(matchedWord))
        const wordDelta = matchedWord ? Math.max(0, matchedWord.length - matchedCandidateLen) : 999
        const hierarchyKey = matchedWord ? `${matchedWord} ${normalizedName}` : normalizedName

        return { matchIndex, isFirstWordMatch, exactWordMatch, wordDelta, hierarchyKey, stable: normalizedName }
      }

      return [...list].sort((a, b) => {
        const aMeta = getMatchMeta(a?.name)
        const bMeta = getMatchMeta(b?.name)

        // 1) First-word matches should always win (E.g. "Eggplant" before "Aubergine (eggplant)").
        if (aMeta.isFirstWordMatch !== bMeta.isFirstWordMatch) return aMeta.isFirstWordMatch ? -1 : 1

        // 2) Earlier word match wins (if both are non-first).
        if (aMeta.matchIndex !== bMeta.matchIndex) return aMeta.matchIndex - bMeta.matchIndex

        // 3) Exact word match wins ("egg" beats "eggplant").
        if (aMeta.exactWordMatch !== bMeta.exactWordMatch) return aMeta.exactWordMatch ? -1 : 1

        // 4) Closer match wins (shorter extension after the typed prefix).
        if (aMeta.wordDelta !== bMeta.wordDelta) return aMeta.wordDelta - bMeta.wordDelta

        // 5) Alphabetical within the hierarchy.
        return aMeta.hierarchyKey.localeCompare(bMeta.hierarchyKey) || aMeta.stable.localeCompare(bMeta.stable)
      })
    }

    // PROTECTED: FOOD_DATA_PACKAGED_SORT START
    // Alphabetical hierarchy for packaged foods (considers brand + name)
    const sortPackagedByAlphabeticalHierarchyAsc = (list: any[], searchQuery: string) => {
      const queryNorm = normalizeForMatch(searchQuery)
      const queryTokens = getSearchTokens(searchQuery).filter(Boolean)
      const rankingTokenRaw =
        queryTokens.length > 1 ? queryTokens[queryTokens.length - 1] : queryTokens[0] || queryNorm
      const brandTokenRaw = queryTokens.length > 1 ? queryTokens[0] : ''
      const queryFirst = singularizeToken(rankingTokenRaw)
      const queryAlt = singularizeToken(rankingTokenRaw)
      const queryCandidates = Array.from(new Set([rankingTokenRaw, queryFirst, queryAlt].filter(Boolean)))
      const brandToken = singularizeToken(brandTokenRaw)
      const minCandidateLen = queryCandidates.length > 0 ? Math.min(...queryCandidates.map((t) => t.length)) : 0

      const getMatchMeta = (item: any) => {
        // For packaged foods, consider both brand and name
        const brand = String(item?.brand || '').trim()
        const name = String(item?.name || '').trim()
        const combined = [brand, name].filter(Boolean).join(' ')
        const normalizedCombined = normalizeForMatch(combined)
        const combinedTokens = getSearchTokens(combined)

        let matchIndex = Number.POSITIVE_INFINITY
        let matchedWord = ''
        let matchedCandidateLen = minCandidateLen || 0
        let brandStartsWithQuery = false

        // Check brand first, then name
        const brandTokens = brand ? getSearchTokens(brand) : []
        const nameTokens = name ? getSearchTokens(name) : []

        // Calculate simplicity score: fewer words in product name = simpler = better
        const simplicityScore = nameTokens.length // Lower is better

        // Check brand tokens first
        for (let i = 0; i < brandTokens.length; i += 1) {
          const word = brandTokens[i]
          if (!word) continue
          const wordSingular = singularizeToken(word)
          for (const candidate of queryCandidates) {
            if (!candidate) continue
            if (word.startsWith(candidate)) {
              matchIndex = i
              matchedWord = word
              matchedCandidateLen = candidate.length
              break
            }
            if (wordSingular && wordSingular !== word && wordSingular.startsWith(candidate)) {
              matchIndex = i
              matchedWord = wordSingular
              matchedCandidateLen = candidate.length
              break
            }
          }
          if (matchIndex !== Number.POSITIVE_INFINITY) break
        }

        if (brandToken) {
          brandStartsWithQuery = brandTokens.some((word) => {
            if (!word) return false
            if (word.startsWith(brandToken)) return true
            const wordSingular = singularizeToken(word)
            return wordSingular !== word && wordSingular.startsWith(brandToken)
          })
        }

        // If no brand match, check name tokens
        if (matchIndex === Number.POSITIVE_INFINITY) {
          const nameStartIndex = brandTokens.length
          for (let i = 0; i < nameTokens.length; i += 1) {
            const word = nameTokens[i]
            if (!word) continue
            const wordSingular = singularizeToken(word)
            for (const candidate of queryCandidates) {
              if (!candidate) continue
              if (word.startsWith(candidate)) {
                matchIndex = nameStartIndex + i
                matchedWord = word
                matchedCandidateLen = candidate.length
                break
              }
              if (wordSingular && wordSingular !== word && wordSingular.startsWith(candidate)) {
                matchIndex = nameStartIndex + i
                matchedWord = wordSingular
                matchedCandidateLen = candidate.length
                break
              }
            }
            if (matchIndex !== Number.POSITIVE_INFINITY) break
          }
        }

        const isFirstWordMatch = matchIndex === 0
        const exactWordMatch = queryCandidates.some((c) => c === matchedWord || c === singularizeToken(matchedWord))
        const wordDelta = matchedWord ? Math.max(0, matchedWord.length - matchedCandidateLen) : 999
        const hierarchyKey = matchedWord ? `${matchedWord} ${normalizedCombined}` : normalizedCombined

        return {
          matchIndex,
          isFirstWordMatch,
          exactWordMatch,
          wordDelta,
          hierarchyKey,
          stable: normalizedCombined,
          brandStartsWithQuery,
          simplicityScore,
        }
      }

      return [...list].sort((a, b) => {
        const aMeta = getMatchMeta(a)
        const bMeta = getMatchMeta(b)

        // 1) Earlier word match of the main typed token wins (e.g. "cheese" -> "cheeseburger" before "... & cheese").
        if (aMeta.matchIndex !== bMeta.matchIndex) return aMeta.matchIndex - bMeta.matchIndex

        // 2) Exact word match wins.
        if (aMeta.exactWordMatch !== bMeta.exactWordMatch) return aMeta.exactWordMatch ? -1 : 1

        // 3) Closer match wins (shorter extension after the typed prefix).
        if (aMeta.wordDelta !== bMeta.wordDelta) return aMeta.wordDelta - bMeta.wordDelta

        // 4) If brand was typed too, keep matching brand items ahead.
        if (aMeta.brandStartsWithQuery !== bMeta.brandStartsWithQuery) return aMeta.brandStartsWithQuery ? -1 : 1

        // 5) Simpler names win (fewer words in product name).
        if (aMeta.simplicityScore !== bMeta.simplicityScore) return aMeta.simplicityScore - bMeta.simplicityScore

        // 6) Alphabetical within the hierarchy.
        return aMeta.hierarchyKey.localeCompare(bMeta.hierarchyKey) || aMeta.stable.localeCompare(bMeta.stable)
      })
    }

    // PROTECTED: FOOD_DATA_PACKAGED_SORT END

    const singularizeToken = (value: string) => {
      const lower = value.toLowerCase()
      if (lower.endsWith('ies') && value.length > 4) return `${value.slice(0, -3)}y`
      if (
        lower.endsWith('es') &&
        value.length > 3 &&
        !lower.endsWith('ses') &&
        !lower.endsWith('xes') &&
        !lower.endsWith('zes') &&
        !lower.endsWith('ches') &&
        !lower.endsWith('shes')
      ) {
        return value.slice(0, -2)
      }
      if (lower.endsWith('s') && value.length > 3 && !lower.endsWith('ss')) return value.slice(0, -1)
      return value
    }

    const getSearchTokens = (value: string) => normalizeForMatch(value).split(' ').filter(Boolean)

    const isOneEditAway = (a: string, b: string) => {
      const lenA = a.length
      const lenB = b.length
      if (Math.abs(lenA - lenB) > 1) return false
      if (lenA === lenB) {
        let mismatches = 0
        for (let i = 0; i < lenA; i += 1) {
          if (a[i] !== b[i]) {
            mismatches += 1
            if (mismatches > 1) return false
          }
        }
        return mismatches <= 1
      }
      const shorter = lenA < lenB ? a : b
      const longer = lenA < lenB ? b : a
      let i = 0
      let j = 0
      let edits = 0
      while (i < shorter.length && j < longer.length) {
        if (shorter[i] === longer[j]) {
          i += 1
          j += 1
          continue
        }
        edits += 1
        if (edits > 1) return false
        j += 1
      }
      return true
    }

    const DESCRIPTOR_TOKENS = new Set([
      'raw',
      'fresh',
      'cooked',
      'uncooked',
      'frozen',
      'pasteurized',
      'pasteurised',
      'boiled',
      'baked',
      'roasted',
      'fried',
      'grilled',
      'steamed',
      'sauteed',
      'smoked',
      'dried',
    ])

    // Strip parentheses and their content to prevent synonym matching
    const stripParentheses = (text: string) => {
      return text.replace(/\s*\([^)]*\)/g, '').trim()
    }

    const nameMatchesSearchQuery = (name: string, searchQuery: string, options?: { allowTypo?: boolean }) => {
      const normalizedQuery = normalizeForMatch(searchQuery)
      if (!normalizedQuery) return false

      // Strip parentheses from name to prevent matching via synonyms
      const nameWithoutParentheses = stripParentheses(name)
      const nameTokens = getSearchTokens(nameWithoutParentheses)

      if (normalizedQuery.length === 1) {
        // Single letter: first word must start with it
        if (nameTokens.length === 0) return false
        const firstWord = nameTokens[0]
        return firstWord.startsWith(normalizedQuery)
      }

      const rawTokens = getSearchTokens(searchQuery).filter((token) => token.length >= 2)
      const filteredTokens = rawTokens.filter((token) => !DESCRIPTOR_TOKENS.has(token))
      const queryTokens = filteredTokens.length > 0 ? filteredTokens : rawTokens
      const filteredNameTokens = nameTokens.filter((token) => token.length >= 1)

      if (queryTokens.length === 0 || filteredNameTokens.length === 0) return false

      // For single-word queries: FIRST word must match (strict prefix matching)
      if (queryTokens.length === 1) {
        const queryToken = queryTokens[0]
        const firstWord = filteredNameTokens[0]
        if (!firstWord) return false

        // Exact word match (egg = egg, eggs = eggs)
        if (firstWord === queryToken) return true

        // Singular/plural exact matches only (eggs = egg, but NOT eggs = eggplant)
        const firstWordSingular = singularizeToken(firstWord)
        const querySingular = singularizeToken(queryToken)

        // Exact singular match: "eggs" matches "egg" exactly, "egg" matches "eggs" exactly
        if (firstWordSingular === querySingular) {
          // Both are the same after singularization - this is an exact match
          return true
        }

        // Prefix match: first word must START with the FULL query token
        // This allows "egg" to match "eggplant" but NOT "eggs" to match "eggplant"
        // (because "eggplant" doesn't start with "eggs", only with "egg")
        if (firstWord.startsWith(queryToken)) return true

        // Typo tolerance: only if first letter matches and it's a prefix match
        const allowTypo = (options?.allowTypo ?? true) && queryToken.length >= 3 && queryToken[0] === firstWord[0]
        if (allowTypo) {
          const prefixSame = firstWord.slice(0, queryToken.length)
          if (prefixSame && isOneEditAway(queryToken, prefixSame)) return true
          const prefixLonger = firstWord.slice(0, queryToken.length + 1)
          if (prefixLonger && isOneEditAway(queryToken, prefixLonger)) return true
        }

        // Predictive fallback: allow matching on later words for short typed queries
        // (e.g. "blu" should match "Cheese, blue").
        if (queryToken.length >= 2) {
          const queryTokenSingular = singularizeToken(queryToken)
          const otherWords = filteredNameTokens.slice(1)
          const laterWordMatches = otherWords.some((word) => {
            if (!word) return false
            if (word.startsWith(queryToken)) return true
            const singularWord = singularizeToken(word)
            if (singularWord !== word && singularWord.startsWith(queryToken)) return true
            if (queryTokenSingular !== queryToken && word.startsWith(queryTokenSingular)) return true
            if (
              queryTokenSingular !== queryToken &&
              singularWord !== word &&
              singularWord.startsWith(queryTokenSingular)
            ) {
              return true
            }
            return false
          })
          if (laterWordMatches) return true
        }

        return false
      }

      // Multi-word queries: token matching is order-independent.
      // This allows searches like "blue cheese" to match names like "Cheese, blue".
      const tokenMatches = (token: string, word: string) => {
        if (!token || !word) return false
        if (word.startsWith(token)) return true
        const singularWord = singularizeToken(word)
        if (singularWord !== word && singularWord.startsWith(token)) return true
        const singularToken = singularizeToken(token)
        if (singularToken !== token && word.startsWith(singularToken)) return true
        if (singularToken !== token && singularWord !== word && singularWord.startsWith(singularToken)) return true
        return false
      }

      const allTokensMatchAnywhere = queryTokens.every((token) =>
        filteredNameTokens.some((word) => tokenMatches(token, word)),
      )

      if (!allTokensMatchAnywhere) return false

      // Ranking still prefers first-word matches elsewhere.
      return true
    }

    // PROTECTED: FOOD_DATA_PACKAGED_FILTER START
    const wordStartsWithToken = (word: string, token: string, options?: { allowTypo?: boolean }) => {
      if (!word || !token) return false
      if (word.startsWith(token)) return true
      const singularWord = singularizeToken(word)
      if (singularWord !== word && singularWord.startsWith(token)) return true
      const singularToken = singularizeToken(token)
      if (singularToken !== token && word.startsWith(singularToken)) return true
      if (singularToken !== token && singularWord !== word && singularWord.startsWith(singularToken)) return true
      const allowTypo = (options?.allowTypo ?? false) && token.length >= 3 && token[0] === word[0]
      if (!allowTypo) return false
      const prefixSame = word.slice(0, token.length)
      if (prefixSame && isOneEditAway(token, prefixSame)) return true
      const prefixLonger = word.slice(0, token.length + 1)
      if (prefixLonger && isOneEditAway(token, prefixLonger)) return true
      return false
    }

    const packagedMatchesActiveWordIntent = (
      text: string,
      searchQuery: string,
      options?: { allowTypo?: boolean },
    ) => {
      const rawTokens = getSearchTokens(searchQuery).filter(Boolean)
      const words = getSearchTokens(text).filter(Boolean)
      if (rawTokens.length === 0 || words.length === 0) return false

      const activeToken = rawTokens[rawTokens.length - 1] || ''
      if (!activeToken) return false
      const activeWordMatch = words.some((word) => wordStartsWithToken(word, activeToken, options))
      if (!activeWordMatch) return false

      const leadingTokens = rawTokens.slice(0, -1).filter((token) => token.length >= 2)
      if (leadingTokens.length === 0) return true

      const compact = normalizeForCompact(text)
      return leadingTokens.every((token) => {
        const normalized = normalizeForCompact(token)
        if (normalized && compact.includes(normalized)) return true
        const singular = normalizeForCompact(singularizeToken(token))
        if (singular && compact.includes(singular)) return true
        return false
      })
    }

    const filterItemsByQuery = (
      items: any[],
      searchQuery: string,
      getText: (item: any) => string,
      allowTypoFallback = true,
    ) => {
      if (!Array.isArray(items) || items.length === 0) return []

      // For packaged foods, be more lenient - allow partial matches
      const isPackaged = kindMode === 'packaged'

      if (isPackaged) {
        const rawTokens = getSearchTokens(searchQuery).filter(Boolean)
        // Word-by-word intent: once users type multiple words, the current word must match now.
        if (rawTokens.length > 1) {
          const strict = items.filter((item) => packagedMatchesActiveWordIntent(getText(item), searchQuery, { allowTypo: false }))
          if (strict.length > 0) return strict
          if (!allowTypoFallback) return []
          const typo = items.filter((item) => packagedMatchesActiveWordIntent(getText(item), searchQuery, { allowTypo: true }))
          return typo
        }
        if (rawTokens.length === 1) {
          const active = rawTokens[0]
          const matches = items.filter((item) => {
            const words = getSearchTokens(getText(item)).filter(Boolean)
            if (words.length === 0) return false
            return words.some((word) => wordStartsWithToken(word, active, { allowTypo: false }))
          })
          if (matches.length > 0) return matches
        }
      }

      const prefixMatches = items.filter((item) => nameMatchesSearchQuery(getText(item), searchQuery, { allowTypo: false }))
      if (prefixMatches.length > 0) return prefixMatches
      if (!allowTypoFallback) return []
      return items.filter((item) => nameMatchesSearchQuery(getText(item), searchQuery, { allowTypo: true }))
    }

    // PROTECTED: FOOD_DATA_PACKAGED_FILTER END

    type CustomPackagedItem = {
      id: string
      name: string
      brand?: string | null
      kind?: string | null
      serving_size?: string | null
      servingOptions?: any[] | null
      calories?: number | null
      protein_g?: number | null
      carbs_g?: number | null
      fat_g?: number | null
      fiber_g?: number | null
      sugar_g?: number | null
      source: 'openfoodfacts' | 'usda' | 'fatsecret' | 'custom'
      aliases?: string[]
      __custom?: boolean
    }

    const buildCustomPackagedItems = (rows: any[]): CustomPackagedItem[] => {
      if (!Array.isArray(rows) || rows.length === 0) return []
      const pickDefaultOption = (options: any[]) => {
        if (!Array.isArray(options) || options.length === 0) return null
        return options[0]
      }
      const normalizeBrandForDisplay = (value: any) =>
        String(value || '')
          .toLowerCase()
          .replace(/[^a-z0-9]+/g, '')
          .trim()
      return rows
        .map((row) => {
          const kindValue = row?.kind ? String(row.kind) : null
          const isFastFood = kindValue === 'FAST_FOOD'
          const options = Array.isArray(row?.servingOptions) ? row.servingOptions : []
          if (isFastFood && options.length === 0) return null
          const selected = pickDefaultOption(options)
          const servingLabel =
            (selected?.label || selected?.serving_size || row?.serving_size || '').toString().trim() ||
            '100 g'
          const itemId = row?.id ? String(row.id) : normalizeForCompact(`${row?.brand || ''} ${row?.name || ''}`)
          const rawName = String(row?.name || '').trim()
          const rawBrand = String(row?.brand || '').trim()
          const rowCountry = String(row?.country || '').trim().toUpperCase()
          const name =
            isFastFood && rowCountry === 'AU' && normalizeBrandForDisplay(rawBrand) === 'mcdonalds'
              ? rawName.replace(/\bTwin\s+Twist\s+/gi, '').replace(/\s+/g, ' ').trim()
              : rawName
          return {
            id: `custom:${itemId}`,
            name,
            brand: rawBrand || null,
            kind: kindValue,
            serving_size: servingLabel,
            servingOptions: options.length > 0 ? options : null,
            calories: selected?.calories ?? row?.calories ?? null,
            protein_g: selected?.protein_g ?? row?.protein_g ?? null,
            carbs_g: selected?.carbs_g ?? row?.carbs_g ?? null,
            fat_g: selected?.fat_g ?? row?.fat_g ?? null,
            fiber_g: selected?.fiber_g ?? row?.fiber_g ?? null,
            sugar_g: selected?.sugar_g ?? row?.sugar_g ?? null,
            source: 'custom',
            aliases: Array.isArray(row?.aliases) ? row.aliases : [],
            __custom: true,
          }
        })
        .filter(Boolean) as CustomPackagedItem[]
    }

    const customPackagedItemsPrimary =
      kindMode === 'packaged' ? buildCustomPackagedItems(await getCustomPackagedItems(resolvedCountry)) : []
    let customPackagedItemsAllCountries: CustomPackagedItem[] | null = null

    const loadAllCustomPackagedItems = async () => {
      if (customPackagedItemsAllCountries) return customPackagedItemsAllCountries
      customPackagedItemsAllCountries = buildCustomPackagedItems(await getCustomPackagedItems(null))
      return customPackagedItemsAllCountries
    }

    const getCustomPackagedMatches = (value: string, sourceItems: CustomPackagedItem[] = customPackagedItemsPrimary) => {
      if (!value) return []

      // For packaged foods, be more lenient - check if query tokens appear in name or brand+name
      const queryTokens = getSearchTokens(value).filter((t) => t.length >= 2)
      const normalizedQuery = normalizeForMatch(value)

      const buildMatches = (allowTypo: boolean) =>
        sourceItems.filter((item) => {
          const name = item.name || ''
          const brand = item.brand || ''
          const brandName = brand ? `${brand} ${name}` : name
          const normalizedBrandName = normalizeForMatch(brandName)
          const compactBrandName = normalizeForCompact(brandName)
          const normalizedName = normalizeForMatch(name)
          const compactName = normalizeForCompact(name)
          const normalizedBrand = normalizeForMatch(brand)
          const compactBrand = normalizeForCompact(brand)

          const tokenMatchesLoose = (token: string) => {
            if (!token) return false
            if (normalizedBrandName.includes(token)) return true
            if (compactBrandName.includes(token)) return true
            if (normalizedName.includes(token)) return true
            if (compactName.includes(token)) return true
            if (brand && normalizedBrand.includes(token)) return true
            if (brand && compactBrand.includes(token)) return true
            return false
          }

          // For multi-word queries, check if all tokens appear somewhere (loose matching, compact-aware).
          if (queryTokens.length > 1) {
            if (queryTokens.every((token) => tokenMatchesLoose(token))) return true
          } else if (queryTokens.length === 1) {
            // Single token: allow brand/name compact matching to handle punctuation (e.g. "mcdonalds" vs "McDonald's").
            if (tokenMatchesLoose(queryTokens[0])) return true
          }

          // Check name
          if (nameMatchesSearchQuery(name, value, { allowTypo })) return true
          // Check brand + name combination
          if (brandName && nameMatchesSearchQuery(brandName, value, { allowTypo })) return true
          // Check brand alone (if query matches brand)
          if (brand && (normalizedBrand.includes(normalizedQuery) || compactBrand.includes(normalizeForCompact(value)))) return true
          // Check aliases
          const aliases = Array.isArray(item.aliases) ? item.aliases : []
          return aliases.some((alias) => nameMatchesSearchQuery(alias, value, { allowTypo }))
        })
      const prefixMatches = buildMatches(false)
      const matches = prefixMatches.length > 0 ? prefixMatches : buildMatches(true)
      return matches.map((item) => {
        const { aliases, ...rest } = item
        return rest
      })
    }

    const queryNorm = normalizeForMatch(query)
    const queryCompact = normalizeForCompact(query)
    const queryTokens = queryNorm ? queryNorm.split(' ').filter(Boolean) : []
    const queryTokensNormalized = queryTokens.map((token) => singularizeToken(token))
    const queryFirstToken = queryTokens[0] || ''
    let customPackagedMatches = kindMode === 'packaged' ? getCustomPackagedMatches(query) : []
    // If the user's country has no matching fast-food item, fall back to all-country custom rows
    // so valid items are still discoverable instead of returning an empty list.
    if (kindMode === 'packaged' && customPackagedMatches.length === 0 && resolvedCountry) {
      const allCountryItems = await loadAllCustomPackagedItems()
      const crossCountryMatches = getCustomPackagedMatches(query, allCountryItems)
      if (crossCountryMatches.length > 0) customPackagedMatches = crossCountryMatches
    }
    // If country-specific matches are too narrow, top up with all-country matches.
    // Keep country matches first, then append non-duplicates.
    if (
      kindMode === 'packaged' &&
      resolvedCountry &&
      customPackagedMatches.length > 0 &&
      customPackagedMatches.length < Math.min(limit, 8)
    ) {
      const allCountryItems = await loadAllCustomPackagedItems()
      const crossCountryMatches = getCustomPackagedMatches(query, allCountryItems)
      if (crossCountryMatches.length > 0) {
        const seen = new Set(
          customPackagedMatches.map((item) => `${normalizeForMatch(item?.name)}|${normalizeForMatch(item?.brand)}`),
        )
        const extras = crossCountryMatches.filter((item) => {
          const key = `${normalizeForMatch(item?.name)}|${normalizeForMatch(item?.brand)}`
          if (!key || key === '|') return false
          if (seen.has(key)) return false
          seen.add(key)
          return true
        })
        if (extras.length > 0) customPackagedMatches = [...customPackagedMatches, ...extras]
      }
    }
    let customPackagedApplied = false

    // Owner rule: never return items with missing calories/macros.
    // Enforce this early so "fill up to limit" can still work.
    const hasMacroData = hasCoreFoodNutrition

    const toCustomFoodItems = async (value: string, options?: { allowTypo?: boolean }) => {
      if (kindMode !== 'single') return []
      const matches = await searchCustomFoodMacros(value, limit, { ...options, country: resolvedCountry })
      if (!matches.length) return []
      const items = matches.map((item) => ({
        source: 'custom' as const,
        id: `custom:${item.id || normalizeForCompact(item.name) || normalizeForMatch(item.name)}`,
        name: item.name,
        brand: item.brand ?? null,
        serving_size: '100 g',
        servingOptions: Array.isArray(item.servingOptions) && item.servingOptions.length > 0 ? item.servingOptions : null,
        calories: item.calories,
        protein_g: item.protein_g,
        carbs_g: item.carbs_g,
        fat_g: item.fat_g,
        fiber_g: item.fiber_g,
        sugar_g: item.sugar_g,
        __custom: true,
      }))
      return items.filter((it) => hasMacroData(it))
    }

    const filterSingleFoodItems = (list: any[], value: string, allowTypo = true) => {
      const milkQuery = isSingleMilkQuery(value)
      return filterItemsByQuery(
        list.filter(item => isSingleMilkIdentityCompatible(item?.name, value)),
        milkQuery ? milkSearchText(value) : value,
        item => milkQuery ? milkSearchText(item?.name) : item?.name || '',
        allowTypo,
      )
    }

    const buildSingleFoodResults = async (value: string) => {
      const customPrefix = (await toCustomFoodItems(value, { allowTypo: false }))
        .filter(item => isSingleMilkIdentityCompatible(item?.name, value))
      const localSearchWindow = Math.max(limit, 60)
      const lookupQueries = singleMilkLookupQueries(value)

      // For single foods: only use foundation and legacy (simple foods), NOT branded (product foods)
      // Branded/product foods should only appear for packaged searches
      const [foundation, legacy] = await Promise.all([
        Promise.all(lookupQueries.map(q => searchLocalFoods(q, { pageSize: localSearchWindow, sources: ['usda_foundation'] }))).then(groups => groups.flat()),
        Promise.all(lookupQueries.map(q => searchLocalFoods(q, { pageSize: localSearchWindow, sources: ['usda_sr_legacy'] }))).then(groups => groups.flat()),
      ])

      const combinedMain = [...foundation, ...legacy]
      const dedupe = (list: any[]) => {
        const seen = new Set<string>()
        return list.filter((item) => {
          const key = `${normalizeForMatch(item?.name)}|${normalizeForMatch(item?.brand)}`
          if (!key || key === '|') return false
          if (seen.has(key)) return false
          seen.add(key)
          return true
        })
      }

      // An incomplete Foundation row must not mask a complete Legacy peer.
      const mainDeduped = dedupe(combinedMain.filter(item => hasMacroData(item)))

      const mainWithMacros = mainDeduped.filter((it) => hasMacroData(it))

      const mainPrefix = filterSingleFoodItems(mainWithMacros, value, false)

      const hasPrefixMatches = customPrefix.length > 0 || mainPrefix.length > 0

      const customFinal = hasPrefixMatches ? customPrefix : await toCustomFoodItems(value, { allowTypo: true })
      let mainFinal = hasPrefixMatches
        ? mainPrefix
        : filterSingleFoodItems(mainWithMacros, value, true)
      const requestedTokensForSingle = getSearchTokens(value).map((token) => singularizeToken(token))
      const requestedMilkDrink = requestedTokensForSingle.includes('milk')
      if (requestedMilkDrink) {
        mainFinal = mainFinal.filter((item) => {
          const name = normalizeForMatch(item?.name)
          if (!name) return false
          if (
            !requestedTokensForSingle.some((token) => ['dry', 'dried', 'powder'].includes(token)) &&
            /\bdry|dried|powder\b/.test(name)
          ) {
            return false
          }
          if (!requestedTokensForSingle.includes('chocolate') && /\bchocolate\b/.test(name)) return false
          if (!requestedTokensForSingle.includes('buttermilk') && /\bbuttermilk\b/.test(name)) return false
          if (/^milk\b/.test(name)) return true
          if (/\b(?:almond|oat|soy|coconut) milk\b/.test(name)) return true
          if (/\bmilk beverage\b/.test(name)) return true
          return !/\bbabyfood|baby food|cereal|cheese|yogurt|bread|pudding|custard|dessert|cake|cookie|pie|potato|prepared with|candy|candies|nougat\b/.test(name)
        })
      }
      const requestedPlantMilk =
        requestedTokensForSingle.includes('milk') &&
        requestedTokensForSingle.some((token) => ['almond', 'oat', 'soy', 'coconut'].includes(token))
      if (requestedPlantMilk) {
        mainFinal = mainFinal.filter((item) => {
          const name = normalizeForMatch(item?.name)
          if (/\bcandy|candies|nougat\b/.test(name)) return false
          return requestedTokensForSingle.includes('chocolate') || !/\bchocolate\b/.test(name)
        })
      }

      const scorePlainSingleFoodFit = (item: any) => {
        const name = normalizeForMatch(item?.name)
        if (!name) return 0
        const rawNameTokens = name.split(' ').filter(Boolean)
        const nameTokens = rawNameTokens.map((token) => singularizeToken(token))
        const requestedTokens = getSearchTokens(value).filter(Boolean).map((token) => singularizeToken(token))
        const requestedCoreWithoutDescriptors = requestedTokens.filter((token) => token.length >= 2 && !DESCRIPTOR_TOKENS.has(token))
        const requestedCore =
          requestedCoreWithoutDescriptors.length > 0
            ? requestedCoreWithoutDescriptors
            : requestedTokens.filter((token) => token.length >= 2)
        if (requestedCore.length === 0) return 0

        let score = 0
        requestedCore.forEach((token, index) => {
          if (nameTokens[index] === token) score += index === 0 ? 500 : 220
          else if (nameTokens.includes(token)) score += 120
          if (index === 0 && rawNameTokens[0] === `${token}s`) score += 180
        })
        if (name.includes(' raw')) score += 260
        if (name.includes(' fresh')) score += 120
        if (name.includes(' whole')) score += 90
        if (name.includes(' with skin')) score += 70

        if (requestedCore.includes('coffee')) {
          if (/\bbeverages coffee\b/.test(name)) score += 760
          if (/\bbrewed|espresso|prepared with (?:tap )?water\b/.test(name)) score += 420
          if (/\bcandy|candies|beans|soymilk|whitener|whiteners|creamer|creamers|oil\b/.test(name)) score -= 640
        }
        if (requestedCore.includes('milk')) {
          if (rawNameTokens[0] === 'milk') score += 900
          if (/\bmilk whole\b/.test(name) || /\bwhole milk\b/.test(name)) score += 260
          if (/\bmilk (?:whole|lowfat|nonfat|reduced fat|fluid)\b/.test(name)) score += 180
          if (/\bprepared with whole milk\b/.test(name)) score -= 650
          if (!requestedTokens.includes('buttermilk') && /\bbuttermilk\b/.test(name)) score -= 900
          if (!requestedTokens.includes('canned') && /\bcanned|condensed|evaporated\b/.test(name)) score -= 820
          if (!requestedTokens.includes('dried') && !requestedTokens.includes('powder') && /\bdried|powder\b/.test(name)) score -= 760
          if (!requestedTokens.includes('cultured') && /\bcultured\b/.test(name)) score -= 360
        }
        if (requestedCore.includes('egg')) {
          if (/\begg whole raw fresh\b/.test(name)) score += 520
          if (/\bduck|goose|quail|turkey\b/.test(name)) score -= 260
        }
        if (requestedCore.includes('oat')) {
          if (rawNameTokens[0] === 'oats' || name === 'oats') score += 620
        }
        if (requestedCore.includes('rice')) {
          if (rawNameTokens[0] === 'rice') score += 180
          if (requestedTokens.includes('cooked') && name.includes(' cooked')) score += 260
          if (!requestedTokens.includes('noodle') && /\bnoodle|noodles\b/.test(name)) score -= 520
          if (/\buncle bens|tinkyada|cream of rice|pasta|sausage links\b/.test(name)) score -= 520
          if (/\brice, (?:white|brown), (?:long|medium|short)-grain\b/.test(name)) score += 160
        }
        if (requestedCore.includes('walnut')) {
          if (/\bnuts walnuts\b/.test(name)) score += 620
          if (/\bnuts walnuts english\b/.test(name)) score += 360
          if (!requestedTokens.includes('roasted') && /\broasted\b/.test(name)) score -= 260
          if (!requestedTokens.includes('salt') && /\bsalt|salted\b/.test(name)) score -= 360
          if (!requestedTokens.includes('glazed') && /\bglazed\b/.test(name)) score -= 420
          if (!requestedTokens.includes('oil') && /\boil\b/.test(name)) score -= 640
        }

        const queryAllowsProcessed = requestedTokens.some((token) =>
          ['juice', 'drink', 'beverage', 'canned', 'bottled', 'dried', 'dehydrated', 'sauce', 'cooked', 'frozen', 'oil'].includes(token),
        )
        if (!queryAllowsProcessed) {
          const processedPenalties: Array<[RegExp, number]> = [
            [/\bjuice|drink|beverage|nectar\b/, -700],
            [/\boil\b/, -720],
            [/\bcanned|bottled|packed\b/, -420],
            [/\bdried|dehydrated\b/, -420],
            [/\bfrozen\b/, -260],
            [/\bcooked|stewed|baked|fried|boiled\b/, -220],
            [/\bsauce|butter|jam|jelly|pie filling\b/, -520],
            [/\bpeel|rind|zest\b/, -520],
            [/\bbabyfood|baby food\b/, -520],
            [/\bsnack|chips|crisps|candy|dessert|pie|cake|cookie\b/, -520],
          ]
          processedPenalties.forEach(([pattern, penalty]) => {
            if (pattern.test(name)) score += penalty
          })
        }
        if (!requestedTokens.includes('bran') && /\bbran\b/.test(name)) score -= 360
        if (!requestedTokens.includes('flour') && /\bflour\b/.test(name)) score -= 420
        if (!requestedTokens.includes('powder') && /\bpowder\b/.test(name)) score -= 420

        return score
      }

      const sortSingleFoodResults = (list: any[]) =>
        sortByAlphabeticalHierarchyAsc(list.filter((item) => isFoodPreparationCompatible(item?.name, value)), value)
          .map((item, index) => ({ item, index, score: scorePlainSingleFoodFit(item) }))
          .sort((a, b) => b.score - a.score || a.index - b.index)
          .map((entry) => entry.item)

      const sortedCustom = sortByAlphabeticalHierarchyAsc(customFinal, value)
      const sortedMain = sortSingleFoodResults(mainFinal)

      const combined: any[] = []
      const pushGroup = (group: any[]) => {
        for (const item of group) {
          if (combined.length >= limit) return
          if (!hasMacroData(item)) continue
          if (!isSingleMilkIdentityCompatible(item?.name, value)) continue
          combined.push(item)
        }
      }

      // Return actual USDA library records first, then the custom fallback list.
      // Never invent a preferred USDA ID or substitute fixed nutrition figures.
      // Branded/product foods are excluded from single food searches.
      pushGroup(sortedMain)
      pushGroup(sortedCustom.filter((item) => isFoodPreparationCompatible(item?.name, value)))

      // If we still don't have enough results, use FatSecret as a fallback.
      // (We still return the Helfi database results first.)
      if (!localOnly && combined.length < limit) {
        const fat = await searchFatSecretFoods(value, { pageSize: localSearchWindow })
        const filteredFat = filterSingleFoodItems(fat, value).filter((it) => hasMacroData(it))
        const sortedFat = sortByAlphabeticalHierarchyAsc(filteredFat, value)
        const seen = new Set(combined.map((it) => `${normalizeForMatch(it?.name)}|${normalizeForMatch(it?.brand)}`))
        for (const item of sortedFat) {
          if (combined.length >= limit) break
          if (!hasMacroData(item)) continue
          const key = `${normalizeForMatch(item?.name)}|${normalizeForMatch(item?.brand)}`
          if (!key || key === '|') continue
          if (seen.has(key)) continue
          seen.add(key)
          combined.push(item)
        }
      }

      return combined
    }

    const scoreNameMatch = (name: any) => {
      if (!queryNorm) return 0
      const n = normalizeForMatch(name)
      const nCompact = normalizeForCompact(name)
      if (!n) return 0
      if (nCompact === queryCompact) return 1200
      if (nCompact.startsWith(queryCompact)) return 1000
      if (n === queryNorm) return 900
      if (n.startsWith(queryNorm)) return 750
      if (nCompact.includes(queryCompact)) return 600
      if (n.includes(queryNorm)) return 500
      const nameTokens = n.split(' ').filter(Boolean)
      const scoredTokens = queryTokensNormalized.filter((token) => token.length >= 2)
      const coreTokens = scoredTokens.filter((token) => !DESCRIPTOR_TOKENS.has(token))
      if (scoredTokens.length > 0) {
        const exactMatches = new Set<string>()
        const prefixMatches = new Set<string>()
        for (const token of scoredTokens) {
          if (nameTokens.includes(token)) {
            exactMatches.add(token)
            continue
          }
          if (nameTokens.some((word) => word.startsWith(token))) {
            prefixMatches.add(token)
          }
        }
        if (exactMatches.size > 0) return 520 + exactMatches.size * 120
        if (prefixMatches.size > 0) {
          let score = 360 + prefixMatches.size * 40
          if (coreTokens.length > 0) {
            const exactCoreMatches = coreTokens.filter((token) => nameTokens.includes(token))
            if (exactCoreMatches.length === 0) score -= 200
          }
          return score
        }
      }
      if (queryTokens.length > 0) {
        const hitCount = queryTokens.filter((t) => n.includes(t)).length
        if (hitCount === queryTokens.length) return 420
        return hitCount * 40
      }
      return 0
    }

    const scoreItemName = (it: any) => {
      const combined = [it?.brand, it?.name].filter(Boolean).join(' ').trim()
      let score = scoreNameMatch(combined || it?.name)
      if (kindMode === 'single') {
        score += it?.brand ? -40 : 120
      } else if (it?.brand) {
        score += 40
      }
      const nameNorm = normalizeForMatch(it?.name)
      if (nameNorm) score += Math.max(0, 80 - Math.min(80, nameNorm.length))
      const brandToken = normalizeForMatch(queryFirstToken)
      if (brandToken) {
        const brand = normalizeForMatch(it?.brand)
        const name = normalizeForMatch(it?.name)
        if (brand && brand === brandToken) score += 220
        if (brand && brand.startsWith(brandToken)) score += 180
        if (name && name.startsWith(brandToken)) score += 160
        if (brand && name && name.startsWith(brand)) score += 120
      }
      return score
    }

    const cleanSingleFoodQuery = (value: string) =>
      value
        .replace(/[^\w\s-]/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()

    const buildSingleFoodFallbacks = (value: string) => {
      const original = value.trim()
      if (!original) return []
      const cleaned = cleanSingleFoodQuery(original)
      const candidates = new Set<string>()
      if (cleaned && cleaned.toLowerCase() !== original.toLowerCase()) candidates.add(cleaned)

      const parts = cleaned.split(' ').filter(Boolean)
      if (parts.length > 0) {
        const last = parts[parts.length - 1]
        const singular = singularizeToken(last)
        if (singular && singular !== last) {
          const updated = [...parts]
          updated[updated.length - 1] = singular
          candidates.add(updated.join(' '))
        }
        const base = parts.join(' ')
        const raw = `${base} raw`
        const rawComma = `${base}, raw`
        const cooked = `${base} cooked`
        const cookedComma = `${base}, cooked`
        candidates.add(raw)
        candidates.add(rawComma)
        candidates.add(cooked)
        candidates.add(cookedComma)
      }

      return Array.from(candidates).filter((q) => q.toLowerCase() !== original.toLowerCase())
    }

    // LOCKED: Single-food search must use the local USDA library (foodLibraryItem) only.
    // Do not swap back to the external USDA API. See GUARD_RAILS.md for restore steps.
    const checkUsdaLibraryHealth = async () => {
      const now = Date.now()
      if (now - usdaHealthCache.checkedAt < 10 * 60 * 1000 && usdaHealthCache.count != null) return usdaHealthCache.count
      const count = await prisma.foodLibraryItem.count({ where: { source: { in: ['usda_foundation', 'usda_sr_legacy', 'usda_branded'] } } })
      usdaHealthCache = { count, checkedAt: now }
      return count
    }

    const searchUsdaSingleFood = async (value: string) => {
      const sources = ['usda_foundation', 'usda_sr_legacy']
      const attempt = async (q: string) => {
        if (!q) return []
        const found = await searchLocalFoods(q, { pageSize: limit, sources })
        return filterSingleFoodItems(found, value).filter(item => hasMacroData(item) && isFoodPreparationCompatible(item?.name, value))
      }

      const primary = await attempt(value)
      if (primary.length > 0) return primary

      const fallbacks = buildSingleFoodFallbacks(value)
      for (const fallback of fallbacks) {
        const next = await attempt(fallback)
        if (next.length > 0) return next
      }

      const libraryCount = await checkUsdaLibraryHealth()
      if (libraryCount < 100000) {
        console.warn(`USDA library looks thin (${libraryCount} rows). Consider re-importing USDA data.`)
      }
      if (localOnly) return []
      // As a last resort, hit USDA API so users still get results if the local library is empty.
      const remote = filterSingleFoodItems(await searchUsdaFoods(value, { pageSize: limit, dataType: 'generic' }), value)
        .filter(item => hasMacroData(item) && isFoodPreparationCompatible(item?.name, value))
      if (remote.length > 0) return remote
      for (const fallback of fallbacks) {
        const remoteNext = filterSingleFoodItems(await searchUsdaFoods(fallback, { pageSize: limit, dataType: 'generic' }), value)
          .filter(item => hasMacroData(item) && isFoodPreparationCompatible(item?.name, value))
        if (remoteNext.length > 0) return remoteNext
      }
      return []
    }

    const searchLocalPreferred = async (value: string, resolvedKind: 'packaged' | 'single') => {
      if (!value) return []
      if (resolvedKind === 'packaged') {
        const localPackaged = await searchLocalFoods(value, { pageSize: limit, sources: ['usda_branded'], mode: 'prefix' })
        return sortPackagedByAlphabeticalHierarchyAsc(localPackaged, value).slice(0, limit)
      }
      const [foundation, legacy, branded] = await Promise.all([
        searchLocalFoods(value, { pageSize: limit, sources: ['usda_foundation'] }),
        searchLocalFoods(value, { pageSize: limit, sources: ['usda_sr_legacy'] }),
        searchLocalFoods(value, { pageSize: limit, sources: ['usda_branded'] }),
      ])

      const combined = [...foundation, ...legacy, ...branded]
      const seen = new Set<string>()
      const deduped = combined.filter((item) => {
        const key = `${normalizeForMatch(item?.name)}|${normalizeForMatch(item?.brand)}`
        if (!key || key === '|') return false
        if (seen.has(key)) return false
        seen.add(key)
        return true
      })

      const filtered = filterItemsByQuery(deduped, value, (item) => item?.name || '')
      return sortByNameAsc(filtered).slice(0, limit)
    }

    if (source === 'auto' || !source || source === 'usda' || source === 'fatsecret' || source === 'openfoodfacts') {
      const resolvedKind = kind === 'packaged' ? 'packaged' : 'single'

      const scoredServing = (serving: string | null | undefined, calories?: number | null) => {
        const s = (serving || '').toLowerCase()
        if (!s) return 0
        let score = 1
        // Prefer real package servings over "100 g" defaults.
        if (s.includes('100 g') || s.includes('100g')) score -= isMealQuery ? 8 : 5
        if (s.includes('serving')) score += 2
        if (
          s.includes('piece') ||
          s.includes('biscuit') ||
          s.includes('cookie') ||
          s.includes('slice') ||
          s.includes('pack') ||
          s.includes('packet') ||
          s.includes('each')
        ) {
          score += 3
        }
        if (isMealQuery) {
          if (
            s.includes('kebab') ||
            s.includes('kebap') ||
            s.includes('shawarma') ||
            s.includes('doner') ||
            s.includes('gyro') ||
            s.includes('burger') ||
            s.includes('wrap') ||
            s.includes('burrito') ||
            s.includes('taco') ||
            s.includes('pizza') ||
            s.includes('sandwich') ||
            s.includes('roll') ||
            s.includes('sub') ||
            s.includes('pita')
          ) {
            score += 4
          }
          const cal = Number(calories)
          if (Number.isFinite(cal)) {
            if (cal >= 250 && cal <= 1200) score += 3
            if (cal > 0 && cal < 150) score -= 5
          }
        }
        return score
      }

      const parseServingGrams = (serving: any) => {
        const raw = String(serving || '').toLowerCase()
        const match = raw.match(/(\d+(?:\.\d+)?)\s*g\b/)
        if (!match) return null
        const grams = Number(match[1])
        return Number.isFinite(grams) ? grams : null
      }

      const mealKeywords = [
        'kebab',
        'kebap',
        'shawarma',
        'doner',
        'gyro',
        'burger',
        'wrap',
        'burrito',
        'taco',
        'pizza',
        'sandwich',
        'roll',
        'sub',
        'pita',
        'meal',
        'combo',
      ]
      const isMealQuery = queryTokensNormalized.some((token) => mealKeywords.includes(token))

      const restaurantKeywords = [
        'mcdonald',
        'mcdonalds',
        'burger king',
        'kfc',
        'subway',
        'domino',
        'pizza hut',
        'starbucks',
        'dunkin',
        'taco bell',
        'wendy',
        'popeyes',
        'chipotle',
        'panera',
        'chick fil',
        'chick-fil',
        'five guys',
        'in n out',
        'innout',
        'jack in the box',
        'carls jr',
        'hardees',
        'shake shack',
        'arby',
        'dairy queen',
        'white castle',
      ]
      const isRestaurantQuery = restaurantKeywords.some((keyword) => queryNorm.includes(keyword))

      const isLikelyFullMeal = (it: any) => {
        const servingText = String(it?.serving_size || '').toLowerCase()
        const grams = parseServingGrams(it?.serving_size)
        const calories = Number(it?.calories)
        const hasMealWord =
          servingText.includes('kebab') ||
          servingText.includes('kebap') ||
          servingText.includes('shawarma') ||
          servingText.includes('doner') ||
          servingText.includes('gyro') ||
          servingText.includes('burger') ||
          servingText.includes('wrap') ||
          servingText.includes('burrito') ||
          servingText.includes('taco') ||
          servingText.includes('pizza') ||
          servingText.includes('sandwich') ||
          servingText.includes('roll') ||
          servingText.includes('sub') ||
          servingText.includes('pita')
        if (typeof grams === 'number' && Number.isFinite(grams) && grams >= 120) return true
        if (hasMealWord && typeof grams === 'number' && Number.isFinite(grams) && grams >= 90) return true
        if (Number.isFinite(calories) && calories >= 250) return true
        return false
      }

      const scoreItem = (it: any) => {
        let score = 0
        score += scoreItemName(it)
        if (it?.source === 'custom') score += 8
        if (it?.source === 'usda') score += 4
        if (it?.source === 'fatsecret') score += isMealQuery ? 6 : 2
        if (it?.source === 'openfoodfacts') score += 1
        if (it?.brand) score += 2
        if (Number.isFinite(Number(it?.calories)) && Number(it.calories) > 0) score += 1
        score += scoredServing(it?.serving_size, it?.calories)
        if (isMealQuery) {
          const grams = parseServingGrams(it?.serving_size)
          if (typeof grams === 'number' && Number.isFinite(grams)) {
            if (grams >= 150 && grams <= 600) score += 6
            if (grams >= 90 && grams < 150) score += 2
            if (grams > 0 && grams < 80) score -= 6
          }
          if (it?.source === 'openfoodfacts' && typeof grams === 'number' && grams < 80) score -= 4
          if (it?.source === 'usda' && it?.brand) score += 2
          if (Number.isFinite(Number(it?.calories)) && Number(it.calories) < 150) score -= 4
        }
        return score
      }

      if (resolvedKind === 'single') {
        const combined = await buildSingleFoodResults(query)
        if (combined.length > 0) {
          items = combined
          actualSource = 'auto'
        } else {
          const usdaItems = await searchUsdaSingleFood(query)
          items = sortByAlphabeticalHierarchyAsc(usdaItems, query).slice(0, limit)
          actualSource = 'usda'
        }
      } else {
        const buildCompactFoodQuery = (value: string) => {
          const normalized = normalizeForMatch(value)
          if (!normalized) return null
          const compacted = normalized.replace(/\bcheese burger\b/g, 'cheeseburger')
          return compacted !== normalized ? compacted : null
        }

        const localPackaged = isRestaurantQuery ? [] : await searchLocalPreferred(query, 'packaged')

        const localFiltered = filterItemsByQuery(localPackaged, query, (item) => {
          const combined = [item?.brand, item?.name].filter(Boolean).join(' ')
          return combined || item?.name || ''
        })

        // Owner rule: our database first (custom + local), then OpenFoodFacts, then FatSecret.
        // Custom FAST_FOOD should appear first in packaged search.
        const customFastFood = customPackagedMatches.filter((it) => String(it?.kind || '') === 'FAST_FOOD')
        const customOther = customPackagedMatches.filter((it) => String(it?.kind || '') !== 'FAST_FOOD')
        const sortedCustom = [
          ...sortPackagedByAlphabeticalHierarchyAsc(customFastFood, query),
          ...sortPackagedByAlphabeticalHierarchyAsc(customOther, query),
        ]
        const sortedLocal = sortPackagedByAlphabeticalHierarchyAsc(localFiltered, query)

        const normalizeKey = (value: any) => String(value || '').trim().toLowerCase()
        const seen = new Set<string>()
        const combined: any[] = []
        const pushUnique = (it: any) => {
          if (!hasMacroData(it)) return
          const key = `${normalizeKey(it?.name)}|${normalizeKey(it?.brand)}`
          if (!key || key === '|') return
          if (seen.has(key)) return
          seen.add(key)
          combined.push(it)
        }

        sortedCustom.forEach(pushUnique)
        sortedLocal.forEach(pushUnique)

        if (!localOnly && combined.length < limit) {
          const externalTimeoutMs = combined.length > 0 ? 1200 : 8000
          const externalPageSize = Math.min(25, Math.max(limit, 10))
          const fetchPackagedExternalSorted = async (
            value: string,
            sourceType: 'openfoodfacts' | 'fatsecret',
          ) => {
            if (!value) return []
            const externalItems =
              sourceType === 'openfoodfacts'
                ? await searchOpenFoodFactsByQuery(value, {
                    pageSize: externalPageSize,
                    timeoutMs: Math.max(externalTimeoutMs + 1000, 3500),
                  })
                : await searchFatSecretFoods(value, {
                    pageSize: externalPageSize,
                    timeoutMs: Math.max(externalTimeoutMs + 1000, 3500),
                  })
            const filtered = filterItemsByQuery(externalItems, value, (item) => {
              const label = [item?.brand, item?.name].filter(Boolean).join(' ')
              return label || item?.name || ''
            })
            return sortPackagedByAlphabeticalHierarchyAsc(filtered, value)
          }

          const fetchPackagedExternalWithTimeout = async (
            value: string,
            sourceType: 'openfoodfacts' | 'fatsecret',
            timeoutMs = 1200,
          ) => {
            let timer: ReturnType<typeof setTimeout> | null = null
            try {
              const timeoutFallback = new Promise<any[]>((resolve) => {
                timer = setTimeout(() => resolve([]), timeoutMs)
              })
              return (await Promise.race([
                fetchPackagedExternalSorted(value, sourceType),
                timeoutFallback,
              ])) as any[]
            } catch {
              return []
            } finally {
              if (timer) clearTimeout(timer)
            }
          }

          const pushGroup = (group: any[]) => {
            for (const it of group) {
              if (combined.length >= limit) break
              pushUnique(it)
            }
          }

          const compactQuery = buildCompactFoodQuery(query)

          const [offPrimary, fatPrimary] = await Promise.all([
            fetchPackagedExternalWithTimeout(query, 'openfoodfacts', externalTimeoutMs),
            fetchPackagedExternalWithTimeout(query, 'fatsecret', externalTimeoutMs),
          ])

          pushGroup(offPrimary)
          pushGroup(fatPrimary)

          if (combined.length < limit && compactQuery) {
            const [offCompact, fatCompact] = await Promise.all([
              fetchPackagedExternalWithTimeout(compactQuery, 'openfoodfacts', externalTimeoutMs),
              fetchPackagedExternalWithTimeout(compactQuery, 'fatsecret', externalTimeoutMs),
            ])
            pushGroup(offCompact)
            pushGroup(fatCompact)
          }
        }

        items = combined.slice(0, limit)
        actualSource = 'auto'
        if (customPackagedMatches.length > 0) customPackagedApplied = true
      }
    }

    if (kindMode === 'packaged' && customPackagedMatches.length > 0 && !customPackagedApplied) {
      if (!Array.isArray(items) || items.length === 0) {
        items = sortPackagedByAlphabeticalHierarchyAsc(customPackagedMatches, query).slice(0, limit)
        customPackagedApplied = true
      }
    }

    if (kindMode === 'single' && Array.isArray(items) && items.length > 0) {
      const filtered = filterSingleFoodItems(items, query)
      items = filtered.length > 0 ? filtered : []
    }

    if (Array.isArray(items) && items.length > 0) {
      const filtered = items.filter((item) => hasMacroData(item))
      items = filtered
    }

    if (kindMode === 'single' && Array.isArray(items) && items.length > 0) {
      items = items.map((item) => normalizeSingleLiquidServing(item))
    }

    if (Array.isArray(items) && items.length > 1) {
      if (kindMode !== 'single') {
        // Keep the grouped order: Helfi database first, then FatSecret fallback.
        items = items.slice(0, limit)
      } else {
        items = items.slice(0, limit)
      }
    }

    return NextResponse.json({ success: true, source: actualSource, items })
  } catch (error) {
    console.error('GET /api/food-data error', error)
    return NextResponse.json({ success: false, error: 'Failed to fetch food data' }, { status: 500 })
  }
}

export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { fetchFatSecretServingOptions, fetchUsdaServingOptions } from '@/lib/food-data'
import { buildCustomFoodServingOptions } from '@/lib/food/custom-serving-options'
import { hasCoreFoodNutrition } from '@/lib/food/openfoodfacts'
import { prisma } from '@/lib/prisma'

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const source = (searchParams.get('source') || '').toLowerCase()
    const id = (searchParams.get('id') || '').trim()

    if (!source || !id) {
      return NextResponse.json(
        { success: false, error: 'Missing required parameters: source, id' },
        { status: 400 },
      )
    }

    const normalizedId = id.startsWith('custom:') ? id.slice('custom:'.length) : id

    if (source === 'custom' || id.startsWith('custom:')) {
      const item = await prisma.customFoodItem.findUnique({ where: { id: normalizedId } })
      const storedOptions = Array.isArray(item?.servingOptions) ? item.servingOptions : []
      const options =
        storedOptions.length > 0 || !item
          ? storedOptions
          : buildCustomFoodServingOptions({
              name: item.name,
              kind: item.kind,
              caloriesPer100g: item.caloriesPer100g,
              proteinPer100g: item.proteinPer100g,
              carbsPer100g: item.carbsPer100g,
              fatPer100g: item.fatPer100g,
              fiberPer100g: item.fiberPer100g,
              sugarPer100g: item.sugarPer100g,
            })
      return NextResponse.json({ success: true, source: 'custom', options: options.filter(hasCoreFoodNutrition) })
    }

    if (source === 'usda') {
      const options = await fetchUsdaServingOptions(id)
      return NextResponse.json({ success: true, source: 'usda', options: options.filter(hasCoreFoodNutrition) })
    }

    if (source === 'fatsecret') {
      const options = await fetchFatSecretServingOptions(id)
      return NextResponse.json({ success: true, source: 'fatsecret', options: options.filter(hasCoreFoodNutrition) })
    }

    return NextResponse.json(
      { success: false, error: 'Unsupported source. Expected usda or fatsecret.' },
      { status: 400 },
    )
  } catch (error) {
    console.error('GET /api/food-data/servings error', error)
    return NextResponse.json({ success: false, error: 'Failed to fetch serving options' }, { status: 500 })
  }
}

export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'

import { fetchUsdaServingOptions, searchLocalFoods } from '@/lib/food-data'
import { getFoodUnitGrams } from '@/lib/food/measurement-units'

type SizeUnit =
  | 'piece-small'
  | 'piece-medium'
  | 'piece-large'
  | 'piece-extra-large'
  | 'egg-small'
  | 'egg-medium'
  | 'egg-large'
  | 'egg-extra-large'

type SizeUnitGrams = Partial<Record<SizeUnit, number>>
type MatchedItem = {
  source: 'usda'
  id: string
  name: string
  brand?: string | null
  serving_size?: string | null
  calories?: number | null
  protein_g?: number | null
  carbs_g?: number | null
  fat_g?: number | null
  fiber_g?: number | null
  sugar_g?: number | null
}
type SizeLookupResponse = {
  unitGrams: SizeUnitGrams
  matchedItem: MatchedItem | null
}

const cache = new Map<string, SizeLookupResponse>()

const singularizeToken = (value: string) => {
  const lower = String(value || '').toLowerCase()
  if (!lower) return lower
  if (lower.endsWith('ies') && lower.length > 4) return `${lower.slice(0, -3)}y`
  if (
    lower.endsWith('es') &&
    lower.length > 3 &&
    !lower.endsWith('ses') &&
    !lower.endsWith('xes') &&
    !lower.endsWith('zes') &&
    !lower.endsWith('ches') &&
    !lower.endsWith('shes')
  ) {
    return lower.slice(0, -2)
  }
  if (lower.endsWith('s') && lower.length > 3 && !lower.endsWith('ss')) return lower.slice(0, -1)
  return lower
}

const normalizeText = (value: string) =>
  String(value || '')
    .toLowerCase()
    .replace(/&/g, ' and ')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .replace(/\s+/g, ' ')

const getTokens = (value: string) =>
  normalizeText(value)
    .split(' ')
    .filter(Boolean)
    .map((token) => singularizeToken(token))

const EGG_BLOCKLIST = new Set([
  'white',
  'yolk',
  'eggplant',
  'nog',
  'noodle',
  'pasta',
  'salad',
  'sandwich',
  'wrap',
  'burrito',
  'taco',
  'pizza',
  'burger',
  'muffin',
  'bagel',
  'roll',
  'cake',
  'cookie',
  'pancake',
  'waffle',
  'rice',
  'protein',
  'powder',
  'substitute',
  'mix',
])

const isEggFood = (name: string) => {
  const tokens = getTokens(name)
  if (!tokens.includes('egg')) return false
  return tokens.every((token) => !EGG_BLOCKLIST.has(token))
}

const hasPositive = (value: number | null | undefined) => Number.isFinite(Number(value)) && Number(value) > 0

const SIZE_UNITS: SizeUnit[] = [
  'piece-small',
  'piece-medium',
  'piece-large',
  'piece-extra-large',
  'egg-small',
  'egg-medium',
  'egg-large',
  'egg-extra-large',
]

const readBuiltInSizeUnits = (name: string): SizeUnitGrams => {
  const normalized = normalizeText(name)
  const liquidHints = /\b(water|milk|juice|coffee|tea|soda|cola|drink|beverage|smoothie|shake|broth|stock|soup|oil|vinegar|sauce|syrup)\b/
  if (liquidHints.test(normalized) && !isEggFood(name)) return {}

  const source = getFoodUnitGrams(name) || {}
  const unitGrams: SizeUnitGrams = {}
  SIZE_UNITS.forEach((unit) => {
    const grams = Number((source as any)[unit])
    if (Number.isFinite(grams) && grams > 0) unitGrams[unit] = Math.round(grams * 10) / 10
  })
  return unitGrams
}

const mergeSizeUnits = (primary: SizeUnitGrams, fallback: SizeUnitGrams): SizeUnitGrams => {
  const merged: SizeUnitGrams = { ...fallback }
  SIZE_UNITS.forEach((unit) => {
    const grams = Number(primary[unit])
    if (Number.isFinite(grams) && grams > 0) merged[unit] = Math.round(grams * 10) / 10
  })
  return merged
}

const scoreCandidate = (candidateName: string, requestedName: string) => {
  const candidateNorm = normalizeText(candidateName)
  const requestedNorm = normalizeText(requestedName)
  if (!candidateNorm || !requestedNorm) return 0
  if (candidateNorm === requestedNorm) return 2000
  if (candidateNorm.startsWith(requestedNorm)) return 1600

  const candidateTokens = getTokens(candidateName)
  const requestedTokens = getTokens(requestedName)
  let score = 0
  requestedTokens.forEach((token) => {
    if (candidateTokens.includes(token)) {
      score += 200
      return
    }
    if (candidateTokens.some((word) => word.startsWith(token))) score += 120
  })
  if (candidateNorm.includes(requestedNorm)) score += 160
  return score
}

const detectSizeUnit = (labelBase: string, eggFood: boolean): SizeUnit | null => {
  const lower = normalizeText(labelBase)
  if (!lower) return null
  if (
    lower.includes('cup') ||
    lower.includes('tablespoon') ||
    lower.includes('teaspoon') ||
    /\btbsp\b/.test(lower) ||
    /\btsp\b/.test(lower) ||
    /\boz\b/.test(lower) ||
    lower.includes('ounce') ||
    lower.includes('serving') ||
    lower.includes('portion') ||
    lower.includes('slice') ||
    lower.includes('wedge')
  ) {
    return null
  }

  const prefix = eggFood ? 'egg' : 'piece'
  if (/\b(extra large|extra-large|jumbo|xl)\b/.test(lower)) return `${prefix}-extra-large` as SizeUnit
  if (/\bsmall\b/.test(lower)) return `${prefix}-small` as SizeUnit
  if (/\bmedium\b/.test(lower)) return `${prefix}-medium` as SizeUnit
  if (/\blarge\b/.test(lower)) return `${prefix}-large` as SizeUnit
  return null
}

const mapServingOptionsToSizeUnits = (
  name: string,
  options: Array<{ label?: string; serving_size?: string; grams?: number | null }>,
): SizeUnitGrams => {
  const unitGrams: SizeUnitGrams = {}
  const eggFood = isEggFood(name)

  options.forEach((option) => {
    const grams = Number(option?.grams ?? 0)
    if (!Number.isFinite(grams) || grams <= 0) return

    const label = String(option?.label || option?.serving_size || '').trim()
    if (!label) return
    const labelBase = label.split('—')[0]?.trim() || label
    const unit = detectSizeUnit(labelBase, eggFood)
    if (!unit) return

    const current = Number(unitGrams[unit] ?? 0)
    if (!Number.isFinite(current) || current <= 0 || grams > current) {
      unitGrams[unit] = Math.round(grams * 10) / 10
    }
  })

  const extraLargeUnit = eggFood ? 'egg-extra-large' : 'piece-extra-large'
  const largeUnit = eggFood ? 'egg-large' : 'piece-large'
  const mediumUnit = eggFood ? 'egg-medium' : 'piece-medium'
  const smallUnit = eggFood ? 'egg-small' : 'piece-small'

  if (!hasPositive(unitGrams[extraLargeUnit]) && hasPositive(unitGrams[largeUnit]) && hasPositive(unitGrams[mediumUnit])) {
    unitGrams[extraLargeUnit] = Math.round((Number(unitGrams[largeUnit]) + (Number(unitGrams[largeUnit]) - Number(unitGrams[mediumUnit]))) * 10) / 10
  } else if (
    !hasPositive(unitGrams[extraLargeUnit]) &&
    hasPositive(unitGrams[largeUnit]) &&
    hasPositive(unitGrams[smallUnit])
  ) {
    unitGrams[extraLargeUnit] =
      Math.round((Number(unitGrams[largeUnit]) + (Number(unitGrams[largeUnit]) - Number(unitGrams[smallUnit])) / 2) * 10) /
      10
  }

  return unitGrams
}

const findBestUsdaItemForName = async (name: string): Promise<MatchedItem | null> => {
  const matches = await searchLocalFoods(name, {
    pageSize: 20,
    sources: ['usda_foundation', 'usda_sr_legacy'],
    mode: 'prefix-contains',
  })
  if (!Array.isArray(matches) || matches.length === 0) return null

  let best = matches[0] || null
  let bestScore = best ? scoreCandidate(best.name, name) : 0
  matches.slice(1).forEach((candidate) => {
    const score = scoreCandidate(candidate.name, name)
    if (score > bestScore) {
      best = candidate
      bestScore = score
    }
  })
  if (!best?.id) return null
  return {
    source: 'usda',
    id: String(best.id),
    name: String(best.name || '').trim(),
    brand: best.brand ?? null,
    serving_size: best.serving_size ?? null,
    calories: best.calories ?? null,
    protein_g: best.protein_g ?? null,
    carbs_g: best.carbs_g ?? null,
    fat_g: best.fat_g ?? null,
    fiber_g: best.fiber_g ?? null,
    sugar_g: best.sugar_g ?? null,
  }
}

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const name = String(searchParams.get('name') || '').trim()
    const source = String(searchParams.get('source') || '').trim().toLowerCase()
    const id = String(searchParams.get('id') || '').trim()

    if (!name) {
      return NextResponse.json({ success: false, error: 'Missing required parameter: name' }, { status: 400 })
    }

    const cacheKey = `${source}:${id}:${normalizeText(name)}`
    const cached = cache.get(cacheKey)
    if (cached) {
      return NextResponse.json({ success: true, ...cached })
    }

    let matchedItem: MatchedItem | null = source === 'usda' && id ? { source: 'usda', id, name } : null
    if (!matchedItem) matchedItem = await findBestUsdaItemForName(name)
    const usdaId = matchedItem?.id ? String(matchedItem.id) : null

    if (!usdaId) {
      const emptyResponse = { unitGrams: {}, matchedItem: null }
      cache.set(cacheKey, emptyResponse)
      return NextResponse.json({ success: true, ...emptyResponse })
    }

    const builtInUnitGrams = readBuiltInSizeUnits(name)
    const options = await fetchUsdaServingOptions(usdaId)
    const unitGrams = mergeSizeUnits(builtInUnitGrams, mapServingOptionsToSizeUnits(name, options))
    const response = {
      unitGrams,
      matchedItem: Object.keys(unitGrams).length > 0 ? matchedItem : null,
    }
    cache.set(cacheKey, response)
    return NextResponse.json({ success: true, ...response })
  } catch (error) {
    console.error('GET /api/food-data/size-units error', error)
    return NextResponse.json({ success: false, error: 'Failed to fetch size units' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import OpenAI from 'openai'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { CreditManager } from '@/lib/credit-system'
import { runChatCompletionWithLogging } from '@/lib/ai-usage-logger'
import { consumeRateLimit } from '@/lib/rate-limit'

const HEALTH_CHECK_COST_CREDITS = 2
const RATE_LIMIT_WINDOW_MS = 60_000
const RATE_LIMIT_MAX_REQUESTS = 6

const parseJsonSafe = (raw: string | null) => {
  if (!raw) return null
  try {
    return JSON.parse(raw)
  } catch {
    return null
  }
}

const parseSelectedIssues = (healthGoals: any[]) => {
  try {
    const selectedRecord = healthGoals.find((goal: any) => goal?.name === '__SELECTED_ISSUES__')
    const parsed = parseJsonSafe(selectedRecord?.category || null)
    if (Array.isArray(parsed)) {
      return parsed
        .map((name) => String(name || '').trim())
        .filter((name) => name.length > 0)
    }
  } catch {}

  return healthGoals
    .filter((goal: any) => typeof goal?.name === 'string' && !goal.name.startsWith('__'))
    .map((goal: any) => String(goal.name || '').trim())
    .filter((name: string) => name.length > 0)
}

const parseDietTypes = (healthGoals: any[]) => {
  try {
    const storedDiet = healthGoals.find((goal: any) => goal?.name === '__DIET_PREFERENCE__')
    const parsed = parseJsonSafe(storedDiet?.category || null)
    const raw = Array.isArray(parsed?.dietTypes) ? parsed.dietTypes : parsed?.dietType
    if (Array.isArray(raw)) {
      return raw.map((diet: any) => String(diet || '').trim()).filter(Boolean)
    }
    if (typeof raw === 'string' && raw.trim().length > 0) return [raw.trim()]
  } catch {}
  return []
}

const parseProfileInfo = (healthGoals: any[]) => {
  try {
    const storedProfile = healthGoals.find((goal: any) => goal?.name === '__PROFILE_INFO__')
    const parsed = parseJsonSafe(storedProfile?.category || null)
    if (parsed && typeof parsed === 'object') {
      return {
        dateOfBirth: typeof parsed?.dateOfBirth === 'string' ? parsed.dateOfBirth : '',
      }
    }
  } catch {}
  return { dateOfBirth: '' }
}

const parsePrimaryGoal = (healthGoals: any[]) => {
  try {
    const storedGoal = healthGoals.find((goal: any) => goal?.name === '__PRIMARY_GOAL__')
    const parsed = parseJsonSafe(storedGoal?.category || null)
    if (parsed && typeof parsed === 'object') {
      return {
        goalChoice: typeof parsed?.goalChoice === 'string' ? parsed.goalChoice : '',
        goalIntensity: typeof parsed?.goalIntensity === 'string' ? parsed.goalIntensity : '',
      }
    }
  } catch {}
  return { goalChoice: '', goalIntensity: '' }
}

const normalizeTotals = (raw: any) => {
  if (!raw || typeof raw !== 'object') return null
  const toNumber = (value: any) => {
    const parsed = typeof value === 'string' ? parseFloat(value) : Number(value)
    return Number.isFinite(parsed) ? parsed : null
  }
  return {
    calories: toNumber(raw.calories ?? raw.kcal ?? raw.energy ?? raw.cal),
    protein: toNumber(raw.protein ?? raw.protein_g),
    carbs: toNumber(raw.carbs ?? raw.carbs_g),
    fat: toNumber(raw.fat ?? raw.fat_g),
    fiber: toNumber(raw.fiber ?? raw.fiber_g),
    sugar: toNumber(raw.sugar ?? raw.sugar_g),
  }
}

const formatNumber = (value: number | null) => {
  if (value === null || !Number.isFinite(value)) return 'unknown'
  const rounded = Math.round(value * 10) / 10
  return String(rounded)
}

const computeAge = (dob?: string | null) => {
  if (!dob) return null
  const date = new Date(dob)
  if (Number.isNaN(date.getTime())) return null
  const now = new Date()
  let age = now.getFullYear() - date.getFullYear()
  const monthDiff = now.getMonth() - date.getMonth()
  if (monthDiff < 0 || (monthDiff === 0 && now.getDate() < date.getDate())) {
    age -= 1
  }
  return age > 0 && age < 130 ? age : null
}

const parseHealthCheckJson = (raw: string) => {
  const blockMatch = raw.match(/<HEALTH_CHECK>([\s\S]*?)<\/HEALTH_CHECK>/i)
  if (blockMatch && blockMatch[1]) {
    const parsed = parseJsonSafe(blockMatch[1].trim())
    if (parsed && typeof parsed === 'object') return parsed
  }
  const looseMatch = raw.match(/\{[\s\S]*\}/)
  if (looseMatch && looseMatch[0]) {
    const parsed = parseJsonSafe(looseMatch[0])
    if (parsed && typeof parsed === 'object') return parsed
  }
  return null
}

const HEALTH_TRIGGER_THRESHOLDS = {
  sugar: 30,
  carbs: 90,
  fat: 35,
} as const

const HEALTHY_FAT_KEYWORDS = [
  'salmon',
  'sardine',
  'tuna',
  'mackerel',
  'trout',
  'avocado',
  'olive oil',
  'olives',
  'nuts',
  'almond',
  'walnut',
  'pistachio',
  'macadamia',
  'hazelnut',
  'pecan',
  'chia',
  'flax',
  'linseed',
  'hemp',
  'seeds',
  'sunflower',
  'pumpkin',
  'peanut',
  'tahini',
] as const

const escapeRegex = (value: string) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

const containsHealthyFat = (text: string) => {
  const lower = text.toLowerCase()
  return HEALTHY_FAT_KEYWORDS.some((keyword) => {
    const needle = keyword.toLowerCase()
    if (needle.includes(' ')) return lower.includes(needle)
    try {
      return new RegExp(`\\b${escapeRegex(needle)}\\b`).test(lower)
    } catch {
      return lower.includes(needle)
    }
  })
}

const resolveThresholds = (raw: any) => {
  const sugar = Number(raw?.sugar)
  const carbs = Number(raw?.carbs)
  const fat = Number(raw?.fat)
  return {
    sugar: Number.isFinite(sugar) && sugar > 0 ? sugar : HEALTH_TRIGGER_THRESHOLDS.sugar,
    carbs: Number.isFinite(carbs) && carbs > 0 ? carbs : HEALTH_TRIGGER_THRESHOLDS.carbs,
    fat: Number.isFinite(fat) && fat > 0 ? fat : HEALTH_TRIGGER_THRESHOLDS.fat,
  }
}

const buildTriggerFlags = (
  totals: ReturnType<typeof normalizeTotals> | null,
  thresholds: ReturnType<typeof resolveThresholds>,
  options?: { allowHealthyFat?: boolean; itemText?: string }
) => {
  if (!totals) return []
  const flags: string[] = []
  if (typeof totals.sugar === 'number' && totals.sugar > thresholds.sugar) {
    flags.push(`Sugar ${formatNumber(totals.sugar)}g > ${thresholds.sugar}g`)
  }
  if (typeof totals.carbs === 'number' && totals.carbs > thresholds.carbs) {
    flags.push(`Carbs ${formatNumber(totals.carbs)}g > ${thresholds.carbs}g`)
  }
  if (typeof totals.fat === 'number' && totals.fat > thresholds.fat) {
    const itemText = options?.itemText || ''
    const allowHealthy = options?.allowHealthyFat !== false
    const hasHealthyFat = allowHealthy && itemText ? containsHealthyFat(itemText) : false
    const margin = hasHealthyFat ? 20 : 12
    if (totals.fat >= thresholds.fat + margin) {
      flags.push(`Fat ${formatNumber(totals.fat)}g > ${thresholds.fat}g`)
    }
  }
  return flags
}

const buildTriggerDetails = (
  totals: ReturnType<typeof normalizeTotals> | null,
  thresholds: ReturnType<typeof resolveThresholds>,
  options?: { allowHealthyFat?: boolean; itemText?: string }
) => {
  if (!totals) return []
  const triggers: Array<{ key: string; label: string; value: number; limit: number; unit: string }> = []
  if (typeof totals.sugar === 'number' && totals.sugar > thresholds.sugar) {
    triggers.push({
      key: 'sugar',
      label: 'Sugar',
      value: totals.sugar,
      limit: thresholds.sugar,
      unit: 'g',
    })
  }
  if (typeof totals.carbs === 'number' && totals.carbs > thresholds.carbs) {
    triggers.push({
      key: 'carbs',
      label: 'Carbs',
      value: totals.carbs,
      limit: thresholds.carbs,
      unit: 'g',
    })
  }
  if (typeof totals.fat === 'number' && totals.fat > thresholds.fat) {
    const itemText = options?.itemText || ''
    const allowHealthy = options?.allowHealthyFat !== false
    const hasHealthyFat = allowHealthy && itemText ? containsHealthyFat(itemText) : false
    const margin = hasHealthyFat ? 20 : 12
    if (totals.fat < thresholds.fat + margin) {
      return triggers
    }
    triggers.push({
      key: 'fat',
      label: 'Fat',
      value: totals.fat,
      limit: thresholds.fat,
      unit: 'g',
    })
  }
  return triggers
}

export async function POST(req: NextRequest) {
  const session = await getServerSession(authOptions)
  if (!session?.user?.email) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const clientIp = (req.headers.get('x-forwarded-for') || '').split(',')[0]?.trim() || 'unknown'
  const rateKey = (session.user as any)?.id ? `user:${(session.user as any).id}` : `ip:${clientIp}`
  const rateCheck = await consumeRateLimit('food-health-check', rateKey, RATE_LIMIT_MAX_REQUESTS, RATE_LIMIT_WINDOW_MS)
  if (!rateCheck.allowed) {
    const retryAfter = Math.max(1, Math.ceil(rateCheck.retryAfterMs / 1000))
    return NextResponse.json(
      { error: 'Too many health checks. Please wait and try again.' },
      { status: 429, headers: { 'Retry-After': String(retryAfter) } },
    )
  }

  const user = await prisma.user.findUnique({
    where: { email: session.user.email },
    include: { subscription: true, healthGoals: { orderBy: { updatedAt: 'desc' } } },
  })
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  const body = await req.json().catch(() => null)
  const description = typeof body?.description === 'string' ? body.description.trim() : ''
  const totals = normalizeTotals(body?.totals)
  const itemNames = Array.isArray(body?.items)
    ? body.items
        .map((item: any) => String(item?.name || item?.label || '').trim())
        .filter((name: string) => name.length > 0)
        .slice(0, 12)
    : []
  const thresholds = resolveThresholds(body?.thresholds)
  const itemText = [description, itemNames.join(' ')].filter(Boolean).join(' ').trim()

  if (!description && itemNames.length === 0) {
    return NextResponse.json({ error: 'Missing meal data' }, { status: 400 })
  }

  const selectedIssues = parseSelectedIssues(user.healthGoals || [])
  const dietTypes = parseDietTypes(user.healthGoals || [])
  const profileInfo = parseProfileInfo(user.healthGoals || [])
  const primaryGoal = parsePrimaryGoal(user.healthGoals || [])

  const age = computeAge(profileInfo.dateOfBirth)
  const userContextParts = [
    user.gender ? `Gender: ${String(user.gender).toLowerCase()}` : null,
    Number.isFinite(user.weight) ? `Weight: ${user.weight} kg` : null,
    Number.isFinite(user.height) ? `Height: ${user.height} cm` : null,
    age ? `Age: ${age}` : null,
    primaryGoal.goalChoice ? `Goal: ${primaryGoal.goalChoice}` : null,
    primaryGoal.goalIntensity ? `Goal pace: ${primaryGoal.goalIntensity}` : null,
  ].filter(Boolean)

  const triggerFlags = buildTriggerFlags(totals, thresholds, { itemText })
  const triggerDetails = buildTriggerDetails(totals, thresholds, { itemText })
  const mealParts = [
    description ? `Meal: ${description}` : null,
    itemNames.length ? `Items: ${itemNames.join(', ')}` : null,
    totals
      ? `Totals: ${formatNumber(totals.calories)} kcal, ${formatNumber(totals.protein)}g protein, ${formatNumber(totals.carbs)}g carbs, ${formatNumber(totals.fat)}g fat, ${formatNumber(totals.fiber)}g fiber, ${formatNumber(totals.sugar)}g sugar`
      : null,
    triggerFlags.length ? `Triggered by: ${triggerFlags.join('; ')}` : null,
  ].filter(Boolean)

  const prompt = [
    'You are a nutrition coach helping a user avoid foods that conflict with their health goals and diets.',
    'Explain why the meal is problematic for each selected health issue separately. Be specific to that issue and tie it to the macros or ingredients.',
    'If fat is coming from healthier sources (salmon, olive oil, avocado, nuts, seeds), call that out and do not overstate risk unless sugar/carbs are also high.',
    'Write 2-3 sentences per issue, with practical and clear reasoning.',
    'Give one clear swap suggestion that stays similar to the meal, not generic.',
    'If the meal is acceptable, say so briefly and still give a lighter swap.',
    '',
    `Health goals/issues: ${selectedIssues.length ? selectedIssues.join(', ') : 'none listed'}.`,
    `Diet preferences: ${dietTypes.length ? dietTypes.join(', ') : 'none listed'}.`,
    userContextParts.length ? `User: ${userContextParts.join('; ')}.` : '',
    mealParts.join('\n'),
    '',
    'Return JSON between <HEALTH_CHECK> tags with exactly:',
    '{"summary":"string","issues":[{"issue":"string","why":"string"}],"alternative":"string"}',
  ]
    .filter(Boolean)
    .join('\n')

  if (!process.env.OPENAI_API_KEY) {
    return NextResponse.json({ error: 'AI service not configured' }, { status: 500 })
  }

  const cm = new CreditManager(user.id)
  const wallet = await cm.getWalletStatus()
  if (wallet.totalAvailableCents < HEALTH_CHECK_COST_CREDITS) {
    return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
  }

  const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY })
  let content = ''
  try {
    const completion = await runChatCompletionWithLogging(
      openai,
      {
        model: 'gpt-5.6-sol',
        messages: [{ role: 'user', content: prompt }],
        max_tokens: 350,
        temperature: 0.4,
      } as any,
      {
        feature: 'food:health-check',
        userId: user.id,
        userLabel: user.email,
        endpoint: '/api/food-health-check',
      },
    )
    const raw = (completion as any)?.choices?.[0]?.message?.content
    content = typeof raw === 'string' ? raw : Array.isArray(raw) ? raw.map((part: any) => part?.text || '').join('') : ''
  } catch (err) {
    console.error('[food-health-check] AI error', err)
    return NextResponse.json({ error: 'AI failed' }, { status: 500 })
  }

  const parsed = parseHealthCheckJson(content)
  const summary = typeof parsed?.summary === 'string' ? parsed.summary.trim() : ''
  const rawIssues = Array.isArray(parsed?.issues) ? parsed.issues : []
  const issues = rawIssues
    .map((item: any) => ({
      issue: typeof item?.issue === 'string' ? item.issue.trim() : '',
      why: typeof item?.why === 'string' ? item.why.trim() : '',
    }))
    .filter((item: any) => item.issue && item.why)
    .slice(0, 6)
  const alternative = typeof parsed?.alternative === 'string' ? parsed.alternative.trim() : ''
  if (!summary && issues.length === 0 && !alternative) {
    return NextResponse.json({ error: 'Invalid AI response' }, { status: 502 })
  }

  const charged = await cm.chargeCents(HEALTH_CHECK_COST_CREDITS)
  if (!charged) {
    return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
  }

  return NextResponse.json({
    summary: summary || 'This meal may not fully support your current goals.',
    issues,
    alternative: alternative || 'Try a similar meal with less added sugar and more protein.',
    flags: triggerFlags,
    triggers: triggerDetails,
    costCredits: HEALTH_CHECK_COST_CREDITS,
  })
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { getToken } from 'next-auth/jwt'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { normalizeMealCategory } from '@/lib/food-log-categories'
import { deleteFoodPhotosIfUnused } from '@/lib/food-photo-storage'

// Atomic delete endpoint (Food Diary ghost-entry hardening)
//
// Goal: delete DB rows (including conservative duplicate sweeps) AND update the server
// todaysFoods snapshot (__TODAYS_FOODS_DATA__) in the same request so iOS PWA background/resume
// can't resurrect stale cards after refresh.
//
// This endpoint is designed to be idempotent-ish: if the row is already gone, it still succeeds
// and will apply the snapshot update if provided.
export async function POST(request: NextRequest) {
  try {
    let userEmail: string | null = null
    try {
      const session = await getServerSession(authOptions)
      userEmail = session?.user?.email ?? null
    } catch (sessionError) {
      console.error('POST /api/food-log/delete-atomic - getServerSession failed (will try JWT fallback):', sessionError)
    }

    // Match /api/food-log patterns: JWT fallback because getServerSession can be unreliable on some clients.
    if (!userEmail) {
      try {
        const token = await getToken({
          req: request,
          secret: process.env.NEXTAUTH_SECRET || process.env.AUTH_SECRET || 'helfi-secret-key-production-2024',
        })
        if (token?.email) {
          userEmail = String(token.email)
        }
      } catch (tokenError) {
        console.error('POST /api/food-log/delete-atomic - JWT fallback failed:', tokenError)
      }
    }

    if (!userEmail) {
      return NextResponse.json({ error: 'Not authenticated' }, { status: 401 })
    }

    const user = await prisma.user.findUnique({ where: { email: userEmail } })
    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    const body = await request.json().catch(() => ({} as any))

    const requestedIdRaw = (body as any)?.id
    const requestedId = typeof requestedIdRaw === 'string' ? requestedIdRaw.trim() : requestedIdRaw ? String(requestedIdRaw) : ''

    const rawDesc = typeof (body as any)?.description === 'string' ? String((body as any).description).trim() : ''
    const rawCategory = typeof (body as any)?.category === 'string' ? String((body as any).category).trim() : ''
    const category = rawCategory ? normalizeMealCategory(rawCategory) : null
    const rawClientId = typeof (body as any)?.clientId === 'string' ? String((body as any).clientId).trim() : ''
    const rawCreatedAt = (body as any)?.createdAt ?? (body as any)?.createdAtMs ?? null
    let targetCreatedAtMs: number | null = null
    if (typeof rawCreatedAt === 'number' && Number.isFinite(rawCreatedAt)) {
      targetCreatedAtMs = rawCreatedAt
    } else if (typeof rawCreatedAt === 'string' && rawCreatedAt.trim()) {
      const parsed = new Date(rawCreatedAt)
      if (!Number.isNaN(parsed.getTime())) {
        targetCreatedAtMs = parsed.getTime()
      }
    }

    const datePattern = /^\d{4}-\d{2}-\d{2}$/
    const snapshotDateRaw = typeof (body as any)?.snapshotDate === 'string' ? String((body as any).snapshotDate).slice(0, 10) : ''
    const snapshotDate = datePattern.test(snapshotDateRaw) ? snapshotDateRaw : ''

    const datesRaw = Array.isArray((body as any)?.dates) ? ((body as any).dates as any[]) : []
    const dates = Array.from(
      new Set(
        datesRaw
          .map((d) => (typeof d === 'string' ? d.slice(0, 10) : ''))
          .filter((d) => datePattern.test(d)),
      ),
    ).slice(0, 12)

    const snapshotFoodsRaw = Array.isArray((body as any)?.snapshotFoods) ? ((body as any).snapshotFoods as any[]) : null

    const deletedIds = new Set<string>()
    let deletedCount = 0
    const imageUrlsToCheck = new Set<string>()

    // 1) Delete by id + conservative duplicate sweep (fast path + anti-ghost).
    if (requestedId) {
      try {
        const existing = await prisma.foodLog.findUnique({ where: { id: requestedId as any } })
        if (existing && existing.userId === user.id) {
          if (typeof existing.imageUrl === 'string' && existing.imageUrl.trim()) {
            imageUrlsToCheck.add(existing.imageUrl.trim())
          }
          const rawText = String(existing.description || existing.name || '').trim()
          const normalizeDesc = (value: string) => value.split('\n')[0].trim().toLowerCase()
          const targetDesc = normalizeDesc(rawText)
          const needle = rawText.split('\n')[0].trim().slice(0, 140)
          const createdAt = existing.createdAt instanceof Date ? existing.createdAt : new Date(existing.createdAt as any)
          const createdAtMs = createdAt && !Number.isNaN(createdAt.getTime()) ? createdAt.getTime() : NaN
          const targetCategory = normalizeMealCategory((existing as any).meal ?? (existing as any).category) || 'uncategorized'
          const targetMs = Number.isFinite(createdAtMs) ? createdAtMs : null
          const targetLocalDate = typeof (existing as any).localDate === 'string' ? String((existing as any).localDate) : ''
          const targetClientId = rawClientId || (existing as any)?.nutrients?.__clientId || ''

          const shouldSweep = needle.length >= 12 && Number.isFinite(createdAtMs)
          if (shouldSweep) {
            const MATCH_WINDOW_MS = 2000
            const WINDOW_HOURS = 6
            const windowStart = new Date(createdAtMs - WINDOW_HOURS * 60 * 60 * 1000)
            const windowEnd = new Date(createdAtMs + WINDOW_HOURS * 60 * 60 * 1000)

            const addDays = (dateStr: string, delta: number) => {
              const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr)
              if (!m) return ''
              const y = parseInt(m[1], 10)
              const mo = parseInt(m[2], 10)
              const d = parseInt(m[3], 10)
              if (!Number.isFinite(y) || !Number.isFinite(mo) || !Number.isFinite(d)) return ''
              const dt = new Date(Date.UTC(y, mo - 1, d))
              dt.setUTCDate(dt.getUTCDate() + delta)
              return dt.toISOString().slice(0, 10)
            }

            const baseLocalDate = typeof (existing as any).localDate === 'string' ? String((existing as any).localDate) : ''
            const candidateDates = Array.from(
              new Set(
                [
                  baseLocalDate,
                  baseLocalDate ? addDays(baseLocalDate, -1) : '',
                  baseLocalDate ? addDays(baseLocalDate, 1) : '',
                  baseLocalDate ? addDays(baseLocalDate, -2) : '',
                  baseLocalDate ? addDays(baseLocalDate, 2) : '',
                ].filter((d) => typeof d === 'string' && d.length >= 8),
              ),
            )

            const duplicates = await prisma.foodLog.findMany({
              where: {
                userId: user.id,
                OR: [
                  { id: requestedId as any },
                  {
                    createdAt: { gte: windowStart, lte: windowEnd },
                    OR: [
                      { description: { contains: needle, mode: 'insensitive' } },
                      { name: { contains: needle, mode: 'insensitive' } },
                    ],
                  },
                  candidateDates.length > 0
                    ? {
                        localDate: { in: candidateDates },
                        OR: [
                          { description: { contains: needle, mode: 'insensitive' } },
                          { name: { contains: needle, mode: 'insensitive' } },
                        ],
                      }
                    : undefined,
                ].filter(Boolean) as any,
              },
              select: { id: true, imageUrl: true, description: true, name: true, createdAt: true, meal: true, category: true, localDate: true, nutrients: true },
            })

            const filtered = duplicates.filter((row) => {
              const rowDesc = normalizeDesc(String(row.description || row.name || ''))
              if (!rowDesc || rowDesc !== targetDesc) return false
              if (targetClientId) {
                const rowClientId = typeof (row as any)?.nutrients?.__clientId === 'string' ? String((row as any).nutrients.__clientId) : ''
                if (!rowClientId || rowClientId !== targetClientId) return false
              }
              const rowCategory = normalizeMealCategory((row as any)?.meal ?? (row as any)?.category) || 'uncategorized'
              const catMatches =
                rowCategory === targetCategory ||
                rowCategory === 'uncategorized' ||
                targetCategory === 'uncategorized'
              if (!catMatches) return false
              if (targetLocalDate) {
                const rowLocalDate = typeof (row as any)?.localDate === 'string' ? String((row as any).localDate) : ''
                if (rowLocalDate && rowLocalDate !== targetLocalDate) return false
              }
              if (targetMs !== null) {
                const rowMs = row.createdAt ? new Date(row.createdAt as any).getTime() : NaN
                if (!Number.isFinite(rowMs)) return false
                if (Math.abs(rowMs - targetMs) > MATCH_WINDOW_MS) return false
              }
              return true
            })

            filtered.forEach((row) => {
              if (typeof row.imageUrl === 'string' && row.imageUrl.trim()) {
                imageUrlsToCheck.add(row.imageUrl.trim())
              }
            })
            const ids = Array.from(new Set([requestedId, ...filtered.map((d) => d.id)])).slice(0, 50)
            if (ids.length > 0) {
              const result = await prisma.foodLog.deleteMany({
                where: { userId: user.id, id: { in: ids } },
              })
              deletedCount += result.count
              ids.forEach((id) => deletedIds.add(String(id)))
            }
          } else {
            await prisma.foodLog.delete({ where: { id: requestedId as any } })
            deletedCount += 1
            deletedIds.add(String(requestedId))
          }
        }
      } catch (err) {
        // Best-effort: if id delete fails, fall through to description delete + snapshot update.
        console.warn('AGENT_DEBUG', JSON.stringify({ hypothesisId: 'A', location: 'app/api/food-log/delete-atomic/route.ts:POST:id', message: 'Delete-by-id/sweep failed (best-effort)', data: { idPrefix: String(requestedId).slice(0, 8) }, timestamp: Date.now() }))
      }
    }

    // 2) Delete by description/category across dates (server-side sweep, safer than client multi-fetch).
    // Caller provides `dates` (usually selected day + nearby days). We also support a conservative
    // uncategorized sweep on the target day only, because some server rows may miss meal/category.
    const descForServer = rawDesc ? rawDesc.slice(0, 220) : ''
    const targetDay = snapshotDate || (dates[0] || '')
    if (descForServer) {
      try {
        const categoriesToTry: (string | null)[] = []
        if (category) {
          categoriesToTry.push(category)
          if (category !== 'uncategorized' && targetDay) {
            categoriesToTry.push('uncategorized')
          }
        } else {
          categoriesToTry.push(null)
        }

        for (const cat of categoriesToTry) {
          const whereClause: any = {
            userId: user.id,
            OR: [
              { description: { contains: descForServer, mode: 'insensitive' } },
              { name: { contains: descForServer, mode: 'insensitive' } },
            ],
          }
          if (cat) {
            whereClause.AND = whereClause.AND || []
            whereClause.AND.push({ meal: normalizeMealCategory(cat) })
          }
          if (dates.length > 0) {
            whereClause.AND = whereClause.AND || []
            whereClause.AND.push({ localDate: { in: cat === 'uncategorized' && targetDay ? [targetDay] : dates } })
          }
          if (targetCreatedAtMs !== null) {
            const windowStart = new Date(targetCreatedAtMs - 2000)
            const windowEnd = new Date(targetCreatedAtMs + 2000)
            whereClause.AND = whereClause.AND || []
            whereClause.AND.push({ createdAt: { gte: windowStart, lte: windowEnd } })
          }

          const matches = await prisma.foodLog.findMany({
            where: whereClause,
            select: { id: true, imageUrl: true, nutrients: true, createdAt: true },
            take: 50,
          })

          const filteredMatches = matches.filter((row) => {
            if (!rawClientId) return true
            const rowClientId = typeof (row as any)?.nutrients?.__clientId === 'string' ? String((row as any).nutrients.__clientId) : ''
            return Boolean(rowClientId) && rowClientId === rawClientId
          })
          filteredMatches.forEach((row) => {
            if (typeof row.imageUrl === 'string' && row.imageUrl.trim()) {
              imageUrlsToCheck.add(row.imageUrl.trim())
            }
          })
          const ids = Array.from(new Set(filteredMatches.map((m) => String(m.id)))).filter(Boolean).slice(0, 50)
          if (ids.length > 0) {
            const result = await prisma.foodLog.deleteMany({
              where: { userId: user.id, id: { in: ids } },
            })
            deletedCount += result.count
            ids.forEach((id) => deletedIds.add(id))
          }
        }
      } catch (err) {
        console.warn('AGENT_DEBUG', JSON.stringify({ hypothesisId: 'A', location: 'app/api/food-log/delete-atomic/route.ts:POST:desc', message: 'Delete-by-description sweep failed (best-effort)', timestamp: Date.now() }))
      }
    }

    // 3) Snapshot sync: if client provided snapshotFoods, write them now; otherwise attempt to
    // remove deleted ids from the existing snapshot record.
    let snapshotUpdated = false
    let snapshotCount: number | null = null
    try {
      const snapshotKeyName = '__TODAYS_FOODS_DATA__'

      const writeSnapshotFoods = async (foods: any[]) => {
        await prisma.healthGoal.deleteMany({
          where: { userId: user.id, name: snapshotKeyName },
        })
        if (foods.length > 0) {
          await prisma.healthGoal.create({
            data: {
              userId: user.id,
              name: snapshotKeyName,
              category: JSON.stringify({ foods }),
              currentRating: 0,
            },
          })
        }
      }

      if (snapshotFoodsRaw && snapshotFoodsRaw.length >= 0 && snapshotDate) {
        // Trust client to have already minimized/limited; we only ensure date scoping + cap.
        const scoped = snapshotFoodsRaw
          .filter((e) => e && typeof e === 'object')
          .map((e) => ({
            ...e,
            localDate:
              typeof (e as any)?.localDate === 'string' && (e as any).localDate.length >= 8
                ? String((e as any).localDate).slice(0, 10)
                : snapshotDate,
          }))
          .filter((e) => String((e as any).localDate || '') === snapshotDate)
        const capped = scoped.slice(0, 300)
        await writeSnapshotFoods(capped)
        snapshotUpdated = true
        snapshotCount = capped.length
      } else if (deletedIds.size > 0) {
        const existing = await prisma.healthGoal.findFirst({
          where: { userId: user.id, name: snapshotKeyName },
          select: { id: true, category: true },
        })
        if (existing?.category) {
          let parsed: any = null
          try {
            parsed = JSON.parse(String(existing.category))
          } catch {}
          const foods = Array.isArray(parsed?.foods) ? parsed.foods : []
          const filtered = foods.filter((f: any) => {
            const dbId = f && (f.dbId || f.id) ? String(f.dbId || '') : ''
            if (dbId && deletedIds.has(dbId)) return false
            return true
          })
          await writeSnapshotFoods(filtered)
          snapshotUpdated = true
          snapshotCount = filtered.length
        }
      }
    } catch (err) {
      console.warn('AGENT_DEBUG', JSON.stringify({ hypothesisId: 'A', location: 'app/api/food-log/delete-atomic/route.ts:POST:snapshot', message: 'Snapshot sync failed (best-effort)', timestamp: Date.now() }))
    }

    try {
      await deleteFoodPhotosIfUnused(Array.from(imageUrlsToCheck))
    } catch (cleanupError) {
      console.warn('AGENT_DEBUG', JSON.stringify({ hypothesisId: 'PHOTO_CLEAN', location: 'app/api/food-log/delete-atomic/route.ts:POST:cleanup', message: 'Food photo cleanup failed (non-blocking)', timestamp: Date.now() }))
      console.warn(cleanupError)
    }

    return NextResponse.json({
      success: true,
      deleted: deletedCount,
      deletedIds: Array.from(deletedIds),
      snapshotUpdated,
      snapshotCount,
    })
  } catch (error) {
    console.error('POST /api/food-log/delete-atomic error', error)
    return NextResponse.json({ error: 'Failed to delete log' }, { status: 500 })
  }
}

