// Danger zone endpoint: delete matching food logs by description + category for the authenticated user.
// Used as a last-resort cleaner when client-side deletes fail due to mismatched IDs or dates.
export async function POST(request: NextRequest) {
  try {
    let session
    let userEmail: string | null = null
    try {
      session = await getServerSession(authOptions)
      userEmail = session?.user?.email ?? null
    } catch (sessionError) {
      console.error('POST /api/food-log/delete-by-description - getServerSession failed (will try JWT fallback):', sessionError)
    }

    if (!userEmail) {
      try {
        const token = await getToken({
          req: request,
          secret: process.env.NEXTAUTH_SECRET || process.env.AUTH_SECRET || 'helfi-secret-key-production-2024',
        })
        if (token?.email) {
          userEmail = String(token.email)
        }
      } catch (tokenError) {
        console.error('POST /api/food-log/delete-by-description - JWT fallback failed:', tokenError)
      }
    }

    if (!userEmail) {
      return NextResponse.json({ error: 'Not authenticated' }, { status: 401 })
    }

    const user = await prisma.user.findUnique({ where: { email: userEmail } })
    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    const body = await request.json().catch(() => ({} as any))
    const rawDesc = String((body as any)?.description || '').trim()
    const rawCategory = String((body as any)?.category || '').trim()
    const rawClientId = typeof (body as any)?.clientId === 'string' ? String((body as any).clientId).trim() : ''
    const rawCreatedAt = (body as any)?.createdAt ?? (body as any)?.createdAtMs ?? null
    let targetCreatedAtMs: number | null = null
    if (typeof rawCreatedAt === 'number' && Number.isFinite(rawCreatedAt)) {
      targetCreatedAtMs = rawCreatedAt
    } else if (typeof rawCreatedAt === 'string' && rawCreatedAt.trim()) {
      const parsed = new Date(rawCreatedAt)
      if (!Number.isNaN(parsed.getTime())) {
        targetCreatedAtMs = parsed.getTime()
      }
    }
    const targetDates = Array.isArray((body as any)?.dates)
      ? ((body as any).dates as string[]).filter((d) => typeof d === 'string' && d.length >= 8)
      : []

    if (!rawDesc) {
      return NextResponse.json({ error: 'Missing description' }, { status: 400 })
    }

    const category = rawCategory ? normalizeMealCategory(rawCategory) : null
    const descLower = rawDesc.toLowerCase()

    const whereClause: any = {
      userId: user.id,
      OR: [
        { description: { contains: rawDesc, mode: 'insensitive' } },
        { name: { contains: rawDesc, mode: 'insensitive' } },
      ],
    }

    if (category) {
      whereClause.AND = [{ meal: normalizeMealCategory(category) }]
    }

    if (targetDates.length > 0) {
      whereClause.AND = whereClause.AND || []
      whereClause.AND.push({ localDate: { in: targetDates } })
    }
    if (targetCreatedAtMs !== null) {
      const windowStart = new Date(targetCreatedAtMs - 2000)
      const windowEnd = new Date(targetCreatedAtMs + 2000)
      whereClause.AND = whereClause.AND || []
      whereClause.AND.push({ createdAt: { gte: windowStart, lte: windowEnd } })
    }

    const matches = await prisma.foodLog.findMany({
      where: whereClause,
      select: { id: true, description: true, meal: true, localDate: true, imageUrl: true, nutrients: true, createdAt: true },
    })

    const filteredMatches = rawClientId
      ? matches.filter((row) => {
          const rowClientId = typeof (row as any)?.nutrients?.__clientId === 'string' ? String((row as any).nutrients.__clientId) : ''
          return Boolean(rowClientId) && rowClientId === rawClientId
        })
      : matches

    // #region agent log
    try {
      console.log('AGENT_DEBUG', JSON.stringify({hypothesisId:'D',location:'app/api/food-log/delete-by-description/route.ts:POST',message:'Delete-by-description match summary',data:{rawDescLen:rawDesc.length,category,datesCount:targetDates.length,matchesCount:filteredMatches.length,sample:filteredMatches.slice(0,3).map(m=>({idPrefix:String(m.id).slice(0,8),meal:m.meal||null,localDate:m.localDate||null}))},timestamp:Date.now()}));
    } catch {}
    // #endregion agent log

    if (!filteredMatches.length) {
      return NextResponse.json({ success: true, deleted: 0 })
    }

    const ids = filteredMatches.map((m) => m.id)
    const result = await prisma.foodLog.deleteMany({
      where: { id: { in: ids }, userId: user.id },
    })

    try {
      await deleteFoodPhotosIfUnused(filteredMatches.map((row) => row.imageUrl))
    } catch (cleanupError) {
      console.warn('AGENT_DEBUG', JSON.stringify({ hypothesisId: 'PHOTO_CLEAN', location: 'app/api/food-log/delete-by-description/route.ts:POST:cleanup', message: 'Food photo cleanup failed (non-blocking)', timestamp: Date.now() }))
      console.warn(cleanupError)
    }

    return NextResponse.json({ success: true, deleted: result.count, ids })
  } catch (error) {
    console.error('POST /api/food-log/delete-by-description error', error)
    return NextResponse.json({ error: 'Failed to delete logs' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { getToken } from 'next-auth/jwt'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { deleteFoodPhotosIfUnused } from '@/lib/food-photo-storage'
import { normalizeMealCategory } from '@/lib/food-log-categories'

// Delete a specific food log (by id) for the authenticated user
export async function POST(request: NextRequest) {
  try {
    let session
    let userEmail: string | null = null
    try {
      session = await getServerSession(authOptions)
      userEmail = session?.user?.email ?? null
    } catch (sessionError) {
      console.error('POST /api/food-log/delete - getServerSession failed (will try JWT fallback):', sessionError)
    }

    // Match /api/food-log GET: JWT fallback because getServerSession can be unreliable on some clients.
    if (!userEmail) {
      try {
        const token = await getToken({
          req: request,
          secret: process.env.NEXTAUTH_SECRET || process.env.AUTH_SECRET || 'helfi-secret-key-production-2024',
        })
        if (token?.email) {
          userEmail = String(token.email)
        }
      } catch (tokenError) {
        console.error('POST /api/food-log/delete - JWT fallback failed:', tokenError)
      }
    }

    if (!userEmail) {
      return NextResponse.json({ error: 'Not authenticated' }, { status: 401 })
    }

    const user = await prisma.user.findUnique({ where: { email: userEmail } })
    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    const body = await request.json().catch(() => ({} as any))
    const id = String((body as any)?.id || '').trim()
    if (!id) {
      return NextResponse.json({ error: 'Missing id' }, { status: 400 })
    }

    console.log('AGENT_DEBUG', JSON.stringify({hypothesisId:'E',location:'app/api/food-log/delete/route.ts:POST',message:'Delete-by-id requested',data:{idLen:id.length,idPrefix:id.slice(0,8)},timestamp:Date.now()}));

    // Ensure the log belongs to the user
    const existing = await prisma.foodLog.findUnique({ where: { id: id as any } })
    if (!existing || existing.userId !== user.id) {
      return NextResponse.json({ error: 'Not found' }, { status: 404 })
    }
    const imageUrlsToCheck = new Set<string>()
    if (typeof existing.imageUrl === 'string' && existing.imageUrl.trim()) {
      imageUrlsToCheck.add(existing.imageUrl.trim())
    }

    // Many users have duplicate FoodLog rows that represent one visible "meal card".
    // Deleting a single row can appear to work, but the "ghost" resurfaces after refresh
    // because other near-identical rows still exist. To prevent resurrection, do a
    // conservative duplicate sweep around the deleted row.
    let deletedCount = 0
    try {
      const rawText = String(existing.description || existing.name || '').trim()
      const normalizeDesc = (value: string) => value.split('\n')[0].trim().toLowerCase()
      const targetDesc = normalizeDesc(rawText)
      const needle = rawText.split('\n')[0].trim().slice(0, 140)
      const createdAt = existing.createdAt instanceof Date ? existing.createdAt : new Date(existing.createdAt as any)
      const createdAtMs = createdAt && !Number.isNaN(createdAt.getTime()) ? createdAt.getTime() : NaN
      const targetCategory = normalizeMealCategory((existing as any).meal ?? (existing as any).category) || 'uncategorized'
      const targetMs = Number.isFinite(createdAtMs) ? createdAtMs : null
      const targetLocalDate = typeof (existing as any).localDate === 'string' ? String((existing as any).localDate) : ''

      // Only do a sweep when we have a meaningful text seed (avoid nuking short placeholder rows like "0").
      const shouldSweep = needle.length >= 12 && Number.isFinite(createdAtMs)
      if (shouldSweep) {
        const MATCH_WINDOW_MS = 5000
        const WINDOW_HOURS = 6
        const windowStart = new Date(createdAtMs - WINDOW_HOURS * 60 * 60 * 1000)
        const windowEnd = new Date(createdAtMs + WINDOW_HOURS * 60 * 60 * 1000)

        const addDays = (dateStr: string, delta: number) => {
          const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr)
          if (!m) return ''
          const y = parseInt(m[1], 10)
          const mo = parseInt(m[2], 10)
          const d = parseInt(m[3], 10)
          if (!Number.isFinite(y) || !Number.isFinite(mo) || !Number.isFinite(d)) return ''
          const dt = new Date(Date.UTC(y, mo - 1, d))
          dt.setUTCDate(dt.getUTCDate() + delta)
          return dt.toISOString().slice(0, 10)
        }

        const baseLocalDate = typeof (existing as any).localDate === 'string' ? String((existing as any).localDate) : ''
        const candidateDates = Array.from(
          new Set(
            [
              baseLocalDate,
              baseLocalDate ? addDays(baseLocalDate, -1) : '',
              baseLocalDate ? addDays(baseLocalDate, 1) : '',
              baseLocalDate ? addDays(baseLocalDate, -2) : '',
              baseLocalDate ? addDays(baseLocalDate, 2) : '',
            ].filter((d) => typeof d === 'string' && d.length >= 8),
          ),
        )

        const duplicates = await prisma.foodLog.findMany({
          where: {
            userId: user.id,
            OR: [
              // Always include the requested id
              { id: id as any },
              // Time-window match (handles wrong/missing localDate rows that leak across days)
              {
                createdAt: { gte: windowStart, lte: windowEnd },
                OR: [
                  { description: { contains: needle, mode: 'insensitive' } },
                  { name: { contains: needle, mode: 'insensitive' } },
                ],
              },
              // LocalDate match (handles rows with correct localDate but slightly different createdAt)
              candidateDates.length > 0
                ? {
                    localDate: { in: candidateDates },
                    OR: [
                      { description: { contains: needle, mode: 'insensitive' } },
                      { name: { contains: needle, mode: 'insensitive' } },
                    ],
                  }
                : undefined,
            ].filter(Boolean) as any,
          },
          select: { id: true, imageUrl: true, description: true, name: true, createdAt: true, meal: true, category: true, localDate: true },
        })

        const filtered = duplicates.filter((row) => {
          const rowDesc = normalizeDesc(String(row.description || row.name || ''))
          if (!rowDesc || rowDesc !== targetDesc) return false
          const rowCategory = normalizeMealCategory((row as any)?.meal ?? (row as any)?.category) || 'uncategorized'
          const catMatches =
            rowCategory === targetCategory ||
            rowCategory === 'uncategorized' ||
            targetCategory === 'uncategorized'
          if (!catMatches) return false
          if (targetLocalDate) {
            const rowLocalDate = typeof (row as any)?.localDate === 'string' ? String((row as any).localDate) : ''
            if (rowLocalDate && rowLocalDate !== targetLocalDate) return false
          }
          if (targetMs !== null) {
            const rowMs = row.createdAt ? new Date(row.createdAt as any).getTime() : NaN
            if (!Number.isFinite(rowMs)) return false
            if (Math.abs(rowMs - targetMs) > MATCH_WINDOW_MS) return false
          }
          return true
        })

        filtered.forEach((row) => {
          if (typeof row.imageUrl === 'string' && row.imageUrl.trim()) {
            imageUrlsToCheck.add(row.imageUrl.trim())
          }
        })
        const ids = Array.from(new Set([id, ...filtered.map((d) => d.id)])).slice(0, 50)
        const result = await prisma.foodLog.deleteMany({
          where: { userId: user.id, id: { in: ids } },
        })
        deletedCount = result.count

        console.log(
          'AGENT_DEBUG',
          JSON.stringify({
            hypothesisId: 'A',
            location: 'app/api/food-log/delete/route.ts:POST:sweep',
            message: 'Delete-by-id duplicate sweep executed',
            data: { requestedIdPrefix: id.slice(0, 8), needleLen: needle.length, candidateDatesCount: candidateDates.length, deletedCount },
            timestamp: Date.now(),
          }),
        )
      } else {
        await prisma.foodLog.delete({ where: { id: id as any } })
        deletedCount = 1
        console.log(
          'AGENT_DEBUG',
          JSON.stringify({
            hypothesisId: 'A',
            location: 'app/api/food-log/delete/route.ts:POST:sweep',
            message: 'Delete-by-id duplicate sweep skipped (insufficient seed); deleted single row',
            data: { requestedIdPrefix: id.slice(0, 8), needleLen: needle.length, deletedCount },
            timestamp: Date.now(),
          }),
        )
      }
    } catch (sweepErr) {
      // Fall back to single-row delete if sweep fails for any reason.
      try {
        await prisma.foodLog.delete({ where: { id: id as any } })
        deletedCount = Math.max(deletedCount, 1)
      } catch {}
      console.warn('AGENT_DEBUG', JSON.stringify({ hypothesisId: 'A', location: 'app/api/food-log/delete/route.ts:POST:sweep', message: 'Duplicate sweep failed; fell back to single-row delete', data: { requestedIdPrefix: id.slice(0, 8) }, timestamp: Date.now() }))
    }

    try {
      await deleteFoodPhotosIfUnused(Array.from(imageUrlsToCheck))
    } catch (cleanupError) {
      console.warn('AGENT_DEBUG', JSON.stringify({ hypothesisId: 'PHOTO_CLEAN', location: 'app/api/food-log/delete/route.ts:POST:cleanup', message: 'Food photo cleanup failed (non-blocking)', timestamp: Date.now() }))
      console.warn(cleanupError)
    }

    return NextResponse.json({ success: true, deleted: deletedCount })
  } catch (error) {
    console.error('POST /api/food-log/delete error', error)
    return NextResponse.json({ error: 'Failed to delete log' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth/next'
import { getToken } from 'next-auth/jwt'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'

export const dynamic = 'force-dynamic'

// Health check endpoint to quickly verify food diary consistency for the
// authenticated user. Returns counts of FoodLog rows for a date, todaysFoods
// snapshot length, favorites length, and a short list of recent FoodLog entries.
// Usage: GET /api/food-log/health?date=YYYY-MM-DD
export async function GET(request: NextRequest) {
  let userEmail: string | null = null
  try {
    let session = await getServerSession(authOptions)
    userEmail = session?.user?.email ?? null
    let usedTokenFallback = false

    if (!userEmail) {
      try {
        const token = await getToken({
          req: request,
          secret: process.env.NEXTAUTH_SECRET || process.env.AUTH_SECRET || 'helfi-secret-key-production-2024',
        })
        if (token?.email) {
          userEmail = String(token.email)
          usedTokenFallback = true
        }
      } catch (tokenError) {
        console.error('food-log health JWT fallback failed', tokenError)
      }
    }

    if (!userEmail) {
      return NextResponse.json({ error: 'Not authenticated' }, { status: 401 })
    }

    const user = await prisma.user.findUnique({ where: { email: userEmail } })
    if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

    const { searchParams } = new URL(request.url)
    const dateStr = searchParams.get('date') || ''
    const datePattern = /^\d{4}-\d{2}-\d{2}$/
    const targetDate = datePattern.test(dateStr) ? dateStr : null

    // Pull favorites count
    let favoritesCount = 0
    try {
      const favGoal = await prisma.healthGoal.findFirst({
        where: { userId: user.id, name: '__FOOD_FAVORITES__' },
      })
      if (favGoal?.category) {
        const parsed = JSON.parse(favGoal.category)
        const favs = Array.isArray(parsed?.favorites) ? parsed.favorites : Array.isArray(parsed) ? parsed : []
        favoritesCount = favs.length
      }
    } catch (favErr) {
      console.warn('health check: failed to load favorites', favErr)
    }

    // Pull todaysFoods snapshot count
    let todaysFoodsCount = 0
    try {
      const tfGoal = await prisma.healthGoal.findFirst({
        where: { userId: user.id, name: '__TODAYS_FOODS_DATA__' },
      })
      if (tfGoal?.category) {
        const parsed = JSON.parse(tfGoal.category)
        const foods = Array.isArray(parsed?.foods) ? parsed.foods : []
        todaysFoodsCount = foods.length
      }
    } catch (tfErr) {
      console.warn('health check: failed to load todaysFoods snapshot', tfErr)
    }

