    const logs = await prisma.foodLog.findMany({
      where: { userId: user.id },
      select: { id: true, createdAt: true, localDate: true, nutrients: true },
      orderBy: { createdAt: 'desc' },
    })

    const updates = logs
      .map((log) => ({
        id: log.id,
        current: log.localDate || null,
