const isSugarFreeLabel = (value: any) => {
  const text = String(value || '').toLowerCase()
  if (!text) return false
  return (
    /\bsugar[-\s]?free\b/.test(text) ||
    /\bno\s+sugar\b/.test(text) ||
    /\bwith\s+no\s+sugar\b/.test(text)
  )
}

const readFiniteNumber = (source: any, key: string): number | null => {
  if (!source || typeof source !== 'object') return null
  const raw = (source as any)[key]
  const parsed = Number(raw)
  return Number.isFinite(parsed) ? parsed : null
}

const normalizeSugarFreeHotChocolatePayload = (input: {
  description: any
  nutrition: any
  items: any
}) => {
  // DO NOT TOUCH - OWNER LOCK (HEL-162):
  // Final server safety net for Water -> Food drink calories.
  // Keep these rules:
  // - `free` keeps base drink nutrition (small base kcal), never ml-scaled.
  // - `sugar`/`honey` uses sweetener-only calories/macros from sweetener metadata.
  // - Legacy sugar-free rows without full metadata must still self-heal safely.
  // Recovery if broken:
  // 1) Keep `hasSweetenerContext` branch as the first guard.
  // 2) Keep `isSugarHoney` split behavior (`free` base drink, sugar/honey sweetener-only).
  // 3) Keep legacy fallback that blocks inflated values and writes safe fields to nutrition/items.
  const baseNutrition =
    input.nutrition && typeof input.nutrition === 'object' ? { ...(input.nutrition as any) } : null
  if (!baseNutrition) {
    return { nutrition: input.nutrition, items: input.items, changed: false }
  }

  const itemList = Array.isArray(input.items) ? input.items : []
  const drinkType = normalizeDrinkTypeLabel((baseNutrition as any).__drinkType)

  const sweetenerCalories = Math.max(0, readFiniteNumber(baseNutrition, '__sweetenerCalories') || 0)
  const sweetenerCarbs = Math.max(0, readFiniteNumber(baseNutrition, '__sweetenerCarbs') || 0)
  const sweetenerSugar = Math.max(0, readFiniteNumber(baseNutrition, '__sweetenerSugar') || 0)
  const baseDrinkCaloriesRaw =
    readFiniteNumber(baseNutrition, 'calories') ??
    readFiniteNumber(baseNutrition, 'kcal') ??
    0
  const baseDrinkCarbsRaw =
    readFiniteNumber(baseNutrition, 'carbs') ??
    readFiniteNumber(baseNutrition, 'carbs_g') ??
    0
  const baseDrinkSugarRaw =
    readFiniteNumber(baseNutrition, 'sugar') ??
    readFiniteNumber(baseNutrition, 'sugar_g') ??
    0
  const safeBaseDrinkCalories =
    Number.isFinite(Number(baseDrinkCaloriesRaw)) &&
    Number(baseDrinkCaloriesRaw) > 0 &&
    Number(baseDrinkCaloriesRaw) <= 80
      ? Number(baseDrinkCaloriesRaw)
      : 8
  const sweetenerChoice = String(
    (baseNutrition as any).__sweetenerChoice ||
      (baseNutrition as any).__sweetenerType ||
      '',
  )
    .trim()
    .toLowerCase()
  const hasSweetenerMetaValues =
    readFiniteNumber(baseNutrition, '__sweetenerCalories') !== null ||
    readFiniteNumber(baseNutrition, '__sweetenerCarbs') !== null ||
    readFiniteNumber(baseNutrition, '__sweetenerSugar') !== null
  const hasSweetenerContext =
    Boolean(drinkType) &&
    (sweetenerChoice === 'free' ||
      sweetenerChoice === 'sugar' ||
      sweetenerChoice === 'honey' ||
      hasSweetenerMetaValues)
  const round1 = (value: number) => Math.round(value * 10) / 10

  if (hasSweetenerContext) {
    const isSugarHoney = sweetenerChoice === 'sugar' || sweetenerChoice === 'honey'
    const lockedCalories = isSugarHoney ? sweetenerCalories : safeBaseDrinkCalories
    const lockedCarbs = isSugarHoney
      ? sweetenerCarbs
      : Number.isFinite(Number(baseDrinkCarbsRaw)) && Number(baseDrinkCarbsRaw) >= 0 && Number(baseDrinkCarbsRaw) <= 20
      ? Number(baseDrinkCarbsRaw)
      : 0
    const lockedSugar = isSugarHoney
      ? sweetenerSugar
      : Number.isFinite(Number(baseDrinkSugarRaw)) && Number(baseDrinkSugarRaw) >= 0 && Number(baseDrinkSugarRaw) <= 20
      ? Number(baseDrinkSugarRaw)
      : 0

    const normalizedNutrition = {
      ...baseNutrition,
      calories: Math.round(lockedCalories),
      protein: 0,
      carbs: round1(lockedCarbs),
      fat: 0,
      fiber: 0,
      sugar: round1(lockedSugar),
      protein_g: 0,
      carbs_g: round1(lockedCarbs),
      fat_g: 0,
      fiber_g: 0,
      sugar_g: round1(lockedSugar),
      __sweetenerChoice: isSugarHoney ? sweetenerChoice : 'free',
      __sweetenerCalories: isSugarHoney ? lockedCalories : 0,
      __sweetenerCarbs: isSugarHoney ? round1(lockedCarbs) : 0,
      __sweetenerSugar: isSugarHoney ? round1(lockedSugar) : 0,
    }

    let normalizedItems = input.items
    if (itemList.length === 1 && itemList[0] && typeof itemList[0] === 'object') {
      const single = { ...(itemList[0] as any) }
      single.calories = Math.round(lockedCalories)
      single.protein_g = 0
      single.carbs_g = round1(lockedCarbs)
      single.fat_g = 0
      single.fiber_g = 0
      single.sugar_g = round1(lockedSugar)
      normalizedItems = [single]
    }

    return { nutrition: normalizedNutrition, items: normalizedItems, changed: true }
  }

  if (drinkType !== HOT_CHOCOLATE_KEY) {
    return { nutrition: input.nutrition, items: input.items, changed: false }
  }

  const looksSugarFree =
    isSugarFreeLabel((baseNutrition as any).__drinkType) ||
    isSugarFreeLabel(input.description) ||
    itemList.some((item) => isSugarFreeLabel((item as any)?.name || (item as any)?.label || ''))
  if (!looksSugarFree) {
    return { nutrition: input.nutrition, items: input.items, changed: false }
  }

  // Backward guard for older sugar-free hot chocolate rows without new sweetener context.
  const legacyCalories =
    Number.isFinite(Number(baseDrinkCaloriesRaw)) &&
    Number(baseDrinkCaloriesRaw) > 0 &&
    Number(baseDrinkCaloriesRaw) <= 80
      ? Number(baseDrinkCaloriesRaw)
      : 8
  const legacyCarbs =
    Number.isFinite(Number(baseDrinkCarbsRaw)) && Number(baseDrinkCarbsRaw) >= 0 && Number(baseDrinkCarbsRaw) <= 20
      ? Number(baseDrinkCarbsRaw)
      : 0
  const legacySugar =
    Number.isFinite(Number(baseDrinkSugarRaw)) && Number(baseDrinkSugarRaw) >= 0 && Number(baseDrinkSugarRaw) <= 20
      ? Number(baseDrinkSugarRaw)
      : 0
  const normalizedNutrition = {
    ...baseNutrition,
    calories: Math.round(legacyCalories),
    protein: 0,
    carbs: round1(legacyCarbs),
    fat: 0,
    fiber: 0,
    sugar: round1(legacySugar),
    protein_g: 0,
    carbs_g: round1(legacyCarbs),
    fat_g: 0,
    fiber_g: 0,
    sugar_g: round1(legacySugar),
    __sweetenerChoice: 'free',
    __sweetenerCalories: 0,
    __sweetenerCarbs: 0,
    __sweetenerSugar: 0,
  }

  let normalizedItems = input.items
  if (itemList.length === 1 && itemList[0] && typeof itemList[0] === 'object') {
    const single = { ...(itemList[0] as any) }
    single.calories = Math.round(legacyCalories)
    single.protein_g = 0
    single.carbs_g = round1(legacyCarbs)
    single.fat_g = 0
    single.fiber_g = 0
    single.sugar_g = round1(legacySugar)
    normalizedItems = [single]
  }

  return { nutrition: normalizedNutrition, items: normalizedItems, changed: true }
}

const dataUrlToBuffer = (value: string) => {
  const match = /^data:(image\/[a-zA-Z0-9.+-]+);base64,(.+)$/.exec(value)
  if (!match) return null
  const contentType = match[1]
  const buffer = Buffer.from(match[2], 'base64')
  return { contentType, buffer }
}

const contentTypeToExt = (contentType: string) => {
  if (contentType === 'image/png') return 'png'
  if (contentType === 'image/webp') return 'webp'
  if (contentType === 'image/gif') return 'gif'
  return 'jpg'
}

