  return NextResponse.json({ status: 'ok' })
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'
import { prisma } from '@/lib/prisma'
import { ensureHealthJournalSchema } from '@/lib/health-journal-db'

export const dynamic = 'force-dynamic'

async function resolveHealthJournalUserId(request: NextRequest) {
  const nativeUserId = await getUserIdFromNativeAuth(request)
  if (nativeUserId) return nativeUserId

  const session = await getServerSession(authOptions)
  return session?.user?.id || null
}

export async function PATCH(request: NextRequest, { params }: { params: { id: string } }) {
  const userId = await resolveHealthJournalUserId(request)
  if (!userId) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  await ensureHealthJournalSchema()

  const entryId = String(params?.id || '').trim()
  if (!entryId) {
    return NextResponse.json({ error: 'Missing entry id' }, { status: 400 })
  }

  const body = await request.json().catch(() => ({}))
  const content = String(body?.content || '').trim()
  if (!content) {
    return NextResponse.json({ error: 'Missing content' }, { status: 400 })
  }

  const existing = await prisma.healthJournalEntry.findFirst({
    where: { id: entryId, userId },
  })
  if (!existing) {
    return NextResponse.json({ error: 'Not found' }, { status: 404 })
  }

  const entry = await prisma.healthJournalEntry.update({
    where: { id: entryId },
    data: { content },
  })

  return NextResponse.json({ entry })
}

export async function DELETE(request: NextRequest, { params }: { params: { id: string } }) {
  const userId = await resolveHealthJournalUserId(request)
  if (!userId) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  await ensureHealthJournalSchema()

  const entryId = String(params?.id || '').trim()
  if (!entryId) {
    return NextResponse.json({ error: 'Missing entry id' }, { status: 400 })
  }

  const existing = await prisma.healthJournalEntry.findFirst({
    where: { id: entryId, userId },
  })
  if (!existing) {
    return NextResponse.json({ error: 'Not found' }, { status: 404 })
  }

  await prisma.healthJournalEntry.delete({ where: { id: entryId } })
  return NextResponse.json({ ok: true })
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import OpenAI from 'openai'

import { authOptions } from '@/lib/auth'
import { assertAiUsageAllowed, isAiSafetyError } from '@/lib/ai-safety'
import { logAiUsageEvent, runChatCompletionWithLogging } from '@/lib/ai-usage-logger'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'
import { prisma } from '@/lib/prisma'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const MAX_IMAGE_BYTES = 6 * 1024 * 1024
const MAX_AUDIO_BYTES = 12 * 1024 * 1024

const trimSummary = (value: string, fallback: string) => {
  const clean = String(value || '').replace(/\s+/g, ' ').trim()
  if (!clean) return fallback
  return clean.slice(0, 600)
}

const getOpenAIClient = () => {
  if (!process.env.OPENAI_API_KEY) return null
  return new OpenAI({ apiKey: process.env.OPENAI_API_KEY })
}

async function resolveUserId(request: NextRequest): Promise<string | null> {
  const nativeUserId = await getUserIdFromNativeAuth(request)
  if (nativeUserId) return nativeUserId

  const session = await getServerSession(authOptions)
  if (session?.user?.id) return session.user.id
  if (session?.user?.email) {
    const user = await prisma.user.findUnique({
      where: { email: session.user.email },
      select: { id: true },
    })
    if (user?.id) return user.id
  }
  return null
}

const summarizeImage = async (client: OpenAI, file: File, userId: string) => {
  const imageBuffer = await file.arrayBuffer()
  const base64 = Buffer.from(imageBuffer).toString('base64')
  const completion: any = await runChatCompletionWithLogging(
    client,
    {
      model: 'gpt-5.6-sol',
      temperature: 0.2,
      max_tokens: 140,
      messages: [
        {
          role: 'system',
          content:
            'You write short practical health journal notes. Be factual and neutral. Keep it under two short sentences.',
        },
        {
          role: 'user',
          content: [
            {
              type: 'text',
              text:
                'Summarize useful health context from this photo for a weekly health report. Include visible text if present. Do not include private identifiers.',
            },
            {
              type: 'image_url',
              image_url: {
                url: `data:${file.type || 'image/jpeg'};base64,${base64}`,
                detail: 'low',
              },
            },
          ],
        },
      ],
    } as any,
    {
      feature: 'health-journal:extract-image',
      userId,
      endpoint: '/api/health-journal/extract-media',
    },
    {
      image: {
        width: null,
        height: null,
        bytes: file.size,
        mime: file.type || null,
      },
    },
  )

  return trimSummary(
    completion.choices?.[0]?.message?.content || '',
    'Image summarized for health journal context.',
  )
}

const transcribeAudio = async (client: OpenAI, file: File, userId: string) => {
  const model = process.env.HEALTH_JOURNAL_MEDIA_AUDIO_MODEL || 'gpt-4o-mini-transcribe'
  const response = await client.audio.transcriptions.create({
    model,
    file,
    response_format: 'text',
  } as any)

  await logAiUsageEvent({
    feature: 'health-journal:extract-audio',
    userId,
    endpoint: '/api/health-journal/extract-media',
    model,
    promptTokens: 0,
    completionTokens: 0,
    costCents: 0,
    success: true,
    detail: 'audio transcription',
  })

  const text = typeof response === 'string' ? response : (response as any)?.text || ''
  return trimSummary(text, 'Voice note summarized for health journal context.')
}

export async function POST(request: NextRequest) {
  try {
    const userId = await resolveUserId(request)
    if (!userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const formData: any = await request.formData().catch(() => null)
    if (!formData) {
      return NextResponse.json({ error: 'Invalid upload data' }, { status: 400 })
    }

    const rawKind = String(formData.get('kind') || '').trim().toLowerCase()
    const kind = rawKind === 'audio' ? 'audio' : rawKind === 'image' ? 'image' : null
    const file = formData.get('file')

    if (!kind) {
      return NextResponse.json({ error: 'Missing media type' }, { status: 400 })
    }

    if (!(file instanceof File)) {
      return NextResponse.json({ error: 'No media file provided' }, { status: 400 })
    }

    if (kind === 'image') {
      if (!file.type.startsWith('image/')) {
        return NextResponse.json({ error: 'File must be an image' }, { status: 400 })
      }
      if (file.size > MAX_IMAGE_BYTES) {
        return NextResponse.json({ error: 'Image must be less than 6MB' }, { status: 400 })
      }
    } else {
      if (!file.type.startsWith('audio/')) {
        return NextResponse.json({ error: 'File must be audio' }, { status: 400 })
      }
      if (file.size > MAX_AUDIO_BYTES) {
        return NextResponse.json({ error: 'Audio must be less than 12MB' }, { status: 400 })
      }
    }

    const openai = getOpenAIClient()
    if (!openai) {
      const fallback =
        kind === 'image'
          ? 'Image summarized for health journal context.'
          : 'Voice note summarized for health journal context.'
      return NextResponse.json({ success: true, kind, summary: fallback, ai: false })
    }

    await assertAiUsageAllowed({
      feature: kind === 'image' ? 'health-journal:extract-image' : 'health-journal:extract-audio',
      userId,
    })

    const summary = kind === 'image'
      ? await summarizeImage(openai, file, userId)
      : await transcribeAudio(openai, file, userId)

    return NextResponse.json({ success: true, kind, summary, ai: true })
  } catch (error) {
    if (isAiSafetyError(error)) {
      return NextResponse.json(
        { error: 'AI uploads are temporarily paused because usage climbed too fast. Please try again shortly.' },
        { status: 429 },
      )
    }
    const userId = await resolveUserId(request).catch(() => null)
    if (userId) {
      logAiUsageEvent({
        feature: 'health-journal:extract-media',
        userId,
        endpoint: '/api/health-journal/extract-media',
        model: 'unknown',
        promptTokens: 0,
        completionTokens: 0,
        costCents: 0,
        success: false,
        errorMessage: error instanceof Error ? error.message : 'unknown_error',
      }).catch(() => {})
    }
    console.error('[health-journal] media extraction error', error)
    return NextResponse.json({ error: 'Failed to summarize media' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'
import { prisma } from '@/lib/prisma'
import { ensureHealthJournalSchema } from '@/lib/health-journal-db'

export const dynamic = 'force-dynamic'

function buildTodayLocalDate() {
  const now = new Date()
  const yyyy = now.getFullYear()
  const mm = String(now.getMonth() + 1).padStart(2, '0')
  const dd = String(now.getDate()).padStart(2, '0')
  return `${yyyy}-${mm}-${dd}`
}

function isValidDate(value: string) {
  return /^\d{4}-\d{2}-\d{2}$/.test(value)
}

function isValidMonth(value: string) {
  return /^\d{4}-\d{2}$/.test(value)
}

async function resolveHealthJournalUserId(request: NextRequest) {
  const nativeUserId = await getUserIdFromNativeAuth(request)
  if (nativeUserId) return nativeUserId

  const session = await getServerSession(authOptions)
  return session?.user?.id || null
}

export async function GET(request: NextRequest) {
  const userId = await resolveHealthJournalUserId(request)
  if (!userId) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  await ensureHealthJournalSchema()

  const { searchParams } = new URL(request.url)
  const dateParam = String(searchParams.get('date') || '').trim()
  const monthParam = String(searchParams.get('month') || '').trim()

  if (monthParam && isValidMonth(monthParam)) {
    const [yearText, monthText] = monthParam.split('-')
    const year = Number(yearText)
    const month = Number(monthText)
    const daysInMonth = new Date(year, Math.max(0, month - 1) + 1, 0).getDate()
    const monthStart = `${yearText}-${monthText}-01`
    const monthEnd = `${yearText}-${monthText}-${String(daysInMonth).padStart(2, '0')}`

    const rows = await prisma.healthJournalEntry.findMany({
      where: {
        userId,
        localDate: { gte: monthStart, lte: monthEnd },
      },
      distinct: ['localDate'],
      select: { localDate: true },
    })

    return NextResponse.json({ dates: rows.map((row) => row.localDate) })
  }

  const targetDate = isValidDate(dateParam) ? dateParam : buildTodayLocalDate()
  const entries = await prisma.healthJournalEntry.findMany({
    where: { userId, localDate: targetDate },
    orderBy: { createdAt: 'desc' },
  })

  return NextResponse.json({ entries })
}

export async function POST(request: NextRequest) {
  const userId = await resolveHealthJournalUserId(request)
  if (!userId) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  await ensureHealthJournalSchema()

  const body = await request.json().catch(() => ({}))
  const content = String(body?.content || '').trim()
  if (!content) {
    return NextResponse.json({ error: 'Missing content' }, { status: 400 })
  }

  const localDateRaw = String(body?.localDate || '').trim()
  const localDate = isValidDate(localDateRaw) ? localDateRaw : buildTodayLocalDate()

  const entry = await prisma.healthJournalEntry.create({
    data: {
      userId,
      content,
      localDate,
    },
  })

  return NextResponse.json({ entry })
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth/next'
import { getToken } from 'next-auth/jwt'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    let userEmail: string | null = session?.user?.email ?? null

    if (!userEmail) {
      try {
        const token = await getToken({
          req: request,
          secret: process.env.NEXTAUTH_SECRET || process.env.AUTH_SECRET || 'helfi-secret-key-production-2024',
        })
        if (token?.email) {
          userEmail = String(token.email)
        }
      } catch (tokenError) {
        console.error('GET /api/health-setup-meta - JWT fallback failed:', tokenError)
      }
    }

    if (!userEmail) {
      return NextResponse.json({ error: 'Not authenticated' }, { status: 401 })
    }

    const user = await prisma.user.findUnique({
      where: { email: userEmail },
      select: { id: true },
    })

    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    const meta = await prisma.healthGoal.findFirst({
      where: { userId: user.id, name: '__HEALTH_SETUP_META__' },
      orderBy: { updatedAt: 'desc' },
      select: { category: true, updatedAt: true },
    })

    let healthSetupUpdatedAt = 0
    if (meta?.category) {
      try {
        const parsed = JSON.parse(meta.category)
        const parsedUpdatedAt = Number(parsed?.updatedAt)
        if (Number.isFinite(parsedUpdatedAt) && parsedUpdatedAt > 0) {
          healthSetupUpdatedAt = parsedUpdatedAt
        }
      } catch {
        healthSetupUpdatedAt = 0
      }
    }

    if (!healthSetupUpdatedAt && meta?.updatedAt) {
      healthSetupUpdatedAt = new Date(meta.updatedAt).getTime()
    }

    return NextResponse.json({ healthSetupUpdatedAt, serverTime: Date.now() })
  } catch (error) {
    console.error('Error in GET /api/health-setup-meta:', error)
    return NextResponse.json({ error: 'Server error' }, { status: 500 })
  }
}

