export async function POST(req: NextRequest) {
  const user = await getHealthTipUser(req)
  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const body = await req.json().catch(() => ({}))
  let {
    enabled,
    time1,
    time2,
    time3,
    timezone,
    timezoneManual,
    frequency,
    focusFood,
    focusSupplements,
    focusLifestyle,
    acceptPricingTerms,
  } = body as any

  const normalizeTime = (input?: string, defaultValue = '11:30'): string => {
    if (!input) return defaultValue
    const s = String(input).trim().toLowerCase()
    // 24h HH:MM
    const m24 = s.match(/^([01]?\d|2[0-3]):([0-5]\d)$/)
    if (m24) return `${m24[1].padStart(2, '0')}:${m24[2]}`
    // 12h like 7:30 pm
    const m12 = s.match(/^([0-1]?\d):([0-5]\d)\s*(am|pm)$/)
    if (m12) {
      let h = parseInt(m12[1], 10)
      const mm = m12[2]
      const ap = m12[3]
      if (ap === 'pm' && h !== 12) h += 12
      if (ap === 'am' && h === 12) h = 0
      return `${String(h).padStart(2, '0')}:${mm}`
    }
    // Fallback: strip non-digits and interpret as HHMM
    const digits = s.replace(/[^0-9]/g, '')
    if (digits.length >= 3) {
      const h = parseInt(digits.slice(0, digits.length - 2), 10)
      const mm = parseInt(digits.slice(-2), 10)
      const hhClamped = Math.max(0, Math.min(23, h))
      const mmClamped = Math.max(0, Math.min(59, mm))
      return `${String(hhClamped).padStart(2, '0')}:${String(mmClamped).padStart(
        2,
        '0'
      )}`
    }
    return defaultValue
  }

  enabled = !!enabled
  const autoTimes = [...SMART_COACH_AUTO_CHECK_TIMES]
  time1 = autoTimes[0]
  time2 = autoTimes[1]
  time3 = autoTimes[2]
  const timezoneFromBody = timezone ? String(timezone).trim() : ''
  const timezoneManualEnabled =
    timezoneManual === true || timezoneManual === 'true'
