    // ).catch(() => {})
    // await prisma.$executeRawUnsafe(
    //   `ALTER TABLE HealthTipSettings ADD COLUMN IF NOT EXISTS focusFood BOOLEAN NOT NULL DEFAULT true`
    // ).catch(() => {})
    // await prisma.$executeRawUnsafe(
