    )

    if (enabled && acceptedPricingTerms) {
      await prisma.$executeRawUnsafe(
        `UPDATE HealthTipSettings
         SET pricingAcceptedAt = COALESCE(pricingAcceptedAt, NOW())
         WHERE userId = $1`,
        user.id
      ).catch(() => {})
