import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'
import { prisma } from '@/lib/prisma'

async function getHealthTipUser(req: NextRequest) {
  const nativeUserId = await getUserIdFromNativeAuth(req)
  if (nativeUserId) {
    return prisma.user.findUnique({ where: { id: nativeUserId } })
  }

  const session = await getServerSession(authOptions)
  if (!session?.user?.email) {
    return null
  }

  const user = await prisma.user.findUnique({ where: { email: session.user.email } })
  return user
}

export async function GET(req: NextRequest) {
  const user = await getHealthTipUser(req)
  if (!user) {
    return NextResponse.json({ error: 'User not found' }, { status: 404 })
  }

  // Ensure tips table exists
  // await prisma.$executeRawUnsafe(`
  //   CREATE TABLE IF NOT EXISTS HealthTips (
  //     id TEXT PRIMARY KEY,
  //     userId TEXT NOT NULL,
  //     tipDate DATE NOT NULL,
  //     sentAt TIMESTAMP NOT NULL DEFAULT NOW(),
  //     title TEXT NOT NULL,
  //     body TEXT NOT NULL,
  //     category TEXT NOT NULL,
  //     metadata JSONB,
  //     costCents INTEGER,
  //     chargeCents INTEGER
  //   )
  // `)

  // Try to align "today" with the same timezone used for scheduling health tips
  let effectiveTimezone =
    Intl.DateTimeFormat().resolvedOptions().timeZone || 'Australia/Melbourne'

  try {
    // Ensure settings table exists so we can safely query the timezone
    // await prisma.$executeRawUnsafe(`
    //   CREATE TABLE IF NOT EXISTS HealthTipSettings (
    //     userId TEXT PRIMARY KEY,
    //     enabled BOOLEAN NOT NULL DEFAULT true,
    //     time1 TEXT NOT NULL,
    //     time2 TEXT NOT NULL,
    //     time3 TEXT NOT NULL,
    //     timezone TEXT NOT NULL,
    //     frequency INTEGER NOT NULL DEFAULT 1,
    //     focusFood BOOLEAN NOT NULL DEFAULT true,
    //     focusSupplements BOOLEAN NOT NULL DEFAULT true,
    //     focusLifestyle BOOLEAN NOT NULL DEFAULT true
    //   )
    // `)

    const rows: Array<{ timezone: string }> = await prisma.$queryRawUnsafe(
      `SELECT timezone FROM HealthTipSettings WHERE userId = $1`,
      user.id
    )
    if (rows.length > 0 && rows[0].timezone) {
      effectiveTimezone = rows[0].timezone
    }
  } catch {
    // If anything goes wrong, fall back to environment timezone above.
  }

  // Compute "today" in the user's health tip timezone so it matches tipDate written by dispatch
  const now = new Date()
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: effectiveTimezone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(now)
  const day = `${parts.find((p) => p.type === 'year')?.value}-${parts
    .find((p) => p.type === 'month')
    ?.value}-${parts.find((p) => p.type === 'day')?.value}`

  const tips: Array<{
    id: string
    tipDate: string
    sentAt: Date
    title: string
    body: string
    category: string
    costCents: number | null
    chargeCents: number | null
    suggestedQuestions: any
    safetyNote: string | null
  }> = await prisma.$queryRawUnsafe(
    `SELECT 
       id,
       tipDate AS "tipDate",
       sentAt AS "sentAt",
       title,
       body,
       category,
       costCents,
       chargeCents,
       metadata->'suggestedQuestions' AS "suggestedQuestions",
       metadata->>'safetyNote' AS "safetyNote"
     FROM HealthTips
     WHERE userId = $1 AND tipDate = $2::date
     ORDER BY sentAt ASC`,
    user.id,
    day
  )

  // Normalise suggestedQuestions to a simple string array on the wire
  const tipsWithSuggestions = tips.map((tip) => {
    const raw = tip.suggestedQuestions
    const suggestions =
      Array.isArray(raw) && raw.length > 0
        ? raw.filter((q) => typeof q === 'string' && q.trim().length > 0).slice(0, 3)
        : []
    const safetyNote =
      typeof tip.safetyNote === 'string' && tip.safetyNote.trim().length > 0
        ? tip.safetyNote.trim()
        : ''
    return {
      ...tip,
      suggestedQuestions: suggestions,
      safetyNote,
    }
  })

  return NextResponse.json({ tips: tipsWithSuggestions })
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { computeHydrationGoal } from '@/lib/hydration-goal'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'

export const dynamic = 'force-dynamic'

const GOAL_NAME = '__HYDRATION_GOAL__'
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/

const UNIT_TO_ML: Record<string, number> = {
  ml: 1,
  l: 1000,
  oz: 29.5735,
}

function normalizeUnit(value: unknown): string | null {
  const raw = String(value ?? '').trim().toLowerCase()
  if (raw === 'ml' || raw === 'milliliter' || raw === 'milliliters') return 'ml'
  if (raw === 'l' || raw === 'liter' || raw === 'liters') return 'l'
  if (raw === 'oz' || raw === 'ounce' || raw === 'ounces') return 'oz'
  return null
}

function normalizeAmount(value: unknown): number | null {
  const n = Number(value)
  if (!Number.isFinite(n) || n <= 0) return null
  return Math.round(n * 100) / 100
}

function normalizeLocalDate(input: string | null) {
  const trimmed = (input || '').trim()
  if (!DATE_RE.test(trimmed)) return null
  return trimmed
}

function toMl(amount: number, unit: string): number {
  const factor = UNIT_TO_ML[unit] || 1
  return Math.round(amount * factor)
}

function readGoalCategory(user: any, name: string) {
  const goal = (user?.healthGoals || []).find((g: any) => g?.name === name)
  if (!goal?.category) return null
  try {
    return JSON.parse(goal.category)
  } catch {
    return null
  }
}

function parseDietTypes(user: any): string[] {
  const parsed = readGoalCategory(user, '__DIET_PREFERENCE__')
  const raw = Array.isArray(parsed?.dietTypes) ? parsed.dietTypes : parsed?.dietType
  if (Array.isArray(raw)) return raw.filter((v: any) => typeof v === 'string' && v.trim())
  if (typeof raw === 'string' && raw.trim()) return [raw.trim()]
  return []
}

function parseDiabetesType(user: any): string {
  const parsed = readGoalCategory(user, '__ALLERGIES_DATA__')
  return typeof parsed?.diabetesType === 'string' ? parsed.diabetesType : ''
}

function parseBirthdate(user: any): string {
  const parsed = readGoalCategory(user, '__PROFILE_INFO_DATA__')
  return typeof parsed?.dateOfBirth === 'string' ? parsed.dateOfBirth : ''
}

function parsePrimaryGoal(user: any) {
  const parsed = readGoalCategory(user, '__PRIMARY_GOAL__')
  return {
    goalChoice: typeof parsed?.goalChoice === 'string' ? parsed.goalChoice : '',
    goalIntensity: typeof parsed?.goalIntensity === 'string' ? parsed.goalIntensity : '',
  }
}

function getCustomGoal(user: any): { targetMl: number; updatedAt?: string | null } | null {
  const parsed = readGoalCategory(user, GOAL_NAME)
  const targetMl = Number(parsed?.targetMl)
  if (!Number.isFinite(targetMl) || targetMl <= 0) return null
  return {
    targetMl: Math.round(targetMl),
    updatedAt: typeof parsed?.updatedAt === 'string' ? parsed.updatedAt : null,
  }
}

async function getExerciseCaloriesForDate(userId: string, localDate: string | null) {
  if (!localDate) return null
  const entries = await prisma.exerciseEntry.findMany({
    where: { userId, localDate },
    select: { calories: true },
  })
  if (entries.length === 0) return null
  const totalCalories = entries.reduce((sum, entry) => sum + (Number(entry.calories) || 0), 0)
  if (!Number.isFinite(totalCalories) || totalCalories <= 0) return null
  return Math.round(totalCalories)
}

function exerciseCaloriesToBonusMl(calories: number | null) {
  if (!Number.isFinite(calories || NaN) || (calories as number) <= 0) return 0
  const raw = Math.round(calories as number)
  return Math.min(raw, 1500)
}

export async function GET(_req: NextRequest) {
  const session = await getServerSession(authOptions)
  const userId = session?.user?.id || (await getUserIdFromNativeAuth(_req))
  if (!userId) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const user = await prisma.user.findUnique({
    where: { id: userId },
    include: { healthGoals: { orderBy: { updatedAt: 'desc' } } },
  })
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  const dietTypes = parseDietTypes(user)
  const diabetesType = parseDiabetesType(user)
  const birthdate = parseBirthdate(user)
  const primaryGoal = parsePrimaryGoal(user)
  const localDate = normalizeLocalDate(_req.nextUrl.searchParams.get('date'))
  const exerciseCalories = await getExerciseCaloriesForDate(user.id, localDate)
  const exerciseBonusMl = exerciseCaloriesToBonusMl(exerciseCalories)
  const recommended = computeHydrationGoal({
    weightKg: typeof user.weight === 'number' ? user.weight : null,
    heightCm: typeof user.height === 'number' ? user.height : null,
    gender: (user as any)?.gender ?? null,
    bodyType: (user as any)?.bodyType ?? null,
    exerciseFrequency: '',
    exerciseTypes: user.exerciseTypes || [],
    dietTypes,
    diabetesType,
    goalChoice: primaryGoal.goalChoice,
    goalIntensity: primaryGoal.goalIntensity,
    birthdate,
  })

  const recommendedWithBonus = exerciseBonusMl
    ? Math.round((recommended.targetMl + exerciseBonusMl) / 50) * 50
    : recommended.targetMl
  const custom = getCustomGoal(user)
  const targetMl = custom?.targetMl ?? recommendedWithBonus
  const source = custom ? 'custom' : 'auto'

  return NextResponse.json({
    targetMl,
    recommendedMl: recommendedWithBonus,
    source,
    updatedAt: custom?.updatedAt ?? null,
    exerciseBonusMl,
  })
}

export async function POST(req: NextRequest) {
  const session = await getServerSession(authOptions)
  const userId = session?.user?.id || (await getUserIdFromNativeAuth(req))
  if (!userId) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const user = await prisma.user.findUnique({
    where: { id: userId },
    include: { healthGoals: { orderBy: { updatedAt: 'desc' } } },
  })
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  const body = await req.json().catch(() => ({} as any))
  let targetMl: number | null = null
  if (body?.targetMl != null) {
    const n = Number(body.targetMl)
    if (Number.isFinite(n) && n > 0) targetMl = Math.round(n)
  } else {
    const amount = normalizeAmount(body?.amount)
    const unit = normalizeUnit(body?.unit)
    if (amount != null && unit) {
      targetMl = toMl(amount, unit)
    }
  }

  if (!targetMl) {
    return NextResponse.json({ error: 'Invalid goal amount' }, { status: 400 })
  }

  const payload = {
    targetMl,
    updatedAt: new Date().toISOString(),
  }

  const existing = (user.healthGoals || []).find((g: any) => g?.name === GOAL_NAME)
  if (existing) {
    await prisma.healthGoal.update({
      where: { id: existing.id },
      data: { category: JSON.stringify(payload), currentRating: 0 },
    })
  } else {
    await prisma.healthGoal.create({
      data: {
        userId: user.id,
        name: GOAL_NAME,
        category: JSON.stringify(payload),
        currentRating: 0,
      },
    })
  }

  return NextResponse.json({ ok: true, targetMl })
}

export async function DELETE(_req: NextRequest) {
  const session = await getServerSession(authOptions)
  const userId = session?.user?.id || (await getUserIdFromNativeAuth(_req))
  if (!userId) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const user = await prisma.user.findUnique({ where: { id: userId } })
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  await prisma.healthGoal.deleteMany({ where: { userId: user.id, name: GOAL_NAME } })
  return NextResponse.json({ ok: true })
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { logAIUsage } from '@/lib/ai-usage-logger'
import { CreditManager } from '@/lib/credit-system'
import { capMaxTokensToBudget } from '@/lib/cost-meter'
import { chatCompletionWithCost } from '@/lib/metered-openai'
import { consumeFreeCredit, hasFreeCredits } from '@/lib/free-credits'
import { isSubscriptionActive } from '@/lib/subscription-utils'

// Lazy OpenAI import to avoid build-time env requirements
let _openai: any = null
function getOpenAI() {
  if (_openai) return _openai
  const apiKey = process.env.OPENAI_API_KEY
  if (!apiKey) return null
  const OpenAI = require('openai').default
  _openai = new OpenAI({ apiKey })
  return _openai
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'not_authenticated' }, { status: 401 })
    }

    const {
      section,
      question,
      messages: clientMessages,
      issue,
    } = await request.json().catch(() => ({ section: 'safety', question: '', messages: null, issue: '' }))
    const sec = String(section || 'safety').toLowerCase()
    const userId = session.user.id

    // Load a narrow, privacy-conscious slice of recent data for better answers
    const user = await prisma.user.findUnique({
      where: { id: userId },
      include: {
        healthGoals: { orderBy: { updatedAt: 'desc' } },
        supplements: true,
        medications: true,
        healthLogs: { orderBy: { createdAt: 'desc' }, take: 14 },
        foodLogs: { orderBy: { createdAt: 'desc' }, take: 10 },
        subscription: true,
        creditTopUps: true,
      },
    })

    if (!user) return NextResponse.json({ error: 'user_not_found' }, { status: 404 })

    const isPremium = isSubscriptionActive(user.subscription)
    const now = new Date()
    const hasPurchasedCredits = user.creditTopUps?.some(
      (topUp: any) => topUp.expiresAt > now && (topUp.amountCents - topUp.usedCents) > 0
    )
    const hasFreeChatCredits = await hasFreeCredits(userId, 'INSIGHTS_CHAT')
    const allowViaFreeUse = !isPremium && !hasPurchasedCredits && hasFreeChatCredits
    if (!isPremium && !hasPurchasedCredits && !hasFreeChatCredits) {
      return NextResponse.json(
        {
          error: 'Payment required',
          message: 'You\'ve used all your free insights chat uses. Subscribe to a monthly plan or purchase credits to continue.',
          requiresPayment: true,
          exhaustedFreeCredits: true,
        },
        { status: 402 }
      )
    }

    const profile = {
      gender: user.gender,
      height: user.height,
      weight: user.weight,
      goals: (user.healthGoals || []).filter((g: any) => !g.name?.startsWith('__')).map((g: any) => g.name),
      supplements: (user.supplements || []).map((s: any) => ({ name: s.name, dosage: s.dosage, timing: s.timing })),
      medications: (user.medications || []).map((m: any) => ({ name: m.name, dosage: m.dosage, timing: m.timing })),
      recentHealthLogs: (user.healthLogs || []).map((h: any) => ({ rating: h.rating, createdAt: h.createdAt })),
      recentFood: (user.foodLogs || []).map((f: any) => ({ name: f.name, nutrients: f.nutrients, createdAt: f.createdAt })),
    }

    // Fallback answer if OpenAI is not configured
    const fallback = () => {
      const hasIron = profile.supplements.some((s) => /iron/i.test(s.name || '')) || profile.medications.some((m) => /iron/i.test(m.name || ''))
      const hasCalcium = profile.supplements.some((s) => /calcium/i.test(s.name || '')) || profile.medications.some((m) => /calcium/i.test(m.name || ''))
      const hasMagnesium = profile.supplements.some((s) => /magnesium/i.test(s.name || ''))
      const tips: string[] = []
      if (hasIron && hasCalcium) tips.push('Separate iron and calcium by ~2 hours to support absorption (check with your clinician).')
      if (hasMagnesium) tips.push('Magnesium is often better in the evening, 1–2 hours before sleep; avoid pairing with high‑fiber meals.')
      if (tips.length === 0) tips.push('Log your current supplements/medications and daily symptoms; I will tailor specific safety/timing guidance next refresh.')
      const answer = `Here are practical safety pointers based on your current entries:\n- ${tips.join('\n- ')}`
      // Return a threaded shape for the client even in fallback
      const history = Array.isArray(clientMessages) && clientMessages.length
        ? clientMessages.map((m: any) => ({ role: String(m.role || 'user'), content: String(m.content || '') })).slice(-12)
        : (question ? [{ role: 'user', content: String(question) }] : [])
      return { messages: [...history, { role: 'assistant', content: answer }], preview: true }
    }

    const openai = getOpenAI()
    if (!openai) return NextResponse.json(fallback(), { status: 200 })

    // Build threaded chat messages
    const baseSystem = {
      role: 'system',
      content: [
        'You are a careful, non-alarming clinical assistant.',
        `SECTION: ${sec}`,
        'RULES:',
        '- Never diagnose; avoid certainty; suggest to check with clinician for changes.',
        '- Use ONLY the JSON profile provided; be specific, short, and actionable.',
        '- Your reply should be concise and structured with short bullets where helpful.',
        '',
        `PROFILE JSON: ${JSON.stringify(profile)}`,
        issue ? `ISSUE: ${String(issue)}` : '',
      ].filter(Boolean).join('\n'),
    }

    const history = Array.isArray(clientMessages) && clientMessages.length
      ? clientMessages.map((m: any) => ({ role: String(m.role || 'user'), content: String(m.content || '') })).slice(-12)
      : (question ? [{ role: 'user', content: String(question) }] : [])

    const model = 'gpt-5.6-sol'
    const promptText = [baseSystem, ...history].map((m) => m.content).join('\n')
    let maxTokens = 400
    if (!allowViaFreeUse) {
      const cm = new CreditManager(userId)
      const wallet = await cm.getWalletStatus()
      const cappedMaxTokens = capMaxTokensToBudget(model, promptText, maxTokens, wallet.totalAvailableCents)
      if (cappedMaxTokens <= 0) {
        return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
      }
      maxTokens = cappedMaxTokens
    }

    const wrapped = await chatCompletionWithCost(openai, {
      model,
      messages: [baseSystem, ...history],
      temperature: 0.2,
      max_tokens: maxTokens,
    } as any)

    if (!allowViaFreeUse) {
      const cm = new CreditManager(userId)
      const ok = await cm.chargeCents(wrapped.costCents)
      if (!ok) {
        return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
      }
    } else {
      await consumeFreeCredit(userId, 'INSIGHTS_CHAT')
    }

    try {
      await logAIUsage({
        context: { feature: 'insights:ask', userId },
        model,
        promptTokens: wrapped.promptTokens,
        completionTokens: wrapped.completionTokens,
        costCents: wrapped.costCents,
      })
    } catch {
      // Ignore logging failures
    }

    const text = wrapped.completion.choices?.[0]?.message?.content || ''
    return NextResponse.json({ messages: [...history, { role: 'assistant', content: text }], preview: false }, { status: 200 })
  } catch (e) {
    return NextResponse.json({ error: 'server_error' }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'

function clean(s?: string) { return (s || '').trim() }

export async function GET(request: Request) {
  const url = new URL(request.url)
  const issue = clean(url.searchParams.get('issue') || '')
  const supplement = clean(url.searchParams.get('supplement') || '')

  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) return NextResponse.json({ error: 'not_authenticated' }, { status: 401 })

    // Collect minimal context
    const user = await prisma.user.findUnique({
      where: { id: session.user.id },
      include: {
        supplements: true,
        medications: true,
        healthGoals: { orderBy: { updatedAt: 'desc' } },
      },
    })

    // Build a lightweight recommendation object now (stub without OpenAI)
    const title = issue ? issue : (supplement ? supplement : 'Insight')
    const reason = issue
      ? `Based on your selected issue "${issue}" and your current profile.`
      : `Based on your supplement "${supplement}" and your current profile.`
    const actions: string[] = []
    if (issue) {
      actions.push('Review daily habits that impact this issue.')
      actions.push('Track changes for 7 days to see patterns.')
    }
    if (supplement) {
      actions.push('Take with appropriate meal timing if applicable.')
      actions.push('Check for interactions with current medications (confirm with your clinician).')
    }

    const payload = {
      title,
      what: issue ? `Recommendations for ${issue}.` : `Recommendations for ${supplement}.`,
      reason,
      actions,
      timing: supplement ? 'Common timing: morning with food or evening as tolerated.' : undefined,
      safety: 'This is general information. Always confirm with your clinician before changes.'
    }

    return NextResponse.json({ ok: true, data: payload }, { status: 200 })
  } catch (e) {
    return NextResponse.json({ error: 'server_error' }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { logAIUsage } from '@/lib/ai-usage-logger'
import { consumeRateLimit } from '@/lib/rate-limit'
import { CreditManager } from '@/lib/credit-system'
import { capMaxTokensToBudget } from '@/lib/cost-meter'
import { chatCompletionWithCost } from '@/lib/metered-openai'
import { decryptFieldsBatch } from '@/lib/encryption'

const INSIGHTS_RATE_WINDOW_MS = 5 * 60 * 1000 // 5 minutes
const INSIGHTS_RATE_MAX = 2

// Lazy OpenAI import to avoid build-time env requirements
let _openai: any = null
function getOpenAI() {
  if (_openai) return _openai
  const apiKey = process.env.OPENAI_API_KEY
  if (!apiKey) return null
  const OpenAI = require('openai').default
  _openai = new OpenAI({ apiKey })
  return _openai
}

export async function POST(request: Request) {
  const url = new URL(request.url)
  const preview = url.searchParams.get('preview') === '1'
  const enabled = process.env.NEXT_PUBLIC_INSIGHTS_ENABLED === 'true'
  if (!enabled && !preview) {
    return NextResponse.json({ enabled: false, items: [] }, { status: 200 })
  }

  // Personalize from current user's data when available
  let profile: any = null
  let recentFood: any[] = []
  let recentHealthLogs: any[] = []
  // Aggregated nutrition snapshot for the last 7 days (best-effort, safe fallbacks)
  let weeklyNutritionSummary: any = null
  let labTrends: Array<{
    name: string
    latestValue: number
    previousValue: number
    unit: string | null
    change: number
    direction: 'up' | 'down' | 'flat'
    latestDate: string
    previousDate: string
  }> = []
  let labReportCount = 0
  try {
    const session = await getServerSession(authOptions)
    if (session?.user?.id) {
      profile = await prisma.user.findUnique({
        where: { id: session.user.id },
        include: {
          healthGoals: { orderBy: { updatedAt: 'desc' } },
          supplements: true,
          medications: true,
          foodLogs: {
            orderBy: { createdAt: 'desc' },
            take: 30,
          },
          healthLogs: {
            orderBy: { createdAt: 'desc' },
            take: 10,
            include: { goal: true }
          },
        },
      })
      // Include nutrients when available so the AI can be specific
      recentFood = (profile?.foodLogs || []).map((f: any) => ({ name: f.name, nutrients: f.nutrients || null, createdAt: f.createdAt }))
      recentHealthLogs = (profile?.healthLogs || []).map((h: any) => ({ goal: h.goal?.name, rating: h.rating, createdAt: h.createdAt }))

      // Include recent lab trends (best-effort) for insights personalization
      try {
        labReportCount = await prisma.report.count({ where: { userId: session.user.id } })
        const trendWindowStart = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000)
        const labResults = await prisma.labResult.findMany({
          where: { report: { userId: session.user.id, createdAt: { gte: trendWindowStart } } },
          include: { report: { select: { createdAt: true } } },
          orderBy: { createdAt: 'desc' },
          take: 120,
        })

        const analyteMap = new Map<string, Array<{ value: number; unit: string | null; date: Date }>>()
        for (const result of labResults) {
          const encryptedFields: Record<string, string> = {
            analyteName: result.analyteNameEncrypted,
            value: result.valueEncrypted,
          }
          if (result.unitEncrypted) encryptedFields.unit = result.unitEncrypted
          if (result.collectionDateEncrypted) encryptedFields.collectionDate = result.collectionDateEncrypted
          const decrypted = await decryptFieldsBatch(encryptedFields, result.dataKeyEncrypted)
          const name = String(decrypted.analyteName || '').trim()
          if (!name) continue
          const rawValue = String(decrypted.value || '').trim()
          const match = rawValue.match(/-?\d+(\.\d+)?/)
          const numeric = match ? Number(match[0]) : NaN
          if (!Number.isFinite(numeric)) continue
          const unit = decrypted.unit ? String(decrypted.unit).trim() : null
          const date = decrypted.collectionDate ? new Date(decrypted.collectionDate) : result.report?.createdAt || result.createdAt
          if (Number.isNaN(date.getTime())) continue
          const existing = analyteMap.get(name) || []
          existing.push({ value: numeric, unit, date })
          analyteMap.set(name, existing)
        }

        analyteMap.forEach((entries, name) => {
          const sorted = entries.sort((a, b) => b.date.getTime() - a.date.getTime())
          if (sorted.length < 2) return
          const latest = sorted[0]
          const previous = sorted[1]
          const change = +(latest.value - previous.value).toFixed(2)
          const direction = change === 0 ? 'flat' : change > 0 ? 'up' : 'down'
          labTrends.push({
            name,
            latestValue: latest.value,
            previousValue: previous.value,
            unit: latest.unit || previous.unit || null,
            change,
            direction,
            latestDate: latest.date.toISOString(),
            previousDate: previous.date.toISOString(),
          })
        })
        labTrends = labTrends.slice(0, 8)
      } catch {
        labTrends = []
        labReportCount = 0
      }
    }
  } catch {
    // non-blocking
  }

  // Compute a 7-day nutrition summary from recent food logs (best-effort)
  try {
    const cutoff = Date.now() - 7 * 24 * 60 * 60 * 1000
    const last7 = recentFood.filter((f: any) => new Date(f.createdAt).getTime() >= cutoff)
    const sums = {
      calories: 0,
      protein_g: 0,
      carbs_g: 0,
      fat_g: 0,
      fiber_g: 0,
      sugar_g: 0,
      sodium_mg: 0,
    }
    let counted = 0
    const foodCount: Record<string, number> = {}
    for (const f of last7) {
      const n = (f && f.nutrients) || {}
      // Accept multiple possible keys commonly returned by analyzers
      const cals = Number(n.calories ?? n.kcal ?? 0) || 0
      const protein = Number(n.protein_g ?? n.protein ?? 0) || 0
      const carbs = Number(n.carbs_g ?? n.carbohydrates_g ?? n.carbohydrates ?? 0) || 0
      const fat = Number(n.fat_g ?? n.total_fat_g ?? 0) || 0
      const fiber = Number(n.fiber_g ?? n.dietary_fiber_g ?? 0) || 0
      const sugar = Number(n.sugar_g ?? n.sugars_g ?? 0) || 0
      const sodium = Number(n.sodium_mg ?? n.salt_mg ?? 0) || 0
      // Only count entries that have at least one nutrient value
      if (cals || protein || carbs || fat || fiber || sugar || sodium) {
        sums.calories += cals
        sums.protein_g += protein
        sums.carbs_g += carbs
        sums.fat_g += fat
        sums.fiber_g += fiber
        sums.sugar_g += sugar
        sums.sodium_mg += sodium
        counted += 1
      }
      const key = String(f.name || '').trim().toLowerCase()
      if (key) foodCount[key] = (foodCount[key] || 0) + 1
    }
    const topFoods = Object.entries(foodCount)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5)
      .map(([name, count]) => ({ name, count }))

    weeklyNutritionSummary = {
      daysAnalyzed: Math.min(7, Math.max(1, Math.ceil((Date.now() - cutoff) / (24 * 60 * 60 * 1000)))),
      entriesWithNutrients: counted,
      totals: sums,
      dailyAverages: {
        calories: counted ? Math.round(sums.calories / 7) : 0,
        protein_g: counted ? +(sums.protein_g / 7).toFixed(1) : 0,
        carbs_g: counted ? +(sums.carbs_g / 7).toFixed(1) : 0,
        fat_g: counted ? +(sums.fat_g / 7).toFixed(1) : 0,
        fiber_g: counted ? +(sums.fiber_g / 7).toFixed(1) : 0,
        sugar_g: counted ? +(sums.sugar_g / 7).toFixed(1) : 0,
        sodium_mg: counted ? Math.round(sums.sodium_mg / 7) : 0,
      },
      topFoods,
    }
  } catch {
    weeklyNutritionSummary = null
  }

  // Simple personalized fallback insights (used when AI call not available)
  const fallback = () => {
    const goals = profile?.healthGoals?.filter((g: any) => !g.name?.startsWith('__')) || []
    const supplements = profile?.supplements || []
    const meds = profile?.medications || []
    const hasMagnesium = supplements.some((s: any) => /magnesium/i.test(s?.name || ''))
    const hasIron = supplements.some((s: any) => /iron/i.test(s?.name || ''))
    const hasCalcium = supplements.some((s: any) => /calcium/i.test(s?.name || ''))
    const hasOmega3 = supplements.some((s: any) => /(omega|fish\s*oil)/i.test(s?.name || ''))

    const items = [
      {
        id: 'pf1',
        title: goals.length ? `Weekly focus: ${goals[0].name}` : 'Set a clear weekly focus',
        summary: goals.length ? `Prioritize “${goals[0].name}”. Define one measurable action for this week.` : 'Choose 1–2 goals to focus on and define one measurable action.',
        tags: ['goals'],
        confidence: 0.7,
        createdAt: new Date().toISOString(),
      },
      {
        id: 'pf2',
        title: hasMagnesium ? 'Optimize magnesium timing' : 'Start with simple sleep support',
        summary: hasMagnesium ? 'You already take magnesium — try 1–2 hours before bed and avoid pairing with high‑fiber meals for absorption.' : 'If appropriate, consider evening magnesium to support sleep quality.',
        tags: ['supplement','timing','sleep'],
        confidence: 0.72,
        createdAt: new Date().toISOString(),
      },
      {
        id: 'pf3',
        title: hasIron && hasCalcium ? 'Separate iron and calcium' : 'Medication/supplement spacing check',
        summary: hasIron && hasCalcium ? 'Take iron and calcium at least 2 hours apart for absorption (check with your clinician).' : 'Review timing to avoid conflicts; spacing doses by ~2 hours can help (check with your clinician).',
        tags: ['safety','timing'],
        confidence: 0.66,
        createdAt: new Date().toISOString(),
      },
      {
        id: 'pf4',
        title: 'Protein‑forward breakfast',
        summary: 'Aim for 25–35g protein at breakfast to stabilize morning energy and appetite.',
        tags: ['nutrition','energy'],
        confidence: 0.64,
        createdAt: new Date().toISOString(),
      },
      {
        id: 'pf5',
        title: hasOmega3 ? 'Keep omega‑3 consistent' : 'Consider omega‑3 intake',
        summary: hasOmega3 ? 'Take omega‑3 with a meal containing fat for better absorption.' : 'Consider omega‑3 rich foods or a supplement (discuss with your clinician).',
        tags: ['supplement','nutrition'],
        confidence: 0.61,
        createdAt: new Date().toISOString(),
      },
      {
        id: 'pf6',
        title: 'Hydration + fiber baseline',
        summary: 'Target ~2–3L fluids daily and include fiber at each meal for digestion.',
        tags: ['hydration','nutrition'],
        confidence: 0.6,
        createdAt: new Date().toISOString(),
      },
    ]
    return items
  }

  // Real AI generation (also allowed in preview to bypass flag safely)
  if (preview) {
    return NextResponse.json({ enabled: enabled || preview, items: fallback(), preview: true }, { status: 200 })
  }

  const clientIp = (request.headers.get('x-forwarded-for') || '').split(',')[0]?.trim() || 'unknown'
  const rateKey = profile?.id ? `user:${profile.id}` : `ip:${clientIp}`
  const rateCheck = await consumeRateLimit('insights-generate', rateKey, INSIGHTS_RATE_MAX, INSIGHTS_RATE_WINDOW_MS)
  if (!rateCheck.allowed) {
    const retryAfter = Math.max(1, Math.ceil(rateCheck.retryAfterMs / 1000))
    return NextResponse.json(
      { enabled: enabled || preview, items: fallback(), rateLimited: true },
      { status: 429, headers: { 'Retry-After': String(retryAfter) } }
    )
  }

  {
    try {
      const openai = getOpenAI()
      if (openai && profile) {
        const profileText = JSON.stringify({
          gender: profile.gender,
          weight: profile.weight,
          height: profile.height,
          goals: (profile.healthGoals || []).map((g: any) => g.name),
          supplements: (profile.supplements || []).map((s: any) => ({ name: s.name, timing: s.timing })),
          medications: (profile.medications || []).map((m: any) => ({ name: m.name, timing: m.timing })),
          recentFood,
          recentHealthLogs,
          weeklyNutritionSummary,
          labReportCount,
          labTrends,
        })

        const prompt = `You are a careful, data-driven health coach. Based ONLY on the JSON profile below, generate 6 high-value, personalized insights. Avoid generic advice. Use the user's goals, supplements, medications, recent foods (with nutrients), health logs, lab trends, and the 7-day nutrition summary.

Return a JSON array of items where each item has:
  id (string),
  title (string),
  summary (2–3 sentences, specific, quantified when possible),
  tags (array of strings like ['goals','supplement','medication','nutrition','timing','safety','energy','sleep']),
  confidence (0–1),
  reason (string, explain the "why" using the provided data, cite specific numbers like grams/day or averages if available),
  actions (array of 3–5 concrete steps tailored to the user; include amounts/timing/examples; where relevant say "check with your clinician").

Nutrition guidance rules:
- Use weeklyNutritionSummary.dailyAverages to reference protein_g, fiber_g, sugar_g, sodium_mg, calories when available.
- If protein appears low (< 70 g/day for average adult unless height/weight suggests otherwise), propose specific breakfast/lunch/dinner examples with grams.
- If fiber is low (< 25 g/day), suggest concrete swaps to reach ~25–35 g/day with food examples.
- If sugar is high (> 50 g/day) or sodium high (> 2300 mg/day), suggest reductions with practical substitutions.
- Use recentFood to cite examples (e.g., "based on frequent item: greek yogurt").
- Cross-link supplements/medications with timing and interactions (advice as "check with your clinician").

Lab guidance rules:
- If labTrends exist, use them to suggest items to discuss with a clinician (supplements, foods, or possible medication questions).
- Never claim a result is good/bad or diagnose anything; describe movement only (higher/lower/flat vs last result).
- If recommending a supplement or food, check the user's current medications and warn about possible interactions when relevant.
- If you mention medications, phrase it as a discussion point ("ask your clinician if...") and never suggest stopping or starting meds.
- Any lab-based suggestion must include a safety note to check with a medical professional.

Keep each insight skimmable but substantive. Do not return prose outside of the JSON array.

Profile: ${profileText}`
        const model = 'gpt-5.6-sol'
        const cm = new CreditManager(profile.id)
        const wallet = await cm.getWalletStatus()
        const maxTokens = capMaxTokensToBudget(model, prompt, 1000, wallet.totalAvailableCents)
        if (maxTokens <= 0) {
          return NextResponse.json({ enabled: true, items: fallback(), ai: false, requiresPayment: true }, { status: 200 })
        }

        const wrapped = await chatCompletionWithCost(openai, {
          model,
          messages: [{ role: 'user', content: prompt }],
          temperature: 0.2,
          max_tokens: maxTokens,
        } as any)

        const ok = await cm.chargeCents(wrapped.costCents)
        if (!ok) {
          return NextResponse.json({ enabled: true, items: fallback(), ai: false, requiresPayment: true }, { status: 200 })
        }

        try {
          await logAIUsage({
            context: { feature: 'insights:landing-generate', userId: profile.id },
            model,
            promptTokens: wrapped.promptTokens,
            completionTokens: wrapped.completionTokens,
            costCents: wrapped.costCents,
          })
        } catch {
          // Ignore logging failures
        }

        const text = wrapped.completion.choices?.[0]?.message?.content || ''
        // Try to extract JSON array
        const jsonMatch = text.match(/\[([\s\S]*?)\]/)
        const items = jsonMatch ? JSON.parse(jsonMatch[0]) : fallback()
        try {
          // Save to cache for faster subsequent loads
          await prisma.$executeRawUnsafe(
            'CREATE TABLE IF NOT EXISTS "InsightsCache" ("userId" TEXT PRIMARY KEY, "items" JSONB NOT NULL, "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW())'
          )
          await prisma.$executeRawUnsafe(
            'INSERT INTO "InsightsCache" ("userId", "items", "updatedAt") VALUES ($1, $2::jsonb, NOW())\n             ON CONFLICT ("userId") DO UPDATE SET "items" = EXCLUDED."items", "updatedAt" = NOW()',
            profile.id,
            JSON.stringify(items)
          )
        } catch {}
        return NextResponse.json({ enabled: true, items, ai: true }, { status: 200 })
      }
    } catch (e) {
      // fall back below
    }
  }

  return NextResponse.json({ enabled: true, items: fallback(), preview: true }, { status: 200 })
}

