export async function POST(
  request: Request,
  context: { params: { slug: string; section: string } }
) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }
    const contentType = request.headers.get('content-type') || ''
    let body: { message?: string; threadId?: string; newThread?: boolean } = {}
    if (contentType.includes('application/json')) {
      try {
        body = await request.json()
      } catch {}
    }
    const question = String(body?.message || '').trim()
    const section = context.params.section as IssueSectionKey
    await ensureChatTables()

    // Get or create thread
    let thread: { id: string }
    if (body.newThread) {
      // Create new thread only if explicitly requested
      thread = await createThread(session.user.id, context.params.slug, section)
    } else if (body.threadId) {
      // Use existing thread
      thread = { id: body.threadId }
    } else {
      // Get most recent thread or create new one ONLY if no threads exist
      const existingThreads = await listThreads(session.user.id, context.params.slug, section)
      if (existingThreads.length > 0) {
        thread = { id: existingThreads[0].id }
      } else {
        // Only create if truly no threads exist
        thread = await getOrCreateThread(session.user.id, context.params.slug, section)
      }
    }

    if (question) {
      await appendMessage(thread.id, 'user', question)
      // Auto-generate title from first message if thread has no title
      const threads = await listThreads(session.user.id, context.params.slug, section)
      const currentThread = threads.find(t => t.id === thread.id)
      if (currentThread && !currentThread.title) {
        const title = question.length > 50 ? question.substring(0, 47) + '...' : question
        await updateThreadTitle(session.user.id, thread.id, title)
      }
    }

    const accept = (request.headers.get('accept') || '').toLowerCase()
    const wantsStream = accept.includes('text/event-stream')
    const openai = getOpenAIClient()
    const system = await buildSystemPrompt(session.user.id, context.params.slug, section)
    const user = await prisma.user.findUnique({
      where: { id: session.user.id },
      include: { subscription: true, creditTopUps: true },
    })
    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    const isPremium = isSubscriptionActive(user.subscription)
    const now = new Date()
    const hasPurchasedCredits = user.creditTopUps?.some(
      (topUp: any) => topUp.expiresAt > now && (topUp.amountCents - topUp.usedCents) > 0
    )
    const hasFreeChatCredits = await hasFreeCredits(user.id, 'INSIGHTS_CHAT')
    const allowViaFreeUse = !isPremium && !hasPurchasedCredits && hasFreeChatCredits
    if (!isPremium && !hasPurchasedCredits && !hasFreeChatCredits) {
      return NextResponse.json(
        {
          error: 'Payment required',
          message: 'You\'ve used all your free insights chat uses. Subscribe to a monthly plan or purchase credits to continue.',
          requiresPayment: true,
          exhaustedFreeCredits: true,
        },
        { status: 402 }
      )
    }

    if (!openai) {
      // Fallback without OpenAI: echo guidance
      const fallback = `I can help summarize and explain this section ("${context.params.slug}" → ${section}). Please provide a specific question.`
      await appendMessage(thread.id, 'assistant', fallback)
      if (wantsStream) {
        const stream = new ReadableStream({
          start(controller) {
            const enc = new TextEncoder()
            controller.enqueue(enc.encode(`data: ${fallback}\n\n`))
            controller.enqueue(enc.encode('event: end\n\n'))
            controller.close()
          },
        })
        return new Response(stream, { headers: { 'Content-Type': 'text/event-stream' } })
      }
      return NextResponse.json({ assistant: fallback })
    }

    // Load last messages for context
    const history = await listMessages(thread.id, 30)
    const chatMessages = [
      { role: 'system' as const, content: system },
      ...history.map((m) => ({ role: m.role, content: m.content })),
    ]

    if (wantsStream) {
      // Wallet pre-check using conservative estimate (max_tokens)
      const model = 'gpt-5.6-sol'
      const promptText = [system, ...history.map((m) => m.content)].join('\n')
      let maxTokens = 500
      if (!allowViaFreeUse) {
        const cm = new CreditManager(session.user.id)
        const wallet = await cm.getWalletStatus()
        const cappedMaxTokens = capMaxTokensToBudget(model, promptText, maxTokens, wallet.totalAvailableCents)
        if (cappedMaxTokens <= 0) {
          return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
        }
        maxTokens = cappedMaxTokens
      }

      const wrapped = await chatCompletionWithCost(openai, {
        model,
        temperature: 0.2,
        max_tokens: maxTokens,
        messages: chatMessages as any,
      } as any)

      if (!allowViaFreeUse) {
        const cm = new CreditManager(session.user.id)
        const ok = await cm.chargeCents(wrapped.costCents)
        if (!ok) {
          return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
        }
      } else {
        await consumeFreeCredit(session.user.id, 'INSIGHTS_CHAT')
      }

      try {
        await logAIUsage({
          context: { feature: `insights:section-chat:${section}`, userId: session.user.id, issueSlug: context.params.slug },
          model,
          promptTokens: wrapped.promptTokens,
          completionTokens: wrapped.completionTokens,
          costCents: wrapped.costCents,
        })
      } catch {
        // Ignore logging failures
      }

      const textRaw = wrapped.completion.choices?.[0]?.message?.content || ''
      const text = textRaw.trim() ? textRaw : EMPTY_RESPONSE_FALLBACK
      await appendMessage(thread.id, 'assistant', text)
      await updateThreadCost(session.user.id, thread.id, wrapped.costCents, allowViaFreeUse)

      const enc = new TextEncoder()
      const chunks = text.match(/[\s\S]{1,200}/g) || ['']
      const costPayload = JSON.stringify({ costCents: wrapped.costCents, covered: allowViaFreeUse })
      const stream = new ReadableStream({
        start(controller) {
          for (const chunk of chunks) {
            controller.enqueue(enc.encode(`data: ${chunk}\n\n`))
          }
          controller.enqueue(enc.encode(`data: __cost__${costPayload}\n\n`))
          controller.enqueue(enc.encode('event: end\n\n'))
          controller.close()
        },
      })
      return new Response(stream, { headers: { 'Content-Type': 'text/event-stream' } })
    }

    // Non-streaming fallback
  {
    const model = 'gpt-5.6-sol'
    const promptText = [system, ...history.map((m) => m.content)].join('\n')
    let maxTokens = 500
    if (!allowViaFreeUse) {
      const cm = new CreditManager(session.user.id)
      const wallet = await cm.getWalletStatus()
      const cappedMaxTokens = capMaxTokensToBudget(model, promptText, maxTokens, wallet.totalAvailableCents)
      if (cappedMaxTokens <= 0) {
        return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
      }
      maxTokens = cappedMaxTokens
    }
    const wrapped = await chatCompletionWithCost(openai, {
      model,
      temperature: 0.2,
      max_tokens: maxTokens,
      messages: chatMessages as any,
    } as any)
    if (!allowViaFreeUse) {
      const cm = new CreditManager(session.user.id)
      const ok = await cm.chargeCents(wrapped.costCents)
      if (!ok) {
        return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
      }
    } else {
      await consumeFreeCredit(session.user.id, 'INSIGHTS_CHAT')
    }

    // Log AI usage for non-streaming section chat
    try {
      await logAIUsage({
        context: {
          feature: `insights:section-chat:${section}`,
          userId: session.user.id,
          issueSlug: context.params.slug,
        },
        model,
        promptTokens: wrapped.promptTokens,
        completionTokens: wrapped.completionTokens,
        costCents: wrapped.costCents,
      })
    } catch {
      // Ignore logging failures
    }

    const textRaw = wrapped.completion.choices?.[0]?.message?.content || ''
    const text = textRaw.trim() ? textRaw : EMPTY_RESPONSE_FALLBACK
    await appendMessage(thread.id, 'assistant', text)
    await updateThreadCost(session.user.id, thread.id, wrapped.costCents, allowViaFreeUse)
    return NextResponse.json({
      assistant: text,
      threadId: thread.id,
      costCents: wrapped.costCents,
      covered: allowViaFreeUse,
    })
  }
  } catch (error) {
    console.error('[chat.POST] error', error)
    return NextResponse.json({ error: 'server_error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import {
  getIssueSection,
  ISSUE_SECTION_ORDER,
  type IssueSectionKey,
  getCachedIssueSection,
  CURRENT_PIPELINE_VERSION,
} from '@/lib/insights/issue-engine'
import { checkInsightsStatus, getStatusMessage } from '@/lib/insights/regeneration-service'
import { prisma } from '@/lib/prisma'
import {
  checkTargetedRefreshState,
  clearTargetedRefreshState,
  completeTargetedRefreshState,
  recordTargetedRefreshState,
} from '@/lib/insights/targeted-refresh-idempotency'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'

export async function GET(
  _request: NextRequest,
  context: { params: { slug: string; section: string } }
) {
  try {
    const session = await getServerSession(authOptions)
    const userId = session?.user?.id || (await getUserIdFromNativeAuth(_request))
    if (!userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const sectionParam = context.params.section as IssueSectionKey
    if (!ISSUE_SECTION_ORDER.includes(sectionParam)) {
      return NextResponse.json({ error: 'Invalid section' }, { status: 400 })
    }

    // Check insights status for user-friendly messaging
    const statusInfo = await checkInsightsStatus(userId, context.params.slug, sectionParam)
    const statusMessage = getStatusMessage(statusInfo.status, statusInfo.lastGenerated)

    const result = await getIssueSection(userId, context.params.slug, sectionParam)
    if (!result) {
      return NextResponse.json({ error: 'Not found' }, { status: 404 })
    }

    // Debug headers when INSIGHTS_DEBUG=1
    const headers: Record<string, string> = {}
    if (process.env.INSIGHTS_DEBUG === '1') {
      try {
        const extras = (result as any)?.extras ?? {}
        const pipelineVersion = extras.pipelineVersion ?? 'unknown'
        const responseType = extras.quickUsed ? 'quick' : extras.cacheHit ? 'cached' : 'validated'

        headers['X-Debug-ResponseType'] = responseType
        headers['X-Debug-PipelineVersion'] = String(pipelineVersion)

        if (sectionParam === 'supplements') {
          const supplements = extras.supportiveDetails ?? []
          const supplementNames = supplements.map((s: any) => s?.name).filter(Boolean)
          headers['X-Debug-Supplements'] = supplementNames.slice(0, 10).join(',')
          headers['X-Debug-WorkingCount'] = String(supplements.length)
        } else if (sectionParam === 'exercise') {
          const wa = Array.isArray(extras.workingActivities) ? extras.workingActivities : []
          headers['X-Debug-WorkingCount'] = String(wa.length)
          headers['X-Debug-WorkingTitles'] = wa.map((x: any) => x?.title).filter(Boolean).slice(0, 10).join(',')
          // eslint-disable-next-line no-console
          console.log('[insights.api] GET exercise section', {
            slug: context.params.slug,
            workingCount: wa.length,
            workingTitles: wa.map((x: any) => x?.title).filter(Boolean),
          })
        }
      } catch {}
    }

    // Add status information to the response
    const enrichedResult = {
      ...result,
      _meta: {
        status: statusInfo.status,
        lastGenerated: statusInfo.lastGenerated,
        statusMessage: statusMessage.message,
        statusTone: statusMessage.tone,
        needsUpdate: statusInfo.needsUpdate,
      },
    }

    return NextResponse.json(enrichedResult, { status: 200, headers })
  } catch (error) {
    console.error('GET /api/insights/issues/[slug]/sections/[section] error', error)
    return NextResponse.json({ error: 'Failed to load section' }, { status: 500 })
  }
}

export async function POST(
  _request: NextRequest,
  context: { params: { slug: string; section: string } }
) {
  try {
    const session = await getServerSession(authOptions)
    const userId = session?.user?.id || (await getUserIdFromNativeAuth(_request))
    if (!userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const sectionParam = context.params.section as IssueSectionKey
    if (!ISSUE_SECTION_ORDER.includes(sectionParam)) {
      return NextResponse.json({ error: 'Invalid section' }, { status: 400 })
    }

    let body: { mode?: string; range?: { from?: string; to?: string }; force?: boolean } = {}
    try {
      body = await _request.json()
    } catch {}

    const mode = (body?.mode === 'weekly' || body?.mode === 'daily' || body?.mode === 'custom') ? body.mode : 'latest'
    const range = body?.range && (body.range.from || body.range.to) ? body.range : undefined
    const forceRefresh = body?.force === true

    // If force refresh requested, skip cache and regenerate
    if (forceRefresh) {
      const refreshState = await checkTargetedRefreshState({
        userId: userId,
        changeTypes: [],
        affectedSections: [sectionParam],
        targetIssueSlugs: [context.params.slug],
        mode,
        range,
        pipelineVersion: CURRENT_PIPELINE_VERSION,
        intent: 'section-force-refresh',
      })

      if (!refreshState.guardReady) {
        return NextResponse.json(
          { error: 'Safety check paused', message: 'This refresh was paused because Helfi could not confirm whether anything changed.' },
          { status: 429 }
        )
      }

      if (refreshState.shouldSkip) {
        const quickResult = await getIssueSection(userId, context.params.slug, sectionParam, {
          mode,
          range,
          force: false,
        })

        return NextResponse.json({
          result: quickResult || null,
          upgraded: false,
          forceRefreshed: false,
          skippedUnchanged: true,
          generating: false,
          message: 'Nothing changed since the last refresh, so Helfi kept the current insight.',
        }, { status: 200 })
      }

      try {
        await recordTargetedRefreshState({
          userId: userId,
          scope: refreshState.scope,
          payloadHash: refreshState.payloadHash,
          status: 'pending',
        })
      } catch (error) {
        console.warn('[insights.api] Failed to lock section refresh safely', error)
        return NextResponse.json(
          { error: 'Safety check paused', message: 'This refresh was paused because Helfi could not lock it safely.' },
          { status: 429 }
        )
      }

      // Mark as generating in background (non-blocking)
      try {
        await prisma.$executeRawUnsafe(`
          INSERT INTO "InsightsMetadata" ("userId", "issueSlug", "section", "status", "updatedAt")
          VALUES ($1, $2, $3, 'generating', NOW())
          ON CONFLICT ("userId", "issueSlug", "section")
          DO UPDATE SET "status" = 'generating', "updatedAt" = NOW()
        `, userId, context.params.slug, sectionParam)
      } catch (error) {
        // Non-blocking - continue even if metadata update fails
        console.warn('[insights.api] Failed to mark as generating', error)
      }

      // Start regeneration in background (non-blocking)
      // Return immediately so user sees progress bar
      const backgroundRefresh = (async () => {
        try {
          const result = await getIssueSection(userId, context.params.slug, sectionParam, {
            mode,
            range,
            force: true,
          })
          // Mark as fresh after completion
          if (result) {
            await completeTargetedRefreshState({
              userId: userId,
              scope: refreshState.scope,
              payloadHash: refreshState.payloadHash,
            })
            try {
              await prisma.$executeRawUnsafe(`
                INSERT INTO "InsightsMetadata" ("userId", "issueSlug", "section", "status", "dataFingerprint", "lastGeneratedAt", "updatedAt")
                VALUES ($1, $2, $3, 'fresh', '', NOW(), NOW())
                ON CONFLICT ("userId", "issueSlug", "section")
                DO UPDATE SET "status" = 'fresh', "lastGeneratedAt" = NOW(), "updatedAt" = NOW()
              `, userId, context.params.slug, sectionParam)
            } catch (error) {
              console.warn('[insights.api] Failed to mark as fresh', error)
            }
          } else {
            await clearTargetedRefreshState({
              userId: userId,
              scope: refreshState.scope,
              payloadHash: refreshState.payloadHash,
            })
            try {
              await prisma.$executeRawUnsafe(`
                UPDATE "InsightsMetadata" SET "status" = 'stale', "updatedAt" = NOW()
                WHERE "userId" = $1 AND "issueSlug" = $2 AND "section" = $3
              `, userId, context.params.slug, sectionParam)
            } catch {}
          }
        } catch (error) {
          await clearTargetedRefreshState({
            userId: userId,
            scope: refreshState.scope,
            payloadHash: refreshState.payloadHash,
          })
          console.error('[insights.api] Background regeneration failed', error)
          // Mark as stale on error so it can retry
          try {
            await prisma.$executeRawUnsafe(`
              UPDATE "InsightsMetadata" SET "status" = 'stale', "updatedAt" = NOW()
              WHERE "userId" = $1 AND "issueSlug" = $2 AND "section" = $3
            `, userId, context.params.slug, sectionParam)
          } catch {}
        }
      })()
      const waitUntil = (globalThis as any).waitUntil || ((promise: Promise<unknown>) => promise.catch(() => {}))
      waitUntil(backgroundRefresh)

      // Return immediately with current cached result (if available) or empty response
      const quickResult = await getIssueSection(userId, context.params.slug, sectionParam, {
        mode,
        range,
        force: false, // Try to get cached/quick result for immediate display
      })

      return NextResponse.json({ 
        result: quickResult || null, 
        upgraded: false, 
        forceRefreshed: true,
        generating: true 
      }, { status: 200 })
    }

    // Fast path: Return quick result immediately, then upgrade in background
    // This prevents users from waiting a minute for generation
    const quickResult = await getIssueSection(userId, context.params.slug, sectionParam, {
      mode,
      range,
      force: false, // Don't force - use quick if available
    })

    if (quickResult) {
      // Return quick result immediately
      // Background upgrade will happen automatically via computeIssueSection
      return NextResponse.json({ result: quickResult, upgraded: false }, { status: 200 })
    }

    // Fallback: If no quick result available, do full build (but this should be rare)
    const result = await getIssueSection(userId, context.params.slug, sectionParam, {
      mode,
      range,
      force: true,
    })
    if (!result) {
      return NextResponse.json({ error: 'Not found' }, { status: 404 })
    }
    return NextResponse.json({ result, upgraded: true }, { status: 200 })
  } catch (error) {
    console.error('POST /api/insights/issues/[slug]/sections/[section] error', error)
    return NextResponse.json({ error: 'Failed to generate section' }, { status: 500 })
  }
}

