'use server'

import { NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import {
  ISSUE_SECTION_ORDER,
  type IssueSectionKey,
  type ReportMode,
  CURRENT_PIPELINE_VERSION,
} from '@/lib/insights/issue-engine'
import { prisma } from '@/lib/prisma'
import { precomputeQuickSectionsForUser } from '@/lib/insights/issue-engine'
import {
  checkTargetedRefreshState,
  clearTargetedRefreshState,
  completeTargetedRefreshState,
  recordTargetedRefreshState,
} from '@/lib/insights/targeted-refresh-idempotency'

interface PrefetchBody {
  sections?: IssueSectionKey[]
  mode?: ReportMode
  concurrency?: number
  range?: { from?: string; to?: string }
  forceAllIssues?: boolean
}

export async function POST(request: Request, context: { params: { slug: string } }) {
  const session = await getServerSession(authOptions)
  if (!session?.user?.id) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  let body: PrefetchBody = {}
  try {
    body = await request.json()
  } catch {
    body = {}
  }

  const requestedSections = Array.isArray(body.sections)
    ? body.sections.filter((section): section is IssueSectionKey => ISSUE_SECTION_ORDER.includes(section))
    : undefined

  const mode: ReportMode = body.mode === 'weekly' || body.mode === 'daily' || body.mode === 'custom' ? body.mode : 'latest'

  const startedAt = Date.now()
  const concurrency = body.concurrency ?? 4
  const forceAll = body.forceAllIssues === true

  const targetSections = (requestedSections ?? ISSUE_SECTION_ORDER.filter((s) => s !== 'overview'))
    .filter((s) => s !== 'interactions')

  const targetSlugs = forceAll
    ? (
        await prisma.$queryRawUnsafe<Array<{ name: string }>>(
          'SELECT name FROM "CheckinIssues" WHERE "userId" = $1',
          session.user.id
        ).catch(() => []) as Array<{ name: string }>
      ).map((row) => row.name.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, ''))
    : [context.params.slug]

  const refreshState = await checkTargetedRefreshState({
    userId: session.user.id,
    changeTypes: [],
    affectedSections: targetSections,
    targetIssueSlugs: targetSlugs,
    mode,
    range: body.range,
    pipelineVersion: CURRENT_PIPELINE_VERSION,
    intent: forceAll ? 'prefetch-all-quick' : 'prefetch-quick',
  })

  if (!refreshState.guardReady) {
    return NextResponse.json({
      ok: true,
      skippedUnchanged: true,
      safetyStop: true,
      sections: targetSections,
      durationMs: Date.now() - startedAt,
      concurrency,
      scope: forceAll ? 'all-issues' : 'single-issue',
    }, { status: 202 })
  }

  if (refreshState.shouldSkip) {
    return NextResponse.json({
      ok: true,
      skippedUnchanged: true,
      sections: targetSections,
      durationMs: Date.now() - startedAt,
      concurrency,
      scope: forceAll ? 'all-issues' : 'single-issue',
    }, { status: 202 })
  }

  try {
    await recordTargetedRefreshState({
      userId: session.user.id,
      scope: refreshState.scope,
      payloadHash: refreshState.payloadHash,
      status: 'pending',
    })
  } catch {
    return NextResponse.json({
      ok: true,
      skippedUnchanged: true,
      safetyStop: true,
      sections: targetSections,
      durationMs: Date.now() - startedAt,
      concurrency,
      scope: forceAll ? 'all-issues' : 'single-issue',
    }, { status: 202 })
  }

  // Write quick results to DB cache so section pages can read instantly
  try {
    if (forceAll) {
      await precomputeQuickSectionsForUser(session.user.id, { slugs: targetSlugs, sections: targetSections, concurrency })
    } else {
      await precomputeQuickSectionsForUser(session.user.id, { slugs: [context.params.slug], sections: targetSections, concurrency })
    }
    await completeTargetedRefreshState({
      userId: session.user.id,
      scope: refreshState.scope,
      payloadHash: refreshState.payloadHash,
    })
  } catch {
    await clearTargetedRefreshState({
      userId: session.user.id,
      scope: refreshState.scope,
      payloadHash: refreshState.payloadHash,
    })
    return NextResponse.json({
      ok: true,
      skippedUnchanged: true,
      safetyStop: true,
      sections: targetSections,
      durationMs: Date.now() - startedAt,
      concurrency,
      scope: forceAll ? 'all-issues' : 'single-issue',
    }, { status: 202 })
  }

  const durationMs = Date.now() - startedAt

  return NextResponse.json({ ok: true, sections: targetSections, durationMs, concurrency, scope: forceAll ? 'all-issues' : 'single-issue' }, { status: 202 })
}

import { NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { checkInsightsStatus } from '@/lib/insights/regeneration-service'
import { ISSUE_SECTION_ORDER, type IssueSectionKey } from '@/lib/insights/issue-engine'

export async function GET(
  _request: Request,
  context: { params: { slug: string } }
) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const issueSlug = context.params.slug
    const sections = ISSUE_SECTION_ORDER.filter((s) => s !== 'overview') as IssueSectionKey[]

    // Check status for all sections
    const statusPromises = sections.map(async (section) => {
      const status = await checkInsightsStatus(session.user.id, issueSlug, section)
      return {
        section,
        ...status,
      }
    })

    const statuses = await Promise.all(statusPromises)

    // Determine overall status
    const hasStale = statuses.some(s => s.status === 'stale' || s.needsUpdate)
    const hasMissing = statuses.some(s => s.status === 'missing')
    const hasGenerating = statuses.some(s => s.status === 'generating')
    const allFresh = statuses.every(s => s.status === 'fresh' && !s.needsUpdate)

    const needsRegeneration = hasStale || hasMissing || (hasGenerating && !allFresh)

    return NextResponse.json({
      needsRegeneration,
      statuses: statuses.reduce((acc, s) => {
        acc[s.section] = {
          status: s.status,
          needsUpdate: s.needsUpdate,
          lastGenerated: s.lastGenerated?.toISOString() || null,
        }
        return acc
      }, {} as Record<string, { status: string; needsUpdate: boolean; lastGenerated: string | null }>),
    })
  } catch (error) {
    console.error('[insights.api] Error checking insights status', error)
    return NextResponse.json({ error: 'Failed to check insights status' }, { status: 500 })
  }
}

