function getOpenAIClient(): OpenAI | null {
  if (!process.env.OPENAI_API_KEY) return null
  return new OpenAI({ apiKey: process.env.OPENAI_API_KEY })
}

function buildTitle(text: string): string {
  const trimmed = text.trim()
  if (!trimmed) return 'New chat'
  return trimmed.length > 50 ? `${trimmed.slice(0, 47)}...` : trimmed
}

function extractAssistantText(wrapped: any): string {
  const message = wrapped?.completion?.choices?.[0]?.message
  const content = message?.content

  if (typeof content === 'string') {
    return content.trim()
  }

  if (Array.isArray(content)) {
    const combined = content
      .map((part: any) => {
        if (typeof part === 'string') return part
        if (!part || typeof part !== 'object') return ''
        if (typeof part.text === 'string') return part.text
        if (typeof part.content === 'string') return part.content
        return ''
      })
      .join('')
      .trim()
    if (combined) return combined
  }

  if (typeof message?.refusal === 'string' && message.refusal.trim()) {
    return message.refusal.trim()
  }

  return ''
}

function formatForNativePlainText(raw: string): string {
  let text = String(raw || '').replace(/\r\n/g, '\n')

  text = text.replace(/^#{1,6}\s*/gm, '')
  text = text.replace(/\*\*([^*]+)\*\*/g, '$1')
  text = text.replace(/\*([^*\n]+)\*/g, '$1')
  text = text.replace(/`([^`\n]+)`/g, '$1')
  text = text.replace(/^\s*[-*]\s+/gm, '• ')
  text = text.replace(/([^\n])(\d+\.\s)/g, '$1\n$2')
  text = text.replace(/([^\n])(•\s)/g, '$1\n$2')
  text = text.replace(/\n{3,}/g, '\n\n')

  return text.trim()
}

function buildFallbackAssistantText(params: {
  question: string
  summary: string | null
  redFlags: string[]
  nextSteps: string[]
  topCause: { name?: string; whyLikely?: string; confidence?: string } | null
}): string {
  const question = (params.question || '').toLowerCase()
  const topTopicText = params.topCause?.name || 'the main topic from your image notes'
  const topTopicWhy = params.topCause?.whyLikely || null

  const likelyDoctorTriggers = params.redFlags.length
    ? params.redFlags.slice(0, 3)
    : ['fast worsening pain', 'spreading redness', 'fever or feeling very unwell']
  const trackingNotes = params.nextSteps.length
    ? params.nextSteps.slice(0, 4)
    : ['Take clear photos daily to track changes.', 'Write down when the change started.', 'Note whether the area is changing, painful, bleeding, or spreading.']

  if (question.includes('red flag') || question.includes('urgent') || question.includes('emergency')) {
    return [
      '**Short answer**',
      '',
      'The key warning signs are listed below. If you notice any of them, get medical care quickly.',
      '',
      '**Why this matters**',
      '',
      '- These signs can mean the issue is getting worse.',
      '- Fast changes are safer to check early.',
      '',
      '**When to seek care**',
      '',
      ...likelyDoctorTriggers.map((item) => `- ${item}`),
      '- Go to urgent care or emergency now if symptoms are severe or rapidly worsening.',
      '',
      '**Tracking notes**',
      '',
      '- Monitor the area twice daily and note any changes.',
      '- Keep clear notes and photos to show a healthcare professional.',
      '- This guidance does not replace an in-person medical exam.',
    ].join('\n')
  }

  return [
    '**Short answer**',
    '',
    params.summary
      ? `${params.summary}`
      : `From your image notes, the main topic to discuss is ${topTopicText}.`,
    '',
    '**Why this matters**',
    '',
    `- Your notes mention ${topTopicText}.`,
    topTopicWhy ? `- Why this is worth discussing: ${topTopicWhy}` : '- Visible changes can be easier to assess when they are tracked over time.',
    '- Watching changes over time helps you decide when to seek care.',
    '',
    '**When to seek care**',
    '',
    ...likelyDoctorTriggers.map((item) => `- ${item}`),
    '- If you are unsure, booking a routine appointment is a safe next step.',
    '',
    '**Tracking notes**',
    '',
    ...trackingNotes.map((step) => `- ${step}`),
    '- This information is not a diagnosis and does not replace a doctor.',
  ].join('\n')
}

async function resolveMedicalChatUser(request: NextRequest): Promise<{ id: string; email: string | null } | null> {
  const session = await getServerSession(authOptions)
  const sessionUserId = String(session?.user?.id || '').trim()
  if (sessionUserId) {
    const user = await prisma.user.findUnique({
      where: { id: sessionUserId },
      select: { id: true, email: true },
    })
    if (user?.id) return { id: user.id, email: user.email || null }
  }

  const sessionEmail = String(session?.user?.email || '').trim().toLowerCase()
  if (sessionEmail) {
    const user = await prisma.user.findUnique({
      where: { email: sessionEmail },
      select: { id: true, email: true },
    })
    if (user?.id) return { id: user.id, email: user.email || null }
  }

  const token = await getToken({
    req: request as any,
    secret: process.env.NEXTAUTH_SECRET || process.env.AUTH_SECRET || 'helfi-secret-key-production-2024',
  }).catch(() => null)

  const tokenUserId = String(token?.sub || token?.id || '').trim()
  if (tokenUserId) {
    const user = await prisma.user.findUnique({
      where: { id: tokenUserId },
      select: { id: true, email: true },
    })
    if (user?.id) return { id: user.id, email: user.email || null }
  }

  const tokenEmail = String(token?.email || '').trim().toLowerCase()
  if (tokenEmail) {
    const user = await prisma.user.findUnique({
      where: { email: tokenEmail },
      select: { id: true, email: true },
    })
    if (user?.id) return { id: user.id, email: user.email || null }
  }

  const nativeUserId = await getUserIdFromNativeAuth(request)
  if (!nativeUserId) return null

  const nativeUser = await prisma.user.findUnique({
    where: { id: nativeUserId },
    select: { id: true, email: true },
  })
  if (!nativeUser?.id) return null
  return { id: nativeUser.id, email: nativeUser.email || null }
}

export async function GET(req: NextRequest) {
  try {
    const chatUser = await resolveMedicalChatUser(req)
    if (!chatUser?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }
    const url = new URL(req.url)
    const threadId = url.searchParams.get('threadId')
    if (!threadId) {
      return NextResponse.json({ error: 'threadId required' }, { status: 400 })
    }
    let thread = null as Awaited<ReturnType<typeof getThread>> | null
    let messages: Awaited<ReturnType<typeof listMessages>> = []
    try {
      thread = await getThread(chatUser.id, threadId)
      if (!thread) {
        return NextResponse.json({ error: 'Thread not found' }, { status: 404 })
      }
      messages = await listMessages(threadId, 60)
    } catch (storageError) {
      console.error('[medical-chat.GET] storage fallback', storageError)
      messages = []
    }
    return NextResponse.json({ threadId, messages }, { status: 200 })
  } catch (error) {
    console.error('[medical-chat.GET] error', error)
    return NextResponse.json({ error: 'server_error' }, { status: 500 })
  }
}

export async function POST(req: NextRequest) {
  try {
    const isNativeClient = Boolean(req.headers.get('x-native-token') || req.headers.get('X-Native-Token'))
    const chatUser = await resolveMedicalChatUser(req)
    if (!chatUser?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const contentType = req.headers.get('content-type') || ''
    let body: {
      message?: string
      threadId?: string
      analysisResult?: any
    } = {}
    if (contentType.includes('application/json')) {
      try {
        body = await req.json()
      } catch {}
    }

    const question = String(body?.message || '').trim()
    if (!question) {
      return NextResponse.json({ error: 'Message required' }, { status: 400 })
    }

    const safeAnalysisResult =
      body?.analysisResult && typeof body.analysisResult === 'object' ? body.analysisResult : {}
    const contextPayload = { analysisResult: safeAnalysisResult }
    const hasContext = Object.keys(safeAnalysisResult || {}).length > 0

    const requestedThreadId = typeof body?.threadId === 'string' ? body.threadId.trim() : ''
    let threadId = requestedThreadId
    let thread: Awaited<ReturnType<typeof getThread>> | null = null
    let persistChatHistory = true

    try {
      thread = threadId ? await getThread(chatUser.id, threadId) : null

      if (!thread) {
        const title = buildTitle(question)
        const created = await createThread(chatUser.id, hasContext ? contextPayload : undefined, title)
        threadId = created.id
        thread = { id: created.id, title, context: hasContext ? contextPayload : null }
      } else {
        if (hasContext) {
          await updateThreadContext(chatUser.id, threadId, contextPayload)
        }
        if (!thread.title) {
          await updateThreadTitle(chatUser.id, threadId, buildTitle(question))
        }
      }
    } catch (storageError) {
      console.error('[medical-chat.POST] storage fallback', storageError)
      persistChatHistory = false
      threadId = threadId || `medical-fallback-${Date.now()}`
      thread = { id: threadId, title: buildTitle(question), context: hasContext ? contextPayload : null }
    }

    const threadContext = hasContext ? contextPayload : thread?.context || {}
    const analysisResult =
      threadContext?.analysisResult && typeof threadContext.analysisResult === 'object'
        ? threadContext.analysisResult
        : {}

    const openai = getOpenAIClient()
    if (!openai) {
      return NextResponse.json({ error: 'AI service not configured' }, { status: 500 })
    }
    const user = await prisma.user.findUnique({
      where: { id: chatUser.id },
      include: { subscription: true, creditTopUps: true },
    })
    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    const isPremium = isSubscriptionActive(user.subscription)
    const now = new Date()
    const hasPurchasedCredits = user.creditTopUps?.some(
      (topUp: any) => topUp.expiresAt > now && (topUp.amountCents - topUp.usedCents) > 0
    )
    const hasLegacyCredits = Number((user as any)?.additionalCredits || 0) > 0
    const hasPaidAccess = isPremium || hasPurchasedCredits || hasLegacyCredits
    let hasFreeChatCredits = false
    try {
      hasFreeChatCredits = await hasFreeCredits(user.id, 'MEDICAL_CHAT')
    } catch (creditError) {
      console.error('[medical-chat.POST] free-credit fallback', creditError)
      hasFreeChatCredits = false
    }
    const allowViaFreeUse = !hasPaidAccess && hasFreeChatCredits
    if (!hasPaidAccess && !hasFreeChatCredits) {
      return NextResponse.json(
        {
          error: 'Payment required',
          message: 'You\'ve used all your free health image note chat uses. Subscribe to a monthly plan or purchase credits to continue.',
          requiresPayment: true,
          exhaustedFreeCredits: true,
        },
        { status: 402 }
      )
    }

    // Build system prompt with health image notes context.
    const systemPrompt = [
      'You are a careful, patient-friendly general health assistant helping users ask follow-up questions about recent health image notes.',
      'You already have the image notes as background context. Treat them as general notes only. Do not diagnose, do not provide treatment advice, and do not claim certainty.',
      '',
      analysisResult.summary ? `Analysis summary: ${analysisResult.summary}` : '',
      Array.isArray(analysisResult.possibleCauses) && analysisResult.possibleCauses.length
        ? `Doctor discussion topics:\n${analysisResult.possibleCauses
            .map((c: any) => `- ${c.name}: ${c.whyLikely || ''}`.trim())
            .join('\n')}`
        : '',
      Array.isArray(analysisResult.redFlags) && analysisResult.redFlags.length
        ? `Urgent-care warning signs mentioned in the notes:\n${analysisResult.redFlags
            .map((rf: string) => `- ${rf}`)
            .join('\n')}`
        : '',
      Array.isArray(analysisResult.nextSteps) && analysisResult.nextSteps.length
        ? `Tracking notes and doctor questions:\n${analysisResult.nextSteps
            .map((ns: string) => `- ${ns}`)
            .join('\n')}`
        : '',
      analysisResult.analysisText
        ? `Full analysis text (for your reference only):\n${String(analysisResult.analysisText).slice(
            0,
            1200
          )}`
        : '',
      '',
      'When you answer, focus on the user’s specific question, not on re-stating the full notes.',
      '',
      'Always use the following section layout with the bold headings written exactly as shown, each on its own line with a blank line after it:',
      '',
      '**Short answer**',
      '- 2–4 sentences that directly answer the user’s question in plain language.',
      '',
      '**Why this matters**',
      '- 2-4 short bullet points explaining why this is worth tracking or discussing with a healthcare professional.',
      '',
      '**When to seek care**',
      '- Bullet points explaining when it is sensible to book a routine appointment and when it is important to seek urgent or emergency care, tailored to their question.',
      '',
      '**Tracking notes**',
      '- Simple monitoring notes and questions to ask a healthcare professional. Do not give treatment instructions.',
      '',
      'Only pull in details from the original notes when they help answer the question; do NOT dump or repeat the full report. Use short sentences and bullet points so the reply is easy to scan in the chat bubble.',
      '',
      'Safety rules:',
      '- Do NOT provide a formal diagnosis or treatment plan.',
      '- Do NOT say that a doctor is unnecessary; instead, explain when medical review would be sensible.',
      '- Always remind the user that this information does not replace a real doctor examination.',
    ]
      .filter(Boolean)
      .join('\n')

    const accept = (req.headers.get('accept') || '').toLowerCase()
    const wantsStream = accept.includes('text/event-stream')

    const history = persistChatHistory
      ? await listMessages(threadId, 30).catch((storageError) => {
          console.error('[medical-chat.POST] history fallback', storageError)
          persistChatHistory = false
          return []
        })
      : []
    const chatMessages = [
      { role: 'system' as const, content: systemPrompt },
      ...history.map((m) => ({ role: m.role, content: m.content })),
      { role: 'user' as const, content: question },
    ]

    if (persistChatHistory) {
      await appendMessage(threadId, 'user', question).catch((storageError) => {
        console.error('[medical-chat.POST] append user fallback', storageError)
        persistChatHistory = false
      })
    }

    const possibleCauses = Array.isArray(analysisResult?.possibleCauses)
      ? analysisResult.possibleCauses.filter((item: any) => item && typeof item === 'object')
      : []
    const redFlags = Array.isArray(analysisResult?.redFlags)
      ? analysisResult.redFlags.filter((item: any) => typeof item === 'string')
      : []
    const nextSteps = Array.isArray(analysisResult?.nextSteps)
      ? analysisResult.nextSteps.filter((item: any) => typeof item === 'string')
      : []
    const fallbackText = buildFallbackAssistantText({
      question,
      summary: typeof analysisResult?.summary === 'string' ? analysisResult.summary : null,
      redFlags,
      nextSteps,
      topCause: possibleCauses[0] || null,
    })
    const finalFallbackText = isNativeClient ? formatForNativePlainText(fallbackText) : fallbackText

    if (wantsStream) {
      const model = 'gpt-5.6-sol'
      const promptText = [systemPrompt, ...history.map((m) => m.content), question].join('\n')
      let maxTokens = 800
      if (!allowViaFreeUse && !hasPaidAccess) {
        try {
          const cm = new CreditManager(user.id)
          const wallet = await cm.getWalletStatus()
          const cappedMaxTokens = capMaxTokensToBudget(model, promptText, maxTokens, wallet.totalAvailableCents)
          if (cappedMaxTokens <= 0) {
            return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
          }
          maxTokens = cappedMaxTokens
        } catch (billingError) {
          return NextResponse.json({ error: 'Billing error' }, { status: 402 })
        }
      }

      let wrapped: any
      try {
        wrapped = await chatCompletionWithCost(openai, {
          model,
          temperature: 0.2,
          max_tokens: maxTokens,
          messages: chatMessages as any,
        } as any)
      } catch (aiError) {
        if (persistChatHistory) {
          await appendMessage(threadId, 'assistant', finalFallbackText).catch(() => {})
        }
        const enc = new TextEncoder()
        const chunks = finalFallbackText.match(/[\s\S]{1,200}/g) || ['']
        const costPayload = JSON.stringify({ costCents: 0, covered: true })
        const stream = new ReadableStream({
          start(controller) {
            for (const chunk of chunks) {
              controller.enqueue(enc.encode(`data: ${chunk}\n\n`))
            }
            controller.enqueue(enc.encode(`data: __cost__${costPayload}\n\n`))
            controller.enqueue(enc.encode('event: end\n\n'))
            controller.close()
          },
        })
        console.error('[medical-chat.POST] stream AI fallback used', aiError)
        return new Response(stream, { headers: { 'Content-Type': 'text/event-stream' } })
      }

      const text = extractAssistantText(wrapped)
      if (!text) {
        if (persistChatHistory) {
          await appendMessage(threadId, 'assistant', finalFallbackText).catch(() => {})
        }
        const enc = new TextEncoder()
        const chunks = finalFallbackText.match(/[\s\S]{1,200}/g) || ['']
        const costPayload = JSON.stringify({ costCents: 0, covered: true })
        const stream = new ReadableStream({
          start(controller) {
            for (const chunk of chunks) {
              controller.enqueue(enc.encode(`data: ${chunk}\n\n`))
            }
            controller.enqueue(enc.encode(`data: __cost__${costPayload}\n\n`))
            controller.enqueue(enc.encode('event: end\n\n'))
            controller.close()
          },
        })
        return new Response(stream, { headers: { 'Content-Type': 'text/event-stream' } })
      }
      const finalText = isNativeClient ? formatForNativePlainText(text) : text

      if (!allowViaFreeUse) {
        try {
          const cm = new CreditManager(user.id)
          const ok = await cm.chargeCents(wrapped.costCents)
          if (!ok && !hasPaidAccess) {
            return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
          }
          if (!ok && hasPaidAccess) {
            console.error('[medical-chat.POST] paid-user stream charge could not be written')
          }
        } catch (billingError) {
          if (!hasPaidAccess) {
            return NextResponse.json({ error: 'Billing error' }, { status: 402 })
          }
          console.error('[medical-chat.POST] paid-user stream charge fallback', billingError)
        }
      } else {
        try {
          await consumeFreeCredit(user.id, 'MEDICAL_CHAT')
        } catch (creditError) {
          console.error('[medical-chat.POST] consume free credit fallback', creditError)
        }
      }

      try {
        await logAIUsage({
          context: { feature: 'medical-image:chat', userId: user.id },
          model,
          promptTokens: wrapped.promptTokens,
          completionTokens: wrapped.completionTokens,
          costCents: wrapped.costCents,
        })
      } catch {
        // Ignore logging failures
      }

      if (persistChatHistory) {
        await appendMessage(threadId, 'assistant', finalText).catch((storageError) => {
          console.error('[medical-chat.POST] append assistant fallback', storageError)
        })
        await updateThreadCost(chatUser.id, threadId, wrapped.costCents, allowViaFreeUse).catch((storageError) => {
          console.error('[medical-chat.POST] update cost fallback', storageError)
        })
      }
      const enc = new TextEncoder()
      const chunks = finalText.match(/[\s\S]{1,200}/g) || ['']
      const costPayload = JSON.stringify({ costCents: wrapped.costCents, covered: allowViaFreeUse })
      const stream = new ReadableStream({
        start(controller) {
          for (const chunk of chunks) {
            controller.enqueue(enc.encode(`data: ${chunk}\n\n`))
          }
          controller.enqueue(enc.encode(`data: __cost__${costPayload}\n\n`))
          controller.enqueue(enc.encode('event: end\n\n'))
          controller.close()
        },
      })
      return new Response(stream, { headers: { 'Content-Type': 'text/event-stream' } })
    }

    // Non-streaming fallback
    {
      const model = 'gpt-5.6-sol'
      let maxTokens = 800
      // Pre-check
      if (!allowViaFreeUse && !hasPaidAccess) {
        try {
          const cm = new CreditManager(user.id)
          const wallet = await cm.getWalletStatus()
          const cappedMaxTokens = capMaxTokensToBudget(
            model,
            [systemPrompt, ...history.map((m) => m.content), question].join('\n'),
            maxTokens,
            wallet.totalAvailableCents
          )
          if (cappedMaxTokens <= 0) {
            return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
          }
          maxTokens = cappedMaxTokens
        } catch (billingError) {
          return NextResponse.json({ error: 'Billing error' }, { status: 402 })
        }
      }
      let wrapped: any
      try {
        wrapped = await chatCompletionWithCost(openai, {
          model,
          temperature: 0.2,
          max_tokens: maxTokens,
          messages: chatMessages as any,
        } as any)
      } catch (aiError) {
        if (persistChatHistory) {
          await appendMessage(threadId, 'assistant', finalFallbackText).catch(() => {})
        }
        console.error('[medical-chat.POST] non-stream AI fallback used', aiError)
        return NextResponse.json({ assistant: finalFallbackText, costCents: 0, covered: true, threadId })
      }

      const text = extractAssistantText(wrapped)
      if (!text) {
        if (persistChatHistory) {
          await appendMessage(threadId, 'assistant', finalFallbackText).catch(() => {})
        }
        return NextResponse.json({ assistant: finalFallbackText, costCents: 0, covered: true, threadId })
      }
      const finalText = isNativeClient ? formatForNativePlainText(text) : text

      if (!allowViaFreeUse) {
        try {
          const cm = new CreditManager(user.id)
          const ok = await cm.chargeCents(wrapped.costCents)
          if (!ok && !hasPaidAccess) {
            return NextResponse.json({ error: 'Insufficient credits' }, { status: 402 })
          }
          if (!ok && hasPaidAccess) {
            console.error('[medical-chat.POST] paid-user non-stream charge could not be written')
          }
        } catch (billingError) {
          if (!hasPaidAccess) {
            return NextResponse.json({ error: 'Billing error' }, { status: 402 })
          }
          console.error('[medical-chat.POST] paid-user non-stream charge fallback', billingError)
        }
      } else {
        try {
          await consumeFreeCredit(user.id, 'MEDICAL_CHAT')
        } catch (creditError) {
          console.error('[medical-chat.POST] consume free credit fallback', creditError)
        }
      }

      // Log AI usage for non-streaming health image notes chat
      try {
        await logAIUsage({
          context: { feature: 'medical-image:chat', userId: user.id },
          model,
          promptTokens: wrapped.promptTokens,
          completionTokens: wrapped.completionTokens,
          costCents: wrapped.costCents,
        })
      } catch {
        // Ignore logging failures
      }

      if (persistChatHistory) {
        await appendMessage(threadId, 'assistant', finalText).catch((storageError) => {
          console.error('[medical-chat.POST] append assistant fallback', storageError)
        })
        await updateThreadCost(chatUser.id, threadId, wrapped.costCents, allowViaFreeUse).catch((storageError) => {
          console.error('[medical-chat.POST] update cost fallback', storageError)
        })
      }
      return NextResponse.json({ assistant: finalText, costCents: wrapped.costCents, covered: allowViaFreeUse, threadId })
    }
  } catch (error) {
    console.error('[medical-images.chat.POST] error', error)
    return NextResponse.json(
      {
        assistant:
          'I had a temporary issue answering that. Please try sending your question again. If it keeps happening, tap New chat and try once more.',
        costCents: 0,
        covered: true,
      },
      { status: 200 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { del, head, put } from '@vercel/blob'
import { decryptBuffer, encryptBuffer } from '@/lib/file-encryption'
import { verifySignedFileToken } from '@/lib/signed-file'

const CACHE_TTL_SECONDS = 60

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const token = (searchParams.get('token') || '').trim()
    if (!token) {
      return NextResponse.json({ error: 'Missing token' }, { status: 400 })
    }

    const payload = verifySignedFileToken(token)
    if (!payload || payload.usage !== 'MEDICAL_IMAGE') {
      return NextResponse.json({ error: 'Invalid token' }, { status: 401 })
    }

    const fileRecord = await prisma.file.findUnique({
      where: { id: payload.fileId },
    })

    if (!fileRecord || fileRecord.usage !== 'MEDICAL_IMAGE') {
      return NextResponse.json({ error: 'File not found' }, { status: 404 })
    }

    if (payload.userId !== fileRecord.uploadedById) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 403 })
    }

    const metadata = (fileRecord.metadata || {}) as any
    const blobPathname = metadata.blobPathname || fileRecord.cloudinaryId || fileRecord.fileName
    if (!blobPathname) {
      return NextResponse.json({ error: 'File is unavailable' }, { status: 404 })
    }

    const blobInfo = await head(blobPathname)
    if (!blobInfo?.url) {
      return NextResponse.json({ error: 'File is unavailable' }, { status: 404 })
    }

    const blobResponse = await fetch(blobInfo.url, {
      headers: process.env.BLOB_READ_WRITE_TOKEN
        ? { Authorization: `Bearer ${process.env.BLOB_READ_WRITE_TOKEN}` }
        : undefined,
    })

    if (!blobResponse.ok) {
      return NextResponse.json({ error: 'File is unavailable' }, { status: 404 })
    }

    let buffer: Buffer = Buffer.from(await blobResponse.arrayBuffer())
    const isEncrypted = metadata?.encrypted === true

    if (isEncrypted) {
      buffer = decryptBuffer(buffer, metadata?.encryption?.iv, metadata?.encryption?.tag)
    } else {
      try {
        const encryptedPayload = encryptBuffer(buffer)
        const upgradedPath = `medical-images/${fileRecord.uploadedById}/${Date.now()}-${fileRecord.id}.bin`
        const upgradedBlob = await put(upgradedPath, encryptedPayload.encrypted, {
          access: 'public',
          contentType: 'application/octet-stream',
          addRandomSuffix: true,
        })

        await prisma.file.update({
          where: { id: fileRecord.id },
          data: {
            fileName: upgradedBlob.pathname,
            cloudinaryId: upgradedBlob.pathname,
            cloudinaryUrl: upgradedBlob.url,
            secureUrl: upgradedBlob.url,
            isPublic: false,
            metadata: {
              ...(metadata || {}),
              blobPathname: upgradedBlob.pathname,
              blobUrl: upgradedBlob.url,
              encrypted: true,
              encryption: {
                algorithm: 'aes-256-gcm',
                iv: encryptedPayload.iv,
                tag: encryptedPayload.tag,
              },
            },
          },
        })

        await del(blobPathname).catch(() => {})
      } catch (upgradeError) {
        console.warn('Health image note encryption upgrade failed:', upgradeError)
      }
    }

    return new Response(buffer as any, {
      headers: {
        'Content-Type': fileRecord.mimeType || 'application/octet-stream',
        'Cache-Control': `private, max-age=${CACHE_TTL_SECONDS}`,
      },
    })
  } catch (error) {
    console.error('Secure health image note fetch failed:', error)
    return NextResponse.json({ error: 'Failed to load file' }, { status: 500 })
  }
}

export const runtime = 'nodejs'

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'
import { prisma } from '@/lib/prisma'
import { del } from '@vercel/blob'

async function getMedicalImageUser(request: NextRequest) {
  const nativeUserId = await getUserIdFromNativeAuth(request)
  if (nativeUserId) {
    return prisma.user.findUnique({ where: { id: nativeUserId } })
  }

  const session = await getServerSession(authOptions)
  const email = String(session?.user?.email || '').trim().toLowerCase()
  if (!email) return null
  return prisma.user.findUnique({ where: { email } })
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    const user = await getMedicalImageUser(request)
    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const analysisId = params.id
    if (!analysisId) {
      return NextResponse.json({ error: 'Missing id' }, { status: 400 })
    }

    const analysis = await prisma.medicalImageAnalysis.findFirst({
      where: { id: analysisId, userId: user.id },
      include: { imageFile: true },
    })

    if (!analysis) {
      return NextResponse.json({ error: 'Not found' }, { status: 404 })
    }

    const blobTarget = analysis.imageFile?.cloudinaryId || analysis.imageFile?.secureUrl || null
    if (blobTarget && process.env.BLOB_READ_WRITE_TOKEN) {
      try {
        await del(blobTarget)
      } catch (deleteError) {
        console.warn('Failed to delete health image note file:', deleteError)
      }
    }

    await prisma.$transaction([
      prisma.medicalImageAnalysis.delete({ where: { id: analysis.id } }),
      analysis.imageFileId
        ? prisma.file.deleteMany({ where: { id: analysis.imageFileId } })
        : prisma.file.deleteMany({ where: { id: { in: [] } } }),
    ])

    return NextResponse.json({ success: true })
  } catch (error) {
    console.error('Error deleting health image notes history item:', error)
    return NextResponse.json(
      {
        error: 'Failed to delete history item',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'
import { prisma } from '@/lib/prisma'
import { del, put } from '@vercel/blob'
import { encryptBuffer } from '@/lib/file-encryption'
import { createSignedFileToken } from '@/lib/signed-file'

const contentTypeToExt = (contentType: string) => {
  if (contentType === 'image/png') return 'png'
  if (contentType === 'image/webp') return 'webp'
  if (contentType === 'image/gif') return 'gif'
  return 'jpg'
}

async function getMedicalImageUser(request: NextRequest) {
  const nativeUserId = await getUserIdFromNativeAuth(request)
  if (nativeUserId) {
    return prisma.user.findUnique({ where: { id: nativeUserId } })
  }

  const session = await getServerSession(authOptions)
  const email = String(session?.user?.email || '').trim().toLowerCase()
  if (!email) return null
  return prisma.user.findUnique({ where: { email } })
}

export async function GET(request: NextRequest) {
  try {
    const user = await getMedicalImageUser(request)
    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const analyses = await prisma.medicalImageAnalysis.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: 'desc' },
      select: {
        id: true,
        summary: true,
        analysisText: true,
        analysisData: true,
        createdAt: true,
        imageFile: {
          select: {
            id: true,
            uploadedById: true,
          },
        },
      },
    })

    const history = analyses.map((item) => {
      const fileId = item.imageFile?.id
      const ownerId = item.imageFile?.uploadedById || user.id
      const imageUrl = fileId
        ? `/api/medical-images/file?token=${encodeURIComponent(
            createSignedFileToken({ fileId, userId: ownerId, usage: 'MEDICAL_IMAGE' })
          )}`
        : null

      return {
      id: item.id,
      summary: item.summary,
      analysisText: item.analysisText,
      analysisData: item.analysisData,
      createdAt: item.createdAt,
      imageUrl,
    }
  })

    return NextResponse.json({ success: true, history })
  } catch (error) {
    console.error('Error fetching health image notes history:', error)
    return NextResponse.json(
      {
        error: 'Failed to fetch health image notes history',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    )
  }
}

export async function POST(request: NextRequest) {
  try {
    const user = await getMedicalImageUser(request)
    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    if (!process.env.BLOB_READ_WRITE_TOKEN) {
      return NextResponse.json({ error: 'Image storage is not configured' }, { status: 500 })
    }

    // NextRequest.formData() returns a standard web FormData, but type
    // definitions can vary between runtimes and cause build-time TS errors.
    // Cast to `any` here to preserve runtime behavior without changing logic.
    const formData: any = await request.formData()
    const imageFile = formData.get('image')
    const analysisRaw = formData.get('analysis')

    if (!imageFile || typeof imageFile === 'string') {
      return NextResponse.json({ error: 'No image provided' }, { status: 400 })
    }
    if (!analysisRaw || typeof analysisRaw !== 'string') {
      return NextResponse.json({ error: 'No analysis provided' }, { status: 400 })
    }

    let analysisPayload: any
    try {
      analysisPayload = JSON.parse(analysisRaw)
    } catch {
      return NextResponse.json({ error: 'Invalid analysis payload' }, { status: 400 })
    }

    const ext = contentTypeToExt(imageFile.type || 'image/jpeg')
    const filename = `${Date.now()}.${ext}`
    const pathname = `medical-images/${user.id}/${filename}`
    const buffer = Buffer.from(await imageFile.arrayBuffer())
    const encryptedPayload = encryptBuffer(buffer)

    const blob = await put(pathname, encryptedPayload.encrypted, {
      access: 'public',
      contentType: 'application/octet-stream',
      addRandomSuffix: true,
    })

    const fileRecord = await prisma.file.create({
      data: {
        originalName: imageFile.name || filename,
        fileName: blob.pathname,
        fileSize: imageFile.size || buffer.length,
        mimeType: imageFile.type || 'image/jpeg',
        cloudinaryId: blob.pathname,
        cloudinaryUrl: blob.url,
        secureUrl: blob.url,
        uploadedById: user.id,
        fileType: 'IMAGE',
        usage: 'MEDICAL_IMAGE',
        isPublic: false,
        metadata: {
          storage: 'vercel-blob',
          blobPathname: blob.pathname,
          blobUrl: blob.url,
          encrypted: true,
          encryption: {
            algorithm: 'aes-256-gcm',
            iv: encryptedPayload.iv,
            tag: encryptedPayload.tag,
          },
          format: ext,
          originalSize: imageFile.size || buffer.length,
        },
      },
    })

    const analysisData = {
      summary: analysisPayload?.summary ?? null,
      possibleCauses: Array.isArray(analysisPayload?.possibleCauses)
        ? analysisPayload.possibleCauses
        : [],
      redFlags: Array.isArray(analysisPayload?.redFlags) ? analysisPayload.redFlags : [],
      nextSteps: Array.isArray(analysisPayload?.nextSteps) ? analysisPayload.nextSteps : [],
      disclaimer: analysisPayload?.disclaimer ?? null,
    }

    const saved = await prisma.medicalImageAnalysis.create({
      data: {
        userId: user.id,
        imageFileId: fileRecord.id,
        summary: analysisPayload?.summary ?? null,
        analysisText: analysisPayload?.analysisText ?? null,
        analysisData,
      },
    })

    return NextResponse.json({
      success: true,
      historyItem: {
        id: saved.id,
        summary: saved.summary,
        analysisText: saved.analysisText,
        analysisData: saved.analysisData,
        createdAt: saved.createdAt,
        imageUrl: `/api/medical-images/file?token=${encodeURIComponent(
          createSignedFileToken({ fileId: fileRecord.id, userId: user.id, usage: 'MEDICAL_IMAGE' })
        )}`,
      },
    })
  } catch (error) {
    console.error('Error saving health image notes history:', error)
    return NextResponse.json(
      {
        error: 'Failed to save health image notes history',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    )
  }
}

export async function DELETE(request: NextRequest) {
