import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { ensureMedicationCatalogSchema } from '@/lib/medication-catalog-db'

export const dynamic = 'force-dynamic'

const normalizeSearchText = (value: string) => {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
}

const isPlaceholderName = (value: string) => {
  const safe = String(value || '').trim().toLowerCase()
  return new Set([
    'analyzing...',
    'medication added',
    'unknown medication',
    'analysis error',
  ]).has(safe)
}

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const query = String(searchParams.get('q') || '').trim()
    if (query.length < 2) {
      return NextResponse.json({ results: [] }, { headers: { 'Cache-Control': 'no-store' } })
    }

    await ensureMedicationCatalogSchema()

    const tokens = normalizeSearchText(query).split(' ').filter(Boolean).slice(0, 6)
    if (tokens.length === 0) {
      return NextResponse.json({ results: [] }, { headers: { 'Cache-Control': 'no-store' } })
    }

    // Build SQL query with token filters
    const tokenConditions = tokens.map((token, idx) => 
      `("fullName" ILIKE $${idx * 3 + 1} OR "brand" ILIKE $${idx * 3 + 2} OR "product" ILIKE $${idx * 3 + 3})`
    ).join(' OR ')

    const params: any[] = []
    tokens.forEach(token => {
      const pattern = `%${token}%`
      params.push(pattern, pattern, pattern)
    })

    const rows = await prisma.$queryRawUnsafe<Array<{
      fullName: string
      brand: string | null
      product: string | null
      updatedAt: Date
    }>>(
      `SELECT DISTINCT ON ("fullName") "fullName", "brand", "product", "updatedAt"
       FROM "MedicationCatalog"
       WHERE ${tokenConditions}
       ORDER BY "fullName", "updatedAt" DESC
       LIMIT 60`,
      ...params
    )

    const scored = rows
      .map((row) => {
        const label = String(row.fullName || '').trim()
        if (!label || isPlaceholderName(label)) return null
        const haystack = normalizeSearchText(
          `${row.fullName || ''} ${row.brand || ''} ${row.product || ''}`,
        )
        const score = tokens.reduce((acc, token) => (haystack.includes(token) ? acc + 1 : acc), 0)
        return { label, score, updatedAt: row.updatedAt }
      })
      .filter(Boolean) as { label: string; score: number; updatedAt: Date }[]

    scored.sort((a, b) => {
      if (b.score !== a.score) return b.score - a.score
      return b.updatedAt.getTime() - a.updatedAt.getTime()
    })

    const results = scored.slice(0, 12).map((item) => ({
      name: item.label,
      source: 'catalog',
    }))

    return NextResponse.json({ results }, { headers: { 'Cache-Control': 'no-store' } })
  } catch (error) {
    console.error('Medication catalog search failed:', error)
    return NextResponse.json({ results: [] }, { headers: { 'Cache-Control': 'no-store' } })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { searchMedicationReferenceNames } from '@/lib/health-intake-review-match'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

type CacheEntry = { ts: number; data: any }
const cache = new Map<string, CacheEntry>()
const CACHE_TTL_MS = 5 * 60 * 1000

const getCached = (key: string) => {
  const entry = cache.get(key)
  if (!entry) return null
  if (Date.now() - entry.ts > CACHE_TTL_MS) {
    cache.delete(key)
    return null
  }
  return entry.data
}

const setCached = (key: string, data: any) => {
  cache.set(key, { ts: Date.now(), data })
}

const safeName = (value: any) => String(value || '').trim()

const dedupeNames = (items: { name: string; source: string }[]) => {
  const seen = new Set<string>()
  const result: { name: string; source: string }[] = []
  items.forEach((item) => {
    const key = safeName(item.name).toLowerCase()
    if (seen.has(key)) return
    if (!key) return
    seen.add(key)
    result.push(item)
  })
  return result
}

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const query = String(searchParams.get('q') || '').trim()
    if (query.length < 2) {
      return NextResponse.json({ results: [] }, { headers: { 'Cache-Control': 'no-store' } })
    }

    const cacheKey = `med:${query.toLowerCase()}`
    const cached = getCached(cacheKey)
    if (cached) return NextResponse.json(cached, { headers: { 'Cache-Control': 'no-store' } })

    const results = await searchMedicationReferenceNames(query, 10)

    const payload = { results: dedupeNames(results).slice(0, 10) }
    console.log(`Medication search for "${query}": returning ${payload.results.length} results`)
    setCached(cacheKey, payload)
    return NextResponse.json(payload, { headers: { 'Cache-Control': 'no-store' } })
  } catch (error) {
    console.error('Medication search failed:', error)
    return NextResponse.json({ results: [] }, { headers: { 'Cache-Control': 'no-store' } })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { ensureMoodTables } from '@/app/api/mood/_db'

export const dynamic = 'force-dynamic'

function clampInt(value: unknown, min: number, max: number): number | null {
  if (value === null || value === undefined) return null
  const n = Number(value)
  if (!Number.isFinite(n)) return null
  return Math.max(min, Math.min(max, Math.round(n)))
}

function asLocalDate(value: string | null): string | null {
  if (!value) return null
  const trimmed = value.trim()
  if (!/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) return null
  return trimmed
}

function dateFromLocalDate(localDate: string): Date {
  // Date-only columns in Postgres + Prisma map cleanly from a Date instance at UTC midnight.
  return new Date(`${localDate}T00:00:00.000Z`)
}

export async function GET(req: NextRequest) {
  const session = await getServerSession(authOptions)
  if (!session?.user?.email) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  const user = await prisma.user.findUnique({ where: { email: session.user.email } })
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  const { searchParams } = new URL(req.url)
  const localDate = asLocalDate(searchParams.get('localDate')) ?? new Date().toISOString().slice(0, 10)

  try {
    await ensureMoodTables().catch(() => {})

    const mealsTodayCount = await prisma.foodLog.count({
      where: { userId: user.id, localDate },
    }).catch(() => 0)

    const lastMeal = await prisma.foodLog.findFirst({
      where: { userId: user.id },
      orderBy: { createdAt: 'desc' },
      select: { id: true, name: true, createdAt: true, meal: true },
    }).catch(() => null)

    const supplementsCount = await prisma.supplement.count({
      where: { userId: user.id },
    }).catch(() => 0)

    const medicationsCount = await prisma.medication.count({
      where: { userId: user.id },
    }).catch(() => 0)

    const exerciseToday = await prisma.exerciseEntry.aggregate({
      where: { userId: user.id, localDate },
      _sum: { durationMinutes: true, calories: true },
    }).catch(() => ({ _sum: { durationMinutes: null, calories: null } }))

    const stepsToday = await prisma.fitbitData.findUnique({
      where: { userId_date_dataType: { userId: user.id, date: dateFromLocalDate(localDate), dataType: 'steps' } },
      select: { value: true },
    }).catch(() => null)

    const sleepRecent = await prisma.fitbitData.findFirst({
      where: {
        userId: user.id,
        dataType: 'sleep',
        date: { gte: dateFromLocalDate(new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10)) },
      },
      orderBy: { date: 'desc' },
      select: { date: true, value: true },
    }).catch(() => null)

    const stepsCount = (() => {
      const raw = (stepsToday as any)?.value
      if (!raw) return null
      if (typeof raw === 'number') return clampInt(raw, 0, 500_000)
      if (typeof raw === 'object' && raw && 'steps' in raw) return clampInt((raw as any).steps, 0, 500_000)
      return null
    })()

    const sleepMinutes = (() => {
      const raw = (sleepRecent as any)?.value
      if (!raw) return null
      if (typeof raw === 'number') return clampInt(raw, 0, 24 * 60)
      if (typeof raw === 'object' && raw) {
        const maybe = (raw as any).minutes ?? (raw as any).totalMinutesAsleep ?? (raw as any).sleepMinutes
        return clampInt(maybe, 0, 24 * 60)
      }
      return null
    })()

    return NextResponse.json({
      localDate,
      meals: {
        todayCount: mealsTodayCount,
        last: lastMeal
          ? {
              id: lastMeal.id,
              name: lastMeal.name,
              meal: lastMeal.meal,
              at: lastMeal.createdAt,
            }
          : null,
      },
      supplements: { count: supplementsCount },
      medications: { count: medicationsCount },
      activity: {
        stepsToday: stepsCount,
        exerciseMinutesToday: clampInt(exerciseToday._sum.durationMinutes, 0, 24 * 60),
        exerciseCaloriesToday: clampInt(exerciseToday._sum.calories, 0, 50_000),
      },
      sleep: {
        minutes: sleepMinutes,
        date: sleepRecent?.date ?? null,
      },
    })
  } catch (e) {
    console.error('mood context error', e)
    return NextResponse.json({ error: 'Failed to load context' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import webpush from 'web-push'
import { ensureMoodTables } from '@/app/api/mood/_db'
import { scheduleAllMoodReminders, scheduleMoodReminderWithQStash } from '@/lib/qstash'
import { dedupeSubscriptions, normalizeSubscriptionList, removeSubscriptionsByEndpoint, sendToSubscriptions } from '@/lib/push-subscriptions'
import { isSchedulerAuthorized } from '@/lib/scheduler-auth'
import { createInboxNotification } from '@/lib/notification-inbox'
import { isSubscriptionActive } from '@/lib/subscription-utils'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

type DispatchPayload = {
  userId: string
  reminderTime: string
  timezone: string
}

function safeTimezone(input: string) {
  const tz = (input || 'UTC').trim()
  if (!tz) return 'UTC'
  try {
    new Intl.DateTimeFormat('en-GB', { timeZone: tz })
    return tz
  } catch {
    return 'UTC'
  }
}

function localDateForTimezone(now: Date, timezone: string) {
  const dateParts = new Intl.DateTimeFormat('en-GB', {
    timeZone: timezone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(now)
  const year = dateParts.find((p) => p.type === 'year')?.value || '1970'
  const month = dateParts.find((p) => p.type === 'month')?.value || '01'
  const day = dateParts.find((p) => p.type === 'day')?.value || '01'
  return `${year}-${month}-${day}`
}

export async function POST(req: NextRequest) {
  try {
    if (!isSchedulerAuthorized(req)) {
      return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
    }

    const body = (await req.json().catch(() => ({}))) as Partial<DispatchPayload>
    const userId = String(body.userId || '')
    const reminderTime = String(body.reminderTime || '')
    const timezone = String(body.timezone || '')
    if (!userId || !reminderTime || !timezone) {
      return NextResponse.json({ error: 'invalid_payload' }, { status: 400 })
    }

    await ensureMoodTables()

    const subscriptionRows: Array<{ subscription: any }> = await prisma.$queryRawUnsafe(
      `SELECT subscription FROM PushSubscriptions WHERE userId = $1`,
      userId,
    )
    if (!subscriptionRows.length) {
      return NextResponse.json({ error: 'no_subscription' }, { status: 400 })
    }
    const subscriptions = dedupeSubscriptions(normalizeSubscriptionList(subscriptionRows[0].subscription))
    if (!subscriptions.length) {
      return NextResponse.json({ error: 'no_subscription' }, { status: 400 })
    }

    const settingsRows: Array<{
      enabled: boolean
      time1: string
      time2: string
      time3: string
      time4: string | null
      timezone: string
      frequency: number | null
    }> = await prisma.$queryRawUnsafe(
      `SELECT enabled, time1, time2, time3, time4, timezone, frequency FROM MoodReminderSettings WHERE userId = $1`,
      userId,
    )
    const settings = settingsRows[0]
    const user = await prisma.user.findUnique({
      where: { id: userId },
      include: { subscription: true, creditTopUps: true },
    })
    const paidCheckNow = new Date()
    const hasSubscription = isSubscriptionActive(user?.subscription, paidCheckNow)
    const hasPurchasedCredits = (user?.creditTopUps || []).some(
      (topUp: any) => topUp.expiresAt > paidCheckNow && (topUp.amountCents - topUp.usedCents) > 0
    )
    const maxFrequency = (hasSubscription || hasPurchasedCredits) ? 4 : 1
    const resolvedFrequency = Math.max(1, Math.min(maxFrequency, settings?.frequency ?? 1))
    const activeTimes: string[] = []
    if (resolvedFrequency >= 1 && settings?.time1) activeTimes.push(settings.time1)
    if (resolvedFrequency >= 2 && settings?.time2) activeTimes.push(settings.time2)
    if (resolvedFrequency >= 3 && settings?.time3) activeTimes.push(settings.time3)
    if (resolvedFrequency >= 4 && settings?.time4) activeTimes.push(settings.time4)
    const timezoneToUse = settings?.timezone || timezone

    const remindersEnabled = settings?.enabled ?? false
    const reminderStillActive = settings ? activeTimes.includes(reminderTime) : false
    const timezoneStillMatches = settings ? settings.timezone === timezone : false

    if (!remindersEnabled || !reminderStillActive || !timezoneStillMatches) {
      if (settings && settings.enabled) {
        const rescheduleTimezone = safeTimezone(settings.timezone)
        try {
          await scheduleAllMoodReminders(userId, {
            time1: settings.time1,
            time2: settings.time2,
            time3: settings.time3,
            time4: settings.time4,
            timezone: rescheduleTimezone,
            frequency: resolvedFrequency,
          })
        } catch (err) {
          console.error('[MOOD_DISPATCH] Failed to reschedule active reminders after stale job', err)
        }
      }
      return NextResponse.json({
        skipped: 'stale_schedule',
        reason: remindersEnabled ? 'time_or_timezone_changed' : 'disabled',
      })
    }

    const publicKey = process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY || ''
    const privateKey = process.env.VAPID_PRIVATE_KEY || ''
    if (!publicKey || !privateKey) {
      return NextResponse.json({ error: 'vapid_not_configured' }, { status: 500 })
    }
    webpush.setVapidDetails('mailto:support@helfi.ai', publicKey, privateKey)

    const now = new Date()
    const effectiveTimezone = safeTimezone(timezoneToUse)
    const localDate = localDateForTimezone(now, effectiveTimezone)

    const claim: Array<{ userId: string }> = await prisma.$queryRawUnsafe(
      `INSERT INTO MoodReminderDeliveryLog (userId, reminderTime, sentDate, sentAt)
       VALUES ($1, $2, $3::date, NOW())
       ON CONFLICT (userId, reminderTime, sentDate) DO NOTHING
       RETURNING userId`,
      userId,
      reminderTime,
      localDate,
    )

    if (!claim.length) {
      return NextResponse.json({ skipped: 'already_sent' })
    }

    const payload = JSON.stringify({
      title: 'Quick mood check‑in',
      body: 'How are you feeling right now? It takes 10 seconds.',
      url: '/mood/quick',
    })
    const { sent, errors, goneEndpoints } = await sendToSubscriptions(subscriptions, (sub) =>
      webpush.sendNotification(sub, payload)
    )
    if (goneEndpoints.length) {
      const remaining = removeSubscriptionsByEndpoint(subscriptions, goneEndpoints)
      await prisma.$executeRawUnsafe(
        `UPDATE PushSubscriptions SET subscription = $2::jsonb, updatedAt = NOW() WHERE userId = $1`,
        userId,
        JSON.stringify(remaining)
      )
    }
    if (!sent) {
      await prisma.$executeRawUnsafe(
        `DELETE FROM MoodReminderDeliveryLog WHERE userId = $1 AND reminderTime = $2 AND sentDate = $3::date`,
        userId,
        reminderTime,
        localDate,
      ).catch(() => {})
      return NextResponse.json({ error: 'push_failed', details: errors }, { status: 500 })
    }

    await createInboxNotification({
      userId,
      title: 'Quick mood check-in',
      body: 'How are you feeling right now? It takes 10 seconds.',
      url: '/mood/quick',
      type: 'mood_reminder',
      source: 'push',
      eventKey: `mood:${localDate}:${reminderTime}`,
    }).catch(() => {})

    const nextSchedule = await scheduleMoodReminderWithQStash(userId, reminderTime, effectiveTimezone).catch(
      (error) => {
        console.error('[MOOD_DISPATCH] Failed to schedule next reminder via QStash', error)
        return { scheduled: false, reason: 'exception' }
      },
    )
    if (!nextSchedule?.scheduled) {
      console.error('[MOOD_DISPATCH] QStash scheduling returned failure', {
        userId,
        reminderTime,
        timezone: effectiveTimezone,
        reason: nextSchedule?.reason,
      })
    }

    return NextResponse.json({ ok: true })
  } catch (e: any) {
    console.error('[MOOD_DISPATCH] error', e?.stack || e)
    return NextResponse.json({ error: 'dispatch_error', message: e?.message || String(e) }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import crypto from 'crypto'
import { ensureMoodTables } from '@/app/api/mood/_db'
import { deleteNotificationsByType, deleteSmartCoachNotificationsByCategories } from '@/lib/notification-inbox'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'

export const dynamic = 'force-dynamic'

const MOOD_MIN = 1
const MOOD_MAX = 7

async function getMoodUser(req: NextRequest) {
  const session = await getServerSession(authOptions)
  if (session?.user?.email) {
    return prisma.user.findUnique({ where: { email: session.user.email } })
  }
  const nativeUserId = await getUserIdFromNativeAuth(req)
  if (nativeUserId) {
    return prisma.user.findUnique({ where: { id: nativeUserId } })
  }
  return null
}

function clampInt(value: unknown, min: number, max: number): number | null {
  if (value === null || value === undefined) return null
  const n = Number(value)
  if (!Number.isFinite(n)) return null
  return Math.max(min, Math.min(max, Math.round(n)))
}

function normalizeTags(value: unknown): string[] {
  if (!Array.isArray(value)) return []
  const uniq = new Set<string>()
  for (const raw of value) {
    const t = String(raw ?? '').trim()
    if (!t) continue
    const cleaned = t.slice(0, 24)
    uniq.add(cleaned)
    if (uniq.size >= 12) break
  }
  return Array.from(uniq)
}

function normalizeNote(value: unknown): string {
  const note = String(value ?? '').trim()
  return note.length > 600 ? note.slice(0, 600) : note
}

function asLocalDate(value: unknown): string | null {
  const s = String(value ?? '').trim()
  if (!s) return null
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return null
  return s
}

function dateFromLocalDate(localDate: string): Date {
  return new Date(`${localDate}T00:00:00.000Z`)
}

function pickContextFields(value: any) {
  const energyLevel = clampInt(value?.energyLevel, 1, 5)
  const sleepQuality = clampInt(value?.sleepQuality, 1, 5)
  const nutrition = clampInt(value?.nutrition, 1, 5)
  const supplements = clampInt(value?.supplements, 1, 5)
  const medicationEffect = clampInt(value?.medicationEffect, 1, 5)
  const physicalActivity = clampInt(value?.physicalActivity, 1, 5)
  const localHour = clampInt(value?.localHour, 0, 23)
  const intensityPercent = clampInt(value?.intensityPercent, 0, 100)
  const feelings = normalizeTags(value?.feelings)
  return {
    ...(energyLevel == null ? {} : { energyLevel }),
    ...(sleepQuality == null ? {} : { sleepQuality }),
    ...(nutrition == null ? {} : { nutrition }),
    ...(supplements == null ? {} : { supplements }),
    ...(medicationEffect == null ? {} : { medicationEffect }),
    ...(physicalActivity == null ? {} : { physicalActivity }),
    ...(localHour == null ? {} : { localHour }),
    ...(intensityPercent == null ? {} : { intensityPercent }),
    ...(feelings.length > 0 ? { feelings } : {}),
  }
}

async function getPassiveContext(userId: string, localDate: string) {
  const mealsTodayCount = await prisma.foodLog.count({
    where: { userId, localDate },
  }).catch(() => 0)

  const lastMeal = await prisma.foodLog.findFirst({
    where: { userId },
    orderBy: { createdAt: 'desc' },
    select: { id: true, name: true, createdAt: true, meal: true },
  }).catch(() => null)

  const supplementsCount = await prisma.supplement.count({
    where: { userId },
  }).catch(() => 0)

  const medicationsCount = await prisma.medication.count({
    where: { userId },
  }).catch(() => 0)

  const exerciseToday = await prisma.exerciseEntry.aggregate({
    where: { userId, localDate },
    _sum: { durationMinutes: true, calories: true },
  }).catch(() => ({ _sum: { durationMinutes: null, calories: null } }))

  const stepsToday = await prisma.fitbitData.findUnique({
    where: { userId_date_dataType: { userId, date: dateFromLocalDate(localDate), dataType: 'steps' } },
    select: { value: true },
  }).catch(() => null)

  const sleepRecent = await prisma.fitbitData.findFirst({
    where: {
      userId,
      dataType: 'sleep',
      date: { gte: dateFromLocalDate(new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10)) },
    },
    orderBy: { date: 'desc' },
    select: { date: true, value: true },
  }).catch(() => null)

  const stepsCount = (() => {
    const raw = (stepsToday as any)?.value
    if (!raw) return null
    if (typeof raw === 'number') return clampInt(raw, 0, 500_000)
    if (typeof raw === 'object' && raw && 'steps' in raw) return clampInt((raw as any).steps, 0, 500_000)
    return null
  })()

  const sleepMinutes = (() => {
    const raw = (sleepRecent as any)?.value
    if (!raw) return null
    if (typeof raw === 'number') return clampInt(raw, 0, 24 * 60)
    if (typeof raw === 'object' && raw) {
      const maybe = (raw as any).minutes ?? (raw as any).totalMinutesAsleep ?? (raw as any).sleepMinutes
      return clampInt(maybe, 0, 24 * 60)
    }
    return null
  })()

  return {
    mealsTodayCount,
    lastMeal: lastMeal
      ? { id: lastMeal.id, name: lastMeal.name, meal: lastMeal.meal, at: lastMeal.createdAt }
      : null,
    supplementsCount,
    medicationsCount,
    stepsToday: stepsCount,
    exerciseMinutesToday: clampInt(exerciseToday._sum.durationMinutes, 0, 24 * 60),
    exerciseCaloriesToday: clampInt(exerciseToday._sum.calories, 0, 50_000),
    sleepMinutes,
    sleepDate: sleepRecent?.date ?? null,
  }
}

export async function GET(req: NextRequest) {
  const user = await getMoodUser(req)
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  const { searchParams } = new URL(req.url)
  const start = searchParams.get('start')
  const end = searchParams.get('end')
  const period = (searchParams.get('period') || '').toLowerCase()

  const today = new Date().toISOString().slice(0, 10)
  let startLocalDate = asLocalDate(start) ?? null
  let endLocalDate = asLocalDate(end) ?? null

  if (!startLocalDate || !endLocalDate) {
    if (period === 'today') {
      startLocalDate = today
      endLocalDate = today
    } else if (period === 'week') {
      const d = new Date()
      d.setDate(d.getDate() - 6)
      startLocalDate = d.toISOString().slice(0, 10)
      endLocalDate = today
    } else if (period === 'month') {
      const d = new Date()
      d.setDate(d.getDate() - 29)
      startLocalDate = d.toISOString().slice(0, 10)
      endLocalDate = today
    } else {
      startLocalDate = '1970-01-01'
      endLocalDate = today
    }
  }

  try {
    await ensureMoodTables()
    const rows: any[] = await prisma.$queryRawUnsafe(
      `SELECT id, localDate AS "localDate", timestamp, mood, tags, note, context
       FROM MoodEntries
       WHERE userId = $1 AND localDate BETWEEN $2 AND $3
       ORDER BY timestamp DESC`,
      user.id,
      startLocalDate,
      endLocalDate,
    )
    return NextResponse.json({ range: { start: startLocalDate, end: endLocalDate }, entries: rows })
  } catch (e) {
    console.error('mood entries get error', e)
    return NextResponse.json({ error: 'Failed to load entries' }, { status: 500 })
  }
}

export async function POST(req: NextRequest) {
  const user = await getMoodUser(req)
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  const body = await req.json().catch(() => ({} as any))
  const mood = clampInt(body?.mood, MOOD_MIN, MOOD_MAX)
  if (mood == null) return NextResponse.json({ error: 'Mood is required' }, { status: 400 })

  const localDate = asLocalDate(body?.localDate) ?? new Date().toISOString().slice(0, 10)
  const tags = normalizeTags(body?.tags)
  const note = normalizeNote(body?.note)

  const id = crypto.randomUUID()

  try {
    await ensureMoodTables()

    const passive = await getPassiveContext(user.id, localDate)
    const context = {
      ...passive,
      ...pickContextFields(body?.context),
    }

    await prisma.$queryRawUnsafe(
      `INSERT INTO MoodEntries (id, userId, localDate, mood, tags, note, context)
       VALUES ($1, $2, $3, $4, $5::jsonb, $6, $7::jsonb)`,
      id,
      user.id,
      localDate,
      mood,
      JSON.stringify(tags),
      note,
      JSON.stringify(context),
    )

    await deleteNotificationsByType(user.id, ['mood_reminder']).catch(() => {})
    await deleteSmartCoachNotificationsByCategories(user.id, ['mood']).catch(() => {})

    return NextResponse.json({ success: true, id })
  } catch (e) {
    console.error('mood entry save error', e)
    return NextResponse.json({ error: 'Failed to save entry' }, { status: 500 })
  }
}

export async function PATCH(req: NextRequest) {
  const user = await getMoodUser(req)
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  const body = await req.json().catch(() => ({} as any))
  const id = String(body?.id || '').trim()
  const mood = clampInt(body?.mood, MOOD_MIN, MOOD_MAX)
  if (!id || mood == null) return NextResponse.json({ error: 'Entry and mood are required' }, { status: 400 })

  try {
    await ensureMoodTables()
    const updated = await prisma.$executeRawUnsafe(
      `UPDATE MoodEntries
       SET mood = $1, tags = $2::jsonb, note = $3
       WHERE id = $4 AND userId = $5`,
      mood,
      JSON.stringify(normalizeTags(body?.tags)),
      normalizeNote(body?.note),
      id,
      user.id,
    )
    if (!updated) return NextResponse.json({ error: 'Entry not found' }, { status: 404 })
    return NextResponse.json({ success: true })
  } catch (e) {
    console.error('mood entry update error', e)
    return NextResponse.json({ error: 'Failed to update entry' }, { status: 500 })
  }
}

export async function DELETE(req: NextRequest) {
  const user = await getMoodUser(req)
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  const body = await req.json().catch(() => ({} as any))
  const id = String(body?.id || '').trim()
  if (!id) return NextResponse.json({ error: 'Entry is required' }, { status: 400 })

  try {
    await ensureMoodTables()
    const deleted = await prisma.$executeRawUnsafe(
      `DELETE FROM MoodEntries WHERE id = $1 AND userId = $2`,
      id,
      user.id,
    )
    if (!deleted) return NextResponse.json({ error: 'Entry not found' }, { status: 404 })
    return NextResponse.json({ success: true })
  } catch (e) {
    console.error('mood entry delete error', e)
    return NextResponse.json({ error: 'Failed to delete entry' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { ensureMoodTables } from '@/app/api/mood/_db'

export const dynamic = 'force-dynamic'

type Insight = {
  id: string
  title: string
  detail: string
  confidence: 'low' | 'medium' | 'high'
  sampleSize: number
}

type MoodEntryRow = {
  localDate: string
  timestamp: string
  mood: number
  context: any
}

function pearson(x: number[], y: number[]): number | null {
  const n = Math.min(x.length, y.length)
  if (n < 3) return null
  let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0, sumYY = 0, k = 0
  for (let i = 0; i < n; i++) {
    const xi = x[i]
    const yi = y[i]
    if (xi == null || yi == null || isNaN(xi) || isNaN(yi)) continue
    k++
    sumX += xi
    sumY += yi
    sumXY += xi * yi
    sumXX += xi * xi
    sumYY += yi * yi
  }
  if (k < 3) return null
  const cov = sumXY - (sumX * sumY) / k
  const varX = sumXX - (sumX * sumX) / k
  const varY = sumYY - (sumY * sumY) / k
  if (varX <= 0 || varY <= 0) return null
  return cov / Math.sqrt(varX * varY)
}

function confidenceFromSample(sampleSize: number): 'low' | 'medium' | 'high' {
  if (sampleSize >= 21) return 'high'
  if (sampleSize >= 7) return 'medium'
  return 'low'
}

function strengthLabel(r: number | null): string {
  if (r == null) return 'No clear pattern yet'
  const a = Math.abs(r)
  if (a >= 0.7) return 'a stronger tendency'
  if (a >= 0.4) return 'a moderate tendency'
  if (a >= 0.2) return 'a mild tendency'
  return 'a very small tendency'
}

function toFiniteNumber(value: unknown): number | null {
  const n = Number(value)
  return Number.isFinite(n) ? n : null
}

function correlationForEntryContext(entries: MoodEntryRow[], key: string) {
  const x: number[] = []
  const y: number[] = []
  for (const entry of entries) {
    const raw = (entry as any)?.context?.[key]
    const value = toFiniteNumber(raw)
    const mood = toFiniteNumber(entry.mood)
    if (value == null || mood == null) continue
    x.push(value)
    y.push(mood)
  }
  return {
    r: pearson(x, y),
    sampleSize: Math.min(x.length, y.length),
  }
}

export async function GET(req: NextRequest) {
  const session = await getServerSession(authOptions)
  if (!session?.user?.email) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  const user = await prisma.user.findUnique({ where: { email: session.user.email } })
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  const { searchParams } = new URL(req.url)
  const period = (searchParams.get('period') || 'month').toLowerCase()

  const end = new Date().toISOString().slice(0, 10)
  const start = (() => {
    const d = new Date()
    if (period === 'week') d.setDate(d.getDate() - 6)
    else if (period === 'today') d.setDate(d.getDate() - 0)
    else d.setDate(d.getDate() - 29)
    return d.toISOString().slice(0, 10)
  })()

  try {
    await ensureMoodTables()
    const entries: MoodEntryRow[] =
      (await prisma.$queryRawUnsafe(
        `SELECT localDate AS "localDate", timestamp, mood, context
         FROM MoodEntries
         WHERE userId = $1 AND localDate BETWEEN $2 AND $3
         ORDER BY timestamp ASC`,
        user.id,
        start,
        end,
      )) as any

    // Time-of-day buckets (local time is not available; approximate using timestamp hour)
    const buckets = new Map<'morning' | 'afternoon' | 'evening' | 'night', number[]>()
    const bucketOfHour = (h: number) => {
      if (h >= 5 && h <= 11) return 'morning' as const
      if (h >= 12 && h <= 17) return 'afternoon' as const
      if (h >= 18 && h <= 23) return 'evening' as const
      return 'night' as const
    }
    for (const e of entries) {
      const ctxHourRaw = (e as any)?.context?.localHour
      const ctxHour = Number(ctxHourRaw)
      const hour = Number.isFinite(ctxHour) ? Math.max(0, Math.min(23, Math.round(ctxHour))) : new Date(e.timestamp).getHours()
      const b = bucketOfHour(hour)
      if (!buckets.has(b)) buckets.set(b, [])
      buckets.get(b)!.push(Number(e.mood))
    }
    const bucketAverages = Array.from(buckets.entries()).map(([bucket, arr]) => ({
      bucket,
      avg: arr.reduce((a, b) => a + b, 0) / arr.length,
      n: arr.length,
    }))
    bucketAverages.sort((a, b) => b.avg - a.avg)
    const bestBucket = bucketAverages[0]

    // Per-day mood average
    const byDay = new Map<string, number[]>()
    for (const e of entries) {
      if (!byDay.has(e.localDate)) byDay.set(e.localDate, [])
      byDay.get(e.localDate)!.push(Number(e.mood))
    }
    const dayKeys = Array.from(byDay.keys()).sort()
    const moodDailyAvg = dayKeys.map((d) => {
      const arr = byDay.get(d) || []
      const avg = arr.reduce((a, b) => a + b, 0) / Math.max(1, arr.length)
      return { date: d, avg }
    })

    // Join with steps/sleep and meals count
    const dates = dayKeys
    const dateObjects = dates.map((d) => new Date(`${d}T00:00:00.000Z`))
    const fitbit = await prisma.fitbitData.findMany({
      where: { userId: user.id, date: { in: dateObjects }, dataType: { in: ['steps', 'sleep'] } },
      select: { date: true, dataType: true, value: true },
    }).catch(() => [])

    const mealsCounts = await prisma.foodLog.groupBy({
      by: ['localDate'],
      where: { userId: user.id, localDate: { in: dates } },
      _count: { _all: true },
    }).catch(() => [])

    const stepsByDate = new Map<string, number>()
    const sleepByDate = new Map<string, number>()
    for (const row of fitbit as any[]) {
      const d = new Date(row.date).toISOString().slice(0, 10)
      if (row.dataType === 'steps') {
        const v = (row.value?.steps ?? row.value ?? null) as any
        const n = Number(v)
        if (Number.isFinite(n)) stepsByDate.set(d, n)
      }
      if (row.dataType === 'sleep') {
        const v = (row.value?.minutes ?? row.value?.totalMinutesAsleep ?? row.value?.sleepMinutes ?? row.value ?? null) as any
        const n = Number(v)
        if (Number.isFinite(n)) sleepByDate.set(d, n)
      }
    }

    const mealsByDate = new Map<string, number>()
    for (const row of mealsCounts as any[]) {
      mealsByDate.set(String(row.localDate), Number(row._count?._all ?? 0))
    }

    const xMood: number[] = []
    const xSleep: number[] = []
    const xSteps: number[] = []
    const xMeals: number[] = []
    for (const day of moodDailyAvg) {
      const sleep = sleepByDate.get(day.date)
      const steps = stepsByDate.get(day.date)
      const meals = mealsByDate.get(day.date)
      xMood.push(day.avg)
      xSleep.push(sleep ?? NaN)
      xSteps.push(steps ?? NaN)
      xMeals.push(meals ?? NaN)
    }

    const sleepMoodR = pearson(xSleep, xMood)
    const stepsMoodR = pearson(xSteps, xMood)
    const mealsMoodR = pearson(xMeals, xMood)

    const sampleSize = moodDailyAvg.length
    const conf = confidenceFromSample(sampleSize)
    const medicationsTracked = await prisma.medication.count({
      where: { userId: user.id },
    }).catch(() => 0)

    const insights: { sleep: Insight[]; nutrition: Insight[]; supplements: Insight[]; activity: Insight[]; stress: Insight[]; medication: Insight[] } =
      { sleep: [], nutrition: [], supplements: [], activity: [], stress: [], medication: [] }

    if (bestBucket && bestBucket.n >= 3) {
      insights.stress.push({
        id: 'time-of-day',
        title: `You tend to feel best in the ${bestBucket.bucket}`,
        detail: `Based on ${bestBucket.n} check-ins, your average mood is highest in the ${bestBucket.bucket}.`,
        confidence: confidenceFromSample(bestBucket.n),
        sampleSize: bestBucket.n,
      })
    }

    insights.sleep.push({
      id: 'sleep-vs-mood',
      title: 'Sleep and mood show a tendency together',
      detail: `Across ${sampleSize} day(s), sleep hours and mood show ${strengthLabel(sleepMoodR)}. This is a pattern hint, not a rule.`,
      confidence: conf,
      sampleSize,
    })

    const sleepQuality = correlationForEntryContext(entries, 'sleepQuality')
    if (sleepQuality.sampleSize >= 4) {
      insights.sleep.push({
        id: 'sleep-quality-vs-mood',
        title: 'Better sleep quality may support better mood',
        detail: `From ${sleepQuality.sampleSize} check-ins, self-rated sleep quality and mood show ${strengthLabel(sleepQuality.r)}.`,
        confidence: confidenceFromSample(sleepQuality.sampleSize),
        sampleSize: sleepQuality.sampleSize,
      })
    }

    insights.activity.push({
      id: 'steps-vs-mood',
      title: 'Activity and mood may move together',
      detail: `Across ${sampleSize} day(s), daily steps and mood show ${strengthLabel(stepsMoodR)}. Consider it a directional signal.`,
      confidence: conf,
      sampleSize,
    })

    const activityQuality = correlationForEntryContext(entries, 'physicalActivity')
    if (activityQuality.sampleSize >= 4) {
      insights.activity.push({
        id: 'activity-rating-vs-mood',
        title: 'Your activity rating has a mood pattern',
        detail: `From ${activityQuality.sampleSize} check-ins, your activity score and mood show ${strengthLabel(activityQuality.r)}.`,
        confidence: confidenceFromSample(activityQuality.sampleSize),
        sampleSize: activityQuality.sampleSize,
      })
    }

    insights.nutrition.push({
      id: 'meals-vs-mood',
      title: 'Eating patterns may relate to mood',
      detail: `Across ${sampleSize} day(s), days with more logged meals show ${strengthLabel(mealsMoodR)} with mood. This is a tendency, not a claim.`,
      confidence: conf,
      sampleSize,
    })

    const nutritionQuality = correlationForEntryContext(entries, 'nutrition')
    if (nutritionQuality.sampleSize >= 4) {
      insights.nutrition.push({
        id: 'nutrition-rating-vs-mood',
        title: 'Nutrition quality and mood may align',
        detail: `From ${nutritionQuality.sampleSize} check-ins, your nutrition score and mood show ${strengthLabel(nutritionQuality.r)}.`,
        confidence: confidenceFromSample(nutritionQuality.sampleSize),
        sampleSize: nutritionQuality.sampleSize,
      })
    }

    const supplementsImpact = correlationForEntryContext(entries, 'supplements')
    if (supplementsImpact.sampleSize >= 4) {
      insights.supplements.push({
        id: 'supplements-vs-mood',
        title: 'Supplement impact may connect with mood',
        detail: `From ${supplementsImpact.sampleSize} check-ins, supplement impact rating and mood show ${strengthLabel(supplementsImpact.r)}.`,
        confidence: confidenceFromSample(supplementsImpact.sampleSize),
        sampleSize: supplementsImpact.sampleSize,
      })
    } else {
      insights.supplements.push({
        id: 'supplements-more-data',
        title: 'Log supplement impact to unlock a clearer pattern',
        detail: `You currently have limited supplement-impact check-ins. Add this score for a few more days to get a stronger trend.`,
        confidence: 'low',
        sampleSize: supplementsImpact.sampleSize,
      })
    }

    const medicationImpact = correlationForEntryContext(entries, 'medicationEffect')
    if (medicationImpact.sampleSize >= 4) {
      insights.medication.push({
        id: 'medication-vs-mood',
        title: 'Medication impact and mood may be connected',
        detail: `From ${medicationImpact.sampleSize} check-ins, your medication-impact score and mood show ${strengthLabel(medicationImpact.r)}.`,
        confidence: confidenceFromSample(medicationImpact.sampleSize),
        sampleSize: medicationImpact.sampleSize,
      })
    } else if (medicationsTracked > 0) {
      insights.medication.push({
        id: 'medication-track-more',
        title: 'You can unlock medication vs mood trends',
        detail: `You have ${medicationsTracked} medication${medicationsTracked === 1 ? '' : 's'} tracked. Add medication-impact ratings in check-ins to see clearer patterns.`,
        confidence: 'low',
        sampleSize: medicationImpact.sampleSize,
      })
    } else {
      insights.medication.push({
        id: 'medication-not-tracked',
        title: 'No medication data linked yet',
        detail: 'If you track medications and rate their daily impact, mood pattern analysis becomes much more useful.',
        confidence: 'low',
        sampleSize: 0,
      })
    }

    return NextResponse.json({
      range: { start, end },
      insights,
      meta: { sampleSize },
    })
  } catch (e) {
    console.error('mood insights error', e)
    return NextResponse.json({ error: 'Failed to load insights' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { ensureMoodTables } from '@/app/api/mood/_db'
import { extractScopedBlobPath, mapToSignedBlobUrl } from '@/lib/blob-access'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'
import { del } from '@vercel/blob'

export const dynamic = 'force-dynamic'

const MOOD_MEDIA_SCOPE = 'mood-journal'
const MOOD_MEDIA_URL_TTL_SECONDS = 60 * 60

async function getMoodUser(req: NextRequest) {
  const session = await getServerSession(authOptions)
  if (session?.user?.email) {
    return prisma.user.findUnique({ where: { email: session.user.email } })
  }
  const nativeUserId = await getUserIdFromNativeAuth(req)
  if (nativeUserId) {
    return prisma.user.findUnique({ where: { id: nativeUserId } })
  }
  return null
}

const chunk = <T,>(items: T[], size: number) => {
  const result: T[][] = []
  for (let i = 0; i < items.length; i += size) {
    result.push(items.slice(i, i + size))
  }
  return result
}

function coerceMediaList(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value.map((entry) => String(entry ?? '').trim()).filter(Boolean)
  }
  if (typeof value === 'string') {
    const trimmed = value.trim()
    if (!trimmed) return []
    try {
      const parsed = JSON.parse(trimmed)
      if (Array.isArray(parsed)) {
        return parsed.map((entry) => String(entry ?? '').trim()).filter(Boolean)
      }
    } catch {
      return [trimmed]
    }
  }
  return []
}

function normalizeMediaList(value: unknown): string[] {
  const cleaned: string[] = []
  for (const raw of coerceMediaList(value)) {
    const url = String(raw ?? '').trim()
    if (!url) continue
    const blobPath = extractScopedBlobPath(url, MOOD_MEDIA_SCOPE)
    cleaned.push(blobPath || url)
    if (cleaned.length >= 12) break
  }
  return cleaned
}

function normalizeTags(value: unknown): string[] {
  if (!Array.isArray(value)) return []
  const tags: string[] = []
  for (const raw of value) {
    const tag = String(raw ?? '').trim()
    if (!tag) continue
    tags.push(tag.slice(0, 24))
    if (tags.length >= 12) break
  }
  return tags
}

function normalizeText(value: unknown, max: number) {
  return String(value ?? '').trim().slice(0, max)
}

function asLocalDate(value: unknown): string | null {
  const s = String(value ?? '').trim()
  if (!s) return null
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return null
  return s
}

function mapSignedMedia(value: unknown): string[] {
  const result: string[] = []
  for (const raw of coerceMediaList(value)) {
    const url = String(raw ?? '').trim()
    if (!url) continue
    const signed = mapToSignedBlobUrl(url, MOOD_MEDIA_SCOPE, MOOD_MEDIA_URL_TTL_SECONDS)
    result.push(signed || url)
    if (result.length >= 12) break
  }
  return result
}

function mediaBlobPaths(value: unknown): string[] {
  const set = new Set<string>()
  for (const raw of coerceMediaList(value)) {
    const path = extractScopedBlobPath(raw, MOOD_MEDIA_SCOPE)
    if (path) set.add(path)
  }
  return Array.from(set)
}

async function deleteMoodMedia(paths: string[]) {
  if (!process.env.BLOB_READ_WRITE_TOKEN) return
  if (paths.length === 0) return
  const batches = chunk(Array.from(new Set(paths)), 100)
  for (const batch of batches) {
    if (!batch.length) continue
    await del(batch).catch((error) => {
      console.warn('mood journal media delete skipped', error)
    })
  }
}

export async function GET(req: NextRequest, { params }: { params: { id: string } }) {
  const user = await getMoodUser(req)
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  try {
    await ensureMoodTables()
    const rows: any[] = await prisma.$queryRawUnsafe(
      `SELECT id, localDate AS "localDate", title, content, images, tags, audio, prompt, template, createdAt AS "createdAt", updatedAt AS "updatedAt"
       FROM MoodJournalEntries
       WHERE userId = $1 AND id = $2`,
      user.id,
      params.id,
    )
    const entry = rows[0] ?? null
    if (!entry) return NextResponse.json({ error: 'Not found' }, { status: 404 })
    return NextResponse.json({
      entry: {
        ...entry,
        images: mapSignedMedia(entry.images),
        audio: mapSignedMedia(entry.audio),
      },
    })
  } catch (e) {
