}

export async function PUT(req: NextRequest, { params }: { params: { id: string } }) {
  const user = await getMoodUser(req)
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  const body = await req.json().catch(() => ({} as any))
  const title = normalizeText(body?.title, 120)
  const content = normalizeText(body?.content, 20000)
  const images = normalizeMediaList(body?.images)
  const tags = normalizeTags(body?.tags)
  const audio = normalizeMediaList(body?.audio)
  const prompt = normalizeText(body?.prompt, 200)
  const template = normalizeText(body?.template, 200)
  const localDate = asLocalDate(body?.localDate) ?? new Date().toISOString().slice(0, 10)

  if (!title && !content && images.length === 0 && audio.length === 0) {
    return NextResponse.json({ error: 'Entry is empty' }, { status: 400 })
  }

  try {
    await ensureMoodTables()
    const existingRows: any[] = await prisma.$queryRawUnsafe(
      `SELECT images, audio
       FROM MoodJournalEntries
       WHERE userId = $1 AND id = $2`,
      user.id,
      params.id,
    )
    const existing = existingRows[0] || null
    if (!existing) return NextResponse.json({ error: 'Not found' }, { status: 404 })

    const beforePaths = new Set([
      ...mediaBlobPaths(existing.images),
      ...mediaBlobPaths(existing.audio),
    ])
    const nextPaths = new Set([...mediaBlobPaths(images), ...mediaBlobPaths(audio)])
    const removedPaths = Array.from(beforePaths).filter((path) => !nextPaths.has(path))

    const updated = await prisma.$executeRawUnsafe(
      `UPDATE MoodJournalEntries
       SET localDate = $1,
           title = $2,
           content = $3,
           images = $4::jsonb,
           tags = $5::jsonb,
           audio = $6::jsonb,
           prompt = $7,
           template = $8,
           updatedAt = NOW()
       WHERE userId = $9 AND id = $10`,
      localDate,
      title,
      content,
      JSON.stringify(images),
      JSON.stringify(tags),
      JSON.stringify(audio),
      prompt,
      template,
      user.id,
      params.id,
    )
    if (!updated) return NextResponse.json({ error: 'Not found' }, { status: 404 })
    await deleteMoodMedia(removedPaths)
    return NextResponse.json({ success: true })
  } catch (e) {
    console.error('mood journal update error', e)
    return NextResponse.json({ error: 'Failed to update entry' }, { status: 500 })
  }
}

export async function DELETE(req: NextRequest, { params }: { params: { id: string } }) {
  const user = await getMoodUser(req)
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  try {
    await ensureMoodTables()
    const existingRows: any[] = await prisma.$queryRawUnsafe(
      `SELECT images, audio
       FROM MoodJournalEntries
       WHERE userId = $1 AND id = $2`,
      user.id,
      params.id,
    )
    const existing = existingRows[0] || null
    if (!existing) return NextResponse.json({ error: 'Not found' }, { status: 404 })

    const mediaToDelete = [
      ...mediaBlobPaths(existing.images),
      ...mediaBlobPaths(existing.audio),
    ]

    await prisma.$executeRawUnsafe(
      `DELETE FROM MoodJournalEntries WHERE userId = $1 AND id = $2`,
      user.id,
      params.id,
    )
    await deleteMoodMedia(mediaToDelete)
    return NextResponse.json({ success: true })
  } catch (e) {
    console.error('mood journal delete error', e)
    return NextResponse.json({ error: 'Failed to delete entry' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import crypto from 'crypto'
import { ensureMoodTables } from '@/app/api/mood/_db'
import { extractScopedBlobPath, mapToSignedBlobUrl } from '@/lib/blob-access'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'

export const dynamic = 'force-dynamic'

const MOOD_MEDIA_SCOPE = 'mood-journal'
const MOOD_MEDIA_URL_TTL_SECONDS = 60 * 60

async function getMoodUser(req: NextRequest) {
  const session = await getServerSession(authOptions)
  if (session?.user?.email) {
    return prisma.user.findUnique({ where: { email: session.user.email } })
  }
  const nativeUserId = await getUserIdFromNativeAuth(req)
  if (nativeUserId) {
    return prisma.user.findUnique({ where: { id: nativeUserId } })
  }
  return null
}

function coerceMediaList(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value.map((entry) => String(entry ?? '').trim()).filter(Boolean)
  }
  if (typeof value === 'string') {
    const trimmed = value.trim()
    if (!trimmed) return []
    try {
      const parsed = JSON.parse(trimmed)
      if (Array.isArray(parsed)) {
        return parsed.map((entry) => String(entry ?? '').trim()).filter(Boolean)
      }
    } catch {
      return [trimmed]
    }
  }
  return []
}

function asLocalDate(value: unknown): string | null {
  const s = String(value ?? '').trim()
  if (!s) return null
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return null
  return s
}

function clampInt(value: unknown, min: number, max: number, fallback: number) {
  const n = Number(value)
  if (!Number.isFinite(n)) return fallback
  return Math.max(min, Math.min(max, Math.round(n)))
}

function normalizeMediaList(value: unknown): string[] {
  const cleaned: string[] = []
  for (const raw of coerceMediaList(value)) {
    const url = String(raw ?? '').trim()
    if (!url) continue
    const blobPath = extractScopedBlobPath(url, MOOD_MEDIA_SCOPE)
    cleaned.push(blobPath || url)
    if (cleaned.length >= 12) break
  }
  return cleaned
}

function normalizeTags(value: unknown): string[] {
  if (!Array.isArray(value)) return []
  const tags: string[] = []
  for (const raw of value) {
    const tag = String(raw ?? '').trim()
    if (!tag) continue
    tags.push(tag.slice(0, 24))
    if (tags.length >= 12) break
  }
  return tags
}

function normalizeText(value: unknown, max: number) {
  return String(value ?? '').trim().slice(0, max)
}

function mapSignedMedia(value: unknown): string[] {
  const result: string[] = []
  for (const raw of coerceMediaList(value)) {
    const url = String(raw ?? '').trim()
    if (!url) continue
    const signed = mapToSignedBlobUrl(url, MOOD_MEDIA_SCOPE, MOOD_MEDIA_URL_TTL_SECONDS)
    result.push(signed || url)
    if (result.length >= 12) break
  }
  return result
}

export async function GET(req: NextRequest) {
  const user = await getMoodUser(req)
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  const { searchParams } = new URL(req.url)
  const start = asLocalDate(searchParams.get('start'))
  const end = asLocalDate(searchParams.get('end'))
  const limit = clampInt(searchParams.get('limit'), 1, 100, 20)
  const q = String(searchParams.get('q') ?? '').trim()

  try {
    await ensureMoodTables()
    let rows: any[] = []
    if (start && end) {
      rows = await prisma.$queryRawUnsafe(
        `SELECT id, localDate AS "localDate", title, content, images, tags, audio, prompt, template, createdAt AS "createdAt", updatedAt AS "updatedAt"
         FROM MoodJournalEntries
         WHERE userId = $1 AND localDate BETWEEN $2 AND $3
         ORDER BY createdAt DESC`,
        user.id,
        start,
        end,
      )
    } else if (q) {
      rows = await prisma.$queryRawUnsafe(
        `SELECT id, localDate AS "localDate", title, content, images, tags, audio, prompt, template, createdAt AS "createdAt", updatedAt AS "updatedAt"
         FROM MoodJournalEntries
         WHERE userId = $1 AND (title ILIKE $2 OR content ILIKE $2)
         ORDER BY createdAt DESC
         LIMIT $3`,
        user.id,
        `%${q}%`,
        limit,
      )
    } else {
      rows = await prisma.$queryRawUnsafe(
        `SELECT id, localDate AS "localDate", title, content, images, tags, audio, prompt, template, createdAt AS "createdAt", updatedAt AS "updatedAt"
         FROM MoodJournalEntries
         WHERE userId = $1
         ORDER BY createdAt DESC
         LIMIT $2`,
        user.id,
        limit,
      )
    }
    const entries = rows.map((entry) => ({
      ...entry,
      images: mapSignedMedia(entry.images),
      audio: mapSignedMedia(entry.audio),
    }))
    return NextResponse.json({ entries })
  } catch (e) {
    console.error('mood journal get error', e)
    return NextResponse.json({ error: 'Failed to load journal entries' }, { status: 500 })
  }
}

export async function POST(req: NextRequest) {
  const user = await getMoodUser(req)
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  const body = await req.json().catch(() => ({} as any))
  const title = normalizeText(body?.title, 120)
  const content = normalizeText(body?.content, 20000)
  const images = normalizeMediaList(body?.images)
  const tags = normalizeTags(body?.tags)
  const audio = normalizeMediaList(body?.audio)
  const prompt = normalizeText(body?.prompt, 200)
  const template = normalizeText(body?.template, 200)
  const localDate = asLocalDate(body?.localDate) ?? new Date().toISOString().slice(0, 10)

  if (!title && !content && images.length === 0 && audio.length === 0) {
    return NextResponse.json({ error: 'Entry is empty' }, { status: 400 })
  }

  try {
    await ensureMoodTables()
    const id = crypto.randomUUID()
    await prisma.$queryRawUnsafe(
      `INSERT INTO MoodJournalEntries (id, userId, localDate, title, content, images, tags, audio, prompt, template)
       VALUES ($1, $2, $3, $4, $5, $6::jsonb, $7::jsonb, $8::jsonb, $9, $10)`,
      id,
      user.id,
      localDate,
      title,
      content,
      JSON.stringify(images),
      JSON.stringify(tags),
      JSON.stringify(audio),
      prompt,
      template,
    )
    return NextResponse.json({ success: true, id })
  } catch (e) {
    console.error('mood journal save error', e)
    return NextResponse.json({ error: 'Failed to save journal entry' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import OpenAI from 'openai'
import { authOptions } from '@/lib/auth'
import { assertAiUsageAllowed, isAiSafetyError } from '@/lib/ai-safety'
import { logAiUsageEvent, runChatCompletionWithLogging } from '@/lib/ai-usage-logger'
import { prisma } from '@/lib/prisma'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const MAX_IMAGE_BYTES = 6 * 1024 * 1024
const MAX_AUDIO_BYTES = 12 * 1024 * 1024

const getOpenAIClient = () => {
  if (!process.env.OPENAI_API_KEY) return null
  return new OpenAI({ apiKey: process.env.OPENAI_API_KEY })
}

const trimSummary = (value: string, fallback: string) => {
  const clean = String(value || '').replace(/\s+/g, ' ').trim()
  if (!clean) return fallback
  return clean.slice(0, 600)
}

async function resolveUserId(session: any): Promise<string | null> {
  if (session?.user?.id) return session.user.id
  if (session?.user?.email) {
    const user = await prisma.user.findUnique({
      where: { email: session.user.email },
      select: { id: true },
    })
    return user?.id ?? null
  }
  return null
}

const summarizeImage = async (client: OpenAI, file: File, userId: string) => {
  const imageBuffer = await file.arrayBuffer()
  const base64 = Buffer.from(imageBuffer).toString('base64')
  const completion: any = await runChatCompletionWithLogging(
    client,
    {
      model: 'gpt-5.6-sol',
      temperature: 0.2,
      max_tokens: 140,
      messages: [
        {
          role: 'system',
          content:
            'You create short, practical notes for a personal health journal. Be factual. Keep it under two short sentences.',
        },
        {
          role: 'user',
          content: [
            {
              type: 'text',
              text:
                'Summarize useful details from this mood journal image for a weekly report. Include visible text if any. Do not include private identifiers.',
            },
            {
              type: 'image_url',
              image_url: {
                url: `data:${file.type || 'image/jpeg'};base64,${base64}`,
                detail: 'low',
              },
            },
          ],
        },
      ],
    } as any,
    {
      feature: 'mood-journal:extract-image',
      userId,
      endpoint: '/api/mood/journal/extract-media',
    },
    {
      image: {
        width: null,
        height: null,
        bytes: file.size,
        mime: file.type || null,
      },
    },
  )

  return trimSummary(
    completion.choices?.[0]?.message?.content || '',
    'Image uploaded and analyzed for journal context.',
  )
}

const transcribeAudio = async (client: OpenAI, file: File, userId: string) => {
  const model = process.env.MOOD_MEDIA_AUDIO_MODEL || 'gpt-4o-mini-transcribe'
  const response = await client.audio.transcriptions.create({
    model,
    file,
    response_format: 'text',
  } as any)

  await logAiUsageEvent({
    feature: 'mood-journal:extract-audio',
    userId,
    endpoint: '/api/mood/journal/extract-media',
    model,
    promptTokens: 0,
    completionTokens: 0,
    costCents: 0,
    success: true,
    detail: 'audio transcription',
  })

  const text = typeof response === 'string' ? response : (response as any)?.text || ''
  return trimSummary(text, 'Voice note uploaded and analyzed for journal context.')
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.email) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }
    const userId = await resolveUserId(session)

    const formData: any = await request.formData().catch(() => null)
    if (!formData) {
      return NextResponse.json({ error: 'Invalid upload data' }, { status: 400 })
    }

    const rawKind = String(formData.get('kind') || '').trim().toLowerCase()
    const kind = rawKind === 'audio' ? 'audio' : rawKind === 'image' ? 'image' : null
    const file = formData.get('file')

    if (!kind) {
      return NextResponse.json({ error: 'Missing media type' }, { status: 400 })
    }

    if (!(file instanceof File)) {
      return NextResponse.json({ error: 'No media file provided' }, { status: 400 })
    }

    if (kind === 'image') {
      if (!file.type.startsWith('image/')) {
        return NextResponse.json({ error: 'File must be an image' }, { status: 400 })
      }
      if (file.size > MAX_IMAGE_BYTES) {
        return NextResponse.json({ error: 'Image must be less than 6MB' }, { status: 400 })
      }
    } else {
      if (!file.type.startsWith('audio/')) {
        return NextResponse.json({ error: 'File must be audio' }, { status: 400 })
      }
      if (file.size > MAX_AUDIO_BYTES) {
        return NextResponse.json({ error: 'Audio must be less than 12MB' }, { status: 400 })
      }
    }

    const openai = getOpenAIClient()
    if (!openai) {
      const fallback =
        kind === 'image'
          ? 'Image uploaded and analyzed for journal context.'
          : 'Voice note uploaded and analyzed for journal context.'
      return NextResponse.json({ success: true, kind, summary: fallback, ai: false })
    }

    await assertAiUsageAllowed({
      feature: kind === 'image' ? 'mood-journal:extract-image' : 'mood-journal:extract-audio',
      userId,
    })

    const summary =
      kind === 'image'
        ? await summarizeImage(openai, file, userId || 'unknown')
        : await transcribeAudio(openai, file, userId || 'unknown')

    return NextResponse.json({ success: true, kind, summary, ai: true })
  } catch (error) {
    if (isAiSafetyError(error)) {
      return NextResponse.json(
        { error: 'AI uploads are temporarily paused because usage climbed too fast. Please try again shortly.' },
        { status: 429 },
      )
    }
    console.error('mood journal media extraction error', error)
    return NextResponse.json({ error: 'Failed to analyze media' }, { status: 500 })
  }
}

