import { normalizeSubscriptionList } from '@/lib/push-subscriptions'
import { isSubscriptionActive } from '@/lib/subscription-utils'

export const dynamic = 'force-dynamic'
export const runtime = 'nodejs'

type TimeSnapshot = {
  timeZone: string
  ok: boolean
  current: string
  localDate: string
}

function snapshotInTimeZone(now: Date, timeZone: string): TimeSnapshot {
  try {
    const timeParts = new Intl.DateTimeFormat('en-GB', {
      timeZone,
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    }).formatToParts(now)
    const hh = timeParts.find((p) => p.type === 'hour')?.value || '00'
    const mm = timeParts.find((p) => p.type === 'minute')?.value || '00'

    const dateParts = new Intl.DateTimeFormat('en-GB', {
      timeZone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    }).formatToParts(now)
    const year = dateParts.find((p) => p.type === 'year')?.value || '1970'
    const month = dateParts.find((p) => p.type === 'month')?.value || '01'
    const day = dateParts.find((p) => p.type === 'day')?.value || '01'

    return {
      timeZone,
      ok: true,
      current: `${hh}:${mm}`,
      localDate: `${year}-${month}-${day}`,
    }
  } catch {
    const fallback = 'UTC'
    const timeParts = new Intl.DateTimeFormat('en-GB', {
      timeZone: fallback,
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    }).formatToParts(now)
    const hh = timeParts.find((p) => p.type === 'hour')?.value || '00'
    const mm = timeParts.find((p) => p.type === 'minute')?.value || '00'

    const dateParts = new Intl.DateTimeFormat('en-GB', {
      timeZone: fallback,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    }).formatToParts(now)
    const year = dateParts.find((p) => p.type === 'year')?.value || '1970'
    const month = dateParts.find((p) => p.type === 'month')?.value || '01'
    const day = dateParts.find((p) => p.type === 'day')?.value || '01'

    return {
      timeZone: fallback,
      ok: false,
      current: `${hh}:${mm}`,
      localDate: `${year}-${month}-${day}`,
    }
  }
}

export async function GET() {
  const session = await getServerSession(authOptions)
  if (!session?.user?.email) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  const user = await prisma.user.findUnique({
    where: { email: session.user.email },
    include: { subscription: true, creditTopUps: true },
  })
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  await ensureMoodTables()

  const settingsRows: Array<{
    enabled: boolean
    time1: string
    time2: string
    time3: string
    time4: string
    timezone: string
    frequency: number
  }> = await prisma.$queryRawUnsafe(
    `SELECT enabled, time1, time2, time3, time4, timezone, frequency
     FROM MoodReminderSettings
     WHERE userId = $1
     LIMIT 1`,
    user.id,
  )

  const settings = settingsRows[0] || {
    enabled: false,
    time1: '20:00',
    time2: '12:00',
    time3: '18:00',
    time4: '09:00',
    timezone: 'UTC',
    frequency: 1,
  }
  const now = new Date()
  const hasSubscription = isSubscriptionActive(user.subscription, now)
  const hasPurchasedCredits = (user.creditTopUps || []).some(
    (topUp: any) => topUp.expiresAt > now && (topUp.amountCents - topUp.usedCents) > 0
  )
  const maxFrequency = (hasSubscription || hasPurchasedCredits) ? 4 : 1
  const resolvedFrequency = Math.max(1, Math.min(maxFrequency, settings.frequency || 1))

  const nowUtc = new Date()
  const snapshot = snapshotInTimeZone(nowUtc, settings.timezone || 'UTC')
  const backfillWindow = Math.max(1, Math.min(60, parseInt(process.env.REMINDER_LAG_MINUTES || '10', 10)))

  const reminderTimes: string[] = []
  if (resolvedFrequency >= 1) reminderTimes.push(settings.time1 || '20:00')
  if (resolvedFrequency >= 2) reminderTimes.push(settings.time2 || '12:00')
  if (resolvedFrequency >= 3) reminderTimes.push(settings.time3 || '18:00')
  if (resolvedFrequency >= 4) reminderTimes.push(settings.time4 || '09:00')

  let shouldSend = false
  let matchedReminder = ''
  let matchReason = ''

  if (!settings.enabled) {
    matchReason = 'reminders_disabled'
  } else {
    const [ch, cm] = snapshot.current.split(':').map((v) => parseInt(v, 10))
    const currentTotalMinutes = ch * 60 + cm

    for (const reminderTime of reminderTimes) {
      const [rh, rm] = reminderTime.split(':').map((v) => parseInt(v, 10))
      if (Number.isNaN(rh) || Number.isNaN(rm)) continue

      if (rh === ch && rm === cm) {
        shouldSend = true
        matchedReminder = reminderTime
        matchReason = 'exact_match'
        break
      }

      const reminderTotalMinutes = rh * 60 + rm
      let minutesDiff = currentTotalMinutes - reminderTotalMinutes
      if (minutesDiff < 0) minutesDiff += 1440
      if (minutesDiff >= 1 && minutesDiff <= backfillWindow) {
        shouldSend = true
        matchedReminder = reminderTime
        matchReason = `late_cron_${minutesDiff}m`
        break
      }

      let minutesAhead = reminderTotalMinutes - currentTotalMinutes
      if (minutesAhead < 0) minutesAhead += 1440
      if (minutesAhead === 1) {
        shouldSend = true
        matchedReminder = reminderTime
        matchReason = 'early_send_1m'
        break
      }
    }
  }

  const deliveryRows: Array<{ reminderTime: string; sentDate: string; sentAt: string }> =
    await prisma.$queryRawUnsafe(
      `SELECT reminderTime, sentDate::text AS "sentDate", sentAt::text AS "sentAt"
       FROM MoodReminderDeliveryLog
       WHERE userId = $1
       ORDER BY sentAt DESC
       LIMIT 5`,
      user.id,
    )

  const subscriptionRows: Array<{ subscription: any; updatedAt: string }> = await prisma.$queryRawUnsafe(
    `SELECT subscription, updatedAt::text AS "updatedAt" FROM PushSubscriptions WHERE userId = $1 LIMIT 1`,
    user.id,
  )

  return NextResponse.json({
    userId: user.id,
    nowUtc: nowUtc.toISOString(),
    settings,
    maxFrequency,
    snapshot,
    reminderTimes,
    match: {
      shouldSend,
      matchedReminder,
      reason: matchReason || 'no_match',
      backfillWindowMinutes: backfillWindow,
    },
    subscription: {
      present: subscriptionRows.length > 0 && normalizeSubscriptionList(subscriptionRows[0]?.subscription).length > 0,
      updatedAt: subscriptionRows[0]?.updatedAt || null,
      count: subscriptionRows.length ? normalizeSubscriptionList(subscriptionRows[0]?.subscription).length : 0,
    },
    recentDeliveries: deliveryRows,
  })
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'
import { prisma } from '@/lib/prisma'
import { ensureMoodTables } from '@/app/api/mood/_db'
import { publishWithQStash, scheduleAllMoodReminders } from '@/lib/qstash'
import { isSubscriptionActive } from '@/lib/subscription-utils'

export const dynamic = 'force-dynamic'

function normalizeTime(input: unknown, fallback: string) {
  const s = String(input ?? '').trim()
  if (!s) return fallback
  const m24 = s.match(/^([01]\d|2[0-3]):([0-5]\d)$/)
  if (m24) return `${m24[1]}:${m24[2]}`
  return fallback
}

function clampInt(value: unknown, min: number, max: number, fallback: number) {
  const n = Number(value)
  if (!Number.isFinite(n)) return fallback
  return Math.max(min, Math.min(max, Math.round(n)))
}

function normalizeTimezone(input: unknown) {
  const tz = String(input ?? '').trim()
  if (!tz) return 'UTC'
  if (tz.length > 64) return 'UTC'
  try {
    new Intl.DateTimeFormat('en-GB', { timeZone: tz })
    return tz
  } catch {
    return 'UTC'
  }
}

async function getMoodReminderUser(req: NextRequest) {
  const nativeUserId = await getUserIdFromNativeAuth(req)
  if (nativeUserId) {
    return prisma.user.findUnique({
      where: { id: nativeUserId },
      include: { subscription: true, creditTopUps: true },
    })
  }

  const session = await getServerSession(authOptions)
  const email = String(session?.user?.email || '').trim().toLowerCase()
  if (!email) return null
  return prisma.user.findUnique({
    where: { email },
    include: { subscription: true, creditTopUps: true },
  })
}

export async function GET(req: NextRequest) {
  const user = await getMoodReminderUser(req)
  if (!user) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  await ensureMoodTables()
  const now = new Date()
  const hasSubscription = isSubscriptionActive(user.subscription, now)
  const hasPurchasedCredits = (user.creditTopUps || []).some(
    (topUp: any) => topUp.expiresAt > now && (topUp.amountCents - topUp.usedCents) > 0
  )
  const isPaidUser = hasSubscription || hasPurchasedCredits
  const maxFrequency = isPaidUser ? 4 : 1

  const rows: any[] = await prisma.$queryRawUnsafe(
    `SELECT enabled, time1, time2, time3, time4, timezone, frequency
     FROM MoodReminderSettings
     WHERE userId = $1
     LIMIT 1`,
    user.id,
  )

  const row = rows[0] || null
  return NextResponse.json({
    enabled: row?.enabled ?? false,
    time1: row?.time1 ?? '20:00',
    time2: row?.time2 ?? '12:00',
    time3: row?.time3 ?? '18:00',
    time4: row?.time4 ?? '09:00',
    timezone: row?.timezone ?? 'UTC',
    frequency: Math.min(Math.max(1, row?.frequency ?? 1), maxFrequency),
    maxFrequency,
    isPaidUser,
  })
}

export async function POST(req: NextRequest) {
  const user = await getMoodReminderUser(req)
  if (!user) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const body = await req.json().catch(() => ({} as any))
  const enabled = !!body?.enabled
  const time1 = normalizeTime(body?.time1, '20:00')
  const time2 = normalizeTime(body?.time2, '12:00')
  const time3 = normalizeTime(body?.time3, '18:00')
  const time4 = normalizeTime(body?.time4, '09:00')
  const timezone = normalizeTimezone(body?.timezone)
  const now = new Date()
  const hasSubscription = isSubscriptionActive(user.subscription, now)
  const hasPurchasedCredits = (user.creditTopUps || []).some(
    (topUp: any) => topUp.expiresAt > now && (topUp.amountCents - topUp.usedCents) > 0
  )
  const isPaidUser = hasSubscription || hasPurchasedCredits
  const maxFrequency = isPaidUser ? 4 : 1
  const frequency = clampInt(body?.frequency, 1, maxFrequency, 1)

  await ensureMoodTables()

  await prisma.$queryRawUnsafe(
    `INSERT INTO MoodReminderSettings (userId, enabled, time1, time2, time3, time4, timezone, frequency)
     VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
     ON CONFLICT (userId) DO UPDATE SET
       enabled = EXCLUDED.enabled,
       time1 = EXCLUDED.time1,
       time2 = EXCLUDED.time2,
       time3 = EXCLUDED.time3,
       time4 = EXCLUDED.time4,
       timezone = EXCLUDED.timezone,
       frequency = EXCLUDED.frequency`,
    user.id,
    enabled,
    time1,
    time2,
    time3,
    time4,
    timezone,
    frequency,
  )

  let scheduleResults: any[] = []
  if (enabled) {
    scheduleResults = await scheduleAllMoodReminders(user.id, {
      time1,
      time2,
      time3,
      time4,
      timezone,
      frequency,
    }).catch((error) => {
      console.error('[MOOD] Failed to schedule reminders via QStash', error)
      return []
    })
    const failedSchedules = scheduleResults.filter((result) => !result.scheduled)
    if (failedSchedules.length > 0) {
      console.error('[MOOD] QStash scheduling failures detected', { failedSchedules })
    }

    try {
      const now = new Date()
      const fmt = new Intl.DateTimeFormat('en-GB', {
        timeZone: timezone,
        hour: '2-digit',
        minute: '2-digit',
        hour12: false,
      })
      const parts = fmt.formatToParts(now)
      const ch = parseInt(parts.find((p) => p.type === 'hour')?.value || '0', 10)
      const cm = parseInt(parts.find((p) => p.type === 'minute')?.value || '0', 10)
      const currentTotal = ch * 60 + cm
      const sendWindowMinutes = 5
      const candidates: string[] = []
      if (frequency >= 1) candidates.push(time1)
      if (frequency >= 2) candidates.push(time2)
      if (frequency >= 3) candidates.push(time3)
      if (frequency >= 4) candidates.push(time4)
      for (const t of candidates) {
        const [hh, mm] = t.split(':').map((v) => parseInt(v, 10))
        if (Number.isNaN(hh) || Number.isNaN(mm)) continue
        const target = hh * 60 + mm
        let diff = currentTotal - target
        if (diff < 0) diff += 1440
        if (diff >= 0 && diff <= sendWindowMinutes) {
          const publishResult = await publishWithQStash('/api/mood/dispatch', {
            userId: user.id,
            reminderTime: t,
            timezone,
          }).catch(() => ({ ok: false, reason: 'exception' }))
          if (!publishResult?.ok) {
            console.warn('[MOOD] Failed to enqueue immediate reminder via QStash', {
              userId: user.id,
              reminderTime: t,
              reason: publishResult?.reason,
            })
          }
          break
        }
      }
    } catch {}
  }

  return NextResponse.json({ success: true, scheduleResults })
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import webpush from 'web-push'
import { publishWithQStash } from '@/lib/qstash'
import { dedupeSubscriptions, normalizeSubscriptionList, removeSubscriptionsByEndpoint, sendToSubscriptions } from '@/lib/push-subscriptions'
import { isSchedulerAuthorized } from '@/lib/scheduler-auth'
import { createInboxNotification } from '@/lib/notification-inbox'

export const runtime = 'nodejs'

export async function POST(req: NextRequest) {
  const isScheduler = isSchedulerAuthorized(req)
  if (!isScheduler) {
    const session = await getServerSession(authOptions)
    if (!session?.user?.email) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    const user = await prisma.user.findUnique({ where: { email: session.user.email } })
    if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

    const publishResult = await publishWithQStash('/api/mood/send-reminder-now', {
      userId: user.id,
    })
    if (!publishResult.ok) {
      return NextResponse.json({ error: 'Failed to enqueue reminder' }, { status: 500 })
    }
    return NextResponse.json({ enqueued: true })
  }

  const body = await req.json().catch(() => ({}))
  const userId = String(body?.userId || '')
  if (!userId) {
    return NextResponse.json({ error: 'invalid_payload' }, { status: 400 })
  }
  const user = await prisma.user.findUnique({ where: { id: userId } })
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  const rows: Array<{ subscription: any }> = await prisma.$queryRawUnsafe(
    `SELECT subscription FROM PushSubscriptions WHERE userId = $1`,
    user.id,
  )
  if (!rows.length) return NextResponse.json({ error: 'No subscription' }, { status: 400 })
  const subscriptions = dedupeSubscriptions(normalizeSubscriptionList(rows[0].subscription))
  if (!subscriptions.length) return NextResponse.json({ error: 'No subscription' }, { status: 400 })

  const publicKey = process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY || ''
  const privateKey = process.env.VAPID_PRIVATE_KEY || ''
  if (!publicKey || !privateKey) {
    return NextResponse.json({ error: 'VAPID keys not configured' }, { status: 500 })
  }
  webpush.setVapidDetails('mailto:support@helfi.ai', publicKey, privateKey)

  const payload = JSON.stringify({
    title: 'Quick mood check‑in',
    body: 'How are you feeling right now? It takes 10 seconds.',
    url: '/mood/quick',
  })

  try {
    const { sent, errors, goneEndpoints } = await sendToSubscriptions(subscriptions, (sub) =>
      webpush.sendNotification(sub, payload)
    )
    if (goneEndpoints.length) {
      const remaining = removeSubscriptionsByEndpoint(subscriptions, goneEndpoints)
      await prisma.$executeRawUnsafe(
        `UPDATE PushSubscriptions SET subscription = $2::jsonb, updatedAt = NOW() WHERE userId = $1`,
        user.id,
        JSON.stringify(remaining)
      )
    }
    if (!sent) {
      console.error('mood send-reminder-now error', errors.map((e) => e.message).join('; '))
      return NextResponse.json({ error: 'Failed to send reminder' }, { status: 500 })
    }
    await createInboxNotification({
      userId: user.id,
      title: 'Quick mood check-in',
      body: 'How are you feeling right now? It takes 10 seconds.',
      url: '/mood/quick',
      type: 'mood_reminder',
      source: 'push',
      eventKey: `mood:manual:${Date.now()}`,
    }).catch(() => {})
    return NextResponse.json({ success: true, sent })
  } catch (e: any) {
    console.error('mood send-reminder-now error', e?.body || e?.message || e)
    return NextResponse.json({ error: 'Failed to send reminder' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { encode } from 'next-auth/jwt'
import { createRemoteJWKSet, jwtVerify } from 'jose'

import { ensureFreeCreditColumns, NEW_USER_FREE_CREDITS } from '@/lib/free-credits'
import { prisma } from '@/lib/prisma'

const SECRET = process.env.NEXTAUTH_SECRET || process.env.AUTH_SECRET
const SESSION_MAX_AGE_SECONDS = 30 * 24 * 60 * 60
const APPLE_ISSUER = 'https://appleid.apple.com'
const APPLE_KEYS = createRemoteJWKSet(new URL('https://appleid.apple.com/auth/keys'))

function normalizeEmail(value: unknown) {
  return typeof value === 'string' ? value.trim().toLowerCase() : ''
}

function getAppleAudiences() {
  return Array.from(
    new Set(
      [
        process.env.APPLE_BUNDLE_ID,
        process.env.EXPO_PUBLIC_APPLE_BUNDLE_ID,
        'ai.helfi.app',
        process.env.APPLE_CLIENT_ID,
      ]
        .map((value) => (typeof value === 'string' ? value.trim() : ''))
        .filter(Boolean),
    ),
  )
}

function formatName(fullName: any, email: string) {
  const given = typeof fullName?.givenName === 'string' ? fullName.givenName.trim() : ''
  const family = typeof fullName?.familyName === 'string' ? fullName.familyName.trim() : ''
  const joined = [given, family].filter(Boolean).join(' ').trim()
  if (joined) return joined
  return email ? email.split('@')[0] : 'Helfi user'
}

async function createSession(user: { id: string; email: string; name: string | null; image: string | null }) {
  const nowSeconds = Math.floor(Date.now() / 1000)
  const exp = nowSeconds + SESSION_MAX_AGE_SECONDS
  const token = await encode({
    token: {
      sub: user.id,
      id: user.id,
      email: user.email,
      name: user.name || user.email.split('@')[0],
      image: user.image,
      iat: nowSeconds,
      exp,
    },
    secret: SECRET!,
    maxAge: SESSION_MAX_AGE_SECONDS,
  })

  return {
    ok: true,
    token,
    expiresAt: exp * 1000,
    user: { id: user.id, email: user.email, name: user.name, image: user.image },
  }
}

export async function POST(req: NextRequest) {
  try {
    if (!SECRET) {
      return NextResponse.json({ error: 'Server sign in is not configured.' }, { status: 500 })
    }

    const body = await req.json().catch(() => ({}))
    const identityToken = typeof body?.identityToken === 'string' ? body.identityToken.trim() : ''
    if (!identityToken) {
      return NextResponse.json({ error: 'Apple sign in did not return a token.' }, { status: 400 })
    }

    const { payload } = await jwtVerify(identityToken, APPLE_KEYS, {
      issuer: APPLE_ISSUER,
      audience: getAppleAudiences(),
    })

    const appleUserId = typeof payload.sub === 'string' ? payload.sub.trim() : ''
    if (!appleUserId) {
      return NextResponse.json({ error: 'Apple sign in did not return an account id.' }, { status: 400 })
    }

    const tokenEmail = normalizeEmail(payload.email)
    const bodyEmail = normalizeEmail(body?.email)
    const email = tokenEmail || bodyEmail
    const name = formatName(body?.fullName, email)

    let user = await prisma.user.findFirst({
      where: {
        accounts: {
          some: {
            provider: 'apple',
            providerAccountId: appleUserId,
          },
        },
      },
      select: { id: true, email: true, name: true, image: true },
    })

    if (!user) {
      if (!email) {
        return NextResponse.json(
          { error: 'Apple did not share an email address for this sign in. Please use email login, then try Apple again.' },
          { status: 400 },
        )
      }

      const existingByEmail = await prisma.user.findUnique({
        where: { email },
        select: { id: true, email: true, name: true, image: true },
      })

      if (existingByEmail) {
        user = existingByEmail
      } else {
        await ensureFreeCreditColumns()
        user = await prisma.user.create({
          data: {
            email,
            name,
            emailVerified: new Date(),
            termsAccepted: true,
            ...NEW_USER_FREE_CREDITS,
          },
          select: { id: true, email: true, name: true, image: true },
        })
      }

      await prisma.account.upsert({
        where: {
          provider_providerAccountId: {
            provider: 'apple',
            providerAccountId: appleUserId,
          },
        },
        update: {
          id_token: identityToken,
          access_token: typeof body?.authorizationCode === 'string' ? body.authorizationCode : null,
          token_type: 'Bearer',
        },
        create: {
          userId: user.id,
          type: 'oauth',
          provider: 'apple',
          providerAccountId: appleUserId,
          id_token: identityToken,
          access_token: typeof body?.authorizationCode === 'string' ? body.authorizationCode : null,
          token_type: 'Bearer',
        },
      })
    } else {
      await prisma.account.updateMany({
        where: {
          provider: 'apple',
          providerAccountId: appleUserId,
        },
        data: {
          id_token: identityToken,
          access_token: typeof body?.authorizationCode === 'string' ? body.authorizationCode : null,
          token_type: 'Bearer',
        },
      })
    }

    if (email && !user.email.includes('@privaterelay.appleid.com')) {
      await prisma.user
        .update({
          where: { id: user.id },
          data: {
            emailVerified: new Date(),
            name: user.name || name,
          },
        })
        .catch(() => null)
    }

    const latestUser = await prisma.user.findUnique({
      where: { id: user.id },
      select: { id: true, email: true, name: true, image: true },
    })
    if (!latestUser) {
      return NextResponse.json({ error: 'Apple sign in failed. Please try again.' }, { status: 500 })
    }

    const res = NextResponse.json(await createSession(latestUser), { status: 200 })
    res.headers.set('cache-control', 'no-store')
    return res
  } catch (error) {
    console.error('Native Apple sign in failed:', error)
    return NextResponse.json({ error: 'Apple sign in failed. Please try again.' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { encode } from 'next-auth/jwt'
import bcrypt from 'bcryptjs'

import { prisma } from '@/lib/prisma'

// Phone app login (separate from NextAuth's /api/auth/* catch-all):
// - Takes email + password
// - Returns a NextAuth-compatible JWT that the phone app can send as:
//   Authorization: Bearer <token>
//
// This lets the phone app call protected API routes without opening a browser.

const SECRET = process.env.NEXTAUTH_SECRET || process.env.AUTH_SECRET
const SESSION_MAX_AGE_SECONDS = 30 * 24 * 60 * 60 // 30 days

export async function POST(req: NextRequest) {
  try {
    if (!SECRET) {
      return NextResponse.json({ error: 'Server misconfigured' }, { status: 500 })
    }

    const body = await req.json().catch(() => ({}))
    const emailRaw = typeof body?.email === 'string' ? body.email : ''
    const passwordRaw = typeof body?.password === 'string' ? body.password : ''
    const accountTypeRaw = typeof body?.accountType === 'string' ? body.accountType : ''
    const practitionerIntent = accountTypeRaw.trim().toLowerCase() === 'practitioner'

    const email = emailRaw.trim().toLowerCase()
    const password = passwordRaw.trim()

    if (!email || !password) {
      return NextResponse.json({ error: 'Missing email or password' }, { status: 400 })
    }

    const user = await prisma.user.findUnique({
      where: { email },
      select: {
        id: true,
        email: true,
        name: true,
        image: true,
        passwordHash: true,
        emailVerified: true,
        practitionerAccount: { select: { id: true } },
      },
    })

    if (!user?.passwordHash) {
      // Avoid leaking if an account exists.
      return NextResponse.json({ error: 'Invalid email or password' }, { status: 401 })
    }

    const match = await bcrypt.compare(password, user.passwordHash)
    if (!match) {
      return NextResponse.json({ error: 'Invalid email or password' }, { status: 401 })
    }

    // Keep behavior consistent with credentials provider (auto-verify on first successful password login).
    if (!user.emailVerified) {
      try {
        await prisma.user.update({ where: { id: user.id }, data: { emailVerified: new Date() } })
      } catch {
        // Non-blocking.
      }
    }

    let hasPractitionerAccount = Boolean(user.practitionerAccount?.id)
    if (practitionerIntent && !hasPractitionerAccount) {
      try {
        await prisma.practitionerAccount.create({
          data: {
            userId: user.id,
            contactEmail: user.email.toLowerCase(),
          },
        })
        hasPractitionerAccount = true
      } catch {
        // Non-blocking: if it already exists due to a race, treat as practitioner account present.
        hasPractitionerAccount = true
      }
    }

    const nowSeconds = Math.floor(Date.now() / 1000)
    const exp = nowSeconds + SESSION_MAX_AGE_SECONDS
    const token = await encode({
      token: {
        sub: user.id,
        id: user.id,
        email: user.email,
        name: user.name || user.email.split('@')[0],
        image: user.image,
        iat: nowSeconds,
        exp,
      },
      secret: SECRET,
      maxAge: SESSION_MAX_AGE_SECONDS,
    })

    const res = NextResponse.json(
      {
        ok: true,
        token,
        expiresAt: exp * 1000,
        user: {
          id: user.id,
          email: user.email,
          name: user.name,
          image: user.image,
          isPractitioner: hasPractitionerAccount,
        },
      },
      { status: 200 },
    )
    res.headers.set('cache-control', 'no-store')
    return res
  } catch (error) {
    console.error('Native login failed:', error)
    return NextResponse.json({ error: 'Login failed' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getToken } from 'next-auth/jwt'

const SECRET = process.env.NEXTAUTH_SECRET || process.env.AUTH_SECRET

export async function GET(req: NextRequest) {
  try {
    if (!SECRET) {
      return NextResponse.json({ error: 'Server misconfigured' }, { status: 500 })
    }

    const token = await getToken({ req, secret: SECRET }).catch(() => null)
    if (!token?.email) {
      return NextResponse.json({ error: 'Not authenticated' }, { status: 401 })
    }

    const res = NextResponse.json(
      {
        ok: true,
        user: {
          id: token.id || token.sub || null,
          email: String(token.email),
          name: token.name ? String(token.name) : null,
          image: token.image ? String(token.image) : null,
        },
      },
      { status: 200 }
    )
    res.headers.set('cache-control', 'no-store')
    return res
  } catch (error) {
    console.error('Native me failed:', error)
    return NextResponse.json({ error: 'Request failed' }, { status: 500 })
  }
}

