      .btn { display: inline-block; margin-top: 12px; padding: 10px 14px; background: #43a047; color: #fff; border-radius: 10px; text-decoration: none; font-weight: 700; }
    </style>
  </head>
  <body>
    <div class="card">
      <h2>Sign in is not available right now</h2>
      <p>${message}</p>
      <a class="btn" href="helfi://auth-complete?error=provider_not_available">Return to Helfi app</a>
    </div>
  </body>
</html>`
}

export async function GET(request: NextRequest) {
  const providerRaw = String(request.nextUrl.searchParams.get('provider') || '')
    .trim()
    .toLowerCase()
  const modeRaw = String(request.nextUrl.searchParams.get('mode') || 'signin')
    .trim()
    .toLowerCase()
  const provider = providerRaw === 'apple' ? 'apple' : providerRaw === 'google' ? 'google' : null
  const mode = modeRaw === 'signup' ? 'signup' : 'signin'

  if (!provider) {
    return NextResponse.json({ error: 'Invalid provider.' }, { status: 400 })
  }

  if (provider === 'apple' && !isAppleConfigured()) {
    return new NextResponse(
      errorHtml('Apple sign in is not configured on this environment yet. Please use Google or email for now.'),
      { status: 200, headers: { 'content-type': 'text/html; charset=utf-8' } },
    )
  }

  if (provider === 'google' && !isGoogleConfigured()) {
    return new NextResponse(
      errorHtml('Google sign in is not configured on this environment yet. Please use email for now.'),
      { status: 200, headers: { 'content-type': 'text/html; charset=utf-8' } },
    )
  }

  const baseUrl = readBaseUrl(request)
  const callbackUrl = `${completeUrl(baseUrl)}?native=1`
  const response = new NextResponse(
    autoPostHtml({ baseUrl, provider, callbackUrl, mode }),
    { status: 200, headers: { 'content-type': 'text/html; charset=utf-8' } },
  )
  response.headers.append(
    'set-cookie',
    `helfi_native_oauth=1; Path=/; Max-Age=900; SameSite=Lax${baseUrl.startsWith('https://') ? '; Secure' : ''}`,
  )
  return response
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'

import { authOptions } from '@/lib/auth'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'
import { getNativeBillingCatalog } from '@/lib/native-billing/catalog'

async function isAuthorized(request: NextRequest): Promise<boolean> {
  const session = await getServerSession(authOptions)
  const sessionEmail = String(session?.user?.email || '').trim().toLowerCase()
  if (sessionEmail) return true

  const nativeUserId = await getUserIdFromNativeAuth(request)
  return !!nativeUserId
}

export async function GET(request: NextRequest) {
  try {
    const authorized = await isAuthorized(request)
    if (!authorized) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const catalog = getNativeBillingCatalog()
    return NextResponse.json(catalog)
  } catch (error: any) {
    return NextResponse.json(
      {
        error: 'Failed to load native billing catalog',
        message: error?.message || 'Unknown error',
      },
      { status: 500 },
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'

import { authOptions } from '@/lib/auth'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'
import { getNativeBillingCatalog } from '@/lib/native-billing/catalog'
import { ensureSubscriptionStoreColumns, subscriptionSourceLabel } from '@/lib/native-billing/subscription-store'
import { prisma } from '@/lib/prisma'

export const dynamic = 'force-dynamic'
export const revalidate = 0

type BillingUser = {
  id: string
  email: string
}

type BillingHistoryItem = {
  id: string
  type: 'subscription' | 'topup'
  title: string
  subtitle: string
  amountText: string
  status: string
  occurredAt: string
}

function centsToDollars(cents: number): string {
  return `$${(Math.max(0, cents) / 100).toFixed(2)}`
}

function normalizeTopUpCredits(value: number): number {
  const credits = Math.floor(Math.max(0, value))
  if (credits === 25000 || credits === 50000 || credits === 100000) {
    return Math.floor(credits / 100)
  }
  return credits
}

function topUpPriceText(credits: number): string {
  const normalizedCredits = normalizeTopUpCredits(credits)
  const product = getNativeBillingCatalog().products.find(
    (item) => item.kind === 'topup' && item.credits === normalizedCredits,
  )
  return product ? centsToDollars(product.priceCents) : `${normalizedCredits.toLocaleString()} credits`
}

function sourceLabel(source: string): string {
  const raw = source.trim().toLowerCase()
  if (!raw) return 'Unknown source'
  if (raw.startsWith('apple_iap:')) return 'Apple App Store'
  if (raw.startsWith('google_iap:')) return 'Google Play'
  if (raw.startsWith('cs_') || raw.includes('stripe')) return 'Stripe'
  if (raw.includes('admin')) return 'Admin'
  return 'Other source'
}

async function getBillingUser(request: NextRequest): Promise<BillingUser | null> {
