export async function GET(request: NextRequest) {
  try {
    const user = await getBillingUser(request)
    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const [subscription, topUps] = await Promise.all([
      ensureSubscriptionStoreColumns().then(() =>
      prisma.subscription.findUnique({
        where: { userId: user.id },
        select: {
          id: true,
          monthlyPriceCents: true,
          startDate: true,
          endDate: true,
          source: true,
        },
      })),
      prisma.creditTopUp.findMany({
        where: { userId: user.id },
        select: {
          id: true,
          amountCents: true,
          usedCents: true,
          purchasedAt: true,
          expiresAt: true,
          source: true,
        },
        orderBy: { purchasedAt: 'desc' },
        take: 60,
      }),
    ])

    const now = new Date()
    const items: BillingHistoryItem[] = []

    if (subscription?.startDate) {
      const amountCents = Number(subscription.monthlyPriceCents || 0)
      const isActive = !subscription.endDate || subscription.endDate > now
      items.push({
        id: `subscription-${subscription.id}`,
        type: 'subscription',
        title: 'Monthly subscription',
        subtitle: amountCents > 0
          ? `${centsToDollars(amountCents)} per month • ${subscriptionSourceLabel(subscription.source)}`
          : `Premium subscription • ${subscriptionSourceLabel(subscription.source)}`,
        amountText: amountCents > 0 ? centsToDollars(amountCents) : 'Premium',
        status: isActive ? 'Active' : 'Ended',
        occurredAt: subscription.startDate.toISOString(),
      })
    }

    for (const topUp of topUps) {
      const amountCents = Number(topUp.amountCents || 0)
      const credits = normalizeTopUpCredits(amountCents)
      const remaining = Math.max(0, amountCents - Number(topUp.usedCents || 0))
      const expired = topUp.expiresAt <= now
      const status = expired ? 'Expired' : remaining <= 0 ? 'Used' : 'Available'

      items.push({
        id: `topup-${topUp.id}`,
        type: 'topup',
        title: 'Credit top-up',
        subtitle: `${credits.toLocaleString()} credits • ${sourceLabel(String(topUp.source || ''))}`,
        amountText: topUpPriceText(amountCents),
        status,
        occurredAt: topUp.purchasedAt.toISOString(),
      })
    }

    items.sort((a, b) => new Date(b.occurredAt).getTime() - new Date(a.occurredAt).getTime())

    return NextResponse.json({
      ok: true,
      history: items,
    })
  } catch (error: any) {
    return NextResponse.json(
      {
        error: 'Failed to load billing history',
        message: error?.message || 'Unknown error',
      },
      { status: 500 },
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'

import { authOptions } from '@/lib/auth'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'
import { getNativeStoreProductId, type NativeBillingProductCode } from '@/lib/native-billing/catalog'

async function isAuthorized(request: NextRequest): Promise<boolean> {
  const session = await getServerSession(authOptions)
  const sessionEmail = String(session?.user?.email || '').trim().toLowerCase()
  if (sessionEmail) return true

  const nativeUserId = await getUserIdFromNativeAuth(request)
  return !!nativeUserId
}

export async function POST(request: NextRequest) {
  try {
    const authorized = await isAuthorized(request)
    if (!authorized) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const body = await request.json().catch(() => ({}))
    const platform = body?.platform === 'android' ? 'android' : body?.platform === 'ios' ? 'ios' : null
    const code = String(body?.code || '') as NativeBillingProductCode

    if (!platform) {
      return NextResponse.json({ error: 'Invalid platform. Use ios or android.' }, { status: 400 })
    }
    if (!code) {
      return NextResponse.json({ error: 'Missing product code.' }, { status: 400 })
    }

    const storeProductId = getNativeStoreProductId(platform, code)
    if (!storeProductId) {
      return NextResponse.json(
        {
          error: 'Store product not configured',
          message: `${platform === 'ios' ? 'Apple' : 'Google'} product ID is not set for ${code}.`,
        },
        { status: 400 },
      )
    }

    return NextResponse.json({
      ok: true,
      platform,
      code,
      storeProductId,
    })
  } catch (error: any) {
    return NextResponse.json(
      {
        error: 'Failed to prepare purchase',
        message: error?.message || 'Unknown error',
      },
      { status: 500 },
    )
  }
}

