import { NextRequest, NextResponse } from 'next/server'
import Stripe from 'stripe'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { buildGeoKey } from '@/lib/practitioner-utils'

const PRICE_BY_RADIUS: Record<string, number> = {
  R5: 500,
  R10: 1000,
  R25: 1500,
  R50: 2000,
}

const LABEL_BY_RADIUS: Record<string, string> = {
  R5: '5 km',
  R10: '10 km',
  R25: '25 km',
  R50: '50 km',
}

export async function POST(request: NextRequest) {
  const session = await getServerSession(authOptions)
  if (!session?.user?.id || !session.user.email) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const stripeSecretKey = process.env.STRIPE_SECRET_KEY
  if (!stripeSecretKey) {
    return NextResponse.json({ error: 'Payments are not configured yet.' }, { status: 500 })
  }

  const body = await request.json().catch(() => ({}))
  const radiusTier = String(body?.radiusTier || '').trim()
  const priceCents = PRICE_BY_RADIUS[radiusTier]
  const radiusLabel = LABEL_BY_RADIUS[radiusTier]

  if (!priceCents || !radiusLabel) {
    return NextResponse.json({ error: 'Invalid radius selection.' }, { status: 400 })
  }

  const listing = await prisma.practitionerListing.findFirst({
    where: {
      practitionerAccount: { userId: session.user.id },
      reviewStatus: 'APPROVED',
    },
  })

  if (!listing) {
    return NextResponse.json({ error: 'Listing not found or not approved yet.' }, { status: 404 })
  }

  if (listing.status !== 'ACTIVE') {
    return NextResponse.json({ error: 'Boosts are only available for active listings.' }, { status: 400 })
  }

  const geoKey = buildGeoKey({
    country: listing.country,
  })

  if (!geoKey) {
    return NextResponse.json({ error: 'Listing location is incomplete.' }, { status: 400 })
  }

  const stripe = new Stripe(stripeSecretKey, { apiVersion: '2024-06-20' })
  const origin = new URL(request.url).origin

  const checkoutSession = await stripe.checkout.sessions.create({
    mode: 'payment',
    line_items: [
      {
        price_data: {
          currency: 'usd',
          product_data: {
            name: `Helfi Boost (7 days) - ${radiusLabel}`,
          },
          unit_amount: priceCents,
        },
        quantity: 1,
      },
    ],
    success_url: `${origin}/practitioner?boost=success`,
    cancel_url: `${origin}/practitioner?boost=cancelled`,
    customer_email: session.user.email,
    metadata: {
      helfi_boost: '1',
      helfi_boost_listing_id: listing.id,
      helfi_boost_radius_tier: radiusTier,
      helfi_boost_geo_key: geoKey,
      helfi_boost_category_id: listing.categoryId,
      helfi_boost_price_cents: String(priceCents),
      helfi_boost_duration_days: '7',
    },
  })

  return NextResponse.json({ url: checkoutSession.url })
}

import { NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { sendPractitionerContactSummaryEmail } from '@/lib/practitioner-emails'

async function ensureAnalyticsTable() {
  await prisma.$executeRawUnsafe(`
    CREATE TABLE IF NOT EXISTS "AnalyticsEvent" (
      id TEXT PRIMARY KEY,
      "timestamp" TIMESTAMPTZ NOT NULL,
      "action" TEXT,
      "type" TEXT,
      "userId" TEXT,
      payload JSONB NOT NULL
    )
  `)
}

async function ensurePreferencesTable() {
  await prisma.$executeRawUnsafe(`
    CREATE TABLE IF NOT EXISTS "PractitionerNotificationPreference" (
      "practitionerAccountId" TEXT PRIMARY KEY,
      "weeklySummaryEnabled" BOOLEAN NOT NULL DEFAULT true,
      "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
      "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now()
    )
  `)
}

async function getWeeklySummaryEnabled(accountId: string): Promise<boolean> {
  await ensurePreferencesTable()
  const rows = await prisma.$queryRawUnsafe<Array<{ weeklySummaryEnabled: boolean }>>(
    `SELECT "weeklySummaryEnabled"
     FROM "PractitionerNotificationPreference"
     WHERE "practitionerAccountId" = $1`,
    accountId
  )
  if (!rows.length) return true
  return Boolean(rows[0].weeklySummaryEnabled)
}

export async function POST() {
  const session = await getServerSession(authOptions)
  if (!session?.user?.id) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const account = await prisma.practitionerAccount.findUnique({
    where: { userId: session.user.id },
    select: { id: true, contactEmail: true },
  })

  if (!account) {
    return NextResponse.json({ error: 'Account not found.' }, { status: 404 })
  }

  const weeklySummaryEnabled = await getWeeklySummaryEnabled(account.id)
  if (!weeklySummaryEnabled) {
    return NextResponse.json({ error: 'Weekly summary emails are turned off.' }, { status: 400 })
  }

  const listing = await prisma.practitionerListing.findFirst({
    where: { practitionerAccountId: account.id },
    select: { id: true, displayName: true, slug: true },
  })

  if (!listing) {
    return NextResponse.json({ error: 'Listing not found.' }, { status: 404 })
  }

  await ensureAnalyticsTable()

  const rangeEnd = new Date()
  const rangeStart = new Date(rangeEnd.getTime() - 7 * 24 * 60 * 60 * 1000)

  const rows = await prisma.$queryRawUnsafe<
    Array<{ action: string | null; timestamp: Date; payload: any }>
  >(
    `SELECT "action", "timestamp", payload
     FROM "AnalyticsEvent"
     WHERE "timestamp" >= $1 AND "type" = $2
     ORDER BY "timestamp" ASC`,
    rangeStart,
    'practitioner-contact'
  )

  const events = rows
    .map((row) => {
      const payload = typeof row.payload === 'string' ? JSON.parse(row.payload) : row.payload
      const listingId = String(payload?.listingId || '').trim()
      if (!listingId) return null
      return {
        listingId,
        action: row.action || payload?.action || '',
        timestamp: new Date(row.timestamp),
      }
    })
    .filter(Boolean)
    .filter((event: any) => event.listingId === listing.id) as Array<{ listingId: string; action: string; timestamp: Date }>

  if (!events.length) {
    return NextResponse.json({ sent: 0, events: 0, message: 'No recent activity yet.' })
  }

  await sendPractitionerContactSummaryEmail({
    toEmail: account.contactEmail,
    displayName: listing.displayName,
    slug: listing.slug,
    rangeStart,
    rangeEnd,
    events,
  })

  return NextResponse.json({ sent: 1, events: events.length })
}

import { NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'

function daysUntil(date: Date | null | undefined): number | null {
  if (!date) return null
  const diffMs = date.getTime() - Date.now()
  return Math.max(0, Math.ceil(diffMs / (1000 * 60 * 60 * 24)))
}

function hasUsedWinbackTrial(subscription: {
  trialStartAt: Date | null
  currentPeriodStart: Date | null
}) {
  if (!subscription.trialStartAt || !subscription.currentPeriodStart) return false
  const diffMs = subscription.currentPeriodStart.getTime() - subscription.trialStartAt.getTime()
  return diffMs > 1000 * 60 * 60 * 24
}

export async function GET() {
  const session = await getServerSession(authOptions)
  if (!session?.user?.id || !session.user.email) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const account = await prisma.practitionerAccount.findUnique({
    where: { userId: session.user.id },
  })

  if (!account) {
    return NextResponse.json({ account: null, listing: null })
  }

  const listing = await prisma.practitionerListing.findFirst({
    where: { practitionerAccountId: account.id },
    include: {
      category: true,
      subcategory: true,
      subscription: true,
    },
  })

  if (!listing) {
    return NextResponse.json({ account, listing: null })
  }

  const subscription = listing.subscription
  const trialEndsAt = subscription?.trialEndAt ? new Date(subscription.trialEndAt) : null
  const currentPeriodEnd = subscription?.currentPeriodEnd ? new Date(subscription.currentPeriodEnd) : null
  const trialStartAt = subscription?.trialStartAt ? new Date(subscription.trialStartAt) : null
  const currentPeriodStart = subscription?.currentPeriodStart ? new Date(subscription.currentPeriodStart) : null
  const trialHasEnded = trialEndsAt ? trialEndsAt.getTime() <= Date.now() : false
  const winbackUsed = subscription
    ? hasUsedWinbackTrial({ trialStartAt, currentPeriodStart })
    : false
  const winbackEligible = Boolean(
    subscription &&
    trialHasEnded &&
    !winbackUsed &&
    subscription.status !== 'ACTIVE' &&
    !subscription.providerSubscriptionId
  )

  return NextResponse.json({
    account,
    listing: {
      id: listing.id,
      displayName: listing.displayName,
      slug: listing.slug,
      status: listing.status,
      visibilityReason: listing.visibilityReason,
      reviewStatus: listing.reviewStatus,
      reviewNotes: listing.reviewNotes,
      reviewFlagReason: listing.reviewFlagReason,
      aiRiskLevel: listing.aiRiskLevel,
      aiReasoning: listing.aiReasoning,
      categoryName: listing.category?.name || null,
      subcategoryName: listing.subcategory?.name || null,
      serviceType: listing.serviceType,
      trialEndsAt,
      trialDaysLeft: daysUntil(trialEndsAt),
      subscriptionStatus: subscription?.status || null,
      stripeSubscriptionId: subscription?.providerSubscriptionId || null,
      subscriptionPeriodEnd: currentPeriodEnd,
      winbackEligible,
      winbackUsed,
    },
  })
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { Prisma } from '@prisma/client'
import { parseCommaList, normalizeUrl, geocodeAddress } from '@/lib/practitioner-utils'
import { validateBusinessRegistrationNumber } from '@/lib/practitioner-registration'

async function getListingForUser(listingId: string, userId: string) {
