export async function GET(request: NextRequest, { params }: { params: { id: string } }) {
  const session = await getServerSession(authOptions)
  if (!session?.user?.id) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const listing = await getListingForUser(params.id, session.user.id)
  if (!listing) {
    return NextResponse.json({ error: 'Listing not found.' }, { status: 404 })
  }

  return NextResponse.json({ listing })
}

export async function PUT(request: NextRequest, { params }: { params: { id: string } }) {
  const session = await getServerSession(authOptions)
  if (!session?.user?.id) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const listing = await getListingForUser(params.id, session.user.id)
  if (!listing) {
    return NextResponse.json({ error: 'Listing not found.' }, { status: 404 })
  }

  const body = await request.json().catch(() => ({}))
  const businessRegistrationNumber = body?.businessRegistrationNumber
    ? String(body.businessRegistrationNumber).trim()
    : listing.businessRegistrationNumber || ''

  const hasHoursNotes = Object.prototype.hasOwnProperty.call(body, 'hoursNotes')
  const hoursNotes = hasHoursNotes ? String(body?.hoursNotes || '').trim() : ''

  const addressParts = [
    body?.addressLine1,
    body?.addressLine2,
    body?.suburbCity,
    body?.stateRegion,
    body?.postcode,
    body?.country,
  ]
    .map((item) => (item ? String(item).trim() : ''))
    .filter(Boolean)
  const addressString = addressParts.join(', ')
  const providedLat = typeof body?.lat === 'number' ? body.lat : null
  const providedLng = typeof body?.lng === 'number' ? body.lng : null
  const geocoded =
    !providedLat && !providedLng && addressString ? await geocodeAddress(addressString) : null

  const registrationCheck = validateBusinessRegistrationNumber(
    businessRegistrationNumber,
    body?.country ?? listing.country
  )
  if (!registrationCheck.valid) {
    return NextResponse.json({ error: registrationCheck.error }, { status: 400 })
  }

  const updated = await prisma.practitionerListing.update({
    where: { id: listing.id },
    data: {
      displayName: body?.displayName ? String(body.displayName).trim() : listing.displayName,
      categoryId: body?.categoryId || listing.categoryId,
      subcategoryId: body?.subcategoryId || null,
      tags: parseCommaList(body?.tags),
      description: body?.description ? String(body.description).trim() : null,
      phone: body?.phone ? String(body.phone).trim() : null,
      websiteUrl: normalizeUrl(body?.websiteUrl || null),
      emailPublic: body?.emailPublic ? String(body.emailPublic).trim().toLowerCase() : null,
      businessRegistrationNumber: businessRegistrationNumber || null,
      addressLine1: body?.addressLine1 ? String(body.addressLine1).trim() : null,
      addressLine2: body?.addressLine2 ? String(body.addressLine2).trim() : null,
      suburbCity: body?.suburbCity ? String(body.suburbCity).trim() : null,
      stateRegion: body?.stateRegion ? String(body.stateRegion).trim() : null,
      postcode: body?.postcode ? String(body.postcode).trim() : null,
      country: body?.country ? String(body.country).trim() : null,
      lat: providedLat ?? geocoded?.lat ?? listing.lat ?? null,
      lng: providedLng ?? geocoded?.lng ?? listing.lng ?? null,
      serviceType: body?.serviceType || listing.serviceType,
      languages: parseCommaList(body?.languages),
      hoursJson: hasHoursNotes
        ? hoursNotes
          ? { notes: hoursNotes }
          : Prisma.JsonNull
        : undefined,
      images: body?.images ? body.images : null,
    },
  })

  return NextResponse.json({ listing: updated })
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import type { PractitionerAiRiskLevel } from '@prisma/client'
import { screenPractitionerListing } from '@/lib/practitioner-screening'
import { detectTestSignals, lookupPlaceMatch } from '@/lib/practitioner-review'
import { validateBusinessRegistrationNumber } from '@/lib/practitioner-registration'
import {
  sendPractitionerAdminActivatedEmail,
  sendPractitionerAdminFlaggedEmail,
  sendPractitionerApprovedEmail,
  sendPractitionerReviewEmail,
} from '@/lib/practitioner-emails'

function addMonths(date: Date, months: number): Date {
  const next = new Date(date)
  next.setUTCMonth(next.getUTCMonth() + months)
  return next
}

async function getListingForUser(listingId: string, userId: string) {
  return prisma.practitionerListing.findFirst({
    where: {
      id: listingId,
      practitionerAccount: { userId },
    },
    include: {
      practitionerAccount: true,
    },
  })
}

export async function POST(request: NextRequest, { params }: { params: { id: string } }) {
  const session = await getServerSession(authOptions)
  if (!session?.user?.id || !session.user.email) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const listing = await getListingForUser(params.id, session.user.id)
  if (!listing) {
    return NextResponse.json({ error: 'Listing not found.' }, { status: 404 })
  }

  if (listing.reviewStatus === 'APPROVED' && listing.status === 'ACTIVE') {
    return NextResponse.json({ error: 'Your listing is already approved.' }, { status: 400 })
  }

  const hasContact = Boolean(listing.phone || listing.websiteUrl || listing.emailPublic)
  const hasLocation = Boolean((listing.lat && listing.lng) || listing.suburbCity || listing.country)
  if (!hasContact || !hasLocation) {
    return NextResponse.json(
      { error: 'Please add contact details and a location before submitting.' },
      { status: 400 }
    )
  }

  const registrationCheck = validateBusinessRegistrationNumber(
    listing.businessRegistrationNumber,
    listing.country
  )
  if (!registrationCheck.valid) {
    return NextResponse.json({ error: registrationCheck.error }, { status: 400 })
  }

  await prisma.practitionerListing.update({
    where: { id: listing.id },
    data: {
      status: 'PENDING_REVIEW',
      visibilityReason: 'AI_REVIEW_PENDING',
      reviewStatus: 'PENDING',
      reviewDecisionAt: null,
      reviewFlagReason: null,
    },
  })

  const category = await prisma.practitionerCategory.findUnique({ where: { id: listing.categoryId } })
  const subcategory = listing.subcategoryId
    ? await prisma.practitionerCategory.findUnique({ where: { id: listing.subcategoryId } })
    : null

  const hasCoordinates = Boolean(listing.lat && listing.lng)
  const hasFullAddress = Boolean(listing.addressLine1 && listing.suburbCity && listing.country)
  const hasPhone = Boolean(listing.phone)
  const hasWebsite = Boolean(listing.websiteUrl)
  const hasPublicEmail = Boolean(listing.emailPublic)

  const addressString = [listing.addressLine1, listing.suburbCity, listing.stateRegion, listing.postcode, listing.country]
    .filter(Boolean)
    .join(', ')

  const testSignals = detectTestSignals({
    displayName: listing.displayName,
    description: listing.description,
    websiteUrl: listing.websiteUrl,
    emailPublic: listing.emailPublic,
    phone: listing.phone,
    tags: listing.tags,
    address: addressString,
  })

  const placeMatch = await lookupPlaceMatch({
    displayName: listing.displayName,
    address: addressString,
    categoryName: category?.name || null,
    subcategoryName: subcategory?.name || null,
    categorySynonyms: category?.synonyms || [],
    subcategorySynonyms: subcategory?.synonyms || [],
  })

  const manualReviewReasons: string[] = []
  if (testSignals.length > 0) {
    manualReviewReasons.push(...testSignals)
  }
  if (placeMatch.status === 'NOT_FOUND') {
    manualReviewReasons.push('No Google business listing found for the name/address.')
  }
  if (placeMatch.status === 'MISMATCH') {
    manualReviewReasons.push(placeMatch.reason)
  }
  if (placeMatch.status === 'UNKNOWN' && placeMatch.reason === 'Google returned only generic place types.') {
    manualReviewReasons.push('Google does not show this address as a business listing.')
  }

  let screening
  try {
    if (manualReviewReasons.length > 0) {
      screening = {
        riskLevel: 'MEDIUM',
        recommendedAction: 'MANUAL_REVIEW',
        reasoning: 'Listing requires manual review based on verification checks.',
        redFlags: manualReviewReasons,
        raw: { manualReviewReasons, placeMatch },
      }
    } else {
      screening = await screenPractitionerListing({
        listingId: listing.id,
        displayName: listing.displayName,
        description: listing.description,
        websiteUrl: listing.websiteUrl,
        phone: listing.phone,
        emailPublic: listing.emailPublic,
        address: addressString,
        category: category?.name || null,
        subcategory: subcategory?.name || null,
        tags: listing.tags,
        languages: listing.languages,
        hasCoordinates,
        hasFullAddress,
        hasPhone,
        hasWebsite,
        hasPublicEmail,
        placeMatch: {
          status: placeMatch.status,
          reason: placeMatch.reason,
          placeName: placeMatch.placeName || null,
          placeTypes: placeMatch.placeTypes || [],
          businessStatus: placeMatch.businessStatus || null,
        },
        testSignals,
      })
    }
  } catch (error: any) {
    screening = {
      riskLevel: 'MEDIUM',
      recommendedAction: 'MANUAL_REVIEW',
      reasoning: 'Automatic review failed; manual review required.',
      raw: { error: error?.message || 'Screening error' },
    }
  }

  const aiRiskLevel = screening.riskLevel as PractitionerAiRiskLevel
  const aiReasoning = screening.reasoning
  const aiRawJson = screening.raw || null
  const needsManualReview =
    manualReviewReasons.length > 0 || screening.recommendedAction === 'MANUAL_REVIEW' || aiRiskLevel !== 'LOW'

  if (needsManualReview) {
    const updated = await prisma.practitionerListing.update({
      where: { id: listing.id },
      data: {
        status: 'HIDDEN',
        visibilityReason: 'AI_FLAGGED',
        reviewStatus: 'FLAGGED',
        reviewFlagReason: screening.redFlags?.join('\n') || null,
        reviewDecisionAt: new Date(),
        aiRiskLevel,
        aiReasoning,
        aiRawJson,
      },
    })

    await prisma.practitionerModerationLog.create({
      data: {
        listingId: listing.id,
        action: 'HIDE',
        reason: `Flagged by AI: ${aiReasoning}`,
      },
    })

    sendPractitionerReviewEmail({
      practitionerAccountId: listing.practitionerAccountId,
      listingId: listing.id,
      toEmail: listing.practitionerAccount.contactEmail,
      displayName: listing.displayName,
    })
    sendPractitionerAdminFlaggedEmail({
      listingId: listing.id,
      displayName: listing.displayName,
      riskLevel: aiRiskLevel,
      reasoning: aiReasoning,
    })

    return NextResponse.json({ listing: updated, reviewStatus: 'FLAGGED' })
  }

  const now = new Date()
  const trialEnd = addMonths(now, 6)

  const updated = await prisma.practitionerListing.update({
    where: { id: listing.id },
    data: {
      status: 'ACTIVE',
      visibilityReason: 'TRIAL_ACTIVE',
      reviewStatus: 'APPROVED',
      reviewDecisionAt: new Date(),
      aiRiskLevel,
      aiReasoning,
      aiRawJson,
    },
  })

  await prisma.practitionerListingSubscription.upsert({
    where: { listingId: listing.id },
    create: {
      listingId: listing.id,
      status: 'TRIALING',
      trialStartAt: now,
      trialEndAt: trialEnd,
      currentPeriodStart: now,
      currentPeriodEnd: trialEnd,
    },
    update: {
      status: 'TRIALING',
      trialStartAt: now,
      trialEndAt: trialEnd,
      currentPeriodStart: now,
      currentPeriodEnd: trialEnd,
    },
  })

  await prisma.practitionerModerationLog.create({
    data: {
      listingId: listing.id,
      action: 'APPROVE',
      reason: 'Auto-approved by AI',
    },
  })

  sendPractitionerApprovedEmail({
    practitionerAccountId: listing.practitionerAccountId,
    listingId: listing.id,
    toEmail: listing.practitionerAccount.contactEmail,
    displayName: listing.displayName,
    slug: updated.slug,
  })
  sendPractitionerAdminActivatedEmail({
    listingId: listing.id,
    displayName: listing.displayName,
    slug: updated.slug,
  })

  return NextResponse.json({ listing: updated, reviewStatus: 'APPROVED' })
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { parseCommaList, slugify, normalizeUrl, geocodeAddress } from '@/lib/practitioner-utils'
import { validateBusinessRegistrationNumber } from '@/lib/practitioner-registration'

async function ensurePractitionerAccount(userId: string, email: string) {
  let account = await prisma.practitionerAccount.findUnique({ where: { userId } })
  if (!account) {
    account = await prisma.practitionerAccount.create({
      data: {
        userId,
        contactEmail: email.toLowerCase(),
      },
    })
  }
  return account
}

async function generateUniqueSlug(base: string) {
  const normalized = slugify(base)
  if (!normalized) return `listing-${Date.now()}`

  const existing = await prisma.practitionerListing.findFirst({ where: { slug: normalized } })
  if (!existing) return normalized

  let counter = 2
  while (true) {
    const candidate = `${normalized}-${counter}`
    const taken = await prisma.practitionerListing.findFirst({ where: { slug: candidate } })
    if (!taken) return candidate
    counter += 1
  }
}

export async function POST(request: NextRequest) {
  const session = await getServerSession(authOptions)
  if (!session?.user?.id || !session.user.email) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const body = await request.json().catch(() => ({}))
  const displayName = String(body?.displayName || '').trim()
  const categoryId = String(body?.categoryId || '').trim()
  const businessRegistrationNumber = body?.businessRegistrationNumber
    ? String(body.businessRegistrationNumber).trim()
    : ''

  if (!displayName || !categoryId) {
    return NextResponse.json({ error: 'Display name and category are required.' }, { status: 400 })
  }

  const registrationCheck = validateBusinessRegistrationNumber(businessRegistrationNumber, body?.country)
  if (!registrationCheck.valid) {
    return NextResponse.json({ error: registrationCheck.error }, { status: 400 })
  }

  const account = await ensurePractitionerAccount(session.user.id, session.user.email)
  const existingListing = await prisma.practitionerListing.findFirst({
    where: { practitionerAccountId: account.id },
  })

  if (existingListing) {
    return NextResponse.json({ error: 'You already have a listing.' }, { status: 400 })
  }

  const slug = await generateUniqueSlug(displayName)
  const hoursNotes = String(body?.hoursNotes || '').trim()
  const addressParts = [
    body?.addressLine1,
    body?.addressLine2,
    body?.suburbCity,
    body?.stateRegion,
    body?.postcode,
    body?.country,
  ]
    .map((item) => (item ? String(item).trim() : ''))
    .filter(Boolean)
  const addressString = addressParts.join(', ')
  const providedLat = typeof body?.lat === 'number' ? body.lat : null
  const providedLng = typeof body?.lng === 'number' ? body.lng : null
  const geocoded = !providedLat && !providedLng && addressString ? await geocodeAddress(addressString) : null

  const listing = await prisma.practitionerListing.create({
    data: {
      practitionerAccountId: account.id,
      displayName,
      slug,
      categoryId,
      subcategoryId: body?.subcategoryId || null,
      tags: parseCommaList(body?.tags),
      description: body?.description ? String(body.description).trim() : null,
      phone: body?.phone ? String(body.phone).trim() : null,
      websiteUrl: normalizeUrl(body?.websiteUrl || null),
      emailPublic: body?.emailPublic ? String(body.emailPublic).trim().toLowerCase() : null,
      businessRegistrationNumber: businessRegistrationNumber || null,
      addressLine1: body?.addressLine1 ? String(body.addressLine1).trim() : null,
      addressLine2: body?.addressLine2 ? String(body.addressLine2).trim() : null,
      suburbCity: body?.suburbCity ? String(body.suburbCity).trim() : null,
      stateRegion: body?.stateRegion ? String(body.stateRegion).trim() : null,
      postcode: body?.postcode ? String(body.postcode).trim() : null,
      country: body?.country ? String(body.country).trim() : null,
      lat: providedLat ?? geocoded?.lat ?? null,
      lng: providedLng ?? geocoded?.lng ?? null,
      serviceType: body?.serviceType || 'IN_PERSON',
      languages: parseCommaList(body?.languages),
      hoursJson: hoursNotes ? { notes: hoursNotes } : undefined,
      images: body?.images ? body.images : null,
      status: 'DRAFT',
      reviewStatus: 'PENDING',
    },
  })

  return NextResponse.json({ listing })
}

