export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.email) {
      return NextResponse.json({ error: 'Not authenticated' }, { status: 401 })
    }

    // NextRequest.formData() returns a standard web FormData, but type
    // definitions can vary between runtimes and cause build-time TS errors.
    // Cast to `any` here to preserve runtime behavior without changing logic.
    const formData: any = await request.formData()
    const imageFile = formData.get('image')
    const kind = String(formData.get('kind') || '').trim() || 'listing'

    if (!(imageFile instanceof File)) {
      return NextResponse.json({ error: 'No image file provided' }, { status: 400 })
    }

    if (!imageFile.type.startsWith('image/')) {
      return NextResponse.json({ error: 'File must be an image' }, { status: 400 })
    }

    if (imageFile.size > MAX_BYTES) {
      return NextResponse.json({ error: 'File size must be less than 8MB' }, { status: 400 })
    }

    const user = await prisma.user.findUnique({
      where: { email: session.user.email },
      select: { id: true },
    })

    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    const imageBuffer = await imageFile.arrayBuffer()
    const buffer = Buffer.from(imageBuffer)

    const uploadResult = await new Promise((resolve, reject) => {
      cloudinary.uploader.upload_stream(
        {
          resource_type: 'image',
          folder: `helfi/practitioner-listings/${kind}`,
          public_id: `listing_${user.id}_${Date.now()}`,
          transformation: [{ quality: 'auto', fetch_format: 'auto' }],
          invalidate: true,
        },
        (error, result) => {
          if (error) {
            reject(error)
          } else {
            resolve(result)
          }
        }
      ).end(buffer)
    })

    const cloudinaryResult = uploadResult as any

    const fileRecord = await prisma.file.create({
      data: {
        originalName: imageFile.name,
        fileName: cloudinaryResult.public_id,
        fileSize: cloudinaryResult.bytes,
        mimeType: imageFile.type,
        cloudinaryId: cloudinaryResult.public_id,
        cloudinaryUrl: cloudinaryResult.url,
        secureUrl: cloudinaryResult.secure_url,
        uploadedById: user.id,
        fileType: 'IMAGE',
        usage: 'OTHER',
        isPublic: true,
        metadata: {
          source: 'practitioner_listing',
          kind,
          width: cloudinaryResult.width,
          height: cloudinaryResult.height,
          format: cloudinaryResult.format,
        },
      },
    })

    return NextResponse.json({
      success: true,
      url: cloudinaryResult.secure_url,
      fileId: fileRecord.id,
    })
  } catch (error) {
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Upload failed' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { geocodeAddress } from '@/lib/practitioner-utils'
import { createTrackingToken } from '@/lib/practitioner-tracking'

export async function GET(request: NextRequest, { params }: { params: { slug: string } }) {
  const listing = await prisma.practitionerListing.findFirst({
    where: {
      slug: params.slug,
      status: 'ACTIVE',
      reviewStatus: 'APPROVED',
      visibilityReason: { in: ['TRIAL_ACTIVE', 'SUB_ACTIVE'] },
    },
    include: {
      category: true,
      subcategory: true,
    },
  })

  if (!listing) {
    return NextResponse.json({ error: 'Listing not found.' }, { status: 404 })
  }

  if (!listing.lat || !listing.lng) {
    const address = [
      listing.addressLine1,
      listing.addressLine2,
      listing.suburbCity,
      listing.stateRegion,
      listing.postcode,
      listing.country,
    ]
      .filter(Boolean)
      .join(', ')
    const geocoded = address ? await geocodeAddress(address) : null
    if (geocoded?.lat && geocoded?.lng) {
      const updated = await prisma.practitionerListing.update({
        where: { id: listing.id },
        data: { lat: geocoded.lat, lng: geocoded.lng },
      })
      listing.lat = updated.lat
      listing.lng = updated.lng
    }
  }

  return NextResponse.json({
    listing: {
      id: listing.id,
      displayName: listing.displayName,
      slug: listing.slug,
      description: listing.description,
      phone: listing.phone,
      websiteUrl: listing.websiteUrl,
      emailPublic: listing.emailPublic,
      addressLine1: listing.addressLine1,
      addressLine2: listing.addressLine2,
      suburbCity: listing.suburbCity,
      stateRegion: listing.stateRegion,
      postcode: listing.postcode,
      country: listing.country,
      lat: listing.lat,
      lng: listing.lng,
      serviceType: listing.serviceType,
      languages: listing.languages,
      tags: listing.tags,
      hours: listing.hoursJson,
      images: listing.images,
      categoryName: listing.category?.name || null,
      subcategoryName: listing.subcategory?.name || null,
      trackingToken: createTrackingToken(listing.id),
    },
  })
}

