import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { calculateDistanceKm } from '@/lib/practitioner-utils'
import { createTrackingToken } from '@/lib/practitioner-tracking'

function normalize(value: string | null | undefined): string {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

const WORD_EQUIVALENTS: Record<string, string> = {
  sore: 'pain',
  aching: 'pain',
  ache: 'pain',
  hurts: 'pain',
  hurt: 'pain',
  feet: 'foot',
}

function compact(value: string | null | undefined): string {
  return normalize(value).replace(/\s+/g, '')
}

function normalizeWord(word: string): string {
  const mapped = WORD_EQUIVALENTS[word] || word
  if (mapped.endsWith('s') && mapped.length > 3) return mapped.slice(0, -1)
  return mapped
}

function tokenize(value: string | null | undefined): string[] {
  return normalize(value)
    .split(' ')
    .filter(Boolean)
    .map(normalizeWord)
}

function matchesQueryText(source: string | null | undefined, query: string): boolean {
  const normalizedSource = normalize(source)
  if (!normalizedSource || !query) return false

  if (normalizedSource.includes(query) || query.includes(normalizedSource)) return true

  const compactSource = compact(source)
  const compactQuery = compact(query)
  if (compactSource.includes(compactQuery) || compactQuery.includes(compactSource)) return true

  const sourceTokens = tokenize(source)
  const queryTokens = tokenize(query)
  if (!sourceTokens.length || !queryTokens.length) return false
  return queryTokens.every((token) => sourceTokens.includes(token))
}

function deriveRadiusTier(radiusKm: number) {
  if (radiusKm <= 5) return 'R5'
  if (radiusKm <= 10) return 'R10'
  if (radiusKm <= 25) return 'R25'
  return 'R50'
}

function computeQualityScore(listing: any) {
  let score = 0
  const images = listing.images as any
  if (images?.logoUrl) score += 1
  if (listing.description) score += 1
  if (listing.hoursJson) score += 1
  if (listing.websiteUrl) score += 1
  if (listing.emailPublic) score += 1
  return score
}

export async function GET(request: NextRequest) {
  const url = new URL(request.url)
  const categoryId = url.searchParams.get('categoryId') || undefined
  const subcategoryId = url.searchParams.get('subcategoryId') || undefined
  const query = normalize(url.searchParams.get('q'))
  const latParam = url.searchParams.get('lat')
  const lngParam = url.searchParams.get('lng')
  const lat = latParam ? Number(latParam) : Number.NaN
  const lng = lngParam ? Number(lngParam) : Number.NaN
  const radiusKm = Number(url.searchParams.get('radiusKm') || 10)
  const telehealthOnly = url.searchParams.get('telehealth') === 'true'
  const geoKey = url.searchParams.get('geoKey') || undefined

  const where: any = {
    status: 'ACTIVE',
    reviewStatus: 'APPROVED',
    visibilityReason: { in: ['TRIAL_ACTIVE', 'SUB_ACTIVE'] },
  }
  if (categoryId) {
    where.categoryId = categoryId
  }
  if (subcategoryId) {
    where.subcategoryId = subcategoryId
  }

  const listings = await prisma.practitionerListing.findMany({
    where,
    include: {
      category: true,
      subcategory: true,
    },
  })

  const categories = await prisma.practitionerCategory.findMany({
    select: { id: true, name: true, synonyms: true },
  })
  const synonymsMap = new Map<string, string[]>()
  categories.forEach((cat) => {
    synonymsMap.set(cat.id, (cat.synonyms || []).map((syn) => normalize(syn)))
  })

  let filtered = listings

  if (telehealthOnly) {
    filtered = filtered.filter((listing) => listing.serviceType === 'TELEHEALTH' || listing.serviceType === 'BOTH')
  }

  if (query) {
    filtered = filtered.filter((listing) => {
      const textValues = [
        listing.displayName,
        listing.description,
        listing.category?.name,
        listing.subcategory?.name,
        ...(listing.tags || []),
      ]
      const textMatch = textValues.some((value) => matchesQueryText(value, query))
      if (textMatch) return true
      const categorySynonyms = synonymsMap.get(listing.categoryId) || []
      const subcategorySynonyms = listing.subcategoryId ? synonymsMap.get(listing.subcategoryId) || [] : []
      return [...categorySynonyms, ...subcategorySynonyms].some((syn) => matchesQueryText(syn, query))
    })
  }

  const hasLocation = Number.isFinite(lat) && Number.isFinite(lng)
  const center = hasLocation ? { lat, lng } : null

  const withDistance = filtered
    .map((listing) => {
      if (!center || listing.lat == null || listing.lng == null) {
        return { listing, distanceKm: null }
      }
      const distanceKm = calculateDistanceKm(
        { lat: center.lat, lng: center.lng },
        { lat: listing.lat, lng: listing.lng }
      )
      return { listing, distanceKm }
    })
    .filter((item) => {
      if (!center || item.distanceKm == null) return true
      return item.distanceKm <= radiusKm
    })

  const boostTier = deriveRadiusTier(radiusKm)
  const now = new Date()
  let boostedIds: string[] = []
  let topBoostId: string | null = null

  if (categoryId && geoKey) {
    const boosts = await prisma.practitionerBoostPurchase.findMany({
      where: {
        categoryId,
        geoKey,
        radiusTier: boostTier,
        status: 'ACTIVE',
        startsAt: { lte: now },
        endsAt: { gte: now },
      },
    })

    const eligibleBoostIds = boosts.map((boost) => boost.listingId)
    boostedIds = eligibleBoostIds.filter((id) => withDistance.some((item) => item.listing.id === id))

    if (boostedIds.length) {
      boostedIds.sort()
      const bucketKey = `${categoryId}|${geoKey}|${boostTier}`
      const rotation = await prisma.practitionerBoostRotationState.findUnique({ where: { bucketKey } })
      const lastIndex = rotation?.lastServedListingId
        ? boostedIds.indexOf(rotation.lastServedListingId)
        : -1
      const nextIndex = (lastIndex + 1) % boostedIds.length
      topBoostId = boostedIds[nextIndex]

      await prisma.practitionerBoostRotationState.upsert({
        where: { bucketKey },
        create: {
          bucketKey,
          lastServedListingId: topBoostId,
          lastServedAt: new Date(),
        },
        update: {
          lastServedListingId: topBoostId,
          lastServedAt: new Date(),
        },
      })
    }
  }

  const boostedSet = new Set(boostedIds)
  const boostedListings = withDistance
    .filter((item) => boostedSet.has(item.listing.id))
    .sort((a, b) => {
      if (a.listing.id === topBoostId) return -1
      if (b.listing.id === topBoostId) return 1
      return a.listing.id.localeCompare(b.listing.id)
    })

  const nonBoostedListings = withDistance
    .filter((item) => !boostedSet.has(item.listing.id))
    .sort((a, b) => {
      const distanceA = a.distanceKm ?? Number.MAX_SAFE_INTEGER
      const distanceB = b.distanceKm ?? Number.MAX_SAFE_INTEGER
      if (distanceA !== distanceB) return distanceA - distanceB
      const scoreA = computeQualityScore(a.listing)
      const scoreB = computeQualityScore(b.listing)
      return scoreB - scoreA
    })

  const ordered = [...boostedListings, ...nonBoostedListings]

  const results = ordered.map((item) => ({
    id: item.listing.id,
    displayName: item.listing.displayName,
    slug: item.listing.slug,
    categoryName: item.listing.category?.name || null,
    subcategoryName: item.listing.subcategory?.name || null,
    description: item.listing.description,
    phone: item.listing.phone,
    websiteUrl: item.listing.websiteUrl,
    emailPublic: item.listing.emailPublic,
    addressLine1: item.listing.addressLine1,
    suburbCity: item.listing.suburbCity,
    stateRegion: item.listing.stateRegion,
    country: item.listing.country,
    lat: item.listing.lat,
    lng: item.listing.lng,
    serviceType: item.listing.serviceType,
    distanceKm: item.distanceKm,
    isBoosted: boostedSet.has(item.listing.id),
    isTopBoost: topBoostId === item.listing.id,
    trackingToken: createTrackingToken(item.listing.id),
  }))

  return NextResponse.json({
    results,
    center,
    radiusKm,
    boostTier,
  })
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import webpush from 'web-push'
import { scheduleAllActiveReminders, scheduleReminderWithQStash } from '@/lib/qstash'
import { dedupeSubscriptions, normalizeSubscriptionList, removeSubscriptionsByEndpoint, sendToSubscriptions } from '@/lib/push-subscriptions'
import { isSchedulerAuthorized } from '@/lib/scheduler-auth'
import { createInboxNotification } from '@/lib/notification-inbox'
import { isSubscriptionActive } from '@/lib/subscription-utils'
import { ensureCheckinTables } from '@/app/api/checkins/_db'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

type DispatchPayload = {
  userId: string
  reminderTime: string // "HH:MM"
  timezone: string
}

export async function POST(req: NextRequest) {
  try {
    if (!isSchedulerAuthorized(req)) {
      return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
    }

    const body = (await req.json().catch(() => ({}))) as Partial<DispatchPayload>
    const userId = String(body.userId || '')
    const reminderTime = String(body.reminderTime || '')
    const timezone = String(body.timezone || '')
    if (!userId || !reminderTime || !timezone) {
      return NextResponse.json({ error: 'invalid_payload' }, { status: 400 })
    }

    await ensureCheckinTables()

    // Ensure subscription exists
    // await prisma.$executeRawUnsafe(`
    //   CREATE TABLE IF NOT EXISTS PushSubscriptions (
    //     userId TEXT PRIMARY KEY,
    //     subscription JSONB NOT NULL
    //   )
    // `)
    const rows: Array<{ subscription: any }> = await prisma.$queryRawUnsafe(
      `SELECT subscription FROM PushSubscriptions WHERE userId = $1`,
      userId
    )
    if (!rows.length) {
      return NextResponse.json({ error: 'no_subscription' }, { status: 400 })
    }
    const subscriptions = dedupeSubscriptions(normalizeSubscriptionList(rows[0].subscription))
    if (!subscriptions.length) {
      return NextResponse.json({ error: 'no_subscription' }, { status: 400 })
    }

    // Load the latest reminder settings for this user to validate stale schedules
    // await prisma.$executeRawUnsafe(`
    //   CREATE TABLE IF NOT EXISTS CheckinSettings (
    //     userId TEXT PRIMARY KEY,
    //     time1 TEXT NOT NULL,
    //     time2 TEXT NOT NULL,
    //     time3 TEXT NOT NULL,
    //     timezone TEXT NOT NULL,
    //     frequency INTEGER NOT NULL DEFAULT 3
    //   )
    // `)
    const settingsRows: Array<{ enabled: boolean; time1: string; time2: string; time3: string; time4: string | null; timezone: string; frequency: number | null }> =
      await prisma.$queryRawUnsafe(
        `SELECT enabled, time1, time2, time3, time4, timezone, frequency FROM CheckinSettings WHERE userId = $1`,
        userId
      )
    const settings = settingsRows[0]
    if (settings && settings.enabled === false) {
      return NextResponse.json({ skipped: 'disabled' })
    }
    const user = await prisma.user.findUnique({
      where: { id: userId },
      include: { subscription: true, creditTopUps: true },
    })
    const paidCheckNow = new Date()
    const hasSubscription = isSubscriptionActive(user?.subscription, paidCheckNow)
    const hasPurchasedCredits = (user?.creditTopUps || []).some(
      (topUp: any) => topUp.expiresAt > paidCheckNow && (topUp.amountCents - topUp.usedCents) > 0
    )
    const maxFrequency = (hasSubscription || hasPurchasedCredits) ? 4 : 1
    const resolvedFrequency = Math.max(1, Math.min(maxFrequency, settings?.frequency ?? 3))
    const activeTimes: string[] = []
    if (resolvedFrequency >= 1 && settings?.time1) activeTimes.push(settings.time1)
    if (resolvedFrequency >= 2 && settings?.time2) activeTimes.push(settings.time2)
    if (resolvedFrequency >= 3 && settings?.time3) activeTimes.push(settings.time3)
    if (resolvedFrequency >= 4 && settings?.time4) activeTimes.push(settings.time4)
    const timezoneToUse = settings?.timezone || timezone

    const reminderStillActive = settings ? activeTimes.includes(reminderTime) : true
    const timezoneStillMatches = settings ? settings.timezone === timezone : true

    if (!reminderStillActive || !timezoneStillMatches) {
      console.log('[DISPATCH] Skipping stale reminder job', {
        userId,
        reminderTime,
        incomingTimezone: timezone,
        latestTimezone: settings?.timezone,
        activeTimes,
        reason: reminderStillActive ? 'timezone_changed' : 'time_removed',
      })
      if (settings) {
        try {
          await scheduleAllActiveReminders(userId, {
            time1: settings.time1,
            time2: settings.time2,
            time3: settings.time3,
            time4: settings.time4,
            timezone: settings.timezone,
            frequency: resolvedFrequency,
          })
        } catch (err) {
          console.error('[DISPATCH] Failed to reschedule active reminders after stale job', err)
        }
      }
      return NextResponse.json({ skipped: 'stale_schedule' })
    }

    const publicKey = process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY || ''
    const privateKey = process.env.VAPID_PRIVATE_KEY || ''
    if (!publicKey || !privateKey) {
      return NextResponse.json({ error: 'vapid_not_configured' }, { status: 500 })
    }
    webpush.setVapidDetails('mailto:support@helfi.ai', publicKey, privateKey)

    // Delivery log table for de-duplication
    // await prisma.$executeRawUnsafe(`
    //   CREATE TABLE IF NOT EXISTS ReminderDeliveryLog (
    //     userId TEXT NOT NULL,
    //     reminderTime TEXT NOT NULL,
    //     sentDate DATE NOT NULL,
    //     sentAt TIMESTAMP NOT NULL DEFAULT NOW(),
    //     PRIMARY KEY (userId, reminderTime, sentDate)
    //   )
    // `)

    // Compute local date for de-dup (based on the user's tz)
    const now = new Date()
    const effectiveTimezone = timezoneToUse || 'UTC'
    const dateParts = new Intl.DateTimeFormat('en-GB', {
      timeZone: effectiveTimezone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    }).formatToParts(now)
    const localDate = `${dateParts.find(p => p.type==='year')?.value}-${dateParts.find(p=>p.type==='month')?.value}-${dateParts.find(p=>p.type==='day')?.value}`

    const claim: Array<{ userId: string }> = await prisma.$queryRawUnsafe(
      `INSERT INTO ReminderDeliveryLog (userId, reminderTime, sentDate, sentAt)
       VALUES ($1, $2, $3::date, NOW())
       ON CONFLICT (userId, reminderTime, sentDate) DO NOTHING
       RETURNING userId`,
      userId,
      reminderTime,
      localDate
    )
    if (!claim.length) {
      return NextResponse.json({ skipped: 'already_sent' })
    }

    // Send push
    const payload = JSON.stringify({
      title: 'Time for your Helfi check‑in',
      body: 'Rate your selected issues for today in under a minute.',
      url: '/check-in?new=1',
    })
    const { sent, errors, goneEndpoints } = await sendToSubscriptions(subscriptions, (sub) =>
      webpush.sendNotification(sub, payload)
    )
    if (goneEndpoints.length) {
      const remaining = removeSubscriptionsByEndpoint(subscriptions, goneEndpoints)
      await prisma.$executeRawUnsafe(
        `UPDATE PushSubscriptions SET subscription = $2::jsonb, updatedAt = NOW() WHERE userId = $1`,
        userId,
        JSON.stringify(remaining)
      )
    }
    if (!sent) {
      await prisma.$executeRawUnsafe(
        `DELETE FROM ReminderDeliveryLog WHERE userId = $1 AND reminderTime = $2 AND sentDate = $3::date`,
        userId,
        reminderTime,
        localDate
      ).catch(() => {})
      return NextResponse.json({ error: 'push_failed', details: errors }, { status: 500 })
    }

    await createInboxNotification({
      userId,
      title: 'Time for your Helfi check-in',
      body: 'Rate your selected issues for today in under a minute.',
      url: '/check-in?new=1',
      type: 'checkin_reminder',
      source: 'push',
      eventKey: `checkin:${localDate}:${reminderTime}`,
    }).catch(() => {})

    // Schedule the next occurrence for this same reminder
    const nextSchedule = await scheduleReminderWithQStash(userId, reminderTime, effectiveTimezone).catch((error) => {
      console.error('[DISPATCH] Failed to schedule next reminder via QStash', error)
      return { scheduled: false, reason: 'exception' }
    })
    if (!nextSchedule?.scheduled) {
      console.error('[DISPATCH] QStash scheduling returned failure', {
        userId,
        reminderTime,
        timezone,
        reason: nextSchedule?.reason,
      })
    }

    return NextResponse.json({ ok: true })
  } catch (e: any) {
    console.error('[DISPATCH] error', e?.stack || e)
    return NextResponse.json({ error: 'dispatch_error', message: e?.message || String(e) }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import webpush from 'web-push'
import crypto from 'crypto'
import { CreditManager } from '@/lib/credit-system'
import { scheduleHealthTipWithQStash } from '@/lib/qstash'
import {
  dedupeSubscriptions,
  normalizeSubscriptionList,
  removeSubscriptionsByEndpoint,
  sendToSubscriptions,
} from '@/lib/push-subscriptions'
import { createInboxNotification } from '@/lib/notification-inbox'
import { ensureHealthTipTables } from '@/lib/health-tips'
import { isSchedulerAuthorized } from '@/lib/scheduler-auth'
import {
  SMART_COACH_ALERT_COST_CREDITS,
  SMART_COACH_AUTO_CHECK_TIMES,
  SMART_COACH_CATEGORY_COOLDOWN_MINUTES,
  SMART_COACH_DAILY_CAP_CREDITS,
  SMART_COACH_DAILY_MAX_ALERTS,
  SMART_COACH_GLOBAL_COOLDOWN_MINUTES,
  SMART_COACH_MESSAGE_COOLDOWN_MINUTES,
  SMART_COACH_RULE_COOLDOWN_MINUTES,
  ensureSmartCoachTables,
  evaluateSmartCoachRule,
  getLocalDateTime,
  getSmartCoachQuietHours,
  isWithinQuietHours,
  logSmartCoachDecision,
  type SmartCoachBlockReason,
} from '@/lib/smart-health-coach'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

type DispatchPayload = {
  userId: string
  reminderTime: string
  timezone: string
}

function getPushKeys() {
  const publicKey = process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY || ''
  const privateKey = process.env.VAPID_PRIVATE_KEY || ''
  return { publicKey, privateKey, hasKeys: !!publicKey && !!privateKey }
}

async function scheduleNextReminder(userId: string, reminderTime: string, timezone: string) {
  await scheduleHealthTipWithQStash(userId, reminderTime, timezone).catch((error) => {
    console.error('[SMART_COACH] Failed to schedule next run', error)
  })
}

async function claimDispatchWindow(params: {
  userId: string
  localDate: string
  reminderTime: string
}) {
  await prisma.$executeRawUnsafe(
    `DELETE FROM HealthCoachDispatchLock WHERE createdAt < NOW() - INTERVAL '3 days'`
  ).catch(() => {})

  const rows = await prisma.$queryRawUnsafe<Array<{ id: string }>>(
    `INSERT INTO HealthCoachDispatchLock (id, userId, localDate, reminderTime)
     VALUES ($1, $2, $3, $4)
     ON CONFLICT (userId, localDate, reminderTime) DO NOTHING
     RETURNING id`,
    crypto.randomUUID(),
    params.userId,
    params.localDate,
    params.reminderTime
  )

  return rows.length > 0
}

async function pushIfPossible(
  subscriptions: any[],
  payload: string,
  userId: string,
  hasKeys: boolean,
  publicKey: string,
  privateKey: string
) {
  if (!hasKeys || !subscriptions.length) {
    return {
      sent: false,
      subscriptions,
    }
  }

  webpush.setVapidDetails('mailto:support@helfi.ai', publicKey, privateKey)
  const sendResult = await sendToSubscriptions(subscriptions, (sub) =>
    webpush.sendNotification(sub, payload)
  )
  let updated = subscriptions

  if (sendResult.goneEndpoints.length) {
    updated = removeSubscriptionsByEndpoint(updated, sendResult.goneEndpoints)
    await prisma.$executeRawUnsafe(
      `UPDATE PushSubscriptions SET subscription = $2::jsonb, updatedAt = NOW() WHERE userId = $1`,
      userId,
      JSON.stringify(updated)
    ).catch(() => {})
  }

  return {
    sent: !!sendResult.sent,
    subscriptions: updated,
  }
}

async function sendCapReachedNotice(args: {
  userId: string
  localDate: string
  subscriptions: any[]
  hasKeys: boolean
  publicKey: string
  privateKey: string
}) {
  const title = 'Smart Health Coach: daily limit reached'
  const body = 'Daily coach limit reached. New alerts will resume tomorrow.'
  const url = '/health-tips'
  const eventKey = `smart_health_coach_cap:${args.localDate}`

  await createInboxNotification({
    userId: args.userId,
    title,
    body,
    url,
    type: 'smart_health_coach_info',
    source: 'push',
    eventKey,
    metadata: { kind: 'daily_cap' },
  }).catch(() => {})

  const payload = JSON.stringify({ title, body, url })
  await pushIfPossible(
    args.subscriptions,
    payload,
    args.userId,
    args.hasKeys,
    args.publicKey,
    args.privateKey
  ).catch(() => {})
}

async function sendLowCreditsNotice(args: {
  userId: string
  localDate: string
  subscriptions: any[]
  hasKeys: boolean
  publicKey: string
  privateKey: string
}) {
  const title = 'Smart Health Coach: top up needed'
  const body = 'You do not have enough credits for Smart Health Coach alerts right now.'
  const url = '/billing'
  const eventKey = `smart_health_coach_low_credit:${args.localDate}`

  await createInboxNotification({
    userId: args.userId,
    title,
    body,
    url,
    type: 'smart_health_coach_low_credit',
    source: 'push',
    eventKey,
    metadata: { kind: 'low_credit' },
  }).catch(() => {})

  const payload = JSON.stringify({ title, body, url })
  await pushIfPossible(
    args.subscriptions,
    payload,
    args.userId,
    args.hasKeys,
    args.publicKey,
    args.privateKey
  ).catch(() => {})
}

export async function POST(req: NextRequest) {
  const now = new Date()

  try {
    if (!isSchedulerAuthorized(req)) {
      return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
    }

    const body = (await req.json().catch(() => ({}))) as Partial<DispatchPayload>
    const userId = String(body.userId || '')
    const reminderTime = String(body.reminderTime || '')
    const fallbackTimezone = String(body.timezone || 'UTC')

    if (!userId || !reminderTime) {
      return NextResponse.json({ error: 'invalid_payload' }, { status: 400 })
    }

    await ensureHealthTipTables()
    await ensureSmartCoachTables()

    const [settingsRows, subscriptionRows] = await Promise.all([
      prisma.$queryRawUnsafe<
        Array<{
          enabled: boolean
          timezone: string
        }>
      >(
        `SELECT enabled, timezone
         FROM HealthTipSettings
         WHERE userId = $1`,
        userId
      ),
      prisma.$queryRawUnsafe<Array<{ subscription: any }>>(
        `SELECT subscription FROM PushSubscriptions WHERE userId = $1`,
        userId
      ),
    ])

    const settings = settingsRows[0]
    if (!settings || !settings.enabled) {
      await logSmartCoachDecision({
        userId,
        ruleId: 'none',
        triggerResult: 'blocked',
        blockReason: 'disabled',
        creditsCharged: 0,
        metadata: { reminderTime },
      })
      return NextResponse.json({ skipped: 'disabled' })
    }

    const activeTimes: string[] = [...SMART_COACH_AUTO_CHECK_TIMES]

    const effectiveTimezone = settings.timezone || fallbackTimezone || 'UTC'
    const local = getLocalDateTime(effectiveTimezone, now)
    const claimedDispatchWindow = await claimDispatchWindow({
      userId,
      localDate: local.localDate,
      reminderTime,
    })
    if (!claimedDispatchWindow) {
      await logSmartCoachDecision({
        userId,
        ruleId: 'none',
        triggerResult: 'blocked',
        blockReason: 'already_sent',
        creditsCharged: 0,
        metadata: {
          reason: 'duplicate_dispatch_window',
          localDate: local.localDate,
          reminderTime,
          timezone: effectiveTimezone,
        },
      })
      return NextResponse.json({ skipped: 'already_sent' })
    }

    const reminderStillActive = activeTimes.includes(reminderTime)
    const timezoneStillMatches = effectiveTimezone === fallbackTimezone || !fallbackTimezone

    if (!reminderStillActive || !timezoneStillMatches) {
      try {
        await Promise.all(
          activeTimes.map((time) => scheduleHealthTipWithQStash(userId, time, effectiveTimezone))
        )
      } catch (error) {
        console.error('[SMART_COACH] Failed stale schedule resync', error)
      }

      await logSmartCoachDecision({
        userId,
        ruleId: 'none',
        triggerResult: 'blocked',
        blockReason: 'stale_schedule',
        creditsCharged: 0,
        metadata: { reminderTime, timezone: fallbackTimezone, activeTimes, effectiveTimezone },
      })
      return NextResponse.json({ skipped: 'stale_schedule' })
    }

    const quietHours = await getSmartCoachQuietHours(userId)

    if (quietHours.enabled) {
      const localTimeForQuiet = getLocalDateTime(
        quietHours.timezone || effectiveTimezone,
        now
      ).localTime
      const inQuietHours = isWithinQuietHours(
        localTimeForQuiet,
        quietHours.startTime,
        quietHours.endTime
      )
      if (inQuietHours) {
        await logSmartCoachDecision({
          userId,
          ruleId: 'none',
          triggerResult: 'blocked',
          blockReason: 'quiet_hours',
          creditsCharged: 0,
          metadata: {
            localTime: localTimeForQuiet,
            start: quietHours.startTime,
            end: quietHours.endTime,
            timezone: quietHours.timezone || effectiveTimezone,
          },
        })
        await scheduleNextReminder(userId, reminderTime, effectiveTimezone)
        return NextResponse.json({ skipped: 'quiet_hours' })
      }
    }

    const evaluation = await evaluateSmartCoachRule({
      userId,
      timezone: effectiveTimezone,
      now,
    })

    if (!evaluation.rule) {
      await logSmartCoachDecision({
        userId,
        ruleId: 'none',
        triggerResult: 'blocked',
        blockReason: 'no_rule',
        creditsCharged: 0,
        metadata: evaluation.metrics,
      })
      await scheduleNextReminder(userId, reminderTime, effectiveTimezone)
      return NextResponse.json({ skipped: 'no_rule' })
    }

    const dailySummaryRows = await prisma.$queryRawUnsafe<
      Array<{ sentcount: string; chargedcredits: string }>
    >(
      `SELECT
         COUNT(*)::text AS sentCount,
         COALESCE(SUM(COALESCE(chargeCents, 0)), 0)::text AS chargedCredits
       FROM HealthTips
       WHERE userId = $1
         AND tipDate = $2::date
         AND category = 'smart_health_coach'`,
      userId,
      evaluation.localDate
    )
    const sentCount = parseInt(dailySummaryRows[0]?.sentcount || '0', 10) || 0
    const chargedCredits = parseInt(dailySummaryRows[0]?.chargedcredits || '0', 10) || 0

    const subscriptions = dedupeSubscriptions(
      normalizeSubscriptionList(subscriptionRows[0]?.subscription)
    )
    const { publicKey, privateKey, hasKeys } = getPushKeys()

    if (
      sentCount >= SMART_COACH_DAILY_MAX_ALERTS ||
      chargedCredits >= SMART_COACH_DAILY_CAP_CREDITS
    ) {
      await sendCapReachedNotice({
        userId,
        localDate: evaluation.localDate,
        subscriptions,
        hasKeys,
        publicKey,
        privateKey,
      })
      await logSmartCoachDecision({
        userId,
        ruleId: evaluation.rule.ruleId,
        triggerResult: 'blocked',
        blockReason: 'daily_cap',
        creditsCharged: 0,
        metadata: {
          sentCount,
          chargedCredits,
          limitAlerts: SMART_COACH_DAILY_MAX_ALERTS,
          limitCredits: SMART_COACH_DAILY_CAP_CREDITS,
          ...evaluation.metrics,
        },
      })
      await scheduleNextReminder(userId, reminderTime, effectiveTimezone)
      return NextResponse.json({ skipped: 'daily_cap' })
    }

    const globalCooldownRows = await prisma.$queryRawUnsafe<Array<{ tipid: string }>>(
      `SELECT id AS tipId
       FROM HealthTips
       WHERE userId = $1
         AND category = 'smart_health_coach'
         AND sentAt >= NOW() - ($2 * INTERVAL '1 minute')
       ORDER BY sentAt DESC
       LIMIT 1`,
      userId,
      SMART_COACH_GLOBAL_COOLDOWN_MINUTES
    )
    if (globalCooldownRows.length > 0) {
      await logSmartCoachDecision({
        userId,
        ruleId: evaluation.rule.ruleId,
        triggerResult: 'blocked',
        blockReason: 'global_cooldown',
        creditsCharged: 0,
        metadata: {
          cooldownMinutes: SMART_COACH_GLOBAL_COOLDOWN_MINUTES,
          ...evaluation.metrics,
        },
      })
      await scheduleNextReminder(userId, reminderTime, effectiveTimezone)
      return NextResponse.json({ skipped: 'global_cooldown' })
    }

    const ruleCooldownRows = await prisma.$queryRawUnsafe<Array<{ tipid: string }>>(
      `SELECT id AS tipId
       FROM HealthTips
       WHERE userId = $1
         AND category = 'smart_health_coach'
         AND metadata->>'ruleId' = $2
         AND sentAt >= NOW() - ($3 * INTERVAL '1 minute')
       ORDER BY sentAt DESC
       LIMIT 1`,
      userId,
      evaluation.rule.ruleId,
      SMART_COACH_RULE_COOLDOWN_MINUTES
    )
    if (ruleCooldownRows.length > 0) {
      await logSmartCoachDecision({
        userId,
        ruleId: evaluation.rule.ruleId,
        triggerResult: 'blocked',
        blockReason: 'rule_cooldown',
        creditsCharged: 0,
        metadata: {
          cooldownMinutes: SMART_COACH_RULE_COOLDOWN_MINUTES,
          ...evaluation.metrics,
        },
      })
      await scheduleNextReminder(userId, reminderTime, effectiveTimezone)
      return NextResponse.json({ skipped: 'rule_cooldown' })
    }

    const categoryCooldownRows = await prisma.$queryRawUnsafe<Array<{ tipid: string }>>(
      `SELECT id AS tipId
       FROM HealthTips
       WHERE userId = $1
         AND category = 'smart_health_coach'
         AND metadata->>'category' = $2
         AND sentAt >= NOW() - ($3 * INTERVAL '1 minute')
       ORDER BY sentAt DESC
       LIMIT 1`,
      userId,
      evaluation.rule.category,
      SMART_COACH_CATEGORY_COOLDOWN_MINUTES
    )
    if (categoryCooldownRows.length > 0) {
      await logSmartCoachDecision({
        userId,
        ruleId: evaluation.rule.ruleId,
        triggerResult: 'blocked',
        blockReason: 'category_cooldown',
        creditsCharged: 0,
        metadata: {
          category: evaluation.rule.category,
          cooldownMinutes: SMART_COACH_CATEGORY_COOLDOWN_MINUTES,
          ...evaluation.metrics,
        },
      })
      await scheduleNextReminder(userId, reminderTime, effectiveTimezone)
      return NextResponse.json({ skipped: 'category_cooldown' })
    }

    const messageCooldownRows = await prisma.$queryRawUnsafe<Array<{ tipid: string }>>(
      `SELECT id AS tipId
       FROM HealthTips
       WHERE userId = $1
         AND category = 'smart_health_coach'
         AND title = $2
         AND body = $3
         AND sentAt >= NOW() - ($4 * INTERVAL '1 minute')
       ORDER BY sentAt DESC
       LIMIT 1`,
      userId,
      evaluation.rule.title,
      evaluation.rule.body,
      SMART_COACH_MESSAGE_COOLDOWN_MINUTES
    )
    if (messageCooldownRows.length > 0) {
      await logSmartCoachDecision({
        userId,
        ruleId: evaluation.rule.ruleId,
        triggerResult: 'blocked',
        blockReason: 'message_cooldown',
        creditsCharged: 0,
        metadata: {
          cooldownMinutes: SMART_COACH_MESSAGE_COOLDOWN_MINUTES,
          ...evaluation.metrics,
        },
      })
      await scheduleNextReminder(userId, reminderTime, effectiveTimezone)
      return NextResponse.json({ skipped: 'message_cooldown' })
    }

    const creditManager = new CreditManager(userId)
    const wallet = await creditManager.getWalletStatus()
    if ((wallet.totalAvailableCents || 0) < SMART_COACH_ALERT_COST_CREDITS) {
      await sendLowCreditsNotice({
        userId,
        localDate: evaluation.localDate,
        subscriptions,
        hasKeys,
        publicKey,
        privateKey,
      })
      await logSmartCoachDecision({
        userId,
        ruleId: evaluation.rule.ruleId,
        triggerResult: 'blocked',
        blockReason: 'insufficient_credits',
        creditsCharged: 0,
        metadata: { walletTotal: wallet.totalAvailableCents, ...evaluation.metrics },
      })
      await scheduleNextReminder(userId, reminderTime, effectiveTimezone)
      return NextResponse.json({ skipped: 'insufficient_credits' })
    }

    const charged = await creditManager.chargeCents(SMART_COACH_ALERT_COST_CREDITS)
    if (!charged) {
      await logSmartCoachDecision({
        userId,
        ruleId: evaluation.rule.ruleId,
        triggerResult: 'blocked',
        blockReason: 'billing_failed',
        creditsCharged: 0,
        metadata: evaluation.metrics,
      })
      await scheduleNextReminder(userId, reminderTime, effectiveTimezone)
      return NextResponse.json({ skipped: 'billing_failed' }, { status: 402 })
    }

    const eventKey = `smart_health_coach:${evaluation.localDate}:${evaluation.rule.ruleId}:${Math.floor(
      now.getTime() / (60 * 60 * 1000)
    )}`

    const notificationPayload = JSON.stringify({
      title: evaluation.rule.title,
      body: evaluation.rule.body,
      url: evaluation.rule.url,
    })

    const pushResult = await pushIfPossible(
      subscriptions,
      notificationPayload,
      userId,
      hasKeys,
      publicKey,
      privateKey
    )

    const notificationId = await createInboxNotification({
      userId,
      title: evaluation.rule.title,
      body: evaluation.rule.body,
      url: evaluation.rule.url,
      type: 'smart_health_coach_alert',
      source: 'push',
      eventKey,
      metadata: {
        ruleId: evaluation.rule.ruleId,
        category: evaluation.rule.category,
        localDate: evaluation.localDate,
        localTime: evaluation.localTime,
      },
    }).catch(() => null)

    const tipId = crypto.randomUUID()
    await prisma.$executeRawUnsafe(
      `INSERT INTO HealthTips (
        id, userId, tipDate, sentAt, title, body, category, metadata, costCents, chargeCents
      )
      VALUES ($1,$2,$3::date,NOW(),$4,$5,$6,$7::jsonb,$8,$9)`,
      tipId,
      userId,
      evaluation.localDate,
      evaluation.rule.title.slice(0, 140),
      evaluation.rule.body,
      'smart_health_coach',
      JSON.stringify({
        ruleId: evaluation.rule.ruleId,
        category: evaluation.rule.category,
        why: evaluation.rule.why,
        notificationId,
        eventKey,
        pushDelivered: pushResult.sent,
        localTime: evaluation.localTime,
      }).slice(0, 10000),
      SMART_COACH_ALERT_COST_CREDITS,
      SMART_COACH_ALERT_COST_CREDITS
    )

    await logSmartCoachDecision({
      userId,
      ruleId: evaluation.rule.ruleId,
      triggerResult: 'sent',
      blockReason: 'none',
      creditsCharged: SMART_COACH_ALERT_COST_CREDITS,
      notificationId,
      metadata: {
        ...evaluation.metrics,
        localDate: evaluation.localDate,
        localTime: evaluation.localTime,
        timezone: evaluation.timezone,
      },
    })

    await scheduleNextReminder(userId, reminderTime, effectiveTimezone)

    return NextResponse.json({
      ok: true,
      ruleId: evaluation.rule.ruleId,
      tipId,
      creditsCharged: SMART_COACH_ALERT_COST_CREDITS,
      notificationId,
      localDate: local.localDate,
      localTime: local.localTime,
    })
  } catch (error: any) {
    console.error('[SMART_COACH_DISPATCH] error', error?.stack || error)
    const blockReason: SmartCoachBlockReason = 'unknown'
    const body = (await req.json().catch(() => ({}))) as Partial<DispatchPayload>
    const userId = String(body?.userId || '')
    if (userId) {
      await logSmartCoachDecision({
        userId,
        ruleId: 'none',
        triggerResult: 'blocked',
        blockReason,
        creditsCharged: 0,
        metadata: { message: error?.message || String(error) },
      })
    }
    return NextResponse.json(
      { error: 'smart_coach_dispatch_error', message: error?.message || String(error) },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import webpush from 'web-push'
import { dedupeSubscriptions, normalizeSubscriptionList, removeSubscriptionsByEndpoint, sendToSubscriptions } from '@/lib/push-subscriptions'
import { isSchedulerAuthorized } from '@/lib/scheduler-auth'

// Upstash QStash will POST here. This simply reuses our notifyOwner pathway,
// which resolves owner's subscription and performs the web-push delivery.
export async function POST(req: NextRequest) {
  try {
    if (!isSchedulerAuthorized(req)) {
      return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
    }

    const body = await req.json().catch(() => ({}))
    const { event, userEmail, userName, amount, currency, planName, creditAmount } = body || {}
    if (!event || !userEmail) {
      return NextResponse.json({ error: 'invalid_payload' }, { status: 400 })
    }

    // Log receipt
    try {
      await prisma.$executeRawUnsafe(`
        CREATE TABLE IF NOT EXISTS OwnerPushLog (
          createdAt TIMESTAMP NOT NULL DEFAULT NOW(),
          event TEXT,
          userEmail TEXT,
          status TEXT,
          info TEXT
        )
      `)
      await prisma.$executeRawUnsafe(
        `INSERT INTO OwnerPushLog (event, userEmail, status, info) VALUES ($1, $2, $3, $4)`,
        event,
        userEmail,
        'received_qstash',
        null
      )
    } catch {}

    // Direct delivery using same underlying mechanism as reminders
    const publicKey = process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY || ''
    const privateKey = process.env.VAPID_PRIVATE_KEY || ''
    if (!publicKey || !privateKey) {
      return NextResponse.json({ error: 'vapid_not_configured' }, { status: 500 })
    }
    webpush.setVapidDetails('mailto:support@helfi.ai', publicKey, privateKey)

    // Resolve owner subscription
    const ownerEmail = (process.env.OWNER_EMAIL || 'admin@helfi.ai').toLowerCase()

    // Find owner userId in User table (AdminUser accounts map by email)
    const owner = await prisma.user.findUnique({
      where: { email: ownerEmail },
      select: { id: true }
    })
    if (!owner?.id) {
      return NextResponse.json({ error: 'owner_not_found' }, { status: 404 })
    }

    // Ensure PushSubscriptions exists and fetch subscription
    await prisma.$executeRawUnsafe(`
      CREATE TABLE IF NOT EXISTS PushSubscriptions (
        userId TEXT PRIMARY KEY,
        subscription JSONB NOT NULL
      )
    `)
    const subRows: Array<{ subscription: any }> = await prisma.$queryRawUnsafe(
      `SELECT subscription FROM PushSubscriptions WHERE userId = $1`,
      owner.id
    )
    if (!subRows.length) {
      return NextResponse.json({ error: 'no_owner_subscription' }, { status: 400 })
    }
    const subscriptions = dedupeSubscriptions(normalizeSubscriptionList(subRows[0].subscription))
    if (!subscriptions.length) {
      return NextResponse.json({ error: 'no_owner_subscription' }, { status: 400 })
    }

    // Build payload
    const titleMap: Record<string, string> = {
      signup: '🎉 New User Signup',
      subscription: '💰 New Subscription',
      credit_purchase: '💳 Credit Purchase',
    }
    const bodyText =
      event === 'signup'
        ? `${userName || (userEmail || '').split('@')[0]} just signed up!`
        : event === 'subscription'
        ? `${userName || (userEmail || '').split('@')[0]} purchased ${planName || 'Premium'}`
        : `${userName || (userEmail || '').split('@')[0]} bought ${creditAmount ? `${creditAmount} credits` : 'credits'}` +
          (amount ? ` (${(amount / 100).toFixed(2)} ${currency || 'USD'})` : '')

    const payload = JSON.stringify({
      title: titleMap[event] || 'Helfi Update',
      body: bodyText,
      url: '/admin-panel',
    })

    const { sent, errors, goneEndpoints } = await sendToSubscriptions(subscriptions, (sub) =>
      webpush.sendNotification(sub, payload)
    )
    if (goneEndpoints.length) {
      const remaining = removeSubscriptionsByEndpoint(subscriptions, goneEndpoints)
      await prisma.$executeRawUnsafe(
        `UPDATE PushSubscriptions SET subscription = $2::jsonb, updatedAt = NOW() WHERE userId = $1`,
        owner.id,
        JSON.stringify(remaining)
      )
    }
    if (!sent) {
      return NextResponse.json({ error: 'push_failed', details: errors }, { status: 500 })
    }
    try {
      await prisma.$executeRawUnsafe(
        `INSERT INTO OwnerPushLog (event, userEmail, status, info) VALUES ($1, $2, $3, $4)`,
        event,
        userEmail,
        'sent_qstash',
        null
      )
    } catch {}

    return NextResponse.json({ ok: true })
  } catch (e: any) {
    console.error('[OWNER PUSH API] error', e?.stack || e)
    return NextResponse.json({ error: 'owner_push_error', message: e?.message || String(e) }, { status: 500 })
  }
}

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { normalizeSubscriptionList } from '@/lib/push-subscriptions'
import { isSubscriptionActive } from '@/lib/subscription-utils'

// Debug endpoint to check scheduler status and test timing
export async function GET(req: NextRequest) {
  const session = await getServerSession(authOptions)
  if (!session?.user?.email) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const user = await prisma.user.findUnique({
    where: { email: session.user.email },
    include: { subscription: true, creditTopUps: true },
  })
  if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 })

  try {
    // Get user's settings
    const settingsRows: Array<{ time1: string; time2: string; time3: string; time4: string; timezone: string; frequency: number }> =
      await prisma.$queryRawUnsafe(
        `SELECT time1, time2, time3, time4, timezone, frequency FROM CheckinSettings WHERE userId = $1`,
        user.id
      )

    // Get subscription
    const subRows: Array<{ subscription: any }> = await prisma.$queryRawUnsafe(
      `SELECT subscription FROM PushSubscriptions WHERE userId = $1`,
      user.id
    )

    // Calculate current time in user's timezone
    const nowUtc = new Date()
    const settings = settingsRows[0] || {
      time1: '12:30',
      time2: '18:30',
      time3: '21:30',
      time4: '09:00',
      timezone: 'Australia/Melbourne',
      frequency: 3
    }
    const now = new Date()
    const hasSubscription = isSubscriptionActive(user.subscription, now)
    const hasPurchasedCredits = (user.creditTopUps || []).some(
      (topUp: any) => topUp.expiresAt > now && (topUp.amountCents - topUp.usedCents) > 0
    )
    const maxFrequency = (hasSubscription || hasPurchasedCredits) ? 4 : 1
    const resolvedFrequency = Math.max(1, Math.min(maxFrequency, settings.frequency || 1))

    const tz = settings.timezone || 'Australia/Melbourne'
    const fmt = new Intl.DateTimeFormat('en-GB', {
      timeZone: tz,
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    })
    const parts = fmt.formatToParts(nowUtc)
    const hh = parts.find(p => p.type === 'hour')?.value || '00'
    const mm = parts.find(p => p.type === 'minute')?.value || '00'
    const current = `${hh}:${mm}`

    // Build reminder times
    const reminderTimes: string[] = []
    if (resolvedFrequency >= 1) reminderTimes.push(settings.time1)
    if (resolvedFrequency >= 2) reminderTimes.push(settings.time2)
    if (resolvedFrequency >= 3) reminderTimes.push(settings.time3)
    if (resolvedFrequency >= 4) reminderTimes.push(settings.time4)

    // Check if current time matches
    const matches = reminderTimes.map(reminderTime => {
      const [rh, rm] = reminderTime.split(':').map(Number)
      const [ch, cm] = [parseInt(hh, 10), parseInt(mm, 10)]
      return {
        reminderTime,
        currentTime: current,
        matches: rh === ch && rm === cm,
        details: `Reminder: ${rh}:${rm.toString().padStart(2, '0')}, Current: ${ch}:${cm.toString().padStart(2, '0')}`
      }
    })

    // Get recent scheduler logs
    let schedulerLogs: any[] = []
    try {
      await prisma.$executeRawUnsafe(`
        CREATE TABLE IF NOT EXISTS SchedulerLogs (
          id TEXT PRIMARY KEY,
          timestamp TIMESTAMP NOT NULL DEFAULT NOW(),
          utcTime TEXT NOT NULL,
          usersProcessed INTEGER NOT NULL,
          notificationsSent INTEGER NOT NULL,
          errors INTEGER NOT NULL,
          debugInfo JSONB
        )
      `)
      schedulerLogs = await prisma.$queryRawUnsafe(`
        SELECT timestamp, utcTime, usersProcessed, notificationsSent, errors, debugInfo
        FROM SchedulerLogs
        ORDER BY timestamp DESC
        LIMIT 20
      `)
    } catch (e) {
      console.error('Failed to fetch scheduler logs:', e)
    }

    // Get recent QStash schedule attempts
    let qstashScheduleLogs: any[] = []
    try {
      await prisma.$executeRawUnsafe(`
        CREATE TABLE IF NOT EXISTS QstashScheduleLog (
          id TEXT PRIMARY KEY,
          createdAt TIMESTAMP NOT NULL DEFAULT NOW(),
          userId TEXT,
          reminderTime TEXT,
          timezone TEXT,
          deltaMinutes INTEGER,
          notBeforeEpochSeconds BIGINT,
          scheduled BOOLEAN NOT NULL,
          httpStatus INTEGER,
          reason TEXT,
          responseSnippet TEXT
        )
      `)
      qstashScheduleLogs = await prisma.$queryRawUnsafe(`
        SELECT 
          createdAt,
          userId,
          reminderTime,
          timezone,
          deltaMinutes,
          notBeforeEpochSeconds::text AS "notBeforeEpochSeconds",
          scheduled,
          httpStatus,
          reason,
          responseSnippet,
          callbackUrl
        FROM QstashScheduleLog
        ORDER BY createdAt DESC
        LIMIT 20
      `)
    } catch (e) {
      console.error('Failed to fetch QStash schedule logs:', e)
    }

    return NextResponse.json({
      userId: user.id,
      hasSubscription: subRows.length > 0 && normalizeSubscriptionList(subRows[0]?.subscription).length > 0,
      subscriptionCount: subRows.length ? normalizeSubscriptionList(subRows[0]?.subscription).length : 0,
      settings: {
        time1: settings.time1,
        time2: settings.time2,
        time3: settings.time3,
        time4: settings.time4,
        timezone: settings.timezone,
        frequency: resolvedFrequency,
        maxFrequency
      },
      currentTime: {
        utc: nowUtc.toISOString(),
        local: current,
        timezone: tz
      },
      reminderTimes,
      matches,
      nextCronRuns: [
        'Every 5 minutes at :00, :05, :10, :15, :20, :25, :30, :35, :40, :45, :50, :55'
      ],
      recentSchedulerLogs: schedulerLogs,
      recentQstashScheduleLogs: qstashScheduleLogs
    })
  } catch (e: any) {
    return NextResponse.json({ error: e?.message || String(e) }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import webpush from 'web-push'
import crypto from 'crypto'
import { dedupeSubscriptions, normalizeSubscriptionList, removeSubscriptionsByEndpoint, sendToSubscriptions } from '@/lib/push-subscriptions'
import { createInboxNotification } from '@/lib/notification-inbox'
import { isSubscriptionActive } from '@/lib/subscription-utils'
import { ensureCheckinTables } from '@/app/api/checkins/_db'

// Force dynamic execution - prevent caching for cron jobs
export const dynamic = 'force-dynamic'
// Ensure Node.js runtime (web-push requires Node, not Edge)
export const runtime = 'nodejs'

const redactHeaderValue = (key: string, value: string) => {
  const sensitive = new Set(['authorization', 'cookie', 'set-cookie', 'x-native-token'])
  return sensitive.has(key.toLowerCase()) && value ? '[REDACTED]' : value
}

// This endpoint is intended to be triggered by a cron (e.g., Vercel Cron) every 5 minutes.
// It finds users whose reminder time matches the current time in their timezone and sends a push.

export async function POST(req: NextRequest) {
  try {
  const authHeader = req.headers.get('authorization') || ''
  const expected = process.env.SCHEDULER_SECRET || ''

  // Check for Vercel cron header
  // Vercel sends x-vercel-cron header when triggering cron jobs
  const vercelCronHeader = req.headers.get('x-vercel-cron')
  const isVercelCron = vercelCronHeader !== null // Header exists (even if empty, Vercel sets it)

  // Also check all headers for debugging
  const allHeaders: Record<string, string> = {}
  req.headers.forEach((value, key) => {
    allHeaders[key] = redactHeaderValue(key, value)
  })

  // Log authentication attempt for debugging
  console.log('[SCHEDULER] Auth check:', {
    hasVercelCronHeader: vercelCronHeader !== null,
    vercelCronValue: vercelCronHeader,
    isVercelCron,
    hasAuthHeader: !!authHeader,
    hasExpectedSecret: !!expected,
    method: req.method,
    url: req.url,
    allHeaders: Object.keys(allHeaders)
  })

  if (!(isVercelCron || (expected && authHeader === `Bearer ${expected}`))) {
    console.error('[SCHEDULER] ❌ Unauthorized - missing x-vercel-cron header or valid Bearer token')
    console.error('[SCHEDULER] Received headers:', JSON.stringify(allHeaders, null, 2))
    return NextResponse.json({ error: 'Unauthorized', debug: { hasVercelCronHeader: vercelCronHeader !== null, headers: Object.keys(allHeaders) } }, { status: 401 })
  }

  console.log('[SCHEDULER] ✅ Authorized - proceeding with notification check')

  // QStash may be enabled, but we still run the cron as a safety net.
  // This prevents late or missed check-in reminders if QStash is delayed.
  if (process.env.QSTASH_TOKEN) {
    console.log('[SCHEDULER] QStash enabled; running cron fallback for check-ins')
  }

  await ensureCheckinTables()

  const publicKey = process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY || ''
  const privateKey = process.env.VAPID_PRIVATE_KEY || ''
  if (!publicKey || !privateKey) {
    return NextResponse.json({ error: 'VAPID keys not configured' }, { status: 500 })
  }
  webpush.setVapidDetails('mailto:support@helfi.ai', publicKey, privateKey)

  // Ensure required tables exist with full schema
  // await prisma.$executeRawUnsafe(`
  //   CREATE TABLE IF NOT EXISTS CheckinSettings (
  //     userId TEXT PRIMARY KEY,
  //     time1 TEXT NOT NULL,
  //     time2 TEXT NOT NULL,
  //     time3 TEXT NOT NULL,
  //     timezone TEXT NOT NULL,
  //     frequency INTEGER NOT NULL DEFAULT 3
  //   )
  // `)
  // await prisma.$executeRawUnsafe(`
  //   CREATE TABLE IF NOT EXISTS PushSubscriptions (
  //     userId TEXT PRIMARY KEY,
  //     subscription JSONB NOT NULL
  //   )
  // `)
  // await prisma.$executeRawUnsafe(`
  //   CREATE TABLE IF NOT EXISTS ReminderDeliveryLog (
  //     userId TEXT NOT NULL,
  //     reminderTime TEXT NOT NULL,
  //     sentDate DATE NOT NULL,
  //     sentAt TIMESTAMP NOT NULL DEFAULT NOW(),
  //     PRIMARY KEY (userId, reminderTime, sentDate)
  //   )
  // `)

  // // Migrate old schema if needed
  // await prisma.$executeRawUnsafe(`ALTER TABLE CheckinSettings ADD COLUMN IF NOT EXISTS time2 TEXT NOT NULL DEFAULT '18:00'`).catch(() => {})
  // await prisma.$executeRawUnsafe(`ALTER TABLE CheckinSettings ADD COLUMN IF NOT EXISTS time3 TEXT NOT NULL DEFAULT '21:00'`).catch(() => {})
  // await prisma.$executeRawUnsafe(`ALTER TABLE CheckinSettings ADD COLUMN IF NOT EXISTS frequency INTEGER NOT NULL DEFAULT 3`).catch(() => {})

  // Load all users with subscriptions and their reminder settings
  const rows: Array<{
    userId: string | null
    enabled: boolean
    time1: string
    time2: string
    time3: string
    time4: string
    timezone: string
    frequency: number
    subscription: any
  }> = await prisma.$queryRawUnsafe(`
    SELECT DISTINCT 
      p.userId AS "userId", 
      COALESCE(s.enabled, true) AS enabled,
      COALESCE(s.time1, '12:30') AS time1,
      COALESCE(s.time2, '18:30') AS time2,
      COALESCE(s.time3, '21:30') AS time3,
      COALESCE(s.time4, '09:00') AS time4,
      COALESCE(s.timezone, 'Australia/Melbourne') AS timezone,
      COALESCE(s.frequency, 3) AS frequency,
      p.subscription
    FROM PushSubscriptions p
    LEFT JOIN CheckinSettings s ON s.userId = p.userId
  `)

  const nowForPaid = new Date()
  const userIds = rows.map((row) => row.userId).filter((id): id is string => !!id)
  const paidUserIds = new Set<string>()
  if (userIds.length) {
    const users = await prisma.user.findMany({
      where: { id: { in: userIds } },
      include: { subscription: true, creditTopUps: true },
    })
    for (const user of users) {
      const hasSubscription = isSubscriptionActive(user.subscription, nowForPaid)
      const hasPurchasedCredits = (user.creditTopUps || []).some(
        (topUp: any) => topUp.expiresAt > nowForPaid && (topUp.amountCents - topUp.usedCents) > 0
      )
      if (hasSubscription || hasPurchasedCredits) {
        paidUserIds.add(user.id)
      }
    }
  }

  // Determine current HH:MM in each user's timezone and match against their reminder times
  const nowUtc = new Date()
  const sentTo: string[] = []
  const errors: Array<{ userId: string, error: string }> = []
  const debugLog: Array<{ userId: string, timezone: string, currentTime: string, reminderTimes: string[], matched: boolean, reason?: string }> = []

  console.log(`[SCHEDULER] Cron triggered at UTC: ${nowUtc.toISOString()}, Processing ${rows.length} users`)

  // Log scheduler execution to database for tracking
  try {
    // await prisma.$executeRawUnsafe(`
    //   CREATE TABLE IF NOT EXISTS SchedulerLogs (
    //     id TEXT PRIMARY KEY,
    //     timestamp TIMESTAMP NOT NULL DEFAULT NOW(),
    //     utcTime TEXT NOT NULL,
    //     usersProcessed INTEGER NOT NULL,
    //     notificationsSent INTEGER NOT NULL,
    //     errors INTEGER NOT NULL,
    //     debugInfo JSONB
    //   )
    // `)
    const logId = crypto.randomUUID()
    await prisma.$queryRawUnsafe(
      `INSERT INTO SchedulerLogs (id, timestamp, utcTime, usersProcessed, notificationsSent, errors, debugInfo)
       VALUES ($1, $2, $3, $4, $5, $6, $7)`,
      logId,
      nowUtc,
      nowUtc.toISOString(),
      rows.length,
      0, // Will update after processing
      0, // Will update after processing
      JSON.stringify({ cronTriggered: true })
    )
  } catch (e) {
    console.error('[SCHEDULER] Failed to log execution:', e)
  }

  for (const r of rows) {
    try {
      if (!r.enabled) {
        debugLog.push({
          userId: r.userId || 'unknown',
          timezone: r.timezone || 'UTC',
          currentTime: 'n/a',
          reminderTimes: [],
          matched: false,
          reason: 'disabled',
        })
        continue
      }
      const tz = r.timezone || 'UTC'
      const fmt = new Intl.DateTimeFormat('en-GB', {
        timeZone: tz,
        hour: '2-digit',
        minute: '2-digit',
        hour12: false,
      })
      const parts = fmt.formatToParts(nowUtc)
      const hh = parts.find(p => p.type === 'hour')?.value || '00'
      const mm = parts.find(p => p.type === 'minute')?.value || '00'
      const current = `${hh}:${mm}`

      const dateParts = new Intl.DateTimeFormat('en-GB', {
        timeZone: tz,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
      }).formatToParts(nowUtc)
      const year = dateParts.find(p => p.type === 'year')?.value || '1970'
      const month = dateParts.find(p => p.type === 'month')?.value || '01'
      const day = dateParts.find(p => p.type === 'day')?.value || '01'
      const localDate = `${year}-${month}-${day}`

      const maxFrequency = r.userId && paidUserIds.has(r.userId) ? 4 : 1
      const resolvedFrequency = Math.max(1, Math.min(maxFrequency, r.frequency || 1))
      // Build array of reminder times based on frequency
      const reminderTimes: string[] = []
      if (resolvedFrequency >= 1) reminderTimes.push(r.time1 || '12:30')
      if (resolvedFrequency >= 2) reminderTimes.push(r.time2 || '18:30')
      if (resolvedFrequency >= 3) reminderTimes.push(r.time3 || '21:30')
      if (resolvedFrequency >= 4) reminderTimes.push(r.time4 || '09:00')

      // Matching: Exact match, up to N minutes after (catch late cron), or 1 minute early
      let shouldSend = false
      let matchReason = ''
      let matchedReminder = ''
      const backfillWindow = Math.max(1, Math.min(60, parseInt(process.env.REMINDER_LAG_MINUTES || '10', 10)))

      for (const reminderTime of reminderTimes) {
        const [rh, rm] = reminderTime.split(':').map(Number)
        const [ch, cm] = [parseInt(hh, 10), parseInt(mm, 10)]

        // Exact match: current time equals reminder time
        if (rh === ch && rm === cm) {
          shouldSend = true
          matchedReminder = reminderTime
          matchReason = `EXACT MATCH: reminder ${reminderTime} at current time ${current}`
          break
        }

        // Within backfillWindow minutes after: catch late cron (e.g., cron runs late)
        const currentTotalMinutes = ch * 60 + cm
        const reminderTotalMinutes = rh * 60 + rm
        let minutesDiff = currentTotalMinutes - reminderTotalMinutes
        if (minutesDiff < 0) minutesDiff += 1440 // wrap-around safe

        if (minutesDiff >= 1 && minutesDiff <= backfillWindow) {
          shouldSend = true
          matchedReminder = reminderTime
          matchReason = `LATE CRON CATCH: reminder ${reminderTime} was ${minutesDiff} minute(s) ago (current ${current}), sending now (window ${backfillWindow}m)`
          break
        }

        // One minute early: send proactively
        let minutesAhead = reminderTotalMinutes - currentTotalMinutes
        if (minutesAhead < 0) minutesAhead += 1440
        if (minutesAhead === 1) {
          shouldSend = true
          matchedReminder = reminderTime
          matchReason = `EARLY SEND: reminder ${reminderTime} is in 1 minute (current ${current}), sending now`
          break
        }
      }

      const shortId = (r.userId ?? 'unknown').toString().slice(0, 8)
      debugLog.push({
        userId: r.userId ?? 'unknown',
        timezone: tz,
        currentTime: current,
        reminderTimes,
        matched: shouldSend,
        reason: shouldSend ? matchReason : `No match: current=${current}, reminders=${reminderTimes.join(', ')}`
      })

      if (!shouldSend) {
        console.log(`[SCHEDULER] User ${shortId}... (${tz}): No match - current=${current}, reminders=${reminderTimes.join(', ')}`)
        continue
      }

      if (!r.userId) {
        console.warn('[SCHEDULER] Skipping send because userId is null')
        continue
      }

      const subscriptions = dedupeSubscriptions(normalizeSubscriptionList(r.subscription))
      if (!subscriptions.length) {
        errors.push({ userId: r.userId ?? 'unknown', error: 'no_subscription' })
        continue
      }

      const alreadySent: Array<{ exists: number }> = await prisma.$queryRawUnsafe(
        `SELECT 1 as exists FROM ReminderDeliveryLog WHERE userId = $1 AND reminderTime = $2 AND sentDate = $3::date LIMIT 1`,
        r.userId,
        matchedReminder,
        localDate
      )

      if (alreadySent.length > 0) {
        console.log(`[SCHEDULER] User ${shortId}... (${tz}): Reminder ${matchedReminder} already sent today (${localDate}), skipping duplicate.`)
        continue
      }

      console.log(`[SCHEDULER] User ${shortId}... (${tz}): Sending notification - matched ${matchReason}`)

      const payload = JSON.stringify({
        title: 'Time for your Helfi check‑in',
        body: 'Rate your selected issues for today in under a minute.',
        url: '/check-in?new=1'
      })
      const { sent, errors: sendErrors, goneEndpoints } = await sendToSubscriptions(subscriptions, (sub) =>
        webpush.sendNotification(sub, payload)
      )
      if (goneEndpoints.length) {
        const remaining = removeSubscriptionsByEndpoint(subscriptions, goneEndpoints)
        await prisma.$executeRawUnsafe(
          `UPDATE PushSubscriptions SET subscription = $2::jsonb, updatedAt = NOW() WHERE userId = $1`,
          r.userId,
          JSON.stringify(remaining)
        )
      }
      if (!sent) {
        const msg = sendErrors.map((err) => err.message).join('; ')
        errors.push({ userId: r.userId ?? 'unknown', error: msg || 'push_failed' })
        continue
      }
      sentTo.push(r.userId ?? 'unknown')
      await prisma.$queryRawUnsafe(
        `INSERT INTO ReminderDeliveryLog (userId, reminderTime, sentDate, sentAt)
         VALUES ($1, $2, $3::date, NOW())
         ON CONFLICT (userId, reminderTime, sentDate) DO UPDATE SET sentAt = NOW()`,
        r.userId,
        matchedReminder,
        localDate
      )
      await createInboxNotification({
        userId: r.userId,
        title: 'Time for your Helfi check-in',
        body: 'Rate your selected issues for today in under a minute.',
        url: '/check-in?new=1',
        type: 'checkin_reminder',
        source: 'push',
        eventKey: `checkin:${localDate}:${matchedReminder}`,
      }).catch(() => {})
      console.log(`[SCHEDULER] ✅ Notification sent to user ${shortId}...`)
    } catch (e: any) {
      const errorMsg = e?.body || e?.message || String(e)
      const shortId = (r.userId ?? 'unknown').toString().slice(0, 8)
      console.error(`[SCHEDULER] ❌ Error for user ${shortId}...:`, errorMsg)
      errors.push({ userId: r.userId ?? 'unknown', error: errorMsg })
    }
  }

  console.log(`[SCHEDULER] Complete: sent=${sentTo.length}, errors=${errors.length}`)

  // Update log with final counts
  try {
    // Find the most recent log entry and update it
    const recentLogs: any[] = await prisma.$queryRawUnsafe(`
      SELECT id FROM SchedulerLogs 
      WHERE timestamp >= NOW() - INTERVAL '1 minute'
      ORDER BY timestamp DESC
      LIMIT 1
    `)
    if (recentLogs.length > 0) {
      await prisma.$queryRawUnsafe(`
        UPDATE SchedulerLogs 
        SET notificationsSent = $1, errors = $2, debugInfo = $3::jsonb
        WHERE id = $4
      `, sentTo.length, errors.length, JSON.stringify({ debug: debugLog, sentTo, errors }), recentLogs[0].id)
    }
  } catch (e) {
    console.error('[SCHEDULER] Failed to update log:', e)
  }

  return NextResponse.json({ 
    success: true, 
    sent: sentTo.length, 
    errors,
    debug: debugLog,
    timestamp: nowUtc.toISOString()
  })
  } catch (e: any) {
    console.error('[SCHEDULER] Top-level error:', e?.stack || e)
    return NextResponse.json({ error: 'scheduler_crash', message: e?.message || String(e) }, { status: 500 })
  }
}

