function getBaseUrl() {
  let base = process.env.PUBLIC_BASE_URL || (process.env.VERCEL_URL ? `https://${process.env.VERCEL_URL}` : '')
  if (!base) base = 'https://helfi.ai'
  base = base.trim()
  if (!/^https?:\/\//i.test(base)) base = `https://${base}`
  return base.replace(/\/+$/, '')
}

function getResendClient() {
  if (!process.env.RESEND_API_KEY) return null
  return new Resend(process.env.RESEND_API_KEY)
}

function escapeHtml(value: string) {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
}

// PROTECTED: WEEKLY_REPORT_EMAIL_LAYOUT START
function extractSummaryPoints(summary?: string | null) {
  const raw = String(summary || '')
    .replace(/\r/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
  if (!raw) return []

  const normalized = raw
    .replace(/\s+-\s+(?=[A-Z0-9])/g, '\n- ')
    .replace(/\s+•\s+/g, '\n• ')

  const points = normalized
    .split(/\n+/)
    .map((line) => line.replace(/^[-•]\s*/, '').trim())
    .filter(Boolean)

  if (points.length > 1) {
    return points.slice(0, 6)
  }

  return raw
    .split(/(?<=[.!?])\s+(?=[A-Z0-9])/)
    .map((line) => line.trim())
    .filter(Boolean)
    .slice(0, 6)
}

