function normalizeReportItem(item: ReportItem | null | undefined): { name: string; reason: string } {
  const name = String(item?.name || '').trim()
  const reason = String(item?.reason || '').trim()
  return { name, reason }
}

function canonicalizeNameForMatch(input: string): string {
  const raw = String(input || '').trim().toLowerCase()
  if (!raw) return ''
  const cleaned = raw
    .replace(/[^\da-z]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
  if (!cleaned) return ''

  const drop = new Set([
    'mg',
    'mcg',
    'g',
    'kg',
    'ml',
    'iu',
    'tablet',
    'tablets',
    'tab',
    'tabs',
    'capsule',
    'capsules',
    'cap',
    'caps',
    'softgel',
    'softgels',
    'drop',
    'drops',
    'tsp',
    'tbsp',
    'morning',
    'afternoon',
    'evening',
    'night',
    'daily',
    'weekly',
    'once',
    'twice',
  ])

  const tokens = cleaned
    .split(' ')
    .map((t) => t.trim())
    .filter(Boolean)
    .filter((t) => !drop.has(t))
    .filter((t) => !/^\d+(\.\d+)?$/.test(t))
    .filter((t) => !/^\d+(\.\d+)?(mg|mcg|g|kg|ml|iu)$/.test(t))

  return tokens.join(' ').trim()
}

function buildKnownNameSet(rows: Array<{ name?: string | null }>) {
  const out = new Set<string>()
  for (const row of rows || []) {
    const key = canonicalizeNameForMatch(String(row?.name || ''))
    if (key) out.add(key)
  }
  return out
}

function sanitizeSupplementAndMedicationSections(
  sections: Record<ReportSectionKey, ReportSectionBucket>,
  reportContext: { supplements: Array<{ name?: string | null }>; medications: Array<{ name?: string | null }> }
): Record<ReportSectionKey, ReportSectionBucket> {
  const output = { ...sections }

  const knownSupplements = buildKnownNameSet(reportContext?.supplements || [])
  const knownMedications = buildKnownNameSet(reportContext?.medications || [])

  const supplements = output.supplements || { working: [], suggested: [], avoid: [] }
  const medications = output.medications || { working: [], suggested: [], avoid: [] }

  const movedToMedications: Array<{ name: string; reason: string }> = []
  const movedToSupplements: Array<{ name: string; reason: string }> = []

  const filterBucket = (items: ReportItem[], shouldKeep: (item: { name: string; reason: string }) => boolean) => {
    const next: Array<{ name: string; reason: string }> = []
    for (const item of items || []) {
      const normalized = normalizeReportItem(item)
      if (!normalized.name) continue
      if (!shouldKeep(normalized)) continue
      next.push(normalized)
    }
    return next
  }

  // 1) Move known medications out of Supplements, and known supplements out of Medications.
  const moveMedsOutOfSupplements = (items: ReportItem[]) =>
    filterBucket(items, (it) => {
      const key = canonicalizeNameForMatch(it.name)
      const isKnownMedication = key && knownMedications.has(key)
      const isKnownSupplement = key && knownSupplements.has(key)
      if (isKnownMedication && !isKnownSupplement) {
        movedToMedications.push(it)
        return false
      }
      return true
    })
  const moveSuppsOutOfMedications = (items: ReportItem[]) =>
    filterBucket(items, (it) => {
      const key = canonicalizeNameForMatch(it.name)
      const isKnownMedication = key && knownMedications.has(key)
      const isKnownSupplement = key && knownSupplements.has(key)
      if (isKnownSupplement && !isKnownMedication) {
        movedToSupplements.push(it)
        return false
      }
      return true
    })

  supplements.working = moveMedsOutOfSupplements(supplements.working || [])
  supplements.suggested = moveMedsOutOfSupplements(supplements.suggested || [])
  supplements.avoid = moveMedsOutOfSupplements(supplements.avoid || [])

  medications.working = moveSuppsOutOfMedications(medications.working || [])
  medications.suggested = moveSuppsOutOfMedications(medications.suggested || [])
  medications.avoid = moveSuppsOutOfMedications(medications.avoid || [])

  // If it was in the user's known list, it should land in "working".
  if (movedToMedications.length) {
    medications.working = [...(medications.working || []), ...movedToMedications]
  }
  if (movedToSupplements.length) {
    supplements.working = [...(supplements.working || []), ...movedToSupplements]
  }

  // 2) If the user already takes it, it can't be a "suggestion" or "avoid" item.
  const removeKnownFromSuggestedAndAvoid = (bucket: ReportSectionBucket, known: Set<string>) => {
    bucket.suggested = filterBucket(bucket.suggested || [], (it) => {
      const key = canonicalizeNameForMatch(it.name)
      return !(key && known.has(key))
    })
    bucket.avoid = filterBucket(bucket.avoid || [], (it) => {
      const key = canonicalizeNameForMatch(it.name)
      return !(key && known.has(key))
    })
  }
  removeKnownFromSuggestedAndAvoid(supplements, knownSupplements)
  removeKnownFromSuggestedAndAvoid(medications, knownMedications)

  // 3) Deduplicate by name (not by reason), and ensure an item can’t appear in multiple buckets.
  const enforceUniqueAcrossBuckets = (bucket: ReportSectionBucket) => {
    const seen = new Set<string>()
    const dedupeList = (items: ReportItem[]) => {
      const next: Array<{ name: string; reason: string }> = []
      for (const item of items || []) {
        const normalized = normalizeReportItem(item)
        const key = canonicalizeNameForMatch(normalized.name)
        if (!key) continue
        if (seen.has(key)) continue
        seen.add(key)
        next.push(normalized)
      }
      return next
    }
    bucket.working = dedupeList(bucket.working || [])
    bucket.suggested = dedupeList(bucket.suggested || [])
    bucket.avoid = dedupeList(bucket.avoid || [])
  }
  enforceUniqueAcrossBuckets(supplements)
  enforceUniqueAcrossBuckets(medications)

  // 4) Last safety pass: if an item still appears in both sections, prefer Medications.
  const medNames = new Set<string>()
  for (const item of [...(medications.working || []), ...(medications.suggested || []), ...(medications.avoid || [])]) {
    const key = canonicalizeNameForMatch(String((item as any)?.name || ''))
    if (key) medNames.add(key)
  }
  const stripIfInMedications = (items: ReportItem[]) =>
    filterBucket(items, (it) => {
      const key = canonicalizeNameForMatch(it.name)
      if (!key) return false
      if (medNames.has(key) && !knownSupplements.has(key)) return false
      return true
    })
  supplements.working = stripIfInMedications(supplements.working || [])
  supplements.suggested = stripIfInMedications(supplements.suggested || [])
  supplements.avoid = stripIfInMedications(supplements.avoid || [])

  output.supplements = supplements
  output.medications = medications
  return output
}

function extractNamedValues(input: unknown): string[] {
  if (!input) return []
  if (typeof input === 'string') {
    const value = input.trim()
    return value ? [value] : []
  }
  if (Array.isArray(input)) {
    return input.flatMap((item) => extractNamedValues(item))
  }
  if (typeof input === 'object') {
    const record = input as Record<string, unknown>
    const directKeys = ['name', 'title', 'label', 'issue', 'goal', 'condition']
    const direct = directKeys
      .map((key) => String(record[key] || '').trim())
      .filter(Boolean)
    if (direct.length) return direct
    return Object.values(record)
      .flatMap((value) => (typeof value === 'string' ? extractNamedValues(value) : []))
      .slice(0, 6)
  }
  return []
}

function parseSupplementDose(value: string | null | undefined) {
  const raw = String(value || '').trim().toLowerCase()
  if (!raw) return null
  const match = raw.match(/(\d+(\.\d+)?)\s*(mcg|mg|g|iu)\b/)
  if (!match) return null
  const amount = Number(match[1])
  if (!Number.isFinite(amount)) return null
  return { amount, unit: match[3] }
}

function formatSupplementNameList(names: string[], max = 3) {
  const clean = names.map((name) => String(name || '').trim()).filter(Boolean)
  if (!clean.length) return 'your current stack'
  const visible = clean.slice(0, max)
  const extra = clean.length - visible.length
  if (extra > 0) {
    return `${visible.join(', ')} + ${extra} more`
  }
  return visible.join(', ')
}

function formatDoseTiming(item: any) {
  const parts = [
    String(item?.dosage || '').trim() ? `dose: ${String(item.dosage).trim()}` : '',
    String(item?.timing || '').trim() ? `timing: ${String(item.timing).trim()}` : '',
  ].filter(Boolean)
  return parts.length ? ` (${parts.join(', ')})` : ''
}

function focusContextFromReport(context: any) {
  const checkinGoals = Array.isArray(context?.checkinSummary?.goals) ? context.checkinSummary.goals : []
  const issueLabels = extractNamedValues(context?.issues)
  const goalLabels = [
    ...extractNamedValues(context?.goals),
    ...checkinGoals.map((goal: any) => String(goal?.goal || '').trim()).filter(Boolean),
  ]
  const healthSituationText = extractNamedValues(context?.healthSituations).join(' ')
  const focusLabels = [...goalLabels, ...issueLabels].filter(Boolean)
  return {
    goalLabels,
    issueLabels,
    focusLabels,
    focusText: `${focusLabels.join(' ')} ${healthSituationText}`.toLowerCase(),
  }
}

function pickFocusLabelFromContext(
  focusLabels: string[],
  patterns: RegExp[],
  fallback: string
) {
  return focusLabels.find((label) => patterns.some((pattern) => pattern.test(label.toLowerCase()))) || fallback
}

function supplementRole(name: string) {
  const lower = String(name || '').toLowerCase()
  if (/citrulline|arginine|beet|nitric/.test(lower)) {
    return {
      patterns: [/libido/, /erection/, /sexual/, /blood flow/],
      fallback: 'erections or blood flow',
      reason: 'it is usually used for blood-flow support',
    }
  }
  if (/maca|tongkat|fadogia|tribulus/.test(lower)) {
    return {
      patterns: [/libido/, /sexual/, /testosterone/, /energy/],
      fallback: 'libido or energy',
      reason: 'it is usually taken for libido, hormone, or energy support',
    }
  }
  if (/magnesium|glycinate|taurate|threonate/.test(lower)) {
    return {
      patterns: [/sleep/, /stress/, /mood/, /recovery/, /muscle/],
      fallback: 'sleep, stress, mood, or recovery',
      reason: 'it may support relaxation, muscle function, and recovery',
    }
  }
  if (/creatine/.test(lower)) {
    return {
      patterns: [/strength/, /muscle/, /training/, /exercise/, /energy/, /recovery/],
      fallback: 'training, energy, or recovery',
      reason: 'it may support strength output, training capacity, and recovery',
    }
  }
  if (/omega|fish oil|epa|dha/.test(lower)) {
    return {
      patterns: [/mood/, /inflammation/, /heart/, /recovery/, /brain/],
      fallback: 'mood, recovery, or heart health',
      reason: 'it may support inflammation balance, mood, and heart health',
    }
  }
  if (/probiotic|lactobacillus|bifido/.test(lower)) {
    return {
      patterns: [/gut/, /digestion/, /bowel/, /bloat/, /constipation/, /diarrh/],
      fallback: 'digestion or bowel regularity',
      reason: 'it may support gut balance and bowel regularity',
    }
  }
  if (/psyllium|fiber|fibre|inulin/.test(lower)) {
    return {
      patterns: [/gut/, /digestion/, /bowel/, /constipation/, /cholesterol/],
      fallback: 'digestion or bowel regularity',
      reason: 'it may support fiber intake and bowel regularity',
    }
  }
  if (/zinc/.test(lower)) {
    return {
      patterns: [/libido/, /testosterone/, /immune/, /skin/, /recovery/],
      fallback: 'immune, libido, or recovery support',
      reason: 'it is commonly used for immune, hormone, and recovery support',
    }
  }
  if (/vitamin\s*d|\bd-?3\b/.test(lower)) {
    return {
      patterns: [/immune/, /mood/, /bone/, /testosterone/, /energy/],
      fallback: 'immune, mood, bone, or energy support',
      reason: 'it may support immune, bone, mood, and hormone-related health',
    }
  }
  if (/b12|methylcobalamin|b complex|folate/.test(lower)) {
    return {
      patterns: [/energy/, /fatigue/, /mood/, /brain fog/, /focus/],
      fallback: 'energy, mood, or focus',
      reason: 'it may support energy metabolism and nervous-system function',
    }
  }
  if (/collagen|gelatin/.test(lower)) {
    return {
      patterns: [/joint/, /skin/, /recovery/, /injury/],
      fallback: 'skin, joints, or recovery',
      reason: 'it may support connective tissue, skin, and joint goals',
    }
  }
  if (/coq10|ubiquinol|ubiquinone/.test(lower)) {
    return {
      patterns: [/energy/, /heart/, /recovery/, /fatigue/],
      fallback: 'energy, heart health, or recovery',
      reason: 'it may support cellular energy and heart-related goals',
    }
  }
  return null
}

function buildSupplementWorkingItems(context: any): ReportItem[] {
  const supplements = Array.isArray(context?.supplements) ? context.supplements : []
  const { focusLabels } = focusContextFromReport(context)
  return supplements.slice(0, 10).map((item: any) => {
    const name = String(item?.name || '').trim()
    const role = supplementRole(name)
    const focus = role ? pickFocusLabelFromContext(focusLabels, role.patterns, role.fallback) : (focusLabels[0] || 'your current goals')
    const why = role
      ? `${name}${formatDoseTiming(item)} matches ${focus} because ${role.reason}.`
      : `${name}${formatDoseTiming(item)} is part of your current stack, so it should be reviewed against ${focus}.`
    return {
      name,
      reason: `${why}\nKeep this item steady while comparing erections, libido, digestion, energy, recovery, mood, symptoms, and weekly food/fluid patterns.`,
    }
  }).filter((item: ReportItem) => item.name)
}

function buildMedicationGuidance(context: any): ReportSectionBucket {
  const medications = Array.isArray(context?.medications) ? context.medications : []
  const supplements = Array.isArray(context?.supplements) ? context.supplements : []
  const { focusLabels, focusText } = focusContextFromReport(context)
  const bucket: ReportSectionBucket = { working: [], suggested: [], avoid: [] }
  const currentSupplementNames: string[] = supplements.map((item: any) => String(item?.name || '').trim()).filter(Boolean)

  const hasBloodFlowMed = medications.some((item: any) =>
    /tadalafil|sildenafil|vardenafil|avanafil|nitrate|nitroglycerin/i.test(String(item?.name || ''))
  )
  const hasBloodFlowSupplement = currentSupplementNames.some((name) =>
    /citrulline|arginine|beet|nitric/i.test(name)
  )
  const libidoFocus = /libido|erection|sexual|testosterone|blood flow/.test(focusText)

  for (const item of medications.slice(0, 10)) {
    const name = String(item?.name || '').trim()
    if (!name) continue
    const lower = name.toLowerCase()
    let focus = focusLabels[0] || 'your current goals'
    let reason = `${name}${formatDoseTiming(item)} is listed in your current medication routine.`
    if (/tadalafil|sildenafil|vardenafil|avanafil/.test(lower)) {
      focus = pickFocusLabelFromContext(focusLabels, [/libido/, /erection/, /sexual/, /blood flow/], 'erection or libido support')
      reason = `${name}${formatDoseTiming(item)} matches ${focus} because it is commonly used for erection blood-flow support.`
    }
    bucket.working.push({
      name,
      reason: `${reason}\nKeep dose and timing consistent, and compare it with libido, erection quality, energy, recovery, mood, and symptom notes before changing anything.`,
    })
  }

  if (medications.length) {
    bucket.working.push({
      name: 'Medication timing is captured',
      reason: `Your medication list includes timing information, which makes the weekly report more useful than a plain medicine list.\nThat timing can be compared with erection quality, libido, energy, digestion, mood, symptoms, and exercise recovery.`,
    })
    bucket.suggested.push({
      name: 'Medication review focus',
      reason: `You have ${medications.length} medication(s) listed, so the useful next step is not adding more guesses.\nReview timing, side effects, and goal changes with your prescriber, especially if erections, libido, digestion, energy, or mood changed this week.`,
    })
    bucket.suggested.push({
      name: 'Compare dose timing with daily patterns',
      reason: `Your report also has food, hydration, exercise, mood, symptom, and check-in data.\nCompare medication timing with the best and worst days before deciding whether the medicine itself is the issue.`,
    })
  }

  if (hasBloodFlowMed) {
    bucket.avoid.push({
      name: 'Nitrates or extra blood-flow products without review',
      reason: `${formatSupplementNameList(medications.map((item: any) => String(item?.name || '').trim()), 4)} affects blood-flow planning.\nDo not combine erection medicines with nitrates, and check before adding strong blood-flow supplements${hasBloodFlowSupplement ? ` like ${formatSupplementNameList(currentSupplementNames.filter((name: string) => /citrulline|arginine|beet|nitric/i.test(name)), 3)}` : ''}.`,
    })
  }

  if (libidoFocus && medications.length) {
    bucket.avoid.push({
      name: 'Changing dose based on one week',
      reason: `Your goals mention libido or erections, and this report only covers 7 days.\nAvoid changing medication dose from one weekly pattern unless your prescriber tells you to.`,
    })
  }

  if (medications.length) {
    bucket.avoid.push({
      name: 'Mixing medication changes with supplement changes',
      reason: `Your account has ${medications.length} medication(s) and ${supplements.length} supplement(s) listed.\nAvoid changing medication timing and adding new supplements in the same week, because the report will not know what caused the change.`,
    })
  }

  return bucket
}

function pushReportItem(
  bucket: ReportItem[],
  name: string,
  reason: string,
  max = 4
) {
  const cleanName = String(name || '').trim()
  const cleanReason = String(reason || '').trim()
  if (!cleanName || !cleanReason) return
  const key = canonicalizeNameForMatch(cleanName) || cleanName.toLowerCase()
  if (bucket.some((item) => (canonicalizeNameForMatch(String(item?.name || '')) || String(item?.name || '').toLowerCase()) === key)) return
  if (bucket.length >= max) return
  bucket.push({ name: cleanName, reason: cleanReason })
}

function enrichReportSections(
  sections: Record<ReportSectionKey, ReportSectionBucket>,
  context: any
): Record<ReportSectionKey, ReportSectionBucket> {
  const next = buildDefaultSections()
  for (const key of REPORT_SECTIONS) {
    next[key] = {
      working: Array.isArray(sections?.[key]?.working) ? [...sections[key].working] : [],
      suggested: Array.isArray(sections?.[key]?.suggested) ? [...sections[key].suggested] : [],
      avoid: Array.isArray(sections?.[key]?.avoid) ? [...sections[key].avoid] : [],
    }
  }

  const coverage = context?.coverage || {}
  const nutritionSummary = context?.nutritionSummary || {}
  const hydrationSummary = context?.hydrationSummary || {}
  const exerciseSummary = context?.exerciseSummary || {}
  const moodSummary = context?.moodSummary || {}
  const symptomSummary = context?.symptomSummary || {}
  const checkinSummary = context?.checkinSummary || {}
  const dataFlags = context?.dataFlags || {}
  const correlationSignals = context?.correlationSignals || {}
  const trendSignals = Array.isArray(context?.trendSignals) ? context.trendSignals : []
  const riskFlags = Array.isArray(context?.riskFlags) ? context.riskFlags : []
  const foodHighlights = context?.foodHighlights || {}
  const mealTimingSummary = context?.mealTimingSummary || {}
  const supplements = Array.isArray(context?.supplements) ? context.supplements : []
  const medications = Array.isArray(context?.medications) ? context.medications : []
  const labHighlights = Array.isArray(context?.labs?.highlights) ? context.labs.highlights : []
  const labTrends = Array.isArray(context?.labTrends) ? context.labTrends : []
  const journalSummary = context?.journalSummary || {}

  const goals = extractNamedValues(context?.goals).filter(Boolean)
  const issues = extractNamedValues(context?.issues).filter(Boolean)
  const focus = goals[0] || issues[0] || 'your current health goals'
  const topFoods = Array.isArray(nutritionSummary?.topFoods) ? nutritionSummary.topFoods.map((item: any) => String(item?.name || '').trim()).filter(Boolean) : []
  const topDrinks = Array.isArray(hydrationSummary?.topDrinks) ? hydrationSummary.topDrinks.map((item: any) => String(item?.label || item?.name || '').trim()).filter(Boolean) : []
  const topSymptoms = Array.isArray(symptomSummary?.topSymptoms) ? symptomSummary.topSymptoms.map((item: any) => String(item?.name || '').trim()).filter(Boolean) : []
  const topActivities = Array.isArray(exerciseSummary?.topActivities) ? exerciseSummary.topActivities.map((item: any) => String(item?.name || '').trim()).filter(Boolean) : []

  pushReportItem(
    next.overview.working,
    'Strong weekly data signal',
    `${coverage.daysActive || 0} active day(s) and ${coverage.totalEvents || 0} total entries gave this report enough signal to compare habits with ${focus}.\nThis is the right foundation for a useful weekly health report.`,
    4
  )
  if (goals.length) {
    pushReportItem(
      next.overview.working,
      'Goals are clear enough to personalize',
      `Your current goals include ${goals.slice(0, 4).join(', ')}.\nThat lets the report connect food, supplements, medications, mood, symptoms, and exercise to the outcomes you actually care about.`,
      4
    )
  }
  if (Array.isArray(checkinSummary?.goals) && checkinSummary.goals.length) {
    pushReportItem(
      next.overview.working,
      'Check-ins connect habits to outcomes',
      `${checkinSummary.goals.length} goal check-in area(s) were available this week.\nThose scores help show whether current routines are lining up with energy, libido, digestion, mood, or recovery.`,
      4
    )
  }
  pushReportItem(
    next.overview.suggested,
    'Pick the strongest pattern for next week',
    `This report has ${coverage.foodCount || 0} food entries, ${coverage.waterCount || 0} water entries, and ${coverage.exerciseCount || 0} exercise entries.\nChoose one pattern from those areas to repeat for 7 days so the next comparison is cleaner.`,
    4
  )
  pushReportItem(
    next.overview.suggested,
    'Use symptoms and mood as the scoreboard',
    `Mood entries (${coverage.moodCount || 0}) and symptom entries (${coverage.symptomCount || 0}) are the clearest feedback signals.\nCompare them against food, hydration, supplements, medications, and exercise timing before changing the whole routine.`,
    4
  )
  pushReportItem(
    next.overview.avoid,
    'Changing too many things at once',
    `This report is comparing many inputs at the same time: food, fluids, supplements, medications, movement, mood, symptoms, and check-ins.\nAvoid changing several big things in one week, because it makes the next report much harder to trust.`,
    4
  )
  if (supplements.length >= 6) {
    pushReportItem(
      next.overview.avoid,
      'Adding more to an already large stack',
      `Your current supplement list has ${supplements.length} item(s).\nAvoid adding more products until the report can show which current items line up with better energy, libido, digestion, mood, symptoms, or recovery.`,
      4
    )
  }

  if (nutritionSummary?.daysWithLogs || coverage.foodCount) {
    if (topFoods.length) {
      pushReportItem(
        next.nutrition.working,
        'Real food pattern captured',
        `Top logged foods this week included ${topFoods.slice(0, 5).join(', ')}.\nThat gives the report real meals to compare with energy, digestion, bowel movements, mood, and symptoms.`,
        4
      )
    }
    if (nutritionSummary?.dailyAverages?.protein_g) {
      pushReportItem(
        next.nutrition.working,
        'Protein baseline is visible',
        `Average protein was about ${nutritionSummary.dailyAverages.protein_g}g per day.\nThat matters for recovery, libido support, hunger, and steady energy.`,
        4
      )
    }
    if (nutritionSummary?.dailyAverages?.fiber_g) {
      pushReportItem(
        next.nutrition.working,
        'Fiber can now be compared with digestion',
        `Average fiber was about ${nutritionSummary.dailyAverages.fiber_g}g per day.\nThat gives the report a bowel-movement and digestion signal to compare next week.`,
        4
      )
    }
    pushReportItem(
      next.nutrition.suggested,
      'Make one meal a clear protein anchor',
      `Food logs show ${coverage.foodCount || 0} entries across ${nutritionSummary.daysWithLogs || 0} day(s).\nChoose one meal each day with an obvious protein source so energy, hunger, libido, and recovery patterns are easier to read.`,
      4
    )
    pushReportItem(
      next.nutrition.suggested,
      'Pair digestion goals with fiber and fluids',
      `Bowel Movements is one of the saved goals, and average fiber was ${nutritionSummary?.dailyAverages?.fiber_g || 0}g while water averaged ${hydrationSummary?.dailyAverageMl || 0} ml.\nUse those two numbers together instead of judging digestion from food alone.`,
      4
    )
    if ((dataFlags.sugarSpikes || []).length) {
      pushReportItem(
        next.nutrition.avoid,
        'Stacking sugar on symptom-heavy days',
        `Sugar was higher on ${(dataFlags.sugarSpikes || []).map((d: any) => d.date).slice(0, 3).join(', ')}.\nAvoid making those days your normal pattern until you compare them with energy, headaches, mood, and digestion.`,
        4
      )
    }
    if ((dataFlags.sodiumSpikes || []).length) {
      pushReportItem(
        next.nutrition.avoid,
        'Letting salty meals sit without water balance',
        `Sodium was highest on ${(dataFlags.sodiumSpikes || []).map((d: any) => d.date).slice(0, 3).join(', ')}.\nAvoid judging headaches, energy, or recovery on those days without also looking at water intake.`,
        4
      )
    }
    pushReportItem(
      next.nutrition.avoid,
      'Judging food from calories only',
      `The report has calories plus protein, carbs, fat, fiber, sugar, sodium, and actual food names.\nAvoid focusing only on calories, because digestion, libido, energy, and recovery often depend on the full pattern.`,
      4
    )
  }

  if (hydrationSummary?.daysWithLogs || coverage.waterCount) {
    pushReportItem(
      next.hydration.working,
      'Hydration was tracked often enough to compare',
      `${coverage.waterCount || 0} drink entries were logged across ${hydrationSummary.daysWithLogs || 0} day(s), averaging about ${hydrationSummary.dailyAverageMl || 0} ml per day.\nThat is useful for reading energy, headaches, bowel movements, and recovery.`,
      4
    )
    if (topDrinks.length) {
      pushReportItem(
        next.hydration.working,
        'Drink types are visible',
        `Common drinks included ${topDrinks.slice(0, 4).join(', ')}.\nThat helps separate plain water patterns from coffee, tea, mineral water, or sweet drinks.`,
        4
      )
    }
    if (correlationSignals.hydrationMood) {
      pushReportItem(
        next.hydration.working,
        'Water has a mood comparison signal',
        `Mood averaged ${correlationSignals.hydrationMood.highAvg} on higher-water days vs ${correlationSignals.hydrationMood.lowAvg} on lower-water days.\nThat makes hydration worth keeping steady next week.`,
        4
      )
    }
    pushReportItem(
      next.hydration.suggested,
      'Front-load water earlier',
      `Average water was ${hydrationSummary.dailyAverageMl || 0} ml per day.\nTry getting the first bottle in earlier so headaches, energy, bowel movements, and training feel easier to compare.`,
      4
    )
    if ((dataFlags.lowHydrationDays || []).length) {
      pushReportItem(
        next.hydration.suggested,
        'Fix the lowest-water days first',
        `Lower-water days showed up on ${(dataFlags.lowHydrationDays || []).map((d: any) => d.date).slice(0, 3).join(', ')}.\nImproving those days will tell more than adding extra water on already good days.`,
        4
      )
      pushReportItem(
        next.hydration.avoid,
        'Letting low-water days explain every symptom',
        `Low-water days can affect energy, headaches, digestion, and recovery.\nAvoid blaming supplements, medications, or food changes until water is steadier on those low days.`,
        4
      )
    }
    pushReportItem(
      next.hydration.avoid,
      'Counting sweet drinks as the whole hydration plan',
      `The report can see drink names, not just total fluid.\nAvoid relying on sweet drinks, coffee, or tea as the whole hydration base if headaches, energy, or digestion are the goal.`,
      4
    )
  }

  if (exerciseSummary?.sessions || coverage.exerciseCount) {
    pushReportItem(
      next.exercise.working,
      'Movement routine is active',
      `${exerciseSummary.sessions || coverage.exerciseCount || 0} session(s) and about ${exerciseSummary.totalMinutes || 0} total minute(s) were logged this week.\nThat is useful support for energy, libido, mood, recovery, and sleep quality.`,
      4
    )
    if (topActivities.length) {
      pushReportItem(
        next.exercise.working,
        'Training variety is visible',
        `Logged activity included ${topActivities.slice(0, 4).join(', ')}.\nThat gives the report enough variety to compare strength, cardio, walking, and recovery days.`,
        4
      )
    }
    if (correlationSignals.exerciseMood) {
      pushReportItem(
        next.exercise.working,
        'Movement lines up with mood',
        `Mood averaged ${correlationSignals.exerciseMood.highAvg} on higher-movement days vs ${correlationSignals.exerciseMood.lowAvg} on lower-movement days.\nThat is a useful reason to protect short movement sessions.`,
        4
      )
    }
    pushReportItem(
      next.exercise.suggested,
      'Protect recovery after harder sessions',
      `This week included about ${exerciseSummary.totalMinutes || 0} movement minute(s).\nMatch harder sessions with enough water, protein, and magnesium-style recovery support before adding more intensity.`,
      4
    )
    pushReportItem(
      next.exercise.suggested,
      'Keep at least one easy movement day',
      `Energy, libido, sleep quality, and recovery are saved goals.\nUse one easy walk or mobility day to see whether symptoms and mood improve without extra training stress.`,
      4
    )
    if ((dataFlags.lowActivityDays || []).length) {
      pushReportItem(
        next.exercise.avoid,
        'All-or-nothing movement weeks',
        `Movement dropped on ${(dataFlags.lowActivityDays || []).map((d: any) => d.date).slice(0, 3).join(', ')}.\nAvoid making exercise either hard or nothing; short easy sessions give the report a cleaner signal.`,
        4
      )
    }
    pushReportItem(
      next.exercise.avoid,
      'Adding intensity while recovery signals are unclear',
      `The report is also watching water, protein, mood, symptoms, and sleep-quality goals.\nAvoid increasing training load if those recovery signals are moving the wrong way.`,
      4
    )
  }

  if (moodSummary?.entries || coverage.moodCount) {
    pushReportItem(
      next.mood.working,
      'Mood was tracked enough to compare',
      `${coverage.moodCount || moodSummary.entries || 0} mood entry/entries were available this week, with an average around ${moodSummary.averageMood ?? 'not set'}.\nThat helps judge whether food, hydration, exercise, supplements, and medication timing are helping or hurting.`,
      4
    )
    const moodTrend = trendSignals.find((item: any) => String(item?.metric || '').toLowerCase() === 'mood')
    if (moodTrend) {
      pushReportItem(
        next.mood.working,
        'Mood trend is measurable',
        `Mood moved from ${moodTrend.firstAvg} to ${moodTrend.secondAvg} across the week.\nThat gives next week a clear comparison point.`,
        4
      )
    }
    pushReportItem(
      next.mood.suggested,
      'Compare mood with water and movement first',
      `The same week has ${coverage.waterCount || 0} water entries and ${coverage.exerciseCount || 0} exercise entries.\nCheck those before assuming mood changes came from supplements or medications.`,
      4
    )
    if ((dataFlags.lowMoodDays || []).length) {
      pushReportItem(
        next.mood.suggested,
        'Look at the lowest mood days',
        `Lower-mood days showed on ${(dataFlags.lowMoodDays || []).map((d: any) => d.date).slice(0, 3).join(', ')}.\nCompare those days with food timing, sugar, water, exercise, and medication timing.`,
        4
      )
    }
    pushReportItem(
      next.mood.avoid,
      'Treating one low mood day as the whole story',
      `This report has a 7-day mood pattern, not just one day.\nAvoid changing supplements or medications from one low score without checking the surrounding food, sleep-quality goal, water, and exercise pattern.`,
      4
    )
  }

  if (symptomSummary?.entries || coverage.symptomCount) {
    pushReportItem(
      next.symptoms.working,
      'Symptoms were captured for pattern finding',
      `${coverage.symptomCount || symptomSummary.entries || 0} symptom entry/entries were available this week.\nThat gives the report something real to compare against food, hydration, mood, medication timing, and supplement changes.`,
      4
    )
    if (topSymptoms.length) {
      pushReportItem(
        next.symptoms.working,
        'Top symptoms are visible',
        `Common symptoms included ${topSymptoms.slice(0, 4).join(', ')}.\nThat helps focus the report on the symptoms that actually repeated.`,
        4
      )
    }
    pushReportItem(
      next.symptoms.suggested,
      'Compare symptoms with same-day meals',
      `Food logs include ${coverage.foodCount || 0} entries this week.\nUse same-day food, fluids, and meal timing to check whether symptoms repeat after similar patterns.`,
      4
    )
    pushReportItem(
      next.symptoms.suggested,
      'Use hydration as a first filter',
      `Water averaged about ${hydrationSummary.dailyAverageMl || 0} ml per day.\nBefore blaming a supplement or medication, compare symptom-heavy days with lower-water days.`,
      4
    )
    if ((dataFlags.symptomHeavyDays || []).length) {
      pushReportItem(
        next.symptoms.avoid,
        'Ignoring symptom-heavy days',
        `Symptoms were heavier on ${(dataFlags.symptomHeavyDays || []).map((d: any) => d.date).slice(0, 3).join(', ')}.\nAvoid treating those as random; they are the best days to compare against sugar, late meals, water, and stress.`,
        4
      )
    }
    if (correlationSignals.sugarSymptoms) {
      pushReportItem(
        next.symptoms.avoid,
        'Repeating higher-sugar symptom days',
        `Symptoms averaged ${correlationSignals.sugarSymptoms.highAvg} on higher-sugar days vs ${correlationSignals.sugarSymptoms.lowAvg} on lower-sugar days.\nAvoid repeating the higher-sugar pattern until the symptom link is clearer.`,
        4
      )
    }
  }

  if (journalSummary?.entries || mealTimingSummary?.lateMealDays?.length || mealTimingSummary?.lateSnackDays?.length || coverage.checkinCount) {
    pushReportItem(
      next.lifestyle.working,
      'Lifestyle notes and check-ins add context',
      `${coverage.checkinCount || 0} check-in entry/entries and ${journalSummary.entries || 0} journal note(s) were available.\nThat gives the report context beyond food, supplements, and medications.`,
      4
    )
    if (mealTimingSummary?.lateMealDays?.length) {
      pushReportItem(
        next.lifestyle.avoid,
        'Late meals on repeat',
        `Late meals showed up on ${mealTimingSummary.lateMealDays.slice(0, 3).join(', ')}.\nAvoid repeating that pattern if sleep quality, digestion, morning energy, or symptoms are worse afterward.`,
        4
      )
    }
    if (mealTimingSummary?.lateSnackDays?.length) {
      pushReportItem(
        next.lifestyle.avoid,
        'Late snacks without checking next day',
        `Late snacks showed up on ${mealTimingSummary.lateSnackDays.slice(0, 3).join(', ')}.\nAvoid judging sleep quality or morning energy without checking whether those snack nights were different.`,
        4
      )
    }
    pushReportItem(
      next.lifestyle.suggested,
      'Keep evening routine steady for one week',
      `Sleep Quality and Energy are saved goals.\nKeep meal timing, caffeine, fluids, and magnesium timing steadier for 7 days so the next report can spot what changes.`,
      4
    )
    pushReportItem(
      next.lifestyle.suggested,
      'Add one short note on unusual days',
      `${journalSummary.entries || 0} journal note(s) were available this week.\nA short note on headache, digestion, libido, or low-energy days will make next week’s report much sharper.`,
      4
    )
    pushReportItem(
      next.lifestyle.avoid,
      'Moving bedtime, meals, and supplements together',
      `The report is trying to compare sleep quality, energy, digestion, libido, and recovery.\nAvoid changing bedtime, late food, and supplement timing all at once.`,
      4
    )
  }

  if (labHighlights.length || labTrends.length || coverage.labCount) {
    if (labHighlights.length) {
      pushReportItem(
        next.labs.working,
        'Lab highlights are available',
        `${labHighlights.length} lab highlight(s) were available for this report.\nThat gives supplement and medication advice a stronger safety check than symptoms alone.`,
        4
      )
    }
    if (labTrends.length) {
      pushReportItem(
        next.labs.working,
        'Lab movement can be compared',
        `${labTrends[0]?.name || 'A marker'} moved ${labTrends[0]?.direction || 'across results'} compared with the prior result.\nTrend direction matters more than one isolated number.`,
        4
      )
    }
    pushReportItem(
      next.labs.suggested,
      'Use labs before adding high-dose nutrients',
      `${supplements.length} supplement(s) are listed in the current stack.\nUse lab data before adding high-dose vitamin D, iron, zinc, B vitamins, or hormone-focused products.`,
      4
    )
    pushReportItem(
      next.labs.avoid,
      'Guessing from labs without a clinician',
      `Lab data can change supplement and medication decisions.\nAvoid changing medication or high-dose supplement plans from a lab note without a clinician review.`,
      4
    )
  }

  if (riskFlags.length) {
    for (const flag of riskFlags.slice(0, 3)) {
      pushReportItem(next.overview.avoid, String(flag?.name || 'Risk flag'), String(flag?.reason || ''), 4)
    }
  }

  const empty = { working: [], suggested: [], avoid: [] }
  if (!supplements.length) next.supplements = { ...empty }
  if (!medications.length) next.medications = { ...empty }
  if (!(nutritionSummary?.daysWithLogs || coverage.foodCount)) next.nutrition = { ...empty }
  if (!(hydrationSummary?.daysWithLogs || coverage.waterCount)) next.hydration = { ...empty }
  if (!(exerciseSummary?.sessions || coverage.exerciseCount)) next.exercise = { ...empty }
  if (!(moodSummary?.entries || coverage.moodCount)) next.mood = { ...empty }
  if (!(symptomSummary?.entries || coverage.symptomCount)) next.symptoms = { ...empty }
  if (!(journalSummary?.entries || mealTimingSummary?.lateMealDays?.length || mealTimingSummary?.lateSnackDays?.length || coverage.checkinCount)) {
    next.lifestyle = { ...empty }
  }
  if (!(labHighlights.length || labTrends.length || coverage.labCount)) next.labs = { ...empty }

  return next
}

function buildSupplementGuidance(context: any): Pick<ReportSectionBucket, 'suggested' | 'avoid'> {
  const supplements = Array.isArray(context?.supplements) ? context.supplements : []
  const medications = Array.isArray(context?.medications) ? context.medications : []
  const { goalLabels, issueLabels, focusLabels, focusText } = focusContextFromReport(context)
  const knownSupplements = buildKnownNameSet(supplements)
  const lowHydrationDays = Array.isArray(context?.dataFlags?.lowHydrationDays) ? context.dataFlags.lowHydrationDays : []
  const lowMoodDays = Array.isArray(context?.dataFlags?.lowMoodDays) ? context.dataFlags.lowMoodDays : []
  const symptomHeavyDays = Array.isArray(context?.dataFlags?.symptomHeavyDays) ? context.dataFlags.symptomHeavyDays : []
  const topSymptoms = Array.isArray(context?.symptomSummary?.topSymptoms) ? context.symptomSummary.topSymptoms : []
  const currentSupplementNames: string[] = supplements.map((item: any) => String(item?.name || '').trim()).filter(Boolean)
  const currentMedicationNames: string[] = medications.map((item: any) => String(item?.name || '').trim()).filter(Boolean)

  const hasSupplement = (pattern: RegExp) =>
    supplements.some((item: any) => pattern.test(String(item?.name || '').toLowerCase()))
  const findSupplements = (pattern: RegExp) =>
    supplements.filter((item: any) => pattern.test(String(item?.name || '').toLowerCase()))
  const addUnique = (bucket: ReportItem[], name: string, reason: string) => {
    const key = canonicalizeNameForMatch(name)
    if (!key) return
    if (bucket.some((item) => canonicalizeNameForMatch(String(item?.name || '')) === key)) return
    if (knownSupplements.has(key)) return
    bucket.push({ name, reason })
  }
  const pickFocusLabel = (patterns: RegExp[], fallback: string) =>
    focusLabels.find((label) => patterns.some((pattern) => pattern.test(label.toLowerCase()))) || fallback

  const suggested: ReportItem[] = []
  const avoid: ReportItem[] = []

  const libidoFocus = /libido|erection|sexual|testosterone/.test(focusText)
  const moodFocus = /mood|stress|anxiety|depression|focus|brain fog/.test(focusText)
  const gutFocus = /bowel|digestion|gut|bloat|constipation|diarrh|stomach|ibs|reflux/.test(focusText)
  const energyFocus = /energy|fatigue|tired|motivation/.test(focusText)
  const sleepFocus = /sleep|insomnia|rest/.test(focusText)
  const exerciseMinutes = Number(context?.exerciseSummary?.totalMinutes || 0)
  const labHighlights = Array.isArray(context?.labs?.highlights) ? context.labs.highlights : []
  const hasKidneyConcern = /kidney|renal/.test(focusText)
  const onVascularMedication = currentMedicationNames.some((name: string) =>
    /tadalafil|sildenafil|vardenafil|avanafil|nitroglycerin|nitrate/.test(name.toLowerCase())
  )

  if (libidoFocus && !onVascularMedication && !hasSupplement(/\bcitrulline\b/i)) {
    const focus = pickFocusLabel([/libido/, /erection/, /sexual/, /testosterone/], 'libido support')
    addUnique(
      suggested,
      'L-Citrulline',
      `Your goals mention ${focus}, and your current stack already includes ${formatSupplementNameList(currentSupplementNames)}.\nL-Citrulline is one to review if you want a more targeted option that is not already in the stack.`
    )
  }

  if (libidoFocus && onVascularMedication) {
    addUnique(
      avoid,
      'Extra blood-flow supplements without review',
      `Your goals mention ${pickFocusLabel([/libido/, /erection/, /sexual/, /testosterone/], 'libido or erections')}, and your medication list includes a blood-flow medicine.\nSteer away from adding L-Citrulline, arginine, beetroot, or similar products unless your prescriber says it fits.`
    )
  }

  if ((moodFocus || lowMoodDays.length >= 2) && !hasSupplement(/omega[\s-]*3|fish oil|epa|dha/i)) {
    const focus = pickFocusLabel([/mood/, /stress/, /anxiety/, /focus/, /brain fog/], 'mood support')
    addUnique(
      suggested,
      'Omega-3',
      `${focus} shows up in your goals${lowMoodDays.length ? `, and ${lowMoodDays.length} lower-mood day(s) showed up in this report` : ''}. Omega-3 does not appear in your current stack.\nIt is one to review before piling on more overlapping vitamins.`
    )
  }

  if ((gutFocus || topSymptoms.some((item: any) => /bloat|constipation|diarrh|reflux|gut|stomach/i.test(String(item?.name || '').toLowerCase()))) && !hasSupplement(/psyllium|fiber|fibre/i)) {
    const topSymptom = topSymptoms.map((item: any) => String(item?.name || '').trim()).filter(Boolean)[0]
    addUnique(
      suggested,
      'Psyllium husk',
      `${pickFocusLabel([/bowel/, /digestion/, /gut/, /bloat/, /constipation/, /diarrh/, /reflux/], 'Digestion')} shows up in your report${topSymptom ? `, with ${topSymptom} also logged this week` : ''}. Psyllium husk does not appear in your current stack.\nIt is a simpler option to review before adding a bigger gut blend.`
    )
  }

  if (lowHydrationDays.length >= 2 && !hasSupplement(/electrolyte|hydration/i)) {
    addUnique(
      suggested,
      'Electrolyte support',
      `${lowHydrationDays.length} lower-water day(s) showed up this week, and no electrolyte product appears in your current stack of ${currentSupplementNames.length} supplement(s).\nA simple electrolyte option may fit better than adding another random capsule.`
    )
  }

  if ((exerciseMinutes >= 60 || /strength|muscle|training|performance/.test(focusText)) && !hasKidneyConcern && !hasSupplement(/\bcreatine\b/i)) {
    addUnique(
      suggested,
      'Creatine monohydrate',
      `You logged about ${exerciseMinutes || 0} minutes of movement this week, and creatine does not appear in your current stack.\nIf performance or recovery matters to you, this is one to review before adding more niche products.`
    )
  }

  if ((sleepFocus || moodFocus) && !hasKidneyConcern && !hasSupplement(/magnesium/i)) {
    const focus = pickFocusLabel([/sleep/, /stress/, /mood/, /anxiety/], 'sleep or stress support')
    addUnique(
      suggested,
      'Magnesium glycinate',
      `Your goals mention ${focus}, and magnesium does not appear in your current stack of ${currentSupplementNames.length} supplement(s).\nIt is a more focused option than adding another mixed calming blend.`
    )
  }

  const zincProducts = findSupplements(/\bzinc\b/i)
  if (zincProducts.length >= 2) {
    addUnique(
      avoid,
      'Extra zinc products',
      `Your current stack already includes ${formatSupplementNameList(zincProducts.map((item: any) => String(item?.name || '').trim()), 4)}. That is ${zincProducts.length} zinc product(s) before adding anything else.\nSteer away from extra zinc products unless a clinician gives a clear reason.`
    )
  }

  const vitaminDProducts = findSupplements(/vitamin\s*d|\bd-?3\b/i)
  const totalVitaminDIu = vitaminDProducts.reduce((sum: number, item: any) => {
    const parsed = parseSupplementDose(item?.dosage)
    if (!parsed) return sum
    if (parsed.unit === 'iu') return sum + parsed.amount
    return sum
  }, 0)
  if (totalVitaminDIu >= 4000) {
    addUnique(
      avoid,
      'More vitamin D on top',
      `Your current stack already shows ${formatSupplementNameList(vitaminDProducts.map((item: any) => String(item?.name || '').trim()))} at about ${Math.round(totalVitaminDIu)} IU total.\nSteer away from adding more vitamin D on top until labs say it is needed.`
    )
  }

  const vitaminCProducts = findSupplements(/vitamin\s*c|\bascorb/i)
  const totalVitaminCMg = vitaminCProducts.reduce((sum: number, item: any) => {
    const parsed = parseSupplementDose(item?.dosage)
    if (!parsed) return sum
    if (parsed.unit === 'mg') return sum + parsed.amount
    if (parsed.unit === 'g') return sum + parsed.amount * 1000
    if (parsed.unit === 'mcg') return sum + parsed.amount / 1000
    return sum
  }, 0)
  if (totalVitaminCMg >= 1000) {
    addUnique(
      avoid,
      'More vitamin C on top',
      `Your current stack already shows about ${Math.round(totalVitaminCMg)} mg of vitamin C, which is already a large daily dose.\nSteer away from piling more vitamin C on top of that dose.`
    )
  }

  if ((libidoFocus || energyFocus) && currentSupplementNames.length >= 6) {
    addUnique(
      avoid,
      'Testosterone booster blends',
      `Your goals mention ${pickFocusLabel([/libido/, /erection/, /sexual/, /testosterone/, /energy/, /fatigue/], 'energy or performance')}, and your current routine already lists ${currentSupplementNames.length} supplements.\nSteer away from testosterone booster blends because they make it harder to tell what is really helping.`
    )
  }

  if ((lowMoodDays.length >= 2 || symptomHeavyDays.length >= 2) && currentSupplementNames.length >= 6) {
    addUnique(
      avoid,
      'High-stimulant pre-workouts',
      `${lowMoodDays.length} lower-mood day(s) and ${symptomHeavyDays.length} heavier-symptom day(s) showed up this week, while your current routine already lists ${currentSupplementNames.length} supplements.\nSteer away from high-stimulant pre-workouts if you want cleaner feedback from the report.`
    )
  }

  if (avoid.length < 2 && currentSupplementNames.length >= 6) {
    addUnique(
      avoid,
      'Extra multi-ingredient blends',
      `Your current routine already lists ${currentSupplementNames.length} supplements, which is a big stack to judge cleanly.\nSteer away from adding another big multi-ingredient blend all at once.`
    )
  }

  if (!suggested.length && !hasSupplement(/omega[\s-]*3|fish oil|epa|dha/i)) {
    const fallbackFocus = goalLabels[0] || issueLabels[0] || 'your current goals'
    addUnique(
      suggested,
      'Omega-3',
      `${fallbackFocus} is one of the focus areas in this report, and omega-3 does not appear in your current stack of ${currentSupplementNames.length} supplement(s).\nIt is one of the cleaner gaps to review before adding more overlap.`
    )
  }

  if (!suggested.length && !hasSupplement(/probiotic/i)) {
    const symptomLabel = topSymptoms.map((item: any) => String(item?.name || '').trim()).filter(Boolean)[0] || 'your current symptoms'
    addUnique(
      suggested,
      'Probiotic',
      `${symptomLabel} shows up in this report, and probiotic support does not appear in your current stack.\nIt is one simple option to review if you want to add something new carefully.`
    )
  }

  if (suggested.length < 3 && currentSupplementNames.length >= 6) {
    addUnique(
      suggested,
      'One-at-a-time supplement review',
      `Your current routine already lists ${currentSupplementNames.length} supplements, including ${formatSupplementNameList(currentSupplementNames, 4)}.\nBefore adding more, pick one current supplement to keep especially consistent for 7 days and compare it with libido, digestion, energy, mood, symptoms, and recovery.`
    )
  }

  if (suggested.length < 3 && currentSupplementNames.length >= 4) {
    addUnique(
      suggested,
      'Match timing to the goal',
      `Your supplement list has enough items that timing matters, not just the product names.\nMatch morning items to energy/libido goals and evening items to sleep/recovery goals so the next report can judge the pattern more clearly.`
    )
  }

  if (!avoid.length && labHighlights.length) {
    addUnique(
      avoid,
      'Iron unless labs clearly need it',
      `${labHighlights.length} lab highlight(s) showed up in this report, but the report should stay targeted to what those labs actually show.\nSteer away from adding iron just in case unless a lab result clearly points that way.`
    )
  }

  return {
    suggested: suggested.slice(0, 3),
    avoid: avoid.slice(0, 3),
  }
}

function applySupplementGuidance(
  sections: Record<ReportSectionKey, ReportSectionBucket>,
  context: any
): Record<ReportSectionKey, ReportSectionBucket> {
  const next = { ...sections }
  const supplements = next.supplements || { working: [], suggested: [], avoid: [] }
  const medications = next.medications || { working: [], suggested: [], avoid: [] }
  const guidance = buildSupplementGuidance(context)
  const supplementWorking = buildSupplementWorkingItems(context)
  const medicationGuidance = buildMedicationGuidance(context)
  const mergeBucket = (existing: ReportItem[], additions: ReportItem[], max = 4) => {
    const merged = Array.isArray(existing) ? [...existing] : []
    for (const item of additions || []) {
      pushReportItem(merged, String(item?.name || ''), String(item?.reason || ''), max)
    }
    return merged
  }

  if (supplementWorking.length && (!Array.isArray(supplements.working) || supplements.working.length < Math.min(6, supplementWorking.length))) {
    const existing = Array.isArray(supplements.working) ? supplements.working : []
    const existingNames = new Set(existing.map((item) => canonicalizeNameForMatch(String(item?.name || ''))).filter(Boolean))
    supplements.working = [
      ...existing,
      ...supplementWorking.filter((item) => {
        const key = canonicalizeNameForMatch(String(item?.name || ''))
        return key && !existingNames.has(key)
      }),
    ].slice(0, 10)
  }

  supplements.suggested = mergeBucket(supplements.suggested || [], guidance.suggested || [], 4)
  supplements.avoid = mergeBucket(supplements.avoid || [], guidance.avoid || [], 4)

  medications.working = mergeBucket(medications.working || [], medicationGuidance.working || [], 4)
  medications.suggested = mergeBucket(medications.suggested || [], medicationGuidance.suggested || [], 4)
  medications.avoid = mergeBucket(medications.avoid || [], medicationGuidance.avoid || [], 4)

  next.supplements = supplements
  next.medications = medications
  return next
}

function dedupeReportSections(
  sections: Record<ReportSectionKey, ReportSectionBucket>
): Record<ReportSectionKey, ReportSectionBucket> {
  const seen = new Set<string>()
  const output = buildDefaultSections()
  for (const key of REPORT_SECTIONS) {
    const section = sections[key] || { working: [], suggested: [], avoid: [] }
    const dedupeBucket = (items: ReportItem[]) => {
      const unique: ReportItem[] = []
      for (const item of items) {
        const normalized = normalizeReportItem(item)
        const identity = `${normalized.name.toLowerCase()}|${normalized.reason.toLowerCase()}`
        if (!normalized.name && !normalized.reason) continue
        if (seen.has(identity)) continue
        seen.add(identity)
        unique.push(normalized)
      }
      return unique
    }
    output[key] = {
      working: dedupeBucket(section.working || []),
      suggested: dedupeBucket(section.suggested || []),
      avoid: dedupeBucket(section.avoid || []),
    }
  }
  return output
}

function resolveDayKey(localDate?: string | null, createdAt?: Date | string | null) {
  const local = String(localDate || '').trim()
  if (local) return local
  if (!createdAt) return ''
  const date = typeof createdAt === 'string' ? new Date(createdAt) : createdAt
  if (Number.isNaN(date.getTime())) return ''
  return date.toISOString().slice(0, 10)
}

function normalizeMealLabel(input?: string | null) {
  const raw = String(input || '').trim().toLowerCase()
  if (!raw) return 'other'
  if (raw.includes('breakfast')) return 'breakfast'
  if (raw.includes('lunch')) return 'lunch'
  if (raw.includes('dinner')) return 'dinner'
  if (raw.includes('snack')) return 'snacks'
  return raw
}

function formatLocalDate(date: Date, timezone: string) {
  try {
    return new Intl.DateTimeFormat('en-CA', {
      timeZone: timezone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    }).format(date)
  } catch {
    return date.toISOString().slice(0, 10)
  }
}

function formatLocalHour(date: Date, timezone: string) {
  try {
    const hourText = new Intl.DateTimeFormat('en-GB', {
      timeZone: timezone,
      hour: '2-digit',
      hour12: false,
    }).format(date)
    const hour = Number(hourText)
    return Number.isFinite(hour) ? hour : date.getUTCHours()
  } catch {
    return date.getUTCHours()
  }
}

function formatLocalTime(date: Date, timezone: string) {
  try {
    return new Intl.DateTimeFormat('en-US', {
      timeZone: timezone,
      hour: 'numeric',
      minute: '2-digit',
      hour12: true,
    }).format(date)
  } catch {
    return date.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })
  }
}

function buildNutritionSummary(
  foodLogs: Array<{ name: string | null; nutrients: any; createdAt: Date; localDate?: string | null; meal?: string | null }>
) {
  const totals = {
    calories: 0,
    protein_g: 0,
    carbs_g: 0,
    fat_g: 0,
    fiber_g: 0,
    sugar_g: 0,
    sodium_mg: 0,
  }
  let counted = 0
  const foodCount = new Map<string, { name: string; count: number }>()
  const dayTotals = new Map<
    string,
    {
      date: string
      entries: number
      calories: number
      protein_g: number
      carbs_g: number
      fat_g: number
      fiber_g: number
      sugar_g: number
      sodium_mg: number
      meals: Record<string, number>
    }
  >()

  for (const f of foodLogs) {
    const n = (f && f.nutrients) || {}
    const cals = Number(n.calories ?? n.kcal ?? 0) || 0
    const protein = Number(n.protein_g ?? n.protein ?? 0) || 0
    const carbs = Number(n.carbs_g ?? n.carbohydrates_g ?? n.carbohydrates ?? 0) || 0
    const fat = Number(n.fat_g ?? n.total_fat_g ?? 0) || 0
    const fiber = Number(n.fiber_g ?? n.dietary_fiber_g ?? 0) || 0
    const sugar = Number(n.sugar_g ?? n.sugars_g ?? 0) || 0
    const sodium = Number(n.sodium_mg ?? n.salt_mg ?? 0) || 0
    if (cals || protein || carbs || fat || fiber || sugar || sodium) {
      totals.calories += cals
      totals.protein_g += protein
      totals.carbs_g += carbs
      totals.fat_g += fat
      totals.fiber_g += fiber
      totals.sugar_g += sugar
      totals.sodium_mg += sodium
      counted += 1
    }
    const rawName = String(f.name || '').trim()
    const key = rawName.toLowerCase()
    if (key) {
      const existing = foodCount.get(key) || { name: rawName, count: 0 }
      existing.count += 1
      foodCount.set(key, existing)
    }

    const dayKey = resolveDayKey(f.localDate ?? null, f.createdAt)
    if (dayKey) {
      const existing = dayTotals.get(dayKey) || {
        date: dayKey,
        entries: 0,
        calories: 0,
        protein_g: 0,
        carbs_g: 0,
        fat_g: 0,
        fiber_g: 0,
        sugar_g: 0,
        sodium_mg: 0,
        meals: {},
      }
      existing.entries += 1
      existing.calories += cals
      existing.protein_g += protein
      existing.carbs_g += carbs
      existing.fat_g += fat
      existing.fiber_g += fiber
      existing.sugar_g += sugar
      existing.sodium_mg += sodium
      const mealKey = normalizeMealLabel(f.meal ?? null)
      existing.meals[mealKey] = (existing.meals[mealKey] || 0) + 1
      dayTotals.set(dayKey, existing)
    }
  }

  const topFoods = Array.from(foodCount.values())
    .sort((a, b) => b.count - a.count)
    .slice(0, 5)
    .map((item) => ({ name: item.name, count: item.count }))

  const dailyTotals = Array.from(dayTotals.values()).sort((a, b) => a.date.localeCompare(b.date))

  return {
    entriesWithNutrients: counted,
    totals,
    dailyAverages: {
      calories: counted ? Math.round(totals.calories / 7) : 0,
      protein_g: counted ? +(totals.protein_g / 7).toFixed(1) : 0,
      carbs_g: counted ? +(totals.carbs_g / 7).toFixed(1) : 0,
      fat_g: counted ? +(totals.fat_g / 7).toFixed(1) : 0,
      fiber_g: counted ? +(totals.fiber_g / 7).toFixed(1) : 0,
      sugar_g: counted ? +(totals.sugar_g / 7).toFixed(1) : 0,
      sodium_mg: counted ? Math.round(totals.sodium_mg / 7) : 0,
    },
    daysWithLogs: dayTotals.size,
    dailyTotals,
    topFoods,
  }
}

function buildFoodHighlights(
  foodLogs: Array<{ name: string | null; createdAt: Date; localDate?: string | null }>
) {
  const overallCounts = new Map<string, { name: string; count: number }>()
  const dayCounts = new Map<string, Map<string, { name: string; count: number }>>()

  for (const log of foodLogs) {
    const name = String(log?.name || '').trim()
    if (name) {
      const key = name.toLowerCase()
      const existingOverall = overallCounts.get(key) || { name, count: 0 }
      existingOverall.count += 1
      overallCounts.set(key, existingOverall)
      const dayKey = resolveDayKey(log.localDate ?? null, log.createdAt)
      if (dayKey) {
        const existing = dayCounts.get(dayKey) || new Map()
        const existingDay = existing.get(key) || { name, count: 0 }
        existingDay.count += 1
        existing.set(key, existingDay)
        dayCounts.set(dayKey, existing)
      }
    }
  }

  const overallTopFoods = Array.from(overallCounts.values())
    .sort((a, b) => b.count - a.count)
    .slice(0, 8)
    .map((item) => ({ name: item.name, count: item.count }))

  const dailyTopFoods = Array.from(dayCounts.entries())
    .sort((a, b) => a[0].localeCompare(b[0]))
    .map(([date, counts]) => ({
      date,
      foods: Array.from(counts.values())
        .sort((a, b) => b.count - a.count)
        .slice(0, 3)
        .map((item) => ({ name: item.name, count: item.count })),
    }))

  return { overallTopFoods, dailyTopFoods }
}

function buildHydrationSummary(
  waterLogs: Array<{ amountMl: number | null; label?: string | null; localDate?: string | null; createdAt: Date }>
) {
  let totalMl = 0
  const daySet = new Set<string>()
  const labelCounts = new Map<string, { label: string; count: number }>()
  const dayTotals = new Map<string, { date: string; entries: number; totalMl: number }>()

  for (const log of waterLogs) {
    const ml = Number(log?.amountMl ?? 0) || 0
    totalMl += ml
    const day = resolveDayKey(log?.localDate ?? null, log?.createdAt ?? null)
    if (day) daySet.add(day)
    const rawLabel = String(log?.label || '').trim()
    const key = rawLabel.toLowerCase()
    if (key) {
      const existing = labelCounts.get(key)
      if (existing) {
        existing.count += 1
      } else {
        labelCounts.set(key, { label: rawLabel, count: 1 })
      }
    }
    if (day) {
      const existing = dayTotals.get(day) || { date: day, entries: 0, totalMl: 0 }
      existing.entries += 1
      existing.totalMl += ml
      dayTotals.set(day, existing)
    }
  }

  const topDrinks = Array.from(labelCounts.values())
    .sort((a, b) => b.count - a.count)
    .slice(0, 5)

  const roundedTotal = Math.round(totalMl * 10) / 10
  return {
    entries: waterLogs.length,
    totalMl: roundedTotal,
    dailyAverageMl: Math.round((roundedTotal / 7) * 10) / 10,
    daysWithLogs: daySet.size,
    topDrinks,
    dailyTotals: Array.from(dayTotals.values()).sort((a, b) => a.date.localeCompare(b.date)),
  }
}

function buildJournalSummary(
  entries: Array<{ content: string; createdAt: Date; localDate?: string | null }>,
  timezone: string
) {
  const daySet = new Set<string>()
  const highlights = entries.slice(0, 4).map((entry) => {
    const date = entry.localDate || formatLocalDate(entry.createdAt, timezone)
    daySet.add(date)
    return {
      date,
      time: formatLocalTime(entry.createdAt, timezone),
      note: clipText(entry.content || '', 180),
    }
  })
  return {
    entries: entries.length,
    daysWithNotes: daySet.size,
    highlights,
  }
}

function buildMedicalImageSummary(
  entries: Array<{ summary?: string | null; analysisText?: string | null; analysisData?: any; createdAt: Date }>,
  timezone: string
) {
  const daySet = new Set<string>()
  const highlights = entries.slice(0, 4).map((entry) => {
    const date = formatLocalDate(entry.createdAt, timezone)
    daySet.add(date)
    const possibleCauses = Array.isArray(entry?.analysisData?.possibleCauses)
      ? entry.analysisData.possibleCauses
          .map((item: any) => String(item?.name || '').trim())
          .filter(Boolean)
          .slice(0, 3)
      : []
    const redFlags = Array.isArray(entry?.analysisData?.redFlags)
      ? entry.analysisData.redFlags.map((item: any) => String(item || '').trim()).filter(Boolean)
      : []
    const nextSteps = Array.isArray(entry?.analysisData?.nextSteps)
      ? entry.analysisData.nextSteps.map((item: any) => String(item || '').trim()).filter(Boolean).slice(0, 2)
      : []

    const rawSummary = String(entry?.summary || '').trim()
    const rawAnalysis = String(entry?.analysisText || '').trim()
    const summary = clipText(rawSummary || rawAnalysis || 'Saved health image note.', 220)

    return {
      date,
      time: formatLocalTime(entry.createdAt, timezone),
      summary,
      possibleCauses,
      redFlags,
      nextSteps,
    }
  })

  return {
    entries: entries.length,
    daysWithScans: daySet.size,
    highlights,
  }
}

function buildJournalDigest(
  entries: Array<{ content: string; createdAt: Date; localDate?: string | null }>,
  timezone: string
) {
  const dayMap = new Map<string, { notes: Array<{ time: string; note: string }>; total: number }>()
  const sorted = [...entries].sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime())

  for (const entry of sorted) {
    const date = entry.localDate || formatLocalDate(entry.createdAt, timezone)
    const time = formatLocalTime(entry.createdAt, timezone)
    const bucket = dayMap.get(date) || { notes: [], total: 0 }
    bucket.total += 1
    if (bucket.notes.length < 3) {
      bucket.notes.push({ time, note: clipText(entry.content || '', 180) })
    }
    dayMap.set(date, bucket)
  }

  return Array.from(dayMap.entries())
    .sort((a, b) => a[0].localeCompare(b[0]))
    .map(([date, data]) => ({ date, notes: data.notes, count: data.total }))
}

function safeJsonStringify(value: any) {
  try {
    return JSON.stringify(value, (_key, val) => (typeof val === 'bigint' ? val.toString() : val))
  } catch {
    return ''
  }
}

function sliceList<T>(value: T[] | undefined | null, max: number) {
  return Array.isArray(value) ? value.slice(0, max) : value
}

