      time: formatLocalTime(entry.createdAt, timezone),
    })),
    timezone,
    nutritionSignals,
    mealTimingSummary,
    timeOfDayNutrition,
    overlapSignals: {
      symptomLateMealDays: symptomLateMealOverlap,
      symptomHighSugarDays: symptomHighSugarOverlap,
    },
    sectionSignals: {
      supplements: (user.supplements || []).length,
      medications: (user.medications || []).length,
      nutrition: { entries: coverage.foodCount, days: nutritionSummary.daysWithLogs || 0 },
      hydration: { entries: coverage.waterCount, days: hydrationSummary.daysWithLogs || 0 },
      exercise: { sessions: exerciseSummary.sessions, days: exerciseSummary.daysActive },
      mood: { entries: moodSummary.entries, days: moodSummary.daysWithLogs },
      symptoms: { entries: symptomSummary.entries, unique: symptomSummary.uniqueSymptoms },
      labs: { reports: coverage.labCount, trends: labTrends.length, highlights: labHighlights.length },
      talkToAi: { userMessages: talkToAiSummary.userMessageCount, days: talkToAiSummary.activeDays },
      journal: { entries: journalSummary.entries, days: journalSummary.daysWithNotes },
      medicalImages: { entries: medicalImageSummary.entries, days: medicalImageSummary.daysWithScans },
    },
  }

  const healthSituationsText = healthSituations
    ? clipText(typeof healthSituations === 'string' ? healthSituations : JSON.stringify(healthSituations), 600)
    : null

  const reportSignals = buildReportSignals({
    reportContext: {
      ...reportContext,
      healthSituations: healthSituationsText,
    },
    nutritionSummary,
    hydrationSummary,
    exerciseSummary,
    moodSummary,
    symptomSummary,
    checkinSummary,
    mealTimingSummary,
    timeOfDayNutrition,
    correlationSignals,
    trendSignals,
    riskFlags,
    dataFlags,
    overlapSignals: reportContext.overlapSignals,
    labHighlights,
    labTrends,
    medicalImageSummary,
    insightCandidates,
    talkToAiSummary,
    journalEntries: reportContext.journalEntries,
    dailyStats: compactDailyStats,
    nutritionSignals,
    timezone,
  })
  const MAX_LLM_CONTEXT_CHARS = 120000
  const modelInput = buildModelInput({ ...reportSignals, coverage })
  const modelPayload = shrinkModelPayload(modelInput, MAX_LLM_CONTEXT_CHARS)
  const llmPayloadJson = modelPayload.json
  const llmPayloadSize = modelPayload.size

  const model = 'gpt-5.6-sol'
  const weeklyLlmRaw = (process.env.ENABLE_WEEKLY_REPORT_LLM || '').toLowerCase().trim()
  const llmEnabled = weeklyLlmRaw ? weeklyLlmRaw === 'true' || weeklyLlmRaw === '1' || weeklyLlmRaw === 'yes' : true
  let reportPayload: any = null
  let summaryText = ''
  let llmUsage: { promptTokens: number; completionTokens: number; costCents: number; model: string } | null = null
  let chargeCents = preflightCostCents

  const llmPayloadReady = Boolean(llmPayloadJson) && llmPayloadSize <= MAX_LLM_CONTEXT_CHARS
  let llmStatus: 'ok' | 'disabled' | 'missing_key' | 'payload_too_large' | 'error' = 'disabled'
  if (!llmEnabled) {
    llmStatus = 'disabled'
  } else if (!process.env.OPENAI_API_KEY) {
    llmStatus = 'missing_key'
  } else if (!llmPayloadReady) {
    llmStatus = 'payload_too_large'
  } else {
    try {
      const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY })
      const prompt = `You are a careful, data-driven health coach. Use ONLY the JSON data provided.

Generate a 7-day health report in plain language with this exact JSON shape:
{
  "summary": "6-10 short bullet points separated by new lines",
  "wins": [{"name": "", "reason": ""}],
  "gaps": [{"name": "", "reason": ""}],
  "sections": {
    "overview": { "working": [{"name": "", "reason": ""}], "suggested": [{"name": "", "reason": ""}], "avoid": [{"name": "", "reason": ""}] },
    "supplements": { "working": [], "suggested": [], "avoid": [] },
    "medications": { "working": [], "suggested": [], "avoid": [] },
    "nutrition": { "working": [], "suggested": [], "avoid": [] },
    "hydration": { "working": [], "suggested": [], "avoid": [] },
    "exercise": { "working": [], "suggested": [], "avoid": [] },
    "lifestyle": { "working": [], "suggested": [], "avoid": [] },
    "labs": { "working": [], "suggested": [], "avoid": [] },
    "mood": { "working": [], "suggested": [], "avoid": [] },
    "symptoms": { "working": [], "suggested": [], "avoid": [] }
  }
}

Rules:
- Write in simple, everyday English. No medical jargon.
- Every sentence must reference a specific data point (numbers, dates, logged items, or named goals/issues).
- When you mention a day or event, include the date or time from the data.
- Each item should be two short lines: line 1 = what happened and why it matters, line 2 = clear next step.
- Use real signals from the JSON data. No generic advice.
- Do not claim you can measure “sleep consistency” unless the JSON includes real sleep tracking data. If sleep data is missing, do not mention sleep consistency at all.
- Supplements section rules:
  - Do NOT put medications in the Supplements section. If an item is in medications JSON, it must go in the Medications section (or be omitted if unclear).
  - Do NOT “suggest” or “avoid” a supplement the user already takes (as listed in the supplements JSON). If they already take it, it can only appear in supplements.working.
  - Do not repeat the same supplement across working/suggested/avoid. Pick the single best bucket.
  - Supplements.working must explain the user's current supplement stack, not just list it. Tie each useful current supplement to goals/issues such as erections, libido, bowel movements, digestion, energy, mood, or recovery when those goals/issues exist in JSON.
  - If the JSON includes 6+ supplements, include at least 6 supplement items across supplements.working + supplements.suggested (unless the JSON is missing supplement names).
  - For each supplement item you include: use the exact supplement name from JSON, mention dosage/timing if provided, and tie it to at least one named goal/issue from JSON when possible.
  - If a supplement name is unclear (brand blend / unknown ingredients), say you can’t connect it confidently yet and avoid guessing ingredients.
- Medications section rules:
  - Medications.working must explain why each current medication may matter for the user's named goals/issues.
  - Do not suggest new prescription medicines. Use Medications.suggested for review questions, timing checks, side effects, and clinician discussion points.
  - Medications.avoid should include safety cautions, overlap cautions, or "do not change dose without prescriber" items when relevant.
- Use insightCandidates, correlationSignals, trendSignals, and riskFlags as your primary signals when available.
- Use nutritionSummary.topFoods, foodHighlights, and dailyStats.topFoods to name actual foods (not just calories).
- Do not ask the user what they ate or to log meals. Use the foods already in the data.
- If journalEntries exist, include at least 2 items that quote the note with date/time and link it to the same day's foods, fluids, exercise, mood, symptoms, or check-ins.
- If check-in data exists, include at least 1 item that names the goal and ties it to a specific date range or change.
- If medicalImageSummary exists, include at least 1 item in overview, symptoms, or labs that references the saved note date/time and summary.
- Use health image note possibleCauses, redFlags, and nextSteps only as supporting context from the saved note. Do not present them as a diagnosis.
- Do not list raw log counts or repeat "you logged X entries" unless it directly supports a pattern or gap.
- Avoid telling the user to "keep logging" unless a section has no usable data.
- If sectionSignals show data for a section, include 2-3 items in "working" or "suggested" when there is enough data; otherwise include at least 1.
- Only include "avoid" items when dataFlags show spikes/low days or symptom-heavy days.
- If a section truly has no data, leave its arrays empty.
- If you cannot support a win or gap with data, leave that list empty.
- Only use information from the JSON. Do not invent labs, diagnoses, or missing logs.
- Tie insights to goals, issues, and healthSituations when available.
- If talkToAi data exists, connect it to logged data in the relevant sections and summary.
- Use supportive, non-alarming language.
- If data is thin, say that clearly and suggest exactly what to track next week (specific to missing areas).
- Avoid filler phrases. Every sentence must reference a data point or a clear pattern.
- If labTrends or lab highlights are present, describe movement (up/down/flat) without labeling good or bad.
- If you suggest supplements, diet changes, or possible medications based on labs, check against current medications and allergies. If unsure, say to check with a clinician.
- Do not tell the user how to navigate the app or where to find logs.
- Do not repeat the same insight in more than one section.

JSON data:
${llmPayloadJson}
`

      const isGpt5 = model.toLowerCase().includes('gpt-5')
      const request: any = {
        model,
        messages: [{ role: 'user', content: prompt }],
        max_tokens: 2600,
        reasoning_effort: 'medium',
        response_format: { type: 'json_object' },
      }
      if (!isGpt5) {
        request.temperature = 0.2
      }

      const { completion, costCents, promptTokens, completionTokens } = await chatCompletionWithCost(openai, request)

      llmUsage = {
        promptTokens,
        completionTokens,
        costCents,
        model,
      }
      llmStatus = 'ok'

      const content = completion.choices?.[0]?.message?.content || ''
      const parsed = safeJsonParse(content)
      if (parsed && parsed.sections) {
        reportPayload = parsed
        summaryText = typeof parsed.summary === 'string' ? parsed.summary : ''
      }
    } catch (error) {
      console.warn('[weekly-report] LLM generation failed', error)
      llmStatus = 'error'
    }
  }
  if (llmEnabled && !llmPayloadReady) {
    console.warn('[weekly-report] LLM payload too large', {
      size: llmPayloadSize,
      max: MAX_LLM_CONTEXT_CHARS,
    })
  }

  const estimatedCostCents = costCentsEstimateFromText(model, llmPayloadJson, 2600 * 4)
  chargeCents = Math.max(1, llmUsage?.costCents ?? estimatedCostCents ?? preflightCostCents)

  const fallbackPayload = buildFallbackReport(reportContext)
  if (!reportPayload) {
    reportPayload = fallbackPayload
    summaryText = reportPayload.summary
  }

  const sections = buildDefaultSections()
  const wins = Array.isArray(reportPayload?.wins) && reportPayload.wins.length ? reportPayload.wins : fallbackPayload.wins
  const gaps = Array.isArray(reportPayload?.gaps) && reportPayload.gaps.length ? reportPayload.gaps : fallbackPayload.gaps
  const incomingSections = reportPayload.sections || {}
  const fallbackSections = fallbackPayload.sections || {}
  REPORT_SECTIONS.forEach((key) => {
    const incoming = incomingSections[key] || {}
    const fallback = fallbackSections[key] || {}
    sections[key] = {
      working:
        Array.isArray(incoming.working) && incoming.working.length
          ? incoming.working
          : Array.isArray(fallback.working)
            ? fallback.working
            : [],
      suggested:
        Array.isArray(incoming.suggested) && incoming.suggested.length
          ? incoming.suggested
          : Array.isArray(fallback.suggested)
            ? fallback.suggested
            : [],
      avoid:
        Array.isArray(incoming.avoid) && incoming.avoid.length
          ? incoming.avoid
          : Array.isArray(fallback.avoid)
            ? fallback.avoid
            : [],
    }
  })

  reportPayload.sections = dedupeReportSections(
    enrichReportSections(
      applySupplementGuidance(sanitizeSupplementAndMedicationSections(sections, reportContext), reportContext),
      reportContext
    )
  )
  reportPayload.wins = wins
  reportPayload.gaps = gaps
  if (!summaryText) {
    summaryText = typeof reportPayload.summary === 'string' ? reportPayload.summary : fallbackPayload.summary
  }

  let charged = false
  let chargeFailed = false
  try {
    charged = await cm.chargeCents(chargeCents)
  } catch (error) {
    chargeFailed = true
    console.warn('[weekly-report] Credit charge failed', error)
  }
  if (!charged && !chargeFailed) {
    const lockedReport = await updateWeeklyReportRecord(userId, report.id, {
      status: 'LOCKED',
      summary: 'Your weekly report is ready to unlock with a subscription or top-up credits.',
      dataSummary: {
        supplements: reportContext.supplements,
        medications: reportContext.medications,
        coverage,
        dataWarning,
        talkToAiSummary,
        hydrationSummary,
        nutritionSummary,
        medicalImageSummary,
        journalSummary,
        moodSummary,
        symptomSummary,
        exerciseSummary,
        checkinSummary,
        dailyStats,
        labTrends,
        labHighlights,
        llmUsage,
        llmStatus,
        llmChargeCents: chargeCents,
        llmPayloadSize,
        llmPayloadMax: MAX_LLM_CONTEXT_CHARS,
        lockedReason: 'insufficient_credits',
      },
      report: null,
      readyAt: now.toISOString(),
    })
    await upsertWeeklyReportState(userId, {
      lastReportAt: now.toISOString(),
      nextReportDueAt: getNextDueAt(now).toISOString(),
      lastStatus: 'LOCKED',
    })
    await queueWeeklyReportNotification(lockedReport).catch(() => {})
    return NextResponse.json({ status: 'locked' })
  }

  const updated = await updateWeeklyReportRecord(userId, report.id, {
    status: 'READY',
    summary: summaryText,
    dataSummary: {
      supplements: reportContext.supplements,
      medications: reportContext.medications,
      coverage,
      dataWarning,
      talkToAiSummary,
      hydrationSummary,
      nutritionSummary,
      medicalImageSummary,
      journalSummary,
      moodSummary,
      symptomSummary,
      exerciseSummary,
      checkinSummary,
      dailyStats,
      labTrends,
      labHighlights,
      llmUsage,
      llmStatus,
      llmChargeCents: chargeCents,
      llmPayloadSize,
      llmPayloadMax: MAX_LLM_CONTEXT_CHARS,
      ...(chargeFailed ? { chargeSkipped: true } : {}),
    },
    report: reportPayload,
    model,
    creditsCharged: charged ? chargeCents : 0,
    readyAt: now.toISOString(),
  })

  if (!updated) {
    await upsertWeeklyReportState(userId, { lastStatus: 'FAILED' })
    return NextResponse.json({ status: 'failed' }, { status: 500 })
  }

  await upsertWeeklyReportState(userId, {
    lastReportAt: now.toISOString(),
    nextReportDueAt: getNextDueAt(now).toISOString(),
    lastStatus: 'READY',
  })
  await queueWeeklyReportNotification(updated).catch(() => {})

  return NextResponse.json({ status: 'ready', reportId: report.id })
  } catch (error: any) {
    console.error('[weekly-report] Failed to generate report', error)
    return NextResponse.json({ error: 'report_failed' }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'
import {
  ensureReadyWeeklyReportNextDueInFuture,
  getLatestWeeklyReport,
  getWeeklyReportState,
  markWeeklyReportOnboardingComplete,
  setWeeklyReportsEnabled,
} from '@/lib/weekly-health-report'
import { prisma } from '@/lib/prisma'
import { isSubscriptionActive } from '@/lib/subscription-utils'
import { getWeeklyReportRequestUser, isWeeklyReportHealthSetupComplete } from '@/lib/weekly-report-request-auth'
import { isHealthSetupComplete } from '@/lib/health-setup-completion'

export async function GET(request: NextRequest) {
  const requestUser = await getWeeklyReportRequestUser(request)
  if (!requestUser?.id) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }
  const session = { user: requestUser }

  let [state, latest] = await Promise.all([
    getWeeklyReportState(requestUser.id),
    getLatestWeeklyReport(requestUser.id),
  ])
  const healthSetupComplete = await isWeeklyReportHealthSetupComplete(requestUser.id)
  if (!healthSetupComplete) {
    return NextResponse.json({
      healthSetupComplete: false,
      reportId: null,
      status: null,
      reportReady: false,
      reportLocked: false,
      showPopup: false,
      summary: null,
      periodStart: null,
      periodEnd: null,
      dataSummary: null,
      nextReportDueAt: null,
      lastReportAt: state?.lastReportAt ?? null,
      reportsEnabled: false,
      reportsEnabledAt: state?.reportsEnabledAt ?? null,
    })
  }

  // PROTECTED: WEEKLY_STATUS_SELF_HEAL START
  if (!state?.nextReportDueAt) {
    const isOwnerTestAccount = String(session.user.email || '').toLowerCase() === 'info@sonicweb.com.au'
    const user = await prisma.user.findUnique({
      where: { id: session.user.id },
      select: {
        gender: true,
        weight: true,
        height: true,
        subscription: {
          select: {
            plan: true,
            endDate: true,
          },
        },
        healthGoals: { select: { name: true, category: true } },
      },
    })

    if (user) {
      const eligible = isHealthSetupComplete({
        gender: user.gender,
        weight: user.weight,
        height: user.height,
        goals: user.healthGoals,
      })
      const hasActivePlan = isSubscriptionActive(user.subscription ?? null, new Date())
      if ((hasActivePlan || isOwnerTestAccount) && eligible) {
        await setWeeklyReportsEnabled(session.user.id, true, { scheduleFrom: new Date() })
        state = await getWeeklyReportState(session.user.id)
      }

      if (!state?.nextReportDueAt && eligible) {
        await markWeeklyReportOnboardingComplete(session.user.id)
        state = await getWeeklyReportState(session.user.id)
      }
    }
  }
  // PROTECTED: WEEKLY_STATUS_SELF_HEAL END

  const reportReady = latest?.status === 'READY'
  const reportLocked = latest?.status === 'LOCKED'
  state = await ensureReadyWeeklyReportNextDueInFuture(requestUser.id, state, latest)
  const now = Date.now()
  const lastShownAt = latest?.lastShownAt ? new Date(latest.lastShownAt).getTime() : 0
  const shouldShowPopup = Boolean(
    (reportReady || reportLocked) &&
      !latest?.viewedAt &&
      !latest?.dontShowAt &&
      (lastShownAt === 0 || now - lastShownAt >= 24 * 60 * 60 * 1000)
  )

  return NextResponse.json({
    reportId: latest?.id ?? null,
    healthSetupComplete: true,
    status: latest?.status ?? null,
    reportReady,
    reportLocked,
    showPopup: shouldShowPopup,
    summary: latest?.summary ?? null,
    periodStart: latest?.periodStart ?? null,
    periodEnd: latest?.periodEnd ?? null,
    dataSummary: latest?.dataSummary ?? null,
    nextReportDueAt: state?.nextReportDueAt ?? null,
    lastReportAt: state?.lastReportAt ?? null,
    reportsEnabled: state?.reportsEnabled ?? false,
    reportsEnabledAt: state?.reportsEnabledAt ?? null,
  })
}

import { NextRequest, NextResponse } from 'next/server'
import { getWeeklyReportRequestUser } from '@/lib/weekly-report-request-auth'

const buildBaseUrl = (request: NextRequest) => {
  const envBase =
    process.env.NEXT_PUBLIC_APP_URL ||
    process.env.NEXT_PUBLIC_SITE_URL ||
    process.env.NEXTAUTH_URL ||
    (process.env.VERCEL_URL ? `https://${process.env.VERCEL_URL}` : '')
  if (envBase) return envBase.replace(/\/$/, '')
  const host = request.headers.get('x-forwarded-host') || request.headers.get('host') || ''
  if (!host) return ''
  const proto = request.headers.get('x-forwarded-proto') || 'https'
  return `${proto}://${host}`
}

export async function POST(request: NextRequest) {
  const requestUser = await getWeeklyReportRequestUser(request)
  if (!requestUser?.id) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const userId = requestUser.id
  const schedulerSecret = process.env.SCHEDULER_SECRET || ''
  const baseUrl = buildBaseUrl(request)
  if (!baseUrl) {
    return NextResponse.json({ error: 'Missing base URL' }, { status: 500 })
  }

  const cookie = request.headers.get('cookie') || ''
  const response = await fetch(`${baseUrl}/api/reports/weekly/run`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...(schedulerSecret ? { Authorization: `Bearer ${schedulerSecret}` } : {}),
      ...(cookie ? { cookie } : {}),
    },
    body: JSON.stringify({ userId, triggerSource: 'manual' }),
  })

  const payload = await response.json().catch(() => ({}))
  if (!response.ok) {
    return NextResponse.json({ error: payload?.error || 'Failed to trigger report' }, { status: response.status })
  }

  return NextResponse.json({ ok: true, result: payload })
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { ensureSupplementCatalogSchema } from '@/lib/supplement-catalog-db'

export const dynamic = 'force-dynamic'

const normalizeSearchText = (value: string) => {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
}

const isPlaceholderName = (value: string) => {
  const safe = String(value || '').trim().toLowerCase()
  return new Set([
    'analyzing...',
    'supplement added',
    'unknown supplement',
    'analysis error',
  ]).has(safe)
}

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const query = String(searchParams.get('q') || '').trim()
    if (query.length < 2) {
      return NextResponse.json({ results: [] }, { headers: { 'Cache-Control': 'no-store' } })
    }

    await ensureSupplementCatalogSchema()

    const tokens = normalizeSearchText(query).split(' ').filter(Boolean).slice(0, 6)
    if (tokens.length === 0) {
      return NextResponse.json({ results: [] }, { headers: { 'Cache-Control': 'no-store' } })
    }

    const tokenFilters = tokens.map((token) => ({
      OR: [
        { fullName: { contains: token, mode: 'insensitive' as const } },
        { brand: { contains: token, mode: 'insensitive' as const } },
        { product: { contains: token, mode: 'insensitive' as const } },
      ],
    }))

    const rows = await prisma.supplementCatalog.findMany({
      where: { OR: tokenFilters },
      orderBy: [{ updatedAt: 'desc' }],
      distinct: ['fullName'],
      take: 60,
    })

    const scored = rows
      .map((row) => {
        const label = String(row.fullName || '').trim()
        if (!label || isPlaceholderName(label)) return null
        const haystack = normalizeSearchText(
          `${row.fullName || ''} ${row.brand || ''} ${row.product || ''}`,
        )
        const score = tokens.reduce((acc, token) => (haystack.includes(token) ? acc + 1 : acc), 0)
        return { label, score, updatedAt: row.updatedAt }
      })
      .filter(Boolean) as { label: string; score: number; updatedAt: Date }[]

    scored.sort((a, b) => {
      if (b.score !== a.score) return b.score - a.score
      return b.updatedAt.getTime() - a.updatedAt.getTime()
    })

    const results = scored.slice(0, 12).map((item) => ({
      name: item.label,
      source: 'catalog',
    }))

    return NextResponse.json({ results }, { headers: { 'Cache-Control': 'no-store' } })
  } catch (error) {
    console.error('Supplement catalog search failed:', error)
    return NextResponse.json({ results: [] }, { headers: { 'Cache-Control': 'no-store' } })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { searchSupplementReferenceNames } from '@/lib/health-intake-review-match'

type CacheEntry = { ts: number; data: any }
const cache = new Map<string, CacheEntry>()
const CACHE_TTL_MS = 5 * 60 * 1000

const getCached = (key: string) => {
  const entry = cache.get(key)
  if (!entry) return null
  if (Date.now() - entry.ts > CACHE_TTL_MS) {
    cache.delete(key)
    return null
  }
  return entry.data
}

const setCached = (key: string, data: any) => {
  cache.set(key, { ts: Date.now(), data })
}

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const query = String(searchParams.get('q') || '').trim()
    if (query.length < 2) {
      return NextResponse.json({ results: [] })
    }

    const cacheKey = `supp:${query.toLowerCase()}`
    const cached = getCached(cacheKey)
    if (cached) return NextResponse.json(cached)

    const results = await searchSupplementReferenceNames(query, 10)

    const payload = { results }
    setCached(cacheKey, payload)
    return NextResponse.json(payload)
  } catch (error) {
    console.error('Supplement search failed:', error)
    return NextResponse.json({ results: [] })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'

export const dynamic = 'force-dynamic'

// GUARD RAIL: Recovery-only route. Keep identity checks and do not remove credit/date/favorites repair steps.
const IDENTITY_MARKER = '[SYSTEM] Identity verified'
const IDENTITY_MAX_AGE_MS = 24 * 60 * 60 * 1000
const FUTURE_GRACE_MS = 36 * 60 * 60 * 1000

const normalizeEmail = (value: string) => value.trim().toLowerCase()

const isValidLocalDate = (value: string | null) => {
  if (!value) return false
  return /^\d{4}-\d{2}-\d{2}$/.test(value)
}

const formatLocalDateFromTimestamp = (timestampMs: number, tzMin: number) => {
  if (!Number.isFinite(timestampMs)) return null
  const local = new Date(timestampMs - tzMin * 60 * 1000)
  const y = local.getUTCFullYear()
  const m = String(local.getUTCMonth() + 1).padStart(2, '0')
  const d = String(local.getUTCDate()).padStart(2, '0')
  return `${y}-${m}-${d}`
}

const parseClientIdTimestampMs = (clientId: string) => {
  if (!clientId) return NaN
  const parts = clientId.split('-')
  if (parts.length < 2) return NaN
  const base36 = parts[parts.length - 2]
  if (!base36) return NaN
  const ms = parseInt(base36, 36)
  return Number.isFinite(ms) ? ms : NaN
}

const coerceTimestampMs = (value: any) => {
  if (typeof value === 'number' && Number.isFinite(value)) return value
  if (value instanceof Date) {
    const ms = value.getTime()
    return Number.isFinite(ms) ? ms : NaN
  }
  if (typeof value === 'string' && value.trim()) {
    const ms = Date.parse(value)
    return Number.isFinite(ms) ? ms : NaN
  }
  return NaN
}

const extractLoggedAtMs = (log: any) => {
  const nutrients = log?.nutrients || {}
  const direct =
    nutrients?.__loggedAt ||
    nutrients?.__sourceCreatedAt ||
    nutrients?.loggedAt ||
    nutrients?.logged_at
  const directMs = coerceTimestampMs(direct)
  if (Number.isFinite(directMs)) return directMs
  const clientId =
    typeof nutrients?.__clientId === 'string'
      ? nutrients.__clientId
      : typeof nutrients?.__clientID === 'string'
      ? nutrients.__clientID
      : typeof nutrients?.__client_id === 'string'
      ? nutrients.__client_id
      : ''
  const clientMs = parseClientIdTimestampMs(clientId)
  return Number.isFinite(clientMs) ? clientMs : NaN
}

const isPlausibleTimestamp = (timestampMs: number, nowMs: number) => {
  if (!Number.isFinite(timestampMs)) return false
  if (timestampMs < 946684800000) return false
  return timestampMs <= nowMs + FUTURE_GRACE_MS
}

const pickBestTimestampMs = (log: any, nowMs: number) => {
  const createdMs = coerceTimestampMs(log?.createdAt)
  const loggedAtMs = extractLoggedAtMs(log)
  const createdOk = isPlausibleTimestamp(createdMs, nowMs)
  const loggedOk = isPlausibleTimestamp(loggedAtMs, nowMs)
  if (createdOk && loggedOk) {
    const drift = Math.abs(loggedAtMs - createdMs)
    if (drift <= FUTURE_GRACE_MS) return loggedAtMs
  }
  if (createdOk) return createdMs
  if (loggedOk) return loggedAtMs
  return Number.isFinite(createdMs) ? createdMs : loggedAtMs
}

const parseFavoritesCount = (category: string | null) => {
  if (!category) return 0
  try {
    const parsed = JSON.parse(category)
    const favs = Array.isArray(parsed?.favorites)
      ? parsed.favorites
      : Array.isArray(parsed)
      ? parsed
      : []
    return favs.length
  } catch {
    return 0
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => ({}))
    const ticketId = String(body?.ticketId || '').trim()
    const email = normalizeEmail(String(body?.email || ''))
    const tier = String(body?.tier || '30').trim()
    const tzMin = Number.isFinite(Number(body?.tz))
      ? Number(body.tz)
      : Number.isFinite(Number(body?.tzMin))
      ? Number(body.tzMin)
      : 0

    if (!ticketId || !email) {
      return NextResponse.json({ error: 'Missing ticketId or email' }, { status: 400 })
    }

    const ticket = await prisma.supportTicket.findFirst({
      where: { id: ticketId, userEmail: email },
      include: { responses: { orderBy: { createdAt: 'desc' } } },
    })
    if (!ticket) {
      return NextResponse.json({ error: 'Ticket not found' }, { status: 404 })
    }

    const identity = (ticket.responses || []).find(
      (response) =>
        response.isAdminResponse &&
        typeof response.message === 'string' &&
        response.message.startsWith(IDENTITY_MARKER),
    )
    if (!identity) {
      return NextResponse.json({ error: 'Identity not verified' }, { status: 403 })
    }
    const identityAge = Date.now() - new Date(identity.createdAt).getTime()
    if (!Number.isFinite(identityAge) || identityAge > IDENTITY_MAX_AGE_MS) {
      return NextResponse.json({ error: 'Identity check expired' }, { status: 403 })
    }

    const user = await prisma.user.findFirst({
      where: { email: { equals: email, mode: 'insensitive' } },
    })
    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    const priceCentsMap: Record<string, number> = {
      '10': 1000,
      '20': 2000,
      '30': 3000,
      '50': 5000,
    }
    const priceCents = priceCentsMap[tier] || 3000
    const now = new Date()

    await prisma.subscription.upsert({
      where: { userId: user.id },
      update: {
        plan: 'PREMIUM',
        monthlyPriceCents: priceCents,
        startDate: now,
        endDate: null,
      },
      create: {
        userId: user.id,
        plan: 'PREMIUM',
        monthlyPriceCents: priceCents,
        startDate: now,
      },
    })

    await prisma.user.update({
      where: { id: user.id },
      data: {
        dailyAnalysisCredits: 30,
        walletMonthlyUsedCents: 0,
        walletMonthlyResetAt: now,
        monthlySymptomAnalysisUsed: 0,
        monthlyFoodAnalysisUsed: 0,
        monthlyMedicalImageAnalysisUsed: 0,
        monthlyInteractionAnalysisUsed: 0,
        monthlyInsightsGenerationUsed: 0,
      } as any,
    })

    const logs = await prisma.foodLog.findMany({
      where: { userId: user.id },
      select: { id: true, createdAt: true, localDate: true, nutrients: true },
      orderBy: { createdAt: 'desc' },
    })

    const nowMs = Date.now()
    const updates = logs
      .map((log) => ({
        id: log.id,
        current: log.localDate || null,
        localDate: formatLocalDateFromTimestamp(pickBestTimestampMs(log, nowMs), tzMin),
      }))
      .filter((row) => row.localDate && row.localDate !== row.current)

    const updatedIds: string[] = []
    const batchSize = 200
    for (let i = 0; i < updates.length; i += batchSize) {
      const batch = updates.slice(i, i + batchSize)
      await prisma.$transaction(
        batch.map((row) =>
          prisma.foodLog.update({
            where: { id: row.id },
            data: { localDate: row.localDate as string },
          }),
        ),
      )
      updatedIds.push(...batch.map((row) => row.id))
    }

    const favoritesGoal = await prisma.healthGoal.findFirst({
      where: { userId: user.id, name: '__FOOD_FAVORITES__' },
      orderBy: { createdAt: 'desc' },
    })
    const favoritesCount = parseFavoritesCount(favoritesGoal?.category || null)
    let favoritesRestored = false
    let favoritesBackupFound = false

    if (favoritesCount === 0) {
      const backup = await prisma.healthGoal.findFirst({
        where: {
          userId: user.id,
          name: { startsWith: '__FOOD_FAVORITES__BACKUP__' },
        },
        orderBy: { createdAt: 'desc' },
      })
      favoritesBackupFound = Boolean(backup?.category)
      if (backup?.category) {
        if (favoritesGoal?.id) {
          await prisma.healthGoal.update({
            where: { id: favoritesGoal.id },
            data: { category: backup.category, currentRating: 0 },
          })
        } else {
          await prisma.healthGoal.create({
            data: {
              userId: user.id,
              name: '__FOOD_FAVORITES__',
              category: backup.category,
              currentRating: 0,
            },
          })
        }
        favoritesRestored = true
      }
    }

    return NextResponse.json({
      success: true,
      subscriptionTier: priceCents,
      repairedFoodLogs: updatedIds.length,
      favoritesRestored,
      favoritesBackupFound,
    })
  } catch (error) {
    console.error('POST /api/support/account-repair error', error)
    return NextResponse.json({ error: 'Repair failed' }, { status: 500 })
  }
}

