      await prisma.healthGoal.create({
        data: {
          userId: user.id,
          name: '__FOOD_FAVORITES__',
          category: payload,
          currentRating: 0,
        },
      })
    }

    return NextResponse.json({ success: true, label })
  } catch (error) {
