  } catch {
    return []
  }
}

const looksLikeMealBuilderCreatedItemId = (rawId: any) => {
  const id = typeof rawId === 'string' ? rawId : ''
  if (!id) return false
  if (/^(openfoodfacts|usda|fatsecret):[^:]+:\d{9,}$/i.test(id)) return true
  if (/^ai:\d{9,}:[0-9a-f]+$/i.test(id)) return true
  if (/^edit:\d{9,}:[0-9a-f]+$/i.test(id)) return true
  return false
}

const shouldMarkCustom = (items: any[], origin: string) => {
  if (origin === 'meal-builder' || origin === 'combined') return true
  return items.some((item) => looksLikeMealBuilderCreatedItemId(item?.id))
}

const buildFavoriteId = (seed: string) => `fav-${Date.now()}-${seed}`

export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => ({}))
    const ticketId = String(body?.ticketId || '').trim()
    const email = normalizeEmail(String(body?.email || ''))
    const labelRaw = String(body?.label || '').trim()

    if (!ticketId || !email || !labelRaw) {
      return NextResponse.json({ error: 'Missing ticketId, email, or label' }, { status: 400 })
    }

    const ticket = await prisma.supportTicket.findFirst({
      where: { id: ticketId, userEmail: email },
      include: { responses: { orderBy: { createdAt: 'desc' } } },
    })
    if (!ticket) {
      return NextResponse.json({ error: 'Ticket not found' }, { status: 404 })
    }

    const identity = (ticket.responses || []).find(
      (response) =>
        response.isAdminResponse &&
        typeof response.message === 'string' &&
        response.message.startsWith(IDENTITY_MARKER),
    )
    if (!identity) {
      return NextResponse.json({ error: 'Identity not verified' }, { status: 403 })
    }
    const identityAge = Date.now() - new Date(identity.createdAt).getTime()
    if (!Number.isFinite(identityAge) || identityAge > IDENTITY_MAX_AGE_MS) {
      return NextResponse.json({ error: 'Identity check expired' }, { status: 403 })
    }

    const user = await prisma.user.findFirst({
      where: { email: { equals: email, mode: 'insensitive' } },
    })
    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    const desiredLabel = extractFavoriteLabel(labelRaw)
    const desiredText = normalizeText(desiredLabel)
    const desiredTokens = desiredText.split(' ').filter((token) => token.length > 2)

    const logs = await prisma.foodLog.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: 'desc' },
      take: 800,
      select: {
        id: true,
        name: true,
        description: true,
        imageUrl: true,
        nutrients: true,
        items: true,
        meal: true,
        category: true,
        createdAt: true,
      },
    })

    const candidates = logs
      .map((log) => {
        const text = String(log.description || log.name || '').trim()
        if (!text) return null
        const normalized = normalizeText(text)
        if (!normalized) return null
        const hits = desiredTokens.length
          ? desiredTokens.filter((token) => normalized.includes(token)).length
          : normalized.includes(desiredText)
          ? 1
          : 0
        if (hits === 0) return null
        const originRaw =
          (log.nutrients as any)?.__origin ||
          (log.nutrients as any)?.origin ||
          ''
        const origin = typeof originRaw === 'string' ? originRaw.toLowerCase().trim() : ''
        const items =
          Array.isArray(log.items)
            ? log.items
            : Array.isArray((log.nutrients as any)?.items)
            ? (log.nutrients as any)?.items
            : []
        const customMeal = shouldMarkCustom(items, origin)
        return {
          log,
          hits,
          customMeal,
        }
      })
      .filter(Boolean) as Array<{ log: any; hits: number; customMeal: boolean }>

    const best = candidates.sort((a, b) => {
      if (a.customMeal !== b.customMeal) return a.customMeal ? -1 : 1
      if (a.hits !== b.hits) return b.hits - a.hits
      return new Date(b.log.createdAt).getTime() - new Date(a.log.createdAt).getTime()
    })[0]

    if (!best) {
      return NextResponse.json({ error: 'Meal not found' }, { status: 404 })
    }

    const log = best.log
    const originRaw =
      (log.nutrients as any)?.__origin ||
      (log.nutrients as any)?.origin ||
      ''
    const origin = typeof originRaw === 'string' ? originRaw.toLowerCase().trim() : ''
    const items =
      Array.isArray(log.items)
        ? log.items
        : Array.isArray((log.nutrients as any)?.items)
        ? (log.nutrients as any)?.items
        : []
    const customMeal = shouldMarkCustom(items, origin)

    const favorite = {
      id: buildFavoriteId(Math.random().toString(16).slice(2)),
      sourceId: String(log.id || ''),
      label: desiredLabel,
      description: desiredLabel,
      nutrition: log.nutrients || null,
      total: log.nutrients || null,
      items: Array.isArray(items) && items.length > 0 ? items : null,
      photo: log.imageUrl || null,
      method: customMeal ? (origin === 'combined' ? 'combined' : 'meal-builder') : origin || 'text',
      ...(customMeal ? { customMeal: true } : {}),
      meal: log.meal || log.category || 'uncategorized',
      createdAt: log.createdAt ? new Date(log.createdAt).getTime() : Date.now(),
    }

    const existingGoal = await prisma.healthGoal.findFirst({
      where: { userId: user.id, name: '__FOOD_FAVORITES__' },
      orderBy: { createdAt: 'desc' },
    })
    const existingFavorites = parseFavoritesList(existingGoal?.category || null)

    const existingMatch = existingFavorites.find((fav: any) => {
      const favSource = fav?.sourceId ? String(fav.sourceId) : ''
      if (favSource && favSource === favorite.sourceId) return true
      const favLabel = normalizeText(String(fav?.label || fav?.description || ''))
      return favLabel && favLabel === normalizeText(desiredLabel)
    })
    if (existingMatch) {
      return NextResponse.json({ success: true, alreadyExists: true, label: desiredLabel })
    }

    const merged = [...existingFavorites, favorite]
    const payload = JSON.stringify({ favorites: merged })

    if (existingGoal?.id) {
      await prisma.healthGoal.update({
        where: { id: existingGoal.id },
        data: { category: payload, currentRating: 0 },
      })
    } else {
      await prisma.healthGoal.create({
        data: {
          userId: user.id,
          name: '__FOOD_FAVORITES__',
          category: payload,
          currentRating: 0,
        },
      })
    }

    return NextResponse.json({
      success: true,
      label: desiredLabel,
      customMeal,
    })
  } catch (error) {
    console.error('POST /api/support/favorite-restore error', error)
    return NextResponse.json({ error: 'Restore failed' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'

export const dynamic = 'force-dynamic'

// GUARD RAIL: Recovery-only route. Always verify identity and back up existing favorites before rebuild.
const IDENTITY_MARKER = '[SYSTEM] Identity verified'
const IDENTITY_MAX_AGE_MS = 24 * 60 * 60 * 1000

const normalizeEmail = (value: string) => value.trim().toLowerCase()

const normalizeLabel = (value: string) => value.trim().toLowerCase()

const extractFavoriteLabel = (raw: string) => {
  const text = String(raw || '').trim()
  if (!text) return 'Favorite meal'
  const firstLine = text.split('\n')[0] || text
  const cleaned = firstLine.split('Calories:')[0].trim()
  return cleaned || firstLine.trim() || 'Favorite meal'
}

const looksLikeMealBuilderCreatedItemId = (rawId: any) => {
  const id = typeof rawId === 'string' ? rawId : ''
  if (!id) return false
  if (/^(openfoodfacts|usda|fatsecret):[^:]+:\d{9,}$/i.test(id)) return true
  if (/^ai:\d{9,}:[0-9a-f]+$/i.test(id)) return true
  if (/^edit:\d{9,}:[0-9a-f]+$/i.test(id)) return true
  return false
}

const shouldMarkCustom = (items: any[], origin: string) => {
  if (origin === 'meal-builder' || origin === 'combined') return true
  return items.some((item) => looksLikeMealBuilderCreatedItemId(item?.id))
}

const parseFavoritesList = (category: string | null) => {
  if (!category) return []
  try {
    const parsed = JSON.parse(category)
    if (Array.isArray(parsed?.favorites)) return parsed.favorites
    if (Array.isArray(parsed)) return parsed
    return []
  } catch {
    return []
  }
}

const buildFavoriteId = (seed: string) => `fav-${Date.now()}-${seed}`

export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => ({}))
    const ticketId = String(body?.ticketId || '').trim()
    const email = normalizeEmail(String(body?.email || ''))
    const limitRaw = Number(body?.limit)
    const limit = Number.isFinite(limitRaw) ? Math.min(Math.max(limitRaw, 50), 500) : 250

    if (!ticketId || !email) {
      return NextResponse.json({ error: 'Missing ticketId or email' }, { status: 400 })
    }

    const ticket = await prisma.supportTicket.findFirst({
      where: { id: ticketId, userEmail: email },
      include: { responses: { orderBy: { createdAt: 'desc' } } },
    })
    if (!ticket) {
      return NextResponse.json({ error: 'Ticket not found' }, { status: 404 })
    }

    const identity = (ticket.responses || []).find(
      (response) =>
        response.isAdminResponse &&
        typeof response.message === 'string' &&
        response.message.startsWith(IDENTITY_MARKER),
    )
    if (!identity) {
      return NextResponse.json({ error: 'Identity not verified' }, { status: 403 })
    }
    const identityAge = Date.now() - new Date(identity.createdAt).getTime()
    if (!Number.isFinite(identityAge) || identityAge > IDENTITY_MAX_AGE_MS) {
      return NextResponse.json({ error: 'Identity check expired' }, { status: 403 })
    }

    const user = await prisma.user.findFirst({
      where: { email: { equals: email, mode: 'insensitive' } },
    })
    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    const existingGoal = await prisma.healthGoal.findFirst({
      where: { userId: user.id, name: '__FOOD_FAVORITES__' },
      orderBy: { createdAt: 'desc' },
    })
    const existingFavorites = parseFavoritesList(existingGoal?.category || null)

    // Backup the current favorites (best-effort).
    if (existingGoal?.category) {
      try {
        await prisma.healthGoal.create({
          data: {
            userId: user.id,
            name: `__FOOD_FAVORITES__BACKUP__${Date.now()}`,
            category: String(existingGoal.category),
            currentRating: 0,
          },
        })
      } catch {
        // best effort only
      }
    }

    const logs = await prisma.foodLog.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: 'desc' },
      take: limit,
      select: {
        id: true,
        name: true,
        description: true,
        imageUrl: true,
        nutrients: true,
        items: true,
        meal: true,
        category: true,
        createdAt: true,
      },
    })

    const seen = new Set<string>()
    const rebuilt: any[] = []

    for (const log of logs) {
      const description = String(log.description || log.name || '').trim()
      if (!description) continue
      const label = extractFavoriteLabel(description)
      const labelKey = normalizeLabel(label)
      const sourceId = String(log.id || '')
      const key = sourceId ? `src:${sourceId}` : `lbl:${labelKey}`
      if (!labelKey || seen.has(key)) continue

      const originRaw =
        (log.nutrients as any)?.__origin ||
        (log.nutrients as any)?.origin ||
        ''
      const origin = typeof originRaw === 'string' ? originRaw.toLowerCase().trim() : ''
      const items =
        Array.isArray(log.items) ? log.items : Array.isArray((log.nutrients as any)?.items) ? (log.nutrients as any)?.items : []
      const customMeal = shouldMarkCustom(items, origin)

      const favorite = {
        id: buildFavoriteId(Math.random().toString(16).slice(2)),
        sourceId,
        label,
        description: label,
        nutrition: log.nutrients || null,
        total: log.nutrients || null,
        items: Array.isArray(items) && items.length > 0 ? items : null,
        photo: log.imageUrl || null,
        method: customMeal ? (origin === 'combined' ? 'combined' : 'meal-builder') : origin || 'text',
        ...(customMeal ? { customMeal: true } : {}),
        meal: log.meal || log.category || 'uncategorized',
        createdAt: log.createdAt ? new Date(log.createdAt).getTime() : Date.now(),
      }

      rebuilt.push(favorite)
      seen.add(key)
    }

    const merged = (() => {
      const base = Array.isArray(existingFavorites) ? existingFavorites : []
      const mergedList: any[] = [...base]
      const keys = new Set<string>()
      base.forEach((fav: any) => {
        const src = fav?.sourceId ? String(fav.sourceId) : ''
        const lbl = normalizeLabel(String(fav?.label || fav?.description || ''))
        if (src) keys.add(`src:${src}`)
        if (lbl) keys.add(`lbl:${lbl}`)
      })
      rebuilt.forEach((fav) => {
        const src = fav?.sourceId ? String(fav.sourceId) : ''
        const lbl = normalizeLabel(String(fav?.label || fav?.description || ''))
        const keySrc = src ? `src:${src}` : ''
        const keyLbl = lbl ? `lbl:${lbl}` : ''
        if ((keySrc && keys.has(keySrc)) || (keyLbl && keys.has(keyLbl))) return
        if (keySrc) keys.add(keySrc)
        if (keyLbl) keys.add(keyLbl)
        mergedList.push(fav)
      })
      return mergedList
    })()

    const payload = JSON.stringify({ favorites: merged })
    const existingGoals = await prisma.healthGoal.findMany({
      where: { userId: user.id, name: '__FOOD_FAVORITES__' },
      orderBy: { createdAt: 'desc' },
      select: { id: true },
    })
    const primary = existingGoals[0] || null
    if (primary?.id) {
      await prisma.healthGoal.update({
        where: { id: primary.id },
        data: { category: payload, currentRating: 0 },
      })
      if (existingGoals.length > 1) {
        await prisma.healthGoal.deleteMany({
          where: { id: { in: existingGoals.slice(1).map((g) => g.id) } },
        })
      }
    } else {
      await prisma.healthGoal.create({
        data: {
          userId: user.id,
          name: '__FOOD_FAVORITES__',
          category: payload,
          currentRating: 0,
        },
      })
    }

    return NextResponse.json({
      success: true,
      rebuiltCount: rebuilt.length,
      totalFavorites: merged.length,
    })
  } catch (error) {
    console.error('POST /api/support/favorites-rebuild error', error)
    return NextResponse.json({ error: 'Rebuild failed' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import crypto from 'crypto'
import { prisma } from '@/lib/prisma'
import { buildSupportFeedbackPrompt, processSupportTicketAutoReply, sendSupportFeedbackEmail, sendSupportTranscriptEmail } from '@/lib/support-automation'
import { getSupportAgentForTimestamp } from '@/lib/support-agents'
import { rehydrateSupportTicket } from '@/lib/support-attachments'

function guestTokenPrefix(token: string) {
  return `guest:${token}`
}

function normalizeEmail(email: string) {
  return email.trim().toLowerCase()
}

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url)
  const ticketId = String(searchParams.get('ticketId') || '').trim()
  const token = String(searchParams.get('token') || '').trim()
  if (!ticketId || !token) {
    return NextResponse.json({ error: 'Missing ticketId or token' }, { status: 400 })
  }

  const ticket = await prisma.supportTicket.findFirst({
    where: {
      id: ticketId,
      externalMessageId: guestTokenPrefix(token),
    },
    include: {
      responses: { orderBy: { createdAt: 'asc' } },
    },
  })

  if (!ticket) {
    return NextResponse.json({ error: 'Ticket not found' }, { status: 404 })
  }

  return NextResponse.json({ ticket: ticket ? rehydrateSupportTicket(ticket) : null })
}

export async function POST(request: NextRequest) {
  const body = await request.json().catch(() => ({}))
  const action = String(body?.action || '').trim()

  if (action === 'create') {
    const name = String(body?.name || '').trim()
    const email = normalizeEmail(String(body?.email || ''))
    const message = String(body?.message || '').trim()

    if (!email || !message) {
      return NextResponse.json({ error: 'Name, email, and message are required' }, { status: 400 })
    }

    const token = crypto.randomBytes(12).toString('hex')
    const ticket = await prisma.supportTicket.create({
      data: {
        subject: 'Website inquiry',
        message,
        userEmail: email,
        userName: name || undefined,
        status: 'OPEN',
        priority: 'LOW',
        category: 'GENERAL',
        externalMessageId: guestTokenPrefix(token),
      },
      include: { responses: { orderBy: { createdAt: 'asc' } } },
    })

    try {
      await processSupportTicketAutoReply({
        ticketId: ticket.id,
        latestUserMessage: message,
        source: 'web_chat',
      })
    } catch (aiError) {
      console.error('🤖 [SUPPORT AI] Failed to auto-reply to inquiry chat:', aiError)
    }

    const updatedTicket = await prisma.supportTicket.findUnique({
      where: { id: ticket.id },
      include: { responses: { orderBy: { createdAt: 'asc' } } },
    })

    return NextResponse.json({
      ticket: updatedTicket ? rehydrateSupportTicket(updatedTicket) : updatedTicket,
      token,
    })
  }

  if (action === 'add_response') {
    const ticketId = String(body?.ticketId || '').trim()
    const token = String(body?.token || '').trim()
    const message = String(body?.message || '').trim()
    if (!ticketId || !token || !message) {
      return NextResponse.json({ error: 'ticketId, token, and message are required' }, { status: 400 })
    }

    const ticket = await prisma.supportTicket.findFirst({
      where: {
        id: ticketId,
        externalMessageId: guestTokenPrefix(token),
      },
    })
    if (!ticket) {
      return NextResponse.json({ error: 'Ticket not found' }, { status: 404 })
    }

    await prisma.ticketResponse.create({
      data: {
        ticketId,
        message,
        isAdminResponse: false,
        userEmail: ticket.userEmail,
      },
    })

    await prisma.supportTicket.update({
      where: { id: ticketId },
      data: {
        status: 'AWAITING_RESPONSE',
        updatedAt: new Date(),
      },
    })

    try {
      await processSupportTicketAutoReply({
        ticketId,
        latestUserMessage: message,
        source: 'web_chat',
      })
    } catch (aiError) {
      console.error('🤖 [SUPPORT AI] Failed to auto-reply to inquiry message:', aiError)
    }

    const updatedTicket = await prisma.supportTicket.findUnique({
      where: { id: ticketId },
      include: { responses: { orderBy: { createdAt: 'asc' } } },
    })

    return NextResponse.json({ ticket: updatedTicket ? rehydrateSupportTicket(updatedTicket) : updatedTicket })
  }

  if (action === 'end_chat') {
    const ticketId = String(body?.ticketId || '').trim()
    const token = String(body?.token || '').trim()
    if (!ticketId || !token) {
      return NextResponse.json({ error: 'ticketId and token are required' }, { status: 400 })
    }

    const ticket = await prisma.supportTicket.findFirst({
      where: {
        id: ticketId,
        externalMessageId: guestTokenPrefix(token),
      },
      include: { responses: { orderBy: { createdAt: 'asc' } } },
    })
    if (!ticket) {
      return NextResponse.json({ error: 'Ticket not found' }, { status: 404 })
    }

    const agent = getSupportAgentForTimestamp(new Date(ticket.createdAt || Date.now()))
    const feedbackPrompt = buildSupportFeedbackPrompt(ticket.userName, agent)
    const hasFeedbackPrompt = ticket.responses?.some((response) => response.isAdminResponse && response.message?.includes('rate your support experience'))
    if (!hasFeedbackPrompt) {
      await prisma.ticketResponse.create({
        data: {
          ticketId: ticket.id,
          message: feedbackPrompt,
          isAdminResponse: true,
          adminId: null,
        },
      })
    }

    await prisma.supportTicket.update({
      where: { id: ticket.id },
      data: {
        status: 'RESOLVED',
        updatedAt: new Date(),
      },
    })

    try {
      await sendSupportTranscriptEmail(ticket.id)
    } catch (emailError) {
      console.error('📧 [SUPPORT TRANSCRIPT] Failed to send inquiry transcript:', emailError)
    }

    const updatedTicket = await prisma.supportTicket.findUnique({
      where: { id: ticket.id },
      include: { responses: { orderBy: { createdAt: 'asc' } } },
    })

    return NextResponse.json({ ticket: updatedTicket ? rehydrateSupportTicket(updatedTicket) : updatedTicket })
  }

  if (action === 'submit_feedback') {
    const ticketId = String(body?.ticketId || '').trim()
    const token = String(body?.token || '').trim()
    const rating = Number(body?.rating || 0)
    const comment = String(body?.comment || '').trim()
    if (!ticketId || !token) {
      return NextResponse.json({ error: 'ticketId and token are required' }, { status: 400 })
    }
    if (!Number.isFinite(rating) || rating < 1 || rating > 5) {
      return NextResponse.json({ error: 'rating must be between 1 and 5' }, { status: 400 })
    }

    const ticket = await prisma.supportTicket.findFirst({
      where: {
        id: ticketId,
        externalMessageId: guestTokenPrefix(token),
      },
    })
    if (!ticket) {
      return NextResponse.json({ error: 'Ticket not found' }, { status: 404 })
    }

    const feedbackMessage = [
      `[FEEDBACK] Rating: ${rating}/5`,
      comment ? `Comment: ${comment}` : 'Comment: (none)',
    ].join('\n')

    await prisma.ticketResponse.create({
      data: {
        ticketId,
        message: feedbackMessage,
        isAdminResponse: false,
        userEmail: ticket.userEmail,
      },
    })

    await prisma.supportTicket.update({
      where: { id: ticketId },
      data: {
        status: 'CLOSED',
        updatedAt: new Date(),
      },
    })

    try {
      await sendSupportFeedbackEmail({ ticketId, rating, comment })
    } catch (emailError) {
      console.error('📧 [SUPPORT FEEDBACK] Failed to send inquiry feedback email:', emailError)
    }

    const updatedTicket = await prisma.supportTicket.findUnique({
      where: { id: ticketId },
      include: { responses: { orderBy: { createdAt: 'asc' } } },
    })

    return NextResponse.json({ ticket: updatedTicket ? rehydrateSupportTicket(updatedTicket) : updatedTicket })
  }

  if (action === 'delete_ticket') {
    const ticketId = String(body?.ticketId || '').trim()
    const token = String(body?.token || '').trim()
    if (!ticketId || !token) {
      return NextResponse.json({ error: 'ticketId and token are required' }, { status: 400 })
    }

    const ticket = await prisma.supportTicket.findFirst({
      where: {
        id: ticketId,
        externalMessageId: guestTokenPrefix(token),
      },
    })
    if (!ticket) {
      return NextResponse.json({ error: 'Ticket not found' }, { status: 404 })
    }

    await prisma.supportTicket.delete({
      where: { id: ticketId },
    })

    return NextResponse.json({ success: true })
  }

  return NextResponse.json({ error: 'Invalid action' }, { status: 400 })
}

import { NextRequest, NextResponse } from 'next/server'
import { put } from '@vercel/blob'
import { prisma } from '@/lib/prisma'
import { buildSignedBlobUrl } from '@/lib/blob-access'

const MAX_UPLOAD_BYTES = 15 * 1024 * 1024
const ALLOWED_TYPES = new Set([
  'image/jpeg',
  'image/png',
  'image/webp',
  'image/gif',
  'application/pdf',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
])

function sanitizeFilename(name: string) {
  return name.replace(/[^a-zA-Z0-9._-]/g, '_')
}

function guestTokenPrefix(token: string) {
  return `guest:${token}`
}

export async function POST(request: NextRequest) {
  if (!process.env.BLOB_READ_WRITE_TOKEN) {
    return NextResponse.json({ error: 'Upload system not configured' }, { status: 503 })
  }

  // NextRequest.formData() returns a standard web FormData, but type
  // definitions can vary between runtimes and cause build-time TS errors.
  // Cast to `any` here to preserve runtime behavior without changing logic.
  const formData: any = await request.formData().catch(() => null)
  if (!formData) {
    return NextResponse.json({ error: 'Invalid upload data' }, { status: 400 })
  }

  const ticketId = String(formData.get('ticketId') || '').trim()
  const token = String(formData.get('token') || '').trim()
  if (!ticketId || !token) {
    return NextResponse.json({ error: 'Missing ticketId or token' }, { status: 400 })
  }

  const ticket = await prisma.supportTicket.findFirst({
    where: { id: ticketId, externalMessageId: guestTokenPrefix(token) },
  })
  if (!ticket) {
    return NextResponse.json({ error: 'Ticket not found' }, { status: 404 })
  }

  const file = formData.get('file')
  if (!(file instanceof File)) {
    return NextResponse.json({ error: 'No file provided' }, { status: 400 })
  }

  if (!ALLOWED_TYPES.has(file.type)) {
    return NextResponse.json({ error: 'Unsupported file type' }, { status: 400 })
  }

  if (file.size > MAX_UPLOAD_BYTES) {
    return NextResponse.json({ error: 'File is too large (max 15MB)' }, { status: 400 })
  }

  const buffer = Buffer.from(await file.arrayBuffer())
  const safeName = sanitizeFilename(file.name || 'upload')
  const pathname = `support/inquiry/${ticketId}/${Date.now()}-${safeName}`

  const blob = await put(pathname, buffer, {
    access: 'public',
    contentType: file.type || 'application/octet-stream',
  })

  const signedUrl = buildSignedBlobUrl(blob.pathname, 'support', 60 * 60)
  if (!signedUrl) {
    return NextResponse.json({ error: 'Failed to create secure link' }, { status: 500 })
  }

  return NextResponse.json({
    name: file.name || safeName,
    url: signedUrl,
    path: blob.pathname,
    type: file.type,
    size: file.size,
  })
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'
import { prisma } from '@/lib/prisma'
import { TicketCategory, TicketPriority } from '@prisma/client'
import { buildSupportFeedbackPrompt, processSupportTicketAutoReply, sendSupportFeedbackEmail, sendSupportTranscriptEmail } from '@/lib/support-automation'
import { getSupportAgentForTimestamp } from '@/lib/support-agents'
import { rehydrateSupportTicket } from '@/lib/support-attachments'

function normalizeCategory(value: string | undefined): TicketCategory {
  const upper = (value || '').toUpperCase()
  const allowed: TicketCategory[] = ['GENERAL', 'TECHNICAL', 'BILLING', 'ACCOUNT', 'FEATURE_REQUEST', 'BUG_REPORT', 'EMAIL']
  return allowed.includes(upper as TicketCategory) ? (upper as TicketCategory) : 'GENERAL'
}

function normalizePriority(value: string | undefined): TicketPriority {
  const upper = (value || '').toUpperCase()
  const allowed: TicketPriority[] = ['LOW', 'MEDIUM', 'HIGH', 'URGENT']
  return allowed.includes(upper as TicketPriority) ? (upper as TicketPriority) : 'MEDIUM'
}

async function getSupportUser(request: NextRequest) {
  const session = await getServerSession(authOptions)
  const sessionEmail = String(session?.user?.email || '').trim().toLowerCase()

  if (sessionEmail) {
    const user = await prisma.user.findUnique({
      where: { email: sessionEmail },
      select: { id: true, email: true, name: true },
    })

    return {
      id: String(session?.user?.id || user?.id || ''),
      email: sessionEmail,
      name: String(session?.user?.name || user?.name || ''),
    }
  }

  const nativeUserId = await getUserIdFromNativeAuth(request)
  if (!nativeUserId) return null

  const user = await prisma.user.findUnique({
    where: { id: nativeUserId },
    select: { id: true, email: true, name: true },
  })

  const email = String(user?.email || '').trim().toLowerCase()
  if (!email) return null

  return {
    id: user?.id || nativeUserId,
    email,
    name: String(user?.name || ''),
  }
}

function supportTicketOwnerWhere(user: { id?: string | null; email: string }) {
  const email = String(user.email || '').trim().toLowerCase()
  const id = String(user.id || '').trim()
  if (!id) return { userEmail: email }
  return { OR: [{ userId: id }, { userEmail: email }] }
}

export async function GET(request: NextRequest) {
  const user = await getSupportUser(request)
  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { searchParams } = new URL(request.url)
  const activeOnly = searchParams.get('activeOnly') !== '0'
  const listMode = searchParams.get('list') === '1'
  const ticketIdParam = String(searchParams.get('ticketId') || '').trim()

  const whereClause: any = supportTicketOwnerWhere(user)
  if (activeOnly) {
    whereClause.status = { notIn: ['RESOLVED', 'CLOSED'] }
  }

  if (ticketIdParam) {
    const ticket = await prisma.supportTicket.findFirst({
      where: { ...whereClause, id: ticketIdParam },
      include: {
        responses: { orderBy: { createdAt: 'asc' } },
      },
    })
    return NextResponse.json({ ticket: ticket ? rehydrateSupportTicket(ticket) : null })
  }

  if (listMode) {
    const tickets = await prisma.supportTicket.findMany({
      where: whereClause,
      orderBy: { createdAt: 'desc' },
      select: {
        id: true,
        subject: true,
        status: true,
        priority: true,
        category: true,
        createdAt: true,
        updatedAt: true,
      },
    })
    return NextResponse.json({ tickets })
  }

  const ticket = await prisma.supportTicket.findFirst({
    where: whereClause,
    orderBy: { createdAt: 'desc' },
    include: {
      responses: { orderBy: { createdAt: 'asc' } },
    },
  })

  return NextResponse.json({ ticket: ticket ? rehydrateSupportTicket(ticket) : null })
}

export async function POST(request: NextRequest) {
  const user = await getSupportUser(request)
  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }
  const email = user.email
  const name = user.name

  const body = await request.json().catch(() => ({}))
  const action = String(body?.action || '').trim()
  const message = String(body?.message || '').trim()
  const requiresMessage = action === 'create' || action === 'add_response'

  if (requiresMessage && !message) {
    return NextResponse.json({ error: 'Message is required' }, { status: 400 })
  }

  if (action === 'create') {
    const subject = String(body?.subject || '').trim() || `Support request from ${email}`
    const category = normalizeCategory(body?.category)
    const priority = normalizePriority(body?.priority)

    const ticket = await prisma.supportTicket.create({
      data: {
        subject,
        message,
        userEmail: email,
        userName: name || undefined,
        userId: user.id || null,
        status: 'OPEN',
        priority,
        category,
      },
      include: {
        responses: { orderBy: { createdAt: 'asc' } },
      },
    })

    try {
      await processSupportTicketAutoReply({
        ticketId: ticket.id,
        latestUserMessage: message,
        source: 'app_ticket',
      })
    } catch (aiError) {
      console.error('🤖 [SUPPORT AI] Failed to auto-reply to in-app ticket:', aiError)
    }

    const updatedTicket = await prisma.supportTicket.findUnique({
      where: { id: ticket.id },
      include: { responses: { orderBy: { createdAt: 'asc' } } },
    })

    return NextResponse.json({ ticket: updatedTicket ? rehydrateSupportTicket(updatedTicket) : updatedTicket })
  }

  if (action === 'add_response') {
    const ticketId = String(body?.ticketId || '').trim()
    if (!ticketId) {
      return NextResponse.json({ error: 'ticketId is required' }, { status: 400 })
    }

    const ticket = await prisma.supportTicket.findFirst({
      where: { id: ticketId, ...supportTicketOwnerWhere(user) },
    })
    if (!ticket) {
      return NextResponse.json({ error: 'Ticket not found' }, { status: 404 })
    }

    await prisma.ticketResponse.create({
      data: {
        ticketId,
        message,
        isAdminResponse: false,
        userEmail: email,
      },
    })

    await prisma.supportTicket.update({
      where: { id: ticketId },
      data: {
        status: 'AWAITING_RESPONSE',
        updatedAt: new Date(),
      },
    })

    try {
      await processSupportTicketAutoReply({
        ticketId,
        latestUserMessage: message,
        source: 'app_reply',
      })
    } catch (aiError) {
      console.error('🤖 [SUPPORT AI] Failed to auto-reply to in-app reply:', aiError)
    }

    const updatedTicket = await prisma.supportTicket.findUnique({
      where: { id: ticketId },
      include: { responses: { orderBy: { createdAt: 'asc' } } },
    })

    return NextResponse.json({ ticket: updatedTicket ? rehydrateSupportTicket(updatedTicket) : updatedTicket })
  }

  if (action === 'end_chat') {
    const ticketId = String(body?.ticketId || '').trim()
    if (!ticketId) {
      return NextResponse.json({ error: 'ticketId is required' }, { status: 400 })
    }

    const ticket = await prisma.supportTicket.findFirst({
      where: { id: ticketId, ...supportTicketOwnerWhere(user) },
      include: { responses: { orderBy: { createdAt: 'asc' } } },
    })
    if (!ticket) {
      return NextResponse.json({ error: 'Ticket not found' }, { status: 404 })
    }

    const agent = getSupportAgentForTimestamp(new Date(ticket.createdAt || Date.now()))
    const feedbackPrompt = buildSupportFeedbackPrompt(ticket.userName, agent)
    const hasFeedbackPrompt = ticket.responses?.some((response) => response.isAdminResponse && response.message?.includes('rate your support experience'))
    if (!hasFeedbackPrompt) {
      await prisma.ticketResponse.create({
        data: {
          ticketId: ticket.id,
          message: feedbackPrompt,
          isAdminResponse: true,
          adminId: null,
        },
      })
    }

    await prisma.supportTicket.update({
      where: { id: ticket.id },
      data: {
        status: 'RESOLVED',
        updatedAt: new Date(),
      },
    })

    try {
      await sendSupportTranscriptEmail(ticket.id)
    } catch (emailError) {
      console.error('📧 [SUPPORT TRANSCRIPT] Failed to send transcript:', emailError)
    }

    const updatedTicket = await prisma.supportTicket.findUnique({
      where: { id: ticket.id },
      include: { responses: { orderBy: { createdAt: 'asc' } } },
    })

    return NextResponse.json({ ticket: updatedTicket ? rehydrateSupportTicket(updatedTicket) : updatedTicket })
  }

  if (action === 'delete_ticket') {
    const ticketId = String(body?.ticketId || '').trim()
    if (!ticketId) {
      return NextResponse.json({ error: 'ticketId is required' }, { status: 400 })
    }

    const ticket = await prisma.supportTicket.findFirst({
      where: { id: ticketId, ...supportTicketOwnerWhere(user) },
    })
    if (!ticket) {
      return NextResponse.json({ error: 'Ticket not found' }, { status: 404 })
    }

    await prisma.supportTicket.delete({
      where: { id: ticketId },
    })

    return NextResponse.json({ success: true })
  }

  if (action === 'submit_feedback') {
    const ticketId = String(body?.ticketId || '').trim()
    const rating = Number(body?.rating || 0)
    const comment = String(body?.comment || '').trim()
    if (!ticketId) {
      return NextResponse.json({ error: 'ticketId is required' }, { status: 400 })
    }
    if (!Number.isFinite(rating) || rating < 1 || rating > 5) {
      return NextResponse.json({ error: 'rating must be between 1 and 5' }, { status: 400 })
    }

    const ticket = await prisma.supportTicket.findFirst({
      where: { id: ticketId, ...supportTicketOwnerWhere(user) },
    })
    if (!ticket) {
      return NextResponse.json({ error: 'Ticket not found' }, { status: 404 })
    }

    const feedbackMessage = [
      `[FEEDBACK] Rating: ${rating}/5`,
      comment ? `Comment: ${comment}` : 'Comment: (none)',
    ].join('\n')

    await prisma.ticketResponse.create({
      data: {
        ticketId,
        message: feedbackMessage,
        isAdminResponse: false,
        userEmail: email,
      },
    })

    await prisma.supportTicket.update({
      where: { id: ticketId },
      data: {
        status: 'CLOSED',
        updatedAt: new Date(),
      },
    })

    try {
      await sendSupportFeedbackEmail({ ticketId, rating, comment })
    } catch (emailError) {
      console.error('📧 [SUPPORT FEEDBACK] Failed to send feedback email:', emailError)
    }

    const updatedTicket = await prisma.supportTicket.findUnique({
      where: { id: ticketId },
      include: { responses: { orderBy: { createdAt: 'asc' } } },
    })

    return NextResponse.json({ ticket: updatedTicket ? rehydrateSupportTicket(updatedTicket) : updatedTicket })
  }

  return NextResponse.json({ error: 'Invalid action' }, { status: 400 })
}

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'
import { put } from '@vercel/blob'
import { prisma } from '@/lib/prisma'
import { buildSignedBlobUrl } from '@/lib/blob-access'

const MAX_UPLOAD_BYTES = 15 * 1024 * 1024
const ALLOWED_TYPES = new Set([
  'image/jpeg',
  'image/png',
  'image/webp',
  'image/gif',
  'application/pdf',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
])

function sanitizeFilename(name: string) {
  return name.replace(/[^a-zA-Z0-9._-]/g, '_')
}

export async function POST(request: NextRequest) {
  const session = await getServerSession(authOptions)
  const userId = session?.user?.id || (await getUserIdFromNativeAuth(request))
  if (!userId) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  if (!process.env.BLOB_READ_WRITE_TOKEN) {
    return NextResponse.json({ error: 'Upload system not configured' }, { status: 503 })
  }

  // NextRequest.formData() returns a standard web FormData, but type
  // definitions can vary between runtimes and cause build-time TS errors.
  // Cast to `any` here to preserve runtime behavior without changing logic.
  const formData: any = await request.formData().catch(() => null)
  if (!formData) {
    return NextResponse.json({ error: 'Invalid upload data' }, { status: 400 })
  }

  const file = formData.get('file')
  if (!(file instanceof File)) {
    return NextResponse.json({ error: 'No file provided' }, { status: 400 })
  }

  if (!ALLOWED_TYPES.has(file.type)) {
    return NextResponse.json({ error: 'Unsupported file type' }, { status: 400 })
  }

  if (file.size > MAX_UPLOAD_BYTES) {
    return NextResponse.json({ error: 'File is too large (max 15MB)' }, { status: 400 })
  }

  const buffer = Buffer.from(await file.arrayBuffer())
  const safeName = sanitizeFilename(file.name || 'upload')
  const pathname = `support/${userId}/${Date.now()}-${safeName}`

  const blob = await put(pathname, buffer, {
    access: 'public',
    contentType: file.type || 'application/octet-stream',
  })

  const signedUrl = buildSignedBlobUrl(blob.pathname, 'support', 60 * 60)
  if (!signedUrl) {
    return NextResponse.json({ error: 'Failed to create secure link' }, { status: 500 })
  }

  const fileType = file.type.startsWith('image/') ? 'IMAGE' : 'DOCUMENT'
  const usage = file.type.startsWith('image/') ? 'OTHER' : 'DOCUMENT'

  const fileRecord = await prisma.file.create({
    data: {
      originalName: file.name || safeName,
      fileName: blob.pathname,
      fileSize: file.size,
      mimeType: file.type || 'application/octet-stream',
      cloudinaryId: blob.pathname,
      cloudinaryUrl: blob.url,
      secureUrl: blob.url,
      uploadedById: userId,
      fileType,
      usage,
      metadata: {
        storage: 'vercel-blob',
        blobUrl: blob.url,
        blobPathname: blob.pathname,
        access: 'public',
      },
    },
  })

  return NextResponse.json({
    fileId: fileRecord.id,
    name: fileRecord.originalName,
    url: signedUrl,
    path: blob.pathname,
    type: fileRecord.mimeType,
    size: fileRecord.fileSize,
    fileType,
  })
}

