const normalizeAuditString = (value: any) => {
  if (value === null || value === undefined) return ''
  return String(value).trim()
}

const normalizeAuditNumber = (value: any) => {
  const n = Number(value)
  return Number.isFinite(n) ? Number(n) : null
}

const stableAuditValue = (value: any) => {
  if (value === null || value === undefined) return null
  if (typeof value === 'number') {
    return Number.isFinite(value) ? Number(value) : null
  }
  if (typeof value === 'string') return value
  if (typeof value === 'boolean') return value
  try {
    return JSON.parse(JSON.stringify(value))
  } catch {
    return String(value)
  }
}

const buildProfileTargetChanges = (before: Record<string, any>, after: Record<string, any>) => {
  const fields = ['weight', 'height', 'exerciseFrequency', 'bodyType', 'birthdate', 'goalChoice', 'goalIntensity']
  const changes: Record<string, { from: any; to: any }> = {}
  fields.forEach((field) => {
    const fromValue = stableAuditValue(before[field])
    const toValue = stableAuditValue(after[field])
    if (JSON.stringify(fromValue) !== JSON.stringify(toValue)) {
      changes[field] = { from: fromValue, to: toValue }
    }
  })
  return changes
}

const appendProfileTargetAuditEntry = async (params: {
  userId: string
  eventType: 'changed' | 'blocked_missing_stamp' | 'blocked_stale_stamp'
  source: string
  incomingHealthSetupUpdatedAt: number | null
  serverHealthSetupUpdatedAt: number
  requestKeys: string[]
  changes?: Record<string, { from: any; to: any }>
  note?: string
}) => {
  try {
    const existingAudit = await prisma.healthGoal.findFirst({
      where: { userId: params.userId, name: PROFILE_TARGET_AUDIT_RECORD_NAME },
      orderBy: { updatedAt: 'desc' },
    })

    let existingEntries: any[] = []
    if (existingAudit?.category) {
      try {
        const parsed = JSON.parse(existingAudit.category)
        if (Array.isArray(parsed?.entries)) existingEntries = parsed.entries
      } catch {
        existingEntries = []
      }
    }

    const entry = {
      changedAt: new Date().toISOString(),
      eventType: params.eventType,
      source: params.source,
      incomingHealthSetupUpdatedAt: params.incomingHealthSetupUpdatedAt,
      serverHealthSetupUpdatedAt: params.serverHealthSetupUpdatedAt,
      requestKeys: params.requestKeys.slice(0, 40),
      changes: params.changes || {},
      note: params.note || '',
    }

    const nextEntries = [...existingEntries, entry].slice(-MAX_PROFILE_TARGET_AUDIT_ENTRIES)
    const auditPayload = {
      userId: params.userId,
      name: PROFILE_TARGET_AUDIT_RECORD_NAME,
      category: JSON.stringify({ entries: nextEntries }),
      currentRating: 0,
    }

    const auditRecord = existingAudit
      ? await prisma.healthGoal.update({
          where: { id: existingAudit.id },
          data: auditPayload,
        })
      : await prisma.healthGoal.create({ data: auditPayload })

    await prisma.healthGoal.deleteMany({
      where: {
        userId: params.userId,
        name: PROFILE_TARGET_AUDIT_RECORD_NAME,
        id: { not: auditRecord.id },
      },
    })
  } catch (error) {
    console.warn('Failed to append profile target audit entry', error)
  }
}

const splitSupplementName = (rawName: string) => {
  const cleaned = String(rawName || '').trim()
  if (!cleaned) return { brand: null as string | null, product: null as string | null }
  const parts = cleaned.split(' - ').map((part) => part.trim()).filter(Boolean)
  if (parts.length >= 2) {
    const brand = parts[0] || null
    const product = parts.slice(1).join(' - ').trim() || null
    return { brand, product }
  }
  return { brand: null, product: cleaned }
}

const isPlaceholderName = (value: string) => {
  const safe = String(value || '').trim().toLowerCase()
  return new Set([
    'analyzing...',
    'supplement added',
    'unknown supplement',
    'analysis error',
    'unknown medication',
    'medication added',
  ]).has(safe)
}

const splitMedicationName = (rawName: string) => {
  const cleaned = String(rawName || '').trim()
  if (!cleaned) return { brand: null as string | null, product: null as string | null }
  // Medications might be "Brand (Generic)" or "Generic (Brand)" format
  if (cleaned.includes('(') && cleaned.includes(')')) {
    const match = cleaned.match(/^(.+?)\s*\((.+?)\)$/)
    if (match) {
      return { brand: match[1].trim() || null, product: match[2].trim() || null }
    }
  }
  // Try "Brand - Product" format
  const parts = cleaned.split(' - ').map((part) => part.trim()).filter(Boolean)
  if (parts.length >= 2) {
    const brand = parts[0] || null
    const product = parts.slice(1).join(' - ').trim() || null
    return { brand, product }
  }
  return { brand: null, product: cleaned }
}

const buildSupplementCatalogRows = (supplements: any[], userId: string) => {
  if (!Array.isArray(supplements)) return []
  return supplements
    .filter((supp: any) => supp && supp.name && String(supp.name || '').trim().length > 0)
    .map((supp: any) => {
      const { brand, product } = splitSupplementName(supp.name)
      const isPhoto = supp.method === 'photo' || !!supp.imageUrl
      return {
        userId,
        brand,
        product,
        fullName: String(supp.name || '').trim(),
        dosage: String(supp.dosage || '').trim(),
        source: isPhoto ? 'photo' : 'manual',
      }
    })
    .filter((row) => row.fullName && !isPlaceholderName(row.fullName))
}

const buildMedicationCatalogRows = (medications: any[], userId: string) => {
  if (!Array.isArray(medications)) return []
  return medications
    .filter((med: any) => med && med.name && String(med.name || '').trim().length > 0)
    .map((med: any) => {
      const { brand, product } = splitMedicationName(med.name)
      const isPhoto = !!med.imageUrl
      return {
        userId,
        brand,
        product,
        fullName: String(med.name || '').trim(),
        dosage: String(med.dosage || '').trim(),
        source: isPhoto ? 'photo' : 'manual',
      }
    })
    .filter((row) => row.fullName && !isPlaceholderName(row.fullName))
}

const normalizeFoodCategory = (raw: any) => {
  const value = typeof raw === 'string' ? raw.toLowerCase() : ''
  if (/breakfast/.test(value)) return 'breakfast'
  if (/lunch/.test(value)) return 'lunch'
  if (/dinner/.test(value)) return 'dinner'
  if (/snack/.test(value)) return 'snacks'
  if (/other/.test(value) || /uncat/.test(value)) return 'uncategorized'
  return value && value.trim().length > 0 ? value.trim() : 'uncategorized'
}

const extractFavoriteIdFromNutrition = (nutrients: any) => {
  if (!nutrients || typeof nutrients !== 'object') return ''
  const raw = (nutrients as any).__favoriteId
  return typeof raw === 'string' ? raw.trim() : ''
}

const extractFavoriteUsageTimestampMs = (log: any) => {
  if (!log || typeof log !== 'object') return 0
  const nutrients = log?.nutrients && typeof log.nutrients === 'object' ? (log.nutrients as any) : null
  const addedOrder = Number(nutrients?.__addedOrder)
  if (Number.isFinite(addedOrder) && addedOrder > 0) return addedOrder
  const createdAt = log?.createdAt ? new Date(log.createdAt).getTime() : NaN
  if (Number.isFinite(createdAt) && createdAt > 0) return createdAt
  return 0
}

const extractFavoriteLabelFromLog = (description: any, fallback?: any) => {
  const raw = String(description || fallback || '').trim()
  if (!raw) return 'Favorite meal'
  const firstLine = raw.split('\n')[0] || raw
  const cleaned = firstLine.split('Calories:')[0].trim()
  return cleaned || firstLine.trim() || 'Favorite meal'
}

