        };
      }
    } catch (e) {
      console.log('No blood results data found in storage');
    }

    // Get today's food entries
    let normalizedTodaysFoods: any[] = []
    let favorites: any[] = []
    let foodNameOverrides: any[] = []
    let foodLibrary: any[] = []
    if (includeFoodData) {
      const normalizeCategory = (raw: any) => {
        const value = typeof raw === 'string' ? raw.toLowerCase() : ''
        if (/breakfast/.test(value)) return 'breakfast'
        if (/lunch/.test(value)) return 'lunch'
        if (/dinner/.test(value)) return 'dinner'
        if (/snack/.test(value)) return 'snacks'
        if (/other/.test(value) || /uncat/.test(value)) return 'uncategorized'
        return value && value.trim().length > 0 ? value.trim() : 'uncategorized'
      }
      const buildTodayIso = () => {
        const d = new Date()
        const y = d.getFullYear()
        const m = String(d.getMonth() + 1).padStart(2, '0')
        const day = String(d.getDate()).padStart(2, '0')
        return `${y}-${m}-${day}`
      }
      let todaysFoods: any[] = []
      try {
        const storedFoods = user.healthGoals.find((goal: any) => goal.name === '__TODAYS_FOODS_DATA__');
        if (storedFoods && storedFoods.category) {
          const parsed = JSON.parse(storedFoods.category);
          todaysFoods = parsed.foods || [];
        }
      } catch (e) {
        console.log('No todays foods data found in storage');
      }
      const deriveLocalDateFromEntry = (entry: any) => {
        try {
          const ts = typeof entry?.id === 'number' ? entry.id : Number(entry?.id)
          if (Number.isFinite(ts)) {
            const d = new Date(ts)
            if (!Number.isNaN(d.getTime())) {
              const y = d.getFullYear()
              const m = String(d.getMonth() + 1).padStart(2, '0')
              const day = String(d.getDate()).padStart(2, '0')
              return `${y}-${m}-${day}`
            }
          }
        } catch {}
        return ''
      }
      normalizedTodaysFoods = Array.isArray(todaysFoods)
        ? todaysFoods
            .map((entry: any) => {
              const category = normalizeCategory(entry?.meal ?? entry?.category ?? entry?.mealType ?? entry?.persistedCategory)
              const explicitLocalDate =
                typeof entry?.localDate === 'string' && entry.localDate.length >= 8
                  ? entry.localDate
                  : ''
              const derivedLocalDate = deriveLocalDateFromEntry(entry)
              const localDate = explicitLocalDate || derivedLocalDate
              if (!localDate) return null
              return {
                ...entry,
                meal: category,
                category,
                persistedCategory: entry?.persistedCategory ?? category,
                localDate,
              }
            })
            .filter(Boolean)
        : []

      // Get saved favorites.
      //
      // IMPORTANT:
      // Some accounts can end up with multiple `__FOOD_FAVORITES__` rows (historical writes / recovery routes).
      // `user.healthGoals.find(...)` is not deterministic because Prisma does not guarantee ordering here.
      // If we pick an older row, the UI can "revert" to an old long USDA title after refresh.
      // Always pick the newest favorites record.
      try {
        const storedFavorites = (() => {
          const matches = (user.healthGoals || []).filter((goal: any) => goal?.name === '__FOOD_FAVORITES__')
          if (matches.length <= 1) return matches[0] || null
          return matches
            .slice()
            .sort((a: any, b: any) => {
              const aTs = a?.createdAt ? new Date(a.createdAt).getTime() : 0
              const bTs = b?.createdAt ? new Date(b.createdAt).getTime() : 0
              return bTs - aTs
            })[0]
        })()
        if (storedFavorites && storedFavorites.category) {
          const parsed = JSON.parse(storedFavorites.category)
          if (Array.isArray(parsed?.favorites)) {
            favorites = parsed.favorites
          } else if (Array.isArray(parsed)) {
            favorites = parsed
          }
        }
      } catch (e) {
        console.log('No favorites data found in storage')
      }

      // Backfill missing favorite recency for older records.
      // Some historical favorites were saved without lastUsedAt, which causes wrong ordering.
      // We repair this once by deriving usage from linked diary logs.
      try {
        const needsLastUsedBackfill = (Array.isArray(favorites) ? favorites : []).some(
          (fav: any) => Number(fav?.lastUsedAt) <= 0,
        )
        if (needsLastUsedBackfill) {
          const cutoff = new Date(Date.now() - 120 * 24 * 60 * 60 * 1000)
          const recentUsageLogs = await prisma.foodLog.findMany({
            where: { userId: user.id, createdAt: { gte: cutoff } },
            orderBy: { createdAt: 'desc' },
            take: 2000,
            select: {
              id: true,
              createdAt: true,
              nutrients: true,
            },
          })

          const lastUsedByFavoriteId = new Map<string, number>()
          recentUsageLogs.forEach((log: any) => {
            const favoriteId = extractFavoriteIdFromNutrition(log?.nutrients)
            if (!favoriteId) return
            const usageTs = extractFavoriteUsageTimestampMs(log)
            if (!Number.isFinite(usageTs) || usageTs <= 0) return
            const prev = Number(lastUsedByFavoriteId.get(favoriteId) || 0)
            if (usageTs > prev) lastUsedByFavoriteId.set(favoriteId, usageTs)
          })

          if (lastUsedByFavoriteId.size > 0) {
            let changed = false
            const repaired = (Array.isArray(favorites) ? favorites : []).map((fav: any) => {
              const currentLastUsed = Number(fav?.lastUsedAt)
              if (Number.isFinite(currentLastUsed) && currentLastUsed > 0) return fav
              const favId = typeof fav?.id === 'string' ? String(fav.id).trim() : ''
              if (!favId) return fav
              const recoveredLastUsed = Number(lastUsedByFavoriteId.get(favId) || 0)
              if (!Number.isFinite(recoveredLastUsed) || recoveredLastUsed <= 0) return fav
              changed = true
              return { ...fav, lastUsedAt: recoveredLastUsed }
            })

            if (changed) {
              favorites = repaired
              const existingGoals = await prisma.healthGoal.findMany({
                where: { userId: user.id, name: '__FOOD_FAVORITES__' },
                orderBy: { createdAt: 'desc' },
                select: { id: true },
              })
              const primary = existingGoals[0] || null
              if (primary?.id) {
                await prisma.healthGoal.update({
                  where: { id: primary.id },
                  data: {
                    category: JSON.stringify({ favorites }),
                    currentRating: 0,
                  },
                })
                if (existingGoals.length > 1) {
                  await prisma.healthGoal.deleteMany({
                    where: { id: { in: existingGoals.slice(1).map((g) => g.id) } },
                  })
                }
              } else {
                await prisma.healthGoal.create({
                  data: {
                    userId: user.id,
                    name: '__FOOD_FAVORITES__',
                    category: JSON.stringify({ favorites }),
                    currentRating: 0,
                  },
                })
              }
              console.log('Backfilled missing favorites lastUsedAt from diary history')
            }
          }
        }
      } catch (backfillError) {
        console.warn('Favorite recency backfill failed (non-blocking)', backfillError)
      }

      // Recovery guard:
      // If diary logs still point to favorite IDs that are missing from the stored favorites list,
      // rebuild those missing favorites from recent logs so user-saved meals do not disappear.
      try {
        const favoriteIds = new Set(
          (Array.isArray(favorites) ? favorites : [])
            .map((fav: any) => (typeof fav?.id === 'string' ? String(fav.id).trim() : ''))
            .filter(Boolean),
        )
        const existingById = new Map<string, any>()
        const existingLabelKeys = new Set<string>()
        const existingSourceIds = new Set<string>()
        ;(Array.isArray(favorites) ? favorites : []).forEach((fav: any) => {
          const id = typeof fav?.id === 'string' ? String(fav.id).trim() : ''
          if (id) existingById.set(id, fav)
          const labelKey = normalizeFavoriteLabelKey(fav?.label || fav?.description || '')
          if (labelKey) existingLabelKeys.add(labelKey)
          const sourceId = typeof fav?.sourceId === 'string' ? String(fav.sourceId).trim() : ''
          if (sourceId) existingSourceIds.add(sourceId)
        })
        const cutoff = new Date(Date.now() - 60 * 24 * 60 * 60 * 1000)
        const recentLogs = await prisma.foodLog.findMany({
          where: { userId: user.id, createdAt: { gte: cutoff } },
          orderBy: { createdAt: 'desc' },
          take: 1200,
          select: {
            id: true,
            name: true,
            description: true,
            imageUrl: true,
            nutrients: true,
            items: true,
            meal: true,
            category: true,
            createdAt: true,
          },
        })
        const recovered: any[] = []
        for (const log of recentLogs) {
          const nutrients = log?.nutrients && typeof log.nutrients === 'object' ? (log.nutrients as any) : null
          const favoriteId = extractFavoriteIdFromNutrition(nutrients)
          if (!favoriteId || favoriteIds.has(favoriteId) || existingById.has(favoriteId)) continue
          const label = extractFavoriteLabelFromLog(log?.description || log?.name || '', log?.name || 'Favorite meal')
          const labelKey = normalizeFavoriteLabelKey(label)
          const sourceId = log?.id ? String(log.id).trim() : ''
          if (labelKey && existingLabelKeys.has(labelKey)) continue
          if (sourceId && existingSourceIds.has(sourceId)) continue
          const items =
            Array.isArray(log?.items) && log.items.length > 0
              ? (log.items as any[])
              : Array.isArray((nutrients as any)?.items)
              ? ((nutrients as any).items as any[])
              : []
          const originRaw =
            typeof (nutrients as any)?.__origin === 'string'
              ? (nutrients as any).__origin
              : typeof (nutrients as any)?.origin === 'string'
              ? (nutrients as any).origin
              : ''
          const origin = String(originRaw || '').toLowerCase().trim()
          const customMeal = shouldMarkRecoveredFavoriteAsCustom(Array.isArray(items) ? items : [], origin)
          const createdAtMs = log?.createdAt ? new Date(log.createdAt).getTime() : Date.now()
          const recoveredFavorite: any = {
            id: favoriteId,
            sourceId: sourceId || null,
            label,
            description: label,
            nutrition: nutrients || null,
            total: nutrients || null,
            items: Array.isArray(items) && items.length > 0 ? items : null,
            photo: log?.imageUrl || null,
            method: customMeal ? (origin === 'combined' ? 'combined' : 'meal-builder') : origin || 'text',
            ...(customMeal ? { customMeal: true } : {}),
            meal: normalizeFoodCategory(log?.meal || log?.category || 'uncategorized'),
            createdAt: createdAtMs,
            lastUsedAt: createdAtMs,
          }
          recovered.push(recoveredFavorite)
          favoriteIds.add(favoriteId)
          existingById.set(favoriteId, recoveredFavorite)
          if (labelKey) existingLabelKeys.add(labelKey)
          if (sourceId) existingSourceIds.add(sourceId)
        }
        if (recovered.length > 0) {
          favorites = [...favorites, ...recovered]
          try {
            const existingGoals = await prisma.healthGoal.findMany({
              where: { userId: user.id, name: '__FOOD_FAVORITES__' },
              orderBy: { createdAt: 'desc' },
              select: { id: true },
            })
            const payload = JSON.stringify({ favorites })
            const primary = existingGoals[0] || null
            if (primary?.id) {
              await prisma.healthGoal.update({
                where: { id: primary.id },
                data: { category: payload, currentRating: 0 },
              })
              if (existingGoals.length > 1) {
                await prisma.healthGoal.deleteMany({
                  where: { id: { in: existingGoals.slice(1).map((g) => g.id) } },
                })
              }
            } else {
              await prisma.healthGoal.create({
                data: {
                  userId: user.id,
                  name: '__FOOD_FAVORITES__',
                  category: payload,
                  currentRating: 0,
                },
              })
            }
          } catch (repairWriteError) {
            console.warn('Could not persist recovered favorites (non-blocking)', repairWriteError)
          }
          console.log('Recovered missing favorites from linked logs:', recovered.length)
        }
      } catch (recoveryError) {
        console.warn('Favorite recovery check failed (non-blocking)', recoveryError)
      }

      // Get saved food name overrides (used for user renames without forcing favorites)
      try {
        const storedOverrides = (() => {
          const matches = (user.healthGoals || []).filter((goal: any) => goal?.name === '__FOOD_NAME_OVERRIDES__')
          if (matches.length <= 1) return matches[0] || null
          return matches
            .slice()
            .sort((a: any, b: any) => {
              const aTs = a?.createdAt ? new Date(a.createdAt).getTime() : 0
              const bTs = b?.createdAt ? new Date(b.createdAt).getTime() : 0
              return bTs - aTs
            })[0]
        })()
        if (storedOverrides && storedOverrides.category) {
          const parsed = JSON.parse(storedOverrides.category)
          if (Array.isArray(parsed?.overrides)) {
            foodNameOverrides = parsed.overrides
          } else if (Array.isArray(parsed)) {
            foodNameOverrides = parsed
          }
        }
      } catch (e) {
        console.log('No food name overrides data found in storage')
      }

      // Get food library (all-items list, independent from daily diary)
      try {
        const storedLibrary = user.healthGoals.find((goal: any) => goal.name === '__FOOD_LIBRARY__')
        if (storedLibrary && storedLibrary.category) {
          const parsed = JSON.parse(storedLibrary.category)
          if (Array.isArray(parsed?.items)) {
            foodLibrary = parsed.items
          } else if (Array.isArray(parsed?.library)) {
            foodLibrary = parsed.library
          } else if (Array.isArray(parsed)) {
            foodLibrary = parsed
          }
        }
      } catch (e) {
        console.log('No food library data found in storage')
      }
    }

    // Get device interest (stored in hidden goal record)
    let deviceInterestData: any = {}
    try {
      const storedDeviceInterest = user.healthGoals.find((goal: any) => goal.name === '__DEVICE_INTEREST__');
      if (storedDeviceInterest && storedDeviceInterest.category) {
        const parsed = JSON.parse(storedDeviceInterest.category);
        deviceInterestData = parsed || {}
      }
    } catch (e) {
      console.log('No device interest data found in storage');
    }

    // Get profile info data
    let profileInfoData = { firstName: '', lastName: '', bio: '', dateOfBirth: '', email: user.email || '' };
    try {
      const storedProfileInfo = user.healthGoals.find((goal: any) => goal.name === '__PROFILE_INFO_DATA__');
      if (storedProfileInfo && storedProfileInfo.category) {
        const parsed = JSON.parse(storedProfileInfo.category);
        profileInfoData = {
          firstName: parsed.firstName || '',
          lastName: parsed.lastName || '',
          bio: parsed.bio || '',
          dateOfBirth: parsed.dateOfBirth || '',
          email: parsed.email || user.email || ''
        };
      } else {
        // If no stored profile info, try to extract from user.name
        if (user.name) {
          const nameParts = user.name.split(' ');
          if (nameParts.length >= 2) {
            profileInfoData.firstName = nameParts[0];
            profileInfoData.lastName = nameParts.slice(1).join(' ');
          } else if (nameParts.length === 1) {
            profileInfoData.firstName = nameParts[0];
          }
        }
      }
      // Fallback: if stored profile info missing DOB but user has one, surface it
      if (!profileInfoData.dateOfBirth && (user as any).dateOfBirth) {
        profileInfoData.dateOfBirth = (user as any).dateOfBirth;
      }
    } catch (e) {
      console.log('No profile info data found in storage');
    }

    // Get primary goal choice + intensity (Step 2) stored as hidden health goal
    let primaryGoalData: {
      goalChoice?: string
      goalIntensity?: string
      goalTargetWeightKg?: number | null
      goalTargetWeightUnit?: string
      goalPaceKgPerWeek?: number | null
      goalCalorieTarget?: number | null
      goalMacroSplit?: { proteinPct?: number | null; carbPct?: number | null; fatPct?: number | null } | null
      goalMacroMode?: string
      goalFiberTarget?: number | null
      goalSugarMax?: number | null
    } = {};
    try {
      const storedPrimaryGoal = user.healthGoals.find((goal: any) => goal.name === '__PRIMARY_GOAL__');
      if (storedPrimaryGoal?.category) {
      const parsed = JSON.parse(storedPrimaryGoal.category);
      const parseOptionalNumber = (value: any) => {
        const n = Number(value)
        return Number.isFinite(n) ? n : null
      }
      const parseMacroSplit = (value: any) => {
        if (!value || typeof value !== 'object') return null
        const proteinPct = parseOptionalNumber(value.proteinPct)
        const carbPct = parseOptionalNumber(value.carbPct)
        const fatPct = parseOptionalNumber(value.fatPct)
        if (proteinPct === null && carbPct === null && fatPct === null) return null
        return { proteinPct, carbPct, fatPct }
      }
      primaryGoalData = {
        goalChoice: typeof parsed.goalChoice === 'string' ? parsed.goalChoice : '',
        goalIntensity: typeof parsed.goalIntensity === 'string' ? parsed.goalIntensity.toLowerCase() : '',
        goalTargetWeightKg: parseOptionalNumber(parsed.goalTargetWeightKg),
        goalTargetWeightUnit: typeof parsed.goalTargetWeightUnit === 'string' ? parsed.goalTargetWeightUnit.toLowerCase() : '',
        goalPaceKgPerWeek: parseOptionalNumber(parsed.goalPaceKgPerWeek),
        goalCalorieTarget: parseOptionalNumber(parsed.goalCalorieTarget),
        goalMacroSplit: parseMacroSplit(parsed.goalMacroSplit),
        goalMacroMode: typeof parsed.goalMacroMode === 'string' ? parsed.goalMacroMode.toLowerCase() : '',
        goalFiberTarget: parseOptionalNumber(parsed.goalFiberTarget),
        goalSugarMax: parseOptionalNumber(parsed.goalSugarMax),
      };
    }
  } catch (e) {
    console.log('No primary goal data found in storage');
  }

    // Transform to onboarding format
    let selectedGoals: string[] = []
    try {
      const selectedRecord = user.healthGoals.find((goal: any) => goal.name === '__SELECTED_ISSUES__')
      if (selectedRecord?.category) {
        const parsed = JSON.parse(selectedRecord.category)
        if (Array.isArray(parsed)) {
          selectedGoals = parsed.map((name) => String(name || '')).filter(Boolean)
        }
      }
    } catch (error) {
      console.warn('Failed to parse __SELECTED_ISSUES__ health goal', error)
      selectedGoals = []
    }
    console.log('GET /api/user-data - Parsed __SELECTED_ISSUES__ snapshot:', { count: selectedGoals.length, goals: selectedGoals })

    const hydrationGoal = computeHydrationGoal({
      weightKg: typeof user.weight === 'number' ? user.weight : null,
      heightCm: typeof user.height === 'number' ? user.height : null,
      gender: (user as any)?.gender ?? null,
      bodyType: (user as any)?.bodyType ?? null,
      exerciseFrequency: exerciseData.exerciseFrequency || '',
      exerciseTypes: exerciseData.exerciseTypes || [],
      dietTypes,
      diabetesType: allergyData.diabetesType,
      goalChoice: primaryGoalData.goalChoice || '',
      goalIntensity: primaryGoalData.goalIntensity || '',
      birthdate: profileInfoData.dateOfBirth || '',
    })
    let customHydrationTarget: number | null = null
    let hydrationUpdatedAt: string | null = null
    try {
      const storedHydrationGoal = user.healthGoals.find((goal: any) => goal.name === '__HYDRATION_GOAL__')
      if (storedHydrationGoal?.category) {
        const parsed = JSON.parse(storedHydrationGoal.category)
        const target = Number(parsed?.targetMl)
        if (Number.isFinite(target) && target > 0) {
          customHydrationTarget = Math.round(target)
          hydrationUpdatedAt = typeof parsed?.updatedAt === 'string' ? parsed.updatedAt : null
        }
      }
    } catch {
      customHydrationTarget = null
      hydrationUpdatedAt = null
    }
    const hydrationTarget = customHydrationTarget ?? hydrationGoal.targetMl
    const hydrationSource = customHydrationTarget ? 'custom' : 'auto'

    let healthSetupUpdatedAt: number | null = null
    try {
      const storedMeta = user.healthGoals.find((goal: any) => goal.name === '__HEALTH_SETUP_META__')
      if (storedMeta?.category) {
        const parsed = JSON.parse(storedMeta.category)
        const parsedUpdatedAt = Number(parsed?.updatedAt)
        if (Number.isFinite(parsedUpdatedAt) && parsedUpdatedAt > 0) {
          healthSetupUpdatedAt = parsedUpdatedAt
        }
      }
    } catch {
      healthSetupUpdatedAt = null
    }

    const onboardingData = {
      gender: user.gender?.toLowerCase() || '',
      weight: user.weight?.toString() || '',
      height: user.height?.toString() || '',
      bodyType: user.bodyType?.toLowerCase() || '',
      birthdate: profileInfoData.dateOfBirth || '',
      exerciseFrequency: exerciseData.exerciseFrequency || '',
      exerciseTypes: exerciseData.exerciseTypes || [],
      goals: selectedGoals.length
        ? selectedGoals
        : user.healthGoals.filter((goal: any) => !goal.name.startsWith('__')).map((goal: any) => goal.name),
      healthSituations: healthSituationsData,
      bloodResults: bloodResultsData,
      supplements: dedupeItems(user.supplements.map((supp: any) => ({
        name: supp.name,
        dosage: supp.dosage,
        timing: supp.timing,
        dateAdded: supp.dateAdded || supp.createdAt || new Date().toISOString(),
        method: supp.method || 'manual',
        scheduleInfo: supp.scheduleInfo || 'Daily',
        imageUrl: supp.imageUrl || null
      }))),
      medications: dedupeItems(user.medications.map((med: any) => ({
        name: med.name,
        dosage: med.dosage,
        timing: med.timing,
        dateAdded: med.dateAdded || med.createdAt || new Date().toISOString(),
        method: med.method || 'manual',
        scheduleInfo: med.scheduleInfo || 'Daily',
        imageUrl: med.imageUrl || null
      }))),
      profileImage: user.image || null,
      country: user.country || headerCountry || '',
      todaysFoods: normalizedTodaysFoods,
      favorites,
      foodLibrary,
      foodNameOverrides,
      profileInfo: profileInfoData,
      deviceInterest: deviceInterestData,
      termsAccepted: (user as any).termsAccepted === true,
      goalChoice: primaryGoalData.goalChoice || '',
      goalIntensity: (primaryGoalData.goalIntensity || 'standard').toString().toLowerCase(),
      goalTargetWeightKg: primaryGoalData.goalTargetWeightKg ?? null,
      goalTargetWeightUnit: primaryGoalData.goalTargetWeightUnit || '',
      goalPaceKgPerWeek: primaryGoalData.goalPaceKgPerWeek ?? null,
      goalCalorieTarget: primaryGoalData.goalCalorieTarget ?? null,
      goalMacroSplit: primaryGoalData.goalMacroSplit ?? null,
      goalMacroMode: primaryGoalData.goalMacroMode || 'auto',
      goalFiberTarget: primaryGoalData.goalFiberTarget ?? null,
      goalSugarMax: primaryGoalData.goalSugarMax ?? null,
      allergies: allergyData.allergies,
      diabetesType: allergyData.diabetesType,
      dietTypes,
      healthCheckSettings,
      healthSetupUpdatedAt,
      hydrationGoal: {
        targetMl: hydrationTarget,
        targetL: Math.round((hydrationTarget / 1000) * 100) / 100,
        recommendedMl: hydrationGoal.targetMl,
        recommendedL: Math.round((hydrationGoal.targetMl / 1000) * 100) / 100,
        source: hydrationSource,
        updatedAt: hydrationUpdatedAt,
      },
    }

    // Fallback: if primary goal still missing, use the first non-hidden health goal as a soft default
    if (!onboardingData.goalChoice && onboardingData.goals.length > 0) {
      onboardingData.goalChoice = onboardingData.goals[0]
    }

    console.log('GET /api/user-data - Returning onboarding data for user')

    // Debug: Log transformed data being returned
    console.log('GET /api/user-data - Transformed onboarding data:', {
      gender: onboardingData.gender,
      weight: onboardingData.weight,
      height: onboardingData.height,
      bodyType: onboardingData.bodyType,
      exerciseFrequency: onboardingData.exerciseFrequency,
      exerciseTypes: onboardingData.exerciseTypes,
      goalsCount: onboardingData.goals.length,
      supplementsCount: onboardingData.supplements.length,
      medicationsCount: onboardingData.medications.length,
      hasProfileImage: !!onboardingData.profileImage
    })

    return NextResponse.json({ data: onboardingData })
  } catch (error) {
    console.error('Error loading user data:', error)
    return NextResponse.json({ error: 'Failed to load data' }, { status: 500 })
  }
}

