                VALUES ($1, $2, $3, $4, $5, $6, $7, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
                ON CONFLICT ("userId", "fullName", "dosage", "source") DO NOTHING
              `,
                `med-cat-${user.id}-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`,
                row.userId || null,
                row.brand || null,
                row.product || null,
                row.fullName,
