              try {
                console.log('AGENT_DEBUG', JSON.stringify({
                  hypothesisId: 'A',
                  location: 'app/api/user-data/route.ts:POST:appendFoodLog',
                  message: 'Appended FoodLog row from /api/user-data (potential duplicate source)',
                  data: {
