// Separate component for search params handling with Suspense
function SearchParamsHandler({
  setError,
  setMessage,
  setIsSignUp,
  setShowResendVerification,
  setAuthContext,
}: {
  setError: (error: string) => void
  setMessage: (message: string) => void
  setIsSignUp: (value: boolean) => void
  setShowResendVerification: (value: boolean) => void
  setAuthContext: (value: 'default' | 'practitioner') => void
}) {
  const searchParams = useSearchParams()

  useEffect(() => {
    const errorParam = searchParams.get('error')
    const messageParam = searchParams.get('message')
    const planParam = searchParams.get('plan')
    const modeParam = searchParams.get('mode')
    const contextParam = searchParams.get('context')
    const nextParam = searchParams.get('next')

    // If plan parameter exists, show signup form by default
    if (planParam) {
      setIsSignUp(true)
    }

    // If explicitly requested, show signup form by default
    if (modeParam === 'signup') {
      setIsSignUp(true)
    }

    if (contextParam === 'practitioner' || (nextParam && nextParam.startsWith('/practitioner'))) {
      setAuthContext('practitioner')
    }


    if (errorParam) {
      switch (errorParam) {
        case 'CredentialsSignin':
          setError('Invalid email or password. Please try again.')
          break
        case 'EMAIL_NOT_VERIFIED':
          setError('Please verify your email before signing in. Check your inbox or resend the verification email.')
          setShowResendVerification(true)
          break
        case 'OAuthSignin':
          setError('Error signing in with Google. Please try again.')
          break
        case 'OAuthCallback':
          setError('Error during authentication. Please try again.')
          break
        default:
          setError('An error occurred during sign in. Please try again.')
      }
    }

    if (messageParam) {
      switch (messageParam) {
        case 'signout':
          setMessage('You have been signed out successfully.')
          break
        case 'reset_success':
          setMessage('Your password has been updated. Please sign in.')
          break
        case 'verified':
          setMessage('Your email is verified. Please sign in.')
          setIsSignUp(false)
          break
        default:
          setMessage('Status updated.')
      }
    }
  }, [searchParams, setError, setMessage, setIsSignUp, setShowResendVerification, setAuthContext])

  return null
}

type InstallPlatform = 'ios' | 'android' | 'other'

interface BeforeInstallPromptEvent extends Event {
  prompt: () => Promise<void>
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed'; platform: string }>
}

const getInstallPlatform = (): InstallPlatform => {
  if (typeof window === 'undefined') return 'other'
  const ua = window.navigator.userAgent || ''
  if (/android/i.test(ua)) return 'android'
  if (/iphone|ipad|ipod/i.test(ua)) return 'ios'
  return 'other'
}

const isIOSSafari = () => {
  if (typeof window === 'undefined') return false
  const ua = window.navigator.userAgent || ''
  const isIOS = /iphone|ipad|ipod/i.test(ua)
  const isSafari = /safari/i.test(ua) && !/crios|fxios|edgios|opios|duckduckgo/i.test(ua)
  return isIOS && isSafari
}

const isStandaloneMode = () => {
  if (typeof window === 'undefined') return false
  return window.matchMedia('(display-mode: standalone)').matches || (window.navigator as any).standalone === true
}

const getInstallContext = () => {
  const platform = getInstallPlatform()
  const standalone = isStandaloneMode()
  return {
    platform,
    standalone,
    eligible: platform !== 'other' && !standalone,
  }
}

const sanitizeNextTarget = (value: string | null) => {
  if (!value) return null
  const trimmed = value.trim()
  if (!trimmed.startsWith('/')) return null
  if (trimmed.startsWith('//')) return null
  return trimmed
}

const withQueryParam = (value: string, key: string, val: string) => {
  if (!value) return value
  try {
    const base = typeof window !== 'undefined' ? window.location.origin : 'https://helfi.ai'
    const url = new URL(value, base)
    url.searchParams.set(key, val)
    return url.pathname + url.search + url.hash
  } catch {
    return value
  }
}

export default function SignIn() {
  const router = useRouter()
  const { status, data: session } = useSession()
  const [loading, setLoading] = useState(false)
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [isSignUp, setIsSignUp] = useState(false)
  const [error, setError] = useState('')
  const [message, setMessage] = useState('')
  const [showPassword, setShowPassword] = useState(false)
  const [rememberMe, setRememberMe] = useState(true)
  const [showResendVerification, setShowResendVerification] = useState(false)
  const [installPromptVisible, setInstallPromptVisible] = useState(false)
  const [installTarget, setInstallTarget] = useState('/onboarding')
  const [installPlatform, setInstallPlatform] = useState<InstallPlatform>('other')
  const [deferredPrompt, setDeferredPrompt] = useState<BeforeInstallPromptEvent | null>(null)
  const [installOutcome, setInstallOutcome] = useState<'accepted' | 'dismissed' | null>(null)
  const [isSafariIOS, setIsSafariIOS] = useState(false)
  const skipAutoRedirectRef = useRef(false)
  const [authContext, setAuthContext] = useState<'default' | 'practitioner'>('default')
  const backFallbackHref =
    status === 'authenticated' && !session?.user?.isPractitioner
      ? '/dashboard'
      : authContext === 'practitioner'
        ? '/list-your-practice/start'
        : '/'

  // If the user is already logged in and somehow lands on the sign-in page
  // (for example, via the iOS Home Screen icon), immediately send them into
  // the main app instead of making them log in again. Respect Health Setup:
  // - If Health Setup is incomplete, always go to /onboarding (existing behaviour).
  // - If complete, resume last in-app page when possible, otherwise go to dashboard.
  // - If plan parameter exists, redirect to checkout after auth.
  useEffect(() => {
    if (status !== 'authenticated') return
    if (skipAutoRedirectRef.current) return
    if (installPromptVisible) return
    if (typeof window === 'undefined') {
      router.replace('/dashboard')
      return
    }
    const searchParams = new URLSearchParams(window.location.search)
    if (searchParams.get('reauth') === '1') {
      return
    }

    const resume = async () => {
      const nextParam = sanitizeNextTarget(searchParams.get('next'))
      const contextParam = searchParams.get('context')
      const practitionerIntent =
        contextParam === 'practitioner' || (nextParam && nextParam.startsWith('/practitioner')) || authContext === 'practitioner'

      if (session?.user?.isPractitioner) {
        if (maybeShowInstallPrompt('/practitioner')) {
          return
        }
        router.replace('/practitioner')
        return
      }

      if (practitionerIntent) {
        // Hard lock: normal signed-in users must re-auth for practitioner flow.
        skipAutoRedirectRef.current = true
        try {
          await signOut({ redirect: false })
        } catch (error) {
          console.warn('Session clear failed for practitioner auth flow', error)
        } finally {
          skipAutoRedirectRef.current = false
        }
        return
      }

      // Check for plan parameter - first from URL, then from sessionStorage (for post-verification flow)
      let planParam = searchParams.get('plan')

      // If no plan in URL, check sessionStorage (stored during signup)
      if (!planParam) {
        try {
          planParam = sessionStorage.getItem('helfi:signupPlan')
          if (planParam) {
            // Clear it after retrieving
            sessionStorage.removeItem('helfi:signupPlan')
          }
        } catch {}
      }

      if (planParam) {
        // User came from homepage with a plan selected - redirect to checkout
        try {
          const res = await fetch('/api/billing/create-checkout-session', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ plan: planParam }),
          })
          if (res.ok) {
            const { url } = await res.json()
            if (url) {
              window.location.href = url
              return
            }
          }
        } catch (error) {
          console.error('Checkout redirect error:', error)
          // Fall through to normal redirect
        }
      }

      const isPractitionerFlow =
        contextParam === 'practitioner' || (nextParam && nextParam.startsWith('/practitioner'))

      if (nextParam && isPractitionerFlow) {
        if (maybeShowInstallPrompt(nextParam)) {
          return
        }
        router.replace(nextParam)
        return
      }

      // First, check Health Setup status without changing its existing rules.
      try {
        const res = await fetch('/api/health-setup-status', { method: 'GET' })
        if (res.ok) {
          const data = await res.json()
          const complete = !!data.complete
          if (!complete) {
            // Before onboarding starts, optionally encourage linking Apple login
            // (prevents accidental "second account" issues later).
            const shouldSkipAppleLinkPrompt = () => {
              try {
                if (localStorage.getItem('helfi:skipAppleLinkPrompt') === '1') return true
                const untilRaw = localStorage.getItem('helfi:skipAppleLinkPromptUntil')
                if (untilRaw) {
                  const until = Number(untilRaw)
                  if (Number.isFinite(until) && until > Date.now()) return true
                }
              } catch {
                // Ignore storage errors
              }
              return false
            }

            // IMPORTANT: don't rely on component state (appleEnabled) here, because it can still be loading.
            // Instead, check providers + link status directly to avoid race conditions.
            if (!shouldSkipAppleLinkPrompt()) {
              let hasAppleProvider = false
              try {
                const providers = await getProviders()
                hasAppleProvider = Boolean((providers as any)?.apple)
              } catch {
                hasAppleProvider = false
              }

              if (hasAppleProvider) {
                try {
                  const linkRes = await fetch('/api/auth/apple/link/status', { method: 'GET' })
                  if (linkRes.ok) {
                    const linkData = await linkRes.json()
                    const linked = Boolean(linkData?.linked)
                    if (!linked) {
                      router.replace('/auth/link-apple?next=/onboarding')
                      return
                    }
                  }
                } catch {
                  // If link check fails, don't block onboarding.
                }
              }
            }

            router.replace('/onboarding')
            return
          }
        }
      } catch {
        // If this fails, fall back to normal behaviour below.
      }

      // Health Setup complete: try to restore last in-app path.
      let target = '/dashboard'
      try {
        const lastPath = localStorage.getItem('helfi:lastPath')
        if (lastPath && !lastPath.startsWith('/auth') && lastPath !== '/' && !lastPath.startsWith('/healthapp')) {
          target = lastPath
        }
      } catch {
        // Ignore storage errors and use default target.
      }
      if (maybeShowInstallPrompt(target)) {
        return
      }
      router.replace(target)
    }

    void resume()
  }, [status, router, installPromptVisible, session, authContext])

  useEffect(() => {
    if (typeof window === 'undefined') return
    setInstallPlatform(getInstallPlatform())
    setIsSafariIOS(isIOSSafari())

    const handleBeforeInstallPrompt = (event: Event) => {
      event.preventDefault()
      setDeferredPrompt(event as BeforeInstallPromptEvent)
    }

    const handleAppInstalled = () => {
      setInstallOutcome('accepted')
      try {
        localStorage.setItem('helfi:pwaInstalled', '1')
      } catch {}
    }

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt)
    window.addEventListener('appinstalled', handleAppInstalled)

    return () => {
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt)
      window.removeEventListener('appinstalled', handleAppInstalled)
    }
  }, [])

  const maybeShowInstallPrompt = (target: string) => {
    if (typeof window === 'undefined') return false
    if (installPromptVisible) return true

    const { platform, eligible } = getInstallContext()
    if (!eligible) return false

    try {
      if (localStorage.getItem('helfi:pwaInstallPromptSeen') === '1') {
        return false
      }
    } catch {
      // Ignore storage errors
    }

    try {
      localStorage.setItem('helfi:pwaInstallPromptSeen', '1')
    } catch {
      // Ignore storage errors
    }

    setInstallPlatform(platform)
    setInstallTarget(target)
    setInstallPromptVisible(true)
    return true
  }

  const handleContinueToApp = () => {
    setInstallPromptVisible(false)
    try {
      localStorage.setItem('helfi:pwaInstallPromptSeen', '1')
    } catch {
      // Ignore storage errors
    }
    window.location.href = installTarget
  }

  const handleInstallClick = async () => {
    if (!deferredPrompt) return
    try {
      await deferredPrompt.prompt()
      const choice = await deferredPrompt.userChoice
      setInstallOutcome(choice.outcome === 'accepted' ? 'accepted' : 'dismissed')
    } catch {
      setInstallOutcome('dismissed')
    }
  }

  useEffect(() => {
    try {
      const storedRemember = localStorage.getItem('helfi:rememberMe')
      const storedEmail = localStorage.getItem('helfi:rememberEmail')
      if (storedRemember === null) {
        // Default to remembered on first load so PWA sessions don't evaporate
        localStorage.setItem('helfi:rememberMe', '1')
      } else {
        setRememberMe(storedRemember === '1')
      }
      if (storedEmail) {
        setEmail(storedEmail)
      }
    } catch (storageError) {
      console.warn('Remember me restore failed', storageError)
    }
  }, [])

  const handleGoogleAuth = async () => {
    setLoading(true)
    // Check for plan parameter to preserve it through OAuth flow
    const searchParams = new URLSearchParams(window.location.search)
    const planParam = searchParams.get('plan')
    const nextParam = sanitizeNextTarget(searchParams.get('next'))
    const fallbackTarget = authContext === 'practitioner' ? '/practitioner?practitionerSignup=1' : '/onboarding'
    const nextTarget = authContext === 'practitioner' && (nextParam === '/practitioner' || nextParam?.startsWith('/practitioner'))
      ? withQueryParam(nextParam, 'practitionerSignup', '1')
      : nextParam
    const callbackUrl = planParam
      ? `/auth/signin?plan=${encodeURIComponent(planParam)}`
      : nextTarget || fallbackTarget
    if (authContext === 'practitioner') {
      try {
        sessionStorage.setItem('helfi:practitionerSignup', '1')
      } catch {}
    }
    await signIn('google', { callbackUrl })
  }

  const persistRememberState = (remember: boolean, emailValue: string) => {
    try {
      if (remember && emailValue) {
        localStorage.setItem('helfi:rememberMe', '1')
        localStorage.setItem('helfi:rememberEmail', emailValue.toLowerCase())
        localStorage.removeItem('helfi:lastManualSignOut')
      } else {
        localStorage.removeItem('helfi:rememberMe')
        localStorage.removeItem('helfi:rememberEmail')
      }
    } catch (storageError) {
      console.warn('Remember me storage failed', storageError)
    }
  }

  const handleEmailAuth = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!email || !password) return

    const normalizedEmail = email.trim().toLowerCase()

    setLoading(true)
    setError('')
    setMessage('')
    setShowResendVerification(false)

    if (isSignUp) {
      // Handle signup via direct API (no NextAuth flash)
      try {
        const signupPayload: Record<string, string> = { email, password }
        if (authContext === 'practitioner') {
          signupPayload.accountType = 'practitioner'
        }
        const response = await fetch('/api/auth/signup', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(signupPayload),
        })

        const data = await response.json()

        if (!response.ok) {
          setError(data.error || 'Failed to create account. Please try again.')
        } else {
          // Success - check for plan parameter to preserve it
          const searchParams = new URLSearchParams(window.location.search)
          const planParam = searchParams.get('plan')
          const nextParam = sanitizeNextTarget(searchParams.get('next'))
          if (nextParam) {
            try {
              sessionStorage.setItem('helfi:postAuthTarget', nextParam)
            } catch {}
          }
          if (planParam) {
            // Store plan in sessionStorage to retrieve after email verification
            try {
              sessionStorage.setItem('helfi:signupPlan', planParam)
            } catch {}
          }
          // Redirect to check email page
          window.location.href = `/auth/check-email?email=${encodeURIComponent(email)}`
        }
      } catch (error) {
        console.error('Signup error:', error)
        setError('Failed to create account. Please try again.')
      }
    } else {
      // Handle signin via NextAuth credentials
      try {
        skipAutoRedirectRef.current = true
        // Check for plan parameter to preserve it through auth flow
        const searchParams = new URLSearchParams(window.location.search)
        const planParam = searchParams.get('plan')
        const nextParam = sanitizeNextTarget(searchParams.get('next'))
        const callbackUrl = planParam
          ? `/auth/signin?plan=${encodeURIComponent(planParam)}`
          : nextParam || '/onboarding'

        const res = await signIn('credentials', {
          email: normalizedEmail,
          password,
          callbackUrl,
          redirect: false,
        })
        if (res?.ok) {
          persistRememberState(rememberMe, normalizedEmail)
          setLoading(false)
          // Check for plan parameter - first from URL, then from sessionStorage
          let planParamToUse = planParam
          if (!planParamToUse) {
            try {
              planParamToUse = sessionStorage.getItem('helfi:signupPlan')
              if (planParamToUse) {
                sessionStorage.removeItem('helfi:signupPlan')
              }
            } catch {}
          }

          // Redirect to checkout if plan parameter exists
          if (planParamToUse) {
            try {
              const checkoutRes = await fetch('/api/billing/create-checkout-session', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ plan: planParamToUse }),
              })
              if (checkoutRes.ok) {
                const { url } = await checkoutRes.json()
                if (url) {
                  window.location.href = url
                  return
                }
              }
            } catch (error) {
              console.error('Checkout redirect error:', error)
            }
          }
          let nextTarget = nextParam || '/onboarding'
          if (!nextParam && authContext === 'practitioner') {
            nextTarget = '/practitioner?practitionerSignup=1'
          }
          if (authContext === 'practitioner' && nextTarget.startsWith('/practitioner')) {
            nextTarget = withQueryParam(nextTarget, 'practitionerSignup', '1')
          }
          if (!nextParam) {
            try {
              const storedTarget = sessionStorage.getItem('helfi:postAuthTarget')
              if (storedTarget) {
                sessionStorage.removeItem('helfi:postAuthTarget')
                const sanitized = sanitizeNextTarget(storedTarget)
                if (sanitized) {
                  nextTarget = sanitized
                }
              }
            } catch {}
          }
          if (maybeShowInstallPrompt(nextTarget)) {
            return
          }
          window.location.href = nextTarget
          return
        } else {
          if (res?.error === 'EMAIL_NOT_VERIFIED') {
            setError('Please verify your email before signing in. Check your inbox or resend the verification email.')
            setShowResendVerification(true)
            setLoading(false)
            skipAutoRedirectRef.current = false
            return
          }
          setError('Invalid email or password')
        }
      } catch (error) {
        console.error('Signin error:', error)
        setError('Signin failed. Please try again.')
        skipAutoRedirectRef.current = false
        return
      }
    }
    setLoading(false)
    skipAutoRedirectRef.current = false
  }

  return (
    <>
      {/* Wrap search params handler in Suspense */}
      <Suspense fallback={null}>
        <SearchParamsHandler
          setError={setError}
          setMessage={setMessage}
          setIsSignUp={setIsSignUp}
          setShowResendVerification={setShowResendVerification}
          setAuthContext={setAuthContext}
        />
      </Suspense>

      {installPromptVisible && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4">
          <div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-xl">
            <div className="flex items-start justify-between gap-4 flex-wrap">
              <div>
                <h3 className="text-xl font-semibold text-gray-900">Add Helfi to your Home Screen</h3>
                <p className="mt-1 text-sm text-gray-600">
                  It opens like an app and keeps you signed in.
                </p>
              </div>
              <button
                onClick={handleContinueToApp}
                className="text-sm text-gray-500 hover:text-gray-700"
              >
                Skip
              </button>
            </div>

            <div className="mt-5">
              {installPlatform === 'ios' && (
                <div className="space-y-3 text-sm text-gray-700">
                  <p className="font-medium text-gray-900">iPhone or iPad steps</p>
                  <ol className="space-y-2">
                    {!isSafariIOS && (
                      <li className="flex gap-3">
                        <span className="flex h-6 w-6 items-center justify-center rounded-full bg-helfi-green-light/40 text-xs font-semibold text-helfi-green">1</span>
                        <span>In Chrome, open the menu and tap Open in Safari.</span>
                      </li>
                    )}
                    <li className="flex gap-3">
                      <span className="flex h-6 w-6 items-center justify-center rounded-full bg-helfi-green-light/40 text-xs font-semibold text-helfi-green">{isSafariIOS ? '1' : '2'}</span>
                      <span>Tap the Share button in Safari.</span>
                    </li>
                    <li className="flex gap-3">
                      <span className="flex h-6 w-6 items-center justify-center rounded-full bg-helfi-green-light/40 text-xs font-semibold text-helfi-green">{isSafariIOS ? '2' : '3'}</span>
                      <span>Scroll and tap Add to Home Screen.</span>
                    </li>
                    <li className="flex gap-3">
                      <span className="flex h-6 w-6 items-center justify-center rounded-full bg-helfi-green-light/40 text-xs font-semibold text-helfi-green">{isSafariIOS ? '3' : '4'}</span>
                      <span>Tap Add. You are done.</span>
                    </li>
                  </ol>
                  {!isSafariIOS && (
                    <div className="rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-xs text-amber-700">
                      iOS installs only work from Safari.
                    </div>
                  )}
                </div>
              )}

              {installPlatform === 'android' && (
                <div className="space-y-3 text-sm text-gray-700">
                  <p className="font-medium text-gray-900">Android steps</p>
                  <ol className="space-y-2">
                    {deferredPrompt ? (
                      <>
                        <li className="flex gap-3">
                          <span className="flex h-6 w-6 items-center justify-center rounded-full bg-helfi-green-light/40 text-xs font-semibold text-helfi-green">1</span>
                          <span>Tap Install below.</span>
                        </li>
                        <li className="flex gap-3">
                          <span className="flex h-6 w-6 items-center justify-center rounded-full bg-helfi-green-light/40 text-xs font-semibold text-helfi-green">2</span>
                          <span>Confirm the install prompt.</span>
                        </li>
                        <li className="flex gap-3">
                          <span className="flex h-6 w-6 items-center justify-center rounded-full bg-helfi-green-light/40 text-xs font-semibold text-helfi-green">3</span>
                          <span>Open Helfi from your Home Screen.</span>
                        </li>
                      </>
                    ) : (
                      <>
                        <li className="flex gap-3">
                          <span className="flex h-6 w-6 items-center justify-center rounded-full bg-helfi-green-light/40 text-xs font-semibold text-helfi-green">1</span>
                          <span>Open the browser menu (three dots).</span>
                        </li>
                        <li className="flex gap-3">
                          <span className="flex h-6 w-6 items-center justify-center rounded-full bg-helfi-green-light/40 text-xs font-semibold text-helfi-green">2</span>
                          <span>Tap Install app or Add to Home Screen.</span>
                        </li>
                        <li className="flex gap-3">
                          <span className="flex h-6 w-6 items-center justify-center rounded-full bg-helfi-green-light/40 text-xs font-semibold text-helfi-green">3</span>
                          <span>Confirm the install.</span>
                        </li>
                      </>
                    )}
                  </ol>
                </div>
              )}

              {installOutcome === 'accepted' && (
                <div className="mt-4 rounded-lg border border-green-200 bg-green-50 px-3 py-2 text-sm text-green-700">
                  Installed. You can open Helfi from your Home Screen.
                </div>
              )}
              {installOutcome === 'dismissed' && (
                <div className="mt-4 rounded-lg border border-gray-200 bg-gray-50 px-3 py-2 text-sm text-gray-600">
                  No problem. You can install it anytime from your browser menu.
                </div>
              )}
            </div>

            <div className="mt-6 flex flex-col gap-3">
              {installPlatform === 'android' && deferredPrompt && (
                <button
                  onClick={handleInstallClick}
                  className="w-full rounded-lg bg-helfi-green px-4 py-3 text-white transition-colors hover:bg-helfi-green-dark"
                >
                  Install app
                </button>
              )}
              <button
                onClick={handleContinueToApp}
                className="w-full rounded-lg border border-gray-300 px-4 py-3 text-gray-700 transition-colors hover:bg-gray-50"
              >
                Continue to app
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="min-h-screen flex items-center justify-center bg-gradient-to-b from-white to-helfi-green-light/10 p-4">
        <div className="max-w-md w-full space-y-8">
          <div className="flex items-center justify-between">
            <button
              type="button"
              onClick={() => {
                if (typeof window !== 'undefined') {
                  const referrer = document.referrer || ''
                  const referrerPath = referrer ? new URL(referrer, window.location.origin).pathname : ''
                  const canSafelyGoBack = window.history.length > 1 && !referrerPath.startsWith('/auth/signin')
                  if (canSafelyGoBack) {
                    router.back()
                    return
                  }
                  window.location.href = backFallbackHref
                  return
                }
              }}
              className="inline-flex items-center justify-center px-4 py-2 rounded-full border border-emerald-200 text-emerald-800 font-semibold hover:border-emerald-300 hover:text-emerald-900 transition-colors"
            >
              ← Back
            </button>
            {status === 'authenticated' && !session?.user?.isPractitioner && (
              <Link
                href="/dashboard"
                className="inline-flex items-center justify-center px-4 py-2 rounded-full bg-helfi-green text-white font-semibold hover:bg-helfi-green/90 transition-colors"
              >
                Go to Dashboard
              </Link>
            )}
          </div>

          {/* Logo */}
          <div className="flex justify-center">
            <Link
              href={authContext === 'practitioner' ? '/list-your-practice' : '/'}
              className="relative w-24 h-24"
            >
              <Image
                src="/mobile-assets/LOGOS/helfi-01-01.png"
                alt="Helfi Logo"
                fill
                className="object-contain"
                priority
              />
            </Link>
          </div>

          {/* Sign In Form */}
          <div className="text-center">
            <h2 className="text-2xl font-bold text-helfi-black mb-4">
              {isSignUp
                ? authContext === 'practitioner'
                  ? 'Practitioner portal - create account'
                  : 'Create Account'
                : authContext === 'practitioner'
                  ? 'Practitioner portal sign in'
                  : 'Welcome to Helfi'}
            </h2>
            <p className="text-gray-600 mb-8">
              {isSignUp
                ? authContext === 'practitioner'
                  ? 'Create your practitioner account to list your practice on Helfi.'
                  : 'Create a new account to get started'
                : authContext === 'practitioner'
                  ? 'Sign in to manage your listing and boosts.'
                  : 'Sign in to your account'}
            </p>
            {authContext === 'practitioner' && (
              <div className="space-y-2 text-sm">
                <Link href="/list-your-practice" className="text-helfi-green hover:underline block">
                  Back to list your practice
                </Link>
                <div className="text-gray-600">
                  Looking for the normal Helfi app?{' '}
                  <Link href="/auth/signin" className="text-helfi-green hover:underline">
                    User log in
                  </Link>{' '}
                  or{' '}
                  <Link href="/auth/signin?mode=signup" className="text-helfi-green hover:underline">
                    create a user account
                  </Link>
                  .
                </div>
              </div>
            )}
          </div>

          <div className="space-y-4">
            {/* Google Sign In - PRESERVED UNTOUCHED */}
            <button
              onClick={handleGoogleAuth}
              disabled={loading}
              className="w-full flex items-center justify-center gap-3 bg-white border border-gray-300 text-gray-700 px-4 py-3 rounded-lg hover:bg-gray-50 transition-colors disabled:opacity-50 disabled:cursor-not-allowed font-medium"
            >
              <svg className="w-5 h-5" viewBox="0 0 24 24">
                <path
                  fill="#4285F4"
                  d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
                />
                <path
                  fill="#34A853"
                  d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
                />
                <path
                  fill="#FBBC05"
                  d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
                />
                <path
                  fill="#EA4335"
                  d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
                />
              </svg>
              Continue with Google
            </button>

            <div className="relative">
              <div className="absolute inset-0 flex items-center">
                <div className="w-full border-t border-gray-300" />
              </div>
              <div className="relative flex justify-center text-sm">
                <span className="px-2 bg-white text-gray-500">Or with email</span>
              </div>
            </div>

            {/* Email/Password Form - RESTORED FROM COMMIT 89581b3 */}
            <form onSubmit={handleEmailAuth} className="space-y-4">
              <div>
                <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-2">
                  Email address
                </label>
                <input
                  id="email"
                  name="email"
                  type="email"
                  autoComplete="email"
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full px-3 py-3 border border-gray-300 rounded-lg shadow-sm placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-helfi-green focus:border-helfi-green"
                  placeholder="Enter your email"
                />
              </div>

              <div>
                <label htmlFor="password" className="block text-sm font-medium text-gray-700 mb-2">
                  Password
                </label>
                <div className="relative">
                  <input
                    id="password"
                    name="password"
                    type={showPassword ? "text" : "password"}
                    autoComplete={isSignUp ? "new-password" : "current-password"}
                    required
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="w-full px-3 py-3 pr-12 border border-gray-300 rounded-lg shadow-sm placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-helfi-green focus:border-helfi-green"
                    placeholder="Enter your password"
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute inset-y-0 right-0 flex items-center pr-3 text-gray-400 hover:text-gray-600 transition-colors"
                  >
                    {showPassword ? (
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.878 9.878L3 3m6.878 6.878L21 21" />
                      </svg>
                    ) : (
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                      </svg>
                    )}
                  </button>
                </div>
                {!isSignUp && (
                  <div className="mt-2 text-right">
                    <Link href="/auth/forgot-password" className="text-sm text-helfi-green hover:underline">
                      Forgot password?
                    </Link>
                  </div>
                )}
              </div>

              {!isSignUp && (
                <div className="flex items-start justify-between gap-3">
                  <label className="inline-flex items-center gap-2 text-sm text-gray-700 select-none">
                    <input
                      type="checkbox"
                      checked={rememberMe}
                      onChange={(e) => setRememberMe(e.target.checked)}
                      className="h-4 w-4 rounded border-gray-300 text-helfi-green focus:ring-helfi-green"
                    />
                    Keep me signed in
                  </label>
                  <span className="text-xs text-gray-500 leading-5">
                    If unchecked, you stay signed in for at least 24 hours.
                  </span>
                </div>
              )}

              {error && (
                <div className="text-red-600 text-sm">{error}</div>
              )}
              {showResendVerification && (
                <button
                  type="button"
                  onClick={async () => {
                    try {
                      const res = await fetch('/api/auth/resend-verification', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ email: email.trim().toLowerCase() }),
                      })
                      const data = await res.json().catch(() => ({}))
                      if (!res.ok) {
                        setError(data?.error || 'Failed to resend verification email.')
                        return
                      }
                      setMessage('Verification email sent. Please check your inbox.')
                      setShowResendVerification(false)
                    } catch {
                      setError('Failed to resend verification email. Please try again.')
                    }
                  }}
                  className="text-sm text-helfi-green hover:underline"
                >
                  Resend verification email
                </button>
              )}

              {message && (
                <div className="text-green-600 text-sm">{message}</div>
              )}

              <button
                type="submit"
                disabled={loading || !email || !password}
                className="w-full bg-helfi-green text-white px-4 py-3 rounded-lg hover:bg-helfi-green-dark transition-colors disabled:opacity-50 disabled:cursor-not-allowed font-medium"
              >
                {loading ? 'Please wait...' : isSignUp ? 'Create Account' : 'Sign In'}
              </button>
            </form>

            {/* Sign Up / Sign In Toggle - RESTORED */}
            <div className="text-center">
              <button
                onClick={() => setIsSignUp(!isSignUp)}
                className="text-helfi-green hover:underline text-sm"
              >
                {isSignUp
                  ? 'Already have an account? Sign in'
                  : authContext === 'practitioner'
                    ? 'New here? Create your practitioner account'
                    : "Don't have an account? Sign up"}
              </button>
            </div>
          </div>

          <div className="mt-6 text-center text-sm text-gray-600">
            <p>
              By continuing, you agree to our{' '}
              <Link href="/terms" className="text-helfi-green hover:underline">
                Terms of Service
              </Link>{' '}
              and{' '}
              <Link href="/privacy" className="text-helfi-green hover:underline">
                Privacy Policy
              </Link>
            </p>
          </div>
        </div>
      </div>
    </>
  )
}

'use client'
import { Cog6ToothIcon } from '@heroicons/react/24/outline'

import React, { useState, useEffect } from 'react'
import { useSession, signOut } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import Image from 'next/image'
import Link from 'next/link'
import MobileMoreMenu from '@/components/MobileMoreMenu'
import UsageMeter from '@/components/UsageMeter'
import PageHeader from '@/components/PageHeader'
import ConfirmationModal from '@/components/ConfirmationModal'
import MessageModal from '@/components/MessageModal'
import { creditCostDisplayList, usageDisplayList } from '@/data/creditCosts'

export default function BillingPage() {
  const { data: session } = useSession()
  const [loading, setLoading] = useState(true)
  const [currentPlan, setCurrentPlan] = useState('free')
  const [dropdownOpen, setDropdownOpen] = useState(false)
  const router = useRouter()
  const [profileImage, setProfileImage] = useState<string>('')
  const [subscription, setSubscription] = useState<any>(null)
  const [hasActiveSubscription, setHasActiveSubscription] = useState(false)
  const [isManagingSubscription, setIsManagingSubscription] = useState(false)
  const [isCreatingPortalSession, setIsCreatingPortalSession] = useState(false)

  // Modal states
  const [showCancelConfirm, setShowCancelConfirm] = useState(false)
  const [showMessageModal, setShowMessageModal] = useState(false)
  const [messageModalContent, setMessageModalContent] = useState<{ title: string; message: string; type?: 'success' | 'error' | 'info' }>({ title: '', message: '' })

  // Stripe checkout
  const [isCreatingCheckout, setIsCreatingCheckout] = useState<string | null>(null)

  // Usage stats (real usage history)
  const [usageRange, setUsageRange] = useState<'7d' | '1m' | '2m' | '6m' | 'all' | 'custom'>('7d')
  const [usageStart, setUsageStart] = useState<string>('')
  const [usageEnd, setUsageEnd] = useState<string>('')
  const [usageStats, setUsageStats] = useState<Record<string, number> | null>(null)
  const [usageStatsLoading, setUsageStatsLoading] = useState(false)
  const [usageStatsError, setUsageStatsError] = useState<string | null>(null)

  const toDateInputValue = (d: Date) => {
    const yyyy = d.getFullYear()
    const mm = String(d.getMonth() + 1).padStart(2, '0')
    const dd = String(d.getDate()).padStart(2, '0')
    return `${yyyy}-${mm}-${dd}`
  }
  const startCheckout = async (plan: string, quantity: number = 1) => {
    try {
      setIsCreatingCheckout(plan)
      const res = await fetch('/api/billing/create-checkout-session', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ plan, quantity }),
      })
      if (!res.ok) {
        const data = await res.json().catch(() => ({}))
        // Show user-friendly error message
        const errorMessage = data?.message || data?.error || 'Checkout error'
        setMessageModalContent({
          title: 'Checkout Error',
          message: errorMessage,
          type: 'error'
        })
        setShowMessageModal(true)
        return
      }
      const { url } = await res.json()
      if (url) {
        window.location.href = url
      } else {
        throw new Error('No checkout URL returned')
      }
    } catch (e: any) {
      setMessageModalContent({
        title: 'Error',
        message: e?.message || 'Failed to start checkout',
        type: 'error'
      })
      setShowMessageModal(true)
    } finally {
      setIsCreatingCheckout(null)
    }
  }

  // Load real usage stats for Billing
  useEffect(() => {
    if (!session?.user) return

    const load = async () => {
      setUsageStatsLoading(true)
      setUsageStatsError(null)
      try {
        const params = new URLSearchParams()
        params.set('range', usageRange)
        if (usageRange === 'custom') {
          if (usageStart) params.set('start', usageStart)
          if (usageEnd) params.set('end', usageEnd)
        }
        const res = await fetch(`/api/credit/feature-usage-stats?${params.toString()}`, { cache: 'no-store' })
        if (!res.ok) {
          const data = await res.json().catch(() => ({}))
          throw new Error(data?.error || 'Could not load usage stats')
        }
        const data = await res.json()
        setUsageStats(data?.usage || null)
      } catch (e: any) {
        setUsageStats(null)
        setUsageStatsError(e?.message || 'Could not load usage stats')
      } finally {
        setUsageStatsLoading(false)
      }
    }

    // If user picks custom but dates are empty, set a sensible default (last 7 days).
    if (usageRange === 'custom' && (!usageStart || !usageEnd)) {
      const now = new Date()
      const start = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000)
      const startValue = usageStart || toDateInputValue(start)
      const endValue = usageEnd || toDateInputValue(now)
      if (!usageStart) setUsageStart(startValue)
      if (!usageEnd) setUsageEnd(endValue)
      // Wait for state updates, then the effect will re-run and load.
      return
    }

    load()
  }, [session, usageRange, usageStart, usageEnd])

  // Close dropdown on outside click
  useEffect(() => {
    function handleClick(e: MouseEvent) {
      const target = e.target as HTMLElement;
      // Check if click is outside both the button and the dropdown content
      if (!target.closest('.dropdown-container')) {
        setDropdownOpen(false);
      }
    }
    if (dropdownOpen) {
      document.addEventListener('mousedown', handleClick);
      return () => document.removeEventListener('mousedown', handleClick);
    }
  }, [dropdownOpen]);

  // Load profile image from database
  useEffect(() => {
    const loadProfileImage = async () => {
      try {
        const response = await fetch('/api/user-data');
        if (response.ok) {
          const result = await response.json();
          if (result.data && result.data.profileImage) {
            setProfileImage(result.data.profileImage);
          }
        }
      } catch (error) {
        console.error('Error loading profile image:', error);
      }
    };

    if (session) {
      loadProfileImage();
    }
  }, [session]);

  useEffect(() => {
    if (session) {
      setLoading(false)
    }
  }, [session])

  // Load subscription status
  useEffect(() => {
    const loadSubscription = async () => {
      try {
        const res = await fetch('/api/billing/subscription')
        if (res.ok) {
          const data = await res.json()
          console.log('Subscription data:', data) // Debug log
          if (data.hasSubscription && data.isActive) {
            setSubscription(data.subscription)
            setHasActiveSubscription(true)
            setCurrentPlan(data.subscription?.tier || 'free')
          } else {
            setHasActiveSubscription(false)
            setSubscription(null)
          }
        } else {
          console.error('Failed to load subscription:', res.status)
        }
      } catch (error) {
        console.error('Error loading subscription:', error)
      }
    }
    if (session) {
      loadSubscription()
    }
  }, [session])

  // If returning from Stripe, confirm top-up (no useSearchParams to keep static safe)
  useEffect(() => {
    if (typeof window === 'undefined') return
    const params = new URLSearchParams(window.location.search)
    const checkout = params.get('checkout')
    const sid = params.get('session_id')
    if (checkout === 'success' && sid) {
      fetch(`/api/billing/confirm?session_id=${encodeURIComponent(sid)}`)
        .then(() => {
          // Reload subscription after successful checkout
          fetch('/api/billing/subscription')
            .then(res => res.json())
            .then(data => {
              if (data.hasSubscription && data.isActive) {
                setSubscription(data.subscription)
                setCurrentPlan(data.subscription.tier)
              }
            })
            .catch(() => {})
          // Turn on weekly reports after a successful purchase
          fetch('/api/reports/weekly/preferences', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ enabled: true }),
          }).catch(() => {})
        })
        .catch(() => {})
    }
  }, [])

  // Handle subscription management
  const handleCancelSubscription = async () => {
    setShowCancelConfirm(true)
  }

  const confirmCancelSubscription = async () => {
    setShowCancelConfirm(false)
    setIsManagingSubscription(true)
    try {
      const res = await fetch('/api/billing/subscription', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'cancel' }),
      })

      if (res.ok) {
        const data = await res.json()

        // Format the cancellation date message
        let message = data.message || 'Subscription canceled successfully'
        if (data.cancellationDate) {
          const cancelDate = new Date(data.cancellationDate)
          const formattedDate = cancelDate.toLocaleDateString('en-US', { 
            weekday: 'long', 
            year: 'numeric', 
            month: 'long', 
            day: 'numeric' 
          })
          message = `Your subscription will remain active until ${formattedDate}. After that date, your subscription will be canceled and you'll lose access to premium features.`
        }

        setMessageModalContent({
          title: 'Subscription Canceled',
          message,
          type: 'success'
        })
        setShowMessageModal(true)

        // Reload subscription status
        const subRes = await fetch('/api/billing/subscription')
        if (subRes.ok) {
          const subData = await subRes.json()
          if (subData.hasSubscription && subData.isActive) {
            setSubscription(subData.subscription)
            setHasActiveSubscription(true)
          } else {
            setHasActiveSubscription(false)
            setSubscription(null)
          }
        }
      } else {
        const error = await res.json().catch(() => ({}))
        setMessageModalContent({
          title: 'Error',
          message: error.message || error.error || error.details?.message || 'Failed to cancel subscription',
          type: 'error'
        })
        setShowMessageModal(true)
      }
    } catch (error: any) {
      console.error('Cancel subscription error:', error)
      setMessageModalContent({
        title: 'Error',
        message: error?.message || 'Failed to cancel subscription',
        type: 'error'
      })
      setShowMessageModal(true)
    } finally {
      setIsManagingSubscription(false)
    }
  }

  const handleChangePlan = async (newPlan: string, action: 'upgrade' | 'downgrade') => {
    setIsManagingSubscription(true)
    try {
      const res = await fetch('/api/billing/subscription', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action, newPlan }),
      })

      if (res.ok) {
        const data = await res.json()
        setMessageModalContent({
          title: 'Success',
          message: data.message || `Subscription ${action === 'upgrade' ? 'upgraded' : 'downgraded'} successfully`,
          type: 'success'
        })
        setShowMessageModal(true)
        // Reload subscription status
        const subRes = await fetch('/api/billing/subscription')
        if (subRes.ok) {
          const subData = await subRes.json()
          if (subData.hasSubscription && subData.isActive) {
            setSubscription(subData.subscription)
            setHasActiveSubscription(true)
            setCurrentPlan(subData.subscription.tier)
          } else {
            setHasActiveSubscription(false)
            setSubscription(null)
          }
        }
      } else {
        const error = await res.json().catch(() => ({}))
        setMessageModalContent({
          title: 'Error',
          message: error.message || error.error || error.details?.message || `Failed to ${action} subscription`,
          type: 'error'
        })
        setShowMessageModal(true)
      }
    } catch (error: any) {
      console.error(`${action} subscription error:`, error)
      setMessageModalContent({
        title: 'Error',
        message: error?.message || `Failed to ${action} subscription`,
        type: 'error'
      })
      setShowMessageModal(true)
    } finally {
      setIsManagingSubscription(false)
    }
  }

  const handleManagePortal = async () => {
    setIsCreatingPortalSession(true)
    try {
      const res = await fetch('/api/billing/portal', { method: 'POST' })
      if (!res.ok) {
        const data = await res.json().catch(() => ({}))
        // Show the actual error message from the API
        const errorMessage = data?.message || data?.error || 'Could not open subscription management. Please try again.'
        setMessageModalContent({
          title: 'Error',
          message: errorMessage,
          type: 'error'
        })
        setShowMessageModal(true)
        return
      }
      const data = await res.json()
      if (data?.url) {
        window.location.href = data.url
      } else {
        setMessageModalContent({
          title: 'Error',
          message: 'Could not open subscription management. Please try again.',
          type: 'error'
        })
        setShowMessageModal(true)
      }
    } catch (err: any) {
      console.error('Portal error:', err)
      setMessageModalContent({
        title: 'Error',
        message: err?.message || 'Could not open subscription management. Please try again.',
        type: 'error'
      })
      setShowMessageModal(true)
    } finally {
      setIsCreatingPortalSession(false)
    }
  }

  const handleSignOut = async () => {
    // Clear user-specific localStorage before signing out
    if (session?.user?.id) {
      localStorage.removeItem(`profileImage_${session.user.id}`);
      localStorage.removeItem(`cachedProfileImage_${session.user.id}`);
    }
    await signOut({ callbackUrl: '/auth/signin' })
  }

  return (
    <div className="min-h-screen bg-gray-50 pb-[calc(7rem+env(safe-area-inset-bottom))]">
      <PageHeader title="Subscription & Billing" />

      {/* Main Content */}
      <div className="max-w-6xl mx-auto px-6 py-8 pb-8">
        {/* Current Subscription */}
        {hasActiveSubscription && subscription && (
          <div className="bg-white rounded-lg shadow-sm p-6 mb-8 border-2 border-green-500">
            <div className="flex items-center justify-between mb-4">
              <div>
                <h2 className="text-2xl font-bold text-gray-900">Current Subscription</h2>
                <p className="text-gray-600 mt-1">
                  {subscription.tier} 
                  {subscription.credits > 0 && ` - ${subscription.credits.toLocaleString()} credits/month`}
                </p>
              </div>
              <div className="text-right">
                <div className="text-sm text-gray-500">Status</div>
                <div className="text-lg font-semibold text-green-600">Active</div>
              </div>
            </div>

            {subscription.stripeCurrentPeriodEnd && (
              <div className="mb-4 text-sm text-gray-600">
                Next billing date: {new Date(subscription.stripeCurrentPeriodEnd).toLocaleDateString()}
              </div>
            )}

            {subscription.stripeCancelAtPeriodEnd && (
              <div className="mb-4 p-3 bg-yellow-50 border border-yellow-200 rounded-lg text-sm text-yellow-800">
                ⚠️ Your subscription will be canceled at the end of the current billing period.
              </div>
            )}

            <div className="flex flex-wrap gap-3">
              <button
                onClick={handleManagePortal}
                disabled={isCreatingPortalSession}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {isCreatingPortalSession ? 'Opening portal…' : 'Manage subscription'}
              </button>

              {!subscription.stripeCancelAtPeriodEnd && (
                <button
                  onClick={handleCancelSubscription}
                  disabled={isManagingSubscription}
                  className="px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {isManagingSubscription ? 'Processing...' : 'Cancel Subscription'}
                </button>
              )}

              {/* Upgrade/Downgrade options */}
              {(!subscription.monthlyPriceCents || subscription.monthlyPriceCents !== 1000) && (
                <button
                  onClick={() => handleChangePlan('plan_10_monthly', (subscription.monthlyPriceCents || 0) > 1000 ? 'downgrade' : 'upgrade')}
                  disabled={isManagingSubscription}
                  className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {(subscription.monthlyPriceCents || 0) > 1000 ? 'Downgrade to $10/month' : 'Switch to $10/month'}
                </button>
              )}

              {(!subscription.monthlyPriceCents || subscription.monthlyPriceCents !== 2000) && (
                <button
                  onClick={() => handleChangePlan('plan_20_monthly', (subscription.monthlyPriceCents || 0) > 2000 ? 'downgrade' : 'upgrade')}
                  disabled={isManagingSubscription}
                  className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {(subscription.monthlyPriceCents || 0) > 2000 ? 'Downgrade to $20/month' : 'Switch to $20/month'}
                </button>
              )}

              {(!subscription.monthlyPriceCents || subscription.monthlyPriceCents !== 3000) && (
                <button
                  onClick={() => handleChangePlan('plan_30_monthly', (subscription.monthlyPriceCents || 0) > 3000 ? 'downgrade' : 'upgrade')}
                  disabled={isManagingSubscription}
                  className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {(subscription.monthlyPriceCents || 0) > 3000 ? 'Downgrade to $30/month' : 'Switch to $30/month'}
                </button>
              )}

              {(!subscription.monthlyPriceCents || subscription.monthlyPriceCents !== 5000) && (
                <button
                  onClick={() => handleChangePlan('plan_50_monthly', (subscription.monthlyPriceCents || 0) > 5000 ? 'downgrade' : 'upgrade')}
                  disabled={isManagingSubscription}
                  className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {(subscription.monthlyPriceCents || 0) > 5000 ? 'Downgrade to $50/month' : 'Switch to $50/month'}
                </button>
              )}
            </div>
          </div>
        )}

        {/* Available Plans */}
        <div className="bg-white rounded-lg shadow-sm p-6 mb-8">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-2xl font-bold text-gray-900">Plans</h2>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
            {/* $10 plan */}
            <div className="border border-gray-200 rounded-2xl p-8 shadow-sm hover:shadow-md transition-shadow bg-white">
              <h3 className="text-lg font-semibold text-gray-900 mb-2">$10 / month</h3>
              <p className="text-3xl font-bold text-gray-900 mb-1">Monthly wallet: 700 credits</p>
              <p className="text-xs text-gray-500 mb-4">Credits refresh monthly. No rollover.</p>
              <ul className="space-y-2 mb-6 text-sm text-gray-600">
                <li className="flex items-center"><span className="w-4 h-4 text-green-500 mr-2">✓</span> All features unlocked</li>
                <li className="flex items-center"><span className="w-4 h-4 text-green-500 mr-2">✓</span> Percentage‑based usage meter</li>
                <li className="flex items-center"><span className="w-4 h-4 text-green-500 mr-2">✓</span> Top‑ups valid 12 months</li>
              </ul>
              <button
                onClick={() => startCheckout('plan_10_monthly')}
                disabled={isCreatingCheckout === 'plan_10_monthly'}
                className="w-full bg-helfi-green text-white px-4 py-2 rounded-lg hover:bg-helfi-green/90 transition-colors disabled:opacity-60"
              >
                {isCreatingCheckout === 'plan_10_monthly' ? 'Redirecting…' : 'Choose $10 Plan'}
              </button>
            </div>

            {/* $20 plan */}
            <div className="border border-gray-200 rounded-2xl p-8 shadow-sm hover:shadow-md transition-shadow bg-white">
              <h3 className="text-lg font-semibold text-gray-900 mb-2">$20 / month</h3>
              <p className="text-3xl font-bold text-gray-900 mb-1">Monthly wallet: 1,400 credits</p>
              <p className="text-xs text-gray-500 mb-4">Credits refresh monthly. No rollover.</p>
              <ul className="space-y-2 mb-6 text-sm text-gray-600">
                <li className="flex items-center"><span className="w-4 h-4 text-green-500 mr-2">✓</span> All features unlocked</li>
                <li className="flex items-center"><span className="w-4 h-4 text-green-500 mr-2">✓</span> Percentage‑based usage meter</li>
                <li className="flex items-center"><span className="w-4 h-4 text-green-500 mr-2">✓</span> Top‑ups valid 12 months</li>
              </ul>
              <button
                onClick={() => startCheckout('plan_20_monthly')}
                disabled={isCreatingCheckout === 'plan_20_monthly'}
                className="w-full bg-helfi-green text-white px-4 py-2 rounded-lg hover:bg-helfi-green/90 transition-colors disabled:opacity-60"
              >
                {isCreatingCheckout === 'plan_20_monthly' ? 'Redirecting…' : 'Choose $20 Plan'}
              </button>
            </div>

