'use client'

import { Suspense, useEffect, useState } from 'react'
import VoiceChat from '@/components/VoiceChat'
import { useRouter, useSearchParams } from 'next/navigation'

function ChatPageContent() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const isFood = searchParams.get('context') === 'food'
  const openHistory = searchParams.get('history') === '1'
  const selectedDate = searchParams.get('date') || ''
  const voicePrompt = searchParams.get('voicePrompt') || ''
  const voicePromptToken = searchParams.get('voicePromptToken') || ''
  const [privateVoicePrompt, setPrivateVoicePrompt] = useState('')
  const entryContext = isFood ? 'food' : 'general'
  const handleExit = () => {
    router.push('/food')
  }

  useEffect(() => {
    let cancelled = false
    if (voicePrompt || !voicePromptToken) {
      setPrivateVoicePrompt('')
      return () => {
        cancelled = true
      }
    }

    fetch(`/api/native/voice-prompt-handoff?token=${encodeURIComponent(voicePromptToken)}`, {
      credentials: 'include',
    })
      .then(async (response) => {
        if (!response.ok) return ''
        const data = await response.json().catch(() => ({}))
        return typeof data?.prompt === 'string' ? data.prompt : ''
      })
      .then((prompt) => {
        if (!cancelled) setPrivateVoicePrompt(prompt)
      })
      .catch(() => {
        if (!cancelled) setPrivateVoicePrompt('')
      })

    return () => {
      cancelled = true
    }
  }, [voicePrompt, voicePromptToken])

  return (
    <VoiceChat
      className="flex-1"
      entryContext={entryContext}
      selectedDate={selectedDate}
      openHistoryOnLoad={openHistory}
      initialInput={voicePrompt || privateVoicePrompt}
      onExit={isFood ? handleExit : undefined}
    />
  )
}

export default function ChatPage() {
  return (
    <div className="bg-[#f6f8f7] flex flex-col flex-1 min-h-0">
      <Suspense fallback={null}>
        <ChatPageContent />
      </Suspense>
    </div>
  )
}

'use client'

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { useRouter, usePathname } from 'next/navigation'
import Link from 'next/link'
import PageHeader from '@/components/PageHeader'
import { Line } from 'react-chartjs-2'
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  TimeScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler,
} from 'chart.js'
import type { ChartData, ChartOptions, TooltipItem } from 'chart.js'
import 'chartjs-adapter-date-fns'
import { format } from 'date-fns'

ChartJS.register(
  CategoryScale,
  LinearScale,
  TimeScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler,
)

export const dynamic = 'force-dynamic'

type Row = { date: string; timestamp?: string | null; issueId: string; name: string; polarity: 'positive'|'negative'; value: number | null; note?: string }
type HistoryCache = { rows: Row[]; fetchedAt: number }

export default function CheckinHistoryPage() {
  const router = useRouter()
  const pathname = usePathname()
  const chartRef = useRef<any>(null)
  const lastTooltipKeyRef = useRef<string | null>(null)
  const [rows, setRows] = useState<Row[]>([])
  const [allIssues, setAllIssues] = useState<string[]>([])
  const [selectedIssues, setSelectedIssues] = useState<Set<string>>(new Set())
  const [start, setStart] = useState<string>('')
  const [end, setEnd] = useState<string>('')
  const [timePeriod, setTimePeriod] = useState<'daily' | 'weekly' | 'monthly' | 'yearly' | 'all' | 'custom'>('all')
  const pageSize = 10
  const [page, setPage] = useState(1)
  const [expandedRow, setExpandedRow] = useState<string | null>(null)
  const [tooltipActive, setTooltipActive] = useState(false)
  const [editingEntry, setEditingEntry] = useState<Row | null>(null)
  const [editValue, setEditValue] = useState<number | null>(null)
  const [editNote, setEditNote] = useState<string>('')
  const [loading, setLoading] = useState(false)

  const handleChartWheelCapture = useCallback((event: React.WheelEvent<HTMLDivElement>) => {
    if (typeof document === 'undefined') return
    if (Math.abs(event.deltaY) <= Math.abs(event.deltaX)) return

    const contentZone =
      document.querySelector('[data-scroll-zone="content"]') instanceof HTMLElement
        ? (document.querySelector('[data-scroll-zone="content"]') as HTMLElement)
        : null

    const scrollContainer =
      contentZone && contentZone.scrollHeight > contentZone.clientHeight + 1
        ? contentZone
        : ((document.scrollingElement as HTMLElement | null) ?? null)

    if (!scrollContainer) return

    const maxScroll = Math.max(0, scrollContainer.scrollHeight - scrollContainer.clientHeight)
    if (maxScroll <= 0) return

    const nextTop = Math.max(0, Math.min(maxScroll, scrollContainer.scrollTop + event.deltaY))
    if (nextTop === scrollContainer.scrollTop) return

    scrollContainer.scrollTop = nextTop
    event.preventDefault()
  }, [])

  const LABELS = ['Really bad', 'Bad', 'Below average', 'Average', 'Above average', 'Good', 'Excellent'] as const
  const COLOR_PALETTE = [
    'rgb(34, 197, 94)',
    'rgb(59, 130, 246)',
    'rgb(168, 85, 247)',
    'rgb(236, 72, 153)',
    'rgb(251, 146, 60)',
    'rgb(234, 179, 8)',
    'rgb(14, 165, 233)',
  ]

  const HISTORY_CACHE_TTL_MS = 5 * 60_000
  const buildHistoryCacheKey = (startValue: string, endValue: string) =>
    `checkin-history-v2:${startValue || 'all'}:${endValue || 'all'}`
  const readHistoryCache = (key: string): HistoryCache | null => {
    if (typeof window === 'undefined') return null
    try {
      const raw = window.sessionStorage.getItem(key)
      if (!raw) return null
      const parsed = JSON.parse(raw)
      if (!parsed?.rows || !Array.isArray(parsed.rows) || parsed.rows.length === 0) return null
      return parsed
    } catch {
      return null
    }
  }
  const writeHistoryCache = (key: string, history: Row[]) => {
    if (typeof window === 'undefined') return
    try {
      window.sessionStorage.setItem(key, JSON.stringify({ rows: history, fetchedAt: Date.now() }))
    } catch {
      // ignore cache write errors
    }
  }

  const getRatingLabel = (value: number | null) => {
    if (value === null || value === undefined) return 'N/A'
    const clamped = Math.max(0, Math.min(6, value))
    return LABELS[clamped]
  }

  const toRGBA = (color: string, alpha: number) =>
    color.startsWith('rgb(')
      ? color.replace('rgb(', 'rgba(').replace(')', `, ${alpha})`)
      : color

  const load = async (overrides?: { start?: string; end?: string }, options?: { force?: boolean }) => {
    setLoading(true)
    try {
      const startValue = overrides?.start ?? start
      const endValue = overrides?.end ?? end
      const cacheKey = buildHistoryCacheKey(startValue, endValue)
      if (!options?.force) {
        const cached = readHistoryCache(cacheKey)
        if (cached && Date.now() - cached.fetchedAt < HISTORY_CACHE_TTL_MS) {
          const history = cached.rows
          setRows(history)
          const issues = Array.from(new Set(history.map((r: Row) => r.name))).sort() as string[]
          setAllIssues(issues)
          if (selectedIssues.size === 0) {
            setSelectedIssues(new Set(issues))
          }
          return
        }
      }
      const params = new URLSearchParams()
      if (startValue) params.set('start', startValue)
      if (endValue) params.set('end', endValue)
      const res = await fetch(`/api/checkins/history?${params.toString()}`, { cache: 'no-store' })
      const data = await res.json()
      const history = Array.isArray(data?.history) ? data.history : []
      setRows(history)

      // Extract unique issue names
      const issues = Array.from(new Set(history.map((r: Row) => r.name))).sort() as string[]
      setAllIssues(issues)
      if (selectedIssues.size === 0) {
        setSelectedIssues(new Set(issues))
      }
      writeHistoryCache(cacheKey, history)
    } catch (e) {
      console.error('Failed to load history', e)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => { load() }, [])
  useEffect(() => {
    if (timePeriod !== 'custom' && (start || end)) {
      setStart('')
      setEnd('')
      load({ start: '', end: '' })
    }
  }, [timePeriod])

  // Filter rows by selected issues and time period
  const filteredRows = useMemo(() => {
    let filtered = rows

    // Filter by selected issues
    if (selectedIssues.size > 0 && selectedIssues.size < allIssues.length) {
      filtered = filtered.filter(r => selectedIssues.has(r.name))
    }

    // Filter by time period
    if (timePeriod !== 'all' && timePeriod !== 'custom' && filtered.length > 0) {
      const now = new Date()
      const cutoffDate = new Date()

      switch (timePeriod) {
        case 'daily':
          cutoffDate.setDate(now.getDate() - 30) // Last 30 days
          break
        case 'weekly':
          cutoffDate.setDate(now.getDate() - 84) // Last 12 weeks
          break
        case 'monthly':
          cutoffDate.setMonth(now.getMonth() - 12) // Last 12 months
          break
        case 'yearly':
          cutoffDate.setFullYear(now.getFullYear() - 5) // Last 5 years
          break
      }

      const cutoffStr = cutoffDate.toISOString().slice(0, 10)
      filtered = filtered.filter(r => r.date >= cutoffStr)
    }

    return filtered
  }, [rows, selectedIssues, allIssues.length, timePeriod])

  const groupedRows = useMemo(() => {
    const groups: { key: string; dateLabel: string; timeLabel: string; entries: Row[] }[] = []
    const seen = new Map<string, number>()

    filteredRows.forEach((row) => {
      let key = row.date
      let dateLabel = row.date
      let timeLabel = ''
      if (row.timestamp) {
        const parsed = new Date(row.timestamp)
        if (!Number.isNaN(parsed.getTime())) {
          key = format(parsed, 'yyyy-MM-dd HH:mm')
          dateLabel = format(parsed, 'yyyy-MM-dd')
          timeLabel = format(parsed, 'h:mm a')
        }
      }
      const existingIndex = seen.get(key)
      if (existingIndex === undefined) {
        groups.push({ key, dateLabel, timeLabel, entries: [row] })
        seen.set(key, groups.length - 1)
      } else {
        groups[existingIndex].entries.push(row)
      }
    })

    return groups
  }, [filteredRows])

  const visibleHistoryRangeLabel = useMemo(() => {
    if (filteredRows.length === 0) return 'No data available for the selected time period.'

    const timestamps = filteredRows
      .map((row) => {
        const parsed = row.timestamp ? new Date(row.timestamp) : new Date(`${row.date}T12:00:00`)
        return Number.isNaN(parsed.getTime()) ? null : parsed
      })
      .filter((value): value is Date => value !== null)
      .sort((a, b) => a.getTime() - b.getTime())

    if (timestamps.length === 0) return 'No data available for the selected time period.'

    const first = timestamps[0]
    const last = timestamps[timestamps.length - 1]
    const firstLabel = format(first, 'MMM d')
    const lastLabel = format(last, 'MMM d')

    if (firstLabel === lastLabel) {
      return `Showing data for ${firstLabel}`
    }

    return `Showing data from ${firstLabel} to ${lastLabel}`
  }, [filteredRows])

  useEffect(() => {
    setPage(1)
  }, [groupedRows.length])

  const handleChartClick = (event: React.MouseEvent<HTMLCanvasElement>) => {
    const chart = chartRef.current
    if (!chart) return
    const nativeEvent = (event.nativeEvent ?? event) as unknown as Event
    const elements = chart.getElementsAtEventForMode(nativeEvent, 'nearest', { intersect: true }, true)

    if (!elements.length) {
      if (tooltipActive) {
        lastTooltipKeyRef.current = null
        chart.tooltip?.setActiveElements([], { x: 0, y: 0 })
        chart.update()
        setTooltipActive(false)
      }
      return
    }

    const { datasetIndex, index } = elements[0]
    const key = `${datasetIndex}:${index}`
    if (lastTooltipKeyRef.current === key) {
      lastTooltipKeyRef.current = null
      chart.tooltip?.setActiveElements([], { x: 0, y: 0 })
      chart.update()
      setTooltipActive(false)
      return
    }

    lastTooltipKeyRef.current = key
    const point = chart.getDatasetMeta(datasetIndex).data[index] as { x: number; y: number }
    chart.tooltip?.setActiveElements([{ datasetIndex, index }], { x: point.x, y: point.y })
    chart.update()
    setTooltipActive(true)
  }

  const handleTooltipDismiss = () => {
    const chart = chartRef.current
    if (!chart) return
    lastTooltipKeyRef.current = null
    chart.tooltip?.setActiveElements([], { x: 0, y: 0 })
    chart.update()
    setTooltipActive(false)
  }

  const handleDelete = async (date: string, issueId: string) => {
    if (!confirm('Delete this rating?')) return
    try {
      const res = await fetch(`/api/checkins/ratings?date=${date}&issueId=${issueId}`, { method: 'DELETE' })
      if (res.ok) {
        await load(undefined, { force: true })
        // setShowDeleteMenu(null) // This state was removed
      } else {
        alert('Failed to delete rating')
      }
    } catch (e) {
      alert('Error deleting rating')
    }
  }

  const handleEdit = (entry: Row) => {
    setEditingEntry(entry)
    setEditValue(entry.value)
    setEditNote(entry.note || '')
    // setShowDeleteMenu(null) // This state was removed
  }

  const handleSaveEdit = async () => {
    if (!editingEntry) return
    try {
      const res = await fetch('/api/checkins/ratings', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          date: editingEntry.date,
          issueId: editingEntry.issueId,
          value: editValue,
          note: editNote
        })
      })
      if (res.ok) {
        await load(undefined, { force: true })
        setEditingEntry(null)
      } else {
        alert('Failed to update rating')
      }
    } catch (e) {
      alert('Error updating rating')
    }
  }

  const handleDeleteSelected = async () => {
    if (selectedIssues.size === 0) return
    const issueIds = filteredRows
      .filter(r => selectedIssues.has(r.name))
      .map(r => r.issueId)
      .filter((v, i, a) => a.indexOf(v) === i)

    if (!confirm(`Delete all ratings for ${selectedIssues.size} selected issue(s)?`)) return

    try {
      const res = await fetch('/api/checkins/ratings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'delete-by-issues', issueIds })
      })
      if (res.ok) {
        await load(undefined, { force: true })
        setSelectedIssues(new Set())
      } else {
        alert('Failed to delete ratings')
      }
    } catch (e) {
      alert('Error deleting ratings')
    }
  }

  const handleResetAll = async () => {
    if (!confirm('Delete ALL rating data? This cannot be undone.')) return
    try {
      const res = await fetch('/api/checkins/ratings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'delete-all' })
      })
      if (res.ok) {
        await load(undefined, { force: true })
        setSelectedIssues(new Set())
      } else {
        alert('Failed to reset data')
      }
    } catch (e) {
      alert('Error resetting data')
    }
  }

  const toggleSelectAll = () => {
    if (selectedIssues.size === allIssues.length) {
      setSelectedIssues(new Set())
    } else {
      setSelectedIssues(new Set(allIssues))
    }
  }

  const toggleIssue = (issue: string) => {
    const newSet = new Set(selectedIssues)
    if (newSet.has(issue)) {
      newSet.delete(issue)
    } else {
      newSet.add(issue)
    }
    setSelectedIssues(newSet)
  }

  // Prepare chart data
  const chartData: ChartData<'line', { x: string; y: number | null }[]> = useMemo(() => {
    if (filteredRows.length === 0) return { labels: [], datasets: [] }

    const allDates = Array.from(new Set(filteredRows.map(r => r.date))).sort()
    const allIssueNames = Array.from(new Set(filteredRows.map(r => r.name))).sort()

    const colors = [
      'rgb(34, 197, 94)', // green
      'rgb(59, 130, 246)', // blue
      'rgb(168, 85, 247)', // purple
      'rgb(236, 72, 153)', // pink
      'rgb(251, 146, 60)', // orange
      'rgb(234, 179, 8)', // yellow
      'rgb(14, 165, 233)', // sky
    ]

    const datasets = allIssueNames.map((name, index) => {
      // Create a map of date -> value for this issue
      const valueMap = new Map<string, number | null>()
      filteredRows
        .filter(r => r.name === name)
        .forEach(r => {
          valueMap.set(r.date, r.value)
        })

      // Build data array aligned with allDates
      const data = allDates.map(date => {
        const value = valueMap.get(date)
        return {
          x: date,
          y: value === undefined ? null : value,
        }
      })

      const color = COLOR_PALETTE[index % COLOR_PALETTE.length]

      return {
        label: name,
        data,
        borderColor: color,
        backgroundColor: toRGBA(color, 0.15),
        tension: 0.35,
        fill: true,
        spanGaps: true,
        pointRadius: 3,
        pointHoverRadius: 5,
      }
    })

    return {
      labels: allDates,
      datasets
    }
  }, [filteredRows])

  const chartOptions: ChartOptions<'line'> = useMemo(() => {
    // Determine time unit and format based on selected period
    let timeUnit: 'day' | 'week' | 'month' | 'year' = 'day'
    let displayFormat = 'MMM d'
    let maxTicks = 7

    switch (timePeriod) {
      case 'daily':
        timeUnit = 'day'
        displayFormat = 'MMM d'
        maxTicks = 10
        break
      case 'weekly':
        timeUnit = 'week'
        displayFormat = 'MMM d'
        maxTicks = 12
        break
      case 'monthly':
        timeUnit = 'month'
        displayFormat = 'MMM yyyy'
        maxTicks = 12
        break
      case 'yearly':
        timeUnit = 'year'
        displayFormat = 'yyyy'
        maxTicks = 5
        break
      case 'all':
        timeUnit = 'day'
        displayFormat = 'MMM d, yyyy'
        maxTicks = 15
        break
    }

    return {
      responsive: true,
      maintainAspectRatio: false,
      resizeDelay: 150,
      animation: false,
      plugins: {
        legend: {
          position: 'bottom',
          labels: {
            usePointStyle: true,
            padding: 15,
          }
        },
        tooltip: {
          mode: 'index',
          intersect: false,
          title: (items: TooltipItem<'line'>[]) => {
            if (!items?.length) return ''
            const parsedX = items[0].parsed.x
            const dateValue = typeof parsedX === 'string' ? parsedX : Number(parsedX)
            return format(new Date(dateValue), displayFormat === 'MMM d' ? 'MMM d, yyyy' : displayFormat)
          },
          label: (context: TooltipItem<'line'>) => {
            const datasetLabel = context.dataset.label || ''
            const value = context.parsed.y
            if (value === null) return `${datasetLabel}: N/A`
            return `${datasetLabel}: ${value} • ${getRatingLabel(value)}`
          }
        }
      },
      scales: {
        y: {
          beginAtZero: true,
          max: 6,
          ticks: {
            stepSize: 1,
          }
        },
        x: {
          type: 'time',
          time: {
            unit: timeUnit,
            displayFormats: {
              [timeUnit]: displayFormat
            }
          },
          ticks: {
            maxRotation: 0,
            autoSkip: true,
            maxTicksLimit: maxTicks,
          },
        }
      }
    }
  }, [timePeriod])
  const totalPages = Math.max(1, Math.ceil(groupedRows.length / pageSize))
  const pageStart = groupedRows.length === 0 ? 0 : (page - 1) * pageSize + 1
  const pageEnd = Math.min(page * pageSize, groupedRows.length)
  const pagedGroups = groupedRows.slice((page - 1) * pageSize, page * pageSize)

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 pb-24 overflow-x-hidden">
      <PageHeader title="Today's Check-In" backHref="/more" />

      {/* Tabs */}
      <div className="max-w-5xl mx-auto px-4 pt-4">
        <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-xl">
          <Link
            href="/check-in"
            className={`flex-1 py-2 text-sm font-medium rounded-lg text-center transition-colors ${
              pathname !== '/check-in/history'
                ? 'bg-white dark:bg-slate-700 shadow-sm text-helfi-green'
                : 'text-slate-500 dark:text-slate-400'
            }`}
          >
            Today's Check-in
          </Link>
          <Link
            href="/check-in/history"
            className={`flex-1 py-2 text-sm font-medium rounded-lg text-center transition-colors ${
              pathname === '/check-in/history'
                ? 'bg-white dark:bg-slate-700 shadow-sm text-helfi-green'
                : 'text-slate-500 dark:text-slate-400'
            }`}
          >
            Rating History
          </Link>
        </div>
      </div>

      <main className="max-w-5xl mx-auto px-4 pb-24">
        <div className="space-y-8 pt-6">
          <div>
            <h1 className="text-2xl md:text-3xl font-bold text-gray-900 dark:text-white mb-2">Check-in History</h1>
            <p className="text-xs md:text-sm text-gray-500 dark:text-gray-400 mb-4">
              Scale: 0 Really bad · 1 Bad · 2 Below average · 3 Average · 4 Above average · 5 Good · 6 Excellent
            </p>
          </div>

          {timePeriod === 'custom' && (
            <div className="space-y-3 mb-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Start Date</label>
              <input
                type="date"
                value={start}
                onChange={(e) => setStart(e.target.value)}
                className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-4 py-2.5 dark:bg-gray-700 dark:text-white focus:ring-2 focus:ring-helfi-green focus:border-transparent"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">End Date</label>
              <input
                type="date"
                value={end}
                onChange={(e) => setEnd(e.target.value)}
                className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-4 py-2.5 dark:bg-gray-700 dark:text-white focus:ring-2 focus:ring-helfi-green focus:border-transparent"
              />
            </div>
            <button
              onClick={() => load(undefined, { force: true })}
              disabled={loading}
              className="w-full bg-helfi-green text-white px-4 py-2.5 rounded-lg hover:bg-helfi-green/90 disabled:opacity-60 font-medium transition-colors"
            >
              {loading ? 'Loading...' : 'Apply Filter'}
            </button>
          </div>
          )}

          {/* Filtering Section */}
          {allIssues.length > 0 && (
            <section>
              <div className="flex items-end justify-between mb-3">
                <h3 className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                  Filter by Health Issue
                </h3>
                <button
                  onClick={toggleSelectAll}
                  className="text-helfi-green text-xs font-semibold"
                >
                  {selectedIssues.size === allIssues.length ? 'Deselect All' : 'Select All'}
                </button>
              </div>
              <div className="flex gap-2 overflow-x-auto scrollbar-none pb-2">
                {allIssues.map(issue => (
                  <button
                    key={issue}
                    onClick={() => toggleIssue(issue)}
                    className={`whitespace-nowrap px-4 py-2 rounded-full text-sm font-medium shadow-sm transition-transform active:scale-95 ${
                      selectedIssues.has(issue)
                        ? 'bg-helfi-green text-white'
                        : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700'
                    }`}
                  >
                    {issue}
                  </button>
                ))}
              </div>
              {selectedIssues.size > 0 && selectedIssues.size < allIssues.length && (
                <button
                  onClick={handleDeleteSelected}
                  className="mt-3 text-xs text-red-600 hover:underline"
                >
                  Delete Selected ({selectedIssues.size})
                </button>
              )}
            </section>
          )}


          {/* Chart */}
          {filteredRows.length > 0 && chartData.datasets.length > 0 && (
            <section>
              <div className="flex items-center justify-between mb-2">
                <h2 className="text-xl font-bold text-gray-900 dark:text-white">Trends Over Time</h2>
                <div className="relative">
                  <select
                    value={timePeriod}
                    onChange={(e) => setTimePeriod(e.target.value as 'daily' | 'weekly' | 'monthly' | 'yearly' | 'all' | 'custom')}
                    className="appearance-none bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg pl-3 pr-8 py-2 text-sm font-medium text-slate-700 dark:text-slate-200 focus:ring-2 focus:ring-helfi-green focus:border-transparent cursor-pointer"
                  >
                    <option value="daily">30 Days</option>
                    <option value="weekly">12 Weeks</option>
                    <option value="monthly">12 Months</option>
                    <option value="yearly">5 Years</option>
                    <option value="all">All Time</option>
                    <option value="custom">Custom Date</option>
                  </select>
                  <span className="pointer-events-none absolute right-2 top-1/2 -translate-y-1/2 text-slate-400">
                    <svg className="w-4 h-4" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true">
                      <path fillRule="evenodd" d="M5.23 7.21a.75.75 0 011.06.02L10 10.94l3.71-3.71a.75.75 0 111.06 1.06l-4.24 4.25a.75.75 0 01-1.06 0L5.21 8.29a.75.75 0 01.02-1.08z" clipRule="evenodd" />
                    </svg>
                  </span>
                </div>
              </div>
              <p className="text-sm text-slate-500 dark:text-slate-400 mb-4">
                Ratings are scored 0 (Really bad) to 6 (Excellent). Hover the chart to see exact values.
              </p>
              <p className="text-xs text-slate-500 dark:text-slate-400 -mt-2 mb-4">
                {visibleHistoryRangeLabel}
              </p>

              <div className="relative h-56 md:h-72" onWheelCapture={handleChartWheelCapture}>
                <Line
                  ref={chartRef}
                  data={chartData}
                  options={chartOptions}
                  onClick={handleChartClick}
                  onMouseLeave={handleTooltipDismiss}
                />
                {tooltipActive && (
                  <button
                    type="button"
                    onClick={handleTooltipDismiss}
                    className="absolute right-2 top-2 z-10 rounded-md border border-slate-200 bg-white/95 px-2 py-1 text-xs font-medium text-slate-600 shadow-sm hover:bg-white"
                    aria-label="Hide chart tooltip"
                  >
                    Hide tip
                  </button>
                )}
              </div>
              <div className="flex flex-wrap gap-4 mt-4 justify-center">
                {chartData.datasets.map((dataset) => (
                  <div key={dataset.label} className="flex items-center gap-1.5">
                    <span
                      className="w-2 h-2 rounded-full"
                      style={{ backgroundColor: dataset.borderColor as string }}
                      aria-hidden="true"
                    />
                    <span className="text-[10px] text-slate-500 font-medium">{dataset.label}</span>
                  </div>
                ))}
              </div>
            </section>
          )}

          <section>
            <h2 className="text-lg font-bold mb-4 text-gray-900 dark:text-white">Check-in History</h2>
            {groupedRows.length === 0 ? (
              <div className="py-8 text-center text-gray-500 dark:text-gray-400">
                {rows.length === 0 ? 'No ratings yet.' : 'No ratings match your filters.'}
              </div>
            ) : (
              <>
                <div className="grid gap-3 md:grid-cols-2">
                  {pagedGroups.map((group) => {
                    const rowKey = group.key

                    return (
                      <div
                        key={rowKey}
                        className="bg-white dark:bg-slate-800 p-4 pr-5 rounded-xl shadow-sm border border-slate-100 dark:border-slate-800"
                      >
                        <button
                          type="button"
                          onClick={() => setExpandedRow((current) => (current === rowKey ? null : rowKey))}
                          className="w-full text-left"
                        >
                          <div className="flex items-center justify-between gap-3">
                            <div className="flex items-center gap-3">
                              <span className="text-sm font-semibold text-gray-900 dark:text-white">
                                {group.dateLabel}
                              </span>
                              {group.timeLabel && (
                                <span className="text-xs font-semibold text-slate-400 uppercase">
                                  {group.timeLabel}
                                </span>
                              )}
                            </div>
                            <span
                              className={`text-slate-400 transition-transform ${
                                expandedRow === rowKey ? 'rotate-180' : ''
                              }`}
                              aria-hidden="true"
                            >
                              <svg className="w-4 h-4" viewBox="0 0 20 20" fill="currentColor">
                                <path fillRule="evenodd" d="M5.23 7.21a.75.75 0 011.06.02L10 10.94l3.71-3.71a.75.75 0 111.06 1.06l-4.24 4.25a.75.75 0 01-1.06 0L5.21 8.29a.75.75 0 01.02-1.08z" clipRule="evenodd" />
                              </svg>
                            </span>
                          </div>
                        </button>
                        {expandedRow === rowKey && (
                          <div className="mt-4 space-y-3">
                            {group.entries.map((entry) => {
                              const label = getRatingLabel(entry.value)
                              const color = entry.value === null || entry.value === undefined ? 'bg-gray-100 text-gray-600 border-gray-200 dark:bg-gray-700 dark:text-gray-400' :
                                entry.value <= 1 ? 'bg-red-100 text-red-700 border-red-200 dark:bg-red-900/30 dark:text-red-400' :
                                entry.value <= 3 ? 'bg-yellow-100 text-yellow-800 border-yellow-200 dark:bg-yellow-900/30 dark:text-yellow-400' :
                                'bg-green-100 text-green-700 border-green-200 dark:bg-green-900/30 dark:text-green-400'

                              return (
                                <div key={`${entry.issueId}-${entry.date}`} className="flex flex-wrap items-center justify-between gap-3">
                                  <div className="min-w-0">
                                    <p className="text-sm font-semibold text-gray-900 dark:text-white">
                                      {entry.name}
                                    </p>
                                    {entry.note && (
                                      <p className="text-xs text-slate-500 mt-1">Note: {entry.note}</p>
                                    )}
                                  </div>
                                  <div className="flex items-center gap-2">
                                    <span className={`px-3 py-1 rounded-full text-xs font-bold border ${color}`}>
                                      {label}
                                      {entry.value !== null && entry.value !== undefined && (
                                        <span className="ml-1 opacity-70">({entry.value})</span>
                                      )}
                                    </span>
                                    <button
                                      onClick={() => handleEdit(entry)}
                                      className="px-3 py-1.5 text-xs font-semibold text-slate-700 dark:text-slate-200 border border-slate-200 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700"
                                    >
                                      Edit
                                    </button>
                                    <button
                                      onClick={() => handleDelete(entry.date, entry.issueId)}
                                      className="px-3 py-1.5 text-xs font-semibold text-red-600 border border-red-200 rounded-lg hover:bg-red-50 dark:hover:bg-red-900/20"
                                    >
                                      Delete
                                    </button>
                                  </div>
                                </div>
                              )
                            })}
                          </div>
                        )}
                      </div>
                    )
                  })}
                </div>
                <div className="flex justify-between items-center mt-6">
                  <p className="text-xs text-slate-500 font-medium">
                    Showing {pageStart}-{pageEnd} of {groupedRows.length}
                  </p>
                  <div className="flex gap-2">
                    <button
                      onClick={() => setPage((p) => Math.max(1, p - 1))}
                      disabled={page <= 1}
                      className="px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs font-semibold disabled:opacity-50"
                    >
                      Previous
                    </button>
                    <button
                      onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                      disabled={page >= totalPages}
                      className="px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs font-semibold disabled:opacity-50"
                    >
                      Next
                    </button>
                  </div>
                </div>
              </>
            )}
          </section>

          {/* Reset Button */}
          {rows.length > 0 && (
            <footer className="mt-10 text-center">
              <button
                onClick={handleResetAll}
                className="w-full py-4 border-2 border-dashed border-red-200 dark:border-red-900/30 text-red-500 dark:text-red-400 font-bold rounded-2xl hover:bg-red-50 dark:hover:bg-red-900/10 transition-colors"
              >
                Reset All Data
              </button>
              <p className="mt-4 text-[10px] text-slate-400 leading-relaxed max-w-xs mx-auto">
                Resetting your data will permanently delete your check-in history. This action cannot be undone.
              </p>
            </footer>
          )}
        </div>
      </main>

      {/* Edit Modal */}
      {editingEntry && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-xl max-w-md w-full p-6">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">Edit Rating</h3>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">Rating</label>
                <div className="grid grid-cols-4 gap-2">
                  {LABELS.map((label, idx) => (
                    <button
                      key={idx}
                      onClick={() => setEditValue(idx)}
                      className={`px-3 py-2 rounded-lg text-xs border transition-colors ${
                        editValue === idx
                          ? 'bg-helfi-green text-white border-helfi-green'
                          : 'bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-300 border-gray-200 dark:border-gray-600 hover:border-helfi-green'
                      }`}
                    >
                      {label}
                    </button>
                  ))}
                </div>
                <button
                  onClick={() => setEditValue(null)}
                  className="mt-2 text-xs text-gray-600 dark:text-gray-400 hover:underline"
                >
                  Mark as N/A
                </button>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">Note (optional)</label>
                <textarea
                  value={editNote}
                  onChange={(e) => setEditNote(e.target.value)}
                  rows={3}
                  className="w-full border border-gray-300 dark:border-gray-600 rounded-lg px-3 py-2 dark:bg-gray-700 dark:text-white"
                  placeholder="Add a note..."
                />
              </div>
              <div className="flex gap-3 justify-end">
                <button
                  onClick={() => setEditingEntry(null)}
                  className="px-4 py-2 text-sm font-medium text-gray-700 dark:text-gray-300 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700"
                >
                  Cancel
                </button>
                <button
                  onClick={handleSaveEdit}
                  className="px-4 py-2 text-sm font-medium text-white bg-helfi-green rounded-lg hover:bg-helfi-green/90"
                >
                  Save
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import React, { useEffect, useMemo, useRef, useState } from 'react'
import { usePathname } from 'next/navigation'
import Link from 'next/link'
import PageHeader from '@/components/PageHeader'

const LABELS = [
  'Really bad',
  'Bad',
  'Below average',
  'Average',
  'Above average',
  'Good',
  'Excellent',
] as const

type UserIssue = { id: string; name: string; polarity: 'positive' | 'negative' }
type TodayCache = {
  issues: UserIssue[]
  ratings: Record<string, number | null>
  notes: Record<string, string>
  na: Record<string, boolean>
  fetchedAt: number
}

export default function CheckInPage() {
  const [ratings, setRatings] = useState<Record<string, number | null>>({})
  const [notes, setNotes] = useState<Record<string, string>>({})
  const [na, setNa] = useState<Record<string, boolean>>({})
  const [issues, setIssues] = useState<UserIssue[]>([])
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const pendingIdRef = useRef<string | null>(
    typeof window !== 'undefined'
      ? new URLSearchParams(window.location.search).get('notificationId')?.trim() || null
      : null
  )

  useEffect(() => {
    const CACHE_KEY = 'checkins:today:cache'
    const CACHE_TTL_MS = 5 * 60_000
    const forceBlank =
      typeof window !== 'undefined' &&
      new URLSearchParams(window.location.search).get('new') === '1'

    const readCache = (): TodayCache | null => {
      if (typeof window === 'undefined') return null
      try {
        const raw = window.sessionStorage.getItem(CACHE_KEY)
        if (!raw) return null
        const parsed = JSON.parse(raw) as TodayCache
        if (!parsed?.fetchedAt) return null
        return parsed
      } catch {
        return null
      }
    }

    const writeCache = (data: TodayCache) => {
      if (typeof window === 'undefined') return
      try {
        window.sessionStorage.setItem(CACHE_KEY, JSON.stringify(data))
      } catch {
        // ignore
      }
    }

    const cached = forceBlank ? null : readCache()
    const cacheFresh = cached && Date.now() - cached.fetchedAt < CACHE_TTL_MS
    if (cached && cacheFresh) {
      setIssues(cached.issues || [])
      setRatings(cached.ratings || {})
      setNotes(cached.notes || {})
      setNa(cached.na || {})
      setLoading(false)
    }

    // Load actual issues if API is available
    if (!cacheFresh) setLoading(true)
    fetch('/api/checkins/today', { cache: 'no-store' as any })
      .then(r => r.json())
      .then((data) => {
        let nextIssues: UserIssue[] = []
        let nextRatings: Record<string, number | null> = {}
        if (Array.isArray(data?.issues)) {
          const seen = new Set<string>()
          const unique = [] as UserIssue[]
          for (const it of data.issues as UserIssue[]) {
            const key = (it.name || '').toLowerCase().trim()
            if (!seen.has(key)) { seen.add(key); unique.push(it) }
          }
          if (unique.length > 0) {
            nextIssues = unique
            setIssues(unique)
          }
        }
        if (!forceBlank && Array.isArray(data?.ratings)) {
          const map: Record<string, number | null> = {}
          for (const r of data.ratings) map[r.issueId] = r.value
          nextRatings = map
          setRatings(map)
        } else if (forceBlank) {
          setRatings({})
          setNotes({})
          setNa({})
        }
        if (!forceBlank) {
          writeCache({
            issues: nextIssues,
            ratings: nextRatings,
            notes: {},
            na: {},
            fetchedAt: Date.now(),
          })
        }
      })
      .catch(() => {})
      .finally(() => setLoading(false))
  }, [])

  useEffect(() => {
    if (!pendingIdRef.current) return
    try {
      sessionStorage.setItem('helfi:pending-notification-id', pendingIdRef.current)
    } catch {}
  }, [])

  const setRating = (issueId: string, value: number) => {
    setRatings((r) => {
      const current = r[issueId]
      const nextValue = current === value ? null : value
      const updated = { ...r, [issueId]: nextValue }
      return updated
    })
    setNa((n) => {
      const updated = { ...n, [issueId]: false }
      return updated
    })
  }

  const handleSave = async () => {
    if (saving) return
    setSaving(true)
    try {
      const pendingId =
        pendingIdRef.current ||
        (typeof window !== 'undefined' ? sessionStorage.getItem('helfi:pending-notification-id') : null)
      const payload = issues.map((it) => ({
        issueId: it.id,
        value: na[it.id] ? null : (ratings[it.id] ?? null),
        note: notes[it.id] || '',
        isNa: !!na[it.id],
      }))
      const res = await fetch('/api/checkins/today', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ratings: payload, notificationId: pendingId || undefined }),
      })
      if (!res.ok) {
        const data = await res.json().catch(() => ({}))
        throw new Error(data?.detail || data?.error || 'Failed to save')
      }
      try {
        for (let index = sessionStorage.length - 1; index >= 0; index -= 1) {
          const key = sessionStorage.key(index)
          if (key?.startsWith('checkin-history:') || key?.startsWith('checkin-history-v2:')) {
            sessionStorage.removeItem(key)
          }
        }
      } catch {}
      try {
        const CACHE_KEY = 'checkins:today:cache'
        const payloadRatings: Record<string, number | null> = {}
        for (const item of payload) payloadRatings[item.issueId] = item.value
        sessionStorage.setItem(
          CACHE_KEY,
          JSON.stringify({
            issues,
            ratings: payloadRatings,
            notes,
            na,
            fetchedAt: Date.now(),
          }),
        )
      } catch {}
      if (pendingId) {
        try {
          sessionStorage.removeItem('helfi:pending-notification-id')
        } catch {}
        pendingIdRef.current = null
      }
      // Navigate after save
      try {
        const search = typeof window !== 'undefined' ? window.location.search : ''
        const params = new URLSearchParams(search)
        const ret = params.get('return') || ''
        const ref = document.referrer || ''
        const isEditMode = !!params.get('new')
        const cameFromOnboarding = ret.includes('/onboarding') || ref.includes('/onboarding')
        if (isEditMode) {
          // When adding issues after onboarding, go straight to dashboard
          window.location.assign('/dashboard')
          return
        }
        if (cameFromOnboarding) {
          // First-time onboarding flow
          window.location.assign('/onboarding?step=5')
          return
        }
        // Default
        window.location.assign('/dashboard')
        return
      } catch {}
      alert('Saved today\'s ratings.')
    } catch (e: any) {
      alert(e?.message || 'Failed to save. Please try again.')
    } finally {
      setSaving(false)
    }
  }

  const pathname = usePathname()
  const isHistoryPage = pathname === '/check-in/history'

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 pb-24">
      <PageHeader title="Today's Check-In" backHref="/more" />

      {/* Tabs */}
      <div className="max-w-3xl mx-auto px-4 pt-4">
        <div className="bg-white dark:bg-gray-800 rounded-t-xl border-b border-gray-200 dark:border-gray-700">
          <div className="flex">
            <Link
              href="/check-in"
              className={`flex-1 px-4 py-3 text-center font-medium transition-colors ${
                !isHistoryPage
                  ? 'text-helfi-green border-b-2 border-helfi-green'
                  : 'text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-gray-200'
              }`}
            >
              Today's Check-in
            </Link>
            <Link
              href="/check-in/history"
              className={`flex-1 px-4 py-3 text-center font-medium transition-colors ${
                isHistoryPage
                  ? 'text-helfi-green border-b-2 border-helfi-green'
                  : 'text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-gray-200'
              }`}
            >
              Rating History
            </Link>
          </div>
        </div>
      </div>

      {!isHistoryPage ? (
        <main className="max-w-3xl mx-auto px-4 py-6">
          <div className="bg-white dark:bg-gray-800 rounded-b-2xl shadow-sm p-6">
            <div className="mb-2">
              <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Today's check‑in</h1>
              <Link href="/notifications/reminders" className="inline-flex items-center text-sm text-helfi-green hover:underline font-medium mt-2">
                Set your notifications →
              </Link>
            </div>
            <p className="text-sm text-gray-600 dark:text-gray-400 mb-6">Rate how you went today. One tap per item, then Save.</p>

        {loading ? (
          <div className="flex items-center justify-center py-12">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-helfi-green"></div>
          </div>
        ) : (
          <div className="space-y-6">
            {issues.length === 0 && (
              <div className="border border-yellow-200 bg-yellow-50 text-yellow-800 rounded-xl p-4 text-sm">
                No issues selected yet. Go to <a className="underline" href="/onboarding?step=4">Health Setup</a> to choose what you want to track.
              </div>
            )}
          {issues
            // Filter only for ?new= parameter, otherwise show all issues so users can see and edit their ratings
            .filter((it) => {
              try {
                const params = new URLSearchParams(window.location.search || '')
                // If ?new= is present, show only those newly added issues
                const onlyNew = params.get('new')
                if (onlyNew && onlyNew !== '1') {
                  const set = new Set(onlyNew.split('|').map(s => s.toLowerCase()))
                  return set.has((it.name || '').toLowerCase())
                }
                // Always show all issues - users should see what they've rated
                return true
              } catch {}
              return true
            })
            .map((issue) => {
            const isPlural = () => {
              const n = (issue.name || '').trim()
              // Simple plural detection with common exceptions
              // Treat words like "Bowel Movements", "Movements", "Allergies" as plural
              if (/\b(movements|allergies|bowels|bowel movements)\b/i.test(n)) return true
              // Ends with 's' and not 'ss' → likely plural (e.g., "Headaches", "Rashes")
              return /[^s]s$/i.test(n)
            }
            const question = issue.polarity === 'negative'
              ? `How were your ${issue.name} levels today?`
              : (isPlural() ? `How were your ${issue.name} today?` : `How was your ${issue.name} today?`)
            const selectedRating = ratings[issue.id]
            const isNotApplicable = na[issue.id]
            return (
              <div key={issue.id} className="border border-gray-200 dark:border-gray-700 rounded-xl p-4 dark:bg-gray-800/50">
                <div className="font-medium mb-3 text-gray-900 dark:text-white">{question}</div>
                <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-7 gap-2">
                  {LABELS.map((label, idx) => {
                    const isSelected = selectedRating === idx && !isNotApplicable
                    return (
                      <button
                        key={idx}
                        type="button"
                        onClick={(e) => {
                          e.preventDefault()
                          e.stopPropagation()
                          setRating(issue.id, idx)
                        }}
                        className={`text-xs px-2 py-2 rounded-lg border transition-all duration-200 font-medium ${
                          isSelected
                            ? 'bg-[#4CAF50] text-white border-[#4CAF50] shadow-md'
                            : 'bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-300 border-gray-200 dark:border-gray-600 hover:border-[#4CAF50] hover:bg-gray-50 dark:hover:bg-gray-600'
                        }`}
                        style={isSelected ? { backgroundColor: '#4CAF50', color: 'white', borderColor: '#4CAF50' } : undefined}
                      >
                        {label}
                      </button>
                    )
                  })}
                </div>
                {/* Optional details accordion */}
                <details className="mt-3">
                  <summary className="text-sm text-gray-600 cursor-pointer select-none">Add details (optional)</summary>
                  <textarea
                    value={notes[issue.id] || ''}
                    onChange={(e)=>setNotes((m)=>({ ...m, [issue.id]: e.target.value }))}
                    rows={3}
                    placeholder="Anything notable today?"
                    className="mt-2 w-full border rounded-lg p-2 text-sm"
                  />
                </details>
                <div className="mt-3">
                  <label className="inline-flex items-center gap-2 text-sm text-gray-700">
                    <input type="checkbox" checked={!!na[issue.id]} onChange={(e)=> setNa((m)=>({ ...m, [issue.id]: e.target.checked }))} />
                    Not applicable for this time
                  </label>
                </div>
              </div>
            )
          })}
          </div>
        )}

        {!loading && (
          <div className="mt-6 flex justify-end">
            <button
              onClick={handleSave}
              disabled={saving}
              aria-live="polite"
              className="bg-helfi-green text-white px-4 py-2 rounded-lg hover:bg-helfi-green/90 disabled:cursor-wait disabled:opacity-70"
            >
              {saving ? 'Saving…' : "Save today's ratings"}
            </button>
          </div>
        )}
          </div>
        </main>
      ) : null}
    </div>
  )
}

'use client'
import { Cog6ToothIcon, UserIcon } from '@heroicons/react/24/outline'

import React, { useState, useEffect, useRef } from 'react'
import { useSession, signOut } from 'next-auth/react'
import Image from 'next/image'
import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { useUserData } from '@/components/providers/UserDataProvider'
import { isCacheFresh, readClientCache, writeClientCache } from '@/lib/client-cache'
import { countVisibleHealthGoals, hasBasicProfileData, isHealthSetupComplete } from '@/lib/health-setup-completion'
import MobileMoreMenu from '@/components/MobileMoreMenu'
import UsageMeter from '@/components/UsageMeter'
import FitbitSummary from '@/components/devices/FitbitSummary'

const DASHBOARD_CACHE_TTL_MS = 5 * 60_000

export default function Dashboard() {
  // ⚠️ HEALTH SETUP GUARD RAIL
  // Dashboard onboarding logic is tightly coupled to HEALTH_SETUP_PROTECTION.md:
  // - Onboarding is "complete" only when gender, weight, height, and at least one health goal exist.
  // - Brand-new users may be redirected to /onboarding, but only if
  //   sessionStorage.onboardingDeferredThisSession !== '1' (user has NOT chosen "I'll do it later").
  // - The green "Onboarding Complete" card must only show when onboardingComplete === true.
  // Do NOT loosen these checks or remove the deferral flag without reading
  // HEALTH_SETUP_PROTECTION.md and getting explicit user approval.
  const { data: session } = useSession()
  const pathname = usePathname()
  const { profileImage: providerProfileImage } = useUserData()
  const cacheKey = session?.user?.email ? `dashboard-data:${session.user.email}` : ''
  const [onboardingData, setOnboardingData] = useState<any>(null)
  const [showResetConfirm, setShowResetConfirm] = useState(false)
  const [dropdownOpen, setDropdownOpen] = useState(false)
  const [affiliateMenu, setAffiliateMenu] = useState<{ label: string; href: string } | null>(null)
  const [profileImage, setProfileImage] = useState<string | null>(null)
  const [deviceInterest, setDeviceInterest] = useState<{ fitbit?: boolean; garmin?: boolean; googleFit?: boolean; oura?: boolean; polar?: boolean; huawei?: boolean }>({})
  const [savingInterest, setSavingInterest] = useState(false)
  const [fitbitConnected, setFitbitConnected] = useState(false)
  const [fitbitLoading, setFitbitLoading] = useState(false)
  const [garminConnected, setGarminConnected] = useState(false)
  const garminConnectEnabled = process.env.NEXT_PUBLIC_GARMIN_CONNECT_ENABLED === 'true'
  const popupRef = useRef<Window | null>(null)
  const checkIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null)

  // Profile data - prefer real photos; fall back to professional icon instead of inline SVG
  const hasProfileImage = !!(providerProfileImage || profileImage || session?.user?.image)
  const userImage = (providerProfileImage || profileImage || session?.user?.image || '') as string
  const userName = session?.user?.name || 'User';

  // Close dropdown on outside click
  useEffect(() => {
    function handleClick(e: MouseEvent) {
      const target = e.target as HTMLElement;
      // Check if click is outside both the button and the dropdown content
      if (!target.closest('.dropdown-container')) {
        setDropdownOpen(false);
      }
    }
    if (dropdownOpen) {
      document.addEventListener('mousedown', handleClick);
      return () => document.removeEventListener('mousedown', handleClick);
    }
  }, [dropdownOpen]);

  useEffect(() => {
    if (!session?.user?.email) {
      setAffiliateMenu(null)
      return
    }
    let cancelled = false
    setAffiliateMenu({ label: 'Become an Affiliate', href: '/affiliate/apply' })
    const loadAffiliateMenu = async () => {
      try {
        const res = await fetch('/api/affiliate/application', { cache: 'no-store' })
        const data = await res.json().catch(() => ({} as any))
        if (!res.ok) return
        const hasAffiliate = !!data?.affiliate
        const hasApplication = !!data?.application
        const menu = hasAffiliate
          ? { label: 'Affiliate Portal', href: '/affiliate' }
          : hasApplication
            ? { label: 'Affiliate Application', href: '/affiliate/apply' }
            : { label: 'Become an Affiliate', href: '/affiliate/apply' }
        if (!cancelled) setAffiliateMenu(menu)
      } catch {
        // ignore
      }
    }
    loadAffiliateMenu()
    return () => {
      cancelled = true
    }
  }, [session?.user?.email])

  // Load existing data from database (cross-device sync)
  useEffect(() => {
    const applyUserData = (data: any, allowRedirect: boolean) => {
      if (!data) return

      console.log('✅ Successfully loaded data from database');
      console.log('📊 Dashboard Data Summary:', {
        hasProfileImage: !!data.profileImage,
        hasHealthGoals: !!data.goals?.length,
        hasSupplements: !!data.supplements?.length,
        hasMedications: !!data.medications?.length,
        dataSize: JSON.stringify(data).length + ' characters'
      })

      // Define onboarding completion using the same rule as Insights:
      // 1) basic profile data present, and 2) at least one health goal selected.
      const hasBasicProfile = hasBasicProfileData(data)
      const hasHealthGoals = countVisibleHealthGoals(data.goals) > 0
      const onboardingComplete = isHealthSetupComplete({
        gender: data.gender,
        weight: data.weight,
        height: data.height,
        goals: data.goals,
      })

      // For truly brand-new users with no meaningful data at all, redirect
      // into onboarding on first visit, but respect "I'll do it later"
      // for the current browser session.
      if (
        allowRedirect &&
        !onboardingComplete &&
        !hasBasicProfile &&
        !hasHealthGoals &&
        !data.supplements?.length &&
        !data.medications?.length
      ) {
        const deferred =
          typeof window !== 'undefined' && sessionStorage.getItem('onboardingDeferredThisSession') === '1'
        if (!deferred) {
          console.log('🎯 Brand new user detected - redirecting to onboarding')
          window.location.href = '/onboarding'
          return
        }
        console.log('⏳ Onboarding deferred this session — staying on dashboard')
      }

      setOnboardingData({ ...data, onboardingComplete })
      // Load device interest flags if present
      if (data.deviceInterest && typeof data.deviceInterest === 'object') {
        setDeviceInterest(data.deviceInterest)
      }

      // Check Fitbit connection status
      checkFitbitStatus()
      // Check Garmin connection status
      if (garminConnectEnabled) checkGarminStatus()

      // Load profile image from database and cache it
      if (data.profileImage) {
        setProfileImage(data.profileImage)
        // Cache in localStorage for instant loading on other pages (user-specific)
        if (session?.user?.id) {
          localStorage.setItem(`cachedProfileImage_${session.user.id}`, data.profileImage)
        }
      }
    }

    const loadUserData = async () => {
      try {
        // 🔍 DASHBOARD PERFORMANCE MEASUREMENT START
        console.log('🚀 DASHBOARD LOADING PERFORMANCE TRACKING')
        console.time('⏱️ Dashboard Data Loading')
        const dashboardStartTime = Date.now()

        console.log('📤 Loading user data from database...');
        const response = await fetch('/api/user-data', {
          cache: 'no-cache',
          headers: {
            'Cache-Control': 'no-cache'
          }
        });

        const dataLoadTime = Date.now() - dashboardStartTime
        console.log('📈 Dashboard API Response:', {
          duration: dataLoadTime + 'ms',
          status: response.status,
          statusText: response.statusText
        })

        if (response.ok) {
          const result = await response.json();
          if (result.data) {
            applyUserData(result.data, true)
            if (cacheKey) {
              writeClientCache(cacheKey, result.data)
            }
          } else {
            // No data at all - definitely a new user
            const deferred = typeof window !== 'undefined' && sessionStorage.getItem('onboardingDeferredThisSession') === '1';
            if (!deferred) {
              console.log('🎯 No user data found - redirecting new user to onboarding');
              window.location.href = '/onboarding';
              return;
            } else {
              console.log('⏳ Onboarding deferred with no data — staying on dashboard');
            }
          }
        } else if (response.status === 404) {
          console.log('ℹ️ No existing data found for user in database - redirecting to onboarding');
          window.location.href = '/onboarding';
          return;
        } else if (response.status === 401) {
          console.log('⚠️ User not authenticated - redirecting to login');
          // Don't use localStorage fallback, force proper authentication
          setOnboardingData(null);
        } else {
          console.error('❌ Failed to load data from database:', response.status, response.statusText);
          setOnboardingData(null);
        }

        console.timeEnd('⏱️ Dashboard Data Loading')
        console.log('🏁 Dashboard loading completed in', Date.now() - dashboardStartTime + 'ms')
      } catch (error) {
        console.timeEnd('⏱️ Dashboard Data Loading')
        console.error('💥 Error loading user data from database:', error);
        // No localStorage fallback - force database-only approach
        setOnboardingData(null);
      }
    };

    // Load cached profile image immediately for instant display (user-specific)
    if (session?.user?.id) {
      const cachedImage = localStorage.getItem(`cachedProfileImage_${session.user.id}`);
      if (cachedImage) {
        setProfileImage(cachedImage);
      }
    }

    const cached = cacheKey ? readClientCache<any>(cacheKey) : null
    const cachedData = cached?.data
    if (cachedData) {
      applyUserData(cachedData, false)
    }
    const cachedIsEmpty =
      !!cachedData &&
      !cachedData.gender &&
      !cachedData.weight &&
      !cachedData.height &&
      !(cachedData.goals && cachedData.goals.length > 0) &&
      !(cachedData.supplements && cachedData.supplements.length > 0) &&
      !(cachedData.medications && cachedData.medications.length > 0)
    const shouldFetch =
      !cached ||
      !isCacheFresh(cached, DASHBOARD_CACHE_TTL_MS) ||
      cachedIsEmpty
    if (session && shouldFetch) {
      loadUserData();
    }

    // Listen for messages from popup window (Fitbit OAuth)
    const handleMessage = (event: MessageEvent) => {
      if (event.data?.type === 'FITBIT_CONNECTED' && event.data.success) {
        checkFitbitStatus()
        setFitbitLoading(false)
      } else if (event.data?.type === 'FITBIT_ERROR') {
        alert('Fitbit connection failed: ' + event.data.error)
        setFitbitLoading(false)
      }
    }
    window.addEventListener('message', handleMessage)

    return () => {
      window.removeEventListener('message', handleMessage)
    }
  }, [session, cacheKey]);

  const handleEditOnboarding = () => {
    // Navigate directly to onboarding - data will be loaded from database
    console.log('Navigating to edit onboarding, data will be loaded from database')
    window.location.href = '/onboarding'
  }

  const handleResetData = async () => {
    try {
      // Delete from database
      const response = await fetch('/api/user-data', {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' }
      });

      if (response.ok) {
        console.log('Data successfully deleted from database');
        setOnboardingData(null)
        setShowResetConfirm(false)
        // Redirect to onboarding to start fresh
        window.location.href = '/onboarding'
      } else {
        console.error('Failed to delete from database:', response.status, response.statusText);
        alert('Failed to reset data. Please try again.');
      }
    } catch (error) {
      console.error('Error deleting from database:', error);
      alert('Failed to reset data. Please try again.');
    }
  }

  const saveDeviceInterest = async (next: any) => {
    try {
      setSavingInterest(true)
      const res = await fetch('/api/user-data', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ deviceInterest: next })
      })
      if (!res.ok) {
        throw new Error('Device interest update failed')
      }
      setDeviceInterest(next)
    } catch (e) {
      console.error('Failed to save device interest', e)
    } finally {
      setSavingInterest(false)
    }
  }

  const checkFitbitStatus = async () => {
    try {
      const response = await fetch('/api/fitbit/status')
      if (response.ok) {
        const data = await response.json()
        setFitbitConnected(data.connected)
        return data.connected
      }
      return false
    } catch (error) {
      console.error('Error checking Fitbit status:', error)
      return false
    }
  }

  const checkGarminStatus = async () => {
    if (!garminConnectEnabled) {
      setGarminConnected(false)
      return false
    }
    try {
      const response = await fetch('/api/garmin/status')
      if (response.ok) {
        const data = await response.json()
        setGarminConnected(!!data.connected)
        return !!data.connected
      }
      return false
    } catch (error) {
      console.error('Error checking Garmin status:', error)
      return false
    }
  }

  const handleConnectFitbit = async () => {
    setFitbitLoading(true)
    try {
      // Open Fitbit OAuth in a popup window so users can still see Helfi
      const width = 600
      const height = 700
      const left = window.screen.width / 2 - width / 2
      const top = window.screen.height / 2 - height / 2

      const popup = window.open(
        '/api/auth/fitbit/authorize',
        'Fitbit Authorization',
        `width=${width},height=${height},left=${left},top=${top},toolbar=no,menubar=no,scrollbars=yes,resizable=yes`
      )

      if (!popup) {
        alert('Please allow popups for this site to connect Fitbit')
        setFitbitLoading(false)
        return
      }

      popupRef.current = popup

      // Check if popup is closed (user cancelled)
      const checkClosed = setInterval(() => {
        if (popup.closed) {
          clearInterval(checkClosed)
          if (checkIntervalRef.current) {
            clearInterval(checkIntervalRef.current)
            checkIntervalRef.current = null
          }
          setFitbitLoading(false)
          // Check status in case they completed it quickly
          setTimeout(() => checkFitbitStatus(), 1000)
        }
      }, 500)

      // Poll for connection status - check every 2 seconds
      checkIntervalRef.current = setInterval(async () => {
        const connected = await checkFitbitStatus()
        if (connected) {
          clearInterval(checkClosed)
          if (checkIntervalRef.current) {
            clearInterval(checkIntervalRef.current)
            checkIntervalRef.current = null
          }
          // Try to close popup if still open
          if (popup && !popup.closed) {
            try {
              popup.close()
            } catch (e) {
              // Popup might be on different origin, ignore
            }
          }
          setFitbitLoading(false)
        }
      }, 2000)

      // Cleanup after 5 minutes
      setTimeout(() => {
        clearInterval(checkClosed)
        if (checkIntervalRef.current) {
          clearInterval(checkIntervalRef.current)
          checkIntervalRef.current = null
        }
        setFitbitLoading(false)
      }, 300000)
    } catch (error) {
      console.error('Error connecting Fitbit:', error)
      alert('Failed to connect Fitbit. Please try again.')
      setFitbitLoading(false)
    }
  }

  // Cleanup intervals on unmount
  useEffect(() => {
    return () => {
      if (checkIntervalRef.current) {
        clearInterval(checkIntervalRef.current)
      }
    }
