type MealCategory = 'breakfast' | 'lunch' | 'dinner' | 'snacks' | 'uncategorized'

const FOOD_IMAGE_ACCEPT = 'image/*,.avif,.webp,.web'

type NormalizedFoodItem = {
  source: 'openfoodfacts' | 'usda' | 'fatsecret' | 'custom'
  id: string
  name: string
  brand?: string | null
  serving_size?: string | null
  calories?: number | null
  protein_g?: number | null
  carbs_g?: number | null
  fat_g?: number | null
  fiber_g?: number | null
  sugar_g?: number | null
  __suggestion?: boolean
  __searchQuery?: string
}

type ServingOption = {
  id: string
  label?: string | null
  serving_size?: string | null
  grams?: number | null
  ml?: number | null
  calories?: number | null
  protein_g?: number | null
  carbs_g?: number | null
  fat_g?: number | null
  fiber_g?: number | null
  sugar_g?: number | null
  source?: string | null
}

type BuilderUnit =
  | 'g'
  | 'ml'
  | 'oz'
  | 'tsp'
  | 'tbsp'
  | 'quarter-cup'
  | 'half-cup'
  | 'three-quarter-cup'
  | 'cup'
  | 'pinch'
  | 'handful'
  | 'piece'
  | 'piece-small'
  | 'piece-medium'
  | 'piece-large'
  | 'piece-extra-large'
  | 'egg-small'
  | 'egg-medium'
  | 'egg-large'
  | 'egg-extra-large'
  | 'slice'
  | 'serving'

type PortionUnit = 'serving' | 'g' | 'oz'

