const buildTodayIso = () => {
  const d = new Date()
  const y = d.getFullYear()
  const m = String(d.getMonth() + 1).padStart(2, '0')
  const day = String(d.getDate()).padStart(2, '0')
  return `${y}-${m}-${day}`
}

const round3 = (n: number) => Math.round(n * 1000) / 1000

const computeTotalsFromItems = (items: RecommendedItem[]): MacroTotals => computeRecommendedTotals(items)

const alignTimestampToLocalDate = (iso: string, localDate: string) => {
  try {
    if (!localDate || localDate.length < 8) return iso
    const base = new Date(iso)
    if (Number.isNaN(base.getTime())) return iso
    const [y, m, d] = localDate.split('-').map((v) => parseInt(v, 10))
    if (!Number.isFinite(y) || !Number.isFinite(m) || !Number.isFinite(d)) return iso
    const anchored = new Date(y, m - 1, d, base.getHours(), base.getMinutes(), base.getSeconds(), base.getMilliseconds())
    return anchored.toISOString()
  } catch {
    return iso
  }
}

const normalizeTotalsForFoodLog = (totals: MacroTotals) => recommendedFoodLogTotals(totals)

const parseFractionToken = (value: string) => {
  const raw = String(value || '').trim()
  const m = raw.match(/^(\d+)\s*\/\s*(\d+)$/)
  if (!m) return null
  const top = Number(m[1])
  const bottom = Number(m[2])
  if (!Number.isFinite(top) || !Number.isFinite(bottom) || bottom <= 0) return null
  return top / bottom
}

const parseLeadingAmount = (servingSize: string): { amount: number | null; rest: string } => {
  const s = String(servingSize || '').trim()
  if (!s) return { amount: null, rest: '' }
  const mixed = s.match(/^(\d+)\s+(\d+\/\d+)\s+(.*)$/)
  if (mixed) {
    const whole = Number(mixed[1])
    const frac = parseFractionToken(mixed[2])
    if (Number.isFinite(whole) && frac !== null) return { amount: whole + frac, rest: String(mixed[3] || '').trim() }
  }
  const frac = s.match(/^(\d+\/\d+)\s+(.*)$/)
  if (frac) {
    const parsed = parseFractionToken(frac[1])
    if (parsed !== null) return { amount: parsed, rest: String(frac[2] || '').trim() }
  }
  const plain = s.match(/^(\d+(?:[.,]\d+)?)\s+(.*)$/)
  if (plain) {
    const parsed = Number(String(plain[1]).replace(',', '.'))
    if (Number.isFinite(parsed)) return { amount: parsed, rest: String(plain[2] || '').trim() }
  }
  const compact = s.match(/^(\d+(?:[.,]\d+)?)([a-zA-Z]+)\s*(.*)$/)
  if (compact) {
    const parsed = Number(String(compact[1]).replace(',', '.'))
    if (Number.isFinite(parsed)) {
      const tail = String(compact[3] || '').trim()
      return { amount: parsed, rest: `${String(compact[2] || '').trim()} ${tail}`.trim() }
    }
  }
  return { amount: null, rest: s }
}

const formatImportAmount = (value: number) => {
  const n = round3(value)
  if (!Number.isFinite(n)) return ''
  if (Math.abs(n - Math.round(n)) < 0.0001) return String(Math.round(n))
  return String(n)
}

const buildImportLineFromRecommendedItem = (item: RecommendedItem) => {
  const name = String(item?.name || '').trim()
  if (!name) return ''
  const servings = Number(item?.servings)
  if (!Number.isFinite(servings) || servings <= 0) return ''

  const serving = String(item?.serving_size || '').trim().toLowerCase()
  const parsed = parseLeadingAmount(serving)
  const baseAmount = parsed.amount ?? 1
  const rest = String(parsed.rest || '').trim().toLowerCase()

  const startsWith = (value: string) => rest.startsWith(value)
  const has = (value: string) => rest.includes(value)

  let unit: string | null = null
  if (startsWith('kg') || startsWith('kilogram')) unit = 'kg'
  else if (startsWith('g ') || rest === 'g' || startsWith('gram')) unit = 'g'
  else if (startsWith('ml') || startsWith('milliliter')) unit = 'ml'
  else if (rest === 'l' || startsWith('liter')) unit = 'l'
  else if (startsWith('oz') || startsWith('ounce')) unit = 'oz'
  else if (startsWith('tsp') || startsWith('teaspoon')) unit = 'tsp'
  else if (startsWith('tbsp') || startsWith('tablespoon')) unit = 'tbsp'
  else if (startsWith('cup')) unit = 'cup'
  else if (startsWith('clove')) unit = 'clove'
  else if (startsWith('slice') || startsWith('piece') || startsWith('pc')) unit = 'piece'
  else if (has('egg')) {
    if (has('extra large')) unit = 'extra large egg'
    else if (has('large')) unit = 'large egg'
    else if (has('medium')) unit = 'medium egg'
    else if (has('small')) unit = 'small egg'
    else unit = 'egg'
  }

  if (unit) {
    const amount = formatImportAmount(Math.max(0, servings * Math.max(0.0001, baseAmount)))
    if (amount) return `${amount} ${unit} ${name}`.trim()
  }

  if (Math.abs(servings - 1) < 0.0001) return name
  return `${formatImportAmount(servings)} ${name}`.trim()
}

const buildRecipeImportDraftFromRecommendation = (
  rec: RecommendedMealRecord,
  items: RecommendedItem[],
  categoryLabel: string,
): RecipeImportDraft => {
  const pairs = (Array.isArray(items) ? items : [])
    .slice(0, 60)
    .map((it) => {
      const importLine = buildImportLineFromRecommendedItem(it)
      return { importLine, item: it }
    })
    .filter((pair) => Boolean(pair.importLine))

  const ingredients = pairs.map((pair) => pair.importLine)
  const prefillItems = pairs.map((pair) => ({
    importLine: pair.importLine,
    id: pair.item?.id ? String(pair.item.id) : undefined,
    name: String(pair.item?.name || '').trim() || 'Food',
    serving_size: pair.item?.serving_size || null,
    calories: optionalNutrient(pair.item?.calories),
    protein_g: optionalNutrient(pair.item?.protein_g),
    carbs_g: optionalNutrient(pair.item?.carbs_g),
    fat_g: optionalNutrient(pair.item?.fat_g),
    fiber_g: optionalNutrient(pair.item?.fiber_g),
    sugar_g: optionalNutrient(pair.item?.sugar_g),
  }))

  const recipe = rec?.recipe || null
  const steps = Array.isArray(recipe?.steps)
    ? recipe.steps.map((step) => String(step || '').trim()).filter(Boolean).slice(0, 30)
    : []

  const servingsRaw = Number(recipe?.servings)
  const servings = Number.isFinite(servingsRaw) && servingsRaw > 0 ? servingsRaw : null
  const prepRaw = Number(recipe?.prepMinutes)
  const prepMinutes = Number.isFinite(prepRaw) && prepRaw >= 0 ? prepRaw : null
  const cookRaw = Number(recipe?.cookMinutes)
  const cookMinutes = Number.isFinite(cookRaw) && cookRaw >= 0 ? cookRaw : null

  return {
    title: String(rec?.mealName || '').trim() || `AI Recommended ${categoryLabel}`,
    servings,
    prepMinutes,
    cookMinutes,
    ingredients,
    prefillItems,
    steps,
    sourceUrl: null,
    saveRecipe: false,
    createdAt: Date.now(),
  }
}

const formatNumber = (value: number | null | undefined, decimals = 0) => {
  const rounded = roundOptionalNutrient(value, decimals)
  if (rounded == null) return '—'
  return decimals > 0 ? rounded.toFixed(decimals) : String(rounded)
}

const formatMacroValue = (value: number | null | undefined, unit: string, decimals = 0) => {
  const base = formatNumber(value, decimals)
  if (base === '—') return '—'
  return unit ? `${base} ${unit}` : base
}

type RecommendedLastView = {
  key: string
  savedAt: number
  date: string
  category: MealCategory
  active: RecommendedMealRecord | null
  itemsDraft: RecommendedItem[] | null
  activeTab: 'ingredients' | 'recipe' | 'why'
  history: RecommendedMealRecord[]
  seenExplain?: boolean | null
}

type RecommendedLastViewStore = Record<string, RecommendedLastView>

const RECOMMENDED_LAST_VIEW_STORAGE_KEY = 'food:recommended:lastView'
const RECOMMENDED_LAST_VIEW_TTL_MS = 6 * 60 * 60 * 1000
const RECOMMENDED_RESUME_KEY = 'food:resume:last:recommended'

const buildRecommendedViewKey = (date: string, category: MealCategory) => `${date || ''}:${category || ''}`

const readRecommendedLastView = (date: string, category: MealCategory) => {
  if (typeof window === 'undefined') return null
  try {
    const raw = window.sessionStorage.getItem(RECOMMENDED_LAST_VIEW_STORAGE_KEY)
    if (!raw) return null
    const parsed = JSON.parse(raw) as RecommendedLastViewStore
    const key = buildRecommendedViewKey(date, category)
    const entry = parsed?.[key]
    if (!entry || entry.key !== key) return null
    const savedAt = Number(entry.savedAt) || 0
    if (!savedAt || Date.now() - savedAt > RECOMMENDED_LAST_VIEW_TTL_MS) return null
    return entry
  } catch {
    return null
  }
}

const writeRecommendedLastView = (payload: RecommendedLastView) => {
  if (typeof window === 'undefined') return
  try {
    const raw = window.sessionStorage.getItem(RECOMMENDED_LAST_VIEW_STORAGE_KEY)
    const parsed = raw ? (JSON.parse(raw) as RecommendedLastViewStore) : {}
    parsed[payload.key] = payload
    window.sessionStorage.setItem(RECOMMENDED_LAST_VIEW_STORAGE_KEY, JSON.stringify(parsed))
  } catch {
    // Ignore storage errors
  }
}

const readRecommendedResumeStamp = (): number => {
  if (typeof window === 'undefined') return 0
  try {
    const raw = window.sessionStorage.getItem(RECOMMENDED_RESUME_KEY)
    const parsed = raw ? Number(raw) : 0
    return Number.isFinite(parsed) ? parsed : 0
  } catch {
    return 0
  }
}

const shouldRefreshOnResume = (): boolean => {
  if (typeof window === 'undefined') return false
  const hiddenAt = readAppHiddenAt()
  if (!hiddenAt) return false
  const lastHandled = readRecommendedResumeStamp()
  return hiddenAt > lastHandled
}

const markResumeHandled = () => {
  if (typeof window === 'undefined') return
  try {
    window.sessionStorage.setItem(RECOMMENDED_RESUME_KEY, String(Date.now()))
  } catch {}
}

export default function RecommendedMealClient() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const { userData, updateUserData } = useUserData()
  const userCountry = String(userData?.country || '').trim()

  const date = searchParams.get('date') || buildTodayIso()
  const category = normalizeMealCategory(searchParams.get('category'))
  const freshKey = searchParams.get('fresh') || ''
  const categoryLabel = CATEGORY_LABELS[category]
  const cachedLastView = useMemo(() => readRecommendedLastView(date, category), [date, category])

  const [loadingContext, setLoadingContext] = useState(true)
  const [generating, setGenerating] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [history, setHistory] = useState<RecommendedMealRecord[]>(() => cachedLastView?.history || [])
  const [active, setActive] = useState<RecommendedMealRecord | null>(() => cachedLastView?.active || null)
  const [itemsDraft, setItemsDraft] = useState<RecommendedItem[] | null>(() => cachedLastView?.itemsDraft || null)
  const [savingDiary, setSavingDiary] = useState(false)
  const [openingBuilder, setOpeningBuilder] = useState(false)
  const [seenExplain, setSeenExplain] = useState<boolean | null>(() =>
    typeof cachedLastView?.seenExplain === 'boolean' ? cachedLastView.seenExplain : null,
  )
  const [commitSaving, setCommitSaving] = useState(false)
  const [activeTab, setActiveTab] = useState<'ingredients' | 'recipe' | 'why'>(() => cachedLastView?.activeTab || 'ingredients')
  const [resumeTick, setResumeTick] = useState(0)
  const skipActiveResetRef = useRef(false)

  const tzOffsetMin = useMemo(() => String(new Date().getTimezoneOffset()), [])

  useEffect(() => {
    if (typeof document === 'undefined') return
    const handleVisibility = () => {
      if (document.visibilityState !== 'visible') return
      if (!readAppHiddenAt()) return
      setResumeTick((prev) => prev + 1)
    }
    document.addEventListener('visibilitychange', handleVisibility)
    return () => document.removeEventListener('visibilitychange', handleVisibility)
  }, [])

  const draftTotals = useMemo(() => {
    const items = itemsDraft || active?.items || []
    return computeTotalsFromItems(items)
  }, [itemsDraft, active?.items])

  const costCredits = AI_MEAL_RECOMMENDATION_CREDITS
  const hasRecommendation = Boolean(active)
  const activeIsCommitted = useMemo(() => {
    if (!active?.id) return false
    return history.some((h) => h && h.id === active.id)
  }, [active?.id, history])

  const load = async (preserveActive: boolean, markResume: boolean) => {
    setLoadingContext(true)
    setError(null)
    try {
      const qs = new URLSearchParams()
      qs.set('date', date)
      qs.set('category', category)
      qs.set('tz', tzOffsetMin)
      const res = await fetch(`/api/ai-meal-recommendation?${qs.toString()}`, { cache: 'no-store' })
      if (!res.ok) {
        const txt = await res.text().catch(() => '')
        throw new Error(txt || `Load failed (${res.status})`)
      }
      const data = (await res.json()) as ApiGetResponse
      setSeenExplain(typeof data.seenExplain === 'boolean' ? data.seenExplain : null)
      const nextHistory = Array.isArray(data.history) ? data.history : []
      setHistory(nextHistory)
      if (!preserveActive) {
        setActive(null)
        setItemsDraft(null)
      }
      if (markResume) {
        markResumeHandled()
      }
    } catch (e: any) {
      setError(e?.message || 'Unable to load recommendations right now.')
    } finally {
      setLoadingContext(false)
    }
  }

  const generate = async () => {
    setGenerating(true)
    setError(null)
    try {
      const res = await fetch('/api/ai-meal-recommendation', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ date, category, tz: tzOffsetMin }),
      })
      if (res.status === 402) {
        setError(`Not enough credits to generate. This costs ${costCredits} credits.`)
        return
      }
      if (!res.ok) {
        const payload = await res.json().catch(() => null)
        const msgFromJson =
          typeof payload?.error === 'string'
            ? payload.error
            : typeof payload?.message === 'string'
              ? payload.message
              : null
        if (msgFromJson) throw new Error(msgFromJson)
        const txt = await res.text().catch(() => '')
        try {
          const parsed = txt ? JSON.parse(txt) : null
          const msgFromText =
            typeof parsed?.error === 'string'
              ? parsed.error
              : typeof parsed?.message === 'string'
                ? parsed.message
                : null
          if (msgFromText) throw new Error(msgFromText)
        } catch {}
        throw new Error(txt || `Generate failed (${res.status})`)
      }
      const data = (await res.json()) as ApiPostResponse
      setHistory(Array.isArray(data.history) ? data.history : [])
      setActive(data.recommendation || null)
      setSeenExplain(true)
      setItemsDraft(null)
      try {
        window.dispatchEvent(new Event('credits:refresh'))
      } catch {}
    } catch (e: any) {
      setError(e?.message || 'Unable to generate a recommendation right now.')
    } finally {
      setGenerating(false)
    }
  }

  const setActiveFromHistory = (record: RecommendedMealRecord) => {
    setError(null)
    setActive(record)
    setItemsDraft(null)
  }

  useEffect(() => {
    setError(null)
    const cached = readRecommendedLastView(date, category)
    const shouldPreserve = Boolean(cached?.active)
    const shouldResumeRefresh = shouldRefreshOnResume()
    const hasCached = Boolean(
      (cached?.active && cached.active.items && cached.active.items.length > 0) ||
        (cached?.history && cached.history.length > 0),
    )
    const isManualRefresh = Boolean(freshKey)
    if (cached && !isManualRefresh) {
      skipActiveResetRef.current = true
      if (Array.isArray(cached.history)) setHistory(cached.history)
      setActive(cached.active || null)
      setItemsDraft(cached.itemsDraft || null)
      if (cached.activeTab) setActiveTab(cached.activeTab)
      if (typeof cached.seenExplain === 'boolean') setSeenExplain(cached.seenExplain)
    } else {
      setActive(null)
      setItemsDraft(null)
    }
    const shouldLoad = isManualRefresh || !hasCached || shouldResumeRefresh
    if (!shouldLoad) {
      setLoadingContext(false)
      return
    }
    load(shouldPreserve && !isManualRefresh, shouldResumeRefresh)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [date, category, freshKey, resumeTick])

  useEffect(() => {
    // New date/category should be treated as a fresh screen.
    const cached = readRecommendedLastView(date, category)
    if (cached?.activeTab) {
      setActiveTab(cached.activeTab)
      return
    }
    setActiveTab('ingredients')
  }, [date, category])

  useEffect(() => {
    if (loadingContext) return
    if (seenExplain === null) return
    if (seenExplain) return
    // First-time: force the disclosure screen before generating anything.
    const qs = new URLSearchParams()
    qs.set('date', date)
    qs.set('category', category)
    qs.set('returnTo', `/food/recommended?date=${encodeURIComponent(date)}&category=${encodeURIComponent(category)}`)
    router.replace(`/food/recommended/explain?${qs.toString()}`)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loadingContext, seenExplain, date, category])

  useEffect(() => {
    if (skipActiveResetRef.current) {
      skipActiveResetRef.current = false
      return
    }
    setItemsDraft(null)
    setActiveTab('ingredients')
  }, [active?.id])

  useEffect(() => {
    const payload: RecommendedLastView = {
      key: buildRecommendedViewKey(date, category),
      savedAt: Date.now(),
      date,
      category,
      active,
      itemsDraft,
      activeTab,
      history: Array.isArray(history) ? history.slice(0, 12) : [],
      seenExplain,
    }
    writeRecommendedLastView(payload)
  }, [date, category, active, itemsDraft, activeTab, history, seenExplain])

  const currentItems = itemsDraft || active?.items || []

  const mealMacroRows = useMemo(() => {
    const calories = typeof draftTotals.calories === 'number' ? Math.round(draftTotals.calories) : null
    const protein = typeof draftTotals.protein_g === 'number' ? draftTotals.protein_g : null
    const carbs = typeof draftTotals.carbs_g === 'number' ? draftTotals.carbs_g : null
    const fat = typeof draftTotals.fat_g === 'number' ? draftTotals.fat_g : null
    const fiber = typeof draftTotals.fiber_g === 'number' ? draftTotals.fiber_g : null
    const sugar = typeof draftTotals.sugar_g === 'number' ? draftTotals.sugar_g : null

    const macroValues = [protein, carbs, fat, fiber, sugar].filter((v): v is number => typeof v === 'number' && v > 0)
    const maxMacro = macroValues.length > 0 ? Math.max(...macroValues) : 0

    return [
      {
        key: 'calories',
        label: 'Calories',
        display: formatMacroValue(calories, 'kcal'),
        color: '#10b981',
        percent: calories && calories > 0 ? 1 : 0,
      },
      {
        key: 'protein',
        label: 'Protein',
        display: formatMacroValue(protein, 'g', 1),
        color: '#ef4444',
        percent: maxMacro > 0 && typeof protein === 'number' ? protein / maxMacro : 0,
      },
      {
        key: 'carbs',
        label: 'Carbs',
        display: formatMacroValue(carbs, 'g', 1),
        color: '#22c55e',
        percent: maxMacro > 0 && typeof carbs === 'number' ? carbs / maxMacro : 0,
      },
      {
        key: 'fat',
        label: 'Fat',
        display: formatMacroValue(fat, 'g', 1),
        color: '#6366f1',
        percent: maxMacro > 0 && typeof fat === 'number' ? fat / maxMacro : 0,
      },
      {
        key: 'fiber',
        label: 'Fiber',
        display: formatMacroValue(fiber, 'g', 1),
        color: '#12adc9',
        percent: maxMacro > 0 && typeof fiber === 'number' ? fiber / maxMacro : 0,
      },
      {
        key: 'sugar',
        label: 'Sugar',
        display: formatMacroValue(sugar, 'g', 1),
        color: '#f97316',
        percent: maxMacro > 0 && typeof sugar === 'number' ? sugar / maxMacro : 0,
      },
    ].filter((row) => row.display !== '—')
  }, [draftTotals])

  const updateServings = (index: number, next: number) => {
    const safe = Number.isFinite(next) ? Math.max(0, Math.min(20, next)) : 0
    setItemsDraft((prev) => {
      const base = prev ? [...prev] : currentItems.map((it) => ({ ...it }))
      const nextItems = base.map((it, idx) => (idx === index ? { ...it, servings: safe } : it))
      return nextItems
    })
  }

  const saveToFavorites = async () => {
    if (!active) return
    const nutritionError = recommendationNutritionError(currentItems)
    if (nutritionError) { setError(nutritionError); return }
    const totals = draftTotals
    const favorites = Array.isArray((userData as any)?.favorites) ? ((userData as any).favorites as any[]) : []
    const payload = {
      id: `fav-${Date.now()}`,
      sourceId: null,
      label: active.mealName || `AI Recommended ${categoryLabel}`,
      description: active.mealName || `AI Recommended ${categoryLabel}`,
      nutrition: normalizeTotalsForFoodLog(totals),
      total: normalizeTotalsForFoodLog(totals),
      items: currentItems,
      recipe: active.recipe || null,
      photo: null,
      method: 'ai-recommended',
      meal: category,
      createdAt: Date.now(),
    }
    const existingIndex = favorites.findIndex((fav: any) => fav?.label && payload.label && fav.label === payload.label)
    const nextFavorites = existingIndex >= 0 ? favorites.map((f: any, i: number) => (i === existingIndex ? { ...payload, id: f.id || payload.id } : f)) : [...favorites, payload]
    updateUserData({ favorites: nextFavorites })
    try {
      await fetch('/api/user-data', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ favorites: nextFavorites }),
      })
    } catch {}

    // Persist this recommendation into AI history only after the user saves.
    try {
      setCommitSaving(true)
      const res = await fetch('/api/ai-meal-recommendation', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'commit',
          recommendation: {
            ...active,
            items: currentItems,
            totals: draftTotals,
            date,
            category,
          },
        }),
      })
      if (res.ok) {
        const data = (await res.json().catch(() => null)) as any
        if (data?.history && Array.isArray(data.history)) setHistory(data.history)
      }
    } catch {
    } finally {
      setCommitSaving(false)
    }
  }

  const addToDiary = async () => {
    if (!active) return
    const nutritionError = recommendationNutritionError(currentItems)
    if (nutritionError) { setError(nutritionError); return }
    const totals = normalizeTotalsForFoodLog(draftTotals)
    const nutritionPayload = {
      ...totals,
      __origin: 'ai-recommended',
      __aiRecipe: active.recipe || null,
      __aiWhy: active.why || '',
      __aiMealId: active.id || '',
    }
    const createdAtIso = alignTimestampToLocalDate(new Date().toISOString(), date)
    const payload = {
      description: active.mealName || `AI Recommended ${categoryLabel}`,
      nutrition: nutritionPayload,
      imageUrl: null,
      items: currentItems,
      localDate: date,
      meal: category,
      category,
      createdAt: createdAtIso,
    }
    setSavingDiary(true)
    try {
      const res = await fetch('/api/food-log', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })
      if (!res.ok) {
        setError('Saving failed. Please try again.')
        return
      }

      // Persist this recommendation into AI history only after the user saves.
      try {
        setCommitSaving(true)
        const commitRes = await fetch('/api/ai-meal-recommendation', {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            action: 'commit',
            recommendation: {
              ...active,
              items: currentItems,
              totals: draftTotals,
              date,
              category,
            },
          }),
        })
        if (commitRes.ok) {
          const data = (await commitRes.json().catch(() => null)) as any
          if (data?.history && Array.isArray(data.history)) setHistory(data.history)
        }
      } catch {}

      const qs = new URLSearchParams()
      qs.set('date', date)
      qs.set('refresh', '1')
      qs.set('refreshAt', String(Date.now()))
      router.push(`/food?${qs.toString()}`)
    } catch {
      setError('Saving failed. Please try again.')
    } finally {
      setCommitSaving(false)
      setSavingDiary(false)
    }
  }

  // PROTECTED: RECOMMENDED_MEAL_BUILD_HANDOFF START
  const openInMealBuilder = () => {
    if (!active) return
    const draft = buildRecipeImportDraftFromRecommendation(active, currentItems, categoryLabel)
    if (draft.ingredients.length === 0 && draft.steps.length === 0) {
      setError('This recommendation has no importable ingredients yet. Please generate another meal.')
      return
    }
    setError(null)
    try {
      // Reuse the existing Recipe Import pipeline so Build a meal shows live matching progress.
      sessionStorage.setItem('food:recipeImportDraft', JSON.stringify(draft))
    } catch {
      setError('Could not open Build a meal right now. Please try again.')
      return
    }
    setOpeningBuilder(true)
    const qs = new URLSearchParams()
    qs.set('date', date)
    qs.set('category', category)
    qs.set('recipeImport', '1')
    qs.set('t', String(Date.now()))
    router.push(`/food/build-meal?${qs.toString()}`)
  }
  // PROTECTED: RECOMMENDED_MEAL_BUILD_HANDOFF END

  const pageTitle = `AI Recommended ${categoryLabel}`

  const recipeMeta = useMemo(() => {
    const recipe = active?.recipe
    if (!recipe) return null
    const parts: string[] = []
    if (typeof recipe.prepMinutes === 'number' && Number.isFinite(recipe.prepMinutes)) parts.push(`Prep ${Math.round(recipe.prepMinutes)} min`)
    if (typeof recipe.cookMinutes === 'number' && Number.isFinite(recipe.cookMinutes)) parts.push(`Cook ${Math.round(recipe.cookMinutes)} min`)
    if (typeof recipe.servings === 'number' && Number.isFinite(recipe.servings)) parts.push(`${Math.round(recipe.servings)} serving${Math.round(recipe.servings) === 1 ? '' : 's'}`)
    return parts.length > 0 ? parts.join(' • ') : null
  }, [active?.recipe])

  // PROTECTED: RECOMMENDED_MEAL_BUILD_BUTTON_ROW START
  const ActionButtons = ({ className }: { className?: string }) => (
