}

const MAX_IMAGE_BYTES = 6 * 1024 * 1024
const MAX_AUDIO_BYTES = 12 * 1024 * 1024
const MAX_MEDIA_ITEMS = 6
const AUDIO_INPUT_STORAGE_KEY = 'helfi-health-journal-audio-input-id'
const AUDIO_OUTPUT_STORAGE_KEY = 'helfi-health-journal-audio-output-id'

function trimSummary(value: string, fallback: string) {
  const clean = String(value || '').replace(/\s+/g, ' ').trim()
  if (!clean) return fallback
  return clean.slice(0, 320)
}

function buildMediaId() {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID()
  }
  return `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
}

function mergeContentWithMediaNotes(content: string, summaries: string[]) {
  const base = String(content || '').trim()
  const cleaned = summaries.map((item) => trimSummary(item, '')).filter(Boolean)
  if (!cleaned.length) return base
  const list = cleaned.map((item, index) => `${index + 1}. ${item}`).join('\n')
  const block = `Media notes (auto-summarized):\n${list}`
  return [base, block].filter(Boolean).join('\n\n').trim()
}

function audioMimeFromName(name: string) {
  const lower = String(name || '').toLowerCase()
  if (lower.endsWith('.mp3')) return 'audio/mpeg'
  if (lower.endsWith('.wav')) return 'audio/wav'
  if (lower.endsWith('.m4a')) return 'audio/mp4'
  if (lower.endsWith('.aac')) return 'audio/aac'
  return 'audio/webm'
}

async function detectSilentAudio(blob: Blob): Promise<boolean> {
  try {
    if (typeof window === 'undefined') return false
    const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext
    if (!AudioContextClass) return false

    const context = new AudioContextClass()
    try {
      const arrayBuffer = await blob.arrayBuffer()
      const decoded = await context.decodeAudioData(arrayBuffer.slice(0))
      let energy = 0
      let sampleCount = 0
      for (let channel = 0; channel < decoded.numberOfChannels; channel += 1) {
        const data = decoded.getChannelData(channel)
        const step = Math.max(1, Math.floor(data.length / 12000))
        for (let i = 0; i < data.length; i += step) {
          const value = data[i]
          energy += value * value
          sampleCount += 1
        }
      }
      const rms = Math.sqrt(energy / Math.max(sampleCount, 1))
      return rms < 0.004
    } finally {
      await context.close().catch(() => {})
    }
  } catch {
    return false
  }
}

function buildTodayIso() {
  const now = new Date()
  const yyyy = now.getFullYear()
  const mm = String(now.getMonth() + 1).padStart(2, '0')
  const dd = String(now.getDate()).padStart(2, '0')
  return `${yyyy}-${mm}-${dd}`
}

function formatShortDayLabel(iso: string) {
  try {
    const [y, m, d] = iso.split('-').map((v) => parseInt(v, 10))
    const local = new Date(y, (m || 1) - 1, d || 1)
    return local.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })
  } catch {
    return iso
  }
}

function formatTimeLabel(iso: string) {
  const date = new Date(iso)
  if (Number.isNaN(date.getTime())) return ''
  return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
}

