import { useEffect, useMemo, useState } from 'react'
import Link from 'next/link'
import Image from 'next/image'
import { signOut } from 'next-auth/react'
import { useUserData } from '@/components/providers/UserDataProvider'
import { UserIcon } from '@heroicons/react/24/outline'

export const DEFAULT_INSIGHTS_AVATAR = '' // no longer used; kept for backward compatibility

interface InsightsTopNavProps {
  sessionUser: {
    name: string | null
    email: string | null
    image: string | null
  }
}

export default function InsightsTopNav({ sessionUser }: InsightsTopNavProps) {
  const { profileImage: providerProfileImage } = useUserData()
  const [dropdownOpen, setDropdownOpen] = useState(false)
  const [affiliateMenu, setAffiliateMenu] = useState<{ label: string; href: string } | null>(null)
  const [unreadCount, setUnreadCount] = useState(0)

  const hasProfileImage = useMemo(
    () => !!(providerProfileImage || sessionUser.image),
    [providerProfileImage, sessionUser.image]
  )
  const avatarSrc = useMemo(() => {
    return (providerProfileImage || sessionUser.image || '') as string
  }, [providerProfileImage, sessionUser.image])

  useEffect(() => {
    function handleClick(e: MouseEvent) {
      const target = e.target as HTMLElement
      if (!target.closest('.dropdown-container')) {
        setDropdownOpen(false)
      }
    }
    if (dropdownOpen) {
      document.addEventListener('mousedown', handleClick)
      return () => document.removeEventListener('mousedown', handleClick)
    }
  }, [dropdownOpen])

  useEffect(() => {
    if (!sessionUser?.email) {
      setAffiliateMenu(null)
      return
    }
    let cancelled = false
    setAffiliateMenu({ label: 'Become an Affiliate', href: '/affiliate/apply' })
    const loadAffiliateMenu = async () => {
      try {
        const res = await fetch('/api/affiliate/application', { cache: 'no-store' })
        const data = await res.json().catch(() => ({} as any))
        if (!res.ok) return
        const hasAffiliate = !!data?.affiliate
        const hasApplication = !!data?.application
        const menu = hasAffiliate
          ? { label: 'Affiliate Portal', href: '/affiliate' }
          : hasApplication
            ? { label: 'Affiliate Application', href: '/affiliate/apply' }
            : { label: 'Become an Affiliate', href: '/affiliate/apply' }
        if (!cancelled) setAffiliateMenu(menu)
      } catch {
        // ignore
      }
    }
    loadAffiliateMenu()
    return () => {
      cancelled = true
    }
  }, [sessionUser?.email])

  useEffect(() => {
    if (!sessionUser?.email) return
    let mounted = true
    const loadUnread = async () => {
      try {
        const res = await fetch('/api/notifications/unread-count', { cache: 'no-store' as any })
        if (!res.ok) return
        const data = await res.json().catch(() => ({}))
        if (mounted) {
          const count = typeof data?.count === 'number' ? data.count : 0
          setUnreadCount(Number.isFinite(count) ? count : 0)
        }
      } catch {
        // ignore
      }
    }
    loadUnread()

    const handleRefresh = () => loadUnread()
    window.addEventListener('focus', handleRefresh)
    window.addEventListener('notifications:refresh', handleRefresh)
    return () => {
      mounted = false
      window.removeEventListener('focus', handleRefresh)
      window.removeEventListener('notifications:refresh', handleRefresh)
    }
  }, [sessionUser?.email])

  return (
    <nav className="bg-white border-b border-gray-200 px-4 py-3">
      <div className="max-w-7xl mx-auto flex justify-between items-center">
        {/* Page Title - Mobile only (desktop has sidebar) */}
        <h1 className="md:hidden flex-1 text-center text-lg font-semibold text-gray-900">Insights</h1>
        <div className="hidden md:block"></div>

        {/* Profile Avatar & Dropdown */}
        <div className="relative dropdown-container" id="insights-profile-dropdown">
          <button
            onClick={() => setDropdownOpen((v) => !v)}
            className="focus:outline-none"
            aria-label="Open profile menu"
          >
            <div className="relative">
              {hasProfileImage ? (
                <Image
                  src={avatarSrc}
                  alt="Profile"
                  width={48}
                  height={48}
                  className="w-12 h-12 rounded-full border-2 border-helfi-green shadow-sm object-cover"
                />
              ) : (
                <div className="w-12 h-12 rounded-full bg-helfi-green shadow-sm flex items-center justify-center">
                  <UserIcon className="w-6 h-6 text-white" aria-hidden="true" />
                </div>
              )}
              {unreadCount > 0 && (
                <span className="absolute -top-1 -right-1 min-w-[18px] px-1 h-[18px] rounded-full bg-red-500 text-white text-[10px] font-semibold flex items-center justify-center shadow">
                  {unreadCount > 99 ? '99+' : unreadCount}
                </span>
              )}
            </div>
          </button>
          {dropdownOpen && (
            <div className="absolute right-0 mt-2 w-64 bg-white rounded-xl shadow-lg py-2 z-50 border border-gray-100">
              <div className="flex items-center px-4 py-3 border-b border-gray-100">
                {hasProfileImage ? (
                  <Image
                    src={avatarSrc}
                    alt="Profile"
                    width={40}
                    height={40}
                    className="w-10 h-10 rounded-full object-cover mr-3"
                  />
                ) : (
                  <div className="w-10 h-10 rounded-full bg-helfi-green flex items-center justify-center mr-3">
                    <UserIcon className="w-6 h-6 text-white" aria-hidden="true" />
                  </div>
                )}
                <div>
                  <div className="font-semibold text-gray-900">{sessionUser.name || 'User'}</div>
                  <div className="text-xs text-gray-500">{sessionUser.email || 'user@email.com'}</div>
                </div>
              </div>
              <Link href="/profile" className="block px-4 py-2 text-gray-700 hover:bg-gray-50">Profile</Link>
              <Link href="/account" className="block px-4 py-2 text-gray-700 hover:bg-gray-50">Account Settings</Link>
              <Link href="/profile/image" className="block px-4 py-2 text-gray-700 hover:bg-gray-50">Upload/Change Profile Photo</Link>
              <Link href="/billing" className="block px-4 py-2 text-gray-700 hover:bg-gray-50">Subscription & Billing</Link>
              {affiliateMenu && (
                <Link href={affiliateMenu.href} className="block px-4 py-2 text-gray-700 hover:bg-gray-50">
                  {affiliateMenu.label}
                </Link>
              )}
              <Link href="/notifications" className="block px-4 py-2 text-gray-700 hover:bg-gray-50">Notifications</Link>
              <Link href="/help" className="block px-4 py-2 text-gray-700 hover:bg-gray-50">Help & Support</Link>
              <button
                onClick={() => signOut({ callbackUrl: '/auth/signin' })}
                className="block w-full text-left px-4 py-2 text-red-600 hover:bg-gray-50 font-semibold"
              >
                Logout
              </button>
            </div>
          )}
        </div>
      </div>
    </nav>
  )
}

