'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import type { IssueSectionKey } from '@/lib/insights/issue-engine'

interface IssueSectionNavProps {
  issueSlug: string
  sections: IssueSectionKey[]
}

const LABELS: Record<IssueSectionKey, string> = {
  overview: 'Overview',
  exercise: 'Exercise',
  supplements: 'Supplements',
  medications: 'Medications',
  interactions: 'Supplements × Meds',
  labs: 'Labs & Bloodwork',
  nutrition: 'Nutrition & Food',
  lifestyle: 'Lifestyle',
}

export default function IssueSectionNav({ issueSlug, sections }: IssueSectionNavProps) {
  const pathname = usePathname()
  return (
    <div className="flex items-center gap-2 overflow-x-auto pb-2">
      {sections.map((section) => {
        const overviewPath = `/insights/issues/${issueSlug}`
        const href = section === 'overview' ? `${overviewPath}/overview` : `/insights/issues/${issueSlug}/${section}`
        const isOverviewActive = section === 'overview' && (pathname === overviewPath || pathname === `${overviewPath}/overview`)
        const isSectionActive = pathname === href || pathname.startsWith(`${href}/`)
        const isActive = isOverviewActive || isSectionActive
        return (
          <Link
            key={section}
            href={href}
            className={`px-4 py-2 rounded-full border text-sm font-semibold whitespace-nowrap transition-colors ${
              isActive ? 'bg-helfi-green text-white border-helfi-green shadow-sm' : 'bg-white text-gray-700 border-gray-200 hover:border-helfi-green hover:text-helfi-green'
            }`}
            onClick={() => {
              try {
                const reduced = window.matchMedia('(prefers-reduced-motion: reduce)')?.matches
                const pref = localStorage.getItem('hapticsEnabled')
                const enabled = pref === null ? true : pref === 'true'
                if (!reduced && enabled && 'vibrate' in navigator) {
                  navigator.vibrate(8)
                }
              } catch {
                // ignore haptic errors
              }
            }}
          >
            {LABELS[section] ?? section}
          </Link>
        )
      })}
    </div>
  )
}

'use client'

import { FormEvent, KeyboardEvent, useEffect, useLayoutEffect, useMemo, useRef, useState, useCallback, type PointerEvent } from 'react'
import { createPortal } from 'react-dom'
import { formatChatContent } from '@/lib/chatFormatting'

interface SectionChatProps {
  issueSlug: string
  section: string
  issueName: string
}

type ChatMessage = { role: 'user' | 'assistant'; content: string }
type ChatThread = {
  id: string
  title: string | null
  archivedAt?: string | null
  lastChargedCost?: number | null
  lastChargedAt?: string | null
  lastChargeCovered?: boolean | null
  createdAt: string
  updatedAt: string
}

const COST_PREFIX = '__cost__'

export default function SectionChat({ issueSlug, section, issueName }: SectionChatProps) {
  const [messages, setMessages] = useState<ChatMessage[]>([])
  const [input, setInput] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [isListening, setIsListening] = useState(false)
  const [threads, setThreads] = useState<ChatThread[]>([])
  const [threadId, setThreadId] = useState<string | null>(null)
  const [threadsOpen, setThreadsOpen] = useState(false)
  const [renameOpen, setRenameOpen] = useState(false)
  const [renameValue, setRenameValue] = useState('')
  const [renameCleared, setRenameCleared] = useState(false)
  const [hasSpeechRecognition, setHasSpeechRecognition] = useState(false)
  const [expanded, setExpanded] = useState(false)
  const [actionThreadId, setActionThreadId] = useState<string | null>(null)
  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false)
  const [deletePending, setDeletePending] = useState(false)
  const containerRef = useRef<HTMLDivElement | null>(null)
  const textareaRef = useRef<HTMLTextAreaElement | null>(null)
  const enabled = (process.env.NEXT_PUBLIC_INSIGHTS_CHAT || 'true').toLowerCase() === 'true' || (process.env.NEXT_PUBLIC_INSIGHTS_CHAT || '') === '1'
  const recognitionRef = useRef<any>(null)
  const resizeRafRef = useRef<number | null>(null)
  const [isClient, setIsClient] = useState(false)
  const longPressTimerRef = useRef<number | null>(null)
  const longPressTriggeredRef = useRef(false)

  const currentThreadTitle = useMemo(() => {
    if (!threadId) return 'New chat'
    return threads.find((thread) => thread.id === threadId)?.title || 'New chat'
  }, [threadId, threads])

  const currentCharge = useMemo(() => {
    if (!threadId) return null
    const thread = threads.find((item) => item.id === threadId)
    if (!thread || typeof thread.lastChargedCost !== 'number') return null
    return {
      cost: thread.lastChargedCost,
      covered: Boolean(thread.lastChargeCovered),
      at: thread.lastChargedAt || '',
    }
  }, [threadId, threads])

  const actionThread = actionThreadId ? threads.find((thread) => thread.id === actionThreadId) : null
  const actionThreadArchived = actionThreadId ? Boolean(actionThread?.archivedAt) : false

  const threadGroups = useMemo(() => {
    const startOfToday = new Date()
    startOfToday.setHours(0, 0, 0, 0)
    const visibleThreads = threads.filter((thread) => !thread.archivedAt)
    const groups = {
      today: [] as ChatThread[],
      yesterday: [] as ChatThread[],
      week: [] as ChatThread[],
      older: [] as ChatThread[],
    }
    visibleThreads.forEach((thread) => {
      const updated = new Date(thread.updatedAt)
      updated.setHours(0, 0, 0, 0)
      const diffDays = Math.floor((startOfToday.getTime() - updated.getTime()) / 86400000)
      if (diffDays <= 0) {
        groups.today.push(thread)
      } else if (diffDays === 1) {
        groups.yesterday.push(thread)
      } else if (diffDays < 7) {
        groups.week.push(thread)
      } else {
        groups.older.push(thread)
      }
    })
    return [
      { label: 'Today', items: groups.today },
      { label: 'Yesterday', items: groups.yesterday },
      { label: 'Previous 7 days', items: groups.week },
      { label: 'Older', items: groups.older },
    ]
  }, [threads])

  const hasThreads = threadGroups.some((group) => group.items.length > 0)
  const archivedThreads = useMemo(
    () => threads.filter((thread) => thread.archivedAt),
    [threads]
  )

  const getApiErrorMessage = useCallback((data: any) => {
    const message =
      (typeof data?.message === 'string' && data.message.trim()) ||
      (typeof data?.error === 'string' && data.error.trim()) ||
      'Sorry, something went wrong. Please try again.'
    if (message === 'server_error') return 'Sorry, something went wrong. Please try again.'
    return message
  }, [])

  const recoverAssistantMessage = useCallback(async (preferredThreadId?: string | null) => {
    try {
      let targetThreadId = preferredThreadId || threadId
      if (!targetThreadId) {
        const threadsRes = await fetch(`/api/insights/issues/${issueSlug}/sections/${section}/threads`, { cache: 'no-store' })
        if (threadsRes.ok) {
          const threadsData = await threadsRes.json()
          const nextThreads = Array.isArray(threadsData?.threads) ? threadsData.threads : []
          if (nextThreads.length) {
            setThreads(nextThreads)
            const nextThread = nextThreads.find((item: ChatThread) => !item.archivedAt) || nextThreads[0]
            targetThreadId = nextThread?.id || null
            if (targetThreadId) setThreadId(targetThreadId)
          }
        }
      }
      if (!targetThreadId) return false
      const messagesRes = await fetch(
        `/api/insights/issues/${issueSlug}/sections/${section}/chat?threadId=${targetThreadId}`,
        { cache: 'no-store' }
      )
      if (!messagesRes.ok) return false
      const messagesData = await messagesRes.json().catch(() => null)
      const messageList = Array.isArray(messagesData?.messages) ? messagesData.messages : []
      const lastAssistant = [...messageList]
        .reverse()
        .find((msg) => msg?.role === 'assistant' && typeof msg?.content === 'string' && msg.content.trim())
      if (!lastAssistant?.content) return false
      setMessages((prev) => {
        const last = prev[prev.length - 1]
        if (last?.role === 'assistant' && last.content === lastAssistant.content) return prev
        return [...prev, { role: 'assistant', content: lastAssistant.content }]
      })
      return true
    } catch {
      return false
    }
  }, [issueSlug, section, threadId])

  // Smooth single-frame resize to prevent jitter when text grows/shrinks quickly
  const resizeTextarea = useCallback(() => {
    if (resizeRafRef.current) cancelAnimationFrame(resizeRafRef.current)
    resizeRafRef.current = requestAnimationFrame(() => {
      const textarea = textareaRef.current
      if (!textarea) return
      const container = containerRef.current
      const shouldStick =
        container && container.scrollHeight - container.scrollTop - container.clientHeight < 24
      const minHeight = 52
      const maxHeight = 200
      textarea.style.height = 'auto'
      const desired = Math.min(Math.max(textarea.scrollHeight, minHeight), maxHeight)
      if (textarea.style.height !== `${desired}px`) {
        textarea.style.height = `${desired}px`
      }
      textarea.style.overflowY = textarea.scrollHeight > maxHeight ? 'auto' : 'hidden'

      // Show expand control when textarea height exceeds ~3-4 lines (around 156px for 3 lines)
      // Using scrollHeight which reflects actual content height
      if (shouldStick && container) {
        container.scrollTop = container.scrollHeight
      }
    })
  }, [])

  // Initialize speech recognition
  useEffect(() => {
    if (typeof window === 'undefined' || !enabled) return

    // Check for speech recognition support immediately
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition
    if (SpeechRecognition) {
      setHasSpeechRecognition(true)
    } else {
      return
    }

    const recognition = new SpeechRecognition()
    recognition.continuous = true
    recognition.interimResults = true
    recognition.lang = 'en-US'

    let finalTranscript = ''

    recognition.onstart = () => {
      setIsListening(true)
      finalTranscript = ''
    }

    recognition.onresult = (event: any) => {
      let interimTranscript = ''

      for (let i = event.resultIndex; i < event.results.length; i++) {
        const transcript = event.results[i][0].transcript
        if (event.results[i].isFinal) {
          finalTranscript += transcript + ' '
        } else {
          interimTranscript += transcript
        }
      }

      setInput(finalTranscript + interimTranscript)
    }

    recognition.onerror = (event: any) => {
      setIsListening(false)
      if (event.error !== 'no-speech') {
        setError('Speech recognition error. Please try again.')
      }
    }

    recognition.onend = () => {
      setIsListening(false)
      if (finalTranscript.trim()) {
        setInput(finalTranscript.trim())
      }
    }

    recognitionRef.current = recognition
    return () => {
      if (recognitionRef.current) recognitionRef.current.stop()
    }
  }, [enabled])

  // Track client-side mount so we can safely use portals
  useEffect(() => {
    setIsClient(true)
  }, [])

  // Auto-resize textarea pre-paint to reduce flicker
  useLayoutEffect(() => {
    resizeTextarea()
  }, [input, resizeTextarea])

  function startListening() {
    if (!recognitionRef.current || isListening) return
    try {
      recognitionRef.current.start()
    } catch (err) {
      setError('Failed to start voice recognition')
    }
  }

  function stopListening() {
    if (recognitionRef.current && isListening) {
      recognitionRef.current.stop()
      setIsListening(false)
    }
  }

  // Load threads and current thread on mount
  useEffect(() => {
    if (!enabled) return
    let cancelled = false
    ;(async () => {
      try {
        let hasThreads = false
        // Load threads
        const threadsRes = await fetch(`/api/insights/issues/${issueSlug}/sections/${section}/threads`, { cache: 'no-store' })
        if (threadsRes.ok) {
          const threadsData = await threadsRes.json()
          if (!cancelled && threadsData.threads && Array.isArray(threadsData.threads)) {
            setThreads(threadsData.threads)
            hasThreads = threadsData.threads.length > 0
            if (threadsData.threads.length > 0 && !threadId) {
              const latestThread = threadsData.threads.find((thread: ChatThread) => !thread.archivedAt) || threadsData.threads[0]
              setThreadId(latestThread.id)
              loadThreadMessages(latestThread.id)
            }
          }
        }
        // Only try backward compatibility if we have NO threads (to avoid creating duplicates)
        if (!cancelled && !hasThreads && !threadId) {
          const res = await fetch(`/api/insights/issues/${issueSlug}/sections/${section}/chat`, { cache: 'no-store' })
          if (res.ok) {
            const data = await res.json()
            if (!cancelled && typeof data?.threadId === 'string') {
              setThreadId(data.threadId)
              const serverMessages = Array.isArray(data?.messages)
                ? data.messages.map((m: any) => ({ role: m.role, content: m.content })).filter((m: any) => m?.content)
                : []
              if (!cancelled && serverMessages.length) setMessages(serverMessages)
            }
          }
        }
      } catch {}
    })()
    return () => { cancelled = true }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled, issueSlug, section])

  async function loadThreadMessages(threadIdToLoad: string) {
    try {
      const res = await fetch(`/api/insights/issues/${issueSlug}/sections/${section}/chat?threadId=${threadIdToLoad}`, { cache: 'no-store' })
      if (res.ok) {
        const data = await res.json()
        const serverMessages = Array.isArray(data?.messages)
          ? data.messages.map((m: any) => ({ role: m.role, content: m.content })).filter((m: any) => m?.content)
          : []
        setMessages(serverMessages)
      }
    } catch (err) {
      console.error('Failed to load thread messages:', err)
    }
  }

  function handleSelectThread(threadIdToSelect: string) {
    setThreadId(threadIdToSelect)
    loadThreadMessages(threadIdToSelect)
    setThreadsOpen(false)
  }

  function openThreadActions(targetThreadId: string) {
    setActionThreadId(targetThreadId)
    setRenameOpen(false)
    setDeleteConfirmOpen(false)
    setDeletePending(false)
    longPressTriggeredRef.current = true
  }

  function closeThreadActions() {
    setActionThreadId(null)
    setRenameOpen(false)
    setDeleteConfirmOpen(false)
    setDeletePending(false)
    longPressTriggeredRef.current = false
  }

  function startLongPress(event: PointerEvent, targetThreadId: string) {
    if (event.pointerType !== 'touch') return
    if (longPressTimerRef.current) {
      window.clearTimeout(longPressTimerRef.current)
    }
    longPressTimerRef.current = window.setTimeout(() => {
      openThreadActions(targetThreadId)
    }, 500)
  }

  function endLongPress() {
    if (longPressTimerRef.current) {
      window.clearTimeout(longPressTimerRef.current)
    }
  }

  async function handleNewChat() {
    try {
      const res = await fetch(`/api/insights/issues/${issueSlug}/sections/${section}/threads`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({}),
      })
      if (res.ok) {
        const data = await res.json()
        const newThreadId = data.threadId
        setThreadId(newThreadId)
        setMessages([])
        setThreadsOpen(false)
        // Reload threads
        const threadsRes = await fetch(`/api/insights/issues/${issueSlug}/sections/${section}/threads`, { cache: 'no-store' })
        if (threadsRes.ok) {
          const threadsData = await threadsRes.json()
          if (threadsData.threads) setThreads(threadsData.threads)
        }
      }
    } catch (err) {
      console.error('Failed to create new thread:', err)
    }
  }

  async function handleArchiveThread(targetThreadId: string) {
    const targetThread = threads.find((thread) => thread.id === targetThreadId)
    if (!targetThread) return
    const nextArchived = !targetThread.archivedAt
    let nextThreadId = threadId
    if (nextArchived && threadId === targetThreadId) {
      const fallback = threads.find((thread) => thread.id !== targetThreadId && !thread.archivedAt)
      nextThreadId = fallback ? fallback.id : null
    }
    try {
      const res = await fetch(`/api/insights/issues/${issueSlug}/sections/${section}/threads`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ threadId: targetThreadId, archived: nextArchived }),
      })
      if (res.ok) {
        const threadsRes = await fetch(`/api/insights/issues/${issueSlug}/sections/${section}/threads`, { cache: 'no-store' })
        if (threadsRes.ok) {
          const threadsData = await threadsRes.json()
          if (threadsData.threads) {
            setThreads(threadsData.threads)
            if (nextThreadId) {
              setThreadId(nextThreadId)
              loadThreadMessages(nextThreadId)
            } else {
              setThreadId(null)
              setMessages([])
            }
          }
        }
      }
    } catch (err) {
      console.error('Failed to archive thread:', err)
    }
    closeThreadActions()
  }

  async function handleRenameThread(threadIdToRename: string, title: string) {
    const nextTitle = title.trim()
    if (!nextTitle) return
    try {
      const res = await fetch(`/api/insights/issues/${issueSlug}/sections/${section}/threads`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ threadId: threadIdToRename, title: nextTitle }),
      })
      if (res.ok) {
        setThreads((prev) =>
          prev.map((thread) => (thread.id === threadIdToRename ? { ...thread, title: nextTitle } : thread))
        )
      }
    } catch (err) {
      console.error('Failed to rename thread:', err)
    }
  }

  async function handleDeleteThread(threadIdToDelete: string) {
    try {
      const res = await fetch(`/api/insights/issues/${issueSlug}/sections/${section}/threads`, {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ threadId: threadIdToDelete }),
      })
      if (res.ok) {
        // Reload threads
        const threadsRes = await fetch(`/api/insights/issues/${issueSlug}/sections/${section}/threads`, { cache: 'no-store' })
        if (threadsRes.ok) {
          const threadsData = await threadsRes.json()
          if (threadsData.threads) {
            setThreads(threadsData.threads)
            if (threadsData.threads.length > 0) {
              const nextThread = threadsData.threads.find((thread: ChatThread) => !thread.archivedAt) || threadsData.threads[0]
              setThreadId(nextThread.id)
              loadThreadMessages(nextThread.id)
            } else {
              setThreadId(null)
              setMessages([])
            }
          }
        }
        setThreadsOpen(false)
      }
    } catch (err) {
      console.error('Failed to delete thread:', err)
    }
  }

  useEffect(() => {
    const container = containerRef.current
    if (!container) return
    if (messages.length === 0 && !loading) return
    container.scrollTop = container.scrollHeight
  }, [messages, loading])

  // NOTE: We intentionally do NOT manipulate page scroll when expanding.
  // The expanded chat is rendered in a fullscreen portal overlay,
  // so closing it simply removes the overlay and leaves page scroll
  // exactly where it was.

  useEffect(() => {
    return () => {
      if (resizeRafRef.current) cancelAnimationFrame(resizeRafRef.current)
    }
  }, [])

  function onComposerKeyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
    if (event.key === 'Enter' && !event.shiftKey) {
      event.preventDefault()
      const form = (event.target as HTMLTextAreaElement).closest('form') as HTMLFormElement | null
      form?.requestSubmit()
    }
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const text = input.trim()
    if (!text) {
      setError('Enter a question to ask the AI.')
      return
    }
    try {
      setLoading(true)
      setError(null)
      stopListening()
      const nextMessages: ChatMessage[] = [...messages, { role: 'user', content: text }]
      setMessages(nextMessages)
      setInput('')
      let activeThreadId = threadId

      // Attempt streaming via SSE to new chat endpoint
      const url = `/api/insights/issues/${issueSlug}/sections/${section}/chat`
      const res = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Accept: 'text/event-stream' },
        body: JSON.stringify({ 
          message: text,
          threadId: threadId || undefined,
          newThread: false, // Never create a new thread automatically - user must click "+ New"
        }),
      })

      if (!res.ok) {
        const data = await res.json().catch(() => null)
        setError(getApiErrorMessage(data))
        return
      }

      if ((res.headers.get('content-type') || '').includes('text/event-stream') && res.body) {
        const reader = res.body.getReader()
        const decoder = new TextDecoder()
        let buffer = ''
        let hasAssistant = false
        const applyChunk = (chunk: string) => {
          if (chunk.startsWith('event: end')) {
            return
          }
          if (!chunk.startsWith('data:')) return
          const raw = chunk.replace(/^data:\s?/, '')
          const trimmed = raw.trim()
          if (trimmed.startsWith(COST_PREFIX)) {
            try {
              const payload = JSON.parse(trimmed.slice(COST_PREFIX.length))
              if (payload && typeof payload.costCents === 'number') {
                const targetId = activeThreadId || threadId
                if (targetId) {
                  const costNow = new Date().toISOString()
                  setThreads((prev) =>
                    prev.map((thread) =>
                      thread.id === targetId
                        ? {
                            ...thread,
                            lastChargedCost: payload.costCents,
                            lastChargedAt: costNow,
                            lastChargeCovered: Boolean(payload.covered),
                          }
                        : thread
                    )
                  )
                }
              }
            } catch {}
            return
          }
          let token = ''
          try {
            const parsed = JSON.parse(trimmed)
            if (typeof parsed === 'string') {
              token = parsed
            } else if (parsed && typeof parsed.token === 'string') {
              token = parsed.token
            } else {
              token = raw
            }
          } catch {
            token = raw
          }
          if (!token) return
          if (!hasAssistant) {
            setMessages((prev) => [...prev, { role: 'assistant', content: token }])
            hasAssistant = true
          } else {
            setMessages((prev) => {
              const copy = prev.slice()
              copy[copy.length - 1] = { role: 'assistant', content: (copy[copy.length - 1] as any).content + token }
              return copy
            })
          }
        }

        while (true) {
          const { value, done } = await reader.read()
          if (done) break
          buffer += decoder.decode(value, { stream: true })
          const parts = buffer.split('\n\n')
          buffer = parts.pop() || ''
          for (const chunk of parts) {
            applyChunk(chunk)
            if (chunk.startsWith('event: end')) {
              // Response complete - reload threads to get updated title
              const threadsRes = await fetch(`/api/insights/issues/${issueSlug}/sections/${section}/threads`, { cache: 'no-store' })
              if (threadsRes.ok) {
                const threadsData = await threadsRes.json()
                if (threadsData.threads) {
                  setThreads(threadsData.threads)
                  // Update threadId if we created a new thread
                  if (!activeThreadId && threadsData.threads.length > 0) {
                    const nextThread = threadsData.threads.find((thread: ChatThread) => !thread.archivedAt) || threadsData.threads[0]
                    setThreadId(nextThread.id)
                    activeThreadId = nextThread.id
                  }
                }
              }
            }
          }
        }

        if (buffer.trim()) {
          applyChunk(buffer.trim())
        }

