function fallbackIssue(slug: string): IssueSummary {
  const readable = slug
    .replace(/[-_]+/g, ' ')
    .trim()
    .split(' ')
    .filter(Boolean)
    .map(part => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ')
  return {
    id: `temp:${slug}`,
    slug,
    name: readable || 'Insight',
    polarity: 'negative',
    severityLabel: 'Needs data',
    severityScore: null,
    currentRating: null,
    ratingScaleMax: 6,
    trend: 'inconclusive',
    trendDelta: null,
    lastUpdated: null,
    highlight: 'Needs more data before we can generate trends.',
    blockers: ['Log more recent data so we can generate this report.'],
    status: 'needs-data',
  }
}

