  Filler,
  type ChartOptions,
} from 'chart.js'

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, ArcElement, Tooltip, Legend, Filler)

const PrintModeContext = createContext(false)

type DailyStat = {
  date: string
  calories?: number
  waterMl?: number
  exerciseMinutes?: number
  moodAvg?: number | null
  symptomCount?: number
}

type NutritionSummary = {
