import { getServerSession } from 'next-auth'
import { redirect } from 'next/navigation'
import { authOptions } from '@/lib/auth'
import {
  ensureReadyWeeklyReportNextDueInFuture,
  getWeeklyReportChatActivity,
  getLatestWeeklyReport,
  getWeeklyReportById,
  getWeeklyReportState,
  listWeeklyReports,
} from '@/lib/weekly-health-report'
import WeeklyReportClient from './WeeklyReportClient'

interface WeeklyReportPageProps {
  searchParams?: { id?: string }
}

export default async function WeeklyReportPage({ searchParams }: WeeklyReportPageProps) {
  const session = await getServerSession(authOptions)
  if (!session?.user?.id) {
    const reportId = typeof searchParams?.id === 'string' ? searchParams?.id : ''
    const callback = reportId ? `/insights/weekly-report?id=${encodeURIComponent(reportId)}` : '/insights/weekly-report'
    redirect(`/auth/signin?callbackUrl=${encodeURIComponent(callback)}`)
  }

  const reportId = typeof searchParams?.id === 'string' ? searchParams?.id : ''
  const [report, reports, stateRaw] = await Promise.all([
    reportId ? getWeeklyReportById(session.user.id, reportId) : getLatestWeeklyReport(session.user.id),
    listWeeklyReports(session.user.id, 50),
    getWeeklyReportState(session.user.id),
  ])
  const state = await ensureReadyWeeklyReportNextDueInFuture(session.user.id, stateRaw, report)
  const verifiedChatActivity = report
    ? await getWeeklyReportChatActivity(session.user.id, report.periodStart, report.periodEnd)
    : null
  const canManualReport = String(session.user.email || '').toLowerCase() === 'info@sonicweb.com.au'
  const reportsEnabled =
    Boolean(state?.reportsEnabled) ||
    Boolean(state?.reportsEnabledAt) ||
    Boolean(state?.nextReportDueAt) ||
    Boolean(report) ||
    reports.length > 0

  return (
    <WeeklyReportClient
      report={report}
      reports={reports}
      nextReportDueAt={state?.nextReportDueAt ?? null}
      canManualReport={canManualReport}
      reportsEnabled={reportsEnabled}
      verifiedChatActivity={verifiedChatActivity}
    />
  )
}

import { getServerSession } from 'next-auth'
import { redirect } from 'next/navigation'
import { authOptions } from '@/lib/auth'
import { getWeeklyReportById, getWeeklyReportChatActivity } from '@/lib/weekly-health-report'
import WeeklyReportPrintClient from './weekly-report-print-client'

interface WeeklyReportPrintPageProps {
  searchParams?: { id?: string }
}

export default async function WeeklyReportPrintPage({ searchParams }: WeeklyReportPrintPageProps) {
  const session = await getServerSession(authOptions)
  const reportId = typeof searchParams?.id === 'string' ? searchParams?.id : ''

  if (!session?.user?.id) {
    const callback = reportId
      ? `/insights/weekly-report/print?id=${encodeURIComponent(reportId)}`
      : '/insights/weekly-report'
    redirect(`/auth/signin?callbackUrl=${encodeURIComponent(callback)}`)
  }

  if (!reportId) {
    redirect('/insights/weekly-report')
  }

  const report = await getWeeklyReportById(session.user.id, reportId)
  if (!report) {
    redirect('/insights/weekly-report')
  }

  const verifiedChatActivity = await getWeeklyReportChatActivity(
    session.user.id,
    report.periodStart,
    report.periodEnd
  )

  return <WeeklyReportPrintClient report={report} verifiedChatActivity={verifiedChatActivity} />
}

