                {wins.map((item: any, idx: number) => (
                  <div key={`win-${idx}`} className="rounded-xl border border-emerald-100 bg-white p-4 print-avoid-break">
                    <div className="font-semibold text-emerald-900">{replaceIsoDates(item.name || 'Win')}</div>
