                  <div className="font-semibold text-emerald-950">{replaceIsoDates(String(s?.name || 'Supplement'))}</div>
                  {(s?.dosage || s?.timing) ? (
                    <div className="mt-1 text-sm text-emerald-900/80">
                      {s?.dosage ? `Dose: ${s.dosage}` : 'Dose: -'} {' • '}
                      {s?.timing ? `Timing: ${s.timing}` : 'Timing: -'}
