'use client'

import { useCallback, useEffect, useState } from 'react'
import Link from 'next/link'
import Image from 'next/image'
import { usePathname } from 'next/navigation'
import PageHeader from '@/components/PageHeader'

type MedicalAnalysisResult = {
  summary?: string | null
  possibleCauses?: Array<{ name: string; whyLikely?: string; confidence?: string }>
  redFlags?: string[]
  nextSteps?: string[]
  analysisText?: string | null
}

type MedicalHistoryItem = {
  id: string
  summary?: string | null
  analysisText?: string | null
  analysisData?: MedicalAnalysisResult | null
  createdAt: string
  imageUrl?: string | null
}

const SAFE_IMAGE_NOTE_FALLBACK =
  'Older saved image note. Please review this image with a qualified healthcare professional if you are concerned.'

const riskyMedicalClaimPattern =
  /\b(possibly indicating|may indicate|could indicate|suggests|suggesting|consistent with|likely|viral infection|skin reaction|infection|cancer|melanoma|diagnosis|diagnose)\b/i

function safeImageNoteText(value: unknown, fallback = SAFE_IMAGE_NOTE_FALLBACK) {
  const text = String(value || '').trim()
  if (!text) return ''
  if (riskyMedicalClaimPattern.test(text)) return fallback
  return text
}

function safeDiscussionTopicName(value: unknown) {
  return safeImageNoteText(value, 'Image detail to discuss with a doctor') || 'Image detail to discuss with a doctor'
}

function SavedScanImage({ imageUrl }: { imageUrl?: string | null }) {
  const [failed, setFailed] = useState(false)

  if (!imageUrl || failed) {
    return (
      <div className="h-36 w-full rounded-lg border border-dashed border-gray-200 bg-gray-50 flex items-center justify-center text-xs text-gray-400 text-center px-3">
        Image unavailable
      </div>
    )
  }

  return (
    <Image
      src={imageUrl}
      alt="Saved medical scan"
      width={144}
      height={144}
      className="h-36 w-full rounded-lg object-cover border border-gray-100"
      onError={() => setFailed(true)}
      unoptimized
    />
  )
}

export default function MedicalImagesHistoryPage() {
  const pathname = usePathname()
  const [historyItems, setHistoryItems] = useState<MedicalHistoryItem[]>([])
  const [historyLoading, setHistoryLoading] = useState<boolean>(false)
  const [historyError, setHistoryError] = useState<string | null>(null)
  const [historyDeletingId, setHistoryDeletingId] = useState<string | null>(null)
  const [historyClearing, setHistoryClearing] = useState<boolean>(false)
  const [expandedHistoryId, setExpandedHistoryId] = useState<string | null>(null)

  const loadHistory = useCallback(async () => {
    try {
      setHistoryLoading(true)
      setHistoryError(null)
      const res = await fetch('/api/medical-images/history', { cache: 'no-store' as any })
      if (!res.ok) {
        throw new Error('Failed to load history')
      }
      const data = await res.json()
      const nextHistory = Array.isArray(data?.history)
        ? data.history.map((item: any) => ({
            ...item,
            analysisData: item?.analysisData && typeof item.analysisData === 'object' ? item.analysisData : null,
          }))
        : []
      setHistoryItems(nextHistory)
    } catch (err) {
      setHistoryError((err as Error).message || 'Failed to load history')
    } finally {
      setHistoryLoading(false)
    }
  }, [])

  useEffect(() => {
    loadHistory()
  }, [loadHistory])

  const handleDeleteHistoryItem = async (id: string) => {
    if (!window.confirm('Delete this saved image note? This cannot be undone.')) return
    try {
      setHistoryDeletingId(id)
      setHistoryError(null)
      const res = await fetch(`/api/medical-images/history/${id}`, { method: 'DELETE' })
      if (!res.ok) {
        throw new Error('Failed to delete saved image note')
      }
      setHistoryItems((prev) => prev.filter((item) => item.id !== id))
      setExpandedHistoryId((prev) => (prev === id ? null : prev))
    } catch (err) {
      setHistoryError((err as Error).message || 'Failed to delete saved image note')
    } finally {
      setHistoryDeletingId(null)
    }
  }

  const handleClearHistory = async () => {
    if (!window.confirm('Clear all saved image notes? This cannot be undone.')) return
    try {
      setHistoryClearing(true)
      setHistoryError(null)
      const res = await fetch('/api/medical-images/history', { method: 'DELETE' })
      if (!res.ok) {
        throw new Error('Failed to clear history')
      }
      setHistoryItems([])
      setExpandedHistoryId(null)
    } catch (err) {
      setHistoryError((err as Error).message || 'Failed to clear history')
    } finally {
      setHistoryClearing(false)
    }
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      <PageHeader title="Health Image Notes" />

      {/* Tabs */}
      <div className="max-w-7xl mx-auto w-full px-4 pt-4">
        <div className="bg-white rounded-t-xl border-b border-gray-200">
          <div className="flex">
            <Link
              href="/medical-images"
              style={{ width: '100%' }}
              className={`flex-1 px-4 py-3 text-center font-medium transition-colors ${
                pathname !== '/medical-images/history'
                  ? 'text-helfi-green border-b-2 border-helfi-green'
                  : 'text-gray-600 hover:text-gray-900'
              }`}
            >
              Health Image Notes
            </Link>
            <Link
              href="/medical-images/history"
              style={{ width: '100%' }}
              className={`flex-1 px-4 py-3 text-center font-medium transition-colors ${
                pathname === '/medical-images/history'
                  ? 'text-helfi-green border-b-2 border-helfi-green'
                  : 'text-gray-600 hover:text-gray-900'
              }`}
            >
              History
            </Link>
          </div>
        </div>
      </div>

      <main className="flex-1">
        <div className="max-w-7xl mx-auto px-4 py-6">
          <div className="bg-white rounded-b-2xl shadow-sm border border-gray-200 p-6">
            <div className="flex items-center justify-between gap-2 mb-4">
              <div>
                <h1 className="text-2xl font-bold text-gray-900">Health Image Notes History</h1>
                <p className="text-xs text-gray-500 mt-1">Only scans you chose to save appear here.</p>
              </div>
              <div className="flex items-center gap-3 text-xs">
                {historyItems.length > 0 && (
                  <button
                    onClick={handleClearHistory}
                    className="text-red-600 hover:text-red-700 disabled:opacity-60"
                    type="button"
                    disabled={historyClearing}
                  >
                    {historyClearing ? 'Clearing...' : 'Clear all'}
                  </button>
                )}
                <button
                  onClick={loadHistory}
                  className="text-gray-600 hover:text-gray-900 disabled:opacity-60"
                  type="button"
                  disabled={historyLoading}
                >
                  Refresh
                </button>
              </div>
            </div>

            {historyLoading && <div className="text-sm text-gray-500">Loading history...</div>}
            {historyError && <div className="text-sm text-red-700">{historyError}</div>}
            {!historyLoading && !historyError && historyItems.length === 0 && (
              <div className="text-sm text-gray-500">No saved image notes yet.</div>
            )}

            <div className="mt-4 space-y-4">
              {historyItems.map((item) => {
                const analysisData = item.analysisData || null
                const possibleCauses = Array.isArray(analysisData?.possibleCauses)
                  ? analysisData?.possibleCauses
                  : []
                const redFlags = Array.isArray(analysisData?.redFlags) ? analysisData?.redFlags : []
                const nextSteps = Array.isArray(analysisData?.nextSteps) ? analysisData?.nextSteps : []
                const safeSummary = safeImageNoteText(item.summary)
                const safeAnalysisText = safeImageNoteText(item.analysisText)
                const isExpanded = expandedHistoryId === item.id
                const createdAtLabel = item.createdAt
                  ? new Date(item.createdAt).toLocaleString()
                  : 'Unknown date'

                return (
                  <div key={item.id} className="border border-gray-200 rounded-lg p-4 bg-white">
                    <div className="flex flex-col gap-4 md:flex-row">
                      <div className="w-full md:w-36 flex-shrink-0">
                        <SavedScanImage imageUrl={item.imageUrl} />
                      </div>
                      <div className="flex-1 space-y-2">
                        <div className="flex items-center justify-between gap-2">
                          <div className="text-xs text-gray-500">{createdAtLabel}</div>
                          <div className="flex items-center gap-3 text-xs">
                            <button
                              type="button"
                              onClick={() => setExpandedHistoryId(isExpanded ? null : item.id)}
                              className="text-helfi-green hover:text-helfi-green/80"
                            >
                              {isExpanded ? 'Hide details' : 'View details'}
                            </button>
                            <button
                              type="button"
                              onClick={() => handleDeleteHistoryItem(item.id)}
                              className="text-red-600 hover:text-red-700 disabled:opacity-60"
                              disabled={historyDeletingId === item.id || historyClearing}
                            >
                              {historyDeletingId === item.id ? 'Deleting...' : 'Delete'}
                            </button>
                          </div>
                        </div>
                        {safeSummary && <p className="text-sm text-gray-800">{safeSummary}</p>}
                        {!safeSummary && safeAnalysisText && (
                          <p className="text-sm text-gray-800 whitespace-pre-line">{safeAnalysisText}</p>
                        )}

                        {isExpanded && (
                          <div className="pt-2 space-y-3 text-sm text-gray-700">
                            {possibleCauses.length > 0 && (
                              <div>
                                <div className="font-medium text-gray-900 mb-1">Topics to discuss with a doctor</div>
                                <ul className="space-y-1">
                                  {possibleCauses.map((cause: any, idx: number) => (
                                    <li key={`${cause.name}-${idx}`} className="flex items-center gap-2">
                                      <span className="text-gray-900">{safeDiscussionTopicName(cause.name)}</span>
                                      {cause.confidence && (
                                        <span className="text-xs text-gray-500">(general)</span>
                                      )}
                                    </li>
                                  ))}
                                </ul>
                              </div>
                            )}
                            {redFlags.length > 0 && (
                              <div>
                                <div className="font-medium text-red-700 mb-1">When to seek urgent care</div>
                                <ul className="list-disc list-inside space-y-1 text-red-800">
                                  {redFlags.map((flag: string, idx: number) => (
                                    <li key={idx}>{flag}</li>
                                  ))}
                                </ul>
                              </div>
                            )}
                            {nextSteps.length > 0 && (
                              <div>
                                <div className="font-medium text-gray-900 mb-1">Tracking notes and doctor questions</div>
                                <ul className="list-disc list-inside space-y-1">
                                  {nextSteps.map((step: string, idx: number) => (
                                    <li key={idx}>{step}</li>
                                  ))}
                                </ul>
                              </div>
                            )}
                            {safeAnalysisText && safeSummary && (
                              <div>
                                <div className="font-medium text-gray-900 mb-1">Full notes</div>
                                <p className="whitespace-pre-line">{safeAnalysisText}</p>
                              </div>
                            )}
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                )
              })}
            </div>
          </div>
        </div>
      </main>
    </div>
  )
}

'use client'
import { Cog6ToothIcon } from '@heroicons/react/24/outline'

import { useCallback, useEffect, useRef, useState } from 'react'
import Link from 'next/link'
import { usePathname } from 'next/navigation'
import CreditPurchaseModal from '@/components/CreditPurchaseModal'
import AiConsentModal, { hasSavedAiConsent, saveAiConsent } from '@/components/AiConsentModal'
import MobileMoreMenu from '@/components/MobileMoreMenu'
import UsageMeter from '@/components/UsageMeter'
import FeatureUsageDisplay from '@/components/FeatureUsageDisplay'
import PageHeader from '@/components/PageHeader'
import MedicalImageChat from './MedicalImageChat'
import PractitionerRecommendations from '@/components/PractitionerRecommendations'

type ConfidenceLevel = 'low' | 'medium' | 'high'

type MedicalPossibleCause = {
  name: string
  whyLikely: string
  confidence: ConfidenceLevel | string
}

type MedicalAnalysisResult = {
  summary?: string | null
  possibleCauses?: MedicalPossibleCause[]
  redFlags?: string[]
  nextSteps?: string[]
  disclaimer?: string
  analysisText?: string
}

const SAFE_IMAGE_NOTE_FALLBACK =
  'Image note created. Please review this image with a qualified healthcare professional if you are concerned.'

const riskyMedicalClaimPattern =
  /\b(possibly indicating|may indicate|could indicate|suggests|suggesting|consistent with|likely|viral infection|skin reaction|infection|cancer|melanoma|diagnosis|diagnose)\b/i

function safeImageNoteText(value: unknown, fallback = SAFE_IMAGE_NOTE_FALLBACK) {
  const text = String(value || '').trim()
  if (!text) return ''
  if (riskyMedicalClaimPattern.test(text)) return fallback
  return text
}

function safeDiscussionTopicName(value: unknown) {
  return safeImageNoteText(value, 'Image detail to discuss with a doctor') || 'Image detail to discuss with a doctor'
}

export default function MedicalImagesPage() {
  const pathname = usePathname()
  const [imageFile, setImageFile] = useState<File | null>(null)
  const [imagePreview, setImagePreview] = useState<string | null>(null)
  const [isAnalyzing, setIsAnalyzing] = useState<boolean>(false)
  const [analysis, setAnalysis] = useState<string | null>(null)
  const [analysisResult, setAnalysisResult] = useState<MedicalAnalysisResult | null>(null)
  const [error, setError] = useState<string>('')
  const [saveToHistory, setSaveToHistory] = useState<boolean>(false)
  const [historySaveError, setHistorySaveError] = useState<string | null>(null)
  const [currentHistorySaving, setCurrentHistorySaving] = useState<boolean>(false)
  const [currentHistorySaved, setCurrentHistorySaved] = useState<boolean>(false)
  const [showCreditsModal, setShowCreditsModal] = useState<boolean>(false)
  const [creditInfo, setCreditInfo] = useState<any>({
    dailyUsed: 0,
    dailyLimit: 0,
    additionalCredits: 0,
    plan: 'FREE',
    creditCost: 2, // Health image notes cost 2 credits
    featureUsageToday: { foodAnalysis: 0, interactionAnalysis: 0 }
  })
  const [usageMeterRefresh, setUsageMeterRefresh] = useState<number>(0) // Trigger for UsageMeter refresh
  const [hasPaidAccess, setHasPaidAccess] = useState<boolean>(false)
  const [hasAnalyzedCurrentImage, setHasAnalyzedCurrentImage] = useState<boolean>(false)
  const [analysisSessionId, setAnalysisSessionId] = useState<number>(0)
  const resultRef = useRef<HTMLDivElement | null>(null)
  const [creditRefreshTick, setCreditRefreshTick] = useState<number>(0)
  const [showAiConsent, setShowAiConsent] = useState<boolean>(false)

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) {
      setImageFile(file)
      setAnalysis(null)
      setAnalysisResult(null)
      setError('')
      setHistorySaveError(null)
      setHasAnalyzedCurrentImage(false)
      setCurrentHistorySaved(false)
      setCurrentHistorySaving(false)
      // Create preview
      const reader = new FileReader()
      reader.onloadend = () => {
        setImagePreview(reader.result as string)
      }
      reader.readAsDataURL(file)
    }
  }

  useEffect(() => {
    const handler = () => setCreditRefreshTick((v) => v + 1)
    try {
      window.addEventListener('credits:refresh', handler)
      return () => window.removeEventListener('credits:refresh', handler)
    } catch {
      return () => {}
    }
  }, [])

  useEffect(() => {
    const fetchCreditStatus = async () => {
      try {
        const res = await fetch(`/api/credit/status`, { cache: 'no-store' })
        if (!res.ok) return
        const data = await res.json()
        const isPremium = data?.plan === 'PREMIUM'
        const hasWalletCredits =
          typeof data?.totalAvailableCents === 'number' && data.totalAvailableCents > 0
        const hasLegacyCredits =
          typeof data?.credits?.total === 'number' && data.credits.total > 0

        setHasPaidAccess(Boolean(isPremium || hasWalletCredits || hasLegacyCredits))
      } catch {
        // ignore failures – fall back to showing free banner
      }
    }
    fetchCreditStatus()
  }, [creditRefreshTick])

  const saveCurrentToHistory = useCallback(async () => {
    if (!imageFile) {
      setHistorySaveError('Please upload an image before saving.')
      return
    }
    if (!analysis && !analysisResult) {
      setHistorySaveError('Please create image notes before saving.')
      return
    }
    if (currentHistorySaved || currentHistorySaving) return

    try {
      setCurrentHistorySaving(true)
      setHistorySaveError(null)

      const payload = {
        summary: safeImageNoteText(analysisResult?.summary) || null,
        possibleCauses: Array.isArray(analysisResult?.possibleCauses)
          ? analysisResult.possibleCauses.map((cause) => ({
              ...cause,
              name: safeDiscussionTopicName(cause.name),
              whyLikely: safeImageNoteText(
                cause.whyLikely,
                'This visible detail is worth discussing with a healthcare professional.',
              ),
              confidence: 'low',
            }))
          : [],
        redFlags: Array.isArray(analysisResult?.redFlags) ? analysisResult?.redFlags : [],
        nextSteps: Array.isArray(analysisResult?.nextSteps) ? analysisResult?.nextSteps : [],
        disclaimer: analysisResult?.disclaimer ?? null,
        analysisText: safeImageNoteText(analysis ?? analysisResult?.analysisText) || null,
      }

      const formData = new FormData()
      formData.append('image', imageFile)
      formData.append('analysis', JSON.stringify(payload))

      const res = await fetch('/api/medical-images/history', {
        method: 'POST',
        body: formData,
      })
      if (!res.ok) {
        const data = await res.json().catch(() => ({}))
        throw new Error(data?.error || 'Failed to save scan to history')
      }
      const data = await res.json()
      setCurrentHistorySaved(true)
    } catch (err) {
      setHistorySaveError((err as Error).message || 'Failed to save scan to history')
    } finally {
      setCurrentHistorySaving(false)
    }
  }, [analysis, analysisResult, currentHistorySaved, currentHistorySaving, imageFile])

  const handleSaveToggle = async (checked: boolean) => {
    setSaveToHistory(checked)
    if (checked && (analysisResult || analysis) && !currentHistorySaved && !currentHistorySaving) {
      await saveCurrentToHistory()
    }
  }

  const runImageNotes = async () => {
    const selectedImageFile = imageFile
    if (!selectedImageFile) {
      setError('Please select an image first')
      return
    }

    setError('')
    setAnalysis(null)
    setAnalysisResult(null)
    setIsAnalyzing(true)
    setHasAnalyzedCurrentImage(false)
    setHistorySaveError(null)
    setCurrentHistorySaved(false)
    setCurrentHistorySaving(false)

    try {
      const formData = new FormData()
      formData.append('image', selectedImageFile)
      formData.append('saveToHistory', saveToHistory ? 'true' : 'false')

      const response = await fetch('/api/test-vision', {
        method: 'POST',
        body: formData,
      })

      if (response.status === 402) {
        const data = await response.json()
        setCreditInfo({
          dailyUsed: 0,
          dailyLimit: 0,
          additionalCredits: data.additionalCredits ?? 0,
          plan: data.plan ?? 'FREE',
          creditCost: 2,
          featureUsageToday: { foodAnalysis: 0, interactionAnalysis: 0 }
        })
        setShowCreditsModal(true)
        setIsAnalyzing(false)
        return
      }

      if (!response.ok) {
        const data = await response.json().catch(() => ({}))
        throw new Error(data?.error || data?.message || 'Failed to create image notes')
      }

      const result = await response.json()
      if (result.success) {
        const analysisText = typeof result.analysis === 'string' ? result.analysis : null
        const possibleCauses = Array.isArray(result.possibleCauses) ? result.possibleCauses : []
        const redFlags = Array.isArray(result.redFlags) ? result.redFlags : []
        const nextSteps = Array.isArray(result.nextSteps) ? result.nextSteps : []
        const hasStructured =
          Boolean(result.summary) ||
          possibleCauses.length > 0 ||
          redFlags.length > 0 ||
          nextSteps.length > 0

        if (!analysisText && !hasStructured) {
          throw new Error('Invalid response from server')
        }

        if (analysisText) {
          setAnalysis(analysisText)
        }

        const structured: MedicalAnalysisResult = {
          summary: result.summary ?? null,
          possibleCauses,
          redFlags,
          nextSteps,
          disclaimer:
            result.disclaimer ||
            'These are general image notes only. They are not medical advice, diagnosis, or treatment. A qualified healthcare professional should review any health concern.',
          analysisText: analysisText ?? undefined,
        }
        if (analysisText || hasStructured) {
          setAnalysisResult(structured)
        }
        setAnalysisSessionId(prev => prev + 1)
        setHasAnalyzedCurrentImage(true)
        // Trigger usage meter refresh after successful analysis
        try { window.dispatchEvent(new Event('credits:refresh')); } catch {}

        if (saveToHistory) {
          if (result.historySaved && result.historyItem) {
            setCurrentHistorySaved(true)
          } else if (result.historyError) {
            setHistorySaveError(result.historyError)
          } else if (!result.historySaved) {
            setHistorySaveError('We could not save this scan to your history.')
          }
        }
      } else {
        throw new Error('Invalid response from server')
      }
    } catch (e: any) {
      setError(e?.message || 'Something went wrong')
    } finally {
      setIsAnalyzing(false)
    }
  }

  const handleAnalyze = async () => {
    if (!imageFile) {
      setError('Please select an image first')
      return
    }
    if (hasAnalyzedCurrentImage) {
      setError('This image already has notes. Reset to create notes for a new image.')
      return
    }

    if (!hasSavedAiConsent()) {
      setShowAiConsent(true)
      return
    }

    await runImageNotes()
  }

  const handleAiConsentAgree = () => {
    saveAiConsent()
    setShowAiConsent(false)
    void runImageNotes()
  }

  const handleReset = () => {
    setImageFile(null)
    setImagePreview(null)
    setAnalysis(null)
    setAnalysisResult(null)
    setError('')
    setHasAnalyzedCurrentImage(false)
    setCurrentHistorySaved(false)
    setCurrentHistorySaving(false)
  }

  useEffect(() => {
    if (!analysisResult) return
    const el = resultRef.current
    if (!el) return
    requestAnimationFrame(() => {
      el.scrollIntoView({ behavior: 'smooth', block: 'start' })
    })
  }, [analysisResult])

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      <PageHeader title="Health Image Notes" />
      <AiConsentModal
        open={showAiConsent}
        onAgree={handleAiConsentAgree}
        onCancel={() => setShowAiConsent(false)}
      />

      {/* Tabs */}
      <div className="max-w-7xl mx-auto w-full px-4 pt-4">
        <div className="bg-white rounded-t-xl border-b border-gray-200">
          <div className="flex">
            <Link
              href="/medical-images"
              style={{ width: '100%' }}
              className={`flex-1 px-4 py-3 text-center font-medium transition-colors ${
                pathname !== '/medical-images/history'
                  ? 'text-helfi-green border-b-2 border-helfi-green'
                  : 'text-gray-600 hover:text-gray-900'
              }`}
            >
              Health Image Notes
            </Link>
            <Link
              href="/medical-images/history"
              style={{ width: '100%' }}
              className={`flex-1 px-4 py-3 text-center font-medium transition-colors ${
                pathname === '/medical-images/history'
                  ? 'text-helfi-green border-b-2 border-helfi-green'
                  : 'text-gray-600 hover:text-gray-900'
              }`}
            >
              History
            </Link>
          </div>
        </div>
      </div>

      {/* Content */}
      <main className="flex-1">
        <div className="mx-auto w-full px-0 sm:px-4 md:max-w-3xl md:px-4 py-6">
          <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4 md:p-6">
            <h1 className="text-xl font-semibold text-gray-900 mb-1">Health Image Notes</h1>
            <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-4">
              <h2 className="text-sm font-semibold text-blue-900 mb-2">What is this feature?</h2>
              <p className="text-sm text-blue-800 mb-2">
                Helfi can create simple notes about visible details in a health-related image so you can track changes and discuss them with a qualified healthcare professional.
              </p>
              <p className="text-sm text-blue-800 font-medium mb-1">Useful for recording:</p>
              <ul className="text-sm text-blue-800 list-disc list-inside space-y-1 ml-2">
                <li>Visible skin changes you want to monitor</li>
                <li>Photos you want to discuss with a doctor</li>
                <li>Wound, nail, eye, or skin appearance notes</li>
                <li>Changes over time for your own records</li>
              </ul>
              <p className="text-xs text-blue-700 mt-3 italic">
                This tool provides general image notes only. It does not diagnose, treat, or replace a doctor's examination.
              </p>
            </div>

            <div className="mb-4 text-xs text-gray-600 bg-white border border-gray-200 rounded-lg p-3">
              <div className="font-semibold text-gray-900 mb-1">General health sources</div>
              <p className="mb-2">
                Helfi uses these public sources as general references. Results are not diagnoses.
              </p>
              <ul className="list-disc list-inside space-y-1">
                <li><a className="text-helfi-green underline" href="https://medlineplus.gov/healthtopics.html" target="_blank" rel="noreferrer">MedlinePlus Health Topics</a></li>
                <li><a className="text-helfi-green underline" href="https://www.mayoclinic.org/healthy-lifestyle" target="_blank" rel="noreferrer">Mayo Clinic Health Information</a></li>
                <li><a className="text-helfi-green underline" href="https://www.nhs.uk/live-well/" target="_blank" rel="noreferrer">NHS Health Information</a></li>
              </ul>
            </div>

            {/* Image Upload */}
            <div className="mb-4">
              {!imagePreview ? (
                <label className="flex flex-col items-center justify-center w-full h-64 border-2 border-gray-300 border-dashed rounded-lg cursor-pointer bg-gray-50 hover:bg-gray-100 transition-colors">
                  <div className="flex flex-col items-center justify-center pt-5 pb-6">
                    <svg className="w-10 h-10 mb-3 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
                    </svg>
                    <p className="mb-2 text-sm text-gray-500">
                      <span className="font-semibold">Click to upload</span> or drag and drop
                    </p>
                    <p className="text-xs text-gray-500">PNG, JPG, GIF up to 10MB</p>
                  </div>
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handleImageSelect}
                    className="hidden"
                  />
                </label>
              ) : (
                <div className="relative">
                  <img
                    src={imagePreview}
                    alt="Preview"
                    className="w-full h-auto rounded-lg border border-gray-200 max-h-96 object-contain bg-gray-50"
                  />
                  <button
                    onClick={handleReset}
