'use client'

import React, { useEffect, useMemo, useRef, useState } from 'react'
import PageHeader from '@/components/PageHeader'
import MoodTabs from '@/components/mood/MoodTabs'
import MoodTrendGraph from '@/components/mood/MoodTrendGraph'
import { emojiForMoodValue } from '@/components/mood/moodScale'
import MoodPieChart from '@/components/mood/MoodPieChart'
import InsightsBottomNav from '@/app/insights/InsightsBottomNav'

export const dynamic = 'force-dynamic'

type MoodEntry = {
  id: string
  localDate: string
  timestamp: string
  mood: number
  tags: any
  note: string
  context: any
}

type EntriesResponse = {
  range: { start: string; end: string }
  entries: MoodEntry[]
}
type SuggestedActionKind = 'breath' | 'walk' | 'hydrate' | 'journal'

function safeTags(tags: any): string[] {
  if (Array.isArray(tags)) return tags.map((t) => String(t)).filter(Boolean)
  if (typeof tags === 'string') {
    try {
      const parsed = JSON.parse(tags)
      if (Array.isArray(parsed)) return parsed.map((t) => String(t)).filter(Boolean)
    } catch {}
  }
  return []
}

function safeContext(ctx: any): Record<string, any> {
  if (!ctx) return {}
  if (typeof ctx === 'object') return ctx
  if (typeof ctx === 'string') {
    try {
      const parsed = JSON.parse(ctx)
      if (parsed && typeof parsed === 'object') return parsed
    } catch {}
  }
  return {}
}

function asDateString(d: Date) {
  const yyyy = d.getFullYear()
  const mm = String(d.getMonth() + 1).padStart(2, '0')
  const dd = String(d.getDate()).padStart(2, '0')
  return `${yyyy}-${mm}-${dd}`
}

function parseLocalDate(localDate: string) {
  return new Date(`${localDate}T00:00:00.000Z`)
}

function shiftDays(localDate: string, deltaDays: number) {
  const d = parseLocalDate(localDate)
  d.setUTCDate(d.getUTCDate() + deltaDays)
  return asDateString(d)
}

function daysBetweenInclusive(start: string, end: string) {
  const a = parseLocalDate(start)
  const b = parseLocalDate(end)
  const diff = Math.round((b.getTime() - a.getTime()) / (24 * 60 * 60 * 1000))
  return Math.max(1, diff + 1)
}

function moodSummaryFromAverage(avg: number) {
  if (avg >= 6.3) return 'Mostly Amazing'
  if (avg >= 5.5) return 'Mostly Great'
  if (avg >= 4.7) return 'Mostly Good'
  if (avg >= 3.8) return 'Mostly Okay'
  if (avg >= 2.8) return 'Mostly Meh'
  if (avg >= 1.8) return 'Mostly Bad'
  return 'Mostly Terrible'
}

function dotColorForAvg(avg: number | null) {
  if (avg == null) return 'bg-gray-300 dark:bg-gray-600'
  if (avg >= 5) return 'bg-green-400'
  if (avg >= 3.5) return 'bg-yellow-400'
  return 'bg-red-400'
}

function firstDayOfMonth(localDate: string) {
  const d = parseLocalDate(localDate)
  d.setUTCDate(1)
  return asDateString(d)
}

function lastDayOfMonth(localDate: string) {
  const d = parseLocalDate(localDate)
  d.setUTCMonth(d.getUTCMonth() + 1)
  d.setUTCDate(0)
  return asDateString(d)
}

function mondayIndexFromUtcDate(localDate: string) {
  // 0..6 where 0 is Monday
  const d = parseLocalDate(localDate)
  const dow = d.getUTCDay() // 0 Sun ... 6 Sat
  return (dow + 6) % 7
}

function formatDayLabel(localDate: string) {
  const today = asDateString(new Date())
  const yesterday = shiftDays(today, -1)
  if (localDate === today) return 'Today'
  if (localDate === yesterday) return 'Yesterday'
  const d = new Date(`${localDate}T00:00:00`)
  return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' })
}

function entryDayKey(entry: MoodEntry) {
  const localDate = String(entry.localDate || '').slice(0, 10)
  if (localDate) return localDate
  const ts = new Date(entry.timestamp)
  if (!Number.isNaN(ts.getTime())) return asDateString(ts)
  return ''
}

function monthLabelFromDate(localDate: string) {
  const d = parseLocalDate(localDate)
  return d.toLocaleDateString(undefined, { month: 'short' })
}

function actionDetails(kind: SuggestedActionKind) {
  if (kind === 'breath') {
    return {
      title: 'Next best step: 60-second reset',
      detail: 'Take six slow breaths. In 4 seconds, out 6 seconds.',
    }
  }
  if (kind === 'walk') {
    return {
      title: 'Next best step: 5-minute walk',
      detail: 'A short walk can quickly improve energy and mood.',
    }
  }
  if (kind === 'journal') {
    return {
      title: 'Next best step: write 2 lines',
      detail: 'Capture what worked so you can repeat it tomorrow.',
    }
  }
  return {
    title: 'Next best step: hydrate now',
    detail: 'Drink a glass of water to help stabilize focus and mood.',
  }
}

export default function MoodHistoryPage() {
  const [timeframe, setTimeframe] = useState<'day' | 'week' | 'month' | 'year'>('week')
  const [chartMode, setChartMode] = useState<'pie' | 'wave'>('wave')
  const [selectedDay, setSelectedDay] = useState<string | null>(null)
  const [entries, setEntries] = useState<MoodEntry[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [trendPct, setTrendPct] = useState<number | null>(null)
  const [yearAverageMap, setYearAverageMap] = useState<Map<string, number>>(new Map())
  const [streakDays, setStreakDays] = useState<number>(0)
  const [expandedDays, setExpandedDays] = useState<Record<string, boolean>>({})
  const [recentEntries, setRecentEntries] = useState<MoodEntry[]>([])
  const [showAllEntries, setShowAllEntries] = useState(false)
  const [openEntryMenu, setOpenEntryMenu] = useState<string | null>(null)
  const [savedAction, setSavedAction] = useState<SuggestedActionKind | null>(null)
  const [breathingActive, setBreathingActive] = useState(false)
  const [breathingSecondsLeft, setBreathingSecondsLeft] = useState(60)
  const weekScrollRef = useRef<HTMLDivElement | null>(null)

  const [banner, setBanner] = useState<string | null>(null)
  useEffect(() => {
    try {
      const params = new URLSearchParams(window.location.search || '')
      if (params.get('saved') === '1') {
        setBanner('Saved mood check‑in.')
        const t = setTimeout(() => setBanner(null), 2500)
        const action = params.get('action')
        if (action === 'breath' || action === 'walk' || action === 'hydrate' || action === 'journal') {
          setSavedAction(action)
        }
        return () => clearTimeout(t)
      }
    } catch {}
  }, [])

  useEffect(() => {
    if (!breathingActive) return
    if (breathingSecondsLeft <= 0) {
      setBreathingActive(false)
      return
    }
    const timer = window.setTimeout(() => setBreathingSecondsLeft((value) => value - 1), 1000)
    return () => window.clearTimeout(timer)
  }, [breathingActive, breathingSecondsLeft])

  useEffect(() => {
    try {
      const storedTimeframe = localStorage.getItem('moodHistoryTimeframe') as any
      const storedChartMode = localStorage.getItem('moodHistoryChartMode') as any
      if (storedTimeframe === 'day' || storedTimeframe === 'week' || storedTimeframe === 'month' || storedTimeframe === 'year') {
        setTimeframe(storedTimeframe)
      }
      if (storedChartMode === 'pie' || storedChartMode === 'wave') {
        setChartMode(storedChartMode)
      }
    } catch {}
  }, [])

  useEffect(() => {
    try {
      localStorage.setItem('moodHistoryTimeframe', timeframe)
    } catch {}
  }, [timeframe])

  useEffect(() => {
    try {
      localStorage.setItem('moodHistoryChartMode', chartMode)
    } catch {}
  }, [chartMode])

  useEffect(() => {
    let ignore = false
    const today = asDateString(new Date())

    const range = (() => {
      if (timeframe === 'day') {
        const base = selectedDay || today
        return { start: shiftDays(base, -6), end: base }
      }
      if (timeframe === 'week') return { start: shiftDays(today, -6), end: today }
      if (timeframe === 'month') return { start: shiftDays(today, -29), end: today }
      return { start: shiftDays(today, -364), end: today }
    })()

    const load = async () => {
      let hasCache = false
      try {
        const cacheKey = `moodHistoryCache:${range.start}:${range.end}`
        const cachedRaw = sessionStorage.getItem(cacheKey)
        if (cachedRaw) {
          const cached = JSON.parse(cachedRaw)
          if (Array.isArray(cached?.entries)) {
            setEntries(cached.entries)
            hasCache = true
          }
        }
      } catch {}

      setLoading(!hasCache)
      setError(null)
      try {
        const curRes = await fetch(`/api/mood/entries?start=${range.start}&end=${range.end}`, { cache: 'no-store' as any })
        if (!curRes.ok) throw new Error('Failed to load')
        const cur = (await curRes.json()) as EntriesResponse
        if (ignore) return
        setEntries(Array.isArray(cur.entries) ? cur.entries : [])
        try {
          const cacheKey = `moodHistoryCache:${range.start}:${range.end}`
          sessionStorage.setItem(cacheKey, JSON.stringify({ entries: cur.entries, cachedAt: Date.now() }))
        } catch {}
        if (!ignore) setLoading(false)

        const days = daysBetweenInclusive(range.start, range.end)
        const prev = {
          start: shiftDays(range.start, -days),
          end: shiftDays(range.start, -1),
        }

        void (async () => {
          try {
            const prevRes = await fetch(`/api/mood/entries?start=${prev.start}&end=${prev.end}`, { cache: 'no-store' as any })
            if (!prevRes.ok) throw new Error('Failed to load previous')
            const prevData = (await prevRes.json()) as EntriesResponse
            if (ignore) return
            const avgMood = (list: MoodEntry[]) => {
              const nums = list.map((e) => Number(e.mood)).filter((n) => Number.isFinite(n))
              if (nums.length === 0) return null
              return nums.reduce((a, b) => a + b, 0) / nums.length
            }
            const curAvg = avgMood(cur.entries || [])
            const prevAvg = avgMood(prevData.entries || [])
            if (curAvg != null && prevAvg != null && prevAvg > 0) {
              setTrendPct(((curAvg - prevAvg) / prevAvg) * 100)
            } else {
              setTrendPct(null)
            }
          } catch {
            if (!ignore) setTrendPct(null)
          }
        })()

      } catch (e: any) {
        if (!ignore) setError(e?.message || 'Failed to load history')
      } finally {
        if (!ignore && !hasCache) setLoading(false)
      }
    }
    load()
    return () => { ignore = true }
  }, [timeframe, selectedDay])

  useEffect(() => {
    let ignore = false
    const today = asDateString(new Date())
    const start = shiftDays(today, -6)
    const end = today
    const loadRecent = async () => {
      try {
        const res = await fetch(`/api/mood/entries?start=${start}&end=${end}`, { cache: 'no-store' as any })
        if (!res.ok) return
        const j = (await res.json()) as EntriesResponse
        if (!ignore) setRecentEntries(Array.isArray(j.entries) ? j.entries : [])
      } catch {}
    }
    loadRecent()
    return () => { ignore = true }
  }, [entries])

  useEffect(() => {
    let ignore = false
    const today = asDateString(new Date())
    const start = shiftDays(today, -364)
    const end = today
    const loadStreak = async () => {
      try {
        const res = await fetch(`/api/mood/entries?start=${start}&end=${end}`, { cache: 'no-store' as any })
        if (!res.ok) return
        const j = (await res.json()) as EntriesResponse
        if (ignore) return
        const daysWithEntries = new Set<string>()
        for (const e of j.entries || []) {
          const d = String(e.localDate || '').slice(0, 10)
          if (d) daysWithEntries.add(d)
        }
        let streak = 0
        let cursor = today
        while (daysWithEntries.has(cursor)) {
          streak += 1
          cursor = shiftDays(cursor, -1)
          if (streak > 365) break
        }

        const sums = new Map<string, { sum: number; n: number }>()
        for (const entry of j.entries || []) {
          const day = String(entry.localDate || '').slice(0, 10)
          const mood = Number(entry.mood)
          if (!day || !Number.isFinite(mood)) continue
          const current = sums.get(day) || { sum: 0, n: 0 }
          current.sum += mood
          current.n += 1
          sums.set(day, current)
        }
        const averages = new Map<string, number>()
        sums.forEach((value, day) => {
          averages.set(day, value.sum / Math.max(1, value.n))
        })
        setStreakDays(streak)
        setYearAverageMap(averages)
      } catch {}
    }
    loadStreak()
    return () => { ignore = true }
  }, [])

  const chartEntries = useMemo(() => {
    if (timeframe !== 'day' && timeframe !== 'week') return entries
    if (timeframe === 'day' && selectedDay) return entries
    if (recentEntries.length === 0) return entries
    const merged = new Map<string, MoodEntry>()
    for (const entry of entries) merged.set(entry.id, entry)
    for (const entry of recentEntries) merged.set(entry.id, entry)
    return Array.from(merged.values())
  }, [entries, recentEntries, timeframe, selectedDay])

  const points = useMemo(() => {
    const xs = chartEntries
      .slice()
      .sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime())
      .map((e) => ({ timestamp: e.timestamp, mood: Number(e.mood) }))
    return xs
  }, [chartEntries])

  const daySeries = useMemo(() => {
    const map = new Map<string, MoodEntry[]>()
    for (const entry of chartEntries) {
      const day = entryDayKey(entry)
      if (!day) continue
      if (!map.has(day)) map.set(day, [])
      map.get(day)!.push(entry)
    }

    const today = asDateString(new Date())
    const base = timeframe === 'day' ? (selectedDay || today) : today
    const days = (timeframe === 'week' || timeframe === 'day')
      ? Array.from({ length: 7 }, (_, i) => shiftDays(base, i - 6))
      : Array.from(map.keys()).sort((a, b) => parseLocalDate(a).getTime() - parseLocalDate(b).getTime())

    return days.map((day) => {
      const items = (map.get(day) || []).slice().sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime())
      return {
        day,
        label: formatDayLabel(day),
        points: items.map((e) => ({ timestamp: e.timestamp, mood: Number(e.mood) })),
      }
    })
  }, [chartEntries, timeframe, selectedDay])

  const weekSummaryPoints = useMemo(() => {
    if (timeframe !== 'week') return []
    return daySeries.map((day) => {
      const counts = new Map<number, number>()
      for (const point of day.points) {
        const value = Number(point.mood)
        if (!Number.isFinite(value)) continue
        counts.set(value, (counts.get(value) || 0) + 1)
      }
      let topMood: number | null = null
      let topCount = -1
      counts.forEach((count, mood) => {
        if (count > topCount) {
          topCount = count
          topMood = mood
        } else if (count === topCount && topMood != null && mood > topMood) {
          topMood = mood
        }
      })
      const stamp = new Date(`${day.day}T12:00:00`)
      return {
        timestamp: Number.isNaN(stamp.getTime()) ? `${day.day}T12:00:00` : stamp.toISOString(),
        mood: topMood,
        label: day.label,
      }
    })
  }, [daySeries, timeframe])

  useEffect(() => {
    if (timeframe !== 'week' && timeframe !== 'day') return
    if (loading) return
    const el = weekScrollRef.current
    if (!el) return
    const scrollToEnd = () => {
      const target = Math.max(0, el.scrollWidth - el.clientWidth)
      el.scrollLeft = target
    }
    requestAnimationFrame(() => {
      scrollToEnd()
      setTimeout(scrollToEnd, 160)
      setTimeout(scrollToEnd, 320)
    })
  }, [timeframe, daySeries.length, loading])

  const recentGroups = useMemo(() => {
    const source = timeframe === 'day'
      ? (recentEntries.length ? recentEntries : chartEntries)
      : chartEntries
    const sorted = source
      .slice()
      .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())
    const map = new Map<string, MoodEntry[]>()
    const order: string[] = []
    for (const entry of sorted) {
      const day = entryDayKey(entry)
      if (!day) continue
      if (!map.has(day)) {
        map.set(day, [])
        order.push(day)
      }
      map.get(day)!.push(entry)
    }
    return order.slice(0, 3).map((day) => ({
      day,
      entries: (map.get(day) || []).slice().sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()),
    }))
  }, [chartEntries, recentEntries, timeframe])

  const formatTime = (ts: any) => {
    try {
      const d = new Date(ts)
      if (Number.isNaN(d.getTime())) return ''
      return d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })
    } catch {
      return ''
    }
  }

  const dailyAverages = useMemo(() => {
    const sums = new Map()
    for (const e of chartEntries) {
      const d = String(e.localDate || '').slice(0, 10)
      const v = Number(e.mood)
      if (!d || !Number.isFinite(v)) continue
      const cur = sums.get(d) || { sum: 0, n: 0 }
      cur.sum += v
      cur.n += 1
      sums.set(d, cur)
    }
    const avg = new Map()
    sums.forEach((v, d) => avg.set(d, v.sum / v.n))
    return avg
  }, [chartEntries])

  const overallAverage = useMemo(() => {
    const nums = chartEntries.map((e) => Number(e.mood)).filter((n) => Number.isFinite(n))
    if (nums.length === 0) return null
    return nums.reduce((a, b) => a + b, 0) / nums.length
  }, [chartEntries])

  const hasEntries = useMemo(() => {
    if (timeframe === 'week') return weekSummaryPoints.some((p) => Number.isFinite(p.mood))
    return points.length > 0
  }, [timeframe, weekSummaryPoints, points.length])

  const topMood = useMemo(() => {
    const counts = new Map()
    for (const e of chartEntries) {
      const v = Number(e.mood)
      if (!Number.isFinite(v)) continue
      counts.set(v, (counts.get(v) || 0) + 1)
    }
    let best: { mood: number; n: number } | null = null
    counts.forEach((n, mood) => {
      if (!best || n > best.n) best = { mood, n }
    })
    return best
  }, [chartEntries])

  const topMoodValue = (topMood as any)?.mood as number | null
  const topMoodCount = (topMood as any)?.n as number | null
  const entriesToRender = showAllEntries ? entries.slice(0, 12) : entries.slice(0, 5)
  const hasMoreEntries = entries.length > 5

  const monthGrid = useMemo(() => {
    const today = asDateString(new Date())
    const start = firstDayOfMonth(today)
    const end = lastDayOfMonth(today)
    const daysInMonth = Number(end.slice(8, 10))
    const pad = mondayIndexFromUtcDate(start)
    const cells: any[] = []
    for (let i = 0; i < pad; i++) cells.push({ type: 'pad' })
    for (let day = 1; day <= daysInMonth; day++) {
      const d = start.slice(0, 8) + String(day).padStart(2, '0')
      cells.push({ type: 'day', date: d, day, avg: yearAverageMap.get(d) ?? null })
    }
    return { cells, today }
  }, [yearAverageMap])

  const yearPixels = useMemo(() => {
    const months: Array<{ key: string; label: string; cells: any[] }> = []
    const now = new Date()
    for (let i = 11; i >= 0; i--) {
      const monthDate = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - i, 1))
      const monthStart = asDateString(monthDate)
      const monthEndDate = new Date(Date.UTC(monthDate.getUTCFullYear(), monthDate.getUTCMonth() + 1, 0))
      const monthEnd = asDateString(monthEndDate)
      const daysInMonth = Number(monthEnd.slice(8, 10))
      const pad = mondayIndexFromUtcDate(monthStart)
      const cells: any[] = []
      for (let j = 0; j < pad; j++) cells.push({ type: 'pad' })
      for (let day = 1; day <= daysInMonth; day++) {
        const date = monthStart.slice(0, 8) + String(day).padStart(2, '0')
        cells.push({ type: 'day', date, avg: yearAverageMap.get(date) ?? null })
      }
      months.push({
        key: monthStart,
        label: monthLabelFromDate(monthStart),
        cells,
      })
    }
    return months
  }, [yearAverageMap])

  const handleShareSummary = async () => {
    const summary = [
      `Helfi mood summary (${timeframe})`,
      overallAverage == null ? 'Average mood: no data yet' : `Average mood: ${overallAverage.toFixed(1)} / 7`,
      topMoodValue == null ? 'Top mood: no data yet' : `Top mood: ${emojiForMoodValue(topMoodValue)} (${topMoodCount || 0} times)`,
      `Current streak: ${streakDays} day${streakDays === 1 ? '' : 's'}`,
    ].join('\n')

    try {
      if (navigator.share) {
        await navigator.share({
          title: 'Helfi mood summary',
          text: summary,
        })
        return
      }
    } catch {}

    try {
      await navigator.clipboard.writeText(summary)
      setBanner('Mood summary copied.')
      setTimeout(() => setBanner(null), 2000)
    } catch {}
  }

  const clearMoodHistoryCache = () => {
    try {
      for (let index = sessionStorage.length - 1; index >= 0; index -= 1) {
        const key = sessionStorage.key(index)
        if (key?.startsWith('moodHistoryCache:')) sessionStorage.removeItem(key)
      }
    } catch {}
  }

  const editMoodEntry = async (entry: MoodEntry) => {
    const moodInput = window.prompt('Mood score from 1 (terrible) to 7 (amazing):', String(entry.mood))
    if (moodInput === null) return
    const mood = Math.round(Number(moodInput))
    if (!Number.isFinite(mood) || mood < 1 || mood > 7) {
      alert('Please enter a number from 1 to 7.')
      return
    }
    const note = window.prompt('Update your note (optional):', entry.note || '')
    if (note === null) return
    const res = await fetch('/api/mood/entries', {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: entry.id, mood, note, tags: safeTags(entry.tags) }),
    })
    if (!res.ok) {
      alert('Could not update this mood check-in.')
      return
    }
    const applyUpdate = (item: MoodEntry) => item.id === entry.id ? { ...item, mood, note } : item
    setEntries((current) => current.map(applyUpdate))
    setRecentEntries((current) => current.map(applyUpdate))
    clearMoodHistoryCache()
    setOpenEntryMenu(null)
    setBanner('Mood check-in updated.')
  }

  const deleteMoodEntry = async (entry: MoodEntry) => {
    if (!window.confirm('Delete this mood check-in? This cannot be undone.')) return
    const res = await fetch('/api/mood/entries', {
      method: 'DELETE',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: entry.id }),
    })
    if (!res.ok) {
      alert('Could not delete this mood check-in.')
      return
    }
    setEntries((current) => current.filter((item) => item.id !== entry.id))
    setRecentEntries((current) => current.filter((item) => item.id !== entry.id))
    clearMoodHistoryCache()
    setOpenEntryMenu(null)
    setBanner('Mood check-in deleted.')
  }

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 pb-24">
      <PageHeader title="Mood" backHref="/mood" />
      <MoodTabs />

      <main className="max-w-3xl mx-auto px-4 py-6">
        {banner && (
          <div className="mb-4 rounded-xl border border-green-200 bg-green-50 text-green-800 px-4 py-3 text-sm">
            {banner}
          </div>
        )}

        {savedAction && (
          <div className="mb-4 rounded-2xl border border-emerald-200 bg-emerald-50 px-4 py-3">
            <div className="text-[11px] font-bold uppercase tracking-wider text-emerald-700">Right after check-in</div>
            <div className="mt-1 text-sm font-bold text-emerald-900">{actionDetails(savedAction).title}</div>
            <div className="mt-1 text-xs text-emerald-800">{actionDetails(savedAction).detail}</div>
            {savedAction === 'breath' && (
              <div className="mt-3 flex items-center gap-2">
                <button
                  type="button"
                  onClick={() => {
                    setBreathingSecondsLeft(60)
                    setBreathingActive(true)
                  }}
                  className="rounded-xl bg-emerald-600 text-white text-xs font-semibold px-3 py-2"
                >
                  {breathingActive ? `Reset running: ${breathingSecondsLeft}s` : 'Start 60s breathing'}
                </button>
                {breathingActive && (
                  <button
                    type="button"
                    onClick={() => {
                      setBreathingActive(false)
                      setBreathingSecondsLeft(60)
                    }}
                    className="rounded-xl border border-emerald-300 text-emerald-700 text-xs font-semibold px-3 py-2"
                  >
                    Stop
                  </button>
                )}
              </div>
            )}
          </div>
        )}

        <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-sm border border-gray-100 dark:border-gray-700 p-4">
          <div className="flex h-12 w-full items-center justify-between rounded-full bg-white dark:bg-gray-800 p-1.5 shadow-sm border border-gray-100 dark:border-gray-700">
            {(['day', 'week', 'month', 'year'] as const).map((t) => {
              const active = timeframe === t
              const label = t === 'day' ? 'Day' : t[0].toUpperCase() + t.slice(1)
              return (
                <button
                  key={t}
                  type="button"
                  onClick={() => {
                    setTimeframe(t)
                    if (t !== 'day') setSelectedDay(null)
                  }}
                  className="relative flex flex-1 h-full items-center justify-center rounded-full transition-all"
                >
                  <span className={`z-10 text-sm font-semibold ${active ? 'text-white' : 'text-gray-600 dark:text-gray-300'}`}>
                    {label}
                  </span>
                  <span className={`absolute inset-0 rounded-full bg-helfi-green transition-all duration-300 ${active ? 'opacity-100 scale-100' : 'opacity-0 scale-95'}`} />
                </button>
              )
            })}
          </div>

          <div className="mt-3 flex items-center justify-end gap-2">
            <button
              type="button"
              onClick={handleShareSummary}
              className="rounded-full border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 px-3 py-1.5 text-xs font-semibold text-gray-700 dark:text-gray-200"
            >
              Share summary
            </button>
          </div>

          <div className="mt-4">
            <div className="flex items-center justify-between mb-4">
              <div className="flex flex-col gap-1">
                <h3 className="text-gray-500 dark:text-gray-300 text-sm font-bold uppercase tracking-wider">
                  {chartMode === 'pie' ? 'Mood Breakdown' : 'Mood Wave'}
                </h3>
                <div className="flex items-baseline gap-2 flex-wrap">
                  <p className="text-3xl font-bold tracking-tight text-gray-900 dark:text-white">
                    {overallAverage == null ? 'No data yet' : moodSummaryFromAverage(overallAverage)}
                  </p>
                  {trendPct != null && (
                    <span className="inline-flex items-center gap-1 text-helfi-green text-sm font-bold bg-helfi-green/10 px-2 py-0.5 rounded-full">
                      <span className="material-symbols-outlined text-sm leading-none">trending_up</span>
                      {Math.abs(trendPct).toFixed(0)}%
                    </span>
                  )}
                </div>
              </div>
              <div className="flex items-center rounded-full border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 p-1">
                {(['pie', 'wave'] as const).map((mode) => {
                  const active = chartMode === mode
                  return (
                    <button
                      key={mode}
                      type="button"
                      onClick={() => setChartMode(mode)}
                      className={[
                        'px-3 py-1 rounded-full text-xs font-semibold transition-colors',
                        active ? 'bg-helfi-green text-white' : 'text-gray-600 dark:text-gray-300',
                      ].join(' ')}
                    >
                      {mode === 'pie' ? 'Pie' : 'Wave'}
                    </button>
                  )
                })}
              </div>
            </div>

	            {loading ? (
	              <div className="flex items-center justify-center py-12">
	                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-helfi-green"></div>
	              </div>
	            ) : error ? (
	              <div className="rounded-xl border border-red-200 bg-red-50 text-red-700 px-4 py-3 text-sm">
	                {error}
	              </div>
            ) : !hasEntries ? (
	              <div className="rounded-xl border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/60 text-gray-600 dark:text-gray-300 px-4 py-6 text-sm">
	                No mood entries yet. Add your first check‑in from the Mood tab.
	              </div>
	            ) : (
                <div className="space-y-4">
                  {timeframe === 'day' ? (
                    <div className="space-y-2">
                      <div className="text-xs text-gray-500 dark:text-gray-400">
                        Swipe left or right to view each day.
                      </div>
                      <div
                        ref={weekScrollRef}
                        className="flex gap-4 overflow-x-auto snap-x snap-mandatory pb-2 -mx-4 px-4 touch-pan-x"
                      >
                        {daySeries.map((day) => (
                          <div key={day.day} className="min-w-full snap-center">
                            <div className="text-sm font-semibold text-gray-800 dark:text-gray-100 mb-2">
                              {day.label}
                            </div>
                            <div className="relative h-[220px] w-full rounded-2xl bg-white dark:bg-gray-900 shadow-sm border border-gray-100 dark:border-gray-700 p-4 overflow-visible">
                              {chartMode === 'pie' ? (
                                <MoodPieChart entries={day.points} />
                              ) : (
                                <MoodTrendGraph points={day.points} showTimeAxis />
                              )}
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  ) : timeframe === 'week' ? (
                    <div className="space-y-2">
                      <div className="text-xs text-gray-500 dark:text-gray-400">
                        Weekly summary of your most common mood each day.
                      </div>
                      <div className="relative h-[220px] w-full rounded-2xl bg-white dark:bg-gray-900 shadow-sm border border-gray-100 dark:border-gray-700 p-4 overflow-visible">
                        {chartMode === 'pie' ? (
                          <MoodPieChart entries={chartEntries} />
                        ) : (
                          <MoodTrendGraph points={weekSummaryPoints} fillArea={false} spanGaps />
                        )}
                      </div>
                    </div>
                  ) : (
                    <div className="relative h-[220px] w-full rounded-2xl bg-white dark:bg-gray-900 shadow-sm border border-gray-100 dark:border-gray-700 p-4 overflow-visible">
                      {chartMode === 'pie' ? (
                        <MoodPieChart entries={entries} />
                      ) : (
                        <MoodTrendGraph points={points} />
                      )}
                    </div>
                  )}
                  <div className="rounded-2xl bg-white dark:bg-gray-900 border border-gray-100 dark:border-gray-700 p-4">
                    <div className="text-xs font-bold uppercase tracking-wider text-gray-500 dark:text-gray-300 mb-3">
                      Recent check‑ins
                    </div>
                    {recentGroups.length === 0 ? (
                      <div className="text-sm text-gray-500 dark:text-gray-400">
                        No check‑ins yet.
                      </div>
                    ) : (
                      <div className="space-y-2">
                        {recentGroups.map((group) => {
                          const expanded = !!expandedDays[group.day]
                          return (
                            <div
                              key={group.day}
                              className="rounded-xl border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800/60 overflow-hidden"
                            >
                              <button
                                type="button"
                                onClick={() =>
                                  setExpandedDays((prev) => ({
                                    ...prev,
                                    [group.day]: !prev[group.day],
                                  }))
                                }
                                className="w-full flex items-center justify-between px-3 py-2"
                              >
                                <div className="flex items-center gap-2">
                                  <span className="text-sm font-semibold text-gray-800 dark:text-gray-100">
                                    {formatDayLabel(group.day)}
                                  </span>
                                  <span className="text-xs text-gray-500 dark:text-gray-400">
                                    {group.entries.length} check‑in{group.entries.length === 1 ? '' : 's'}
                                  </span>
                                </div>
                                <span
                                  className={[
                                    'material-symbols-outlined text-base text-gray-500 transition-transform',
                                    expanded ? 'rotate-180' : '',
                                  ].join(' ')}
                                >
                                  expand_more
                                </span>
                              </button>
                              {expanded && (
                                <div className="flex flex-wrap gap-2 px-3 pb-3">
                                  {group.entries.map((e) => (
                                    <div
                                      key={e.id}
                                      className="relative inline-flex items-center gap-2 rounded-full border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800 px-3 py-2"
                                    >
                                      <span className="text-lg leading-none">{emojiForMoodValue(Number(e.mood))}</span>
                                      <span className="text-sm font-semibold text-gray-800 dark:text-gray-200">
                                        {formatTime(e.timestamp)}
                                      </span>
                                      <button
                                        type="button"
                                        aria-label={`Actions for mood check-in at ${formatTime(e.timestamp)}`}
                                        onClick={() => setOpenEntryMenu((current) => current === e.id ? null : e.id)}
                                        className="rounded-full px-1 text-gray-500 hover:text-gray-900 dark:hover:text-white"
                                      >
                                        ⋯
                                      </button>
                                      {openEntryMenu === e.id && (
                                        <div className="absolute right-0 top-full z-20 mt-1 min-w-28 overflow-hidden rounded-lg border border-gray-200 bg-white shadow-lg dark:border-gray-700 dark:bg-gray-900">
                                          <button type="button" onClick={() => void editMoodEntry(e)} className="block w-full px-3 py-2 text-left text-sm hover:bg-gray-50 dark:hover:bg-gray-800">Edit</button>
                                          <button type="button" onClick={() => void deleteMoodEntry(e)} className="block w-full px-3 py-2 text-left text-sm text-red-600 hover:bg-red-50 dark:hover:bg-gray-800">Delete</button>
                                        </div>
                                      )}
                                    </div>
                                  ))}
                                </div>
                              )}
                            </div>
                          )
                        })}
                      </div>
                    )}
                  </div>
                </div>
	            )}
	          </div>
	        </div>

        <div className="px-1 mt-5">
          <h3 className="text-gray-900 dark:text-white text-lg font-bold mb-3">Highlights</h3>
          <div className="grid grid-cols-2 gap-3">
            <div className="bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm border border-gray-100 dark:border-gray-700">
              <p className="text-gray-500 dark:text-gray-300 text-[11px] font-bold uppercase tracking-wider">Top Mood</p>
              <div className="mt-2 flex items-center justify-between">
                <div className="text-3xl leading-none">{topMoodValue ? emojiForMoodValue(topMoodValue) : '🙂'}</div>
                <span className="text-xs font-semibold text-helfi-green bg-helfi-green/10 px-2 py-1 rounded-md">
                  {topMoodCount ? `${topMoodCount}x` : '0x'}
                </span>
              </div>
            </div>
            <div className="bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm border border-gray-100 dark:border-gray-700">
              <p className="text-gray-500 dark:text-gray-300 text-[11px] font-bold uppercase tracking-wider">Streak</p>
              <div className="mt-2 flex items-center gap-2">
