              )
            })}
          </div>
          {hasMoreEntries && (
            <div className="mt-3 px-1">
              <button
                type="button"
                onClick={() => setShowAllEntries((prev) => !prev)}
                className="text-sm font-semibold text-helfi-green hover:underline"
