              </button>
            </div>
          )}
        </div>
      </main>

      <InsightsBottomNav />
    </div>
  )
}

function minutesToHours(minutes: number | null) {
  if (!minutes) return '—'
  const hrs = minutes / 60
  return `${hrs.toFixed(1)} h`
}

