                  onChange={(e) => setTime3(e.target.value)}
                  disabled={!enabled}
                  className="rounded-xl border border-slate-200 dark:border-gray-700 bg-white dark:bg-gray-900 px-3 py-2 text-sm text-slate-800 dark:text-white disabled:opacity-50"
