import MedicalDisclaimerBanner from '@/components/marketing/MedicalDisclaimerBanner'
import PublicFooter from '@/components/marketing/PublicFooter'
import PublicHeader from '@/components/marketing/PublicHeader'
import { newsPostBySlug, newsPosts } from '@/data/news-posts'
import { absoluteUrl } from '@/lib/site-url'

type NewsArticlePageProps = {
  params: {
    slug: string
  }
}

export function generateStaticParams() {
  return newsPosts.map((post) => ({ slug: post.slug }))
}

export function generateMetadata({ params }: NewsArticlePageProps): Metadata {
  const post = newsPostBySlug.get(params.slug)

  if (!post) {
    return {
      title: 'Article not found | Helfi News',
    }
  }

  const socialImage = post.heroImage ? absoluteUrl(post.heroImage) : absoluteUrl('/icons/app-1024.png')

  return {
    title: post.seoTitle,
    description: post.seoDescription,
    alternates: {
      canonical: absoluteUrl(`/news/${post.slug}`),
    },
    openGraph: {
      title: post.seoTitle,
      description: post.seoDescription,
      url: absoluteUrl(`/news/${post.slug}`),
      type: 'article',
      publishedTime: new Date(post.publishedAt).toISOString(),
      modifiedTime: new Date(post.updatedAt).toISOString(),
      authors: [post.author],
      images: [
        {
          url: socialImage,
          alt: post.heroImageAlt || post.title,
        },
      ],
    },
    twitter: {
      card: 'summary_large_image',
      title: post.seoTitle,
      description: post.seoDescription,
      images: [socialImage],
    },
  }
}

function formatDate(value: string) {
  return new Date(value).toLocaleDateString('en-US', {
    month: 'long',
    day: 'numeric',
    year: 'numeric',
  })
}

function formatReadingTime(value: string) {
  const match = value.match(/\d+/)
  if (!match) return value
  return `About ${match[0]} minutes`
}

