  { label: 'Urology', category: 'GPs & Doctors', subcategory: 'Urologist', icon: 'water_drop', tone: 'text-blue-700' },
]

const SYMPTOM_CATEGORY_HINTS = PRACTITIONER_SYMPTOM_HINTS
const SEARCH_WORD_EQUIVALENTS: Record<string, string> = {
  sore: 'pain',
  aching: 'pain',
  ache: 'pain',
  hurts: 'pain',
  hurt: 'pain',
  feet: 'foot',
}

const normalizeSearchText = (value: string) =>
  String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()

const compactSearchText = (value: string) => normalizeSearchText(value).replace(/\s+/g, '')

const normalizeSearchWord = (word: string) => {
  const mapped = SEARCH_WORD_EQUIVALENTS[word] || word
  if (mapped.endsWith('s') && mapped.length > 3) return mapped.slice(0, -1)
  return mapped
}

const tokenizeSearchText = (value: string) =>
  normalizeSearchText(value)
    .split(' ')
    .filter(Boolean)
    .map(normalizeSearchWord)

const matchesSearchText = (source: string, input: string) => {
  const normalizedSource = normalizeSearchText(source)
  const normalizedInput = normalizeSearchText(input)
  if (!normalizedSource || !normalizedInput) return false
  if (normalizedSource.includes(normalizedInput) || normalizedInput.includes(normalizedSource)) return true

  const compactSource = compactSearchText(source)
  const compactInput = compactSearchText(input)
  if (compactSource.includes(compactInput) || compactInput.includes(compactSource)) return true

  const sourceTokens = tokenizeSearchText(source)
  const inputTokens = tokenizeSearchText(input)
  if (!sourceTokens.length || !inputTokens.length) return false
  return inputTokens.every((token) => sourceTokens.includes(token))
}

export default function PractitionerDirectoryPage() {
  const { data: session, status } = useSession()
  const showSignedInUserFlow = status === 'authenticated'
  const [quickAccessOpen, setQuickAccessOpen] = useState(false)
  const [categories, setCategories] = useState<CategoryNode[]>([])
  const [categoryId, setCategoryId] = useState('')
  const [subcategoryId, setSubcategoryId] = useState('')
  const [query, setQuery] = useState('')
  const [locationQuery, setLocationQuery] = useState('')
  const [locationResults, setLocationResults] = useState<LocationResult[]>([])
  const [selectedLocation, setSelectedLocation] = useState<LocationResult | null>(null)
  const [radiusKm, setRadiusKm] = useState(10)
  const [telehealthOnly, setTelehealthOnly] = useState(false)
  const [results, setResults] = useState<SearchResult[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [pendingScroll, setPendingScroll] = useState(false)
  const [pullOffset, setPullOffset] = useState(0)
  const [pullRefreshing, setPullRefreshing] = useState(false)
  const subcategoryRef = useRef<HTMLSelectElement | null>(null)
  const resultsRef = useRef<HTMLDivElement | null>(null)
  const pullStartYRef = useRef<number | null>(null)
  const pullOffsetRef = useRef(0)
  const pullScrollParentRef = useRef<HTMLElement | null>(null)
  const pullRefreshingRef = useRef(false)

  const isValidEmail = (value: string | null | undefined) => {
    if (!value) return false
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())
  }

  const persistLocation = (location: LocationResult) => {
    try {
      localStorage.setItem('helfi:practitionerLocation', JSON.stringify(location))
    } catch {
      // Ignore storage errors
    }
  }

  const geoKey = useMemo(() => {
    if (!selectedLocation) return ''
    const country = String(selectedLocation.country || '').trim().toLowerCase()
    return country ? country : ''
  }, [selectedLocation])

  const subcategories = useMemo(() => {
    const parent = categories.find((cat) => cat.id === categoryId)
    return parent?.children || []
  }, [categories, categoryId])

  const categoryMatches = useMemo(() => {
    const normalizedQuery = normalizeSearchText(query)
    if (!normalizedQuery) return []
    const matches: CategoryMatch[] = []
    categories.forEach((category) => {
      const categorySynonyms = category.synonyms || []
      const categoryMatch = matchesSearchText(category.name, normalizedQuery) || categorySynonyms.some((syn) => matchesSearchText(syn, normalizedQuery))
      if (categoryMatch) {
        matches.push({
          id: `category-${category.id}`,
          label: category.name,
          categoryId: category.id,
        })
      }
      category.children?.forEach((child) => {
        const childSynonyms = child.synonyms || []
        const childMatch = matchesSearchText(child.name, normalizedQuery) || childSynonyms.some((syn) => matchesSearchText(syn, normalizedQuery))
        if (childMatch) {
          matches.push({
            id: `subcategory-${child.id}`,
            label: child.name,
            categoryId: category.id,
            subcategoryId: child.id,
            parentLabel: category.name,
          })
        }
      })
    })
    return matches.slice(0, 10)
  }, [categories, query])

  const symptomMatches = useMemo(() => {
    const normalizedQuery = normalizeSearchText(query)
    if (!normalizedQuery || normalizedQuery.length < 3) return []
    const matches: CategoryMatch[] = []
    const categoryLookup = new Map<string, CategoryNode>()
    categories.forEach((category) => {
      categoryLookup.set(category.name.toLowerCase(), category)
    })

    SYMPTOM_CATEGORY_HINTS.forEach((hint) => {
      const matched = hint.terms.some((term) => matchesSearchText(term, normalizedQuery))
      if (!matched) return
      const category = categoryLookup.get(hint.category.toLowerCase())
      if (!category) return
      let subcategoryId: string | undefined
      let parentLabel: string | undefined
      if (hint.subcategory) {
        const child = category.children?.find((item) => item.name.toLowerCase() === hint.subcategory?.toLowerCase())
        if (child) {
          subcategoryId = child.id
          parentLabel = category.name
        }
      }
      matches.push({
        id: `symptom-${category.id}-${subcategoryId || 'all'}`,
        label: hint.subcategory || category.name,
        categoryId: category.id,
        subcategoryId,
        parentLabel,
      })
    })

    return matches
  }, [categories, query])

  const findSymptomMatchForQuery = (searchQuery: string): CategoryMatch | null => {
    const normalizedQuery = normalizeSearchText(searchQuery)
    if (!normalizedQuery || normalizedQuery.length < 3) return null

    const categoryLookup = new Map<string, CategoryNode>()
    categories.forEach((category) => {
      categoryLookup.set(category.name.toLowerCase(), category)
    })

    for (const hint of SYMPTOM_CATEGORY_HINTS) {
      const matched = hint.terms.some((term) => matchesSearchText(term, normalizedQuery))
      if (!matched) continue

      const category = categoryLookup.get(hint.category.toLowerCase())
      if (!category) continue

      let matchedSubcategoryId: string | undefined
      let matchedParentLabel: string | undefined
      if (hint.subcategory) {
        const child = category.children?.find((item) => item.name.toLowerCase() === hint.subcategory?.toLowerCase())
        if (child) {
          matchedSubcategoryId = child.id
          matchedParentLabel = category.name
        }
      }

      return {
        id: `auto-symptom-${category.id}-${matchedSubcategoryId || 'all'}`,
        label: hint.subcategory || category.name,
        categoryId: category.id,
        subcategoryId: matchedSubcategoryId,
        parentLabel: matchedParentLabel,
      }
    }

    return null
  }

  const suggestedMatches = useMemo(() => {
    const merged: CategoryMatch[] = []
    const seen = new Set<string>()
    const addMatch = (match: CategoryMatch) => {
      const key = `${match.categoryId}:${match.subcategoryId || ''}`
      if (seen.has(key)) return
      seen.add(key)
      merged.push(match)
    }
    categoryMatches.forEach(addMatch)
    symptomMatches.forEach(addMatch)
    return merged.slice(0, 10)
  }, [categoryMatches, symptomMatches])

  const loadCategories = async () => {
    try {
      const res = await fetch('/api/practitioners/categories', { cache: 'no-store' })
      const data = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(data?.error || 'Failed to load categories')
      setCategories(data?.categories || [])
    } catch (err: any) {
      console.error(err)
    }
  }

  React.useEffect(() => {
    loadCategories()
  }, [])

  React.useEffect(() => {
    try {
      const saved = localStorage.getItem('helfi:practitionerLocation')
      if (saved) {
        const parsed = JSON.parse(saved)
        if (parsed?.lat && parsed?.lng) {
          setSelectedLocation(parsed)
          setLocationQuery(parsed.displayName || '')
        }
      }
    } catch {
      // Ignore storage errors
    }
  }, [])

  React.useEffect(() => {
    if (typeof window === 'undefined') return
    const params = new URLSearchParams(window.location.search)
    const categoryParam = params.get('categoryId') || ''
    const subcategoryParam = params.get('subcategoryId') || ''
    const queryParam = params.get('q') || ''

    if (categoryParam || subcategoryParam || queryParam) {
      setCategoryId(categoryParam)
      setSubcategoryId(subcategoryParam)
      setQuery(queryParam)
      setResults([])
      setError(null)
      return
    }

    let isReload = false
    try {
      const navigationEntry = performance.getEntriesByType('navigation')[0] as PerformanceNavigationTiming | undefined
      isReload = navigationEntry?.type === 'reload' || (performance as any)?.navigation?.type === 1
    } catch {
      isReload = false
    }

    if (isReload) {
      try {
        sessionStorage.removeItem('helfi:practitionerSearchState')
      } catch {
        // Ignore storage errors
      }
      return
    }

    try {
      const saved = sessionStorage.getItem('helfi:practitionerSearchState')
      if (!saved) return
      const parsed = JSON.parse(saved)
      if (!parsed || !parsed.results) return
      setCategoryId(parsed.categoryId || '')
      setSubcategoryId(parsed.subcategoryId || '')
      setQuery(parsed.query || '')
      setLocationQuery(parsed.locationQuery || '')
      setSelectedLocation(parsed.selectedLocation || null)
      setRadiusKm(typeof parsed.radiusKm === 'number' ? parsed.radiusKm : 10)
      setTelehealthOnly(Boolean(parsed.telehealthOnly))
      setResults(Array.isArray(parsed.results) ? parsed.results : [])
    } catch {
      // Ignore bad state
    }
  }, [])

  React.useEffect(() => {
    if (!pendingScroll || loading) return
    if (resultsRef.current) {
      resultsRef.current.scrollIntoView({ behavior: 'smooth' })
    }
    setPendingScroll(false)
  }, [pendingScroll, loading, results])

  const handleLocationSearch = async () => {
    if (!locationQuery.trim()) return
    setError(null)
    try {
      const res = await fetch(`/api/practitioners/geocode?q=${encodeURIComponent(locationQuery.trim())}`)
      const data = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(data?.error || 'Location lookup failed')
      const mapped = (data?.results || []).map((item: any) => {
        const address = item.address || {}
        return {
          lat: Number(item.lat),
          lng: Number(item.lon),
          displayName: item.display_name,
          city: address.city || address.town || address.village || address.suburb,
          state: address.state,
          country: address.country,
          postcode: address.postcode,
        }
      })
      setLocationResults(mapped)
    } catch (err: any) {
      setError(err?.message || 'Location lookup failed')
    }
  }

  const handleUseMyLocation = () => {
    if (!navigator.geolocation) {
      alert('Location is not available in this browser.')
      return
    }
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const lat = pos.coords.latitude
        const lng = pos.coords.longitude
        try {
          const res = await fetch(`/api/practitioners/reverse-geocode?lat=${lat}&lng=${lng}`)
          const data = await res.json().catch(() => ({}))
          const address = data?.result?.address || {}
          const location: LocationResult = {
            lat,
            lng,
            displayName: data?.result?.display_name || 'Current location',
            city: address.city || address.town || address.village || address.suburb,
            state: address.state,
            country: address.country,
            postcode: address.postcode,
          }
          setSelectedLocation(location)
          setLocationQuery(location.displayName)
          setLocationResults([])
          persistLocation(location)
        } catch {
          const location: LocationResult = {
            lat,
            lng,
            displayName: 'Current location',
          }
          setSelectedLocation(location)
          setLocationQuery(location.displayName)
          setLocationResults([])
          persistLocation(location)
        }
      },
      () => alert('We could not access your location. Please enter it manually.')
    )
  }

  const persistSearchState = (payload: {
    categoryId: string
    subcategoryId: string
    query: string
    locationQuery: string
    selectedLocation: LocationResult | null
    radiusKm: number
    telehealthOnly: boolean
    results: SearchResult[]
  }) => {
    try {
      sessionStorage.setItem('helfi:practitionerSearchState', JSON.stringify(payload))
    } catch {
      // Ignore storage errors
    }
  }

  const handleSearch = async (overrides?: { categoryId?: string; subcategoryId?: string; query?: string }) => {
    setLoading(true)
    setError(null)
    setPendingScroll(true)
    try {
      let effectiveCategoryId = overrides?.categoryId ?? categoryId
      let effectiveSubcategoryId = overrides?.subcategoryId ?? subcategoryId
      let effectiveQuery = overrides?.query ?? query

      if (!effectiveCategoryId && !effectiveSubcategoryId && effectiveQuery.trim()) {
        const autoSymptomMatch = findSymptomMatchForQuery(effectiveQuery)
        if (autoSymptomMatch) {
          effectiveCategoryId = autoSymptomMatch.categoryId
          effectiveSubcategoryId = autoSymptomMatch.subcategoryId || ''
          // Keep the search broad once we identify the right specialty.
          effectiveQuery = ''
          setCategoryId(effectiveCategoryId)
          setSubcategoryId(effectiveSubcategoryId)
        }
      }

      const params = new URLSearchParams()
      if (effectiveCategoryId) params.set('categoryId', effectiveCategoryId)
      if (effectiveSubcategoryId) params.set('subcategoryId', effectiveSubcategoryId)
      if (effectiveQuery.trim()) params.set('q', effectiveQuery.trim())
      if (selectedLocation) {
        params.set('lat', String(selectedLocation.lat))
        params.set('lng', String(selectedLocation.lng))
      }
      params.set('radiusKm', String(radiusKm))
      params.set('telehealth', telehealthOnly ? 'true' : 'false')
      if (geoKey) params.set('geoKey', geoKey)

      const res = await fetch(`/api/practitioners/search?${params.toString()}`)
      const data = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(data?.error || 'Search failed')
      const nextResults = data?.results || []
      setResults(nextResults)
      persistSearchState({
        categoryId: effectiveCategoryId,
        subcategoryId: effectiveSubcategoryId,
        query: effectiveQuery,
        locationQuery,
        selectedLocation,
        radiusKm,
        telehealthOnly,
        results: nextResults,
      })
    } catch (err: any) {
      setError(err?.message || 'Search failed')
    } finally {
      setLoading(false)
    }
  }

  const handleQuickAccess = (item: QuickAccess) => {
    const category = categories.find((cat) => cat.name === item.category)
    if (!category) {
      setQuery(item.label)
      handleSearch({ query: item.label })
      return
    }
    setCategoryId(category.id)
    if (item.subcategory) {
      const subcategory = category.children?.find((child) => child.name === item.subcategory)
      setSubcategoryId(subcategory?.id || '')
      handleSearch({ categoryId: category.id, subcategoryId: subcategory?.id || '' })
    } else {
      setSubcategoryId('')
      handleSearch({ categoryId: category.id, subcategoryId: '' })
    }
  }

  const applyCategoryMatch = (match: CategoryMatch) => {
    setCategoryId(match.categoryId)
    setSubcategoryId(match.subcategoryId || '')
    setQuery('')
    setTimeout(() => {
      subcategoryRef.current?.focus()
    }, 0)
    handleSearch({
      categoryId: match.categoryId,
      subcategoryId: match.subcategoryId || '',
      query: '',
    })
  }

  const markers = useMemo(() => {
    return results
      .filter((item) => item.lat != null && item.lng != null)
      .map((item) => ({
        id: item.id,
        name: item.displayName,
        lat: item.lat as number,
        lng: item.lng as number,
        address: [item.addressLine1, item.suburbCity, item.stateRegion, item.country].filter(Boolean).join(', '),
        isBoosted: item.isBoosted,
      }))
  }, [results])

  const trackClick = (item: SearchResult, action: string) => {
    if (!item?.trackingToken) return
    const payload = JSON.stringify({
      listingId: item.id,
      action,
      token: item.trackingToken,
    })
    if (navigator.sendBeacon) {
      navigator.sendBeacon('/api/practitioners/contact-click', new Blob([payload], { type: 'application/json' }))
      return
    }
    fetch('/api/practitioners/contact-click', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: payload,
      keepalive: true,
    }).catch(() => undefined)
  }

  const center = selectedLocation
    ? { lat: selectedLocation.lat, lng: selectedLocation.lng }
    : markers.length
      ? { lat: markers[0].lat, lng: markers[0].lng }
      : { lat: -37.8136, lng: 144.9631 }

  const quickRows = [QUICK_ACCESS.slice(0, 6), QUICK_ACCESS.slice(6, 12), QUICK_ACCESS.slice(12, 18)]
  const directorySchema = {
    '@context': 'https://schema.org',
    '@graph': [
      {
        '@type': 'WebPage',
        '@id': absoluteUrl('/practitioners#webpage'),
        url: absoluteUrl('/practitioners'),
        name: 'Find Health Practitioners Near You | Helfi Directory',
        description:
          'Search a free practitioner directory by specialty, location, and telehealth.',
      },
      {
        '@type': 'MedicalBusiness',
        '@id': absoluteUrl('/practitioners#directory'),
        name: 'Helfi Practitioner Directory',
        url: absoluteUrl('/practitioners'),
        description:
          'Directory for finding trusted health practitioners by category, location, and telehealth.',
      },
      {
        '@type': 'ItemList',
        '@id': absoluteUrl('/practitioners#quick-categories'),
        name: 'Practitioner quick access categories',
        itemListElement: QUICK_ACCESS.slice(0, 10).map((item, index) => ({
          '@type': 'ListItem',
          position: index + 1,
          name: item.label,
          url: absoluteUrl(`/practitioners?query=${encodeURIComponent(item.label)}`),
        })),
      },
    ],
  }

  const PULL_REFRESH_ACTIVATE = 80
  const PULL_REFRESH_THRESHOLD = 320
  const PULL_REFRESH_MAX = 420
  const PULL_REFRESH_START_ZONE = 140
  const getScrollTop = () => {
    if (typeof window === 'undefined') return 0
    const scroller = document.scrollingElement
    if (scroller && Number.isFinite(scroller.scrollTop)) return scroller.scrollTop
    return window.scrollY || 0
  }
  const getScrollParent = (target: EventTarget | null) => {
    if (typeof window === 'undefined') return null
    if (!(target instanceof Element)) return null
    let el: Element | null = target
    while (el && el !== document.body) {
      const style = window.getComputedStyle(el)
      const overflowY = style?.overflowY
      if ((overflowY === 'auto' || overflowY === 'scroll') && el.scrollHeight > el.clientHeight + 1) {
        return el as HTMLElement
      }
      el = el.parentElement
    }
    return null
  }
  const isEditableElement = (target: EventTarget | null) => {
    if (typeof document === 'undefined') return false
    if (!(target instanceof Element)) return false
    return Boolean(target.closest('input, textarea, select, [contenteditable="true"]'))
  }
  const refreshPage = async () => {
    if (pullRefreshingRef.current) return
    pullRefreshingRef.current = true
    setPullRefreshing(true)
    setTimeout(() => {
      if (typeof window !== 'undefined') window.location.reload()
    }, 200)
  }
  const handlePullStart = (e: React.TouchEvent) => {
    if (typeof window === 'undefined') return
    if (getScrollTop() > 0) return
    if (pullRefreshingRef.current) return
    if (isEditableElement(e.target) || isEditableElement(document.activeElement)) return
    const scrollParent = getScrollParent(e.target)
    if (scrollParent && scrollParent.scrollTop > 0) return
    pullOffsetRef.current = 0
    setPullOffset(0)
    const startY = e.touches[0]?.clientY ?? null
    if (startY === null || startY > PULL_REFRESH_START_ZONE) return
    pullScrollParentRef.current = scrollParent
    pullStartYRef.current = startY
  }
  const handlePullMove = (e: React.TouchEvent) => {
    if (pullStartYRef.current === null) return
    if (isEditableElement(e.target) || isEditableElement(document.activeElement)) {
      pullStartYRef.current = null
      pullOffsetRef.current = 0
      pullScrollParentRef.current = null
      setPullOffset(0)
      return
    }
    if (pullScrollParentRef.current && pullScrollParentRef.current.scrollTop > 0) {
      pullStartYRef.current = null
      pullOffsetRef.current = 0
      pullScrollParentRef.current = null
      setPullOffset(0)
      return
    }
    if (getScrollTop() > 0) {
      pullStartYRef.current = null
      pullOffsetRef.current = 0
      pullScrollParentRef.current = null
      setPullOffset(0)
      return
    }
    const currentY = e.touches[0]?.clientY ?? 0
    const delta = currentY - (pullStartYRef.current || 0)
    if (delta <= PULL_REFRESH_ACTIVATE) {
      pullOffsetRef.current = 0
      setPullOffset(0)
      return
    }
    const nextOffset = Math.min(PULL_REFRESH_MAX, delta - PULL_REFRESH_ACTIVATE)
    pullOffsetRef.current = nextOffset
    setPullOffset(nextOffset)
  }
  const handlePullEnd = async () => {
    if (pullStartYRef.current === null) return
    const shouldRefresh = pullOffsetRef.current >= PULL_REFRESH_THRESHOLD
    pullStartYRef.current = null
    pullOffsetRef.current = 0
    pullScrollParentRef.current = null
    setPullOffset(0)
    if (shouldRefresh) {
      await refreshPage()
    }
  }

  return (
    <div
      className="min-h-screen bg-white"
      onTouchStart={handlePullStart}
      onTouchMove={handlePullMove}
      onTouchEnd={handlePullEnd}
      onTouchCancel={handlePullEnd}
    >
