'use client'

import React, { useState, useEffect, useRef } from 'react'
import { useSession, signOut } from 'next-auth/react'
import Link from 'next/link'
import Image from 'next/image'
import { useUserData } from '@/components/providers/UserDataProvider'
import { UserIcon } from '@heroicons/react/24/outline'

export default function ProfileImage() {
  const { data: session } = useSession()
  const { updateProfileImage } = useUserData()
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle')
  const [selectedImage, setSelectedImage] = useState<File | null>(null)
  const [imagePreview, setImagePreview] = useState<string | null>(null)
  const [currentProfileImage, setCurrentProfileImage] = useState<string | null>(null)
  const [showCamera, setShowCamera] = useState(false)
  const [dropdownOpen, setDropdownOpen] = useState(false)
  const videoRef = useRef<HTMLVideoElement>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  // Profile data - prefer real photos; fall back to professional icon
  const hasProfileImage = !!(currentProfileImage || session?.user?.image)
  const userImage = (currentProfileImage || session?.user?.image || '') as string
  const userName = session?.user?.name || 'User';

  // Close dropdown on outside click
  useEffect(() => {
    function handleClick(e: MouseEvent) {
      if (!(e.target as HTMLElement).closest('#profile-dropdown')) {
        setDropdownOpen(false);
      }
    }
    if (dropdownOpen) {
      document.addEventListener('mousedown', handleClick);
    } else {
      document.removeEventListener('mousedown', handleClick);
    }
    return () => document.removeEventListener('mousedown', handleClick);
  }, [dropdownOpen]);

  // Load current profile image on mount
  useEffect(() => {
    const loadCurrentImage = async () => {
      try {
        console.log('Profile/Image page - Loading profile image from database...');
        const response = await fetch('/api/user-data', {
          cache: 'no-cache',
          headers: {
            'Cache-Control': 'no-cache'
          }
        });
        if (response.ok) {
          const result = await response.json();
          console.log('Profile/Image page - API response:', { hasData: !!result.data, hasProfileImage: !!(result.data?.profileImage) });
          if (result.data && result.data.profileImage) {
            console.log('Profile/Image page - Setting profile image from database (Cloudinary URL)');
            setCurrentProfileImage(result.data.profileImage);

            // Clean up old localStorage entries (migration cleanup)
            if (session?.user?.id) {
              localStorage.removeItem(`profileImage_${session.user.id}`);
            }
          } else {
            console.log('Profile/Image page - No profile image found in database response');
          }
        } else {
          console.error('Profile/Image page - API call failed:', response.status, response.statusText);
        }
      } catch (error) {
        console.error('Error loading profile image:', error);
      }
    };

    loadCurrentImage();
  }, [session?.user?.id]);

  // Auto-save when image changes
  useEffect(() => {
    if (!selectedImage) return;

    const saveImage = async () => {
      setSaveStatus('saving');

      try {
        // Upload to Cloudinary via new API
        const formData = new FormData();
        formData.append('image', selectedImage);

        console.log('Uploading image to Cloudinary...');
        console.log('Session status before upload:', { hasSession: !!session, userEmail: session?.user?.email });
        const response = await fetch('/api/upload-profile-image', {
          method: 'POST',
          body: formData,
          credentials: 'include' // Ensure cookies are sent
        });

        const result = await response.json();

        if (result.success) {
          console.log('Cloudinary upload successful:', result);

          // Set the Cloudinary URL as the profile image
          setCurrentProfileImage(result.imageUrl);
          // Broadcast to shared data provider so other pages update instantly
          try {
            updateProfileImage(result.imageUrl)
          } catch (e) {
            console.warn('Could not update shared profile image provider:', e)
          }

          // Clear localStorage (no longer needed with Cloudinary)
          if (session?.user?.id) {
            localStorage.removeItem(`profileImage_${session.user.id}`);
            // Also set the cached key used by Dashboard for instant display
            try {
              localStorage.setItem(`cachedProfileImage_${session.user.id}`, result.imageUrl)
            } catch {}
          }

          setSaveStatus('saved');
          setTimeout(() => setSaveStatus('idle'), 2000);

          console.log('Image optimization stats:', result.optimizations);
        } else {
          throw new Error(result.error || 'Upload failed');
        }
      } catch (error) {
        console.error('Error uploading image:', error);
        setSaveStatus('idle');
        alert('Failed to upload image. Please try again.');
      }
    };

    saveImage();
  }, [selectedImage, session?.user?.id]);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      // Validate file type
      if (!file.type.startsWith('image/')) {
        alert('Please select an image file');
        return;
      }

      // Validate file size (5MB limit)
      if (file.size > 5 * 1024 * 1024) {
        alert('File size must be less than 5MB');
        return;
      }

      setSelectedImage(file);

      // Create preview
      const reader = new FileReader();
      reader.onload = (e) => {
        setImagePreview(e.target?.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const startCamera = async () => {
    try {
      // Check if camera is supported
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        alert('Camera not supported on this device or browser.');
        return;
      }

      setShowCamera(true);
      await new Promise<void>((resolve) => requestAnimationFrame(() => resolve()));

      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { 
          facingMode: 'user',
          width: { ideal: 640 },
          height: { ideal: 480 }
        }
      });

      if (!videoRef.current) {
        stream.getTracks().forEach((track) => track.stop());
        throw new Error('Camera preview could not be opened.');
      }

      videoRef.current.srcObject = stream;
      videoRef.current.onloadedmetadata = () => {
        videoRef.current?.play();
      };
    } catch (error: any) {
        setShowCamera(false);
        console.error('Error accessing camera:', error);
        let errorMessage = 'Unable to access camera. ';

        if (error?.name === 'NotAllowedError') {
          errorMessage += 'Please allow camera permissions in your browser settings.';
        } else if (error?.name === 'NotFoundError') {
          errorMessage += 'No camera found on this device.';
        } else if (error?.name === 'NotSupportedError') {
          errorMessage += 'Camera not supported on this browser.';
        } else {
          errorMessage += 'Please check your camera and permissions.';
        }

        alert(errorMessage);
      }
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');

      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;

      if (context) {
        context.drawImage(video, 0, 0);

        canvas.toBlob((blob) => {
          if (blob) {
            const file = new File([blob], 'profile-photo.jpg', { type: 'image/jpeg' });
            setSelectedImage(file);

            // Create preview
            const reader = new FileReader();
            reader.onload = (e) => {
              setImagePreview(e.target?.result as string);
            };
            reader.readAsDataURL(file);

            // Stop camera
            stopCamera();
          }
        }, 'image/jpeg', 0.8);
      }
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setShowCamera(false);
  };

  const removeCurrentImage = async () => {
    if (confirm('Are you sure you want to remove your profile picture?')) {
      setSaveStatus('saving');

      try {
        // Remove profile image (set to null in database)
        const response = await fetch('/api/user-data', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ profileImage: null })
        });

        if (response.ok) {
          // Clear localStorage (no longer needed)
          if (session?.user?.id) {
            localStorage.removeItem(`profileImage_${session.user.id}`);
          }

          setCurrentProfileImage(null);
          setSelectedImage(null);
          setImagePreview(null);
          // Broadcast removal to shared provider and clear dashboard cache
          try {
            updateProfileImage('')
          } catch {}
          if (session?.user?.id) {
            try { localStorage.removeItem(`cachedProfileImage_${session.user.id}`) } catch {}
          }
          setSaveStatus('saved');
          setTimeout(() => setSaveStatus('idle'), 2000);
        } else {
          throw new Error('Failed to remove image');
        }
      } catch (error) {
        console.error('Error removing image:', error);
        setSaveStatus('idle');
