'use client'
import { Cog6ToothIcon, UserIcon } from '@heroicons/react/24/outline'

import React, { useCallback, useEffect, useRef, useState } from 'react'
import { useSession, signOut } from 'next-auth/react'
import Link from 'next/link'
import Image from 'next/image'
import { useUserData } from '@/components/providers/UserDataProvider'
import MobileMoreMenu from '@/components/MobileMoreMenu'
import PageHeader from '@/components/PageHeader'
import { useSaveOnLeave } from '@/lib/use-save-on-leave'

export default function Profile() {
  const { data: session } = useSession()
  const { userData, profileImage, updateUserData, updateProfileImage, refreshData } = useUserData()
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle')
  const [dropdownOpen, setDropdownOpen] = useState(false)
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false)
  const [profileData, setProfileData] = useState({
    firstName: '',
    lastName: '',
    email: session?.user?.email || '',
    bio: '',
    dateOfBirth: '',
    gender: ''
  })
  const profileSnapshotRef = useRef<string>('')
  const profileRef = useRef(profileData)
  const dirtyRef = useRef(false)
  const hasInitializedRef = useRef(false)

  // Profile data - prefer real photos; fall back to professional icon
  const hasProfileImage = !!(profileImage || session?.user?.image)
  const userImage = (profileImage || session?.user?.image || '') as string
  const userName = session?.user?.name || 'User';

  // Close dropdown on outside click
  useEffect(() => {
    function handleClick(e: MouseEvent) {
      const target = e.target as HTMLElement;
      // Check if click is outside both the button and the dropdown content
      if (!target.closest('.dropdown-container')) {
        setDropdownOpen(false);
      }
    }
    if (dropdownOpen) {
      document.addEventListener('mousedown', handleClick);
      return () => document.removeEventListener('mousedown', handleClick);
    }
  }, [dropdownOpen]);

  // Load cached data from provider (no API call needed!)
  useEffect(() => {
    if (userData && session) {
      console.log('Profile page - Loading data from UserDataProvider cache (no API call)...');
      // Use cached data from provider instead of making API call
      const mergedData = {
        firstName: userData.profileInfo?.firstName || '',
        lastName: userData.profileInfo?.lastName || '',
        bio: userData.profileInfo?.bio || '',
        dateOfBirth: userData.profileInfo?.dateOfBirth || '',
        gender: userData.profileInfo?.gender || userData.gender || '',
        email: session?.user?.email || ''
      };

      // 🔧 FIX: Only update state if current state is empty (initial load)
      // This prevents overwriting user input during active editing
      setProfileData(prev => {
        // If user hasn't entered any data yet, load from cache
        const next = (!prev.firstName && !prev.lastName && !prev.bio && !prev.dateOfBirth && !prev.gender)
          ? mergedData
          : {
              ...prev,
              email: session?.user?.email || prev.email
            }

        if (!hasInitializedRef.current) {
          hasInitializedRef.current = true
          profileSnapshotRef.current = JSON.stringify(next)
          dirtyRef.current = false
          setHasUnsavedChanges(false)
        }

        return next
      });

      console.log('Profile page - Data loaded from cache instantly!');
    } else if (!userData && session) {
      // Fallback to localStorage while provider loads
      const savedProfile = localStorage.getItem('profileData');
      if (savedProfile) {
        try {
          const parsed = JSON.parse(savedProfile);
          setProfileData(prev => {
            const next = {
              ...prev,
              ...parsed,
              email: session?.user?.email || prev.email
            }
            if (!hasInitializedRef.current) {
              hasInitializedRef.current = true
              profileSnapshotRef.current = JSON.stringify(next)
              dirtyRef.current = false
              setHasUnsavedChanges(false)
            }
            return next
          });
          console.log('Profile page - Loaded from localStorage fallback');
        } catch (e) {
          console.error('Error parsing saved profile:', e);
        }
      }
    }
  }, [userData, session]);

  useEffect(() => {
    profileRef.current = profileData
    if (!hasInitializedRef.current) return
    const snapshot = JSON.stringify(profileData)
    const dirty = snapshot !== profileSnapshotRef.current
    dirtyRef.current = dirty
    setHasUnsavedChanges(dirty)
  }, [profileData])

  const saveProfile = useCallback(async (options?: { silent?: boolean; keepalive?: boolean; payload?: typeof profileData }) => {
    const payload = options?.payload ?? profileRef.current
    if (!options?.silent) setSaveStatus('saving')
    try {
      const response = await fetch('/api/user-data', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ profileInfo: payload }),
        keepalive: !!options?.keepalive,
      })

      if (!response.ok) {
        throw new Error(`Failed to save: ${response.status} ${response.statusText}`)
      }

      updateUserData({ profileInfo: payload })
      localStorage.setItem('profileData', JSON.stringify(payload))
      profileSnapshotRef.current = JSON.stringify(payload)
      dirtyRef.current = false
      setHasUnsavedChanges(false)
      if (!options?.silent) {
        setSaveStatus('saved')
        setTimeout(() => setSaveStatus('idle'), 2000)
      }
      console.log('Profile saved successfully.')
    } catch (error) {
      console.error('Error saving profile to database:', error)
      localStorage.setItem('profileData', JSON.stringify(payload))
      if (!options?.silent) {
        setSaveStatus('error')
      }
    }
  }, [updateUserData])

  useEffect(() => {
    if (!hasInitializedRef.current || !hasUnsavedChanges) return
    const timeoutId = window.setTimeout(() => {
      void saveProfile({ payload: profileRef.current })
    }, 800)
    return () => window.clearTimeout(timeoutId)
  }, [hasUnsavedChanges, profileData, saveProfile])

  useSaveOnLeave(() => {
    if (!dirtyRef.current) return
    void saveProfile({ silent: true, keepalive: true, payload: profileRef.current })
  })

  const updateProfileData = (field: string, value: string) => {
    setProfileData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  return (
    <div className="min-h-screen bg-gray-50">
      <PageHeader title="Profile" />

      {/* Main Content */}
      <div className="max-w-3xl mx-auto px-4 py-8 pb-24 md:pb-8">
        <div className="bg-white rounded-lg shadow-sm p-6">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-2xl font-bold text-gray-900">Profile Information</h2>

            {/* Auto-save Notice */}
            <div className={`text-sm ${saveStatus === 'error' ? 'text-red-600' : 'text-gray-500'}`} aria-live="polite">
              {saveStatus === 'saving' && 'Saving changes…'}
              {saveStatus === 'saved' && 'All changes saved'}
              {saveStatus === 'error' && 'Could not save. Please try again.'}
              {saveStatus === 'idle' && 'Changes save automatically'}
            </div>
          </div>

          {/* Auto-save Notice */}
          <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 mb-6">
            <div className="flex items-center">
              <svg className="w-5 h-5 text-blue-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
              <p className="text-blue-700 text-sm">
                <span className="font-medium">Auto-save enabled:</span> Your changes save automatically as you type.
              </p>
            </div>
          </div>

          {/* Profile Photo */}
          <div className="mb-8 text-center">
            {hasProfileImage ? (
              <Image
                src={userImage}
                alt={userName}
                width={96}
                height={96}
                className="w-24 h-24 rounded-full object-cover mx-auto mb-4"
                priority
              />
            ) : (
              <div className="w-24 h-24 rounded-full bg-helfi-green flex items-center justify-center mx-auto mb-4">
                <UserIcon className="w-12 h-12 text-white" aria-hidden="true" />
              </div>
            )}
            <Link href="/profile/image" className="text-helfi-green hover:underline">
              Change Profile Photo
            </Link>
          </div>

          {/* Profile Form */}
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">First Name</label>
                <input
                  type="text"
                  value={profileData.firstName}
                  onChange={(e) => updateProfileData('firstName', e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-helfi-green focus:border-helfi-green"
                  placeholder="Enter your first name"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Last Name</label>
                <input
                  type="text"
                  value={profileData.lastName}
                  onChange={(e) => updateProfileData('lastName', e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-helfi-green focus:border-helfi-green"
                  placeholder="Enter your last name"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Bio</label>
              <textarea
                rows={4}
                value={profileData.bio}
                onChange={(e) => updateProfileData('bio', e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-helfi-green focus:border-helfi-green"
                placeholder="Tell us about yourself..."
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Date of Birth</label>
                <input
                  type="date"
                  value={profileData.dateOfBirth}
                  onChange={(e) => updateProfileData('dateOfBirth', e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-helfi-green focus:border-helfi-green"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Gender</label>
                <select 
                  value={profileData.gender}
                  onChange={(e) => updateProfileData('gender', e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-helfi-green focus:border-helfi-green"
                >
                  <option value="">Select gender</option>
                  <option value="male">Male</option>
                  <option value="female">Female</option>
                  <option value="other">Other</option>
                  <option value="prefer-not-to-say">Prefer not to say</option>
                </select>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Mobile Bottom Navigation - Inspired by Google, Facebook, Amazon mobile apps */}
      <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 px-4 py-2 z-40">
        <div className="flex items-center justify-around">

          {/* Dashboard */}
          <Link href="/dashboard" className="flex flex-col items-center py-2 px-1 min-w-0 flex-1">
            <div className="text-gray-400">
              <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24">
                <path d="M3 13h8V3H3v10zm0 8h8v-6H3v6zm10 0h8V11h-8v10zm0-18v6h8V3h-8z"/>
              </svg>
            </div>
