                  <button
                    type="button"
                    onClick={closeThreadActions}
                    className="flex-1 rounded-lg border border-gray-200 px-3 py-2 text-sm text-gray-600 hover:bg-gray-50"
                  >
                    Cancel
                  </button>
                  <button
                    type="button"
                    onClick={() => {
                      if (!actionThreadId) return
                      handleRenameThread(actionThreadId, renameValue)
                      closeThreadActions()
                    }}
                    className="flex-1 rounded-lg bg-black px-3 py-2 text-sm text-white hover:bg-gray-800"
                  >
                    Save
                  </button>
                </div>
              </div>
            )}

            {deleteConfirmOpen && (
              <div className="px-4 py-4">
                <div className="text-sm font-semibold text-gray-900 mb-2">Delete this chat?</div>
                <div className="text-xs text-gray-500 mb-4">This can’t be undone.</div>
                <div className="flex gap-2">
                  <button
                    type="button"
                    onClick={closeThreadActions}
                    className="flex-1 rounded-lg border border-gray-200 px-3 py-2 text-sm text-gray-600 hover:bg-gray-50"
                  >
                    Cancel
                  </button>
                  <button
                    type="button"
                    onClick={async () => {
                      if (!actionThreadId) return
                      setDeletePending(true)
                      await handleDeleteThread(actionThreadId)
                      setDeletePending(false)
                      closeThreadActions()
                    }}
                    disabled={deletePending}
                    className="flex-1 rounded-lg bg-red-600 px-3 py-2 text-sm text-white hover:bg-red-700 active:bg-red-700 active:translate-y-[1px] active:scale-[0.99] transition disabled:opacity-60 disabled:cursor-not-allowed"
                  >
                    {deletePending ? 'Deleting…' : 'Delete'}
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </section>
  )

  // When expanded, render the chat as a true fullscreen overlay
  // using a portal so it is independent of the page layout.
  if (expanded && isClient && typeof document !== 'undefined') {
    return createPortal(chatUI, document.body)
  }

  return chatUI
}

'use client'

import { useCallback, useEffect, useState } from 'react'
import Link from 'next/link'
import { usePathname } from 'next/navigation'
import PageHeader from '@/components/PageHeader'

type SymptomHistoryItem = {
  id: string
  symptoms: any
  duration?: string | null
  notes?: string | null
  summary?: string | null
  analysisText?: string | null
  analysisData?: {
    possibleCauses?: Array<{ name: string; whyLikely?: string; confidence?: string }>
    redFlags?: string[]
    nextSteps?: string[]
  } | null
  createdAt: string
}

export default function SymptomHistoryPage() {
  const pathname = usePathname()
  const [historyItems, setHistoryItems] = useState<SymptomHistoryItem[]>([])
  const [historyLoading, setHistoryLoading] = useState(false)
  const [historyError, setHistoryError] = useState<string | null>(null)
  const [historyDeletingId, setHistoryDeletingId] = useState<string | null>(null)
  const [historyClearing, setHistoryClearing] = useState(false)
  const [expandedHistoryId, setExpandedHistoryId] = useState<string | null>(null)

  const loadHistory = useCallback(async () => {
    try {
      setHistoryLoading(true)
      setHistoryError(null)
      const res = await fetch('/api/symptoms/history', { cache: 'no-store' as any })
      if (!res.ok) {
        throw new Error('Failed to load history')
      }
      const data = await res.json()
      const nextHistory = Array.isArray(data?.history) ? data.history : []
      setHistoryItems(nextHistory)
    } catch (err) {
      setHistoryError((err as Error).message || 'Failed to load history')
    } finally {
      setHistoryLoading(false)
    }
  }, [])

  useEffect(() => {
    loadHistory()
  }, [loadHistory])

  const handleDeleteHistoryItem = async (id: string) => {
    if (!window.confirm('Delete these symptom notes? This cannot be undone.')) return
    try {
      setHistoryDeletingId(id)
      setHistoryError(null)
      const res = await fetch(`/api/symptoms/history/${id}`, { method: 'DELETE' })
      if (!res.ok) {
        throw new Error('Failed to delete symptom notes')
      }
      setHistoryItems((prev) => prev.filter((item) => item.id !== id))
      setExpandedHistoryId((prev) => (prev === id ? null : prev))
    } catch (err) {
      setHistoryError((err as Error).message || 'Failed to delete symptom notes')
    } finally {
      setHistoryDeletingId(null)
    }
  }

  const handleClearHistory = async () => {
    if (!window.confirm('Clear all symptom notes? This cannot be undone.')) return
    try {
      setHistoryClearing(true)
      setHistoryError(null)
      const res = await fetch('/api/symptoms/history', { method: 'DELETE' })
      if (!res.ok) {
        throw new Error('Failed to clear history')
      }
      setHistoryItems([])
      setExpandedHistoryId(null)
    } catch (err) {
      setHistoryError((err as Error).message || 'Failed to clear history')
    } finally {
      setHistoryClearing(false)
    }
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      <PageHeader title="Symptom Notes" />

      <div className="max-w-7xl mx-auto w-full px-4 pt-4">
        <div className="bg-white rounded-t-xl border-b border-gray-200">
          <div className="flex">
            <Link
              href="/symptoms"
              style={{ width: '100%' }}
              className={`flex-1 px-4 py-3 text-center font-medium transition-colors ${
                pathname !== '/symptoms/history'
                  ? 'text-helfi-green border-b-2 border-helfi-green'
                  : 'text-gray-600 hover:text-gray-900'
              }`}
            >
              Symptom Notes
            </Link>
            <Link
              href="/symptoms/history"
              style={{ width: '100%' }}
              className={`flex-1 px-4 py-3 text-center font-medium transition-colors ${
                pathname === '/symptoms/history'
                  ? 'text-helfi-green border-b-2 border-helfi-green'
                  : 'text-gray-600 hover:text-gray-900'
              }`}
            >
              History
            </Link>
          </div>
        </div>
      </div>

      <main className="flex-1">
        <div className="max-w-7xl mx-auto px-4 py-6">
          <div className="bg-white rounded-b-2xl shadow-sm border border-gray-200 p-6">
            <div className="flex items-center justify-between gap-2 mb-4">
              <div>
                <h1 className="text-2xl font-bold text-gray-900">Symptom History</h1>
                <p className="text-xs text-gray-500 mt-1">
                  Review your previous symptom notes. You can delete any entry at any time.
                </p>
              </div>
              <div className="flex items-center gap-3 text-xs">
                {historyItems.length > 0 && (
                  <button
                    onClick={handleClearHistory}
                    className="text-red-600 hover:text-red-700 disabled:opacity-60"
                    type="button"
                    disabled={historyClearing}
                  >
                    {historyClearing ? 'Clearing...' : 'Clear all'}
                  </button>
                )}
                <button
                  onClick={loadHistory}
                  className="text-gray-600 hover:text-gray-900 disabled:opacity-60"
                  type="button"
                  disabled={historyLoading}
                >
                  Refresh
                </button>
              </div>
            </div>

            {historyLoading && <div className="text-sm text-gray-500">Loading history...</div>}
            {historyError && <div className="text-sm text-red-700">{historyError}</div>}
            {!historyLoading && !historyError && historyItems.length === 0 && (
              <div className="text-sm text-gray-500">No saved symptom notes yet.</div>
            )}

            <div className="mt-4 space-y-4">
              {historyItems.map((item) => {
                const symptoms = Array.isArray(item.symptoms) ? item.symptoms : []
                const analysisData = item.analysisData || null
                const possibleCauses = Array.isArray(analysisData?.possibleCauses)
                  ? analysisData?.possibleCauses
                  : []
                const redFlags = Array.isArray(analysisData?.redFlags) ? analysisData?.redFlags : []
                const nextSteps = Array.isArray(analysisData?.nextSteps) ? analysisData?.nextSteps : []
                const isExpanded = expandedHistoryId === item.id
                const createdAtLabel = item.createdAt
                  ? new Date(item.createdAt).toLocaleString()
                  : 'Unknown date'

                return (
                  <div key={item.id} className="border border-gray-200 rounded-lg p-4 bg-white">
                    <div className="flex items-center justify-between gap-2">
                      <div className="text-xs text-gray-500">{createdAtLabel}</div>
                      <div className="flex items-center gap-3 text-xs">
                        <button
                          type="button"
                          onClick={() => setExpandedHistoryId(isExpanded ? null : item.id)}
                          className="text-helfi-green hover:text-helfi-green/80"
                        >
                          {isExpanded ? 'Hide details' : 'View details'}
                        </button>
                        <button
                          type="button"
                          onClick={() => handleDeleteHistoryItem(item.id)}
                          className="text-red-600 hover:text-red-700 disabled:opacity-60"
                          disabled={historyDeletingId === item.id || historyClearing}
                        >
                          {historyDeletingId === item.id ? 'Deleting...' : 'Delete'}
                        </button>
                      </div>
                    </div>

                    <div className="mt-3 space-y-2">
                      {symptoms.length > 0 && (
                        <div className="text-sm text-gray-900">
                          <span className="font-medium">Symptoms:</span> {symptoms.join(', ')}
                        </div>
                      )}
                      {item.duration && (
                        <div className="text-sm text-gray-700">
                          <span className="font-medium">Duration:</span> {item.duration}
                        </div>
                      )}
                      {item.summary && (
                        <p className="text-sm text-gray-800">{item.summary}</p>
                      )}
                    </div>

                    {isExpanded && (
                      <div className="pt-3 space-y-3 text-sm text-gray-700">
                        {item.notes && (
                          <div>
                            <div className="font-medium text-gray-900 mb-1">Notes</div>
                            <p className="whitespace-pre-line">{item.notes}</p>
                          </div>
                        )}
                        {possibleCauses.length > 0 && (
                          <div>
                            <div className="font-medium text-gray-900 mb-1">Topics to discuss with a doctor</div>
                            <ul className="space-y-1">
                              {possibleCauses.map((cause: any, idx: number) => (
                                <li key={`${cause.name}-${idx}`} className="flex items-center gap-2">
                                  <span className="text-gray-900">{cause.name}</span>
                                  {cause.confidence && (
                                    <span className="text-xs text-gray-500">(general)</span>
                                  )}
                                </li>
                              ))}
                            </ul>
                          </div>
                        )}
                        {redFlags.length > 0 && (
                          <div>
                            <div className="font-medium text-red-700 mb-1">When to seek urgent care</div>
                            <ul className="list-disc list-inside space-y-1 text-red-800">
                              {redFlags.map((flag: string, idx: number) => (
                                <li key={idx}>{flag}</li>
                              ))}
                            </ul>
                          </div>
                        )}
                        {nextSteps.length > 0 && (
                          <div>
                            <div className="font-medium text-gray-900 mb-1">Tracking notes and doctor questions</div>
                            <ul className="list-disc list-inside space-y-1">
                              {nextSteps.map((step: string, idx: number) => (
                                <li key={idx}>{step}</li>
                              ))}
                            </ul>
                          </div>
                        )}
                        {item.analysisText && (
                          <div>
                            <div className="font-medium text-gray-900 mb-1">Full notes</div>
                            <p className="whitespace-pre-line">{item.analysisText}</p>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                )
              })}
            </div>
          </div>
        </div>
      </main>
    </div>
  )
}

'use client'
import { Cog6ToothIcon } from '@heroicons/react/24/outline'

import { useEffect, useMemo, useRef, useState } from 'react'
import Link from 'next/link'
import { usePathname } from 'next/navigation'
import CreditPurchaseModal from '@/components/CreditPurchaseModal'
import AiConsentModal, { hasSavedAiConsent, saveAiConsent } from '@/components/AiConsentModal'
import MobileMoreMenu from '@/components/MobileMoreMenu'
import SymptomChat from './SymptomChat'
import UsageMeter from '@/components/UsageMeter'
import FeatureUsageDisplay from '@/components/FeatureUsageDisplay'
import PageHeader from '@/components/PageHeader'
import PractitionerRecommendations from '@/components/PractitionerRecommendations'

type AnalysisResult = {
  success: boolean
  analysisText?: string
  summary?: string | null
  possibleCauses?: Array<{ name: string; whyLikely: string; confidence: 'low' | 'medium' | 'high' }>
  redFlags?: string[]
  nextSteps?: string[]
  disclaimer?: string
  error?: string
}

export default function SymptomAnalysisPage() {
  const pathname = usePathname()
  const [symptomInput, setSymptomInput] = useState<string>('')
  const [selectedSymptoms, setSelectedSymptoms] = useState<string[]>([])
  const [duration, setDuration] = useState<string>('')
  const [notes, setNotes] = useState<string>('')

  const [isAnalyzing, setIsAnalyzing] = useState<boolean>(false)
  const [phase, setPhase] = useState<number>(0)
  const [progress, setProgress] = useState<number>(0)
  const [result, setResult] = useState<AnalysisResult | null>(null)
  const [error, setError] = useState<string>('')

  const [showCreditsModal, setShowCreditsModal] = useState<boolean>(false)
  const [creditInfo, setCreditInfo] = useState<any>({ dailyUsed: 0, dailyLimit: 0, additionalCredits: 0, plan: 'FREE', creditCost: 1 })
  const [tagsExpanded, setTagsExpanded] = useState<boolean>(false)
  const [usageMeterRefresh, setUsageMeterRefresh] = useState<number>(0) // Trigger for UsageMeter refresh
  const resultRef = useRef<HTMLDivElement | null>(null)
  const voicePrefillAppliedRef = useRef<string>('')
  const [hasPaidAccess, setHasPaidAccess] = useState<boolean>(false)
  const [creditRefreshTick, setCreditRefreshTick] = useState<number>(0)
  const [voicePrefillParams, setVoicePrefillParams] = useState({ symptoms: '', duration: '', notes: '' })
  const [showAiConsent, setShowAiConsent] = useState<boolean>(false)

  // Progress phases shown while analyzing
  const phases = useMemo(() => [
    'Gathering context',
    'Preparing general notes',
    'Checking urgent warning signs',
    'Drafting questions to discuss'
  ], [])

  useEffect(() => {
    if (!isAnalyzing) return
    setPhase(0)
    setProgress(0)
    let pct = 0
    // Cap progress at 85% during simulation, will jump to 100% when API completes
    const timer = setInterval(() => {
      pct = Math.min(85, pct + Math.random() * 7 + 3)
      setProgress(pct)
      // advance phase roughly every ~25%
      if (pct > 75) setPhase(3)
      else if (pct > 50) setPhase(2)
      else if (pct > 25) setPhase(1)
      else setPhase(0)
    }, 350)
    return () => clearInterval(timer)
  }, [isAnalyzing])

  useEffect(() => {
    const handler = () => setCreditRefreshTick((v) => v + 1)
    try {
      window.addEventListener('credits:refresh', handler)
      return () => window.removeEventListener('credits:refresh', handler)
    } catch {
      return () => {}
    }
  }, [])

  useEffect(() => {
    if (typeof window === 'undefined') return
    const params = new URLSearchParams(window.location.search)
    setVoicePrefillParams({
      symptoms: params.get('voiceSymptoms') || '',
      duration: params.get('voiceDuration') || '',
      notes: params.get('voiceNotes') || '',
    })
  }, [])

  useEffect(() => {
    const key = `${voicePrefillParams.symptoms}|${voicePrefillParams.duration}|${voicePrefillParams.notes}`
    if (!voicePrefillParams.symptoms || voicePrefillAppliedRef.current === key) return
    voicePrefillAppliedRef.current = key

    const symptoms = voicePrefillParams.symptoms
      .split(/[,\n]/)
      .map((item) => item.replace(/[.?!]+$/g, '').trim())
      .filter(Boolean)
      .slice(0, 12)

    if (symptoms.length) {
      setSelectedSymptoms((prev) => Array.from(new Set([...prev, ...symptoms])))
    }
    if (voicePrefillParams.duration) setDuration((current) => current || voicePrefillParams.duration)
    if (voicePrefillParams.notes) setNotes((current) => current || voicePrefillParams.notes)
  }, [voicePrefillParams])

  useEffect(() => {
    const fetchCreditStatus = async () => {
      try {
        const res = await fetch(`/api/credit/status`, { cache: 'no-store' })
        if (!res.ok) return
        const data = await res.json()
        const isPremium = data?.plan === 'PREMIUM'
        const hasWalletCredits =
          typeof data?.totalAvailableCents === 'number' && data.totalAvailableCents > 0
        const hasLegacyCredits =
          typeof data?.credits?.total === 'number' && data.credits.total > 0

        setHasPaidAccess(Boolean(isPremium || hasWalletCredits || hasLegacyCredits))
      } catch {
        // ignore failures – fall back to showing free banner
      }
    }
    fetchCreditStatus()
  }, [creditRefreshTick])

  const quickTags = [
    'Fever','Headache','Cough','Sore throat','Runny nose','Nasal congestion','Sneezing','Fatigue','Body aches','Chills','Night sweats',
    'Shortness of breath','Chest pain','Palpitations','Dizziness','Lightheadedness','Confusion','Anxiety','Depressed mood','Insomnia',
    'Nausea','Vomiting','Diarrhea','Constipation','Abdominal pain','Bloating','Heartburn','Indigestion','Loss of appetite',
    'Back pain','Joint pain','Muscle pain','Swollen joints','Rash','Itchy skin','Hives','Head pressure','Loss of taste','Loss of smell',
    'Ear pain','Tooth pain','Sore gums','Swollen glands','Frequent urination','Burning urination','Blood in urine','Blood in stool'
  ]

  const handleAddTag = (tag: string) => {
    setSelectedSymptoms((prev) => (prev.includes(tag) ? prev : [...prev, tag]))
  }

  const handleAddSymptom = () => {
    const s = symptomInput.trim()
    if (!s) return
    setSelectedSymptoms((prev) => (prev.includes(s) ? prev : [...prev, s]))
    setSymptomInput('')
  }

  const handleRemoveSymptom = (symptom: string) => {
    setSelectedSymptoms((prev) => prev.filter((s) => s !== symptom))
  }

  const runSymptomNotes = async () => {
    setError('')
    setResult(null)
    setIsAnalyzing(true)
    try {
      const res = await fetch('/api/analyze-symptoms', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ symptoms: selectedSymptoms, duration, notes })
      })

      if (res.status === 402) {
        const data = await res.json()
        setCreditInfo({
          dailyUsed: 0,
          dailyLimit: 0,
          additionalCredits: data.additionalCredits ?? 0,
          plan: data.plan ?? 'FREE',
          creditCost: data.creditCost ?? 1,
          dailyLimits: data.dailyLimits,
          featureUsageToday: data.featureUsageToday,
        })
        setShowCreditsModal(true)
        return
      }

      if (!res.ok) {
        const data = await res.json().catch(() => ({}))
        throw new Error(data?.error || 'Failed to create symptom notes')
      }

      const data: AnalysisResult = await res.json()
      setResult(data)
      // Trigger usage meter refresh after successful analysis
      try { window.dispatchEvent(new Event('credits:refresh')); } catch {}
    } catch (e: any) {
      setError(e?.message || 'Something went wrong')
    } finally {
      setIsAnalyzing(false)
      setProgress(100)
    }
  }

  const handleAnalyze = async () => {
    const hasAny = selectedSymptoms.length > 0
    if (!hasAny) {
      setError('Please enter at least one symptom.')
      return
    }

    if (!hasSavedAiConsent()) {
      setShowAiConsent(true)
      return
    }

    await runSymptomNotes()
  }

  const handleAiConsentAgree = () => {
