interface LayoutWrapperProps {
  children: ReactNode
}

const FEEDBACK_REQUIRED_ACTIVE_DAYS = 3

function toLocalDateKey(date: Date): string {
  const y = date.getFullYear()
  const m = `${date.getMonth() + 1}`.padStart(2, '0')
  const d = `${date.getDate()}`.padStart(2, '0')
  return `${y}-${m}-${d}`
}

function previousLocalDateKey(dateKey: string): string | null {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateKey)
  if (!match) return null
  const year = Number(match[1])
  const month = Number(match[2])
  const day = Number(match[3])
  if (!Number.isFinite(year) || !Number.isFinite(month) || !Number.isFinite(day)) return null
  const date = new Date(year, month - 1, day)
  date.setDate(date.getDate() - 1)
  return toLocalDateKey(date)
}

function parseActiveDayList(raw: string | null): string[] {
  if (!raw) return []
  try {
    const parsed = JSON.parse(raw)
    if (!Array.isArray(parsed)) return []
    return parsed
      .filter((value) => typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value))
      .slice(-60)
  } catch {
    return []
  }
}

function calculateConsecutiveActiveDays(activeDays: string[], todayKey: string): number {
  if (!activeDays.length) return 0
  const activeSet = new Set(activeDays)
  let streak = 0
  let cursor: string | null = todayKey
  while (cursor && activeSet.has(cursor)) {
    streak += 1
    cursor = previousLocalDateKey(cursor)
  }
  return streak
}

export default function LayoutWrapper({ children }: LayoutWrapperProps) {
  const pathname = usePathname()
  const router = useRouter()
  const { data: session, status } = useSession()
  const [showHealthSetupReminder, setShowHealthSetupReminder] = useState(false)
  const [showFeedbackPrompt, setShowFeedbackPrompt] = useState(false)
  const [feedbackPromptSeenServer, setFeedbackPromptSeenServer] = useState<boolean | null>(null)
  const [goalSyncNotice, setGoalSyncNotice] = useState<string | null>(null)
  const lastLocationRef = useRef('')
  const sidebarNavLockRef = useRef(0)
  const [sidebarPortal, setSidebarPortal] = useState<HTMLElement | null>(null)
  const goalSyncTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const [resumeTick, setResumeTick] = useState(0)
  const contentRef = useRef<HTMLDivElement | null>(null)
  const pullStartYRef = useRef<number | null>(null)
  const pullOffsetRef = useRef(0)
  const pullResetTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const pullRefreshingRef = useRef(false)
  const pullScrollParentRef = useRef<HTMLElement | null>(null)
  const [pullOffset, setPullOffset] = useState(0)
  const [pullRefreshing, setPullRefreshing] = useState(false)

  // Pages that should ALWAYS be public (no sidebar regardless of auth status)
  const publicPages = [
    '/',
    '/healthapp',
    '/public-home',
    '/auth/signin',
    '/auth/verify',
    '/auth/check-email',
    '/auth/forgot-password',
    '/auth/reset-password',
    '/onboarding',
    '/privacy',
    '/terms',
    '/help',
    '/faq',
    '/list-your-practice',
    '/list-your-practice/start',
    '/affiliate/apply',
    '/affiliate/terms',
  ]

  const isFeaturePath = pathname.startsWith('/features')
  const isNewsPath = pathname === '/news' || pathname.startsWith('/news/')
  const isPractitionerDirectoryPath =
    pathname === '/practitioners' || pathname.startsWith('/practitioners/')
  const isPractitionerPortalPath =
    pathname === '/practitioner' || pathname.startsWith('/practitioner/')
  const isWeeklyReportPrintPage = pathname.startsWith('/insights/weekly-report/print')
  const isPublicPage =
    publicPages.includes(pathname) || isFeaturePath || isNewsPath || isPractitionerDirectoryPath
  const isChatPage = pathname === '/chat'
  const isFoodDiaryPage = pathname === '/food'

  // Admin panel paths should never show user sidebar
  const isAdminPanelPath =
    pathname.startsWith('/admin-panel') || pathname.startsWith('/main-admin')

  // Dark mode is only allowed inside the signed-in app.
  // Keep public/auth pages in light mode even if the user enabled dark mode previously.
  const isOnboardingPath = pathname.startsWith('/onboarding')
  const themeAllowed =
    status === 'authenticated' &&
    !isWeeklyReportPrintPage &&
    !isAdminPanelPath &&
    (!isPublicPage || isOnboardingPath)

  const feedbackPromptStorageKey = session?.user?.email
    ? `helfi:feedback-prompt-shown:${session.user.email.toLowerCase()}`
    : ''
  const feedbackActiveDaysStorageKey = session?.user?.email
    ? `helfi:feedback-active-days:${session.user.email.toLowerCase()}`
    : ''

  const rememberFeedbackPromptSeen = useCallback((syncServer = true) => {
    if (feedbackPromptStorageKey && typeof window !== 'undefined') {
      try {
        localStorage.setItem(feedbackPromptStorageKey, '1')
      } catch {
        // Ignore storage errors
      }
    }
    setFeedbackPromptSeenServer(true)
    if (!syncServer) return
    fetch('/api/feedback-prompt', { method: 'POST' }).catch(() => {
      // Ignore network errors; local marker already prevents repeat in this browser
    })
  }, [feedbackPromptStorageKey])

  const dismissFeedbackPrompt = useCallback((openSupport: boolean) => {
    setShowFeedbackPrompt(false)
    rememberFeedbackPromptSeen(true)
    if (openSupport) {
      router.push('/support')
    }
  }, [rememberFeedbackPromptSeen, router])
  useEffect(() => {
    if (typeof document === 'undefined') return

    if (!themeAllowed) {
      document.documentElement.classList.remove('dark')
      return
    }

    try {
      const enabled = localStorage.getItem('darkMode') === 'true'
      document.documentElement.classList.toggle('dark', enabled)
    } catch {
      // Ignore storage errors
    }
  }, [themeAllowed])

  useEffect(() => {
    if (status !== 'authenticated' || !feedbackPromptStorageKey) {
      setFeedbackPromptSeenServer(null)
      return
    }

    let cancelled = false
    ;(async () => {
      try {
        const response = await fetch('/api/feedback-prompt', { method: 'GET', cache: 'no-store' })
        if (!response.ok) {
          if (!cancelled) setFeedbackPromptSeenServer(false)
          return
        }
        const data = await response.json().catch(() => ({}))
        const seen = Boolean(data?.seen)
        if (seen && feedbackPromptStorageKey && typeof window !== 'undefined') {
          try {
            localStorage.setItem(feedbackPromptStorageKey, '1')
          } catch {
            // Ignore storage errors
          }
        }
        if (!cancelled) setFeedbackPromptSeenServer(seen)
      } catch {
        if (!cancelled) setFeedbackPromptSeenServer(false)
      }
    })()

    return () => {
      cancelled = true
    }
  }, [status, feedbackPromptStorageKey, session?.user?.id])

  useEffect(() => {
    if (status !== 'authenticated') return
    if (!feedbackActiveDaysStorageKey) return
    if (!feedbackPromptStorageKey) return
    if (feedbackPromptSeenServer === null) return
    if (feedbackPromptSeenServer) return
    if (isPublicPage || isAdminPanelPath || isPractitionerPortalPath) return
    if (pathname.startsWith('/support')) return
    if ((session as any)?.user?.needsVerification) return

    try {
      const todayKey = toLocalDateKey(new Date())
      const activeDays = parseActiveDayList(localStorage.getItem(feedbackActiveDaysStorageKey))
      if (!activeDays.includes(todayKey)) {
        activeDays.push(todayKey)
        activeDays.sort()
        localStorage.setItem(feedbackActiveDaysStorageKey, JSON.stringify(activeDays.slice(-60)))
      }

      const streak = calculateConsecutiveActiveDays(activeDays, todayKey)
      if (streak < FEEDBACK_REQUIRED_ACTIVE_DAYS) return
      if (localStorage.getItem(feedbackPromptStorageKey) === '1') {
        setFeedbackPromptSeenServer(true)
        return
      }
    } catch {
      // Ignore storage errors
      return
    }

    // Mark as shown immediately so it can only appear once per user.
    rememberFeedbackPromptSeen(true)
    setShowFeedbackPrompt(true)
  }, [
    status,
    feedbackActiveDaysStorageKey,
    feedbackPromptStorageKey,
    feedbackPromptSeenServer,
    isPublicPage,
    isAdminPanelPath,
    isPractitionerPortalPath,
    pathname,
    rememberFeedbackPromptSeen,
    session,
  ])

  useEffect(() => {
    if (typeof window === 'undefined') return
    const handler = (href: string) => {
      try {
        const target = new URL(href, window.location.origin)
        if (target.origin !== window.location.origin) return
        const next = `${target.pathname}${target.search}${target.hash}`
        router.push(next)
      } catch {
        try {
          window.location.assign(href)
        } catch {
          // Ignore navigation errors
        }
      }
    }
    ;(window as any).__helfiNavigate = handler
    return () => {
      try {
        if ((window as any).__helfiNavigate === handler) {
          delete (window as any).__helfiNavigate
        }
      } catch {
        // Ignore cleanup errors
      }
    }
  }, [router])

  // ⚠️ GUARD RAIL: Allow pinch zoom, but always snap back to normal size after the gesture ends.
  useEffect(() => {
    if (typeof document === 'undefined') return
    const meta = document.querySelector('meta[name="viewport"]')
    if (!meta) return

    const allowZoomContent =
      'width=device-width, initial-scale=1, minimum-scale=1, maximum-scale=5, user-scalable=yes'
    const lockZoomContent =
      'width=device-width, initial-scale=1, minimum-scale=1, maximum-scale=1, user-scalable=yes'
    meta.setAttribute('content', allowZoomContent)

    let resetTimer: ReturnType<typeof setTimeout> | null = null
    const resetZoom = () => {
      meta.setAttribute('content', lockZoomContent)
      if (resetTimer) {
        clearTimeout(resetTimer)
      }
      resetTimer = setTimeout(() => {
        meta.setAttribute('content', allowZoomContent)
      }, 50)
    }

    const handleZoomChange = () => {
      if (window.visualViewport && window.visualViewport.scale > 1) {
        resetZoom()
      }
    }

    const handleGestureEnd = () => {
      handleZoomChange()
    }

    document.addEventListener('gestureend', handleGestureEnd, true)
    if (window.visualViewport) {
      window.visualViewport.addEventListener('resize', handleZoomChange)
    }

    return () => {
      document.removeEventListener('gestureend', handleGestureEnd, true)
      if (window.visualViewport) {
        window.visualViewport.removeEventListener('resize', handleZoomChange)
      }
      if (resetTimer) {
        clearTimeout(resetTimer)
      }
    }
  }, [])

  // ⚠️ GUARD RAIL: Scroll guard prevents accidental taps when a user is just scrolling.
  useEffect(() => {
    if (typeof document === 'undefined') return
    let startX = 0
    let startY = 0
    let moved = false
    let lastTouchTime = 0
    const threshold = 8

    const handleTouchStart = (event: TouchEvent) => {
      if (event.touches.length !== 1) return
      const touch = event.touches[0]
      startX = touch.clientX
      startY = touch.clientY
      moved = false
    }

    const handleTouchMove = (event: TouchEvent) => {
      if (event.touches.length !== 1) return
      const touch = event.touches[0]
      const dx = Math.abs(touch.clientX - startX)
      const dy = Math.abs(touch.clientY - startY)
      if (dx > threshold || dy > threshold) {
        moved = true
      }
    }

    const handleTouchEnd = () => {
      lastTouchTime = Date.now()
    }

    const handleClickCapture = (event: MouseEvent) => {
      if (!moved) return
      if (Date.now() - lastTouchTime > 450) return
      event.preventDefault()
      event.stopPropagation()
      moved = false
    }

    document.addEventListener('touchstart', handleTouchStart, { passive: true })
    document.addEventListener('touchmove', handleTouchMove, { passive: true })
    document.addEventListener('touchend', handleTouchEnd, { passive: true })
    document.addEventListener('touchcancel', handleTouchEnd, { passive: true })
    document.addEventListener('click', handleClickCapture, true)

    return () => {
      document.removeEventListener('touchstart', handleTouchStart)
      document.removeEventListener('touchmove', handleTouchMove)
      document.removeEventListener('touchend', handleTouchEnd)
      document.removeEventListener('touchcancel', handleTouchEnd)
      document.removeEventListener('click', handleClickCapture, true)
    }
  }, [])

  useEffect(() => {
    if (typeof document === 'undefined') return
    const getScrollableChild = (start: Element | null, stopAt: Element | null) => {
      let el = start
      while (el && el !== stopAt) {
        const style = window.getComputedStyle(el)
        const overflowY = style?.overflowY
        if (
          (overflowY === 'auto' || overflowY === 'scroll' || overflowY === 'overlay') &&
          el.scrollHeight > el.clientHeight + 1
        ) {
          return el as HTMLElement
        }
        el = el.parentElement
      }
      return null
    }

    const handleWheel = (event: WheelEvent) => {
      if (Math.abs(event.deltaX) > Math.abs(event.deltaY)) return
      const pointerTarget = event.target instanceof Element ? event.target : null
      if (!pointerTarget) return
      const zone = pointerTarget.closest('[data-scroll-zone="sidebar"]')
      if (!zone) return

      const innerScrollable = getScrollableChild(pointerTarget, zone)
      if (innerScrollable && innerScrollable !== zone) return

      const zoneEl = zone as HTMLElement
      if (zoneEl.scrollHeight <= zoneEl.clientHeight + 1) return

      zoneEl.scrollTop += event.deltaY
      event.preventDefault()
    }

    document.addEventListener('wheel', handleWheel, { passive: false })
    return () => {
      document.removeEventListener('wheel', handleWheel)
    }
  }, [])

  useEffect(() => {
    if (typeof window === 'undefined') return
    const handler = () => {
      setGoalSyncNotice('We refreshed your goal from your latest saved data to keep devices in sync.')
      if (goalSyncTimeoutRef.current) {
        clearTimeout(goalSyncTimeoutRef.current)
      }
      goalSyncTimeoutRef.current = setTimeout(() => {
        setGoalSyncNotice(null)
      }, 6000)
    }
    window.addEventListener('userData:goalSync', handler as EventListener)
    return () => {
      window.removeEventListener('userData:goalSync', handler as EventListener)
      if (goalSyncTimeoutRef.current) {
        clearTimeout(goalSyncTimeoutRef.current)
        goalSyncTimeoutRef.current = null
      }
    }
  }, [])

  useEffect(() => {
    if (typeof document === 'undefined') return
    let portal = document.getElementById('desktop-sidebar-portal') as HTMLElement | null
    if (!portal) {
      portal = document.createElement('div')
      portal.id = 'desktop-sidebar-portal'
      document.body.appendChild(portal)
    }
    setSidebarPortal(portal)
  }, [])

  // ⚠️ HEALTH SETUP GUARD RAIL
  // The 5-minute global Health Setup reminder must:
  // - Only appear for authenticated users on non-public, non-admin pages.
  // - Use GET /api/health-setup-status to respect account-wide "Don't ask me again".
  // - Show at most once per browser session via sessionStorage.helfiHealthSetupReminderShownThisSession.
  // Do NOT convert this into a hard block or change the timing/behaviour without
  // reading HEALTH_SETUP_PROTECTION.md and obtaining explicit user approval.

  // One-time per-session reminder: if a user has been using the app
  // for more than ~5 minutes without completing Health Setup, gently prompt
  // them to finish it. Users can permanently opt out of this reminder for
  // their account by choosing "Don't ask me again".
  useEffect(() => {
    if (status !== 'authenticated') return
    if (isPublicPage || isAdminPanelPath || isPractitionerPortalPath) return
    if ((session as any)?.user?.needsVerification) return

    try {
      if (sessionStorage.getItem('helfiHealthSetupReminderShownThisSession') === '1') {
        return
      }
    } catch {
      // Ignore storage errors
    }

    const timer = setTimeout(async () => {
      try {
        const res = await fetch('/api/health-setup-status', { method: 'GET' })
        if (!res.ok) return
        const data = await res.json()
        const complete = !!data.complete
        const reminderDisabled = !!data.reminderDisabled

        if (!complete && !reminderDisabled) {
          setShowHealthSetupReminder(true)
          try {
            sessionStorage.setItem('helfiHealthSetupReminderShownThisSession', '1')
          } catch {
            // Ignore
          }
        }
      } catch {
        // Non-blocking; ignore failures
      }
    }, 5 * 60 * 1000)

    return () => clearTimeout(timer)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [status, pathname, isAdminPanelPath, isPublicPage, isPractitionerPortalPath, session])

  // Track the last in-app page the user visited (for “resume where I left off”).
  // We only store non-public, non-admin paths so onboarding / auth pages are excluded.
  useEffect(() => {
    if (status !== 'authenticated') return
    if (isPublicPage || isAdminPanelPath || isPractitionerPortalPath) return
    if (typeof window === 'undefined') return
    try {
      const fullPath = window.location.pathname + window.location.search
      localStorage.setItem('helfi:lastPath', fullPath)
      // Mirror the last path into a simple cookie so the server can redirect
      const encoded = encodeURIComponent(fullPath)
      const maxAgeSeconds = 5 * 365 * 24 * 60 * 60 // ~5 years
      document.cookie = `helfi-last-path=${encoded}; path=/; max-age=${maxAgeSeconds}; samesite=lax`
    } catch {
      // Ignore storage errors
    }
  }, [status, pathname, isAdminPanelPath, isPublicPage, isPractitionerPortalPath])

  useEffect(() => {
    if (typeof window === 'undefined') return
    if (status !== 'authenticated') return
    if (isPublicPage || isAdminPanelPath || isPractitionerPortalPath) return

    const locationKey = `${window.location.pathname}?${window.location.search}|${resumeTick}`
    if (lastLocationRef.current === locationKey) return
    lastLocationRef.current = locationKey

    try {
      const params = new URLSearchParams(window.location.search)
      const pendingId = params.get('notificationId')
      const notificationOpen = params.get('notificationOpen') === '1'
      const preferredUrlPrefix = notificationOpen ? window.location.pathname : ''
      let shouldCheckPending = notificationOpen

      try {
        if (sessionStorage.getItem('helfi:notification-open') === '1') {
          shouldCheckPending = true
        }
      } catch {
        // Ignore storage errors
      }

      if (pendingId) {
        storePendingNotificationId(pendingId)
      }

      const runPendingOpen = (urlPrefix?: string | null) => {
        const endpoint = new URL('/api/notifications/pending-open', window.location.origin)
        if (urlPrefix) endpoint.searchParams.set('urlPrefix', urlPrefix)
        fetch(endpoint.toString(), { cache: 'no-store' as any })
          .then((res) => (res.ok ? res.json() : null))
          .then((data) => {
            if (!data) return
            const url = typeof data?.url === 'string' ? data.url : ''
            const pending = typeof data?.id === 'string' ? data.id : ''
            if (pending) storePendingNotificationId(pending)
            if (!url) return
            const targetUrl = new URL(url, window.location.origin)
            const currentUrl = new URL(window.location.href)
            if (urlPrefix && targetUrl.pathname !== urlPrefix) {
              return
            }
            if (targetUrl.pathname === currentUrl.pathname) return
            if (window.location.href === targetUrl.href) return
            window.location.href = targetUrl.href
          })
          .catch(() => {})
      }

      const readNotificationOpenFromDb = () =>
        new Promise<boolean>((resolve) => {
          if (typeof indexedDB === 'undefined') return resolve(false)
          try {
            const request = indexedDB.open('helfi-notifications', 1)
            request.onupgradeneeded = () => {
              try {
                request.result.createObjectStore('meta')
              } catch (e) {}
            }
            request.onerror = () => resolve(false)
            request.onsuccess = () => {
              const db = request.result
              try {
                const tx = db.transaction('meta', 'readonly')
                const store = tx.objectStore('meta')
                const getReq = store.get('notificationOpen')
                getReq.onerror = () => {
                  try {
                    db.close()
                  } catch {}
                  resolve(false)
                }
                getReq.onsuccess = () => {
                  const value = getReq.result
                  const ts = typeof value === 'number' ? value : null
                  const fresh = typeof ts === 'number' && Date.now() - ts < 5 * 60 * 1000
                  try {
                    db.close()
                  } catch {}
                  resolve(fresh)
                }
              } catch (e) {
                try {
                  db.close()
                } catch {}
                resolve(false)
              }
            }
          } catch {
            resolve(false)
          }
        })

      const clearNotificationOpenFromDb = () =>
        new Promise<void>((resolve) => {
          if (typeof indexedDB === 'undefined') return resolve()
          try {
            const request = indexedDB.open('helfi-notifications', 1)
            request.onupgradeneeded = () => {
              try {
                request.result.createObjectStore('meta')
              } catch (e) {}
            }
            request.onerror = () => resolve()
            request.onsuccess = () => {
              const db = request.result
              try {
                const tx = db.transaction('meta', 'readwrite')
                const store = tx.objectStore('meta')
                store.delete('notificationOpen')
                tx.oncomplete = () => {
                  try {
                    db.close()
                  } catch {}
                  resolve()
                }
                tx.onerror = () => {
                  try {
                    db.close()
                  } catch {}
                  resolve()
                }
              } catch (e) {
                try {
                  db.close()
                } catch {}
                resolve()
              }
            }
          } catch {
            resolve()
          }
        })

      const finalizePendingCheck = () => {
        runPendingOpen(preferredUrlPrefix || null)
        try {
          sessionStorage.removeItem('helfi:notification-open')
        } catch {
          // Ignore storage errors
        }
        void clearNotificationOpenFromDb()
      }

      if (shouldCheckPending) {
        finalizePendingCheck()
      } else {
        fetch('/api/notifications/notification-open', { cache: 'no-store' as any })
          .then((res) => (res.ok ? res.json() : null))
          .then((data) => {
            if (!data?.open) return
            finalizePendingCheck()
          })
          .catch(() => {})
        readNotificationOpenFromDb().then((open) => {
          if (!open) return
          finalizePendingCheck()
        })
      }

      if (pendingId || notificationOpen) {
        params.delete('notificationId')
        params.delete('notificationOpen')
        const query = params.toString()
        const nextUrl = `${window.location.pathname}${query ? `?${query}` : ''}${window.location.hash || ''}`
        window.history.replaceState(null, '', nextUrl)
      }

    } catch {
      // Ignore URL errors
    }
  })

  useEffect(() => {
    if (typeof window === 'undefined') return
    const bump = () => {
      setResumeTick((prev) => prev + 1)
    }
    const handleVisibility = () => {
      if (document.visibilityState === 'visible') bump()
    }
    window.addEventListener('focus', bump)
    window.addEventListener('pageshow', bump)
    document.addEventListener('visibilitychange', handleVisibility)
    return () => {
      window.removeEventListener('focus', bump)
      window.removeEventListener('pageshow', bump)
      document.removeEventListener('visibilitychange', handleVisibility)
    }
  }, [])

  // Show sidebar only if:
  // 1. User is authenticated (status === 'authenticated') AND
  // 2. Current page is not in publicPages list AND
  // 3. Current page is not an admin panel path
  const shouldShowSidebar =
    status === 'authenticated' &&
    !isWeeklyReportPrintPage &&
    !isAdminPanelPath &&
    !isPractitionerPortalPath &&
    (!isPublicPage || isOnboardingPath)

  const pagesWithOwnMobileBottomNav = [
    '/account',
    '/billing',
    '/dashboard',
    '/devices',
    '/food',
    '/food/water',
    '/health-tracking',
    '/help',
    '/insights',
    '/medical-images',
    '/mood',
    '/mood/history',
    '/mood/journal',
    '/mood/quick',
    '/more',
    '/onboarding',
    '/profile',
    '/settings',
    '/symptoms',
  ]
  const shouldShowGlobalMobileBottomNav =
    shouldShowSidebar &&
    !isChatPage &&
    !pagesWithOwnMobileBottomNav.includes(pathname) &&
    !pathname.startsWith('/insights/')

  const pullRefreshEnabled = shouldShowSidebar && !isChatPage && !isFoodDiaryPage
  const PULL_REFRESH_ACTIVATE = 60
  const PULL_REFRESH_THRESHOLD = 280
  const PULL_REFRESH_MAX = 360
  const PULL_REFRESH_START_ZONE = 140

  const isEditableElement = (target: EventTarget | null) => {
    if (typeof document === 'undefined') return false
    if (!(target instanceof Element)) return false
    if (target.closest('[data-pull-refresh-disabled="true"]')) return true
    return Boolean(target.closest('input, textarea, select, [contenteditable="true"]'))
  }

  const getScrollTop = () => {
    if (contentRef.current) return contentRef.current.scrollTop
    if (typeof window !== 'undefined') return window.scrollY
    return 0
  }

  const getScrollParent = (target: EventTarget | null) => {
    if (typeof window === 'undefined') return null
    if (!(target instanceof Element)) return null
    let el: Element | null = target
    while (el && el !== contentRef.current) {
      const style = window.getComputedStyle(el)
      const overflowY = style?.overflowY
      if ((overflowY === 'auto' || overflowY === 'scroll') && el.scrollHeight > el.clientHeight + 1) {
        return el as HTMLElement
      }
      el = el.parentElement
    }
    return null
  }

  const hasVisibleEditableFields = () => {
    if (typeof document === 'undefined') return false
    const root = contentRef.current || document.body
    const fields = root.querySelectorAll('input, textarea, select, [contenteditable="true"]')
    if (!fields.length) return false
    return Array.from(fields).some((field) => {
      if (field instanceof HTMLInputElement) {
        if (field.type === 'hidden' || field.disabled || field.readOnly) return false
      }
      if (field instanceof HTMLTextAreaElement || field instanceof HTMLSelectElement) {
        if (field.disabled) return false
      }
      if (field instanceof HTMLElement) {
        const style = window.getComputedStyle(field)
        if (style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0') {
          return false
        }
        const rect = field.getBoundingClientRect()
        if (rect.width === 0 || rect.height === 0) return false
      }
      return true
    })
  }

  const clearPullState = () => {
    pullStartYRef.current = null
    pullOffsetRef.current = 0
    pullScrollParentRef.current = null
    setPullOffset(0)
  }

  const triggerPullRefresh = () => {
    if (typeof window === 'undefined') return
    pullRefreshingRef.current = true
    setPullRefreshing(true)
    if (pullResetTimeoutRef.current) {
      clearTimeout(pullResetTimeoutRef.current)
    }
    pullResetTimeoutRef.current = setTimeout(() => {
      pullRefreshingRef.current = false
      setPullRefreshing(false)
    }, 2000)
    window.location.reload()
  }

  const handlePullStart = (event: React.TouchEvent<HTMLDivElement>) => {
    if (!pullRefreshEnabled) return
    if (pullRefreshingRef.current) return
    if (event.touches.length !== 1) return
    if (getScrollTop() > 0) return
    if (isEditableElement(event.target) || isEditableElement(document.activeElement)) return
    if (hasVisibleEditableFields()) return
    const scrollParent = getScrollParent(event.target)
    if (scrollParent && scrollParent.scrollTop > 0) return
    pullOffsetRef.current = 0
    setPullOffset(0)
    const startY = event.touches[0]?.clientY ?? null
    if (startY === null || startY > PULL_REFRESH_START_ZONE) return
    pullScrollParentRef.current = scrollParent
    pullStartYRef.current = startY
  }

  const handlePullMove = (event: React.TouchEvent<HTMLDivElement>) => {
    if (!pullRefreshEnabled) return
    if (pullStartYRef.current === null) return
    if (hasVisibleEditableFields()) {
      clearPullState()
      return
    }
    if (pullScrollParentRef.current && pullScrollParentRef.current.scrollTop > 0) {
      clearPullState()
      return
    }
    if (getScrollTop() > 0) {
      clearPullState()
      return
    }
    const currentY = event.touches[0]?.clientY ?? 0
    const delta = currentY - (pullStartYRef.current || 0)
    if (delta <= PULL_REFRESH_ACTIVATE) {
      pullOffsetRef.current = 0
      setPullOffset(0)
      return
    }
    const nextOffset = Math.min(PULL_REFRESH_MAX, delta - PULL_REFRESH_ACTIVATE)
    pullOffsetRef.current = nextOffset
    setPullOffset(nextOffset)
  }

  const handlePullEnd = () => {
    if (!pullRefreshEnabled) {
      clearPullState()
      return
    }
    if (pullStartYRef.current === null) return
    const shouldRefresh = pullOffsetRef.current >= PULL_REFRESH_THRESHOLD
    clearPullState()
    if (shouldRefresh) {
      triggerPullRefresh()
    }
  }

  useEffect(() => {
    if (!pullRefreshEnabled) {
      clearPullState()
      if (pullRefreshingRef.current) {
        pullRefreshingRef.current = false
        setPullRefreshing(false)
      }
    }
    return () => {
      if (pullResetTimeoutRef.current) {
        clearTimeout(pullResetTimeoutRef.current)
        pullResetTimeoutRef.current = null
      }
    }
  }, [pullRefreshEnabled, pathname])

  const handleSidebarNavigate = useCallback(
    (href: string, e: SidebarNavigateEvent) => {
      try {
        e.preventDefault()
      } catch {}
      if (typeof href !== 'string' || !href) return
      const now = Date.now()
      if (now - sidebarNavLockRef.current < 350) return
      sidebarNavLockRef.current = now

      // Health Setup / Onboarding: if there are unsaved changes, ask the user once
      // before leaving the section (the onboarding page owns the popup).
      if (isOnboardingPath) {
        try {
          const hasUnsaved =
            !!(window as any).__helfiOnboardingPhysicalHasUnsavedChanges ||
            !!(window as any).__helfiOnboardingHasUnsavedChanges
          const autoUpdateFlag = (window as any).__helfiOnboardingAutoUpdateOnExit
          const allowBackgroundExit = autoUpdateFlag !== false
          if (hasUnsaved) {
            if (!allowBackgroundExit) {
              window.postMessage({ type: 'OPEN_ONBOARDING_UPDATE_POPUP', navigateTo: href }, '*')
              return
            }
          }
        } catch {
          // fall through
        }
      }

      try {
        router.push(href)
      } catch {
        window.location.assign(href)
      }
    },
    [isOnboardingPath, router]
  )

  useEffect(() => {
    if (typeof document === 'undefined') return
    if (!shouldShowSidebar || !isOnboardingPath) return
    if ((window as any).__helfiOnboardingSidebarOverride) return

    const handler = (event: Event) => {
      const target = event.target as Element | null
      if (!target) return
      const sidebar = document.querySelector('[data-helfi-sidebar="true"]') as HTMLElement | null
      if (!sidebar || !sidebar.contains(target)) return
      const anchor = (target as HTMLElement).closest('a[href]') as HTMLAnchorElement | null
      if (!anchor) return
      const href = anchor.getAttribute('href')
      if (!href) return
      try {
        event.preventDefault()
      } catch {}
      try {
        ;(event as Event).stopPropagation?.()
      } catch {}
      handleSidebarNavigate(href, event)
    }

    document.addEventListener('pointerdown', handler, true)
    document.addEventListener('mousedown', handler, true)
    document.addEventListener('click', handler, true)
    return () => {
      document.removeEventListener('pointerdown', handler, true)
      document.removeEventListener('mousedown', handler, true)
      document.removeEventListener('click', handler, true)
    }
  }, [shouldShowSidebar, isOnboardingPath, handleSidebarNavigate])

  // Don't show sidebar while session is loading to prevent flickering
  if (status === 'loading') {
    return (
      <div className="min-h-screen">
        {children}
      </div>
    )
  }

  // Check if authenticated user needs email verification
  if (status === 'authenticated' && session?.user?.needsVerification && !isPublicPage && !isAdminPanelPath) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-b from-white to-helfi-green-light/10 p-4">
        <div className="max-w-md w-full bg-white rounded-lg shadow-lg p-6 text-center">
          <div className="mb-4">
            <div className="mx-auto w-16 h-16 bg-yellow-100 rounded-full flex items-center justify-center">
              <svg className="w-8 h-8 text-yellow-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L4.082 16.5c-.77.833.192 2.5 1.732 2.5z" />
              </svg>
            </div>
          </div>
          <h2 className="text-xl font-semibold text-gray-900 mb-2">Email Verification Required</h2>
          <p className="text-gray-600 mb-4">
            Please check your email for a verification link. You must verify your email address before accessing your account.
          </p>
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 mb-4">
            <p className="text-blue-700 text-sm">
              📧 Verification email sent to: <strong>{session?.user?.email}</strong>
            </p>
          </div>
          <div className="space-y-3">
            <button
              onClick={async () => {
                try {
                  const response = await fetch('/api/auth/resend-verification', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ email: session?.user?.email })
                  })

                  if (response.ok) {
                    alert('✅ Verification email sent! Please check your inbox.')
                  } else {
                    const error = await response.json()
                    alert(`❌ Failed to send email: ${error.error}`)
                  }
                } catch (error) {
                  alert('❌ Failed to send verification email. Please try again.')
                }
              }}
              className="w-full bg-blue-500 text-white px-4 py-2 rounded-lg hover:bg-blue-600 transition-colors font-medium"
            >
              📧 Resend Verification Email
            </button>
            <button
              onClick={() => window.location.href = '/auth/signin'}
              className="w-full bg-gray-500 text-white px-4 py-2 rounded-lg hover:bg-gray-600 transition-colors font-medium"
            >
              Back to Sign In
            </button>
          </div>
        </div>
      </div>
    )
  }

  if (status === 'unauthenticated' && !isPublicPage && !isAdminPanelPath) {
    if (typeof window !== 'undefined') {
      window.location.href = '/auth/signin'
    }
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <p className="text-gray-600">Redirecting...</p>
        </div>
      </div>
    )
  }

  if (shouldShowSidebar) {
    return (
      <div className="flex min-h-screen bg-gray-50">
        {/* Desktop Sidebar - Only for authenticated users on app pages */}
        {sidebarPortal
          ? createPortal(
              <DesktopSidebar pathname={pathname} onNavigate={handleSidebarNavigate} />,
              sidebarPortal
            )
          : null}

        {/* Main Content */}
        <div
          ref={contentRef}
          onTouchStart={handlePullStart}
          onTouchMove={handlePullMove}
          onTouchEnd={handlePullEnd}
          onTouchCancel={handlePullEnd}
          data-scroll-zone="content"
          className={`md:pl-64 flex flex-col flex-1 relative overflow-x-hidden ${
            isChatPage ? 'overflow-hidden h-[100dvh]' : 'overflow-y-auto'
          } ${shouldShowGlobalMobileBottomNav ? 'pb-[calc(5rem+env(safe-area-inset-bottom))] md:pb-0' : ''}`}
        >
          {goalSyncNotice && (
            <div className="fixed top-4 right-4 z-50 max-w-xs w-full mx-4 md:mx-0">
              <div className="bg-white border border-emerald-200 shadow-lg rounded-lg p-3">
                <div className="text-sm font-semibold text-gray-900">Goal updated</div>
                <div className="text-xs text-gray-600 mt-1">{goalSyncNotice}</div>
              </div>
            </div>
          )}
          {pullRefreshEnabled && (pullRefreshing || pullOffset > 0) && (
            <div
              className="flex items-center justify-center text-sm text-gray-500 transition-all duration-150"
              style={{ height: pullRefreshing ? 48 : Math.min(pullOffset, 80) }}
            >
              {pullRefreshing ? (
                <span className="flex items-center gap-2">
                  <svg className="w-4 h-4 animate-spin" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"
                    />
                  </svg>
                  Refreshing...
                </span>
              ) : (
                <span>{pullOffset >= PULL_REFRESH_THRESHOLD ? 'Release to refresh' : 'Pull to refresh'}</span>
              )}
            </div>
          )}
          {showFeedbackPrompt && (
            <div className="fixed inset-0 z-[10001] flex items-center justify-center bg-black/40 p-4">
              <div className="max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-xl bg-white p-5 shadow-2xl sm:p-6">
                <h2 className="text-[2rem] font-semibold leading-tight text-gray-900 sm:text-2xl">
                  {FEEDBACK_POPUP_COPY.title}
                </h2>
                <p className="mt-4 text-[1.35rem] leading-[2rem] text-gray-700 sm:mt-3 sm:text-base sm:leading-7">
                  {FEEDBACK_POPUP_COPY.body}
                </p>
                <ul className="mt-5 space-y-3 text-[1.35rem] leading-[2rem] text-gray-700 sm:mt-4 sm:space-y-2 sm:text-base sm:leading-7">
                  {FEEDBACK_POPUP_COPY.supportSteps.map((step) => (
                    <li key={step} className="flex items-start gap-2">
                      <span className="mt-2 h-2.5 w-2.5 rounded-full bg-emerald-500 sm:mt-2 sm:h-1.5 sm:w-1.5" />
                      <span>{step}</span>
                    </li>
                  ))}
                </ul>
                <div className="mt-6 flex flex-col gap-3 sm:flex-row sm:gap-2">
                  <button
                    type="button"
                    onClick={() => dismissFeedbackPrompt(true)}
                    className="flex-1 rounded-md bg-helfi-green px-4 py-3 text-[1.45rem] font-semibold text-white transition-colors hover:bg-emerald-700 sm:py-2 sm:text-base"
                  >
                    {FEEDBACK_POPUP_COPY.primaryButtonLabel}
                  </button>
                  <button
                    type="button"
                    onClick={() => dismissFeedbackPrompt(false)}
                    className="flex-1 rounded-md bg-gray-100 px-4 py-3 text-[1.45rem] font-semibold text-gray-700 transition-colors hover:bg-gray-200 sm:py-2 sm:text-base"
                  >
                    {FEEDBACK_POPUP_COPY.secondaryButtonLabel}
                  </button>
                </div>
              </div>
            </div>
          )}
          {showHealthSetupReminder && (
            <div className="fixed bottom-4 right-4 z-50 max-w-sm w-full mx-4 md:mx-0">
              <div className="bg-white border border-helfi-green/30 shadow-xl rounded-lg p-4">
                <h2 className="text-sm font-semibold text-helfi-black dark:text-white mb-1">
                  Complete your Health Setup for accurate insights
                </h2>
                <p className="text-xs text-gray-600 mb-3">
                  Helfi can only give you precise health guidance when your Health Setup is finished.
                </p>
                <div className="flex flex-col sm:flex-row gap-2">
                  <button
                    type="button"
                    onClick={() => {
                      setShowHealthSetupReminder(false)
                      router.push('/onboarding?step=1')
                    }}
                    className="flex-1 bg-helfi-green text-white text-sm px-3 py-2 rounded-md hover:bg-helfi-green-dark transition-colors"
                  >
                    Complete Health Setup
                  </button>
                  <button
                    type="button"
                    onClick={async () => {
                      setShowHealthSetupReminder(false)
                      try {
                        await fetch('/api/health-setup-status', {
                          method: 'POST',
                          headers: { 'Content-Type': 'application/json' },
                          body: JSON.stringify({ disableReminder: true }),
                        })
                      } catch {
                        // Non-blocking; if this fails we may remind again in a future session
                      }
                    }}
                    className="flex-1 bg-gray-100 text-gray-700 text-sm px-3 py-2 rounded-md hover:bg-gray-200 transition-colors"
                  >
                    Don&apos;t ask me again
                  </button>
                </div>
              </div>
            </div>
          )}
          {children}
          {shouldShowGlobalMobileBottomNav && <MobileBottomNav />}
          <SupportChatWidget />
          <WeeklyReportReadyModal />
        </div>
      </div>
    )
  }

  // Public pages or unauthenticated users - no sidebar
  const showBackToTop = status !== 'authenticated'
  return (
    <div className="min-h-screen overflow-x-hidden">
      {children}
      {!isWeeklyReportPrintPage && <SupportChatWidget />}
      {showBackToTop && !isWeeklyReportPrintPage && <BackToTopButton />}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import Link from 'next/link'

interface LowCreditsModalProps {
  isOpen: boolean
  onClose: () => void
  creditsRemaining?: number
  featureName?: string
}

export default function LowCreditsModal({ 
  isOpen, 
  onClose, 
  creditsRemaining = 0,
  featureName = 'AI features'
}: LowCreditsModalProps) {
  const [isClosing, setIsClosing] = useState(false)

  useEffect(() => {
    if (isOpen) {
      setIsClosing(false)
      // Prevent body scroll when modal is open
      document.body.style.overflow = 'hidden'
    } else {
      document.body.style.overflow = ''
    }
    return () => {
      document.body.style.overflow = ''
    }
  }, [isOpen])

  const handleClose = () => {
    setIsClosing(true)
    setTimeout(() => {
      onClose()
      setIsClosing(false)
    }, 200)
  }

  if (!isOpen) return null

  return (
    <div 
      className={`fixed inset-0 z-50 flex items-center justify-center p-4 transition-opacity duration-200 ${
        isClosing ? 'opacity-0' : 'opacity-100'
      }`}
      onClick={handleClose}
    >
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" />

      {/* Modal */}
      <div 
        className={`relative bg-white rounded-2xl shadow-2xl max-w-md w-full transform transition-all duration-200 ${
          isClosing ? 'scale-95 opacity-0' : 'scale-100 opacity-100'
        }`}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Close button */}
        <button
          onClick={handleClose}
          className="absolute top-4 right-4 p-2 text-gray-400 hover:text-gray-600 transition-colors rounded-full hover:bg-gray-100"
          aria-label="Close"
        >
          <svg
            className="w-5 h-5"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            aria-hidden="true"
          >
            <path d="M18 6L6 18" />
            <path d="M6 6l12 12" />
          </svg>
