'use client'

import { useRouter } from 'next/navigation'
import { useSession, signOut } from 'next-auth/react'
import Image from 'next/image'
import { useEffect, useState } from 'react'
import Link from 'next/link'
import { useUserData } from '@/components/providers/UserDataProvider'
import { UserIcon } from '@heroicons/react/24/outline'
import { isCacheFresh, readClientCache, writeClientCache } from '@/lib/client-cache'

const AFFILIATE_CACHE_TTL_MS = 10 * 60_000

interface PageHeaderProps {
  title: string
  backHref?: string // Optional custom back destination, defaults to router.back()
}

export default function PageHeader({ title, backHref }: PageHeaderProps) {
  const router = useRouter()
  const { data: session } = useSession()
  const { profileImage } = useUserData()
  const [dropdownOpen, setDropdownOpen] = useState(false)
  const [affiliateMenu, setAffiliateMenu] = useState<{ label: string; href: string } | null>(null)
  const [unreadCount, setUnreadCount] = useState(0)
  const affiliateCacheKey = session?.user?.email ? `affiliate-menu:${session.user.email}` : ''

  const hasProfileImage = !!(profileImage || session?.user?.image)
  const userImage = (profileImage || session?.user?.image || '') as string
  const userName = session?.user?.name || 'User'

  const handleBack = () => {
    if (typeof window !== 'undefined' && window.history.length > 1) {
      router.back()
      return
    }
    if (backHref) {
      router.push(backHref)
      return
    }
    router.push('/dashboard')
  }

  const handleSignOut = async () => {
    // Clear user-specific localStorage before signing out
    if (session?.user?.id) {
      localStorage.removeItem(`profileImage_${session.user.id}`)
      localStorage.removeItem(`cachedProfileImage_${session.user.id}`)
    }
    await signOut({ callbackUrl: '/auth/signin' })
  }

  useEffect(() => {
    if (!session?.user?.id) return
    let mounted = true
    const loadUnread = async () => {
      try {
        const res = await fetch('/api/notifications/unread-count', { cache: 'no-store' as any })
        if (!res.ok) return
        const data = await res.json().catch(() => ({}))
        if (mounted) {
          const count = typeof data?.count === 'number' ? data.count : 0
          setUnreadCount(Number.isFinite(count) ? count : 0)
        }
      } catch {
        // ignore
      }
    }
    loadUnread()

    const handleRefresh = () => loadUnread()
    window.addEventListener('focus', handleRefresh)
    window.addEventListener('notifications:refresh', handleRefresh)
    return () => {
      mounted = false
      window.removeEventListener('focus', handleRefresh)
      window.removeEventListener('notifications:refresh', handleRefresh)
    }
  }, [session?.user?.id])

  useEffect(() => {
    if (!affiliateCacheKey) {
      setAffiliateMenu(null)
      return
    }
    let cancelled = false
    setAffiliateMenu({ label: 'Become an Affiliate', href: '/affiliate/apply' })
    const cached = affiliateCacheKey ? readClientCache<{ label: string; href: string }>(affiliateCacheKey) : null
    if (cached?.data) {
      setAffiliateMenu(cached.data)
    }
    if (cached && isCacheFresh(cached, AFFILIATE_CACHE_TTL_MS)) {
      return () => {
        cancelled = true
      }
    }
    const load = async () => {
      try {
        const res = await fetch('/api/affiliate/application', { cache: 'no-store' })
        const data = await res.json().catch(() => ({} as any))
        if (!res.ok) return

        const hasAffiliate = !!data?.affiliate
        const hasApplication = !!data?.application

        const menu = hasAffiliate
          ? { label: 'Affiliate Portal', href: '/affiliate' }
          : hasApplication
            ? { label: 'Affiliate Application', href: '/affiliate/apply' }
            : { label: 'Become an Affiliate', href: '/affiliate/apply' }

        if (!cancelled) {
          setAffiliateMenu(menu)
          if (affiliateCacheKey) {
            writeClientCache(affiliateCacheKey, menu)
          }
        }
      } catch {
        // ignore
      }
    }
    load()
    return () => {
      cancelled = true
    }
  }, [affiliateCacheKey])

  return (
    <nav className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 px-4 py-3">
      <div className="max-w-7xl mx-auto flex items-center justify-between">
        {/* Back Button */}
        <button
          onClick={handleBack}
          className="flex items-center justify-center w-10 h-10 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors touch-manipulation"
          aria-label="Go back"
        >
          <svg
            className="w-6 h-6 text-gray-700 dark:text-gray-300"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M15 19l-7-7 7-7"
            />
          </svg>
        </button>

        {/* Page Title - Centered */}
        <h1 className="flex-1 text-center text-lg font-semibold text-gray-900 dark:text-white">
          {title}
        </h1>

        {/* Profile Avatar & Dropdown */}
        <div className="relative dropdown-container" id="profile-dropdown">
          <button
            onClick={() => setDropdownOpen((v) => !v)}
            className="focus:outline-none"
            aria-label="Open profile menu"
          >
            <div className="relative">
              {hasProfileImage ? (
                <Image
                  src={userImage}
                  alt="Profile"
                  width={40}
                  height={40}
                  className="w-10 h-10 rounded-full border-2 border-helfi-green shadow-sm object-cover"
                />
              ) : (
                <div className="w-10 h-10 rounded-full bg-helfi-green shadow-sm flex items-center justify-center">
                  <UserIcon className="w-6 h-6 text-white" aria-hidden="true" />
                </div>
              )}
              {unreadCount > 0 && (
                <span className="absolute -top-1 -right-1 min-w-[18px] px-1 h-[18px] rounded-full bg-red-500 text-white text-[10px] font-semibold flex items-center justify-center shadow">
                  {unreadCount > 99 ? '99+' : unreadCount}
                </span>
              )}
            </div>
          </button>
          {dropdownOpen && (
            <div className="absolute right-0 mt-2 w-64 bg-white dark:bg-gray-800 rounded-xl shadow-lg py-2 z-50 border border-gray-100 dark:border-gray-700 animate-fade-in">
              <div className="flex items-center px-4 py-3 border-b border-gray-100 dark:border-gray-700">
                {hasProfileImage ? (
                  <Image
                    src={userImage}
                    alt="Profile"
                    width={40}
                    height={40}
                    className="w-10 h-10 rounded-full object-cover mr-3"
                  />
                ) : (
                  <div className="w-10 h-10 rounded-full bg-helfi-green flex items-center justify-center mr-3">
                    <UserIcon className="w-6 h-6 text-white" aria-hidden="true" />
                  </div>
                )}
                <div>
                  <div className="font-semibold text-gray-900 dark:text-white">{userName}</div>
                  <div className="text-xs text-gray-500 dark:text-gray-400">
                    {session?.user?.email || 'user@email.com'}
                  </div>
                </div>
              </div>
              <Link
                href="/profile"
                className="block px-4 py-2 text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700"
                onClick={() => setDropdownOpen(false)}
              >
                Profile
              </Link>
              <Link
                href="/account"
                className="block px-4 py-2 text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700"
                onClick={() => setDropdownOpen(false)}
              >
                Account Settings
              </Link>
              <Link
                href="/profile/image"
                className="block px-4 py-2 text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700"
                onClick={() => setDropdownOpen(false)}
              >
                Upload/Change Profile Photo
              </Link>
              <Link
                href="/billing"
                className="block px-4 py-2 text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700"
                onClick={() => setDropdownOpen(false)}
              >
                Subscription & Billing
              </Link>
              {affiliateMenu && (
                <Link
                  href={affiliateMenu.href}
                  className="block px-4 py-2 text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700"
                  onClick={() => setDropdownOpen(false)}
                >
                  {affiliateMenu.label}
                </Link>
              )}
              <Link
                href="/notifications"
                className="block px-4 py-2 text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700"
                onClick={() => setDropdownOpen(false)}
              >
                Notifications
              </Link>
              <Link
                href="/privacy"
                className="block px-4 py-2 text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700"
                onClick={() => setDropdownOpen(false)}
              >
                Privacy Settings
              </Link>
              <Link
                href="/support"
                className="block px-4 py-2 text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700"
                onClick={() => setDropdownOpen(false)}
              >
                Help & Support
              </Link>
              <div className="border-t border-gray-100 dark:border-gray-700 my-2"></div>
              <button
                onClick={handleSignOut}
                className="block w-full text-left px-4 py-2 text-red-600 dark:text-red-400 hover:bg-gray-50 dark:hover:bg-gray-700 font-semibold"
              >
                Logout
              </button>
            </div>
          )}
        </div>
      </div>
    </nav>
  )
}

'use client'

import { useEffect, useMemo, useState } from 'react'
import Link from 'next/link'

type PractitionerRecommendation = {
  id: string
  displayName: string
  slug: string
  categoryName: string | null
  subcategoryName: string | null
  description: string | null
  phone: string | null
  websiteUrl: string | null
  emailPublic: string | null
  suburbCity: string | null
  stateRegion: string | null
  country: string | null
  distanceKm: number | null
  reason: string
  matchedIssue: string
  trackingToken?: string | null
}

type UserLocation = {
  lat: number
  lng: number
  country?: string | null
}

type Props = {
  issueText: string
  sourceArea: 'onboarding' | 'chat' | 'image' | 'symptom-notes'
  className?: string
  compact?: boolean
  requestLocation?: boolean
}

const LOCATION_KEY = 'helfi:practitionerLocation'

function readSavedLocation(): UserLocation | null {
  if (typeof window === 'undefined') return null
  try {
    const params = new URLSearchParams(window.location.search)
    const lat = Number(params.get('practitionerLat'))
    const lng = Number(params.get('practitionerLng'))
    const isLocalTest =
      window.location.hostname === 'localhost' ||
      window.location.hostname === '127.0.0.1' ||
      window.location.hostname === '::1'
    if (isLocalTest && Number.isFinite(lat) && Number.isFinite(lng)) {
      return {
        lat,
        lng,
        country: params.get('practitionerCountry') || null,
      }
    }
  } catch {
    // Continue to saved location below.
  }
  try {
    const raw = window.localStorage.getItem(LOCATION_KEY)
    if (!raw) return null
    const parsed = JSON.parse(raw)
    const lat = Number(parsed?.lat)
    const lng = Number(parsed?.lng)
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null
    return {
      lat,
      lng,
      country: typeof parsed?.country === 'string' ? parsed.country : null,
    }
  } catch {
    return null
  }
}

function getBrowserLocation(): Promise<UserLocation | null> {
  if (typeof navigator === 'undefined' || !navigator.geolocation) return Promise.resolve(null)
  return new Promise((resolve) => {
    navigator.geolocation.getCurrentPosition(
      (position) => {
        resolve({
          lat: position.coords.latitude,
          lng: position.coords.longitude,
        })
      },
      () => resolve(null),
      { enableHighAccuracy: false, timeout: 5000, maximumAge: 1000 * 60 * 60 }
    )
  })
}

function formatPlace(item: PractitionerRecommendation) {
  return [item.suburbCity, item.stateRegion, item.country].filter(Boolean).join(', ')
}

function isNativeRecommendationBridge() {
  if (typeof window === 'undefined') return false
  try {
    const params = new URLSearchParams(window.location.search)
    return (
      params.get('helfiNative') === '1' ||
      document.documentElement.getAttribute('data-helfi-native-webview') === '1' ||
      Boolean((window as any).ReactNativeWebView?.postMessage)
    )
  } catch {
    return false
  }
}

function postNativeRecommendationRequest(issueText: string, sourceArea: Props['sourceArea']) {
  try {
    const bridge = (window as any).ReactNativeWebView
    if (!bridge || typeof bridge.postMessage !== 'function') return
    bridge.postMessage(
      JSON.stringify({
        type: 'helfi:practitionerRecommendationRequest',
        issueText,
        sourceArea,
      })
    )
  } catch {
    // Native bridge is optional; the website still renders normally.
  }
}

export default function PractitionerRecommendations({
  issueText,
  sourceArea,
  className = '',
  compact = false,
  requestLocation = true,
}: Props) {
  const [results, setResults] = useState<PractitionerRecommendation[]>([])
  const [loaded, setLoaded] = useState(false)
  const trimmedIssueText = useMemo(() => String(issueText || '').trim(), [issueText])

  useEffect(() => {
    let cancelled = false

    async function load() {
      setLoaded(false)
      setResults([])
      if (isNativeRecommendationBridge()) {
        postNativeRecommendationRequest(trimmedIssueText, sourceArea)
        setLoaded(true)
        return
      }

      if (!trimmedIssueText) {
        setLoaded(true)
        return
      }

      const savedLocation = readSavedLocation()
      const location = savedLocation || (requestLocation ? await getBrowserLocation() : null)
      if (!location || cancelled) {
        setLoaded(true)
        return
      }

      try {
        const res = await fetch('/api/practitioners/recommendations', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            issueText: trimmedIssueText,
            sourceArea,
            lat: location.lat,
            lng: location.lng,
            country: location.country || undefined,
          }),
        })
        const data = await res.json().catch(() => ({}))
        if (!cancelled && res.ok && Array.isArray(data?.results)) {
          setResults(data.results)
        }
      } catch {
        if (!cancelled) setResults([])
      } finally {
        if (!cancelled) setLoaded(true)
      }
    }

    load()
    return () => {
      cancelled = true
    }
  }, [requestLocation, sourceArea, trimmedIssueText])

  if (!loaded || results.length === 0) return null

  return (
    <section className={`${compact ? 'mt-3' : 'mt-5'} ${className}`.trim()}>
      <div className="rounded-lg border border-emerald-200 bg-emerald-50/70 p-3 md:p-4">
        <div className="mb-3">
          <h3 className="text-sm font-semibold text-emerald-950">Practitioners near you</h3>
          <p className="mt-1 text-xs text-emerald-800">
            Based on what you shared, these nearby practitioners may be relevant.
          </p>
        </div>
        <div className="space-y-2">
          {results.map((item) => {
            const contactUrl = item.websiteUrl || `/practitioners/${item.slug}`
            const place = formatPlace(item)
            return (
              <div key={item.id} className="rounded-md border border-emerald-100 bg-white p-3">
                <div className="flex items-start justify-between gap-3">
                  <div className="min-w-0">
                    <div className="text-sm font-semibold text-gray-950">{item.displayName}</div>
                    <div className="mt-0.5 text-xs text-gray-600">
                      {[item.subcategoryName, item.categoryName].filter(Boolean).join(' - ')}
                    </div>
                  </div>
                  {typeof item.distanceKm === 'number' && (
                    <div className="shrink-0 rounded-full bg-emerald-100 px-2 py-1 text-xs font-semibold text-emerald-800">
                      {item.distanceKm}km
                    </div>
                  )}
                </div>
                {place && <div className="mt-2 text-xs text-gray-600">{place}</div>}
                <div className="mt-2 text-xs text-gray-700">{item.reason}</div>
                <div className="mt-3 flex flex-wrap gap-2">
                  <Link
                    href={`/practitioners/${item.slug}`}
