const MEAL_OPTIONS_JSON_START = '[[MEAL_OPTIONS_JSON]]'
const MEAL_OPTIONS_JSON_END = '[[/MEAL_OPTIONS_JSON]]'

const isIsoDate = (value: string) => /^\d{4}-\d{2}-\d{2}$/.test(String(value || '').trim())
const buildTodayIso = () => {
  const now = new Date()
  const year = now.getFullYear()
  const month = String(now.getMonth() + 1).padStart(2, '0')
  const day = String(now.getDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

const stripOuterBold = (value: string) => {
  const v = String(value || '').trim()
  if (v.startsWith('**') && v.endsWith('**') && v.length > 4) return v.slice(2, -2).trim()
  return v
}

const inferCategoryFromMealTitle = (title: string): MealCategory => {
  const t = String(title || '').toLowerCase()
  if (
    /(breakfast|oat|porridge|omelette|omelet|toast|pancake|waffle|yogurt bowl|smoothie bowl|granola)/i.test(t)
  ) {
    return 'breakfast'
  }
  if (/(snack|protein bar|trail mix|popcorn|nuts|apple slices|fruit cup)/i.test(t)) return 'snacks'
  if (/(lunch|salad|sandwich|wrap|bowl)/i.test(t)) return 'lunch'
  if (/(dinner|steak|curry|stir fry|chili|pasta|roast|salmon|chicken breast)/i.test(t)) return 'dinner'
  return 'uncategorized'
}

const normalizeMealCategory = (raw: any): MealCategory => {
  const v = String(raw || '').toLowerCase().trim()
  if (!v) return 'uncategorized'
  if (v.includes('breakfast')) return 'breakfast'
  if (v.includes('lunch')) return 'lunch'
  if (v.includes('dinner')) return 'dinner'
  if (v.includes('snack')) return 'snacks'
  if (v.includes('uncat') || v.includes('other')) return 'uncategorized'
  return 'uncategorized'
}

const toPositiveNumberOrNull = (raw: any) => {
  const n = Number(raw)
  return Number.isFinite(n) && n > 0 ? n : null
}

const normalizeIngredientToken = (raw: string) => {
  const value = String(raw || '')
    .replace(/^[\s•*\-–—]+/, '')
    .replace(/^\d+\.\s+/, '')
    .replace(/\s+/g, ' ')
    .trim()
  if (!value) return ''
  return value
}

const splitTitleIntoIngredients = (title: string) => {
  const cleaned = String(title || '')
    .replace(/\((.*?)\)/g, '')
    .replace(/\s+/g, ' ')
    .trim()
  if (!cleaned) return []
  const chunks = cleaned
    .split(/\s+\+\s+|\s+&\s+|\s+with\s+|,\s+(?=[a-z0-9])/i)
    .map((part) => normalizeIngredientToken(part))
    .filter(Boolean)
  const unique = Array.from(new Set(chunks.map((item) => item.toLowerCase()))).map((key) =>
    chunks.find((item) => item.toLowerCase() === key) || '',
  )
  return unique.filter(Boolean).slice(0, 12)
}

const isRecipeIngredientHeader = (line: string) =>
  /^(ingredients?|you(?:'|’)ll need|what you(?:'|’)ll need|shopping list)\b[:\-]?\s*$/i.test(
    String(line || '').trim(),
  )

const isRecipeStepHeader = (line: string) =>
  /^(instructions?|directions?|method|steps?|how to (make|cook|prepare))\b[:\-]?\s*$/i.test(
    String(line || '').trim(),
  )

const cleanRecipeTitle = (line: string) =>
  String(line || '')
    .replace(/^recipe[:\-]?\s*/i, '')
    .replace(/^here(?:'|’)s\s+(?:a|the)\s+/i, '')
    .replace(/[.!?]+$/, '')
    .trim()

const isRecipeSignalLine = (line: string) => {
  const normalized = String(line || '').toLowerCase()
  if (!normalized) return false
  return (
    normalized.includes('ingredient') ||
    normalized.includes('instruction') ||
    normalized.includes('directions') ||
    normalized.includes('method') ||
    normalized.includes('step') ||
    normalized.includes('cook') ||
    normalized.includes('serve') ||
    normalized.includes('stir') ||
    normalized.includes('simmer') ||
    normalized.includes('bake') ||
    normalized.includes('saute')
  )
}

const clampServingCount = (value: number) => {
  if (!Number.isFinite(value)) return 1
  return Math.max(1, Math.min(12, Math.round(value)))
}

const parseServingCountFromText = (text: string): number | null => {
  const raw = String(text || '')
  if (!raw) return null

  const rangeMatch =
    raw.match(/\b(?:serves?|servings?)\s*[:\-]?\s*(\d+(?:\.\d+)?)\s*(?:to|-)\s*(\d+(?:\.\d+)?)/i) ||
    raw.match(/\b(\d+(?:\.\d+)?)\s*(?:to|-)\s*(\d+(?:\.\d+)?)\s*servings?\b/i)
  if (rangeMatch) {
    const first = Number(rangeMatch[1])
    const second = Number(rangeMatch[2])
    if (Number.isFinite(first) && Number.isFinite(second) && first > 0 && second > 0) {
      return clampServingCount((first + second) / 2)
    }
  }

  const singleMatch =
    raw.match(/\b(?:serves?|servings?)\s*[:\-]?\s*(\d+(?:\.\d+)?)/i) ||
    raw.match(/\bfor\s+(\d+(?:\.\d+)?)\s+(?:people|servings?)\b/i) ||
    raw.match(/\b(\d+(?:\.\d+)?)\s+servings?\b/i)
  if (!singleMatch) return null
  const value = Number(singleMatch[1])
  if (!Number.isFinite(value) || value <= 0) return null
  return clampServingCount(value)
}

const parseApproxRecipeCaloriesFromText = (text: string): number | null => {
  const match = String(text || '').match(/(-?\d+(?:\.\d+)?)\s*kcal\b/i)
  if (!match) return null
  const value = Number(match[1])
  if (!Number.isFinite(value) || value <= 0) return null
  return value
}

