const resolveRecipeServingCount = (params: {
  text: string
  title: string
  ingredientsCount: number
  seed?: number | null
}) => {
  const text = String(params.text || '')
  const title = String(params.title || '')
  const context = `${title}\n${text}`
  const explicit = parseServingCountFromText(text) || parseServingCountFromText(title)
  if (explicit) return explicit
  if (/\b(single serve|single-serving|for one|one serving)\b/i.test(context)) return 1

  let estimate =
    Number.isFinite(Number(params.seed)) && Number(params.seed) > 0 ? clampServingCount(Number(params.seed)) : 1

  const calories = parseApproxRecipeCaloriesFromText(text)
  if (calories !== null) {
    if (calories >= 2200) estimate = Math.max(estimate, 4)
    else if (calories >= 1500) estimate = Math.max(estimate, 3)
    else if (calories >= 900) estimate = Math.max(estimate, 2)
  }

  const count = Number(params.ingredientsCount)
  if (Number.isFinite(count) && count > 0) {
    if (count >= 10) estimate = Math.max(estimate, 4)
    else if (count >= 7) estimate = Math.max(estimate, 3)
    else if (count >= 4) estimate = Math.max(estimate, 2)
  }

  if (estimate < 2 && /\b(pasta|alfredo|curry|stir fry|soup|chili|salad|roast|casserole)\b/i.test(context)) {
    estimate = 2
  }

  return clampServingCount(estimate)
}

const parseSingleRecipeOptionFromText = (text: string): ParsedFoodOption | null => {
  const lines = String(text || '')
    .replace(/\r/g, '')
    .split('\n')
    .map((line) => stripOuterBold(line).trim())
    .filter(Boolean)
  if (lines.length === 0) return null

  const hasRecipeSignal = lines.some((line) => isRecipeSignalLine(line))
  if (!hasRecipeSignal) return null

  let inferredTitle = ''
  for (const line of lines) {
    if (isRecipeIngredientHeader(line) || isRecipeStepHeader(line)) break
    if (/^(current totals|targets|macros|after eating|servings?|serves|option\s+\d+):/i.test(line)) continue
    if (/^\d+[.)]\s+/.test(line)) continue
    if (/^[-•*]\s+/.test(line)) continue
    if (line.length < 4) continue
    inferredTitle = cleanRecipeTitle(line)
    break
  }

  const ingredients: string[] = []
  const steps: string[] = []
  let inIngredients = false
  let inSteps = false
  let sawNumberedStep = false

  for (const rawLine of lines) {
    const line = String(rawLine || '').trim()
    if (!line) continue
    if (isRecipeIngredientHeader(line)) {
      inIngredients = true
      inSteps = false
      continue
    }
    if (isRecipeStepHeader(line)) {
      inSteps = true
      inIngredients = false
      continue
    }

    const numbered = line.match(/^(\d+)[.)]\s+(.+)$/)
    if (numbered) {
      sawNumberedStep = true
      inSteps = true
      inIngredients = false
      const stepLine = normalizeIngredientToken(numbered[2])
      if (stepLine) steps.push(stepLine)
      continue
    }

    const bullet = line.match(/^[-•*]\s+(.+)$/)
    if (bullet) {
      const bulletLine = normalizeIngredientToken(bullet[1])
      if (!bulletLine) continue
      if (inSteps) {
        steps.push(bulletLine)
      } else if (inIngredients || !sawNumberedStep) {
        ingredients.push(bulletLine)
      }
      continue
    }

    if (inIngredients) {
      ingredients.push(normalizeIngredientToken(line))
      continue
    }
    if (inSteps) {
      steps.push(normalizeIngredientToken(line))
    }
  }

  const uniqueIngredients = Array.from(new Set(ingredients.map((line) => line.toLowerCase())))
    .map((key) => ingredients.find((line) => line.toLowerCase() === key) || '')
    .filter(Boolean)
    .slice(0, 60)
  const cleanSteps = steps.map((line) => normalizeIngredientToken(line)).filter(Boolean).slice(0, 30)

  if (uniqueIngredients.length < 2 || cleanSteps.length < 2) return null

  const title = inferredTitle || 'Custom meal recipe'
  const servings = resolveRecipeServingCount({
    text,
    title,
    ingredientsCount: uniqueIngredients.length,
  })
  return {
    key: `option-1-${title.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`,
    index: 1,
    title,
    ingredients: uniqueIngredients,
    steps: cleanSteps,
    category: inferCategoryFromMealTitle(title),
    servings,
    prepMinutes: null,
    cookMinutes: null,
  }
}

const EMPTY_FOOD_MACROS: FoodMacroValues = {
  calories: null,
  protein: null,
  carbs: null,
  fat: null,
  fiber: null,
  sugar: null,
}

const hasAnyFoodMacroValues = (values: FoodMacroValues | null) =>
  Boolean(
    values &&
      (values.calories != null ||
        values.protein != null ||
        values.carbs != null ||
        values.fat != null ||
        values.fiber != null ||
        values.sugar != null),
  )

const parseFoodMacroValuesFromText = (line: string): FoodMacroValues => {
  const text = String(line || '')
  const pick = (regex: RegExp) => {
    const match = text.match(regex)
    if (!match) return null
    const value = Number(match[1])
    return Number.isFinite(value) ? value : null
  }
  return {
    calories: pick(/(-?\d+(?:\.\d+)?)\s*kcal/i),
    protein: pick(/(-?\d+(?:\.\d+)?)\s*g\s*protein/i),
    carbs: pick(/(-?\d+(?:\.\d+)?)\s*g\s*carbs?/i),
    fat: pick(/(-?\d+(?:\.\d+)?)\s*g\s*fat/i),
    fiber: pick(/(-?\d+(?:\.\d+)?)\s*g\s*(?:fiber|fibre)/i),
    sugar: pick(/(-?\d+(?:\.\d+)?)\s*g\s*sugar/i),
  }
}

const mergeFoodMacroValues = (base: FoodMacroValues | null, patch: FoodMacroValues): FoodMacroValues | null => {
  if (!hasAnyFoodMacroValues(patch)) return base
  const seed = base || EMPTY_FOOD_MACROS
  return {
    calories: patch.calories ?? seed.calories,
    protein: patch.protein ?? seed.protein,
    carbs: patch.carbs ?? seed.carbs,
    fat: patch.fat ?? seed.fat,
    fiber: patch.fiber ?? seed.fiber,
    sugar: patch.sugar ?? seed.sugar,
  }
}

const parseFoodMacroSnapshot = (content: string): FoodMacroSnapshot | null => {
  const lines = String(content || '')
    .replace(/\r/g, '')
    .split('\n')
    .map((line) => stripOuterBold(line).trim())
    .filter(Boolean)

  let current: FoodMacroValues | null = null
  let targets: FoodMacroValues | null = null
  let after: FoodMacroValues | null = null
  let active: 'current' | 'targets' | 'after' | null = null

  for (const rawLine of lines) {
    const line = rawLine.replace(/^[•*\-]\s+/, '').trim()
    if (!line) continue

    const currentHeader = line.match(/^Current totals:\s*(.*)$/i)
    if (currentHeader) {
      current = mergeFoodMacroValues(current, parseFoodMacroValuesFromText(currentHeader[1] || ''))
      active = 'current'
      continue
    }

    const targetsHeader = line.match(/^Targets:\s*(.*)$/i)
    if (targetsHeader) {
      targets = mergeFoodMacroValues(targets, parseFoodMacroValuesFromText(targetsHeader[1] || ''))
      active = 'targets'
      continue
    }

    const afterHeader = line.match(/^After eating:\s*(.*)$/i)
    if (afterHeader) {
      after = mergeFoodMacroValues(after, parseFoodMacroValuesFromText(afterHeader[1] || ''))
      active = 'after'
      continue
    }

    if (/^(option\s+\d+:|recipe:|ingredients?:|steps?:|macros:)/i.test(line)) {
      active = null
      continue
    }

    if (active) {
      const parsed = parseFoodMacroValuesFromText(line)
      if (active === 'current') current = mergeFoodMacroValues(current, parsed)
      if (active === 'targets') targets = mergeFoodMacroValues(targets, parsed)
      if (active === 'after') after = mergeFoodMacroValues(after, parsed)
    }
  }

  if (!hasAnyFoodMacroValues(targets)) return null
  if (!hasAnyFoodMacroValues(current) && !hasAnyFoodMacroValues(after)) return null

  return { current, targets, after }
}

const stripFoodMacroSummaryFromDisplay = (content: string): string => {
  const lines = String(content || '').replace(/\r/g, '').split('\n')
  const keptLines: string[] = []
  let inMacroBlock = false

  for (const rawLine of lines) {
    const line = String(rawLine || '')
    const trimmed = stripOuterBold(line).trim()
    if (!trimmed) {
      if (!inMacroBlock) keptLines.push(line)
      continue
    }

    const normalized = trimmed.replace(/^[•*\-]\s+/, '').trim()
    const isMacroHeader = /^(current totals|targets|after eating|macros(?:\s*\([^)]+\))?|consumed|remaining)\s*:/i.test(
      normalized,
    )
    const isBoundary = /^(option\s+\d+:|recipe:|ingredients?:|steps?:|directions?:|method:|servings?:|serves\b)/i.test(
      normalized,
    )
    const isMacroLine = hasAnyFoodMacroValues(parseFoodMacroValuesFromText(normalized))

    if (isMacroHeader) {
      inMacroBlock = true
      continue
    }

    if (inMacroBlock) {
      if (isBoundary) {
        inMacroBlock = false
        keptLines.push(line)
        continue
      }
      if (isMacroLine) continue
      inMacroBlock = false
      keptLines.push(line)
      continue
    }

    keptLines.push(line)
  }

  return keptLines.join('\n').replace(/\n{3,}/g, '\n\n').trim()
}

const parseQuotedStringArray = (raw: string) => {
  const out: string[] = []
  const rx = /"((?:\\.|[^"\\])*)"/g
  let match: RegExpExecArray | null = null
  while ((match = rx.exec(String(raw || '')))) {
    try {
      out.push(String(JSON.parse(`"${match[1]}"`) || '').trim())
    } catch {
      out.push(String(match[1] || '').trim())
    }
  }
  return out.filter(Boolean)
}

const safeParseJson = (raw: string) => {
  const cleaned = String(raw || '')
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim()
  if (!cleaned) return null
  const tryParse = (value: string) => {
    try {
      return JSON.parse(value)
    } catch {
      return null
    }
  }
  const direct = tryParse(cleaned)
  if (direct) return direct
  const noTrailingCommas = cleaned.replace(/,\s*([}\]])/g, '$1')
  const retry = tryParse(noTrailingCommas)
  if (retry) return retry
  const firstBrace = cleaned.indexOf('{')
  if (firstBrace >= 0) {
    let depth = 0
    for (let i = firstBrace; i < cleaned.length; i += 1) {
      const ch = cleaned[i]
      if (ch === '{') depth += 1
      if (ch === '}') depth -= 1
      if (depth === 0) {
        const candidate = cleaned.slice(firstBrace, i + 1)
        const extracted = tryParse(candidate)
        if (extracted) return extracted
        break
      }
    }
  }
  return null
}
const parseStructuredFoodOptions = (raw: any): ParsedFoodOption[] => {
  const source = Array.isArray(raw) ? raw : Array.isArray(raw?.options) ? raw.options : []
  return source
    .map((entry: any, idx: number) => {
      const title = String(entry?.title || entry?.mealName || '').trim()
      if (!title) return null
      const indexRaw = Number(entry?.optionNumber ?? entry?.index ?? idx + 1)
      const index = Number.isFinite(indexRaw) && indexRaw > 0 ? Math.round(indexRaw) : idx + 1
      const ingredients = Array.isArray(entry?.ingredients)
        ? entry.ingredients.map((line: any) => normalizeIngredientToken(String(line || ''))).filter(Boolean).slice(0, 60)
        : []
      const steps = Array.isArray(entry?.steps)
        ? entry.steps.map((line: any) => normalizeIngredientToken(String(line || ''))).filter(Boolean).slice(0, 30)
        : []
      return {
        key: `option-${index}-${title.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`,
        index,
        title,
        ingredients: ingredients.length > 0 ? ingredients : splitTitleIntoIngredients(title),
        steps: steps.length > 0 ? steps : [`Assemble ${title}.`],
        category: normalizeMealCategory(entry?.category || inferCategoryFromMealTitle(title)),
        servings: toPositiveNumberOrNull(entry?.servings),
        prepMinutes: toPositiveNumberOrNull(entry?.prepMinutes),
        cookMinutes: toPositiveNumberOrNull(entry?.cookMinutes),
      } as ParsedFoodOption
    })
    .filter((entry: ParsedFoodOption | null): entry is ParsedFoodOption => Boolean(entry))
}

const parseLooseStructuredFoodOptions = (raw: string): ParsedFoodOption[] => {
  const options: ParsedFoodOption[] = []
  const text = String(raw || '').replace(/\r/g, '')
  const rx =
    /"optionNumber"\s*:\s*(\d+)[\s\S]*?"title"\s*:\s*"([^"]+)"[\s\S]*?"category"\s*:\s*"([^"]*)"[\s\S]*?"servings"\s*:\s*(null|-?\d+(?:\.\d+)?)?[\s\S]*?"prepMinutes"\s*:\s*(null|-?\d+(?:\.\d+)?)?[\s\S]*?"cookMinutes"\s*:\s*(null|-?\d+(?:\.\d+)?)?[\s\S]*?"ingredients"\s*:\s*\[([\s\S]*?)\][\s\S]*?"steps"\s*:\s*\[([\s\S]*?)\]/gi
  let match: RegExpExecArray | null = null
  while ((match = rx.exec(text))) {
    const indexRaw = Number(match[1])
    const title = String(match[2] || '').trim()
    if (!title) continue
    const ingredients = parseQuotedStringArray(match[7]).map((line) => normalizeIngredientToken(line)).filter(Boolean)
    const steps = parseQuotedStringArray(match[8]).map((line) => normalizeIngredientToken(line)).filter(Boolean)
    options.push({
      key: `option-${indexRaw}-${title.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`,
      index: Number.isFinite(indexRaw) && indexRaw > 0 ? Math.round(indexRaw) : options.length + 1,
      title,
      ingredients: ingredients.length > 0 ? ingredients : splitTitleIntoIngredients(title),
      steps: steps.length > 0 ? steps : [`Assemble ${title}.`],
      category: normalizeMealCategory(match[3]),
      servings: toPositiveNumberOrNull(match[4]),
      prepMinutes: toPositiveNumberOrNull(match[5]),
      cookMinutes: toPositiveNumberOrNull(match[6]),
    })
  }
  return options
}
// PROTECTED: FOOD_CHAT_PARSE_AND_FALLBACK START
const parseFoodAssistantResponse = (
  content: string,
): { displayContent: string; options: ParsedFoodOption[] } => {
  const raw = String(content || '')
  const start = raw.indexOf(MEAL_OPTIONS_JSON_START)
  const end = start >= 0 ? raw.indexOf(MEAL_OPTIONS_JSON_END, start + MEAL_OPTIONS_JSON_START.length) : -1
  let displayContent = raw
  let structuredOptions: ParsedFoodOption[] = []

  if (start >= 0) {
    const hasEndMarker = end > start
    const before = raw.slice(0, start).trimEnd()
    const after = hasEndMarker ? raw.slice(end + MEAL_OPTIONS_JSON_END.length).trimStart() : ''
    displayContent = `${before}${before && after ? '\n\n' : ''}${after}`.trim()
    const jsonRaw = raw
      .slice(start + MEAL_OPTIONS_JSON_START.length, hasEndMarker ? end : raw.length)
      .trim()
    if (jsonRaw) {
      structuredOptions = parseStructuredFoodOptions(safeParseJson(jsonRaw))
      if (structuredOptions.length === 0) {
        structuredOptions = parseLooseStructuredFoodOptions(jsonRaw)
      }
    }
  }

  displayContent = displayContent
    .replaceAll(MEAL_OPTIONS_JSON_START, '')
    .replaceAll(MEAL_OPTIONS_JSON_END, '')
    .trim()
  if (structuredOptions.length === 1) {
    const option = structuredOptions[0]
    const resolvedServings = resolveRecipeServingCount({
      text: displayContent,
      title: option.title,
      ingredientsCount: option.ingredients.length,
      seed: option.servings,
    })
    structuredOptions = [{ ...option, servings: resolvedServings }]
  }
  if (structuredOptions.length > 0) {
    return { displayContent, options: structuredOptions }
  }

  const lines = displayContent
    .split('\n')
    .map((line) => stripOuterBold(line).trim())
    .filter(Boolean)

  const options: Array<{ index: number; title: string; detailLines: string[] }> = []
  let current: { index: number; title: string; detailLines: string[] } | null = null

  for (const line of lines) {
    const optionMatch = line.match(/^Option\s+(\d+):\s*(.+)$/i)
    if (optionMatch) {
      if (current) options.push(current)
      current = {
        index: Number(optionMatch[1]),
        title: String(optionMatch[2] || '').trim(),
        detailLines: [],
      }
      continue
    }
    if (current) current.detailLines.push(line)
  }
  if (current) options.push(current)

  const fallbackOptions = options
    .map((opt) => {
      const nonMacroLines = opt.detailLines.filter((line) => !/^(Macros|After eating)\s*:/i.test(line))
      const bulletIngredients = nonMacroLines
        .map((line) => {
          const bullet = line.match(/^[-•*]\s+(.+)$/)
          return bullet ? normalizeIngredientToken(bullet[1]) : ''
        })
        .filter(Boolean)
      const titleIngredients = splitTitleIntoIngredients(opt.title)
      const ingredients = bulletIngredients.length > 0 ? bulletIngredients.slice(0, 20) : titleIngredients
      const steps = nonMacroLines
        .map((line) => {
          const numbered = line.match(/^\d+\.\s+(.+)$/)
          return numbered ? normalizeIngredientToken(numbered[1]) : ''
        })
        .filter(Boolean)
      return {
        key: `option-${opt.index}-${String(opt.title || '').toLowerCase().replace(/[^a-z0-9]+/g, '-')}`,
        index: opt.index,
        title: opt.title,
        ingredients,
        steps: steps.length > 0 ? steps : [`Assemble ${opt.title}.`],
        category: inferCategoryFromMealTitle(opt.title),
        servings: 1,
        prepMinutes: null,
        cookMinutes: null,
      }
    })
    .filter((opt) => opt.title.length > 0)

  if (fallbackOptions.length > 0) {
    return { displayContent, options: fallbackOptions }
  }

  const singleRecipeOption = parseSingleRecipeOptionFromText(displayContent)
  if (singleRecipeOption) {
    return { displayContent, options: [singleRecipeOption] }
  }

  return { displayContent, options: [] }
}
