                  <span className="font-semibold text-gray-800">{Math.round(percent)}%</span>
                </div>
                <div className="mt-1 h-3 w-full rounded-full bg-gray-200">
                  <div className={`h-3 rounded-full ${row.bar}`} style={{ width: `${percent}%` }} />
                </div>
