import React, { useEffect, useMemo, useState } from 'react'
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Tooltip,
  Legend,
  TimeScale,
} from 'chart.js'
import 'chartjs-adapter-date-fns'
import { Line } from 'react-chartjs-2'

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Tooltip, Legend, TimeScale)

type SeriesResponse = {
  success: boolean
  range: { start: string; end: string }
  series: {
    steps: Array<{ date: string; steps?: number }>
    heartrate: Array<{ date: string; restingHeartRate?: number }>
    sleep: Array<{ date: string; minutes?: number }>
    weight: Array<{ date: string; weightKg?: number }>
  }
}

function toDataset(
  xs: string[],
  ys: (number | undefined)[],
  color: string,
  label: string
) {
  return {
    labels: xs,
    datasets: [
      {
        label,
        data: ys.map((v) => (typeof v === 'number' ? v : null)),
        fill: false,
        borderColor: color,
        backgroundColor: color,
        tension: 0.25,
        spanGaps: true,
      },
    ],
  }
}

const baseOptions = {
  responsive: true,
  maintainAspectRatio: false,
  interaction: { mode: 'index' as const, intersect: false },
  plugins: { legend: { display: false } },
  scales: {
    x: { type: 'time' as const, time: { unit: 'day' as const } },
    y: { beginAtZero: true },
  },
}

export default function FitbitCharts({ rangeDays = 30 }: { rangeDays?: number }) {
  const [data, setData] = useState<SeriesResponse | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true)
      setError(null)
      try {
        const end = new Date()
        const start = new Date()
        start.setDate(end.getDate() - (rangeDays - 1))
        const startStr = start.toISOString().slice(0, 10)
        const endStr = end.toISOString().slice(0, 10)
        const res = await fetch(`/api/fitbit/data?start=${startStr}&end=${endStr}`)
        if (!res.ok) throw new Error('Failed to load Fitbit data')
        setData((await res.json()) as SeriesResponse)
      } catch (e: any) {
        setError(e?.message || 'Failed to load data')
      } finally {
        setLoading(false)
      }
    }
    fetchData()
  }, [rangeDays])

  const xs = useMemo(() => (data ? data.series.steps.map((s) => s.date) : []), [data])
  const steps = useMemo(() => (data ? data.series.steps.map((s) => s.steps ?? undefined) : []), [data])
  const rhr = useMemo(
    () => (data ? data.series.heartrate.map((s) => s.restingHeartRate ?? undefined) : []),
    [data]
  )
  const sleepMin = useMemo(
    () => (data ? data.series.sleep.map((s) => s.minutes ?? undefined) : []),
    [data]
  )
  const weightKg = useMemo(
    () => (data ? data.series.weight.map((s) => s.weightKg ?? undefined) : []),
    [data]
  )

  if (loading) {
    return <div className="h-64 rounded-xl border bg-white animate-pulse" />
  }
  if (error) {
    return (
      <div className="p-4 rounded-xl border bg-red-50 border-red-200 text-red-700 text-sm">
        {error}
      </div>
    )
  }
  if (!data) return null

  // Check if we have any data at all
  const hasData = data.series.steps.some(s => s.steps != null) ||
                  data.series.heartrate.some(h => h.restingHeartRate != null) ||
                  data.series.sleep.some(s => s.minutes != null) ||
                  data.series.weight.some(w => w.weightKg != null)

  if (!hasData) {
    return (
      <div className="p-4 rounded-xl border bg-gray-50 border-gray-200 text-gray-600 text-sm">
        No Fitbit data available yet. Connect your Fitbit and sync data, or load demo data to see charts.
      </div>
    )
  }

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      <div className="p-4 rounded-xl border bg-white h-72">
        <div className="text-sm text-gray-600 mb-2">Steps per day</div>
        <Line data={toDataset(xs, steps, '#10b981', 'Steps')} options={baseOptions as any} />
      </div>

      <div className="p-4 rounded-xl border bg-white h-72">
        <div className="text-sm text-gray-600 mb-2">Resting heart rate</div>
        <Line data={toDataset(xs, rhr, '#3b82f6', 'Resting HR')} options={baseOptions as any} />
      </div>

      <div className="p-4 rounded-xl border bg-white h-72">
        <div className="text-sm text-gray-600 mb-2">Sleep minutes</div>
        <Line data={toDataset(xs, sleepMin, '#a855f7', 'Sleep (min)')} options={baseOptions as any} />
      </div>

      <div className="p-4 rounded-xl border bg-white h-72">
        <div className="text-sm text-gray-600 mb-2">Weight (kg)</div>
        <Line data={toDataset(xs, weightKg, '#f59e0b', 'Weight')} options={baseOptions as any} />
      </div>
    </div>
  )
}

'use client'

import React, { useEffect, useMemo, useState } from 'react'

type FitbitSeries = {
  success: boolean
  range: { start: string; end: string }
  series: {
    steps: Array<{ date: string; steps?: number }>
    sleep: Array<{ date: string; minutes?: number }>
  }
}

type CheckinRow = { date: string; issueId: string; name: string; polarity: 'positive' | 'negative'; value: number | null; note?: string }
type CheckinHistory = { history: CheckinRow[] }
type MoodEntry = { localDate: string; mood: number }
type MoodHistory = { entries: MoodEntry[] }

function pearson(x: number[], y: number[]): number | null {
  const n = Math.min(x.length, y.length)
  if (n < 3) return null
  let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0, sumYY = 0, k = 0
  for (let i = 0; i < n; i++) {
    const xi = x[i]
    const yi = y[i]
    if (xi == null || yi == null || isNaN(xi) || isNaN(yi)) continue
    k++
    sumX += xi
    sumY += yi
    sumXY += xi * yi
    sumXX += xi * xi
    sumYY += yi * yi
  }
  if (k < 3) return null
  const cov = sumXY - (sumX * sumY) / k
  const varX = sumXX - (sumX * sumX) / k
  const varY = sumYY - (sumY * sumY) / k
  if (varX <= 0 || varY <= 0) return null
  return cov / Math.sqrt(varX * varY)
}

function strengthLabel(r: number | null): string {
  if (r == null) return 'No correlation'
  const a = Math.abs(r)
  if (a >= 0.7) return `Strong (${r.toFixed(2)})`
  if (a >= 0.4) return `Moderate (${r.toFixed(2)})`
  if (a >= 0.2) return `Weak (${r.toFixed(2)})`
  return `Very weak (${r.toFixed(2)})`
}

export default function FitbitCorrelations({ rangeDays = 30 }: { rangeDays?: number }) {
  const [fitbit, setFitbit] = useState<FitbitSeries | null>(null)
  const [checkins, setCheckins] = useState<CheckinHistory | null>(null)
  const [mood, setMood] = useState<MoodHistory | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    const load = async () => {
      setLoading(true)
      setError(null)
      try {
        // Fitbit
        const end = new Date()
        const start = new Date()
        start.setDate(end.getDate() - (rangeDays - 1))
        const startStr = start.toISOString().slice(0, 10)
        const endStr = end.toISOString().slice(0, 10)
        const fbRes = await fetch(`/api/fitbit/data?start=${startStr}&end=${endStr}&dataTypes=steps,sleep`)
        if (!fbRes.ok) throw new Error('Failed to load Fitbit data')
        setFitbit((await fbRes.json()) as FitbitSeries)
        // Mood (preferred)
        const moodRes = await fetch(`/api/mood/entries?start=${startStr}&end=${endStr}`)
        if (moodRes.ok) setMood((await moodRes.json()) as MoodHistory)
        // Checkins (optional)
        try {
          const ciRes = await fetch(`/api/checkins/history?start=${startStr}&end=${endStr}`)
          if (ciRes.ok) setCheckins((await ciRes.json()) as CheckinHistory)
        } catch (e) {
          console.warn('Check-ins history unavailable:', e)
        }
      } catch (e: any) {
        setError(e?.message || 'Failed to load correlations')
      } finally {
        setLoading(false)
      }
    }
    load()
  }, [rangeDays])

  const dailyMood = useMemo(() => {
    const map = new Map<string, number[]>()
    const moodEntries = (mood as any)?.entries
    if (Array.isArray(moodEntries) && moodEntries.length > 0) {
      for (const row of moodEntries as MoodEntry[]) {
        const d = String(row.localDate || '').slice(0, 10)
        const v = Number(row.mood)
        if (!d || !Number.isFinite(v)) continue
        // Align to 0..6 range used elsewhere.
        const scaled = Math.max(0, Math.min(6, v - 1))
        if (!map.has(d)) map.set(d, [])
        map.get(d)!.push(scaled)
      }
    } else if (checkins?.history) {
      for (const row of checkins.history) {
        const d = row.date.slice(0, 10)
        const v = row.value ?? 0
        if (!map.has(d)) map.set(d, [])
        map.get(d)!.push(v)
      }
    }
    const avg = new Map<string, number>()
    map.forEach((arr, d) => {
      const mean = arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : 0
      avg.set(d, mean)
    })
    return avg
  }, [checkins, mood])

  const series = useMemo(() => {
    if (!fitbit) return null
    const steps = fitbit.series.steps.map((s) => s.steps ?? 0)
    const sleepHrs = fitbit.series.sleep.map((s) => (s.minutes ?? 0) / 60)
    const xs = fitbit.series.steps.map((s) => s.date)
    const mood = xs.map((d) => dailyMood.get(d) ?? null)
    const stepsMood = pearson(steps, mood.map((v) => (v == null ? NaN : v)) as number[])
    const sleepMood = pearson(sleepHrs, mood.map((v) => (v == null ? NaN : v)) as number[])

    // Find low-sleep + low-mood days
    const flagged: Array<{ date: string; sleepHrs: number; mood: number | null }> = []
    xs.forEach((d, i) => {
      const sh = sleepHrs[i]
      const m = mood[i]
      if (sh > 0 && sh < 6 && (m == null || m < 3)) {
        flagged.push({ date: d, sleepHrs: sh, mood: m })
      }
    })

    return {
      stepsMood,
      sleepMood,
      flagged: flagged.slice(0, 5),
    }
  }, [fitbit, dailyMood])

  if (loading) {
    return <div className="rounded-xl border bg-white p-4 animate-pulse h-40" />
  }
  if (error) {
    return (
      <div className="p-4 rounded-xl border bg-red-50 border-red-200 text-red-700 text-sm">
        {error}
      </div>
    )
  }
  if (!fitbit || !series) return null

  // Check if we have any Fitbit data
  const hasFitbitData = fitbit.series.steps.some(s => s.steps != null) ||
                        fitbit.series.sleep.some(s => s.minutes != null)

  if (!hasFitbitData) {
    return (
      <div className="p-4 rounded-xl border bg-gray-50 border-gray-200 text-gray-600 text-sm">
        No Fitbit data available yet. Connect your Fitbit and sync data, or load demo data to see correlations.
      </div>
    )
  }

  return (
    <div className="rounded-xl border bg-white p-4">
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-3">
        <div>
          <div className="text-sm text-gray-500">Correlations (last {rangeDays} days)</div>
          <div className="text-lg font-semibold text-gray-900">How your activity and sleep relate to mood</div>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mt-4">
        <div className="p-4 rounded-lg border">
          <div className="text-sm text-gray-500">Steps ↔︎ Mood</div>
          <div className="text-xl font-semibold mt-1">{strengthLabel(series.stepsMood)}</div>
          <p className="text-xs text-gray-500 mt-1">Correlation uses daily steps and your daily mood check-ins (or check-in ratings if mood is empty).</p>
        </div>
        <div className="p-4 rounded-lg border">
          <div className="text-sm text-gray-500">Sleep ↔︎ Mood</div>
          <div className="text-xl font-semibold mt-1">{strengthLabel(series.sleepMood)}</div>
          <p className="text-xs text-gray-500 mt-1">Correlation uses total sleep hours per night vs. your daily mood check-ins.</p>
        </div>
      </div>

      {series.flagged.length > 0 && (
        <div className="mt-4">
          <div className="text-sm text-gray-600 mb-2">Recent low sleep + low mood days</div>
          <div className="rounded-lg border overflow-hidden">
            <table className="min-w-full text-sm">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-3 py-2 text-left text-gray-600 font-medium">Date</th>
                  <th className="px-3 py-2 text-left text-gray-600 font-medium">Sleep</th>
                  <th className="px-3 py-2 text-left text-gray-600 font-medium">Avg Mood</th>
                </tr>
              </thead>
              <tbody>
                {series.flagged.map((row) => (
                  <tr key={row.date} className="border-t">
                    <td className="px-3 py-2">{row.date}</td>
                    <td className="px-3 py-2">{row.sleepHrs.toFixed(1)} h</td>
                    <td className="px-3 py-2">{row.mood == null ? 'N/A' : row.mood.toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  )
}

