}

export default function FitbitSummary({ rangeDays = 7 }: { rangeDays?: number }) {
  const [data, setData] = useState<SeriesResponse | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true)
      setError(null)
      try {
        const end = new Date()
        const start = new Date()
        start.setDate(end.getDate() - (rangeDays - 1))
        const startStr = start.toISOString().slice(0, 10)
        const endStr = end.toISOString().slice(0, 10)
        const res = await fetch(`/api/fitbit/data?start=${startStr}&end=${endStr}`)
        if (!res.ok) throw new Error('Failed to load Fitbit data')
        const json = (await res.json()) as SeriesResponse
        setData(json)
      } catch (e: any) {
        setError(e?.message || 'Failed to load data')
      } finally {
        setLoading(false)
      }
    }
    fetchData()
  }, [rangeDays])

  const today = useMemo(() => {
    if (!data) return null
    const lastIdx = data.series.steps.length - 1
    return {
      steps: data.series.steps[lastIdx]?.steps,
      calories: data.series.steps[lastIdx]?.calories,
      distanceKm: data.series.steps[lastIdx]?.distanceKm,
      rhr: data.series.heartrate[data.series.heartrate.length - 1]?.restingHeartRate,
