function toDataset(xs: string[], ys: (number | undefined)[], color: string, label: string) {
  return {
    labels: xs,
    datasets: [
      {
        label,
        data: ys.map((v) => (typeof v === 'number' ? v : null)),
        fill: false,
        borderColor: color,
        backgroundColor: color,
        tension: 0.25,
        spanGaps: true,
      },
    ],
  }
}

