'use client'

import { useMemo, useState } from 'react'

type MacroTotals = {
  calories: number | null
  protein_g: number | null
  carbs_g: number | null
  fat_g: number | null
  fiber_g: number | null
  sugar_g: number | null
}

const safeNumber = (value: any) => {
  const num = Number(value)
  return Number.isFinite(num) ? num : 0
}

const kcalToKj = (kcal: number) => kcal * 4.184
const normalizeNearZero = (value: number) => (Math.abs(value) < 0.0001 ? 0 : value)
const formatMacroAmount = (value: number, unit?: string) => {
  const numeric = normalizeNearZero(value)
  const abs = Math.abs(numeric)
  let display = '0'
  if (abs > 0 && abs < 0.1) {
    display = (Math.round(numeric * 100) / 100).toFixed(2)
  } else if (abs >= 0.1 && abs < 1) {
    display = (Math.round(numeric * 10) / 10).toFixed(1)
  } else if (abs >= 1 && abs < 10) {
    display = String(Math.round(numeric * 10) / 10)
  } else if (abs >= 10) {
    display = String(Math.round(numeric))
  }
  return unit ? `${display} ${unit}` : display
}

export default function DailyMacroSummary({ targets, used }: { targets: MacroTotals; used: MacroTotals }) {
  const [energyUnit, setEnergyUnit] = useState<'kcal' | 'kJ'>('kcal')

  const rows = useMemo(() => {
    const macroRows = [
      { key: 'protein', label: 'Protein', consumed: safeNumber(used.protein_g), target: safeNumber(targets.protein_g), unit: 'g', color: '#ef4444', cap: false },
      { key: 'carbs', label: 'Carbs', consumed: safeNumber(used.carbs_g), target: safeNumber(targets.carbs_g), unit: 'g', color: '#22c55e', cap: false },
      { key: 'fat', label: 'Fat', consumed: safeNumber(used.fat_g), target: safeNumber(targets.fat_g), unit: 'g', color: '#6366f1', cap: false },
      { key: 'fibre', label: 'Fibre', consumed: safeNumber(used.fiber_g), target: safeNumber(targets.fiber_g), unit: 'g', color: '#12adc9', cap: false },
      { key: 'sugar', label: 'Sugar (max)', consumed: safeNumber(used.sugar_g), target: safeNumber(targets.sugar_g), unit: 'g', color: '#f97316', cap: true },
    ].filter((row) => row.target > 0)

    return macroRows
  }, [targets, used])

  const energy = useMemo(() => {
    const consumedKcal = safeNumber(used.calories)
    const targetKcal = safeNumber(targets.calories)
    if (targetKcal <= 0) return null
    const consumed = energyUnit === 'kJ' ? kcalToKj(consumedKcal) : consumedKcal
    const target = energyUnit === 'kJ' ? kcalToKj(targetKcal) : targetKcal
    const remaining = Math.max(0, target - consumed)
    const pctRaw = target > 0 ? consumed / target : 0
    const percentDisplay = target > 0 ? pctRaw * 100 : 0
    const over = percentDisplay > 100
    return {
      label: 'Calories',
      consumed,
      target,
      remaining,
      percentDisplay: Math.round(percentDisplay),
      percentExact: percentDisplay,
      over,
      unit: energyUnit,
      color: '#10b981',
    }
  }, [energyUnit, targets.calories, used.calories])

  return (
    <div className="bg-white border border-gray-200 rounded-2xl shadow-sm p-4">
      <div className="flex items-center justify-between mb-3">
        <div className="text-sm font-semibold text-gray-900">Today’s macro summary</div>
        <div className="inline-flex items-center text-[11px] sm:text-xs bg-gray-100 rounded-full p-0.5 border border-gray-200">
          <button
            type="button"
            onClick={() => setEnergyUnit('kcal')}
            className={`px-2 py-0.5 rounded-full ${energyUnit === 'kcal' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500'}`}
          >
            kcal
          </button>
          <button
            type="button"
            onClick={() => setEnergyUnit('kJ')}
            className={`px-2 py-0.5 rounded-full ${energyUnit === 'kJ' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500'}`}
          >
            kJ
          </button>
        </div>
      </div>

      <div className="space-y-3">
        {energy && (
          <div className="space-y-1">
            <div className="flex items-center justify-between text-sm">
              <div className="text-gray-900 font-semibold flex items-center gap-2">
                <span>{energy.label}</span>
                <span className="text-gray-700 font-normal">
                  {formatMacroAmount(energy.consumed)} / {formatMacroAmount(energy.target)} {energy.unit}
                </span>
                <span className="font-semibold" style={{ color: energy.over ? '#ef4444' : energy.color }}>
                  {formatMacroAmount(energy.remaining)} {energy.unit} left
                </span>
              </div>
              <div className={`text-xs font-semibold ${energy.over ? 'text-red-600' : 'text-gray-900'}`}>
                {energy.percentExact > 0 && energy.percentExact < 1 ? '<1%' : energy.percentDisplay > 0 ? `${energy.percentDisplay}%` : '0%'}
              </div>
            </div>
            <div className="h-2 w-full bg-gray-200 rounded-full overflow-hidden">
              <div
                className="h-2 rounded-full transition-all"
                style={{ width: `${Math.min(100, Math.max(0, energy.target > 0 ? (energy.consumed / energy.target) * 100 : 0))}%`, backgroundColor: energy.over ? '#ef4444' : energy.color }}
              />
            </div>
          </div>
        )}

        {rows.map((row) => {
          const pctRaw = row.target > 0 ? row.consumed / row.target : 0
          const pct = Math.max(0, pctRaw)
          const percentDisplay = row.target > 0 ? Math.round(pctRaw * 100) : 0
          const over = pctRaw * 100 > 100
          const remaining = Math.max(0, row.target - row.consumed)
          return (
            <div key={row.key} className="space-y-1">
              <div className="flex items-center justify-between text-sm">
                <div className="text-gray-900 font-semibold flex items-center gap-2">
                  <span>{row.label}</span>
                  <span className="text-gray-700 font-normal">
                    {formatMacroAmount(row.consumed)} / {formatMacroAmount(row.target)} {row.unit}
                    {row.cap ? ' cap' : ''}
                  </span>
                  <span className="font-semibold" style={{ color: over ? '#ef4444' : row.color }}>
                    {formatMacroAmount(remaining)} {row.unit} left
                  </span>
                </div>
                <div className={`text-xs font-semibold ${over ? 'text-red-600' : 'text-gray-900'}`}>
                  {pctRaw > 0 && pctRaw < 0.01 ? '<1%' : percentDisplay > 0 ? `${percentDisplay}%` : '0%'}
                </div>
              </div>
              <div className="h-2 w-full bg-gray-200 rounded-full overflow-hidden">
                <div
                  className="h-2 rounded-full transition-all"
                  style={{ width: `${Math.min(100, pct * 100)}%`, backgroundColor: over ? '#ef4444' : row.color }}
                />
              </div>
            </div>
          )
        })}

        {rows.length === 0 && (
          <div className="text-xs text-gray-500">Set daily targets in Health Setup to see macro progress.</div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useEffect, useMemo, useState } from 'react'

type MissingFoodReportProps = {
  defaultQuery?: string
  kind?: 'single' | 'packaged'
  country?: string
  source?: string
  className?: string
}

const toCountryLabel = (value: string) => {
  const v = String(value || '').trim().toUpperCase()
  if (!v) return 'Unknown'
  return v
}

export default function MissingFoodReport({
  defaultQuery,
  kind = 'single',
  country,
  source,
  className,
}: MissingFoodReportProps) {
  const [open, setOpen] = useState(false)
  const [name, setName] = useState('')
  const [brand, setBrand] = useState('')
  const [size, setSize] = useState('')
  const [notes, setNotes] = useState('')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [done, setDone] = useState(false)

  const resolvedCountry = useMemo(() => toCountryLabel(country || ''), [country])

  useEffect(() => {
    if (!open) return
    setError(null)
    setDone(false)
    const next = String(defaultQuery || '').trim()
    if (next) setName(next)
  }, [open, defaultQuery])

  const submit = async () => {
    const trimmed = name.trim()
    if (!trimmed) {
      setError('Please enter the item name.')
      return
    }
    setBusy(true)
    setError(null)
    try {
      const payload = {
        name: trimmed,
        brand: brand.trim() || null,
        chain: brand.trim() || null,
        size: size.trim() || null,
        notes: notes.trim() || null,
        kind,
        query: String(defaultQuery || '').trim() || null,
        country: resolvedCountry === 'Unknown' ? null : resolvedCountry,
        source: source || null,
      }
      const res = await fetch('/api/food-missing', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })
      if (!res.ok) {
        setError('Something went wrong. Please try again.')
        return
      }
      setDone(true)
      setBrand('')
      setSize('')
      setNotes('')
    } catch {
      setError('Something went wrong. Please try again.')
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className={className}>
      <button
        type="button"
        onClick={() => setOpen(true)}
        className="text-xs font-semibold text-emerald-700 hover:text-emerald-800"
      >
        Missing item? Tell us
      </button>

      {open && (
        <div className="fixed inset-0 z-[10000]">
          <div
            className="absolute inset-0 bg-black/40"
            onClick={() => setOpen(false)}
          />
          <div className="absolute inset-0 flex items-center justify-center px-4">
            <div className="w-full max-w-md rounded-2xl border border-gray-200 bg-white p-4 shadow-xl">
              <div className="flex items-center justify-between">
                <div className="text-sm font-semibold text-gray-900">Report missing item</div>
                <button
                  type="button"
                  onClick={() => setOpen(false)}
                  className="p-2 rounded-md hover:bg-gray-100"
                  aria-label="Close"
                >
                  ✕
                </button>
              </div>

              <div className="mt-3 space-y-3">
                <div className="text-xs text-gray-500">Country: {resolvedCountry}</div>

                <div>
                  <label className="text-xs font-semibold text-gray-700">Item name *</label>
                  <input
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    className="mt-1 w-full rounded-lg border border-gray-300 px-3 py-2 text-sm"
                    placeholder="e.g. Strawberry sundae"
                  />
                </div>

                <div>
                  <label className="text-xs font-semibold text-gray-700">Brand or chain</label>
                  <input
                    value={brand}
                    onChange={(e) => setBrand(e.target.value)}
                    className="mt-1 w-full rounded-lg border border-gray-300 px-3 py-2 text-sm"
                    placeholder="e.g. McDonald's"
                  />
                </div>

                <div>
                  <label className="text-xs font-semibold text-gray-700">Size (optional)</label>
                  <input
                    value={size}
                    onChange={(e) => setSize(e.target.value)}
                    className="mt-1 w-full rounded-lg border border-gray-300 px-3 py-2 text-sm"
                    placeholder="e.g. Small / Medium / Large"
                  />
                </div>

                <div>
                  <label className="text-xs font-semibold text-gray-700">Extra notes</label>
                  <textarea
                    value={notes}
                    onChange={(e) => setNotes(e.target.value)}
                    className="mt-1 w-full rounded-lg border border-gray-300 px-3 py-2 text-sm"
                    rows={3}
                    placeholder="Anything else that helps"
                  />
                </div>

                {error && <div className="text-xs text-red-600">{error}</div>}
                {done && <div className="text-xs text-emerald-700">Thanks. We have it.</div>}

                <div className="flex items-center justify-end gap-2">
                  <button
                    type="button"
                    onClick={() => setOpen(false)}
                    className="px-3 py-2 text-xs font-semibold text-gray-600"
                  >
                    Close
                  </button>
                  <button
                    type="button"
                    disabled={busy}
                    onClick={submit}
                    className="px-3 py-2 rounded-lg bg-emerald-600 text-white text-xs font-semibold hover:bg-emerald-700 disabled:opacity-60"
                  >
                    {busy ? 'Sending…' : 'Send'}
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useEffect, useMemo, useState } from 'react'
import NutrientCards from './NutrientCards'
import { roundOptionalNutrient, scaleOptionalNutrient } from '@/lib/food/nutrient-values'
import {
  convertItemMeasurement,
  formatItemMeasurementUnit,
  itemMeasurementUnitOptions,
  recordedServingBasis,
  type ItemMeasurementUnit,
} from '@/lib/food/serving-measurements'

type RecommendedItem = {
  name: string
  serving_size?: string | null
  calories?: number | null
  protein_g?: number | null
  carbs_g?: number | null
  fat_g?: number | null
  fiber_g?: number | null
  sugar_g?: number | null
  servings: number
}

type BuilderUnit = ItemMeasurementUnit
const clamp = (n: number, min: number, max: number) => Math.min(max, Math.max(min, n))
// Keep calculation precision in editable amounts; round only nutrient displays.
const formatDecimal = (value: number) => Number.isFinite(value) && value >= 0 ? String(value) : ''
const extractPieceGramsFromLabel = (label: string) => {
  const match = label.match(/\((\d+(?:\.\d+)?)\s*g\)/i)
  const grams = match ? Number(match[1]) : NaN
  return Number.isFinite(grams) && grams > 0 ? grams : null
}
const recommendedAmount = (item: RecommendedItem, servings: number, unit: BuilderUnit, pieceGrams: number | null, country: string) =>
  servings === 0 ? 0 : convertItemMeasurement(servings, 'serving', unit, item, pieceGrams, 1, { toCountry: country })
const recommendedServings = (item: RecommendedItem, amount: number, unit: BuilderUnit, pieceGrams: number | null, country: string) => {
  if (!Number.isFinite(amount) || amount < 0) return null
  if (!itemMeasurementUnitOptions(item, pieceGrams, country).includes(unit)) return null
  // Zero intentionally removes an ingredient from this editable recipe.
  return amount === 0 ? 0 : convertItemMeasurement(amount, unit, 'serving', item, pieceGrams, 1, { fromCountry: country })
}

export default function RecommendedIngredientCard({
  item,
  index,
  onServingsChange,
  country = '',
}: {
  item: RecommendedItem
  index: number
  onServingsChange: (index: number, next: number) => void
  country?: string
}) {
  const servings = useMemo(() => {
    const raw = Number(item?.servings ?? 1)
    return Number.isFinite(raw) ? clamp(raw, 0, 20) : 1
  }, [item?.servings])
  const servingSizeLabel = item.serving_size ? String(item.serving_size).trim() : '1 serving'
  const pieceGrams = useMemo(() => extractPieceGramsFromLabel(servingSizeLabel), [servingSizeLabel])
  const units = useMemo(() => itemMeasurementUnitOptions(item, pieceGrams, country), [item, pieceGrams, country])
  const initialUnit = useMemo(() => {
    const basis = recordedServingBasis(item)
    return basis && units.includes(basis.unit) ? basis.unit : 'serving'
  }, [item, units])
  const amountFromServings = recommendedAmount(item, servings, initialUnit, pieceGrams, country)
  const [expanded, setExpanded] = useState(false)
  const [selectedUnit, setSelectedUnit] = useState<BuilderUnit>(initialUnit)
  const [amountInput, setAmountInput] = useState(() => formatDecimal(amountFromServings ?? NaN))
  const [amountFocused, setAmountFocused] = useState(false)

  useEffect(() => {
    setSelectedUnit(initialUnit)
  }, [initialUnit])
  useEffect(() => {
    if (amountFocused) return
    setAmountInput(formatDecimal(recommendedAmount(item, servings, selectedUnit, pieceGrams, country) ?? NaN))
  }, [amountFocused, item, selectedUnit, servings, pieceGrams, country])

  const totals = useMemo(
    () => ({
      calories: roundOptionalNutrient(scaleOptionalNutrient(item.calories, servings), 0),
      protein_g: roundOptionalNutrient(scaleOptionalNutrient(item.protein_g, servings), 3),
      carbs_g: roundOptionalNutrient(scaleOptionalNutrient(item.carbs_g, servings), 3),
      fat_g: roundOptionalNutrient(scaleOptionalNutrient(item.fat_g, servings), 3),
      fiber_g: roundOptionalNutrient(scaleOptionalNutrient(item.fiber_g, servings), 3),
      sugar_g: roundOptionalNutrient(scaleOptionalNutrient(item.sugar_g, servings), 3),
    }),
    [item.calories, item.carbs_g, item.fat_g, item.fiber_g, item.protein_g, item.sugar_g, servings],
  )
  const fullAmountLabel = `${amountInput} ${selectedUnit}`
  const applyAmountChange = (raw: string, unit: BuilderUnit = selectedUnit) => {
    setAmountInput(raw)
    if (!raw.trim()) return
    const nextServings = recommendedServings(item, Number(raw), unit, pieceGrams, country)
    if (nextServings != null) onServingsChange(index, nextServings)
  }
  const handleUnitChange = (nextUnit: BuilderUnit) => {
    if (!units.includes(nextUnit)) return
    // Changing a display unit conserves the exact committed serving count.
    // Never recalculate that count from a rounded or unfinished input draft.
    const converted = recommendedAmount(item, servings, nextUnit, pieceGrams, country)
    if (converted == null) return
    setSelectedUnit(nextUnit)
    setAmountInput(formatDecimal(converted))
  }

  return (
    <div className="rounded-2xl border border-gray-200 overflow-hidden">
      <button
        type="button"
        onClick={() => setExpanded((prev) => !prev)}
        className="w-full flex items-center justify-between px-3 py-3 bg-white hover:bg-gray-50"
      >
        <div className="min-w-0 text-left">
          <div className="text-sm font-semibold text-gray-900 truncate">{item.name}</div>
          <div className="text-[11px] text-gray-500 truncate">
            {servingSizeLabel ? `Serving: ${servingSizeLabel}` : 'Serving: (unknown)'} • Amount (full recipe): {fullAmountLabel}
          </div>
        </div>
        <span className="text-gray-400">{expanded ? '▾' : '▸'}</span>
      </button>

      {expanded && (
        <div className="px-3 pb-3 bg-white space-y-3">
          <div className="grid grid-cols-2 gap-2">
            <div className="space-y-1">
              <div className="text-xs font-semibold text-gray-700">Amount</div>
              <input
                type="number"
                inputMode="decimal"
                min={0}
                step="0.1"
                value={amountInput}
                onFocus={() => setAmountFocused(true)}
                onBlur={() => setAmountFocused(false)}
                onChange={(e) => applyAmountChange(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500"
              />
            </div>
            <div className="space-y-1">
              <div className="text-xs font-semibold text-gray-700">Serving size</div>
              <select
                value={selectedUnit}
                onChange={(e) => handleUnitChange(e.target.value as BuilderUnit)}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg bg-white focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500"
              >
                {units.map((unit) => (
                  <option key={unit} value={unit}>
                    {formatItemMeasurementUnit(item, unit, pieceGrams, country)}
                  </option>
                ))}
              </select>
            </div>
          </div>

          <NutrientCards values={{
            calories: totals.calories,
            protein: totals.protein_g,
            carbs: totals.carbs_g,
            fat: totals.fat_g,
            fiber: totals.fiber_g,
            sugar: totals.sugar_g,
          }} />
        </div>
      )}
    </div>
  )
}

'use client'

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'

type RollerTimePickerProps = {
  value: string
  onChange: (next: string) => void
  className?: string
}

const ITEM_HEIGHT = 36
const VISIBLE_ROWS = 5
const VIEWPORT_HEIGHT = ITEM_HEIGHT * VISIBLE_ROWS
const CENTER_OFFSET = (VIEWPORT_HEIGHT - ITEM_HEIGHT) / 2
const INFINITE_REPEAT_BLOCKS = 12

const pad2 = (n: number) => String(n).padStart(2, '0')

const parseTime24 = (value: string) => {
  if (!/^\d{2}:\d{2}$/.test(String(value || ''))) {
    const now = new Date()
    return { hour24: now.getHours(), minute: now.getMinutes() }
  }
  const [hRaw, mRaw] = value.split(':').map((v) => parseInt(v, 10))
  const hour24 = Number.isFinite(hRaw) ? Math.min(23, Math.max(0, hRaw)) : 0
  const minute = Number.isFinite(mRaw) ? Math.min(59, Math.max(0, mRaw)) : 0
  return { hour24, minute }
}

const toTime24 = (hour12: number, minute: number, meridiem: 'AM' | 'PM') => {
  const normalizedHour12 = Math.min(12, Math.max(1, hour12))
  const base = normalizedHour12 % 12
  const hour24 = meridiem === 'PM' ? base + 12 : base
  return `${pad2(hour24)}:${pad2(Math.min(59, Math.max(0, minute)))}`
}

function InfiniteWheelColumn({
  label,
  options,
  selectedIndex,
  onSelect,
  enabled,
}: {
  label: string
  options: string[]
  selectedIndex: number
  onSelect: (index: number) => void
  enabled: boolean
}) {
  const scrollRef = useRef<HTMLDivElement | null>(null)
  const currentIndexRef = useRef(0)
  const wheelRemainderRef = useRef(0)
  const lastWheelDirectionRef = useRef<1 | -1 | 0>(0)
  const lastWheelTsRef = useRef(0)
  const wheelControlUntilRef = useRef(0)
  const itemCount = options.length * INFINITE_REPEAT_BLOCKS
  const displayValues = useMemo(() => Array.from({ length: itemCount }, (_, i) => options[i % options.length]), [itemCount, options])

  const normalizeIndex = useCallback(
    (index: number) => ((index % options.length) + options.length) % options.length,
    [options.length],
  )

  const toRawIndex = useCallback(
    (targetIndex: number) => Math.floor(INFINITE_REPEAT_BLOCKS / 2) * options.length + normalizeIndex(targetIndex),
    [normalizeIndex, options.length],
  )

  const topForRaw = useCallback((raw: number) => raw * ITEM_HEIGHT - CENTER_OFFSET, [])

  const topForIndex = useCallback(
    (targetIndex: number) => topForRaw(toRawIndex(targetIndex)),
    [toRawIndex, topForRaw],
  )

  const commitSelection = useCallback(
    (nextIndex: number) => {
      const normalized = normalizeIndex(nextIndex)
      if (normalized === currentIndexRef.current) return
      currentIndexRef.current = normalized
      onSelect(normalized)
    },
    [normalizeIndex, onSelect],
  )

  const scrollToIndex = useCallback(
    (targetIndex: number, behavior: ScrollBehavior = 'auto') => {
      const el = scrollRef.current
      if (!el) return
      el.scrollTo({ top: topForIndex(targetIndex), behavior })
    },
    [topForIndex],
  )

  useEffect(() => {
    if (!enabled) return
    const normalized = normalizeIndex(selectedIndex)
    currentIndexRef.current = normalized
    scrollToIndex(normalized, 'auto')
  }, [enabled, normalizeIndex, scrollToIndex, selectedIndex])

  const step = useCallback((delta: number) => {
    const next = normalizeIndex(currentIndexRef.current + delta)
    commitSelection(next)
    scrollToIndex(next, 'auto')
  }, [commitSelection, normalizeIndex, scrollToIndex])

  const handleWheelStep = (event: React.WheelEvent<HTMLDivElement>) => {
    event.preventDefault()
    const rawDelta = Number(event.deltaY)
    if (!Number.isFinite(rawDelta) || rawDelta === 0) return

    const scale = event.deltaMode === 1 ? ITEM_HEIGHT / 3 : event.deltaMode === 2 ? ITEM_HEIGHT : 1
    const delta = rawDelta * scale
    if (Math.abs(delta) < 3) return

    const direction: 1 | -1 = delta > 0 ? 1 : -1
    const now = typeof performance !== 'undefined' ? performance.now() : Date.now()
    const elapsed = now - lastWheelTsRef.current
    wheelControlUntilRef.current = now + 180

    if (elapsed > 180 || direction !== lastWheelDirectionRef.current) {
      wheelRemainderRef.current = 0
    }

    lastWheelDirectionRef.current = direction
    lastWheelTsRef.current = now
    wheelRemainderRef.current += delta

    const threshold = 24
    let iterations = 0
    while (wheelRemainderRef.current >= threshold && iterations < 8) {
      step(1)
      wheelRemainderRef.current -= threshold
      iterations += 1
    }
    while (wheelRemainderRef.current <= -threshold && iterations < 8) {
      step(-1)
      wheelRemainderRef.current += threshold
      iterations += 1
    }
  }

  const handleScroll = () => {
    const el = scrollRef.current
    if (!el) return
    const now = typeof performance !== 'undefined' ? performance.now() : Date.now()

    // When wheel-stepping, lock to the commanded index so inertia cannot sling back by one.
    if (now < wheelControlUntilRef.current) {
      const expectedTop = topForIndex(currentIndexRef.current)
      if (Math.abs(el.scrollTop - expectedTop) > 0.5) {
        el.scrollTop = expectedTop
      }
      return
    }

    const raw = Math.round((el.scrollTop + CENTER_OFFSET) / ITEM_HEIGHT)
    const normalized = normalizeIndex(raw)
    if (normalized !== currentIndexRef.current) commitSelection(normalized)

    const minRaw = options.length * 2
    const maxRaw = itemCount - options.length * 2
    if (raw < minRaw || raw > maxRaw) {
      el.scrollTop = topForRaw(toRawIndex(normalized))
    }
  }

  return (
    <div className="w-20">
      <div className="mb-1 text-center text-[10px] font-semibold uppercase tracking-wide text-gray-500">{label}</div>
      <div className="mb-1 hidden justify-center md:flex">
        <button
          type="button"
          onClick={() => step(-1)}
          className="rounded-md border border-gray-200 bg-white px-2 py-0.5 text-xs font-semibold text-gray-600 hover:bg-gray-50"
          aria-label={`${label} up`}
        >
          ^
        </button>
      </div>
      <div className="relative h-[180px] rounded-xl border border-gray-200 bg-white">
        <div className="pointer-events-none absolute inset-x-0 top-0 z-20 h-12 bg-gradient-to-b from-white to-transparent" />
        <div className="pointer-events-none absolute inset-x-0 bottom-0 z-20 h-12 bg-gradient-to-t from-white to-transparent" />

        <div
          ref={scrollRef}
          onScroll={handleScroll}
          onWheel={handleWheelStep}
          onKeyDown={(event) => {
            if (event.key === 'ArrowUp') {
              event.preventDefault()
              step(-1)
            } else if (event.key === 'ArrowDown') {
              event.preventDefault()
              step(1)
            }
          }}
          tabIndex={0}
          className="scrollbar-hide relative z-10 h-full overflow-y-auto overscroll-contain snap-y snap-mandatory touch-pan-y"
          style={{ WebkitOverflowScrolling: 'touch' }}
        >
          {displayValues.map((value, i) => {
            const isSelected = options[((i % options.length) + options.length) % options.length] === options[selectedIndex]
            return (
              <button
                key={`${label}-${i}-${value}`}
                type="button"
                onClick={() => {
                  const next = normalizeIndex(i)
                  commitSelection(next)
                  scrollToIndex(next, 'auto')
                }}
                className={`flex h-9 w-full snap-center items-center justify-center text-base transition ${
                  isSelected ? 'mx-1 rounded-md bg-emerald-500 font-semibold text-white shadow-sm' : 'text-gray-600'
                }`}
              >
                {value}
              </button>
            )
          })}
        </div>
      </div>
      <div className="mt-1 hidden justify-center md:flex">
        <button
          type="button"
          onClick={() => step(1)}
          className="rounded-md border border-gray-200 bg-white px-2 py-0.5 text-xs font-semibold text-gray-600 hover:bg-gray-50"
          aria-label={`${label} down`}
        >
          v
        </button>
      </div>
    </div>
  )
}

function FiniteWheelColumn({
  label,
  options,
  selectedIndex,
  onSelect,
  enabled,
}: {
  label: string
  options: string[]
  selectedIndex: number
  onSelect: (index: number) => void
  enabled: boolean
}) {
  const scrollRef = useRef<HTMLDivElement | null>(null)
  const currentIndexRef = useRef(0)
  const wheelRemainderRef = useRef(0)
  const lastWheelDirectionRef = useRef<1 | -1 | 0>(0)
  const lastWheelTsRef = useRef(0)
  const wheelControlUntilRef = useRef(0)

  const clampIndex = useCallback(
    (index: number) => Math.min(options.length - 1, Math.max(0, index)),
    [options.length],
  )

  const topForIndex = useCallback((index: number) => clampIndex(index) * ITEM_HEIGHT, [clampIndex])

  const commitSelection = useCallback(
    (nextIndex: number) => {
      const clamped = clampIndex(nextIndex)
      if (clamped === currentIndexRef.current) return
      currentIndexRef.current = clamped
      onSelect(clamped)
    },
    [clampIndex, onSelect],
  )

  useEffect(() => {
    if (!enabled) return
    const el = scrollRef.current
    if (!el) return
    const clamped = clampIndex(selectedIndex)
    currentIndexRef.current = clamped
    el.scrollTo({ top: topForIndex(clamped), behavior: 'auto' })
  }, [clampIndex, enabled, selectedIndex, topForIndex])

  const handleScroll = () => {
    const el = scrollRef.current
    if (!el) return
    const now = typeof performance !== 'undefined' ? performance.now() : Date.now()

    // During wheel stepping, keep the column anchored to current selection.
    if (now < wheelControlUntilRef.current) {
      const expectedTop = topForIndex(currentIndexRef.current)
      if (Math.abs(el.scrollTop - expectedTop) > 0.5) {
        el.scrollTop = expectedTop
      }
      return
    }

    const raw = Math.round(el.scrollTop / ITEM_HEIGHT)
    const clamped = clampIndex(raw)
    if (clamped !== currentIndexRef.current) commitSelection(clamped)
  }

  const step = useCallback((delta: number) => {
    const next = clampIndex(currentIndexRef.current + delta)
    commitSelection(next)
    const el = scrollRef.current
    if (el) {
      el.scrollTo({ top: topForIndex(next), behavior: 'auto' })
    }
  }, [clampIndex, commitSelection, topForIndex])

  const handleWheelStep = (event: React.WheelEvent<HTMLDivElement>) => {
    event.preventDefault()
    const rawDelta = Number(event.deltaY)
    if (!Number.isFinite(rawDelta) || rawDelta === 0) return

    const scale = event.deltaMode === 1 ? ITEM_HEIGHT / 3 : event.deltaMode === 2 ? ITEM_HEIGHT : 1
    const delta = rawDelta * scale
    if (Math.abs(delta) < 3) return

    const direction: 1 | -1 = delta > 0 ? 1 : -1
    const now = typeof performance !== 'undefined' ? performance.now() : Date.now()
    const elapsed = now - lastWheelTsRef.current
    wheelControlUntilRef.current = now + 180

    if (elapsed > 180 || direction !== lastWheelDirectionRef.current) {
      wheelRemainderRef.current = 0
    }

    lastWheelDirectionRef.current = direction
    lastWheelTsRef.current = now
    wheelRemainderRef.current += delta

    const threshold = 24
    let iterations = 0
    while (wheelRemainderRef.current >= threshold && iterations < 8) {
      step(1)
      wheelRemainderRef.current -= threshold
      iterations += 1
    }
    while (wheelRemainderRef.current <= -threshold && iterations < 8) {
      step(-1)
      wheelRemainderRef.current += threshold
      iterations += 1
    }
  }

  return (
    <div className="w-20">
      <div className="mb-1 text-center text-[10px] font-semibold uppercase tracking-wide text-gray-500">{label}</div>
      <div className="mb-1 hidden justify-center md:flex">
        <button
          type="button"
          onClick={() => step(-1)}
          className="rounded-md border border-gray-200 bg-white px-2 py-0.5 text-xs font-semibold text-gray-600 hover:bg-gray-50"
          aria-label={`${label} up`}
        >
          ^
        </button>
      </div>
      <div className="relative h-[180px] rounded-xl border border-gray-200 bg-white">
        <div className="pointer-events-none absolute inset-x-0 top-0 z-20 h-12 bg-gradient-to-b from-white to-transparent" />
        <div className="pointer-events-none absolute inset-x-0 bottom-0 z-20 h-12 bg-gradient-to-t from-white to-transparent" />

        <div
          ref={scrollRef}
          onScroll={handleScroll}
          onWheel={handleWheelStep}
          onKeyDown={(event) => {
            if (event.key === 'ArrowUp') {
              event.preventDefault()
              step(-1)
            } else if (event.key === 'ArrowDown') {
              event.preventDefault()
              step(1)
            }
          }}
          tabIndex={0}
          className="scrollbar-hide relative z-10 h-full overflow-y-auto overscroll-contain snap-y snap-mandatory touch-pan-y"
          style={{ WebkitOverflowScrolling: 'touch' }}
        >
          <div style={{ height: CENTER_OFFSET }} />
          {options.map((value, i) => {
            const isSelected = i === selectedIndex
            return (
              <button
                key={`${label}-${value}`}
                type="button"
                onClick={() => {
                  commitSelection(i)
                  const el = scrollRef.current
                  if (el) {
                    el.scrollTo({ top: topForIndex(i), behavior: 'auto' })
                  }
                }}
                className={`flex h-9 w-full snap-center items-center justify-center text-base transition ${
                  isSelected ? 'mx-1 rounded-md bg-emerald-500 font-semibold text-white shadow-sm' : 'text-gray-600'
                }`}
              >
                {value}
              </button>
            )
          })}
          <div style={{ height: CENTER_OFFSET }} />
        </div>
      </div>
      <div className="mt-1 hidden justify-center md:flex">
        <button
          type="button"
          onClick={() => step(1)}
          className="rounded-md border border-gray-200 bg-white px-2 py-0.5 text-xs font-semibold text-gray-600 hover:bg-gray-50"
          aria-label={`${label} down`}
        >
          v
        </button>
      </div>
    </div>
  )
}

export default function RollerTimePicker({ value, onChange, className }: RollerTimePickerProps) {
  const [open, setOpen] = useState(false)
  const [openAbove, setOpenAbove] = useState(false)
  const rootRef = useRef<HTMLDivElement | null>(null)

  const { hour24, minute } = useMemo(() => parseTime24(value), [value])
  const hour12 = hour24 % 12 === 0 ? 12 : hour24 % 12
  const meridiem: 'AM' | 'PM' = hour24 >= 12 ? 'PM' : 'AM'

  const hours = useMemo(() => Array.from({ length: 12 }, (_, i) => pad2(i + 1)), [])
  const minutes = useMemo(() => Array.from({ length: 60 }, (_, i) => pad2(i)), [])
  const meridiems = ['AM', 'PM'] as const

  const hourIndex = hour12 - 1
  const minuteIndex = minute
  const meridiemIndex = meridiems.indexOf(meridiem)

  const applyHourIndex = (nextIndex: number) => {
    onChange(toTime24(nextIndex + 1, minute, meridiem))
  }

  const applyMinuteIndex = (nextIndex: number) => {
    onChange(toTime24(hour12, nextIndex, meridiem))
  }

  const applyMeridiemIndex = (nextIndex: number) => {
    onChange(toTime24(hour12, minute, meridiems[nextIndex] || 'AM'))
  }

  const classValue = className ? ` ${className}` : ''
  const display = `${pad2(hour12)}:${pad2(minute)} ${meridiem.toLowerCase()}`

  const updatePlacement = () => {
    const rect = rootRef.current?.getBoundingClientRect()
    if (!rect) return
    const estimatedPopoverHeight = 300
    const spaceBelow = window.innerHeight - rect.bottom
    const spaceAbove = rect.top
    setOpenAbove(spaceBelow < estimatedPopoverHeight && spaceAbove > spaceBelow)
  }

  useEffect(() => {
    if (!open) return
    updatePlacement()

    const handleOutside = (event: MouseEvent | TouchEvent) => {
      const target = event.target as Node | null
      if (target && rootRef.current && !rootRef.current.contains(target)) {
        setOpen(false)
      }
    }

    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setOpen(false)
    }

    document.addEventListener('mousedown', handleOutside)
    document.addEventListener('touchstart', handleOutside)
    window.addEventListener('keydown', handleEscape)
    window.addEventListener('resize', updatePlacement)
    window.addEventListener('scroll', updatePlacement, true)
    return () => {
      document.removeEventListener('mousedown', handleOutside)
      document.removeEventListener('touchstart', handleOutside)
      window.removeEventListener('keydown', handleEscape)
      window.removeEventListener('resize', updatePlacement)
      window.removeEventListener('scroll', updatePlacement, true)
    }
  }, [open])

  const togglePicker = () => {
    if (open) {
      setOpen(false)
      return
    }
    updatePlacement()
    setOpen(true)
  }

  return (
    <div ref={rootRef} className={`relative${classValue}`}>
      <button
        type="button"
        onClick={togglePicker}
        className="w-full rounded-xl border border-gray-300 bg-white px-3 py-2.5 text-left text-sm font-medium text-gray-900 shadow-sm hover:border-emerald-300 focus:outline-none focus:ring-2 focus:ring-emerald-500"
        aria-label="Change entry time"
        aria-expanded={open}
      >
        <span className="flex items-center justify-between">
          <span>{display}</span>
          <span className="text-xs text-gray-500">{open ? 'Hide' : 'Edit'}</span>
        </span>
      </button>

      {open && (
        <div
          className={`absolute left-0 z-50 w-[min(96vw,340px)] rounded-2xl border border-gray-200 bg-white p-3 shadow-xl ${
            openAbove ? 'bottom-full mb-2' : 'top-full mt-2'
          }`}
        >
          <div className="mb-3 flex items-center justify-between">
            <div className="text-xs font-semibold uppercase tracking-wide text-gray-500">Select time</div>
            <button
              type="button"
              onClick={() => setOpen(false)}
              className="rounded-md px-2 py-1 text-xs font-semibold text-emerald-700 hover:bg-emerald-50"
            >
              Done
            </button>
          </div>

          <div className="flex items-start justify-between gap-2">
            <InfiniteWheelColumn label="Hour" options={hours} selectedIndex={hourIndex} onSelect={applyHourIndex} enabled={open} />
            <InfiniteWheelColumn label="Minute" options={minutes} selectedIndex={minuteIndex} onSelect={applyMinuteIndex} enabled={open} />
            <FiniteWheelColumn
              label="AM/PM"
              options={[...meridiems]}
              selectedIndex={meridiemIndex}
              onSelect={applyMeridiemIndex}
              enabled={open}
            />
          </div>
        </div>
      )}

      {open && !openAbove && <div className="h-16" aria-hidden="true" />}
    </div>
  )
}

