              {MOOD_LEVELS.map((m) => {
                const isSelected = m.value === value
                return (
                  <button
                    key={m.value}
                    type="button"
                    onClick={() => {
                      onChange(m.value)
                      triggerHaptic()
                    }}
                    className={[
                      'touch-manipulation select-none rounded-xl py-2 flex flex-col items-center justify-center',
                      'transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-helfi-green focus-visible:ring-offset-2 focus-visible:ring-offset-white dark:focus-visible:ring-offset-gray-900',
                      isSelected ? 'bg-white dark:bg-gray-800 shadow-sm' : 'bg-transparent hover:bg-white/50 dark:hover:bg-white/5',
                    ].join(' ')}
                    aria-pressed={isSelected}
                    aria-label={m.label}
                  >
                    <div style={{ color: m.color }} className="leading-none">
                      <MoodFaceIcon level={m.value} selected={isSelected} />
                    </div>
                    <div className="mt-1 text-[10px] leading-tight text-gray-700 dark:text-gray-200">
                      {m.value}
                    </div>
                  </button>
                )
              })}
            </div>
          </div>
        </div>

        <div className="mt-3">
          <input
            type="range"
            min={MOOD_LEVELS[0].value}
            max={MOOD_LEVELS[MOOD_LEVELS.length - 1].value}
            step={1}
            value={value ?? 4}
            onChange={(e) => {
              const next = Number(e.target.value) as MoodValue
              onChange(next)
              triggerHaptic()
            }}
            className="w-full accent-helfi-green"
            aria-label="Mood slider"
          />
          <div className="mt-1 flex justify-between text-xs text-gray-500 dark:text-gray-400">
            <span>{MOOD_LEVELS[0].label}</span>
            <span>{MOOD_LEVELS[MOOD_LEVELS.length - 1].label}</span>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import React, { useMemo, useState } from 'react'
import { DEFAULT_MOOD_TAGS } from '@/components/mood/moodScale'

function normalizeTag(tag: string) {
  return tag.trim().replace(/\s+/g, ' ').slice(0, 24)
}

const DEFAULT_TAG_LABELS = DEFAULT_MOOD_TAGS.map((tag) => tag.label)
const DEFAULT_TAG_EMOJI = new Map<string, string>(
  DEFAULT_MOOD_TAGS.map((tag) => [normalizeTag(tag.label), tag.emoji]),
)

const EMOTION_GROUPS: Array<{ key: string; title: string; toneClass: string; tags: string[] }> = [
  {
    key: 'positive',
    title: 'Positive',
    toneClass: 'text-emerald-700 bg-emerald-50 border-emerald-200',
    tags: ['Calm', 'Peaceful', 'Balanced', 'Relaxed', 'Content', 'Confident', 'Grateful', 'Hopeful', 'Optimistic'],
  },
  {
    key: 'energy',
    title: 'Energy',
    toneClass: 'text-blue-700 bg-blue-50 border-blue-200',
    tags: ['Focused', 'Clear-minded', 'Motivated', 'Productive', 'Inspired', 'Energised', 'Excited'],
  },
  {
    key: 'stress',
    title: 'Stress',
    toneClass: 'text-amber-700 bg-amber-50 border-amber-200',
    tags: ['Anxious', 'Worried', 'Stressed', 'Frustrated', 'Overwhelmed', 'Restless', 'Irritable'],
  },
  {
    key: 'low',
    title: 'Low Mood',
    toneClass: 'text-rose-700 bg-rose-50 border-rose-200',
    tags: ['Sad', 'Down', 'Lonely', 'Flat', 'Foggy', 'Sensitive'],
  },
  {
    key: 'fatigue',
    title: 'Fatigue',
    toneClass: 'text-violet-700 bg-violet-50 border-violet-200',
    tags: ['Tired', 'Drained', 'Burnt out'],
  },
]

function extractEmoji(tag: string) {
  const trimmed = tag.trim()
  if (!trimmed) return ''
  const first = Array.from(trimmed)[0] ?? ''
  const code = first.codePointAt(0) ?? 0
  const isEmoji =
    (code >= 0x1f300 && code <= 0x1fbff) ||
    (code >= 0x2600 && code <= 0x27bf)
  return isEmoji ? first : ''
}

export default function MoodTagChips({
  value,
  onChange,
  title = 'Mood tags',
}: {
  value: string[]
  onChange: (next: string[]) => void
  title?: string
}) {
  const [adding, setAdding] = useState(false)
  const [custom, setCustom] = useState('')

  const selected = useMemo(() => new Set(value.map((t) => normalizeTag(t)).filter(Boolean)), [value])

  const toggle = (tag: string) => {
    const t = normalizeTag(tag)
    if (!t) return
    const next = new Set(selected)
    if (next.has(t)) next.delete(t)
    else next.add(t)
    onChange(Array.from(next))
  }

  const addCustom = () => {
    const t = normalizeTag(custom)
    if (!t) return
    const next = new Set(selected)
    next.add(t)
    onChange(Array.from(next))
    setCustom('')
    setAdding(false)
  }

  const allTags = useMemo(() => {
    const merged = new Set<string>(DEFAULT_TAG_LABELS)
    selected.forEach((t) => merged.add(t))
    return Array.from(merged)
  }, [selected])

  const tagsByGroup = useMemo(() => {
    const grouped = EMOTION_GROUPS.map((group) => ({
      ...group,
      tags: group.tags.filter((tag) => allTags.includes(tag)),
    }))
    const groupedSet = new Set(grouped.flatMap((group) => group.tags.map((tag) => normalizeTag(tag))))
    const custom = allTags.filter((tag) => !groupedSet.has(normalizeTag(tag)))
    return { grouped, custom }
  }, [allTags])

  const renderChip = (tag: string) => {
    const normalized = normalizeTag(tag)
    const isSelected = selected.has(normalized)
    const defaultEmoji = DEFAULT_TAG_EMOJI.get(normalized)
    let emoji = defaultEmoji ?? ''
    let label = tag

    if (!emoji) {
      const fromTag = extractEmoji(tag)
      if (fromTag) {
        emoji = fromTag
        label = tag.replace(fromTag, '').trim()
      } else {
        emoji = '🙂'
      }
    }

    if (!label) label = tag

    return (
      <button
        key={tag}
        type="button"
        onClick={() => toggle(tag)}
        className={[
          'inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full border text-sm touch-manipulation',
          'transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-helfi-green focus-visible:ring-offset-2 focus-visible:ring-offset-white dark:focus-visible:ring-offset-gray-900',
          isSelected
            ? 'bg-helfi-green text-white border-helfi-green'
            : 'bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-700/50',
        ].join(' ')}
        aria-pressed={isSelected}
      >
        <span className="text-base leading-none" aria-hidden>
          {emoji}
        </span>
        <span>{label}</span>
      </button>
    )
  }

  return (
    <div className="w-full">
      <div className="mb-2 flex items-center justify-between">
        <div className="text-sm font-medium text-gray-700 dark:text-gray-200">{title}</div>
        {value.length > 0 && (
          <button
            type="button"
            onClick={() => onChange([])}
            className="text-xs font-semibold text-helfi-green hover:text-helfi-green-dark dark:text-helfi-green-light"
          >
            Clear all
          </button>
        )}
      </div>

      <div className="space-y-3">
        {tagsByGroup.grouped.map((group) => (
          <div key={group.key}>
            <div className={`inline-flex items-center rounded-full border px-2.5 py-1 text-[11px] font-bold uppercase tracking-wider ${group.toneClass}`}>
              {group.title}
            </div>
            <div className="mt-2 flex flex-wrap gap-2">
              {group.tags.map((tag) => renderChip(tag))}
            </div>
          </div>
        ))}

        {tagsByGroup.custom.length > 0 && (
          <div>
            <div className="inline-flex items-center rounded-full border px-2.5 py-1 text-[11px] font-bold uppercase tracking-wider text-slate-700 bg-slate-50 border-slate-200">
              Custom
            </div>
            <div className="mt-2 flex flex-wrap gap-2">
              {tagsByGroup.custom.map((tag) => renderChip(tag))}
            </div>
          </div>
        )}

        <div className="flex flex-wrap gap-2 pt-1">
          <button
            type="button"
            onClick={() => setAdding((v) => !v)}
            className="px-3 py-1.5 rounded-full border border-dashed border-gray-300 dark:border-gray-600 text-sm text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700/50 touch-manipulation"
          >
            + Add feeling
          </button>
        </div>
      </div>

      {adding && (
        <div className="mt-3 flex gap-2">
          <input
            value={custom}
            onChange={(e) => setCustom(e.target.value)}
            placeholder="Custom tag"
            className="flex-1 rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 px-3 py-2 text-sm text-gray-900 dark:text-white"
            maxLength={24}
          />
          <button
            type="button"
            onClick={addCustom}
            className="rounded-lg bg-helfi-green px-4 py-2 text-sm font-medium text-white disabled:opacity-50"
            disabled={!normalizeTag(custom)}
          >
            Add
          </button>
        </div>
      )}
    </div>
  )
}

'use client'

import React, { useMemo } from 'react'
import { Line } from 'react-chartjs-2'
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  TimeScale,
  PointElement,
  LineElement,
  Tooltip,
  Filler,
} from 'chart.js'
import type { ChartData, ChartOptions } from 'chart.js'
import 'chartjs-adapter-date-fns'
import { MOOD_LEVELS, emojiForMoodValue } from '@/components/mood/moodScale'

ChartJS.register(
  CategoryScale,
  LinearScale,
  TimeScale,
  PointElement,
  LineElement,
  Tooltip,
  Filler,
)

export type MoodPoint = { timestamp: string; mood: number | null; label?: string }

export default function MoodTrendGraph({
  points,
  showTimeAxis = false,
  fillArea = true,
  spanGaps = false,
  showLegend = true,
}: {
  points: MoodPoint[]
  showTimeAxis?: boolean
  fillArea?: boolean
  spanGaps?: boolean
  showLegend?: boolean
}) {
  const chartPoints = useMemo(() => {
    if (points.length !== 1) {
      return points.map((p, index) => ({ x: p.timestamp, y: p.mood, sourceIndex: index }))
    }

    const base = points[0]
    if (!Number.isFinite(Number(base?.mood))) {
      return []
    }
    const baseDate = new Date(base.timestamp)
    if (Number.isNaN(baseDate.getTime())) {
      return [{ x: new Date().toISOString(), y: base.mood }]
    }

    const start = new Date(baseDate)
    start.setHours(0, 0, 0, 0)
    const end = new Date(baseDate)
    end.setHours(23, 59, 59, 999)

    return [
      { x: start.toISOString(), y: base.mood, synthetic: true, sourceIndex: -1 },
      { x: baseDate.toISOString(), y: base.mood, sourceIndex: 0 },
      { x: end.toISOString(), y: base.mood, synthetic: true, sourceIndex: -1 },
    ]
  }, [points])

  const emojiPlugin = useMemo(() => ({
    id: 'emojiPoints',
    afterDatasetsDraw: (chart: any) => {
      const meta = chart.getDatasetMeta(0)
      if (!meta?.data?.length) return
      const dataset = chart.data.datasets?.[0]
      if (!dataset) return
      const { ctx, chartArea } = chart
      const fontSize = 28
      ctx.save()
      ctx.font = `${fontSize}px "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", sans-serif`
      ctx.textAlign = 'center'
      ctx.textBaseline = 'middle'
      meta.data.forEach((point: any, index: number) => {
        const raw = (dataset.data as any[])?.[index]
        if (raw?.synthetic) return
        const moodValue = Number(raw?.y)
        if (!Number.isFinite(moodValue)) return
        const emoji = emojiForMoodValue(moodValue)
        const y = Math.max(point.y - (fontSize * 0.9), chartArea.top + fontSize * 0.6)
        ctx.fillText(emoji, point.x, y)
      })
      ctx.restore()
    },
  }), [])

  const formatTime = (ts: string) => {
    try {
      const d = new Date(ts)
      if (Number.isNaN(d.getTime())) return ''
      return d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })
    } catch {
      return ''
    }
  }

  const formatDay = (ts: string) => {
    try {
      const d = new Date(ts)
      if (Number.isNaN(d.getTime())) return ''
      return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' })
    } catch {
      return ''
    }
  }

  const data: ChartData<'line', { x: string; y: number | null }[]> = useMemo(() => {
    return {
      labels: [],
      datasets: [
        {
          label: 'Mood',
          data: chartPoints,
          borderColor: 'rgb(22, 163, 74)',
          backgroundColor: 'rgba(22, 163, 74, 0.14)',
          tension: 0.35,
          fill: fillArea,
          spanGaps,
          pointRadius: (ctx) => ((ctx.raw as any)?.synthetic ? 0 : 3),
          pointHoverRadius: (ctx) => ((ctx.raw as any)?.synthetic ? 0 : 5),
          pointHitRadius: (ctx) => ((ctx.raw as any)?.synthetic ? 0 : 18),
          pointBackgroundColor: 'rgb(34, 197, 94)',
        },
      ],
    }
  }, [chartPoints, fillArea, spanGaps])

  const options: ChartOptions<'line'> = useMemo(() => ({
    responsive: true,
    maintainAspectRatio: false,
    events: ['click'],
    plugins: {
      legend: { display: false },
      tooltip: {
        enabled: false,
        external: (context) => {
          const { chart, tooltip } = context
          const parent = chart.canvas.parentNode as HTMLElement | null
          if (!parent) return

          let tooltipEl = parent.querySelector<HTMLDivElement>('#mood-line-tooltip')
          if (!tooltipEl) {
            tooltipEl = document.createElement('div')
            tooltipEl.id = 'mood-line-tooltip'
            tooltipEl.style.position = 'absolute'
            tooltipEl.style.pointerEvents = 'none'
            tooltipEl.style.opacity = '0'
            tooltipEl.style.transform = 'translate(-50%, -110%)'
            tooltipEl.style.transition = 'opacity 0.1s ease'
            tooltipEl.style.background = 'rgba(17, 24, 39, 0.9)'
            tooltipEl.style.borderRadius = '12px'
            tooltipEl.style.padding = '12px 14px'
            tooltipEl.style.color = '#fff'
            tooltipEl.style.textAlign = 'center'
            tooltipEl.style.fontFamily = 'inherit'
            tooltipEl.style.minWidth = '140px'
            tooltipEl.style.maxWidth = '220px'
            tooltipEl.style.boxShadow = '0 8px 20px rgba(0,0,0,0.2)'
            parent.appendChild(tooltipEl)
          }

          if (tooltip.opacity === 0) {
            tooltipEl.style.opacity = '0'
            return
          }

          const dataIndex = tooltip.dataPoints?.[0]?.dataIndex ?? 0
          const raw = (chart.data.datasets?.[0]?.data as any[])?.[dataIndex]
          const sourceIndex = typeof raw?.sourceIndex === 'number' ? raw.sourceIndex : dataIndex
          const point = sourceIndex >= 0 ? points[sourceIndex] : null
          const moodValue = Number(point?.mood ?? tooltip.dataPoints?.[0]?.parsed?.y)
          if (!Number.isFinite(moodValue)) {
            tooltipEl.style.opacity = '0'
            return
          }

          const moodLabel = MOOD_LEVELS.find((m) => m.value === moodValue)?.label ?? `Mood ${moodValue}`
          const detail = showTimeAxis
            ? `Time: ${formatTime(point?.timestamp || '') || '—'}`
            : point?.label
              ? point.label
              : `Day: ${formatDay(point?.timestamp || '') || '—'}`

          tooltipEl.innerHTML = ''

          const titleEl = document.createElement('div')
          titleEl.style.fontSize = '16px'
          titleEl.style.fontWeight = '600'
          titleEl.style.marginBottom = '6px'
          titleEl.style.textAlign = 'center'
          titleEl.textContent = moodLabel

          const detailEl = document.createElement('div')
          detailEl.style.fontSize = '14px'
          detailEl.style.fontWeight = '500'
          detailEl.style.textAlign = 'center'
          detailEl.style.width = '100%'
          detailEl.textContent = detail

          tooltipEl.appendChild(titleEl)
          tooltipEl.appendChild(detailEl)

          const { offsetLeft, offsetTop } = chart.canvas
          tooltipEl.style.left = `${offsetLeft + tooltip.caretX}px`
          tooltipEl.style.top = `${offsetTop + tooltip.caretY}px`
          const aboveTop = tooltip.caretY - tooltipEl.offsetHeight - 12
          tooltipEl.style.transform = aboveTop < 0 ? 'translate(-50%, 12px)' : 'translate(-50%, -110%)'
          tooltipEl.style.opacity = '1'
        },
      },
    },
    interaction: { mode: 'nearest', intersect: false },
    onClick: (_event, elements, chart) => {
      const chartRef = chart as any
      const active = chartRef.$activeMoodPoint as { datasetIndex: number; index: number } | undefined
      if (!elements?.length) {
        if (active) {
          chart.setActiveElements([])
          chart.tooltip?.setActiveElements([], { x: 0, y: 0 })
          chartRef.$activeMoodPoint = undefined
          chart.update()
        }
        return
      }

      const first = elements[0] as any
      const next = { datasetIndex: first.datasetIndex, index: first.index }
      const isSame = !!active && active.datasetIndex === next.datasetIndex && active.index === next.index
      if (isSame) {
        chart.setActiveElements([])
        chart.tooltip?.setActiveElements([], { x: 0, y: 0 })
        chartRef.$activeMoodPoint = undefined
        chart.update()
        return
      }

      chart.setActiveElements([next])
      chart.tooltip?.setActiveElements([next], {
        x: first.element?.x ?? 0,
        y: first.element?.y ?? 0,
      })
      chartRef.$activeMoodPoint = next
      chart.update()
    },
    scales: {
      x: {
        type: 'time',
        time: {
          unit: showTimeAxis ? 'hour' : 'day',
          displayFormats: { hour: 'h a', day: 'MMM d' },
        },
        grid: { display: false },
        ticks: {
          maxRotation: 0,
          autoSkip: true,
          maxTicksLimit: showTimeAxis ? 6 : 7,
        },
      },
      y: {
        min: 1,
        max: 7,
        ticks: {
          stepSize: 1,
          callback: (v) => {
            if (v === 1) return 'Low'
            if (v === 4) return 'Mid'
            if (v === 7) return 'High'
            return ''
          },
        },
        grid: { color: 'rgba(148, 163, 184, 0.18)' },
      },
    },
  }), [points, showTimeAxis])

  return (
    <div className="h-full w-full flex flex-col">
      <div className="h-48 w-full">
        <Line data={data as any} options={options as any} plugins={[emojiPlugin]} />
      </div>
      {showLegend && (
        <div className="mt-2 flex items-center justify-between text-[11px] text-gray-500 dark:text-gray-300 px-1">
          <span>Low mood</span>
          <span className="text-helfi-green font-semibold">Mood trend</span>
          <span>High mood</span>
        </div>
      )}
    </div>
  )
}

'use client'

