import React, { useState } from 'react';

interface ConsentGateProps {
  onConsent: (consent: ConsentData) => void;
  isPasswordProtected: boolean;
}

export interface ConsentData {
  decryptionConsent: boolean;
  passwordConsent: boolean;
  retentionConsent: boolean;
}

export default function ConsentGate({ onConsent, isPasswordProtected }: ConsentGateProps) {
  const [decryptionConsent, setDecryptionConsent] = useState(false);
  const [passwordConsent, setPasswordConsent] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (isPasswordProtected && (!decryptionConsent || !passwordConsent)) {
      return;
    }

    onConsent({
      decryptionConsent,
      passwordConsent,
      retentionConsent: false,
    });
  };

  const canProceed = isPasswordProtected 
    ? (decryptionConsent && passwordConsent)
    : true;

  return (
    <div className="bg-white rounded-lg shadow-md p-6 max-w-2xl mx-auto">
      <h2 className="text-2xl font-bold text-gray-900 mb-4">
        Consent Required for PDF Processing
      </h2>

      <div className="space-y-4 mb-6">
        <p className="text-gray-700 leading-relaxed">
          Before we can process your laboratory report PDF, we need your explicit consent for how we handle your data.
        </p>

        {isPasswordProtected && (
          <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
            <p className="text-yellow-800 font-medium mb-2">
              ⚠️ Password-Protected PDF Detected
            </p>
            <p className="text-yellow-700 text-sm">
              Your PDF is password-protected. You will need to provide the password to proceed.
            </p>
          </div>
        )}

        <div className="space-y-4">
          {/* Required Consent 1 */}
          <label className="flex items-start space-x-3 cursor-pointer">
            <input
              type="checkbox"
              checked={decryptionConsent}
              onChange={(e) => setDecryptionConsent(e.target.checked)}
              className="mt-1 h-5 w-5 text-green-600 focus:ring-green-500 border-gray-300 rounded"
              required
            />
            <div className="flex-1">
              <span className="text-gray-900 font-medium">
                I authorize Helfi to decrypt my uploaded PDF using the password I provide, only once, to extract my laboratory test results for analysis within my account.
              </span>
              <span className="text-red-600 ml-1">*</span>
            </div>
          </label>

          {/* Required Consent 2 */}
          <label className="flex items-start space-x-3 cursor-pointer">
            <input
              type="checkbox"
              checked={passwordConsent}
              onChange={(e) => setPasswordConsent(e.target.checked)}
              className="mt-1 h-5 w-5 text-green-600 focus:ring-green-500 border-gray-300 rounded"
              required
            />
            <div className="flex-1">
              <span className="text-gray-900 font-medium">
                I understand Helfi will not store my password and will permanently delete the original PDF after extraction.
              </span>
              <span className="text-red-600 ml-1">*</span>
            </div>
          </label>
        </div>
      </div>

      <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-6">
        <h3 className="text-blue-900 font-semibold mb-2">Security & Privacy</h3>
        <ul className="text-blue-800 text-sm space-y-1 list-disc list-inside">
          <li>Your password is used only once for decryption and is never stored</li>
          <li>All lab values are encrypted at rest using industry-standard encryption</li>
          <li>Original PDFs are deleted automatically after extraction</li>
          <li>Full audit trail is maintained for compliance</li>
        </ul>
      </div>

      <form onSubmit={handleSubmit}>
        <button
          type="submit"
          disabled={!canProceed}
          className={`w-full py-3 px-4 rounded-lg font-medium transition-colors ${
            canProceed
              ? 'bg-green-600 hover:bg-green-700 text-white'
              : 'bg-gray-300 text-gray-500 cursor-not-allowed'
          }`}
        >
          {canProceed ? 'I Consent - Continue' : 'Please accept required consents'}
        </button>
      </form>

      <p className="text-xs text-gray-500 mt-4 text-center">
        By proceeding, you agree to our{' '}
        <a href="/terms" className="text-green-600 hover:underline">
          Terms of Use
        </a>{' '}
        and{' '}
        <a href="/privacy" className="text-green-600 hover:underline">
          Privacy Policy
        </a>
        .
      </p>
    </div>
  );
}

'use client';

import React, { useState, useRef } from 'react';
import { PDFDocument } from 'pdf-lib';
import ConsentGate, { ConsentData } from './ConsentGate';

interface LabReportUploadProps {
  onUploadComplete?: (reportId: string) => void;
  compact?: boolean;
}

export default function LabReportUpload({ onUploadComplete, compact }: LabReportUploadProps) {
  const [files, setFiles] = useState<File[]>([]);
  const [password, setPassword] = useState('');
  const [consentData, setConsentData] = useState<ConsentData | null>(null);
  const [isPasswordProtected, setIsPasswordProtected] = useState(false);
  const [uploadStatus, setUploadStatus] = useState<'idle' | 'uploading' | 'processing' | 'completed' | 'error'>('idle');
  const [error, setError] = useState<string | null>(null);
  const [reportId, setReportId] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFiles = Array.from(e.target.files || []);
    if (selectedFiles.length === 0) return;

    if (isPasswordProtected && selectedFiles.length > 1) {
      setError('For password-protected PDFs, upload one file at a time.');
      return;
    }

    const isAllowedType = (name: string) => {
      const lower = name.toLowerCase();
      return lower.endsWith('.pdf') || lower.endsWith('.jpg') || lower.endsWith('.jpeg') || lower.endsWith('.png');
    };
    const invalidFile = selectedFiles.find((item) => !isAllowedType(item.name));
    if (invalidFile) {
      setError('Only PDF, JPG, or PNG files are allowed');
      return;
    }

    const totalSize = selectedFiles.reduce((sum, item) => sum + item.size, 0);
    if (totalSize > 25 * 1024 * 1024) {
      setError('Combined file size must be less than 25MB');
      return;
    }

    if (isPasswordProtected) {
      const onlyPdf = selectedFiles.every((item) => item.name.toLowerCase().endsWith('.pdf'));
      if (!onlyPdf) {
        setError('Password-protected upload only works with a single PDF file.');
        return;
      }
    }

    setFiles(selectedFiles);
    setError(null);
    setConsentData(null); // Reset consent when file changes
  };

  const handleConsent = (consent: ConsentData) => {
    setConsentData(consent);
  };

  const handleUpload = async () => {
    if (!files.length || !consentData) {
      setError('Please select a file and provide consent');
      return;
    }

    if (isPasswordProtected && !password) {
      setError('Password is required for password-protected PDFs');
      return;
    }

    if (isPasswordProtected && files.length > 1) {
      setError('For password-protected PDFs, upload one file at a time.');
      return;
    }

    if (isPasswordProtected) {
      const onlyPdf = files.every((item) => item.name.toLowerCase().endsWith('.pdf'));
      if (!onlyPdf) {
        setError('Password-protected upload only works with a single PDF file.');
        return;
      }
    }

    setUploadStatus('uploading');
    setError(null);

    try {
      let uploadFile = files[0];
      if (files.length > 1) {
        const merged = await PDFDocument.create();
        for (const item of files) {
          const bytes = await item.arrayBuffer();
          const lower = item.name.toLowerCase();
          if (lower.endsWith('.pdf')) {
            const pdf = await PDFDocument.load(bytes);
            const pages = await merged.copyPages(pdf, pdf.getPageIndices());
            pages.forEach((page) => merged.addPage(page));
          } else if (lower.endsWith('.png')) {
            const image = await merged.embedPng(bytes);
            const page = merged.addPage([image.width, image.height]);
            page.drawImage(image, {
              x: 0,
              y: 0,
              width: image.width,
              height: image.height,
            });
          } else {
            const image = await merged.embedJpg(bytes);
            const page = merged.addPage([image.width, image.height]);
            page.drawImage(image, {
              x: 0,
              y: 0,
              width: image.width,
              height: image.height,
            });
          }
        }
        const mergedBytes = await merged.save();
        if (mergedBytes.byteLength > 25 * 1024 * 1024) {
          setError('Combined file size must be less than 25MB');
          setUploadStatus('error');
          return;
        }
        uploadFile = new File([mergedBytes as any], `lab-report-${Date.now()}.pdf`, {
          type: 'application/pdf',
        });
      } else if (files.length === 1) {
        const single = files[0];
        const lower = single.name.toLowerCase();
        if (!lower.endsWith('.pdf')) {
          const merged = await PDFDocument.create();
          const bytes = await single.arrayBuffer();
          if (lower.endsWith('.png')) {
            const image = await merged.embedPng(bytes);
            const page = merged.addPage([image.width, image.height]);
            page.drawImage(image, {
              x: 0,
              y: 0,
              width: image.width,
              height: image.height,
            });
          } else {
            const image = await merged.embedJpg(bytes);
            const page = merged.addPage([image.width, image.height]);
            page.drawImage(image, {
              x: 0,
              y: 0,
              width: image.width,
              height: image.height,
            });
          }
          const mergedBytes = await merged.save();
          if (mergedBytes.byteLength > 25 * 1024 * 1024) {
            setError('File size must be less than 25MB');
            setUploadStatus('error');
            return;
          }
          uploadFile = new File([mergedBytes as any], `lab-report-${Date.now()}.pdf`, {
            type: 'application/pdf',
          });
        }
      }

      // Step 1: Create report record and get report ID
      const presignResponse = await fetch('/api/reports/presign', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          fileName: uploadFile.name,
          fileSize: uploadFile.size,
          isPasswordProtected,
          password: isPasswordProtected ? password : undefined,
          decryptionConsent: consentData.decryptionConsent,
          passwordConsent: consentData.passwordConsent,
          retentionConsent: consentData.retentionConsent,
        }),
      });

      if (!presignResponse.ok) {
        const errorData = await presignResponse.json();
        throw new Error(errorData.error || 'Failed to create report record');
      }

      const { reportId: newReportId } = await presignResponse.json();
      setReportId(newReportId);

      // Step 2: Upload to Vercel Blob
      const uploadFormData = new FormData();
      uploadFormData.append('file', uploadFile);

      const uploadResponse = await fetch(`/api/reports/${newReportId}/upload`, {
        method: 'POST',
        body: uploadFormData,
      });

      if (!uploadResponse.ok) {
        const errorData = await uploadResponse.json();
        throw new Error(errorData.error || 'Failed to upload file');
      }

      // Step 3: Process PDF
      setUploadStatus('processing');

      const processResponse = await fetch(`/api/reports/${newReportId}/process`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          password: isPasswordProtected ? password : undefined,
        }),
      });

      if (!processResponse.ok) {
        const errorData = await processResponse.json();
        throw new Error(errorData.error || 'Failed to process PDF');
      }

      const processData = await processResponse.json();

      setUploadStatus('completed');
      setPassword(''); // Clear password from memory

      if (onUploadComplete) {
        onUploadComplete(newReportId);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Upload failed');
      setUploadStatus('error');
    }
  };

  return (
    <div className={compact ? 'max-w-3xl mx-auto' : 'max-w-3xl mx-auto p-6'}>
      {!compact && (
        <>
          <h1 className="text-3xl font-bold text-gray-900 mb-6">
            Upload Laboratory Report
          </h1>
          <p className="text-sm text-gray-600 mb-4">
            Processing uses AI credits (2× model cost). Typical: 6–10 credits depending on file length and extraction.
          </p>
        </>
      )}

      {uploadStatus === 'idle' && (
        <div className="space-y-6">
          {/* File Selection */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Select PDF or image file(s)
            </label>
            <input
              ref={fileInputRef}
              type="file"
              accept=".pdf,.png,.jpg,.jpeg"
              multiple
              onChange={handleFileSelect}
              className="block w-full text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:text-sm file:font-semibold file:bg-green-50 file:text-green-700 hover:file:bg-green-100"
            />
            {files.length > 0 && (
              <div className="mt-2 text-sm text-gray-600">
                <div>
                  Selected: {files.length} file{files.length > 1 ? 's' : ''} (
                  {(files.reduce((sum, item) => sum + item.size, 0) / 1024 / 1024).toFixed(2)} MB)
                </div>
                {files.length <= 3 && (
                  <ul className="mt-1 list-disc list-inside">
                    {files.map((item) => (
                      <li key={item.name}>{item.name}</li>
                    ))}
                  </ul>
                )}
              </div>
            )}
          </div>

          {/* Password Protection Detection */}
          {files.length > 0 && (
            <div>
              <label className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  checked={isPasswordProtected}
                  onChange={(e) => setIsPasswordProtected(e.target.checked)}
                  disabled={files.length > 1 || files.some((item) => !item.name.toLowerCase().endsWith('.pdf'))}
                  className="h-4 w-4 text-green-600 focus:ring-green-500 border-gray-300 rounded"
                />
                <span className="text-sm text-gray-700">
                  My PDF is password-protected
                </span>
              </label>
              {(files.length > 1 || files.some((item) => !item.name.toLowerCase().endsWith('.pdf'))) && (
                <p className="mt-2 text-xs text-gray-500">
                  For multiple files or image uploads, please use unlocked files or upload one PDF at a time.
                </p>
              )}

              {isPasswordProtected && (
                <div className="mt-3">
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    PDF Password
                  </label>
                  <input
                    type="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="Enter PDF password"
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-green-500 focus:border-green-500"
                  />
                  <p className="mt-1 text-xs text-gray-500">
                    Your password will be used only once for decryption and will not be stored.
                  </p>
                </div>
              )}
            </div>
          )}

          {/* Consent Gate */}
          {files.length > 0 && (
            <div>
              <ConsentGate
                onConsent={handleConsent}
                isPasswordProtected={isPasswordProtected}
              />
            </div>
          )}

          {/* Upload Button */}
          {files.length > 0 && consentData && (
            <button
              onClick={handleUpload}
              className="w-full py-3 px-4 bg-green-600 hover:bg-green-700 text-white font-medium rounded-lg transition-colors"
            >
              Upload and Process PDF
            </button>
          )}

          {error && (
            <div className="bg-red-50 border border-red-200 rounded-lg p-4">
              <p className="text-red-800">{error}</p>
            </div>
          )}
        </div>
      )}

      {/* Upload Status */}
      {uploadStatus === 'uploading' && (
        <div className="text-center py-8">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-600 mx-auto mb-4"></div>
          <p className="text-gray-700">Uploading PDF...</p>
        </div>
      )}

      {uploadStatus === 'processing' && (
        <div className="text-center py-8">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-600 mx-auto mb-4"></div>
          <p className="text-gray-700">Processing PDF...</p>
          <p className="text-sm text-gray-500 mt-2">
            Decrypting, extracting lab values, and encrypting data...
          </p>
        </div>
      )}

      {uploadStatus === 'completed' && (
        <div className="bg-green-50 border border-green-200 rounded-lg p-6 text-center">
          <div className="text-green-600 text-4xl mb-4">✓</div>
          <h2 className="text-xl font-bold text-green-900 mb-2">
            PDF Processed Successfully!
          </h2>
          <p className="text-green-800 mb-4">
            Your laboratory report has been processed and encrypted.
          </p>
          <button
            onClick={() => {
              setFiles([]);
              setPassword('');
              setConsentData(null);
              setUploadStatus('idle');
              setReportId(null);
              if (fileInputRef.current) {
                fileInputRef.current.value = '';
              }
            }}
            className="px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg"
          >
            Upload Another Report
          </button>
        </div>
      )}

      {uploadStatus === 'error' && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-6">
          <h2 className="text-xl font-bold text-red-900 mb-2">
            Processing Failed
          </h2>
          <p className="text-red-800 mb-4">{error}</p>
          <button
            onClick={() => {
              setUploadStatus('idle');
              setError(null);
            }}
            className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg"
          >
            Try Again
          </button>
        </div>
      )}
    </div>
  );
}

'use client'

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import Image from 'next/image'
import { usePathname } from 'next/navigation'
import { useSession } from 'next-auth/react'
import { getCurrentSupportAgent, getSupportAgentForTimestamp } from '@/lib/support-agents'

type SupportAttachment = {
  id?: string
  name: string
  url: string
  path?: string
  type?: string
  size?: number
}

const URL_REGEX = /https?:\/\/[^\s]+/g

const ATTACHMENTS_MARKER = '[[ATTACHMENTS]]'

const STORAGE_KEYS = {
  open: 'helfi:support:widget:open',
  hidden: 'helfi:support:widget:hidden',
  guestTicketId: 'helfi:support:guest:ticketId',
  guestToken: 'helfi:support:guest:token',
  guestName: 'helfi:support:guest:name',
  guestEmail: 'helfi:support:guest:email',
  guestHistory: 'helfi:support:guest:history',
}

export default function SupportChatWidget() {
  const { data: session } = useSession()
  const pathname = usePathname()
  const isHome = pathname === '/'
  const isLoggedIn = Boolean(session?.user?.email)
  const [isOpen, setIsOpen] = useState(false)
  const [isWidgetHidden, setIsWidgetHidden] = useState(false)
  const [hasReachedAnchor, setHasReachedAnchor] = useState(!isHome)
  const [animateIn, setAnimateIn] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const [isAwaitingReply, setIsAwaitingReply] = useState(false)
  const [ticket, setTicket] = useState<any | null>(null)
  const [message, setMessage] = useState('')
  const [attachments, setAttachments] = useState<SupportAttachment[]>([])
  const [isUploading, setIsUploading] = useState(false)
  const [attachmentError, setAttachmentError] = useState('')
  const [optimisticMessages, setOptimisticMessages] = useState<Array<{
    id: string
    message: string
    attachments: SupportAttachment[]
    isAdminResponse: boolean
    createdAt: string
  }>>([])
  const [guestName, setGuestName] = useState('')
  const [guestEmail, setGuestEmail] = useState('')
  const [guestToken, setGuestToken] = useState('')
  const [guestTicketId, setGuestTicketId] = useState('')
  const [guestHistory, setGuestHistory] = useState<Array<{
    ticketId: string
    token: string
    subject: string
    createdAt: string
    updatedAt: string
  }>>([])
  const [feedbackRating, setFeedbackRating] = useState(0)
  const [feedbackComment, setFeedbackComment] = useState('')
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false)
  const messagesEndRef = useRef<HTMLDivElement | null>(null)

  const isChatClosed = ticket && ['RESOLVED', 'CLOSED'].includes(ticket.status)
  const shouldHideWidget = pathname === '/support' || pathname.startsWith('/admin-panel') || pathname.startsWith('/main-admin')
  const agent = useMemo(() => {
    if (ticket?.createdAt) {
      return getSupportAgentForTimestamp(new Date(ticket.createdAt))
    }
    return getCurrentSupportAgent()
  }, [ticket?.createdAt])
  const triggerHaptic = useCallback(() => {
    if (typeof navigator !== 'undefined' && typeof navigator.vibrate === 'function') {
      navigator.vibrate(8)
    }
  }, [])

  useEffect(() => {
    if (typeof window === 'undefined') return
    setIsOpen(window.localStorage.getItem(STORAGE_KEYS.open) === 'true')
    setIsWidgetHidden(window.localStorage.getItem(STORAGE_KEYS.hidden) === 'true')
    setGuestTicketId(window.localStorage.getItem(STORAGE_KEYS.guestTicketId) || '')
    setGuestToken(window.localStorage.getItem(STORAGE_KEYS.guestToken) || '')
    setGuestName(window.localStorage.getItem(STORAGE_KEYS.guestName) || '')
    setGuestEmail(window.localStorage.getItem(STORAGE_KEYS.guestEmail) || '')
    try {
      const rawHistory = window.localStorage.getItem(STORAGE_KEYS.guestHistory)
      if (rawHistory) {
        const parsed = JSON.parse(rawHistory)
        if (Array.isArray(parsed)) {
          setGuestHistory(parsed)
        }
      }
    } catch {
      setGuestHistory([])
    }
  }, [])

  useEffect(() => {
    if (typeof window === 'undefined') return
    window.localStorage.setItem(STORAGE_KEYS.open, String(isOpen))
  }, [isOpen])

  useEffect(() => {
    if (typeof window === 'undefined') return
    window.localStorage.setItem(STORAGE_KEYS.hidden, String(isWidgetHidden))
  }, [isWidgetHidden])

  useEffect(() => {
    if (typeof window === 'undefined') return
    if (!isHome) {
      setHasReachedAnchor(true)
      return
    }
    setHasReachedAnchor(false)
    const anchor = document.querySelector('[data-chat-anchor="food-photo-analysis"]')
    if (!anchor) {
      setHasReachedAnchor(true)
      return
    }
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          setHasReachedAnchor(true)
          observer.disconnect()
        }
      },
      { threshold: 0.2 }
    )
    observer.observe(anchor)
    return () => observer.disconnect()
  }, [isHome])

  useEffect(() => {
    if (!hasReachedAnchor || isWidgetHidden) {
      setAnimateIn(false)
      return
    }
    const raf = window.requestAnimationFrame(() => setAnimateIn(true))
    return () => window.cancelAnimationFrame(raf)
  }, [hasReachedAnchor, isWidgetHidden])

  useEffect(() => {
    if (typeof window === 'undefined') return
    if (guestTicketId) {
      window.localStorage.setItem(STORAGE_KEYS.guestTicketId, guestTicketId)
    } else {
      window.localStorage.removeItem(STORAGE_KEYS.guestTicketId)
    }
  }, [guestTicketId])

  useEffect(() => {
    if (typeof window === 'undefined') return
    if (guestToken) {
      window.localStorage.setItem(STORAGE_KEYS.guestToken, guestToken)
    } else {
      window.localStorage.removeItem(STORAGE_KEYS.guestToken)
    }
  }, [guestToken])

  useEffect(() => {
    if (typeof window === 'undefined') return
    if (guestName) {
      window.localStorage.setItem(STORAGE_KEYS.guestName, guestName)
    }
    if (guestEmail) {
      window.localStorage.setItem(STORAGE_KEYS.guestEmail, guestEmail)
    }
  }, [guestName, guestEmail])

  useEffect(() => {
    if (typeof window === 'undefined') return
    window.localStorage.setItem(STORAGE_KEYS.guestHistory, JSON.stringify(guestHistory))
  }, [guestHistory])

  const splitMessageAttachments = (messageText: string) => {
    const markerIndex = messageText.indexOf(ATTACHMENTS_MARKER)
    if (markerIndex === -1) {
      return { text: messageText, attachments: [] as SupportAttachment[] }
    }
    const text = messageText.slice(0, markerIndex).trim()
    const raw = messageText.slice(markerIndex + ATTACHMENTS_MARKER.length).trim()
    if (!raw) {
      return { text, attachments: [] as SupportAttachment[] }
    }
    try {
      const parsed = JSON.parse(raw)
      const parsedAttachments = Array.isArray(parsed)
        ? parsed
            .map((item) => ({
              id: item?.id ? String(item.id) : undefined,
              name: String(item?.name || ''),
              url: String(item?.url || ''),
              path: item?.path ? String(item.path) : undefined,
              type: item?.type ? String(item.type) : undefined,
              size: typeof item?.size === 'number' ? item.size : undefined,
            }))
            .filter((item) => item.name && item.url)
        : []
      return { text, attachments: parsedAttachments }
    } catch {
      return { text: messageText, attachments: [] as SupportAttachment[] }
    }
  }

  const serializeMessageWithAttachments = (text: string, items: SupportAttachment[]) => {
    if (!items.length) return text
    const payload = items.map((att) => ({
      id: att.id,
      name: att.name,
      url: att.url,
      path: att.path,
      type: att.type,
      size: att.size,
    }))
    return `${text}\n\n${ATTACHMENTS_MARKER}\n${JSON.stringify(payload)}`
  }

  const conversationItems = useMemo(() => {
    if (!ticket) return [...optimisticMessages]
    const initial = splitMessageAttachments(String(ticket.message || ''))
    const base = [
      {
        id: `ticket-${ticket.id}`,
        message: initial.text,
        attachments: initial.attachments,
        isAdminResponse: false,
        createdAt: ticket.createdAt,
      },
    ]
    const responses = (ticket.responses || [])
      .filter((response: any) => {
        const msg = String(response.message || '')
        return !msg.startsWith('[SYSTEM]') && !msg.startsWith('[FEEDBACK]')
      })
      .map((response: any) => {
        const parsed = splitMessageAttachments(String(response.message || ''))
        return {
          id: response.id,
          message: parsed.text,
          attachments: parsed.attachments,
          isAdminResponse: response.isAdminResponse,
          createdAt: response.createdAt,
        }
      })
    return [...base, ...responses, ...optimisticMessages]
  }, [ticket, optimisticMessages])

  useEffect(() => {
    if (!isOpen) return
    const timer = window.setTimeout(() => {
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' })
    }, 0)
    return () => window.clearTimeout(timer)
  }, [isOpen, conversationItems.length])

  const loadTicket = useCallback(async (forceLoad = false) => {
    if (!forceLoad && !isOpen) return
    setIsLoading(true)
    try {
      if (isLoggedIn) {
        const response = await fetch('/api/support/tickets?activeOnly=1')
        if (response.ok) {
          const result = await response.json()
          const nextTicket = result.ticket || null
          setTicket(nextTicket)
          setFeedbackSubmitted(Boolean(result.ticket?.responses?.some((res: any) => String(res.message || '').startsWith('[FEEDBACK]'))))
          if (nextTicket) {
            setIsOpen(!isWidgetHidden)
          } else {
            setIsOpen(false)
          }
        }
      } else if (guestTicketId && guestToken) {
        const response = await fetch(`/api/support/inquiry?ticketId=${guestTicketId}&token=${guestToken}`)
        if (response.ok) {
          const result = await response.json()
          setTicket(result.ticket || null)
          setFeedbackSubmitted(Boolean(result.ticket?.responses?.some((res: any) => String(res.message || '').startsWith('[FEEDBACK]'))))
        }
      }
    } catch (error) {
      console.error('Error loading support chat:', error)
    }
    setIsLoading(false)
  }, [isOpen, isLoggedIn, guestTicketId, guestToken, isWidgetHidden])

  useEffect(() => {
    if (isOpen) {
      loadTicket()
    }
  }, [isOpen, loadTicket])

  useEffect(() => {
    if (!isLoggedIn) return
    loadTicket(true)
  }, [isLoggedIn, loadTicket])

  const uploadSupportFile = async (file: File) => {
    const formData = new FormData()
    formData.append('file', file)
    if (!isLoggedIn && guestTicketId && guestToken) {
      formData.append('ticketId', guestTicketId)
      formData.append('token', guestToken)
    }

    const endpoint = isLoggedIn ? '/api/support/uploads' : '/api/support/inquiry/uploads'
    const response = await fetch(endpoint, {
      method: 'POST',
      body: formData,
    })
    if (!response.ok) {
      const error = await response.json().catch(() => ({}))
      throw new Error(error?.error || 'Upload failed')
    }
    return response.json()
  }

  const handleUploadFiles = async (files: File[]) => {
    if (!files.length) return
    setAttachmentError('')
    setIsUploading(true)
    try {
      const uploads = await Promise.all(
        files.map(async (file) => {
          const result = await uploadSupportFile(file)
          return {
            id: result.fileId,
            name: result.name,
            url: result.url,
            path: result.path,
            type: result.type,
            size: result.size,
          } as SupportAttachment
        })
      )
      setAttachments((prev) => [...prev, ...uploads])
    } catch (error: any) {
      setAttachmentError(error?.message || 'Failed to upload file')
    } finally {
      setIsUploading(false)
    }
  }

  const handlePasteUpload = async (event: React.ClipboardEvent<HTMLTextAreaElement>) => {
    const items = Array.from(event.clipboardData?.items || [])
    const imageFiles: File[] = []
    for (const item of items) {
      if (item.kind === 'file' && item.type.startsWith('image/')) {
        const file = item.getAsFile()
        if (file) imageFiles.push(file)
      }
    }
    if (imageFiles.length > 0) {
      await handleUploadFiles(imageFiles)
    }
  }

  const createGuestChat = async (payloadMessage: string, payloadAttachments: SupportAttachment[], optimisticId: string) => {
    if (!guestEmail.trim() || (!payloadMessage.trim() && payloadAttachments.length === 0)) return
    setIsLoading(true)
    try {
      const response = await fetch('/api/support/inquiry', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'create',
          name: guestName.trim(),
          email: guestEmail.trim(),
          message: serializeMessageWithAttachments(payloadMessage.trim(), payloadAttachments),
        }),
      })
      if (response.ok) {
        const result = await response.json()
        setTicket(result.ticket || null)
        setGuestToken(result.token || '')
        setGuestTicketId(result.ticket?.id || '')
        if (result.ticket?.id && result.token) {
          setGuestHistory((prev) => {
            const existing = prev.find((item) => item.ticketId === result.ticket.id)
            if (existing) return prev
            return [
              {
                ticketId: result.ticket.id,
                token: result.token,
                subject: result.ticket.subject || 'Support chat',
                createdAt: result.ticket.createdAt || new Date().toISOString(),
                updatedAt: result.ticket.updatedAt || new Date().toISOString(),
              },
              ...prev,
            ]
          })
        }
        setOptimisticMessages((prev) => prev.filter((item) => item.id !== optimisticId))
      }
      if (!response.ok) {
        setOptimisticMessages((prev) => prev.filter((item) => item.id !== optimisticId))
      }
    } catch (error) {
      console.error('Error starting inquiry chat:', error)
      setOptimisticMessages((prev) => prev.filter((item) => item.id !== optimisticId))
    }
    setIsLoading(false)
    setIsAwaitingReply(false)
  }

  const sendMessage = async () => {
    const trimmedMessage = message.trim()
    const outgoingAttachments = attachments
    if (!trimmedMessage && outgoingAttachments.length === 0) return
    if (isChatClosed || isLoading || isUploading) return
    if (!ticket && !isLoggedIn && !guestEmail.trim()) return

    triggerHaptic()
    setIsAwaitingReply(true)
    const optimisticId = `local-${Date.now()}-${Math.random().toString(16).slice(2)}`
    setOptimisticMessages((prev) => [
      ...prev,
      {
        id: optimisticId,
        message: trimmedMessage,
        attachments: outgoingAttachments,
        isAdminResponse: false,
        createdAt: new Date().toISOString(),
      },
    ])
    setMessage('')
    setAttachments([])
    if (!ticket) {
      if (isLoggedIn) {
        setIsLoading(true)
        try {
          const response = await fetch('/api/support/tickets', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              action: 'create',
              subject: 'Support chat',
              message: serializeMessageWithAttachments(message.trim(), attachments),
              category: 'TECHNICAL',
              priority: 'MEDIUM',
            }),
          })
          if (response.ok) {
            const result = await response.json()
            setTicket(result.ticket || null)
            setOptimisticMessages((prev) => prev.filter((item) => item.id !== optimisticId))
          }
          if (!response.ok) {
            setOptimisticMessages((prev) => prev.filter((item) => item.id !== optimisticId))
          }
        } catch (error) {
          console.error('Error creating support chat:', error)
          setOptimisticMessages((prev) => prev.filter((item) => item.id !== optimisticId))
        }
        setIsLoading(false)
        setIsAwaitingReply(false)
      } else {
        await createGuestChat(trimmedMessage, outgoingAttachments, optimisticId)
      }
      return
    }

    setIsLoading(true)
    try {
      const endpoint = isLoggedIn ? '/api/support/tickets' : '/api/support/inquiry'
      const payload = isLoggedIn
        ? { action: 'add_response', ticketId: ticket.id, message: serializeMessageWithAttachments(message.trim(), attachments) }
        : { action: 'add_response', ticketId: ticket.id, token: guestToken, message: serializeMessageWithAttachments(message.trim(), attachments) }

      const response = await fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })

      if (response.ok) {
        const result = await response.json()
        setTicket(result.ticket || null)
        setOptimisticMessages((prev) => prev.filter((item) => item.id !== optimisticId))
      }
      if (!response.ok) {
        setOptimisticMessages((prev) => prev.filter((item) => item.id !== optimisticId))
      }
    } catch (error) {
      console.error('Error sending support message:', error)
      setOptimisticMessages((prev) => prev.filter((item) => item.id !== optimisticId))
    }
    setIsLoading(false)
    setIsAwaitingReply(false)
  }

  const handleChatKeyDown = (event: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.key !== 'Enter' || event.shiftKey || event.nativeEvent.isComposing) return
    event.preventDefault()
    if (isChatClosed || isLoading || isUploading) return
    if (!isLoggedIn && !guestEmail.trim()) return
    sendMessage()
  }

  const endChat = async () => {
    if (!ticket) return
    triggerHaptic()
    setIsLoading(true)
    try {
      const endpoint = isLoggedIn ? '/api/support/tickets' : '/api/support/inquiry'
      const payload = isLoggedIn
        ? { action: 'end_chat', ticketId: ticket.id }
        : { action: 'end_chat', ticketId: ticket.id, token: guestToken }

      const response = await fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })
      if (response.ok) {
        const result = await response.json()
        setTicket(result.ticket || null)
      }
    } catch (error) {
      console.error('Error ending support chat:', error)
    }
    setIsLoading(false)
    setIsAwaitingReply(false)
  }

  const submitFeedback = async () => {
    if (!ticket || feedbackRating < 1) return
    triggerHaptic()
    setIsLoading(true)
    try {
      const endpoint = isLoggedIn ? '/api/support/tickets' : '/api/support/inquiry'
      const payload = isLoggedIn
        ? { action: 'submit_feedback', ticketId: ticket.id, rating: feedbackRating, comment: feedbackComment.trim() }
        : { action: 'submit_feedback', ticketId: ticket.id, token: guestToken, rating: feedbackRating, comment: feedbackComment.trim() }

      const response = await fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })
      if (response.ok) {
        const result = await response.json()
        setTicket(result.ticket || null)
        setFeedbackSubmitted(true)
      }
    } catch (error) {
      console.error('Error submitting feedback:', error)
    }
    setIsLoading(false)
  }

  const startNewChat = () => {
    triggerHaptic()
    setTicket(null)
    setMessage('')
    setAttachments([])
    setOptimisticMessages([])
    setFeedbackRating(0)
    setFeedbackComment('')
    setFeedbackSubmitted(false)
    setIsAwaitingReply(false)
    if (!isLoggedIn) {
      setGuestToken('')
      setGuestTicketId('')
    }
  }

  const clearChat = () => {
    triggerHaptic()
    setTicket(null)
    setMessage('')
    setAttachments([])
    setOptimisticMessages([])
    setFeedbackRating(0)
    setFeedbackComment('')
    setFeedbackSubmitted(false)
    setIsOpen(false)
    setIsAwaitingReply(false)
    if (!isLoggedIn) {
      setGuestToken('')
      setGuestTicketId('')
    }
  }

  const openGuestTicket = async (ticketId: string, token: string) => {
    triggerHaptic()
    setIsLoading(true)
    try {
      const response = await fetch(`/api/support/inquiry?ticketId=${ticketId}&token=${token}`)
      if (response.ok) {
        const result = await response.json()
        setTicket(result.ticket || null)
        setGuestTicketId(ticketId)
        setGuestToken(token)
      }
    } catch (error) {
      console.error('Error loading guest ticket:', error)
    }
    setIsLoading(false)
  }

  const deleteGuestTicket = async (ticketId: string, token: string) => {
    const confirmed = typeof window !== 'undefined'
      ? window.confirm('Delete this ticket permanently? This cannot be undone.')
      : false
    if (!confirmed) return
    triggerHaptic()
    try {
      const response = await fetch('/api/support/inquiry', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'delete_ticket', ticketId, token }),
      })
      if (response.ok) {
        setGuestHistory((prev) => prev.filter((item) => item.ticketId !== ticketId))
        if (guestTicketId === ticketId) {
          setTicket(null)
          setGuestTicketId('')
          setGuestToken('')
        }
      }
    } catch (error) {
      console.error('Error deleting guest ticket:', error)
    }
  }

  if (shouldHideWidget) return null
  if (isLoggedIn) return null
  if (!hasReachedAnchor) return null

  const containerClassName = isOpen
    ? 'fixed inset-0 z-[60] md:inset-auto md:bottom-24 md:right-5'
    : 'fixed bottom-5 right-4 md:bottom-24 md:right-5 z-[60] max-w-[calc(100vw-2rem)]'

  const handleHideWidget = () => {
    triggerHaptic()
    setIsOpen(false)
    setIsWidgetHidden(true)
  }

  const handleShowWidget = () => {
    triggerHaptic()
    setIsWidgetHidden(false)
  }

  return (
    <div className={containerClassName}>
      {isWidgetHidden && (
        <button
          type="button"
          onClick={handleShowWidget}
          className="flex h-11 w-11 items-center justify-center rounded-full border border-emerald-100 bg-white/90 text-emerald-600 shadow-lg transition-transform duration-200 hover:-translate-y-0.5 hover:shadow-xl active:scale-[0.98] backdrop-blur"
          aria-label="Show chat"
        >
          <svg viewBox="0 0 24 24" className="h-5 w-5" fill="currentColor" aria-hidden="true">
            <path d="M4 4h16v11H7l-3 3V4zm3 5h10v2H7V9zm0-4h10v2H7V5z" />
          </svg>
        </button>
      )}

      {!isWidgetHidden && (
        <div className={`transition-all duration-500 ${animateIn ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-2'}`}>
          {!isOpen && (
            <div className="flex items-center gap-2">
              <button
                onClick={() => {
                  triggerHaptic()
                  setIsOpen(true)
                }}
                className="group flex items-center gap-3 rounded-full border border-emerald-100 bg-white/90 px-4 py-2 shadow-lg transition-all duration-200 hover:-translate-y-0.5 hover:shadow-xl active:scale-[0.98] backdrop-blur"
              >
                <Image
                  src={agent.avatar}
                  alt={`${agent.name} avatar`}
                  width={40}
                  height={40}
                  className="rounded-full object-cover ring-2 ring-white"
                />
                <div className="text-left">
                  <div className="text-sm font-semibold text-gray-900">Chat with {agent.name}</div>
                  <div className="text-xs text-gray-500">Questions? We’re here.</div>
                </div>
              </button>
              <button
                type="button"
                onClick={handleHideWidget}
                className="flex h-10 w-10 items-center justify-center rounded-full border border-emerald-100 bg-white/90 text-gray-500 shadow-md transition-all duration-200 hover:-translate-y-0.5 hover:text-gray-700 hover:shadow-lg active:scale-[0.98] backdrop-blur"
                aria-label="Hide chat widget"
                title="Hide"
              >
                <svg viewBox="0 0 20 20" className="h-4 w-4" fill="currentColor" aria-hidden="true">
                  <path d="M10 12l-6-7h12l-6 7z" />
                </svg>
              </button>
            </div>
          )}

          {isOpen && (
            <div className="w-full h-full max-w-none max-h-none bg-white rounded-none shadow-none border-0 flex flex-col min-h-0 md:w-[360px] md:max-w-[92vw] md:h-[520px] md:max-h-[80vh] md:rounded-2xl md:shadow-[0_18px_60px_rgba(16,24,40,0.18)] md:border md:border-gray-100">
              <div className="flex items-center justify-between px-4 py-3 border-b border-gray-100 bg-white/95 backdrop-blur-md rounded-t-2xl">
                <div className="flex items-center gap-3">
                  <div className="relative">
                    <Image
                      src={agent.avatar}
                      alt={`${agent.name} avatar`}
                      width={40}
                      height={40}
                      className="rounded-full object-cover border border-gray-100"
                    />
                    <span className="absolute bottom-0.5 right-0.5 h-2.5 w-2.5 bg-emerald-500 rounded-full border-2 border-white" />
                  </div>
                  <div className="flex flex-col">
                    <div className="text-sm font-bold text-gray-900">{agent.name}</div>
                    <div className={`text-[11px] font-semibold ${isChatClosed ? 'text-gray-400' : 'text-emerald-600'}`}>
                      {isChatClosed ? 'Chat Closed' : 'Active Support'}
                    </div>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <button
                    type="button"
                    onClick={startNewChat}
