import jwt from 'jsonwebtoken'

const JWT_SECRET = process.env.JWT_SECRET || process.env.NEXTAUTH_SECRET

export interface AdminTokenPayload {
  adminId: string
  email: string
  role: string
}

export function verifyAdminToken(token: string): AdminTokenPayload | null {
  if (!JWT_SECRET) return null
  try {
    const decoded = jwt.verify(token, JWT_SECRET) as AdminTokenPayload
    return decoded
  } catch (error) {
    return null
  }
}

export function extractAdminFromHeaders(authHeader: string | null): AdminTokenPayload | null {
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return null
  }

  const token = authHeader.replace('Bearer ', '')
  return verifyAdminToken(token)
}

import { getServerSession } from 'next-auth'
import { getToken } from 'next-auth/jwt'
import type { NextRequest } from 'next/server'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { getUserIdFromNativeAuth } from '@/lib/native-auth'

const SESSION_COOKIE_NAME =
  process.env.NODE_ENV === 'production' ? '__Secure-next-auth.session-token' : 'next-auth.session-token'

export async function getAffiliateUser(request: NextRequest) {
  const session = await getServerSession(authOptions)
  const sessionEmail = session?.user?.email?.toLowerCase() || null
  const sessionId = (session?.user as any)?.id as string | undefined

  if (sessionEmail) {
    return prisma.user.findUnique({ where: { email: sessionEmail }, select: { id: true, email: true } })
  }

  if (sessionId) {
    return prisma.user.findUnique({ where: { id: sessionId }, select: { id: true, email: true } })
  }

  const token = await getToken({
    req: request,
    secret: process.env.NEXTAUTH_SECRET || 'helfi-secret-key-production-2024',
    cookieName: SESSION_COOKIE_NAME,
  })
  const tokenEmail = token?.email ? String(token.email).toLowerCase() : null
  const tokenId = token?.id ? String(token.id) : null

  if (tokenEmail) {
    return prisma.user.findUnique({ where: { email: tokenEmail }, select: { id: true, email: true } })
  }

  if (tokenId) {
    return prisma.user.findUnique({ where: { id: tokenId }, select: { id: true, email: true } })
  }

  const nativeUserId = await getUserIdFromNativeAuth(request)
  if (nativeUserId) {
    return prisma.user.findUnique({ where: { id: nativeUserId }, select: { id: true, email: true } })
  }

  return null
}

import crypto from 'crypto'
import { prisma } from '@/lib/prisma'

function generateCandidateCode(): string {
  const raw = crypto.randomBytes(10).toString('base64url')
  return raw.replace(/[-_]/g, '').slice(0, 10).toLowerCase()
}

export async function createUniqueAffiliateCode(): Promise<string> {
  for (let attempt = 0; attempt < 20; attempt++) {
    const code = generateCandidateCode()
    const existing = await prisma.affiliate.findUnique({ where: { code }, select: { id: true } })
    if (!existing) return code
  }
  throw new Error('Failed to generate unique affiliate code')
}

import crypto from 'crypto'
import type { NextRequest } from 'next/server'

export const AFFILIATE_COOKIE_MAX_AGE_SECONDS = 30 * 24 * 60 * 60 // 30 days

export const AFFILIATE_COOKIES = {
  code: 'helfi_aff_code',
  clickId: 'helfi_aff_click',
  visitorId: 'helfi_aff_vid',
  clickedAtMs: 'helfi_aff_ts',
} as const

export type AffiliateCookieData = {
  code: string
  clickId: string
  visitorId: string
  clickedAtMs: number
}

export function normalizeAffiliateCode(input: string): string {
  return input.trim().toLowerCase()
}

export function getOrCreateVisitorId(request: NextRequest): string {
  const existing = request.cookies.get(AFFILIATE_COOKIES.visitorId)?.value
  if (existing && existing.length >= 10) return existing
  return crypto.randomUUID()
}

export function getAffiliateCookieData(request: NextRequest): AffiliateCookieData | null {
  const code = request.cookies.get(AFFILIATE_COOKIES.code)?.value
  const clickId = request.cookies.get(AFFILIATE_COOKIES.clickId)?.value
  const visitorId = request.cookies.get(AFFILIATE_COOKIES.visitorId)?.value
  const clickedAtMsStr = request.cookies.get(AFFILIATE_COOKIES.clickedAtMs)?.value
  const clickedAtMs = clickedAtMsStr ? Number(clickedAtMsStr) : NaN

  if (!code || !clickId || !visitorId || !Number.isFinite(clickedAtMs)) return null
  return { code, clickId, visitorId, clickedAtMs }
}

export function isAffiliateAttributionFresh(clickedAtMs: number, nowMs: number = Date.now()): boolean {
  const ageSeconds = Math.floor((nowMs - clickedAtMs) / 1000)
  return ageSeconds >= 0 && ageSeconds <= AFFILIATE_COOKIE_MAX_AGE_SECONDS
}

import OpenAI from 'openai'
import { runChatCompletionWithLogging } from '@/lib/ai-usage-logger'

export type AffiliateScreeningInput = {
  email: string
  name: string
  website?: string | null
  primaryChannel?: string | null
  primaryChannelOther?: string | null
  audienceSize?: string | null
  promotionMethod: string
  notes?: string | null
  ip?: string | null
  userAgent?: string | null
  country?: string | null
  region?: string | null
  city?: string | null
}

export type AffiliateScreeningResult = {
  riskLevel: 'LOW' | 'MEDIUM' | 'HIGH'
  recommendedAction: 'AUTO_APPROVE' | 'MANUAL_REVIEW'
  reasoning: string
  redFlags?: string[]
  raw?: any
}

function getOpenAI(): OpenAI | null {
  if (!process.env.OPENAI_API_KEY) return null
  return new OpenAI({ apiKey: process.env.OPENAI_API_KEY })
}

function tryParseJsonObject(text: string): any | null {
  const start = text.indexOf('{')
  const end = text.lastIndexOf('}')
  if (start < 0 || end < 0 || end <= start) return null
  try {
    return JSON.parse(text.slice(start, end + 1))
  } catch {
    return null
  }
}

export async function screenAffiliateApplication(input: AffiliateScreeningInput): Promise<AffiliateScreeningResult> {
  const webhookUrl = process.env.AFFILIATE_SCREENING_WEBHOOK_URL
  if (webhookUrl) {
    const resp = await fetch(webhookUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type: 'affiliate_application', input }),
    })
    if (!resp.ok) {
      throw new Error(`Affiliate screening webhook failed: ${resp.status}`)
    }
    const data = await resp.json().catch(() => ({}))
    const risk = String(data?.riskLevel || data?.risk || '').toUpperCase()
    const action = String(data?.recommendedAction || data?.action || '').toUpperCase()
    if (!['LOW', 'MEDIUM', 'HIGH'].includes(risk) || !['AUTO_APPROVE', 'MANUAL_REVIEW'].includes(action)) {
      throw new Error('Affiliate screening webhook returned invalid result')
    }
    return {
      riskLevel: risk as any,
      recommendedAction: action as any,
      reasoning: String(data?.reasoning || data?.summary || 'No reasoning provided'),
      redFlags: Array.isArray(data?.redFlags) ? data.redFlags.map((x: any) => String(x)) : undefined,
      raw: data,
    }
  }

  const openai = getOpenAI()
  if (!openai) {
    return {
      riskLevel: 'MEDIUM',
      recommendedAction: 'MANUAL_REVIEW',
      reasoning: 'OPENAI_API_KEY not configured; defaulting to manual review.',
    }
  }

  const model = 'gpt-5.6-sol'
  const system = `You are an affiliate application screening service for a SaaS app.
Return ONLY valid JSON with keys:
- riskLevel: one of LOW|MEDIUM|HIGH
- recommendedAction: one of AUTO_APPROVE|MANUAL_REVIEW
- reasoning: short explanation
- redFlags: array of strings (optional)
`
  const user = {
    input,
    criteria: [
      'Email domain quality',
      'Consistency of applicant details',
      'Clarity and specificity of promotion method',
      'Signs of automated or low-effort submissions',
      'IP / location anomalies (where available)',
    ],
  }

  const result = await runChatCompletionWithLogging(
    openai,
    {
      model,
      temperature: 0.1,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: JSON.stringify(user) },
      ],
    },
    { feature: 'affiliate:screening', userLabel: input.email, endpoint: 'affiliate_screening' }
  )

  const text = (result as any)?.choices?.[0]?.message?.content || ''
  const parsed = tryParseJsonObject(text) || {}
  const riskLevel = String(parsed?.riskLevel || '').toUpperCase()
  const recommendedAction = String(parsed?.recommendedAction || '').toUpperCase()

  if (!['LOW', 'MEDIUM', 'HIGH'].includes(riskLevel) || !['AUTO_APPROVE', 'MANUAL_REVIEW'].includes(recommendedAction)) {
    return {
      riskLevel: 'MEDIUM',
      recommendedAction: 'MANUAL_REVIEW',
      reasoning: 'AI returned an invalid response; defaulting to manual review.',
      raw: { text },
    }
  }

  return {
    riskLevel: riskLevel as any,
    recommendedAction: recommendedAction as any,
    reasoning: String(parsed?.reasoning || 'No reasoning provided'),
    redFlags: Array.isArray(parsed?.redFlags) ? parsed.redFlags.map((x: any) => String(x)) : undefined,
    raw: parsed,
  }
}

const inferContentTypeFromName = (name: string) => {
  const lower = String(name || '').toLowerCase()
  if (lower.endsWith('.jpg') || lower.endsWith('.jpeg')) return 'image/jpeg'
  if (lower.endsWith('.png')) return 'image/png'
  if (lower.endsWith('.gif')) return 'image/gif'
  if (lower.endsWith('.webp') || lower.endsWith('.web')) return 'image/webp'
  if (lower.endsWith('.avif')) return 'image/avif'
  if (lower.endsWith('.heic')) return 'image/heic'
  if (lower.endsWith('.heif')) return 'image/heif'
  return null
}

const detectContentTypeFromBuffer = (buffer: Buffer) => {
  if (buffer.length < 12) return null

  if (buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff) return 'image/jpeg'
  if (
    buffer[0] === 0x89 &&
    buffer[1] === 0x50 &&
    buffer[2] === 0x4e &&
    buffer[3] === 0x47
  ) {
    return 'image/png'
  }
  if (buffer.slice(0, 6).toString('ascii') === 'GIF87a' || buffer.slice(0, 6).toString('ascii') === 'GIF89a') {
    return 'image/gif'
  }
  if (
    buffer.slice(0, 4).toString('ascii') === 'RIFF' &&
    buffer.slice(8, 12).toString('ascii') === 'WEBP'
  ) {
    return 'image/webp'
  }

  if (buffer.slice(4, 8).toString('ascii') === 'ftyp') {
    const brand = buffer.slice(8, 12).toString('ascii').toLowerCase()
    if (brand === 'avif' || brand === 'avis') return 'image/avif'
    if (brand === 'heic' || brand === 'heix' || brand === 'hevc' || brand === 'hevx') return 'image/heic'
    if (brand === 'heif' || brand === 'heis' || brand === 'heim' || brand === 'hevm' || brand === 'mif1' || brand === 'msf1') {
      return 'image/heif'
    }
  }

  return null
}

export const resolveImageContentType = (type: string | null | undefined, name: string | null | undefined, buffer: Buffer) => {
  const detected = detectContentTypeFromBuffer(buffer)
  if (detected) return detected
  const trimmedType = String(type || '').trim().toLowerCase()
  if (trimmedType.startsWith('image/')) return trimmedType
  return inferContentTypeFromName(String(name || '')) || 'image/jpeg'
}

const shouldConvertForAi = (mimeType: string) => {
  return mimeType === 'image/avif' || mimeType === 'image/heic' || mimeType === 'image/heif'
}

export async function normalizeImageForAi(buffer: Buffer, mimeType: string) {
  if (!shouldConvertForAi(mimeType)) {
    return { buffer, mimeType, converted: false as const }
  }

  try {
    const sharpModule = await import('sharp')
    const sharp = sharpModule.default || sharpModule
    const convertedBuffer = await sharp(buffer).rotate().jpeg({ quality: 92 }).toBuffer()
    return { buffer: convertedBuffer, mimeType: 'image/jpeg', converted: true as const }
  } catch (error) {
    console.warn('[ai-image-normalize] failed to convert image for AI, using original format', error)
    return { buffer, mimeType, converted: false as const }
  }
}

