// Convenience wrapper: run OpenAI chat completion, capture usage/cost, log it, and return the completion.
export async function runChatCompletionWithLogging(
  openai: any,
  params: any,
  context: UsageContext,
  extras?: {
    image?: ImageMeta | null
    successDetail?: string | null
    callDetail?: string | null
  }
) {
  const asyncContext = getRunContext()
  const mergedContext: UsageContext = {
    ...context,
    feature: context.feature || asyncContext?.feature || 'unknown',
    userId: context.userId ?? asyncContext?.meta?.userId ?? null,
    runId: context.runId ?? asyncContext?.runId ?? null,
  }
  try {
    const { completion, costCents, promptTokens, completionTokens } = await chatCompletionWithCost(openai, params, mergedContext)
    const model = (completion as any)?.model || params?.model || 'unknown'
    logAiUsageEvent({
      ...mergedContext,
      model,
      promptTokens,
      completionTokens,
      costCents,
      image: extras?.image ?? null,
      detail: extras?.successDetail ?? null,
      callDetail: extras?.callDetail ?? null,
      success: true,
    }).catch(() => {})
    return completion
  } catch (err: any) {
    const model = params?.model || 'unknown'
    logAiUsageEvent({
      ...mergedContext,
      model,
      promptTokens: 0,
      completionTokens: 0,
      costCents: 0,
      image: extras?.image ?? null,
      success: false,
      errorMessage: err?.message || 'unknown_error',
    }).catch(() => {})
    throw err
  }
}

import { prisma } from '@/lib/prisma'

export async function getRunCostCents(runId: string, userId: string) {
  if (!runId || !userId) return { costCents: 0, count: 0, promptTokens: 0, completionTokens: 0 }
  const aggregate = await prisma.aIUsageEvent.aggregate({
    _sum: { costCents: true, promptTokens: true, completionTokens: true },
    _count: { _all: true },
    where: {
      runId,
      userId,
      success: true,
    },
  })
  return {
    costCents: Number(aggregate._sum.costCents || 0),
    count: Number(aggregate._count?._all || 0),
    promptTokens: Number(aggregate._sum.promptTokens || 0),
    completionTokens: Number(aggregate._sum.completionTokens || 0),
  }
}

