import jwt from 'jsonwebtoken'

let cachedSecret: { value: string; expiresAtMs: number } | null = null

const readEnv = () => {
  const clientId = process.env.APPLE_CLIENT_ID?.trim() || ''
  const teamId = process.env.APPLE_TEAM_ID?.trim() || ''
  const keyId = process.env.APPLE_KEY_ID?.trim() || ''
  const rawPrivateKey = process.env.APPLE_PRIVATE_KEY || ''
  // Vercel env vars often store multiline keys with literal "\n".
  const privateKey = rawPrivateKey.replace(/\\n/g, '\n').trim()

  if (!clientId || !teamId || !keyId || !privateKey) {
    return null
  }

  return { clientId, teamId, keyId, privateKey }
}

/**
 * Apple OAuth requires a client_secret which is a signed JWT (ES256).
 * This helper builds it from APPLE_* environment variables.
 *
 * Returns null if Apple OAuth isn't configured in this environment.
 */
export const getAppleClientSecret = () => {
  const now = Date.now()
  if (cachedSecret && cachedSecret.expiresAtMs > now + 60_000) {
    return cachedSecret.value
  }

  const env = readEnv()
  if (!env) return null

  // Apple allows a max of 6 months for the client_secret JWT expiry.
  const sixMonthsSeconds = 60 * 60 * 24 * 180
  const iat = Math.floor(now / 1000)
  const exp = iat + sixMonthsSeconds

  const value = jwt.sign(
    {},
    env.privateKey,
    {
      algorithm: 'ES256',
      keyid: env.keyId,
      issuer: env.teamId,
      subject: env.clientId,
      audience: 'https://appleid.apple.com',
      expiresIn: sixMonthsSeconds,
    }
  )

  cachedSecret = { value, expiresAtMs: now + sixMonthsSeconds * 1000 }
  return value
}

/**
 * Audit logging utility for PDF processing events
 * Ensures full audit trail for compliance
 */

import { prisma } from '@/lib/prisma';
import { AuditEventType } from '@prisma/client';

export interface AuditEventData {
  reportId?: string;
  userId: string;
  eventType: AuditEventType;
  eventDescription: string;
  metadata?: Record<string, any>;
  ipAddress?: string;
  userAgent?: string;
}

/**
 * Create an audit event
 * Automatically redacts sensitive information from metadata
 */
export async function createAuditEvent(data: AuditEventData): Promise<void> {
  try {
    // Redact sensitive information from metadata
    const redactedMetadata = data.metadata ? redactSensitiveData(data.metadata) : undefined;

    await prisma.auditEvent.create({
      data: {
        reportId: data.reportId,
        userId: data.userId,
        eventType: data.eventType,
        eventDescription: data.eventDescription,
        metadata: redactedMetadata,
        ipAddress: data.ipAddress,
        userAgent: data.userAgent,
      },
    });
  } catch (error) {
    // Don't throw - audit logging failures shouldn't break the main flow
    console.error('❌ Failed to create audit event:', error);
  }
}

/**
 * Redact sensitive information from metadata
 * Removes passwords, full file contents, and other PII
 */
function redactSensitiveData(metadata: Record<string, any>): Record<string, any> {
  const redacted = { ...metadata };

  // Remove password fields
  if (redacted.password) {
    redacted.password = '[REDACTED]';
  }

  if (redacted.passwordHash) {
    redacted.passwordHash = '[REDACTED]';
  }

  // Truncate large text fields
  if (redacted.text && typeof redacted.text === 'string' && redacted.text.length > 500) {
    redacted.text = redacted.text.substring(0, 500) + '...[TRUNCATED]';
  }

  // Remove file buffers
  if (redacted.buffer) {
    redacted.buffer = '[BINARY_DATA_REDACTED]';
  }

  if (redacted.pdfBuffer) {
    redacted.pdfBuffer = '[BINARY_DATA_REDACTED]';
  }

  // Remove S3 keys that might contain sensitive paths
  if (redacted.s3Key) {
    redacted.s3Key = redacted.s3Key.replace(/[^/]+$/, '[FILENAME_REDACTED]');
  }

  return redacted;
}

/**
 * Get audit events for a report
 */
export async function getReportAuditEvents(reportId: string) {
  return prisma.auditEvent.findMany({
