          } else if (!dbUser.emailVerified) {
            // Auto-verify existing users who sign in with OAuth.
            console.log(`🔄 Auto-verifying existing ${providerLabel} user:`, dbUser.email)
            await prisma.user.update({
              where: { id: dbUser.id },
              data: { emailVerified: new Date() }
            })
          }

          if (provider && providerAccountId) {
            await prisma.account.upsert({
              where: {
                provider_providerAccountId: {
                  provider,
                  providerAccountId,
                },
              },
              update: {
                userId: dbUser.id,
                type: String(account?.type || 'oauth'),
                refresh_token: (account as any)?.refresh_token || null,
                access_token: (account as any)?.access_token || null,
                expires_at:
                  typeof (account as any)?.expires_at === 'number' ? (account as any).expires_at : null,
                token_type: (account as any)?.token_type || null,
                scope: (account as any)?.scope || null,
                id_token: (account as any)?.id_token || null,
                session_state: (account as any)?.session_state || null,
              },
              create: {
                userId: dbUser.id,
                type: String(account?.type || 'oauth'),
                provider,
                providerAccountId,
                refresh_token: (account as any)?.refresh_token || null,
                access_token: (account as any)?.access_token || null,
                expires_at:
                  typeof (account as any)?.expires_at === 'number' ? (account as any).expires_at : null,
                token_type: (account as any)?.token_type || null,
                scope: (account as any)?.scope || null,
                id_token: (account as any)?.id_token || null,
                session_state: (account as any)?.session_state || null,
              },
            })
          }

          // Send welcome email for new OAuth users (don't await to avoid blocking auth)
          if (isNewUser) {
            const userName = dbUser.name || dbUser.email.split('@')[0]
            console.log(`📧 Sending welcome email to new ${providerLabel} user:`, userName)
            sendWelcomeEmail({
              email: dbUser.email,
              name: userName,
            }).catch(error => {
              console.error(`❌ ${providerLabel} welcome email failed (non-blocking):`, error)
            })

            // Notify owner of new OAuth signup (don't await to avoid blocking auth)
            notifyOwner({
              event: 'signup',
              userEmail: dbUser.email,
              userName: dbUser.name || undefined,
            }).catch(error => {
              console.error('❌ Owner notification failed (non-blocking):', error)
            })

            sendOwnerSignupEmail({
              userEmail: dbUser.email,
              userName: dbUser.name || undefined,
            }).catch(error => {
              console.error('❌ Signup email alert failed (non-blocking):', error)
            })
          }

          // Update user ID for session
          user.id = dbUser.id
          user.email = dbUser.email
          if (!user.name) {
            user.name = dbUser.name || dbUser.email.split('@')[0]
          }
          if (!user.image && dbUser.image) {
            user.image = dbUser.image
          }
          resolvedEmail = dbUser.email
          console.log(`✅ ${providerLabel} user processed:`, { id: dbUser.id, email: dbUser.email, isNew: isNewUser })
        } catch (error) {
          console.error('❌ OAuth user creation error:', error)
          return false
        }
      }

      return true
    },
    async redirect({ url, baseUrl }) {
      console.log('🔄 Redirect callback:', { url, baseUrl })

      // CRITICAL FIX: Handle development vs production environment properly
      const isDevMode = process.env.NODE_ENV === 'development'
      const actualBaseUrl = isDevMode ? 'http://localhost:3000' : baseUrl

      console.log('🌍 Environment:', { isDevMode, actualBaseUrl, originalBaseUrl: baseUrl })

      // Handle signout - go to home
      if (url.includes('signout') || url.includes('signOut')) {
        return actualBaseUrl + '/'
      }

      // Native OAuth safety: if OAuth fails, route back into native completion endpoint
      // so the app can receive a clear error instead of landing on the web sign-in page.
      try {
        const parsed = new URL(url, actualBaseUrl)
        const isNativeOAuthError =
          parsed.pathname === '/auth/signin' &&
          parsed.searchParams.has('error') &&
          String(parsed.searchParams.get('callbackUrl') || '').includes('/api/native-auth/oauth/complete')
        if (isNativeOAuthError) {
          const oauthError = String(parsed.searchParams.get('error') || 'OAuthSignin').trim()
          return `${actualBaseUrl}/api/native-auth/oauth/complete?error=${encodeURIComponent(oauthError)}`
        }
      } catch {
        // ignore parse issues and continue with normal redirect handling
      }

      // If URL is relative, use it with actualBaseUrl
      if (url.startsWith('/')) {
        return actualBaseUrl + url
      }

      // If URL matches actualBaseUrl origin, allow it
      try {
        const urlOrigin = new URL(url).origin
        const actualBaseOrigin = new URL(actualBaseUrl).origin
        if (urlOrigin === actualBaseOrigin) {
          console.log('✅ URL origin matches, allowing:', url)
          return url
        }
      } catch (e) {
        console.log('⚠️ URL parsing failed, using default redirect')
      }

      // Default: redirect to dashboard (onboarding redirect will be handled client-side for new users only)
      const defaultRedirect = actualBaseUrl + '/dashboard'
      console.log('🎯 Default redirect to dashboard:', defaultRedirect)
      return defaultRedirect
    },
    async session({ session, token }) {
      console.log('📋 Session callback:', { 
        tokenEmail: token?.email,
        tokenId: token?.id 
      })

      try {
        // Add user info to session from JWT token
        if (token?.email) {
          // CRITICAL: Validate that user still exists in database
          const dbUser = await prisma.user.findUnique({
            where: { id: token.id as string },
            include: { practitionerAccount: { select: { id: true } } },
          })

          if (!dbUser) {
            console.log('🚫 User account deleted - invalidating session:', token.email)
            // Return empty session to force complete logout
            return {
              expires: session.expires,
              user: undefined
            }
          }

          const revokedAt = await getSessionRevokedAt(dbUser.id)
          if (revokedAt) {
            const tokenIssuedAt =
              typeof token?.iat === 'number' ? new Date(token.iat * 1000) : null
            if (!tokenIssuedAt || revokedAt > tokenIssuedAt) {
              console.log('🚫 Session revoked by admin:', token.email)
              return {
                expires: session.expires,
                user: undefined
              }
            }
          }

          session.user = {
            id: token.id as string,
            email: token.email as string,
            name: token.name as string,
            image: (dbUser.image as string) || (token.image as string) || null,
            needsVerification: !dbUser.emailVerified,
            isPractitioner: !!dbUser.practitionerAccount,
          }
        }

        console.log('✅ Session validated:', { 
          id: session.user?.id, 
          email: session.user?.email 
        })

        return session
      } catch (error) {
        console.error('❌ Session callback error:', error)
        return session
      }
    },
    async jwt({ token, user, account, profile }) {
      console.log('🎫 JWT callback:', { 
        hasUser: !!user,
        tokenEmail: token?.email,
        provider: account?.provider
      })

      try {
        // Add user info to token on first sign in
        if (user) {
          token.id = user.id
          token.email = user.email
          token.name = user.name
          token.image = user.image

          console.log('✅ JWT token updated:', { 
            id: token.id, 
            email: token.email 
          })
        }

        // For Google OAuth, also store profile image
        if (account?.provider === 'google' && profile) {
          token.image = profile.image || user?.image
        }

        return token
      } catch (error) {
        console.error('❌ JWT callback error:', error)
        return token
      }
    }
  },
  pages: {
    signIn: '/auth/signin',
    error: '/auth/oauth-error',
  },
  debug: true,
  secret: process.env.NEXTAUTH_SECRET || 'helfi-secret-key-production-2024'
}

import { createSignedBlobToken, SignedBlobScope } from '@/lib/signed-blob'
import { extractBlobPathWithPrefixes, normalizeBlobPath } from '@/lib/blob-paths'

const BLOB_SCOPE_PREFIXES: Record<SignedBlobScope, string[]> = {
  'food-photo': ['food-photos/'],
  'support': ['support/', 'support/inquiry/'],
  'mood-journal': ['mood-journal/'],
}

export const isPathAllowedForScope = (path: string, scope: SignedBlobScope) =>
  BLOB_SCOPE_PREFIXES[scope].some((prefix) => path.startsWith(prefix))

export const extractScopedBlobPath = (
  value: string | null | undefined,
  scope: SignedBlobScope,
) => extractBlobPathWithPrefixes(value, BLOB_SCOPE_PREFIXES[scope])

export const buildSignedBlobUrl = (
  path: string,
  scope: SignedBlobScope,
  expiresInSeconds = 900,
): string | null => {
  const normalized = normalizeBlobPath(path)
  if (!isPathAllowedForScope(normalized, scope)) return null
  const token = createSignedBlobToken({ path: normalized, scope }, expiresInSeconds)
  return `/api/blob?path=${encodeURIComponent(normalized)}&token=${encodeURIComponent(token)}`
}

export const mapToSignedBlobUrl = (
  value: string | null | undefined,
  scope: SignedBlobScope,
  expiresInSeconds = 900,
): string | null => {
  const path = extractScopedBlobPath(value, scope)
  if (!path) return null
  return buildSignedBlobUrl(path, scope, expiresInSeconds)
}

export { BLOB_SCOPE_PREFIXES, normalizeBlobPath }

const BLOB_HOST = 'blob.vercel-storage.com'
const BLOB_PROXY_PATH = '/api/blob'

const normalizeBlobPath = (path: string) => path.replace(/^\/+/, '')

const looksLikeUrl = (value: string) => /^https?:\/\//i.test(value)

const extractFromProxyUrl = (value: string): string | null => {
  if (!value.startsWith(BLOB_PROXY_PATH)) return null
  try {
    const parsed = new URL(value, 'http://localhost')
    const path = parsed.searchParams.get('path')
    if (!path) return null
    return normalizeBlobPath(path)
  } catch {
    return null
  }
}

const extractFromBlobUrl = (value: string): string | null => {
  try {
    const parsed = new URL(value)
    if (!parsed.hostname.includes(BLOB_HOST)) return null
    return normalizeBlobPath(parsed.pathname)
  } catch {
    return null
  }
}

export const extractBlobPath = (value: string | null | undefined): string | null => {
  if (!value || typeof value !== 'string') return null
  const trimmed = value.trim()
  if (!trimmed) return null

  if (trimmed.startsWith(BLOB_PROXY_PATH)) {
    return extractFromProxyUrl(trimmed)
  }

  if (looksLikeUrl(trimmed)) {
    return extractFromBlobUrl(trimmed)
  }

  if (trimmed.startsWith('data:') || trimmed.startsWith('blob:')) return null

  return normalizeBlobPath(trimmed)
}

export const extractBlobPathWithPrefixes = (
  value: string | null | undefined,
  prefixes: string[],
): string | null => {
  const path = extractBlobPath(value)
  if (!path) return null
  if (!prefixes.some((prefix) => path.startsWith(prefix))) return null
  return path
}

export const isBlobPath = (value: string | null | undefined, prefixes: string[]) =>
  Boolean(extractBlobPathWithPrefixes(value, prefixes))

export { normalizeBlobPath }

function escapeForRegExp(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

export function formatChatContent(
  raw: string,
  options?: {
    headings?: string[]
  }
): string {
  let text = (raw || '').replace(/\r\n/g, '\n').replace(/\u2022/g, '- ')

  // Normalize single-asterisk emphasis to bold so the renderer doesn't show stray asterisks.
  text = text.replace(/(^|[^*])\*([^\s*][^*\n]{0,80}?[^\s*])\*(?!\*)/g, (_match, prefix, inner) => {
    return `${prefix}**${inner}**`
  })

  // Force key headings onto their own line when provided.
  if (options?.headings?.length) {
    for (const heading of options.headings) {
      const pattern = new RegExp(escapeForRegExp(heading), 'g')
      text = text.replace(pattern, `\n${heading}\n`)
    }
  }

  // Add missing line breaks before numbered / bulleted lists (model sometimes streams them without breaks).
  text = text.replace(/([^\n])(\d+\.\s)/g, '$1\n$2')
  text = text.replace(/([^\n])([-*•]\s)/g, '$1\n$2')

  // If a list starts immediately after a colon/semicolon, give it breathing room.
  text = text.replace(/([:;])\s*(\d+\.\s)/g, '$1\n\n$2')

  // Drop lines that are only list markers so they don't render as empty bullets.
  text = text.replace(/^\s*[-*•]\s*$/gm, '')

  // Collapse any excessive blank lines so spacing stays neat.
  text = text.replace(/\n{3,}/g, '\n\n')

  return text.trim()
}

type CacheEntry<T> = {
  data: T
  updatedAt: number
}

const memoryCache = new Map<string, CacheEntry<unknown>>()
const STORAGE_PREFIX = 'helfi.cache.'

function storageKey(key: string) {
  return `${STORAGE_PREFIX}${key}`
}

function canUseStorage() {
  return typeof window !== 'undefined' && typeof window.localStorage !== 'undefined'
}

export function readClientCache<T>(key: string): CacheEntry<T> | null {
  if (!key) return null
  const mem = memoryCache.get(key)
  if (mem) return mem as CacheEntry<T>
  if (!canUseStorage()) return null

  try {
    const raw = window.localStorage.getItem(storageKey(key))
    if (!raw) return null
    const parsed = JSON.parse(raw) as CacheEntry<T>
    if (!parsed || typeof parsed.updatedAt !== 'number') return null
    memoryCache.set(key, parsed)
    return parsed
  } catch {
    return null
  }
}

export function writeClientCache<T>(key: string, data: T): CacheEntry<T> {
  const entry: CacheEntry<T> = { data, updatedAt: Date.now() }
  if (!key) return entry
  memoryCache.set(key, entry)
  if (!canUseStorage()) return entry
  try {
    window.localStorage.setItem(storageKey(key), JSON.stringify(entry))
  } catch {}
  return entry
}

export function clearClientCache(prefix?: string) {
  if (!canUseStorage()) {
    if (!prefix) {
      memoryCache.clear()
    } else {
      memoryCache.forEach((_value, key) => {
        if (key.startsWith(prefix)) memoryCache.delete(key)
      })
    }
    return
  }

  if (!prefix) {
    memoryCache.clear()
    try {
      Object.keys(window.localStorage).forEach((key) => {
        if (key.startsWith(STORAGE_PREFIX)) {
          window.localStorage.removeItem(key)
        }
      })
    } catch {}
    return
  }

  memoryCache.forEach((_value, key) => {
    if (key.startsWith(prefix)) memoryCache.delete(key)
  })
  try {
    Object.keys(window.localStorage).forEach((key) => {
      if (key.startsWith(STORAGE_PREFIX + prefix)) {
        window.localStorage.removeItem(key)
      }
    })
  } catch {}
}

export function isCacheFresh(entry: CacheEntry<unknown> | null, maxAgeMs: number) {
  if (!entry) return false
  if (!Number.isFinite(maxAgeMs) || maxAgeMs <= 0) return false
  return Date.now() - entry.updatedAt <= maxAgeMs
}

// Centralized cost metering for AI usage.
// Prices are in cents per 1,000 tokens. Defaults reflect public pricing circa mid‑2024/2025.
// You can override any value by setting an env var like:
// HELFI_PRICE_GPT4O_INPUT_CENTS_PER_1K, HELFI_PRICE_GPT4O_OUTPUT_CENTS_PER_1K, etc.

type ModelPrices = {
  inputCentsPer1k: number;
  outputCentsPer1k: number;
};

// Global markup multiplier to apply to all computed costs (e.g., 2 = 2x AI cost).
// Default is 2x per user request.
const BILLING_MARKUP_MULTIPLIER = (() => {
  const v = process.env.HELFI_BILLING_MARKUP_MULTIPLIER;
  const n = Number(v);
  if (Number.isFinite(n) && n > 0) return n;
  return 2; // default: double the AI cost to cover service margin
})();

const envNumber = (key: string, fallback: number): number => {
  const v = process.env[key];
  if (!v) return fallback;
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
};

