const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value))

const normalizeDietTypes = (raw: any): string[] => {
  if (Array.isArray(raw)) {
    return Array.from(
      new Set(
        raw
          .filter((v) => typeof v === 'string')
          .map((v) => v.trim())
          .filter(Boolean),
      ),
    )
  }
  if (typeof raw === 'string') {
    const v = raw.trim()
    return v ? [v] : []
  }
  return []
}

