const addSuggestion = (suggestions: string[], value: string) => {
  const clean = value.trim()
  if (!clean) return
  if (!suggestions.includes(clean)) suggestions.push(clean)
}

export const checkDietCompatibility = (input: DietCheckInput): DietCheckResult => {
  const dietId = (input.dietId || '').toString().trim()
  const warnings: string[] = []
  const suggestions: string[] = []
  if (!dietId) return { warnings, suggestions }

  const option = getDietOption(dietId)
  const blob = normalizeTextBlob(input)
  const carbs = Number(input.totals?.carbs_g)
  const sugar = Number(input.totals?.sugar_g)
  const hasMeat = hasAny(blob, KEYWORDS.meat)
  const hasFish = hasAny(blob, KEYWORDS.fishSeafood)
  const hasDairy = hasAny(blob, KEYWORDS.dairy)
  const hasEggs = hasAny(blob, KEYWORDS.eggs)
  const hasGluten = hasAny(blob, KEYWORDS.gluten)
  const hasGrains = hasAny(blob, KEYWORDS.grains)

  const maybeWarn = (condition: boolean, text: string) => {
    if (!condition) return
    warnings.push(text)
  }

  const basicSwapForAnimalProduct = () => {
    addSuggestion(suggestions, 'Try tofu, tempeh, beans, or lentils as a swap.')
    addSuggestion(suggestions, 'Try a plant-based milk or yogurt instead of dairy.')
  }

  switch (dietId) {
    // Plant-based
    case 'vegan':
      maybeWarn(hasMeat || hasFish, 'This looks like it contains meat or seafood, which doesn’t fit a vegan diet.')
      maybeWarn(hasDairy, 'This looks like it contains dairy, which doesn’t fit a vegan diet.')
      maybeWarn(hasEggs, 'This looks like it contains eggs, which doesn’t fit a vegan diet.')
      maybeWarn(hasAny(blob, KEYWORDS.honey), 'This looks like it contains honey, which doesn’t fit a vegan diet.')
      if (warnings.length) basicSwapForAnimalProduct()
      break
    case 'vegetarian':
      maybeWarn(hasMeat || hasFish, 'This looks like it contains meat or seafood, which doesn’t fit a vegetarian diet.')
      if (warnings.length) addSuggestion(suggestions, 'Try tofu, tempeh, beans, or lentils as a swap for meat.')
      break
    case 'lacto-vegetarian':
      maybeWarn(hasMeat || hasFish, 'This looks like it contains meat or seafood, which doesn’t fit a lacto-vegetarian diet.')
      maybeWarn(hasEggs, 'This looks like it contains eggs, which doesn’t fit a lacto-vegetarian diet.')
      if (warnings.length) addSuggestion(suggestions, 'Try beans or lentils instead of meat, and skip eggs.')
      break
    case 'ovo-vegetarian':
      maybeWarn(hasMeat || hasFish, 'This looks like it contains meat or seafood, which doesn’t fit an ovo-vegetarian diet.')
      maybeWarn(hasDairy, 'This looks like it contains dairy, which doesn’t fit an ovo-vegetarian diet.')
      if (warnings.length) addSuggestion(suggestions, 'Try a dairy-free version (or swap dairy for a plant-based option).')
      break
    case 'lacto-ovo-vegetarian':
      maybeWarn(hasMeat || hasFish, 'This looks like it contains meat or seafood, which doesn’t fit a lacto-ovo vegetarian diet.')
      if (warnings.length) addSuggestion(suggestions, 'Try beans, lentils, or tofu as a swap for meat.')
      break
    case 'wfpb':
      maybeWarn(hasMeat || hasFish || hasDairy || hasEggs, 'This looks like it contains animal products, which doesn’t fit a whole-food plant-based diet.')
      maybeWarn(hasAny(blob, KEYWORDS.processed), 'This looks quite processed. Whole-food plant-based usually prefers less processed foods.')
      if (warnings.length) addSuggestion(suggestions, 'Try a whole-food option (beans, lentils, vegetables, whole grains) instead.')
      break
    case 'raw-vegan':
      maybeWarn(hasMeat || hasFish || hasDairy || hasEggs, 'This looks like it contains animal products, which doesn’t fit a raw vegan diet.')
      maybeWarn(/fried|roast|baked|grilled|cooked/.test(blob), 'This looks cooked. Raw vegan is usually uncooked foods.')
      if (warnings.length) addSuggestion(suggestions, 'Try raw options like salads, smoothies, or fresh fruit.')
      break

    // Animal-focused
    case 'carnivore':
      maybeWarn(hasAny(blob, KEYWORDS.plantsCommon) || hasGrains, 'This looks like it contains plant foods, which doesn’t fit a carnivore diet.')
      if (Number.isFinite(carbs) && carbs > 10) {
        warnings.push('This looks higher in carbs than most carnivore meals.')
      }
      if (Number.isFinite(sugar) && sugar > 5) {
        warnings.push('This looks higher in sugar than most carnivore meals.')
      }
      if (warnings.length) addSuggestion(suggestions, 'Try a simple meat-only meal (e.g. steak, eggs, fish).')
      break
    case 'lion':
      maybeWarn(hasAny(blob, KEYWORDS.nonRuminantAnimal) || hasAny(blob, KEYWORDS.plantsCommon) || hasDairy, 'Lion diet is usually ruminant meat only (plus salt/water). This meal may not fit.')
      if (Number.isFinite(carbs) && carbs > 10) {
        warnings.push('This looks higher in carbs than most lion diet meals.')
      }
      if (Number.isFinite(sugar) && sugar > 5) {
        warnings.push('This looks higher in sugar than most lion diet meals.')
      }
      if (warnings.length) addSuggestion(suggestions, 'Try beef or lamb (simple, unseasoned) as a swap.')
      break
    case 'keto-carnivore':
      maybeWarn(hasAny(blob, KEYWORDS.plantsCommon) || hasGrains, 'This looks like it contains plant foods, which may not fit keto carnivore.')
      if (Number.isFinite(carbs) && carbs > 20) {
        warnings.push('This looks higher in carbs than most keto carnivore meals.')
      }
      if (warnings.length) addSuggestion(suggestions, 'Try a fatty cut of meat with eggs or butter (if you allow dairy).')
      break
    case 'paleo-animal-leaning':
      maybeWarn(hasGrains, 'Paleo usually avoids grains. This meal may not fit.')
      maybeWarn(hasAny(blob, ['processed', 'soda', 'candy']), 'Paleo usually avoids processed foods. This meal may not fit.')
      if (warnings.length) addSuggestion(suggestions, 'Try meat/fish with vegetables instead of grains.')
      break
    case 'primal':
      maybeWarn(hasGrains, 'Primal usually avoids grains. This meal may not fit.')
      if (warnings.length) addSuggestion(suggestions, 'Try meat/fish with vegetables; some dairy is usually okay for primal.')
      break

    // Low-carb
    case 'keto':
      if (Number.isFinite(carbs) && carbs > 40) {
        warnings.push('This looks higher in carbs than most keto meals.')
        addSuggestion(suggestions, 'Try a lower-carb swap (more protein/veg, less bread/rice/pasta).')
      } else if (hasAny(blob, KEYWORDS.grains) || hasAny(blob, KEYWORDS.sugary)) {
        warnings.push('This looks like it contains bread, pasta, rice, or sweets, which often don’t fit keto.')
        addSuggestion(suggestions, 'Try a low-carb swap (salad, cauliflower rice, or extra veggies).')
      }
      break
    case 'low-carb':
      if (Number.isFinite(carbs) && carbs > 80) {
        warnings.push('This looks high in carbs for a low-carb diet.')
        addSuggestion(suggestions, 'Try smaller portions of bread/rice/pasta, and add more protein/veg.')
      }
      break
    case 'atkins':
      if (hasAny(blob, KEYWORDS.sugary) || hasAny(blob, KEYWORDS.grains)) {
        warnings.push('This looks like it contains bread/pasta/sweets, which may not fit Atkins (depending on your phase).')
        addSuggestion(suggestions, 'Try a lower-carb swap (salad, protein, vegetables).')
      }
      break
    case 'zero-carb':
      maybeWarn(Number.isFinite(carbs) ? carbs > 5 : hasAny(blob, KEYWORDS.grains) || hasAny(blob, KEYWORDS.sugary), 'This looks like it contains carbs, which may not fit zero-carb.')
      if (warnings.length) addSuggestion(suggestions, 'Try a meat/egg/fish-based meal with no bread, rice, or fruit.')
      break

    // Grain / gluten
    case 'gluten-free':
      maybeWarn(hasGluten, 'This looks like it may contain gluten, which doesn’t fit a gluten-free diet.')
      if (warnings.length) addSuggestion(suggestions, 'Try a gluten-free version (gluten-free bread/pasta) or a rice/potato swap.')
      break
    case 'grain-free':
      maybeWarn(hasGrains, 'This looks like it contains grains, which doesn’t fit a grain-free diet.')
      if (warnings.length) addSuggestion(suggestions, 'Try a grain-free swap (vegetables, potatoes, or salad).')
      break
    case 'wheat-free':
      maybeWarn(hasAny(blob, ['wheat', 'flour', 'bread', 'pasta', 'noodle']), 'This looks like it may contain wheat, which doesn’t fit a wheat-free diet.')
      if (warnings.length) addSuggestion(suggestions, 'Try a wheat-free version (gluten-free bread/pasta) or rice.')
      break
    case 'low-fodmap':
      maybeWarn(hasAny(blob, KEYWORDS.lowFodmapCommon), 'This may include common high-FODMAP foods (like garlic, onion, wheat, beans, milk, or certain fruits).')
      if (warnings.length) addSuggestion(suggestions, 'Try a simpler version without garlic/onion, and use gluten-free grains if needed.')
      break

    // Timing-based (no food-specific conflicts)
    case 'intermittent-fasting':
    case 'omad':
    case 'time-restricted':
    case 'calorie-restriction':
      // No specific “against the diet” food keywords here.
      break

    // Medical / therapeutic
    case 'low-histamine':
      maybeWarn(hasAny(blob, KEYWORDS.histamineCommon), 'This may include common histamine triggers (like aged cheese, fermented foods, alcohol, or certain fish).')
      if (warnings.length) addSuggestion(suggestions, 'Try fresh, simple foods (fresh meat, rice, most vegetables).')
      break
    case 'low-oxalate':
      maybeWarn(hasAny(blob, KEYWORDS.oxalateCommon), 'This may include high-oxalate foods (like spinach, almonds, or chocolate).')
      if (warnings.length) addSuggestion(suggestions, 'Try a lower-oxalate swap (most meats, dairy, and many vegetables).')
      break
    case 'low-purine':
      maybeWarn(hasAny(blob, KEYWORDS.purineCommon), 'This may include high-purine foods (like organ meats, sardines, or beer).')
      if (warnings.length) addSuggestion(suggestions, 'Try lean proteins and plenty of water.')
      break
    case 'renal':
      maybeWarn(hasAny(blob, KEYWORDS.renalCommon), 'This may include foods that can be tricky on a renal diet (like banana, potato, tomato, or avocado).')
      if (warnings.length) addSuggestion(suggestions, 'Consider kidney-friendly swaps based on your plan (ask your clinician for the exact rules).')
      break
    case 'diabetic':
      if (Number.isFinite(sugar) && sugar > 25) {
        warnings.push('This looks high in sugar for a diabetic-friendly meal.')
        addSuggestion(suggestions, 'Try a lower-sugar swap (more protein/veg, fewer sweets).')
      } else if (Number.isFinite(carbs) && carbs > 80) {
        warnings.push('This looks high in carbs for a diabetic-friendly meal.')
        addSuggestion(suggestions, 'Try smaller portions of bread/rice/pasta and add more protein/veg.')
      }
      break
    case 'gerd':
      maybeWarn(hasAny(blob, KEYWORDS.refluxTriggers), 'This may include common reflux triggers (spicy foods, coffee, citrus, tomato, chocolate, or fried foods).')
      if (warnings.length) addSuggestion(suggestions, 'Try a milder version (less spicy, less fried, smaller portions).')
      break

    // Ethical / lifestyle
    case 'halal':
      maybeWarn(hasAny(blob, ['pork', 'bacon', 'ham']), 'This looks like it contains pork, which doesn’t fit halal.')
      maybeWarn(hasAny(blob, KEYWORDS.alcohol), 'This looks like it contains alcohol, which doesn’t fit halal.')
      if (warnings.length) addSuggestion(suggestions, 'Try a halal-certified option (chicken, beef, or lamb) and skip alcohol.')
      break
    case 'kosher': {
      const hasPork = hasAny(blob, ['pork', 'bacon', 'ham'])
      const hasShellfish = hasAny(blob, ['shrimp', 'prawn', 'crab', 'lobster', 'shellfish', 'mussel', 'oyster'])
      maybeWarn(hasPork, 'This looks like it contains pork, which doesn’t fit kosher.')
      maybeWarn(hasShellfish, 'This looks like it contains shellfish, which doesn’t fit kosher.')
      // Very simple meat + dairy mixing check
      const meatish = hasMeat || hasFish
      const dairyish = hasDairy
      maybeWarn(meatish && dairyish, 'This may mix meat and dairy, which doesn’t fit kosher rules.')
      if (warnings.length) addSuggestion(suggestions, 'Try a kosher-certified version (and avoid mixing meat and dairy).')
      break
    }
    case 'jain':
      maybeWarn(hasMeat || hasFish, 'This looks like it contains meat or seafood, which doesn’t fit a Jain diet.')
      maybeWarn(hasEggs, 'This looks like it contains eggs, which doesn’t fit a Jain diet.')
      maybeWarn(hasAny(blob, KEYWORDS.roots), 'This may include root vegetables (like onion, garlic, or potato), which often don’t fit a Jain diet.')
      if (warnings.length) addSuggestion(suggestions, 'Try Jain-friendly meals with non-root vegetables, legumes, and grains (as allowed).')
      break
    case 'buddhist-vegetarian':
      maybeWarn(hasMeat || hasFish, 'This looks like it contains meat or seafood, which may not fit Buddhist vegetarian choices.')
      maybeWarn(hasAny(blob, ['garlic', 'onion']), 'Some Buddhist vegetarian plans avoid garlic/onion. This meal may not fit.')
      if (warnings.length) addSuggestion(suggestions, 'Try a vegetarian version without garlic/onion if that matters for you.')
      break

    // Mixed / balanced + performance (no strict checks)
    default:
      // For all other diet IDs, keep it quiet unless we can offer something helpful.
      break
  }

  return { warnings, suggestions }
}

export type MultiDietCheckResult = {
  warningsByDiet: Array<{ dietId: string; dietLabel: string; warnings: string[] }>
  suggestions: string[]
}

export const checkMultipleDietCompatibility = (input: Omit<DietCheckInput, 'dietId'> & { dietIds: string[] }): MultiDietCheckResult => {
  const dietIds = normalizeDietTypes(input.dietIds)
  const warningsByDiet: Array<{ dietId: string; dietLabel: string; warnings: string[] }> = []
  const suggestions: string[] = []

  for (const dietId of dietIds) {
    const option = getDietOption(dietId)
    const single = checkDietCompatibility({
      dietId,
      itemNames: input.itemNames,
      analysisText: input.analysisText,
      totals: input.totals,
    })
    if (single.warnings.length) {
      warningsByDiet.push({
        dietId,
        dietLabel: option?.label || dietId,
        warnings: single.warnings,
      })
    }
    for (const s of single.suggestions) {
      if (!suggestions.includes(s)) suggestions.push(s)
    }
  }

  return { warningsByDiet, suggestions }
}

/**
 * Encryption utilities for PDF lab report data
 * Uses AES-256-GCM for field-level encryption
 * Encryption keys are derived from a master key stored in environment variables
 */

import { createCipheriv, createDecipheriv, randomBytes, scrypt, createHash } from 'crypto';
import { promisify } from 'util';

const scryptAsync = promisify(scrypt);

const ALGORITHM = 'aes-256-gcm';
const IV_LENGTH = 12; // 96 bits for GCM
const SALT_LENGTH = 32;
const TAG_LENGTH = 16; // 128 bits for GCM authentication tag
const KEY_LENGTH = 32; // 256 bits

// Get or generate master encryption key from environment
function getMasterKey(): Buffer {
  const masterKeyEnv = process.env.ENCRYPTION_MASTER_KEY;

  if (!masterKeyEnv) {
    throw new Error('ENCRYPTION_MASTER_KEY environment variable is required. Generate one with: openssl rand -base64 32');
  }

  // If it's base64 encoded, decode it; otherwise use it directly
  try {
    return Buffer.from(masterKeyEnv, 'base64');
  } catch {
    // If not base64, hash it to get consistent 32-byte key
    return createHash('sha256').update(masterKeyEnv).digest();
  }
}

/**
 * Derive a data encryption key (DEK) from master key with a salt
 * This ensures each record can have a unique key while using the master key
 */
async function deriveDataKey(salt: Buffer): Promise<Buffer> {
  const masterKey = getMasterKey();
  const key = (await scryptAsync(masterKey, salt, KEY_LENGTH)) as Buffer;
  return key;
}

/**
 * Generate a random data encryption key (DEK)
 * For per-record encryption, we generate a unique key and encrypt it with the master key
 */
function generateDataKey(): Buffer {
  return randomBytes(KEY_LENGTH);
}

/**
 * Encrypt a data encryption key using the master key
 * This is our "envelope encryption" - encrypting keys with keys
 */
async function encryptDataKey(dataKey: Buffer, salt: Buffer): Promise<string> {
  const masterKey = getMasterKey();
  const key = (await scryptAsync(masterKey, salt, KEY_LENGTH)) as Buffer;

  const iv = randomBytes(IV_LENGTH);
  const cipher = createCipheriv(ALGORITHM, key, iv);

  let encrypted = cipher.update(dataKey, undefined, 'hex');
  encrypted += cipher.final('hex');

  const tag = cipher.getAuthTag();

  // Return base64 encoded: salt:iv:encrypted:tag
  return Buffer.from(`${salt.toString('hex')}:${iv.toString('hex')}:${encrypted}:${tag.toString('hex')}`).toString('base64');
}

/**
 * Decrypt a data encryption key using the master key
 */
async function decryptDataKey(encryptedKeyBase64: string): Promise<Buffer> {
  const parts = Buffer.from(encryptedKeyBase64, 'base64').toString('utf8').split(':');
  if (parts.length !== 4) {
    throw new Error('Invalid encrypted key format');
  }

  const [saltHex, ivHex, encrypted, tagHex] = parts;
  const salt = Buffer.from(saltHex, 'hex');
  const iv = Buffer.from(ivHex, 'hex');
  const tag = Buffer.from(tagHex, 'hex');

  const masterKey = getMasterKey();
  const key = (await scryptAsync(masterKey, salt, KEY_LENGTH)) as Buffer;

  const decipher = createDecipheriv(ALGORITHM, key, iv);
  decipher.setAuthTag(tag);

  let decrypted = decipher.update(encrypted, 'hex');
  decrypted = Buffer.concat([decrypted, decipher.final()]);

  return decrypted;
}

/**
 * Derive encryption key from password using scrypt
 * Used for password-protected PDFs (ephemeral, not stored)
 */
async function deriveKeyFromPassword(password: string, salt: Buffer): Promise<Buffer> {
  const key = (await scryptAsync(password, salt, KEY_LENGTH)) as Buffer;
  return key;
}

/**
 * Encrypt data using AES-256-GCM
 */
function encryptWithAES(data: string, key: Buffer): { encrypted: string; iv: string; tag: string } {
  const iv = randomBytes(IV_LENGTH);
  const cipher = createCipheriv(ALGORITHM, key, iv);

  let encrypted = cipher.update(data, 'utf8', 'hex');
  encrypted += cipher.final('hex');

  const tag = cipher.getAuthTag();

  return {
    encrypted,
    iv: iv.toString('hex'),
    tag: tag.toString('hex'),
  };
}

/**
 * Decrypt data using AES-256-GCM
 */
function decryptWithAES(
  encrypted: string,
  key: Buffer,
  iv: string,
  tag: string
): string {
  const ivBuffer = Buffer.from(iv, 'hex');
  const tagBuffer = Buffer.from(tag, 'hex');
  const decipher = createDecipheriv(ALGORITHM, key, ivBuffer);
  decipher.setAuthTag(tagBuffer);

  let decrypted = decipher.update(encrypted, 'hex', 'utf8');
  decrypted += decipher.final('utf8');

  return decrypted;
}

/**
 * Encrypt a field value with AES-256-GCM and wrap the key
 * Returns a JSON string containing encrypted data, IV, tag, and wrapped key
 */
export async function encryptField(value: string): Promise<string> {
  if (!value) {
    return '';
  }

  // Generate a data encryption key for this field
  const dataKey = generateDataKey();
  const salt = randomBytes(SALT_LENGTH);

  // Encrypt the value
  const { encrypted, iv, tag } = encryptWithAES(value, dataKey);

  // Wrap the data key with master key
  const wrappedKey = await encryptDataKey(dataKey, salt);

  // Return JSON string with all components
  return JSON.stringify({
    encrypted,
    iv,
    tag,
    wrappedKey,
  });
}

/**
 * Decrypt a field value that was encrypted with encryptField
 */
export async function decryptField(encryptedDataJson: string): Promise<string> {
  if (!encryptedDataJson) {
    return '';
  }

  try {
    const { encrypted, iv, tag, wrappedKey } = JSON.parse(encryptedDataJson);

    // Unwrap the data key
    const dataKey = await decryptDataKey(wrappedKey);

    // Decrypt the value
    return decryptWithAES(encrypted, dataKey, iv, tag);
  } catch (error) {
    console.error('❌ Field decryption failed:', error);
    throw new Error(`Failed to decrypt field: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

/**
 * Encrypt multiple fields in batch (more efficient for multiple lab results)
 * Returns encrypted data with a single wrapped key for all fields
 */
export async function encryptFieldsBatch(fields: Record<string, string>): Promise<{
  encryptedFields: Record<string, string>;
  wrappedKey: string;
}> {
  // Generate a single data key for all fields
  const dataKey = generateDataKey();
  const salt = randomBytes(SALT_LENGTH);
  const wrappedKey = await encryptDataKey(dataKey, salt);

  const encryptedFields: Record<string, string> = {};

  for (const [key, value] of Object.entries(fields)) {
    if (value) {
      const { encrypted, iv, tag } = encryptWithAES(value, dataKey);
      encryptedFields[key] = JSON.stringify({ encrypted, iv, tag });
    }
  }

  return {
    encryptedFields,
    wrappedKey,
  };
}

/**
 * Decrypt multiple fields that were encrypted with encryptFieldsBatch
 */
export async function decryptFieldsBatch(
  encryptedFields: Record<string, string>,
  wrappedKey: string
): Promise<Record<string, string>> {
  const dataKey = await decryptDataKey(wrappedKey);
  const decryptedFields: Record<string, string> = {};

  for (const [key, encryptedDataJson] of Object.entries(encryptedFields)) {
    try {
      const { encrypted, iv, tag } = JSON.parse(encryptedDataJson);
      decryptedFields[key] = decryptWithAES(encrypted, dataKey, iv, tag);
    } catch (error) {
      console.error(`❌ Failed to decrypt field ${key}:`, error);
      decryptedFields[key] = '';
    }
  }

  return decryptedFields;
}

/**
 * Hash password for verification (ephemeral - not stored)
 * Uses scrypt with random salt
 */
export async function hashPasswordForVerification(password: string): Promise<{ hash: string; salt: string }> {
  const salt = randomBytes(SALT_LENGTH);
  const hash = (await scryptAsync(password, salt, 64)) as Buffer;
  return {
    hash: hash.toString('hex'),
    salt: salt.toString('hex'),
  };
}

/**
 * Verify password hash
 */
export async function verifyPasswordHash(
  password: string,
  hashHex: string,
  saltHex: string
): Promise<boolean> {
  try {
    const salt = Buffer.from(saltHex, 'hex');
    const hash = (await scryptAsync(password, salt, 64)) as Buffer;
    return hash.toString('hex') === hashHex;
  } catch (error) {
    return false;
  }
}

import { sendOwnerErrorAlertEmail } from '@/lib/admin-alerts'

type ErrorReportOptions = {
  source: string
  error: unknown
  userId?: string
  userEmail?: string
  details?: Record<string, unknown>
  recipientEmail?: string
}

type ErrorReportCacheEntry = {
  lastSentAt: number
  count: number
}

const REPORT_THROTTLE_MS = 60 * 60 * 1000
const MAX_DETAILS_LENGTH = 2000

const globalForErrorReporter = globalThis as typeof globalThis & {
  __helfiErrorReportCache?: Map<string, ErrorReportCacheEntry>
}

const cache = globalForErrorReporter.__helfiErrorReportCache ?? new Map<string, ErrorReportCacheEntry>()
if (!globalForErrorReporter.__helfiErrorReportCache) {
  globalForErrorReporter.__helfiErrorReportCache = cache
}

function normalizeError(error: unknown): { name: string; message: string; stack: string } {
  if (error instanceof Error) {
    return {
      name: error.name || 'Error',
      message: error.message || 'Unknown error',
      stack: error.stack || '',
    }
  }
  if (typeof error === 'string') {
    return { name: 'Error', message: error, stack: '' }
  }
  return { name: 'Error', message: 'Unknown error', stack: '' }
}

function buildFingerprint(source: string, message: string): string {
  const trimmed = (message || 'Unknown error').slice(0, 140)
  return `${source}::${trimmed}`
}

function safeStringify(value: unknown): string {
  try {
    return JSON.stringify(value, null, 2)
  } catch {
    return String(value || '')
  }
}

export async function reportCriticalError(options: ErrorReportOptions): Promise<void> {
  try {
    const normalized = normalizeError(options.error)
    const fingerprint = buildFingerprint(options.source, normalized.message)
    const now = Date.now()
    const entry = cache.get(fingerprint)

    if (entry && now - entry.lastSentAt < REPORT_THROTTLE_MS) {
      entry.count += 1
      cache.set(fingerprint, entry)
      return
    }

    const count = (entry?.count ?? 0) + 1
    cache.set(fingerprint, { lastSentAt: now, count })

    const detailsPayload = {
      ...options.details,
      errorName: normalized.name,
      errorMessage: normalized.message,
      errorStack: normalized.stack,
    }
    const details = safeStringify(detailsPayload).slice(0, MAX_DETAILS_LENGTH)

    await sendOwnerErrorAlertEmail({
      source: options.source,
      message: normalized.message,
      userId: options.userId,
      userEmail: options.userEmail,
      count,
      details,
      recipientEmail: options.recipientEmail,
    })
  } catch (error) {
    console.error('❌ [ERROR REPORTER] Failed to report error:', error)
  }
}

export function calculateExerciseCalories(params: {
  met: number
  weightKg: number
  durationMinutes: number
}) {
  const durationHours = params.durationMinutes / 60
  return params.met * params.weightKg * durationHours
}

export function parseFitbitActivitiesToIngest(params: { date: string; payload: any }) {
  const items = Array.isArray(params.payload?.activities) ? params.payload.activities : []
  return items
    .map((a: any) => {
      const logId = a?.logId ?? a?.activityLogId ?? a?.id
      const deviceId = logId !== null && logId !== undefined ? String(logId) : ''
      const startTimeRaw = a?.startTime || a?.startDate || a?.originalStartTime
      const startTime = startTimeRaw ? new Date(String(startTimeRaw)) : null
      const durationMs = Number(a?.duration ?? a?.activeDuration ?? 0)
      const durationMinutes = Number.isFinite(durationMs) ? durationMs / 60000 : 0
      const calories = Number(a?.calories ?? a?.activityCalories ?? a?.caloriesOut ?? 0)
      const label = String(a?.activityName || a?.name || a?.activityTypeName || 'Fitbit activity')

      if (!deviceId) return null
      if (!Number.isFinite(durationMinutes) || durationMinutes <= 0) return null
      if (!Number.isFinite(calories) || calories <= 0) return null

      // Fitbit list can span multiple dates; filter to selected date when startTime is present.
      if (startTime && !Number.isNaN(startTime.getTime())) {
        const d = `${startTime.getFullYear()}-${String(startTime.getMonth() + 1).padStart(2, '0')}-${String(startTime.getDate()).padStart(2, '0')}`
        if (d !== params.date) return null
      }

      return {
        deviceId,
        startTime: startTime && !Number.isNaN(startTime.getTime()) ? startTime : null,
        durationMinutes,
        calories,
        label,
        raw: a,
      }
    })
    .filter(Boolean)
}

export function extractGarminWorkouts(payload: any) {
  const results: Array<{
    deviceId: string
    startTime: Date | null
    durationMinutes: number
    calories: number
    label: string
    raw: any
  }> = []

  const seen = new Set<string>()

  const visit = (node: any) => {
    if (!node) return
    if (Array.isArray(node)) {
      for (const item of node) visit(item)
      return
    }
    if (typeof node !== 'object') return

    const activityId = node.activityId ?? node.activitySummaryId ?? node.summaryId ?? node.id
    const durationSeconds = node.durationInSeconds ?? node.duration ?? node.activeDurationInSeconds ?? null
    const calories = node.activeKilocalories ?? node.totalKilocalories ?? node.calories ?? node.kilocalories ?? null
    const startSeconds = node.startTimeInSeconds ?? node.startTimeInMillis ?? null
    const startIso = node.startTime ?? node.startDate ?? null
    const labelRaw = node.activityName ?? node.activityType ?? node.sport ?? node.type ?? 'Garmin activity'

    const deviceId = activityId !== null && activityId !== undefined ? String(activityId) : ''
    const durationMinutes =
      Number.isFinite(Number(durationSeconds)) ? Number(durationSeconds) / 60 : 0
    const kcal = Number(calories)

    let startTime: Date | null = null
    if (Number.isFinite(Number(startSeconds)) && Number(startSeconds) > 0) {
      const millis = Number(startSeconds) > 9_999_999_999 ? Number(startSeconds) : Number(startSeconds) * 1000
      const dt = new Date(millis)
      startTime = Number.isNaN(dt.getTime()) ? null : dt
    } else if (startIso) {
      const dt = new Date(String(startIso))
      startTime = Number.isNaN(dt.getTime()) ? null : dt
    }

    if (deviceId && durationMinutes > 0 && kcal > 0) {
      const key = `${deviceId}:${startTime ? startTime.toISOString() : ''}:${Math.round(durationMinutes)}:${Math.round(kcal)}`
      if (!seen.has(key)) {
        seen.add(key)
        results.push({
          deviceId,
          startTime,
          durationMinutes,
          calories: kcal,
          label: String(labelRaw),
          raw: node,
        })
      }
    }

    for (const value of Object.values(node)) {
      visit(value)
    }
  }

  visit(payload)
  return results
}

import { prisma } from '@/lib/prisma'

export type HealthProfile = {
  weightKg: number | null
  heightCm: number | null
  ageYears: number | null
  primaryGoal: 'LOSE' | 'MAINTAIN' | 'GAIN' | 'SHRED' | null
  intensity: 'MILD' | 'STANDARD' | 'AGGRESSIVE' | null
  bodyType: 'ECTO' | 'MESO' | 'ENDO' | null
}

function calculateAgeYears(birthdate?: string | null): number | null {
  if (!birthdate) return null
  const [y, m, d] = birthdate.split('-').map((v) => parseInt(v, 10))
  if (!y || !m || !d) return null
  const today = new Date()
  let age = today.getFullYear() - y
  const monthDiff = today.getMonth() + 1 - m
  const dayDiff = today.getDate() - d
  if (monthDiff < 0 || (monthDiff === 0 && dayDiff < 0)) age -= 1
  if (!Number.isFinite(age) || age <= 0 || age > 110) return null
  return age
}

function mapGoal(choice?: string | null): HealthProfile['primaryGoal'] {
  const v = (choice || '').toLowerCase()
  if (v.includes('shred')) return 'SHRED'
  if (v.includes('lose')) return 'LOSE'
  if (v.includes('gain') || v.includes('bulk')) return 'GAIN'
  if (v.includes('maintain')) return 'MAINTAIN'
  return null
}

function mapIntensity(v?: string | null): HealthProfile['intensity'] {
  const raw = (v || '').toLowerCase()
  if (raw === 'mild') return 'MILD'
  if (raw === 'aggressive') return 'AGGRESSIVE'
  if (raw === 'standard') return 'STANDARD'
  return null
}

function mapBodyType(v: any): HealthProfile['bodyType'] {
  if (v === 'ECTOMORPH') return 'ECTO'
  if (v === 'MESOMORPH') return 'MESO'
  if (v === 'ENDOMORPH') return 'ENDO'
  return null
}

export async function getHealthProfileForUser(userId: string): Promise<HealthProfile> {
  const user = await prisma.user.findUnique({
    where: { id: userId },
    include: { healthGoals: { orderBy: { updatedAt: 'desc' } } },
  })

  if (!user) {
    return {
      weightKg: null,
      heightCm: null,
      ageYears: null,
      primaryGoal: null,
      intensity: null,
      bodyType: null,
    }
  }

  const profileInfoGoal = user.healthGoals.find((goal: any) => goal.name === '__PROFILE_INFO_DATA__')
  let dateOfBirth = ''
  try {
    const parsed = profileInfoGoal?.category ? JSON.parse(profileInfoGoal.category) : null
    if (parsed && typeof parsed?.dateOfBirth === 'string') dateOfBirth = parsed.dateOfBirth
  } catch {
    // ignore
  }

  const primaryGoalRecord = user.healthGoals.find((goal: any) => goal.name === '__PRIMARY_GOAL__')
  let goalChoice = ''
  let goalIntensity = ''
  try {
    const parsed = primaryGoalRecord?.category ? JSON.parse(primaryGoalRecord.category) : null
    if (parsed && typeof parsed?.goalChoice === 'string') goalChoice = parsed.goalChoice
    if (parsed && typeof parsed?.goalIntensity === 'string') goalIntensity = parsed.goalIntensity
  } catch {
    // ignore
  }

  return {
    weightKg: typeof user.weight === 'number' && Number.isFinite(user.weight) ? user.weight : null,
    heightCm: typeof user.height === 'number' && Number.isFinite(user.height) ? user.height : null,
    ageYears: calculateAgeYears(dateOfBirth),
    primaryGoal: mapGoal(goalChoice),
    intensity: mapIntensity(goalIntensity),
    bodyType: mapBodyType(user.bodyType),
  }
}

import { prisma } from '@/lib/prisma'
import { calculateExerciseCalories } from '@/lib/exercise/calories'
import { getHealthProfileForUser } from '@/lib/exercise/health-profile'

export type ExerciseIngestSource = 'FITBIT' | 'GARMIN' | 'APPLE_HEALTH'

export type IngestExerciseEntryInput = {
  userId: string
  source: ExerciseIngestSource
  deviceId: string
  localDate: string // YYYY-MM-DD
  startTime?: Date | null
  durationMinutes: number
  calories?: number | null
  met?: number | null
  label: string
  rawPayload?: any
}

export async function ingestExerciseEntry(input: IngestExerciseEntryInput) {
  const durationMinutes = Math.max(1, Math.min(24 * 60, Math.floor(input.durationMinutes)))
  const deviceCalories = Number(input.calories)
  const met = input.met !== null && input.met !== undefined ? Number(input.met) : null

  let calories =
    Number.isFinite(deviceCalories) && deviceCalories > 0 ? deviceCalories : null

  if (calories === null && met !== null && Number.isFinite(met) && met > 0) {
    const health = await getHealthProfileForUser(input.userId)
    if (health.weightKg) {
      calories = calculateExerciseCalories({
        met,
        weightKg: health.weightKg,
        durationMinutes,
      })
    }
  }

  if (calories === null || !Number.isFinite(calories) || calories <= 0) {
    return { created: false, entry: null as any }
  }

  const existing = await prisma.exerciseEntry.findFirst({
    where: { userId: input.userId, source: input.source, deviceId: input.deviceId },
  })

  const data = {
    userId: input.userId,
    localDate: input.localDate,
    startTime: input.startTime ?? null,
    durationMinutes,
    source: input.source,
    deviceId: input.deviceId,
    label: input.label,
    met: met !== null && Number.isFinite(met) && met > 0 ? met : 0,
    calories,
    rawPayload: input.rawPayload ?? null,
  } as const

  if (existing) {
    const entry = await prisma.exerciseEntry.update({
      where: { id: existing.id },
      data,
    })
    return { created: false, entry }
  }

  const entry = await prisma.exerciseEntry.create({ data })
  return { created: true, entry }
}

export function distanceBasedMet(params: { name: string; speedKmh: number }) {
  const n = (params.name || '').toLowerCase()
  const s = params.speedKmh
  if (!Number.isFinite(s) || s <= 0) return null

  if (n.includes('walk')) {
    if (s < 4) return 2.8
    if (s < 5.5) return 3.3
    if (s < 6.8) return 4.3
    return 6.5
  }

  if (n.includes('run') || n.includes('jog')) {
    if (s < 8.5) return 7.0
    if (s < 9.5) return 8.3
    if (s < 11.5) return 9.8
    return 11.5
  }

  if (n.includes('cycl') || n.includes('bike')) {
    if (s < 16) return 4.0
    if (s < 22) return 8.0
    return 10.0
  }

  return null
}

export function inferMetAndLabel(params: {
  exerciseName: string
  baseMet: number
  durationMinutes: number
  distanceKm?: number | null
}) {
  const durationMins = Math.max(1, Math.floor(params.durationMinutes))
  const distanceKm =
    params.distanceKm !== null && params.distanceKm !== undefined ? Number(params.distanceKm) : null

  let met = params.baseMet
  let label = params.exerciseName

  if (distanceKm && Number.isFinite(distanceKm) && distanceKm > 0) {
    const speedKmh = distanceKm / (durationMins / 60)
    const inferredMet = distanceBasedMet({ name: params.exerciseName, speedKmh })
    if (inferredMet) {
      met = inferredMet
      const lower = params.exerciseName.toLowerCase()
      const base =
        lower.includes('walk')
          ? 'Walking'
          : lower.includes('run') || lower.includes('jog')
          ? 'Running'
          : lower.includes('cycl') || lower.includes('bike')
          ? 'Cycling'
          : params.exerciseName
      label = `${base} (${Math.round(speedKmh * 10) / 10} km/h)`
    }
  }

  return { met, label, durationMinutes: durationMins }
}

function positiveNumber(value: unknown) {
  const parsed = Number(value)
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null
}

export function estimateVoiceExerciseDurationMinutes(params: {
  exerciseName?: unknown
  steps?: unknown
  caloriesKcal?: unknown
}) {
  const name = String(params.exerciseName || '').toLowerCase()
  const steps = positiveNumber(params.steps)
  const caloriesKcal = positiveNumber(params.caloriesKcal)

  if (steps) {
    const stepsPerMinute = /run|jog/.test(name) ? 160 : 100
    return Math.max(1, Math.min(24 * 60, Math.round(steps / stepsPerMinute)))
  }

  if (caloriesKcal) {
    const caloriesPerMinute = /run|jog/.test(name)
      ? 10
      : /cycl|bike|ride/.test(name)
      ? 8
      : /gym|strength|weight|workout/.test(name)
      ? 7
      : 5
    return Math.max(1, Math.min(24 * 60, Math.round(caloriesKcal / caloriesPerMinute)))
  }

  return null
}

