import { createCipheriv, createDecipheriv, createHash, randomBytes } from 'crypto'

const FILE_ALGORITHM = 'aes-256-gcm'
const FILE_IV_LENGTH = 12
const FILE_TAG_LENGTH = 16
const FILE_KEY_LENGTH = 32

function getFileKey(): Buffer {
  const masterKeyEnv = process.env.ENCRYPTION_MASTER_KEY
  if (!masterKeyEnv) {
    throw new Error('ENCRYPTION_MASTER_KEY environment variable is required')
  }

  try {
    const decoded = Buffer.from(masterKeyEnv, 'base64')
    if (decoded.length >= FILE_KEY_LENGTH) {
      return decoded.subarray(0, FILE_KEY_LENGTH)
    }
  } catch {
    // Fall back to hash-based key derivation below.
  }

  return createHash('sha256').update(masterKeyEnv).digest()
}

export function encryptBuffer(input: Buffer): {
  encrypted: Buffer
  iv: string
  tag: string
} {
  const iv = randomBytes(FILE_IV_LENGTH)
  const key = getFileKey()
  const cipher = createCipheriv(FILE_ALGORITHM, key, iv)

  const encrypted = Buffer.concat([cipher.update(input), cipher.final()])
  const tag = cipher.getAuthTag()

  return {
    encrypted,
    iv: iv.toString('hex'),
    tag: tag.toString('hex'),
  }
}

export function decryptBuffer(input: Buffer, ivHex: string, tagHex: string): Buffer {
  if (!ivHex || !tagHex) {
    throw new Error('Missing encryption metadata')
  }

  const iv = Buffer.from(ivHex, 'hex')
  const tag = Buffer.from(tagHex, 'hex')
  if (iv.length !== FILE_IV_LENGTH || tag.length !== FILE_TAG_LENGTH) {
    throw new Error('Invalid encryption metadata')
  }

  const key = getFileKey()
  const decipher = createDecipheriv(FILE_ALGORITHM, key, iv)
  decipher.setAuthTag(tag)
  return Buffer.concat([decipher.update(input), decipher.final()])
}

import { prisma } from '@/lib/prisma'

export interface FitbitTokens {
  access_token: string
  refresh_token: string
  expires_at: number | null
  token_type: string
}

/**
 * Get Fitbit account tokens for a user, refreshing if necessary
 */
export async function getFitbitTokens(userId: string): Promise<FitbitTokens | null> {
  // Find Fitbit account for user
  const fitbitAccount = await prisma.account.findFirst({
    where: {
      userId,
      provider: 'fitbit',
    },
  })

  if (!fitbitAccount || !fitbitAccount.access_token || !fitbitAccount.refresh_token) {
    return null
  }

  // Check if token needs refresh (expires within 5 minutes)
  const now = Math.floor(Date.now() / 1000)
  const expiresAt = fitbitAccount.expires_at || 0

  if (expiresAt - now < 300) {
    // Token expired or expiring soon, refresh it
    const refreshed = await refreshFitbitToken(fitbitAccount.refresh_token, userId)
    if (!refreshed) {
      return null
    }
    return refreshed
  }

  return {
    access_token: fitbitAccount.access_token,
    refresh_token: fitbitAccount.refresh_token,
    expires_at: fitbitAccount.expires_at,
    token_type: fitbitAccount.token_type || 'Bearer',
  }
}

/**
 * Refresh Fitbit access token
 */
async function refreshFitbitToken(
  refreshToken: string,
  userId: string
): Promise<FitbitTokens | null> {
  const clientId = process.env.FITBIT_CLIENT_ID
  const clientSecret = process.env.FITBIT_CLIENT_SECRET

  if (!clientId || !clientSecret) {
    console.error('❌ Fitbit credentials not configured')
    return null
  }

  try {
    const response = await fetch('https://api.fitbit.com/oauth2/token', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        Authorization: `Basic ${Buffer.from(`${clientId}:${clientSecret}`).toString('base64')}`,
      },
      body: new URLSearchParams({
        grant_type: 'refresh_token',
        refresh_token: refreshToken,
      }),
    })

    if (!response.ok) {
      const errorData = await response.text()
      console.error('❌ Fitbit token refresh failed:', errorData)
      return null
    }

    const tokens = await response.json()
    const expiresAt = tokens.expires_in
      ? Math.floor(Date.now() / 1000) + tokens.expires_in
      : null

    // Update tokens in database
    const fitbitAccount = await prisma.account.findFirst({
      where: {
        userId,
        provider: 'fitbit',
      },
    })

    if (fitbitAccount) {
      await prisma.account.update({
        where: { id: fitbitAccount.id },
        data: {
          access_token: tokens.access_token,
          refresh_token: tokens.refresh_token || refreshToken,
          expires_at: expiresAt,
          token_type: tokens.token_type,
        },
      })
    }

    return {
      access_token: tokens.access_token,
      refresh_token: tokens.refresh_token || refreshToken,
      expires_at: expiresAt,
      token_type: tokens.token_type,
    }
  } catch (error) {
    console.error('❌ Error refreshing Fitbit token:', error)
    return null
  }
}

/**
 * Make authenticated request to Fitbit API
 */
export async function fitbitApiRequest(
  userId: string,
  endpoint: string,
  options: RequestInit = {}
): Promise<Response | null> {
  const tokens = await getFitbitTokens(userId)
  if (!tokens) {
    return null
  }

  const url = endpoint.startsWith('http') ? endpoint : `https://api.fitbit.com${endpoint}`

  return fetch(url, {
    ...options,
    headers: {
      Authorization: `Bearer ${tokens.access_token}`,
      ...options.headers,
    },
  })
}

/**
 * Get Fitbit user ID for a user
 */
export async function getFitbitUserId(userId: string): Promise<string | null> {
  const fitbitAccount = await prisma.account.findFirst({
    where: {
      userId,
      provider: 'fitbit',
    },
  })

  return fitbitAccount?.providerAccountId || null
}

import { prisma } from '@/lib/prisma'

/**
 * Ensure the FitbitData table and required indexes exist.
 * Safe to run repeatedly; uses IF NOT EXISTS guards.
 */
export async function ensureFitbitDataSchema(): Promise<void> {
  try {
    // Create table
    await prisma.$executeRawUnsafe(`
      CREATE TABLE IF NOT EXISTS "FitbitData" (
        "id" TEXT NOT NULL,
        "userId" TEXT NOT NULL,
        "date" DATE NOT NULL,
        "dataType" TEXT NOT NULL,
        "value" JSONB NOT NULL,
        "syncedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
        "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
        "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
        CONSTRAINT "FitbitData_pkey" PRIMARY KEY ("id")
      );
    `)

    // FK to User
    await prisma.$executeRawUnsafe(`
      DO $$
      BEGIN
        IF NOT EXISTS (
          SELECT 1
          FROM information_schema.table_constraints tc
          WHERE tc.constraint_name = 'FitbitData_userId_fkey'
        ) THEN
          ALTER TABLE "FitbitData"
          ADD CONSTRAINT "FitbitData_userId_fkey"
          FOREIGN KEY ("userId") REFERENCES "User"("id")
          ON DELETE CASCADE ON UPDATE CASCADE;
        END IF;
      END $$;
    `).catch((err) => {
      // Constraint might already exist, ignore
      console.log('FK constraint check (non-fatal):', err?.message)
    })

    // Unique and indexes
    await prisma.$executeRawUnsafe(`
      DO $$
      BEGIN
        IF NOT EXISTS (
          SELECT 1
          FROM pg_indexes
          WHERE indexname = 'FitbitData_userId_date_dataType_key'
        ) THEN
          CREATE UNIQUE INDEX "FitbitData_userId_date_dataType_key"
          ON "FitbitData"("userId","date","dataType");
        END IF;
      END $$;
    `).catch((err) => {
      // Index might already exist, ignore
      console.log('Unique index check (non-fatal):', err?.message)
    })

    await prisma.$executeRawUnsafe(`
      CREATE INDEX IF NOT EXISTS "FitbitData_userId_date_idx" ON "FitbitData"("userId","date");
    `).catch((err) => {
      console.log('Index creation (non-fatal):', err?.message)
    })

    await prisma.$executeRawUnsafe(`
      CREATE INDEX IF NOT EXISTS "FitbitData_userId_dataType_idx" ON "FitbitData"("userId","dataType");
    `).catch((err) => {
      console.log('Index creation (non-fatal):', err?.message)
    })
  } catch (error: any) {
    console.error('❌ Error ensuring FitbitData schema:', error)
    console.error('Error message:', error?.message)
    console.error('Error code:', error?.code)
    // Re-throw so caller knows it failed
    throw new Error(`Failed to ensure FitbitData schema: ${error?.message || 'Unknown error'}`)
  }
}

