const normalizeFoodText = (value: string) =>
  String(value || '')
    .toLowerCase()
    .replace(/&/g, ' and ')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .replace(/\s+/g, ' ')

const isLikelyLiquidFoodName = (nameRaw: string | null | undefined) => {
  const label = normalizeFoodText(String(nameRaw || ''))
  if (!label) return false
  if (label.includes('milk chocolate')) return false
  if (/\b(chocolate|cocoa)\b/.test(label) && !/\b(chocolate milk|hot chocolate|milkshake|shake|smoothie|syrup)\b/.test(label)) {
    return false
  }
  const solidHints = [
    'bread',
    'cookie',
    'biscuit',
    'cracker',
    'cereal',
    'chips',
    'crisps',
    'popcorn',
    'powder',
    'mix',
    'bar',
    'cake',
    'brownie',
  ]
  if (solidHints.some((hint) => new RegExp(`\\b${hint}(?:s|es|ed)?\\b`).test(label))) return false
  const liquidHints = [
    'water',
    'milk',
    'juice',
    'coffee',
    'tea',
    'soda',
    'cola',
    'drink',
    'beverage',
    'smoothie',
    'shake',
    'milkshake',
    'broth',
    'stock',
    'soup',
    'oil',
    'vinegar',
    'sauce',
    'syrup',
  ]
  return liquidHints.some((hint) => new RegExp(`\\b${hint}(?:s|es)?\\b`).test(label))
}

const liquidDensityGramsPerMl = (nameRaw: string | null | undefined) =>
  liquidDensity(String(nameRaw || ''))

const OPENFOODFACTS_BASE_URL =
  process.env.OPENFOODFACTS_BASE_URL || 'https://world.openfoodfacts.org'

const OPENFOODFACTS_USER_AGENT =
  process.env.OPENFOODFACTS_USER_AGENT || 'helfi-app/1.0 (support@helfi.ai)'

const USDA_API_KEY = process.env.USDA_API_KEY
// Default to provided credentials if env vars are not set (per user request for FatSecret packaged lookups)
const FATSECRET_CLIENT_ID =
  process.env.FATSECRET_CLIENT_ID || ''
const FATSECRET_CLIENT_SECRET =
  process.env.FATSECRET_CLIENT_SECRET || ''

type TimeoutFetchInit = RequestInit & { timeoutMs?: number }

const buildScaledServingOption = (
  params: {
    fdcId: string
    idSuffix: string
    label: string
    grams: number | null
    ml: number | null
    unit: 'g' | 'ml' | 'oz'
    baseWeightGrams: number
    base: {
      calories: number | null
      protein_g: number | null
      carbs_g: number | null
      fat_g: number | null
      fiber_g: number | null
      sugar_g: number | null
    }
  },
): ServingOption | null => {
  const amount = params.grams ?? params.ml
  if (!Number.isFinite(Number(amount)) || Number(amount) <= 0) return null
  if (!Number.isFinite(Number(params.baseWeightGrams)) || params.baseWeightGrams <= 0) return null
  if (params.base.calories == null || !Number.isFinite(params.base.calories)) return null

  const factor = Number(amount) / params.baseWeightGrams
  return {
    id: `usda:${params.fdcId}:${params.idSuffix}`,
    label: params.label,
    serving_size: params.label,
    grams: params.grams,
    ml: params.ml,
    unit: params.unit,
    // These values may become the basis for another amount; display code rounds them.
    calories: params.base.calories * factor,
    protein_g: params.base.protein_g != null ? params.base.protein_g * factor : null,
    carbs_g: params.base.carbs_g != null ? params.base.carbs_g * factor : null,
    fat_g: params.base.fat_g != null ? params.base.fat_g * factor : null,
    fiber_g: params.base.fiber_g != null ? params.base.fiber_g * factor : null,
    sugar_g: params.base.sugar_g != null ? params.base.sugar_g * factor : null,
    source: 'usda',
  }
}

const appendOptionIfMissing = (options: ServingOption[], option: ServingOption | null) => {
  if (!option) return
  const key = `${normalizeFoodText(option.serving_size)}|${option.grams ?? ''}|${option.ml ?? ''}`
  const exists = options.some((existing) => {
    const existingKey = `${normalizeFoodText(existing.serving_size)}|${existing.grams ?? ''}|${existing.ml ?? ''}`
    return existingKey === key
  })
  if (!exists) options.push(option)
}

const appendLiquidServingOptions = (
  options: ServingOption[],
  fdcId: string,
  foodName: string,
  baseWeightGrams: number,
  base: Parameters<typeof buildScaledServingOption>[0]['base'],
) => {
  if (!isLikelyLiquidFoodName(foodName)) return
  const density = liquidDensityGramsPerMl(foodName)
  if (density == null) return
  const addMl = (idSuffix: string, label: string, ml: number) => {
    appendOptionIfMissing(
      options,
      buildScaledServingOption({
        fdcId,
        idSuffix,
        label,
        grams: ml * density,
        ml,
        unit: 'ml',
        baseWeightGrams,
        base,
      }),
    )
  }

  addMl('100ml', '100 ml', 100)
  addMl('250ml', '250 ml', 250)
  addMl('cup-240ml', '1 cup (240 ml)', 240)
  addMl('tbsp-15ml', '1 tbsp (15 ml)', 15)
}

const appendCommonFoodServingOptions = (
  options: ServingOption[],
  fdcId: string,
  foodName: string,
  baseWeightGrams: number,
  base: Parameters<typeof buildScaledServingOption>[0]['base'],
) => {
  if (isLikelyLiquidFoodName(foodName)) return
  const foodUnitGrams = getFoodUnitGrams(foodName)
  if (!foodUnitGrams) return

  const units: MeasurementUnit[] = [
    'piece-small',
    'piece-medium',
    'piece-large',
    'piece-extra-large',
    'egg-small',
    'egg-medium',
    'egg-large',
    'egg-extra-large',
    'half-cup',
    'cup',
  ]

  units.forEach((unit) => {
    const grams = Number(foodUnitGrams[unit])
    if (!Number.isFinite(grams) || grams <= 0) return
    const label = formatUnitLabel(unit, foodName, grams)
    appendOptionIfMissing(
      options,
      buildScaledServingOption({
        fdcId,
        idSuffix: `common-${unit}`,
        label,
        grams,
        ml: null,
        unit: 'g',
        baseWeightGrams,
        base,
      }),
    )
  })
}

function nowMs(): number {
  return Date.now()
}

async function fetchWithTimeout(url: string, init: TimeoutFetchInit = {}): Promise<Response> {
  const timeoutMs = typeof init.timeoutMs === 'number' && Number.isFinite(init.timeoutMs) ? init.timeoutMs : 3500
  const controller = new AbortController()
  const signal = init.signal

  const onAbort = () => {
    try {
      controller.abort()
    } catch {}
  }
  if (signal) {
    if (signal.aborted) {
      onAbort()
    } else {
      try {
        signal.addEventListener('abort', onAbort, { once: true })
      } catch {}
    }
  }

  const t = setTimeout(() => {
    try {
      controller.abort()
    } catch {}
  }, timeoutMs)

  try {
    const { timeoutMs: _timeoutMs, signal: _signal, ...rest } = init
    return await fetch(url, { ...rest, signal: controller.signal })
  } finally {
    clearTimeout(t)
    if (signal) {
      try {
        signal.removeEventListener('abort', onAbort)
      } catch {}
    }
  }
}

const parseNumber = foodNumberOrNull

export async function searchLocalFoods(
  query: string,
  opts: { pageSize?: number; sources?: string[]; mode?: 'prefix' | 'prefix-contains' } = {},
): Promise<NormalizedFoodItem[]> {
  const q = String(query || '').trim()
  if (!q) return []
  const pageSize = opts.pageSize ?? 10
  const sources = Array.isArray(opts.sources) && opts.sources.length > 0 ? opts.sources : null
  const mode = opts.mode || 'prefix-contains'

  try {
    const normalizePrefixToken = (value: string) =>
      value
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, ' ')
        .trim()
        .replace(/\s+/g, ' ')
    const singularizeToken = (value: string) => {
      const lower = value.toLowerCase()
      if (lower.endsWith('ies') && value.length > 4) return `${value.slice(0, -3)}y`
      if (
        lower.endsWith('es') &&
        value.length > 3 &&
        !lower.endsWith('ses') &&
        !lower.endsWith('xes') &&
        !lower.endsWith('zes') &&
        !lower.endsWith('ches') &&
        !lower.endsWith('shes')
      ) {
        return value.slice(0, -2)
      }
      if (lower.endsWith('s') && value.length > 3 && !lower.endsWith('ss')) return value.slice(0, -1)
      return value
    }
    const normalizedQuery = normalizePrefixToken(q)
    const rawTokens = normalizedQuery.split(' ').filter(Boolean)
    const toTitleCase = (value: string) => value.replace(/\b([a-z])/g, (match) => match.toUpperCase())
    // Packaged callers filter by every typed word after this query. Apply those
    // words before the row limit so broad brands cannot crowd out the product.
    const prefixTokens = rawTokens.length > 0 ? (mode === 'prefix' ? rawTokens : rawTokens.slice(0, 3)) : [normalizedQuery || q]
    const sourceFilter = sources ? { source: { in: sources } } : null

    // Word-prefix matching for USDA names like: "Squash, summer, zucchini, raw".
    // We keep DB search broad enough to find later words, then callers can still
    // apply strict "prefix only" filtering.
    const buildWordPrefixPatterns = (token: string) => {
      const t = String(token || '').trim()
      if (!t) return []
      const patterns = new Set<string>()
      patterns.add(` ${t}`)
      patterns.add(`, ${t}`)
      patterns.add(`(${t}`)
      patterns.add(`-${t}`)
      patterns.add(`/${t}`)
      return Array.from(patterns)
    }

    const buildTokenVariants = (token: string) => {
      const base = singularizeToken(token)
      const tokens = base && base !== token ? [token, base] : [token]
      const variants = new Set<string>()
      const add = (v: string) => {
        const t = String(v || '').trim()
        if (!t) return
        variants.add(t)
        variants.add(t.toUpperCase())
        variants.add(toTitleCase(t))
      }
      tokens.forEach(add)
      return Array.from(variants)
    }

    // For multi-word searches, require all words to match somewhere (AND),
    // otherwise big generic words like "potato" can crowd out "sweet potato".
    const isMultiToken = prefixTokens.length > 1

    const prefixFilter = (() => {
      if (prefixTokens.length === 0) return null
      if (!isMultiToken) {
        const tokenSet = new Set<string>()
        for (const token of prefixTokens) {
          buildTokenVariants(token).forEach((v) => tokenSet.add(v))
        }
        const prefixConditions = Array.from(tokenSet).flatMap((token) => [
          { name: { startsWith: token } },
          { brand: { startsWith: token } },
        ])
        return prefixConditions.length > 0 ? { OR: prefixConditions } : null
      }
      const tokenClauses = prefixTokens.map((token) => {
        const variants = buildTokenVariants(token)
        const patterns = variants.flatMap((v) => buildWordPrefixPatterns(v))
        const brandTokens = variants.filter((v) => String(v || '').trim().length >= 2)
        const conditions = [
          ...variants.map((v) => ({ name: { startsWith: v } })),
          ...variants.map((v) => ({ brand: { startsWith: v } })),
          ...patterns.map((pattern) => ({ name: { contains: pattern, mode: 'insensitive' as const } })),
          ...patterns.map((pattern) => ({ brand: { contains: pattern, mode: 'insensitive' as const } })),
          ...brandTokens.map((v) => ({ brand: { contains: v, mode: 'insensitive' as const } })),
        ]
        return conditions.length > 0 ? { OR: conditions } : {}
      })
      return tokenClauses.length > 0 ? { AND: tokenClauses } : null
    })()

    // Single-token searches still need a second pass to match later words
    // like "zuc" → "Squash, summer, zucchini...".
    const allowContains = !isMultiToken && mode !== 'prefix' && normalizedQuery.length >= 1
    const containsConditions = allowContains
      ? prefixTokens.flatMap((token) => {
          const variants = buildTokenVariants(token)
          const patterns = variants.flatMap((v) => buildWordPrefixPatterns(v))
          const brandTokens = variants.filter((v) => String(v || '').trim().length >= 2)
          return [
            ...patterns.map((pattern) => ({ name: { contains: pattern, mode: 'insensitive' as const } })),
            ...patterns.map((pattern) => ({ brand: { contains: pattern, mode: 'insensitive' as const } })),
            ...brandTokens.map((v) => ({ brand: { contains: v, mode: 'insensitive' as const } })),
          ]
        })
      : []

    const containsFilter = containsConditions.length > 0 ? { OR: containsConditions } : null
    const buildWhere = (filter: any, excludeIds?: string[]) => {
      const clauses = []
      if (sourceFilter) clauses.push(sourceFilter)
      if (filter) clauses.push(filter)
      if (excludeIds && excludeIds.length > 0) clauses.push({ id: { notIn: excludeIds } })
      if (clauses.length === 0) return {}
      if (clauses.length === 1) return clauses[0]
      return { AND: clauses }
    }

    const prefixRows = await prisma.foodLibraryItem.findMany({
      where: buildWhere(prefixFilter),
      take: pageSize,
      orderBy: { name: 'asc' },
    })

    const remaining = Math.max(0, pageSize - prefixRows.length)
    const prefixIds = prefixRows.map((row) => row.id)
    const containsRows =
      remaining > 0 && mode !== 'prefix' && containsFilter
        ? await prisma.foodLibraryItem.findMany({
            where: buildWhere(containsFilter, prefixIds),
            take: remaining,
            orderBy: { name: 'asc' },
          })
        : []

    const rows = [...prefixRows, ...containsRows]
    return rows.flatMap<NormalizedFoodItem>((row) => {
      const servingSize = usdaLibraryServingSize(row)
      if (servingSize == null) return []
      return [{
      source: 'usda',
      id: String(row.fdcId ?? row.id),
      name: row.name,
      brand: row.brand ?? undefined,
      serving_size: servingSize,
      calories: foodNumberOrNull(row.calories),
      protein_g: foodNumberOrNull(row.proteinG),
      carbs_g: foodNumberOrNull(row.carbsG),
      fat_g: foodNumberOrNull(row.fatG),
      fiber_g: foodNumberOrNull(row.fiberG),
      sugar_g: foodNumberOrNull(row.sugarG),
      }]
    })
  } catch (err) {
    console.warn('Local food search failed', err)
    return []
  }
}

function normalizeOpenFoodFactsProduct(product: any): NormalizedFoodItem | null {
  if (!product) return null
  const nutr = product.nutriments || {}

  const name: string =
    (product.product_name as string) ||
    (product.generic_name as string) ||
    (product.brands as string) ||
    (product.code as string) ||
    ''
  if (!name) return null

  const brand = (product.brands as string) || undefined

  return {
    source: 'openfoodfacts',
    id: String(product.code || product.id || name),
    name,
    brand,
    ...normalizeOffNutrition(product),
  }
}

export async function searchOpenFoodFactsByQuery(
  query: string,
  opts: { pageSize?: number; timeoutMs?: number } = {},
): Promise<NormalizedFoodItem[]> {
  const pageSize = opts.pageSize ?? 5
  const timeoutMs = Number.isFinite(Number(opts.timeoutMs)) ? Math.max(1000, Number(opts.timeoutMs)) : 3000
  if (!query.trim()) return []

  const params = new URLSearchParams({
    action: 'process',
    search_terms: query,
    search_simple: '1',
    json: '1',
    page_size: String(pageSize),
  })

  const url = `${openFoodFactsBaseUrl()}/cgi/search.pl?${params.toString()}`

  try {
    const res = await fetchWithTimeout(url, {
      headers: {
        'User-Agent': OPENFOODFACTS_USER_AGENT,
      },
      // keep timeouts modest to avoid blocking the analyzer too long
      cache: 'no-store',
      next: { revalidate: 0 },
      timeoutMs,
    })

    if (!res.ok) {
      console.warn('OpenFoodFacts search failed', res.status, await res.text())
      return []
    }

    const data = await res.json()
    const products: any[] = Array.isArray(data.products) ? data.products : []

    const normalized: NormalizedFoodItem[] = []
    for (const p of products) {
      const n = normalizeOpenFoodFactsProduct(p)
      if (n) {
        normalized.push(n)
      }
    }
    return normalized
  } catch (err) {
    console.warn('OpenFoodFacts API error', err)
    return []
  }
}

function openFoodFactsBaseUrl(): string {
  return OPENFOODFACTS_BASE_URL.replace(/\/$/, '')
}

// USDA FoodData Central

interface UsdaFoodNutrient {
  nutrientName?: string
  unitName?: string
  value?: number
  amount?: number
  nutrientId?: number
  nutrientNumber?: string
  nutrient?: {
    name?: string
    unitName?: string
    number?: string
    id?: number
  }
}

interface UsdaFood {
  fdcId: number
  description: string
  brandName?: string
  dataType?: string
  servingSize?: number
  servingSizeUnit?: string | { name?: string }
  foodNutrients?: UsdaFoodNutrient[]
  foodPortions?: Array<{
    gramWeight?: number
    modifier?: string
    portionDescription?: string
    measureUnit?: { name?: string }
  }>
}


function normalizeUsdaFood(food: UsdaFood): NormalizedFoodItem | null {
  if (!food || !food.description) return null
  const { energyKcal, protein, carbs, fat, fiber, sugar } = extractUsdaNutrients(food)
  const basis = usdaNutrientBasis(food)
  if (basis == null) return null

  return {
    source: 'usda',
    id: String(food.fdcId),
    name: food.description,
    brand: food.brandName,
    serving_size: `100 ${basis}`,
    calories: energyKcal,
    protein_g: protein,
    carbs_g: carbs,
    fat_g: fat,
    fiber_g: fiber,
    sugar_g: sugar,
  }
}

export async function fetchUsdaServingOptions(fdcId: string): Promise<ServingOption[]> {
  if (!USDA_API_KEY) {
    console.warn('USDA_API_KEY not configured; skipping USDA serving lookup')
    return []
  }
  if (!fdcId) return []

  const url = `https://api.nal.usda.gov/fdc/v1/food/${encodeURIComponent(fdcId)}?api_key=${USDA_API_KEY}`
  try {
    const res = await fetchWithTimeout(url, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
      },
      cache: 'no-store',
      next: { revalidate: 0 },
      timeoutMs: 3500,
    })

    if (!res.ok) {
      console.warn('USDA food detail failed', res.status, await res.text())
      return []
    }

    const food: UsdaFood = await res.json()
    const { energyKcal, protein, carbs, fat, fiber, sugar } = extractUsdaNutrients(food)
    if (energyKcal == null) return []
    const base = {
      calories: energyKcal,
      protein_g: protein,
      carbs_g: carbs,
      fat_g: fat,
      fiber_g: fiber,
      sugar_g: sugar,
    }
    if (!hasCoreFoodNutrition(base) || usdaNutrientBasis(food) == null) return []

    const baseWeightGrams = 100
    const options: ServingOption[] = usdaStandardServingOptions(food, fdcId)

    const foodName = String((food as any)?.description || (food as any)?.lowercaseDescription || '').trim()
    if (usdaNutrientBasis(food) === 'g') {
      appendLiquidServingOptions(options, fdcId, foodName, baseWeightGrams, base)
      appendCommonFoodServingOptions(options, fdcId, foodName, baseWeightGrams, base)
    }

    const deduped = new Map<string, ServingOption>()
    options.forEach((opt) => {
      const key = `${opt.serving_size}|${opt.grams || ''}`
      if (!deduped.has(key)) deduped.set(key, opt)
    })
    return Array.from(deduped.values())
  } catch (err) {
    console.warn('USDA serving lookup error', err)
    return []
  }
}

export async function searchUsdaFoods(
  query: string,
  opts: { pageSize?: number; dataType?: 'branded' | 'generic' | 'all' } = {},
): Promise<NormalizedFoodItem[]> {
  if (!USDA_API_KEY) {
    console.warn('USDA_API_KEY not configured; skipping USDA lookup')
    return []
  }
  const pageSize = opts.pageSize ?? 5
  const dataType = opts.dataType ?? 'all'
  const dataTypeParam =
    dataType === 'branded'
      ? 'Branded'
      : dataType === 'generic'
      ? ['Foundation', 'Survey (FNDDS)', 'SR Legacy'].join(',')
      : ['Foundation', 'Branded', 'Survey (FNDDS)', 'SR Legacy'].join(',')

  if (!query.trim()) return []

  const params = new URLSearchParams({
    api_key: USDA_API_KEY,
    query,
    pageSize: String(pageSize),
    dataType: dataTypeParam,
  })

  const url = `https://api.nal.usda.gov/fdc/v1/foods/search?${params.toString()}`

  try {
    const res = await fetchWithTimeout(url, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
      },
      cache: 'no-store',
      next: { revalidate: 0 },
      timeoutMs: 3500,
    })

    if (!res.ok) {
      console.warn('USDA search failed', res.status, await res.text())
      return []
    }

    const data = await res.json()
    const foods: UsdaFood[] = Array.isArray(data.foods) ? data.foods : []
    const out: NormalizedFoodItem[] = []
    for (const f of foods) {
