// FatSecret Platform API

interface FatSecretFood {
  food_id: string
  food_name: string
  food_type: string
  brand_name?: string
  food_description?: string
  servings?: {
    serving: FatSecretServing | FatSecretServing[]
  }
}

interface FatSecretServing {
  serving_id: string
  serving_description: string
  serving_url: string
  metric_serving_amount: string
  metric_serving_unit: string
  number_of_units: string
  measurement_description: string
  calories: string
  carbohydrate: string
  protein: string
  fat: string
  saturated_fat?: string
  polyunsaturated_fat?: string
  monounsaturated_fat?: string
  cholesterol?: string
  sodium?: string
  potassium?: string
  fiber?: string
  sugar?: string
}

interface FatSecretSearchResponse {
  foods?: {
    food?: FatSecretFood | FatSecretFood[]
    total_results?: string
    max_results?: string
    page_number?: string
  }
}

interface FatSecretFoodDetail {
  food?: FatSecretFood | null
}

function normalizeFatSecretFood(food: FatSecretFood): NormalizedFoodItem | null {
  if (!food || !food.food_name) return null

  // Use the first serving as default, or try to find a standard serving
  const rawServings = food.servings?.serving
  const servings = (Array.isArray(rawServings) ? rawServings : rawServings ? [rawServings] : [])
    .filter((serving) => ['calories', 'protein', 'carbohydrate', 'fat'].every((key) => foodNumberOrNull((serving as any)?.[key]) !== null))
  if (servings.length === 0) return null

  const lower = (v: any) => String(v || '').toLowerCase()
  const parseValue = (val: string | undefined): number | null => {
    return foodNumberOrNull(val)
  }
  const parseAmount = (val: string | undefined): number | null => parseValue(val)

  // Prefer real package servings over generic "100 g".
  const scoreServing = (s: any) => {
    let score = 0
    const measurement = lower(s?.measurement_description || s?.serving_description)
    const metricUnit = lower(s?.metric_serving_unit)
    const metricAmount = parseAmount(s?.metric_serving_amount)

    if (measurement.includes('100 g') || measurement.includes('100g')) score -= 10
    if (measurement.includes('serving')) score += 2

    // Common packaged units (biscuits, slices, pieces, bars, etc.)
    if (
      measurement.includes('biscuit') ||
      measurement.includes('cookie') ||
      measurement.includes('slice') ||
      measurement.includes('piece') ||
      measurement.includes('bar') ||
      measurement.includes('packet') ||
      measurement.includes('pack')
    ) {
      score += 6
    }

    // Prefer metric amounts that look like real servings (roughly 5g–150g).
    if (metricUnit === 'g' && metricAmount != null) {
      if (metricAmount >= 5 && metricAmount <= 150) score += 5
      if (metricAmount === 100) score -= 4
    }

    // Prefer explicit "1" unit servings when available.
    const numberOfUnits = parseAmount(s?.number_of_units)
    if (numberOfUnits != null) {
      if (numberOfUnits === 1) score += 2
      if (numberOfUnits > 1) score += 1
    }

    return score
  }

  const preferredServing = [...servings].sort((a, b) => scoreServing(b) - scoreServing(a))[0] || servings[0]

  const servingSizeBase =
    preferredServing.measurement_description || preferredServing.serving_description || '1 serving'
  const metricAmount = parseAmount(preferredServing.metric_serving_amount)
  const metricUnit = preferredServing.metric_serving_unit
  const servingSizeLabel =
    metricAmount != null &&
    metricAmount > 0 &&
    metricUnit &&
    typeof servingSizeBase === 'string' &&
    !/\b\d+(\.\d+)?\s*(g|ml)\b/i.test(servingSizeBase)
      ? `${servingSizeBase} (${metricAmount} ${metricUnit})`
      : servingSizeBase

  return {
    source: 'fatsecret',
    id: food.food_id,
    name: food.food_name,
    brand: food.brand_name || null,
    serving_size: servingSizeLabel,
    calories: parseValue(preferredServing.calories),
    protein_g: parseValue(preferredServing.protein),
    carbs_g: parseValue(preferredServing.carbohydrate),
    fat_g: parseValue(preferredServing.fat),
    fiber_g: parseValue(preferredServing.fiber),
    sugar_g: parseValue(preferredServing.sugar),
  }
}

let fatSecretTokenCacheByScope: Record<string, { token: string; expiresAtMs: number }> = {}

async function getFatSecretAccessToken(scope = 'basic'): Promise<string | null> {
  if (!FATSECRET_CLIENT_ID || !FATSECRET_CLIENT_SECRET) {
    console.warn('FatSecret credentials not configured')
    return null
  }

  const scopeKey = scope && String(scope).trim().length > 0 ? String(scope).trim() : 'basic'
  const cached = fatSecretTokenCacheByScope[scopeKey]
  if (cached && cached.token && nowMs() < cached.expiresAtMs - 10_000) {
    return cached.token
  }

  try {
    // FatSecret uses OAuth 2.0 client credentials flow
    const params = new URLSearchParams({
      grant_type: 'client_credentials',
      scope: scopeKey,
    })

    const auth = Buffer.from(`${FATSECRET_CLIENT_ID}:${FATSECRET_CLIENT_SECRET}`).toString('base64')

    const res = await fetchWithTimeout('https://oauth.fatsecret.com/connect/token', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        Authorization: `Basic ${auth}`,
      },
      body: params.toString(),
      cache: 'no-store',
      timeoutMs: 2500,
    })

    if (!res.ok) {
      const errorText = await res.text()
      console.warn('FatSecret token request failed', res.status, errorText.substring(0, 200))
      return null
    }

    const data = await res.json()
    const token = data.access_token || null
    const expiresInSecRaw = data.expires_in
    const expiresInSec =
      typeof expiresInSecRaw === 'number'
        ? expiresInSecRaw
        : typeof expiresInSecRaw === 'string'
        ? parseInt(expiresInSecRaw, 10)
        : NaN

    if (token) {
      // Default to 5 minutes if FatSecret doesn't return expires_in for some reason.
      const ttlMs = Number.isFinite(expiresInSec) && expiresInSec > 0 ? expiresInSec * 1000 : 5 * 60 * 1000
      // Keep a little safety margin so we don't reuse an expired token.
      fatSecretTokenCacheByScope[scopeKey] = { token, expiresAtMs: nowMs() + Math.max(30_000, ttlMs) }
    } else {
      delete fatSecretTokenCacheByScope[scopeKey]
    }
    return token
  } catch (err) {
    console.warn('FatSecret token error', err)
    return null
  }
}

async function fetchFatSecretFoodDetail(
  foodId: string,
  options: { accessToken?: string; timeoutMs?: number } = {},
): Promise<FatSecretFood | null> {
  if (!/^\d+$/.test(String(foodId))) return null
  const accessToken = options.accessToken || await getFatSecretAccessToken()
  if (!accessToken) return null
  try {
    const params = new URLSearchParams({
      method: 'food.get.v2',
      food_id: String(foodId),
      format: 'json',
    })
    const url = `https://platform.fatsecret.com/rest/server.api?${params.toString()}`

    const res = await fetchWithTimeout(url, {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${accessToken}`,
        'Content-Type': 'application/json',
      },
      cache: 'no-store',
      next: { revalidate: 0 },
      timeoutMs: options.timeoutMs ?? 3500,
    })

    if (!res.ok) {
      console.warn('FatSecret food.get.v2 failed', res.status)
      return null
    }

    const data: FatSecretFoodDetail = await res.json()
    const food = data.food
    if (!food || String(food.food_id) !== String(foodId) || !food.food_name) return null
    return food
  } catch {
    console.warn('FatSecret detail lookup failed')
    return null
  }
}

export async function fetchFatSecretServingOptions(foodId: string): Promise<ServingOption[]> {
  const food = await fetchFatSecretFoodDetail(foodId)
  if (!food?.servings?.serving) return []
  const servings = (Array.isArray(food.servings.serving) ? food.servings.serving : [food.servings.serving])
    .filter((serving) => ['calories', 'protein', 'carbohydrate', 'fat'].every((key) => foodNumberOrNull((serving as any)?.[key]) !== null))
  try {
    const options: ServingOption[] = []
    servings.forEach((serving: any, idx: number) => {
      const metricAmount = Number(serving?.metric_serving_amount)
      const metricUnit = String(serving?.metric_serving_unit || '').toLowerCase()
      const measurement = String(serving?.measurement_description || serving?.serving_description || 'Serving')
      const hasMetric = Number.isFinite(metricAmount) && metricAmount > 0 && metricUnit

      const grams = hasMetric && metricUnit === 'g' ? metricAmount : null
      const ml = hasMetric && metricUnit === 'ml' ? metricAmount : null
      const unit: 'g' | 'ml' | 'oz' | undefined =
        metricUnit === 'g' ? 'g' : metricUnit === 'ml' ? 'ml' : metricUnit === 'oz' ? 'oz' : undefined

      const label = hasMetric ? `${measurement} — ${metricAmount} ${metricUnit}` : measurement
      const parseValue = (val: string | undefined): number | null => {
        return foodNumberOrNull(val)
      }

      options.push({
        id: `fatsecret:${foodId}:${serving?.serving_id ?? idx}`,
        label,
        serving_size: label,
        grams,
        ml,
        unit,
        calories: parseValue(serving?.calories),
        protein_g: parseValue(serving?.protein),
        carbs_g: parseValue(serving?.carbohydrate),
        fat_g: parseValue(serving?.fat),
        fiber_g: parseValue(serving?.fiber),
        sugar_g: parseValue(serving?.sugar),
        source: 'fatsecret',
      })
    })

    return options
  } catch (err) {
    console.warn('FatSecret serving lookup error', err)
    return []
  }
}

export async function searchFatSecretFoods(
  query: string,
  opts: { pageSize?: number; timeoutMs?: number } = {},
): Promise<NormalizedFoodItem[]> {
  if (!FATSECRET_CLIENT_ID || !FATSECRET_CLIENT_SECRET) {
    console.warn('FatSecret credentials not configured; skipping FatSecret lookup')
    return []
  }

  const pageSize = Math.min(50, Math.max(1, Math.floor(Number(opts.pageSize) || 5)))
  const timeoutMs = Number.isFinite(Number(opts.timeoutMs)) ? Math.max(1000, Number(opts.timeoutMs)) : 3500
  if (!query.trim()) return []

  const accessToken = await getFatSecretAccessToken()
  if (!accessToken) {
    console.warn('Failed to obtain FatSecret access token')
    return []
  }

  try {
    const deadline = Date.now() + timeoutMs
    const params = new URLSearchParams({
      method: 'foods.search',
      search_expression: query,
      max_results: String(pageSize),
      format: 'json',
    })

    const url = `https://platform.fatsecret.com/rest/server.api?${params.toString()}`

    const res = await fetchWithTimeout(url, {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${accessToken}`,
        'Content-Type': 'application/json',
      },
      cache: 'no-store',
      next: { revalidate: 0 },
      timeoutMs,
    })

    if (!res.ok) {
      console.warn('FatSecret search failed', res.status)
      return []
    }

    const data: FatSecretSearchResponse = await res.json()
    const rawFoods = data.foods?.food
    const foods = (Array.isArray(rawFoods) ? rawFoods : rawFoods ? [rawFoods] : []).slice(0, pageSize)
    const resolved: Array<NormalizedFoodItem | null> = foods.map(() => null)
    let cursor = 0
    // Search v1 returns summaries, not serving nutrition. Resolve real detail
    // responses within the existing timeout, with at most four in flight.
    const worker = async () => {
      while (cursor < foods.length) {
        const index = cursor++
        const summary = foods[index]
        const remainingMs = deadline - Date.now()
        if (remainingMs <= 0) return
        const food = await fetchFatSecretFoodDetail(String(summary?.food_id || ''), { accessToken, timeoutMs: remainingMs })
        if (food) resolved[index] = normalizeFatSecretFood(food)
      }
    }
    await Promise.all(Array.from({ length: Math.min(4, foods.length) }, worker))
    return resolved.filter((item): item is NormalizedFoodItem => item !== null)
  } catch (err) {
    console.warn('FatSecret API error', err)
    return []
  }
}

export async function fetchFatSecretBrandList(
  startsWith: string,
  options?: { brandType?: string; region?: string; language?: string; limit?: number },
): Promise<string[]> {
  const prefix = String(startsWith || '').trim()
  if (prefix.length < 2) return []

  const accessToken = await getFatSecretAccessToken('premier')
  if (!accessToken) return []

  try {
    const params = new URLSearchParams({
      starts_with: prefix,
      format: 'json',
    })
    if (options?.brandType) params.set('brand_type', options.brandType)
    if (options?.region) params.set('region', options.region)
    if (options?.language) params.set('language', options.language)

    const url = `https://platform.fatsecret.com/rest/brands/v2?${params.toString()}`
    const res = await fetchWithTimeout(url, {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${accessToken}`,
        'Content-Type': 'application/json',
      },
      cache: 'no-store',
      timeoutMs: 2500,
    })

    if (!res.ok) {
      const text = await res.text()
      console.warn('FatSecret brands list failed', res.status, text.substring(0, 200))
      return []
    }

    const data = await res.json().catch(() => ({} as any))
    const raw =
      (data as any)?.food_brands?.food_brand ||
      (data as any)?.food_brands ||
      (data as any)?.brands ||
      []

    const list = Array.isArray(raw) ? raw : [raw]
    const names: string[] = []
    const seen = new Set<string>()

    const addName = (value: any) => {
      const name = String(value || '').trim()
      if (!name) return
      const key = name.toLowerCase()
      if (seen.has(key)) return
      seen.add(key)
      names.push(name)
    }

    list.forEach((item) => {
      if (!item) return
      if (typeof item === 'string') {
        addName(item)
        return
      }
      const candidate =
        (item as any).food_brand_name ||
        (item as any).brand_name ||
        (item as any).food_brand ||
        (item as any).name
      addName(candidate)
    })

    const limit = options?.limit && Number.isFinite(options.limit) ? Math.max(1, Math.min(options.limit, 50)) : 20
    return names.slice(0, limit)
  } catch (err) {
    console.warn('FatSecret brands list error', err)
    return []
  }
}

// Enhanced lookup function that tries multiple sources with fallback
export async function lookupFoodNutrition(
  query: string,
  options?: {
    preferSource?: 'usda' | 'fatsecret' | 'openfoodfacts'
    maxResults?: number
    usdaDataType?: 'branded' | 'generic' | 'all'
  },
): Promise<NormalizedFoodItem[]> {
  const maxResults = options?.maxResults ?? 3
  const preferSource = options?.preferSource || 'usda'
  const usdaDataType = options?.usdaDataType

  // Try sources in order of preference
  const sources: Array<() => Promise<NormalizedFoodItem[]>> = []

  if (preferSource === 'usda') {
    sources.push(() => searchUsdaFoods(query, { pageSize: maxResults, dataType: usdaDataType }))
    sources.push(() => searchFatSecretFoods(query, { pageSize: maxResults }))
  } else if (preferSource === 'fatsecret') {
    sources.push(() => searchFatSecretFoods(query, { pageSize: maxResults }))
    sources.push(() => searchUsdaFoods(query, { pageSize: maxResults, dataType: usdaDataType }))
  } else {
    // "openfoodfacts" is accepted for backwards-compat, but we no longer call OpenFoodFacts.
    sources.push(() => searchFatSecretFoods(query, { pageSize: maxResults }))
    sources.push(() => searchUsdaFoods(query, { pageSize: maxResults, dataType: usdaDataType }))
  }

  // Try each source until we get results
  for (const sourceFn of sources) {
    try {
      const results = await sourceFn()
      if (results && results.length > 0) {
        console.log(`✅ Found ${results.length} results from ${results[0].source} for query: ${query}`)
        return results
      }
    } catch (err) {
      console.warn(`⚠️ Source lookup failed, trying next:`, err)
      continue
    }
  }

  console.warn(`⚠️ No results found from any source for query: ${query}`)
  return []
}

import { prisma } from '@/lib/prisma'
import { calculateDailyTargets } from '@/lib/daily-targets'

export type MacroTotals = {
  calories: number | null
  protein_g: number | null
  carbs_g: number | null
  fat_g: number | null
  fiber_g: number | null
  sugar_g: number | null
}

export type MacroRemaining = {
  remaining: number
  remainingClamped: number
  overBy: number
}

export type FoodDiarySnapshot = {
  localDate: string
  tzOffsetMin: number
  totals: MacroTotals
  targets: MacroTotals
  remaining: Record<keyof MacroTotals, MacroRemaining | null>
  priority: {
    low: string[]
    nearCap: string[]
  }
  logCount: number
}

const DATE_RE = /^\d{4}-\d{2}-\d{2}$/

const toNumber = (value: any) => {
  const n = Number(value)
  return Number.isFinite(n) ? n : null
}

const round1 = (value: number | null) =>
  typeof value === 'number' && Number.isFinite(value) ? Math.round(value * 10) / 10 : null

const clampMin = (value: number, min: number) => Math.max(min, value)

const buildMacroTotals = (logs: Array<{ nutrients: any }>): MacroTotals => {
  const totals = { calories: 0, protein_g: 0, carbs_g: 0, fat_g: 0, fiber_g: 0, sugar_g: 0 }
  let counted = 0

  logs.forEach((log) => {
    const n = (log && log.nutrients && typeof log.nutrients === 'object') ? log.nutrients : {}
    const calories = toNumber(n.calories ?? n.energy_kcal ?? n.energy)
    const protein = toNumber(n.protein_g ?? n.protein)
    const carbs = toNumber(n.carbs_g ?? n.carbohydrates_g ?? n.carbohydrates ?? n.carbs)
    const fat = toNumber(n.fat_g ?? n.total_fat_g ?? n.fat)
    const fiber = toNumber(n.fiber_g ?? n.fiber)
    const sugar = toNumber(n.sugar_g ?? n.sugar)
    const hasAny =
      (calories ?? 0) > 0 ||
      (protein ?? 0) > 0 ||
      (carbs ?? 0) > 0 ||
      (fat ?? 0) > 0 ||
      (fiber ?? 0) > 0 ||
      (sugar ?? 0) > 0

    if (!hasAny) return
    counted += 1
    totals.calories += calories ?? 0
    totals.protein_g += protein ?? 0
    totals.carbs_g += carbs ?? 0
    totals.fat_g += fat ?? 0
    totals.fiber_g += fiber ?? 0
    totals.sugar_g += sugar ?? 0
  })

  return {
    calories: Math.round(totals.calories),
    protein_g: round1(totals.protein_g),
    carbs_g: round1(totals.carbs_g),
    fat_g: round1(totals.fat_g),
    fiber_g: round1(totals.fiber_g),
    sugar_g: round1(totals.sugar_g),
  }
}

const buildRemaining = (target: number | null, consumed: number | null) => {
  if (typeof target !== 'number' || !Number.isFinite(target) || target <= 0) return null
  const used = typeof consumed === 'number' && Number.isFinite(consumed) ? consumed : 0
  const remaining = target - used
  return {
    remaining: round1(remaining) ?? remaining,
    remainingClamped: round1(clampMin(remaining, 0)) ?? clampMin(remaining, 0),
    overBy: round1(clampMin(-remaining, 0)) ?? clampMin(-remaining, 0),
  }
}

const getExerciseCaloriesForDate = async (userId: string, date: string) => {
  const entries = await prisma.exerciseEntry.findMany({
    where: { userId, localDate: date },
    select: { calories: true },
  })
  if (!entries.length) return 0
  const totalCalories = entries.reduce((sum, entry) => sum + (Number(entry.calories) || 0), 0)
  if (!Number.isFinite(totalCalories) || totalCalories <= 0) return 0
  return Math.round(totalCalories)
}

const loadFoodLogsForDate = async (userId: string, date: string, tzOffsetMin: number) => {
  const [y, m, d] = date.split('-').map((v) => parseInt(v, 10))
  const start = new Date(Date.UTC(y, m - 1, d, 0, 0, 0) + tzOffsetMin * 60 * 1000)
  const end = new Date(start.getTime() + 24 * 60 * 60 * 1000 - 1)
  const logs = await prisma.foodLog.findMany({
    where: {
      userId,
      OR: [
        { localDate: date },
        { localDate: null, createdAt: { gte: start, lte: end } },
        { createdAt: { gte: start, lte: end } },
      ],
    },
    orderBy: { createdAt: 'desc' },
    select: { nutrients: true, localDate: true, createdAt: true },
  })

  const filtered = logs.filter((log) => {
    if (log.localDate === date) return true
    const createdAt = log.createdAt instanceof Date ? log.createdAt : new Date(log.createdAt as any)
    if (Number.isNaN(createdAt.getTime())) return false
    const local = new Date(createdAt.getTime() - tzOffsetMin * 60 * 1000)
    const iso = `${local.getUTCFullYear()}-${String(local.getUTCMonth() + 1).padStart(2, '0')}-${String(local.getUTCDate()).padStart(2, '0')}`
    return iso === date
  })

  return filtered
}

const buildTargetsForUser = (user: any) => {
  const profile = (() => {
    try {
      const stored = user.healthGoals?.find((g: any) => g?.name === '__PROFILE_INFO_DATA__')
      const parsed = stored?.category ? JSON.parse(stored.category) : null
      return parsed && typeof parsed === 'object' ? parsed : {}
    } catch {
      return {}
    }
  })()

  const primaryGoal = (() => {
    try {
      const stored = user.healthGoals?.find((g: any) => g?.name === '__PRIMARY_GOAL__')
      const parsed = stored?.category ? JSON.parse(stored.category) : null
      return parsed && typeof parsed === 'object' ? parsed : {}
    } catch {
      return {}
    }
  })()

  const selectedIssues = (() => {
    try {
      const stored = user.healthGoals?.find((g: any) => g?.name === '__SELECTED_ISSUES__')
      const parsed = stored?.category ? JSON.parse(stored.category) : null
      return Array.isArray(parsed) ? parsed.map((v: any) => String(v || '')).filter(Boolean) : []
    } catch {
      return []
    }
  })()

  const healthSituations = (() => {
    try {
      const stored = user.healthGoals?.find((g: any) => g?.name === '__HEALTH_SITUATIONS_DATA__')
      const parsed = stored?.category ? JSON.parse(stored.category) : null
      return parsed && typeof parsed === 'object' ? parsed : {}
    } catch {
      return {}
    }
  })()

  const allergySettings = (() => {
    try {
      const stored = user.healthGoals?.find((g: any) => g?.name === '__ALLERGIES_DATA__')
      const parsed = stored?.category ? JSON.parse(stored.category) : null
      return parsed && typeof parsed === 'object' ? parsed : { allergies: [], diabetesType: '' }
    } catch {
      return { allergies: [], diabetesType: '' }
    }
  })()

  const dietTypes = (() => {
    try {
      const stored = user.healthGoals?.find((g: any) => g?.name === '__DIET_PREFERENCE__')
      const parsed = stored?.category ? JSON.parse(stored.category) : null
      if (!parsed || typeof parsed !== 'object') return []
      const raw = Array.isArray((parsed as any).dietTypes) ? (parsed as any).dietTypes : (parsed as any).dietType
      if (Array.isArray(raw)) return raw.map((v: any) => String(v || '').trim()).filter(Boolean)
      if (typeof raw === 'string' && raw.trim()) return [raw.trim()]
      return []
    } catch {
      return []
    }
  })()

  const goalChoiceValue =
    typeof primaryGoal?.goalChoice === 'string' ? primaryGoal.goalChoice.toLowerCase() : ''
  const useManualTargets = goalChoiceValue.includes('lose') || goalChoiceValue.includes('gain')

  const targets = calculateDailyTargets({
    gender: user.gender ? String(user.gender).toLowerCase() : '',
    birthdate: typeof profile?.dateOfBirth === 'string' ? profile.dateOfBirth : '',
    weightKg: typeof user.weight === 'number' ? user.weight : null,
    heightCm: typeof user.height === 'number' ? user.height : null,
    exerciseFrequency: typeof user.exerciseFrequency === 'string' ? user.exerciseFrequency : '',
    dietTypes,
    goals: selectedIssues,
    goalChoice: typeof primaryGoal?.goalChoice === 'string' ? primaryGoal.goalChoice : '',
    goalIntensity:
      typeof primaryGoal?.goalIntensity === 'string' &&
      ['mild', 'standard', 'aggressive'].includes(primaryGoal.goalIntensity.toLowerCase())
        ? (primaryGoal.goalIntensity.toLowerCase() as any)
        : 'standard',
    calorieTarget: useManualTargets && typeof primaryGoal?.goalCalorieTarget === 'number' ? primaryGoal.goalCalorieTarget : null,
    macroSplit:
      useManualTargets && primaryGoal?.goalMacroSplit && typeof primaryGoal.goalMacroSplit === 'object'
        ? primaryGoal.goalMacroSplit
        : null,
    fiberTarget: useManualTargets && typeof primaryGoal?.goalFiberTarget === 'number' ? primaryGoal.goalFiberTarget : null,
    sugarMax: useManualTargets && typeof primaryGoal?.goalSugarMax === 'number' ? primaryGoal.goalSugarMax : null,
    bodyType: user.bodyType ? String(user.bodyType).toLowerCase() : '',
    diabetesType:
      typeof allergySettings?.diabetesType === 'string' &&
      ['type1', 'type2', 'prediabetes'].includes(allergySettings.diabetesType.toLowerCase())
        ? (allergySettings.diabetesType.toLowerCase() as any)
        : null,
    healthSituations: healthSituations as any,
  })

  return {
    calories: targets.calories ?? null,
    protein_g: targets.protein ?? null,
    carbs_g: targets.carbs ?? null,
    fat_g: targets.fat ?? null,
    fiber_g: typeof targets.fiber === 'number' ? targets.fiber : null,
    sugar_g: typeof targets.sugarMax === 'number' ? targets.sugarMax : null,
  } satisfies MacroTotals
}

export async function buildFoodDiarySnapshot(params: {
  userId: string
  localDate: string
  tzOffsetMin: number
}): Promise<FoodDiarySnapshot | null> {
  const { userId, localDate, tzOffsetMin } = params
  if (!DATE_RE.test(localDate)) return null

  const user = await prisma.user.findUnique({
    where: { id: userId },
    include: { healthGoals: { orderBy: { updatedAt: 'desc' } } },
  })
  if (!user) return null

  const [logs, targets] = await Promise.all([
    loadFoodLogsForDate(userId, localDate, tzOffsetMin),
    Promise.resolve(buildTargetsForUser(user)),
  ])

  const totalsRaw = buildMacroTotals(logs)
  const macroCalories =
    (totalsRaw.protein_g || 0) * 4 +
    (totalsRaw.carbs_g || 0) * 4 +
    (totalsRaw.fat_g || 0) * 9
  const totals: MacroTotals = {
    ...totalsRaw,
    calories:
      Number.isFinite(macroCalories) && macroCalories > 0
        ? Math.round(macroCalories)
        : totalsRaw.calories,
  }

  const exerciseCalories = await getExerciseCaloriesForDate(userId, localDate)
  const adjustedTargets: MacroTotals = { ...targets }
  if (exerciseCalories > 0) {
    if (typeof adjustedTargets.calories === 'number' && adjustedTargets.calories > 0) {
      adjustedTargets.calories = adjustedTargets.calories + exerciseCalories
    }

    const protein = Number(adjustedTargets.protein_g)
    const carbs = Number(adjustedTargets.carbs_g)
    const fat = Number(adjustedTargets.fat_g)
    if (Number.isFinite(protein) && Number.isFinite(carbs) && Number.isFinite(fat)) {
      if (protein > 0 && carbs > 0 && fat > 0) {
        const proteinCals = protein * 4
        const carbCals = carbs * 4
        const fatCals = fat * 9
        const totalMacroCals = proteinCals + carbCals + fatCals
        if (Number.isFinite(totalMacroCals) && totalMacroCals > 0) {
          const pShare = proteinCals / totalMacroCals
          const cShare = carbCals / totalMacroCals
          const fShare = fatCals / totalMacroCals
          adjustedTargets.protein_g = protein + (exerciseCalories * pShare) / 4
          adjustedTargets.carbs_g = carbs + (exerciseCalories * cShare) / 4
          adjustedTargets.fat_g = fat + (exerciseCalories * fShare) / 9
        }
      }
    }
  }

  const remaining = {
    calories: buildRemaining(adjustedTargets.calories, totals.calories),
    protein_g: buildRemaining(adjustedTargets.protein_g, totals.protein_g),
    carbs_g: buildRemaining(adjustedTargets.carbs_g, totals.carbs_g),
    fat_g: buildRemaining(adjustedTargets.fat_g, totals.fat_g),
    fiber_g: buildRemaining(adjustedTargets.fiber_g, totals.fiber_g),
    sugar_g: buildRemaining(adjustedTargets.sugar_g, totals.sugar_g),
  }

  const deficitCandidates: Array<{ key: string; ratio: number }> = []
  const nearCap: string[] = []
  const pushDeficit = (label: string, target: number | null, consumed: number | null) => {
    if (typeof target !== 'number' || !Number.isFinite(target) || target <= 0) return
    const used = typeof consumed === 'number' && Number.isFinite(consumed) ? consumed : 0
    const remainingValue = target - used
    if (remainingValue <= 0) {
      nearCap.push(label)
      return
    }
    const ratio = remainingValue / target
    if (ratio <= 0.12) {
      nearCap.push(label)
    }
    deficitCandidates.push({ key: label, ratio })
  }

  pushDeficit('Protein', adjustedTargets.protein_g, totals.protein_g)
  pushDeficit('Fiber', adjustedTargets.fiber_g, totals.fiber_g)
  pushDeficit('Carbs', adjustedTargets.carbs_g, totals.carbs_g)
  pushDeficit('Fat', adjustedTargets.fat_g, totals.fat_g)
  pushDeficit('Sugar', adjustedTargets.sugar_g, totals.sugar_g)
  pushDeficit('Calories', adjustedTargets.calories, totals.calories)

  const low = deficitCandidates
    .sort((a, b) => b.ratio - a.ratio)
    .map((entry) => entry.key)

  return {
    localDate,
    tzOffsetMin,
    totals,
    targets: adjustedTargets,
    remaining,
    priority: {
      low: low.slice(0, 3),
      nearCap: Array.from(new Set(nearCap)).slice(0, 3),
    },
    logCount: logs.length,
  }
}

export type HealthCheckFrequency = 'always' | 'high' | 'never'

export type HealthCheckSettings = {
  enabled: boolean
  frequency: HealthCheckFrequency
  dailyCap: number | null
  thresholds: {
    sugar: number | null
    carbs: number | null
    fat: number | null
  }
}

export const DEFAULT_HEALTH_CHECK_SETTINGS: HealthCheckSettings = {
  enabled: true,
  frequency: 'high',
  dailyCap: null,
  thresholds: {
    sugar: null,
    carbs: null,
    fat: null,
  },
}

const toOptionalNumber = (value: any) => {
  const n = Number(value)
  return Number.isFinite(n) && n > 0 ? n : null
}

const normalizeFrequency = (value: any): HealthCheckFrequency => {
  const raw = typeof value === 'string' ? value.toLowerCase().trim() : ''
  if (raw === 'always' || raw === 'never' || raw === 'high') return raw
  return 'high'
}

export const normalizeHealthCheckSettings = (raw: any): HealthCheckSettings => {
  if (!raw || typeof raw !== 'object') return { ...DEFAULT_HEALTH_CHECK_SETTINGS }
  const thresholds = raw?.thresholds && typeof raw.thresholds === 'object' ? raw.thresholds : {}
  return {
    enabled: raw?.enabled !== false,
    frequency: normalizeFrequency(raw?.frequency),
    dailyCap: toOptionalNumber(raw?.dailyCap),
    thresholds: {
      sugar: toOptionalNumber(thresholds?.sugar),
      carbs: toOptionalNumber(thresholds?.carbs),
      fat: toOptionalNumber(thresholds?.fat),
    },
  }
}

export const mergeHealthCheckSettings = (
  base: HealthCheckSettings,
  overrides?: Partial<HealthCheckSettings>,
) => ({
  ...base,
  ...(overrides || {}),
  thresholds: {
    ...base.thresholds,
    ...(overrides?.thresholds || {}),
  },
})

export const normalizeMealCategory = (raw: any): string | null => {
  const value = typeof raw === 'string' ? raw.toLowerCase() : ''
  if (/breakfast/.test(value)) return 'breakfast'
  if (/lunch/.test(value)) return 'lunch'
  if (/dinner/.test(value)) return 'dinner'
  if (/snack/.test(value)) return 'snacks'
  if (/uncat/.test(value) || /other/.test(value)) return 'uncategorized'
  if (typeof raw === 'string' && raw.trim()) return raw.trim()
  return null
}

type Basis = 'per_serving' | 'per_100g'
type EnergyUnit = 'kcal' | 'kJ' | null

export type NormalizedFoodInput = {
  source?: string | null
  id?: string | number | null
  name?: string | null
  brand?: string | null
  serving_size?: string | null
  servings?: number | null
  calories?: number | null
  protein_g?: number | null
  carbs_g?: number | null
  fat_g?: number | null
  fiber_g?: number | null
  sugar_g?: number | null
  barcode?: string | null
  basis?: Basis | null
  quantity_g?: number | null
  energyUnit?: EnergyUnit
  pieces?: number | null
  piecesPerServing?: number | null
}

const WORD_NUMBER_MAP: Record<string, string> = {
  one: '1',
  two: '2',
  three: '3',
  four: '4',
  five: '5',
  six: '6',
  seven: '7',
  eight: '8',
  nine: '9',
  ten: '10',
  eleven: '11',
  twelve: '12',
}

const DISCRETE_KEYWORDS = [
  'egg',
  'eggs',
  'patty',
  'pattie',
  'patties',
  'nugget',
  'nuggets',
  'wing',
  'wings',
  'drumstick',
  'drumsticks',
  'chicken leg',
  'chicken legs',
  'slice',
  'slices',
  'strip',
  'strips',
  'tender',
  'tenders',
  'bite',
  'bites',
  'piece',
  'pieces',
  'cookie',
  'cookies',
  'cracker',
  'crackers',
  'biscuit',
  'biscuits',
]

export const replaceWordNumbers = (text: string | null | undefined): string => {
  if (!text) return ''
  return String(text).replace(/\b(one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)\b/gi, (m) => {
    const repl = WORD_NUMBER_MAP[m.toLowerCase()]
    return repl || m
  })
}

export const parseCountFromText = (text: string | null | undefined): number | null => {
  if (!text) return null
  const normalized = replaceWordNumbers(String(text).toLowerCase()).replace(/\b(a|an)\b/g, '1')
  const stripped = normalized.replace(
    /\b\d+(?:\.\d+)?\s*(g|gram|grams|kg|ml|milliliter|millilitre|l|liter|litre|oz|ounce|ounces|lb|pound|pounds)\b/g,
    ' ',
  )
  const keywordPattern = DISCRETE_KEYWORDS.map((kw) => kw.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|')
  const match = stripped.match(
    new RegExp(`(\\d+(?:\\.\\d+)?)\\s*(?:x\\s*)?(?:[a-z-]+\\s+){0,2}(?:${keywordPattern})\\b`),
  )
  if (!match) return null
  const n = parseFloat(match[1])
  return Number.isFinite(n) && n > 0 ? n : null
}

const isProduceSliceLabel = (text: string): boolean => {
  const lower = (text || '').toLowerCase()
  if (!lower.includes('slice')) return false
  return (
    lower.includes('avocado') ||
    lower.includes('cucumber') ||
    lower.includes('tomato') ||
    lower.includes('zucchini') ||
    lower.includes('courgette')
  )
}

const isDiscreteLabel = (text: string | null | undefined): boolean => {
  if (!text) return false
  const lower = text.toLowerCase()
  // Sliced produce behaves like a portion (weight/servings), not a discrete piece count.
  if (isProduceSliceLabel(lower)) return false
  return DISCRETE_KEYWORDS.some((kw) => lower.includes(kw))
}

const parseGramWeight = (label: string | null | undefined): number | null => {
  if (!label) return null
  const normalized = replaceWordNumbers(label)
  const gMatch = normalized.match(/(\d+(?:\.\d+)?)\s*(g|gram|grams)/i)
  if (gMatch) return parseFloat(gMatch[1])
  const mlMatch = normalized.match(/(\d+(?:\.\d+)?)\s*(ml|milliliter|millilitre)/i)
  if (mlMatch) return parseFloat(mlMatch[1])
  const ozMatch = normalized.match(/(\d+(?:\.\d+)?)\s*(oz|ounce|ounces)/i)
  if (ozMatch) return parseFloat(ozMatch[1]) * 28.3495
  return null
}

const inferPiecesFromLabel = (name?: string | null, servingSize?: string | null): number | null => {
  const label = replaceWordNumbers([name, servingSize].filter(Boolean).join(' '))
  if (!label.trim()) return null

  // Prefer explicit parenthetical counts like "(6 crackers)" or "(3 pieces)"
  const paren = label.match(/\((\d+(?:\.\d+)?)\s*(?:pieces?|pcs|crackers?|cookies?|nuggets?|patt(?:y|ies)|slices?)\)/i)
  if (paren) {
    const val = parseFloat(paren[1])
    if (Number.isFinite(val) && val > 0) return val
  }

  const explicit = label.match(
    /(\d+(?:\.\d+)?)\s*(?:pieces?|pcs|crackers?|cookies?|nuggets?|patt(?:y|ies)|slices?|eggs?|bacon|rashers?|strips?|sausages?|links?|wings?|drumsticks?|tenders?|meatballs?|sticks?|bars?|bites?|biscuits?)/i,
  )
  if (explicit) {
    const val = parseFloat(explicit[1])
    if (Number.isFinite(val) && val > 0) return val
  }
  return null
}

export const normalizeDiscreteItemCounts = (
  item: any,
  options?: { analysisText?: string | null },
): { item: any; changed: boolean; debug?: any } => {
  if (!item || typeof item !== 'object') return { item, changed: false }

  const next = { ...item }
  const label = replaceWordNumbers([next.name, next.serving_size || next.servingSize].filter(Boolean).join(' ').trim())
  const isDiscrete = isDiscreteLabel(label)

  if (!isDiscrete) {
    return { item: next, changed: false }
  }

  const initialServings = Number.isFinite(Number(next.servings)) && Number(next.servings) > 0 ? Number(next.servings) : 1
  const existingPiecesPerServing =
    Number.isFinite(Number((next as any).piecesPerServing)) && Number((next as any).piecesPerServing) > 0
      ? Number((next as any).piecesPerServing)
      : null
  const inferredPieces = inferPiecesFromLabel(next.name, next.serving_size || (next as any).servingSize)
  const inferredFromAnalysis = options?.analysisText ? parseCountFromText(options.analysisText) : null

  let piecesPerServing = existingPiecesPerServing || inferredPieces || inferredFromAnalysis || null
  let servings = initialServings
  let changed = false

  // Plan rule: single discrete item with servings > 1 but no pieces → set piecesPerServing = servings, clamp servings = 1
  if (servings > 1 && !piecesPerServing) {
    piecesPerServing = servings
    servings = 1
    changed = true
  }

  // If analysis text suggests a larger count than the label, prefer the analysis hint.
  if (inferredFromAnalysis && (!piecesPerServing || inferredFromAnalysis > piecesPerServing)) {
    piecesPerServing = inferredFromAnalysis
    servings = 1
    changed = true
  }

  if (piecesPerServing && piecesPerServing > 0 && piecesPerServing !== existingPiecesPerServing) {
    ;(next as any).piecesPerServing = piecesPerServing
    changed = true
  }

  if (servings !== initialServings) {
    next.servings = servings
  }

  // Seed pieces for the UI if missing
  if (
    piecesPerServing &&
    (!Number.isFinite(Number((next as any).pieces)) || Number((next as any).pieces) <= 0)
  ) {
    ;(next as any).pieces = Math.max(1, Math.round(piecesPerServing * servings * 1000) / 1000)
    changed = true
  }

  return {
    item: next,
    changed,
    debug: {
      name: next.name,
      serving_size: next.serving_size,
      servings: next.servings,
      pieces: (next as any).pieces,
      piecesPerServing: (next as any).piecesPerServing,
      inferredPieces,
    },
  }
}

export const normalizeDiscreteItems = (
  items: any[],
  options?: { analysisText?: string | null },
): { items: any[]; changed: boolean; debug: any[] } => {
  if (!Array.isArray(items) || items.length === 0) return { items, changed: false, debug: [] }

  const normalized: any[] = []
  const debug: any[] = []
  let changed = false

  for (const item of items) {
    const { item: next, changed: itemChanged, debug: d } = normalizeDiscreteItemCounts(item, options)
    normalized.push(next)
    if (itemChanged) changed = true
    if (d) debug.push(d)
  }

  return { items: normalized, changed, debug }
}

export const normalizeBarcodeFood = (food: NormalizedFoodInput): { food: NormalizedFoodInput; debug: any } => {
  const next: NormalizedFoodInput = { ...food }
  let calories = Number.isFinite(Number(next.calories)) ? Number(next.calories) : null
  let protein = Number.isFinite(Number(next.protein_g)) ? Number(next.protein_g) : null
  let carbs = Number.isFinite(Number(next.carbs_g)) ? Number(next.carbs_g) : null
  let fat = Number.isFinite(Number(next.fat_g)) ? Number(next.fat_g) : null
  let fiber = Number.isFinite(Number(next.fiber_g)) ? Number(next.fiber_g) : null
  let sugar = Number.isFinite(Number(next.sugar_g)) ? Number(next.sugar_g) : null

  const quantityG = Number.isFinite(Number(next.quantity_g)) && Number(next.quantity_g) > 0 ? Number(next.quantity_g) : parseGramWeight(next.serving_size)
  const energyUnit: EnergyUnit = next.energyUnit || null

  // Normalize energy to kcal (heuristic: values > 4000 likely kJ)
  let convertedFromKJ = false
  if (energyUnit === 'kJ' && calories !== null) {
    calories = Math.round((calories as number) / 4.184)
    convertedFromKJ = true
  } else if (calories !== null && calories > 4000) {
    calories = Math.round(calories / 4.184)
    convertedFromKJ = true
  }

  // Scale from per-100g to per-serving if possible
  if (next.basis === 'per_100g' && quantityG && quantityG > 0) {
    const factor = quantityG / 100
    const scale = (v: number | null) => (Number.isFinite(Number(v)) ? Math.round(Number(v) * factor * 1000) / 1000 : null)
    calories = scale(calories)
    protein = scale(protein)
    carbs = scale(carbs)
    fat = scale(fat)
    fiber = scale(fiber)
    sugar = scale(sugar)
  }

  next.calories = calories
  next.protein_g = protein
  next.carbs_g = carbs
  next.fat_g = fat
  next.fiber_g = fiber
  next.sugar_g = sugar
  next.servings = 1

  // Pieces inference for discrete packaged foods
  const inferredPieces = inferPiecesFromLabel(next.name, next.serving_size)
  if (inferredPieces && inferredPieces > 0) {
    next.piecesPerServing = inferredPieces
    next.pieces = inferredPieces
  }

  return {
    food: next,
    debug: {
      source: next.source,
      serving_size: next.serving_size,
      basis: next.basis || null,
      quantity_g: quantityG || null,
      calories,
      protein,
      carbs,
      fat,
      fiber,
      sugar,
      convertedFromKJ,
      inferredPieces: next.piecesPerServing || null,
    },
  }
}

export const summarizeDiscreteItemsForLog = (items: any[]) =>
  Array.isArray(items)
    ? items
        .filter((it) => isDiscreteLabel(`${it?.name || ''} ${it?.serving_size || ''}`))
        .slice(0, 6)
        .map((it) => ({
          name: it?.name,
          serving_size: it?.serving_size,
          servings: it?.servings,
          pieces: (it as any)?.pieces,
          piecesPerServing: (it as any)?.piecesPerServing,
        }))
    : []

import { del } from '@vercel/blob'
import { prisma } from '@/lib/prisma'
import { extractBlobPathWithPrefixes } from '@/lib/blob-paths'

const FOOD_PHOTO_PREFIX = 'food-photos/'
const FOOD_PHOTO_PREFIXES = [FOOD_PHOTO_PREFIX]

const normalizeFoodPhotoPath = (value: string) =>
  extractBlobPathWithPrefixes(value, FOOD_PHOTO_PREFIXES)

const chunk = <T,>(items: T[], size: number) => {
  const result: T[][] = []
  for (let i = 0; i < items.length; i += size) {
    result.push(items.slice(i, i + size))
  }
  return result
}

export const deleteFoodPhotosIfUnused = async (
  urls: Array<string | null | undefined>,
) => {
  if (!process.env.BLOB_READ_WRITE_TOKEN) return { deleted: 0, skipped: 0 }

  const parsed = urls
    .filter((url): url is string => typeof url === 'string' && url.trim().length > 0)
    .map((url) => {
      const trimmed = url.trim()
      return {
        raw: trimmed,
        path: normalizeFoodPhotoPath(trimmed),
      }
    })
    .filter((item) => item.path)

  const candidates = Array.from(new Set(parsed.map((item) => item.path!)))

  if (candidates.length === 0) return { deleted: 0, skipped: 0 }

  const usageKeys = Array.from(
    new Set(parsed.flatMap((item) => (item.raw ? [item.raw, item.path!] : [item.path!]))),
  )
  const stillUsed = await prisma.foodLog.findMany({
    where: { imageUrl: { in: usageKeys } },
    select: { imageUrl: true },
  })
  const stillUsedSet = new Set(
    stillUsed.map((row) => row.imageUrl).filter((url): url is string => typeof url === 'string'),
  )
  Array.from(stillUsedSet).forEach((value) => {
    const path = normalizeFoodPhotoPath(value)
    if (path) stillUsedSet.add(path)
  })

  const toDelete = candidates.filter((path) => !stillUsedSet.has(path))
  if (toDelete.length === 0) return { deleted: 0, skipped: candidates.length }

  const batches = chunk(toDelete, 100)
  for (const batch of batches) {
    if (batch.length === 0) continue
    await del(batch)
  }

  return { deleted: toDelete.length, skipped: candidates.length - toDelete.length }
}

export const normalizeText = (value: string) =>
  String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .replace(/\s+/g, ' ')

export const buildCustomFoodKey = (params: {
  name: string
  brand?: string | null
  kind: string
  country?: string | null
}) => {
  const base = `${params.brand ? `${params.brand} ` : ''}${params.name}`.trim()
  const country = params.country ? normalizeText(params.country) : ''
  const suffix = country ? `|${country}` : ''
  return `${normalizeText(base)}|${params.kind}${suffix}`.trim()
}

const normalizeBrandAlias = (brand: string) => {
  const compact = brand.replace(/[^a-z0-9]+/gi, ' ').trim()
  const noPunct = brand.replace(/[^a-z0-9]+/gi, '').trim()
  const variants = new Set<string>()
  if (compact && compact !== brand) variants.add(compact)
  if (noPunct && noPunct !== brand && noPunct !== compact) variants.add(noPunct)
  if (brand.toLowerCase().includes('&')) {
    const replaced = brand.replace(/&/g, 'and')
    variants.add(replaced)
    const replacedCompact = replaced.replace(/[^a-z0-9]+/gi, ' ').trim()
    if (replacedCompact) variants.add(replacedCompact)
  }
  return Array.from(variants)
}

export const buildCustomFoodAliases = (name: string, brand?: string | null) => {
  const aliases: string[] = []
  if (brand) {
    aliases.push(`${name} (${brand})`)
    aliases.push(`${brand} ${name}`)
    normalizeBrandAlias(brand).forEach((variant) => {
      aliases.push(`${name} (${variant})`)
      aliases.push(`${variant} ${name}`)
    })
  }
  return Array.from(new Set(aliases.filter(Boolean)))
}

import 'server-only'
import { prisma } from '@/lib/prisma'
import { buildCustomFoodServingOptions } from '@/lib/food/custom-serving-options'

export type CustomFoodMacro = {
  id?: string
  name: string
  calories: number | null
  protein_g: number | null
  carbs_g: number | null
  fat_g: number | null
  fiber_g: number | null
  sugar_g: number | null
  brand?: string | null
  country?: string | null
  kind?: 'SINGLE' | 'PACKAGED' | 'FAST_FOOD'
  aliases?: string[]
  servingOptions?: any[] | null
}

let cachedItems: CustomFoodMacro[] | null = null
let cacheLoadedAt = 0
const CACHE_TTL_MS = 5 * 60 * 1000

const normalizeText = (value: string) =>
  String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .replace(/\s+/g, ' ')

const singularizeToken = (value: string) => {
  const lower = value.toLowerCase()
  if (lower.endsWith('ies') && value.length > 4) return `${value.slice(0, -3)}y`
  if (
    lower.endsWith('es') &&
    value.length > 3 &&
    !lower.endsWith('ses') &&
    !lower.endsWith('xes') &&
    !lower.endsWith('zes') &&
    !lower.endsWith('ches') &&
    !lower.endsWith('shes')
  ) {
    return value.slice(0, -2)
  }
  if (lower.endsWith('s') && value.length > 3 && !lower.endsWith('ss')) return value.slice(0, -1)
  return value
}

const getTokens = (value: string) => normalizeText(value).split(' ').filter(Boolean)

const isOneEditAway = (a: string, b: string) => {
  const lenA = a.length
  const lenB = b.length
  if (Math.abs(lenA - lenB) > 1) return false
  if (lenA === lenB) {
    let mismatches = 0
    for (let i = 0; i < lenA; i += 1) {
      if (a[i] !== b[i]) {
        mismatches += 1
        if (mismatches > 1) return false
      }
    }
    return mismatches <= 1
  }
  const shorter = lenA < lenB ? a : b
  const longer = lenA < lenB ? b : a
  let i = 0
  let j = 0
  let edits = 0
  while (i < shorter.length && j < longer.length) {
    if (shorter[i] === longer[j]) {
      i += 1
      j += 1
      continue
    }
    edits += 1
    if (edits > 1) return false
    j += 1
  }
  return true
}

// Strip parentheses and their content to prevent synonym matching
const stripParentheses = (text: string) => {
  return text.replace(/\s*\([^)]*\)/g, '').trim()
}

const nameMatchesQuery = (name: string, query: string, options?: { allowTypo?: boolean }) => {
  const normalizedQuery = normalizeText(query)
  if (!normalizedQuery) return false

  // Strip parentheses from name to prevent matching via synonyms
  const nameWithoutParentheses = stripParentheses(name)
  const nameTokens = getTokens(nameWithoutParentheses)

  if (normalizedQuery.length === 1) {
    // Single letter: first word must start with it
    if (nameTokens.length === 0) return false
    const firstWord = nameTokens[0]
    return firstWord.startsWith(normalizedQuery)
  }

  const queryTokens = getTokens(query).filter((token) => token.length >= 2)
  const filteredNameTokens = nameTokens.filter((token) => token.length >= 1)
  if (queryTokens.length === 0 || filteredNameTokens.length === 0) return false

  // For single-word queries: FIRST word must match (strict prefix matching)
  if (queryTokens.length === 1) {
    const queryToken = queryTokens[0]
    const firstWord = filteredNameTokens[0]
    if (!firstWord) return false

    // Exact word match (egg = egg, eggs = eggs)
    if (firstWord === queryToken) return true

    // Singular/plural exact matches only (eggs = egg, but NOT eggs = eggplant)
    const firstWordSingular = singularizeToken(firstWord)
    const querySingular = singularizeToken(queryToken)

    // Exact singular match: "eggs" matches "egg" exactly, "egg" matches "eggs" exactly
    if (firstWordSingular === querySingular) {
      // Both are the same after singularization - this is an exact match
      return true
    }

    // Prefix match: first word must START with the FULL query token
    // This allows "egg" to match "eggplant" but NOT "eggs" to match "eggplant"
    // (because "eggplant" doesn't start with "eggs", only with "egg")
    if (firstWord.startsWith(queryToken)) return true

    // Typo tolerance: only if first letter matches and it's a prefix match
    const allowTypo = (options?.allowTypo ?? true) && queryToken.length >= 3 && queryToken[0] === firstWord[0]
    if (allowTypo) {
      const prefixSame = firstWord.slice(0, queryToken.length)
      if (prefixSame && isOneEditAway(queryToken, prefixSame)) return true
      const prefixLonger = firstWord.slice(0, queryToken.length + 1)
      if (prefixLonger && isOneEditAway(queryToken, prefixLonger)) return true
    }

    // Predictive fallback: allow matching on later words for short typed queries
    // (e.g. "blu" should match "Cheese, blue").
    if (queryToken.length >= 2) {
      const queryTokenSingular = singularizeToken(queryToken)
      const otherWords = filteredNameTokens.slice(1)
      const laterWordMatches = otherWords.some((word) => {
        if (!word) return false
        if (word.startsWith(queryToken)) return true
        const singularWord = singularizeToken(word)
        if (singularWord !== word && singularWord.startsWith(queryToken)) return true
        if (queryTokenSingular !== queryToken && word.startsWith(queryTokenSingular)) return true
        if (
          queryTokenSingular !== queryToken &&
          singularWord !== word &&
          singularWord.startsWith(queryTokenSingular)
        ) {
          return true
        }
        return false
      })
      if (laterWordMatches) return true
    }

    return false
  }

  // Multi-word queries: token matching is order-independent.
  // This allows searches like "blue cheese" to match names like "Cheese, blue".
  const tokenMatches = (token: string, word: string) => {
    if (!token || !word) return false
    if (word.startsWith(token)) return true
    const singularWord = singularizeToken(word)
    if (singularWord !== word && singularWord.startsWith(token)) return true
    const singularToken = singularizeToken(token)
    if (singularToken !== token && word.startsWith(singularToken)) return true
    if (singularToken !== token && singularWord !== word && singularWord.startsWith(singularToken)) return true
    return false
  }

  const allTokensMatchAnywhere = queryTokens.every((token) =>
    filteredNameTokens.some((word) => tokenMatches(token, word)),
  )

  if (!allTokensMatchAnywhere) return false

  // Ranking still prefers first-word matches elsewhere.
  return true
}

const loadCustomFoods = async () => {
  if (cachedItems && Date.now() - cacheLoadedAt < CACHE_TTL_MS) return cachedItems
  const rows = await prisma.customFoodItem.findMany()
  const items: CustomFoodMacro[] = rows.map((row) => {
    const storedServingOptions = Array.isArray(row.servingOptions) ? row.servingOptions : []
    const generatedServingOptions =
      storedServingOptions.length > 0
        ? storedServingOptions
        : buildCustomFoodServingOptions({
            name: row.name,
            kind: row.kind,
            caloriesPer100g: row.caloriesPer100g,
            proteinPer100g: row.proteinPer100g,
            carbsPer100g: row.carbsPer100g,
            fatPer100g: row.fatPer100g,
            fiberPer100g: row.fiberPer100g,
            sugarPer100g: row.sugarPer100g,
          })
    const servingOptions = generatedServingOptions.length > 0 ? generatedServingOptions : null
    return {
      id: row.id,
      name: row.name,
      brand: row.brand ?? null,
      country: row.country ?? null,
      kind: row.kind as CustomFoodMacro['kind'],
      calories: row.caloriesPer100g ?? null,
      protein_g: row.proteinPer100g ?? null,
      carbs_g: row.carbsPer100g ?? null,
      fat_g: row.fatPer100g ?? null,
      fiber_g: row.fiberPer100g ?? null,
      sugar_g: row.sugarPer100g ?? null,
      aliases: Array.isArray(row.aliases) ? row.aliases : [],
      servingOptions,
    }
  })
  cachedItems = items
  cacheLoadedAt = Date.now()
  return items
}

export const searchCustomFoodMacros = async (
  query: string,
  limit = 10,
  options?: { allowTypo?: boolean; country?: string | null },
): Promise<CustomFoodMacro[]> => {
  const q = String(query || '').trim()
  if (!q) return []
  const matchCountry = String(options?.country || '').trim().toUpperCase()
  const allItems = (await loadCustomFoods()).filter((item) => item.kind === 'SINGLE' || !item.kind)
  const buildKey = (item: CustomFoodMacro) =>
    `${normalizeText(item.name)}|${normalizeText(item.brand || '')}`

  const items = (() => {
    if (!matchCountry) return allItems
    const exact = allItems.filter((item) => String(item.country || '').trim().toUpperCase() === matchCountry)
    if (exact.length === 0) {
      return allItems.filter((item) => {
        const itemCountry = String(item.country || '').trim().toUpperCase()
        return !itemCountry || itemCountry === matchCountry
      })
    }
    const exactKeys = new Set(exact.map(buildKey))
    const fallback = allItems.filter((item) => {
      const itemCountry = String(item.country || '').trim().toUpperCase()
      if (itemCountry && itemCountry !== matchCountry) return false
      if (!itemCountry) return !exactKeys.has(buildKey(item))
      return itemCountry === matchCountry
    })
    return [...exact, ...fallback]
  })()
  if (items.length === 0) return []

  const allowTypo = options?.allowTypo ?? true
  const matchesQuery = (item: CustomFoodMacro, strict: boolean) => {
    const allow = strict ? false : allowTypo
    if (nameMatchesQuery(item.name, q, { allowTypo: allow })) return true
    if (item.brand && nameMatchesQuery(`${item.brand} ${item.name}`, q, { allowTypo: allow })) return true
    const aliases = Array.isArray(item.aliases) ? item.aliases : []
    return aliases.some((alias) => nameMatchesQuery(String(alias || ''), q, { allowTypo: allow }))
  }

  const prefixMatches = items.filter((item) => matchesQuery(item, true))
  const base = prefixMatches.length > 0 || !allowTypo ? prefixMatches : items.filter((item) => matchesQuery(item, false))
  const matches = base.sort((a, b) => normalizeText(a.name).localeCompare(normalizeText(b.name)))
  if (matches.length === 0) return []
  return matches.slice(0, Math.max(1, limit))
}

export const getCustomPackagedItems = async (country?: string | null): Promise<CustomFoodMacro[]> => {
  const matchCountry = String(country || '').trim().toUpperCase()
  const allItems = (await loadCustomFoods()).filter(
    (item) => item.kind === 'PACKAGED' || item.kind === 'FAST_FOOD',
  )
  const buildKey = (item: CustomFoodMacro) =>
    `${normalizeText(item.name)}|${normalizeText(item.brand || '')}`

  if (!matchCountry) return allItems

  const exact = allItems.filter((item) => String(item.country || '').trim().toUpperCase() === matchCountry)
  if (exact.length === 0) {
    return allItems.filter((item) => {
      const itemCountry = String(item.country || '').trim().toUpperCase()
      return !itemCountry || itemCountry === matchCountry
    })
  }

  const exactKeys = new Set(exact.map(buildKey))
  const fallback = allItems.filter((item) => {
    const itemCountry = String(item.country || '').trim().toUpperCase()
    if (itemCountry && itemCountry !== matchCountry) return false
    // Anything with an exact country match is already in `exact` above.
    if (itemCountry === matchCountry) return false
    // For global items (no country), keep only those that don't duplicate an exact match.
    if (!itemCountry) return !exactKeys.has(buildKey(item))
    return false
  })

  return [...exact, ...fallback]
}

/** Compare saved nutrient content without depending on object property order. */
const canonicalContent = (value: unknown): unknown => {
  if (Array.isArray(value)) return value.map(canonicalContent)
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value)
      .filter(([, item]) => item !== undefined)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([key, item]) => [key, canonicalContent(item)]))
  }
  return value
}

export const hasSameDiaryNutrientContent = (a: any, b: any): boolean =>
  JSON.stringify(canonicalContent({ nutrition: a?.nutrition, total: a?.total, items: a?.items })) ===
  JSON.stringify(canonicalContent({ nutrition: b?.nutrition, total: b?.total, items: b?.items }))

/** Saved clock/date changes must refresh even when nutrients and IDs match. */
export const hasSameDiaryEntryTime = (a: any, b: any): boolean =>
  JSON.stringify(canonicalContent({ createdAt: a?.createdAt, time: a?.time, localDate: a?.localDate })) ===
  JSON.stringify(canonicalContent({ createdAt: b?.createdAt, time: b?.time, localDate: b?.localDate }))

import fs from 'fs'
import path from 'path'
import { normalizeText } from './custom-food-import'

export type FastFoodMenuServing = {
  id: string
  label: string
  serving_size: string
  grams?: number | null
  ml?: number | null
  calories?: number | null
  protein_g?: number | null
  carbs_g?: number | null
  fat_g?: number | null
  fiber_g?: number | null
  sugar_g?: number | null
}

export type FastFoodMenuItem = {
  country: string | null
  chain: string
  name: string
  servingOptions: FastFoodMenuServing[]
  sourceUrls: string[]
}

const DATA_PATH = path.join(process.cwd(), 'data', 'food-overrides', 'fast_food_menus.csv')
const CACHE_TTL_MS = 5 * 60 * 1000
let cachedAt = 0
let cachedItems: FastFoodMenuItem[] = []

const parseCsvLine = (line: string): string[] => {
  const cells: string[] = []
  let current = ''
  let inQuotes = false
  for (let i = 0; i < line.length; i += 1) {
    const ch = line[i]
    if (ch === '"') {
      const next = line[i + 1]
      if (inQuotes && next === '"') {
        current += '"'
        i += 1
        continue
      }
      inQuotes = !inQuotes
      continue
    }
    if (ch === ',' && !inQuotes) {
      cells.push(current)
      current = ''
      continue
    }
    current += ch
  }
  cells.push(current)
  return cells.map((cell) => cell.trim())
}

const parseCsv = (filePath: string) => {
  if (!fs.existsSync(filePath)) return { headers: [] as string[], records: [] as string[][] }
  const content = fs.readFileSync(filePath, 'utf8')
  const rows = content
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
  if (rows.length === 0) return { headers: [] as string[], records: [] as string[][] }
  const headers = parseCsvLine(rows[0]).map((header) => header.toLowerCase())
  const records = rows.slice(1).map((line) => parseCsvLine(line))
  return { headers, records }
}

const toNumber = (value: string | undefined | null) => {
  if (value == null) return null
  const trimmed = String(value).trim()
  if (!trimmed) return null
  const num = Number(trimmed)
  return Number.isFinite(num) ? num : null
}

const buildServingLabel = (sizeLabel: string, grams: number | null, ml: number | null) => {
  const label = String(sizeLabel || '').trim()
  if (grams && grams > 0) return `${label} (${grams} g)`
  if (ml && ml > 0) return `${label} (${ml} ml)`
  return label || '1 serving'
}

export const loadFastFoodMenuItems = () => {
  const now = Date.now()
  if (cachedItems.length > 0 && now - cachedAt < CACHE_TTL_MS) return cachedItems

  const parsed = parseCsv(DATA_PATH)
  if (!parsed.records.length) {
    cachedItems = []
    cachedAt = now
    return cachedItems
  }

  const headerIndex = new Map<string, number>()
  parsed.headers.forEach((header, index) => headerIndex.set(header, index))

  const get = (row: string[], key: string) => {
    const idx = headerIndex.get(key)
    if (idx == null) return ''
    return row[idx] ?? ''
  }

  type Row = {
    country: string | null
    chain: string
    name: string
    sizeLabel: string
    grams: number | null
    ml: number | null
    calories: number | null
    protein_g: number | null
    carbs_g: number | null
    fat_g: number | null
    fiber_g: number | null
    sugar_g: number | null
    sourceUrl: string | null
  }

  const rows: Row[] = []
  for (const record of parsed.records) {
    const chain = String(get(record, 'chain') || '').trim()
    const name = String(get(record, 'item') || '').trim()
    const sizeLabel = String(get(record, 'size_label') || get(record, 'size') || '').trim()
    if (!chain || !name || !sizeLabel) continue
    const calories = toNumber(get(record, 'calories'))
    const protein = toNumber(get(record, 'protein_g'))
    const carbs = toNumber(get(record, 'carbs_g'))
    const fat = toNumber(get(record, 'fat_g'))
    if (calories == null || protein == null || carbs == null || fat == null) continue
    const country = String(get(record, 'country') || '').trim().toUpperCase() || null
    rows.push({
      country,
      chain,
      name,
      sizeLabel,
      grams: toNumber(get(record, 'grams')),
      ml: toNumber(get(record, 'ml')),
      calories,
      protein_g: protein,
      carbs_g: carbs,
      fat_g: fat,
      fiber_g: toNumber(get(record, 'fiber_g')),
      sugar_g: toNumber(get(record, 'sugar_g')),
      sourceUrl: String(get(record, 'source_url') || '').trim() || null,
    })
  }

  const grouped = new Map<string, FastFoodMenuItem>()
  for (const row of rows) {
    const key = `${row.country || ''}|${normalizeText(row.chain)}|${normalizeText(row.name)}`
    const existing = grouped.get(key)
    const servingLabel = buildServingLabel(row.sizeLabel, row.grams, row.ml)
    const option: FastFoodMenuServing = {
      id: `serving-${normalizeText(`${row.chain} ${row.name} ${row.sizeLabel}`)}`,
      label: servingLabel,
      serving_size: servingLabel,
      grams: row.grams,
      ml: row.ml,
      calories: row.calories,
      protein_g: row.protein_g,
      carbs_g: row.carbs_g,
      fat_g: row.fat_g,
      fiber_g: row.fiber_g,
      sugar_g: row.sugar_g,
    }

    if (existing) {
      existing.servingOptions.push(option)
      if (row.sourceUrl) existing.sourceUrls.push(row.sourceUrl)
    } else {
      grouped.set(key, {
        country: row.country,
        chain: row.chain,
        name: row.name,
        servingOptions: [option],
        sourceUrls: row.sourceUrl ? [row.sourceUrl] : [],
      })
    }
  }

  const items = Array.from(grouped.values()).map((item) => {
    const sortedOptions = [...item.servingOptions].sort((a, b) => {
      const aSize = a.grams ?? a.ml ?? 0
      const bSize = b.grams ?? b.ml ?? 0
      if (aSize === 0 || bSize === 0) return 0
      return aSize - bSize
    })
    return { ...item, servingOptions: sortedOptions }
  })

  cachedItems = items
  cachedAt = now
  return cachedItems
}

import { prisma } from '../prisma'
import { buildCustomFoodAliases, buildCustomFoodKey, normalizeText } from './custom-food-import'
import { loadFastFoodMenuItems } from './fast-food-menus'

const normalizeChain = (value: string | null | undefined) =>
  normalizeText(String(value || '')).replace(/\s+/g, ' ').trim()

const stripSizeTokens = (value: string) => {
  if (!value) return ''
  const lower = value.toLowerCase()
  const tokensToStrip = [
    'small',
    'medium',
    'large',
    'regular',
    'size',
    'kids',
    'kid',
    'tall',
    'grande',
    'venti',
    'short',
    'single',
    'double',
    'triple',
  ]
  const cleaned = lower
    .split(/\s+/g)
    .filter((token) => token && !tokensToStrip.includes(token))
    .join(' ')
  return cleaned.trim()
}

const normalizeItemName = (value: string) => normalizeText(stripSizeTokens(value))

const removeChainFromName = (name: string, chain: string | null | undefined) => {
  if (!chain) return name
  const chainNorm = normalizeChain(chain)
  if (!chainNorm) return name
  const nameNorm = normalizeChain(name)
  if (!nameNorm) return name
  if (nameNorm.startsWith(chainNorm)) {
    return nameNorm.slice(chainNorm.length).trim()
  }
  return nameNorm
}

export type FastFoodSyncResult = {
  added: number
  updated: number
  total: number
  errors: number
  addedKeys: string[]
}

export const syncFastFoodMenus = async (params?: {
  country?: string | null
  chain?: string | null
}): Promise<FastFoodSyncResult> => {
  const requestedCountry = String(params?.country || '').trim().toUpperCase()
  const requestedChain = normalizeChain(params?.chain || '')

  const menuItems = loadFastFoodMenuItems().filter((item) => {
    if (requestedCountry && item.country && String(item.country).toUpperCase() !== requestedCountry) return false
    if (requestedCountry && !item.country) return false
    if (requestedChain) {
      const itemChain = normalizeChain(item.chain)
      if (!itemChain) return false
      if (itemChain !== requestedChain) return false
    }
    return true
  })
  let added = 0
  let updated = 0
  let errors = 0
  const addedKeys: string[] = []

  for (const item of menuItems) {
    try {
      const aliases = buildCustomFoodAliases(item.name, item.chain)
      const key = buildCustomFoodKey({
        name: item.name,
        brand: item.chain,
        kind: 'FAST_FOOD',
        country: item.country ?? null,
      })

      const existing = await prisma.customFoodItem.findUnique({ where: { key } })

      await prisma.customFoodItem.upsert({
        where: { key },
        create: {
          key,
          name: item.name,
          brand: item.chain,
          country: item.country ?? null,
          kind: 'FAST_FOOD',
          group: 'fast_food',
          caloriesPer100g: null,
          proteinPer100g: null,
          carbsPer100g: null,
          fatPer100g: null,
          fiberPer100g: null,
          sugarPer100g: null,
          aliases,
          servingOptions: item.servingOptions,
        },
        update: {
          name: item.name,
          brand: item.chain,
          country: item.country ?? null,
          kind: 'FAST_FOOD',
          group: 'fast_food',
          caloriesPer100g: null,
          proteinPer100g: null,
          carbsPer100g: null,
          fatPer100g: null,
          fiberPer100g: null,
          sugarPer100g: null,
          aliases,
          servingOptions: item.servingOptions,
        },
      })

      if (existing) {
        updated += 1
      } else {
        added += 1
        addedKeys.push(key)
      }
    } catch (error) {
      errors += 1
      console.error('Fast food menu sync failed for item:', item.name, error)
    }
  }

  return { added, updated, total: menuItems.length, errors, addedKeys }
}

const menuMatchScore = (reportName: string, menuName: string) => {
  const reportNorm = normalizeItemName(reportName)
  const menuNorm = normalizeItemName(menuName)
  if (!reportNorm || !menuNorm) return 0
  if (reportNorm === menuNorm) return 3
  if (reportNorm.includes(menuNorm) || menuNorm.includes(reportNorm)) return 2
  return 0
}

export const findMenuMatchForReport = (params: {
  name: string
  brand?: string | null
  country?: string | null
}) => {
  const menuItems = loadFastFoodMenuItems()
  const reportCountry = String(params.country || '').trim().toUpperCase()
  const reportBrand = normalizeChain(params.brand || '')
  const reportName = String(params.name || '').trim()
  const cleanedName = removeChainFromName(reportName, params.brand)

  let best: (typeof menuItems)[number] | null = null
  let bestScore = 0

  for (const item of menuItems) {
    if (reportCountry && item.country && reportCountry !== String(item.country).toUpperCase()) continue
    if (reportBrand) {
      const itemBrand = normalizeChain(item.chain)
      if (!itemBrand) continue
      if (itemBrand !== reportBrand && !itemBrand.includes(reportBrand) && !reportBrand.includes(itemBrand)) continue
    }

    const score = menuMatchScore(cleanedName || reportName, item.name)
    if (score > bestScore) {
      bestScore = score
      best = item
    }
  }

  return best
}

export type FoodNameOverrideRow = {
  from: string
  to: string
  itemId?: string
  favoriteId?: string
  sourceId?: string
  barcode?: string
  createdAt?: number
}

export type FoodNameOverrideIndex = Map<string, string> & {
  __byItemId?: Map<string, string>
  __byFavoriteId?: Map<string, string>
  __bySourceId?: Map<string, string>
  __byBarcode?: Map<string, string>
}

export const normalizeFoodName = (name: string | null | undefined) =>
  String(name || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()

// Keep this intentionally simple: the UI should show a short, clean title (not AI paragraphs or macro lines).
export const extractBaseMealDescription = (value: string | null | undefined) => {
  const raw = String(value || '').trim()
  if (!raw) return ''
  const firstLine = raw.split('\n')[0] || raw
  const withoutNutrition = firstLine.split(/Calories\s*:/i)[0] || firstLine
  const withoutJson = withoutNutrition.split(/<ITEMS_JSON>/i)[0] || withoutNutrition
  return String(withoutJson || '').trim()
}

export const normalizeMealLabel = (raw: any) => extractBaseMealDescription(String(raw || ''))

export const createFoodNameOverrideIndex = (overrides: any): FoodNameOverrideIndex => {
  const map = new Map<string, string>() as FoodNameOverrideIndex
  const byItemId = new Map<string, string>()
  const byFavoriteId = new Map<string, string>()
  const bySourceId = new Map<string, string>()
  const byBarcode = new Map<string, string>()

  const list = Array.isArray(overrides) ? (overrides as FoodNameOverrideRow[]) : []
  for (const row of list) {
    const fromRaw = typeof (row as any)?.from === 'string' ? String((row as any).from) : ''
    const toRaw = typeof (row as any)?.to === 'string' ? String((row as any).to) : ''
    const itemIdRaw = typeof (row as any)?.itemId === 'string' ? String((row as any).itemId).trim() : ''
    const favIdRaw = typeof (row as any)?.favoriteId === 'string' ? String((row as any).favoriteId).trim() : ''
    const srcIdRaw = typeof (row as any)?.sourceId === 'string' ? String((row as any).sourceId).trim() : ''
    const barcodeRaw = typeof (row as any)?.barcode === 'string' ? String((row as any).barcode).trim() : ''

    const from = normalizeMealLabel(fromRaw)
    const to = normalizeMealLabel(toRaw).trim()
    if (!from || !to) continue

    if (itemIdRaw) byItemId.set(itemIdRaw, to)
    if (favIdRaw) byFavoriteId.set(favIdRaw, to)
    if (srcIdRaw) bySourceId.set(srcIdRaw, to)
    if (barcodeRaw) byBarcode.set(barcodeRaw, to)

    const key = normalizeFoodName(from)
    if (key) map.set(key, to)
  }

  map.__byItemId = byItemId
  map.__byFavoriteId = byFavoriteId
  map.__bySourceId = bySourceId
  map.__byBarcode = byBarcode
  return map
}

const readEntryBarcode = (entry: any) => {
  try {
    const items = Array.isArray(entry?.items) ? entry.items : []
    const single = items.length === 1 ? items[0] : null
    const direct = single && (single?.barcode || single?.gtinUpc || null)
    if (direct) return String(direct).trim()
    const hit = items.find((it: any) => it?.barcode || it?.detectionMethod === 'barcode')
    if (hit?.barcode) return String(hit.barcode).trim()
    if (entry?.barcode) return String(entry.barcode).trim()
  } catch {}
  return ''
}

const readEntryItemId = (entry: any) => {
  try {
    const items = Array.isArray(entry?.items) ? entry.items : []
    const single = items.length === 1 ? items[0] : null
    const id = single && typeof single?.id === 'string' ? String(single.id).trim() : ''
    if (id) return id
  } catch {}
  return ''
}

const readEntryFavoriteId = (entry: any) => {
  try {
    const direct =
      (entry?.favorite && entry.favorite.id && String(entry.favorite.id)) ||
      (entry?.nutrition && (entry.nutrition as any).__favoriteId) ||
      (entry?.nutrients && (entry.nutrients as any).__favoriteId) ||
      (entry && entry.id && (entry.method || entry.customMeal != null) ? String(entry.id) : '')
    return direct ? String(direct).trim() : ''
  } catch {}
  return ''
}

const readEntrySourceId = (entry: any) => {
  try {
    const direct =
      (entry?.source && entry.source.id && String(entry.source.id)) ||
      (entry?.sourceId && String(entry.sourceId)) ||
      (entry?.nutrition && (entry.nutrition as any).__sourceId) ||
      (entry?.nutrients && (entry.nutrients as any).__sourceId)
    return direct ? String(direct).trim() : ''
  } catch {}
  return ''
}

export const applyFoodNameOverride = (raw: any, entry: any, index: FoodNameOverrideIndex) => {
  const rawString = raw === null || raw === undefined ? '' : String(raw || '')

  try {
    const itemId = readEntryItemId(entry)
    const byItemId = index?.__byItemId
    if (itemId && byItemId && typeof byItemId.get === 'function') {
      const hit = byItemId.get(itemId)
      if (hit) return hit
    }

    const barcode = readEntryBarcode(entry)
    const byBarcode = index?.__byBarcode
    if (barcode && byBarcode && typeof byBarcode.get === 'function') {
      const hit = byBarcode.get(barcode)
      if (hit) return hit
    }

    const favId = readEntryFavoriteId(entry)
    const byFavoriteId = index?.__byFavoriteId
    if (favId && byFavoriteId && typeof byFavoriteId.get === 'function') {
      const hit = byFavoriteId.get(favId)
      if (hit) return hit
    }

    const srcId = readEntrySourceId(entry)
    const bySourceId = index?.__bySourceId
    if (srcId && bySourceId && typeof bySourceId.get === 'function') {
      const hit = bySourceId.get(srcId)
      if (hit) return hit
    }
  } catch {}

  const base = normalizeMealLabel(rawString).trim()
  if (!base) return ''
  const key = normalizeFoodName(base)
  const hit = key ? index.get(key) : ''
  return hit || base
}

// Useful for UIs that want a "rename" only when an override actually changes something.
export const resolveFoodNameOverrideOnly = (raw: any, entry: any, index: FoodNameOverrideIndex) => {
  const rawString = raw === null || raw === undefined ? '' : String(raw || '')
  const base = normalizeMealLabel(rawString).trim()
  if (!base) return ''
  const applied = normalizeMealLabel(applyFoodNameOverride(rawString, entry, index) || '').trim()
  if (!applied) return ''
  const baseKey = normalizeFoodName(base)
  const appliedKey = normalizeFoodName(applied)
  if (baseKey && appliedKey && baseKey !== appliedKey) return applied
  if (!baseKey && applied !== base && applied.toLowerCase() !== base.toLowerCase()) return applied
  return ''
}

