export type FoodUnitGrams = Partial<Record<MeasurementUnit, number>>

export const DEFAULT_UNIT_GRAMS: Record<MeasurementUnit, number> = {
  g: 1,
  ml: 1,
  oz: 28.3495,
  tsp: 5,
  tbsp: 14,
  'quarter-cup': 218 / 4,
  'half-cup': 218 / 2,
  'three-quarter-cup': (218 * 3) / 4,
  cup: 218,
  pinch: 0.3,
  handful: 30,
  piece: 100,
  'piece-small': 100,
  'piece-medium': 100,
  'piece-large': 100,
  'piece-extra-large': 100,
  'egg-small': 38,
  'egg-medium': 44,
  'egg-large': 50,
  'egg-extra-large': 56,
  slice: 30,
  serving: 100,
}

export const DISPLAY_MEASUREMENT_UNITS: MeasurementUnit[] = [
  'g',
  'ml',
  'oz',
  'tsp',
  'tbsp',
  'quarter-cup',
  'half-cup',
  'three-quarter-cup',
  'cup',
  'pinch',
  'piece',
  'piece-small',
  'piece-medium',
  'piece-large',
  'piece-extra-large',
]

const EGG_UNITS: MeasurementUnit[] = ['egg-small', 'egg-medium', 'egg-large', 'egg-extra-large']
const EGG_UNIT_GRAMS: FoodUnitGrams = {
  'egg-small': DEFAULT_UNIT_GRAMS['egg-small'],
  'egg-medium': DEFAULT_UNIT_GRAMS['egg-medium'],
  'egg-large': DEFAULT_UNIT_GRAMS['egg-large'],
  'egg-extra-large': DEFAULT_UNIT_GRAMS['egg-extra-large'],
}

const FOOD_VARIANT_REPLACEMENTS: Array<[RegExp, string]> = [
  [/\byoghurt\b/g, 'yogurt'],
  [/\bchilli\b/g, 'chili'],
  [/\baubergine\b/g, 'eggplant'],
  [/\bcourgette\b/g, 'zucchini'],
  [/\bcapsicum\b/g, 'bell pepper'],
  [/\bbeetroot\b/g, 'beet'],
  [/\bsweetcorn\b/g, 'corn'],
  [/\bgarbanzo\b/g, 'chickpea'],
  [/\bscallions?\b/g, 'spring onion'],
  [/\bgreen onions?\b/g, 'spring onion'],
  [/\brocket\b/g, 'arugula'],
  [/\bcoriander\b/g, 'cilantro'],
  [/\bicing sugar\b/g, 'powdered sugar'],
  [/\bconfectioners? sugar\b/g, 'powdered sugar'],
  [/\bsultanas?\b/g, 'raisins'],
]

const normalizeFoodValue = (value: string) => {
  let normalized = value.toLowerCase().replace(/&/g, ' and ')
  normalized = normalized.normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  FOOD_VARIANT_REPLACEMENTS.forEach(([pattern, replacement]) => {
    normalized = normalized.replace(pattern, replacement)
  })
  return normalized.replace(/[^a-z0-9]+/g, ' ').trim().replace(/\s+/g, ' ')
}

const singularizeToken = (value: string) => {
  const lower = value.toLowerCase()
  if (lower.endsWith('ies') && value.length > 4) return `${value.slice(0, -3)}y`
  // Handle plurals like peaches/dishes/watches -> peach/dish/watch.
  if (
    (lower.endsWith('ches') ||
      lower.endsWith('shes') ||
      lower.endsWith('xes') ||
      lower.endsWith('zes') ||
      lower.endsWith('ses') ||
      lower.endsWith('oes')) &&
    value.length > 4
  ) {
    return value.slice(0, -2)
  }
  // Keep words like "citrus" intact; only trim trailing "s" for likely plurals.
  if (lower.endsWith('s') && value.length > 3 && !lower.endsWith('ss') && !lower.endsWith('us')) {
    return value.slice(0, -1)
  }
  return value
}

const tokenizeFoodValue = (value: string) =>
  normalizeFoodValue(value)
    .split(' ')
    .map((token) => singularizeToken(token))
    .filter(Boolean)

const EGG_BLOCKLIST = new Set([
  'white',
  'yolk',
  'eggplant',
  'nog',
  'noodle',
  'pasta',
  'salad',
  'sandwich',
  'wrap',
  'burrito',
  'taco',
  'pizza',
  'burger',
  'muffin',
  'bagel',
  'roll',
  'cake',
  'cookie',
  'pancake',
  'waffle',
  'rice',
  'protein',
  'powder',
  'substitute',
  'mix',
])

const isEggFood = (name: string | null | undefined) => {
  const tokens = tokenizeFoodValue(String(name || '').trim())
  if (!tokens.includes('egg')) return false
  return tokens.every((token) => !EGG_BLOCKLIST.has(token))
}

export const isLiquidFood = (name: string | null | undefined) => {
  const normalized = normalizeFoodValue(String(name || '').trim())
  if (!normalized) return false
  if (normalized.includes('milk chocolate')) return false
  if (
    /\b(chocolate|cocoa)\b/.test(normalized) &&
    !/\b(chocolate milk|hot chocolate|milkshake|shake|smoothie|syrup)\b/.test(normalized)
  ) {
    return false
  }
  const solidHints = [
    'bread',
    'cookie',
    'biscuit',
    'cracker',
    'cereal',
    'chips',
    'crisps',
    'popcorn',
    'powder',
    'mix',
    'bar',
    'cake',
    'brownie',
  ]
  if (solidHints.some((hint) => new RegExp(`\\b${hint}(?:s|es|ed)?\\b`).test(normalized))) return false
  const liquidHints = [
    'water',
    'milk',
    'juice',
    'coffee',
    'tea',
    'soda',
    'cola',
    'drink',
    'beverage',
    'smoothie',
    'shake',
    'milkshake',
    'broth',
    'stock',
    'soup',
    'oil',
    'vinegar',
    'sauce',
    'syrup',
  ]
  return liquidHints.some((hint) => new RegExp(`\\b${hint}(?:s|es)?\\b`).test(normalized))
}

const splitFoodOptions = (value: string) =>
  value
    .split(/\/|,|\bor\b/gi)
    .map((chunk) => chunk.trim())
    .filter(Boolean)

type FoodAlias = {
  tokens: string[]
  entryIndex: number
  score: number
}

const buildFoodAliases = (entries: Array<{ food: string }>): FoodAlias[] => {
  const aliases: FoodAlias[] = []
  const seen = new Set<string>()
  entries.forEach((entry, entryIndex) => {
    const raw = String(entry?.food || '').trim()
    if (!raw) return

    const modifierChunks: string[] = []
    const baseRaw = raw.replace(/\(([^)]*)\)/g, (_, inner) => {
      modifierChunks.push(inner)
      return ' '
    })
    const baseParts = baseRaw
      .split('/')
      .map((chunk) => chunk.trim())
      .filter(Boolean)
    const modifiers = modifierChunks.flatMap((chunk) => splitFoodOptions(chunk))

    const addAlias = (phrase: string, scoreBoost = 0) => {
      const tokens = tokenizeFoodValue(phrase)
      if (tokens.length === 0) return
      const key = `${entryIndex}:${tokens.join('|')}`
      if (seen.has(key)) return
      seen.add(key)
      aliases.push({ tokens, entryIndex, score: tokens.length + scoreBoost })
    }

    baseParts.forEach((base) => {
      addAlias(base)
      modifiers.forEach((modifier) => addAlias(`${base} ${modifier}`, 1))
    })
  })
  return aliases
}

const resolveFoodUnitGrams = (
  name: string | null | undefined,
  entries: Array<{ food: string }>,
  aliases: FoodAlias[],
  cache: Map<string, FoodUnitGrams | null>,
  buildUnitGrams: (entry: any) => FoodUnitGrams,
): FoodUnitGrams | null => {
  const normalized = normalizeFoodValue(String(name || '').trim())
  if (!normalized) return null
  if (cache.has(normalized)) return cache.get(normalized) || null
  const tokens = new Set(tokenizeFoodValue(normalized))
  let bestScore = 0
  let bestIndex = -1
  for (const alias of aliases) {
    if (!alias.tokens.every((token) => tokens.has(token))) continue
    if (alias.score > bestScore) {
      bestScore = alias.score
      bestIndex = alias.entryIndex
    }
  }
  const entry = bestIndex >= 0 ? entries[bestIndex] : null
  const result = entry ? buildUnitGrams(entry) : null
  cache.set(normalized, result)
  return result
}

const toUnitValue = (value: number | null) => (Number.isFinite(Number(value)) ? Number(value) : undefined)

const explicitPieceExtraLarge = (entry: { piece_extra_large_g?: number | null }) =>
  toUnitValue(entry.piece_extra_large_g ?? null)

const getProducePieceLabel = (unit: MeasurementUnit, produceName: string) => {
  if (/\bwatermelon\b/.test(produceName)) {
    if (unit === 'piece-small') return '1/8 watermelon'
    if (unit === 'piece-medium') return '1/4 watermelon'
    if (unit === 'piece-large') return '1/2 watermelon'
    if (unit === 'piece-extra-large') return '1 watermelon'
  }
  if (unit === 'piece-small') return produceName ? `small ${produceName}` : 'small piece'
  if (unit === 'piece-medium') return produceName ? `medium ${produceName}` : 'medium piece'
  if (unit === 'piece-large') return produceName ? `large ${produceName}` : 'large piece'
  return produceName ? `extra large ${produceName}` : 'extra large piece'
}

const buildDryFoodUnitGrams = (entry: (typeof DRY_FOOD_MEASUREMENTS)[number]): FoodUnitGrams => ({
  pinch: entry.pinch_g,
  tsp: entry.tsp_g,
  tbsp: entry.tbsp_g,
  'quarter-cup': entry.quarter_cup_g,
  'half-cup': entry.half_cup_g,
  'three-quarter-cup': entry.three_quarter_cup_g,
  cup: entry.cup_g,
})

const buildDairySemiSolidUnitGrams = (
  entry: (typeof DAIRY_SEMI_SOLID_MEASUREMENTS)[number],
): FoodUnitGrams => ({
  tsp: entry.tsp_g,
  tbsp: entry.tbsp_g,
  'quarter-cup': entry.quarter_cup_g,
  'half-cup': entry.half_cup_g,
  'three-quarter-cup': entry.three_quarter_cup_g,
  cup: entry.cup_g,
})

const buildProduceUnitGrams = (entry: (typeof PRODUCE_MEASUREMENTS)[number]): FoodUnitGrams => {
  const small = toUnitValue(entry.piece_small_g)
  const medium = toUnitValue(entry.piece_medium_g)
  const large = toUnitValue(entry.piece_large_g)
  let extraLarge: number | null = explicitPieceExtraLarge(entry) ?? null
  if (
    (!Number.isFinite(Number(extraLarge)) || Number(extraLarge) <= 0) &&
    Number.isFinite(Number(large)) &&
    Number.isFinite(Number(medium)) &&
    Number(large) > 0 &&
    Number(medium) > 0
  ) {
    extraLarge = Number(large) + (Number(large) - Number(medium))
  } else if (
    (!Number.isFinite(Number(extraLarge)) || Number(extraLarge) <= 0) &&
    Number.isFinite(Number(large)) &&
    Number.isFinite(Number(small)) &&
    Number(large) > 0 &&
    Number(small) > 0
  ) {
    extraLarge = Number(large) + (Number(large) - Number(small)) / 2
  }
  return {
    'quarter-cup': toUnitValue(entry.quarter_cup_raw_g),
    'half-cup': toUnitValue(entry.half_cup_raw_g),
    'three-quarter-cup': toUnitValue(entry.three_quarter_cup_raw_g),
    cup: toUnitValue(entry.raw_cup_g),
    'piece-small': small,
    'piece-medium': medium,
    'piece-large': large,
    'piece-extra-large': toUnitValue(extraLarge),
  }
}

const DRY_FOOD_ALIASES = buildFoodAliases(DRY_FOOD_MEASUREMENTS)
const DRY_FOOD_LOOKUP_CACHE = new Map<string, FoodUnitGrams | null>()
const DAIRY_SEMI_SOLID_ALIASES = buildFoodAliases(DAIRY_SEMI_SOLID_MEASUREMENTS)
const DAIRY_SEMI_SOLID_LOOKUP_CACHE = new Map<string, FoodUnitGrams | null>()
const PRODUCE_ALIASES = buildFoodAliases(PRODUCE_MEASUREMENTS)
const PRODUCE_LOOKUP_CACHE = new Map<string, FoodUnitGrams | null>()

export const getDryFoodUnitGrams = (name: string | null | undefined): FoodUnitGrams | null =>
  resolveFoodUnitGrams(name, DRY_FOOD_MEASUREMENTS, DRY_FOOD_ALIASES, DRY_FOOD_LOOKUP_CACHE, buildDryFoodUnitGrams)

export const getDairySemiSolidUnitGrams = (name: string | null | undefined): FoodUnitGrams | null =>
  resolveFoodUnitGrams(
    name,
    DAIRY_SEMI_SOLID_MEASUREMENTS,
    DAIRY_SEMI_SOLID_ALIASES,
    DAIRY_SEMI_SOLID_LOOKUP_CACHE,
    buildDairySemiSolidUnitGrams,
  )

export const getProduceUnitGrams = (name: string | null | undefined): FoodUnitGrams | null =>
  resolveFoodUnitGrams(name, PRODUCE_MEASUREMENTS, PRODUCE_ALIASES, PRODUCE_LOOKUP_CACHE, buildProduceUnitGrams)

export const getFoodUnitGrams = (name: string | null | undefined): FoodUnitGrams | null =>
  isLiquidFood(name) ? null :
  (isEggFood(name) ? EGG_UNIT_GRAMS : null) ||
  getProduceUnitGrams(name) ||
  getDairySemiSolidUnitGrams(name) ||
  getDryFoodUnitGrams(name)

export const getAllowedUnitsForFood = (
  name: string | null | undefined,
  pieceGrams?: number | null,
): MeasurementUnit[] => {
  let units: MeasurementUnit[] = [...DISPLAY_MEASUREMENT_UNITS]
  if (isLiquidFood(name)) {
    return units.filter(
      (unit) =>
        unit === 'ml' ||
        unit === 'g' ||
        unit === 'oz' ||
        unit === 'tsp' ||
        unit === 'tbsp' ||
        unit === 'quarter-cup' ||
        unit === 'half-cup' ||
        unit === 'three-quarter-cup' ||
      unit === 'cup',
    )
  }
  units = units.filter((unit) => unit !== 'ml')
  if (isEggFood(name)) {
    const disallowed = new Set<MeasurementUnit>([
      'tsp',
      'tbsp',
      'quarter-cup',
      'half-cup',
      'three-quarter-cup',
      'cup',
      'pinch',
      'handful',
      'piece',
      'piece-small',
      'piece-medium',
      'piece-large',
      'piece-extra-large',
    ])
    units = units.filter((unit) => !disallowed.has(unit) && !EGG_UNITS.includes(unit))
    return [...units, ...EGG_UNITS]
  }
  const produceUnits = name ? getProduceUnitGrams(name) : null
  const isProduce = Boolean(produceUnits)
  if (isProduce) units = units.filter((unit) => unit !== 'tsp' && unit !== 'tbsp' && unit !== 'pinch')
  const hasPieceSmall = Number.isFinite(Number(produceUnits?.['piece-small'])) && Number(produceUnits?.['piece-small']) > 0
  const hasPieceMedium = Number.isFinite(Number(produceUnits?.['piece-medium'])) && Number(produceUnits?.['piece-medium']) > 0
  const hasPieceLarge = Number.isFinite(Number(produceUnits?.['piece-large'])) && Number(produceUnits?.['piece-large']) > 0
  const hasPieceExtraLarge =
    Number.isFinite(Number(produceUnits?.['piece-extra-large'])) && Number(produceUnits?.['piece-extra-large']) > 0
  if (hasPieceSmall || hasPieceMedium || hasPieceLarge) {
    units = units.filter((unit) => unit !== 'piece')
  } else if (!pieceGrams || pieceGrams <= 0) {
    units = units.filter((unit) => unit !== 'piece')
  }
  if (!hasPieceSmall) units = units.filter((unit) => unit !== 'piece-small')
  if (!hasPieceMedium) units = units.filter((unit) => unit !== 'piece-medium')
  if (!hasPieceLarge) units = units.filter((unit) => unit !== 'piece-large')
  if (!hasPieceExtraLarge) units = units.filter((unit) => unit !== 'piece-extra-large')
  return units
}

export const formatUnitLabel = (unit: MeasurementUnit, name?: string | null, pieceGrams?: number | null) => {
  const foodUnitGrams = name ? getFoodUnitGrams(name) : null
  const produceUnits = name ? getProduceUnitGrams(name) : null
  const normalizedProduceName = produceUnits ? normalizeFoodValue(String(name || '').trim()) : ''
  const produceName = (() => {
    if (!normalizedProduceName) return ''
    const descriptorTokens = new Set([
      'raw',
      'cooked',
      'fresh',
      'frozen',
      'canned',
      'ripe',
      'unripe',
      'yellow',
      'green',
      'red',
      'orange',
      'purple',
      'white',
      'black',
      'peeled',
      'unpeeled',
      'sliced',
      'diced',
      'chopped',
      'halved',
      'whole',
      'all',
      'commercial',
      'varieties',
    ])
    const tokens = normalizedProduceName.split(' ').filter(Boolean)
    while (tokens.length > 1 && descriptorTokens.has(tokens[tokens.length - 1])) {
      tokens.pop()
    }
    if (tokens.length > 0) {
      tokens[0] = singularizeToken(tokens[0])
    }
    const cleaned = tokens.join(' ').trim()
    if (cleaned) return cleaned
    // For garlic, "piece" is almost always a clove.
    if (/\bgarlic\b/.test(normalizedProduceName) && !/\b(powder|granules?)\b/.test(normalizedProduceName)) return 'clove'
    return normalizedProduceName
  })()
  const unitValue = foodUnitGrams?.[unit]
  if (unit === 'g') return 'g'
  if (unit === 'ml') return 'ml'
  if (unit === 'oz') return 'oz'
  if (unit === 'tsp') return `tsp — ${Number.isFinite(Number(unitValue)) && Number(unitValue) > 0 ? Number(unitValue) : 5}g`
  if (unit === 'tbsp') return `tbsp — ${Number.isFinite(Number(unitValue)) && Number(unitValue) > 0 ? Number(unitValue) : 14}g`
  if (unit === 'quarter-cup') return `1/4 cup — ${Number.isFinite(Number(unitValue)) && Number(unitValue) > 0 ? Number(unitValue) : 54.5}g`
  if (unit === 'half-cup') return `1/2 cup — ${Number.isFinite(Number(unitValue)) && Number(unitValue) > 0 ? Number(unitValue) : 109}g`
  if (unit === 'three-quarter-cup') return `3/4 cup — ${Number.isFinite(Number(unitValue)) && Number(unitValue) > 0 ? Number(unitValue) : 163.5}g`
  if (unit === 'cup') return `cup — ${Number.isFinite(Number(unitValue)) && Number(unitValue) > 0 ? Number(unitValue) : 218}g`
  if (unit === 'pinch') return `pinch — ${Number.isFinite(Number(unitValue)) && Number(unitValue) > 0 ? Number(unitValue) : 0.3}g`
  if (unit === 'egg-small') {
    const grams = Number.isFinite(Number(unitValue)) && Number(unitValue) > 0 ? Number(unitValue) : DEFAULT_UNIT_GRAMS['egg-small']
    return `small egg — ${Math.round(grams * 10) / 10}g`
  }
  if (unit === 'egg-medium') {
    const grams = Number.isFinite(Number(unitValue)) && Number(unitValue) > 0 ? Number(unitValue) : DEFAULT_UNIT_GRAMS['egg-medium']
    return `medium egg — ${Math.round(grams * 10) / 10}g`
  }
  if (unit === 'egg-large') {
    const grams = Number.isFinite(Number(unitValue)) && Number(unitValue) > 0 ? Number(unitValue) : DEFAULT_UNIT_GRAMS['egg-large']
    return `large egg — ${Math.round(grams * 10) / 10}g`
  }
  if (unit === 'egg-extra-large') {
    const grams =
      Number.isFinite(Number(unitValue)) && Number(unitValue) > 0 ? Number(unitValue) : DEFAULT_UNIT_GRAMS['egg-extra-large']
    return `extra large egg — ${Math.round(grams * 10) / 10}g`
  }
  if (unit === 'piece') {
    if (pieceGrams && pieceGrams > 0) return `piece — ${Math.round(pieceGrams * 10) / 10}g`
    return 'piece'
  }
  if (unit === 'piece-small') {
    const grams = Number(unitValue)
    if (Number.isFinite(grams) && grams > 0) return `${getProducePieceLabel(unit, produceName)} — ${Math.round(grams * 10) / 10}g`
    return getProducePieceLabel(unit, produceName)
  }
  if (unit === 'piece-medium') {
    const grams = Number(unitValue)
    if (Number.isFinite(grams) && grams > 0) return `${getProducePieceLabel(unit, produceName)} — ${Math.round(grams * 10) / 10}g`
    return getProducePieceLabel(unit, produceName)
  }
  if (unit === 'piece-large') {
    const grams = Number(unitValue)
    if (Number.isFinite(grams) && grams > 0) return `${getProducePieceLabel(unit, produceName)} — ${Math.round(grams * 10) / 10}g`
    return getProducePieceLabel(unit, produceName)
  }
  if (unit === 'piece-extra-large') {
    const grams = Number(unitValue)
    if (Number.isFinite(grams) && grams > 0) return `${getProducePieceLabel(unit, produceName)} — ${Math.round(grams * 10) / 10}g`
    return getProducePieceLabel(unit, produceName)
  }
  return unit
}

export const resolveUnitGrams = (
  unit: MeasurementUnit,
  baseAmount?: number | null,
  baseUnit?: MeasurementUnit | null,
  pieceGrams?: number | null,
  foodUnitGrams?: FoodUnitGrams | null,
) => {
  const foodOverride = foodUnitGrams?.[unit]
  if (Number.isFinite(Number(foodOverride)) && Number(foodOverride) > 0) return Number(foodOverride)
  if (
    unit === 'piece' ||
    unit === 'piece-small' ||
    unit === 'piece-medium' ||
    unit === 'piece-large' ||
    unit === 'piece-extra-large'
  ) {
    if (pieceGrams && pieceGrams > 0) return pieceGrams
    return DEFAULT_UNIT_GRAMS.piece
  }
  if (
    (unit === 'serving' || unit === 'slice' || unit === 'handful') &&
    baseAmount &&
    baseUnit &&
    Object.prototype.hasOwnProperty.call(DEFAULT_UNIT_GRAMS, baseUnit)
  ) {
    return baseAmount * DEFAULT_UNIT_GRAMS[baseUnit]
  }
  return DEFAULT_UNIT_GRAMS[unit]
}

export const convertAmount = (
  amount: number,
  from: MeasurementUnit,
  to: MeasurementUnit,
  baseAmount?: number | null,
  baseUnit?: MeasurementUnit | null,
  pieceGrams?: number | null,
  foodUnitGrams?: FoodUnitGrams | null,
) => {
  if (!Number.isFinite(amount)) return amount
  if (from === to) return amount
  const fromGrams = resolveUnitGrams(from, baseAmount, baseUnit, pieceGrams, foodUnitGrams)
  const toGrams = resolveUnitGrams(to, baseAmount, baseUnit, pieceGrams, foodUnitGrams)
  if (!Number.isFinite(fromGrams) || !Number.isFinite(toGrams) || toGrams <= 0) return amount
  const grams = amount * fromGrams
  return grams / toGrams
}

// Keep in sync with native/src/lib/nutrientValues.ts. Missing nutrition is not zero.
export function optionalNutrient(value: unknown): number | null {
  if (value == null || typeof value === 'boolean' || (typeof value === 'string' && !value.trim())) return null
  const number = Number(value)
  return Number.isFinite(number) && number >= 0 ? number : null
}

export function readOptionalNutrient(record: any, keys: string[]): number | null {
  for (const key of keys) {
    if (record?.[key] !== undefined) return optionalNutrient(record[key])
  }
  return null
}

export function scaleOptionalNutrient(value: unknown, factor: number): number | null {
  if (!Number.isFinite(factor) || factor < 0) return null
  if (factor === 0) return 0
  const number = optionalNutrient(value)
  return number == null ? null : number * factor
}

export function sumOptionalNutrients(left: unknown, right: unknown): number | null {
  const a = optionalNutrient(left)
  const b = optionalNutrient(right)
  return a == null || b == null ? null : a + b
}

export function roundOptionalNutrient(value: unknown, decimals = 1): number | null {
  const number = optionalNutrient(value)
  const factor = 10 ** decimals
  return number == null ? null : Math.round(number * factor) / factor
}

// One nutrient basis for both packaged search and barcode lookup.
export const foodNumberOrNull = (value: unknown): number | null => {
  if (value == null || typeof value === 'boolean') return null
  if (typeof value !== 'number' && typeof value !== 'string') return null
  if (typeof value === 'string' && !value.trim()) return null
  const number = Number(value)
  return Number.isFinite(number) && number >= 0 ? number : null
}

// Core nutrition must be usable before a food or serving can be selected.
// Missing optional fibre/sugar values do not make a result incomplete.
export const hasCoreFoodNutrition = (item: any): boolean =>
  ['calories', 'protein_g', 'carbs_g', 'fat_g'].every(key => foodNumberOrNull(item?.[key]) !== null)

export function normalizeOffNutrition(product: any) {
  const nutr = product?.nutriments || {}
  const label = String(product?.serving_size || '').trim()
  const measured = label.match(/(\d+(?:[.,]\d+)?)\s*(kg|g|grams?|ml|millilit(?:er|re)s?|lit(?:er|re)s?|l)\b/i)
  const unit = measured?.[2].toLowerCase()
  const volume = !!unit && /^(ml|millilit|l)/.test(unit)
  const labelledQuantity = measured ? Number(measured[1].replace(',', '.')) * (/^(kg|l|lit)/.test(unit!) ? 1000 : 1) : null
  const quantity = labelledQuantity ?? foodNumberOrNull(product?.serving_quantity)
  const factor = quantity != null && quantity > 0 ? quantity / 100 : null
  const energy = (suffix: string) => {
    const kcal = foodNumberOrNull(nutr[`energy-kcal_${suffix}`])
    if (kcal != null) return kcal
    const kj = foodNumberOrNull(nutr[`energy-kj_${suffix}`]) ?? foodNumberOrNull(nutr[`energy_${suffix}`])
    return kj == null ? null : kj / 4.184
  }
  const fields = {
    calories: [energy('serving'), energy('100g')],
    protein_g: [foodNumberOrNull(nutr.proteins_serving), foodNumberOrNull(nutr.proteins_100g)],
    carbs_g: [foodNumberOrNull(nutr.carbohydrates_serving), foodNumberOrNull(nutr.carbohydrates_100g)],
    fat_g: [foodNumberOrNull(nutr.fat_serving), foodNumberOrNull(nutr.fat_100g)],
    fiber_g: [foodNumberOrNull(nutr.fiber_serving), foodNumberOrNull(nutr.fiber_100g)],
    sugar_g: [foodNumberOrNull(nutr.sugars_serving), foodNumberOrNull(nutr.sugars_100g)],
  }
  const hasServing = Object.values(fields).some(([serving]) => serving != null)
  // Unknown serving weights cannot justify combining a label portion with 100g data.
  const useServing = (hasServing && !!label) || (factor != null && !!label)
  const value = (field: keyof typeof fields) => {
    const [serving, hundred] = fields[field]
    if (!useServing) return hundred
    return serving ?? (hundred != null && factor != null ? hundred * factor : null)
  }
  return {
    serving_size: useServing ? label : `100 ${volume || product?.serving_quantity_unit === 'ml' ? 'ml' : 'g'}`,
    calories: value('calories'), protein_g: value('protein_g'), carbs_g: value('carbs_g'),
    fat_g: value('fat_g'), fiber_g: value('fiber_g'), sugar_g: value('sugar_g'),
    // Values are now canonical kcal per the displayed serving. Never convert/scale twice.
    basis: 'per_serving' as const,
    energyUnit: 'kcal' as const,
  }
}

import { optionalNutrient, roundOptionalNutrient, scaleOptionalNutrient, sumOptionalNutrients } from './nutrient-values'

const KEYS = ['calories', 'protein_g', 'carbs_g', 'fat_g', 'fiber_g', 'sugar_g'] as const
export type RecommendedMacroTotals = Record<(typeof KEYS)[number], number | null>
export type RecommendedNutritionItem = Partial<RecommendedMacroTotals> & { name?: string; servings: number }

// Sum original per-serving values at full precision. A removed (zero-count)
// ingredient contributes nothing; a missing value in an eaten ingredient
// makes that nutrient's total unknown, never a smaller apparently complete sum.
export function computeRecommendedTotals(items: RecommendedNutritionItem[]): RecommendedMacroTotals {
  const totals: RecommendedMacroTotals = { calories: 0, protein_g: 0, carbs_g: 0, fat_g: 0, fiber_g: 0, sugar_g: 0 }
  for (const item of items) {
    for (const key of KEYS) totals[key] = sumOptionalNutrients(totals[key], scaleOptionalNutrient(item[key], item.servings))
  }
  return totals
}

export function recommendationNutritionError(items: RecommendedNutritionItem[]): string | null {
  if (!items.length || items.every(item => item.servings === 0)) return 'This meal has no ingredients with a positive amount. Adjust an ingredient before saving.'
  for (const item of items) {
    if (!Number.isFinite(item.servings) || item.servings < 0 || item.servings > 20) return 'Please enter a valid ingredient amount before saving.'
    if (item.servings === 0) continue
    if (KEYS.slice(0, 4).some(key => optionalNutrient(item[key]) == null)) {
      return `Nutrition is incomplete for ${item.name || 'an ingredient'}. Use Build this meal to find a matching food before saving.`
    }
  }
  return null
}

export function recommendedFoodLogTotals(totals: RecommendedMacroTotals) {
  return {
    calories: roundOptionalNutrient(totals.calories, 0),
    protein: roundOptionalNutrient(totals.protein_g, 3),
    carbs: roundOptionalNutrient(totals.carbs_g, 3),
    fat: roundOptionalNutrient(totals.fat_g, 3),
    fiber: roundOptionalNutrient(totals.fiber_g, 3),
    sugar: roundOptionalNutrient(totals.sugar_g, 3),
  }
}

import { convertFoodAmount, liquidDensity, liquidHouseholdMl, parseFoodServing, type FoodBaseUnit } from '../../native/src/lib/foodUnits'
import { formatUnitLabel, getAllowedUnitsForFood, getFoodUnitGrams, isLiquidFood, type MeasurementUnit } from './measurement-units'

export type ItemMeasurementUnit = MeasurementUnit | 'fl oz'
type Basis = { amount: number; unit: 'g' | 'ml' }
const positive = (value: unknown): number | null => {
  if (value == null || typeof value === 'boolean' || String(value).trim() === '') return null
  const number = Number(value)
  return Number.isFinite(number) && number > 0 ? number : null
}
const nameOf = (item: any) => String(item?.name || item?.food || '')
const volumeUnits: Partial<Record<ItemMeasurementUnit, number>> = {
  ml: 1, 'fl oz': 29.5735295625,
}
const cupFractions: Partial<Record<ItemMeasurementUnit, number>> = {
  'quarter-cup': 0.25, 'half-cup': 0.5, 'three-quarter-cup': 0.75, cup: 1,
}
const metricBasis = (amount: number, unit: FoodBaseUnit): Basis => ({
  amount: unit === 'oz' ? amount * 28.349523125 : unit === 'fl oz' ? amount * 29.5735295625 : amount,
  unit: unit === 'ml' || unit === 'fl oz' ? 'ml' : 'g',
})

// These are recorded serving/custom measurements, not estimates from calories
// or generic "one serving" weights. Keep the existing per-piece multiplier.
export function recordedServingBasis(item: any, multiplier = 1): Basis | null {
  const grams = positive(item?.customGramsPerServing)
  const ml = positive(item?.customMlPerServing)
  const parsed = parseFoodServing(String(item?.serving_size || ''), nameOf(item))
  if (parsed) {
    const basis = metricBasis(parsed.amount, parsed.unit)
    const custom = basis.unit === 'g' ? grams : ml
    return { amount: custom ?? basis.amount * multiplier, unit: basis.unit }
  }
  if (grams != null) return { amount: grams, unit: 'g' }
  if (ml != null) return { amount: ml, unit: 'ml' }
  return null
}

const quantity = (text: string, kind: string): number | null => {
  const token = kind === 'cup' ? 'cups?' : kind === 'tbsp' ? '(?:tbsp|tablespoons?)' : '(?:tsp|teaspoons?)'
  const match = text.match(new RegExp(`(?:^|[\\s(])(\\d+\\s+\\d+\\/\\d+|\\d+\\/\\d+|\\d+(?:\\.\\d+)?)\\s*${token}\\b`))
  if (!match) return 1
  const parts = match[1].split(/\s+/)
  const fraction = parts.pop()!
  const pair = fraction.split('/')
  const value = pair.length === 2 ? Number(pair[0]) / Number(pair[1]) : Number(fraction)
  return positive(value + (parts.length ? Number(parts[0]) : 0))
}

function recordedHouseholdMeasure(item: any, unit: ItemMeasurementUnit): Basis | null {
  const target = cupFractions[unit] ? 'cup' : unit
  if (!['cup', 'tsp', 'tbsp'].includes(target)) return null
  for (const option of [item, ...(Array.isArray(item?.servingOptions) ? item.servingOptions : [])]) {
    const label = String(option?.serving_size || option?.label || '').toLowerCase()
    const kind = /\bcups?\b/.test(label) ? 'cup' : /\b(tbsp|tablespoons?)\b/.test(label) ? 'tbsp' : /\b(tsp|teaspoons?)\b/.test(label) ? 'tsp' : null
    if (kind !== target) continue
    const count = quantity(label, kind)
    if (count == null) continue
    const parsed = parseFoodServing(label, nameOf(item))
    const basis = parsed ? metricBasis(parsed.amount, parsed.unit)
      : positive(option?.grams) != null ? { amount: Number(option.grams), unit: 'g' as const }
      : positive(option?.ml) != null ? { amount: Number(option.ml), unit: 'ml' as const } : null
    if (basis) return { ...basis, amount: basis.amount / count * (cupFractions[unit] || 1) }
  }
  return null
}

function unitMeasure(item: any, unit: ItemMeasurementUnit, pieceGrams?: number | null, multiplier = 1, country = ''): Basis | null {
  if (unit === 'serving') return recordedServingBasis(item, multiplier)
  if (unit === 'g') return { amount: 1, unit: 'g' }
  if (unit === 'oz') return { amount: 28.349523125, unit: 'g' }
  if (unit === 'ml' || unit === 'fl oz') return { amount: volumeUnits[unit]!, unit: 'ml' }
  const recorded = recordedHouseholdMeasure(item, unit)
  if (recorded) return recorded
  const householdMl = liquidHouseholdMl(country)[unit]
  if (isLiquidFood(nameOf(item)) && householdMl) return { amount: householdMl, unit: 'ml' }
  const grams = positive(getFoodUnitGrams(nameOf(item))?.[unit as MeasurementUnit])
    ?? (unit === 'piece' || unit === 'slice' ? positive(pieceGrams) : null)
  return grams == null ? null : { amount: grams, unit: 'g' }
}

export function convertItemMeasurement(amount: number, from: ItemMeasurementUnit, to: ItemMeasurementUnit, item: any, pieceGrams?: number | null, multiplier = 1, regions?: { fromCountry?: string; toCountry?: string }): number | null {
  if (!Number.isFinite(amount) || amount <= 0) return null
  // Count-only foods can still be adjusted by their recorded serving.
  if (from === 'serving' && to === 'serving') return amount
  const source = unitMeasure(item, from, pieceGrams, multiplier, regions?.fromCountry)
  const target = unitMeasure(item, to, pieceGrams, multiplier, regions?.toCountry)
  if (!source || !target) return null
  const converted = convertFoodAmount(amount * source.amount, source.unit, target.unit, liquidDensity(nameOf(item)))
  return Number.isFinite(converted) && converted > 0 ? converted / target.amount : null
}

export function servingRatioFromMeasurement(item: any, amount: number, unit: ItemMeasurementUnit, multiplier = 1): number | null {
  return convertItemMeasurement(amount, unit, 'serving', item, null, multiplier)
}

export function itemMeasurementUnitOptions(item: any, pieceGrams?: number | null, country = ''): ItemMeasurementUnit[] {
  const basis = recordedServingBasis(item)
  if (!basis) return ['serving']
  const candidates: ItemMeasurementUnit[] = [...getAllowedUnitsForFood(nameOf(item), pieceGrams)]
  if (basis.unit === 'ml' || liquidDensity(nameOf(item)) != null) candidates.push('ml', 'fl oz')
  return [...new Set(candidates)].filter(unit => convertItemMeasurement(1, unit, 'serving', item, pieceGrams, 1, { fromCountry: country }) != null)
}

export function formatItemMeasurementUnit(item: any, unit: ItemMeasurementUnit, pieceGrams?: number | null, country = ''): string {
  if (unit === 'g' || unit === 'ml' || unit === 'oz' || unit === 'fl oz') return unit
  if (unit.startsWith('piece') || unit.startsWith('egg') || unit === 'slice') return formatUnitLabel(unit as MeasurementUnit, nameOf(item), pieceGrams)
  const measure = unitMeasure(item, unit, pieceGrams, 1, country)
  const label = ({ 'quarter-cup': '1/4 cup', 'half-cup': '1/2 cup', 'three-quarter-cup': '3/4 cup' } as Partial<Record<ItemMeasurementUnit, string>>)[unit] || unit
  return measure ? `${label} — ${Number(measure.amount.toFixed(3))} ${measure.unit}` : label
}

export function itemMeasurementPhysicalAmount(item: any, amount: number, unit: ItemMeasurementUnit, country = ''): Basis | null {
  if (!Number.isFinite(amount) || amount <= 0) return null
  const measure = unitMeasure(item, unit, null, 1, country)
  return measure ? { amount: amount * measure.amount, unit: measure.unit } : null
}

const words = (value: unknown) => String(value ?? '').toLowerCase().replace(/[^a-z0-9.%]+/g, ' ').replace(/\s+/g, ' ').trim()
const plantKinds = ['almond', 'oat', 'soy', 'coconut', 'rice', 'cashew', 'hemp', 'pea', 'macadamia']
const otherFood = /\b(babyfood|baby food|cereal|oatmeal|porridge|bar|bars|cheese|yogurt|yoghurt|bread|pudding|custard|dessert|cake|cookie|cookies|pie|potato|candy|candies|nougat|chicken|egg|eggs|pancake|pancakes|soup|sauce|creamer|whitener)\b/

// These aliases affect matching only. Never rename a returned provider record
// or alter its nutrient values, portion basis, identity or preparation.
export function milkSearchText(value: unknown): string {
  return words(value)
    .replace(/\b(almond|oat|soy|coconut|rice|cashew|hemp|pea|macadamia)milk\b/g, '$1 milk')
    .replace(/\b(?:skim|skimmed)\b/g, 'nonfat')
    .replace(/\bfat[ -]free\b/g, 'nonfat')
    .replace(/\bfull cream\b/g, 'whole')
    .replace(/\blow fat\b/g, 'lowfat')
    .replace(/\b(\d+(?:\.\d+)?)\s*%/g, '$1 percent ')
    .replace(/\s+/g, ' ').trim()
}

export function isSingleMilkQuery(value: unknown): boolean {
  const text = milkSearchText(value)
  return /\bmilk\b/.test(text) && !otherFood.test(text)
}

export function singleMilkLookupQueries(value: string): string[] {
  if (!isSingleMilkQuery(value)) return [value]
  const normalized = milkSearchText(value)
  const compound = normalized.replace(/\b(almond|oat|soy|coconut|rice|cashew|hemp|pea|macadamia) milk\b/g, '$1milk')
  // Preserve the literal query (including percentage symbols) for database
  // records, and add only the known spelling/label aliases, not looser foods.
  return Array.from(new Set([value, normalized, compound]))
}

export function isSingleMilkIdentityCompatible(name: unknown, query: unknown): boolean {
  if (!isSingleMilkQuery(query)) return true
  const candidate = milkSearchText(name)
  const requested = milkSearchText(query)
  if (!/\bmilk\b/.test(candidate) || otherFood.test(candidate) || /\bprepared with\b/.test(candidate)) return false
  const requestedPlant = plantKinds.find(kind => new RegExp(`\\b${kind} milk\\b|\\bmilk (?:of )?${kind}\\b`).test(requested))
  if (requestedPlant && !new RegExp(`\\b${requestedPlant} milk\\b|\\bmilk (?:of )?${requestedPlant}\\b`).test(candidate)) return false
  if (!requestedPlant && /\b(nonfat|whole|lowfat|reduced fat)\b/.test(requested) && plantKinds.some(kind => new RegExp(`\\b${kind} milk\\b|\\bmilk (?:of )?${kind}\\b`).test(candidate))) return false
  for (const variant of ['chocolate', 'buttermilk', 'dry', 'dried', 'powder', 'condensed', 'evaporated']) {
    if (new RegExp(`\\b${variant}\\b`).test(candidate) && !new RegExp(`\\b${variant}\\b`).test(requested)) return false
  }
  if (/\bnonfat\b/.test(requested) && !/\bnonfat\b/.test(candidate)) return false
  if (/\bwhole\b/.test(requested) && !/\bwhole\b/.test(candidate)) return false
  const percentage = requested.match(/(?:^|\s)(\d+(?:\.\d+)?) percent\b/)
  if (percentage && !Array.from(candidate.matchAll(/(?:^|\s)(\d+(?:\.\d+)?) percent\b/g)).some(match => Number(match[1]) === Number(percentage[1]))) return false
  return true
}

import { prisma } from '@/lib/prisma';

/**
 * Free Credits System
 * 
 * New users receive:
 * - 5 x Food image analysis
 * - 2 x Symptom notes
 * - 2 x Health image notes
 * - 2 x Supplement/Medication interaction analysis
 * - 1 x Full Health intake analysis (when completing onboarding page 11)
 * - 3 x Insights updates (when changing health setup)
 * - 2 x Symptom follow-up chats
 * - 2 x Medical image follow-up chats
 * - 2 x Insights chats
 * - 2 x Voice chats
 * - 2 x Food re-analyses
 * - 2 x Interaction re-analyses
 * 
 * These credits are consumed BEFORE wallet credits.
 * Low credits warning only shows AFTER free credits are exhausted.
 */

export type FreeCreditType = 
  | 'FOOD_ANALYSIS'
  | 'FOOD_REANALYSIS'
  | 'SYMPTOM_ANALYSIS'
  | 'SYMPTOM_CHAT'
  | 'MEDICAL_ANALYSIS'
  | 'MEDICAL_CHAT'
  | 'INTERACTION_ANALYSIS'
  | 'INTERACTION_REANALYSIS'
  | 'SUPPLEMENT_IMAGE'
  | 'MEDICATION_IMAGE'
  | 'HEALTH_INTAKE'
  | 'INSIGHTS_UPDATE'
  | 'INSIGHTS_CHAT'
  | 'VOICE_CHAT';

const FREE_CREDIT_FIELDS: Record<FreeCreditType, keyof any> = {
  FOOD_ANALYSIS: 'freeFoodAnalysisRemaining',
  FOOD_REANALYSIS: 'freeFoodReanalysisRemaining',
  SYMPTOM_ANALYSIS: 'freeSymptomAnalysisRemaining',
  SYMPTOM_CHAT: 'freeSymptomChatRemaining',
  MEDICAL_ANALYSIS: 'freeMedicalAnalysisRemaining',
  MEDICAL_CHAT: 'freeMedicalChatRemaining',
  INTERACTION_ANALYSIS: 'freeInteractionAnalysisRemaining',
  INTERACTION_REANALYSIS: 'freeInteractionReanalysisRemaining',
  SUPPLEMENT_IMAGE: 'freeSupplementImageRemaining',
  MEDICATION_IMAGE: 'freeMedicationImageRemaining',
  HEALTH_INTAKE: 'freeHealthIntakeRemaining',
  INSIGHTS_UPDATE: 'freeInsightsUpdateRemaining',
  INSIGHTS_CHAT: 'freeInsightsChatRemaining',
  VOICE_CHAT: 'freeVoiceChatRemaining',
};

export const EXTRA_FREE_CREDITS = {
  freeSymptomChatRemaining: 2,
  freeMedicalChatRemaining: 2,
  freeInsightsChatRemaining: 2,
  freeVoiceChatRemaining: 2,
  freeFoodReanalysisRemaining: 2,
  freeInteractionReanalysisRemaining: 2,
};

export const NEW_USER_FREE_CREDITS = {
  freeFoodAnalysisRemaining: 5,
  freeSymptomAnalysisRemaining: 2,
  freeMedicalAnalysisRemaining: 2,
  freeInteractionAnalysisRemaining: 2,
  freeSupplementImageRemaining: 10,
  freeMedicationImageRemaining: 10,
  freeHealthIntakeRemaining: 1,
  freeInsightsUpdateRemaining: 3,
  ...EXTRA_FREE_CREDITS,
};

export async function ensureFreeCreditColumns() {
  try {
    await prisma.$executeRawUnsafe(`
      ALTER TABLE "User"
        ADD COLUMN IF NOT EXISTS "freeSymptomChatRemaining" INT DEFAULT 0,
        ADD COLUMN IF NOT EXISTS "freeMedicalChatRemaining" INT DEFAULT 0,
        ADD COLUMN IF NOT EXISTS "freeInsightsChatRemaining" INT DEFAULT 0,
        ADD COLUMN IF NOT EXISTS "freeVoiceChatRemaining" INT DEFAULT 0,
        ADD COLUMN IF NOT EXISTS "freeFoodReanalysisRemaining" INT DEFAULT 0,
        ADD COLUMN IF NOT EXISTS "freeInteractionReanalysisRemaining" INT DEFAULT 0,
        ADD COLUMN IF NOT EXISTS "freeSupplementImageRemaining" INT DEFAULT 0,
        ADD COLUMN IF NOT EXISTS "freeMedicationImageRemaining" INT DEFAULT 0
    `)
  } catch (error) {
    console.warn('Failed to ensure free credit columns:', error)
  }
}

/**
 * Check if user has free credits remaining for a feature
 */
export async function hasFreeCredits(
  userId: string,
  creditType: FreeCreditType
): Promise<boolean> {
  await ensureFreeCreditColumns()
  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: { [FREE_CREDIT_FIELDS[creditType]]: true } as any,
  });

  if (!user) return false;

  const remaining = (user as any)[FREE_CREDIT_FIELDS[creditType]] as number | undefined;
  return (remaining ?? 0) > 0;
}

/**
 * Consume one free credit for a feature
 * Returns true if credit was consumed, false if none available
 */
export async function consumeFreeCredit(
  userId: string,
  creditType: FreeCreditType
): Promise<boolean> {
  await ensureFreeCreditColumns()
  const field = FREE_CREDIT_FIELDS[creditType];

  // Check current value
  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: { [field]: true } as any,
  });

  if (!user) return false;

  const current = (user as any)[field] as number | undefined;
  if (!current || current <= 0) return false;

  // Decrement the counter
  try {
    await prisma.user.update({
      where: { id: userId },
      data: {
        [field]: {
          decrement: 1,
        },
      } as any,
    });
    return true;
  } catch (error) {
    console.error(`Failed to consume free credit for ${creditType}:`, error);
    return false;
  }
}

/**
 * Get all free credit counts for a user
 */
export async function getFreeCreditsStatus(userId: string) {
  await ensureFreeCreditColumns()
  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: {
      createdAt: true,
      freeFoodAnalysisRemaining: true,
      freeFoodReanalysisRemaining: true,
      freeSymptomAnalysisRemaining: true,
      freeSymptomChatRemaining: true,
      freeMedicalAnalysisRemaining: true,
      freeMedicalChatRemaining: true,
      freeInteractionAnalysisRemaining: true,
      freeInteractionReanalysisRemaining: true,
      freeSupplementImageRemaining: true,
      freeMedicationImageRemaining: true,
      freeHealthIntakeRemaining: true,
      freeInsightsUpdateRemaining: true,
      freeInsightsChatRemaining: true,
      freeVoiceChatRemaining: true,
    } as any,
  });

  if (!user) {
    return {
      food: 0,
      foodReanalysis: 0,
      symptom: 0,
      symptomChat: 0,
      medical: 0,
      medicalChat: 0,
      interaction: 0,
      interactionReanalysis: 0,
      supplementImage: 0,
      medicationImage: 0,
      healthIntake: 0,
      insights: 0,
      insightsChat: 0,
      voiceChat: 0,
      total: 0,
    };
  }

  const food = (user as any).freeFoodAnalysisRemaining ?? 0;
  let foodReanalysis = (user as any).freeFoodReanalysisRemaining ?? 0;
  const symptom = (user as any).freeSymptomAnalysisRemaining ?? 0;
  let symptomChat = (user as any).freeSymptomChatRemaining ?? 0;
  const medical = (user as any).freeMedicalAnalysisRemaining ?? 0;
  let medicalChat = (user as any).freeMedicalChatRemaining ?? 0;
  const interaction = (user as any).freeInteractionAnalysisRemaining ?? 0;
  let interactionReanalysis = (user as any).freeInteractionReanalysisRemaining ?? 0;
  const supplementImage = (user as any).freeSupplementImageRemaining ?? 0;
  const medicationImage = (user as any).freeMedicationImageRemaining ?? 0;
  const healthIntake = (user as any).freeHealthIntakeRemaining ?? 0;
  const insights = (user as any).freeInsightsUpdateRemaining ?? 0;
  let insightsChat = (user as any).freeInsightsChatRemaining ?? 0;
  let voiceChat = (user as any).freeVoiceChatRemaining ?? 0;

  const extrasTotal =
    symptomChat +
    medicalChat +
    insightsChat +
    voiceChat +
    foodReanalysis +
    interactionReanalysis;

  const createdAt = (user as any).createdAt ? new Date((user as any).createdAt).getTime() : 0;
  const isRecentAccount = createdAt > 0 && Date.now() - createdAt <= 7 * 24 * 60 * 60 * 1000;

  if (extrasTotal === 0 && isRecentAccount) {
    try {
      await prisma.user.update({
        where: { id: userId },
        data: EXTRA_FREE_CREDITS as any,
      });
      symptomChat = EXTRA_FREE_CREDITS.freeSymptomChatRemaining;
      medicalChat = EXTRA_FREE_CREDITS.freeMedicalChatRemaining;
      insightsChat = EXTRA_FREE_CREDITS.freeInsightsChatRemaining;
      voiceChat = EXTRA_FREE_CREDITS.freeVoiceChatRemaining;
      foodReanalysis = EXTRA_FREE_CREDITS.freeFoodReanalysisRemaining;
      interactionReanalysis = EXTRA_FREE_CREDITS.freeInteractionReanalysisRemaining;
    } catch (error) {
      console.warn('Failed to backfill free credits:', error);
    }
  }

  return {
    food,
    foodReanalysis,
    symptom,
    symptomChat,
    medical,
    medicalChat,
    interaction,
    interactionReanalysis,
    supplementImage,
    medicationImage,
    healthIntake,
    insights,
    insightsChat,
    voiceChat,
    total:
      food +
      foodReanalysis +
      symptom +
      symptomChat +
      medical +
      medicalChat +
      interaction +
      interactionReanalysis +
      supplementImage +
      medicationImage +
      healthIntake +
      insights +
      insightsChat +
      voiceChat,
  };
}

/**
 * Check if user has exhausted all free credits
 */
export async function hasExhaustedFreeCredits(userId: string): Promise<boolean> {
  const status = await getFreeCreditsStatus(userId);
  return status.total === 0;
}

import { prisma } from '@/lib/prisma'

/**
 * Ensure Garmin tables exist (idempotent).
 * Vercel builds don’t run `prisma migrate deploy` in this repo, so we defensively create tables at runtime.
 */
export async function ensureGarminSchema(): Promise<void> {
  try {
    await prisma.$executeRawUnsafe(`
      CREATE TABLE IF NOT EXISTS "GarminRequestToken" (
        "id" TEXT NOT NULL,
        "userId" TEXT NOT NULL,
        "oauthToken" TEXT NOT NULL,
        "oauthTokenSecret" TEXT NOT NULL,
        "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
        "expiresAt" TIMESTAMP(3),
        CONSTRAINT "GarminRequestToken_pkey" PRIMARY KEY ("id")
      );
    `)

