  if (_openai) return _openai
  const apiKey = process.env.OPENAI_API_KEY
  if (!apiKey) {
    console.warn('[insights.llm] Missing OPENAI_API_KEY; LLM calls will be skipped')
    return null
  }

  const OpenAI = require('openai').default
  _openai = new OpenAI({ apiKey })
  return _openai
}

export function getInsightsLlmStatus() {
  const raw = (process.env.ENABLE_INSIGHTS_LLM || '').toLowerCase().trim()
  const enabled = raw === 'true' || raw === '1' || raw === 'yes'
  const apiKeyPresent = typeof process.env.OPENAI_API_KEY === 'string' && process.env.OPENAI_API_KEY.trim().length > 0
  return {
    enabled,
    apiKeyPresent,
    model: DEFAULT_INSIGHTS_MODEL,
  }
}

function logLlmEvent(reason: string, extra: Record<string, unknown> = {}) {
  const ctx = getRunContext()
  const meta = ctx?.meta
  const payload = {
    runId: ctx?.runId ?? null,
    feature: ctx?.feature ?? 'insights:unknown',
    userId: meta?.userId ?? extra.userId ?? null,
    changeTypes: meta?.changeTypes,
    sections: meta?.sections,
    phase: meta?.phase ?? 'full',
    ...extra,
  }
  console.log('[insights.llm]', reason, payload)
}

async function createCompletion(
  params: any,
  context: { feature: string; userId?: string | null; issueSlug?: string | null; runId?: string | null } = {
    feature: 'insights:unknown',
  }
) {
  const openai = getOpenAIClient()
  const runCtx = getRunContext()
  const runId = runCtx?.runId ?? null
  if (!openai) {
    logLlmEvent('skipped:llm-unavailable', {
      userId: context.userId ?? runCtx?.meta?.userId ?? null,
      issueSlug: context.issueSlug ?? null,
      reason: 'missing-openai-or-flag-disabled',
    })
    return null
  }

  logLlmEvent('llm-call:start', {
    userId: context.userId ?? runCtx?.meta?.userId ?? null,
    issueSlug: context.issueSlug ?? null,
    model: params?.model,
  })
  return runChatCompletionWithLogging(
    openai,
    params,
    { ...context, runId },
    { callDetail: `${context.feature || 'insights:unknown'}:${params?.model || ''}` }
  )
}

const DEFAULT_INSIGHTS_MODEL = 'gpt-5.6-sol'

const llmSectionSchema = z.object({
  summary: z.string().optional(),
  working: z
    .array(
      z.object({
        name: z.string(),
        reason: z.string().min(1),
        dosage: z.string().optional().nullable(),
        timing: z.string().optional().nullable(),
      })
    )
    .default([]),
  suggested: z
    .array(
      z.object({
        name: z.string(),
        reason: z.string().min(1),
        protocol: z.string().optional().nullable(),
      })
    )
    .default([]),
  avoid: z
    .array(
      z.object({
        name: z.string(),
        reason: z.string().min(1),
      })
    )
    .default([]),
  recommendations: z
    .array(
      z.object({
        title: z.string(),
        description: z.string(),
        actions: z.array(z.string()).default([]),
        priority: z.enum(['now', 'soon', 'monitor']).default('monitor'),
      })
    )
    .default([]),
})

export type SectionLLMResult = z.infer<typeof llmSectionSchema>

type SectionMode =
  | 'supplements'
  | 'medications'
  | 'exercise'
  | 'nutrition'
  | 'lifestyle'
  | 'labs'

interface LLMInputData {
  issueName: string
  issueSummary?: string | null
  issueSlug?: string | null
  items?: Array<{ name: string; dosage?: string | null; timing?: string[] | null }>
  otherItems?: Array<{ name: string; dosage?: string | null }>
  profile?: {
    gender?: string | null
    weight?: number | null
    height?: number | null
    bodyType?: string | null
    exerciseFrequency?: string | null
    exerciseTypes?: string[] | null
    healthSituations?: {
      healthIssues?: string | null
      healthProblems?: string | null
      additionalInfo?: string | null
      skipped?: boolean | null
    }
  }
  userId?: string | null
  mode: SectionMode
}

interface LLMOptions {
  minWorking?: number
  minSuggested?: number
  minAvoid?: number
  maxRetries?: number
  disableCache?: boolean
}

type CanonicalType = 'food' | 'supplement' | 'exercise' | 'medication' | 'other'

interface ClassificationEntry {
  name: string
  reason?: string | null
}

interface ClassifiedItem {
  name: string
  canonicalType: CanonicalType
  inDomain: boolean
  explanation?: string
}

export interface GeneratedCandidateItem {
  name: string
  candidateType: CanonicalType
  bucket: 'suggested' | 'avoid'
  reason: string
  protocol?: string | null
}

export async function generateSectionCandidates(params: {
  issueName: string
  issueSummary?: string | null
  profile?: LLMInputData['profile']
  mode: SectionMode
  count?: { suggested?: number; avoid?: number }
  userId?: string | null
  issueSlug?: string | null
}): Promise<GeneratedCandidateItem[] | null> {
  const openai = getOpenAIClient()
  if (!openai) return null
  const suggested = Math.max(4, params.count?.suggested ?? 6)
  const avoid = Math.max(4, params.count?.avoid ?? 6)

  // Add exercise-specific guidance for intake exerciseTypes
  const exerciseGuidance = params.mode === 'exercise' && params.profile?.exerciseTypes?.length
    ? `\n\nCRITICAL FOR EXERCISE MODE: The user has selected these exercise types in their health intake: ${JSON.stringify(params.profile.exerciseTypes)}. Evaluate each exercise against "${params.issueName}" - if supportive, consider including them in suggested (they will be promoted to working if they match intake selections).`
    : ''

    const user = `Write SECTION: ${params.mode} for issue "${params.issueName}".
Generate only two arrays: suggested and avoid. Each item must include: name, candidateType guess ∈ {food,supplement,exercise,medication,other}, reason (two sentences: mechanism + direct relevance), and optional protocol.
Counts: suggested≥${suggested}, avoid≥${avoid}.
Profile: ${JSON.stringify(params.profile ?? {}, null, 2)}${exerciseGuidance}
Return strict JSON {"suggested": [...], "avoid": [...]}`
  try {
    console.time(`[insights.genCandidates:${params.mode}]`)
    const response: any = await createCompletion({
      model: DEFAULT_INSIGHTS_MODEL,
      temperature: 0.2,
      max_tokens: 700,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: 'You propose domain-appropriate items with concise clinical reasons. Output JSON only.' },
        { role: 'user', content: user },
      ],
    }, { feature: `insights:generate-section-candidates:${params.mode}`, userId: params.userId, issueSlug: params.issueSlug ?? null })
    console.timeEnd(`[insights.genCandidates:${params.mode}]`)
    const content = response.choices?.[0]?.message?.content
    if (!content) return null
    let json: any
    try {
      json = JSON.parse(content)
    } catch {
      const stripped = content.replace(/```[a-zA-Z]*\n?|```/g, '').trim()
      const objMatch = stripped.match(/\{[\s\S]*\}/)
      if (!objMatch) return null
      json = JSON.parse(objMatch[0])
    }
    const all: GeneratedCandidateItem[] = []
    const pushItems = (arr: any[], bucket: 'suggested' | 'avoid') => {
      for (const it of Array.isArray(arr) ? arr : []) {
        if (!it || typeof it.name !== 'string' || typeof it.reason !== 'string') continue
        const ct = typeof it.candidateType === 'string' ? String(it.candidateType).toLowerCase() : 'other'
        const canonicalType: CanonicalType =
          ct === 'food' || ct === 'supplement' || ct === 'exercise' || ct === 'medication' ? (ct as CanonicalType) : 'other'
        all.push({
          name: it.name,
          candidateType: canonicalType,
          bucket,
          reason: it.reason,
          protocol: typeof it.protocol === 'string' ? it.protocol : null,
        })
      }
    }
    pushItems(json?.suggested, 'suggested')
    pushItems(json?.avoid, 'avoid')
    return all
  } catch (error) {
    console.warn('[insights.llm] generateSectionCandidates error', error)
    return null
  }
}

function allowedCanonicalTypesForMode(mode: SectionMode): Set<CanonicalType> | null {
  switch (mode) {
    case 'nutrition':
      return new Set<CanonicalType>(['food'])
    case 'exercise':
      return new Set<CanonicalType>(['exercise'])
    case 'supplements':
      return new Set<CanonicalType>(['supplement'])
    case 'medications':
      return new Set<CanonicalType>(['medication'])
    default:
      return null // no strict filtering for lifestyle/labs
  }
}

function meetsMinimums(
  data: SectionLLMResult,
  { minWorking, minSuggested, minAvoid }: { minWorking: number; minSuggested: number; minAvoid: number }
) {
  const workingOk = minWorking === 0 || data.working.length >= minWorking
  const suggestedOk = data.suggested.length >= minSuggested
  const avoidOk = data.avoid.length >= minAvoid
  return workingOk && suggestedOk && avoidOk
}

function scoreCandidate(data: SectionLLMResult) {
  // Weight suggested/avoid slightly higher because they matter most for actionability.
  return data.working.length * 2 + data.suggested.length * 3 + data.avoid.length * 3 + data.recommendations.length
}

interface RepairArgs {
  mode: SectionMode
  issueName: string
  issueSummary?: string | null
  minWorking: number
  minSuggested: number
  minAvoid: number
  focusItems: Array<{ name: string; dosage?: string | null; timing?: string[] | null }>
  otherItems: Array<{ name: string; dosage?: string | null }>
  profile?: LLMInputData['profile']
  previous: SectionLLMResult
}

async function repairLLMOutput({
  mode,
  issueName,
  issueSummary,
  minWorking,
  minSuggested,
  minAvoid,
  focusItems,
  otherItems,
  profile,
  previous,
}: RepairArgs): Promise<SectionLLMResult | null> {
  try {
    const repairPrompt = `
You produced the following JSON guidance for "${issueName}" but it failed minimum coverage requirements. Revise it so every bucket meets the minimum counts.

Previous JSON:
${JSON.stringify(previous, null, 2)}

Context (focus items, other items, profile):
${JSON.stringify({ focusItems, otherItems, profile: profile ?? {} }, null, 2)}

Mode guidance:
${modeGuidance(mode)}

Issue summary:
${issueSummary ?? 'Not supplied.'}

Requirements:
- Suggested must contain at least ${minSuggested} unique items (not in focusItems unless altering protocol).
- Avoid must contain at least ${minAvoid} items relevant to ${issueName}.
- ${minWorking === 0 ? 'Working can remain empty if no focusItems support the issue, but explain why in the summary.' : `Working must contain at least ${minWorking} logged items when appropriate.`}
- Every reason must be two sentences: first sentence = mechanism; second sentence = direct relevance/action (include dose/timing when useful).
- Keep strictly to the JSON schema used previously (no additional keys).
- If data is sparse, rely on best-practice clinician guidance for ${issueName}; do not fabricate patient-specific logs.
`

    const response: any = await createCompletion({
      model: DEFAULT_INSIGHTS_MODEL,
      temperature: 0.05,
      max_tokens: 600,
      response_format: { type: 'json_object' },
      messages: [
        {
          role: 'system',
          content:
            'You are a careful health tracking assistant. Adjust prior guidance to meet explicit minimum requirements without omitting important safety details.',
        },
        {
          role: 'user',
          content: repairPrompt,
        },
      ],
    }, { feature: `insights:repair:${mode}` })
    const content = response.choices?.[0]?.message?.content
    if (!content) return null

    let json: unknown
    try {
      json = JSON.parse(content)
    } catch {
      const stripped = content.replace(/```[a-zA-Z]*\n?|```/g, '').trim()
      const objMatch = stripped.match(/\{[\s\S]*\}/)
      if (!objMatch) {
        console.warn('[insights.llm] Repair pass failed to locate JSON object', { content })
        return null
      }
      try {
        json = JSON.parse(objMatch[0])
      } catch (parseError) {
        console.warn('[insights.llm] Repair pass JSON parse failed', { content })
        return null
      }
    }

    const parsed = llmSectionSchema.safeParse(json)
    if (!parsed.success) {
      console.warn('[insights.llm] Repair pass produced invalid JSON', { issues: parsed.error.issues, content })
      return null
    }
    return parsed.data
  } catch (error) {
    console.error('[insights.llm] Repair pass failed', error)
    return null
  }
}

function modeGuidance(mode: SectionMode) {
  switch (mode) {
    case 'supplements':
      return 'Evaluate supplements only (herbs, vitamins, nutraceuticals). CRITICAL: You MUST analyze each logged supplement in focusItems by understanding its active ingredient(s) and mechanism of action. For brand-name supplements (e.g., "Super Miraforte", "Life Extension products"), you MUST research or recognize the product formulation and analyze it by its key ingredients. For example, if a user logs "Sunfiber", recognize it contains partially hydrolyzed guar gum (PHGG) and evaluate its impact on the issue. If a user logs a testosterone/libido supplement (e.g., products marketed for "men\'s health", "testosterone support", "libido"), analyze it by its key ingredients (zinc, chrysin, muira puama, maca, stinging nettle, lignans, etc.) and include it in "working" if those ingredients are supportive for the issue. However, ALWAYS output the exact logged name from focusItems (e.g., "Super Miraforte", not "Zinc" or "Muira Puama"). Identify which logged supplements are truly helpful for the issue, which novel additions to discuss with a clinician, and which supplements people with this issue should avoid or monitor. Never include alcohol, foods, or lifestyle items in this section.'
    case 'medications':
      return 'Evaluate prescription and OTC pharmaceutical therapies only (no supplements, herbs, nutraceuticals, or vitamins). CRITICAL: You MUST analyze each logged medication in focusItems by understanding its active ingredient(s), mechanism of action, and therapeutic class. For brand-name medications, recognize the generic/active ingredient but ALWAYS output the exact logged name from focusItems. Highlight medications that are supporting the issue, medication additions to discuss with a prescriber, and medications that warrant caution or avoidance.'
    case 'exercise':
      return 'Evaluate exercise and movement patterns. CRITICAL: You MUST check profile.exerciseTypes in the user context. If any exercises from profile.exerciseTypes are supportive for this issue, you MUST include them in the "working" bucket with a mechanism-based reason, even if no formal exercise logs exist. For logged exercises in focusItems, analyze their physiological effects and movement patterns. Highlight the training that supports this issue, recommended additions, and activities/protocols to limit or avoid. Always use the exact logged name from focusItems.'
    case 'nutrition':
      return 'Evaluate nutrition patterns using foods, meals, or dietary patterns only. Do not mention supplements or pills. CRITICAL: Analyze each logged food/meal in focusItems by understanding its macronutrient profile, micronutrients, and physiological effects. Recognize variations (e.g., "Chicken breast" vs "Grilled chicken") but ALWAYS output the exact logged name from focusItems. Highlight foods/meals that help, additions to include, and foods or dietary approaches to avoid for this issue. Only mark "working" foods that are present in focusItems.'
    case 'lifestyle':
      return 'Evaluate lifestyle habits (sleep, stress, routines). CRITICAL: Analyze each logged habit or pattern in focusItems by understanding its physiological and psychological mechanisms. Always use the exact logged name/description from focusItems. Highlight habits that are helping, habits to add, and habits/behaviours to avoid for this issue.'
    case 'labs':
      return `Evaluate labs and biomarker monitoring for PERSONAL HEALTH. CRITICAL: The issue name refers to a PERSONAL HEALTH CONDITION (e.g., "Energy" means personal energy/fatigue levels, NOT environmental energy efficiency). Analyze each logged lab result in focusItems by understanding what the biomarker measures and its relationship to the PERSONAL HEALTH issue. Always use the exact logged test name from focusItems. ONLY suggest health-related lab tests (blood tests, biomarkers, medical diagnostics). NEVER suggest environmental audits, energy efficiency tests, or any non-medical tests. Highlight labs already supporting the issue, labs to order or review, and labs/testing patterns that require caution.`
    default:
      return ''
  }
}

function hasDhtSensitivity(profile?: LLMInputData['profile']) {
  if (!profile?.healthSituations) return false
  const text = [
    profile.healthSituations.healthIssues,
    profile.healthSituations.healthProblems,
    profile.healthSituations.additionalInfo,
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase()
  if (!text) return false
  return /\bdht\b/.test(text) ||
    text.includes('dihydrotestosterone') ||
    text.includes('5-alpha') ||
    text.includes('5 alpha') ||
    text.includes('5α')
}

function buildPrompt(
  {
    issueName,
    issueSummary,
    userContext,
    mode,
    minWorking,
    minSuggested,
    minAvoid,
    force,
    dhtSensitive,
  }: {
    issueName: string
    issueSummary?: string | null
    userContext: string
    mode: SectionMode
    minWorking: number
    minSuggested: number
    minAvoid: number
    force: boolean
    dhtSensitive: boolean
  }
) {
  const guidanceFocus = modeGuidance(mode)
  // CRITICAL: Clarify that issue names refer to PERSONAL HEALTH, not environmental topics
  const issueClarification = mode === 'labs' 
    ? `\n\n⚠️ CRITICAL CONTEXT: The issue "${issueName}" refers to a PERSONAL HEALTH CONDITION. For example:\n- "Energy" means personal energy levels/fatigue, NOT environmental energy efficiency\n- "Sleep" means personal sleep quality, NOT sleep systems or sleep technology\n- "Libido" means personal sexual health, NOT libido in other contexts\n\nYou MUST ONLY generate health-related lab test recommendations (blood tests, biomarkers, medical diagnostics). NEVER suggest environmental audits, energy efficiency tests, sustainability assessments, or any non-medical tests.\n\n`
    : ''

  const header = `You are a clinician-grade health assistant helping with the PERSONAL HEALTH issue "${issueName}".${issueClarification}`

  // CRITICAL: Explicit instruction for exercise mode - must appear early in prompt
  const exerciseTypesInstruction = mode === 'exercise'
    ? `

═══════════════════════════════════════════════════════════════════════════════
🚨 EXERCISE MODE - CRITICAL INSTRUCTION: profile.exerciseTypes → "working" ONLY 🚨
═══════════════════════════════════════════════════════════════════════════════

BEFORE generating your response, you MUST:

1. Look at the user context JSON above
2. Find the "profile" object → locate the "exerciseTypes" array (e.g., ["Walking", "Bike riding", "Boxing"])
3. For EVERY exercise in profile.exerciseTypes:
   a) Evaluate: "Is this exercise supportive for "${issueName}"?"
   b) If YES → Add it to the "working" array (NOT suggested, NOT avoid - WORKING ONLY)
   c) Use the EXACT name from profile.exerciseTypes (preserve capitalization exactly)
   d) Provide a mechanism-based reason

🚨 CRITICAL RULE: Exercises from profile.exerciseTypes that are supportive MUST go in "working"
   - DO NOT put them in "suggested" 
   - DO NOT put them in "avoid"
   - They belong in "working" because the user has already selected them in their health intake

EXAMPLE: If profile.exerciseTypes = ["Walking", "Bike riding", "Boxing"] and issue = "Bowel Movements":
- Walking → Supportive (digestive stimulation) → MUST go in "working" array
- Bike riding → Evaluate → If supportive, MUST go in "working" array
- Boxing → Evaluate → If supportive, MUST go in "working" array

If profile.exerciseTypes = ["Walking"] and issue = "Libido":
- Walking → Supportive (cardiovascular, stress reduction) → MUST go in "working" array

The "suggested" array is ONLY for exercises NOT already in profile.exerciseTypes.
═══════════════════════════════════════════════════════════════════════════════

`
    : ''

  const baseGuidance = `
Provide precise, evidence-aligned guidance. Use the user context plus widely accepted best practice. If data is insufficient, state that but still offer clinician-ready suggestions.

CRITICAL: You MUST thoroughly analyze every item in focusItems (the user's logged items). For each item:
- Understand what it is at a fundamental level (ingredients, active compounds, mechanisms, nutritional profile, physiological effects)
- Evaluate how it impacts the current issue based on evidence-based mechanisms
- If it supports the issue, include it in "working" with a mechanism-based reason and optional dose/timing
- If it warrants caution for this issue, include it in "avoid" with a short clinical rationale
- If it is neutral/irrelevant, you may omit it (do not put in suggested)
- ALWAYS use the EXACT name from focusItems - never substitute with generic names, ingredient names, or alternative terminology

STRICT RULES:
- Prioritise logged items: if a focusItem is plausibly supportive for the issue, include it in "working" using the exact name from focusItems and provide rationale.
- Supplements mode: Analyze by active ingredient(s) but output exact logged name. Only include supplements/herbs/nutraceuticals. Never include alcohol, foods, or lifestyle items in any bucket.
- Medications mode: Analyze by active ingredient(s) and therapeutic class but output exact logged name (brand or generic as logged).
- Nutrition mode: Analyze by nutritional profile and physiological effects but output exact logged name. Only mark foods as "working" if they appear in focusItems. Use suggested/avoid for novel foods.
- Exercise mode: CRITICAL - You MUST check profile.exerciseTypes in the user context. If any exercises listed in profile.exerciseTypes are supportive for this issue, you MUST include them in the "working" bucket even if they don't appear in focusItems. Use the exact exercise name from profile.exerciseTypes and provide a mechanism-based reason explaining how it supports the issue. This is required when focusItems is empty or when intake exercises are relevant. For logged exercises, analyze physiological effects but use exact logged name.
- Lifestyle mode: Analyze mechanisms but use exact logged habit/pattern name.
- Labs mode: CRITICAL - ONLY generate health-related lab test recommendations (blood tests, biomarkers, medical diagnostics). The issue name refers to PERSONAL HEALTH (e.g., "Energy" = personal energy/fatigue, NOT environmental energy). NEVER suggest environmental audits, energy efficiency tests, or non-medical tests. Analyze biomarker significance but use exact logged test name.
- Reasons must include mechanism + relevance; add dose/timing or execution guidance where appropriate.
- If focusItems is empty but profile.exerciseTypes contains supportive exercises, those exercises MUST appear in "working" - do not leave working empty.
- Even if user data is sparse, you MUST still populate "suggested" and "avoid" to the minimum counts using widely accepted best practice for ${issueName}. Never respond with "everything covered."

Classify findings into three buckets: working (helpful/supportive today), suggested (worth discussing with clinician to add), avoid (risky or counterproductive). Always provide detailed clinical reasons (two sentences: mechanism + direct issue relevance/action). ${guidanceFocus}
Ensure the suggested array contains at least ${minSuggested} unique entries that are not already in the focusItems list, and avoid duplicating any names from focusItems unless you are recommending a changed protocol. Provide concise but specific reasons (mechanism + relevance) and include dosing/timing where appropriate.

Return JSON exactly matching this schema (no extra keys, no missing keys, do not rename fields):
{
  "summary": string,
  "working": Array<{"name": string, "reason": string, "dosage"?: string | null, "timing"?: string | null}>,
  "suggested": Array<{"name": string, "reason": string, "protocol"?: string | null}>,
  "avoid": Array<{"name": string, "reason": string}>,
  "recommendations": Array<{"title": string, "description": string, "actions": string[], "priority": "now" | "soon" | "monitor"}>
}
All strings must be non-empty and plain text. Use null when optional fields are unknown. Do not include title/description keys inside working/suggested/avoid items—use name/reason exactly. Suggestions must be novel relative to the focusItems and otherItems lists (case-insensitive) unless you are recommending a changed protocol.
Close every array/object and ensure the JSON is syntactically valid—never truncate or omit closing braces.
  `

  const forceNote = force
    ? `You must output at least ${minWorking} working item(s)${minWorking === 0 ? ' (it is acceptable for working to stay empty only if no focusItems are supportive AND no profile.exerciseTypes are supportive)' : ''}, ${minSuggested} suggested item(s), and ${minAvoid} avoid item(s). Suggested items must not duplicate any names already present in focusItems or otherItems. If logged data is sparse, rely on clinician-grade best-practice guidance for ${issueName} rather than saying everything is covered. Keep every reason to exactly two sentences (mechanism + actionable relevance with dose/timing when helpful).`
    : ''

  // Add targeted domain rules for specific issues
  const loweredIssue = issueName.toLowerCase()
  const libidoRules = loweredIssue.includes('libido') || loweredIssue.includes('erection')
    ? `\nIssue-specific rules for libido/erection quality:\n- Consider sex, age, weight/height, and training frequency when assessing androgen status and arousal.\n- Evaluate mechanisms: testosterone/DHT, nitric oxide/endothelial function, SHBG, stress/cortisol, sleep.\n- When focusItems include botanicals commonly discussed for libido (e.g., Tongkat Ali, Cistanche, Muira Puama), assess them and include in "working" if supportive with rationale; otherwise omit without moving them to suggested.\n- CRITICAL FOR BRAND-NAME SUPPLEMENTS: If a supplement name suggests testosterone/libido support (e.g., products with "testosterone", "libido", "men's health", "erection", "virility", "Miraforte", or similar marketing), analyze it by its key ingredients (zinc, chrysin, muira puama, maca, stinging nettle, lignans, tribulus, tongkat ali, etc.) and include it in "working" if those ingredients are supportive, even if you don't recognize the exact brand name. Use the exact logged name but explain the mechanism based on its ingredient profile.\n- For males, flag 5-alpha-reductase inhibitors (e.g., saw palmetto) as potential libido-reducing; explain the DHT rationale and advise clinician discussion.\n- Provide concrete protocols where possible (e.g., dosing ranges/timing windows).\n`
    : ''
  const dhtGuidance = dhtSensitive && (mode === 'supplements' || mode === 'medications')
    ? `\nUser note: they are sensitive to lowered DHT. Avoid recommending DHT-lowering items (e.g., saw palmetto, finasteride/dutasteride, fenugreek, high-dose spearmint/peppermint, reishi, licorice) unless clinically justified; if mentioned, place them in "avoid" with a caution.\n`
    : ''

  return `${header}\n\nIssue summary: ${issueSummary ?? 'Not supplied.'}\n\nUser context (JSON):\n${userContext}\n${exerciseTypesInstruction}\n${baseGuidance}\n${libidoRules}${dhtGuidance}${forceNote}`
}

function uniqueByName<T extends { name: string }>(items: T[]): T[] {
  const seen = new Set<string>()
  const out: T[] = []
  for (const it of items) {
    const key = it.name.trim().toLowerCase()
    if (seen.has(key)) continue
    seen.add(key)
    out.push(it)
  }
  return out
}

async function classifyCandidatesForSection(params: {
  issueName: string
  mode: SectionMode
  items: ClassificationEntry[]
  trace: string
  userId?: string | null
  issueSlug?: string | null
  runId?: string | null
}): Promise<ClassifiedItem[] | null> {
  const { issueName, mode, items, trace, userId, issueSlug, runId } = params
  if (!items.length) return []
  try {
    const system = 'You are a precise classifier. For each item, assign a canonicalType and whether it is in-domain for the requested section. Output strict JSON.'
    const user = `Classify the following items for issue "${issueName}" in SECTION: ${mode}.

Return JSON with an array under key "items"; each element: {"name": string, "canonicalType": one of [food,supplement,exercise,medication,other], "inDomain": boolean, "explanation": string}.

Items:\n${JSON.stringify(items, null, 2)}`

    console.time(`${trace}:classify`)
    const response: any = await createCompletion({
      model: DEFAULT_INSIGHTS_MODEL,
      temperature: 0,
      max_tokens: 500,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
    }, { feature: `insights:classify:${mode}`, userId, issueSlug, runId })
    console.timeEnd(`${trace}:classify`)

    const content = response.choices?.[0]?.message?.content
    if (!content) return null
    let json: any
    try {
      json = JSON.parse(content)
    } catch {
      const stripped = content.replace(/```[a-zA-Z]*\n?|```/g, '').trim()
      const objMatch = stripped.match(/\{[\s\S]*\}/)
      if (!objMatch) return null
      json = JSON.parse(objMatch[0])
    }
    const out = Array.isArray(json?.items) ? json.items : []
    return out
      .filter((it: any) => it && typeof it.name === 'string')
      .map((it: any) => ({
