/**
 * Evaluates user's logged items (focusItems) to identify which are supportive for the issue.
 * This is a fallback when the main LLM doesn't properly match logged names.
 * Analyzes items at ingredient/mechanism level but ALWAYS returns exact logged names.
 */
export async function evaluateFocusItemsForIssue(params: {
  issueName: string
  issueSummary?: string | null
  mode: SectionMode
  focusItems: Array<{ name: string; dosage?: string | null; timing?: string[] | null }>
}): Promise<Array<{ name: string; reason: string; dosage?: string | null; timing?: string | null }> | null> {
  const { issueName, issueSummary, mode, focusItems } = params
  if (!focusItems.length) return []

  const openai = getOpenAIClient()
  if (!openai) return null

  const modeGuidanceText = modeGuidance(mode)
  const prompt = `For issue "${issueName}"${issueSummary ? ` (${issueSummary})` : ''}, SECTION: ${mode}.

${modeGuidanceText}

The user has logged these items:
${JSON.stringify(focusItems, null, 2)}

CRITICAL INSTRUCTIONS:
1. Analyze each logged item by understanding its active ingredients, compounds, mechanisms, or physiological effects
2. For brand-name supplements you don't recognize, research or infer their formulation based on the product name, marketing claims, or common formulations in that category
3. For libido/erection issues: If a supplement name suggests testosterone/libido support (contains words like "testosterone", "libido", "men's health", "erection", "virility", "Miraforte", or similar), analyze it by its typical ingredient profile (zinc, chrysin, muira puama, maca, stinging nettle, lignans, etc.) and include it in "working" if those ingredients are supportive
4. Evaluate whether each item is supportive for "${issueName}" based on evidence-based mechanisms
5. Output matches by INDEX back to the provided array (0-based). Do NOT invent new items.
6. For each supportive item, return its {index, reason, dosage?, timing?}. You may also include name, but index is REQUIRED.
7. FIBER SUPPLEMENTS FOR BOWEL HEALTH: If the issue relates to bowel movements, digestion, constipation, regularity, or stool quality (check case-insensitively), treat clinically supported soluble/prebiotic fibers as supportive. This includes:
   - Partially hydrolyzed guar gum (PHGG) - includes products like "Sunfiber"
   - Psyllium husk
   - Inulin, acacia/arabic gum, methylcellulose, glucomannan, wheat dextrin, pectin
   - ANY product name containing the word "fiber" (e.g., "Sunfiber", "FiberChoice", "Benefiber")
   Explain the mechanism (hydration/gel formation, fermentation to SCFAs, stool normalization). Use the logged dose/timing when provided.
6. Return ONLY items that are plausibly supportive for this issue

Return JSON:
  {
    "supportive": Array<{
      "index": number (0-based index into the provided items),
      "name"?: string (optional, should be EXACT logged name),
      "reason": string (two sentences: mechanism + direct relevance),
      "dosage": string | null,
      "timing": string | null
    }>
  }`

  try {
    const response: any = await runChatCompletionWithLogging(openai, {
      model: DEFAULT_INSIGHTS_MODEL,
      temperature: 0.1,
      max_tokens: 600,
      response_format: { type: 'json_object' },
      messages: [
        {
          role: 'system',
          content: 'You are a cautious health tracking assistant. Review logged items by their mechanisms but ALWAYS output exact logged names. Output strict JSON only.',
        },
        { role: 'user', content: prompt },
      ],
    }, { feature: `insights:evaluate-focus:${mode}` })

    const content = response.choices?.[0]?.message?.content
    if (!content) return null

    let json: any
    try {
      json = JSON.parse(content)
    } catch {
      const stripped = content.replace(/```[a-zA-Z]*\n?|```/g, '').trim()
      const objMatch = stripped.match(/\{[\s\S]*\}/)
      if (!objMatch) return null
      json = JSON.parse(objMatch[0])
    }

    const supportive = Array.isArray(json?.supportive) ? json.supportive : []

    // Map results back to exact logged names, preserving dosage/timing from logs
    const loggedMap = new Map<string, { name: string; dosage?: string | null; timing?: string[] | null }>()
    for (const item of focusItems) {
      const key = item.name.trim().toLowerCase()
      loggedMap.set(key, item)
    }

    const out: Array<{ name: string; reason: string; dosage?: string | null; timing?: string | null }> = []
    for (const it of supportive) {
      if (!it || typeof it.reason !== 'string') continue
      let logged: { name: string; dosage?: string | null; timing?: string[] | null } | undefined
      if (typeof it.index === 'number' && it.index >= 0 && it.index < focusItems.length) {
        logged = focusItems[it.index]
      } else if (typeof it.name === 'string') {
        const key = it.name.trim().toLowerCase()
        logged = loggedMap.get(key)
      }
      if (!logged) continue
      out.push({
        name: logged.name,
        reason: it.reason,
        dosage: logged.dosage ?? (typeof it.dosage === 'string' ? it.dosage : null),
        timing: Array.isArray(logged.timing) ? (typeof it.timing === 'string' ? it.timing : (logged.timing?.[0] ?? null)) : (typeof it.timing === 'string' ? it.timing : null),
      })
    }
    return out
  } catch (error) {
    if (isAiSafetyError(error)) throw error
    console.warn('[insights.llm] evaluateFocusItemsForIssue error', error)
    return null
  }
}

export async function generateDegradedSection(
  input: LLMInputData,
  options: { minSuggested?: number; minAvoid?: number } = {}
): Promise<SectionLLMResult | null> {
  const openai = getOpenAIClient()
  if (!openai) return null
  const userId = input.userId ?? null
  const issueSlug = input.issueSlug ?? null
  const minSuggested = Math.max(4, options.minSuggested ?? 4)
  const minAvoid = Math.max(4, options.minAvoid ?? 4)
  const typeSet = allowedCanonicalTypesForMode(input.mode)
  const expected: CanonicalType | null = typeSet ? Array.from(typeSet)[0] : null
  const trace = `[insights:degraded:${input.mode}:${Math.random().toString(36).slice(2, 8)}]`
  let generateMs = 0
  let classifyMs = 0
  let fillMs = 0
  let rewriteMs = 0

  try {
    const user = `For issue "${input.issueName}", SECTION: ${input.mode}. Data may be sparse.
Generate minimally valid guidance with ONLY in-domain items. Output JSON with keys suggested and avoid only; working may be empty. Each item: name, reason (two sentences), optional protocol.
Counts: suggested≥${minSuggested}, avoid≥${minAvoid}.`
    const g0 = Date.now()
    console.time(`${trace}:generate`)
    const resp: any = await runChatCompletionWithLogging(openai, {
      model: DEFAULT_INSIGHTS_MODEL,
      temperature: 0.2,
      max_tokens: 700,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: 'Produce domain-correct, concise items. Output JSON only.' },
        { role: 'user', content: user },
      ],
    }, { feature: `insights:degraded:${input.mode}`, userId, issueSlug })
    console.timeEnd(`${trace}:generate`)
    generateMs += Date.now() - g0
    const content = resp.choices?.[0]?.message?.content
    if (!content) return null
    let json: any
    try {
      json = JSON.parse(content)
    } catch {
      const stripped = content.replace(/```[a-zA-Z]*\n?|```/g, '').trim()
      const objMatch = stripped.match(/\{[\s\S]*\}/)
      if (!objMatch) return null
      json = JSON.parse(objMatch[0])
    }
    const base: SectionLLMResult = {
      summary: 'Initial guidance generated while we prepare a deeper report.',
      working: [],
      suggested: Array.isArray(json?.suggested) ? json.suggested : [],
      avoid: Array.isArray(json?.avoid) ? json.avoid : [],
      recommendations: [],
    }
    // Classify and keep only expected domain
    const itemsForClassification: ClassificationEntry[] = [
      ...base.suggested.map((s) => ({ name: s.name, reason: s.reason })),
      ...base.avoid.map((a) => ({ name: a.name, reason: a.reason })),
    ]
    const c0 = Date.now()
    const classified = await classifyCandidatesForSection({
      issueName: input.issueName,
      mode: input.mode,
      items: itemsForClassification,
      trace,
      userId,
      issueSlug,
    })
    classifyMs += Date.now() - c0
    const typeMap = new Map<string, CanonicalType>()
    for (const it of classified ?? []) {
      typeMap.set(it.name.trim().toLowerCase(), it.canonicalType)
    }
    const keep = (name: string) => {
      const t = typeMap.get(name.trim().toLowerCase())
      return expected ? t === expected : true
    }
    let suggested = base.suggested.filter((s) => keep(s.name))
    let avoid = base.avoid.filter((a) => keep(a.name))
    // Top up if still short
    const disallow = [
      ...suggested.map((s) => s.name),
      ...avoid.map((a) => a.name),
    ]
    const needSuggested = Math.max(0, minSuggested - suggested.length)
    if (needSuggested > 0) {
      const f0 = Date.now()
      const more = await fillMissingItemsForSection({
        issueName: input.issueName,
        mode: input.mode,
        bucket: 'suggested',
        expectedType: expected,
        needed: needSuggested,
        disallowNames: disallow,
        trace,
        userId,
        issueSlug,
      })
      fillMs += Date.now() - f0
      suggested = uniqueByName([...suggested, ...(more ?? [])])
    }
    const needAvoid = Math.max(0, minAvoid - avoid.length)
    if (needAvoid > 0) {
      const f1 = Date.now()
      const more = await fillMissingItemsForSection({
        issueName: input.issueName,
        mode: input.mode,
        bucket: 'avoid',
        expectedType: expected,
        needed: needAvoid,
        disallowNames: [
          ...suggested.map((s) => s.name),
          ...avoid.map((a) => a.name),
        ],
        trace,
        userId,
        issueSlug,
      })
      fillMs += Date.now() - f1
      avoid = uniqueByName([...avoid, ...(more ?? [])])
    }
    const out: SectionLLMResult = {
      summary: base.summary,
      working: [],
      suggested,
      avoid,
      recommendations: [],
    }
    ;(out as any)._timings = {
      generateMs,
      classifyMs,
      rewriteMs,
      fillMs,
      totalMs: generateMs + classifyMs + rewriteMs + fillMs,
    }
    return out
  } catch (error) {
    if (isAiSafetyError(error)) throw error
    console.warn('[insights.llm] generateDegradedSection error', error)
    return null
  }
}

// Quick degraded generator: single-pass candidate generation filtered to the expected domain.
// Designed for fast first-paint. Uses only one LLM call and avoids repair/classify loops.
export async function generateDegradedSectionQuick(
  input: LLMInputData,
  options: { minSuggested?: number; minAvoid?: number } = {}
): Promise<SectionLLMResult | null> {
  const minSuggested = Math.max(4, options.minSuggested ?? 4)
  const minAvoid = Math.max(4, options.minAvoid ?? 4)

  try {
    const expectedSet = allowedCanonicalTypesForMode(input.mode)
    const expected: CanonicalType | null = expectedSet ? Array.from(expectedSet)[0] : null
    const candidates = await generateSectionCandidates({
      issueName: input.issueName,
      issueSummary: input.issueSummary,
      profile: input.profile,
      mode: input.mode,
      count: { suggested: Math.max(6, minSuggested), avoid: Math.max(6, minAvoid) },
      userId: input.userId ?? null,
      issueSlug: input.issueSlug ?? null,
    })
    if (!candidates) return null

    const keep = (ct: CanonicalType) => (expected ? ct === expected : true)
    const suggested = candidates
      .filter((c) => c.bucket === 'suggested' && keep(c.candidateType))
      .slice(0, Math.max(minSuggested, 6))
      .map((c) => ({ name: c.name, reason: c.reason, protocol: c.protocol ?? null }))
    const avoid = candidates
      .filter((c) => c.bucket === 'avoid' && keep(c.candidateType))
      .slice(0, Math.max(minAvoid, 6))
      .map((c) => ({ name: c.name, reason: c.reason }))

    // Ensure minimum counts by truncation fallback (should already meet due to counts above)
    const finalSuggested = suggested.slice(0, Math.max(minSuggested, 4))
    const finalAvoid = avoid.slice(0, Math.max(minAvoid, 4))

    // For exercise mode, check intake exerciseTypes and add supportive ones to working
    let working: Array<{ name: string; reason: string; dosage?: string | null; timing?: string | null }> = []
    if (input.mode === 'exercise' && input.profile?.exerciseTypes?.length) {
      // For quick path, we'll add intake exercises that are likely supportive
      // The full path will do a proper LLM evaluation
      const intakeTypes = input.profile.exerciseTypes
      console.log('[exercise.quick] Checking intake exerciseTypes for working:', intakeTypes)

      // Add intake exercises to working with a generic supportive reason
      // The full path will refine these with proper LLM evaluation
      for (const exerciseType of intakeTypes) {
        working.push({
          name: exerciseType,
          reason: `${exerciseType} can support ${input.issueName} through improved cardiovascular health, stress reduction, and overall physical wellbeing. Regular ${exerciseType.toLowerCase()} helps maintain optimal body function and may contribute positively to this health goal.`,
          dosage: null,
          timing: null,
        })
      }
      console.log('[exercise.quick] Added intake exercises to working:', working.map(w => w.name))
    }

    return {
      summary: 'Initial guidance generated while we prepare a deeper report.',
      working,
      suggested: finalSuggested,
      avoid: finalAvoid,
      recommendations: [],
    }
  } catch (error) {
    if (isAiSafetyError(error)) throw error
    console.warn('[insights.llm] generateDegradedSectionQuick error', error)
    return null
  }
}

