export async function generateSectionInsightsFromLLM(
  input: LLMInputData,
  options: LLMOptions = {}
): Promise<SectionLLMResult | null> {
  const openai = getOpenAIClient()
  if (!openai) {
    return null
  }

  const userId = input.userId ?? null
  const issueSlug = input.issueSlug ?? null
  const focusItems = (input.items ?? []).slice(0, input.mode === 'nutrition' ? 200 : 8)
  const otherItems = (input.otherItems ?? []).slice(0, input.mode === 'nutrition' ? 8 : 6)
  const minWorking = options.minWorking ?? (focusItems.length > 0 ? 1 : 0)
  const minSuggested = options.minSuggested ?? 4
  const minAvoid = options.minAvoid ?? 4
  const isTargetedRun = getRunContext()?.feature === 'insights:targeted'
  const nutritionQualityMode = isTargetedRun && input.mode === 'nutrition'
  const costSaver = isTargetedRun && input.mode !== 'nutrition'
  const maxRetries = nutritionQualityMode ? Math.max(options.maxRetries ?? 2, 2) : costSaver ? 1 : options.maxRetries ?? 3
  const maxTokens = nutritionQualityMode ? 420 : costSaver ? 220 : 650
  const disableCache = options.disableCache ?? false
  const runId = getRunContext()?.runId ?? null

  const userContext = JSON.stringify(
    {
      focusItems,
      otherItems,
      profile: input.profile ?? {},
    },
    null,
    2
  )
  const dhtSensitive = hasDhtSensitivity(input.profile)

  // Debug logging for exercise mode
  if (input.mode === 'exercise') {
    console.log('[exercise.llm] Input profile:', JSON.stringify(input.profile, null, 2))
    console.log('[exercise.llm] exerciseTypes in profile:', input.profile?.exerciseTypes)
    console.log('[exercise.llm] focusItems (normalized logs):', focusItems)
  }

  const cacheKey = JSON.stringify({
    issueName: input.issueName,
    issueSummary: input.issueSummary ?? '',
    mode: input.mode,
    userContext,
    minWorking,
    minSuggested,
    minAvoid,
  })

  const cached = disableCache ? null : insightCache.get(cacheKey)
  const nowTs = Date.now()
  if (!disableCache && cached && cached.expiresAt > nowTs) {
    logLlmEvent('cache-hit', {
      userId,
      issueSlug,
      mode: input.mode,
      cacheExpiresAt: new Date(cached.expiresAt).toISOString(),
    })
    return cached.result
  }
  logLlmEvent('cache-miss', { userId, issueSlug, mode: input.mode })

  let generateMs = 0
  let classifyMs = 0
  let rewriteMs = 0
  let fillMs = 0
  let generateAttempts = 0
  let bestCandidate: { result: SectionLLMResult; score: number; metMinimums: boolean } | null = null
  for (let attempt = 0; attempt < maxRetries; attempt += 1) {
    const force = attempt > 0
    const prompt = buildPrompt({
      issueName: input.issueName,
      issueSummary: input.issueSummary,
      userContext,
      mode: input.mode,
      minWorking,
      minSuggested,
      minAvoid,
      force,
      dhtSensitive,
    })

    try {
      const g0 = Date.now()
      console.time(`[insights.gen:${input.mode}]`)
      const response: any = await runChatCompletionWithLogging(openai, {
        model: DEFAULT_INSIGHTS_MODEL,
        temperature: 0.05,
        max_tokens: maxTokens,
        response_format: { type: 'json_object' },
        messages: [
          {
            role: 'system',
            content:
              'You are a careful health tracking assistant. Follow instructions precisely, remain evidence-aligned, and never fabricate data.',
          },
          { role: 'user', content: prompt },
        ],
      }, { feature: `insights:generate:${input.mode}`, userId, issueSlug, runId })
      console.timeEnd(`[insights.gen:${input.mode}]`)
      const elapsed = Date.now() - g0
      generateMs += elapsed
      generateAttempts = attempt + 1

      const content = response.choices?.[0]?.message?.content
      if (!content) {
        continue
      }

      let json: unknown
      try {
        json = JSON.parse(content)
      } catch (parseError) {
        // Attempt a salvage parse: strip code fences and extract the first JSON object
        const stripped = content.replace(/```[a-zA-Z]*\n?|```/g, '').trim()
        const objMatch = stripped.match(/\{[\s\S]*\}/)
        if (objMatch) {
          try {
            json = JSON.parse(objMatch[0])
          } catch (e) {
            console.warn('[insights.llm] Salvage parse failed', { content })
            throw parseError
          }
        } else {
          console.warn('[insights.llm] Failed to parse JSON content', { content })
          throw parseError
        }
      }

      const parsed = llmSectionSchema.safeParse(json)
      if (!parsed.success) {
        console.warn('[insights.llm] Invalid LLM JSON', {
          issues: parsed.error.issues,
          content,
        })
        continue
      }

      const data = parsed.data
      const meets = meetsMinimums(data, { minWorking, minSuggested, minAvoid })
      const score = scoreCandidate(data)
      if (!bestCandidate || score > bestCandidate.score) {
        bestCandidate = { result: data, score, metMinimums: meets }
      }
      if (meets || costSaver) {
        break
      }

      // If minWorking is set due to intake exercises (not logs), be more lenient
      // Accept best candidate if we have at least some working items, even if not meeting strict minimums
      if (minWorking === 1 && focusItems.length === 0 && data.working.length > 0) {
        console.log('[insights.llm] Accepting result with working items despite not meeting strict minimums')
        break
      }
    } catch (error) {
      if (isAiSafetyError(error)) throw error
      console.error('[insights.llm] Failed to fetch LLM output', error)
    }
  }

  // Stage 2: classification + fill-missing over the best candidate (with one repair attempt if needed)
  const trace = `[insights:${input.mode}:${Math.random().toString(36).slice(2, 8)}]`
  let base: SectionLLMResult | null = bestCandidate?.result ?? null
  if (base && !bestCandidate?.metMinimums && !costSaver) {
    const r0 = Date.now()
    const repaired = await repairLLMOutput({
      mode: input.mode,
      issueName: input.issueName,
      issueSummary: input.issueSummary,
      minWorking,
      minSuggested,
      minAvoid,
      focusItems,
      otherItems,
      profile: input.profile,
      previous: base,
    })
    generateMs += Date.now() - r0
    if (repaired) base = repaired
  }

  if (!base) return null

  const allowed = allowedCanonicalTypesForMode(input.mode)
  let working = base.working.slice()
  let suggested = base.suggested.slice()
  let avoid = base.avoid.slice()

  console.log('[insights.llm] pre-classify counts', {
    mode: input.mode,
    working: working.length,
    suggested: suggested.length,
    avoid: avoid.length,
  })

  if (allowed) {
    const itemsForClassification: ClassificationEntry[] = [
      ...working.map((w) => ({ name: w.name, reason: w.reason })),
      ...suggested.map((s) => ({ name: s.name, reason: s.reason })),
      ...avoid.map((a) => ({ name: a.name, reason: a.reason })),
    ]
    const c0 = Date.now()
    const classified = await classifyCandidatesForSection({
      issueName: input.issueName,
      mode: input.mode,
      items: itemsForClassification,
      trace,
      runId,
      userId,
      issueSlug,
    })
    classifyMs += Date.now() - c0
    const typeMap = new Map<string, CanonicalType>()
    for (const it of classified ?? []) {
      typeMap.set(it.name.trim().toLowerCase(), it.canonicalType)
    }

    const keep = (name: string) => {
      const key = name.trim().toLowerCase()
      const t = typeMap.get(key)
      if (!t) return false
      return allowed.has(t)
    }

    const droppedWorking = working.filter((w) => !keep(w.name))
    const droppedSuggested = suggested.filter((s) => !keep(s.name))
    const droppedAvoid = avoid.filter((a) => !keep(a.name))
    working = working.filter((w) => keep(w.name))
    suggested = suggested.filter((s) => keep(s.name))
    avoid = avoid.filter((a) => keep(a.name))

    console.log('[insights.llm] post-classify counts', {
      mode: input.mode,
      working: working.length,
      suggested: suggested.length,
      avoid: avoid.length,
    })

    // Rewrite out-of-domain candidates into the correct domain, then re-classify
    if (droppedSuggested.length && !costSaver) {
      const rw0 = Date.now()
      const rewritten = await rewriteCandidatesToDomain({
        issueName: input.issueName,
        mode: input.mode,
        bucket: 'suggested',
        expectedType: Array.from(allowed)[0] ?? null,
        items: droppedSuggested.map((it) => ({ name: it.name, reason: it.reason })),
        attempts: 2,
        trace,
        userId,
        issueSlug,
        runId,
      })
      rewriteMs += Date.now() - rw0
      if (rewritten?.length) {
        const cc0 = Date.now()
        const reClassified = await classifyCandidatesForSection({
          issueName: input.issueName,
          mode: input.mode,
          items: rewritten.map((m) => ({ name: m.name, reason: m.reason })),
          trace,
          runId,
          userId,
          issueSlug,
        })
      classifyMs += Date.now() - cc0
        const filtered = (reClassified ?? [])
          .filter((it) => allowed.has(it.canonicalType))
          .map((it) => {
            const src = rewritten.find((m) => m.name.trim().toLowerCase() === it.name.trim().toLowerCase())!
            return { name: src.name, reason: src.reason, protocol: null as string | null }
          })
        suggested = uniqueByName([...suggested, ...filtered])
      }
    }
    if (droppedAvoid.length && !costSaver) {
      const rw1 = Date.now()
      const rewritten = await rewriteCandidatesToDomain({
        issueName: input.issueName,
        mode: input.mode,
        bucket: 'avoid',
        expectedType: Array.from(allowed)[0] ?? null,
        items: droppedAvoid.map((it) => ({ name: it.name, reason: it.reason })),
        attempts: 2,
        trace,
        userId,
        issueSlug,
        runId,
      })
      rewriteMs += Date.now() - rw1
      if (rewritten?.length) {
        const cc1 = Date.now()
        const reClassified = await classifyCandidatesForSection({
          issueName: input.issueName,
          mode: input.mode,
          items: rewritten.map((m) => ({ name: m.name, reason: m.reason })),
          trace,
          runId,
          userId,
          issueSlug,
        })
        classifyMs += Date.now() - cc1
        const filtered = (reClassified ?? [])
          .filter((it) => allowed.has(it.canonicalType))
          .map((it) => {
            const src = rewritten.find((m) => m.name.trim().toLowerCase() === it.name.trim().toLowerCase())!
            return { name: src.name, reason: src.reason, protocol: null as string | null }
          })
        avoid = uniqueByName([...avoid, ...filtered])
      }
    }

    // Fill-missing up to 3 retries per bucket
    for (const bucket of ['suggested', 'avoid'] as const) {
      let attempts = 0
      // eslint-disable-next-line no-constant-condition
      while (true) {
        const need = bucket === 'suggested' ? Math.max(0, minSuggested - suggested.length) : Math.max(0, minAvoid - avoid.length)
        if (need <= 0 || attempts >= (costSaver ? 1 : 3)) break
        const disallow = [
          ...suggested.map((s) => s.name),
          ...avoid.map((a) => a.name),
          ...working.map((w) => w.name),
        ]
        const expected: CanonicalType | null = Array.from(allowed)[0] ?? null
        const f0 = Date.now()
        const more = await fillMissingItemsForSection({
          issueName: input.issueName,
          mode: input.mode,
          bucket,
          expectedType: expected,
          needed: need,
          disallowNames: disallow,
          trace,
          userId,
          issueSlug,
          runId,
        })
        fillMs += Date.now() - f0
        attempts += 1
        if (!more || !more.length) break
        // classify the new items
        const c1 = Date.now()
        const moreClassified = await classifyCandidatesForSection({
          issueName: input.issueName,
          mode: input.mode,
          items: more.map((m) => ({ name: m.name, reason: m.reason })),
          trace,
          runId,
          userId,
          issueSlug,
        })
        classifyMs += Date.now() - c1
        const filtered = (moreClassified ?? [])
          .filter((it) => allowed.has(it.canonicalType))
          .map((it) => {
            const src = more.find((m) => m.name.trim().toLowerCase() === it.name.trim().toLowerCase())!
            return { name: src.name, reason: src.reason, protocol: src.protocol ?? null }
          })
        if (bucket === 'suggested') {
          suggested = uniqueByName([...suggested, ...filtered])
        } else {
          avoid = uniqueByName([...avoid, ...filtered])
        }
        console.log('[insights.llm] fill-missing iteration', {
          mode: input.mode,
          bucket,
          added: filtered.length,
          suggested: suggested.length,
          avoid: avoid.length,
        })
      }
    }
  }

  const validated = suggested.length >= minSuggested && avoid.length >= minAvoid
  const final: SectionLLMResult = {
    summary: base.summary,
    working,
    suggested,
    avoid,
    recommendations: base.recommendations ?? [],
  }

  console.log('[insights.llm] final counts', {
    mode: input.mode,
    validated,
    working: final.working.length,
    suggested: final.suggested.length,
    avoid: final.avoid.length,
  })

  if (validated && !disableCache) {
    insightCache.set(cacheKey, {
      expiresAt: Date.now() + CACHE_TTL_MS,
      result: final,
    })
  }
  // Attach timings for observability
  ;(final as any)._timings = {
    generateMs,
    classifyMs,
    rewriteMs,
    fillMs,
    totalMs: generateMs + classifyMs + rewriteMs + fillMs,
    attempts: {
      generate: generateAttempts,
    },
  }
  return final
}

/**
 * Insights Regeneration Service
 * 
 * This service provides automatic background regeneration of insights when health data changes.
 * Unlike previous attempts that generated insights on-demand (causing 20-60s waits), this system:
 * 
 * 1. Tracks what data each insight was based on (data fingerprints)
 * 2. Detects when relevant health data actually changes
 * 3. Automatically regenerates affected sections in the background
 * 4. Allows instant display of cached insights while updates happen
 * 
 * Key Difference from Previous Agents:
 * - Previous: Generate on click → user waits 20-60s
 * - This: Generate on data change → user sees instant cached result (<2s)
 */

import { prisma } from '@/lib/prisma'
import { precomputeIssueSectionsForUser, precomputeQuickSectionsForUser } from './issue-engine'
import { withRunContext, type RunContext } from '../run-context'
import type { IssueSectionKey } from './issue-engine'

export interface InsightMetadata {
  userId: string
  issueSlug: string
  section: IssueSectionKey
  lastGeneratedAt: Date
  dataFingerprint: string // Hash of source data used for generation
  status: 'fresh' | 'stale' | 'generating'
}

export interface DataChangeEvent {
  userId: string
  changeType:
    | 'supplements'
    | 'medications'
    | 'food'
    | 'exercise'
    | 'health_goals'
    | 'health_situations'
    | 'profile'
    | 'blood_results'
  timestamp: Date
}

export class ManualRegenerationTimeoutError extends Error {
  timeoutMs: number

  constructor(timeoutMs: number) {
    super(`Manual regeneration timed out after ${timeoutMs}ms`)
    this.name = 'ManualRegenerationTimeoutError'
    this.timeoutMs = timeoutMs
  }
}

async function withTimeout<T>(promise: Promise<T>, timeoutMs?: number): Promise<T> {
  if (!timeoutMs || timeoutMs <= 0) return promise

  let timer: ReturnType<typeof setTimeout> | null = null
  try {
    return await Promise.race([
      promise,
      new Promise<T>((_, reject) => {
        timer = setTimeout(() => reject(new ManualRegenerationTimeoutError(timeoutMs)), timeoutMs)
      }),
    ])
  } finally {
    if (timer) clearTimeout(timer)
  }
}

/**
 * Creates a fingerprint (hash) of the data to detect real changes
 */
function createDataFingerprint(data: any): string {
  const json = JSON.stringify(data)
  // Simple hash function (for production, consider using crypto.subtle or a library)
  let hash = 0
  for (let i = 0; i < json.length; i++) {
    const char = json.charCodeAt(i)
    hash = (hash << 5) - hash + char
    hash = hash & hash // Convert to 32bit integer
  }
  return hash.toString(36)
}

/**
 * Map change types to affected insight sections
 */
export function getAffectedSections(changeType: DataChangeEvent['changeType']): IssueSectionKey[] {
  const mapping: Record<DataChangeEvent['changeType'], IssueSectionKey[]> = {
    // Narrowed to just the sections a user expects to change, to keep runtime fast and scoped.
    supplements: ['supplements'], // only when supplements change
    medications: ['medications'], // interactions disabled per user request
    food: ['nutrition'], // nutrition only runs via food diary changes
    exercise: [], // exercise insights removed
    // Goals/situations no longer fan out to lifestyle (section removed)
    health_goals: [],
    health_situations: [],
    // Profile changes should not fan out across goals; no sections triggered
    profile: [],
    // Labs stay isolated and only run when labs are uploaded/changed
    blood_results: ['labs'],
  }
  return mapping[changeType] || []
}

