/**
 * Get current data fingerprint for a user
 */
async function getCurrentDataFingerprint(userId: string): Promise<string> {
  try {
    const user = await prisma.user.findUnique({
      where: { id: userId },
      include: {
        healthGoals: { select: { name: true, currentRating: true } },
        supplements: { select: { name: true, dosage: true, timing: true } },
        medications: { select: { name: true, dosage: true, timing: true } },
        foodLogs: {
          where: {
            createdAt: {
              gte: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000), // Last 7 days
            },
          },
          select: { name: true, nutrients: true },
        },
        exerciseLogs: {
          where: {
            createdAt: {
              gte: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000),
            },
          },
          select: { type: true, duration: true },
        },
      },
    })

    if (!user) return ''

    const relevantData = {
      profile: {
        gender: user.gender,
        weight: user.weight,
        height: user.height,
        bodyType: user.bodyType,
        exerciseFrequency: user.exerciseFrequency,
      },
      goals: user.healthGoals.map((g) => ({ name: g.name, rating: g.currentRating })),
      supplements: user.supplements.map((s) => ({ name: s.name, dosage: s.dosage, timing: s.timing })),
      medications: user.medications.map((m) => ({ name: m.name, dosage: m.dosage, timing: m.timing })),
      recentFoods: user.foodLogs.length,
      recentExercise: user.exerciseLogs.length,
    }

    return createDataFingerprint(relevantData)
  } catch (error) {
    console.warn('[regeneration-service] Error creating fingerprint', error)
    return ''
  }
}

/**
 * Check if insights are stale (need regeneration)
 */
export async function checkInsightsStatus(
  userId: string,
  issueSlug: string,
  section: IssueSectionKey
): Promise<{ status: 'fresh' | 'stale' | 'missing' | 'generating'; lastGenerated: Date | null; needsUpdate: boolean }> {
  try {
    await ensureMetadataTable()

    const rows: any[] = await prisma.$queryRawUnsafe(
      'SELECT "lastGeneratedAt", "dataFingerprint", "status" FROM "InsightsMetadata" WHERE "userId" = $1 AND "issueSlug" = $2 AND "section" = $3',
      userId,
      issueSlug,
      section
    )

    if (!rows || !rows[0]) {
      return { status: 'missing', lastGenerated: null, needsUpdate: true }
    }

    const metadata = rows[0]
    const currentFingerprint = await getCurrentDataFingerprint(userId)

    // If fingerprints don't match, data has changed
    const needsUpdate = metadata.dataFingerprint !== currentFingerprint

    return {
      status: needsUpdate ? 'stale' : (metadata.status as 'fresh' | 'stale' | 'generating'),
      lastGenerated: metadata.lastGeneratedAt ? new Date(metadata.lastGeneratedAt) : null,
      needsUpdate,
    }
  } catch (error) {
    console.warn('[regeneration-service] Error checking status', error)
    return { status: 'missing', lastGenerated: null, needsUpdate: true }
  }
}

/**
 * Mark sections as stale when data changes
 */
async function markSectionsStale(userId: string, sections: IssueSectionKey[]): Promise<void> {
  try {
    await ensureMetadataTable()

    // Get all issues for this user
    const user = await prisma.user.findUnique({
      where: { id: userId },
      include: { healthGoals: { orderBy: { updatedAt: 'desc' } } },
    })

    if (!user) return

    // Extract issue slugs from health goals (simplified - in real system would be more robust)
    let issueNames = user.healthGoals
      .filter((g) => !g.name.startsWith('__'))
      .map((g) => g.name.toLowerCase().replace(/[^a-z0-9]+/g, '-'))

    // Fallback: if no healthGoals on the user record, try CheckinIssues (selected issues)
    if (!issueNames.length) {
      try {
        const rows: Array<{ name: string }> = await prisma.$queryRawUnsafe(
          'SELECT name FROM "CheckinIssues" WHERE "userId" = $1',
          userId
        )
        issueNames = rows
          .map((r) => r.name || '')
          .filter((name) => name && !name.startsWith('__'))
          .map((name) => name.toLowerCase().replace(/[^a-z0-9]+/g, '-'))
      } catch (e) {
        console.warn('[manual-regeneration] fallback issues lookup failed', { userId, error: e })
      }
    }

    // If still no issues, bail early to avoid a no-op regen that never charges
    if (!issueNames.length) {
      console.warn('[manual-regeneration] no issues/goals to regenerate for user', { userId })
      return
    }

    // Mark each section for each issue as stale
    for (const issueSlug of issueNames) {
      for (const section of sections) {
        await prisma.$queryRawUnsafe(
          `INSERT INTO "InsightsMetadata" ("userId", "issueSlug", "section", "status", "dataFingerprint", "updatedAt") 
           VALUES ($1, $2, $3, 'stale', '', NOW())
           ON CONFLICT ("userId", "issueSlug", "section") 
           DO UPDATE SET "status" = 'stale', "updatedAt" = NOW()`,
          userId,
          issueSlug,
          section
        )
      }
    }

    console.log(`[regeneration-service] Marked ${sections.length} sections as stale for user ${userId}`)
  } catch (error) {
    console.warn('[regeneration-service] Error marking sections stale', error)
  }
}

/**
 * Update metadata after successful generation
 */
async function updateMetadataAfterGeneration(
  userId: string,
  issueSlug: string,
  section: IssueSectionKey
): Promise<void> {
  try {
    await ensureMetadataTable()
    const fingerprint = await getCurrentDataFingerprint(userId)

    await prisma.$queryRawUnsafe(
      `INSERT INTO "InsightsMetadata" ("userId", "issueSlug", "section", "lastGeneratedAt", "dataFingerprint", "status", "updatedAt")
       VALUES ($1, $2, $3, NOW(), $4, 'fresh', NOW())
       ON CONFLICT ("userId", "issueSlug", "section")
       DO UPDATE SET "lastGeneratedAt" = NOW(), "dataFingerprint" = $4, "status" = 'fresh', "updatedAt" = NOW()`,
      userId,
      issueSlug,
      section,
      fingerprint
    )
  } catch (error) {
    console.warn('[regeneration-service] Error updating metadata', error)
  }
}

/**
 * Trigger background regeneration for affected sections.
 * Temporarily paused unless explicitly enabled to stop runaway background calls.
 */
const BACKGROUND_REGEN_ENABLED = process.env.ENABLE_INSIGHTS_BACKGROUND_REGEN === 'true'

export async function triggerBackgroundRegeneration(event: DataChangeEvent): Promise<void> {
  if (!BACKGROUND_REGEN_ENABLED) {
    console.log('[regeneration-service] Background regeneration is disabled; skipping trigger.', event)
    return
  }

  const { userId, changeType } = event

  try {
    console.log(`[regeneration-service] Data change detected: ${changeType} for user ${userId}`)

    // 1. Determine which sections are affected by this change
    const affectedSections = getAffectedSections(changeType)

    if (affectedSections.length === 0) {
      console.log('[regeneration-service] No affected sections for this change type')
      return
    }

    // 2. Mark affected sections as stale
    await markSectionsStale(userId, affectedSections)

    // 3. Kick off background regeneration (non-blocking!)
    // This runs asynchronously - the user doesn't wait for it
    setImmediate(async () => {
      try {
        console.log(`[regeneration-service] Starting background regeneration for sections: ${affectedSections.join(', ')}`)

        // Mark as generating
        await ensureMetadataTable()
        const user = await prisma.user.findUnique({
          where: { id: userId },
          include: { healthGoals: { orderBy: { updatedAt: 'desc' } } },
        })

        if (!user) return

        const issueNames = user.healthGoals
          .filter((g) => !g.name.startsWith('__'))
          .map((g) => g.name.toLowerCase().replace(/[^a-z0-9]+/g, '-'))

        for (const issueSlug of issueNames) {
          for (const section of affectedSections) {
            await prisma.$queryRawUnsafe(
              `UPDATE "InsightsMetadata" SET "status" = 'generating', "updatedAt" = NOW() 
               WHERE "userId" = $1 AND "issueSlug" = $2 AND "section" = $3`,
              userId,
              issueSlug,
              section
            )
          }
        }

        // Run precomputation with concurrency control
        await precomputeIssueSectionsForUser(userId, { concurrency: 4, sectionsFilter: affectedSections })

        // Update metadata to mark as fresh
        for (const issueSlug of issueNames) {
          for (const section of affectedSections) {
            await updateMetadataAfterGeneration(userId, issueSlug, section)
          }
        }

        console.log(`[regeneration-service] Background regeneration complete for user ${userId}`)
      } catch (error) {
        console.error('[regeneration-service] Background regeneration failed', error)

        // Mark as stale again so it can retry later
        await markSectionsStale(userId, affectedSections)
      }
    })

    console.log('[regeneration-service] Background regeneration triggered (non-blocking)')
  } catch (error) {
    console.error('[regeneration-service] Error triggering regeneration', error)
  }
}

/**
 * Manually trigger regeneration for selected change types, even when background
 * regeneration is disabled. This is used for explicit "Update Insights" clicks
 * so we only regenerate the affected sections.
 */
export async function triggerManualSectionRegeneration(
  userId: string,
  changeTypes: DataChangeEvent['changeType'][],
  options: {
    inline?: boolean
    runContext?: RunContext | null
    preferQuick?: boolean
    slugs?: string[]
    timeoutMs?: number
  } = {}
): Promise<IssueSectionKey[]> {
  const requestedTypes = Array.isArray(changeTypes) ? changeTypes : []
  const changeTypesForLog = requestedTypes
  const affectedSections = Array.from(
    new Set(
      requestedTypes.flatMap((type) => getAffectedSections(type)).filter(Boolean)
    )
  )

  if (!userId || affectedSections.length === 0) {
    return []
  }

  const runTask = async () => {
    await markSectionsStale(userId, affectedSections)
    try {
      await ensureMetadataTable()
      const user = await prisma.user.findUnique({
        where: { id: userId },
        include: { healthGoals: { orderBy: { updatedAt: 'desc' } } },
      })

      if (!user) return

      let issueNames = user.healthGoals
        .filter((g) => !g.name.startsWith('__'))
        .map((g) => g.name.toLowerCase().replace(/[^a-z0-9]+/g, '-'))

      // Fallback: some users keep active issue choices in CheckinIssues.
      if (!issueNames.length) {
        try {
          const rows: Array<{ name: string }> = await prisma.$queryRawUnsafe(
            'SELECT name FROM "CheckinIssues" WHERE "userId" = $1',
            userId
          )
          issueNames = rows
            .map((r) => r.name || '')
            .filter((name) => name && !name.startsWith('__'))
            .map((name) => name.toLowerCase().replace(/[^a-z0-9]+/g, '-'))
        } catch (e) {
          console.warn('[manual-regeneration] fallback issues lookup failed', { userId, error: e })
        }
      }

      console.log('[manual-regeneration] start', {
        userId,
        changeTypes: requestedTypes,
        affectedSections,
        issues: issueNames,
        inline: options.inline === true,
        preferQuick: options.preferQuick === true,
        timeoutMs: options.timeoutMs,
        runContext: options.runContext,
      })

      const providedSlugs =
        Array.isArray(options.slugs) && options.slugs.length
          ? Array.from(new Set(options.slugs.map((s) => String(s || '').trim()).filter(Boolean)))
          : []
      const targetSlugs = providedSlugs.length ? providedSlugs : issueNames.length ? issueNames : ['general-health']

      const buildContextForPhase = (phase: 'quick' | 'full'): RunContext | null => {
        if (!options.runContext) return null
        return {
          ...options.runContext,
          meta: {
            ...(options.runContext.meta || {}),
            userId,
            changeTypes: requestedTypes,
            sections: affectedSections,
            phase,
          },
        }
      }

      const runWithScopedContext = async (phase: 'quick' | 'full', runner: () => Promise<void>) => {
        const ctx = buildContextForPhase(phase)
        const runPromise = Promise.resolve(ctx ? withRunContext(ctx, runner) : runner())
        await withTimeout(runPromise, options.timeoutMs)
      }

      // Mark as generating (best-effort; fallback slug may not exist in DB)
      for (const issueSlug of targetSlugs) {
        for (const section of affectedSections) {
          await prisma.$queryRawUnsafe(
            `UPDATE "InsightsMetadata" SET "status" = 'generating', "updatedAt" = NOW() 
             WHERE "userId" = $1 AND "issueSlug" = $2 AND "section" = $3`,
            userId,
            issueSlug,
            section
          )
        }
      }

      // IMPORTANT: When a runContext is provided (manual/targeted regen),
      // avoid double LLM passes. Skip the quick pass and run the full pass once.
      const shouldSkipQuick = Boolean(options.runContext)
      if (options.preferQuick && !shouldSkipQuick) {
        console.log('[manual-regeneration] quick precompute start', {
          userId,
          changeTypes: requestedTypes,
          sections: affectedSections,
          issues: targetSlugs,
        })
        await runWithScopedContext('quick', () =>
          precomputeQuickSectionsForUser(userId, {
            concurrency: 4,
            sectionsFilter: affectedSections,
            slugs: targetSlugs,
          })
        )
        console.log('[manual-regeneration] quick precompute complete', {
          userId,
          changeTypes: requestedTypes,
          sections: affectedSections,
          issues: targetSlugs,
        })
      } else if (options.preferQuick && shouldSkipQuick) {
        console.log('[manual-regeneration] quick precompute skipped (runContext present to avoid double charges)', {
          userId,
          changeTypes: requestedTypes,
          sections: affectedSections,
          issues: targetSlugs,
        })
      }

      console.log('[manual-regeneration] full precompute start', {
        userId,
        changeTypes: requestedTypes,
        sections: affectedSections,
        issues: targetSlugs,
      })
      await runWithScopedContext('full', () =>
        precomputeIssueSectionsForUser(userId, {
          concurrency: 4,
          sectionsFilter: affectedSections,
          slugs: targetSlugs,
        })
      )
      console.log('[manual-regeneration] full precompute complete', {
        userId,
        changeTypes: requestedTypes,
        sections: affectedSections,
        issues: targetSlugs,
      })

      for (const issueSlug of targetSlugs) {
        for (const section of affectedSections) {
          await updateMetadataAfterGeneration(userId, issueSlug, section)
        }
      }
      console.log('[manual-regeneration] complete', {
        userId,
        changeTypes: requestedTypes,
        affectedSections,
        issues: issueNames,
        inline: options.inline === true,
        preferQuick: options.preferQuick === true,
        timeoutMs: options.timeoutMs,
        runContext: options.runContext,
      })
    } catch (error) {
      console.error('[manual-regeneration] Failed to regenerate sections', {
        userId,
        changeTypes: requestedTypes,
        affectedSections,
        inline: options.inline === true,
        preferQuick: options.preferQuick === true,
        timeoutMs: options.timeoutMs,
        runContext: options.runContext,
        error,
      })
      try {
        await markSectionsStale(userId, affectedSections)
      } catch {}
      throw error
    }
  }

  try {
    if (options.inline) {
      if (options.runContext) {
        await withRunContext(options.runContext, runTask)
      } else {
        await runTask()
      }
    } else {
      // When inline is false, return a promise that resolves when the background run finishes
      return await new Promise<IssueSectionKey[]>((resolve, reject) => {
        setImmediate(() => {
          const runner = async () => {
            try {
              if (options.runContext) {
                await withRunContext(options.runContext, runTask)
              } else {
                await runTask()
              }
              resolve(affectedSections)
            } catch (error) {
              reject(error)
            }
          }
          runner().catch((error) => {
            console.error('[manual-regeneration] Background regeneration failed', error)
            reject(error)
          })
        })
      })
    }
  } catch (error) {
    console.error('[manual-regeneration] Failed to start regeneration', error)
  }

  return affectedSections
}

/**
 * Get user-friendly status message based on insight status
 */
export function getStatusMessage(status: 'fresh' | 'stale' | 'missing' | 'generating', lastGenerated: Date | null): {
  message: string
  tone: 'positive' | 'neutral' | 'info'
} {
  switch (status) {
    case 'fresh':
      if (lastGenerated) {
        const hoursAgo = Math.floor((Date.now() - lastGenerated.getTime()) / (1000 * 60 * 60))
        if (hoursAgo < 1) {
          return { message: 'Fresh insights based on your latest data', tone: 'positive' }
        } else if (hoursAgo < 24) {
          return { message: `No changes detected since ${hoursAgo}h ago`, tone: 'neutral' }
        } else {
          const daysAgo = Math.floor(hoursAgo / 24)
          return { message: `No changes detected since ${daysAgo}d ago`, tone: 'neutral' }
        }
      }
      return { message: 'Current insights ready', tone: 'positive' }

    case 'generating':
      return { message: 'Updating based on your recent changes...', tone: 'info' }

    case 'stale':
      return { message: 'Updating insights based on your recent changes...', tone: 'info' }

    case 'missing':
      return { message: 'Generating your personalized insights...', tone: 'info' }

    default:
      return { message: 'Insights available', tone: 'neutral' }
  }
}

import { prisma } from '@/lib/prisma'
import { hashPayload } from '@/lib/write-guard'
import type { DataChangeEvent } from '@/lib/insights/regeneration-service'

type ChangeType = DataChangeEvent['changeType']

type CheckTargetedRefreshStateInput = {
  userId: string
  changeTypes: ChangeType[]
  affectedSections: string[]
  targetIssueSlugs: string[]
  mode?: string
  range?: { from?: string; to?: string }
  pipelineVersion?: string | null
  intent?: string
}

type CheckTargetedRefreshStateResult = {
  guardReady: boolean
  shouldSkip: boolean
  payloadHash: string
  scope: string
  hitCount: number
  matchState: 'pending' | 'completed' | null
}

let refreshStateReady = false
const PENDING_REFRESH_TTL_MS = 1000 * 60 * 10

const normalizeText = (value: unknown) => String(value || '').trim().toLowerCase()

const normalizeStringList = (value: unknown): string[] => {
  if (!Array.isArray(value)) return []
  return Array.from(new Set(value.map((item) => normalizeText(item)).filter(Boolean))).sort()
}

const normalizeNumber = (value: unknown): number | null => {
  const num = Number(value)
  return Number.isFinite(num) ? Number(num) : null
}

const normalizeDateString = (value: unknown): string => {
  if (!value) return ''
  const date = new Date(String(value))
  return Number.isNaN(date.getTime()) ? normalizeText(value) : date.toISOString()
}

const normalizeRange = (range: CheckTargetedRefreshStateInput['range']) => ({
  from: normalizeDateString(range?.from),
  to: normalizeDateString(range?.to),
})

const normalizeRoundedNumberString = (value: unknown): string => {
  if (value === null || value === undefined || value === '') return ''
  const num = Number(value)
  return Number.isFinite(num) ? String(Math.round(num)) : normalizeText(value)
}

const normalizeDecimalString = (value: unknown, precision: number): string => {
  if (value === null || value === undefined || value === '') return ''
  const num = Number(value)
  return Number.isFinite(num) ? num.toFixed(precision) : normalizeText(value)
}

const sortByJson = <T>(items: T[]): T[] =>
  items.slice().sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b)))

const safeParseJson = (value: string | null | undefined) => {
  if (!value) return null
  try {
    return JSON.parse(value)
  } catch {
    return null
  }
}

function toIssueSlug(name: string) {
  return String(name || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
}

const normalizeFoodNutrients = (value: unknown) => {
  if (!value || typeof value !== 'object') return value ?? null
  const raw = value as Record<string, unknown>
  return {
    calories: normalizeNumber(raw.calories),
    protein_g: normalizeNumber(raw.protein_g),
    carbs_g: normalizeNumber(raw.carbs_g),
    fat_g: normalizeNumber(raw.fat_g),
    fiber_g: normalizeNumber(raw.fiber_g),
    sugar_g: normalizeNumber(raw.sugar_g),
    sodium_mg: normalizeNumber(raw.sodium_mg),
  }
}

const normalizeDocumentList = (value: unknown) => {
  if (!Array.isArray(value)) return []
  return sortByJson(
    value.map((item) => {
      if (!item || typeof item !== 'object') {
        return { value: normalizeText(item) }
      }
      const raw = item as Record<string, unknown>
      return {
        id: normalizeText(raw.id),
        name: normalizeText(raw.name),
        url: normalizeText(raw.url),
        uploadedAt: normalizeDateString(raw.uploadedAt),
      }
    })
  )
}

const normalizeImageList = (value: unknown) => {
  if (!Array.isArray(value)) return []
  return sortByJson(
    value.map((item) => {
      if (!item || typeof item !== 'object') {
        return { value: normalizeText(item) }
      }
      const raw = item as Record<string, unknown>
      return {
        id: normalizeText(raw.id),
        name: normalizeText(raw.name),
        url: normalizeText(raw.url),
      }
    })
  )
}

const normalizeMarkerList = (value: unknown) => {
  if (!Array.isArray(value)) return []
  return sortByJson(
    value.map((item) => {
      const raw = item && typeof item === 'object' ? (item as Record<string, unknown>) : {}
      return {
        name: normalizeText(raw.name),
        value: normalizeNumber(raw.value),
        unit: normalizeText(raw.unit),
        reference: normalizeText(raw.reference),
      }
    })
  )
}

async function ensureRefreshStateTable() {
  if (refreshStateReady) return
  try {
    await prisma.$executeRawUnsafe(`
      CREATE TABLE IF NOT EXISTS "InsightsRefreshState" (
        "userId" TEXT NOT NULL,
        "scope" TEXT NOT NULL,
        "payloadHash" TEXT NOT NULL,
        "lastCompletedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        "lastRunId" TEXT,
        "hitCount" INTEGER NOT NULL DEFAULT 1,
        "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        PRIMARY KEY ("userId", "scope")
      )
    `)
    await prisma.$executeRawUnsafe(
      'CREATE INDEX IF NOT EXISTS insights_refresh_state_updated_idx ON "InsightsRefreshState" ("updatedAt" DESC)'
    ).catch(() => {})
    await prisma.$executeRawUnsafe(
      'ALTER TABLE "InsightsRefreshState" ADD COLUMN IF NOT EXISTS "status" TEXT NOT NULL DEFAULT \'completed\''
    ).catch(() => {})
    await prisma.$executeRawUnsafe(
      'ALTER TABLE "InsightsRefreshState" ADD COLUMN IF NOT EXISTS "startedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW()'
    ).catch(() => {})
    refreshStateReady = true
  } catch (error) {
    console.warn('[targeted-refresh-idempotency] Failed to ensure table', error)
    throw error
  }
}

async function buildPayloadHash(input: CheckTargetedRefreshStateInput) {
  const safeUserId = String(input.userId || '').trim()
  if (!safeUserId) {
    return { payloadHash: '', scope: '' }
  }

  try {
    const changeTypes = Array.from(
      new Set(input.changeTypes.map((item) => String(item || '').trim()).filter(Boolean))
    ).sort()
    const affectedSections = Array.from(
      new Set(input.affectedSections.map((item) => String(item || '').trim()).filter(Boolean))
    ).sort()
    const targetIssueSlugs = Array.from(
      new Set(input.targetIssueSlugs.map((item) => toIssueSlug(String(item || ''))).filter(Boolean))
    ).sort()
    const mode = normalizeText(input.mode || 'latest') || 'latest'
    const range = normalizeRange(input.range)
    const pipelineVersion = normalizeText(input.pipelineVersion || '')
    const intent = normalizeText(input.intent || 'default') || 'default'
    const rangeKey = [range.from || 'none', range.to || 'none'].join('|')

    const user = await prisma.user.findUnique({
      where: { id: safeUserId },
      select: {
        gender: true,
        weight: true,
        height: true,
        bodyType: true,
        exerciseFrequency: true,
        exerciseTypes: true,
        healthGoals: {
          select: {
            name: true,
            category: true,
            currentRating: true,
          },
        },
        supplements: {
          select: {
            name: true,
            dosage: true,
            timing: true,
          },
        },
        medications: {
          select: {
            name: true,
            dosage: true,
            timing: true,
          },
        },
        foodLogs: {
          where: {
            createdAt: {
              gte: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000),
            },
          },
          select: {
            name: true,
            description: true,
            meal: true,
            localDate: true,
            nutrients: true,
            createdAt: true,
          },
          orderBy: { createdAt: 'desc' },
          take: 300,
        },
        exerciseLogs: {
          where: {
            createdAt: {
              gte: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000),
            },
          },
          select: {
            type: true,
            duration: true,
            intensity: true,
            createdAt: true,
          },
          orderBy: { createdAt: 'desc' },
          take: 300,
        },
      },
    })

    if (!user) {
      return { payloadHash: '', scope: '' }
    }

    const hiddenGoals = new Map(user.healthGoals.filter((goal) => goal.name.startsWith('__')).map((goal) => [goal.name, goal]))
    const visibleGoalSlugs = sortByJson(
      user.healthGoals
        .filter((goal) => !goal.name.startsWith('__'))
        .map((goal) => ({
          slug: toIssueSlug(goal.name),
          name: normalizeText(goal.name),
          category: normalizeText(goal.category),
          currentRating: normalizeNumber(goal.currentRating),
        }))
        .filter((goal) => goal.slug)
    )
    const selectedIssueSlugs = sortByJson(
      (
        await prisma.$queryRawUnsafe<Array<{ name: string }>>(
          'SELECT name FROM "CheckinIssues" WHERE "userId" = $1',
          safeUserId
        ).catch(() => []) as Array<{ name: string }>
      )
        .map((row) => ({ slug: toIssueSlug(row.name), name: normalizeText(row.name) }))
        .filter((row) => row.slug)
    )

    const profileInfoRaw = safeParseJson(hiddenGoals.get('__PROFILE_INFO_DATA__')?.category) as Record<string, unknown> | null
    const primaryGoalRaw = safeParseJson(hiddenGoals.get('__PRIMARY_GOAL__')?.category) as Record<string, unknown> | null
    const allergiesRaw = safeParseJson(hiddenGoals.get('__ALLERGIES_DATA__')?.category) as Record<string, unknown> | null
    const dietRaw = safeParseJson(hiddenGoals.get('__DIET_PREFERENCE__')?.category) as Record<string, unknown> | null

    const profile = {
      gender: normalizeText(user.gender),
      weight: normalizeRoundedNumberString(user.weight),
      height: normalizeRoundedNumberString(user.height),
      bodyType: normalizeText(user.bodyType),
      birthdate: normalizeText(profileInfoRaw?.dateOfBirth),
      dietTypes: normalizeStringList(
        Array.isArray(dietRaw?.dietTypes)
          ? (dietRaw?.dietTypes as unknown[])
          : typeof dietRaw?.dietType === 'string'
          ? [dietRaw.dietType]
          : []
      ),
      goalChoice: normalizeText(primaryGoalRaw?.goalChoice),
      goalIntensity: normalizeText(primaryGoalRaw?.goalIntensity || 'standard'),
      goalTargetWeightKg: normalizeDecimalString(primaryGoalRaw?.goalTargetWeightKg, 1),
      goalTargetWeightUnit: normalizeText(primaryGoalRaw?.goalTargetWeightUnit),
      goalPaceKgPerWeek: normalizeDecimalString(primaryGoalRaw?.goalPaceKgPerWeek, 2),
      goalCalorieTarget: normalizeRoundedNumberString(primaryGoalRaw?.goalCalorieTarget),
      goalMacroSplit: primaryGoalRaw?.goalMacroSplit && typeof primaryGoalRaw.goalMacroSplit === 'object'
        ? {
            proteinPct: normalizeDecimalString((primaryGoalRaw.goalMacroSplit as Record<string, unknown>).proteinPct, 3),
            carbPct: normalizeDecimalString((primaryGoalRaw.goalMacroSplit as Record<string, unknown>).carbPct, 3),
            fatPct: normalizeDecimalString((primaryGoalRaw.goalMacroSplit as Record<string, unknown>).fatPct, 3),
          }
        : null,
      goalMacroMode: normalizeText(primaryGoalRaw?.goalMacroMode || 'auto'),
      goalFiberTarget: normalizeRoundedNumberString(primaryGoalRaw?.goalFiberTarget),
      goalSugarMax: normalizeRoundedNumberString(primaryGoalRaw?.goalSugarMax),
      allergies: normalizeStringList(allergiesRaw?.allergies),
      diabetesType: normalizeText(allergiesRaw?.diabetesType),
      exerciseFrequency: normalizeText(user.exerciseFrequency),
      exerciseTypes: normalizeStringList(user.exerciseTypes),
    }

    const supplements = sortByJson(
      user.supplements.map((item) => ({
        name: normalizeText(item.name),
        dosage: normalizeText(item.dosage),
        timing: normalizeStringList(item.timing),
      }))
    )

    const medications = sortByJson(
      user.medications.map((item) => ({
        name: normalizeText(item.name),
        dosage: normalizeText(item.dosage),
        timing: normalizeStringList(item.timing),
      }))
    )

    const healthSituationsGoal = hiddenGoals.get('__HEALTH_SITUATIONS_DATA__')
    const healthSituationsRaw = safeParseJson(healthSituationsGoal?.category)
    const healthSituations = healthSituationsRaw
      ? {
          healthIssues: normalizeText((healthSituationsRaw as Record<string, unknown>).healthIssues),
          healthProblems: normalizeText((healthSituationsRaw as Record<string, unknown>).healthProblems),
          additionalInfo: normalizeText((healthSituationsRaw as Record<string, unknown>).additionalInfo),
          skipped: Boolean((healthSituationsRaw as Record<string, unknown>).skipped),
        }
      : null

    const bloodResultsGoal = hiddenGoals.get('__BLOOD_RESULTS_DATA__')
    const bloodResultsRaw = safeParseJson(bloodResultsGoal?.category)
    const bloodResults = bloodResultsRaw
      ? {
          uploadMethod: normalizeText((bloodResultsRaw as Record<string, unknown>).uploadMethod),
          skipped: Boolean((bloodResultsRaw as Record<string, unknown>).skipped),
          notes: normalizeText((bloodResultsRaw as Record<string, unknown>).notes),
          documents: normalizeDocumentList((bloodResultsRaw as Record<string, unknown>).documents),
          images: normalizeImageList((bloodResultsRaw as Record<string, unknown>).images),
          markers: normalizeMarkerList((bloodResultsRaw as Record<string, unknown>).markers),
        }
      : null

    const todaysFoodsGoal = hiddenGoals.get('__TODAYS_FOODS_DATA__')
    const todaysFoodsRaw = safeParseJson(todaysFoodsGoal?.category)
    const todaysFoods = Array.isArray((todaysFoodsRaw as Record<string, unknown> | null)?.foods)
      ? sortByJson(
          ((todaysFoodsRaw as Record<string, unknown>).foods as unknown[]).map((item) => {
            const raw = item && typeof item === 'object' ? (item as Record<string, unknown>) : {}
            return {
              name: normalizeText(raw.name),
              meal: normalizeText(raw.meal),
              calories: normalizeNumber(raw.calories),
              protein_g: normalizeNumber(raw.protein_g),
              carbs_g: normalizeNumber(raw.carbs_g),
              fat_g: normalizeNumber(raw.fat_g),
            }
          })
        )
      : []

    const foodLogs = sortByJson(
      user.foodLogs.map((log) => ({
        name: normalizeText(log.name),
        description: normalizeText(log.description),
        meal: normalizeText(log.meal),
        localDate: normalizeText(log.localDate),
        nutrients: normalizeFoodNutrients(log.nutrients),
        createdAt: normalizeDateString(log.createdAt),
      }))
    )

    const exerciseLogs = sortByJson(
      user.exerciseLogs.map((log) => ({
        type: normalizeText(log.type),
        duration: normalizeNumber(log.duration),
        intensity: normalizeText(log.intensity),
        createdAt: normalizeDateString(log.createdAt),
      }))
    )

    const isFullRefresh = affectedSections.includes('full')
    const includeProfile = isFullRefresh || affectedSections.some((section) => section === 'supplements' || section === 'medications')
    const includeHealthSituations = isFullRefresh || affectedSections.some((section) => section === 'supplements' || section === 'medications')
    const includeSupplements = isFullRefresh || affectedSections.includes('supplements')
    const includeMedications = isFullRefresh || affectedSections.includes('medications')
    const includeBloodResults = isFullRefresh || affectedSections.includes('labs')
    const includeFood = isFullRefresh || affectedSections.includes('nutrition')

    const includeIssueSummaryState = isFullRefresh || targetIssueSlugs.length > 0

    const payload = {
      version: 2,
      changeTypes,
      affectedSections,
      targetIssueSlugs,
      request: {
        mode,
        range,
        pipelineVersion,
        intent,
      },
      data: {
        profile: includeProfile ? profile : undefined,
        supplements: includeSupplements ? supplements : undefined,
        medications: includeMedications ? medications : undefined,
        healthSituations: includeHealthSituations ? healthSituations : undefined,
        bloodResults: includeBloodResults ? bloodResults : undefined,
        food:
          includeFood
            ? {
                foodLogs,
                todaysFoods,
              }
            : undefined,
        exercise: isFullRefresh ? { exerciseLogs } : undefined,
        visibleGoals: includeIssueSummaryState ? visibleGoalSlugs : undefined,
        selectedIssues: includeIssueSummaryState ? selectedIssueSlugs : undefined,
      },
    }

    return {
      payloadHash: hashPayload(payload),
      scope: [
        'targeted-insights',
        affectedSections.join('|') || 'none',
        targetIssueSlugs.join('|') || 'general-health',
        mode,
        rangeKey,
        pipelineVersion || 'current',
        intent,
      ].join('::'),
    }
  } catch (error) {
    console.warn('[targeted-refresh-idempotency] Failed to build payload hash', error)
    return { payloadHash: '', scope: '' }
  }
}

export async function checkTargetedRefreshState(
  input: CheckTargetedRefreshStateInput
): Promise<CheckTargetedRefreshStateResult> {
  const { payloadHash, scope } = await buildPayloadHash(input)
  if (!payloadHash || !scope) {
    return { guardReady: false, shouldSkip: false, payloadHash, scope, hitCount: 0, matchState: null }
  }

  try {
    await ensureRefreshStateTable()

    const rows: Array<{ payloadHash: string; hitCount: number; status: string | null; startedAt: Date | null }> = await prisma.$queryRawUnsafe(
      'SELECT "payloadHash", "hitCount", "status", "startedAt" FROM "InsightsRefreshState" WHERE "userId" = $1 AND "scope" = $2',
      input.userId,
      scope
    )
    const existing = rows?.[0]
    if (existing?.payloadHash === payloadHash) {
      const matchState = existing.status === 'pending' ? 'pending' : 'completed'
      const pendingStartedAt = existing.startedAt ? new Date(existing.startedAt).getTime() : 0
      if (matchState === 'pending' && pendingStartedAt > 0 && Date.now() - pendingStartedAt > PENDING_REFRESH_TTL_MS) {
        await prisma.$queryRawUnsafe(
          'DELETE FROM "InsightsRefreshState" WHERE "userId" = $1 AND "scope" = $2 AND "payloadHash" = $3',
          input.userId,
          scope,
          payloadHash
        )
        return {
          guardReady: true,
          shouldSkip: false,
          payloadHash,
          scope,
          hitCount: 1,
          matchState: null,
        }
      }
      const nextHitCount = Number(existing.hitCount || 0) + 1
      await prisma.$queryRawUnsafe(
        'UPDATE "InsightsRefreshState" SET "hitCount" = $1, "updatedAt" = NOW() WHERE "userId" = $2 AND "scope" = $3',
        nextHitCount,
        input.userId,
        scope
      )
      return {
        guardReady: true,
        shouldSkip: true,
        payloadHash,
        scope,
        hitCount: nextHitCount,
        matchState,
      }
    }
  } catch (error) {
    console.warn('[targeted-refresh-idempotency] Failed to read refresh state', error)
    return { guardReady: false, shouldSkip: false, payloadHash, scope, hitCount: 0, matchState: null }
  }

  return { guardReady: true, shouldSkip: false, payloadHash, scope, hitCount: 1, matchState: null }
}

export async function recordTargetedRefreshState(options: {
  userId: string
  scope: string
  payloadHash: string
  runId?: string | null
  status?: 'pending' | 'completed'
}) {
  if (!options.userId || !options.scope || !options.payloadHash) return

  try {
    await ensureRefreshStateTable()
    await prisma.$queryRawUnsafe(
      `INSERT INTO "InsightsRefreshState" ("userId", "scope", "payloadHash", "lastCompletedAt", "lastRunId", "hitCount", "updatedAt", "status", "startedAt")
       VALUES ($1, $2, $3, CASE WHEN $5 = 'completed' THEN NOW() ELSE NOW() END, $4, 1, NOW(), $5, NOW())
       ON CONFLICT ("userId", "scope")
       DO UPDATE SET "payloadHash" = EXCLUDED."payloadHash",
                     "lastCompletedAt" = CASE WHEN EXCLUDED."status" = 'completed' THEN EXCLUDED."lastCompletedAt" ELSE "InsightsRefreshState"."lastCompletedAt" END,
                     "lastRunId" = EXCLUDED."lastRunId",
                     "hitCount" = 1,
                     "status" = EXCLUDED."status",
                     "startedAt" = NOW(),
                     "updatedAt" = NOW()`,
      options.userId,
      options.scope,
      options.payloadHash,
      options.runId || null,
      options.status || 'completed'
    )
  } catch (error) {
    console.warn('[targeted-refresh-idempotency] Failed to record refresh state', error)
    throw error
  }
}

export async function completeTargetedRefreshState(options: {
  userId: string
  scope: string
  payloadHash: string
  runId?: string | null
}) {
  if (!options.userId || !options.scope || !options.payloadHash) return

  try {
    await ensureRefreshStateTable()
    await prisma.$queryRawUnsafe(
      `INSERT INTO "InsightsRefreshState" ("userId", "scope", "payloadHash", "lastCompletedAt", "lastRunId", "hitCount", "updatedAt", "status", "startedAt")
       VALUES ($1, $2, $3, NOW(), $4, 1, NOW(), 'completed', NOW())
       ON CONFLICT ("userId", "scope")
       DO UPDATE SET "payloadHash" = EXCLUDED."payloadHash",
                     "lastCompletedAt" = NOW(),
                     "lastRunId" = EXCLUDED."lastRunId",
                     "hitCount" = 1,
                     "status" = 'completed',
                     "updatedAt" = NOW()`,
      options.userId,
      options.scope,
      options.payloadHash,
      options.runId || null
    )
  } catch (error) {
    console.warn('[targeted-refresh-idempotency] Failed to complete refresh state', error)
    throw error
  }
}

export async function clearTargetedRefreshState(options: {
  userId: string
  scope: string
  payloadHash?: string | null
}) {
  if (!options.userId || !options.scope) return

  try {
    await ensureRefreshStateTable()
    if (options.payloadHash) {
      await prisma.$queryRawUnsafe(
        'DELETE FROM "InsightsRefreshState" WHERE "userId" = $1 AND "scope" = $2 AND "payloadHash" = $3',
        options.userId,
        options.scope,
        options.payloadHash
      )
      return
    }

    await prisma.$queryRawUnsafe(
      'DELETE FROM "InsightsRefreshState" WHERE "userId" = $1 AND "scope" = $2',
      options.userId,
      options.scope
    )
  } catch (error) {
    console.warn('[targeted-refresh-idempotency] Failed to clear refresh state', error)
  }
}

