}

export async function listThreads(userId: string): Promise<ChatThread[]> {
  await ensureMedicalChatTables()
  const rows: Array<{
    id: string
    title: string | null
    archivedAt: Date | null
    lastChargedCost: number | null
    lastChargedAt: Date | null
