    'SELECT "id","title","archivedAt","lastChargedCost","lastChargedAt","lastChargeCovered","createdAt","updatedAt" FROM "MedicalChatThread" WHERE "userId" = $1 ORDER BY "updatedAt" DESC LIMIT 50',
    userId
