  await ensureMedicalChatTables()
  const id = uuid()
  await prisma.$executeRawUnsafe(
    'INSERT INTO "MedicalChatThread" ("id","userId","title","context") VALUES ($1,$2,$3,CAST($4 AS JSONB))',
