    'SELECT "id","title","context" FROM "MedicalChatThread" WHERE "id" = $1 AND "userId" = $2 LIMIT 1',
    threadId,
    userId
  )
  const row = rows[0]
  if (!row) return null
  return {
    id: row.id,
    title: row.title,
    context: row.context ? (row.context as ChatContext) : null,
