/**
 * Ensure MedicationCatalog table exists (idempotent).
 * Vercel builds don't run migrations here, so we create it at runtime.
 */
export async function ensureMedicationCatalogSchema(): Promise<void> {
  try {
    await prisma.$executeRawUnsafe(`
      CREATE TABLE IF NOT EXISTS "MedicationCatalog" (
        "id" TEXT NOT NULL,
        "userId" TEXT,
        "brand" TEXT,
        "product" TEXT,
        "fullName" TEXT NOT NULL,
        "dosage" TEXT NOT NULL DEFAULT '',
        "source" TEXT NOT NULL,
        "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
        "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
        CONSTRAINT "MedicationCatalog_pkey" PRIMARY KEY ("id")
      );
    `)

    await prisma.$executeRawUnsafe(`
      CREATE INDEX IF NOT EXISTS "MedicationCatalog_brand_idx" ON "MedicationCatalog"("brand");
    `).catch(() => {})

    await prisma.$executeRawUnsafe(`
      CREATE INDEX IF NOT EXISTS "MedicationCatalog_product_idx" ON "MedicationCatalog"("product");
    `).catch(() => {})

    await prisma.$executeRawUnsafe(`
      CREATE INDEX IF NOT EXISTS "MedicationCatalog_fullName_idx" ON "MedicationCatalog"("fullName");
    `).catch(() => {})

    await prisma.$executeRawUnsafe(`
      CREATE UNIQUE INDEX IF NOT EXISTS "MedicationCatalog_userId_fullName_dosage_source_key"
      ON "MedicationCatalog"("userId", "fullName", "dosage", "source");
    `).catch(() => {})

    await prisma.$executeRawUnsafe(`
      DO $$
      BEGIN
        IF NOT EXISTS (
          SELECT 1 FROM information_schema.table_constraints
          WHERE constraint_name = 'MedicationCatalog_userId_fkey'
        ) THEN
          ALTER TABLE "MedicationCatalog"
          ADD CONSTRAINT "MedicationCatalog_userId_fkey"
          FOREIGN KEY ("userId") REFERENCES "User"("id")
          ON DELETE SET NULL ON UPDATE CASCADE;
        END IF;
      END $$;
    `).catch(() => {})
  } catch (error: any) {
    console.error('❌ Error ensuring MedicationCatalog schema:', error)
    throw new Error(`Failed to ensure MedicationCatalog schema: ${error?.message || 'Unknown error'}`)
  }
}

import OpenAI from 'openai';
import { costCentsForTokens, estimateTokensFromText } from './cost-meter';
import { reportCriticalError } from '@/lib/error-reporter';
import { assertAiUsageAllowed } from '@/lib/ai-safety';
import { getRunContext } from './run-context';
import { HELFI_ANALYSIS_MODEL, isSpecialistOpenAIModel } from './ai-models';

type CreateParams = Parameters<OpenAI['chat']['completions']['create']>[0];
type AiCallContext = {
  feature?: string | null
  userId?: string | null
  runId?: string | null
}

export type CompletionWithCost<T = any> = {
  completion: T;
  costCents: number;
  promptTokens: number;
  completionTokens: number;
};

function shouldReportCriticalOpenAIError(error: any): boolean {
  const status = Number(error?.status ?? error?.statusCode ?? error?.response?.status ?? 0)
  const code = String(error?.code || error?.error?.code || '').toLowerCase()
  const message = String(error?.message || '').toLowerCase()

  // Expected client input errors (bad MIME/file types) should not spam owner alerts.
  if (status === 400) {
    if (
      code === 'invalid_image_format' ||
      message.includes('invalid mime type') ||
      message.includes('only image types are supported') ||
      message.includes('invalid image format') ||
      message.includes('unsupported image')
    ) {
      return false
    }
  }

  return true
}

/**
 * Non-streaming chat completion that returns calculated cost in cents.
 * Callers can then charge the wallet accordingly.
 */
export async function chatCompletionWithCost(
  openai: OpenAI,
  params: CreateParams,
  context: AiCallContext = {}
): Promise<CompletionWithCost<OpenAI.Chat.Completions.ChatCompletion>> {
  const asyncContext = getRunContext()
  const mergedContext: AiCallContext = {
    feature: context.feature ?? asyncContext?.feature ?? null,
    userId: context.userId ?? asyncContext?.meta?.userId ?? null,
    runId: context.runId ?? asyncContext?.runId ?? null,
  }
  const requestedModel = String((params as any).model || '').trim()
  const keepRequestedModel =
    mergedContext.feature === 'admin:food-benchmark' ||
    isSpecialistOpenAIModel(requestedModel)
  const effectiveModel = keepRequestedModel ? requestedModel : HELFI_ANALYSIS_MODEL
  const effectiveParams: any = { ...params, model: effectiveModel }
  const modelName = effectiveModel.toLowerCase()
  const isGpt5Family = modelName.includes('gpt-5')
  const normalizedParams = (() => {
    if (!isGpt5Family) return effectiveParams
    const maxTokens = Number(effectiveParams.max_tokens)
    const maxCompletionTokens = Number(effectiveParams.max_completion_tokens)
    const next: any = { ...effectiveParams }
    delete next.max_tokens
    delete next.temperature
    if (modelName.includes('gpt-5.6') && !next.reasoning_effort) {
      // Most Helfi calls have small, user-facing response budgets. GPT-5.6
      // counts reasoning tokens inside max_completion_tokens, so using "low"
      // can consume the whole allowance and return no visible answer.
      // Use the model's supported "none" setting by default; quality-first
      // workflows such as weekly reports opt into more reasoning explicitly.
      next.reasoning_effort = 'none'
    }
    if (Number.isFinite(maxCompletionTokens) && maxCompletionTokens > 0) {
      next.max_completion_tokens = maxCompletionTokens
    } else if (Number.isFinite(maxTokens) && maxTokens > 0) {
      next.max_completion_tokens = maxTokens
    }
    return next
  })()
  try {
    await assertAiUsageAllowed(mergedContext)
    const completion = await openai.chat.completions.create({
      ...normalizedParams,
      stream: false,
    } as any);

    // Try to use official usage first; if absent, fall back to a rough estimate.
    const usage = (completion as any).usage || {};
    const model = (completion as any).model || effectiveModel || HELFI_ANALYSIS_MODEL;
    const promptTokens = Number(usage?.prompt_tokens || 0);
    const completionTokens = Number(usage?.completion_tokens || 0);

    let costCents = 0;
    if (promptTokens > 0 || completionTokens > 0) {
      costCents = costCentsForTokens(model, { promptTokens, completionTokens });
    } else {
      // Fallback: estimate from message text and max_tokens
      const promptText = extractPromptText(params.messages);
      const maxTokens =
        Number((params as any).max_tokens) ||
        Number((params as any).max_completion_tokens) ||
        0;
      const expectedOutputChars = Math.max(0, maxTokens * 4);
      costCents = costCentsForTokens(model, {
        promptTokens: estimateTokensFromText(promptText),
        completionTokens: Math.ceil(expectedOutputChars / 4),
      });
    }

    return {
      completion,
      costCents,
      promptTokens,
      completionTokens,
    };
  } catch (error) {
    const model = effectiveModel || 'unknown'
    const maxTokens =
      Number((params as any).max_tokens) ||
      Number((params as any).max_completion_tokens) ||
      0
    if (shouldReportCriticalOpenAIError(error)) {
      reportCriticalError({
        source: 'openai.chat.completions',
        error,
        details: {
          model,
          maxTokens,
        },
      })
    }
    throw error
  }
}

function extractPromptText(messages: any[]): string {
  try {
    return (messages || [])
      .map((m) => {
        if (!m?.content) return '';
        if (typeof m.content === 'string') return m.content;
        if (Array.isArray(m.content)) {
          return m.content
            .map((p: any) => (typeof p?.text === 'string' ? p.text : ''))
            .join('\n');
        }
        return '';
      })
      .join('\n');
  } catch {
    return '';
  }
}

'use client'

export type LocalMoodMediaKind = 'image' | 'audio'

export type LocalMoodMediaRecord = {
  id: string
  kind: LocalMoodMediaKind
  blob: Blob
  fileName: string
  mimeType: string
  createdAt: number
}

const DB_NAME = 'helfi-local-media'
const DB_VERSION = 1
const STORE_NAME = 'mood-media'
const ENTRY_MAP_KEY = 'helfi-mood-entry-media-map-v1'

type EntryMediaMap = Record<string, string[]>

const isBrowser = () =>
  typeof window !== 'undefined' && typeof indexedDB !== 'undefined'

const openDb = (): Promise<IDBDatabase> =>
  new Promise((resolve, reject) => {
    if (!isBrowser()) {
      reject(new Error('Local media storage is not available in this environment'))
      return
    }

    const request = indexedDB.open(DB_NAME, DB_VERSION)

    request.onupgradeneeded = () => {
      const db = request.result
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' })
      }
    }

    request.onsuccess = () => resolve(request.result)
    request.onerror = () => reject(request.error || new Error('Failed to open local media database'))
  })

const withStore = async <T>(
  mode: IDBTransactionMode,
  run: (store: IDBObjectStore, done: (value: T) => void, fail: (error: unknown) => void) => void,
): Promise<T> => {
  const db = await openDb()
  return new Promise<T>((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, mode)
    const store = tx.objectStore(STORE_NAME)
    let settled = false

    const done = (value: T) => {
      if (settled) return
      settled = true
      resolve(value)
    }

    const fail = (error: unknown) => {
      if (settled) return
      settled = true
      reject(error)
    }

    tx.onerror = () => fail(tx.error || new Error('Local media transaction failed'))
    tx.onabort = () => fail(tx.error || new Error('Local media transaction aborted'))
    tx.oncomplete = () => {
      db.close()
    }

    run(store, done, fail)
  })
}

export async function saveLocalMoodMedia(record: LocalMoodMediaRecord): Promise<void> {
  await withStore<void>('readwrite', (store, done, fail) => {
    const request = store.put(record)
    request.onsuccess = () => done()
    request.onerror = () => fail(request.error || new Error('Failed to save local media'))
  })
}

export async function getLocalMoodMedia(id: string): Promise<LocalMoodMediaRecord | null> {
  return withStore<LocalMoodMediaRecord | null>('readonly', (store, done, fail) => {
    const request = store.get(id)
    request.onsuccess = () => done((request.result as LocalMoodMediaRecord) || null)
    request.onerror = () => fail(request.error || new Error('Failed to load local media'))
  })
}

export async function getLocalMoodMediaMany(ids: string[]): Promise<LocalMoodMediaRecord[]> {
  const results: LocalMoodMediaRecord[] = []
  for (const id of ids) {
    const item = await getLocalMoodMedia(id)
    if (item) results.push(item)
  }
  return results
}

export async function deleteLocalMoodMedia(id: string): Promise<void> {
  await withStore<void>('readwrite', (store, done, fail) => {
    const request = store.delete(id)
    request.onsuccess = () => done()
    request.onerror = () => fail(request.error || new Error('Failed to delete local media'))
  })
}

const readEntryMediaMap = (): EntryMediaMap => {
  if (typeof window === 'undefined') return {}
  const raw = window.localStorage.getItem(ENTRY_MAP_KEY)
  if (!raw) return {}
  try {
    const parsed = JSON.parse(raw)
    if (!parsed || typeof parsed !== 'object') return {}
    return Object.fromEntries(
      Object.entries(parsed)
        .filter((entry): entry is [string, unknown] => Array.isArray((entry as any)[1]))
        .map(([key, value]) => [
          key,
          (value as unknown[])
            .map((item) => String(item || '').trim())
            .filter(Boolean),
        ]),
    )
  } catch {
    return {}
  }
}

const writeEntryMediaMap = (map: EntryMediaMap) => {
  if (typeof window === 'undefined') return
  window.localStorage.setItem(ENTRY_MAP_KEY, JSON.stringify(map))
}

export function getEntryMediaIds(entryId: string): string[] {
  const map = readEntryMediaMap()
  return map[entryId] || []
}

export function setEntryMediaIds(entryId: string, mediaIds: string[]) {
  const map = readEntryMediaMap()
  const cleaned = Array.from(
    new Set(mediaIds.map((item) => String(item || '').trim()).filter(Boolean)),
  )
  if (cleaned.length === 0) {
    delete map[entryId]
  } else {
    map[entryId] = cleaned
  }
  writeEntryMediaMap(map)
}

export function removeEntryMediaIds(entryId: string) {
  const map = readEntryMediaMap()
  if (map[entryId]) {
    delete map[entryId]
    writeEntryMediaMap(map)
  }
}

export function getAllEntryMediaMap(): EntryMediaMap {
  return readEntryMediaMap()
}

export type MoodReminderSyncPayload = {
  enabled: boolean
  frequency: number
  time1: string
  time2: string
  time3: string
  time4: string
  timezone: string
  maxFrequency?: number
  updatedAt?: number
}

const CHANNEL_NAME = 'helfi-mood-reminders'
const STORAGE_KEY = 'helfi-mood-reminders:last-update'

function parsePayload(raw: unknown): MoodReminderSyncPayload | null {
  if (!raw || typeof raw !== 'object') return null
  const data = raw as Record<string, unknown>
  const enabled = typeof data.enabled === 'boolean' ? data.enabled : null
  const frequency = Number(data.frequency)
  const time1 = typeof data.time1 === 'string' ? data.time1 : null
  const time2 = typeof data.time2 === 'string' ? data.time2 : null
  const time3 = typeof data.time3 === 'string' ? data.time3 : null
  const time4 = typeof data.time4 === 'string' ? data.time4 : null
  const timezone = typeof data.timezone === 'string' ? data.timezone : null
  const maxFrequency = Number(data.maxFrequency)
  const updatedAt = Number(data.updatedAt)

  if (
    enabled === null ||
    !Number.isFinite(frequency) ||
    !time1 ||
    !time2 ||
    !time3 ||
    !time4 ||
    !timezone
  ) {
    return null
  }

  return {
    enabled,
    frequency,
    time1,
    time2,
    time3,
    time4,
    timezone,
    maxFrequency: Number.isFinite(maxFrequency) ? maxFrequency : undefined,
    updatedAt: Number.isFinite(updatedAt) ? updatedAt : undefined,
  }
}

export function publishMoodReminderSync(payload: MoodReminderSyncPayload) {
  if (typeof window === 'undefined') return

  const withTimestamp: MoodReminderSyncPayload = {
    ...payload,
    updatedAt: Date.now(),
  }

  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(withTimestamp))
  } catch {}

  try {
    const channel = new BroadcastChannel(CHANNEL_NAME)
    channel.postMessage(withTimestamp)
    channel.close()
  } catch {}
}

export function subscribeMoodReminderSync(onPayload: (payload: MoodReminderSyncPayload) => void) {
  if (typeof window === 'undefined') return () => {}

  const onStorage = (event: StorageEvent) => {
    if (event.key !== STORAGE_KEY || !event.newValue) return
    try {
      const parsed = parsePayload(JSON.parse(event.newValue))
      if (parsed) onPayload(parsed)
    } catch {}
  }

  let channel: BroadcastChannel | null = null
  const onMessage = (event: MessageEvent) => {
    const parsed = parsePayload(event.data)
    if (parsed) onPayload(parsed)
  }

  window.addEventListener('storage', onStorage)
  try {
    channel = new BroadcastChannel(CHANNEL_NAME)
    channel.addEventListener('message', onMessage)
  } catch {}

  return () => {
    window.removeEventListener('storage', onStorage)
    if (channel) {
      channel.removeEventListener('message', onMessage)
      channel.close()
    }
  }
}

import { NextRequest } from 'next/server'
import { decode } from 'next-auth/jwt'

const SECRETS = [process.env.NEXTAUTH_SECRET, process.env.AUTH_SECRET]
  .map((value) => String(value || '').trim())
  .filter(Boolean)

const SALTS: Array<string | undefined> = [
  undefined,
  'next-auth.jwt',
  'authjs.jwt',
  'authjs.session-token',
  '__Secure-authjs.session-token',
  'next-auth.session-token',
  '__Secure-next-auth.session-token',
]

function extractNativeToken(req: NextRequest): string {
  const authHeader = req.headers.get('authorization') || req.headers.get('Authorization') || ''
  const nativeHeader = req.headers.get('x-native-token') || req.headers.get('X-Native-Token') || ''

  if (nativeHeader) {
    return nativeHeader.trim().replace(/^"+|"+$/g, '')
  }

  const match = authHeader.match(/^Bearer\s+(.+)$/i)
  if (match?.[1]) return match[1].trim().replace(/^"+|"+$/g, '')

  const cookieNames = [
    'next-auth.session-token',
    '__Secure-next-auth.session-token',
    'authjs.session-token',
    '__Secure-authjs.session-token',
  ]
  for (const name of cookieNames) {
    const value = req.cookies.get(name)?.value
    if (value) return value.trim().replace(/^"+|"+$/g, '')
  }

  return ''
}

export async function getUserIdFromNativeAuth(req: NextRequest): Promise<string | null> {
  if (!SECRETS.length) return null

  const token = extractNativeToken(req)
  if (!token) return null

  for (const secret of SECRETS) {
    for (const salt of SALTS) {
      try {
        const payload: any = salt
          ? await decode({ token, secret, salt })
          : await decode({ token, secret })
        const userId = payload?.sub || payload?.id
        if (typeof userId === 'string' && userId) {
          return userId
        }
      } catch {
        // Try the next secret/salt combination.
      }
    }
  }

  return null
}

