import crypto from 'crypto'

export type NativeDeviceOauthProvider = 'fitbit' | 'garmin'

type NativeDeviceOauthTicketPayload = {
  provider: NativeDeviceOauthProvider
  userId: string
  exp: number
  nonce: string
}

const TTL_MS = 15 * 60 * 1000

function getSecret() {
  const secret = String(process.env.NEXTAUTH_SECRET || process.env.AUTH_SECRET || '').trim()
  if (!secret) throw new Error('Auth secret is not configured')
  return secret
}

function signPayload(payloadSegment: string) {
  return crypto.createHmac('sha256', getSecret()).update(payloadSegment).digest('base64url')
}

export function createNativeDeviceOauthTicket(provider: NativeDeviceOauthProvider, userId: string) {
  const payload: NativeDeviceOauthTicketPayload = {
    provider,
    userId,
    exp: Date.now() + TTL_MS,
    nonce: crypto.randomUUID(),
  }
  const payloadSegment = Buffer.from(JSON.stringify(payload)).toString('base64url')
  return `${payloadSegment}.${signPayload(payloadSegment)}`
}

export function verifyNativeDeviceOauthTicket(
  ticket: string | null | undefined,
  provider?: NativeDeviceOauthProvider,
): NativeDeviceOauthTicketPayload | null {
  const raw = String(ticket || '').trim()
  const [payloadSegment, signature] = raw.split('.')
  if (!payloadSegment || !signature) return null

  const expected = signPayload(payloadSegment)
  const expectedBytes = Buffer.from(expected)
  const signatureBytes = Buffer.from(signature)
  if (expectedBytes.length !== signatureBytes.length) return null
  if (!crypto.timingSafeEqual(expectedBytes, signatureBytes)) return null

  try {
    const payload = JSON.parse(Buffer.from(payloadSegment, 'base64url').toString('utf8')) as NativeDeviceOauthTicketPayload
    if (!payload?.userId || !payload.provider || !payload.exp) return null
    if (provider && payload.provider !== provider) return null
    if (payload.exp < Date.now()) return null
    return payload
  } catch {
    return null
  }
}

import crypto from 'crypto'
import { prisma } from '@/lib/prisma'

const HANDOFF_NAME_PREFIX = '__NATIVE_VOICE_PROMPT_HANDOFF__:'
const HANDOFF_TTL_MS = 10 * 60 * 1000

function cleanPrompt(value: unknown) {
  return String(value || '').replace(/\s+/g, ' ').trim().slice(0, 1200)
}

function handoffName(token: string) {
  return `${HANDOFF_NAME_PREFIX}${token}`
}

export async function createNativeVoicePromptHandoff(userId: string, prompt: unknown) {
  const cleanedPrompt = cleanPrompt(prompt)
  const token = crypto.randomBytes(24).toString('base64url')
  const expiresAt = Date.now() + HANDOFF_TTL_MS
  const expiresAtSeconds = Math.floor(expiresAt / 1000)

  await prisma.healthGoal.deleteMany({
    where: {
      userId,
      name: { startsWith: HANDOFF_NAME_PREFIX },
      currentRating: { lt: Math.floor(Date.now() / 1000) },
    },
  }).catch(() => {})

  await prisma.healthGoal.create({
    data: {
      userId,
      name: handoffName(token),
      category: JSON.stringify({ prompt: cleanedPrompt, expiresAt }),
      currentRating: expiresAtSeconds,
    },
  })

  return { token, expiresAt }
}

export async function consumeNativeVoicePromptHandoff(userId: string, token: unknown) {
  const cleanToken = String(token || '').trim()
  if (!/^[A-Za-z0-9_-]{20,120}$/.test(cleanToken)) return ''

  const record = await prisma.healthGoal.findFirst({
    where: {
      userId,
      name: handoffName(cleanToken),
    },
    orderBy: { createdAt: 'desc' },
  })
  if (!record) return ''

  await prisma.healthGoal.delete({ where: { id: record.id } }).catch(() => {})

  try {
    const parsed = JSON.parse(record.category || '{}')
    const expiresAt = Number(parsed?.expiresAt)
    if (!Number.isFinite(expiresAt) || expiresAt < Date.now()) return ''
    return cleanPrompt(parsed?.prompt)
  } catch {
    return ''
  }
}

import crypto from 'crypto'

const REVIEW_TOKEN_VERSION = 'v1'

function reviewTokenSecret() {
  const secret = process.env.NEXTAUTH_SECRET || process.env.AUTH_SECRET || process.env.JWT_SECRET
  if (secret) return secret
  if (process.env.NODE_ENV === 'production') {
    throw new Error('Native voice review token secret is not configured.')
  }
  return 'helfi-native-voice-review-token-local'
}

function stableValue(value: any): any {
  if (Array.isArray(value)) return value.map(stableValue)
  if (!value || typeof value !== 'object') return value
  return Object.fromEntries(
    Object.keys(value)
      .filter((key) => key !== 'reviewToken')
      .sort()
      .map((key) => [key, stableValue(value[key])]),
  )
}

function reviewPayload(userId: string, draft: any) {
  return JSON.stringify({
    userId,
    draft: stableValue(draft || {}),
  })
}

export function signNativeVoiceDraft(userId: string, draft: any) {
  const digest = crypto
    .createHmac('sha256', reviewTokenSecret())
    .update(reviewPayload(userId, draft))
    .digest('base64url')
  return `${REVIEW_TOKEN_VERSION}.${digest}`
}

export function verifyNativeVoiceDraft(userId: string, draft: any) {
  const token = String(draft?.reviewToken || '')
  if (!token.startsWith(`${REVIEW_TOKEN_VERSION}.`)) return false
  const expected = signNativeVoiceDraft(userId, draft)
  const expectedBuffer = Buffer.from(expected)
  const tokenBuffer = Buffer.from(token)
  if (expectedBuffer.length !== tokenBuffer.length) return false
  return crypto.timingSafeEqual(expectedBuffer, tokenBuffer)
}

const NEON_API_BASE = 'https://console.neon.tech/api/v2'

export type NeonConsumptionMetric = {
  metric_name: string
  value: number
}

export type NeonConsumptionPeriod = {
  period_start: string
  period_end: string
  consumption: NeonConsumptionMetric[]
}

export type NeonConsumptionResponse = {
  periods?: NeonConsumptionPeriod[]
}

export type NeonUsageSummary = {
  from: string
  to: string
  metrics: Record<string, number>
  note?: string
}

export type NeonCostEstimate = {
  estimatedDailyCostUsd: number | null
  computeUsd?: number
  storageUsd?: number
  note?: string
}

const buildQuery = (params: Record<string, string | undefined>) => {
  const entries = Object.entries(params).filter(([, value]) => value)
  if (!entries.length) return ''
  const query = new URLSearchParams(entries as Array<[string, string]>).toString()
  return `?${query}`
}

const parseNumber = (value: string | undefined, fallback: number) => {
  const parsed = Number(value)
  return Number.isFinite(parsed) ? parsed : fallback
}

export async function fetchNeonUsageSummary(options: {
  from: string
  to: string
  granularity?: 'hourly' | 'daily' | 'monthly'
  orgId?: string
}) : Promise<NeonUsageSummary | null> {
  const apiKey = (process.env.NEON_API_KEY || '').trim()
  if (!apiKey) {
    return null
  }

  const query = buildQuery({
    from: options.from,
    to: options.to,
    granularity: options.granularity || 'daily',
    org_id: options.orgId,
  })

  const url = `${NEON_API_BASE}/consumption_history/account${query}`

  try {
    const response = await fetch(url, {
      headers: {
        Accept: 'application/json',
        Authorization: `Bearer ${apiKey}`,
      },
      cache: 'no-store',
    })

    if (!response.ok) {
      const text = await response.text().catch(() => '')
      return {
        from: options.from,
        to: options.to,
        metrics: {},
        note: `Neon API error (${response.status}). ${text.slice(0, 200)}`,
      }
    }

    const data = (await response.json().catch(() => null)) as NeonConsumptionResponse | null
    const metrics: Record<string, number> = {}

    for (const period of data?.periods || []) {
      for (const item of period.consumption || []) {
        const key = item.metric_name
        const current = metrics[key] || 0
        metrics[key] = current + Number(item.value || 0)
      }
    }

    return {
      from: options.from,
      to: options.to,
      metrics,
    }
  } catch (error: any) {
    return {
      from: options.from,
      to: options.to,
      metrics: {},
      note: error?.message || 'Neon API request failed',
    }
  }
}

export function estimateDailyCostUsd(
  usage: NeonUsageSummary | null,
  options?: {
    computeCuHourUsd?: number
    storageGbMonthUsd?: number
  }
): NeonCostEstimate {
  if (!usage) {
    return { estimatedDailyCostUsd: null, note: 'Neon usage data missing.' }
  }

  const computeSeconds = Number(usage.metrics.compute_time_seconds || 0)
  const storageBytes =
    Number(usage.metrics.synthetic_storage_size_bytes || 0) ||
    Number(usage.metrics.data_storage_bytes || 0) ||
    Number(usage.metrics.logical_size_bytes || 0)

  const computeCuHourUsd = parseNumber(
    process.env.NEON_COMPUTE_CU_HOUR_USD,
    options?.computeCuHourUsd ?? 0.106
  )
  const storageGbMonthUsd = parseNumber(
    process.env.NEON_STORAGE_GB_MONTH_USD,
    options?.storageGbMonthUsd ?? 0.35
  )

  const computeUsd = Number.isFinite(computeSeconds)
    ? (computeSeconds / 3600) * computeCuHourUsd
    : 0
  const storageUsd = Number.isFinite(storageBytes)
    ? (storageBytes / (1024 ** 3)) * (storageGbMonthUsd / 30)
    : 0

  if (!computeUsd && !storageUsd) {
    return { estimatedDailyCostUsd: null, note: 'Neon usage data missing compute/storage metrics.' }
  }

  return {
    estimatedDailyCostUsd: computeUsd + storageUsd,
    computeUsd,
    storageUsd,
  }
}

