  type?: string | null
  source?: string | null
  eventKey?: string | null
  metadata?: Record<string, unknown> | null
  inboxDelayHours?: number | null
}) {
  await ensureNotificationInboxTable()
  if (!params.userId || !params.title) return null
  const id = randomUUID()
  const body = params.body ?? null
  const url = params.url ?? null
  const type = params.type ?? null
  const source = params.source ?? null
  const eventKey = params.eventKey ?? null
  const baseMetadata = params.metadata ?? {}
  const delayHoursRaw =
    typeof params.inboxDelayHours === 'number' && Number.isFinite(params.inboxDelayHours)
      ? params.inboxDelayHours
      : source === 'push'
        ? DEFAULT_PUSH_INBOX_DELAY_HOURS
        : 0
  const delayHours = Math.max(0, delayHoursRaw)
  const metadata =
    delayHours > 0
      ? {
          ...baseMetadata,
          inboxVisibleAfterMs: Date.now() + Math.round(delayHours * 60 * 60 * 1000),
        }
      : baseMetadata
  try {
    await prisma.$executeRawUnsafe(
      `INSERT INTO NotificationInbox (id, userId, title, body, url, type, status, source, eventKey, metadata)
       VALUES ($1,$2,$3,$4,$5,$6,'unread',$7,$8,$9::jsonb)
       ON CONFLICT DO NOTHING`,
      id,
      params.userId,
      params.title,
      body,
      url,
      type,
      source,
      eventKey,
      JSON.stringify(metadata)
    )
  } catch (error) {
    console.warn('[notifications] Failed to create inbox item', error)
    return null
  }
  return id
}

export async function consumePendingNotificationOpen(
  userId: string,
  options?: { withinMinutes?: number; types?: string[]; sources?: string[]; urlPrefix?: string | null }
): Promise<{ id: string; url: string } | null> {
  await ensureNotificationInboxTable()
  const withinMinutes = Math.min(Math.max(Number(options?.withinMinutes ?? 10), 1), 180)
  const types = Array.isArray(options?.types) && options.types.length > 0 ? options.types : null
  const sources = Array.isArray(options?.sources) && options.sources.length > 0 ? options.sources : null
  const urlPrefix = typeof options?.urlPrefix === 'string' && options.urlPrefix.trim() ? options.urlPrefix.trim() : null

  try {
    const rows: Array<{ id: string; url: string | null }> = await prisma.$queryRawUnsafe(
      `SELECT id, url
       FROM NotificationInbox
       WHERE userId = $1
         AND url IS NOT NULL
         AND status = 'unread'
         AND ($2::text[] IS NULL OR type = ANY($2))
         AND ($3::text[] IS NULL OR source = ANY($3))
         AND ($4::text IS NULL OR url LIKE ($4 || '%'))
         AND (metadata->>'launchConsumedAt' IS NULL OR metadata->>'launchConsumedAt' = '')
         AND createdAt >= NOW() - ($5 * INTERVAL '1 minute')
       ORDER BY createdAt DESC
       LIMIT 1`,
      userId,
      types,
      sources,
      urlPrefix,
      withinMinutes
    )

    const row = rows?.[0]
    if (!row?.id || !row?.url) return null

    await prisma.$executeRawUnsafe(
      `UPDATE NotificationInbox
       SET metadata = jsonb_set(COALESCE(NULLIF(metadata, 'null'::jsonb), '{}'::jsonb), '{launchConsumedAt}', to_jsonb(NOW()::text), true)
       WHERE id = $1 AND userId = $2`,
      row.id,
      userId
    )

    return { id: row.id, url: row.url }
  } catch (error) {
    console.warn('[notifications] Failed to consume pending open', error)
    return null
  }
}

