import { prisma } from '@/lib/prisma'
import webpush from 'web-push'
import { dedupeSubscriptions, normalizeSubscriptionList, removeSubscriptionsByEndpoint, sendToSubscriptions } from '@/lib/push-subscriptions'

/**
 * Owner Notification System
 * Sends push notifications to the app owner when important events occur:
 * - New user signups
 * - Subscription purchases
 * - Credit purchases
 * 
 * Uses the same web-push system as check-in reminders.
 * Owner must subscribe to push notifications first via their account.
 */

interface NotificationOptions {
  event: 'signup' | 'subscription' | 'credit_purchase'
  userEmail: string
  userName?: string
  amount?: number // in cents
  currency?: string
  planName?: string
  creditAmount?: number
  additionalInfo?: string
}

/**
 * Get owner's user ID from email (checks both User and AdminUser tables)
 */
async function getOwnerUserId(): Promise<string | null> {
  const ownerEmail = process.env.OWNER_EMAIL
  if (!ownerEmail) {
    console.log('📱 Owner email not configured (set OWNER_EMAIL environment variable)')
    return null
  }

  try {
    // First check AdminUser table (for admin panel users)
    const adminUser = await prisma.adminUser.findUnique({
      where: { email: ownerEmail.toLowerCase() },
      select: { id: true }
    })

    if (adminUser) {
      // For admin users, we need to find their corresponding User account
      // or create a mapping. For now, let's check if there's a User with same email
      const regularUser = await prisma.user.findUnique({
        where: { email: ownerEmail.toLowerCase() },
        select: { id: true }
      })
      return regularUser?.id || null
    }

    // Fallback to regular User table
    const owner = await prisma.user.findUnique({
      where: { email: ownerEmail.toLowerCase() },
      select: { id: true }
    })
    return owner?.id || null
  } catch (error) {
    console.error('❌ Failed to find owner user:', error)
    return null
  }
}

/**
 * Get owner's push subscription from database
 */
async function getOwnerSubscription(): Promise<{ userId: string; subscription: any } | null> {
  const ownerUserId = await getOwnerUserId()
  if (!ownerUserId) {
    return null
  }

  try {
    // Ensure table exists
    // await prisma.$executeRawUnsafe(`
    //   CREATE TABLE IF NOT EXISTS PushSubscriptions (
    //     userId TEXT PRIMARY KEY,
    //     subscription JSONB NOT NULL
    //   )
    // `)

    const rows: Array<{ subscription: any }> = await prisma.$queryRawUnsafe(
      `SELECT subscription FROM PushSubscriptions WHERE userId = $1`,
      ownerUserId
    )

    if (!rows.length) {
      console.log('📱 Owner has not subscribed to push notifications yet')
      return null
    }

    return { userId: ownerUserId, subscription: rows[0].subscription }
  } catch (error) {
    console.error('❌ Failed to get owner subscription:', error)
    return null
  }
}

/**
 * Format amount in cents to currency string
 */
function formatAmount(cents: number, currency: string = 'USD'): string {
  const amount = cents / 100
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: currency,
  }).format(amount)
}

/**
 * Generate notification payload based on event type
 */
function generateNotificationPayload(options: NotificationOptions): { title: string; body: string; url: string } {
  const { event, userEmail, userName, amount, currency, planName, creditAmount } = options
  const displayName = userName || userEmail.split('@')[0]

  switch (event) {
    case 'signup': {
      return {
        title: '🎉 New User Signup',
        body: `${displayName} just signed up!`,
        url: '/admin-panel'
      }
    }

    case 'subscription': {
      const amountStr = amount ? formatAmount(amount, currency) : 'N/A'
      const planStr = planName || 'Premium'
      return {
        title: '💰 New Subscription',
        body: `${displayName} purchased ${planStr} (${amountStr})`,
        url: '/admin-panel'
      }
    }

    case 'credit_purchase': {
      const amountStr = amount ? formatAmount(amount, currency) : 'N/A'
      const creditsStr = creditAmount ? `${creditAmount} credits` : 'credits'
      return {
        title: '💳 Credit Purchase',
        body: `${displayName} bought ${creditsStr} (${amountStr})`,
        url: '/admin-panel'
      }
    }
  }
}

/**
 * Send push notification to owner
 * This function is non-blocking and won't throw errors
 */
export async function notifyOwner(options: NotificationOptions): Promise<void> {
  try {
    // 1) Attempt to deliver via Upstash QStash (same infra used for reminders)
    //    This gives us retries and decouples from the request that triggered the event.
    const qstashToken = process.env.QSTASH_TOKEN || ''
    const schedulerSecret = process.env.SCHEDULER_SECRET || ''
    let base =
      process.env.PUBLIC_BASE_URL ||
      (process.env.VERCEL_URL ? `https://${process.env.VERCEL_URL}` : '') ||
      process.env.NEXT_PUBLIC_APP_URL ||
      ''
    if (base) {
      base = base.trim()
      if (base && !/^https?:\/\//i.test(base)) {
        base = `https://${base}`
      }
      base = base.replace(/\/+$/, '')
    }
    if (qstashToken && base) {
      try {
        const callbackUrl = `${base}/api/push/owner`
        const headers: Record<string, string> = {
          Authorization: `Bearer ${qstashToken}`,
          'Content-Type': 'application/json',
        }
        if (schedulerSecret) {
          headers['Upstash-Forward-Authorization'] = `Bearer ${schedulerSecret}`
        }
        const res = await fetch(`https://qstash.upstash.io/v2/publish/${callbackUrl}`, {
          method: 'POST',
          headers,
          body: JSON.stringify(options),
        })
        // If QStash accepted the message, we can return early and let it handle retries/delivery
        if (res.ok) {
          // Log enqueue
          try {
            // await prisma.$executeRawUnsafe(`
            //   CREATE TABLE IF NOT EXISTS OwnerPushLog (
            //     createdAt TIMESTAMP NOT NULL DEFAULT NOW(),
            //     event TEXT,
            //     userEmail TEXT,
            //     status TEXT,
            //     info TEXT
            //   )
            // `)
            await prisma.$executeRawUnsafe(
              `INSERT INTO OwnerPushLog (event, userEmail, status, info) VALUES ($1, $2, $3, $4)`,
              options.event,
              options.userEmail,
              'enqueued_qstash',
              null
            )
          } catch {}
          console.log(`📢 [OWNER NOTIFICATION] Enqueued via QStash: ${options.event}`)
          return
        } else {
          const text = await res.text().catch(() => '')
          console.warn('[OWNER NOTIFICATION] QStash publish failed, falling back to direct push:', res.status, text.slice(0, 200))
        }
      } catch (e) {
        console.warn('[OWNER NOTIFICATION] QStash publish error, falling back to direct push')
      }
    }

    // 2) Fallback: direct web-push delivery (same as reminders use under the hood)
    const publicKey = process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY || ''
    const privateKey = process.env.VAPID_PRIVATE_KEY || ''

    if (!publicKey || !privateKey) {
      console.log('📱 VAPID keys not configured - push notifications disabled')
      return
    }

    const subscriptionInfo = await getOwnerSubscription()
    if (!subscriptionInfo) {
      // Silently fail - owner hasn't subscribed yet
      return
    }
    const subscriptions = dedupeSubscriptions(normalizeSubscriptionList(subscriptionInfo.subscription))
    if (!subscriptions.length) {
      return
    }

    webpush.setVapidDetails('mailto:support@helfi.ai', publicKey, privateKey)

    const payload = generateNotificationPayload(options)
    const payloadJson = JSON.stringify(payload)

    // Send notification (don't await to avoid blocking)
    sendToSubscriptions(subscriptions, (sub) => webpush.sendNotification(sub, payloadJson)).then(async (result) => {
      if (result.goneEndpoints.length) {
        const remaining = removeSubscriptionsByEndpoint(subscriptions, result.goneEndpoints)
        await prisma.$executeRawUnsafe(
          `UPDATE PushSubscriptions SET subscription = $2::jsonb, updatedAt = NOW() WHERE userId = $1`,
          subscriptionInfo.userId,
          JSON.stringify(remaining)
        ).catch(() => {})
      }
      if (!result.sent) {
        throw new Error('owner_push_failed')
      }
      try {
        // await prisma.$executeRawUnsafe(`
        //   CREATE TABLE IF NOT EXISTS OwnerPushLog (
        //     createdAt TIMESTAMP NOT NULL DEFAULT NOW(),
        //     event TEXT,
        //     userEmail TEXT,
        //     status TEXT,
        //     info TEXT
        //   )
        // `)
        await prisma.$executeRawUnsafe(
          `INSERT INTO OwnerPushLog (event, userEmail, status, info) VALUES ($1, $2, $3, $4)`,
          options.event,
          options.userEmail,
          'sent_direct',
          null
        )
      } catch {}
    }).catch((error: any) => {
      console.error('❌ [OWNER PUSH] Failed to send:', error?.body || error?.message || error)
      try {
        prisma.$executeRawUnsafe(
          `INSERT INTO OwnerPushLog (event, userEmail, status, info) VALUES ($1, $2, $3, $4)`,
          options.event,
          options.userEmail,
          'error_direct',
          String(error?.body || error?.message || error).slice(0, 500)
        ).catch(() => {})
      } catch {}
      // If subscription is invalid, we could optionally remove it here
      // But for now, just log the error
    })

    console.log(`📢 [OWNER NOTIFICATION] Queued ${options.event} push notification`)
  } catch (error) {
    // Never throw - notifications are non-critical
    console.error('❌ [OWNER NOTIFICATION] Failed to queue notification:', error)
  }
}

/**
 * PDF processing utilities for lab reports
 * Handles password-protected PDFs, text extraction, and lab value parsing
 * Uses pdfjs-dist with server-side configuration
 */

// For server-side, we need to use a different approach
// pdfjs-dist has issues with DOMMatrix in Node.js, so we'll use pdf-parse as fallback
// or configure pdfjs-dist to work without DOM APIs

let pdfjsLib: any;
let getDocument: any;
let PDFDocumentProxy: any;

// Dynamic import to handle server-side vs client-side
if (typeof window === 'undefined') {
  try {
    const canvas = require('@napi-rs/canvas');

    if (!globalThis.DOMMatrix && canvas.DOMMatrix) {
      globalThis.DOMMatrix = canvas.DOMMatrix;
    }

    if (!globalThis.ImageData && canvas.ImageData) {
      globalThis.ImageData = canvas.ImageData;
    }

    if (!globalThis.Path2D && canvas.Path2D) {
      globalThis.Path2D = canvas.Path2D;
    }
  } catch (error) {
    console.warn('[pdf-processor] Failed to load @napi-rs/canvas polyfills:', error);
  }

  // Server-side: Use pdfjs-dist without worker (synchronous mode)
  // This avoids DOMMatrix issues
  const pdfjs = require('pdfjs-dist/legacy/build/pdf.mjs');
  const pdfjsWorker = require('pdfjs-dist/legacy/build/pdf.worker.mjs');
  pdfjsLib = pdfjs;
  getDocument = pdfjs.getDocument;

  // Wire up the worker explicitly so Node can use the bundled main-thread fallback.
  (globalThis as any).pdfjsWorker ||= pdfjsWorker;
} else {
  // Client-side: Use standard pdfjs-dist
  pdfjsLib = require('pdfjs-dist');
  getDocument = pdfjsLib.getDocument;
  pdfjsLib.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;
}

// Type definitions
export interface LabValue {
  analyteName: string;
  value: string;
  unit?: string;
  referenceRange?: string;
  collectionDate?: string;
  accessionNumber?: string;
  laboratoryName?: string;
}

export interface PDFProcessingResult {
  text: string;
  labValues: LabValue[];
  pageCount: number;
}

export type PDFDocumentProxyType = any;

/**
 * Load and decrypt password-protected PDF
 */
export async function loadPDF(
  pdfBuffer: Buffer,
  password?: string
): Promise<PDFDocumentProxyType> {
  const loadingTask = getDocument({
    data: new Uint8Array(pdfBuffer),
    password: password,
    useWorkerFetch: false, // Disable worker fetch for server-side
    isEvalSupported: false, // Disable eval for security
    verbosity: 0, // Reduce logging
  });

  try {
    const pdf = await loadingTask.promise;
    return pdf;
  } catch (error: any) {
    if (error.name === 'PasswordException') {
      throw new Error('PDF password incorrect or required');
    }
    throw new Error(`Failed to load PDF: ${error.message}`);
  }
}

/**
 * Extract text from PDF
 */
export async function extractTextFromPDF(pdf: PDFDocumentProxyType): Promise<string> {
  let fullText = '';
  const numPages = pdf.numPages;

  for (let pageNum = 1; pageNum <= numPages; pageNum++) {
    const page = await pdf.getPage(pageNum);
    const textContent = await page.getTextContent();

    // Combine text items with proper spacing
    const pageText = textContent.items
      .map((item: any) => item.str)
      .join(' ');

    fullText += pageText + '\n\n';
  }

  return fullText.trim();
}

/**
 * Parse lab values from extracted text
 * Uses pattern matching to identify common lab test formats
 */
export function parseLabValues(text: string): LabValue[] {
  const labValues: LabValue[] = [];

  // Common patterns for lab results
  // Format: Test Name | Value | Unit | Reference Range
  // Example: "Glucose | 95 | mg/dL | 70-100"

  const lines = text.split('\n');
  let currentLabName = '';
  let currentLabDate: string | undefined;
  let currentAccession: string | undefined;
  let currentLabName_full: string | undefined;

  // Try to extract lab name and date from header
  for (const line of lines.slice(0, 20)) {
    // Look for date patterns
    const dateMatch = line.match(/(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4})/);
    if (dateMatch && !currentLabDate) {
      currentLabDate = dateMatch[1];
    }

    // Look for accession numbers
    const accessionMatch = line.match(/accession[:\s]+([A-Z0-9\-]+)/i);
    if (accessionMatch && !currentAccession) {
      currentAccession = accessionMatch[1];
    }

    // Look for lab name
    const labNameMatch = line.match(/([A-Z][A-Z\s&]+(?:LABORATORY|LAB|DIAGNOSTICS|MEDICAL))/i);
    if (labNameMatch && !currentLabName_full) {
      currentLabName_full = labNameMatch[1].trim();
    }
  }

  // Parse test results
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;

    // Pattern 1: Test Name | Value | Unit | Range
    const pipePattern = /^([A-Z][A-Za-z\s]+?)\s*\|\s*([\d.]+)\s*\|\s*([A-Za-z\/%]+)\s*\|\s*([\d.\-\s<>]+)$/;
    const pipeMatch = line.match(pipePattern);

    if (pipeMatch) {
      labValues.push({
        analyteName: pipeMatch[1].trim(),
        value: pipeMatch[2].trim(),
        unit: pipeMatch[3].trim(),
        referenceRange: pipeMatch[4].trim(),
        collectionDate: currentLabDate,
        accessionNumber: currentAccession,
        laboratoryName: currentLabName_full,
      });
      continue;
    }

    // Pattern 2: Test Name: Value Unit (Range)
    const colonPattern = /^([A-Z][A-Za-z\s]+?):\s*([\d.]+)\s*([A-Za-z\/%]+)\s*\(([\d.\-\s<>]+)\)$/;
    const colonMatch = line.match(colonPattern);

    if (colonMatch) {
      labValues.push({
        analyteName: colonMatch[1].trim(),
        value: colonMatch[2].trim(),
        unit: colonMatch[3].trim(),
        referenceRange: colonMatch[4].trim(),
        collectionDate: currentLabDate,
        accessionNumber: currentAccession,
        laboratoryName: currentLabName_full,
      });
      continue;
    }

    // Pattern 3: Test Name Value Unit Range (tab or multiple spaces)
    const tabPattern = /^([A-Z][A-Za-z\s]+?)\s{2,}([\d.]+)\s+([A-Za-z\/%]+)\s+([\d.\-\s<>]+)$/;
    const tabMatch = line.match(tabPattern);

    if (tabMatch) {
      labValues.push({
        analyteName: tabMatch[1].trim(),
        value: tabMatch[2].trim(),
        unit: tabMatch[3].trim(),
        referenceRange: tabMatch[4].trim(),
        collectionDate: currentLabDate,
        accessionNumber: currentAccession,
        laboratoryName: currentLabName_full,
      });
      continue;
    }

    // Pattern 4: Common test names followed by value
    const commonTests = [
      'Glucose', 'Cholesterol', 'HDL', 'LDL', 'Triglycerides',
      'Hemoglobin', 'Hematocrit', 'WBC', 'RBC', 'Platelets',
      'Sodium', 'Potassium', 'Creatinine', 'BUN', 'ALT', 'AST',
      'TSH', 'T4', 'T3', 'Vitamin D', 'B12', 'Folate',
    ];

    for (const testName of commonTests) {
      const testPattern = new RegExp(`^${testName}[:\s]+([\d.]+)\\s*([A-Za-z\/%]+)?`, 'i');
      const testMatch = line.match(testPattern);

      if (testMatch) {
        labValues.push({
          analyteName: testName,
          value: testMatch[1].trim(),
          unit: testMatch[2]?.trim(),
          collectionDate: currentLabDate,
          accessionNumber: currentAccession,
          laboratoryName: currentLabName_full,
        });
        break;
      }
    }
  }

  // If no structured data found, try to extract any number-value pairs
  if (labValues.length === 0) {
    // Fallback: look for any pattern that might be a lab value
    const fallbackPattern = /([A-Z][A-Za-z\s]{2,30}?)[:\s]+([\d.]+)\s*([A-Za-z\/%]+)?/g;
    let match;

    while ((match = fallbackPattern.exec(text)) !== null) {
      const testName = match[1].trim();
      // Skip if it looks like a date or other non-test value
      if (testName.length > 3 && testName.length < 50 && !testName.match(/^\d/)) {
        labValues.push({
          analyteName: testName,
          value: match[2].trim(),
          unit: match[3]?.trim(),
          collectionDate: currentLabDate,
          accessionNumber: currentAccession,
          laboratoryName: currentLabName_full,
        });
      }
    }
  }

  return labValues;
}

/**
 * Process PDF: decrypt, extract text, and parse lab values
 */
export async function processPDF(
  pdfBuffer: Buffer,
  password?: string
): Promise<PDFProcessingResult> {
  // Load PDF (with password if provided)
  const pdf = await loadPDF(pdfBuffer, password);
  const pageCount = pdf.numPages;

  // Extract text
  const text = await extractTextFromPDF(pdf);

  // Parse lab values
  const labValues = parseLabValues(text);

  return {
    text,
    labValues,
    pageCount,
  };
}

import { prisma } from '@/lib/prisma'
import { PRACTITIONER_CATEGORIES, PractitionerCategorySeed } from '@/data/practitioner-categories'

function normalizeSlug(value: string): string {
  return value
    .toLowerCase()
    .replace(/&/g, 'and')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '')
}

function buildCategorySlug(parentSlug: string | null, seedSlug: string): string {
  const base = normalizeSlug(seedSlug)
  return parentSlug ? `${parentSlug}-${base}` : base
}

async function createCategoryTree(parent: { id: string; slug: string } | null, seed: PractitionerCategorySeed, sortOrder: number) {
  const slug = buildCategorySlug(parent?.slug || null, seed.slug)
  const created = await prisma.practitionerCategory.create({
    data: {
      name: seed.name,
      slug,
      parentId: parent?.id || null,
      synonyms: seed.synonyms || [],
      sortOrder,
    },
  })

  if (seed.children?.length) {
    let childOrder = 0
    for (const child of seed.children) {
      await createCategoryTree(created, child, childOrder++)
    }
  }

  return created
}

export async function ensurePractitionerCategories() {
  const existing = await prisma.practitionerCategory.count()
  if (existing > 0) return

  let order = 0
  for (const category of PRACTITIONER_CATEGORIES) {
    await createCategoryTree(null, category, order++)
  }
}

export async function getPractitionerCategories() {
  await ensurePractitionerCategories()

  return prisma.practitionerCategory.findMany({
    orderBy: [{ sortOrder: 'asc' }, { name: 'asc' }],
  })
}

