  const actionLabels: Record<string, string> = {
    profile_view: 'Profile viewed',
    call: 'Call clicked',
    website: 'Website clicked',
    email: 'Email clicked',
  }

  const counts = options.events.reduce<Record<string, number>>((acc, event) => {
    acc[event.action] = (acc[event.action] || 0) + 1
    return acc
