function normalize(value: string | null | undefined): string {
  return String(value || '')
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

function compact(value: string | null | undefined): string {
  return normalize(value).replace(/\s+/g, '')
}

function matchesTerm(text: string, term: string): boolean {
  const normalizedText = normalize(text)
  const normalizedTerm = normalize(term)
  if (!normalizedText || !normalizedTerm) return false
  if (normalizedText.includes(normalizedTerm)) return true
  return compact(normalizedText).includes(compact(normalizedTerm))
}

function uniqueTargets(issueText: string): PractitionerTarget[] {
  const matched = PRACTITIONER_TARGETS.filter((target) =>
    target.terms.some((term) => matchesTerm(issueText, term))
  )
  const bestByKey = new Map<string, PractitionerTarget>()
  matched.forEach((target) => {
    const key = `${normalize(target.category)}|${normalize(target.subcategory)}`
    const current = bestByKey.get(key)
    if (!current || target.score > current.score) bestByKey.set(key, target)
  })
  return Array.from(bestByKey.values()).sort((a, b) => b.score - a.score)
}

function profileScore(listing: any): number {
  let score = 0
  const images = listing.images as any
  if (images?.logoUrl) score += 1
  if (listing.description) score += 1
  if (listing.hoursJson) score += 1
  if (listing.websiteUrl) score += 2
  if (listing.phone) score += 1
  if (listing.emailPublic) score += 1
  if (listing.addressLine1 || listing.suburbCity) score += 1
  return score
}

function contactScore(listing: any): number {
  if (listing.websiteUrl) return 3
  if (listing.phone) return 2
  if (listing.emailPublic) return 1
  return 0
}

export function extractPractitionerRecommendationText(input: {
  issueText?: string | null
  symptoms?: string[] | null
  possibleCauses?: Array<{ name?: string | null }> | null
  summary?: string | null
  notes?: string | null
}) {
  return [
    input.issueText,
    Array.isArray(input.symptoms) ? input.symptoms.join(', ') : '',
    Array.isArray(input.possibleCauses)
      ? input.possibleCauses.map((cause) => cause?.name).filter(Boolean).join(', ')
      : '',
    input.summary,
    input.notes,
  ]
    .filter(Boolean)
    .join('\n')
    .trim()
}

export async function getPractitionerRecommendations(input: PractitionerRecommendationInput) {
  const lat = Number(input.lat)
  const lng = Number(input.lng)
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
    return { results: [], radiusKm: DEFAULT_RADIUS_KM, matchedIssues: [] }
  }

  const issueText = String(input.issueText || '').trim()
  const targets = uniqueTargets(issueText)
  if (!targets.length) {
    return { results: [], radiusKm: DEFAULT_RADIUS_KM, matchedIssues: [] }
  }

  const requestedRadius = Number.isFinite(Number(input.radiusKm)) ? Number(input.radiusKm) : DEFAULT_RADIUS_KM
  const defaultRadius = Math.max(1, Math.min(DEFAULT_RADIUS_KM, requestedRadius))
  const maxRadius = Math.max(defaultRadius, Math.min(MAX_RADIUS_KM, Number(input.maxRadiusKm) || MAX_RADIUS_KM))
  const limit = Math.max(1, Math.min(6, Number(input.limit) || DEFAULT_LIMIT))
  const country = normalize(input.country)

  const listings = await prisma.practitionerListing.findMany({
    where: {
      status: 'ACTIVE',
      reviewStatus: 'APPROVED',
      visibilityReason: { in: ['TRIAL_ACTIVE', 'SUB_ACTIVE'] },
      lat: { not: null },
      lng: { not: null },
    },
    include: {
      category: true,
      subcategory: true,
    },
  })

  const scored = listings
    .map((listing) => {
      if (country && normalize(listing.country) && normalize(listing.country) !== country) return null
      const categoryName = normalize(listing.category?.name)
      const subcategoryName = normalize(listing.subcategory?.name)

      const target = targets.find((candidate) => {
        const targetCategory = normalize(candidate.category)
        const targetSubcategory = normalize(candidate.subcategory)
        if (targetSubcategory) {
          return targetSubcategory === subcategoryName || targetSubcategory === categoryName
        }
        return targetCategory === categoryName
      })
      if (!target) return null

      const distanceKm = calculateDistanceKm({ lat, lng }, { lat: listing.lat as number, lng: listing.lng as number })
      if (!Number.isFinite(distanceKm) || distanceKm > maxRadius) return null

      const exactSubcategory = normalize(target.subcategory) === subcategoryName
      const matchScore = target.score + (exactSubcategory ? 20 : 0)
      return {
        listing,
        target,
        distanceKm,
        matchScore,
        profileScore: profileScore(listing),
        contactScore: contactScore(listing),
      }
    })
    .filter(Boolean) as Array<{
      listing: any
      target: PractitionerTarget
      distanceKm: number
      matchScore: number
      profileScore: number
      contactScore: number
    }>

  const order = (items: typeof scored) =>
    items.sort((a, b) => {
      if (b.matchScore !== a.matchScore) return b.matchScore - a.matchScore
      if (a.distanceKm !== b.distanceKm) return a.distanceKm - b.distanceKm
      if (b.profileScore !== a.profileScore) return b.profileScore - a.profileScore
      if (b.contactScore !== a.contactScore) return b.contactScore - a.contactScore
      return String(a.listing.displayName || '').localeCompare(String(b.listing.displayName || ''))
    })

  const withinDefault = order(scored.filter((item) => item.distanceKm <= defaultRadius))
  const selected = withinDefault.length >= limit ? withinDefault.slice(0, limit) : order(scored).slice(0, limit)
  const usedRadius = selected.some((item) => item.distanceKm > defaultRadius) ? maxRadius : defaultRadius

  const results = selected.map((item) => ({
    id: item.listing.id,
    displayName: item.listing.displayName,
    slug: item.listing.slug,
    categoryName: item.listing.category?.name || null,
    subcategoryName: item.listing.subcategory?.name || null,
    description: item.listing.description || null,
    phone: item.listing.phone || null,
    websiteUrl: item.listing.websiteUrl || null,
    emailPublic: item.listing.emailPublic || null,
    addressLine1: item.listing.addressLine1 || null,
    suburbCity: item.listing.suburbCity || null,
    stateRegion: item.listing.stateRegion || null,
    country: item.listing.country || null,
    lat: item.listing.lat,
    lng: item.listing.lng,
    serviceType: item.listing.serviceType,
    distanceKm: Math.round(item.distanceKm * 10) / 10,
    reason: item.target.reasonLabel,
    matchedIssue: item.target.issueLabel,
    trackingToken: createTrackingToken(item.listing.id),
  }))

  return {
    results,
    radiusKm: usedRadius,
    matchedIssues: Array.from(new Set(selected.map((item) => item.target.issueLabel))),
    sourceArea: input.sourceArea || null,
  }
}

type RegistrationRule = {
  label: string
  helper: string
  digitCounts?: number[]
  minDigits?: number
  maxDigits?: number
}

const COUNTRY_RULES: Array<{ match: string[]; rule: RegistrationRule }> = [
  {
    match: ['australia', 'au'],
    rule: { label: 'ABN', helper: '11 digits', digitCounts: [11] },
  },
  {
    match: ['united states', 'united states of america', 'usa', 'us'],
    rule: { label: 'EIN', helper: '9 digits', digitCounts: [9] },
  },
  {
    match: ['united kingdom', 'uk', 'great britain', 'england', 'scotland', 'wales', 'northern ireland'],
    rule: { label: 'Company number', helper: '8 digits', digitCounts: [8] },
  },
  {
    match: ['new zealand', 'nz'],
    rule: { label: 'NZBN', helper: '13 digits', digitCounts: [13] },
  },
  {
    match: ['canada', 'ca'],
    rule: { label: 'Business number (BN)', helper: '9 digits', digitCounts: [9] },
  },
]

const DEFAULT_RULE: RegistrationRule = {
  label: 'Business registration number',
  helper: '6-20 digits',
  minDigits: 6,
  maxDigits: 20,
}

function normalizeCountry(input: string | null | undefined): string {
  return String(input || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ')
}

function formatDigitRequirement(rule: RegistrationRule): string {
  if (rule.digitCounts && rule.digitCounts.length > 0) {
    if (rule.digitCounts.length === 1) return `${rule.digitCounts[0]} digits`
    const counts = [...rule.digitCounts].sort((a, b) => a - b)
    const last = counts.pop()
    return `${counts.join(', ')} or ${last} digits`
  }
  if (rule.minDigits && rule.maxDigits) {
    return `${rule.minDigits}-${rule.maxDigits} digits`
  }
  return 'valid digits'
}

export function getBusinessRegistrationRule(country: string | null | undefined): RegistrationRule {
  const normalized = normalizeCountry(country)
  if (!normalized) return DEFAULT_RULE

  for (const entry of COUNTRY_RULES) {
    if (entry.match.some((match) => normalized === match || normalized.includes(match))) {
      return entry.rule
    }
  }

  return DEFAULT_RULE
}

export function validateBusinessRegistrationNumber(
  value: string | null | undefined,
  country: string | null | undefined
): {
  valid: boolean
  error?: string
  digits?: string
  rule: RegistrationRule
} {
  const rule = getBusinessRegistrationRule(country)
  const trimmed = String(value || '').trim()
  if (!trimmed) {
    return {
      valid: false,
      error: 'Business registration number is required.',
      rule,
    }
  }

  const digits = trimmed.replace(/\D/g, '')
  if (!digits) {
    return {
      valid: false,
      error: `${rule.label} must include digits.`,
      rule,
    }
  }
  if (/[A-Za-z]/.test(trimmed)) {
    return {
      valid: false,
      error: `${rule.label} must use digits only.`,
      rule,
    }
  }

  if (rule.digitCounts && !rule.digitCounts.includes(digits.length)) {
    return {
      valid: false,
      error: `${rule.label} must be ${formatDigitRequirement(rule)}.`,
      rule,
    }
  }

  if (rule.minDigits && rule.maxDigits) {
    if (digits.length < rule.minDigits || digits.length > rule.maxDigits) {
      return {
        valid: false,
        error: `${rule.label} must be ${formatDigitRequirement(rule)}.`,
        rule,
      }
    }
  }

  return { valid: true, digits, rule }
}

export type PractitionerPlaceMatchStatus = 'MATCH' | 'MISMATCH' | 'NOT_FOUND' | 'UNKNOWN'

export type PractitionerPlaceMatch = {
  status: PractitionerPlaceMatchStatus
  reason: string
  placeName?: string | null
  placeTypes?: string[]
  businessStatus?: string | null
  raw?: any
}

const GENERIC_PLACE_TYPES = new Set([
  'point_of_interest',
  'establishment',
  'premise',
  'subpremise',
  'route',
  'street_address',
  'intersection',
  'locality',
  'sublocality',
  'political',
  'postal_code',
  'postal_town',
  'country',
  'administrative_area_level_1',
  'administrative_area_level_2',
  'administrative_area_level_3',
  'administrative_area_level_4',
  'administrative_area_level_5',
])

const STOPWORDS = new Set(['and', 'the', 'of', 'or', 'for', 'with', 'a', 'an', 'in'])

const TEST_PATTERNS: Array<{ pattern: RegExp; label: string }> = [
  { pattern: /\btest\b/i, label: 'Contains "test"' },
  { pattern: /\bdummy\b/i, label: 'Contains "dummy"' },
  { pattern: /\bplaceholder\b/i, label: 'Contains "placeholder"' },
  { pattern: /\blorem\b/i, label: 'Contains "lorem"' },
  { pattern: /\bipsum\b/i, label: 'Contains "ipsum"' },
  { pattern: /\bfake\b/i, label: 'Contains "fake"' },
  { pattern: /\bnot\s+real\b/i, label: 'Contains "not real"' },
  { pattern: /\bdo\s+not\s+use\b/i, label: 'Contains "do not use"' },
  { pattern: /\bdelete\s+me\b/i, label: 'Contains "delete me"' },
  { pattern: /\bsample\b/i, label: 'Contains "sample"' },
  { pattern: /\bexample\b/i, label: 'Contains "example"' },
  { pattern: /example\.com/i, label: 'Uses example.com' },
  { pattern: /\btest\.com\b/i, label: 'Uses test.com' },
]

function getMapsApiKey(): string | null {
  return (
    process.env.GOOGLE_MAPS_API_KEY ||
    process.env.GOOGLE_MAPS_SERVER_KEY ||
    process.env.MAPS_API_KEY ||
    null
  )
}

function normalizeText(input: string): string {
  return input
    .toLowerCase()
    .replace(/&/g, 'and')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
}

function buildKeywordSet(inputs: Array<string | null | undefined>): Set<string> {
  const keywords = new Set<string>()
  inputs
    .filter(Boolean)
    .map((value) => normalizeText(String(value)))
    .filter(Boolean)
    .forEach((value) => {
      keywords.add(value)
      value.split(' ').forEach((token) => {
        if (!token || token.length < 2 || STOPWORDS.has(token)) return
        keywords.add(token)
      })
    })
  return keywords
}

function buildPlaceText(placeName: string | null | undefined, placeTypes: string[]): string {
  const typeText = placeTypes.map((type) => type.replace(/_/g, ' ')).join(' ')
  return normalizeText([placeName || '', typeText].join(' '))
}

export function detectTestSignals(input: {
  displayName?: string | null
  description?: string | null
  websiteUrl?: string | null
  emailPublic?: string | null
  phone?: string | null
  tags?: string[] | null
  address?: string | null
}): string[] {
  const combined = [
    input.displayName,
    input.description,
    input.websiteUrl,
    input.emailPublic,
    input.phone,
    input.address,
    ...(input.tags || []),
  ]
    .filter(Boolean)
    .join(' ')

  if (!combined.trim()) return []
  return TEST_PATTERNS.filter(({ pattern }) => pattern.test(combined)).map(({ label }) => label)
}

export async function lookupPlaceMatch(input: {
  displayName: string
  address: string
  categoryName?: string | null
  subcategoryName?: string | null
  categorySynonyms?: string[]
  subcategorySynonyms?: string[]
}): Promise<PractitionerPlaceMatch> {
  const apiKey = getMapsApiKey()
  if (!apiKey) {
    return { status: 'UNKNOWN', reason: 'Google Places API is not configured.' }
  }

  const query = [input.displayName, input.address].filter(Boolean).join(' ').trim()
  if (!query) {
    return { status: 'UNKNOWN', reason: 'Missing listing name or address.' }
  }

  const url = new URL('https://maps.googleapis.com/maps/api/place/textsearch/json')
  url.searchParams.set('query', query)
  url.searchParams.set('key', apiKey)

  const res = await fetch(url.toString())
  if (!res.ok) {
    return { status: 'UNKNOWN', reason: `Google Places lookup failed (${res.status}).` }
  }

  const data = await res.json().catch(() => ({}))
  const result = Array.isArray(data?.results) ? data.results[0] : null
  if (!result) {
    return { status: 'NOT_FOUND', reason: 'No Google Places result found.' }
  }

  const placeName = result?.name ? String(result.name) : null
  const placeTypes: string[] = Array.isArray(result?.types)
    ? result.types.map((type: any) => String(type).toLowerCase())
    : []
  const businessStatus = result?.business_status ? String(result.business_status) : null
  const placeText = buildPlaceText(placeName, placeTypes)

  const keywords = buildKeywordSet([
    input.categoryName,
    input.subcategoryName,
    ...(input.categorySynonyms || []),
    ...(input.subcategorySynonyms || []),
  ])

  const matchesCategory = Array.from(keywords).some((keyword) => placeText.includes(keyword))
  if (matchesCategory) {
    return {
      status: 'MATCH',
      reason: 'Google business types match the selected category.',
      placeName,
      placeTypes,
      businessStatus,
      raw: result,
    }
  }

  const nonGenericTypes = placeTypes.filter((type) => !GENERIC_PLACE_TYPES.has(type))
  if (nonGenericTypes.length === 0) {
    return {
      status: 'UNKNOWN',
      reason: 'Google returned only generic place types.',
      placeName,
      placeTypes,
      businessStatus,
      raw: result,
    }
  }

  return {
    status: 'MISMATCH',
    reason: `Google business types do not match the selected category: ${nonGenericTypes.join(', ')}`,
    placeName,
    placeTypes,
    businessStatus,
    raw: result,
  }
}

import OpenAI from 'openai'
import { runChatCompletionWithLogging } from '@/lib/ai-usage-logger'

export type PractitionerScreeningInput = {
  listingId: string
  displayName: string
  description?: string | null
  websiteUrl?: string | null
  phone?: string | null
  emailPublic?: string | null
  address?: string | null
  category?: string | null
  subcategory?: string | null
  tags?: string[]
  languages?: string[]
  hasCoordinates?: boolean
  hasFullAddress?: boolean
  hasPhone?: boolean
  hasWebsite?: boolean
  hasPublicEmail?: boolean
  placeMatch?: {
    status: 'MATCH' | 'MISMATCH' | 'NOT_FOUND' | 'UNKNOWN'
    reason?: string
    placeName?: string | null
    placeTypes?: string[]
    businessStatus?: string | null
  }
  testSignals?: string[]
}

export type PractitionerScreeningResult = {
  riskLevel: 'LOW' | 'MEDIUM' | 'HIGH'
  recommendedAction: 'AUTO_APPROVE' | 'MANUAL_REVIEW'
  reasoning: string
  redFlags?: string[]
  raw?: any
}

function getOpenAI(): OpenAI | null {
  if (!process.env.OPENAI_API_KEY) return null
  return new OpenAI({ apiKey: process.env.OPENAI_API_KEY })
}

function tryParseJsonObject(text: string): any | null {
  const start = text.indexOf('{')
  const end = text.lastIndexOf('}')
  if (start < 0 || end < 0 || end <= start) return null
  try {
    return JSON.parse(text.slice(start, end + 1))
  } catch {
    return null
  }
}

export async function screenPractitionerListing(
  input: PractitionerScreeningInput
): Promise<PractitionerScreeningResult> {
  const webhookUrl = process.env.PRACTITIONER_SCREENING_WEBHOOK_URL
  if (webhookUrl) {
    const resp = await fetch(webhookUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type: 'practitioner_listing', input }),
    })
    if (!resp.ok) {
      throw new Error(`Practitioner screening webhook failed: ${resp.status}`)
    }
    const data = await resp.json().catch(() => ({}))
    const risk = String(data?.riskLevel || data?.risk || '').toUpperCase()
    const action = String(data?.recommendedAction || data?.action || '').toUpperCase()
    if (!['LOW', 'MEDIUM', 'HIGH'].includes(risk) || !['AUTO_APPROVE', 'MANUAL_REVIEW'].includes(action)) {
      throw new Error('Practitioner screening webhook returned invalid result')
    }
    return {
      riskLevel: risk as any,
      recommendedAction: action as any,
      reasoning: String(data?.reasoning || data?.summary || 'No reasoning provided'),
      redFlags: Array.isArray(data?.redFlags) ? data.redFlags.map((x: any) => String(x)) : undefined,
      raw: data,
    }
  }

  const openai = getOpenAI()
  if (!openai) {
    return {
      riskLevel: 'MEDIUM',
      recommendedAction: 'MANUAL_REVIEW',
      reasoning: 'AI screening is not configured; defaulting to manual review.',
    }
  }

  const model = 'gpt-5.6-sol'
  const system = `You are a fraud and scam screening assistant for a practitioner directory.
Return ONLY valid JSON with keys:
- riskLevel: one of LOW|MEDIUM|HIGH
- recommendedAction: one of AUTO_APPROVE|MANUAL_REVIEW
- reasoning: short explanation in plain language
- redFlags: array of strings (optional)

IMPORTANT:
- Only flag listings when there are clear, serious concerns (fraud, impersonation, illegal claims, guaranteed cures, miracle results, financial scams).
- Normal wellness or holistic language is NOT a reason to flag a listing.
- If the listing has a real address/coordinates and a phone number, that is a strong legitimacy signal.
- If the listing includes obvious test/dummy language, choose MANUAL_REVIEW.
- If the place match status is MISMATCH or NOT_FOUND, choose MANUAL_REVIEW.
- If unsure, choose MANUAL_REVIEW.
`
  const user = {
    input,
    checks: [
      'Only extreme or illegal medical claims (guaranteed cures, miracle results, curing cancer, etc.)',
      'Missing or inconsistent contact details',
      'Likely spam or automated content',
      'Unclear or fake business identity',
      'High-risk language or scams',
      'Test or placeholder content',
      'Google Places mismatch or missing business listing',
    ],
  }

  const result = await runChatCompletionWithLogging(
    openai,
    {
      model,
      temperature: 0.1,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: JSON.stringify(user) },
      ],
    },
    { feature: 'practitioner:screening', userLabel: input.listingId, endpoint: 'practitioner_screening' }
  )

  const text = (result as any)?.choices?.[0]?.message?.content || ''
  const parsed = tryParseJsonObject(text) || {}
  const riskLevel = String(parsed?.riskLevel || '').toUpperCase()
  const recommendedAction = String(parsed?.recommendedAction || '').toUpperCase()

  if (!['LOW', 'MEDIUM', 'HIGH'].includes(riskLevel) || !['AUTO_APPROVE', 'MANUAL_REVIEW'].includes(recommendedAction)) {
    return {
      riskLevel: 'MEDIUM',
      recommendedAction: 'MANUAL_REVIEW',
      reasoning: 'AI returned an invalid response; defaulting to manual review.',
      raw: { text },
    }
  }

  return {
    riskLevel: riskLevel as any,
    recommendedAction: recommendedAction as any,
    reasoning: String(parsed?.reasoning || 'No reasoning provided'),
    redFlags: Array.isArray(parsed?.redFlags) ? parsed.redFlags.map((x: any) => String(x)) : undefined,
    raw: parsed,
  }
}

import { createHmac, timingSafeEqual } from 'crypto'

const TRACKING_TTL_MS = 7 * 24 * 60 * 60 * 1000

function getTrackingSecret(): string | null {
  const secret = (process.env.PRACTITIONER_TRACKING_SECRET || process.env.SCHEDULER_SECRET || '').trim()
  return secret || null
}

export function createTrackingToken(listingId: string): string | null {
  const secret = getTrackingSecret()
  if (!secret) return null
  const expiresAt = Date.now() + TRACKING_TTL_MS
  const payload = `${listingId}.${expiresAt}`
  const signature = createHmac('sha256', secret).update(payload).digest('hex')
  return `${payload}.${signature}`
}

export function verifyTrackingToken(listingId: string, token: string): boolean {
  const secret = getTrackingSecret()
  if (!secret || !token) return false
  const parts = token.split('.')
  if (parts.length !== 3) return false
  const [tokenListingId, expiresAtRaw, signature] = parts
  if (tokenListingId !== listingId) return false
  const expiresAt = Number(expiresAtRaw)
  if (!Number.isFinite(expiresAt) || Date.now() > expiresAt) return false
  const payload = `${tokenListingId}.${expiresAt}`
  const expected = createHmac('sha256', secret).update(payload).digest('hex')
  if (expected.length !== signature.length) return false
  return timingSafeEqual(Buffer.from(expected), Buffer.from(signature))
}

import type { PractitionerRadiusTier } from '@prisma/client'

export function slugify(input: string): string {
  return input
    .toLowerCase()
    .trim()
    .replace(/&/g, 'and')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '')
}

export function parseCommaList(input: string | string[] | null | undefined): string[] {
  if (!input) return []
  if (Array.isArray(input)) {
    return input.map((item) => String(item).trim()).filter(Boolean)
  }
  return String(input)
    .split(',')
    .map((item) => item.trim())
    .filter(Boolean)
}

export function normalizeUrl(url: string | null | undefined): string | null {
  if (!url) return null
  const trimmed = url.trim()
  if (!trimmed) return null
  if (/^https?:\/\//i.test(trimmed)) return trimmed
  return `https://${trimmed}`
}

export async function geocodeAddress(address: string): Promise<{ lat: number; lng: number } | null> {
  const apiKey =
    process.env.GOOGLE_MAPS_API_KEY ||
    process.env.GOOGLE_MAPS_SERVER_KEY ||
    process.env.MAPS_API_KEY
  if (!apiKey) return null
  const trimmed = address.trim()
  if (!trimmed) return null
  const url = new URL('https://maps.googleapis.com/maps/api/geocode/json')
  url.searchParams.set('address', trimmed)
  url.searchParams.set('key', apiKey)
  const res = await fetch(url.toString())
  if (!res.ok) return null
  const data = await res.json().catch(() => ({}))
  if (data?.status !== 'OK') return null
  const location = data?.results?.[0]?.geometry?.location
  if (!location) return null
  return { lat: Number(location.lat), lng: Number(location.lng) }
}

export function buildGeoKey(input: {
  country?: string | null
  stateRegion?: string | null
  suburbCity?: string | null
}) {
  const country = String(input.country || '').trim().toLowerCase()
  return country ? country : ''
}

export function radiusTierToKm(tier: PractitionerRadiusTier): number {
  switch (tier) {
    case 'R5':
      return 5
    case 'R10':
      return 10
    case 'R25':
      return 25
    case 'R50':
      return 50
    default:
      return 10
  }
}

export function calculateDistanceKm(a: { lat: number; lng: number }, b: { lat: number; lng: number }): number {
  const toRad = (value: number) => (value * Math.PI) / 180
  const earthRadiusKm = 6371
  const dLat = toRad(b.lat - a.lat)
  const dLng = toRad(b.lng - a.lng)
  const lat1 = toRad(a.lat)
  const lat2 = toRad(b.lat)

  const h =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.sin(dLng / 2) * Math.sin(dLng / 2) * Math.cos(lat1) * Math.cos(lat2)
  const c = 2 * Math.atan2(Math.sqrt(h), Math.sqrt(1 - h))
  return earthRadiusKm * c
}

import type { PrismaClient } from '@prisma/client'
import { createWriteGuard, hashPayload } from './write-guard'

const WRITE_GUARD_WINDOW_MS = 30 * 1000
const WRITE_ACTIONS = new Set(['create', 'createMany', 'update', 'updateMany', 'upsert', 'delete', 'deleteMany'])

export const attachWriteGuard = (prisma: PrismaClient) => {
  const guard = createWriteGuard(prisma)

  prisma.$use(async (params, next) => {
    if (!WRITE_ACTIONS.has(params.action)) return next(params)
    if (!params.model) return next(params)

    const args = params.args || {}
    const data = args.data || {}
    const where = args.where || {}

    const ownerKey =
      (data && typeof data === 'object' && (data.userId || data.id)) ||
      (where && typeof where === 'object' && (where.userId || where.id))

    if (!ownerKey) return next(params)

    const scope = `${params.model}:${params.action}:${String(ownerKey)}`
    const payloadHash = hashPayload({ data, where, action: params.action })
    if (!payloadHash) return next(params)

    const guardResult = await guard.readGuard({
      ownerKey: String(ownerKey),
      scope,
      payloadHash,
      windowMs: WRITE_GUARD_WINDOW_MS,
    })

    if (guardResult.skip) {
      const modelClient: any = (prisma as any)[params.model]
      if (modelClient && typeof modelClient.findFirst === 'function' && Object.keys(where || {}).length > 0) {
        return modelClient.findFirst({ where })
      }
      if (guardResult.lastRecordId && modelClient && typeof modelClient.findUnique === 'function') {
        return modelClient.findUnique({ where: { id: guardResult.lastRecordId } })
      }
      if (params.action.endsWith('Many')) {
        return { count: 0 }
      }
      return next(params)
    }

    const result = await next(params)

    if (params.action === 'create' || params.action === 'update' || params.action === 'upsert') {
      const recordId =
        (result && typeof result === 'object' && (result as any).id) ||
        (data && typeof data === 'object' && (data as any).id) ||
        (where && typeof where === 'object' && (where as any).id) ||
        null
      await guard.recordWrite({
        ownerKey: String(ownerKey),
        scope,
        payloadHash,
        recordId,
      })
    }

    return result
  })
}

