export async function publishWithQStash(
  callbackPath: string,
  payload: unknown
): Promise<{ ok: boolean; reason?: string; status?: number; responseBody?: string; callbackUrl?: string }> {
  const token = process.env.QSTASH_TOKEN || ''
  const schedulerSecret = process.env.SCHEDULER_SECRET || ''
  if (!token) return { ok: false, reason: 'missing_qstash_token' }

  let base =
    process.env.PUBLIC_BASE_URL ||
    (process.env.VERCEL_URL ? `https://${process.env.VERCEL_URL}` : '')
  if (base) {
    base = base.trim()
    if (base && !/^https?:\/\//i.test(base)) base = `https://${base}`
    base = base.replace(/\/+$/, '')
  }
  if (!base) return { ok: false, reason: 'missing_base_url' }

  const normalizedPath = callbackPath.startsWith('/') ? callbackPath : `/${callbackPath}`
  const callbackUrl = `${base}${normalizedPath}`
  const url = `https://qstash.upstash.io/v2/publish/${callbackUrl}`

  try {
    const headers: Record<string, string> = {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    }
    if (schedulerSecret) {
      headers['Upstash-Forward-Authorization'] = `Bearer ${schedulerSecret}`
    }
    const res = await fetch(url, {
      method: 'POST',
      headers,
      body: JSON.stringify(payload ?? {}),
    })
    const responseBody = await res.text()
    if (!res.ok) return { ok: false, status: res.status, responseBody, callbackUrl, reason: `qstash_http_${res.status}` }
    return { ok: true, status: res.status, responseBody, callbackUrl }
  } catch (error: any) {
    return { ok: false, reason: error?.message || 'fetch_error', responseBody: (error?.stack || String(error)).slice(0, 500), callbackUrl }
  }
}

/**
 * Schedule all active reminders for a user based on frequency (1-3).
 */
export async function scheduleAllActiveReminders(
  userId: string,
  settings: { time1: string; time2: string; time3: string; time4?: string | null; timezone: string; frequency: number }
) {
  const { time1, time2, time3, time4, timezone, frequency } = settings
  const reminders: string[] = []
  if (frequency >= 1) reminders.push(time1)
  if (frequency >= 2) reminders.push(time2)
  if (frequency >= 3) reminders.push(time3)
  if (frequency >= 4 && time4) reminders.push(time4)

  const tasks = reminders.map((reminderTime) =>
    scheduleReminderWithQStash(userId, reminderTime, timezone).then((result) => ({
      reminderTime,
      ...result,
    }))
  )

  try {
    return await Promise.all(tasks)
  } catch (error) {
    console.error('[QSTASH] scheduleAllActiveReminders encountered an error', error)
    return []
  }
}

