const FALLBACK_SITE_URL = 'https://helfi.ai'

function normalizeSiteUrl(value: string | undefined | null): string | null {
  if (!value) return null
  const trimmed = value.trim()
  if (!trimmed) return null

  const withProtocol = /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`

  try {
    const parsed = new URL(withProtocol)
    parsed.pathname = ''
    parsed.search = ''
    parsed.hash = ''
    return parsed.toString().replace(/\/$/, '')
  } catch {
    return null
  }
}

export function getSiteUrl(): string {
  return (
    normalizeSiteUrl(process.env.NEXT_PUBLIC_APP_URL) ||
    normalizeSiteUrl(process.env.NEXT_PUBLIC_SITE_URL) ||
    normalizeSiteUrl(process.env.NEXTAUTH_URL) ||
    FALLBACK_SITE_URL
  )
}

export function absoluteUrl(path: string): string {
  const normalizedPath = path.startsWith('/') ? path : `/${path}`
  return `${getSiteUrl()}${normalizedPath}`
}

export type SubscriptionLike = {
  plan?: string | null
  endDate?: Date | string | null
}

export function isSubscriptionActive(subscription: SubscriptionLike | null | undefined, now = new Date()): boolean {
  if (!subscription?.plan) return false
  const endDate = subscription.endDate ? new Date(subscription.endDate) : null
  if (!endDate || Number.isNaN(endDate.getTime())) return true
  return endDate.getTime() > now.getTime()
}

