function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
}

function renderTextAsHtml(message: string): string {
  return message
    .split('\n')
    .map((line) => {
      if (!line.trim()) {
        return '<div style="height: 10px;"></div>'
      }
      return `<p style="margin: 18px 0; line-height: 1.7; font-size: 16px;">${escapeHtml(line)}</p>`
    })
    .join('')
}

