import { PrismaClient } from '@prisma/client'
import { createHash, randomUUID } from 'crypto'

export type WriteGuardResult = {
  skip: boolean
  hitCount: number
  lastRecordId?: string | null
}

type WriteGuardInput = {
  ownerKey: string
  scope: string
  payloadHash: string
  windowMs: number
}

const sortValue = (value: any): any => {
  if (Array.isArray(value)) {
    return value.map(sortValue)
  }
  if (value && typeof value === 'object') {
    return Object.keys(value)
      .sort()
      .reduce((acc: Record<string, any>, key) => {
        acc[key] = sortValue(value[key])
        return acc
      }, {})
  }
  return value
}

export const hashPayload = (value: any) => {
  try {
    const stable = sortValue(value)
    const json = JSON.stringify(stable) || ''
    return createHash('sha256').update(json).digest('hex')
  } catch {
    return ''
  }
}

export const createWriteGuard = (prisma: PrismaClient) => {
  let writeGuardReady = false

  const ensureWriteGuardTable = async () => {
    if (writeGuardReady) return
    try {
      await prisma.$executeRawUnsafe(`
        CREATE TABLE IF NOT EXISTS WriteGuard (
          id TEXT PRIMARY KEY,
          userId TEXT NOT NULL,
          scope TEXT NOT NULL,
          payloadHash TEXT NOT NULL,
          lastSeenAt TIMESTAMPTZ NOT NULL DEFAULT NOW(),
          hitCount INTEGER NOT NULL DEFAULT 1,
          lastRecordId TEXT
        )
      `)
      await prisma.$executeRawUnsafe(
        'ALTER TABLE WriteGuard ADD COLUMN IF NOT EXISTS lastRecordId TEXT'
      ).catch(() => {})
      await prisma.$executeRawUnsafe(
        'CREATE UNIQUE INDEX IF NOT EXISTS writeguard_user_scope_uq ON WriteGuard (userId, scope)'
      ).catch(() => {})
      await prisma.$executeRawUnsafe(
        'CREATE INDEX IF NOT EXISTS writeguard_lastseen_idx ON WriteGuard (lastSeenAt DESC)'
      ).catch(() => {})
      writeGuardReady = true
    } catch (error) {
      console.warn('[write-guard] Failed to ensure table', error)
    }
  }

  const readGuard = async ({
    ownerKey,
    scope,
    payloadHash,
    windowMs,
  }: WriteGuardInput): Promise<WriteGuardResult> => {
    if (!ownerKey || !scope || !payloadHash) return { skip: false, hitCount: 0 }
    await ensureWriteGuardTable()
    try {
      const rows: any[] = await prisma.$queryRawUnsafe(
        'SELECT id, payloadHash, lastSeenAt, hitCount, lastRecordId FROM WriteGuard WHERE userId = $1 AND scope = $2',
        ownerKey,
        scope
      )
      const existing = rows?.[0]
      const now = Date.now()
      if (existing && existing.payloadHash === payloadHash) {
        const lastSeenAt = existing.lastSeenAt ? new Date(existing.lastSeenAt).getTime() : 0
        if (lastSeenAt && now - lastSeenAt < windowMs) {
          await prisma.$queryRawUnsafe(
            'UPDATE WriteGuard SET lastSeenAt = NOW(), hitCount = hitCount + 1 WHERE id = $1',
            existing.id
          )
          return {
            skip: true,
            hitCount: Number(existing.hitCount || 0) + 1,
            lastRecordId: existing.lastRecordId || null,
          }
        }
      }

      if (existing?.id) {
        await prisma.$queryRawUnsafe(
          'UPDATE WriteGuard SET payloadHash = $1, lastSeenAt = NOW(), hitCount = 1 WHERE id = $2',
          payloadHash,
          existing.id
        )
      } else {
        const id = randomUUID()
        await prisma.$queryRawUnsafe(
          `INSERT INTO WriteGuard (id, userId, scope, payloadHash, lastSeenAt, hitCount)
           VALUES ($1, $2, $3, $4, NOW(), 1)
           ON CONFLICT (userId, scope)
           DO UPDATE SET payloadHash = EXCLUDED.payloadHash, lastSeenAt = EXCLUDED.lastSeenAt, hitCount = 1`,
          id,
          ownerKey,
          scope,
          payloadHash
        )
      }
    } catch (error) {
      console.warn('[write-guard] Failed to check guard', error)
      return { skip: false, hitCount: 0 }
    }

    return { skip: false, hitCount: 1 }
  }

  const recordWrite = async (options: {
    ownerKey: string
    scope: string
    payloadHash: string
    recordId?: string | null
  }) => {
    if (!options.ownerKey || !options.scope || !options.payloadHash) return
    await ensureWriteGuardTable()
    try {
      await prisma.$queryRawUnsafe(
        `INSERT INTO WriteGuard (id, userId, scope, payloadHash, lastSeenAt, hitCount, lastRecordId)
         VALUES ($1, $2, $3, $4, NOW(), 1, $5)
         ON CONFLICT (userId, scope)
         DO UPDATE SET payloadHash = EXCLUDED.payloadHash,
                       lastSeenAt = EXCLUDED.lastSeenAt,
                       hitCount = 1,
                       lastRecordId = EXCLUDED.lastRecordId`,
        randomUUID(),
        options.ownerKey,
        options.scope,
        options.payloadHash,
        options.recordId || null
      )
    } catch (error) {
      console.warn('[write-guard] Failed to record write', error)
    }
  }

  return { readGuard, recordWrite }
}

import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'
import { getToken } from 'next-auth/jwt'

const ADMIN_GATE_COOKIE_MAX_AGE = 30 * 24 * 60 * 60 // 30 days

export async function middleware(request: NextRequest) {
  // Preview-staging should always skip the admin gate to avoid iOS logout loops
  const skipAdminGate = true

  // Skip middleware for static files and API routes that don't need auth
  if (
    request.nextUrl.pathname.startsWith('/_next') ||
    request.nextUrl.pathname.startsWith('/api') ||
    request.nextUrl.pathname.includes('.')
  ) {
    return NextResponse.next()
  }

  try {
    // Get the session token from the request
    const token = await getToken({ 
      req: request, 
      secret: process.env.NEXTAUTH_SECRET || 'helfi-secret-key-production-2024',
      // Use a stable encryption key to prevent session invalidation
      cookieName: process.env.NODE_ENV === 'production' 
        ? '__Secure-next-auth.session-token' 
        : 'next-auth.session-token'
    })

    // If we have a valid token, preserve it by adding stability headers
    if (token) {
      // PWA guard rail: signed-in Home Screen opens must skip login/marketing.
      // Keep practitioner auth links intact so "list your practice" flows
      // can reach the practitioner portal instead of being sent to dashboard.
      const forceLogin =
        request.nextUrl.searchParams.get('reauth') === '1' ||
        request.nextUrl.searchParams.get('forceLogin') === '1'
      const practitionerContext = request.nextUrl.searchParams.get('context') === 'practitioner'
      const nextParam = String(request.nextUrl.searchParams.get('next') || '')
      const practitionerNext = nextParam.startsWith('/practitioner')
      const practitionerAuthIntent = practitionerContext || practitionerNext
      if (!forceLogin && (request.nextUrl.pathname === '/auth/signin' || request.nextUrl.pathname === '/') && !practitionerAuthIntent) {
        const redirectUrl = request.nextUrl.clone()
        redirectUrl.pathname = '/pwa-entry'
        return NextResponse.redirect(redirectUrl)
      }

      const response = NextResponse.next()

      // Refresh admin gate cookie so testers aren't booted back to the gate page
      response.cookies.set('passed_admin_gate', '1', {
        httpOnly: false,
        maxAge: ADMIN_GATE_COOKIE_MAX_AGE,
        path: '/',
        sameSite: 'lax',
        secure: request.nextUrl.protocol === 'https:'
      })

      // Add headers to prevent session invalidation during deployments
      response.headers.set('X-Session-Preserved', 'true')
      response.headers.set('Cache-Control', 'no-cache, no-store, must-revalidate')

      return response
    }
  } catch (error) {
    console.error('Middleware session check error:', error)
    // Continue without session preservation if there's an error
  }

  const pathname = request.nextUrl.pathname
  // Never allow direct access to the temporary staging sign-in page
  if (pathname === '/staging-signin') {
    const url = request.nextUrl.clone()
    url.pathname = '/healthapp'
    return NextResponse.redirect(url)
  }
  const needsAdminGate = pathname === '/auth/signin'
  if (skipAdminGate && needsAdminGate) {
    return NextResponse.next()
  }
  const hasPassedGate = request.cookies.get('passed_admin_gate')?.value === '1'
  if (needsAdminGate && !hasPassedGate) {
    const url = request.nextUrl.clone()
    url.pathname = '/healthapp'
    return NextResponse.redirect(url)
  }

  return NextResponse.next()
}

export const config = {
  matcher: [
    /*
     * Match all request paths except for the ones starting with:
     * - api (API routes)
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico (favicon file)
     */
    '/((?!api|_next/static|_next/image|favicon.ico).*)',
  ],
}

