 *   export GARMIN_OAUTH_TOKEN_URL=https://diauth.garmin.com/di-oauth2-service/oauth/token
 */

const https = require('https')

const PROJECT_NAME = 'helfi-app'
const DEFAULT_REDIRECT = 'https://helfi.ai/api/auth/garmin/callback'
const DEFAULT_BASE_URL = 'https://apis.garmin.com/wellness-api/rest'
const DEFAULT_OAUTH_AUTHORIZE_URL = 'https://connect.garmin.com/oauth2Confirm'
const DEFAULT_OAUTH_TOKEN_URL = 'https://diauth.garmin.com/di-oauth2-service/oauth/token'

function makeRequest(options, data) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let body = ''
      res.on('data', (chunk) => {
        body += chunk
      })
      res.on('end', () => {
        try {
          const parsed = JSON.parse(body)
          resolve({ status: res.statusCode, data: parsed })
        } catch (e) {
          resolve({ status: res.statusCode, data: body })
        }
      })
    })

    req.on('error', (error) => reject(error))

    if (data) {
      req.write(JSON.stringify(data))
    }
    req.end()
  })
}

async function addOrUpdateEnvVar(token, key, value, type = 'encrypted') {
  const options = {
    hostname: 'api.vercel.com',
    path: `/v9/projects/${PROJECT_NAME}/env?upsert=true`,
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
