#!/usr/bin/env node

/**
 * Script to remove legacy Stripe Price ID environment variables from Vercel via API
 * 
 * Usage:
 *   VERCEL_TOKEN=your_token node scripts/remove-legacy-stripe-price-ids.js
 */

const https = require('https');

const PROJECT_NAME = 'helfi-app';

// Legacy Price IDs to remove (no longer used)
const LEGACY_VARS = [
  'STRIPE_PRICE_PREMIUM_MONTHLY',
  'STRIPE_PRICE_PREMIUM_YEARLY',
  'STRIPE_PRICE_PREMIUM_PLUS_MONTHLY',
  'STRIPE_PRICE_PREMIUM_PLUS_YEARLY',
  'STRIPE_PRICE_CREDITS_100',
];

function makeRequest(options) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let body = '';
      res.on('data', (chunk) => {
        body += chunk;
      });
      res.on('end', () => {
        try {
          const parsed = JSON.parse(body);
          resolve({ status: res.statusCode, data: parsed });
        } catch (e) {
          resolve({ status: res.statusCode, data: body });
        }
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    req.end();
  });
}

async function deleteEnvVar(token, key) {
  // First, get all env vars to find the ID for this key
  const listOptions = {
    hostname: 'api.vercel.com',
    path: `/v9/projects/${PROJECT_NAME}/env`,
    method: 'GET',
    headers: {
      'Authorization': `Bearer ${token}`,
    },
  };

  try {
    const listResponse = await makeRequest(listOptions);

    if (listResponse.status !== 200) {
      console.error(`   ❌ Failed to list env vars: ${listResponse.status}`);
      console.error(`   Response:`, JSON.stringify(listResponse.data, null, 2));
      return false;
    }

    // Find the env var(s) with this key
    const envVars = listResponse.data.envs || [];
    const matchingVars = envVars.filter((env) => env.key === key);

    if (matchingVars.length === 0) {
      console.log(`   ⚠️  Variable "${key}" not found (may already be deleted)`);
      return true; // Not an error - just doesn't exist
    }

    // Delete each matching env var (could be multiple if different environments)
    let deletedCount = 0;
    for (const envVar of matchingVars) {
      const deleteOptions = {
        hostname: 'api.vercel.com',
        path: `/v9/projects/${PROJECT_NAME}/env/${envVar.id}`,
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${token}`,
        },
      };

      const deleteResponse = await makeRequest(deleteOptions);

      if (deleteResponse.status === 200 || deleteResponse.status === 204) {
        deletedCount++;
      } else {
        console.error(`   ❌ Failed to delete ${key} (ID: ${envVar.id}): ${deleteResponse.status}`);
        console.error(`   Response:`, JSON.stringify(deleteResponse.data, null, 2));
      }
    }

    if (deletedCount > 0) {
      console.log(`   ✅ Deleted ${deletedCount} instance(s) of "${key}"`);
      return true;
    }

    return false;
  } catch (error) {
    console.error(`   ❌ Error:`, error.message);
    return false;
  }
}

async function main() {
  const token = process.env.VERCEL_TOKEN;

  if (!token) {
    console.error('❌ VERCEL_TOKEN environment variable is required');
    console.error('\nTo get a token:');
    console.error('1. Go to https://vercel.com/account/tokens');
    console.error('2. Create a new token with Full Account scope');
    console.error('3. Run: export VERCEL_TOKEN=your_token_here');
    console.error('4. Then run this script again');
    process.exit(1);
  }

  console.log(`\n🗑️  Removing legacy Stripe Price IDs from Vercel`);
  console.log(`   Project: ${PROJECT_NAME}`);
  console.log(`   Variables to remove: ${LEGACY_VARS.length}`);

  let successCount = 0;
  let failCount = 0;
  let notFoundCount = 0;

  for (const envVar of LEGACY_VARS) {
    console.log(`\n📝 Removing: ${envVar}`);

    const result = await deleteEnvVar(token, envVar);

    if (result) {
      // Check if it was actually deleted or just not found
      const listOptions = {
        hostname: 'api.vercel.com',
        path: `/v9/projects/${PROJECT_NAME}/env`,
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${token}`,
        },
      };

      const checkResponse = await makeRequest(listOptions);
      if (checkResponse.status === 200) {
        const envVars = checkResponse.data.envs || [];
        const stillExists = envVars.some((env) => env.key === envVar);
        if (!stillExists) {
          successCount++;
        } else {
          notFoundCount++;
        }
      } else {
        successCount++; // Assume success if we can't verify
      }
    } else {
      failCount++;
    }

    // Small delay to avoid rate limiting
    await new Promise(resolve => setTimeout(resolve, 500));
  }

  console.log(`\n📊 Summary:`);
  console.log(`   ✅ Successfully deleted: ${successCount}`);
  console.log(`   ⚠️  Not found (already removed): ${notFoundCount}`);
  console.log(`   ❌ Failed: ${failCount}`);

  if (failCount === 0) {
    console.log(`\n🎉 Legacy Stripe Price IDs removed successfully!`);
    console.log(`\n⚠️  Note: You may need to trigger a new deployment for changes to take effect.`);
  } else {
    console.log(`\n⚠️  Some variables failed to remove. Check the errors above.`);
    process.exit(1);
  }
}

main().catch((error) => {
  console.error('❌ Fatal error:', error);
  process.exit(1);
});

import fs from 'node:fs'
import path from 'node:path'
import { createHash } from 'node:crypto'
import { execFileSync } from 'node:child_process'
import { Prisma, PrismaClient } from '@prisma/client'

execFileSync(process.execPath, [path.join(process.cwd(), 'scripts/assert-no-local-openai-key.js')], { stdio: 'inherit' })
if (!process.env.DATABASE_URL) throw new Error('Supply the protected database setting privately.')
const argument = (name: string) => process.argv[process.argv.indexOf(name) + 1]
const planPath = process.argv.includes('--plan') ? argument('--plan') : ''
const backupPath = process.argv.includes('--backup') ? argument('--backup') : ''
const archivePath = process.argv.includes('--archive') ? argument('--archive') : ''
if (!planPath || !backupPath || !archivePath) throw new Error('Supply the reviewed plan, public backup and original archive.')
const apply = process.argv.includes('--apply')
const prisma = new PrismaClient({ log: [] })
const fields = ['source', 'fdcId', 'name', 'brand', 'gtinUpc', 'servingSize', 'calories', 'proteinG', 'carbsG', 'fatG', 'fiberG', 'sugarG'] as const
const records = (filename: string) => fs.readFileSync(filename, 'utf8').split('\n').filter(line => line.trim()).map(line => JSON.parse(line))
async function sha256(filename: string) {
  const digest = createHash('sha256')
  for await (const chunk of fs.createReadStream(filename)) digest.update(chunk)
  return digest.digest('hex')
}

async function run() {
  const manifest = JSON.parse(fs.readFileSync(`${planPath}.manifest.json`, 'utf8'))
  if (manifest.scope !== 'usda_foundation_missing_calories_only'
    || manifest.planSha256 !== await sha256(planPath)
    || manifest.backupSha256 !== await sha256(backupPath)
    || manifest.archiveSha256 !== await sha256(archivePath)) throw new Error('Reviewed plan/archive/backup verification failed.')
  const backup = records(backupPath)
  const originals = new Map(backup.map(row => [row.id, row]))
  const plan = records(planPath)
  if (originals.size !== backup.length || backup.length !== manifest.backupRecords || plan.length !== manifest.counts.planned) throw new Error('Public provider record count mismatch.')
  const seen = new Set<string>()
  for (const row of plan) {
    const before = row.before
    const original = originals.get(before?.id)
    if (!original || seen.has(before.id) || fields.some(field => original[field] !== before[field])
      || before.source !== 'usda_foundation' || !Number.isInteger(before.fdcId) || before.fdcId <= 0
      || before.servingSize !== '100 g' || before.calories !== null || before.brand !== null || before.gtinUpc !== null
      || ![1008, 2047, 2048].includes(row.energyNutrientId)
      || Object.keys(row.after ?? {}).join(',') !== 'calories'
      || typeof row.after.calories !== 'number' || !Number.isFinite(row.after.calories) || row.after.calories < 0) throw new Error('Invalid or out-of-scope Foundation repair row.')
    seen.add(before.id)
  }
  const originalCount = await prisma.foodLibraryItem.count({ where: { source: 'usda_foundation' } })
  if (originalCount !== backup.length) throw new Error('Foundation record count changed after backup.')
  const input = Prisma.sql`jsonb_to_recordset(${JSON.stringify(plan)}::jsonb) AS x("before" jsonb, "after" jsonb)`
  const matches = Prisma.sql`
    f."source" = 'usda_foundation' AND f."id" = x."before"->>'id'
    AND f."fdcId" = (x."before"->>'fdcId')::integer
    AND f."name" = x."before"->>'name'
    AND f."brand" IS NOT DISTINCT FROM x."before"->>'brand'
    AND f."gtinUpc" IS NOT DISTINCT FROM x."before"->>'gtinUpc'
    AND f."servingSize" = '100 g' AND f."calories" IS NULL
    AND f."proteinG" IS NOT DISTINCT FROM (x."before"->>'proteinG')::double precision
    AND f."carbsG" IS NOT DISTINCT FROM (x."before"->>'carbsG')::double precision
    AND f."fatG" IS NOT DISTINCT FROM (x."before"->>'fatG')::double precision
    AND f."fiberG" IS NOT DISTINCT FROM (x."before"->>'fiberG')::double precision
    AND f."sugarG" IS NOT DISTINCT FROM (x."before"->>'sugarG')::double precision`
  if (!apply) {
    const result = await prisma.$queryRaw<Array<{ count: bigint }>>(Prisma.sql`SELECT count(*) AS count FROM "FoodLibraryItem" f, ${input} WHERE ${matches}`)
    if (Number(result[0].count) !== plan.length) throw new Error('A provider record changed after backup; regenerate the plan.')
  } else {
    await prisma.$transaction(async tx => {
      // All rows commit together only if every original value still matches.
      const changed = await tx.$executeRaw(Prisma.sql`
        UPDATE "FoodLibraryItem" f SET "calories" = (x."after"->>'calories')::double precision, "updatedAt" = CURRENT_TIMESTAMP
        FROM ${input} WHERE ${matches}`)
      if (changed !== plan.length) throw new Error('Source snapshot changed; the entire repair was rolled back.')
      if (await tx.foodLibraryItem.count({ where: { source: 'usda_foundation' } }) !== originalCount) throw new Error('Provider identities changed; the entire repair was rolled back.')
    }, { timeout: 30000 })
  }
  const after = await prisma.foodLibraryItem.findMany({ where: { source: 'usda_foundation' }, select: { id: true, source: true, fdcId: true, name: true, brand: true, gtinUpc: true, servingSize: true, calories: true, proteinG: true, carbsG: true, fatG: true, fiberG: true, sugarG: true } })
  const targets = new Map(plan.map(row => [row.before.id, row.after.calories]))
  if (after.length !== backup.length) throw new Error('Provider record count changed.')
  for (const row of after) {
    const before = originals.get(row.id)
    if (!before || fields.some(field => row[field] !== (field === 'calories' && apply && targets.has(row.id) ? targets.get(row.id) : before[field]))) throw new Error('Unexpected provider value changed; inspect the preserved backup.')
  }
  console.log(JSON.stringify({ apply, checked: plan.length, originalCount, finalCount: after.length, allProviderIdentitiesAndOtherValuesPreserved: true, customerTablesTouched: false, missingCaloriesAfter: after.filter(row => row.calories == null).length }))
}

run().catch(() => { console.error('Foundation repair stopped; secret details withheld. Inspect the preserved backup and reviewed plan before retrying.'); process.exitCode = 1 }).finally(() => prisma.$disconnect())

#!/usr/bin/env node

const fs = require('fs')
const crypto = require('crypto')

const BASE_KEYWORDS = [
  'food calorie tracking',
  'calorie tracker',
  'ai calorie tracker',
  'ai food tracker',
  'ai food calorie tracker',
  'ai health report',
]

function base64UrlEncode(input) {
  return Buffer.from(input)
    .toString('base64')
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
}

function buildJwt(clientEmail, privateKey) {
  const now = Math.floor(Date.now() / 1000)
  const header = { alg: 'RS256', typ: 'JWT' }
  const payload = {
    iss: clientEmail,
    scope: 'https://www.googleapis.com/auth/webmasters.readonly',
    aud: 'https://oauth2.googleapis.com/token',
    iat: now,
    exp: now + 3600,
  }

  const encodedHeader = base64UrlEncode(JSON.stringify(header))
  const encodedPayload = base64UrlEncode(JSON.stringify(payload))
  const signingInput = `${encodedHeader}.${encodedPayload}`

  const signer = crypto.createSign('RSA-SHA256')
  signer.update(signingInput)
  signer.end()
  const signature = signer.sign(privateKey, 'base64')
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')

  return `${signingInput}.${signature}`
}

async function getAccessToken(credentials) {
  const assertion = buildJwt(credentials.client_email, credentials.private_key)
  const body = new URLSearchParams({
    grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer',
    assertion,
  })

  const response = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: body.toString(),
  })

  if (!response.ok) {
    const errorText = await response.text()
    throw new Error(`Token request failed: ${response.status} ${errorText}`)
  }

  const data = await response.json()
  return data.access_token
}

function formatDate(date) {
  return date.toISOString().slice(0, 10)
}

function parseArgs() {
  const args = process.argv.slice(2)
  const options = {
    days: 28,
    site: 'sc-domain:helfi.ai',
  }

  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i]
    if (arg === '--days' && args[i + 1]) {
      options.days = Math.max(1, Number(args[i + 1]) || 28)
      i += 1
      continue
    }
    if (arg === '--site' && args[i + 1]) {
      options.site = args[i + 1]
      i += 1
    }
  }

  return options
}

function buildTargetKeywords() {
  const withApp = BASE_KEYWORDS.map((keyword) => `${keyword} app`)
  return Array.from(new Set([...BASE_KEYWORDS, ...withApp]))
}

function printRows(rows, rangeLabel) {
  console.log(`\nKeyword tracking for ${rangeLabel}`)
  console.log('-------------------------------------------------------------')
  console.log('Keyword | Clicks | Impressions | CTR | Avg position')
  console.log('-------------------------------------------------------------')

  rows.forEach((row) => {
    const position = row.position > 0 ? row.position.toFixed(2) : '-'
    console.log(
      `${row.keyword} | ${row.clicks} | ${row.impressions} | ${row.ctr.toFixed(2)}% | ${position}`
    )
  })

  const totals = rows.reduce(
    (acc, row) => {
      acc.clicks += row.clicks
      acc.impressions += row.impressions
      acc.ctrWeightedClicks += row.clicks
      return acc
    },
    { clicks: 0, impressions: 0, ctrWeightedClicks: 0 }
  )

  const overallCtr = totals.impressions > 0 ? (totals.clicks / totals.impressions) * 100 : 0
  console.log('-------------------------------------------------------------')
  console.log(
    `TOTAL | ${totals.clicks} | ${totals.impressions} | ${overallCtr.toFixed(2)}% | -`
  )
}

async function main() {
  const { days, site } = parseArgs()
  const keyPath = process.env.GOOGLE_APPLICATION_CREDENTIALS

  if (!keyPath) {
    console.error('Missing GOOGLE_APPLICATION_CREDENTIALS env var.')
    console.error('Example:')
    console.error('export GOOGLE_APPLICATION_CREDENTIALS="/path/to/service-account.json"')
    process.exit(1)
  }

  if (!fs.existsSync(keyPath)) {
    console.error(`Credential file not found: ${keyPath}`)
    process.exit(1)
  }

  const credentials = JSON.parse(fs.readFileSync(keyPath, 'utf8'))
  const accessToken = await getAccessToken(credentials)

  const endDate = new Date()
  const startDate = new Date()
  startDate.setDate(endDate.getDate() - (days - 1))

  const response = await fetch(
    `https://www.googleapis.com/webmasters/v3/sites/${encodeURIComponent(site)}/searchAnalytics/query`,
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${accessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        startDate: formatDate(startDate),
        endDate: formatDate(endDate),
        dimensions: ['query'],
        rowLimit: 25000,
      }),
    }
  )

  if (!response.ok) {
    const errorText = await response.text()
    throw new Error(`Search Console query failed: ${response.status} ${errorText}`)
  }

  const payload = await response.json()
  const rows = payload.rows || []
  const rowsByQuery = new Map()

  rows.forEach((row) => {
    const query = String(row.keys?.[0] || '').trim().toLowerCase()
    if (!query) return
    rowsByQuery.set(query, row)
  })

  const targets = buildTargetKeywords()
  const reportRows = targets.map((keyword) => {
    const raw = rowsByQuery.get(keyword.toLowerCase())
    const clicks = Number(raw?.clicks || 0)
    const impressions = Number(raw?.impressions || 0)
    const ctr = Number(raw?.ctr || 0) * 100
    const position = Number(raw?.position || 0)
    return { keyword, clicks, impressions, ctr, position }
  })

  printRows(
    reportRows,
    `${formatDate(startDate)} to ${formatDate(endDate)} (${days} days), property ${site}`
  )
}

main().catch((error) => {
  console.error(`\nFailed: ${error.message}`)
  process.exit(1)
})

