  const target = fixture(2317111, 'Sanitarium Crunchy Peanut Butter 500g')
  rows = [
    ...Array.from({ length: 30 }, (_, n) => fixture(n + 1, `APPLE ${n} CEREAL`, { brand: 'CRUNCHY ROLLERS' })),
